INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AKŞAM ERKEN İNER MAHPUSHANEYE', 'aksam-erken-i-ner-mahpushaneye-ahmed-ari-f-1nrv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam erken iner mahpushaneye.
Ejderha olsan kar etmez.
Ne kavgada ustalığın,
Ne de çatal yürek civan oluşun.
Kar etmez, inceden içine dolan,
Alıp götüren hasrete.
Akşam erken iner mahpushaneye.
İner, yedi kol demiri,
Yedi kapıya.
Birden, ağlamaklı olur bahçe.
Karşıda, duvar dibinde,
Üç dal gece sefası,
Üç kök hercai menekşe...
Aynı korkunç sevdadadır
Gökte bulut, dalda kaysı.
Başlar koymağa hapislik.
Karanlık can sıkıntısı...
"Kürdün Gelini"ni söyler maltada biri,
Bense volta''dayım ranza dibinde
Ve hep olmayacak şeyler kurarım,
Gülünç, acemi, çocuksu...
Vurulsam kaybolsam derim,
Çırılçıplak, bir kavgada,
Erkekçe olsun isterim,
Dostluk da, düşmanlık da.
Hiçbiri olmaz halbuki,
Geçer süngüler namluya.
Başlar gece devriyesi jandarmaların...
Hırsla çakarım kibriti,
İlk nefeste yarılanır cıgaram,
Bir duman alırım, dolu,
Bir duman, kendimi öldüresiye,
Biliyorum, "sen de mi?" diyeceksin,
Ama akşam erken iniyor mahpushaneye.
Ve dışarda delikanlı bir bahar,
Seviyorum seni,
Çıldırasıya...', 'Akşam erken iner mahpushaneye. Ejderha olsan kar etmez. Ne kavgada ustalığın, Ne de çatal yürek civan oluşun. Kar etmez, inceden içine dolan...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":true,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞAPKASIZ ADAM', 'sapkasiz-adam-reha-yunluel-ryw5s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kalemden dökülen bir kapkara mürekkepti
o bembeyaz kâğıtların üzerinde kıpraşan
güneş o kapkara mürekkebin altında
yağmur bulutlarından yorgun
ve
yağmur bulutlarından arınmış
güneş yağmura
yağmur güneşe sarılmış
delik şemsiyesinin altında
bir şapkasız adam
yağmurlu günde
güneşe darılmış', 'kalemden dökülen bir kapkara mürekkepti o bembeyaz kâğıtların üzerinde kıpraşan güneş o kapkara mürekkebin altında yağmur bulutlarından yorg...', ARRAY['Türk Edebiyatı','Şiir','Reha Yünlüel']::text[], 8.5, '{"poet":"Reha Yünlüel","poet_slug":"reha_yunluel","theme":"Türk Şiiri","is_hero":true,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BAZEN ÖYLE YAKINIM Kİ SANA', 'bazen-oyle-yakinim-ki-sana-henrik-nordbrandt-0p3uu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen öyle yakınım ki sana, ağlarım.
Bazen öyle uzağım ki senden, gülerim.
Bazen öyle mavi ki gökyüzü çatıların üstünde,
belliymiş gibi gelir, aşk neden böyle
Henrik NORDBRANDT', 'Bazen öyle yakınım ki sana, ağlarım. Bazen öyle uzağım ki senden, gülerim. Bazen öyle mavi ki gökyüzü çatıların üstünde, belliymiş gibi geli...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":true,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEBEKLERİN        ULUSU YOK', 'bebekleri-n-ulusu-yok-ataol-behramoglu-vp461', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ULUSU YOK  İlk
kez yurdumdan uzakta yaşadım bu duyguyu
Bebeklerin ulusu yok
Başlarını tutuşları aynı
Bakarken gözlerinde aynı merak
Ağlarken aynı seslerin tonu
Bebekler çiçeği
insanlığımızın
Güllerin en hası, en goncası
Sarışın bir ışık parçası kimi
Kimi kapkara üzüm tanesi
Babalar çıkarmayın onları
akıldan
Analar koruyun bebeklerinizi
Susturun susturun söyletmeyin
Savaştan yıkımdan söz ederse biri
Bırakalım sevdayla büyüsünler
Serpilip gelişsinler fidan gibi
Senin benim hiç kimsenin değil
Bütün bir yeryüzünündür onlar
Bütün insanlığın gözbebeği
İlk kez yurdumdan uzakta yaşadım
bu duyguyu
Bebeklerin ulusu yok
Bebekler, çiçeği
insanlığımızın
Ve geleceğimizin biricik umudu...', 'ULUSU YOK  İlk kez yurdumdan uzakta yaşadım bu duyguyu Bebeklerin ulusu yok Başlarını tutuşları aynı Bakarken gözlerinde aynı merak Ağlarken...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol_behramoglu","theme":"Türk Şiiri","is_hero":true,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ DAĞA AĞIT', 'uc-daga-agit-nihat-behram-3n6ax', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Açlığın
çıplaklığın acısı mı genişliyor
dalları
meyvaya çağıran rüzgâr mı
Dalgın bir kuşun ötüşünden
sevdiğinin kalbine düşen âşık mı
yağmuru emen toprak mı derinleşiyor
Yas mı tutmalıyım onurlu ölüme
halkın gözlerini dolduran çizgilere
umudu mu çağırmalıyım
Ah gidiyor işte gidiyor göz göre göre
sıcak titreyişi varlığını hayata adamışların
gidiyor
öfkenin haykırışları
yasalarıyla gidiyor kahredişin
zulmün ve iğrençliğin buyruklarıyla gidiyor
toprağa düşen bakımsız yapraklar gibi değil
azarlanmış çocukların kederiyle değil
doğuşun ve sevmenin feryadıyla gidiyor
ölümü donatan arkadaşlarım
Ah gidiyor işte gidiyor göz göre göre
durutarak gündüzleri geceleri
durutarak adanmışlığı, mertliği, yüceliği
damıtıp sevdalarına
neferi toprağa aşılamaya gidiyor arkadaşlarım
Bulutlar da hafif mi kar taneleri kadar
özgürlüğün borcu mu ödeniyor
yaralar mı açılıyor yoksulluğa
ezilmişliğin isyanı mı sesleniyor
Ah gidiyor işte gidiyor göz göre göre
birer rüzgâr uğultusu bırakarak yanan ateşe', 'Açlığın çıplaklığın acısı mı genişliyor dalları meyvaya çağıran rüzgâr mı Dalgın bir kuşun ötüşünden sevdiğinin kalbine düşen âşık mı yağmur...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":true,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ DAMLA GÖZYAŞI', 'uc-damla-gozyasi-endre-ady-yovkq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar öğlesinde, bir sonbahar öğlesinde
Ah, ne de güç
Gülüp geçmek genç kızlara.
Bir sonbahar akşamında, bir sonbahar akşamında
Ah, ne de güç
Durup bakmak yıldızlara.
Bir sonbahar öğlesinde, bir sonbahar akşamında
Ah, ne kolay.
Ağlıya ağlıya yere kapanmak!
Endre ADY', 'Bir sonbahar öğlesinde, bir sonbahar öğlesinde Ah, ne de güç Gülüp geçmek genç kızlara. Bir sonbahar akşamında, bir sonbahar akşamında Ah, n...', ARRAY['Türk Edebiyatı','Şiir','Endre Ady']::text[], 8.5, '{"poet":"Endre Ady","poet_slug":"endre_ady","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ DİL', 'uc-di-l-bedri-rahmi-eyuboglu-eyswv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En azından üç dil bileceksin
En azından üç dilde
Ana avrat dümdüz gideceksin
En azından üç dil bileceksin
En azından üç dilde düşünüp rüya göreceksin
En azından üç dil
Birisi ana dilin
Elin ayağın kadar senin
Ana sütü gibi tatlı
Ana sütü gibi bedava
Nenniler, masallar, küfürler de caba
Ötekiler yedi kat yabancı
Her kelime arslan ağzında
Her kelimeyi bir bir dişinle tırnağınla
Kök sökercesine söküp çıkartacaksın
Her kelimede bir tuğla boyu yükselecek
Her kelimede bir kat daha artacaksın
En azından üç dil bileceksin
En azından üç dilde
Canımın içi demesini
Kırmızı gülün alı var demesini
Nerden ince ise ordan kopsun demesini
Atın ölümü arpadan olsun demesini
Keçiyi yardan uçuran bir tutam ottur demesini
İnsanın insanı sömürmesi
Rezilliğin dik alası demesini
Ne demesi be
Gümbür gümbür gümbür demesini becereceksin
En azından üç dil bileceksin
En azından üç dilde
Ana avrat dümdüz gideceksin
En azından üç dil
Çünkü sen ne tarih ne coğrafya
Ne şu ne busun
Oğlum Mernus
Sen otobüsü kaçırmış bir milletin çocuğusun.', 'En azından üç dil bileceksin En azından üç dilde Ana avrat dümdüz gideceksin En azından üç dil bileceksin En azından üç dilde düşünüp rüya g...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyuboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyuboğlu","poet_slug":"bedri_rahmi_eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-DOĞU-', 'dogu-selahattin-yolgi-den-c25f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'dilimin altında kasnı ve kenevir...
hep aynı lezzet: zorun ülfeti!
bildiği yoldan şaşmayan topal,
her geçene yarasını gösteren mesih
ve golgotha ve ikon: eziyet, eziyet...
&quot; kirie eleison! &quot;
şimdi ıssız yollarda eğri kasnağın ardından uçan çocukluğum,
ipek yolunda kendini kalender sanan gölge;
&quot; ah sustuğum, sustuğum... &quot;
kıldan çadırlarda göçebe düşler,
harabe temellere yeni kaprisler gömen umut
ve filistin
ve ibrahim
ve ince bir saç teli sıcak kumlarda bulduğum.
&quot; ah sustuğum, sustuğum... &quot;
ey gamlı derviş,
gözyaşlarını her zaman kumla paylaşma,
kendi ipimle asmışlardı beni eşiğime,
unutma, unutma...
ah düşümün yarısını paylaşmak için yalvaran doğu;
her sabah güneşi ilk kucaklayan toprak;
nasıldı aşkların senin bir masal gibi yaşanan
ve hafız
ve sadi
ve hayyam...
kemiğin kuma olan aşkının abideleri şimdi!
çalışmayan saat,gülistan, süryani
ve güvercin
ve mardin
ve ince bir saç teli
sıcak kumlarda bulduğum.
&quot; ah sustuğum, sustuğum... &quot;
2001/ kış
istanbul', 'dilimin altında kasnı ve kenevir... hep aynı lezzet: zorun ülfeti! bildiği yoldan şaşmayan topal, her geçene yarasını gösteren mesih ve golg...', ARRAY['Türk Edebiyatı','Şiir','Selahattin Yolgi̇den']::text[], 8.5, '{"poet":"Selahattin Yolgi̇den","poet_slug":"selahattin_yolgiden","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ ELMA', 'uc-elma-asli-durak-ewp3r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gökten üç elma değildi düşen
patriotlarla geldi ölüm
patlamalarla tarihe yazıldı Bağdat
dilim lal oldu, pazar yerleri mezar
allahu ekber diyor adam
kucağında ölü çocuklar
sözlerim saklandı, uyku yasaklandı bize
düşleri çağıran ilaçtan verin
geri gelsin sessiz huzur eski gün
ben ne zaman büyüdüm anacığım
tek elime sığarken yaşadığım yıllar
bin yıllık acılar duruyor bakışlarımda
kıyısındayız bir yanardağ ağzının
geri çağırmıyor gazabını
yıldırımlar kuşanmış tanrıça
teyellenmiş sözcükler sökülsün
kanamasın kabuk tutmuş anılar
kanatları gümüşlü kuşlar geri dönsün
ana gibi yar
Bağdat gibi diyar olmaz diyen
uzak ve eski masallar anlatsın ninem
üç dilek isteyeyim
şişedeki cinden
savaş bitsin savaş bitsin savaş bitsin
bana sımsıkı sarıl baba
masallarda kalsın
ağzından alevler çıkan ejderha.', 'gökten üç elma değildi düşen patriotlarla geldi ölüm patlamalarla tarihe yazıldı Bağdat dilim lal oldu, pazar yerleri mezar allahu ekber diy...', ARRAY['Türk Edebiyatı','Şiir','Aslı  Durak']::text[], 8.5, '{"poet":"Aslı  Durak","poet_slug":"asli_durak","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FAİLİ MEÇHUL İNTİHAR', 'fai-li-mechul-i-nti-har-reha-yunluel-75cos', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '&quot;Faili meçhul intihar&quot; imgesini benden iki sene
önce bulan şair Ahmet Erhan''a...&quot;
faili meçhul bir intiharda
meçhule kaçandım:
bir kaaatil!
tanrının siktirettiği
yerlerde
peygamber peygamber dolaşan;
etrafa deli bakışlar
saçandım!
faili meçhul bir intiharda
arta kalandım:
bir ayyaş!
polisten kaçarken
bir muhbirin
evinde saklandım!
faili meçhul bir intiharda
bir meçhul 3. şahıs:
meçhul eşkali
tüm karakollara dağıtılmış bir aranandım!
gündüzün gölgesi
bir gecede,
kendim denen
o meçhule yakalandım!
fail', '&quot;Faili meçhul intihar&quot; imgesini benden iki sene önce bulan şair Ahmet Erhan''a...&quot; faili meçhul bir intiharda meçhule kaçandım...', ARRAY['Türk Edebiyatı','Şiir','Reha Yünlüel']::text[], 8.5, '{"poet":"Reha Yünlüel","poet_slug":"reha_yunluel","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANİ KURŞUN SIKSAN GEÇMEZ GECEDEN', 'hani-kursun-siksan-gecmez-geceden-ahmed-ari-f-3rktt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yiğit harmanları, yığınaklar,
Kurulmuş çetin dağlarında vatanların.
Dize getirilmiş haydutlar,
Hayınlar, amana gelmiş,
Yetim hakkı sorulmuş,
Hesap görülmüş.
Demdir bu...
Demdir,
Derya dibinde yangınlar,
Kan kesmiş ovalar üstünde Mayıs...
Uçmuş, bir kuştüyü hafifliğinde,
Çelik kadavrası korugan''ların.
Ölünmüş, canım,ölünmüş
Murad alınmış...
Gelgelelim,
Beter, bize kısmetmiş.
Ölüm, böyle altı okka koymaz adama,
Susmak ve beklemek, müthiş
Genciz, namlu gibi,
Ve çatal yürek,
Barışa, bayrama hasret
Uykulara, derin, kaygısız, rahat,
Otuziki dişimizle gülmeğe,
Doyasıya sevişmeğe,yemeğe...
Kaç yol, ağlamaklı olmuşum geceleri,
Asıl, bizim aramızda güzeldir hasret
Ve asıl biz biliriz kederi.
İçim, bir suskunsa tekin mi ola?
O Malta bıçağı,kınsız,uyanık,
Ve genç bir mısradır
Filinta endam...
Neden, neden alnındaki yıkkınlık,
Bakışlarındaki öldüren buğu?
Kaç yol ağlamaklı oluyorum geceleri...
Nasıl da almış aklımı,
Sürmüş, filiz vermiş içimde sevdan,
Dost, düşman söz eder kendi kavlince,
Kınanmak, yiğit başına.
Bu, ne ayıp, ne de yasak,
Öylece bir gerçek, kendi halinde,
Belki, yaşamama sebep...
Evet, ağlamaklı oluyorum, demdir bu.
Hani, kurşun sıksan geçmez geceden,
Anlatamam, nasıl ıssız, nasıl karanlık...
Ve zehir - zıkkım cıgaram.
Gene bir cehennem var yastığımda,
Gel artık...', 'Yiğit harmanları, yığınaklar, Kurulmuş çetin dağlarında vatanların. Dize getirilmiş haydutlar, Hayınlar, amana gelmiş, Yetim hakkı sorulmuş,...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-KARNE-', 'karne-reha-yunluel-umixs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevgili abdullah''a...
on üzerinden sıfırdır kanım
ama iyimser bir fiyaka gibi
durur yakasında
çoğu kere işe yaramaz artım.', 'sevgili abdullah''a... on üzerinden sıfırdır kanım ama iyimser bir fiyaka gibi durur yakasında çoğu kere işe yaramaz artım....', ARRAY['Türk Edebiyatı','Şiir','Reha Yünlüel']::text[], 8.5, '{"poet":"Reha Yünlüel","poet_slug":"reha_yunluel","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ KEZ SENİ SEVİYORUM DİYE UYANDIM', 'uc-kez-seni-sevi-yorum-di-ye-uyandim-i-lhan-berk-56twv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üç kez seni seviyorum diye uyandım
Tuttum sonra çiçeklerin suyunu değiştirdim
Bir bulut başını almış gidiyordu görüyordum.
Sabahın bir yerinden düşmüş gibiydi yüzün.
Sokağı balkonları yarım kalmış bir şiiri teptim
Sıkıldım yemekler yaptım kendime otlar kuruttum
-Taflanım! diyordu bir ses duyuyordum.
Cumhuriyetin ilk günleri gibiydi yüzün.
Kalktım sonra bir aşağı bir yukarı dolaştım
Şiirler okudum şiirlerdeki yaşa geldim
Karanfil sakız kokan soluğunu üstümde duydum.
Eskitiyorum eskitiyorum kalıyor ne kadar güzel olduğun.
Deniz Eskisi', 'Üç kez seni seviyorum diye uyandım Tuttum sonra çiçeklerin suyunu değiştirdim Bir bulut başını almış gidiyordu görüyordum. Sabahın bir yerin...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LEYLİM - LEYLİM', 'leyli-m-leyli-m-ahmed-ari-f-m650c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Leylim - leylim dünyamızın yarısı
Al - yeşil bahar,
Yarısı kar olanda
Gene kavim - kardaş, can - cana düşman,
Gene yediboğum akrep,
Sarı engerek,
Alnımızın aklığında puşt işi zulüm
Ve canım yarı geceler
Çift kanat kapılarına karşı darağaçları,
Mahpusanede çeşme
Yandan akar olanda,
Gelmiş yoklamış ecel
Kaburgam arasından.
Yoklasın hele...
Çağıdır, can dayanmaz,
Çağıdır, en çatal, en ası,
Cehennem koncası memelerinin.
Çağıdır, kırk gün - kırk gece
Kolların boynuma kement,
Ha canım kötüye inat...
Vah ki ne desem,
Kurşunları namlulara sürülü,
İ''kelleri kan,
Baskıncılar uykumuzu yıkar olanda,
Alır yüreğim:
Yankın yasak, aynalara.
İnemem bahçende talan,
Tam, boş yanı bu, derim namussuzun,
Tam, bıçağım cehennem gibi güzelken,
Aklıma düşüyorsun
Ellerim arık...
Bilmiş
Bütün zula''lar
Eğri hançer, kara mavzer, kan pusu.
Ve insan düşüncesinin o en orospu,
O en ayıp, frengili yemişi,
Çıldırtılmış uranyum
Bilmiş,
Bilsinler!
Sana nasıl yandığımı
Uuuuy gelin...
İşte kan tutmuş korsanlar,
Haramla beslenmiş azgın,
Düzmece peygamberler
Ve cüceleri
Ve iğdiş ve aptal kölelerine karşı,
İşte bir kez daha
Bu can bendeyken,
Delin, divanenim işte
Uuuuy gelin...
Bu yasaklar,
Firavun kalıntısı.
Yoksun,
Akdan - karadan.
Gizline, canevine kurulu faklar.
Gün ola, umut kesip korkunç yetinden,
Murdar tutkusuna dünyasızlığın,
Gün ola, düşesin bekler.
Düşme!
Ölürüm...
Gözlerinden, gözlerinden olurum.
Leylim - leylim
Ayvalar, nar olanda
Sen bana yar olanda.
Belalı başımıza
Dünyalar dar olanda.', 'Leylim - leylim dünyamızın yarısı Al - yeşil bahar, Yarısı kar olanda Gene kavim - kardaş, can - cana düşman, Gene yediboğum akrep, Sarı eng...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":68}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İŞÇİ MARŞI', 'i-sci-marsi-can-yucel-jypxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava döndü işçiden işçiden esiyor yel
Dumanı dağıtacak yıldız-poyraz başladı
Bahar yakın demek ki mevsim böyle kışladı
Bu fırtına yarınki sütlimanlara bedel
Hava döndü işçiden, işçiden esiyor yel
Tekliyor işte çağın çarkına okuyan çark
Ve durdu muydu birgün bu kör, avara kasnak
Bir zincir yitirenler bir dünya kazanacak
Sen de o dünyadansın sınıfın bil safa gel
Hava döndü işçiden, işçiden esiyor yel
Köylükler uykusunda döndü dönüyor sola
Güne bakıyor bebek büyüyen yumruğuyla
Başaklar gövderdi bak başkoydular bu yola
Şaltere uzanıyor allaha açılmış el
Hava döndü işçiden, işçiden esiyor yel', 'Hava döndü işçiden işçiden esiyor yel Dumanı dağıtacak yıldız-poyraz başladı Bahar yakın demek ki mevsim böyle kışladı Bu fırtına yarınki sü...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERHABA', 'merhaba-ahmed-ari-f-24nsa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün açar,
Karın verir yağmurlu toprak.
İncesu Deresi, merhaba.
Saçakta serçeler daha çılgındır,
Bulutlarda kartal,
Daha çalımlı.
Koparır göğsünden bir düğme daha,
Tezkere bekliyen biri.
İncesu Deresi, merhaba.
Genç bayraklar vardır,
Barış düşünür,
Kuyularda işçi, mavilikleri.
Ben hepsini düşünürüm,
Yirmidört saat
Ve seni düşünürüm,
Karanlık,hırslı...
Seni, cihanların aziz meyvası.
İlan-ı aşk makamından bir mısra,
Yeşerip, kımıldar içimde,
Düşer aklıma gözlerin...
Oysa murad alamam.
Oysa akdan - karadan
Bilirim, payım bu kadar...
Unutmuş gülmeyi gözbebeklerim.
Unutmuş dudaklarım öpmeyi.
İncesu Deresi, merhaba...', 'Gün açar, Karın verir yağmurlu toprak. İncesu Deresi, merhaba. Saçakta serçeler daha çılgındır, Bulutlarda kartal, Daha çalımlı. Koparır göğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇ NOKTA', 'uc-nokta-sukru-erbas-s1ey5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyük konuşanlar
Alınlarında eğri olmayanlar
Yalnız yükseği görenler
Herkesin ortasında yürüyenler
Bütün ışıkları yananlar
Sesi menevişsizler
Güzü küçümseyenler
Gözyaşına arkasını dönenler
Kendini mutluluk bilenler
Sessizlikten korkanlar
Yalnız eşyalarına gülümseyenler
Öyküsünde öteki olmayanlar
Kederle kirlenenler
Aynası buğusuzlar
Kışa yolu düşmeyenler
Kalbi ölüm mühürlüler
Penceresi dışa açılmayanlar
Aşktan utananlar
Güzelliği kimsesizler
Dili şiddet olanlar
Gövdesi sözünden önce gelenler
Dünyaya dokunmayanlar
Unutanlar, unutanlar
Ey tek heceli darlık...
O mevsimim ki herkesten yapılmış
Üç noktayla biten bir cümleyim artık..', 'Büyük konuşanlar Alınlarında eğri olmayanlar Yalnız yükseği görenler Herkesin ortasında yürüyenler Bütün ışıkları yananlar Sesi menevişsizle...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru_erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONUR DA AĞLAR', 'onur-da-aglar-ahmed-ari-f-n0zx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerinin pınarında
Bir bulut,
Boşandı boşanacak
Nerdeyse.
Aklımdan geçenleri
Okuyorsun su gibi.
Dünya gördü
Bizi boğazladılar...
Tutma gözyaşlarını
Onur da ağlar...
Bırak yıkansın gökyüzü,
Lacivert, yeşil, altın
Işıkları günbatının.
İşte şafaktayız gene
Çırılçıplak
Ve mavi.
İşte sanki dağ yeli
Ve işte sanki meltem...
Kimse toz konduramaz
Kesip attığımız tırnağa bile.
Sen en güzel kızısın
Bütün galaksilerin
Bense tözüyüm artık
Akkor tözüyüm
Prometheus''u yakan
Kara sevdanın...
Ne alnımızda bir ayıp
Ne koltuk altında
Saklı haçımız
Biz bu halkı sevdik
Ve bu ülkeyi.
İşte bağışlanmaz
Korkunç suçumuz...', 'Gözlerinin pınarında Bir bulut, Boşandı boşanacak Nerdeyse. Aklımdan geçenleri Okuyorsun su gibi. Dünya gördü Bizi boğazladılar... Tutma göz...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orhan Veli KANIK'' ın Kaleminden Melih Cevdet ANDAY', 'orhan-veli-kanik-in-kaleminden-melih-cevdet-anday-orhan-veli-kanik-mte67', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Veli KANIK'' ın Kaleminden Melih
Cevdet ANDAY
&quot;Son zamanlarda Melih
Cevdet''i daha çok anlıyorum. (...) Senelerdir, durmadan yenilikler peşinden
koşuyor. Her şiiri bir tecrübenin mahsulüdür. Melih Cevdet''e çok az şiir
söylüyor diyenler o şiirlerin ne ince süzgeçtelerden geçirildiğini sezdikleri
vakit ne kadar haksız olduklarını anlayacaklardır.&quot;
( 1 Mayıs 1946)
&quot;Melih Cevdet ''Rahatı
Kaçan Ağaç'' adlı şiirinde mesut bir ağaçtan bahsediyor. O ağaç mesuttur;
çünkü saadet kelimesini bilmiyor. Sadece, tabiat içinde yaşıyor. Tabiatsa
güzeldir, sevilir; tabiat içinde, ancak mesut olunur. Halbuki insanlar içinde
yaşayan, insanlardan gönül çekmeyi, dert çekmeyi öğrenen insan kolay kolay mesut
olmaz Ağacı, kuşu, karıncayı kıskanır. Melih Cevdet de aynı kıskançlığı
duyuyor.&quot;', 'Veli KANIK'' ın Kaleminden Melih Cevdet ANDAY &quot;Son zamanlarda Melih Cevdet''i daha çok anlıyorum. (...) Senelerdir, durmadan yenilikler p...', ARRAY['Türk Edebiyatı','Şiir','Orhan 
veli Kanik']::text[], 8.5, '{"poet":"Orhan \nveli Kanik","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARKTA            RASTLADIĞIM ADAM', 'parkta-rastladigim-adam-ataol-behramoglu-28nda', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'RASTLADIĞIM ADAM
Parkta
rastladığım adamın
Bir kolu
kesikti bileğinden
Çiftçiymiş
Tekirdağ'' ın
köylüklerinden
Bir kızı
veremden ölmüş
Bu şehri
İstanbul'' da
Karısı
tutturmuş:
Kızımın
mezarı nerde ben orda
Satmış
savmış ihtiyarcık
Varını
yoğunu
Feriköy'' de
bir evceğize
Sokmuşlar
başcağızlarını
İkinci kız
desen
Kibarca: Akıl
hastası
Anaya babaya
Vermez bir
rahat yüzü
Oğlanlardan büyüğü
Dört çocuklu
bir şoför
Küçük
oğlan
Bir
tamirhanede ömür çürütür
Fayda yok
anlayacağın
Ne
oğlanlardan, ne kızlardan
Bir fabrikada
iş bulmuş
Kaçak işçi
çalıştıran
Kırk
yılın köylüsü
Ne yapsın
işçi olursa
Daha yılı
dolmadan
Kaptırıvermiş elini çarka
Gerisi
bilinen hikaye
Patrondan
imdat görmez
Evde karı
ağlar
Deli kız
vermez rahat
Kendisine
rastladığımda
Düşünüp
duruyordu bir kanepede
Ben sordum o
anlattı
Güzelim
Tekirdağ şivesiyle...
(1977)', 'RASTLADIĞIM ADAM Parkta rastladığım adamın Bir kolu kesikti bileğinden Çiftçiymiş Tekirdağ'' ın köylüklerinden Bir kızı veremden ölmüş Bu şeh...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol_behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":72}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ş İ İ R   S A N A T I', 's-i-i-r-s-a-n-a-t-i-eug-ne-guillevic-kmbji', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I
Sözcükler, sözcükler
Karışırlar yapılana
Katafalklar gibi.
Ve yabancıdır
Her dil.
II
Jean Follain''e
Kuşkusuz bir lütuf dilekçesi değildi
Utancın sırlarını
Kendinden geçerek söyleyen ses.
Alışmalıydı ses
Deneyerek sözcükleri,
Yardımıyla edinecek
Ses perdesinin.
III
Korkunun istediği
Gece kuşunun çığlığı,
Güç bir çığlıktır
Gırtlakta biçimlendirilecek.
Oysa akan kan renginde
Düşer bu çığlık,
Ve çınlar acımaklı
Korku saldığı ormanların içinde.
IV
Söktüğümüz sözcükler
Söylememiz gereken,
Azalıyor günler gibi.
V
Eğer açarsa fırtınalar ağzını
Ve güpegündüz gözükürse gece,
Eğer zenci bir kralsa nehir
Katledilmiş, düşmüş sineklerin arasına,
Eğer güzelse bağlar
Ve okşuyorsa ölüleri,
-Postu sermektir çoktan
Söz konusu olan,
Ve kurtarmak paçasını
Kıl çeker gibi tereyağından
Zor işlerin arasından.
Eugène  GUILLEVIC', 'I Sözcükler, sözcükler Karışırlar yapılana Katafalklar gibi. Ve yabancıdır Her dil. II Jean Follain''e Kuşkusuz bir lütuf dilekçesi değildi U...', ARRAY['Türk Edebiyatı','Şiir','Eugène  Guillevic']::text[], 8.5, '{"poet":"Eugène  Guillevic","poet_slug":"eugene_guillevic","theme":"Türk Şiiri","is_hero":false,"total_lines":43}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'RÜSTEMO', 'rustemo-ahmed-ari-f-2y07n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Modan yaylasına eşkin almadan
Maktela üzerinde sağımız
Karbeyaz Çermik Dağları
Solumuz kan kırmızısı Fırat''tır
Dört mevsim yeşildir orman
Ve toprak çetin
Baharları aşiretler iner Dersim üstünden
Sürü otlatır.
Odunda
Kömürde
Pamukta
Gönlü bir akarsu gibi alıp götüren
Irzdan ve ekmekten yana
Bir kara sevdadır
Yeşil murattır
Ve bundan ötürü tutmuş dağları
Ve almış yürümüş sulardan öte
Kıl çadırlarda maceramız
Yasak bundan böyle zulüm;
Ve öşür
Ve haraç
Ve angarya
Ve katil
Ve şirkat
Ve talan
Ve küfür kıza kısrağa
Yasaktır, emreder Dağlar Paşası
Elinde, affetmez Fransız üçlüsü...
Gayrı malumunuz olsun halım
Hayrola encam
Malum ola
Ayan beyan
Dosta ve düşmana serencam
Önce şeyhulislam fetva buyurur
Katlim dört mezhepte vacip görülür
Sonra saray ferman eyler
Ve kaltak vurulur ordugahlarda
Dar vakit yetiştin tatar ağası
Bir elimde kana batmış hamaylim
Bir elim derman eyler
Dostooo
Buncasına kavga demezem
Kızanlar idman eyler
Hele sarılmasın dört bir yanımız
Tamam cümle dağlar mevzi almıştır
Ve yatmış pusuya patikalar
Salavat getirir dağ dağ taburlar
Narlı bahçe üzre kanlı bir akşam
Gelen elçi değil
Azrail olsun
Anam avradım olsun kaçarsam.', 'Modan yaylasına eşkin almadan Maktela üzerinde sağımız Karbeyaz Çermik Dağları Solumuz kan kırmızısı Fırat''tır Dört mevsim yeşildir orman Ve...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":53}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İŞ SAÇMALAMASI', 'i-s-sacmalamasi-turgay-fi-sekci-4uama', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir yayınevim olsa
Bastığım kitaplar satmasa
&quot;Dağıtamıyorsun, tanıtamıyorsun&quot; diye
Yazarlar yakama yapışsa
Ben onları bağlasam
Saçlarını kesip, trenlere doldursam
Eskişehir''e göndersem
Saçmalasam saçmalasam...
Onlar, kaçıp Taksim''e gelseler
Teliflerinin tinerini koklayıp ısınsalar
Kör çalgıcılar gelse
Onlar &quot;ustam öldü ben satarım&quot; oynasalar.
Turgay FİŞEKÇİ
---------------------------------------------------------------------------------------', 'Bir yayınevim olsa Bastığım kitaplar satmasa &quot;Dağıtamıyorsun, tanıtamıyorsun&quot; diye Yazarlar yakama yapışsa Ben onları bağlasam Saç...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
