INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADAM OLANA ÇOK BİLE', 'adam-olana-cok-bi-le-cahit-irgat-93syx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ekmeğimi gözyaşıma bandım da yedim.', 'Ekmeğimi gözyaşıma bandım da yedim....', ARRAY['Türk Edebiyatı','Şiir','Cahit Irgat']::text[], 8.5, '{"poet":"Cahit Irgat","poet_slug":"cahit_irgat","theme":"Türk Şiiri","is_hero":false,"total_lines":3}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADAM', 'adam-salih-bolat-qgd8p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir adam denize bakıyor kumsaldan
uzaktan görünüşü deniz fenerini andıran
dün ordan bir
yıldız düşmüştü
suya
onu araştırıyor, yılan balıklarının ıslıkları
arasında
yengeçleri ürküten kaplumbağanın gözlerinde
titreyerek geçen üç denizatının saydamlığında
ve soluğunda kayalıklardaki kertenkelenin.
(Temmuz Şiirleri)', 'bir adam denize bakıyor kumsaldan uzaktan görünüşü deniz fenerini andıran dün ordan bir yıldız düşmüştü suya onu araştırıyor, yılan balıklar...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih_bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADAMLAR', 'adamlar-oguz-tansel-066w8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adamlar; yolağzında çömelekalmış,
Alınları, elleri çizgi çizgi;
Zincirlenmiş gibi düşüncelerden
Kaygılar içinde yüzleri.
Yüreklerindeki ateşten habersiz,
Gözlerinde toprak özlemi,
Yıllar yılı çağlamış
Başı boş sularca elleri.
Adamlardan güneşi içinde bulan,
Dumandan sıyrılmış dağ gibi;
"Bize uyuşukluk yakışmaz" diye
Doğrulup gürleyiverdi.
"Yaşamak için geldik dünyaya,
Yaratabiliriz iyiyi, güzeli."
Günlük güneşlik kesildi yol
Kararlı gözleri.', 'Adamlar; yolağzında çömelekalmış, Alınları, elleri çizgi çizgi; Zincirlenmiş gibi düşüncelerden Kaygılar içinde yüzleri. Yüreklerindeki ateş...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADANMAK TÜRKÜSÜ', 'adanmak-turkusu-azer-yaran-zx079', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şiirin ulu güzergahında
duygu memurları düş memurları
suyu susturur usu sustururlar
özgürlüğün özge oğlu
sana tiranlar mı öğretecekmiş
bulunca kut''u umudu
dirimin uzun uykusundan
uyanışın ilk sesi - sen
canın aydın ufuklarında
bileğlenen usun ilk sözü
sen Şairsin - özdeğin ve Tanrının oğlu
başlangıçların başı sen - sonların sonu', 'şiirin ulu güzergahında duygu memurları düş memurları suyu susturur usu sustururlar özgürlüğün özge oğlu sana tiranlar mı öğretecekmiş bulun...', ARRAY['Türk Edebiyatı','Şiir','Azer  Yaran']::text[], 8.5, '{"poet":"Azer  Yaran","poet_slug":"azer_yaran","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADEM', 'adem-mehmet-zaman-saclioglu-dif8c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk ölen insan Habil''di
Ölümü bilmeyen tek insandı O
Ne varsa tanıdığımız bugüne dek
O ilk ölümle başladı.
İlk var olan insan Âdem''di
Bilinmeyen insandı O
Ne varsa tanımadığımız dünyada
O''nun oluşundan önceydi.
Havva''nın tek erkeğiydi Âdem
Bilmedi çocukların babasıdır
Başka kadın yoktu ki seçsin
Sevgiyi duymayan ilk insandı O.
Tanrının eli bir O''na değdi
Ama Âdem Tanrıyı bilemedi
Kutsal sorumsuzluğun kurbanı
Ön yazgımız, babamızdı O.
Yalnızdı Âdem, Havva gibiydi
Tanrının koca taş bebekleri
Onlardan kalmadır sanki gözümüz
Kendimizi görürüz baksak da başkas��na.', 'İlk ölen insan Habil''di Ölümü bilmeyen tek insandı O Ne varsa tanıdığımız bugüne dek O ilk ölümle başladı. İlk var olan insan Âdem''di Bilinm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADI ‘EYLÜL’ OLSUN', 'adi-eylul-olsun-i-smail-onat-p6m6g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'adı: ‘eylül’ olsun.
hem son olsun
hem de en güzel ilk
günlerden: ‘pazartesi’
soğuk, güneşli
ve neşeli.
yaprak olsun yemyeşil
‘sararmaya yüz tutmuş ben’de
düş-l-erken
arkamdan bakar olsun.
gülücüğü hep sıcak
dokunuşum olsun ulaştığım
hani o uzak erişilmezliğinde
salınırken yanyana.
bilmiyor olsun gölgemi
bilmeyenler dünyasında
dudaklarında titreşen kelimeler
yine sevgi olsun
hiç susmayacak yıllarca
döküldükçe yavaşça.
bahçemde çiçek olsun
kırmızı, ‘mavi’ye çalan
koklayamayacağım
bakakaldığım
en suskun halim olsun
kilit vurduğum kendime
kapanmış içine ürkek yabancı
uzak kalır olsun
yine mutlu kendi haline.
çizdiğim resim olsun
hayal edip günlerce
uykusuz gecelerde
renkleri karıştırdığım tual
üzerine vurduğum bez
duygularım olsun
şekillerde sakladığım.
yeni bir baslangıç içinde
kucaklanan günler
koşulan öpüş olsun
özlenen sevgili hayallerde
geceyarıları uyandıran
rüyalardan heyecan içinde
sonrasında bilinen mutluluğu
tesellisi olsun.
bir saç teline dokunuş
bir öpüş usulca yanağından
sessizliği bozan
hissedilen nefes olsun
gözlerine bakan gözler
yalnız
mavi
hayal meyal olsun.
adı: ‘eylül’
soyadı: ‘pazartesi’ olsun.', 'adı: ‘eylül’ olsun. hem son olsun hem de en güzel ilk günlerden: ‘pazartesi’ soğuk, güneşli ve neşeli. yaprak olsun yemyeşil ‘sararmaya yüz ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Onat']::text[], 8.5, '{"poet":"İsmail Onat","poet_slug":"ismail_onat","theme":"Türk Şiiri","is_hero":false,"total_lines":56}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADI: GÜL', 'adi-gul-bulent-ozcan-vsmrz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülü vurmuşlar Gül Sokağı''nda,
Uzanmış üç adım yatıyordu gül...
Bir adam usulca bir uçuruma,
"Sevi için" deyip atıyordu gül...
Ve bir kız kanatıp hüznü boyuna,
Hepten sevgisizlere satıyordu gül...
Gülü vurmuşlar Gül Sokağı''nda,
Uzanmış üç adım yatıyordu gül...', 'Gülü vurmuşlar Gül Sokağı''nda, Uzanmış üç adım yatıyordu gül... Bir adam usulca bir uçuruma, "Sevi için" deyip atıyordu gül... Ve bir kız ka...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADI KAYIP', 'adi-kayip-adnan-yucel-6dts8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz yok olursa diyor bir çocuk
Balık kaybolursa
Ne derim benden sonraki çocuklara
İnsanlar kaybolurken gözaltılarda
Çöllerde boğulan nehirler
Ey çocuk
Nasıl varır okyanuslara
Adı karanfil ki suçu rengidir
Özgürlük dilinde bir imge
Tutsaklık dilinde bir söylencedir
Karanlıkta bir el koparır dalından
Artık ölüme varmış bir işkencedir
Orman yok olursa diyor bir çocuk
Ağaç kaybolursa
Ne derim benden sonraki çocuklara
İnsanlar kaybolurken gözaltılarda
Dalından koparılan tomurcuk
Ey çocuk
Nasıl meyvelenir sana ve diğer çocuklara
Adı narçiçeği ki suçu patlamak
Birdenbire güneşe haykırmak
Ve güneş diliyle kıpkızıl çoğalmak
Karanlıkta bir el koparır dalından
Adı kayıptır artık
Daha meyveye bile durmadan
Aç gözlerini o çığlıklaraı çocuk
Kayıp analarının gözlerine bak
O gözler ki karanfil kıvrımında nar çokluğu
Sevda denizlerinde oğul ve kız yokluğudur
Her biri bir depremdir yüreklerde
Her biri açlık içinde zulüm tokluğudur
Sen ki bir badem dalısın baharda
Yüzünde solgun bir yeşil akşamı
Dalıyor gözlerin bir çağın artıklarına
Kazılardan yeni çıkmış gibisin
Bakışlarında düş fosilleri
Güneşli bir yeşili özler gibisin
İnsanlar kaybedilirken ey çocuk
İnsanlık adına
Nasıl başlar bu yeşil ve mavi yolculuk
Hangi gemi kalkar bu ülke limanlarından
Hangi mavilikler karşılar seni
Kıyılar zincir olmuş bileklerde
Dalgalar yargısız infaz
Al kalemi eline ey çocuk
Yeşilin ve mavinin şiirini yeniden yaz', 'Deniz yok olursa diyor bir çocuk Balık kaybolursa Ne derim benden sonraki çocuklara İnsanlar kaybolurken gözaltılarda Çöllerde boğulan nehir...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADIM ADIM İLERLİYORUM', 'adim-adim-i-lerli-yorum-ivo-andrich-wu7cw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '* * *
Adım adım ilerliyorum
belki karşıma bir şey çıkar
bakıp bakıp düşünüyorum
oysa karşımda yalnız kaçınılmazlıklar.
Bir taş ki boğulmaya mahkûm.
Bir perde ki kapanacak
bir daha açılmadan.
Bir kuş ki yalnız bir zamanlar uçtuğu bilinen.
Yaşam yok, ölümse bir türlü gelmiyor.
Anlaşılmaz değin uzun
Uzun, katlanılmazcasına
kişinin alınyazısı.
Ivo ANDRICH', '* * * Adım adım ilerliyorum belki karşıma bir şey çıkar bakıp bakıp düşünüyorum oysa karşımda yalnız kaçınılmazlıklar. Bir taş ki boğulmaya ...', ARRAY['Türk Edebiyatı','Şiir','Ivo Andrich']::text[], 8.5, '{"poet":"Ivo Andrich","poet_slug":"ivo_andrich","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADIM SONBAHAR', 'adim-sonbahar-attila-i-lhan-ckcmq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nasıl iş bu
her yanına çiçek yağmış
erik ağacının
ışık içinde yüzüyor
neresinden baksan
gözlerin kamaşır
oysa ben akşam olmuşum
yapraklarım dökülüyor
usul usul
adım sonbahar', 'nasıl iş bu her yanına çiçek yağmış erik ağacının ışık içinde yüzüyor neresinden baksan gözlerin kamaşır oysa ben akşam olmuşum yapraklarım ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADIMI UNUTTUM', 'adimi-unuttum-asaf-halet-celebi-gqnc2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'adımı unuttum
adı olmıyan yerlerde
ne in
ne cin
ne benî âdem
zamanlar içinde
kuşlar uçuyor
kervanlar geçiyor
bir iğne deliğinden
çarşılar kuruluyor
sarayları oyuncak
insanları karınca şehirler
zamanları gördün mü
bir iğne deliğinden
adımı unuttum
adı olmayan yerlerde
geçip gidenlere bakarak', 'adımı unuttum adı olmıyan yerlerde ne in ne cin ne benî âdem zamanlar içinde kuşlar uçuyor kervanlar geçiyor bir iğne deliğinden çarşılar ku...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi̇']::text[], 8.5, '{"poet":"Asaf Halet Çelebi̇","poet_slug":"asaf_halet_celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADINA YAKTIĞIM TÜRKÜLER', 'adina-yaktigim-turkuler-necati-cumali-3ohiw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne söyler bu türküler
Ay karanlık gecelerde yüzen gemiler
Sevilip sevdikten sonra
İnsan böyle yalnız mı kalır
Bahtına hatırlamak mı düşer
Ne söyler bu türküler
Bomboş ovalardan geçen trenler
Bir kere Menemen''den
Kolları kelepçeli bir adamla
Bir cardarma oturdular yanıma
Manisa''da indiler
Küçüktün annem söyledi
"Atımın adı Dilber''dir"
"İskender Bey dayımdır"
Büyüdüm neden sonra anladım
Has bahçede kör sarmaşık
Karışık güller arasına
Ben şahin değilim
Yükseklerde uçamam tek başıma
Serçe kuşu değilim
İnemem nar dalından
Pınar başına
Pencerem denize karşıdır
Oturur düşünürüm bazı günler
Seni beni mahzun eden bu haller geçer
Gün gelir herkes gibi ben de ölürüm
Bu aşk yürekten yüreğe yeniler
Bir gün ağızdan ağıza dolaşır
Adına yaktığım türküler', 'Ne söyler bu türküler Ay karanlık gecelerde yüzen gemiler Sevilip sevdikten sonra İnsan böyle yalnız mı kalır Bahtına hatırlamak mı düşer Ne...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇADIR KUŞAĞI', 'cadir-kusagi-salim-jabran-1u1jt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstersem gülümserim,
kolay ne var bundan.
Ama karanlığı kalacak gözlerimde
mezar çiçeklerinin,
bir yaşlı selvinin karanlığı kalacak,
alt üst olmuş yurdumun köylerinde,
acı sessizlikle kuşatılmış yurdumun köylerinde,
yıkıntılar arasında güçbelâ ayakta duran
bir yaşlı selvinin.
Hangi halkı parçalamıştır tarih,
parçaladığı kadar benim halkımı?
Halkım benim oldu toprağımdan,
saçıldı dört bir yana halkım benim.
Daldı yurdum uykuya
iççekişleri arasında ufkun.
Bense burdayım,
gözlerim kapkara, zifir gibi,
çadırların karanlığını taşır gözlerim.
Çocuk dudakları değil bu dudaklar artık,
analarını çağıran dudaklar değil,
döndüler kuru bir ekmeğe,
çağırmazlar hiç kimseyi.
Siz orda barıştan dem vurun hâlâ,
ben burda durayım köksüz.
Ben burda boşluğa asılmış bir tavan.
Çadırlarda büyüyen bir kuşağım ben,
ben, çadırlarda çoğalan.
Bir daha kulak verin,
bir daha dinleyin beni:
Büyüyen ve çoğalan bir kuşağım
ben kara çadırlarda.
Kalsın sizin ekmeğiniz sofranızda.
Uyuyayım ben burda aç ve susuz.
Ama tarih dört açsın gözünü
bizim çadır kuşağına.
Salim JABRAN', 'İstersem gülümserim, kolay ne var bundan. Ama karanlığı kalacak gözlerimde mezar çiçeklerinin, bir yaşlı selvinin karanlığı kalacak, alt üst...', ARRAY['Türk Edebiyatı','Şiir','Salim Jabran']::text[], 8.5, '{"poet":"Salim Jabran","poet_slug":"salim_jabran","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADLİ BİR HATA', 'adli-bi-r-hata-guven-turan-c2db6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç kez vurulmuştu;
Yanılamazdı:
Öldürmektir Aşk.
Onun için elini
Tabancasına attığında
Bilmiyordu böyle biteceğini
Bu vukuatın:
Hâlâ yüreğini yokluyor
Duruşmasında.', 'Kaç kez vurulmuştu; Yanılamazdı: Öldürmektir Aşk. Onun için elini Tabancasına attığında Bilmiyordu böyle biteceğini Bu vukuatın: Hâlâ yüreği...', ARRAY['Türk Edebiyatı','Şiir','Güven Turan']::text[], 8.5, '{"poet":"Güven Turan","poet_slug":"guven_turan","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADSIZ BİR ÇİÇEK', 'adsiz-bi-r-ci-cek-edip-cansever-lwc2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rengini dünyaya ilk defa sunan
Adsız bir çiçek gibi parlıyorsa gözlerim
Sevgilim
Bana ''sen bir şairsin'' dediğin zaman.
Yalnız sana yazıyorum bu şiiri
İstersen bir şiir gibi okuma
Çünkü her yıl yeniden yazacağım onu
Soğuklar başlayınca havalanıp
Millerce yol katettikten sonra
Güneyi tadan bir kuşun sevinciyle.
Ve yazmış olacağım bir de
Her dönemde her çağda
Sevdanın kendine özgü diliyle.', 'Rengini dünyaya ilk defa sunan Adsız bir çiçek gibi parlıyorsa gözlerim Sevgilim Bana ''sen bir şairsin'' dediğin zaman. Yalnız sana yazıyorum...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip_cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ADSIZ', 'adsiz-jaroslav-seifert-c6eec', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belki de bugünkü kadar hiç
duyumsamadık avuçlarımızda
bize özgürlük getiren
kızarmış ellerin sıcaklığını.
Henüz yitmedi kulaklarımızda daha
yıpranmış silahlarının uğultusu.
Sokaktaki insanlarımızın kolları
Gene açık eskisi gibi kucaklamaya.
Yüzünüzde bunca gerçek gözyaşları,
kucak açtığında ölülerine toprağımız,
hâlâ sıcak ve yakıcı gözyaşlarımız.
Evet, söylüyorum bunu bütün dünyaya!
Ve bütün yüreğimle haykırıyorum size:
Yaralamayın n''olur bu sevdayı!
Hayalleri paramparça olan ülkemizde
bir o kaldırabilir bunca acıyı.
Jaroslav SEIFERT', 'Belki de bugünkü kadar hiç duyumsamadık avuçlarımızda bize özgürlük getiren kızarmış ellerin sıcaklığını. Henüz yitmedi kulaklarımızda daha ...', ARRAY['Türk Edebiyatı','Şiir','Jaroslav Seifert']::text[], 8.5, '{"poet":"Jaroslav Seifert","poet_slug":"jaroslav_seifert","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞECE', 'asece-ali-yuce-pf8ji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hem yoktu hem vardı
Büyük bir kentin
Gecekondu semtinde
Küçük bir kız vardı
Adı Ayşece
Nar tanesi kar tanesi
Anasının bir tanesi
Gözleri vardı boncuk
Elleri vardı pamuk
Herkes onu çok severdi
Günlerden bir gün
Gide de gelmeye o gün
Bulut oldu yel oldu
Yağmur yağdı sel oldu
Alıp  götürdü evini anasını
Ayşece''yi öksüz koydu
Bir bekledi iki bekledi
Ayşece''nin babası
Eli balyoz dili yılan
Bir kadınla evlendi
Dövdü günde üç öğün
Güzel kızı çirkin analık
Yanık ekmek yedirdi
Su içirdi boz bulanık
Evden kaçtı Ayşece
Az gitti uz gitti
Kırk gece kırk gündüz gitti
Baktı analık arkasında
Ha ulaştı ha ulaşacak
Bir kayaya seslendi
Açıl kayam açıl
Şıkırt açıldı kaya
Ayşece girdi içine
Kapan kayam kapan
Şıkırt kapandı kaya
Güzel Ayşece içerde
Eteği dışarda kaldı
Gördü eteği analık
Yalancıktan ağladı
Açıl kayam açıl
Kaya açılmadı
Bir gelinböceği olup
Pır pır uçmaya başladı
Bakakaldı analık', 'Hem yoktu hem vardı Büyük bir kentin Gecekondu semtinde Küçük bir kız vardı Adı Ayşece Nar tanesi kar tanesi Anasının bir tanesi Gözleri var...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüce']::text[], 8.5, '{"poet":"Ali Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":46}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞAFAK BEKÇİSİ', 'safak-bekci-si-huseyin-avni-ci-nozoglu-jqwj8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'deniz kızları pervane şehrin ucundaki fenere
gözlerimizdeki yıldızlar aydınlatıyor geceyi
Bizans surları Osmanlı bedestenleri Hünkâr camileriyle
bu şehirde hâlâ güneşe açık bir pencerem var
çocukluğum tahta sandalyeli kasaba
sinemasında
nehirde yankısı abla kemancının
nektar içen bir nergis miydi ablam
kıyısını denizlerin süslediği bir şehrin
yağmurlar dağılır camlarında seferberlik
trenlerinin
halkım asırlarca hatırlayacak mutlu sultanlığımı
kemanlarını kutusuna koyarken abla kemancılar
iki perde arası beni hatırlayacaklar bir de Peruz’u
göçerlerin bey sandığı bu delinin kandili
şehrin en güzel masalı asırlar sonra da
buluttan saraylara taç yapan çocuklar
bakır akşamların alaşımında seyredecekler sultanlığımı
ve seslenir çocuğun gözlerindeki yıldız:
-Şafağın tek bekçisi olduğun yetmez mi…', 'deniz kızları pervane şehrin ucundaki fenere gözlerimizdeki yıldızlar aydınlatıyor geceyi Bizans surları Osmanlı bedestenleri Hünkâr camiler...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avni Ci̇nozoğlu']::text[], 8.5, '{"poet":"Hüseyin Avni Ci̇nozoğlu","poet_slug":"huseyin_avni_cinozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞAFAKTA', 'safakta-ahmet-hasi-m-7bpm3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönsek mi bu aşkın şafağından
Gitsek mi ekaalîm-i leyâle?
Bizden daha evvel erişenler
Ağlar bugün evvelki hayâle.
Dönmek mi? Ne mümkün geri dönmek
Düştüyse gönüller bu melâle?
Bir eldir ufuklardan uzanmış
Zulmet bizi çekmekte visale...', 'Dönsek mi bu aşkın şafağından Gitsek mi ekaalîm-i leyâle? Bizden daha evvel erişenler Ağlar bugün evvelki hayâle. Dönmek mi? Ne mümkün geri ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AFFET BİZİ LAMBA', 'affet-bi-zi-lamba-cahit-sitki-taranci-6rtch', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle sarmaş dolaş olduk,
O kadar geçtik ki kendimizden
Lambayı söndürmeyi unutmuşuz,
Perdeleri çekmeyi de.
Meğersem sabah olmuş;
Gün pencereden bizi gözetler.
Cânım geceye veda etmek lazım;
Günün gösterdiği yoldan gitmek lazım,
Affet bizi lamba,
Seni buralara kadar sürükledikse,
Geceki sarhoşluğumuza bağışla.
Vakit varken dönsen memleketine;
Tutsak biz de her günkü yolumuzu.
Haydi uğurlar olsun;
Gecemiz sana emanet.', 'Öyle sarmaş dolaş olduk, O kadar geçtik ki kendimizden Lambayı söndürmeyi unutmuşuz, Perdeleri çekmeyi de. Meğersem sabah olmuş; Gün pencere...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AFRİKA', 'afri-ka-leopold-s-dar-senghor-l8e7g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Afrika Afrika''m benim.
Başeğmez savaşçıların Afrika''sı
Hani o ata yadigârı ovalara adını yazmış
Hani o büyükannemin şarkılarındaki
Karşı ırmak boylarındaki
Savaşçıların Afrika''sı
Ben seni hiç görmedim
Kanın damarlarımda oysa
O güzelim kara kanın
Kırları bayırları sulayan
O güzelim kara kanın
Bulaşır terlerine
Kölelikten canı çıkan çocuklarının
Afrika söyle bana Afrika
Senin sırtın mıdır bu
İki büklüm ezilgin olan
Küçük görmelerin ağırlığı altında
Kızıl yaralar açan sırtında çiçek çiçek
Kırbaç kırbaç inleyen sen misin yaz sıcağında
Erkek bir ses yanıtlıyor
Mert oğlum büyüyor işte yiğit ve güçlü
Burada bunca viranlığın ortasında
Beyaz soluk çiçeklerden bir ağaç
Afrika bu senin Afrikan
Yeniden dallanıp yeşeriyor bak sabırla inatla
Sunarak ürünlerine yavaş yavaş
Acı tadını özgürlüğün.
Leopold Sédar SENGHOR', 'Afrika Afrika''m benim. Başeğmez savaşçıların Afrika''sı Hani o ata yadigârı ovalara adını yazmış Hani o büyükannemin şarkılarındaki Karşı ırm...', ARRAY['Türk Edebiyatı','Şiir','Leopold Sédar Senghor']::text[], 8.5, '{"poet":"Leopold Sédar Senghor","poet_slug":"leopold_sedar_senghor","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AFRİKA''NIN YÜREĞİNDE SABAH', 'afri-ka-nin-yuregi-nde-sabah-patrice-lumumba-zjcwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Binlerce yıl, Afrika''m, bir hayvan gibi acı çektin,
Çölü yalayıp geçen rüzgârda savruldu küllerin.
Gözalıcı, büyülü tapınaklar yaptı zalimler
Ruhunu acılardan kurtarmak için
Barbarların yumruğu, beyazların kırbacına karşı
Yalnız ölmekti senin hakkın bir de ağlamak,
Totemine bitip tükenmez açlık, tutsaklıklar oydular,
Ağaçların kabuğunda bile korkunç, zalim bir ölüm
Sinsice seni gözlüyor, sana doğru geliyordu
Ağaçların deliklerinden, ucundan çıkan dallar gibi
Ölüm vücudunu, tedirgin ruhunu sarıyordu.
Göğsünün üstüne kocaman hain bir engerek yılanı koydular:
Boynuna sert içkilerden bir boyunduruk geçirdiler,
Canın ciğerin karını aldılar elinden, ucuz incilerle göz boyayıp
Varını yoğunu inanılmaz, paha biçilemez.
Kulübenden tamtam sesleri karanlık geceye,
Yüce kara ırmaklara zalim sesler ile taşıdı;
Aldatılan kızların, gözyaşlarının, kanların,
Ve küçük adamların kaynaştığı, doların kral olduğu
Anavatan dedikleri o ilençli ülkelere giden
Gemilerin öyküsünü söyleyip.
İşte orada çocuğum, öğüttüler karını gece gündüz
Amansız, korkunç bir değirmende, yok oldu büyük acılar içinde,
Sen de ötekiler gibi birisin. İyi kalpli beyaz Tanrının
Sonunda bütün insanları uzlaştıracağına inanmanı istiyorlar.
Ateşler yakıp ağladın, içler acısı şarkılarını söyledin
El kapılarına çöken evsiz barksız dilencinin
Derken bir şeyler oldu, bir şeyler kımıldadı içinde
Kanın yanıp tutuştu geceleyin
Dans ettin, bağırdın babadan kalma tutkuyla.
Bir fırtına gibi azgın, ama insancıl bir tonda
Bir güç doğuverdi binlerce yıllık felaketten sonra.
Cazın madensel sesinde, önlenmesi güç bir bağırışla
Bir dev kıpırdanışıyla sarstın her yeri.
Şaşırdı herkes, duman oldu bütün dünya
Kanının çılgın ritmini, cazın delice ritmini duyup
Sapsarı kesildi beyazlar bu yeni şarkıyla
Mor meşaleyi karanlık geceye diken bir şarkıyla.
Sabah işte, kardeşim! Sabah! Yüzüme bak,
Yeni sabahlar başlıyor eski Afrika''da.
Yalnız bizim olacak artık bu ülke, bu su, bu kutsal ırmaklar,
Binlerce yıl anası ağlayan zavallı Afrika.
Tüm gücüyle güneş bizim için parlayacak,
Gözümüzün yaşını, suratımızdaki tükürükleri kurutarak,
Zinciri kopardığın an, koca zinciri,
Kötülüklerin, işkencelerin köküne kibrit suyu,
Hür ve şen bir Kongo doğacak kara topraktan,
Hür ve şen bir Kongo - kara çiçek, kara tohumdan!
Patrice LUMUMBA', 'Binlerce yıl, Afrika''m, bir hayvan gibi acı çektin, Çölü yalayıp geçen rüzgârda savruldu küllerin. Gözalıcı, büyülü tapınaklar yaptı zalimle...', ARRAY['Türk Edebiyatı','Şiir','Patrice Lumumba']::text[], 8.5, '{"poet":"Patrice Lumumba","poet_slug":"patrice_lumumba","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AGOROFILIA', 'agorofilia-henrik-nordbrandt-5mqkl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdamsın sen, umutsuzluğum.
Çılgınlığımsın sen, yeteneğimsin.
Ve henüz bulunmadığım bütün yerlersin
dünyanın dört bucağından beni çağıran.
Şu altı dizesin sen
haykırmamak için kendimi sınırladığım.
Henrik NORDBRANDT', 'Sevdamsın sen, umutsuzluğum. Çılgınlığımsın sen, yeteneğimsin. Ve henüz bulunmadığım bütün yerlersin dünyanın dört bucağından beni çağıran. ...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AH, BEN UYKUDAYKEN SEN BAŞUCUMA GELSEN', 'ah-ben-uykudayken-sen-basucuma-gelsen-victor-hugo-a1s65', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah, ben uykudayken sen başucuma gelsen,
Petrarca''yı ziyaret ettiği gibi Laura''nın, (1)
Değse bana nefesin tam yanımdan geçerken,
İşte o zaman birden
Aralanır dudağım!
Kaç zamandır tutsağı karanlık bir hayalin,
Bitmeli mi bu rüya? Şu kederli yüzüme,
Bir yıldız gibi doğsun senin o gözlerin,
İşte o an düşlerim
Aydınlanacak yine!
Bir kıvılcımın uçuştuğu dudaklarıma
Tanrı''nın arıttığı o aşk parıltılarına,
Bir öpücük kondur, melekten kadına dön,
Ah o zaman ruhum
Uyanır uykusundan!
(1)İtalyan ozanı Petrarca (1304-74) şiirlerinden birinde ölümünden sonra
şiirlerinin kadın kahramanı Laura tarafından mezarının ziyaret edildiğini düşler.
VICTOR HUGO', 'Ah, ben uykudayken sen başucuma gelsen, Petrarca''yı ziyaret ettiği gibi Laura''nın, (1) Değse bana nefesin tam yanımdan geçerken, İşte o zama...', ARRAY['Türk Edebiyatı','Şiir','Victor Hugo']::text[], 8.5, '{"poet":"Victor Hugo","poet_slug":"victor_hugo","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AH LEN AH', 'ah-len-ah-enver-gokce-fkt9y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üşürülmüş
Yılan
Dilli
Bir
Hançerdi
Kardeşim
Yüreğime
Göğsüme
Kollarıma
&quot;Bir
Dönüm
Mülk
Kan
Değerdi
Bizim
Buralarda
Kebanda
Ezirganda
Al
Sizin
Olsun
Helal.
Benden&quot;
Sırtımda
Alacalı
Mintan
Boynumda
Yazma
Afilli
Kasketim
Düşmüş
Yere
Ayağımda
Kara
Kabar
Ayağımda
Soğuk
Kuyu
Lastiği
Boynu
Buruk
Kalmışım
Böyle
Ah
Len
Ah.', 'Üşürülmüş Yılan Dilli Bir Hançerdi Kardeşim Yüreğime Göğsüme Kollarıma &quot;Bir Dönüm Mülk Kan Değerdi Bizim Buralarda Kebanda Ezirganda Al...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver_gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AH ULAN RIZA', 'ah-ulan-riza-yusuf-hayaloglu-x8lq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neden halâ gelmedi, yoksa
Saati mi şaşırdı hıyar?
Gerçi hiç saati olmadı ama
En azından birine sorar.
Cebimde bir lira desen yok,
Madara olduk meyhaneye!
Ah eşşek kafam benim,
Nasıl da güvendim bu hergeleye!
Gelse, balığa çıkacaktık,
Ne çekersek kızartıp birayla yutacaktık.
Kafamız tam olunca, şarkılar döktürüp
Enteresan hayâllere dalacaktık.
Bu sandalı geçen hafta denk getirip
Çalıntıdan düşürdük.
Arkadaşlar ısrar etti,
Biz de, iyi olur, bize uyar diye düşündük.
Saat sekizde gelecekti,
Bana birkaç milyon borç verecekti.
Yoksa o nemrut karısı kaçtı da
Onun peşinden mi gitti?
Eğer öyleyse yandık,
Gudubet gene yaptı yapacağını!
Geçen sene de merdivenden itip
Kırmıştı Rıza''nın bacağını.
Abi, kadında boy şu kadar;
Kalça fırıldak, göz patlak, kafa çatlak!
Korkuyorum, bir gün ya kendini asacak,
Ya horlarken Rıza''yı boğacak!
Bak, şimdi acıdım, aşkolsun adama,
Ben olsam, vallahi baş edemem!..
Hele beş tane velet var ki boy-boy,
Allah''tan düşmanıma dilemem!
Aslında iyi çocuktur Rıza, efendi huyludur,
Herkesin suyuna gider.
Yoksa, kalıba vursan hani,
Tek başına on tane adam eder!
Bir keresinde, hiç unutmam
Üç-beş zibidi haraca dadandı;
Rıza, sandalyeyi kaptığı gibi
Herifleri hastaneye kadar kovaladı!
Aynı mahallede büyüdük, aynı kızları sevdik,
Aynı kafadaydık.
Orta ikiden bıraktık, matematik ağır geliyordu,
Biz, başka havadaydık.
Aynı gömleği giyer, aynı sigaraya takılır,
Aynı takımı tutardık.
Fener''in her maçına iddialaşıp
Millete az mı yemek ısmarladık!..
Bir tek askerde ayrıldık,
Bana Bornova düştü, ona Gelibolu.
Döner dönmez evlendirdiler,
En büyük salaklığı da bu oldu!..
Bense hiç düşünmedim, zaten param yoktu.
Hep tek tabanca gezdim.
Benim beğendiğimi anam istemedi,
Onun gösterdiğini ben sevmedim.
Neyse, bunlar derin mevzu...
Anlaşıldı, bu herif artık gelmeyecek.
Ufaktan yol alayım
Anam evde yalnız, şimdi merağından ölecek!..
Gittim, vurup kafayı yattım;
Rüyamda gördüm, gülümseyerek geldiğini.
Ne bilirdim, yolda kamyon çarpıp
Hastaneye kavuşmadan can verdiğini!..
Vay be Rıza!..
Sonunda sen de düşüp gittin Azrail''in peşine!
Dün, boşuna günahını almışım,
Ne olur, kızma bu kardeşine!
Öğlen kahvede söylediler, Rıza öldü, dediler
Ne kolay söylediler!
Sanki dev bir taş ocağını
Kökünden dinamitleyip üstüme devirdiler!
Ah dostum... o kocaman gövdene
O beyaz kefeni nasıl kıyıp giydirdiler?
O zalim tabutun tahtalarını
Senin üstüne nasıl böyle çivilediler?
Yani sen şimdi gittin, yani yoksun,
Yani bir daha olmayacak mısın?
Yani bir daha borç vermeyecek,
Bir daha bira ısmarlamayacak mısın?
Peki, beni kim kızdıracak,
Kim zar tutacak, kim ağzını şapırdatacak?
Peki, beni bu köhne dünyada
Senin anladığın kadar kim anlayacak?
Ulan Rıza... ne hayâllerimiz vardı oysa,
Ne acayip şeyler yapacaktık...
Totoyu bulunca dükkân açacak,
Adını Dostlar Meyhanesi koyacaktık.
Talih yüzümüze gülecekti be!..
Karıyı boşayıp sıfır mersedes alacaktık.
Hafta sonu iki yavru kapıp
Boğaz yolunda o biçim fiyaka atacaktık!
Ah ulan Rıza... bu mahallenin,
Nesini beğenmedin de öte yere taşındın?
Ara sıra gıcıklaşırdın ama inan ki,
Benim en kıral arkadaşımdın!..
Ah ulan Rıza... ben şimdi,
Bu koca deryada tek başıma ne halt ederim?
Senden ayrılacağımı sanma,
Bir kaç güne kalmaz, ben de gelirim!..', 'Neden halâ gelmedi, yoksa Saati mi şaşırdı hıyar? Gerçi hiç saati olmadı ama En azından birine sorar. Cebimde bir lira desen yok, Madara old...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":102}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AHŞAP RUHA TEN GİYİNMEK', 'ahsap-ruha-ten-gi-yi-nmek-abdulkadir-budak-k1514', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bu kadar boğulmadım içimdeki bir gölde
Sunu yazısı başlığı olacaktı kitabında
Yaprak bir ormanı algılıyorken
Parkla insan yüzlerini karıştırdı her zaman
Ferit çünkü benziyordu parklara
Bir parti marşının sözlerini yazmayı
İsteyen bir adamdan kara bir cümle daha
İçeriği boşaltılan bir anlamda yaşıyoruz
Ten giyinmek zorundayız bu ahşap ruha
Hepimiz Yesenin''dik yani şehrin kır kokusu
Yanlış yerlerde gezerdik polis götürürdü bizi
Başımız derde girerdi Haydar açıklayınca
İçimizdeki ıssızlıktan başlardı Haydar
- Bırak ulan felsefeyi! dedirtirdi sonunda
Ah Ferit neden öldün park değildir mezarlık
Dördümüzü bine böldün ve böylece azaldık', 'Hiç bu kadar boğulmadım içimdeki bir gölde Sunu yazısı başlığı olacaktı kitabında Yaprak bir ormanı algılıyorken Parkla insan yüzlerini karı...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AHLAK', 'ahlak-melih-cevdet-anday-uax8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ahlak kalmadı dünyada
Kiracısı öyle, işçisi öyle
Hami köylü saftır derler a
İnanma
Cırrr
Kapı
Kim o?
Dilenci.
Kuru ekmek verirsin beğenmez
Taze ekmek senin nene!
Kalmadı, dedim ya, kalmadı
Ahlak kalmadı memlekette.', 'Ahlak kalmadı dünyada Kiracısı öyle, işçisi öyle Hami köylü saftır derler a İnanma Cırrr Kapı Kim o? Dilenci. Kuru ekmek verirsin beğenmez T...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AHLAT AĞACI', 'ahlat-agaci-mehmet-basaran-47vu9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eşin dostun yaşıyor bak bahçelerde
Sen çıplak bir doruğun üzerindesin
Tam rüzgârın engini sardığı yerde
Yekpare bir mavilik üstünden akar
Altında köklerini sıkan toprak var
Dertleşir durursun gölgenle
Bazan öyle yakın geçer ki kayan yıldızlar
Halini soruverecekler sanırsın
Dağılır üstündeki yeşil sükût
Ümitle kımıldanırsın
Bakma sana bir ad verdiklerine
Yerle gök arasında bir karaltısın
Ve bütün dünya seni unutmuş
Sanki kim bilecek yaşadığını
Gelmese dallarına birkaç fakir kuş
Ne de dolmaz çilen varmış
İlk defa kırağı yaktı canını
Aşkı sonra bulutların
Rüzgârın cilvesi değil miydi
Döken yapraklarını
Durmuşsun kırların bir ucuna
Ah senin halin köylü hali
Yaşarsın kıraç toprakta
Servi-simin misali', 'Eşin dostun yaşıyor bak bahçelerde Sen çıplak bir doruğun üzerindesin Tam rüzgârın engini sardığı yerde Yekpare bir mavilik üstünden akar Al...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AHMED ARİF', 'ahmed-ari-f-ahmed-arif-7726v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '«Bir şair: Ahmed Arif
Toplar dağların rüzgârlarını
Dağıtır çocuklara erken»
«Hasretinden Prangalar Eskittim» kitabıyla Ahmed Arif’in
şiiri de gün ışığına çıktı. Böylece Ahmed Arif’in Türk şiirinde zaten öteden
beri sağlamış bulunduğu yer, okurun gözünde de matematik bir kesinlik kazandı.
Sanırım, bu yer, bundan sonra en az tartışılır yerlerden biri olarak kalacaktır.
Şu yaşadığımız günler sarsıntılı, karmaşalı günler. Çok hareketli günler. Ama bu
arada fikir ve sanat hayatımızda yerleşik değerler ile yeni değerler arasında,
yerleşik değerlerin kendi içinde, yeni bir trafik doğmuş bulunuyor. Şimdiye dek
şu yönden bakılmış değerlere şimdi bir de bu yönden bakılmakta, dayanıksız
değerler ufalanmakta, silinmekte, çok şeyin hesabı görülmektedir. Ayrıca sağlam
değerler yerlerini bulmaktadır, ya da bulmaları için pek bir şey kalmamaktadır.
Bunun için, iyidir diyorum, bu sarsıntı, bu karmaşa. Daha önce şairler arası bir
«pazarı» olan Ahmed Arif de bu arada bu durumdan fırlayıp okura uzanmak
olanağını buldu, ya da gereğini duydu.
Ahmed Arif Diyarbakır’lı. İlk şiirleri 1948-1951 yılları arasında bir iki
dergide göründü. O günlerde kendisi Ankara Dil ve Tarih Coğrafya Fakültesinde,
felsefe bölümünde öğrenciydi. Sonra tutuklandı. İlk şiirlerini ortaya çıkardığı
sıralarda Orhan Veli ve
arkadaşları şiire iyice hâkim görünüyorlardı. Garip dönemi bitmiş, Sabahattin
Eyuboğlu''nun deyimiyle “halk olarak sanatın” dolaylarında dolaşılmaya
başlamıştı. Bütün gençler, bütün yeni yetmeler
Orhan Veli''ye,
Oktay Rıfat''a,
Melih Cevdet Anday''a
öykünüyordu. Sanki şiir yalnız onların yazdığıydı; onların yazdığından başka
şiir olamazdı sanki. Gençlerin bu bilinçsiz tutumu şiirimize zararlı olmuştur.
Ama genç sanatçıların çoğu böyle olmakla birlikle, aralarında kendi çıkış
noktalarını geliştirmeye çalışan, Orhan Veli ve arkadaşlarına pek kulak asmayan
kimseler de yok değildi. Ahmed Arif’i de bunlardan biri olarak görüyoruz. İlk
şiirinde bile. Gariple gelen şiirin içeriğine aldırmamıştır. Önerilmekte olan ve
bir çeşit şiirsiz şiir diyebileceğimiz hareketi umursamadan kendi doğrultusunda
çalışan birkaç şairden biri de odur.
Ahmed Arif’in şiiri bir bakıma Nâzım
Hikmet çizgisinde, daha doğrusu Nâzım Hikmet''in de bulunduğu çizgide
gelişmiştir. Ama iki şair arasında büyük ayrılıklar var. Nâzım Hikmet,
şehirlerin şairidir. Ovadan seslenir insanlara, büyük düzlüklerden. Ovada akan
«büyük ve bereketli bir ırmak» gibidir. Uygardır. Ahmed Arif ise dağları
söylüyor. Uyrukluk tanımayan, yaşsız dağları «âsi» dağları. Uzun ve tek bir ağıt
gibidir onun şiiri. «Daha deniz görmemiş» çocuklara adanmıştır. Kurdun kuşun
arasında, yaban çiçekleri arasında söylenmiştir, bir hançer kabzasına
işlenmiştir. Ama o ağıtta, bir yerde, birdenbire bir zafer şarkısına
dönülecekmiş gibi bir umut (bir sanrı, daha doğrusu bir hırs), keskin bir
parıltı vardır. Türkü söyleyerek çarpışan, yaralıyken de, arkadaşları için tarih
özeti çıkaran, buna felsefe ve inanç katmayı ihmal etmeyen bir gerillanın
şiiridir. Karşı koymaktan çok, boyun eğmeyen bir doğa içinde. Büyük zenginliği
ilkel bir katkısızlık olan atıcı, avcı bir doğa içinde.
1959-1962 yılları arasında Ankara''daydım,
Muzaffer Erdost
tanıştırmıştı bizi. Hemen dost olmuştuk. O sıra, Muzaffer Erdost Ulus
gazetesinin basımevi müdürüydü. Ahmed Arif de Medeniyet gazetesinde çalışıyordu.
Haftanın üç-dört günü beraberdik. Daha doğrusu üç-dört gecesi. Ben, geceye
doğru, saat 11-12 sıralarında Ulus gazetesine giderdim. O ara, kendi gazetesini
erkenden bağlamış bulunan Ahmed Arif de oraya gelmiş olurdu. Muzaffer''in
odasında oturur, sabaha kadar konuşurduk. Nelerden konuşurduk? Her şeyden.
Sabahleyin, yürüye yürüye Kızılay''a kadar gidilir, orada ayrılınırdı. Yaz, kış,
hep böyle. Bu sıkı ilişki birbirimizi iyice tanımamıza yardım etti. Her şairin
konuşma tarzıyla (hattâ yüzüyle) şiiri arasında bir yakınlık, bir benzerlik
vardır muhakkak; ama konuşmasıyla şiiri arasında bu kadar bir özdeşlik bulunan
bir şaire ilk kez Ahmed Arif’te raslıyordum. Onun şiiri, konuşmasından alınmış
herhangi bir parça gibidir; konuşması ise, şiirin her yöne doğru bir devamı
gibi. Bir bakıma «Oral» (ağza ilişkin) bir şiirdir onunki. Bizde oral şiirin
tuhaf bir kaderi vardır: bu şiirde, genellikle, ya kuru bir söylevciliğe
düşülür, ya da harcıâlem duyguların tekdüze evrenine. Daha doğrusu, nedense
şimdiye kadar genellikle böyle olmuştur. Bu, sözün yakışığı uğruna, şiirin elden
çıkarılması, harcanmasıdır. Ahmed Arif’in şiirinde böyle bir sakınca yok. Hiç
bir zaman söyleve düşmez. Bir duygu sağnağı, imgeler halinde, sıra sıra mısralar
kurar. Ana düşünce, dipte, her zaman belirli, ama sakin durur; çoğalır, büyür
belki, ama kalın bir damar halinde hep dipte durur. Ahmed Arif, kendi şiirine en
uygun yapıyı ve mısra düzenini bulmuş bir şairdir. Anlatımıyla, şiirin özü
arasında özdeşlik vardır. Türkçe destan türünün en ilginç deneylerini yapmıştır.
En ilginç çıkışını desek daha yerinde olacak Bir yalçınlığı koyuyor şiirine
Ahmed Arif, bir graniti. O yalçınlıktan, birden, sınır köylerine iniyor;
«tavukları birbirine karışan» insanları anlatıyor. Bu birdenbirelik onu kekre
diyebileceğimiz bir lirizme ulaştırıyor. Ya da tersi oluyor. Eksiksiz bir silah
koleksiyonunun arasından görüşmecisinin yolladığı taze soğan demetini
görüyorsunuz. Ahmed Arif, Doğu Anadolu''nun, sınır boylarının yersel görüntüleri
içinde oraların türkülerini kalkındırıyor, bütün Anadolu türkülerine ulaştırıyor
onları, büyütüyor, besliyor; ama boğulmuyor onların arasında. Doğu Anadolu
insanının müthiş malzemesini korkusuz bir lirizm içinde önümüze yığıyor. Sonra
bütün Anadolu insanına doğru yayıyor onu.
Pir Sultan Abdal''ı, Urfa''lı
Nazif''i, Köroğlu''na, Bedrettin''e
götürüyor. Büyük bir sevgiye, bir umuda çağırıyor Anadolu insanını; gözlerinden
öperek, çıldırasıya severek. Evet, halk türkülerinden yararlanıyor Ahmed Arif.
Yalnız, halk kaynağının, edebiyat için, şiir için, türkülerden öte daha bir sürü
olanak taşıdığını, hatta öbür halk kaynakları içinde türkülerin o kadar da büyük
bir ağırlık taşımadığını iyi biliyor. Bu yanıyla halk kaynağına eğildiklerini
sanan başka şairlerden ayrılıyor. Onlar gibi sadece türkülere yaslanmıyor.
Özellikle destan türü için vazgeçilmez olan tavrı tâ temelden takınıyor.
Çalışmalarını ona göre yapıyor.
Ahmed Arif kendi şiirine en uygun yapıyı ve mısra düzenini getirmiştir, dedik.
Bir de, Paul Eluard için söylenmiş
bir sözün onun şiirine de uyduğunu söyleyelim: Paul Eluard’ın şiiri imgenin
tutsağı değildir; gerçeküstücü döneminde de, ondan sonraki dönemde de, şiirin
temelinde yatan ana öğe, mısraların kısalığı, kuruluş tarzı ve bunların
birbirleriyle bağlama biçimi sayesinde ipuçlarını hiç bir zaman saklamamıştır.
Ahmed Arif’te de öyle. İmge, çıplaklığın çarpıcılığını taşır; düşünce, vurucu
özelliğini ilk anda kullanır. «Hasretinden Prangalar Eskittim»de bunun birçok
örneğini görüyoruz. Sonra imge onda sınırlı bir öğe değil. Bir bakıma şiirin
kendisi, bütünü. Öyle ki bütünüyle vardır onun şiiri. Kelimeler ilişkin
oldukları kavramları aşan ve daha geniş durumları kavrayan bir nitelik
gösteriyor. Şiirin bütünü içinde kullanılmış bazı düz sözler inanılmaz bir
çarpıcılık, bir imge yeteneği kazanmaktadır Ahmed Arif’te. Öte yandan, şiirin
içinde birer ikişer kelimelik mısralar halinde akan bu sözler biçim yönünden de
önem kazanmaktadır. Öyle ki, kendiliğinden doğan ve yalnız Ahmed Arif’e özgü
gizli bir aruz gibi bu sözlerden bütün şiire bir müzik yayılmakta, ya da bütün
şiir çekidüzenini onlarda bulmaktadır.
Sözgelimi, Otuzüç Kurşun''da:
Yakışıklı
Hafif
İyi süvari
mısralarının;
yine aynı şiirde:
ve karaca sürüsü
Keklik takımı...
mısralarının böyle bir işlevi vardır.
Bu, Mayakovski''nin ritm
elde etmek için yaptığı biçim çalışmalarını akla getiriyorsa da, aslında bu
noktada iki şairin tutumlarını birbirine karıştırmamak gerekir. Mayakovski için,
ritm, bir yerde, her şeydir; «şiirin temel gücünü» ritmde bulur o; bir
endüstriye benzettiği şiir için ritm manyetik gücü ya da elektriklenmeyi temsil
eder. Ahmed Arif için ise ritm sadece bir olanak olarak önemlidir. Ama
aralarındaki asıl ayrım surda sanırım: Mayakovski''de ritm, bir bakıma, şiirin
dışında bir yerdedir, anonim bir tekniktir. Bunun için sık sık düşey ya da yatay
ses benzerliklerine, bağdaşımlarına başvurur. Daha özetlersek: Mayakovski ritmi
ses''te aramaktadır. Ahmed Arif ise söz''de arar. Bunun için onun şiiri bir
noktada «oral» niteliğini bırakır, çok ötelere gider. Bu yanıyla çağdaş şiirin
en yeni yönsemelerine karışır. Özellikle imge konusunda yaptığı sıçrama onu
bugünkü şiiri hazırlayanlardan biri yapmıştır. Zaten birçok şairin onun
etkisinden geçmesi de bunu gösteriyor. Sadece bu bakımdan bile «Hasretinden
Prangalar Eskittim», geç kalmış bir kitap değildir. Bir de şu bakımdan geç
kalmış bir yapıt değildir «Hasretinden Prangalar Eskittim»: Yaşsız bir şiirdir
Ahmed Arif’in şiiri. Günün değil, çağın değil, çağların «aktüalite»siyle
doludur. «Künyesi çizileli» kimbilir kaç yıldız uçmuştur. Dirsek teması içinde
bulunduğu köylülerin, yürüyerek gezdiği kasabaların arasından tarihi kalın
çizgilerle görmeyi sever. Tarihi ve uygarlığı. Yalnız, «Diyarbekir
Kalesinden Notlar ve Adiloş Bebenin Ninnisi»nde daha güncül bir tavrı var.
Otuzüç Kurşun''da da biraz öyle. Bir yerde
tarihten önce yaşamış bir ozan konuşuyor sanırsınız, başka bir yerde en genç
kuşağın bir verimi karşısında gibisinizdir. Bu bakımdan elli yıl sonra da
yayımlansaydı aynı ilgiyi görecek, sevilecekti bence.
Hollanda''ya gittiğimde orada Van Gogh''un sarılarının kaynağını bulmuş ve daha
çok sevmeye başlamıştım. Van Gogh''un resimlerindeki sarıları. Çünkü
Hollanda’daki coğrafya’nın yeryüzü şekillerinin, bitkisel örtünün sarıları Van
Gogh''u içimde somutlamış ve bir yere oturtmuştu. Onun çalışmasını gözümde daha
da büyütmüştü. Doğal verilerle yaratıcı çalışma arasındaki böyle bir ilişki
sanat yapıtının değerini artırıyor. Sanat yapıtı gerçeğin asalağı olmamalıdır,
ama bütün bütüne de ondan kopmamalıdır, ondan kopmayışın kanıtlarını
taşımalıdır.
Aynı şekilde, Erzurum toprağını gördükten, Doğu Anadolu''daki yeryüzü
şekillerini, iyice dolaşıp, içime sindirdikten sonra,
Aşık Veysel''in sesine daha çok tutuldum.
Van Gogh''un sarıları Hollanda toprağının baskın renklerini taşıyor, bir yerde
onlara katkıda bulunuyordu, onların arasında açılmış çılgın, sanrılı çiçekler
gibiydi. Aşık Veysel’in sesinde de Doğu Anadolu toprağının rengi, kıvamı, taşıl
niteliği, köy evlerinin içinden geçen arklar, yüzükoyun yatarak su içen
delikanlılar, genç kızlar vardı. Ahmed Arif’in şiirinde de, şiirini yaparken
kullandığı araçlarda da, anlattığı yerlerin, yapıtına koyduğu hayatın çok
tutarlı bir bileşkesini görüyorum. Özellikle destan timinde bunun nice önemli
olduğunu anlıyorum Ahmed Arifi okurken.
Cesareti söylüyor Ahmed Arif. Yiğitliği.
Bir pınar gibi, bir yeraltı suyu gibi, bir tipi gibi.
«Dostuna yarasını gösterir gibi».
Yücelerde yıllanmış katar katar karın içinde yürüyor yalnayak ve ayakları
yanarak.
Cemal SÜREYA', '«Bir şair: Ahmed Arif Toplar dağların rüzgârlarını Dağıtır çocuklara erken» «Hasretinden Prangalar Eskittim» kitabıyla Ahmed Arif’in şiiri d...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":170}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AHMED ZAATAR*', 'ahmed-zaatar-mahmud-dervi-s-qfgri', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kekikten ve karamış taştan
O eller için
Bu çığlık
Unutulmuş ve yapayalnız
Ahmed için.
Gelip geçen bulutlar
Yurtsuz ve yabancı koydu beni
Ve yalnız dağlar cesaret ediyor
Beni bağrına basmaya
Kıraç bir toprakta.
Doğuyorum yine o eski yaralardan
Sokuluyorum toprağa
Bütün ayrıntılarını görünceye dek
Doğuyorum yine
Denizin taştığı yıl
Kül olmuş kentlerden
Kendimi yapayalnız bulduğum.
Ahmed''di o deniz
Kurşunlar arasından köpük köpük
Bir kamptı öfkeyle büyüyen
Yağan kekikti üstümüze
Ve savaşçılara
Ellerine ayaklarına baktı Ahmed
Unutulmuş trenlerin
Anılarıyla büyüyen
Kimsenin karşılamadığı
Kimsenin el sallamadığı
Yaseminlerle.
Ayakta dikildi yapayalnız
Kendini dinlediği gecelerde
Hakkın hasretini çekerek
Yirmi yıl
Yirmi yıl o yer senin bu yer benim
Dolaştı bir kimliği sora sora
Yalnız yanardağların yanıtladığı.
Ben Arap Ahmet''im
Dedi
Ben kurşunlar
Ben portakallar
Ve düşler.
Benim çadırımdır Tel Zaatar
Anayurt benim
Sürüp giden o yolculuk anayurda
Doğu''dan ta Batı''ya
Bilendi bütün kılıçlar
Ahmed tanımaya başlarken
Ellerini ayaklarını
Süzülen bir yıldız gibi
Bakıp bakıp Hayfa'' ya.
Ahmed''di seçilen kurban
Kentler asfalt organlarını
Bırakıp arkalarında
Düştüler peşine Ahmed''in
Öldürmek için.
Doğu''dan ta Batı''ya
Cenaze törenini hazırlıyorlardı.
Giyotinlerden giyotin beğenip.
Ben Arap Ahmed
Gelsin kuşatmacılar!
Benim kal''am gövdem
Gelsin kuşatmacılar!
Ateş hattıyım ben
Kuşatacağım onları
Çünkü göğsüm
Sığınaktır halkıma
Gelsin kuşatma!
Uzanmış suyun karşısına
Küçük ayrıntılar arasında geziniyorum
Derken dağılmaya başlıyorlar
Akşamla birlikte
Yitiyorum
Uzaklardan gelen
Çıngırak seslerinin içinde.
Kanayan yerlerimden
Anlıyorum yaşadığımı.
Ayak bastığım her yol
Kaçınıyor benden
Kaçıyor
Gönül verdiğim her kent
Ceketimi fırlatıyor bana.
Şiirlere sığınıyorum
Düşlere
Anlıyorum çok geçmeden
Düşlerime kadar girmiş bıçaklar.
Bir mum yakıyorum
Kapanmayan yaramdan.
Bu gece
Bütün çakıl taşları soluyor
Ve damarlı.
Uzaklardaki güzel karım
Sessizliğin senin
Eritti bu ölgün geceyi
Banklar ve ağaçlar
Donup kaldı gölgende.
Hatırla beni
Kendimi unutmadan önce.
O kayalar mektubumdur
Yeryüzüne.
Yükseleceğim
Meyve küfelerinden
Denizden
Yükseleceğim yoksulun şarkısından
Onların şarkısından:
Yaşayacağız!
Yaşayacağız! diyen.
Kekikten ve taştan Ahmed
Yükseleceksin
Hayır! diyerek
Derinden esvap yapacak
Kırlardan gelen köylüler
Zalimleri ortadan kaldırmaya.
Bir çiçek olacak yumruğun
Bir bomba
Her gün hayır! demek için kalkan.
Kılıçlardan kesik kesik gövden
Yeniden yapılacak
Doğacak güneşlerden
Ve dalgalarla nikâhlanacak
Giyotin altında
Hayır! diyeceksin
Hayır!
Akan kanımda öleceksen
Yeniden doğmak için
Un çuvallarından.
Geleceğiz ses vermek için sesine
Bizi çağırdığın zaman
Ve ölümün çehresi
Yitip gidecek sözlerimizden.
Eli ölümün
Savurup atacak bizi
Yalın bir yurda doğru
Yasemin bir düşün beklediği.
Kuşlar bana bıraktı şarkılarını
Ve ben koştum
Yürek atışına tarlaların.
Kanımın derinliklerine in
Derinliklerine in
Derinliklerine ekmeğin
Yalın bir yurdumuz olsun
Yasemin bir düşün beklediği.
Her günkü Ahmed
Saf ve Basit Ahmed
Nasıl kaldırdın ayrılıkları
Meyveyle taş arasında
Kurşunla geyik?
Arap Ahmed, diren!
Kuşatma altında gezeceğiz
Ulaşıncaya dek kıyısına
Ekmeğin ve dalgaların.
Öleceğiz düşü uğruna
Bir yurdun
Ve bekleyen yaseminlerin.
Onda Güz''ün eğrileri var.
Kandaki şiirdir Ahmed.
Dağlar gibi kırışık yüzü
Yankısı çağıran seslerin
Birleşen gövdelerin.
Ey tanınmayan Ahmed
Nasıl yaşadın aramızda
Tam yirmi yıl
Hâlâ belli belirsiz yüzün
Hep çizgilerinde dolaştığımız
Tanınmayan yüzün
Ey ormanlar
Alevler kadar gizli Ahmed
Bize yüzünü tanıt
Söyle son sözünü
Dağılacağız sessizlikte
Geri adım atacağız
İşitsin diye ölüler sözlerini
Yaşayanlar
Belki tanır diye çizgilerini.
Ahmed
Ahmed kardeşim
Kahramanca ölümünü bekliyoruz
Ne zaman?
Ne zaman?
Ne zaman?
Mahmud DERVİŞ
Çeviren : Erdal ALOVA
* Beyrut''ta bir Filistin kampı olan Tel Zaatar Lübnan iç savaşı sırasında
iki ay kuşatma altında kalmıştı. Filistinliler güç koşullar altında kuşatmaya
karşı direnmişlerdi. Arapça''da "kekik dağı" anlamına gelen Tel Zaatar
Filistin direnişinin bir sembolü haline geldi. Hayali bir kahraman olan
Ahmed Zaatar sürekli yerinden edilen ve sürgünde yaşayan Filistinlilerin', 'Kekikten ve karamış taştan O eller için Bu çığlık Unutulmuş ve yapayalnız Ahmed için. Gelip geçen bulutlar Yurtsuz ve yabancı koydu beni Ve ...', ARRAY['Türk Edebiyatı','Şiir','Mahmud Dervi̇ş']::text[], 8.5, '{"poet":"Mahmud Dervi̇ş","poet_slug":"mahmud_dervis","theme":"Türk Şiiri","is_hero":false,"total_lines":187}'::jsonb) ON CONFLICT (slug) DO NOTHING;
