INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AHMET UYSAL', 'ahmet-uysal-ahmet-uysal-dlf2z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak Yazlarda, Ahmet
UYSAL, Düşlem Yayınları, Nisan 1998
Tuzlu bir köpük iziyle
Savrulan kumdur omzunda
Suyla sınadığın şiirler
Bir dergiye düşürür adını
Orada bir nehir ağzında
unutulur son gülüşün
