INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAKIŞTA', 'bi-r-bakista-ahmet-ozer-ti1d5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ürktü içimdeki kuşlar
bir katar kanat sesi yıkadı
haziran göğünü
yüzün bir buluta giriyordu o an
boynunu vermiştin bir çağlayana
bir tutam kırmızı saç uçuşuyordu
karanlığın parmaklarından.
gövdemiz
bir alevin rüzgârında dört nala
sesimizi gezdiren meydanlar
bir güzelliğe açıyor yelkenlerini; heyamola.
şimdi bize biçilmiş ömürleri yaşıyoruz
en güzel günlerimizi bırakarak ardımızda.', 'ürktü içimdeki kuşlar bir katar kanat sesi yıkadı haziran göğünü yüzün bir buluta giriyordu o an boynunu vermiştin bir çağlayana bir tutam k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BÜYÜK KARAMSAR ÜZERİNE DÜŞ', 'bi-r-buyuk-karamsar-uzeri-ne-dus-bertolt-brecht-0frqz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÜZERİNE DÜŞ
(Patates kıtlığı
sırasında)
Bir düş gördüm:
opera binası karşısında
Badanacı*
tam patlatacakken o büyük
söylevini,
birden bir patates belirdi,
kocaman,
orta boy bir tepedn iri,
ve bekleşen kalabalığın
karşısına çıkıp
başladı o da söylev
vermeye.
Ben, dedi alçak sesle,
sizi uyarmaya geldim.
Biliyorum, patatesten başka
bir şey değilim,
küçümen, önemsiz bir
kişi,
pek öyle yüzüne bakılmaz
cinsinden,
tarih kitapları anmaz
adımı,
tepedekilere hele hiçbir
etkim yok.
Büyük şeyler olunca söz
konusu,
yani şan, şeref, namus falan
filan,
gerekir benim kenarda kalmam.
Çünkü asalete hiç uygun
düşmezmiş
beni şan ve şerefle bir
tutmak.
Ama gene de yaptım ben bana
düşeni.
Yardım ettim insanların bu
gözyaşı vadisinde
yaşamlarını
sürdürmelerine.
Şimdi, benimle şuradaki adam
arasında
bir seçim yapma vakti geldi.
Haydi, ya o ya ben!
Onu seçerseniz yitirirsiniz
beni.
Ama ille de ben gereksem size,
onu burdan siktir etmelisiniz.
Onun için, bana kalırsa,
daha fazla vakit kaybetmeyin
dinleyerek onu,
çünküz az sonra yakapaça o
atacak beni burdan.
Ona karşı ayaklanırsanız
öleceğinizi söylese bile
unutmayın şunu sakın:
bensiz de ölürsünüz
çocuklarınızla birlikte
İşte patates böyle
konuştu
Ve badanacı böğürürken
operada,
ve hoparlörler ilettikçe bu
böğürtüleri halka,
o yavaş yavaş,
sanki ne dediğini göstermek
istermiş gibi,
tüm halkın görebileceği
tuhaf bir gösteriye başladı,
Badanacının ağzından
çıkan her sözcükle
içine çekile çekile,
küçücük oldu,
biçimsiz, bumburuşuk.
Bertolt BRECHT', 'ÜZERİNE DÜŞ (Patates kıtlığı sırasında) Bir düş gördüm: opera binası karşısında Badanacı* tam patlatacakken o büyük söylevini, birden bir pa...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt_brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":79}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR DÜŞ', 'bi-r-dus-bayram-balci-gn5gb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir nisan pazarı. belki de cuma. iyice karıştırdım artık günleri
elimi uzatıyorum tutsana. başım dönüyor düşebilirim
elimi uzatıyorum tutsana. bulutlar çöküyor gözlerime
elimi uzatıyorum tutsana. yüreğim ağrıyor ölebilirim
elimi uzatıyorum tut ve bırakma. dayanamam tek başıma
aylardan nisan
günlerde belki bir görüş vakti
elimi uzatıyorum tutsana
ya da bir içli türkü söyle
sıçramalarla uyanıyorum geceyarıları. düşiçindeyim
aklımda dayanılmaz bir sancı
bir hayal gibi dolaşıyor etrafından insanlar
ve sadece gözlerini gördüğüm beyazlar içinde bir kadın
elinin içiyle kapıyor gözlerimi: ÖLMÜŞÜM
elimi uzatıyorum tutsana
bütün zehirler karışmış damarlarıma
elimi uzatıyorum tutsana
yağıyor üzerime dünya
biliyorum ki bir zaman sonra
çiçekler satacak genç bir kız sokaklarda
iliştirip şiirlerimi yakasına
-bayım bir çiçek alır mıydınız
açlık grevinde öldü arkadaşımız
ben sevda diyorum adına', 'bir nisan pazarı. belki de cuma. iyice karıştırdım artık günleri elimi uzatıyorum tutsana. başım dönüyor düşebilirim elimi uzatıyorum tutsan...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR DAHA UYANMAZDIN', 'bi-r-daha-uyanmazdin-cezmi-ersoz-keiat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Martıların sana doğruyu
söyleyecekti
arzu tramvaylarına binmeseydin
Acıların seni yeni bir şehre
götürecekti
Yürüyüşüne vurulmasaydın...
Tuhaf, ele geçmez, tehlikeli bir
hayvandın
Şehrin yaban adamları sana öyle bakmasaydı
uyur, bir daha uyanmazdın...
Cezmi', 'Martıların sana doğruyu söyleyecekti arzu tramvaylarına binmeseydin Acıların seni yeni bir şehre götürecekti Yürüyüşüne vurulmasaydın... Tuh...', ARRAY['Türk Edebiyatı','Şiir','Cezmi
        Ersöz']::text[], 8.5, '{"poet":"Cezmi\n        Ersöz","poet_slug":"cezmi_ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR DE MARTHA VARDI', 'bi-r-de-martha-vardi-selcuk-yamen-4zo6z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir de Martha vardı
Söyleşirdik
Başka dil bilmem
Bilmem Martha''nın dilini derdim
Başka dil bilmem
Bilmem dilimi bilmeyenin dilini, derdi
Kumlardan şekil yapardık bir iki
O Ay''ı çizerdi
Ben denize düşerdim şaşkın
Masallar üşüşürdü sahil soframıza
En yasağından bir içki açılırdı
Söyleşirdik
Göz göze düşerdik o saat, bilmezdik dillerimizi
Yanımızdan bir adam geçerdi
Anlardık yüzünden, alışkındı kimlik sormaya
Martha sofrayı toplardı
Martha beni toplardı
Kaçardık
Adam denize kimlik sorardı
Sirenler ötse denizi anımsardık
Sahildeki soframızı
Ayın şekillenmiş saçlarını
Bir kaç tren geçerdi
Bembeyaz olurdu Martha''nın yüzü
Annem beni sorardı
Ben Martha''yı sorardım
Bir de Martha vardı
Söyleşirdik
Kırlara, derelere giderdik
Nisan geldiğinde yağmura binerdik
Martha çiçeğe benzerdi
Ellerim korkardı
Yanımızdan bir adam geçerdi
anlardık yüzünden, alışkındı kimlik sormaya
Çiçekleri toplardım
Martha''yı toplardım
Kaçardık
Adam çiçeklere kimlik sorardı
Bir de Martha vardı
Masallardan yürümüşçesine çıkar gelirdi yanıma
Kentler vardı, ışıldardı
İnsanlar vardı, telaşlı
Bir de Martha vardı
Seyleyemezdim sevdiğimi
İnsanlar sökün ederdi, kimlik sorardı
Annem beni sorardı
Ben Martha''yı sorardım
Kent hızla kaçardı
Trenler hızla geçerdi
Kondiktör beni sorardı
Ben Martha''yı sorardım
Herkes Martha''yı sorardı
Martha
Bir bilet miydim cebinde eskidim
Martha topla beni: yalnızca gidelim!..', 'Bir de Martha vardı Söyleşirdik Başka dil bilmem Bilmem Martha''nın dilini derdim Başka dil bilmem Bilmem dilimi bilmeyenin dilini, derdi Kum...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yamen']::text[], 8.5, '{"poet":"Selçuk Yamen","poet_slug":"selcuk_yamen","theme":"Türk Şiiri","is_hero":false,"total_lines":57}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR DENİZ KIYISINDA', 'bi-r-deni-z-kiyisinda-peyo-yavorov-90idj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun süre baktım: bir tekdüzelikte
her dalga koşuyordu ardı sıra bir başka dalganın
ıssız ve sonsuz denizde.
Bir kuş gibi tıpkı, hafif kanatlı
belirdi pupa yelken bir tekne
ve ok gibi uzaklaştı.
"Dur! " fakat köpüklü dümen suyundan
hiçbir iz kalmadı geçince bir an.
Silikleşir silikleşmez o tekne
gözlerimden yakıcı yaşlar fışkırdı
yavaşça kayarak yüzüme.
Dünya bir denizdir.. ve benden
nedir kalacak olan ardımda
burada, yaşamış olduğum şeylerden....
Peyo YAVOROV', 'Uzun süre baktım: bir tekdüzelikte her dalga koşuyordu ardı sıra bir başka dalganın ıssız ve sonsuz denizde. Bir kuş gibi tıpkı, hafif kanat...', ARRAY['Türk Edebiyatı','Şiir','Peyo Yavorov']::text[], 8.5, '{"poet":"Peyo Yavorov","poet_slug":"peyo_yavorov","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR DÜŞÜNCE KURCALAR KAFAMI', 'bi-r-dusunce-kurcalar-kafami-s-ndor-petofi-ngae2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir düşünce kurcalar kafamı:
Yatakta, başım yumuşak yastıkta mı ölmeli?
Yoksa bir karanfil gibi mi solmalı yavaşça,
gizli bir kurdun içten içe kemirdiği?
Sessiz sedasız eriyip gitmeli mi yoksa
boş bir odaya bırakılmış mum gibi?
İstemem, tanrım, böyle bir ölüm istemem!
Ölmeyi dilerim ben, ölmeyi birdenbire:
Ayakta, yıldırımla parçalanan bir ağaç gibi,
kasırgayla devrilen bir ağaç gibi ölmeyi,
uçuruma yuvarlanan bir kaya gibi,
tepeden tırnağa titrete sarsa yeri göğü.
Uyanacak bir gün kölelikten usanan halklar,
koşacaklar savaş alanına doğru.
Yüzler yalım yalım, bayraklar altında duracaklar.
Dört bir yanda pırıl pırıl şu onurlu parola:
Herkese özgürlük! Her yerde özgürlük, her yerde!
Yayınca halklar bağıra bağıra
bu sözcükleri dört bucağa, doğudan batıya,
ve başlayınca saldırılar zorbalığa karşı,
isterim ölmek en ön sıralarda,
isterim sulasın yüreğim o şeref tarlasını
gençliğimin fışkıran al kanatlarıyla.
Ağzımdan çıkan mutlu son sözüm
bastırılsın isterim çelik gürültüsüyle,
borazan sesiyle, top gümbürtüsüyle.
Kazanılan zaferle atlar kişnesinler,
var hızlarıyla çiğneyip geçsinler cesedimi,
bıraksınlar paramparça gövdemi savaş alanında.
Başlayınca sonra cenaze töreni,
getirilsin bir araya bütün kemiklerim,
matem marşları çalsın durmadan
kara tüllü bayraklar altında.
bir mezara gömülsün kahramanların hepsi,
senin uğrunda can verenlerin hepsi,
ey özgürlük, ey dünyanın özgürlüğü!
Sándor PETOFİ', 'Bir düşünce kurcalar kafamı: Yatakta, başım yumuşak yastıkta mı ölmeli? Yoksa bir karanfil gibi mi solmalı yavaşça, gizli bir kurdun içten i...', ARRAY['Türk Edebiyatı','Şiir','Sándor Petofi̇']::text[], 8.5, '{"poet":"Sándor Petofi̇","poet_slug":"sandor_petofi","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR EFLATUN ÖLÜM', 'bi-r-eflatun-olum-behcet-aysan-dzo7j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kırgınım, saçılmış
bir nar gibiyim
sessiz akan bir ırmağım
geceden
git dersen giderim
kal dersen kalırım
git
dersen
kuşlar da dönmez, güz kuşları
yanıma kiraz hevenkleri alırım
ve seninle yaşadığım
o iyi günleri,
kötü
günleri bırakırım.
aynı gökyüzü aynı keder
değişen bir şey yok ki
gidip
yağmurlara durayım.
söylenmemiş sahipsiz
bir şarkıyım
belki
sararmış
eski resimlerde kalırım
belki esmer bir çocuğun dilinde.
bütün derinlikler sığ
sözcüklerin hepsi iğreti
değişen bir şey yok hiç
ölüm hariç.
aynı gökyüzü aynı keder.', 'kırgınım, saçılmış bir nar gibiyim sessiz akan bir ırmağım geceden git dersen giderim kal dersen kalırım git dersen kuşlar da dönmez, güz ku...', ARRAY['Türk Edebiyatı','Şiir','Behçet Aysan']::text[], 8.5, '{"poet":"Behçet Aysan","poet_slug":"behcet_aysan","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ŞEHRİ BIRAKMAK', 'bi-r-sehri-birakmak-oktay-ri-fat-horozcu-v3c46', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I
Senin için aldığım menekşeleri
Çalgıcılara dağıttım
Son gece
Son defa başlıyan sabah
Yatağımı yine sen düzelt
Küçük balıkçı çocuğu
Sen denizden
Yaramaz ve çapkın balıkları tutabilirsin
Çok uzaklara gittiğimi
Sana söylemek isterdim
Güzel satıcı kızı
II
Ağaca söyle
Gölgesini getirsin bana yolluk
Sokağı ve denizi isterim pencereden
Senden çörekler isterim
Ay biçiminde
III
Ellerin yetişir vedalaşmaya
Niçin ağlıyorsun', 'I Senin için aldığım menekşeleri Çalgıcılara dağıttım Son gece Son defa başlıyan sabah Yatağımı yine sen düzelt Küçük balıkçı çocuğu Sen den...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ŞEHİR GECESİ HATIRASI', 'bi-r-sehi-r-gecesi-hatirasi-onan-gunoz-c3rw5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'karanlıklar sinemasını oynatıyor gece
sokaklarda intiharsı bir sessizlik
duvarlarda hâlâ aynı yüzler
plastik cinayetlere dair
perdelerin ardına saklıyoruz medeni hâlimizi
tek parola yalnızlık
ve mizanpaj hatalarından
ve renk tüccarlarından
bize kalan tek şey
ötekinin kirli paranoyası
şehrin gözlerinde kartpostal bir bakış
bu şehirde herkes yanındakine aşık !
herkesin içinde yaralı bir çocuk
herkes şiir yazıyor denize bakıp...', 'karanlıklar sinemasını oynatıyor gece sokaklarda intiharsı bir sessizlik duvarlarda hâlâ aynı yüzler plastik cinayetlere dair perdelerin ard...', ARRAY['Türk Edebiyatı','Şiir','Onan Günöz']::text[], 8.5, '{"poet":"Onan Günöz","poet_slug":"onan_gunoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ŞEHRE YAĞACAK YAĞMURUM', 'bi-r-sehre-yagacak-yagmurum-bayram-balci-eulwf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu şehre yağmur yağmazsa üşürüm
bir bardak suyun yarası kanar bende
bir çocuğun avuçlarında kırılmış oyuncak
eksilirim. hayat boşa çıkarır beni
ben bir kedi yavrusuyum şehri tırmalayan
jilet yarasıyım bileklerinde
kendini taşımaktan yorulmuş hayatların
uçurum kıyısıyım yeşile bezenmiş
yoluyorum aklımda ayrıksı otları
ben bu şehre az sonra yağacak yağmurum
aşkın kirpiğinde takılı haylaz bir bulut
içimin sonsuz ormanında koşmaktan yoruldum
hey bana bir resimden küsen sevgili
yol kalbinin kire bulanmış çiçeklerini
yalanlanan gerçek gibi akıyorum şehrin içine
zaman geçiyor. aşk uzaklaşıyor her mevsim
&quot;ben bu yolculuğa çıkmazsam&quot;lı bir cümle kurmalıyım
&quot;eve gitmezsemli&quot; kaygılı bir ağrı
mağrur ve yenik tayfasıyım her aşkın
bulut topluyorum şehrin ormanından
susamışım nihaventim üstelik
çevirdim yüzümü hayattan
kopacak fırtınanın habercisiyim
bu şehre şimdi yağmur yağmazsa
annem bağışlamaz beni', 'bu şehre yağmur yağmazsa üşürüm bir bardak suyun yarası kanar bende bir çocuğun avuçlarında kırılmış oyuncak eksilirim. hayat boşa çıkarır b...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ELİŞİ TANRISI İÇİN AĞIT', 'bi-r-eli-si-tanrisi-i-ci-n-agit-ece-ayhan-qhhl1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Peki nasıl oldu da hatırladı denizde boğulduğunu
nasıl oldu da peki anlatamıyorum biliyorsun
Öyle ölüme düşkündü ki biyoloji sıfır
bir şarkı yiyor şimdi şapkalarını orospular eksiliyor
Ama yok ne olur ağlama böyle ama yok
şunun şurasında tramvaysız, çocuk olmak turunç olmak
Kantocu peruz sahiden yaşadı mı patron?', 'Peki nasıl oldu da hatırladı denizde boğulduğunu nasıl oldu da peki anlatamıyorum biliyorsun Öyle ölüme düşkündü ki biyoloji sıfır bir şarkı...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ÇELENK', 'bi-r-celenk-yannis-ritsos-kzjru', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yapraklarla gizlenmişti yüzün.
Birer birer kopardım yaprakları sana yaklaşmak için.
Son yaprağı kopardığımda, sen gitmiştin. Sonra
bir çelenk ördüm kopan yapraklardan. Kimsem yoktu
verebileceğim. Ben de çelengi alnıma yerleştirdim.
Yannis RITSOS', 'Yapraklarla gizlenmişti yüzün. Birer birer kopardım yaprakları sana yaklaşmak için. Son yaprağı kopardığımda, sen gitmiştin. Sonra bir çelen...', ARRAY['Türk Edebiyatı','Şiir','Yannis Ritsos']::text[], 8.5, '{"poet":"Yannis Ritsos","poet_slug":"yannis_ritsos","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ELİNDE BİR MENDİL ÖBÜRÜNDE KUŞ SESLERİ', 'bi-r-eli-nde-bi-r-mendi-l-oburunde-kus-sesleri-tugrul-keski-n-uz3cr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kalbimi söküp alıyor göğsümden bu şehir
çöplerde oynaşan kediler gibi, ölüme gidiyorum
söylenen gün nerededir, tufan var mı, ne gündür
cemal süreya döner mi geri
bir elinde bir mendil, öbüründe kuş sesleri
öğreneli çok oldu gerçi, meleklerin olmazmış erkekleri
ne gidene bir yer var oralarda ne gidenler dönecek geri', 'kalbimi söküp alıyor göğsümden bu şehir çöplerde oynaşan kediler gibi, ölüme gidiyorum söylenen gün nerededir, tufan var mı, ne gündür cemal...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul  Keski̇n']::text[], 8.5, '{"poet":"Tuğrul  Keski̇n","poet_slug":"tugrul_keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ENGEL ÇIKINCA', 'bi-r-engel-cikinca-kemal-ozer-hmg7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokuş aşağı koştunuz mu hiç?
Durdunuz mu hiç
bir engel çıkınca
birdenbire?
Bileceksiniz öyleyse...
Bir başdönmesi alır
kesilen hızın yerini
ve bacaklarınızda gelen rüzgâr
sizden önce aşar engeli.', 'Yokuş aşağı koştunuz mu hiç? Durdunuz mu hiç bir engel çıkınca birdenbire? Bileceksiniz öyleyse... Bir başdönmesi alır kesilen hızın yerini ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ŞEY', 'bi-r-sey-n-zim-65u8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.
Bir şey ki hava gibi ekmek gibi su gibi
Lâzım insana lâzım onsuz yaşanılmıyor
Ana baba gibi dost gibi yavuklu gibi
Kalp titremeden göz yaşarmadan anılmıyor
Bir şey ki gözünüzde memleket kadar aziz
Aşk ettiğimiz kendimize dert ettiğimiz
Adını çocuklarımıza bellettiğimiz
Bir şey ki hasretine dayanılmıyor
II.
Bir şey daha var yürek acısı
Utandırır insanı düşündürür
Öylesine başka bir kalp ağrısı
Alır beni ta Bursa''ya götürür
Yeşil Bursa''da konuk bir garip kuş
Otur denmiş oracıkta oturmuş
Ta yüreğinden bir türkü tutturmuş
Ne güzel şey dünyada hür olmak hür
Benerci Jokond Varan Üç Bedrettin
Hey kahpe felek ne oyunlar ettin
En yavuz evlâdı bu memleketin
Nâzım ağabey hapislerde çürür', 'I. Bir şey ki hava gibi ekmek gibi su gibi Lâzım insana lâzım onsuz yaşanılmıyor Ana baba gibi dost gibi yavuklu gibi Kalp titremeden göz ya...', ARRAY['Türk Edebiyatı','Şiir','Nâzım']::text[], 8.5, '{"poet":"Nâzım","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ŞEYİN ADI', 'bi-r-seyi-n-adi-ozdemir-asaf-jsfe5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce, büyük büyük düşündüm;
Sonra büyük büyük yaşadım.
Ne varsa, onlar aldı.
Şimdi bana küçük bir ölüm kaldı.', 'Önce, büyük büyük düşündüm; Sonra büyük büyük yaşadım. Ne varsa, onlar aldı. Şimdi bana küçük bir ölüm kaldı....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir_asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR FENİKELİ', 'bi-r-feni-keli-i-lhan-berk-chi0u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1
Denizde boğulan o ilk Fenikelilerdendi.
2
Vergi memurluğu yapardı ve köpekler saldırırdı hep.
3
Babası Barbar akınlarını durdurmuştu.
4
Kırlangıcın geveze bir kuş olduğunu ilk ondan duyduk.
5
Ben o zamanlar çocuktum ve çok fakirdim.
Delta ve Çocuk', '1 Denizde boğulan o ilk Fenikelilerdendi. 2 Vergi memurluğu yapardı ve köpekler saldırırdı hep. 3 Babası Barbar akınlarını durdurmuştu. 4 Kı...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GECE ANSIZIN GELEBİLİRİM', 'bi-r-gece-ansizin-gelebi-li-ri-m-umit-yasar-oguzcan-05utx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kadar yürekten çağırma beni
Bir gece ansızın gelebilirim
Beni bekliyorsan, uyumamışsan
Sevinçten kapında ölebilirim
Belki de hayata yeni başlarım
İçimde küllenen kor alevlenir
Bakarsın hiç gitmem kölen olurum
Belki de seversin beni kim bilir
Kal dersen, dağlarca severim seni
Bir deniz olurum ayaklarında
Aşk bu özleyiş bu, hiç belli olmaz
Kalbim duruverir dudaklarında.
Ya da unuturum kim olduğumu
Hatırlamam belki adımı bile
Belki de çıldırır, deli olurum
Sana kavuşmanın heyecaniyle
Aşk bu, bilinir mi nereye varır
Ne durdurur özleyeni, seveni
Bakarsın ansızın gelebilirim
Bu kadar yürekten çağırma beni.', 'Bu kadar yürekten çağırma beni Bir gece ansızın gelebilirim Beni bekliyorsan, uyumamışsan Sevinçten kapında ölebilirim Belki de hayata yeni ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit_yasar_oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GECE İÇİN EKSİK SORULAR', 'bi-r-gece-i-ci-n-eksi-k-sorular-adnan-azar-97lr4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlığı soruyordun!
Çocukluğumu, yeniyetmeliğimi bilebilecek misin?
Bir kader-kısmet kutun oldu mu hiç senin?
Plastik saatler, zıpzıp toplar içeren bir kutunun
sevincini taşıyabilir miydin bu gecenin içine?
Durmadan genişleyen sessizliğinin neresindesin?
Suskunu ne ile süsleyeceksin?
Şimdi soruların ötesindesin, evet! Ama bir gün,
bir yer seçmiş olacaksın kendine: ya sulara çok yakın,
ya yollar için dar!..
Hem sonra senin de gecelerine durmayacak mı
birbirinden kovulmuş üç-beş adam?
Birbirinden kovulmuş üç - beş adam!', 'Karanlığı soruyordun! Çocukluğumu, yeniyetmeliğimi bilebilecek misin? Bir kader-kısmet kutun oldu mu hiç senin? Plastik saatler, zıpzıp topl...', ARRAY['Türk Edebiyatı','Şiir','Adnan Azar']::text[], 8.5, '{"poet":"Adnan Azar","poet_slug":"adnan_azar","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GELGİTİN İKİ UCUNDA', 'bi-r-gelgi-ti-n-i-ki-ucunda-kemal-ozer-ak5vw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimi sabahlar işe giderken
ikiye bölüyor
yirmi dakikalık yolculuğu
denizin ortasında karşılaştığımız
yabancı bayraklı bir gemi
Bulutlardan sıyrılmış bir demet ışığın
daha da irileştiği gemide
göz göze geliyoruz kimi sabahlar
küpeştede bakan biriyle
kısacık bir an
Günlük kaygıların iğdiş ettiği
çağdaş bir kentli görüyor bana bakınca
benim gözümde ise o
kanat açan bir düş yeni kıyılara doğru
buluşuyoruz bir gelgitin iki ucunda', 'Kimi sabahlar işe giderken ikiye bölüyor yirmi dakikalık yolculuğu denizin ortasında karşılaştığımız yabancı bayraklı bir gemi Bulutlardan s...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜL AÇIYORSA', 'bi-r-gul-aciyorsa-necati-cumali-3zxcs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-1960 Devrim şehitlerinin anısına-
Bir gül açıyorsa şimdi Türkiye''de
Aşkla ümitle açıyor
Adsız unutulmuş her bahçede
Bir gül tomurcuklanıyorsa
Sabaha karşı gecede
Açmak için tomurcuklanıyor
Aşkla ümitle
Sevinçle yaşamak için tomurcuklanıyor
Kanın aktığı yerde
Göz yaşının aktığı yerde
Karanlığı içinde kahrın
Güller açıyor işte
Güller ışık aydınlık içinde
Güller bütün güller bu sabah
Bir ağızdan türkü söyler gibi açıyor her bahçede
Geceler gündüze dönüyor işte
Karanlık ışığa dönüyor işte
Kahır sevince dönüyor işte
Akan kan dökülen yaş
Güle dönüyor işte
Hasetsiz korkusuz kinsiz
Binlerce güller açıyor işte
Dargın kardeşe dönüyor işte
Artık yaşamak bütün Türkiye''de
Bir ağızdan söylenen bir türküye dönüyor', '-1960 Devrim şehitlerinin anısına- Bir gül açıyorsa şimdi Türkiye''de Aşkla ümitle açıyor Adsız unutulmuş her bahçede Bir gül tomurcuklanıyor...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜLÜ SULAMA ZAMANI', 'bi-r-gulu-sulama-zamani-bedrettin-aykin-170ny', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açık mı yüreğinin kapısı sevgilere
Duyuyor musun çağıltısını yaşamın
Yürüyorsa o özsu hücrelerinde
Kaçıncı baharında olursan ol
Vakit hep bir gülü sulama zamanı
Gecikmiş değilsin dinlemeye
Tenin tene sevgiyle her dilden
Söylediği o coşkulu türküyü
Bulur bir gün nerede olsan seni
Sürüp gelir bir yangının izlerini
Tut elinden sokaklara çıkar hüznü
Yoksa büyür sığmaz olur odalara
Konuş onunla havadan sudan söz et
Kuşlardan çiçeklerden istersen
Sadece bir merhaba desen de olur
Gülümse ona bir gün karşılaşınca
Tükenir paylaşılınca yalnızlıklar
Biliyorsun yurtsuz nicedir sevgiler
Geçit verirsen gözlerinin çölünden
Gelir sığınır bir yerinden yüreğine', 'Açık mı yüreğinin kapısı sevgilere Duyuyor musun çağıltısını yaşamın Yürüyorsa o özsu hücrelerinde Kaçıncı baharında olursan ol Vakit hep bi...', ARRAY['Türk Edebiyatı','Şiir','Bedrettin Aykin']::text[], 8.5, '{"poet":"Bedrettin Aykin","poet_slug":"bedrettin_aykin","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜL', 'bi-r-gul-halim-yagcioglu-xe4i6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Odamın penceresi
bir bahçeye bakar
bahçe çırılçıplak
kurumuş ağaçlar
bir kız bilirim
hep ayni günde
ayni saatte
aydınlık iplere
çamaşır asar
Odamın penceresi
bir bahçeye bakar
bahçe bütün bahçeler gibi ıssız
tarumar olmuş çiçekler perişan
sadece bir gül var
kızın gözlerinde
şimşek şimşek açan', 'Odamın penceresi bir bahçeye bakar bahçe çırılçıplak kurumuş ağaçlar bir kız bilirim hep ayni günde ayni saatte aydınlık iplere çamaşır asar...', ARRAY['Türk Edebiyatı','Şiir','Halim Yağcioğlu']::text[], 8.5, '{"poet":"Halim Yağcioğlu","poet_slug":"halim_yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜN ANLARSIN', 'bi-r-gun-anlarsin-umit-yasar-oguzcan-ekep1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykuların kaçar geceleri, bir türlü sabah olmayı bilmez.
Dikilir gözlerin tavanda bir noktaya,
Deli eden bir uğultudur başlar kulaklarında
Ne çarşaf halden anlar ne yastık.
Girmez pencerelerden beklediğin o aydınlık.
Onun unutamadığın hayali,
Sigaradan derin bir nefes çekmişçesine dolar içine.
Kapanır yatağına çaresizliğine ağlarsın.
Sevmek ne imiş bir gün anlarsın.
Bir gün anlarsın aslında her şeyin boş olduğunu.
Şerefin, faziletin, iyiliğin, güzelliğin.
Gün gelir de sesini bir kerecik duyabilmek için,
Vurursun başını soğuk taş duvarlara.
Büyür gitgide incinmişliğin kırılmışlığın.
Duyarsın,
Ta derinden acısını, çaresiz kalmışlığın.
Sevmek ne imiş bir gün anlarsın.
Bir gün anlarsın ne işe yaradığını ellerinin.
Niçin yaratıldığını.
Bu iğrenç dünyaya neden geldiğini.
Uzun uzun seyredersin aynalarda güzelliğini.
Boşuna geçip giden günlerine yanarsın.
Dolar gözlerin, için burkulur.
Sevmek ne imiş bir gün anlarsın.
Bir gün anlarsın tadını sevilen dudakların.
Sevilen gözlerin erişilmezliğini.
O hiç beklenmeyen saat geldi mi?
Düşer saçların önüne, ama bembeyaz.
Uzanır, gökyüzüne ellerin.
Ama çaresiz,
Ama yorgun,
Ama bitkin.
Bir zaman geçmiş günlerin hayaline dalarsın.
Sonra dizilir birbiri ardına gerçekler, acı.
Sevmek ne imiş bir gün anlarsın.
Bir gün anlarsın hayal kurmayı;
Beklemeyi, ümit etmeyi.
Bir kirli gömlek gibi çıkarıp atasın gelir
Bütün vücudunu saran o korkunç geceyi.
Lanet edersin yaşadığına...
Maziden ne kalmışsa yırtar atarsın.
O zaman bir çiçek büyür kabrimde, kendiliğinden.
Seni sevdiğimi işte o gün anlarsın.', 'Uykuların kaçar geceleri, bir türlü sabah olmayı bilmez. Dikilir gözlerin tavanda bir noktaya, Deli eden bir uğultudur başlar kulaklarında N...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit_yasar_oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":45}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜN SABAH SABAH', 'bi-r-gun-sabah-sabah-turgut-uyar-xw8nc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün sabah vakti kapıyı çalsam,
Uykudan uyandırsam seni:
Ki, sisler daha kalkmamıştır Haliç ten.
Vapur düdükleri ötmektedir.
Etraf alacakaranlık,
Köprü açıktır henüz.
Bir gün sabah sabah kapıyı çalsam...
Yolculuğum uzun sürmüş oldukça
Gece demir köprülerden geçmiştir tren.
Dağ başında beş-on haneli köyler,
Telgraf direkleri yollar boyunca
Koşuşup durmuş bizle beraber.
Şarkılar  söylemişim pencereden.
Uyanıp uyanıp yine dalmışım.
Biletim üçüncü mevki,
Fakirlik hali.
Lüle taşından gerdanlığa gücüm yetmemiş,
Sana Sapancadan bir sepet elma almışım.
Ver elini haydarpaşa demişiz,
Vapur rıhtımdadır pırıl pırıl,
Hava hafifden soğuk,
Deniz katran ve balık kokulu.
Köprüden kayıkla geçmişim karşıya,
Bir nefeste çıkmışım bizim yokuşu...
Bir gün sabah sabah kapıyı vursam,
-Kim o dersin uykulu sesinle içerden.
Saçların dağınıkdır, mahmursundur.
Kimbilir ne güzel görünürsün sevgilim,
Bir sabah vakti kapıyı çalsam,
Uykudan uyandırsam seni,
Ki, daha sisler kalkmamıştır Haliç ten.
Fabrika düdükleri ötmektedir.', 'Bir gün sabah vakti kapıyı çalsam, Uykudan uyandırsam seni: Ki, sisler daha kalkmamıştır Haliç ten. Vapur düdükleri ötmektedir. Etraf alacak...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜN SEVİŞMEYİ BANA', 'bi-r-gun-sevi-smeyi-bana-arkadas-zekai-ozger-x5b4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kandan
ve ceninden bir gün daha
başlarken
bir dalı kanatıyorum tırnaklarımla
ağzı açılmamış bir güle dokunuyorum
geceden kalma bir şeyle oynuyor kalbim
bugün biraz daha yorgun başlıyorum
sabah
yeni doğmuş çocuk çirkin ve sisli
vurdukça ilk ışıkları penceremden içeri
kımıldaşır içimin ölü dolu coşkusu
güneş bir ürkekliği gizliyemez
ne de olsa çözülmez yüreğimin kuşkusu
gün, o sevecen çığırtkan
beni yeni bir oyuna çağırıyor
yalnızlık yenilmeyen gladyatör
bana eski bir ölümü anımsatıyor
sabah
taşıyarak bir celladı odama
aşkımın ve bırakılmışlığımın celladını
hüznümle ve çirkinliğimle yargılamadan beni
tanıdığım bir ölümle tehdit ediyor
yalnızlık her sabah öldürüyor beni
çözerek gecenin ipliğini hızımla
hüznümü ve yalnızlığımı sarıyorum sabaha
adi bir etiketi yamayarak üstüne
boyna genişliyen bir orospu gibi
genişledikçe küçülen bir orospu gibi
aşksızlığım küçültüyor beni
korkum ve çirkinliğim utandırıyor beni
gecikilmiş bir aşkı yaşamıya
cinayet tek kurtuluşsa bir yanlışlıktan
önce acıya direnmesini öğrenmeliyim
eskitilmiş bir kurşunla kaplıyorum yüreğimi
acıya ve aşka hazırlıyorum
hergün yeniden yaşamak
boşalan bir birikimi kocamış acılarla
uzuyan bir ölümü bitimliyen vücudum
yani istek. o hep tiksinç görünen
çirkin ve güzel orospu. yeniyetme
bir çırpınışın yorgunluğu yüreğimde
o hep güzel görünen bana
çirkin ve güzel orospu
vücudum. seni seviyorum
acıyla büyütüyorum aşkımı
bir gün bana sevişmeyi öğreticek.', 'kandan ve ceninden bir gün daha başlarken bir dalı kanatıyorum tırnaklarımla ağzı açılmamış bir güle dokunuyorum geceden kalma bir şeyle oyn...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas_zekai_ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜN ÖVGÜSÜ', 'bi-r-gun-ovgusu-afsar-ti-muci-n-7ylq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ölecek olduktan sonra
Musa''nın bir başka türlüsü İsa
Gece duran bir fesleğen saksıda
Gün dalında değişen kasımpatı
Akşam dar geçitlerde aldatıldı
Artık çiçek saymıyorlar akşamı
Sabah olsa olsa uzun selvidir
Duruşu ölümlerle gerilidir
-Yokluğunun tutarsız bir anlamı
Gece neye giderler savaş mı başlatıldı
Bir karanlık yanıyor
Nereye koşarlar dizili adımlarla
Kan en sonun da gene susuzluğu özlerken
Duyarlığım yarı yolda kalıyor
Niye sadece bana bıraktın yamaçları
Seller içimi deşiyor düzenim dağılıyor
Yıkımı yorgunluğu ölümle sevişiyor
Sen gene bak baktıkça düzenim değişiyor
Yaralı güveni dağ aşılmazlığında
Bilinmeyen bir gün gibi aklında
Varlığıyla birden pençeleşiyor
Daralıyor güneşinin kapsamı
Karanlığı sarsılmaz anlamda gelişiyor', 'Ben ölecek olduktan sonra Musa''nın bir başka türlüsü İsa Gece duran bir fesleğen saksıda Gün dalında değişen kasımpatı Akşam dar geçitlerde ...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜNEYDOĞU AĞIDI', 'bi-r-guneydogu-agidi-gulten-akin-bsxvn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk bu sabah
İlk bu sabah göğü görmedim
İlk bu sabah kaysı çiçeklerini
Hüzün ilk kez konuk gibi gelmedi
Efendim, ev sahabım
Karacamı suya indiremedim
Şahanım uçurdum döndüremedim
Dağlar
Enikli kapılar kitlendi
Taş avlular sustu, ben sustum
İlk kez bekledim ölümü
Dostu bekler gibi bekledim
Dağlar
Benim acım acıların beyidir
Canıma bir doru kısrakla gelir
Öfkeyi sabırda eritir
Umut yer
Suyunu gözümden içer bir zaman
Dağlar of dağlar', 'İlk bu sabah İlk bu sabah göğü görmedim İlk bu sabah kaysı çiçeklerini Hüzün ilk kez konuk gibi gelmedi Efendim, ev sahabım Karacamı suya in...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GÜNÜN SONUNDA ARZÛ', 'bi-r-gunun-sonunda-arz-ahmet-hasi-m-ejgar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgun gözümün halkalarında
Güller gibi fecr oldu nümâyân,
Güller gibi... sonsuz, iri güller
Güller ki kamıştan daha nâlân;
Gün doğdu yazık arkalarında!
Altın kulelerden yine kuşlar
Tekrârını ömrün eder i''lân.
Kuşlar mıdır onlar ki her akşam
Âlemlerimizden sefer eyler?
Akşam, yine akşam, yine akşam
Bir sırma kemerdir suya baksam;
Üstümde semâ kavs-i mutalsam!
Akşam, yine akşam, yine akşam
Göllerde bu dem bir kamış olsam!', 'Yorgun gözümün halkalarında Güller gibi fecr oldu nümâyân, Güller gibi... sonsuz, iri güller Güller ki kamıştan daha nâlân; Gün doğdu yazık ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR GİZE UYANIŞ', 'bi-r-gi-ze-uyanis-a-galip-6442k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beyninde dolaşan sorulara
Yanıt
Kalbinde çarpan aşklara
Kanıt
Değilse yaşadıkların
Hükmü tarihtir artık
Kanla yazacakların
UYANIŞ
I
Biliyorum
Üzerimde yükselen bu gökyüzü
Asırlardır bulutu ve yağmuru
Bağrında taşıyan bu gökyüzü
Sabırsız
Biliyorum
Üzerinde dolaşıtığım bu yeryüzü
Beni bağrına basacak olan bu toprak
Sessiz ve telaşsız yürüyüşümden
Rahatsız
Yer ve gök
Hava ve toprak
Nicedir bir insan kılığında yaşayan
Emsalsiz kayğısızlığıma
Misli görülmemiş bir ceza
Biçecek
Kendimi
Gece ile gündüzün bitiştiği çizgiden
Gece ile gündüzün ayrıştığı çizgiye
Mahkum edişim
-umarım sanmıştım-
Yanılsamaydı
Şimdi apaçık bilinen günahım
Bütün mazeretlerimi unuttum
Zehrini emerek beslendiğim yalnızlıklar
Güneşten sakınarak gizlediğim gövdem adına
Bir yalın hakikat olarak
Yeniden doğuyorum sabır taşından
Aşklar ve acılar ağırlasın beni
Umutlar ve düşler
Döktüm gizimi
Tarihim kalmadı
Geri döndüm ve seçtim
Bu serüvende ben de varım
Yazgıma razıyım
Yatağını şaşıran ırmaktım belki
Gölgesini yitiren gezgin olmadım
II
-Kuyuya atılan bir taşın
Geri dönmeyecek yankısını bekleyerek
Harcanan ömür
Irmağın ve rüzğarın yabancısı
Dağların tedirginidir
Ki ancak
Vadilerin ezberlenmiş kıvrımlarında
Ve asırlık sukunetlerde teselli bulur-
Dağların
Irmakların sırrına eriştim
Sustum ve rüzğarın dilini öğrendim
Yanıtı gizlenmiş sorular sorandım hep
-Varolmak var kılmaksa eğer
Neden kanla sulanıyor toprak-
Neden diyordum
Neden
Neden
Lanetlendim bu yüzden
Münkir sayıldım
Acılar ve çığlıklar çekti beni
Kanın izini sürdüm
Bir Karmat Dai''sinin
Şahmaran zehriyle efsunladığı yüreğime
Geceyi ve zulmü boğacak
Ateşten ve sudan
Bir gövde yarattım
Ve artık
Çeliği eriten direncim
Aşkı yeşerten inancımla
Tanınmak isterim
Çünkü ben
Gözbebeklerimdeki karanlığı yıkadım
Avuçlarımdaki çakıl taşlarına
Birer birer
Yeryüzünün bütün lanetlilerine
Nöker bildiklerime pay ettim
Tükenen sabrım
Dinen öfkemle
Yaşamak ve yaşatmak hakkı için
Haykırdım
Erdem isyanda saklıdır
Erdem isyanda saklıdır
III
Yoksul ve yoksun bırakılan da bendim
Bu yüzden lanetlenen de
Çünkü konuşmamak koşuluyla dilime
Görmemek kaydıyla gözlerime bağışlanmıştım
Çünkü sağduyumun ve sessizliğimin emrine uyup
Buyuranından başka dost
Görevimden başka iş edinmediğim için
Yaşamakla ödüllendirilmiştim
Acının hüznün ve yanlızlığın
Rengine boyanmış dört mevsimi
Kum tanelerinin telaşıyla yaşıyordum
Boynumda imal tarihim ve seri numaram
Elimde güneşten yararlanma iznim
Cebimde metal çadırlara manyetik kahırlara
Piramit desenli
Giriş-çıkış kartlarımla
Kentin dokusuna uygun düşmeyeceğim
Semtlerden uzak durarak
Suratıma her bakanın
Normal bir antropoz olduğumdan kuşku duymayacağı
Sıradan sönük bir bakışı ısrarla taşıyarak
Bir sukunet halinde yaşıyordum
Yasakları çiğnemeden
Dengemi bozmayıp sıramı aksatmadan
Mazi hal ve istikbalde
Sukute davet makamlarla
Daralmış mekanlara resmedilecek gövdemi
Talimatlar eşliğinde
Tatbikat alanlarına taşıyordum
Zamanın
Parçalanan bünye
Dağılıp savrulan organlar
İnsanlığın
Çöküşe doğru kasri meyil devinimi
Kendine son arayan bir hikaye
Olduğuna şaşıyordum
İstilacı yanıtlardan müzdarip
Tahripkar beynimle
Yürekte sıkışan aşklar adına
Betonların örtemediği topraktan
Ve saçlarımı tarayan rüzgardan
Aldığım cesaretle
Nerede insan orada isyan çığlığıyla
Hükmedeni hükümsüz kılacak
Sorular çoğaltıyordum
-Bu beden ve bu ömür kime zimmetli
Kim için ve neden yaşamalıyım
Lutüf diye dayatılan bu zulmü-
IV
Gezgin oldum bir zaman
Çıplak ayak elde asa
Durdu duracak bir yürekle
Yollara vurdum kendimi
Dünyaya sırtımı dönüp
Araladım gecenin zifiri karanlığına açılan kapıyı
Yıldızları gözledim
Rüzgarı dinledim
Issızlığa gömülmüş ayışığıyla söyleştim
Son kez baktığım ceylanın
Gözlerinden şavkıyan lanetin
Hakettiğim günah olduğunu bilerek
Gölgemi dağlarda
Sesimi çağlayanlarda bıraktım
Her gece kendi okumla yaralanan yüreğime
Melhem olsun diye
Bulutlardan günışığı dilendim
Kuluk sıfatını haketmek için
Sırat belleyip
Yere serdim insanlığımı
Sürdüm azap diyarlarına kendimi
Kölelere karıştım
Kendimle yarıştım
Cefa çektim
Sefil oldum
Yargıç ben suçlu ben
Bir sırdaş gibi sarılıp hicrana
Gönüllü sürgün oldum
Ruhumu arındıracak nehir
Gövdemi gizleyecek bir şehir aradım
Hıçkırıklarımı çığlığa dönüştürecek
Sur diplerinde biriken ahaliyi umursamayıp
Suratıma kapanan kapıların sırrını anlamadan
Tapınaklar aradım
Putlar
İkonolar
Ayinler
Beynimde uğuldayan karanlık sözler
Sırtımda kabaran kırbaç izleriyle
Bir sığınak bulmak için harcadığım ömrümü
Mahşerin gizi sandığım
Vebalimle teselli ederdim
Zaman tükendi
Sura üflendi nefes
Yay gerildi
Hevesle donandı ok
Ricat hallerim müstesna
Tepeden tırnağa isyan menzilindeyim
V
Işığa yabancı
Renklere düşmandım
Varlığımdan tereddüt eder
Ruhumdan hicap duyardım
Bana kuçak açan bu dünyaya
Kapardım da gözlerimi
Kabirde çürüyecek bedenime
Lamekan cennetler bulabilmek için
Dara durur
Çile çekerdim
Aah...
Benim takatsiz bahtım
Aah...
Mecalsiz kalbim
Sığındığım bütün tekkelerden
Edindiğim sabır taşları
Mürşid bildiğim şehlerden
Kuşandığım karanlık ayetler
Ne tesselli oldu
Azap dolu ömrüme
Ne sızılarımı dindirdi
Perde düştü
Gün vurdu
Kendimden bile sakladığım
Kabuk bağlamış yaralarım
Yeniden soyuldu', 'Beyninde dolaşan sorulara Yanıt Kalbinde çarpan aşklara Kanıt Değilse yaşadıkların Hükmü tarihtir artık Kanla yazacakların UYANIŞ I Biliyoru...', ARRAY['Türk Edebiyatı','Şiir','A. Galip']::text[], 8.5, '{"poet":"A. Galip","poet_slug":"a_galip","theme":"Türk Şiiri","is_hero":false,"total_lines":216}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR İHTİYAR', 'bi-r-i-hti-yar-enver-gokce-b6p9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidiyorlar!
Atları, terkileri,
Göğüslerinde gümüş köstekleri yoktur.
Gidiyorlar!
Baş açık, yalın ayak, ardı arkasına
Ümitten gayri ekmekleri yoktur
Sen
Vermişsin de sırtını meşeye
Koca ihtiyar!
Yolların, yolcuların
Akşamla değişen şeylerin haricindesin.
Hatıralarınla yaşıyorsun :
İşte yine
Getirdiler bohçasını önüne
İşliği, çakmağı, tabakası,
Çorabı, çakısı, ayakkabısı
Ve Zonguldak treni,
Zonguldak madeni, kömür havzası,
Çakmağı, işliği, ayakkabısı.
Ötede insanlar gidiyorlar.
İşte yine getirdiler bohçasını önüne :
Sarsan bir cigara daha
Vursalar orta telden Emrah''ı
Yüreğin tutar mı söylemeğe
Başa gelen halleri?
Bir buçuk ay gezdin dağları
Avutmadı gönlünü
Toprak kokusu, keklik kokusu, çiğdem, çiçekler.
Keklikler konardı
Bir o taşa bir bu taşa
Ha deyip de çekemediğim tetiği.
Kınasını oynatamadığın
Düğününde oynayamadığın
Körpe kuzu düştü yadına,
İndin bahçeye :
Dayadın sırtını duta.
Domatesler kızarmıştı,
Yılı değildi bal armudunun,
Adam boyunu geçmemişti tınaz
Sonra malum...
Şimdi toprağa bakamıyorsun.
Çifte salsan kara öküzü
Gözlerine bakamıyorsun.
Bütün gözler onun gözleri
Bütün çalışanların emeği,
Onun emeği,
Sonra malum...
Zonguldak treni
Kömür dağları, kömür madeni
İnsanlar gidiyorlar
Gurbete,
Şehire,
Kara,
Sen bir efkar gelmiş de ağlıyorsun.', 'Gidiyorlar! Atları, terkileri, Göğüslerinde gümüş köstekleri yoktur. Gidiyorlar! Baş açık, yalın ayak, ardı arkasına Ümitten gayri ekmekleri...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver_gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":56}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KAHRAMANIN MİDESİ', 'bi-r-kahramanin-mi-desi-ercument-behzad-lav-bnx2u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vahşi hayvanlara yediriyorlar ölülerimizi
Beyazlar bizimle savaşınca
Bizse kendimiz yiyormuşuz
Onları haklayınca
Böyle de olsa
Daha şerefli bir mezar değil mi
Hayvan bağırsaklarından
Bir kahramanın midesi?', 'Vahşi hayvanlara yediriyorlar ölülerimizi Beyazlar bizimle savaşınca Bizse kendimiz yiyormuşuz Onları haklayınca Böyle de olsa Daha şerefli ...', ARRAY['Türk Edebiyatı','Şiir','Ercüment Behzad Lav']::text[], 8.5, '{"poet":"Ercüment Behzad Lav","poet_slug":"ercument_behzad_lav","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KAHRAMANIN TEREKESİ', 'bi-r-kahramanin-terekesi-dritero-agolli-qzuo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne okulun yaşlı hademesi bildi
Ne biz, ve ne de eski arkadaşları
İlerde bir gün onun adının
Yıldızlar arasında yer alacağını.
Bilseydik
Okuduğu sırayı toz içinde bırakmaz
Temizlerdik özenle ve umutla
Onun tahtaya yazdığı tebeşirinden bir parça
Saklardı yaşlı hademe sigara tabakasında.
Böyledir işte, çok kez, geleceğin kahramanları
Aramızda yaşarlar da biz bilmeyiz onları.
Dritero  AGOLLİ', 'Ne okulun yaşlı hademesi bildi Ne biz, ve ne de eski arkadaşları İlerde bir gün onun adının Yıldızlar arasında yer alacağını. Bilseydik Okud...', ARRAY['Türk Edebiyatı','Şiir','Dritero  Agolli̇']::text[], 8.5, '{"poet":"Dritero  Agolli̇","poet_slug":"dritero_agolli","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
