INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KAPININ İKİ YÜZÜ', 'bi-r-kapinin-i-ki-yuzu-ahmet-ozer-98zr7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kapının bir yüzü gökyüzüdür
bir yüzünde ağıtı gizlidir tüm annelerin.
içerde biçilen sözcükler çınlar/süt kokan
ağızdan
bir bebek uzun yolculuğuna çıkar uykunun
ufkunda
sobanın parlayan alevleri resmini çizer
yalnızlığın
içerde sözcüklerin masalları dokuyan sıcaklığı
seferberlik trenleridir cephede kalanları
anlatan.
içerde begonyanın damarlı yaprakları
bir haritayı tamamlar
duvarda türküler içmiş bir saz salınır
akordlu telleriyle
mayıslardan fotoğraflar/yürüyen seslere
yaslanmış şiirler
saatin çalışkan yelkovanı/tembel akrep
kutsal kitabın çöl ikliminden sağılan sesi.
dışarıda çınarın dalları tarihle kucaklaşır
karanlığın ellerinden kurtulan güneşin bilge
yüzü
dökülür kapının bir yüzüne
dışarda ayın karanlığı biçen ışığı/suyun
kanayan sesi
kuşların sokulgan uçuşları sirenlerin ürperten
dişleri
korkuya teslim olmuş duvarlar.
gecesefaları yaseminlerle kolkola
bir buhurdandır düşlerimizi havalandıran
dışarda bir hüzün yeli dolaşır
parmakları
tokmakların tozlarında.
içerisi sevgiye akar sesimiz yettiğince
dışarısı hüzne sefer eyler düşlerimizi içerek.', 'bir kapının bir yüzü gökyüzüdür bir yüzünde ağıtı gizlidir tüm annelerin. içerde biçilen sözcükler çınlar/süt kokan ağızdan bir bebek uzun y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KAYIĞA BİNER GECELERİ', 'bi-r-kayiga-bi-ner-geceleri-gulten-akin-ssgyw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tadını, yağmura duygulanmanın
Paylaşır kuşlarla biri gizlice
Gülmesini tutamamış bir sincap
Sallanır utanç bahçesinde
Yalnız atlar yıkılır düzlerde suya özlemlerinden
Bir ben miyim yalnızlığa yenilen, sen, sen, sen
Uzun sokakların ucunda evleri
İlk denemelerden geri dönülmüştür
İtildikçe, içe durduğu bilinen
Bazı dostları yitirmeye gidilir
Yalnız atlar yıkılır düzlerde suya özlemlerinden
Bir ben miyim yalnızlığa yenilen, sen, sen, sen
Bir kayığa biner geceleri
Sığlıkta o kadın tek başına
Dua biçiminde inceltir korkuyu
Sunar içtenliksiz, tanrısına
Yalnız atlar yıkılır düzlerde suya özlemlerinden
Bir ben miyim yalnızlığa yenilen, sen, sen, sen', 'Tadını, yağmura duygulanmanın Paylaşır kuşlarla biri gizlice Gülmesini tutamamış bir sincap Sallanır utanç bahçesinde Yalnız atlar yıkılır d...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KENTİ YAŞAMAK', 'bi-r-kenti-yasamak-ozdemir-i-nce-apsgv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kenti yaşamak
ona boyun eğmektir-
sözleşmesiz, anlaşmasız-,
ne derse tek tek yapacaksın,
düşünmeden, direnmeden.
Yabancıysan
ve gezgin değilsen
"bir kent yeter" diyeceksin,
"tek bir ölüm";
boğazına oturmuş olan
bir bardak su isteyen.
Boyun eğeceksin yolcu!
bir köle gibi tıpkı,
anlamak için belki,
nedir mutluluğu bir tutsağın?', 'Bir kenti yaşamak ona boyun eğmektir- sözleşmesiz, anlaşmasız-, ne derse tek tek yapacaksın, düşünmeden, direnmeden. Yabancıysan ve gezgin d...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir_ince","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KEZ GÖNÜL YIKTINISA', 'bi-r-kez-gonul-yiktinisa-yunus-emre-1xfrt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kez gönül yıktınısa
Bu kıldığın namaz değil
Yetmiş iki millet dahi
Elin yüzün yumaz değil
Bir gönülü yaptınısa
Er eteğin tuttunusa
Bir kez hayır ettinise
Binde bir ise az değil
Yol odur ki doğru vara
Göz odur ki Hakk''ı göre
Er odur alçakta dura
Yüceden bakan göz değil
Erden sana nazar ola
İçin dışın pür nur ola
Belî kurtulmuştan ola
Şol kişi kim gammaz değil
Doğru yola gittin ise
Er eteğin tuttunusa
Bir hayır dua ettinise
Birine bindir az değil
Yunus bu sözleri çatar
Sanki balı yağa katar
Halka meta''ların satar
Yükü gevherdir tuz değil', 'Bir kez gönül yıktınısa Bu kıldığın namaz değil Yetmiş iki millet dahi Elin yüzün yumaz değil Bir gönülü yaptınısa Er eteğin tuttunusa Bir k...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KIYI KAHVESİNDE', 'bi-r-kiyi-kahvesi-nde-i-lhan-berk-zk94x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün ağmıştı. Adaçaylarımızı söylemiş miydik?
Üç kişi bir köşede oturmuş ağ yamıyordu.
Kimimiz aznif oynuyor, cıgara üstüne cıgara
yakıyordu kimimiz. Sanki dünya durmuştu
öyle dalmış gitmiştik. Kendi kendimizdik.
Bir sürü kırlangıç dışarda camlara vuruyordu.
Birden bir ses, yüzüne karışmış bıyıkları,
-Deniz çekildi, dedi. Hepimize tutup
denizde gezdirdiği gözlerini. Büyük
bir boşluk bırakıp sonra da arkasında
Kalktı.
Biz işte o zaman gördük onu
ve çekilen denizi.
O zaman çıktık kendimizden.
Dışarda bir dilim ekmek gibiydi gök.
Delta ve Çocuk', 'Gün ağmıştı. Adaçaylarımızı söylemiş miydik? Üç kişi bir köşede oturmuş ağ yamıyordu. Kimimiz aznif oynuyor, cıgara üstüne cıgara yakıyordu ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KIZ VARDI JAPONYADA', 'bi-r-kiz-vardi-japonyada-n-zim-hi-kmet-1y4ki', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '............
Bir kız vardı Japonyada
ufacık, tefecik bir kız,
Bir bulut vardı dünyada
işi: öldürmekti yalnız.
Bu bulut bu kızcağızın
öldürdü nineciğini,
külünü göğe savurdu,
sonra, yine apansızın
gelip babasını vurdu,
sonra da kızın kendisini.
Ve doymadı ve doymadı
yeni kurbanlar arıyor.
Atom ölümüdür adı,
karanlıkta bağırıyor.
Büyük bir birlik kuralım,
canavarı susturalım.
Savaş cengine gidelim,
canavarı yok edelim.', '............ Bir kız vardı Japonyada ufacık, tefecik bir kız, Bir bulut vardı dünyada işi: öldürmekti yalnız. Bu bulut bu kızcağızın öldürdü...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KIZ', 'bi-r-kiz-kemal-ozer-v3b7r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneş altında titreşen
yağmur damlası gibi
ışık içinde bir kız
on iki - on üç yaşlarında
dolaşıyordu gördüm
boynunda bir tasmayla
Bir ülkü mü, bir düş mü
bir yaşam mı bilinmez
neyse aradığı ona
bağlamaya hazır kendini', 'Güneş altında titreşen yağmur damlası gibi ışık içinde bir kız on iki - on üç yaşlarında dolaşıyordu gördüm boynunda bir tasmayla Bir ülkü m...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KOZADA', 'bi-r-kozada-rifat-ilgaz-qrqzt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geç kalmadık tam zamanı
İş başlamaktaydı başladık
Örüyoruz kozamızı birlikte
Zaman da bir kozadır ipek böceğim
Her solukta örülen
Bir dışındayız bir içinde
Bir gün bizim de dokunacak
Atlasımız çalışkan ellerde
Gül yaprağı inceliğinde duru
Sabahların eridiği mavilikte
Mekikler söyleyecek türkümüzü
En güzeli bu değil mi övgünün
En sürüp gideni ipekte
İlk yağışla başladı diriliş
Özsuyla buğulandı dalların ucu
Yaprağa durdu dipten doruğa
Bahçedeki dut ağacı
(1970)
Uzak Değil adlı şiir kitabından 1970
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Geç kalmadık tam zamanı İş başlamaktaydı başladık Örüyoruz kozamızı birlikte Zaman da bir kozadır ipek böceğim Her solukta örülen Bir dışınd...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR KÖPRÜDEKİ İNSANLAR', 'bi-r-koprudeki-i-nsanlar-wislawa-szymborska-m1tmy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garip bir gezegen, garip insanlarıyla.
Zaman teslim olur, ama tanımazlar.
Protestolarını ifade etmenin yolunu bulur,
Resimler yaparlar, bunun gibi mesela:
İlk bakışta özel bir şey yok.
Su görürsün
Bir sahil görürsün.
Akıntıya karşı zorlukla giden bir tekne görürsün.
Suyun üstünde bir köprü ve üstünde insanlar görürsün.
İnsanlar görünür şekilde adımlarını sıklaştırır,
çünkü demin başlamıştır bir yağmur
kara bir buluttan aşağıya kamçılarcasına.
Mesele şu ki arkasından hiçbir şey olmaz.
Bulut ne biçimini ne rengini değiştirir.
Yağmur ne yoğunlaşır, ne durur.
Tekne hareketsizce süzülür.
Köprüdeki insanlar
biraz önce bulundukları yere koşarlar.
Burada araya sokuşturmadan olmayacak:
bu hiç de öyle masum bir resim değil.
Burada durdurulmuştur zaman.
Yasaları çiğnenmiştir.
Gelişen olaylara etkisi engellenmiştir.
Hakaretle defedilmiştir.
Bir âsinin sayesinde,
belirli birinin, Hiroşige Utagava diye
(nasıl olmuşsa, aslında
uzun zaman önce hayli usulünce
aramızdan göç etmiş bir yaratık)
zaman tökezleyip düştü.
Belki de önemsiz bir kapristi,
birkaç galaksiyi örten uçuğun biriydi,
ama belki şunları da eklemeli:
Buralarda uygun görülür
bu küçük resme büyük itibar göstermek,
hayranlıkla bakıp çağdan çağa heyecanla titremek.
Bazıları için bu yeterli değil.
Boşanan yağmuru bile işitirler,
boyunlara ve omuzlara düşen serin damlaları duyarlar,
köprüye ve insanlara bakarlar,
sanki orada kendilerini görmüşçesine
hep aynı hiç bitirilmeyen koşuda
ebediyen yol alınacak sonsuz bir yol boyunca
ve utanmazlık içinde inanarak
işin aslında böyle olduğuna.
Wislawa SZYMBORSKA', 'Garip bir gezegen, garip insanlarıyla. Zaman teslim olur, ama tanımazlar. Protestolarını ifade etmenin yolunu bulur, Resimler yaparlar, bunu...', ARRAY['Türk Edebiyatı','Şiir','Wislawa Szymborska']::text[], 8.5, '{"poet":"Wislawa Szymborska","poet_slug":"wislawa_szymborska","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR İLKBAHAR ŞİİRİNE BAŞLANGIÇ', 'bi-r-i-lkbahar-si-i-ri-ne-baslangic-melih-cevdet-anday-w52zh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hava ne kadar güzel öğretmenim
Yollar ağaçlar kuşlar ne kadar güzel
Yeryüzü pırıl pırıl öğretmenim
Gizlisi saklısı kalmamış dünyanın
Nesi var nesi yoksa dökmüş ortaya
Bütün bitkiler, bütün hayvanlar, bütün taşlar
Sürüngenler, konglomeralar, serhaslar
Hepsi hepsi ortada öğretmenim.
Ne olur biz de gidelim
Burda kalsın kitaplar
Burda kalsın iğneli karafatmalar
Kollarından bacaklarından gerilmiş kurbağalar
Burda kalsın hepsi
Bomboş kalsın hepsi
Bomboş kalsın evler okullar
Hapishaneler, hastaneler...
Öğretmenim, sevgili öğretmenim
Sırtımıza alırız hastaları
Kim bilir ne özlemişlerdir kırları...
Ya mahpuslar.
Ne sevinirler kimbilir
Sarılıp sarılıp öperler adamı.', 'Hava ne kadar güzel öğretmenim Yollar ağaçlar kuşlar ne kadar güzel Yeryüzü pırıl pırıl öğretmenim Gizlisi saklısı kalmamış dünyanın Nesi va...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ÖLÜM İLANI', 'bi-r-olum-i-lani-can-yucel-nlsbb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaten hayalet olan
Gölge yazar Oğuz’un ölümü de
Herhalde kendinden rivayet
Oğuz’un cenazesi mi
Hayret!
Hem o hiç uyumaz ki
Belki de ilk kez oradan
Kendi kendini Türkçeye çevirecek
Yeni dikilmiş bir kalem selviyle
Ya da en eski daktilosuyla gecenin
Yıldızları tuş', 'Zaten hayalet olan Gölge yazar Oğuz’un ölümü de Herhalde kendinden rivayet Oğuz’un cenazesi mi Hayret! Hem o hiç uyumaz ki Belki de ilk kez ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ÖLÜMSÜZ YALNIZLIĞAŞİMDİ OTAĞ KURDUĞUMUZ', 'bi-r-olumsuz-yalnizligasi-mdi-otag-kurdugumuz-tahsin-sarac-8oh6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ŞİMDİ OTAĞ KURDUĞUMUZ
Islanır bir orman yağmurunda şimdi uzak
O bir suskun mavide ışıyan ilk sevimiz.
Kalacak tüm karanlığıma karşın belki tek
Yalnız seni uyuduğum şu ılık gece.
İlk soluğunca evrenin bir serinlik
Serpilir yirmi çağlar ötesinden çölümüze
Kaç ölümler aştık da vardık ancak işte
Bir ölümsüz yalnızlığa şimdi otağ kurduğumuz.', 'ŞİMDİ OTAĞ KURDUĞUMUZ Islanır bir orman yağmurunda şimdi uzak O bir suskun mavide ışıyan ilk sevimiz. Kalacak tüm karanlığıma karşın belki t...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Saraç']::text[], 8.5, '{"poet":"Tahsin Saraç","poet_slug":"tahsin_sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİRİ ÖLÜNCE', 'bi-ri-olunce-anna-ahmatova-ci8no', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biri ölünce,
İmgeleri değişir artık.
Gözleri başka görür, ağzı bambaşka
Gülümsemelerle gülümser gülümserse.
Bunu bir ozanın
Cenazesinden döndüğümde anladım.
O zamandan bu zamana
Birçok kez doğrulandı anladığım.
1940
Anna AHMATOVA', 'Biri ölünce, İmgeleri değişir artık. Gözleri başka görür, ağzı bambaşka Gülümsemelerle gülümser gülümserse. Bunu bir ozanın Cenazesinden dön...', ARRAY['Türk Edebiyatı','Şiir','Anna Ahmatova']::text[], 8.5, '{"poet":"Anna Ahmatova","poet_slug":"anna_ahmatova","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
