INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CHE GUEVERA', 'che-guevera-che-guevera-samdx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizim de dağlarımız vardır Che Guevera
Bakma şimdi durgunsa, bir şahan gibi duruyorsa
Yorgundur, savaşlar görmüştür, çeteciler barındırmıştır
Yani satılmış değillerdir hiç tüfek patlamıyorsa
Alaçamın, mor meşenin ardına silah çatıp yatmağa
Bizim de dağlarımız vardır Che Guevera
Bizim de halkımız vardır Che Guevera
Unutulmuş uzak tarlalar yalazında
Sazıyla, türküleriyle kardeşliğe vurgun
Bütün ulusların halkları gibi
Ve yalnız büyük fırtınalarla kımıldayan
Bizim de halkımız vardır Che Guevera
Bizim de ozanlarımız vardır Che Guevera
Sağ çıkmış güneşsiz taş odalardan
Yüreğiyle barışa, sevgiye yönelmiş
Çelik öfke bir yanı, bir yanı uysal mavi
Eğilmeden dimdik geçmiş demir kapılardan
Bizim de yiğit insanlarımız vardır Che Guevera
Bizim de delikanlılarımız vardır Che Guevera
Yokluklardan biyol kopup gelmiş
Üç zeytin, az ekmek üniversitelerde
Su gibi kızlar çarpar önce, alkol vurur
Öfkeli dolanırlar caddelerde
Ve başkaldırırlar akılları suya erende
Çünkü Vietnam hepimizin Vietnam''ı
Kongo hepimizin Kongo''su
Bir kere özsu yürümüştür dallara
Patlayacaktır ağır sancılarla karanlıklar
Varmak için o güzel yarınlara
Bizim de dağlarımız vardır Che Guevera', 'Bizim de dağlarımız vardır Che Guevera Bakma şimdi durgunsa, bir şahan gibi duruyorsa Yorgundur, savaşlar görmüştür, çeteciler barındırmıştı...', ARRAY['Türk Edebiyatı','Şiir','Che Guevera']::text[], 8.5, '{"poet":"Che Guevera","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CHE', 'che-arif-damar-h476q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sesti O
Bütün sesler içinde ayrı
Yürü diyen bir ses
Savaş diyen bir ses
Katıl diyen bir ses
Dağlar yadırgamaz en yüksek sesi
Sesi dağlara uygundu
Elleri vardı akan
Durmaya okşamaya alışamayan
Çiçekten sudan yapraktan
Kaleme silâhlara açılan
Elleri sesine uygundu
Saklardı kentin sevincini avuçlarında
Saklardı bir sıcaklığı
Geleceğin güneşini andıran
Hey Hey Hey
Kaç Köroğlu birden göçtü
Kaç Dadaloğlu indi dağdan
Kaç ırmak durdu kaç yıldız  aktı
Düştü yere kaç bin tüfek
Gün gelecek Gün gelecek
Bir köyde yağmur dinecek
Çocuklar güneşte sevinecek
Yolu açık Guevara''nın
Yolu açık Guevara''nın
Çocuklar kadar kim bilecek
Yürüyecek Yürüyecek
Evimize konuk olsa
Yolu da var gidilecek
Sesler ışıklar dursa
Yolu da var gidilecek
Gün gelecek Gün gelecek
Yolu da var gidilecek', 'Bir sesti O Bütün sesler içinde ayrı Yürü diyen bir ses Savaş diyen bir ses Katıl diyen bir ses Dağlar yadırgamaz en yüksek sesi Sesi dağlar...', ARRAY['Türk Edebiyatı','Şiir','Arif  Damar']::text[], 8.5, '{"poet":"Arif  Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CIVA', 'civa-yucel-kayiran-t39ib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'muslukta su var, akar.. biliyorum
kalemde mürekkep.. yazar
benim aklımda ne var ki Necati
akşam cümle cümle iniyor kalbime
doyumsuz her ben bir rakip ötekine
ceza gününün sahibi gibi gülerler
sonra dolanırlar etrafımda Necati
ama neden geç vardım ben bunun farkına
bulutlar yer arar yağmak için kendine
kime yaklaştıysam dinmedi içimdeki fırtına
ancak uzaklaşarak katlandım insanlara Necati
ama kalbim aktı hep neden esrara
köpeklerin halinde bir tuhaflık var
bakıyorlar öyle aldırmadan gülenlerin yaşamına
baktıkça daha çok kuşkulanıyorum ben Necati
ama neden köpüklendi aklım hep böyle kendine döne döne
Bu cıvayı kim koydu kalbimize Necati!
2001
[Çalgın]', 'muslukta su var, akar.. biliyorum kalemde mürekkep.. yazar benim aklımda ne var ki Necati akşam cümle cümle iniyor kalbime doyumsuz her ben ...', ARRAY['Türk Edebiyatı','Şiir','Yücel  Kayiran']::text[], 8.5, '{"poet":"Yücel  Kayiran","poet_slug":"yucel_kayiran","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İCMAL', 'i-cmal-kagan-kok-k6aya', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamandan sorumlu olan kendi
O sözcükleri kaç yalan dile çevirdi
Harap kalevi kelime
Suçlu izbe kalbime
Garip ihbarlar gelirdi
Onca dualar eden kimdi
Bir şenlik değil sadece ayindi
Zangoçsuz çanlar kiliselerde
Sözü icmal edecek diye
Sonuçta susmayı denedi
Ve onca söz sadece söylendi
Kasavet ve nisyan derdi
Hangi ses ve kaç dilde
Daha bin kez söylense de
Sanki aynı anlama gelirdi', 'Zamandan sorumlu olan kendi O sözcükleri kaç yalan dile çevirdi Harap kalevi kelime Suçlu izbe kalbime Garip ihbarlar gelirdi Onca dualar ed...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CİNAYET GIRNATA''DA İŞLENDİ', 'ci-nayet-girnata-da-i-slendi-antonio-machado-y5zr2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'CİNAYET
Tüfekler arasında yürürken görüldü o,
Uzun bir sokaktan
Çıktı soğuk kıra,
Gün doğarken daha
Şafakta, yıldızların altında
Öldürdüler Federico''yu.
Cellâtların mangası
Bakamıyordu yüzüne.
Kapadılar hepsi gözlerini.
Dua ettiler: Tanrı bile kurtarmayacak seni!
Düşüp öldü Federico
- Alnında kan, kurşun barsaklarında. -
Cinayet Gırnata''da işlendi.
Biliyorsunuz, - zavallı Gırnata''da. -
Onun Gırnata''sında.
OZAN VE ÖLÜM
Ölümle başbaşa yürürken görüldü o,
Korkmadan tırpanından.
- Gene de kuleden kuleye güneş
Çekiçler örste, örste, demirci ocaklarının örsünde.
Konuşuyordu Federico
Okşayarak, ölümle. Ölüm dinliyordu onu.
"Daha dün mısralarımda can yoldaşım,
Kuru avuçların şaklıyordu senin
Daha dün mısralarımda,
Daha dün kırağını verdin şarkıma
Ve ağlatı''ma gümüş tırpan keskinliğini,
Seni şakıyacağım, sende artık kalmayan eti,
Olmayan gözlerini,
Rüzgârın dağıttığı saçlarını şakıyacağım
O öpülen kırmızı dudaklarını...
Ölüm, güzel çingenem, ölümümsün dün de bugün de,
İçime çekerken Gırnata''nın havasını, Benim Gırnata''mın."
Yürürken görüldüler onlar...
Bir mezar yontun bana dostlarım
Ozan için
Taştan ve düşten, -Elhamra''da,
Suyun ağladığı bir çeşme üstüne,
Sonsuza kadar desin o:
Cinayet Gırnata''da işlendi! Onun Gırnata''sında!
Antonio MACHADO', 'CİNAYET Tüfekler arasında yürürken görüldü o, Uzun bir sokaktan Çıktı soğuk kıra, Gün doğarken daha Şafakta, yıldızların altında Öldürdüler ...', ARRAY['Türk Edebiyatı','Şiir','Antonio Machado']::text[], 8.5, '{"poet":"Antonio Machado","poet_slug":"antonio_machado","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CİNAYET SAATİ', 'ci-nayet-saati-attila-i-lhan-hmfs6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'haliç''te bir vapuru vurdular dört kişi
demirlemişti eli kolu bağlıydı ağlıyordu
dört bıçak çekip vurdular dört kişi
yemyeşil bir ay gökte dağılıyordu
deli cafer ismail tayfur ve şaşı
maktulün onbeş yıllık arkadaşı
üçü kamarot öteki aşçıbaşı
dört bıçak çekip vurdular dört kişi
cinayeti kör bir kayıkçı gördü
ben gördüm kulaklarım gördü
vapur kudurdu kuduz gibi böğürdü
hiç biriniz orada yoktunuz
demirlemişti eli kolu bağlıydı ağlıyordu
on üç damla gözyaşını saydım
allahına kitabına sövüp saydım
şafak nabız gibi atıyordu
sarhoştum kasımpaşa''daydım
hiç biriniz orada yoktunuz
haliç''te bir vapuru vurdular dört kişi
polis kaatilleri arıyordu
deli cafer ismail tayfur ve şaşı
üzerime yüklediler bu işi
sarhoştum kasımpaşa''daydım
vapuru onlar vurdu ben vurmadım
cinayeti kör bir kayıkçı gördü
ben vursam kendimi vuracaktım', 'haliç''te bir vapuru vurdular dört kişi demirlemişti eli kolu bağlıydı ağlıyordu dört bıçak çekip vurdular dört kişi yemyeşil bir ay gökte da...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CORONA', 'corona-paul-celan-fdz5j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güz kendi yaprağını yiyor elimden: biz iki dostuz.
zamanı ceviz kabuklarından ayıklayıp yürümeyi öğretiyoruz ona:
zamansa dönüyor kabuğuna.
aynada pazar,
düşte uyunan uyku,
ağızsa gerçeği söylemede.
gözüm bir sevgilinin cinselliğine teşne:
öyle bakışıyoruz,
karanlık sözler ediyoruz birbirimize,
haşhaş ve bellek gibi seviyoruz birbirimizi,
uyuyoruz şarap gibi midye kabuğunda,
bir deniz gibi ayın kanlı ışığında.
penceredeyiz sarmaş dolaş,kendimizi seyrediyoruz sokaktan:
vakt erişti, herkesler bilsin bunu!
artık çiçek açma zamanıdır taşın,
yüreğinse tedirginlik zamanı.
zamanıdır, zamanı gelmenin.
artık zamanıdır.
Çeviri: Sevil Eryaşar', 'güz kendi yaprağını yiyor elimden: biz iki dostuz. zamanı ceviz kabuklarından ayıklayıp yürümeyi öğretiyoruz ona: zamansa dönüyor kabuğuna. ...', ARRAY['Türk Edebiyatı','Şiir','Paul Celan']::text[], 8.5, '{"poet":"Paul Celan","poet_slug":"paul_celan","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CİVA YAĞMURLARI', 'ci-va-yagmurlari-arzu-aslan-gmq92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sürgünlerin işiydi
kentin heryerine macun gibi
sıvanmış halsizlik
akşamları zehirli pişmanlığı piç
haftalar boyunca
bütün perşembeler melezdi
düşlerinde uğuldayan civa yağmurları
bir damlası bin yaramaz
yutkunur gibi akardı ıslanmayan caddelerden
sevgili taslakları çaresiz
sürgünlerin işi buydu
can havliyle sılasını boğmak
yeni bir perşembeyi kışkırtıp sinsice
cinnet ertesi ufkundan
ötelere bakmak
zorda kalınca ellerine danışırdı
yüzüne iyi gelirdi bu
akşamları zehirli pişmanlığı piç
gönülsüz uykusuna aldanmayın
düşlerinde civa yağmurları', 'sürgünlerin işiydi kentin heryerine macun gibi sıvanmış halsizlik akşamları zehirli pişmanlığı piç haftalar boyunca bütün perşembeler melezd...', ARRAY['Türk Edebiyatı','Şiir','Arzu Aslan']::text[], 8.5, '{"poet":"Arzu Aslan","poet_slug":"arzu_aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ciğerlerime dolan duman ey o ölümün yoğun anıKar sularının eriyen sesiyim, beni yokluğumdan tanı', 'cigerlerime-dolan-duman-ey-o-olumun-yogun-anikar-sularinin-eriyen-sesiyim-beni-yoklugumdan-tani-c-hakki-zari-c-salxa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar sularının eriyen sesiyim, beni yokluğumdan tanı
SİS VE TUZ
O''na, sıfırda kalana veda şiiri...
Uyku tutmuyor kaçışı olmayan tanıdık sabahı
Açık kapılardan hâki ayak sesleri sızıyor
Tabana çöküyor tavan, sis kaplıyor her yanı
Hayata Dönüş Operasyonu’nun gri kurşunlarıyla
Hasar tespit tutanakları yazıyorum ömrüme
Kan soluyorum, öğürüyor, kusuyor ve soluyorum
Soluyor penceredeki begonyanın yaprakları
Zayıfladıkça gözleri büyüyen ölüm oruççuları
Küfre yaslanıp ayakta durduğum anlar soluyor
Suratımda kahkahaları patlayan kırık aynalar
Ve horozu kalkık tabancaların maskeli tehdidi
Parçalanmış bir kafatası düşürüyor kucağıma
Her kıpırtıda serçeler havalanıyor içimden göğe
Soğuktan titriyorum, parmaklarım uyuşuyor
Gözleri bağlı kuzeyin, oldukça yavan ve yalancı batı
Buz tutuyor gülüşüm ağzımda, buz tutuyor, buz
Anları düşünüp anlamlar aramaya çabalıyorum
Dolanıyor sığıntı halinde, derinliğini arıyor gün
Her şey bir ayrılık armağanıyla adlandırılıyor
Bir kadının salı sabahındaki vazgeçilmez güzelliği
Hayli baş ağrısı, elleri havadaki yenilgi
Kalın bir çift çorap, öksürük nöbeti, boğulma anı
Tuz sonra, sağanak halinde tuz, tuz !..', 'Kar sularının eriyen sesiyim, beni yokluğumdan tanı SİS VE TUZ O''na, sıfırda kalana veda şiiri... Uyku tutmuyor kaçışı olmayan tanıdık sabah...', ARRAY['Türk Edebiyatı','Şiir','C. Hakkı Zari̇ç']::text[], 8.5, '{"poet":"C. Hakkı Zari̇ç","poet_slug":"zaric","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
