INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ ÖRTEN', 'dus-orten-bulent-ozcan-n7124', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Salınır şiirim uykuda
Yanar diri imgelerim
Yüreğim mürekkep lekesi
Damıtır acıyı güzellerim
Hüznümü kanatır bir dize
Süzülüp içinden dizelerin
Gezerim bir bir sözcükleri
Yüzümü Nil''e dökerim
Benim uslu çocuk yanım
Söyle nerde yitik gemin
Kıyı belledin göğü hep
Denizini görmediğin...', 'Salınır şiirim uykuda Yanar diri imgelerim Yüreğim mürekkep lekesi Damıtır acıyı güzellerim Hüznümü kanatır bir dize Süzülüp içinden dizeler...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ - TİLKİ', 'dus-ti-lki-ted-hughes-vbsyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece yarısı anının ormanını düşlüyorum:
Yaşayan başka bir şey var
Saatin yalnızlığının ve parmaklarımın
Kımıldadığı şu boş sayfanın dışında.
Tek yıldız görünmüyor pencereden:
Daha yakın, karanlıkta
Daha derin bir şey
Yalnızlığın içine doğru ilerliyor:
Soğuk, karanlık kar kadar ince,
Bir tilkinin burnu değiyor dala, yaprağa;
İki göz bir devinimi belirtiyor,
Durup yeniden birer birer
Açık seçik izler bırakıyor karın üzerinde
Ağaçlar arasında, sonra dikkatle
Topal bir gölge bacağını sürüklüyor
Ve açıklığa çıkmaktan korkmayan
Bir gövdenin boşluğunda, bir göz,
Büyüyen derinleşen bir yeşillik,
Parlak, dikkat kesilmiş,
Kendi işini görürken, birden,
Sıcak, keskin tilki kokusuyla
Kafadaki karanlık boşluğa yerleşiyor.
Pencere hâlâ yıldızsız; saat işliyor,
Sayfa artık boş değil.', 'Bu gece yarısı anının ormanını düşlüyorum: Yaşayan başka bir şey var Saatin yalnızlığının ve parmaklarımın Kımıldadığı şu boş sayfanın dışın...', ARRAY['Türk Edebiyatı','Şiir','Ted  Hughes']::text[], 8.5, '{"poet":"Ted  Hughes","poet_slug":"ted_hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ VE GERÇEK', 'dus-ve-gercek-metin-guven-sxkju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzun bir eteğin pilesine takılıyor gözlerim
Denizden çıkmış balıklara benzeyen kazağın rengine
Sarılıyoruz, ekmek ve şarap gibiyiz
Hem düş, hem gerçek olduk birbirimize.', 'Uzun bir eteğin pilesine takılıyor gözlerim Denizden çıkmış balıklara benzeyen kazağın rengine Sarılıyoruz, ekmek ve şarap gibiyiz Hem düş, ...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ VE KUDRET', 'dus-ve-kudret-meti-n-findikci-j4j76', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yansıyan kandil yangını
Uzak karanlığın kayganlığında, provasız
Cambuğusuna çizilir iki kalbin arasına düşen bıçak.
Kalbim parçalanmış mimoza
Taşların takasında unutulan
Yıllar sonra ilk neyi sormalıyım sana!
Kendi ışığına doğru uçar aşk.
"İki nehir ki bacakların"
Kendi kuytusuna çekilmiş renksiz,
Birçok beklentiye yenik bakıyorum suyuna
Bir kasrın taşlarındaki hüzün eskisiyle
Bozulsaydı.
Aynasına bakıp kirlettiğimiz suyun büyüsü
Bozulurdu,
İki çıplak ten arasında
Hazır kopmak üzreyken fırtına.
İşte çıplaksın ve gizler yaşıyor bedeninde.
İstanbul, 01.01.1997', 'Yansıyan kandil yangını Uzak karanlığın kayganlığında, provasız Cambuğusuna çizilir iki kalbin arasına düşen bıçak. Kalbim parçalanmış mimoz...', ARRAY['Türk Edebiyatı','Şiir','Meti̇n  Findikçi']::text[], 8.5, '{"poet":"Meti̇n  Findikçi","poet_slug":"metin_findikci","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ VE ŞİİR', 'dus-ve-si-i-r-hu-so-0efgc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep bilinen yaşantılar,
Hep bilinen imgeler.
Nasılsa bir düşte birleştiler,
Sonsuz yeni biçimlerle.
Hep bilinen duygular,
Hep bilinen sözcükler.
Nasılsa bir şairle buluştular,
Sonsuz yeni şiirlerle.
Sarhoş olunca anlar insan şarabın gücünü,
Aşka düşünce aşkı:
Siz benim şiirlerimi yazamazsınız
Ben sizin düşlerinizi göremem.
Hu  ŞÖ', 'Hep bilinen yaşantılar, Hep bilinen imgeler. Nasılsa bir düşte birleştiler, Sonsuz yeni biçimlerle. Hep bilinen duygular, Hep bilinen sözcük...', ARRAY['Türk Edebiyatı','Şiir','Hu  Şö']::text[], 8.5, '{"poet":"Hu  Şö","poet_slug":"hu_so","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ YÜREK', 'dus-yurek-ingeborg-bachmann-gi968', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düş yürek zaman ağacından, düşün yapraklar
bir vakitler güneşin kucakladığı
donmuş dallardan
düşün apaçık gözlerden dökülen yaşlar gibi.
Gün boyu uçuşsa da saçlar rüzgârda
yanık alnında yer tanrısının
bastırır yumruk gömleğin altında
Bulutlar ince sırtlarını sana
bir kez daha iğseler de yumuşama;
önemseme Hymettos senin için
bir kez daha doldursa da petekleri.
Azdır çünkü çiftçiye kurakta tek bir sap,
azdır bir yaz bizim yüce soyumuz için.
Ya nedir yüreğinin kanıtladığı?
Dün ile yarın arasında sallanır durur
sessiz ve yaban;
vuruşları
vuruşları
düşüşüdür zamandan.
Ingeborg BACHMANN', 'Düş yürek zaman ağacından, düşün yapraklar bir vakitler güneşin kucakladığı donmuş dallardan düşün apaçık gözlerden dökülen yaşlar gibi. Gün...', ARRAY['Türk Edebiyatı','Şiir','Ingeborg Bachmann']::text[], 8.5, '{"poet":"Ingeborg Bachmann","poet_slug":"ingeborg_bachmann","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ ÜZÜMÜ', 'dus-uzumu-bedri-rahmi-yle34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bedri rahmi''ye
çekip alırdım seni korungan toprağından
koparır gibi salkım saçak üzümü dalından
kanatırcasına ısırırdım çilekçi dudaklarını
ağız dolusu alırdım seni katıksız
çiğnerdim hasretini bir kerecik yutmadan
düş üzümü iki gözüm benim
alı al dalı bal şeftalim
şekerparem, ıtır kokulu mandalinim
meyhoşsun, serhoşsun, pek hoşsun
taze fidansın, baharsın, çiçeğe kanmışşsın
kelebek peşinde koşmuş yorulmuşsun
darılmışsın afacanlık denizlerine
kımıltısız pınarlarımdan avuç dolusu çarp yüzüne
hınzır kaybolmuşlukları unutursun
gülücüklerimi sarıp yattığın zaman
ben koynuma deniz kızları alırım yakamozlu gecelerde
sen boynunda arsız bir ısırıkla uyanırsın', 'bedri rahmi''ye çekip alırdım seni korungan toprağından koparır gibi salkım saçak üzümü dalından kanatırcasına ısırırdım çilekçi dudaklarını ...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi']::text[], 8.5, '{"poet":"Bedri Rahmi","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dİ', 'di-enver-ercan-d78t9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'elim sana değse
diniyor gece
saçlarından başlıyorum
günü çözmeye
yüzüm sana değse
sürçüyor zaman
daracık odalarda
ben kâfir, sen müslüman
dilim sana değse
uyanıyor sözcükler', 'elim sana değse diniyor gece saçlarından başlıyorum günü çözmeye yüzüm sana değse sürçüyor zaman daracık odalarda ben kâfir, sen müslüman di...', ARRAY['Türk Edebiyatı','Şiir','Enver Ercan']::text[], 8.5, '{"poet":"Enver Ercan","poet_slug":"enver_ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞ BAŞINDA', 'dag-basinda-a-kadi-r-j6bih', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni bir dağ başında böyle yapayalnız kodular,
rüzgarlara, kuşlara, bulutlara yakın,
senin etinden, tırnağından ayrı,
senin kokundan uzak.
Benim güzelim,
benim ceylan bakışlım,
benim kafamın ateşi,
ve yüreğimdeki.
Mümkün mü şu anda rüzgar olmak, kuş olmak,
şu anda üç dört portakal almak, getirmek sana,
sana tuzlu badem,
kabakçekirdeği.
Şu anda hiç bir şey mümkün değil.
Şu anda her şeyden ayrı, her şeyden uzak
ve her şeyden mahrumum ben.
Şu anda sadece yalnızlık ve kahır.
Hayır, güzelim.
hayır, ceylan bakışlım,
hayır, kafamın ateşi, hayır,
hayır, yüreğimdeki.
Şu anda mümkün ve güzel olan tek şey vardır:
Yanarak sevmek seni.', 'Beni bir dağ başında böyle yapayalnız kodular, rüzgarlara, kuşlara, bulutlara yakın, senin etinden, tırnağından ayrı, senin kokundan uzak. B...', ARRAY['Türk Edebiyatı','Şiir','A. Kadi̇r']::text[], 8.5, '{"poet":"A. Kadi̇r","poet_slug":"a_kadir","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞ KELEBEĞİ', 'dag-kelebegi-antonio-machado-2mknz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Platero ile Ben adlı kitabı için Juan Ramon Jimenez''e
Sen değil misin, kelebek,
şu kimsesiz dağların canı,
derin uçurumları ile
sivri tepelerinin?
Sen doğabilesin diye
büyülü değneğiyle
taş fırtınalarına, emretti bir gün
durup susmalarını bir peri
ve zincirlendi o dağlar birbirine
sen uçabilesin diye.
Portakallı karalı,
esmer ve altın rengi,
dağ kelebeği,yabangülü üstünde
kat kat kanatçıkların, ya konar kalkarsın
oynaşarak güneşle, ya da bir günışını
üstünde çarmıha gerilmiş.
Dağ kelebeği,
kırların tepelerin kelebeği,
rengini resme dökemez kimse senin; yaşarsın
onu ancak sen ve kanatların
havada, güneşte, yabangülünde,
öylesine özgür ve öyle tatlısın ki
Juan Ramon Jimenez Fransisken lirinin tellerini
senin için okşar usul usul.
Sierra de Cazorla, 28 Mayıs 1915
Antonio MACHADO', 'Platero ile Ben adlı kitabı için Juan Ramon Jimenez''e Sen değil misin, kelebek, şu kimsesiz dağların canı, derin uçurumları ile sivri tepele...', ARRAY['Türk Edebiyatı','Şiir','Antonio Machado']::text[], 8.5, '{"poet":"Antonio Machado","poet_slug":"antonio_machado","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DA', 'da-arif-damar-27pe0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni seviyordum seni sevdim
Islak buzağıları seviyordum seni sevdim
Kartal kanatlarını mor menekşeleri keçi yollarını
Öğle sıcaklarında ağır salkımların serin odalarını
Patiska örtüleri köşe yastıklarını ak dantelleri
Bir kapının benim için açılmasını tek benim
Beklenmesini seviyordum seni sevdim
Yalnız kendi bardağımda istemiyordum çayları içkileri
Bir otçuğu koparmasını istemiyordum
Sana vermiyecek olduktan istemiyordum
Elma dilimlerinde cıgara küllerini
Yemek artıklarını çiçekli tabaklarda
Kimsenin aç
Karanlıkta kalmasını
Ben seni
Sıcak ekmeklerden bir sokum
Ayın ondördünü', 'Ben seni seviyordum seni sevdim Islak buzağıları seviyordum seni sevdim Kartal kanatlarını mor menekşeleri keçi yollarını Öğle sıcaklarında ...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DADA ŞARKISI', 'dada-sarkisi-tristan-tzara-3ar7e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I
Bir dadacının şarkısı
yüreği dadayla dolu
fazlaca yordu motoru
yüreği dadayla dolu
Asansör bir kral taşıyordu
ağır çıtkırıldım özerk ayrıca
kırsın mı sana sağ kolunu
yollasın mı Roma''daki Papa''ya
Artık bu yüzden işte
Asansörcüğün yüreğinde
dada mada hak getire
Tıkınıp durun çikolata
yıkayıp beyninizi
dada
dada
su için üstüne sonra
II
Bir dadacının şarkısı
ne hüzünlü olan ne de neşeli
seviyordu bir bayan bisikletçiyi
o da ne hüzünlü ne neşeli
ama yılbaşında kıskanç koca
öğrendi ne dönüyorsa hepsini
bir öfke sonucu yolladı Vatikan''a
üç bavul içinde ikisinin cesedini
Ne bizim sevdalı
ne de bayan bisikletçi
artık ne hüzünlü ne neşeli değildi
Beyinler layık ağzınıza
askerinizi yıkayın hamamda
dada
dada
su için üstüne sonra
III
Bir bisikletçinin şarkısı
yüreğin dadası ondaki
bir dadacıydı kısacası
yüreğin tüm dadacıları gibi
Eldivene bürünmüştü bir yılan
güvenlik musluğunu der demez kapadı
yılan gömleğine dönüştü eldiven
ve kucakladı hazreti Papa''yı
Asıl dokunaklı olan
çiçekten bir karın
ve artık yok dada falan
kuş sütü bardaklarda
ve yıkanmıştır çikolata
dada
dada
gelin dana şişkebabına
Tristan  TZARA', 'I Bir dadacının şarkısı yüreği dadayla dolu fazlaca yordu motoru yüreği dadayla dolu Asansör bir kral taşıyordu ağır çıtkırıldım özerk ayrıc...', ARRAY['Türk Edebiyatı','Şiir','Tristan  Tzara']::text[], 8.5, '{"poet":"Tristan  Tzara","poet_slug":"tristan_tzara","theme":"Türk Şiiri","is_hero":false,"total_lines":54}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞDA ATEŞ YAKANLAR', 'dagda-ates-yakanlar-omer-faruk-toprak-21i01', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Bu saatte Kuzey Afrikanın
dağlarında ateş yakanlar var-
Bir şafak vakti başlayacak yolculuğumuz
Cıgaralar sönmüş parmaklarımızda
Düşünmemek mümkün mü gelecek günleri
Bir başka mâkam üzre başlamış şarkılar
Seslerini duyuyorum görmediğim şehirlerin
Milyonlarca insan karşılamış orda barışı
Şu mavi gökyüzü bu ıslak asfalt caddeler
Okyanus kıyıları işte yeşil sırtlı balıklar
Say sayabildiğin kadar hepsi yeryüzünde
Onların hasretini sizler kadar kimbilir
Afrika kıyılarında çarpışan vatanseverler
Korkusuz uyanacağınız sabahları düşünüyorsunuz
Mavi salkımlı pencerelerin arkasında
Başladı işte akşam saatlerinizin hüznü
Dile gelmiş bırak dört duvar konuşuyor
Kimdir onlar diye sormayın bütün insanlar
Ben bilirim o cana kıyan sabahları
Gün doğmuş kuşlar cıvıldaşır dışarda
Bir ince duman tüter bacalardan
Şakır şakır güneşle yıkanır kelimeler
Haberin olmaz çiçek açmış yemyeşil dallardan
Nasıl unutabilirim işte karşımdasın
Dilimde hâlâ tadı var dudaklarının
Yaşamak ne kadar mümkünse o kadar güzel
Elbette özgür konuşmak kolay değil
İstemem artık gözyaşı korku ve keder
Yalnız aydınlık bir Afrika için konuşacağız
Bilmem sen de bunları düşünüyor musun
Yaşamak sade kederle kanla yuğrulmamış
Bir defa da alınterinin saadetin hakkını düşün
Düşün zafer türkülerini düşün barış adına atılan topları
Yağmur çiseler dar sokaklı şehirlerine
Nasıl beklemesin kırkbin köy dörtyüz kasaba
Yaklaşan büyük çimento çelik fabrikalarını
Her sabah haber sorarım gümüş kanatlı kuştan
Artık âşinam olmuş dağda ateş yakanlar
Sabır birikmiş gözlerimde yaş yerine
Biliyorum bir duman gibi tütüyor karşınızda
Karacaoğlan''ın yaktığı türkülerle beraber yürümek
İşte Galata rıhtımı en kalabalık saati köprünün
Farkında mısın Balıkpazarında bütün dükkânlar açık
Göğüs dolusu hasreti var Afrikanın şimdi
Bütün özgür yaşayan insanlara karşı', '-Bu saatte Kuzey Afrikanın dağlarında ateş yakanlar var- Bir şafak vakti başlayacak yolculuğumuz Cıgaralar sönmüş parmaklarımızda Düşünmemek...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Toprak']::text[], 8.5, '{"poet":"Ömer Faruk Toprak","poet_slug":"omer_faruk_toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DADA BİLDİRİSİ (1918)', 'dada-bi-ldi-ri-si-1918-tristan-tzara-ceduc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ailenin yadsınmasını doğuran nefretin tümü ürünü dadadır; yerle bir edici eylemin,
var güçle yumruklarda anlatılışı: DADA; incelik ya da uysal bir uzlaşmanın utangaç
duygusuyla, günümüze değin yadsınmış tüm yolların tanınması: dada; doğuştan
zavallıların dansı olan mantığın yok edilişi: DADA; tüm hiyerarşiler ve uşaklarımızca
bir değer olarak ortaya atılan her tür toplumsal eşitsizliğin yok edilişi: DADA;
eşyanın her biri ve tümü, duygular ve karanlıklar, görünüşler ve koşut çizgilerin
belirgin çarpışması kavga için birer yoldurlar: DADA; belleğin yok edilişi: DADA;
kazıbilimin yok edilişi: DADA; peygamberlerin yok edilişi: DADA; geleceğin yok
edilişi: DADA;saflığın doğrudan ürünü olan her Tanrı''da tartışılmaz salt inanç:
DADA; öbür küreye, uyum gözetmeksizin, zarif atlayış; haykırışçasına çınlayan
disk gibi fırlatılmış sözün izlediği yol; ciddi, tasalı, utangaç, ateşli, güçlü, kararlı
ya da tutkulu olsun, ona bağlı çılgınlıkları içinde tüm kişiliklere saygı; kilisesini,
gereksiz, ağır tüm süspüsünden arındırmak, sevimsiz ya da sevdalı düşünceyi
parıltılı bir çağlayan gibi tükürmek ya da onu göklere çıkarmak - olması ile
olmaması bir büyük doyum duygusuyla- ve çalılıklardakine denk yoğunlukla,
meleklerin vücutlarının ve ruhunun soylu ve altın kanı için saf, temiz böcekler.
Özgürlük: DADA DADA DADA, kasılmış acıların uluması, çelişkilerin, aykırılıkların,
kabalık ve tuhaflıkların (grotesque), bağdaşmazlıkların sarmaşması: YAŞAM.
Tristan  TZARA', 'Ailenin yadsınmasını doğuran nefretin tümü ürünü dadadır; yerle bir edici eylemin, var güçle yumruklarda anlatılışı: DADA; incelik ya da uys...', ARRAY['Türk Edebiyatı','Şiir','Tristan  Tzara']::text[], 8.5, '{"poet":"Tristan  Tzara","poet_slug":"tristan_tzara","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞÇİÇEĞİ SAĞANAĞI', 'dagci-cegi-saganagi-hamdi-ozyurt-xoepc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kızım benim
en güzel şiirim
kırık kapımdan içeri
dağçiçeği sağanağı
hoşgeldin
kalbim artık
ağzın kadar narin
ve ince dudaklarından
babamı vuranı bile affettim
n''olur taşa değmesin
ayağı oğlakların
martılar ah martılar
kırılmadan kanatları
çıkabilse fırtınadan
tarihten eski bir müjdedir
bu caniçi felsefe
bu kısmet bu bereket
bu şaşkın matematik
neye dokunsam beş parmak yeşil
bir artı bir üç ettik
kızım benim
en güzel şiirim
kırık kapımdan i��eri
dağçiçeği sağanağı
hoşgeldin', 'kızım benim en güzel şiirim kırık kapımdan içeri dağçiçeği sağanağı hoşgeldin kalbim artık ağzın kadar narin ve ince dudaklarından babamı vu...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Özyurt']::text[], 8.5, '{"poet":"Hamdi Özyurt","poet_slug":"hamdi_ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAHA SARI', 'daha-sari-melih-elhan-itssu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'adınla yaralı ağaç
kurudu bahçede
daha az giriyorsun
artık düşüme.
bir imge
kayboluyor yavaş yavaş
-yüzün -
bir nehir vazgeçiyor akmaktan,
sesin son kez
geçiyor sokaklardan,
bir şarkı sözsüz kalıyor,
kelebek bırakıyor kendini.
bu güz daha sarı geçecek', 'adınla yaralı ağaç kurudu bahçede daha az giriyorsun artık düşüme. bir imge kayboluyor yavaş yavaş -yüzün - bir nehir vazgeçiyor akmaktan, s...', ARRAY['Türk Edebiyatı','Şiir','Melih Elhan']::text[], 8.5, '{"poet":"Melih Elhan","poet_slug":"melih_elhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞI ISIT! KENDİNİ ISIT! ISINAN NE VARSA BİZDENDİR', 'dagi-isit-kendi-ni-isit-isinan-ne-varsa-bi-zdendi-r-altay-omer-erdogan-lfwp3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen portakaldan denize bakan bir yoksulluksun Akdeniz''in göbeğinde
acemi bir yüzle gülümseyen virgüllerin de dostusun
bir sevişmenin en yırtılan yerisin sen, güneşe vurulursun
körlükler yürürlükte tarihin gümüş asmalarında
coğrafyaya şaraplar döküyor el yordamıyla arzu,
ve uçurum unutturuyor düpedüz korkak olduğumuzu
çiçekler çoktan bırakmış yasta ve zifafta kanamayı
bir şarkıya dolanıyor çöl ve hançer, bin parçaya çelik saat
iki geçimsiz kardeş gibi uzak, iki iliksiz düğme gibi rahat
sen akşamın kahrında çoğalan bir çığlıksın tüm denizlerin kıyısında
konuşkan bir yaranın önsözüsün, ayrılık içip mutluluk kusan
ırmağın coşkusunu, yüksek tepelerin kibrini kuşan
haydi dağı ısıt, kendini ısıt, ısınan ne varsa bizdendir
yok yeni bir aşka başlamanın geçerli tek nedeni
sıfatlarımı geç, zakkumdan say beni
(Taş(ra) Baskısı, 2003)', 'sen portakaldan denize bakan bir yoksulluksun Akdeniz''in göbeğinde acemi bir yüzle gülümseyen virgüllerin de dostusun bir sevişmenin en yırt...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞILGAN GÖNLÜMÜZ', 'dagilgan-gonlumuz-eugenio-montale-9gshf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu dağılgan gönlümüzü kavrayıp her bir yandan
ateşten imlerle açıklayacak
ve tozlu çayırlarda yitmiş bir safran gibi
parıldayacak sözcüğü isteme benden
Ah güven içinde gidiyor insan
dost kendine ve başkalarına
önemsemiyor sıvası dökük bir duvarda
bıraktığı gölgesini kavurucu sıcağın
Sana dünyalar açacak anahtar isteme bizden
belki birkaç hece bir dal gibi kuru ve eğribüğrü
bugün yalnız şunu diyebiliriz sana
olmadığımız ve istemediğimiz şeyi
Türkçesi : Bedrettin Cömert', 'Şu dağılgan gönlümüzü kavrayıp her bir yandan ateşten imlerle açıklayacak ve tozlu çayırlarda yitmiş bir safran gibi parıldayacak sözcüğü is...', ARRAY['Türk Edebiyatı','Şiir','Eugenio Montale']::text[], 8.5, '{"poet":"Eugenio Montale","poet_slug":"eugenio_montale","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞINIK TERİM', 'daginik-teri-m-ren-char-nkymg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bağırdığında dünya susar: kendi dünyanla uzaklaşır.
Her zaman alamadığından daha fazlasını ver. Ve unut. Böyledir kutsal
yol.
Dikeni çiçeğe çeviren, şimşeği köreltir.
Şimşeğin bir tek evi vardır, birçok patikası. Ev yükselir, patikalar
kırıntısız.
Küçük yağmur yaprakları sevindirir ve geçip gider kendini
adlandırmadan.
Yılanların mahkum ettiği köpekler olabilir ya da ne olduğumuzu
susturabilirdik.
Akşam kurtulur çekiçten, insan yüreğine zincirlenmiş kalır.
Yer altındaki kuş, yeryüzündeki yasın şarkısını söyler.
Yalnız siz, çılgın yapraklar, siz doldurursunuz yaşamınızı.
Bir kitabın ölmeye geldiği bir plajı alevlendirmeye bir demet kibrit yeter.
Açıktaki ağaç yalnız. Rüzgarın kucaklaması ondan daha fazla yalnız.
Şimdiki zamanın kuşkusu ve sözünün hiç kazınmadığı uzakta kızıllığın
bu kör kayası olmasaydı, meraksız gerçek  kansız  kalırdı.  Her sözü
kendimize vaadederken, onu terkederek ilerliyoruz.
René CHAR', 'Sen bağırdığında dünya susar: kendi dünyanla uzaklaşır. Her zaman alamadığından daha fazlasını ver. Ve unut. Böyledir kutsal yol. Dikeni çiç...', ARRAY['Türk Edebiyatı','Şiir','René Char']::text[], 8.5, '{"poet":"René Char","poet_slug":"rene_char","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAKTİLODA BAHAR ŞİİRİ', 'dakti-loda-bahar-si-i-ri-metin-demi-rtas-qnge4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bahçedeki vişne ağacı
Çiçekten meyveye döndü
Daktiloda bahar şiiri
İnat ediyor', 'Bahçedeki vişne ağacı Çiçekten meyveye döndü Daktiloda bahar şiiri İnat ediyor...', ARRAY['Türk Edebiyatı','Şiir','Metin Demi̇rtaş']::text[], 8.5, '{"poet":"Metin Demi̇rtaş","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DALA TÜNEMİŞ DOĞAN', 'dala-tunemi-s-dogan-ted-hughes-97z3q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oturuyorum korunun tepesinde, gözlerim kapalı,
Hiçbir şey yapmadan, yalan dolu bir düş olmadan
Arasında kanca gagamla kancalı ayaklarımın.
Ya da kusursuz avların provasını yapıyorum uykumda.
Yüksek ağaçların sağladığı kolaylık!
Havanın taşıma gücü ve güneşin ışığı
Bana çalışıyor
Ve yüzü bana dönük, teftişimi bekliyor toprak.
Ayaklarım dalın pürüzlü kabuğuna kilitli.
Her bir tüyümü yapmak için, tek bir ayağımı
Tüm yaradılış süreci gerekti:
Şimdi ayaklarımın altında ne varsa yaratılmış,
Ya da havalanıp, döndürüyorum tümünü -
Nerede dilersem orada avlanıyorum, hepsi benim çünkü.
Aldatmaca yok benim gövdemde:
Baş kopartmak benim kibarlığım,
Ölüm dağıtmak,
Çünkü tek uçuş yolum
Yaşayanların kemiklerinden geçiyor.
Usa dayalı bir şey değil ileri sürdüğüm hak:
Güneş destekliyor beni.
Hiçbir şey değişmedi ben başlayalı.
Hiçbir değişikliğe izin vermedi gözüm.
Hep böyle tutacağım her şeyi.
Ted  HUGHES', 'Oturuyorum korunun tepesinde, gözlerim kapalı, Hiçbir şey yapmadan, yalan dolu bir düş olmadan Arasında kanca gagamla kancalı ayaklarımın. Y...', ARRAY['Türk Edebiyatı','Şiir','Ted  Hughes']::text[], 8.5, '{"poet":"Ted  Hughes","poet_slug":"ted_hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞLAR', 'daglar-sabahattin-ali-48h39', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başım dağ, saçlarım kardır,
Deli rüzgarlarım vardır,
Ovalar bana çok dardır,
Benim meskenim dağlardır.
Şehirler bana bir tuzak;
İnsan sohbetleri yasak;
Uzak olun benden, uzak,
Benim meskenim dağlardır.
Kalbime benzer taşları,
Heybetli öter kuşları,
Göğe yakındır başları;
Benim meskenim dağlardır.
Yarimi ellere verin;
Sevdamı yellere verin;
Yelleri bana gönderin;
Benim meskenim dağlardır.
Bir gün kadrim bilinirse,
İsmim ağza alınırsa,
Yerim soran bulunursa:
Benim meskenim dağlardır', 'Başım dağ, saçlarım kardır, Deli rüzgarlarım vardır, Ovalar bana çok dardır, Benim meskenim dağlardır. Şehirler bana bir tuzak; İnsan sohbet...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali̇']::text[], 8.5, '{"poet":"Sabahattin Ali̇","poet_slug":"sabahattin_ali","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞLARDA ŞARKI SÖYLE', 'daglarda-sarki-soyle-necip-fazil-kisakurek-haph2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Al eline bir değnek,
Tırman dağlara, söyle!
Şehir farksız olsun tek,
Mukavvadan bir köyle.
Uzasan, göğe ersen,
Cücesin şehirde sen;
Bir dev olmak istersen,
Dağlarda şarkı söyle!', 'Al eline bir değnek, Tırman dağlara, söyle! Şehir farksız olsun tek, Mukavvadan bir köyle. Uzasan, göğe ersen, Cücesin şehirde sen; Bir dev ...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAĞLARDA KAR OLSAYDIM', 'daglarda-kar-olsaydim-yusuf-hayaloglu-orprt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu dağlarda kar olsaydım...
Bir asi rüzgar olsaydım...
Arar bulur muydun beni,
Sahipsiz mezar olsaydım?
Şu yangında har olsaydım...
Ağlayıp bizar olsaydım...
Belki yaslanırdın bana,
Mahpusta duvar olsaydım...
Şu bozkırda han olsaydım,
Yıkık, perişan olsaydım...
Yine sever miydin beni,
Simsiyah duman olsaydım?
Şu yarada kan olsaydım,
Dökülüp ziyan olsaydım...
Bu dünyada yerim yokmuş,
Keşke bir yalan olsaydım!..', 'Şu dağlarda kar olsaydım... Bir asi rüzgar olsaydım... Arar bulur muydun beni, Sahipsiz mezar olsaydım? Şu yangında har olsaydım... Ağlayıp ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DALGACI MAHMUT', 'dalgaci-mahmut-orhan-veli-90bul', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşim gücüm budur benim,
Gökyüzünü boyarım her sabah,
Hepiniz uykudayken.
Uyanır bakarsınız ki mavi.
Deniz yırtılır kimi zaman,
Bilmezsiniz kim diker;
Ben dikerim.
Dalga geçerim kimi zaman da,
O da benim vazifem;
Bir baş düşünürüm başımda,
Bir mide düşünürüm midemde,
Bir ayak düşünürüm ayağımda,
Ne haltedeceğimi bilemem.', 'İşim gücüm budur benim, Gökyüzünü boyarım her sabah, Hepiniz uykudayken. Uyanır bakarsınız ki mavi. Deniz yırtılır kimi zaman, Bilmezsiniz k...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DALGIÇ', 'dalgic-sukran-kurdakul-sbx4a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendi denizlerimin dalgıcıyım ben
Bir alışkanlığı sürdürür gibiyim belki
Soluğum son aşamalarına geldi
Geçtim durdum bilincin dehlizlerinden.
Bahçeler mi yoktu, eski ve yeni
Şarkılar mı, anılara benzer
Gemiler mi yoktu, küsmüş yelkenleri
Gözümün önünde eriyip gittiler.
Bilirdim çizgen neresiydi, yol neresi
Dalardım mavilerin güneşle buluştuğu yerden
Hevesleri, coşkuları, sevinçleri
Ben yaratmışım gibi dökerdim içimden.
Ne varsa doğayla aradığım uyumda
Çiçeğe durmuş ağaçlar gibi iyimser...
Ve sesinin masalında sevdalı,
Bize özgü sözcükler getirdim koynumda.
Kendi denizlerimin dalgıcıyım beni
Bir alışkanlığı sürdürür gibiyim belki
Soluğum son aşamalarına geldi,
Gidiyorum içimdeki sesin peşinden.', 'Kendi denizlerimin dalgıcıyım ben Bir alışkanlığı sürdürür gibiyim belki Soluğum son aşamalarına geldi Geçtim durdum bilincin dehlizlerinden...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DALGIN VE ÖTESİZ', 'dalgin-ve-otesi-z-fernando-pessoa-fr6c9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgın ve ötesiz berisiz
Ve de tanımaksızın
Yüzüyorum ölü denizinde
Kendi varlığımın.
Suyu hissettiğimden
Hissediyorum sıkıntıyı...
Görüyorum seni, ey çalkantı,
Hayat-huzursuzluk...
Bana has yelkenler ki...
Çark etmiş dümeni...
İnsan sureti gibi soğuk
Yıldızlı bir gökyüzü.
Gökyüzüyüm ben, rüzgârım...
Gemiyim ve denizim...
Hissediyorum ki ben değilim...
Yadsımak isterim onu.
(Fragmanlar)
Fernando PESSOA', 'Dalgın ve ötesiz berisiz Ve de tanımaksızın Yüzüyorum ölü denizinde Kendi varlığımın. Suyu hissettiğimden Hissediyorum sıkıntıyı... Görüyoru...', ARRAY['Türk Edebiyatı','Şiir','Fernando Pessoa']::text[], 8.5, '{"poet":"Fernando Pessoa","poet_slug":"fernando_pessoa","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DALGINLIK', 'dalginlik-nahit-ulvi-akgun-awg2n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir pencere açıldı kitabımın sayfasında
El sallayarak sen göründün,
Satırlar takım takım evinin önünde
Ne güzel bu küçük askerler...
Fakat kayboluyorsun pencereden
Şimdi ağlıyor bütün harfler...
Sonra birden beliriyorsun
Elinde nakışlı mendilin, gülümsüyorsun
Ve başlıyorsun konuşmağa
Sesin ağlamaklı,
Sesin yumuşak,
Anlattıklarına karışıyor kitabın anlattıkları...', 'Bir pencere açıldı kitabımın sayfasında El sallayarak sen göründün, Satırlar takım takım evinin önünde Ne güzel bu küçük askerler... Fakat k...', ARRAY['Türk Edebiyatı','Şiir','Nahit Ulvi Akgün']::text[], 8.5, '{"poet":"Nahit Ulvi Akgün","poet_slug":"nahit_ulvi_akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İDAM', 'i-dam-yusuf-altunel-zx9mk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '"... Burdur Kapalı Cezaevinde asılmak suretiyle
idam edildiğinden cesedinin merasim yapılmaksızın
define musade edilmistir."
bir şair asılır
ölen kendi yurdumuz
sözcükler kurşun
düşman namludan dizeler
göğüs kafesime saplıdır
boynumda ilmekten can çekmeler
toprak olur, su olur
karışırız şiir gibi hayata
mısralar barikata durunca
havalanır ateşli iklimlerden imgeler
soğuk ülkelere dökülür
kar gibi, helva gibi usulca
idam mangası dizmişler avluya
şair yolcu bugün tan sökmeden
uğurladılar güvercinler parçalayıp maviyi
yolcu eder gibi baharı pencereden
dalının kırılmasıdır baharın
ilmek geçirmek boynuna ozanın
iklimlerinizde hüküm sürüyor ölümün soğuğu
indirin göklerden yıldızları ve yağmuru
bedenimi yaşama gömün merasim istemez
ateş yakın, şiir atın yangınlarıma, tutuşsun ozanları ülkemin
ki topraklarımda salınsın gelinler, şiirin fidanı boy versin', '"... Burdur Kapalı Cezaevinde asılmak suretiyle idam edildiğinden cesedinin merasim yapılmaksızın define musade edilmistir." bir şair asılır...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DANS EDELİM GEL', 'dans-edeli-m-gel-paul-verlaine-k5wpj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerini severdim en çok,
Gökteki yıldızlardan parlak;
Bir parça da baştan çıkarak.
Dans edelim gel!
Ne halleri vardı, sahiden,
Bedbaht âşığı berbat eden
Onun için hoştu ya zaten.
Dans edelim gel!
Doldurulmadı hâlâ yeri,
Gülden ağzının öpücükleri
Kalbimde öldüğünden beri.
Dans edelim gel!
Dizi dibinde oturduğum
Zamanları hatırlıyorum;
Bu, işte bütün varım yoğum.
Dans edelim gel!
Paul VERLAINE', 'Gözlerini severdim en çok, Gökteki yıldızlardan parlak; Bir parça da baştan çıkarak. Dans edelim gel! Ne halleri vardı, sahiden, Bedbaht âşı...', ARRAY['Türk Edebiyatı','Şiir','Paul Verlaine']::text[], 8.5, '{"poet":"Paul Verlaine","poet_slug":"paul_verlaine","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAR AÇI', 'dar-aci-arif-damar-kxckk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun saçlar yakışırdı sana uzun yıllar
Bir gökyüzü bitince öteki başlardı
Çevik taylar dururdu güneşte olgun başaklar
gölgelikler dururdu,
Ovalar aydınlıkta dururdu
Bulut geçti derdik bilemedin
Ya da yağmur yağacak derdik
Fesleğen saksıda güzel dururdu
Bak bu olacak şey mi kömür beni vurdu
Ayaklarım aldı başını gitti
Ellerim kaldı duvarda
Kalk ne olur pencereyi aç
Uzun saçlar yakışırdı sana uzun yıllar
Bir gökyüzü bitince öteki başlardı.', 'Uzun saçlar yakışırdı sana uzun yıllar Bir gökyüzü bitince öteki başlardı Çevik taylar dururdu güneşte olgun başaklar gölgelikler dururdu, O...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAR DÜNYA', 'dar-dunya-aziz-nesi-n-86qkg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüreğim gövdeme sığmıyor
Gövdem odama
Odam evime sığmıyor
Evim dünyaya
Dünyam evrene sığmıyor
Patlayacağım
Acımın acısından susmuşum
Ki suskunluğum göklere sığmıyor
Böyle bir acıyı kimlere nasıl anlatacağım
Gönül dar geliyor sevgime
Kafam beynime
Ah şakaklarım
Çatlayacağım
Anladım artık anladım
Kimselere anlatamayacağım', 'Yüreğim gövdeme sığmıyor Gövdem odama Odam evime sığmıyor Evim dünyaya Dünyam evrene sığmıyor Patlayacağım Acımın acısından susmuşum Ki susk...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAVET', 'davet-tali-p-apaydin-o8xcd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana lodos demişiz
Bize alıştığın gibi gel
Güneyden koku getir
Dolu dolu bulutların önünde
Es ince ince es ılık ılık
Bir sabah kalkınca
Karları erimiş bulalım
Kabarmış bulalım tarlaları
Buralara oturmuşuz
Sevdir bize
Selam getir
Güldür bizi', 'Sana lodos demişiz Bize alıştığın gibi gel Güneyden koku getir Dolu dolu bulutların önünde Es ince ince es ılık ılık Bir sabah kalkınca Karl...', ARRAY['Türk Edebiyatı','Şiir','Tali̇p Apaydin']::text[], 8.5, '{"poet":"Tali̇p Apaydin","poet_slug":"talip_apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAYANILMAZ', 'dayanilmaz-arif-damar-adi7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerini ölüm bürüdü onların
korkulu rüyalarda uyanıyorlar uykularından.
Günden güne daha cana yakın
günden güne daha yaşanacak hale gelsin diye
her gün daha sağlam
daha usta
daha kahraman ellerle onarılan yeryüzü
eskisinden dar geliyor onlara
eskisinden düşman.
Ne günün ilk ışığı
ne balık sürülerinin ışıldaması suda
ne güneşe uzanan dal
ferahlık vermiyor içlerine.
Çalınan insan emeği yaşatmaz oldu
korkulu rüyalarla uyanarak uykularından
korkunç kararlar verdiler.
Karşı koymazsak eğer
tehlikededir günlük ekmeğimiz
bacamızın tütmesi tehlikededir
evimiz, aşkımız, çocuğumuz
pencerede saksı
kitap sevgisi, insan sevgisi
tehlikededir.
Gözlerini ölüm bürüdü onların
uyumak, uyanmak tehlikededir,
tehlikededir çiçek koklamak
bardakta su, ateşte yemek
bahçede güneş tehlikededir.
Tehlikededir gözbebeklerimiz
Adana''nın pamuğunu yabancılar işliyor
dokuma tezgahları tehlikededir.
İzmir''in üzümü, fındığı Giresun''un
Samsun''un tütünü tehlikededir.
Kapanıyor fabrikalar birer birer
varımız yoğumuz tehlikededir.
Fakat korkunç kararlara ve tehlikelere aldırış etmeden
boy atan başakların şarkısı devam eder
topraktan güneşe avaz avaz.
Çatlayan tohumdaki yaşamak arzusu
her zaman galip, her zaman hür,
dağlardan akan suyun sevinci
her zaman genç, delikanlı
kabına sığmaz...
Dayanılmaz
çocuğunu emziren ananın şefkatine
-yırtıcı, derin-
hilelere, ölümlere karşı gelir
memedeki çocuğun iştahı,
kudreti sonsuz,
dayanılmaz.
Ve sen gözbebeğim
sen erkek sesinle
"İşsiz kalmasın insanlar, öldürmeyelim birbirimizi." dersin
milyonların içinden
milyonlardan ve gün ışığından uzağa götürülür,
işkence görür,
hapis yatar,
sürgün edilirsin;
sevilecek şeyler değilse de bunlar
DAYANILIR...
Halbuki günden güne yaşanacak hale gelen yeryüzünde
toprağın ve insanoğlunun ümitle yarattığı her şey
çatlayan tohum, akan su,
ana şefkati, çocuk iştahı, insan tahammülü,
hayatı öven şiir,
kardeşliği söyleyen şarkı,
mücadele eden resim,
ve emekçinin yüreği, elleri, hasreti
harbe ve ölüme karşıdır
DAYANILMAZ...', 'Gözlerini ölüm bürüdü onların korkulu rüyalarda uyanıyorlar uykularından. Günden güne daha cana yakın günden güne daha yaşanacak hale gelsin...', ARRAY['Türk Edebiyatı','Şiir','Arif  Damar']::text[], 8.5, '{"poet":"Arif  Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":72}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DAYIM GÜL TAKARDI GÖMLEĞİNİN YAKASINA', 'dayim-gul-takardi-gomlegi-ni-n-yakasina-ali-cengi-zkan-m057l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve canlıymışçasına, hergün onu sulardı.
Yağız tenindeki su buharlaşsın diye
Düğmeleri en bıçkın küfürlerle açardı:
Çiçekçiydi, yaprak bitlerini öldürmeyen.
Fotoğrafçı, savaş yıllarına rötuş yapan.
Meddahtı, her akşam eve gülücükle gelen.
Kumraldı, çocukları hep karısına çeken.
Uzun boylu, kendisine palto diktirmeyen.
Sebzeciydi, domatlarını hiç yemeyen.
İşadamı, hasırdan başka minder bilmeyen.
Dindardı, ezan okunurken rakı içmeyen.
Gözlüklüydü, gözleri daha da büyüyen.
Gezgin, İzmir''in parkelerini denetleyen.
Balıkçıydı, elleri suyla nasır tutan.
Nikotinman, sigarası bağlanarak uzayan.
Diplomattı, kokteyle pantolonla giden.
Yatırımcı, geceleri ailesini besleyen.
Dayım gül takardı gömleğinin yakasına
Seni görse, eminim, mutluluktan ağlardı.', 'Ve canlıymışçasına, hergün onu sulardı. Yağız tenindeki su buharlaşsın diye Düğmeleri en bıçkın küfürlerle açardı: Çiçekçiydi, yaprak bitler...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞCE', 'dusce-yasar-mi-rac-nrxqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'badem pencereli
kavun kapılı
nar kiremitli
balık bacalı
küçücük bir evde
yaz sıcağında
sıcacık bir yerde
kış soğuğunda
çiçecik bir evde
kırlar güzeli
esincek bir evde
eylül geceli
ufacık bir evde
gümüş gülüşlü
tefecik bir evde
erik bir evde
yaşamak yaşamak
yaşamak sen(in)le
isterdim ben de', 'badem pencereli kavun kapılı nar kiremitli balık bacalı küçücük bir evde yaz sıcağında sıcacık bir yerde kış soğuğunda çiçecik bir evde kırl...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Mi̇raç']::text[], 8.5, '{"poet":"Yaşar Mi̇raç","poet_slug":"yasar_mirac","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİDDET, ELBET', 'si-ddet-elbet-altay-oktem-q3mjl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bilgece susuyoruz artık saklamayalım
yıldızları tartaklanmış bir sonbahar gecesi
diz çökmüştük hatırla öteki dünyalara
dünyalar dediğim de ne, boşuna abartmayalım
karalarla denizler, çamurlar falan yani
toplasan hepsi hepsi batan bir geminin
sessiz, kıpırtısız can yelekleri
söze nasıl başlamalı basbayağı kan akıyor
ağzımı açtığımda düşlerimden içeri
bilgece susuyoruz çünkü susmak gecesi
patikada kaybolan o yaşsız çocukların
bir bildiği var elbet boşuna kaldırmazlar
coğrafya derslerinde küçük parmaklarını
ıslık çalmazlar, kuş vurmazlar, ağlamazlar boşuna
şiddet diyorsun ne güzel; şiddet, elbet
yoksa yalnız bir ardıcın dalları kırılır
çok ölünür daha, çok kaybolunur
biçimsiz bir kanamadır ah! hayat, anlamsız toprak
hiç kımıldamamış yaprak
bilgece susuyoruz artık saklamayalım
şiddet diyorsun ne güzel; şiddet, elbet
elbet, şiddet
elbet.', 'bilgece susuyoruz artık saklamayalım yıldızları tartaklanmış bir sonbahar gecesi diz çökmüştük hatırla öteki dünyalara dünyalar dediğim de n...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay_oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEDİKODU', 'dedi-kodu-halit-fahri-ozansoy-8qzlg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman bir böcek gibi sinsi, kenarda
Koltukların didikler durur kadifesini,
Hain bir kedi gözü parıldar lambalarda.
Şom ağızlar buz gibi üflerken nefesini,
Bir beddua halinde uzatarak sesini
Saat hırıltılarla can çekişir duvarda.', 'Zaman bir böcek gibi sinsi, kenarda Koltukların didikler durur kadifesini, Hain bir kedi gözü parıldar lambalarda. Şom ağızlar buz gibi üfle...', ARRAY['Türk Edebiyatı','Şiir','Halit Fahri Ozansoy']::text[], 8.5, '{"poet":"Halit Fahri Ozansoy","poet_slug":"halit_fahri_ozansoy","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEDİM', 'dedi-m-kutsiye-bozoklar-jrr8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir dediler;
emektir dedim
Sevda dediler;
bilmektir dedim
İnsan dediler;
sevmektir dedim.
Kavga dediler;
ilmektir dedim
İnanç dediler;
-Uğruna usulca-
ölmektir dedim
Ya tümü dediler;
doyasıya YAŞADIM
Diyebilmektir dedim', 'Şiir dediler; emektir dedim Sevda dediler; bilmektir dedim İnsan dediler; sevmektir dedim. Kavga dediler; ilmektir dedim İnanç dediler; -Uğr...', ARRAY['Türk Edebiyatı','Şiir','Kutsiye Bozoklar']::text[], 8.5, '{"poet":"Kutsiye Bozoklar","poet_slug":"kutsiye_bozoklar","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEĞİŞEN', 'degi-sen-hamdi-ozyurt-0m0jb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen bana daha az acır
beni daha çok severdin eskiden
yıldız düşerdi
öpüştüğümüz taraçaya
yavru ağzı bir sızı
bırakırdı dişlerin
adını bilmediğim
bir çiçeğe benzerdin
hani sularda açan
uğruna ölünesi
akşam akşam ay tozuna
bulanırdı ellerin
çarpıntı kuşlarıydı
göğsünde biryerlerin
bulutlar ertelese yağmurlarını
safi karanfil kokardı geceler
bir gözün sevinçten ağlardı
bir gözün üzünçten
hüznünde kol kola
mandolinli öğrenciler
şimdi en sevdiğim tablo
duvara dönük
meğer yanarken yürürmüş orman
meğer unutkan bir kıvılcım kalırmış
talan hızıyla geçen günlerden
sen bana daha az acır
beni daha çok severdin eskiden', 'sen bana daha az acır beni daha çok severdin eskiden yıldız düşerdi öpüştüğümüz taraçaya yavru ağzı bir sızı bırakırdı dişlerin adını bilmed...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Özyurt']::text[], 8.5, '{"poet":"Hamdi Özyurt","poet_slug":"hamdi_ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEFNE ORMANI', 'defne-ormani-melih-cevdet-anday-us4pn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köle sahipleri ekmek kaygusu çekmedikleri
için felsefe yapıyorlardı, çünkü
Ekmeklerini köleler veriyordu onlara;
Köleler ekmek kaygusu çekmedikleri için
Felsefe yapmıyorlardı, çünkü ekmeklerini
Köle sahipleri veriyordu onlara.
Ve yıkıldı gitti Likya.
Köleler felsefe kaygusu çekmedikleri
İçin ekmek yapıyorlardı, çünkü
Felsefelerini köle sahipleri veriyordu onlara;
Felsefe sahipleri köle kaygusu çekmedikleri
İçin ekmek yapmıyorlardı, çünkü kölelerini
Felsefe veriyordu onlara.
Ve yıkıldı gitti Likya.
Felsefenin ekmeği yoktu, ekmeğin
Felsefesi. Ve sahipsiz felsefenin
Ekmeğini, sahipsiz ekmeğin felsefesi yedi.
Ekmeğin sahipsiz felsefesini
Felsefenin sahipsiz ekmeği.
Ve yıkıldı gitti Likya.
Hala yeşil bir defne ormanı altında.', 'Köle sahipleri ekmek kaygusu çekmedikleri için felsefe yapıyorlardı, çünkü Ekmeklerini köleler veriyordu onlara; Köleler ekmek kaygusu çekme...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEFNELER ÖLMEZ', 'defneler-olmez-rifat-ilgaz-lkebc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir mevsim var ki üşütür yeşilliğimi
Ben geceyle gündüzü bilirim yılları değil.
Ölümsüzlüğü getirdim kıyılarınıza
Düşlerimde hep uzak denizler... Kıyılar...
Gidemem, bağlıyım toprağıma.
Dalımla yaprağımla, ben
Bir savaş simgesiyim oysa
İnsan kardeşlerimin gözünde!
Utkular düşleyen başlar için
Bir çelenk!
Savaşlar, soykırımlar gördük,
İskenderler, Sezarlar,
Ne atlar kaldı onlardan, ne meydanlar...
Gittiler, yıkılıp birer birer,
Biz kaldık.
En kıraç topraklarda tutunduk,
Biz defneler.
Dal kırılır, yaprak dökülür
Ölür mü acılara katlanmasını bilenler,
Direnenler tüm kırımlara karşı...
Ölmez sevgiden yana olanlar
Defneler ölmez!
(Cide, 1978)
Kulağımız Kirişte  adlı şiir kitabından 1983
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Bir mevsim var ki üşütür yeşilliğimi Ben geceyle gündüzü bilirim yılları değil. Ölümsüzlüğü getirdim kıyılarınıza Düşlerimde hep uzak denizl...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEĞİŞİK', 'degi-si-k-can-yucel-vy83f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başka türlü birşey benim istediğim,
Ne ağaca benzer ne de buluta benzer;
Burası gibi değil gideceğim memleket,
Denizi ayrı deniz, havası ayrı hava;
Nerde gördüklerim, nerde o beklediğim kız
Rengi başka, tadı başka.', 'Başka türlü birşey benim istediğim, Ne ağaca benzer ne de buluta benzer; Burası gibi değil gideceğim memleket, Denizi ayrı deniz, havası ayr...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DELİ ŞARKISI', 'deli-sarkisi-mile-verhaeren-cqm67', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gördüm, onları, gördüm,
Çatlak gözleri vardı
Kenevir sakalları
Geçtiler patikadan.
Çerden çöpten iki kol
Bir sırt kurumuş ottan.
Yaralı, delik-deşik, mafsalları ayrılmış
Savaştan çıkmış gibi
Geldiler uzaklardan.
Kulaklar üstünde yamrı-yumru bir şapka,
Bir de yeşil elbise kuzukulağı gibi;
İkiydi, üç oldular, gördüm on tanesinin
Dönüşünü ormandan.
Canımı alıverdi içlerinden birisi
Ve şimdi benim canım tıpkı bir çan gibidir
Onun cebinde çalan.
Derimi alıverdi derken başka bir adam
-Kimseye duyurmayın-
Farkı yoktur derimin
Pörsümüş bir davuldan.
Bu kaskatı toprağa
İplerle bağladılar beni ayaklarımdan;
Bana bakın, bana bakın
Kelimeyim artık ben.
Bir köylüdür bizleri çıplak toprağa çakan,
Çıktı geldi habersiz.
Onların hepsi ve ben, eski elbiseleriz
Alaya aldıkları küçücük çocukların,
İri kargalarla kuzgunları bekleyen.
Émile VERHAEREN', 'Gördüm, onları, gördüm, Çatlak gözleri vardı Kenevir sakalları Geçtiler patikadan. Çerden çöpten iki kol Bir sırt kurumuş ottan. Yaralı, del...', ARRAY['Türk Edebiyatı','Şiir','Émile Verhaeren']::text[], 8.5, '{"poet":"Émile Verhaeren","poet_slug":"emile_verhaeren","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DELİ KIZIN TÜRKÜSÜ', 'deli-kizin-turkusu-gulten-akin-b35m1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'III
Sana büyük caddelerin birinde rastlasam
Elimi uzatsam tutsam götürsem
Gözlerine baksam gözlerine konuşmasak
Anlasan
Elimi uzatsam tutamasam
Olanca sevgimi yalnızlığımı
Düşünsem hayır düşünmesem
Senin hiç haberin olmasa
Senin hiç haberin olmaz ki
Başlar biter kendi kendine o türkü
Yağmur yağar akasyalar ıslanır
Bulutlar uçuşur geceleyin
Ben yağmura deli buluta deli
Bir büyük oyun yaşamak dediğin
Beni ya sevmeli ya öldürmeli
Yitirmeli büyük yolların birinde ne varsa
Böcekler gibi başlamalı yeniden
Bu Allahsız bu yağmur işlemez karanlıkta
Yan garipliğine yürek yan
Gitti giden', 'III Sana büyük caddelerin birinde rastlasam Elimi uzatsam tutsam götürsem Gözlerine baksam gözlerine konuşmasak Anlasan Elimi uzatsam tutama...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DELİKLİ ŞİİR', 'deli-kli-si-i-r-orhan-veli-kanik-fxm3c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cep delik, cepken delik,
Kol delik, mintan delik,
Yen delik, kaftan delik,
Kevgir misin be kardeşlik !', 'Cep delik, cepken delik, Kol delik, mintan delik, Yen delik, kaftan delik, Kevgir misin be kardeşlik !...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanik']::text[], 8.5, '{"poet":"Orhan Veli Kanik","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DELİLİĞE ÖZLEM', 'deli-li-ge-ozlem-umit-sener-ta-iho2k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uzaklık kırılma birbirini tanımlamıyor mu?
hangi geçmişe sığınıyoruz hangi dünde harcıyoruz şimdileri
delileri seyrediyorum gözlerinde yalnızlığa özlem
belki gözlerindeki yalnızlığı özledim
yaprağın gözlerini bağladım
rüzgara bıraktım tenimi
kentleri gördüm her gezginin bağrında kırılan
savruldum bir avuçtan bir avuca
nasırlar bıraktım bana dokunana
gezme gönül savrulma yapraklar gibi
deliliği mi özledin', 'uzaklık kırılma birbirini tanımlamıyor mu? hangi geçmişe sığınıyoruz hangi dünde harcıyoruz şimdileri delileri seyrediyorum gözlerinde yalnı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Şener Ta']::text[], 8.5, '{"poet":"Ümit Şener Ta","poet_slug":"umit_sener_ta","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DELİLER', 'deli-ler-mustak-erenus-zetb8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gök var üstümüzde
Yıldızlar bir ipte dizi
Bizi gözetleyen varsa yukarda
Neyimiz var ki gizli
İşte insanlar sokaklarda
Kimimiz aç, kimimiz dertli
Gülenlerimiz varsa meydanlarda
Deli', 'Bir gök var üstümüzde Yıldızlar bir ipte dizi Bizi gözetleyen varsa yukarda Neyimiz var ki gizli İşte insanlar sokaklarda Kimimiz aç, kimimi...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜELLO', 'duello-ozdemir-asaf-tsrk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her tomurcuk bir çiçeğin uykusuna,
Her çiçek bir yemişin kuşkusuna,
Her yemiş bir böceğin korkusuna,
Uykusuzca, kuşkusuzca, korkusuzca yürür.', 'Her tomurcuk bir çiçeğin uykusuna, Her çiçek bir yemişin kuşkusuna, Her yemiş bir böceğin korkusuna, Uykusuzca, kuşkusuzca, korkusuzca yürür...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir_asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DELTA', 'delta-i-lhan-berk-noacp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'deltaya indiler o eskiden saçları uzayan kadınlar
kelt uzun egemenlikleri kuzeyuç egemenlikleri / uygarlık
tecim gerisinde ve kayser gerisinde o denizlere,  lu   devletinden
bayan wen-ciang''ın güzel uzaklığının mercurus göğüne/o benim
dediğim
göğün sarayı çarşılara///en çok oralara, yahudiyeye xo kuşların
çizili   uçtuğu göğe, kuzeyuca/ çok geçmeden  de   bizim buralara
döndüler
bizim buralarda bir yağmur bırakırdım   //  o bir deniz gibi
duran şimdi bizim kayserimiz minos''a,
iyi dedim dışardaki gökyüzü/
ay arabası/
sonra büyük kargaşalıklar çıktı
,
durmuş denizi ölçmüştük
ve hâlâ oralarda adım güzeldi / durmadan bir ilkçağ göğünü
ararlardı / annemin resimleri yalnızlığına ve sessizliğine varırdı
ve oradaydım ben  bunluk günlerim sabahlara kadar   beyaz
sabahlara kadar ben
kelt''in güneyinde büyük bir deniz vardır
oturdum uzun uzun yukarı baktım
Mısırkalyoniğne', 'deltaya indiler o eskiden saçları uzayan kadınlar kelt uzun egemenlikleri kuzeyuç egemenlikleri / uygarlık tecim gerisinde ve kayser gerisin...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEĞİŞİM', 'degi-si-m-afsar-ti-muci-n-p7z76', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnanç beyler çarmıha gerilmeyi bilene
Çocuk ders çalışıyor görünüşte
Sayfaları yavaş yavaş çeviriyor
Çocuk deniz çalışıyor gerçekte
Gözlerini ufuklara dikiyor
Durup durup adını anıyor
Aşkın sözlüğünü ezberlemekte
Bütün nöbetçilerle yarışıyor
Gözleriyle gelişini beklemekte
Biz şimdi aşk öğrenelim
İnsan dersi sonra da öğreniyor
Yüzyıllık kitaplarda bilgi kendi malımız
Haritadan şehirler kaçmıyor ya
Sevinmek yaşarlığa dokunmaktır
Atlı gibi dört nala içimizden gidiyor
Bazan her şey yanılmaksa bile
Sevişmek gene en az yanılmaktır', 'İnanç beyler çarmıha gerilmeyi bilene Çocuk ders çalışıyor görünüşte Sayfaları yavaş yavaş çeviriyor Çocuk deniz çalışıyor gerçekte Gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖDEŞME', 'odesme-hulya-deniz-unal-efr71', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"Bütün tepelerin üstü sessizdir"
Goethe
O şehir, kabuk tutmayan yara
Serumlar yetmedi damardan sokaklara
Gidemem oraya artık gidemem
İlkin veresiye ardından peşin
Önce azar azar sonra yüklüce
İlçe aldım il ödedim
Herkes gitti dağına ben gitmedim
Duydum ama görmedim yüksekliğini
Sularıyla meşhurmuş, ben boğulurken
Duyumsadım buzlu olduğunu
Tepe aldım dağ ödedim
Şehir ve kin arasındaki sözleşme
Ne kadar yakın şu dev gibi sözlükte
Benim atlasımda kıtalar kadar
Fersah fersah koşuyor atlar, çünkü ben
Milim aldım kilometre ödedim
Usulca esiyordu ılıklığına durdum
Dalgalandı saçlarım hafif bir çarpma
Oradan yayıldı katmanlarıma
Elektriği, sandalyeyi farkettiğimde geçti
Yel aldım kasırga ödedim
Ağaçları biliyor camileri, türbeleri
Bir türküydü söyledimdi hepsine
Zorlanarak çıktımdı yokuşlarını
Maskesizdim evet, biliyor kuşlar
İlle de çınarlar, dürüstler çünkü
Yaprak aldım dal ödedim
En büyük Lokman zaman, senelere yatırdım
Kara üzüm gibi çekirdeksiz yarayı
Ne hava ne ışık ne de güneşe açtım
Şarap gibi bekletip mahzenimde sözledim
Bir dize aldım da şiir ödedim', '"Bütün tepelerin üstü sessizdir" Goethe O şehir, kabuk tutmayan yara Serumlar yetmedi damardan sokaklara Gidemem oraya artık gidemem İlkin v...', ARRAY['Türk Edebiyatı','Şiir','Hülya Deniz Ünal']::text[], 8.5, '{"poet":"Hülya Deniz Ünal","poet_slug":"hulya_deniz_unal","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEMETEVLER PARKINDA EYLÜL I', 'demetevler-parkinda-eylul-i-zerrin-taspinar-ie3bv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman öğleye yakın
geç uyananların boş saatleri
okul tatilleri, işsizlikler
çabucak işportaya düşmüş
mevsim başının gözde giysileri
- bütün göstergeleriyle tüketen bir toplumun -
geçiyoruz asfaltı.
Ardımda
hüznü yürek atışlarında taşıyan bir kız
buzu parçalayan tomurcuğun gülüşü
sanki bir geyikten bugüne kalan.', 'Zaman öğleye yakın geç uyananların boş saatleri okul tatilleri, işsizlikler çabucak işportaya düşmüş mevsim başının gözde giysileri - bütün ...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Taşpinar']::text[], 8.5, '{"poet":"Zerrin Taşpinar","poet_slug":"zerrin_taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEMETEVLER PARKINDA EYLÜL II', 'demetevler-parkinda-eylul-ii-zerrin-taspinar-6g3e7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son kırlangıçlar da bırakacak bu kenti
oluk oluk akacak can sıkıntısı, yaşlılıklar
yazı sırtında duymaktan yorgun
bankları ve renkli çubuklarıyla solacak
Demetevler Parkı.
Sarsak ve beceriksiz adımlarım
utanır gibi kadınlığından
- sahi neden tek başına yürürken biz
hafifçe çatıp kaşlarımızı
yere bakarız ki...', 'Son kırlangıçlar da bırakacak bu kenti oluk oluk akacak can sıkıntısı, yaşlılıklar yazı sırtında duymaktan yorgun bankları ve renkli çubukla...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Taşpinar']::text[], 8.5, '{"poet":"Zerrin Taşpinar","poet_slug":"zerrin_taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEMETEVLER PARKINDA EYLÜL III', 'demetevler-parkinda-eylul-iii-zerrin-taspinar-3jmeh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman öğleye yakın
evlerde şimdi mutfak sesleri.
Sırtımı çevirip onaltı katlı kondulara
parkın mavi havuzunda biraz
aldatmak istiyorum gözlerimi.
Bankta üç adam
buruyorlar kalın kara bıyıklarını
yitip gidiyor hevesim...
Neleri alıp götürmedi ki sular...
Nasıl hoyrat bir sevgiyle bozuldu Marmara
nasıl da eksildim
yine de ölmedi tenimin altında
gümüş pullu balıklar.', 'Zaman öğleye yakın evlerde şimdi mutfak sesleri. Sırtımı çevirip onaltı katlı kondulara parkın mavi havuzunda biraz aldatmak istiyorum gözle...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Taşpinar']::text[], 8.5, '{"poet":"Zerrin Taşpinar","poet_slug":"zerrin_taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEMETEVLER PARKINDA EYLÜL IV', 'demetevler-parkinda-eylul-iv-zerrin-taspinar-z4z9f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zaman öğleye yakın
binlerce yıllık tarihinde insanlığın
bir ömür nedir ki?
Bir damla su
parkta bir kırmızı çiçek belki.
Her mevsim biter
her eylül... geldiği gibi...', 'Zaman öğleye yakın binlerce yıllık tarihinde insanlığın bir ömür nedir ki? Bir damla su parkta bir kırmızı çiçek belki. Her mevsim biter her...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Taşpinar']::text[], 8.5, '{"poet":"Zerrin Taşpinar","poet_slug":"zerrin_taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENGE DURUMU', 'denge-durumu-erik-stinus-rokrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızca üç gün üç gece aç kalana ne mutlu.
Döşeme tahtaları, üşüyen ve aç insanların
ateşiyle kararmış,
mutfaksız ve ıssız,
ama gün doğarken kadınlar ve koyunların,
hüzünlü nöbetçiler ve kuzgunların
buluştukları bir kuyu olduğu için avluda
ve çekip gitmediği için umut,
oturulabilir durumdaki bir otelde
bir kez gözaltına alınmış.
ve cezanın daha uzun süreceğini sanmalarına karşın
yalnızca iki kez
bir hücreye kapatılmış olanlara ne mutlu.
Asker, çeteci ya da ermiş
olmasalar bile,
ölüm tehlikesi içinde yaşayıp
nedensiz korku duymayanlara ne mutlu.
Trenlerin durduğu
köyleri ve kentleri,
mis kokulu gölgeler ve takımyıldızlar gibi
gemileri kendine çeken limanları,
gerçekte ve düşlerde
üzerinden uçtuğu adaları
anımsadığı halde,
bütün dilleri öğrenip
bilineni yeniden bulgulayanlara ne mutlu.
İlk yolculuğun vardığı yerleri,
bütün o dost çehreleri
ve ezgiler dolu o mektupları
uzun zaman anımsayıp
çok seyrek sonuç verse bile,
her sözcüğü birbirine uyan
beklenmedik anlarda doğuvermiş şarkılardan
bir dörtlüğü, bir dizeyi, bir titremi
yakalamak için ter döken,
geriye dönebilmiş yolculara ne mutlu.
diktiği ağacın yetiştiğini,
ekinin harmana dönüştüğünü
görenlere ne mutlu.
Uzak bir yolda
birden dönüşünü şaşıran,
bir son durakta
uzaklardan haber soran
bir başka yolcuyla karşılaşmış yolcuya ne mutlu.
Erik STINUS', 'Yalnızca üç gün üç gece aç kalana ne mutlu. Döşeme tahtaları, üşüyen ve aç insanların ateşiyle kararmış, mutfaksız ve ıssız, ama gün doğarke...', ARRAY['Türk Edebiyatı','Şiir','Erik Stinus']::text[], 8.5, '{"poet":"Erik Stinus","poet_slug":"erik_stinus","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENGE', 'denge-a-nm2ta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bizlerden dışarı gidemiyor vahşet
kan-tetik ilişkisi: İntikam
ne canlar saklar âh umulmadık efkâr
meydanlarda kovulan replikler arka sokak
resmi tarihle işgüzarlık eskiyen suretlerde
ey nöbetçi: geceyi tutanağa geçir
eskidik
biz
linçlerle tazelenir zifiri karanlık
unuttun mu çılgın çocuk, kalıcıdır bu hile şarkta
deliler
kalemlerini koltuklarında saklarlar', 'bizlerden dışarı gidemiyor vahşet kan-tetik ilişkisi: İntikam ne canlar saklar âh umulmadık efkâr meydanlarda kovulan replikler arka sokak r...', ARRAY['Türk Edebiyatı','Şiir','A']::text[], 8.5, '{"poet":"A","poet_slug":"halil_ibrahim_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖDENMEZ', 'odenmez-hidayet-karakus-f2n0e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ışığın şafağa verdiğini
verdin bana
dağları gök sınırlarında
sıyıran rüzgârların
ay ışıltısından kalan
yerlerini verdin
keseklerden seken tarla kuşlarını
suyun sesine koştuğunda
gün aydındı
uyanmamıştı kalbin toprağı
geniş ovalar
uçsuz bucaksız sıfatlarla
kendini tamlayan
bozkırlar verdin bana
bir gün dönersin dedin
bir gün dönersin
o günün adresini kestin yıldızlardan
gittiğim yerlerin
haritalarda
hasretten kanayan şehirlerin
yıkılmış yaşamlarından kalan
kitaplarını verdin bana
herkes unuttu beni
mevsimler defter tutmaz
yolların belleği karışık
uzun kışlardan sonra
uyanan aşkın yorgun aylarını verdin
nasıl sağaltır seni eğninde taşıyan
demir asa demir çarık
çöllerde donmaktan
dağlarda kurumaktan gelen ses
nereye gider
kırılgan bir yaşamın dağdağasında
fırçanın resme verdiğini
elin başağa
soluğun yüreğe verdiğini
verdin bana', 'ışığın şafağa verdiğini verdin bana dağları gök sınırlarında sıyıran rüzgârların ay ışıltısından kalan yerlerini verdin keseklerden seken ta...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Karakuş']::text[], 8.5, '{"poet":"Hidayet Karakuş","poet_slug":"hidayet_karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZİ ANLATIYOR', 'deni-zi-anlatiyor-turgut-uyar-f87so', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'adı çok duyulmuş bir ozan değildi
Tonyalı balıkçılar arasında
-onlar ki her türlü balığı tutarlardı denizden-
ama iyi bir ozandı
bütün söylentilerin tersine
denizde de olabilirdi sandalla
uzun geçmişli denizle
gün batımında var olan
ve gün doğumunda da', 'adı çok duyulmuş bir ozan değildi Tonyalı balıkçılar arasında -onlar ki her türlü balığı tutarlardı denizden- ama iyi bir ozandı bütün söyle...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '''DENİZ'' DEDİK ÖPÜP BAŞIMIZA KODUK TUZU EKMEĞİ', 'deni-z-dedi-k-opup-basimiza-koduk-tuzu-ekmegi-mehmet-basaran-ev4xp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlk günlerindeki gibi Troya''nın
Usulca dokundu mor yamaçlarına
Gül parmaklı şafak İda''nın
Işıdı sonyaz''ın gergin karnı
Kuytularda ince bir rüzgar
Okşadı küçük mavi çiçeklerini sevdanın
Sürüp gidiyordu yaşamın gelgiti
Sürüp gidiyordu doğumlar ölümler
Ardından ölümcül sancıların
Sese dönüştü titreyen çiyler
Baktım gözlerin söylence rengi
Neydi o yumuk avuçlarında
Bir giz gibi sımsıkı tuttuğun şey
Görünce dünyamızı neden ağladın
Söğütler yaprak döktü sular ürperdi
İlk günlerindeki gibi Troya''nın
Hangi korkularla kim demiş
Bir kız doğunca dört duvar sızlar diye
Sızlamadı genişledi duvarlar
Tanelenen başakla geçmişten geleceğe
Bakır taslarla içildi şerbetin
Itırlar defnelerle ilk çeyizin kondu sandığa
Nişanlandın yaşama beşik kertmesi
Onarmış gibi duvarlarını kentin
Dayanıklı olsun diye tüm acılara
Tuzladık kaya tuzuyla bedenini
Yuduk kırk bir çeşit ot katılmış sularla
Ve güllerin ve dikenlerin ve kırların acemisi
Kesilmesin diye dar geçitlerde soluğun
En mavi sözcüklerle seslendik sana
''Deniz'' dedik öpüp başımıza koduk tuzu ekmeği', 'İlk günlerindeki gibi Troya''nın Usulca dokundu mor yamaçlarına Gül parmaklı şafak İda''nın Işıdı sonyaz''ın gergin karnı Kuytularda ince bir r...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ HASRETİ', 'deni-z-hasreti-omer-bedretti-n-usakli-qj8e8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözümde bir damla su deniz olup taşıyor,
Çöllerde kalmış gibi yanıyor, yanıyorum.
Bütün gemicilerin ruhu bende yaşıyor;
Başımdaki gökleri bir deniz sanıyorum.
Nasıl yaşıyacağım ey deniz, senden uzak?...
Yanıp sönüyor gibi gözlerimde fenerin!...
Uyuyor mu limanda her gece sallanarak,
Altundan çivilerle çakılmış gemilerin?...
Sevmiyorum suyunda yıkanmamış rüzgârı;
Dalgaların gözümde tütüyor mavi, yeşil...
İçimi güldürmüyor sensiz ay ışıkları;
Ufkundan yükselmiyen güneşler güneş değil!
Bir gün nehirler gibi çağlıyarak derinden
Dağlardan, ormanlardan sana akacak mıyım?
Ey deniz, şöyle bir gün sana bakacak mıyım,
Elma bahçelerinden, fındık bahçelerinden?..', 'Gözümde bir damla su deniz olup taşıyor, Çöllerde kalmış gibi yanıyor, yanıyorum. Bütün gemicilerin ruhu bende yaşıyor; Başımdaki gökleri bi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedretti̇n Uşakli']::text[], 8.5, '{"poet":"Ömer Bedretti̇n Uşakli","poet_slug":"omer_bedrettin_usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ KABUKLARI', 'deni-z-kabuklari-wolfgang-borchert-8uc2p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz kabukları, renkli, parlak;
çocukların bulduğu.
Deniz kabukları, ince, yuvarlak;
içlerinde rüzgârın uğultusu.
Türkü söyler yüce deniz içlerinde-
görülür müzelerde ışıldadıkları;
sonra eski liman meyhanelerinde,
sonra çocuk odaları...
Deniz kabukları, ince, yuvarlak;
dinle! rüzgârın türküsü duyduğun!
Deniz kabukları, renkli, parlak;
Bir zamanlar çocuklukta bulduğun!
Wolfgang  BORCHERT', 'Deniz kabukları, renkli, parlak; çocukların bulduğu. Deniz kabukları, ince, yuvarlak; içlerinde rüzgârın uğultusu. Türkü söyler yüce deniz i...', ARRAY['Türk Edebiyatı','Şiir','Wolfgang  Borchert']::text[], 8.5, '{"poet":"Wolfgang  Borchert","poet_slug":"wolfgang_borchert","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ KİTABI', 'deni-z-ki-tabi-i-lhan-berk-p39ck', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'VI
Doğabilim
Bitkileri öğreniyorum. Otları, çiçekleri
Bir taflanı alıyorum. Taflan bu diyorum.
Başlıyorum incelemeye tutup iki ucundan.
Bir pelin yaprağını koparıyorum sonra
Özsuyu çıkıyor elime. Bir dalı kanırtıyorum
Yininden. Uzun, incecik bir söğüt dalını
Damarlarını sayıyorum, bir suya bırakıyorum
Dünyanın en güzel yeşili o zaman anlıyorum.
Böyle bütün gün dolaşıp duruyorum
Sonra birden kâğıda kaleme sarılıyorum.
Atlas', 'VI Doğabilim Bitkileri öğreniyorum. Otları, çiçekleri Bir taflanı alıyorum. Taflan bu diyorum. Başlıyorum incelemeye tutup iki ucundan. Bir ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ ORAKÇISI', 'deni-z-orakcisi-kemal-ozer-3ktj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sor kendine bir sabah,
av hazırlığına başlarken;
sulara kim salar ilk güneşi
sen kayığına binmesen,
orağını almasan eline
ilk ürünü kim biçer denizden?
Kent niye bir büyük gergeftir,
geçirmiş ilmiğini alın terine?
Niye aç ağızlardan örülü
bir martı çığlığıdır gök;
iner kalkar başının üzerinde,
küçük dalışlarla yoklar tekneni?
Bir başınasın yaşamı üretirken
zıpkın çizer, kürek acıtır, ağ yorar.
neden elleri bulunmaz elinin yanında,
yorgunluğu neden paylaşmazlar
sofrasına çökerken yeryüzünün,
sor kendine bir sabah.', 'Sor kendine bir sabah, av hazırlığına başlarken; sulara kim salar ilk güneşi sen kayığına binmesen, orağını almasan eline ilk ürünü kim biçe...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ SARHOŞLARI', 'deni-z-sarhoslari-omer-bedretti-n-usakli-tesx6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köpükten omuzları birbirine dayanmış,
Yüksek, mağrur başları akşam rengiyle yanmış,
Sahile koşuyorlar bak deniz sarhoşları!...
Bazen yırtık yelkenli bir sandala çarparak,
Bazen ufkun kıpkızıl şarabına taparak
Gitgide coşuyorlar bak deniz sarhoşları!...
Rüzgârların ıslığı en yakın yoldaşları...
Yıllarca dövünerek içi yenmiş taşları
Bir anda parçalayıp doyacak bu sarhoşlar!...
Çılgın gönüllerinde aşkın en büyük kini,
Yosunlu kayaların o yeşil gözlerini
Deli âşıklar gibi oyacak bu sarhoşlar!...', 'Köpükten omuzları birbirine dayanmış, Yüksek, mağrur başları akşam rengiyle yanmış, Sahile koşuyorlar bak deniz sarhoşları!... Bazen yırtık ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedretti̇n Uşakli']::text[], 8.5, '{"poet":"Ömer Bedretti̇n Uşakli","poet_slug":"omer_bedrettin_usakli","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ TÜRKÜSÜ', 'deni-z-turkusu-yahya-kemal-beyatli-6b9ps', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolu rüzgârla çıkıp ufka giden yelkenli!
Gidişin seçtiğin akşam saatinden belli.
Ömrünün geçtiği sahilden uzaklaştıkça
Ve hayâlinde doğan âleme yaklaştıkça,
Dalga kıvrımları ardında büyür tenhâlık
Başka bir çerçevedir, git gide dünyâ artık.
Daldığın mihveri, gittikçe, sarar başka ziyâ;
Mâvidir her taraf, üstün gece, altın deryâ...
Yol da benzer hem uzun, hem de güzel bir masala
O saatler ki geçer başbaşa yıldızlarla.
Lâkin az sonra lezîz uyku bir encâma varır;
Hilkatin gördüğü rü''yâ biter, etrâf ağarır.
Som gümüşten sular üstünde, giderken ileri
Tâ uzaklarda şafak bir bir açar perdeleri...
Mûsıkîsiyle bir âlem kesilir çalkantı;
Ve nihâyet görünür gök ve deniz saltanatı.
Girdiğin aynada, geçmiş gibi dîğer küreye,
Sorma bir sâniye, şüpheyle, sakın: "Yol nereye?"
Ayılıp neş''eni yükseltici sarhoşluktan,
Yılma korkunç uçurum zannedilen boşluktan
Duy tabîatte biraz sen de ilâh olduğunu,
Rûh erer varlığının zevkine duymakla bunu.
Çıktığın yolda, bugün, yelken açık, yapyalnız,
Gözlerin arkaya çevrilmeyerek, pervâsız,
Yürü! Hür mâviliğin bittiği son hadde kadar!...
İnsan, âlemde hayâl ettiği müddetçe yaşar.', 'Dolu rüzgârla çıkıp ufka giden yelkenli! Gidişin seçtiğin akşam saatinden belli. Ömrünün geçtiği sahilden uzaklaştıkça Ve hayâlinde doğan âl...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZ', 'deni-z-alain-bosquet-5p2i4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deniz mavi bir balık yazıyor,
siliyor gri bir balığı.
Deniz alev alan bir kruvazör yazıyor,
siliyor kötü yazılmış bir kruvazörü.
Şairlerden daha şair
müzisyenlerden daha müzisyen
benim yorumcumdur,
eski deniz,
geleceğin denizi,
taçyaprak taşıyıcısı
kürk taşıyıcısı.
Yerleşiyor içimin derinliğine:
yeşil bir güneş yazıyor,
siliyor  eflatun bir denizi.
Yarı açık bir güneşi yazıyor deniz
kaçıp giden bin köpekbalığı üzerine.
Alain BOSQUET', 'Deniz mavi bir balık yazıyor, siliyor gri bir balığı. Deniz alev alan bir kruvazör yazıyor, siliyor kötü yazılmış bir kruvazörü. Şairlerden ...', ARRAY['Türk Edebiyatı','Şiir','Alain Bosquet']::text[], 8.5, '{"poet":"Alain Bosquet","poet_slug":"alain_bosquet","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZDE AY', 'deni-zde-ay-halit-fahri-ozansoy-izj0m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İndi solgun ve ılık
Ay ışığı denize
Bal rengi bir tatlılık
Çöktü gözlerinize.
Baktınız uzun uzun
Bu sulara baktınız,
Sulara ruhunuzun
Tadını bıraktınız!
Bu tatla aydınlanan enginlere aktınız!', 'İndi solgun ve ılık Ay ışığı denize Bal rengi bir tatlılık Çöktü gözlerinize. Baktınız uzun uzun Bu sulara baktınız, Sulara ruhunuzun Tadını...', ARRAY['Türk Edebiyatı','Şiir','Halit Fahri Ozansoy']::text[], 8.5, '{"poet":"Halit Fahri Ozansoy","poet_slug":"halit_fahri_ozansoy","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZE YAKIN MAĞARALARDA', 'deni-ze-yakin-magaralarda-yorgo-seferis-1ftcv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denize yakın mağaralarda
bir susuzluk duyarsın, bir aşk,
bir coşku
deniz kabukları gibi sert
alır avucuna tutabilirsin.
Denize yakın mağaralarda
günlerce gözlerinin içine baktım,
ne ben seni tanıdım, ne de sen beni.
Yorgo SEFERIS', 'Denize yakın mağaralarda bir susuzluk duyarsın, bir aşk, bir coşku deniz kabukları gibi sert alır avucuna tutabilirsin. Denize yakın mağaral...', ARRAY['Türk Edebiyatı','Şiir','Yorgo Seferis']::text[], 8.5, '{"poet":"Yorgo Seferis","poet_slug":"yorgo_seferis","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZE YAKIN', 'deni-ze-yakin-harry-martinson-2zex4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okyanusun gürültüleri şu anda.
Kumsallar üzerine yuvarlanmakta gülle gibi.
Geçiciliğin bayraktarı denen o kişi
Bu kıyıya ulaşmış,
Bu kumlara uzanmıştı.
Yersiz yurtsuz bir kraldı o.
Salt bir gün sürdü önderliği.
Harry MARTINSON', 'Okyanusun gürültüleri şu anda. Kumsallar üzerine yuvarlanmakta gülle gibi. Geçiciliğin bayraktarı denen o kişi Bu kıyıya ulaşmış, Bu kumlara...', ARRAY['Türk Edebiyatı','Şiir','Harry Martinson']::text[], 8.5, '{"poet":"Harry Martinson","poet_slug":"harry_martinson","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZLİ ANISI', 'deni-zli-anisi-henrik-nordbrandt-zq98j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korlar üstünde bir dans bu yaşam,
yüksek, mavi göğü altında ilkyazın.
Bu dört dize de tutmasa beni,
ben de dans etmeye başlayacağım
Henrik NORDBRANDT', 'Korlar üstünde bir dans bu yaşam, yüksek, mavi göğü altında ilkyazın. Bu dört dize de tutmasa beni, ben de dans etmeye başlayacağım Henrik N...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZLERİ KÜÇÜMSEYEN KIYILAR', 'deni-zleri-kucumseyen-kiyilar-yasin-erol-wq5nc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağaçların asili çınar
Öyle kuşlar konar ki
Dallarını unuttururlar adama
Renklerin asili mavi
Öyle giyerler ki
Bakacak adam bulurlar kadınlığına
Kıyılardan daha asildir deniz
Baksan da bakmasan da
Durgunluğunu bulaştırır kirli adamlığına
Çınarlar yapraklarını döksün yanıma yöreme
Mavi elbiselerden bir yorgan örtün üstüme
Artık ölmem de yetmeyecek
Yaktım içimdeki sandalı
Pişmanım denizleri küçümseyen kıyılara vardığıma', 'Ağaçların asili çınar Öyle kuşlar konar ki Dallarını unuttururlar adama Renklerin asili mavi Öyle giyerler ki Bakacak adam bulurlar kadınlığ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Erol']::text[], 8.5, '{"poet":"Yasin Erol","poet_slug":"yasin_erol","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZİN AYRICALIĞI', 'deni-zi-n-ayricaligi-sukru-erbas-fbx5u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kül uzun sürer, demiştim
Yenilgisini kutsayan bir sesle
Yalnız benim gördüğüm bir uzaklığa bakarak.
İstanbul''u insanın evi yapan
Bir yakınlıktı gövden ve sözlerin
Ihlamur yapraklarından gamzeler alan
Ellerin binlerce göldü masada.
Gölgesi uzun bir yoldan gelmiştim.
Polis çemberinde kaybolmuş caddeler
Yalnız kendi suretini soluyan odalar...
Ne suların aktığı yer, ne rüzgârın ülkesi
Herkes bir yerinden örtüyordu güneşi.
Sesinde denizin büyük ayrıcalığı
Sen bir başka uzaklığa bakarak konuşuyordun:
"Düşü olmayanın yenilgisi de olmaz
Yaşadığı her şey dokurken ömrünü
Pişmanlık insanın kendine kötü bir oyunu."
Gözlerin mi düşlerim mi bilmiyorum
Masmavi büyüyor bozkır geldiğimden beri...
1996', 'Kül uzun sürer, demiştim Yenilgisini kutsayan bir sesle Yalnız benim gördüğüm bir uzaklığa bakarak. İstanbul''u insanın evi yapan Bir yakınlı...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru_erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DENİZİN BEKLEDİĞİ', 'deni-zi-n-bekledi-gi-afsar-ti-muci-n-ak4z7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni sevmek mor denizlerdi biraz
Ne kadar gidilse bir o kadar bitmeyen
Umutlar ve yıkışmalar ardında direnilen
Seni sevmek mevsimler içinde en güzel yaz
Seni sevmek yaşamanın aşılmaz büyüklüğü
Seni sevmek kan dolu yüzyılları korkutan
Ve sığınıp ılık kıyı kentlerine bir akşam
Seni sevmek çocukların düşlerinde gördüğü
Varılırdı daha saydam günlere isteseler
İsteseler yalnızlık giremezdi evlere
Seni sevmek bir kırlangıç olacak bekleseler
Ve uçacak durmadan adasız denizlere
Kim bulacak cam kırığı gözlerinde sevgimi
Sonra yalnız kalmak gibi yoksulca uğuldayan
Bütün okyanusların baş eğdiği tek kaptan
Sana verdim geç diye bütün denizlerimi', 'Seni sevmek mor denizlerdi biraz Ne kadar gidilse bir o kadar bitmeyen Umutlar ve yıkışmalar ardında direnilen Seni sevmek mevsimler içinde ...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEĞİŞİP YOK OLAN BİR KENTİ ANIMSAYARAK', 'degi-si-p-yok-olan-bi-r-kenti-animsayarak-eray-canberk-hs3cp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu kent büyük bir ihaneti gizliyor
sabahlara dek inlemesinden belli
seni nasıl uzak kentlere götürsem
nasıl uyutsam nasıl dinlendirsem
bu kent gizliyor büyük bir ihaneti
bu kent küçücük adamları büyütüyor utanmadan
ışıl ışıl yanan lâmbaları
pişman gözleridir pişman gözleridir pişman
bir ölüyü suçlamak kadar anlamsız
üstüme üstüme geliyor hiçbir şey
anlatmadan anlatmadan anlatmadan
ben nasıl yanılmışım bilmiyorum bilmiyor
ne çok anlatamadığımı gizlemekle
umarsız iniyor umarsız akşam iniyor
bir çiçek bırakıyorum gecenin başladığı yere', 'bu kent büyük bir ihaneti gizliyor sabahlara dek inlemesinden belli seni nasıl uzak kentlere götürsem nasıl uyutsam nasıl dinlendirsem bu ke...', ARRAY['Türk Edebiyatı','Şiir','Eray Canberk']::text[], 8.5, '{"poet":"Eray Canberk","poet_slug":"eray_canberk","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERDİNE YAN ZAVALLI ZENCİ', 'derdi-ne-yan-zavalli-zenci-leopold-s-dar-senghor-rmfik', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Derdine yan küçük Zenci
Kırbaç ıslık çalıyor bak
Sırtında okşadıkça
Kanlı kanlı terli terli
Derdine yan küçük Zenci
Gün uzun yollar uzun
Taşı durmadan işin ne
Beyaz fildişi beyaz Efendine
Derdine yan küçük Zenci
Alışsın çocukların açlığa
Bomboş kaldı kulüben
Sevgili karın uyuyor
Efendinin yatağında
Derdine yan zavallı Zenci derdine
Bir kez vurmuş bahtın damgasını rengine
Leopold Sédar SENGHOR', 'Derdine yan küçük Zenci Kırbaç ıslık çalıyor bak Sırtında okşadıkça Kanlı kanlı terli terli Derdine yan küçük Zenci Gün uzun yollar uzun Taş...', ARRAY['Türk Edebiyatı','Şiir','Leopold Sédar Senghor']::text[], 8.5, '{"poet":"Leopold Sédar Senghor","poet_slug":"leopold_sedar_senghor","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞERİM', 'duseri-m-metin-altiok-uk5m0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazan oturduğum yerde
Kendikendime dalıp giderim,
Bulanık geçmişimle.
Genişleyen halkalar çizerim,
Bir düşün uyanık imgesine.
Gölünüze taş düşerim.
Sizse hep konuşursunuz
Sığınıp kof sözlere,
Kaçarak kendinizden
Uğuldayan hüznünüzle.
Telâşla geceyi bulursunuz.
Gözünüze yaş düşerim.', 'Bazan oturduğum yerde Kendikendime dalıp giderim, Bulanık geçmişimle. Genişleyen halkalar çizerim, Bir düşün uyanık imgesine. Gölünüze taş d...', ARRAY['Türk Edebiyatı','Şiir','Metin Altiok']::text[], 8.5, '{"poet":"Metin Altiok","poet_slug":"metin_altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERİNLEŞEN AKŞAMDA', 'deri-nlesen-aksamda-afsar-ti-muci-n-2s5pp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sigara yaktım durup düşündüm
Neyim var neyim yok döküverdim önüme
Yeniden gözden geçirdim kendimi
Kendime yabancı düştüm gene
Nasıl da sert davranmıştım kendime
Şimdi daha iyi anlıyorum
Ben sokakların kural bilmez çocuğu
Bir başkası olabilir miydim hiç
Kendi yerime
Biraz da anılarla oyalansam
Yaşanmış ve bitirilmiş olanı
Nedense bir türlü sevemiyorum
Yeniden yaşamayı düşünmüyorum
En güzel sevinçlerimi bile
Her zaman kendime dar geliyorum
Ne zaman derinlerime dönsem
Yeni bir sayfa açılıyor önüme
Ne zaman yeni bir şeyleri özlesem
Neden bilmem
Kaskatı bir karanlık yerleşiyor içime', 'Bir sigara yaktım durup düşündüm Neyim var neyim yok döküverdim önüme Yeniden gözden geçirdim kendimi Kendime yabancı düştüm gene Nasıl da s...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERİNLİK ÇEKİMİ  I', 'deri-nli-k-ceki-mi-i-aziz-nesi-n-apo9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yükseklerden bakamıyorum
Korkuyorum
Derinlik çekiyor kendine
Düşecekmişim gibi içimin derinliğine
Başım dönüyor yükseklerden
Çekiyorum beni kendi derinliklerime', 'Yükseklerden bakamıyorum Korkuyorum Derinlik çekiyor kendine Düşecekmişim gibi içimin derinliğine Başım dönüyor yükseklerden Çekiyorum beni ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERİNLİK ÇEKİMİ  II', 'deri-nli-k-ceki-mi-ii-aziz-nesi-n-245ue', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En derini dünyanın kendi uçurumum
Başım dönüyor içimin derinliğinden
Bigün kaldırıp kendimi fırlatacağım
Kendimi kendi içime atacağım
Kartal kanatlarının da bir sınırı var gökte
Uçakların da füzelerin de
Bütün o sınırları aşacağım
Kendimi içimdeki sınırsız boşluğa bırakacağım
Durmadan çekiyor beni bu dipsiz doruksuz uçurum
Gözlerim kararıyor içime bakınca
Atıp kendimi kendime
Derinlik korkusundan büsbütün kurtulacağım', 'En derini dünyanın kendi uçurumum Başım dönüyor içimin derinliğinden Bigün kaldırıp kendimi fırlatacağım Kendimi kendi içime atacağım Kartal...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERS ÇALIŞMA', 'ders-calisma-nicolas-guillen-aq6kb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beyaz çocuklar bugün Alabama''da,
kitaplar okunurken, uygulamalı evödevi olarak,
alevli bir güzelim buket hazırlarlar,
içinden beş zenci cesedi sarkan.
Nicolas  GUILLEN', 'Beyaz çocuklar bugün Alabama''da, kitaplar okunurken, uygulamalı evödevi olarak, alevli bir güzelim buket hazırlarlar, içinden beş zenci cese...', ARRAY['Türk Edebiyatı','Şiir','Nicolas  Guillen']::text[], 8.5, '{"poet":"Nicolas  Guillen","poet_slug":"nicolas_guillen","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERS', 'ders-altay-oktem-v3q4n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-neden yalnızca geçmişin tarihi yazılır?
hocam, bir akarsu; adı yeryüzünde olmayan
dağlara tutunarak, göğe sürtüp yüzünü
beklenmedik denizlere kavuştuğu an
su,
susalım hocam
önce çocuklar konuşsun sonra hep
çocuklar konuşsun!
tek atışta ıskalanan bütün bilyeleri
toplasak hatmileri, begonyaları, yaşlı yüzleri
yoksul çocuk kentleri ele geçirilmeden
ne olurdu hocam paylaşsak şu ölümü
tarih sırra kadem basar mıydı ola?
zamanımız doldu hocam bu ders de bitti
artık vurabilirim seni', '-neden yalnızca geçmişin tarihi yazılır? hocam, bir akarsu; adı yeryüzünde olmayan dağlara tutunarak, göğe sürtüp yüzünü beklenmedik denizle...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay_oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERVİŞ', 'dervi-s-mehmet-taner-jncyl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adam ansızın yolumu çeldi. Kolunu uzatıp
Çekti önüme yığdı sabahı
Şarkılarla koca bir dağ yaptı, atılmış şarkılarla
Sonra bir yumaktan söker gibi
Açtı dağı. Bir yandan açtı, yürüdü bir yandan:
- Bu bir sanrı olsa olsa
Dedi,
Çünki ben, gözleri olmayan ben
Nereye gittiğimi bilmem ki', 'Adam ansızın yolumu çeldi. Kolunu uzatıp Çekti önüme yığdı sabahı Şarkılarla koca bir dağ yaptı, atılmış şarkılarla Sonra bir yumaktan söker...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DERVİŞLİK DEDİKLERİ', 'dervi-sli-k-dedi-kleri-yunus-emre-vcr8u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dervişlik dedikleri
Hırka ile taç değil
Gönlün derviş eyleyen
Hırkaya muhtaç değil
Hırkanın ne suçu var
Sen yoluna varmazsan
Vargıl yolunca yürü
Er yolu kalmaç değil
Dirsin Şeyh''in aşkına
Yalın ayak başı açık
Er var dirlik dirlikmiş
Yalın ayak aç değil
Durmuş marifet söyler
Erene Yunus Emrem
Yol eriyle yoldadır
Yolsuza yoldaş değil', 'Dervişlik dedikleri Hırka ile taç değil Gönlün derviş eyleyen Hırkaya muhtaç değil Hırkanın ne suçu var Sen yoluna varmazsan Vargıl yolunca ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DESEM Kİ', 'desem-ki-cahit-sitki-taranci-igz3z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Desem ki vakitlerden bir Nisan akşamıdır,
Rüzgârların en ferahlatıcısı senden esiyor,
Sende seyrediyorum denizlerin en mavisini,
Ormanların en kuytusunu sende gezmekteyim,
Senden kopardım çiçeklerin en solmazını,
Toprakların en bereketlisini sende sürdüm,
Sende tattım yemişlerin cümlesini.
Desem ki sen benim için,
Hava kadar lazım,
Ekmek kadar mübarek,
Su gibi aziz bir şeysin;
Nimettensin, nimettensin!
Desem  ki...
İnan bana sevgilim inan,
Evimde şenliksin, bahçemde bahar;
Ve soframda en eski şarap.
Ben sende yaşıyorum,
Sen bende hüküm sürmektesin.
Bırak ben söyleyeyim güzelliğini,
Rüzgârlarla, nehirlerle, kuşlarla beraber.
Günlerden sonra bir gün,
Şayet sesimi farkedemezsen,
Rüzgârların, nehirlerin, kuşların sesinden,
Bil ki ölmüşüm.
Fakat yine üzülme, müsterih ol;
Kabirde böceklere ezberletirim güzelliğini,
Ve neden sonra
Tekrar duyduğun gün sesimi gökkubbede,
Hatırla ki mahşer günüdür
Ortalığa düşmüşüm seni arıyorum.', 'Desem ki vakitlerden bir Nisan akşamıdır, Rüzgârların en ferahlatıcısı senden esiyor, Sende seyrediyorum denizlerin en mavisini, Ormanların ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DESTANSI ÖYKÜ''DEN', 'destansi-oyku-den-cevat-capan-ywp9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I
Üç yıl boyunca
hiç durmadan haberciyi bekledik
gözlerimizi dikip
çamlara, kıyıya ve yıldızlara.
Bir olup sabanın demiriyle, omurgasıyla geminin,
İlk tohumu arıyorduk
eski oyun yeniden başlasın diye.
Yaralarla döndük yurdumuza,
elimiz kolumuz tutmuyordu, ağzımız
tuz pas içinde.
Kuzeye doğru yol aldık uyandığımızda,
lekesiz kanatlarıyla bizi sislere salan
kuğuların yaraladığı yabancılardık.
Uluyan gündoğusu çıldırttı bizi kış gecelerinde,
yazları, ölmeyen günün acısında yitirdik kendimizi.
Birlikte getirdik dönüşte
Bu oyma kabartmalarını saygılı bir sanatın.
II
Yeniden bir başka kuyu bir mağara içinde.
Bir zamanlar kolaydı
Putlar, süsler çıkarıp derinliklerinden
Sevindirmek bize bağlı kalan dostları.
İpler kopmuş artık; yalnız kuyu ağzındaki izleri
Ansıtıyor bize, bizi koyup giden mutlulukları:
Kuyu ağzında parmaklar, ozanın deyişiyle.
Bir an taşın serinliğini duyuyor parmaklar
Ve taşa geçiyor gövdenin sıcaklığı,
Her kıpı, sessizlik dolu, damla akmadan
Ruhunu oyuyor mağara sanki kumarda ve yitiriyor.
III
"İçinde hançerlendiğiniz hamamı unutmayın."
Ellerimde bu mermer başla uyandım
Dirseklerimi yoran, nereye koyacağımı bilemediğim.
Bir düşe yuvarlanıyordu baş, ben düşten uyanırken,
Böylece birleşti yaşamlarımız, şimdi ayırması güç.
Bakıyorum gözlere, ne açık ne kapalı,
Konuşmağa çalışan ağıza konuşuyorum,
Tutuyorum derinin ötesine çökmüş yanakları.
Gücüm fazlasına yetmiyor.
Ellerim kayboluyor, sonra dönüyor,
Sakatlanarak.
IV
ARGONOTLAR
Ruha gelince,
tanıyacaksa kendini,
bir başka ruhun
derinliklerine bakması gerek:
hem yabancı, hem düşman, aynada gördük onu.
İyi çocuklardı  yoldaşlarımız, hiç yakınmıyorlardı
yorgunluktan, susuzluktan, soğuktan,
ağaçlar ve dalgalar gibi dayanıklıydılar
rüzgârla yağmuru kabul eden,
geceyle güneşi,
onca değişim içinde  hiç değişmeden.
İyi insanlardı, günlerce başlarını eğip
hep birden soluyarak
küreklerde ter döktüler,
kanlarıyla kızardı uysal derileri.
Kimi zaman türküye durdular, başlarını eğip
hintincirlerinin bittiği ıssız adadan geçerken,
köpeklerin havladığı burnun ötesinde,
batan güne doğru.
Kendini tanıyacaksa ruh, diyorlardı,
bir başka ruhun derinliklerine bakması gerek
Ve kürekler vuruyordu denizin yaldızına gün batarken.
Nice burunlar geçtik, nice adalar,
deniz bir başka denize karışıyordu,
martıları, ayı balıkları başka.
Gün oldu, mutsuz kadınlar yas içinde
dönmeyen çocuklarına ağladılar,
öfkeyle Büyük İskender''i sordu başkaları
ve Asya''nın derinliklerine gömülen kahramanlıkları.
Gecenin kokularıyla yoğun kıyılara demirledik gemiyi,
kuş cıvıltıları, suları elimizde büyük bir mutluluğun
anısını bırakan.
Ama hiç sonu gelmiyordu bu yolculukların.
Ruhları bir olmuştu küreklerle, ıskarmozlarla,
asık yüzlü pruvasıyla geminin,
dümen suyuyla bir,
yüzlerinin görüntüsünü kıran sularla bir.
Birer birer öldüler
başları eğik yoldaşlarımız.
Kürekleri belirtisi kıyıda yattıkları toprağın.
Kimseler yok adlarını anacak. Alın yazısı.
Çeviri : Cevat ÇAPAN
IX
Liman yaşlıdır, artık bekleyemem
Çamlı adalar için çekip giden arkadaşları
Çınarlı adalar için çekip giden arkadaşları
Açık deniz için çekip giden arkadaşları.
Okşarım paslı gemileri, kürekleri okşarım
Ki bedenim canlansın ve güçlensin.
Yelkenler tuz kokusu verir yalnız
Öteki fırtınadan.
Yalnız kalmak isteseydim, sessizlik
Olurdu aradığım, yoksul ufukta
Bu çizgilerin, bu renklerin, bu suskunluğun
Ruhumu parça parça edeceği umudu değil.
Gecenin yıldızları yeniden getirdi bana
Ölümü bekleyen Odysseus''un güvenini, çiriş otları arasında.
Burda çiriş otları arasında demirlediğimiz zaman
Adonis''in yaralandığını bilen boğazı bulalım istedik.
Çeviri : Melih Cevdet ANDAY', 'I Üç yıl boyunca hiç durmadan haberciyi bekledik gözlerimizi dikip çamlara, kıyıya ve yıldızlara. Bir olup sabanın demiriyle, omurgasıyla ge...', ARRAY['Türk Edebiyatı','Şiir','Cevat Çapan']::text[], 8.5, '{"poet":"Cevat Çapan","poet_slug":"yorgo_seferis","theme":"Türk Şiiri","is_hero":false,"total_lines":106}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEVLET KAÇ TAZI TUT', 'devlet-kac-tazi-tut-akif-kurtulus-8z4m6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'halkın imlası taşarsa coğrafyadan
geçer onlar iki yağmur damlasının arasından
göstererek devlete bütün zerafetini
belki de onlarbindir
bir çarşıda kendini kaybetmek gibi bir şey olur bu
kefyede buluşanların safrana karışması gibi
gövdeye bulaşan bir bedesten gibi.
orda yeşil, kandan alırken rengini
tarihin biçimine bürünür güneş
kim güvenir peki tarihe
iki kaşın arası varsa
yolunu bulmak için
ateşi savunmak yetiyorsa
avuçta gül ezip göğe fırlatmak neye yarar
tenimizi yeniden tanımlamaktan başka
hayatın diyorduk, geçen gün laf arasında
hiçbir erdemi kalmadı gözümüzden kaçıracak
tattık hepsini, imzalar attık, gazetelere ilanlar verdik
saftirik demişti muhaliflerimiz son genel kurulda bize
halbuki komedyen taklidi yapıyorduk
bozuk terazi kullandık
melankoliyle coşku arasındaki dengeyi bozmamak için
bizden artan nevroz onlara da yaradı
düzmüş oldular sonunda bütün eksiklerini
o gün birisi ateşkes demişti;
bu kadar kısa sürmese
belki de iyi bir çizgi film yapardık kardugh''lardan
araya reklam girince
ölülerimizi toplar, kaşla göz arasında gömerdik
lan yavşak!
derdik film başlayınca kaldığı yerden
değil mi ki bizi her kavşakta polisle korkuttular
oğlumuzun kirvesi de emniyet amiri olsun
insan olan sırf bu inada bağışlardı
en iyi yardımcı oyuncu ödülünü
kimse ben oynarken elime konuşmasın
biz tarihe tanıklık etmek için ifade vermeye geldik
baş başaltı müselles, kapış serbest''te sıramızı savdık
ruhumuz her ne kadar esas duruştaysa da
vicdanımız rahat
bütün geçiş noktalarında şövalye muamelesi gördük
halbuki kavalyeyiz: çünkü hiçbir yere "damsız girilmez"
hayatın bizden sakınacağı bir anlam da kalmadı nasılsa
öğrendi çocuklar kirpinin sırrını
bütün savunması üstüne işeyinceye kadarmış
demek bu kadar saldırgan olmamız boşuna değil
hem artık herkesin bir evtimsahı var
gözyaşımızla sindirim sistemimiz arasındaki
o tuhaf macerayı izlemek kolay oluyor
ne sürüngenlere hakaret ediyoruz
ne de erkekliğimize dokunuyor sulugözlerimiz
savcılar saygın bulmasa da gayretimiz var en azından
kavakların hangi yolla çiftleştiğini anlamaya
hayber kalesi içinde kaçak yapılaşmaya yok mu bir dur diyecek
var!
peki kan kalesi mukimlerine tapu dağıtmak için
törene ne gerek var
yavrucuğum, bizim üç oda bir salon evimiz
davetsiz misafirlere monitörden kim o demeye mecalimiz var
medeni cesaretimiz var: onlar burdan taşınalı çok oldu
tıkırtıya duyarlı bant kaydımız var bizim yerimize zıvanadan çıkan
hanım çabuk silahımı getir! ince, koskoca hırsızlar nasıl tırsıyor
terminalden havaya fırlatılan en büyük asker için
yeri geldiğinde bükerek sustuğumuz
vücut isterse davula gön yaptığımız bir kalbimiz:
bundan bir bumerang öyküsü çıkaracak
iyi edebiyatçılarımız var
orda şimdi
şırnak: kırbaç: şırraak !
hoh hoh hosaybin
iki üç daha fazla katliam
var
bir kulp var ayrılığa takacak
haydi şimdi hep bir ağızdan:
devlet kaç tazı tut!', 'halkın imlası taşarsa coğrafyadan geçer onlar iki yağmur damlasının arasından göstererek devlete bütün zerafetini belki de onlarbindir bir ç...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif_kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":77}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEVRAN BUYURDU BİZE', 'devran-buyurdu-bi-ze-ernest-hemingway-915js', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devran buyurdu bize  şarkı söyleyin
Ve kesti dilimizi kökünce.
Devran buyurdu bize  su gibi akın
Ve tıpa soktu tüm deliklerimize.
Devran buyurdu bize  kalkıp oynayın
Ve iğneli fıçıyı giydirdi bize.
Ve sonunda ey devran ! al sana,
Dışkının dik âlâsı, buyursana.
Paris 1922
Ernest  HEMINGWAY', 'Devran buyurdu bize  şarkı söyleyin Ve kesti dilimizi kökünce. Devran buyurdu bize  su gibi akın Ve tıpa soktu tüm deliklerimize. Devran buy...', ARRAY['Türk Edebiyatı','Şiir','Ernest  Hemingway']::text[], 8.5, '{"poet":"Ernest  Hemingway","poet_slug":"ernest_hemingway","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEVRAN TERS YÖNE DÖNÜYOR', 'devran-ters-yone-donuyor-bulent-ozcan-pbmiw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dönüyor devran dönüyor,
Devran ters yöne dönüyor...
İşkence, açlık, kıyım var;
Devran ters yöne dönüyor...
Zindan içinde zindanlar,
Kurşuna dizilir canlar,
Ölür nice genç insanlar,
Devran ters yöne dönüyor...
Hiroşima, Halepçeler
Zincirler ve kelepçeler,
Ana babasız bebeler,
Devran ters yöne dönüyor...
Tarih kör topal ve sağır,
Duymaz seni bağır bağır;
Gözyaşı, zulüm ve kahır,
Devran ters yöne dönüyor...', 'Dönüyor devran dönüyor, Devran ters yöne dönüyor... İşkence, açlık, kıyım var; Devran ters yöne dönüyor... Zindan içinde zindanlar, Kurşuna ...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEVRİM TÜRKÜLERİ', 'devri-m-turkuleri-yevgeni-yevtusenko-3uvmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha sık söyleyin devrim türkülerini.
Onları az söylüyorsunuz -
ve benim yaptığım da bu.
Fazlaca mı doyumlusunuz?
Size hiçbir şey heyecan vermiyor mu?
Söyleyin o türküleri.
Yardım edeceklerdir size.
Kitaplar alın.
O türküleri içeren.
Okuyun bıkmadan, usanmadan.
Söyleyin kendi kendinize
sesli ya da içinizden.
Söyleyin çocuklarınıza da,
tabii çocuklarınız varsa.
Duyacaksınız
uzak ve acılı
ağır pranga şangırtlarını,
Göreceksiniz tutuklanmışları, kıskıvrak bağlanmışları,
dövülmüşleri,
kurşuna dizilmişleri,
hurdahaş edilmişleri.
Zamanın yapmacık ve yalancı marşlarına değil
onlar
kendi kutsal türkülerine inanıyorlardı.
O türküleri söylüyorlardı,
gizlice,
usul sesle.
Yüksek sesle söyleyememenin acısını
duyarak yüreklerinde.
Biricik ve unutulmaz bir kanla
bağlıyız onlara biz.
Şimdi o türküleri
yüksek sesle söylemeliyiz!
Yaşamınız pek mi tekdüze?
Pek mi kıpırtısız?
İnsanlara
ve sözlere
artık kalmadı mı güveniniz?
Ama devrim türküleri var
yeryüzünde.
Söyleyin onları.
Size yardım edeceklerdir, göreceksiniz.
Yevgeni YEVTUŞENKO', 'Daha sık söyleyin devrim türkülerini. Onları az söylüyorsunuz - ve benim yaptığım da bu. Fazlaca mı doyumlusunuz? Size hiçbir şey heyecan ve...', ARRAY['Türk Edebiyatı','Şiir','Yevgeni Yevtuşenko']::text[], 8.5, '{"poet":"Yevgeni Yevtuşenko","poet_slug":"yevgeni_yevtusenko","theme":"Türk Şiiri","is_hero":false,"total_lines":45}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEVRİM', 'devri-m-sunay-akin-v3qmn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Temiz kalan tek yerdir devrim
bütün bir yıl
kirlenen duvarda
ama görebilmek için
asıldığı çividen indirilmelidir
yaprakları biten takvim
Zorbalara direnmektir devrim
bir çocuğun
annesinin çantasından aldığı paraları
altına gizlediğini
söylememiştir dövülen
hiçbir halı
İçinde yaşamaktır devrim
dikiş kutusunun
ve topluiğneler gibi
bir arada olmayı gerektirir
karşı koyabilmek için zulmüne
makas denilen patronun
Gece ışıklar arasında koşmaktır devrim
ateş böceklerini
yakalamak isteyen çocukların
peşine takılır gün gelir
yanıp sönen mavi ışıkları
polis arabalarının
Kağıt bir gemidir devrim
bütün gemiler
hurdaya çıksa da sonunda
taşıdığı özgürlük şiiriyle
batmadan yüzer nicedir
dünya sularında
Kim bilir kaç yunus görmüş
kaç deniz gezmiş...', 'Temiz kalan tek yerdir devrim bütün bir yıl kirlenen duvarda ama görebilmek için asıldığı çividen indirilmelidir yaprakları biten takvim Zor...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akin']::text[], 8.5, '{"poet":"Sunay Akin","poet_slug":"sunay_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DIŞARDA KAR', 'disarda-kar-behcet-aysan-dz1vn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kar yağıyor dışarda
sokak lambasına düşüyor
ve serçeler
üşüyor
kenarları hafifçe yanmış
sayfalarına kan
sıçramış
bir kitapta
nâzım hikmet
okuyorum.
dışarda kar yağıyor
ve dağ lokantasına
gidiyor
zengin
kasabalılar.
kar yağıyor dışarda
mektubun yeni gelmiş
istanbul
kokuyor.
dışarda kar yağıyor
seni seviyorum.', 'kar yağıyor dışarda sokak lambasına düşüyor ve serçeler üşüyor kenarları hafifçe yanmış sayfalarına kan sıçramış bir kitapta nâzım hikmet ok...', ARRAY['Türk Edebiyatı','Şiir','Behçet Aysan']::text[], 8.5, '{"poet":"Behçet Aysan","poet_slug":"behcet_aysan","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞÜK', 'dusuk-metin-guven-p2sk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bağırıyor
Urganla boğulan kuşlar gibi
Yere düşüyor cenin
Ve kırmızı kan
Sularda yaşamaz kediler
Kaçarlar böğürtlen gölgesine.', 'Bağırıyor Urganla boğulan kuşlar gibi Yere düşüyor cenin Ve kırmızı kan Sularda yaşamaz kediler Kaçarlar böğürtlen gölgesine....', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜŞÜDÜKÇE', 'usudukce-umut-taydas-fhajy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazdık değse de,
Değmese de-belli ki,
Havalı çocuklardık,
Cefakâr ama
Karışık kasetli,
Babalarımız hep böbrek taşı sahibi,
Onlar işerdi,
Anneler onların başını beklerdi,
Biz üşürdük,
Üşüdükçe kaçardık evden,
Arkadaşlara, sinemalara, oralara,
Necla''nın balkonunun altına,
Yine de hep üşürdük,
Kimsesizlikte yatıya kalır,
Üşüdükçe,
Şair olurduk...
24.03.2002 - 09:43
Umut
"aman da amman"', 'Yazdık değse de, Değmese de-belli ki, Havalı çocuklardık, Cefakâr ama Karışık kasetli, Babalarımız hep böbrek taşı sahibi, Onlar işerdi, Ann...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞKIRILMASI', 'duskirilmasi-yusuf-altunel-ijxuf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'metropolün izbe karanlıkları gizlidir
tutuşturamadığımız yangınlarda
avuçlamak isteyip de hani
dokunamadığımız
mutluluklarda
bir albümde duruyordur belki
sararmış
öpülmemiş dudaklar
gül renkli arzular soluk
okul defterinin arka sayfalarında şimdi
okşanmamış tenler
beklenmemiş gemilerin demir attığı
akıp giden hayatın
yüzen kuru yaprakları
mahşer kalabalığı doldurmuş da bu kenti
bir bana yer kalmamış sanki
arzu dolu haykırışların çınlatamadığı
evlerin duvarlarında saklıdır bir akşam vakti
uzatıp da dokunmak için
değmeden ince boynuna geri çektiğimiz
utangaç, terbiyeli ellerimiz
ateşlemek için dinamitleri
yaktığımız gözlerimizdeki pırıltı
sönmüş mumların kararmış fitilidir şimdi
karanlık yataklarda
tasarlanmış sevişmelerimiz gizlidir
bir sahil kenarında elele
dolaşamamalarımız alevlemiştir yakamozları
güneş boğarken kendisini altın renkli sularda
sevişmemelerimiz yorgun vurmuştur kıyıya
söylenmemiş arzu sözleri
bırakıp ardında düşkırılması
açılmıştır yokluklar okyanusuna
pişmanlık
boz kırların acımasız sırtlanı
çökmüştür akbaba gibi
yüreklerimizin güvercinine
ölesiye sevda kurşunları
binlerce parçaya bölmüştür
faili meçhul düşlerimizi
ayrılık
yargısız infazdır
yeni zamanları
eski zamanlarla
harmanlamakta
demir giysili umutsuzluk firavunu
parçalayıp sevda zincirini
bırakıyor gövdelerimizi asfalt yollara
çelik yelekli infaz timi zaman', 'metropolün izbe karanlıkları gizlidir tutuşturamadığımız yangınlarda avuçlamak isteyip de hani dokunamadığımız mutluluklarda bir albümde dur...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Altunel']::text[], 8.5, '{"poet":"Yusuf Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÖKÜLECEKLER', 'dokulecekler-ece-ayhan-yvpcb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1.Uç Doğu. Anadolu''yu anlatacaktır öğretmen. Haritayı asar.
2.Bütün sınıf korkmuştur; göller, ırmaklar dökülecekler!', '1.Uç Doğu. Anadolu''yu anlatacaktır öğretmen. Haritayı asar. 2.Bütün sınıf korkmuştur; göller, ırmaklar dökülecekler!...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DİKİLİTAŞ (17)', 'di-ki-li-tas-17-hasan-basri-unlu-amzyh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yıllarsonra
ilkdefainsa
niçineçıktı
