amaburuktum
SARILAMADIM', 'yıllarsonra ilkdefainsa niçineçıktı myıllardırd okunmadığım yüzlerebakt ımdahayaşlı dahayorguny üzlerivardı ayrıkotları fesleğenler diknesiz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Ünlü']::text[], 8.5, '{"poet":"Hasan Basri Ünlü","poet_slug":"hasan_basri","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DİKİLİTAŞ I', 'di-ki-li-tas-i-hasan-basri-unlu-pa5fe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'doğduğumyer
