INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELÂ GÖZLÜ BENLİ DİLBER', 'el-gozlu-benli-di-lber-karacaoglan-xry54', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elâ gözlü benli dilber
Koma beni el yerine
Altın kemerin olayım
Dola beni bel yerine
Hecine gönlüm hecine
Yiğide ölüm gecine
Al beni zülfün ucuna
Sallanayım tel yerine
Gel kız karşımda dursana
Şu benim halim bilsene
Zülfünden bir tel versene
Koklıyayım gül yerine
Karacaoğlan der n''olayım
Kolun boynuna dolayım
Nazlı yâr kölen olayım
Kabul eyle kul yerine', 'Elâ gözlü benli dilber Koma beni el yerine Altın kemerin olayım Dola beni bel yerine Hecine gönlüm hecine Yiğide ölüm gecine Al beni zülfün ...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELÂ GÖZLERİNİ SEVDİĞİM DİLBER', 'el-gozleri-ni-sevdi-gi-m-di-lber-karacaoglan-u3fw6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elâ gözlerini sevdiğim dilber
Göster cemalini, görmeğe geldim
Şeftalini derde derman dediler
Gerçek mi sevdiğim sormaya geldim
Gündüz hayallerim, gece düşlerim
Uyandıkça ağlamağa başlarım
Sevdiğim üstünde uçan kuşların
Tutup kanatların kırmağa geldim
Senin âşıkların gülmez dediler
Ağlayıp yaşını silmez dediler
Seni bir kez saran ölmez dediler
Gerçek mi efendim, sormaya geldim
Senin işin yiyip içmek dediler
Yâran ile konup göçmek dediler
Göğsün cennet, koynun uçmak dediler
Hak nasip ederse görmeye geldim
Mail oldum, senin ince beline
Canım kurban olsun tatlı diline
Âşık olup senin hüsnün bağına
Kırmızı güllerin dermeğe geldim
Karac''oğlan der ki, işi doğrusu
Gökte melek, yerde hüma yavrusu
Söyleyim ben sana sözün doğrusu
Soyunup koynuna girmeğe geldim', 'Elâ gözlerini sevdiğim dilber Göster cemalini, görmeğe geldim Şeftalini derde derman dediler Gerçek mi sevdiğim sormaya geldim Gündüz hayall...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELÂ GÖZLÜM BEN BU İLDEN GİDERSEM', 'el-gozlum-ben-bu-i-lden-gi-dersem-karacaoglan-foujp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elâ gözlüm ben bu ilden gidersem
Zülfü perişanım kal melûl melûl
Kerem et aklından çıkarma beni
Ağla göz yaşını sil melûl melûl
Yiğit, ey sevdiğim sen seni gözet
Karayı bağla da beyazı çöz at
Doldur ver bâdeyi, bir dahi uzat
Ayrılık şerbetin ver melûl melûl
Elvan çiçeklerden sokma başına
Kudret kalemini çekme kaşına
Beni unutursan doyma yaşına
Gez benim aşkımla yâr melûl melûl
Karac''oğlan der ki, ölüp ölünce
Ben de güzel sevdim kendi halimce
Varıp gurbet ile vâsıl olunca
Dostlardan haberim al melûl melûl', 'Elâ gözlüm ben bu ilden gidersem Zülfü perişanım kal melûl melûl Kerem et aklından çıkarma beni Ağla göz yaşını sil melûl melûl Yiğit, ey se...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EL KAPILARI', 'el-kapilari-n-zim-hikmet-fkkzs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gerek geçmişte, gerek şimdiki zamanda çeşitli açılardan
toplumumuzu etkileyen büyük olayların halk türkülerine, aydın
kişinin rahatına ve düşüncesine nasıl yansıdığını böyle
bir plakta toplamayı düşündüm. Doğaldır ki derlemek,
toparlamak, birbirini tamamlayan bir düzen içinde vermek kolay
olmuyor. Bu olayların bir kısmı Osmanlı İmparatorluğu döneminde
geçiyor. Yemen adıyla simgelenen ve yurdu dullarla, ağıtlarla
dolduran bitmez tükenmez askerlikler dönemi. O zaman koşulları
içinde aydın kesimine yansımamış, yanlız türkülere geçmiş,
türkülerle bugüne gelebilmiş. Bir kısmı Cumhuriyet döneminde,
şimdiki zamanda geçiyor. Almanya adıyla simgelenen ve yurt dışına
giden işçilerin yaşamıyla ilgili dönem Askerlik değil, savaş
değil; çalışmaya gidiyorlar, ama gidenler yine yurtlarını,
yuvalarını bırakıp gidiyor. Halk yine mutsuz. Türküler yine
acılı ve yakınmalı. Aydın kesiminin bütün sanatlarına ve
bilimsel araştırmalara konu oluyor.
Kuşkusuz belli bir açıdan bakıyorum bunlara. Hangi açıdan
bakarsan bak, sonuç aynı ya, ben yine de belli bir açıdan bakıyorum.
Çağımızın düşüncesi ve halkın yaşamı açısından.
Halkın yaşamı düzenlerin dışında kalan bir şey değil. Böyle
bir düzen, şimdiye kadar ya savaş getirmiş, ya da savaştan
geri kalmayan başka sorunlar. Öyleyse çözüm ne? Çözüm
olarak da Nâzım Hikmet''in bir şiirinde söylediklerini söylüyorum.
Nâzım Hikmet''in şiirlerini benden önce, benden daha
yetenekli müzikçiler getirseydi dinleyiciye, bugün elimizde
daha iyi örnekler bulunabilirdi. Böyle bir boşluğu doldurmak
benim gücümü aşsa da, denemeye değdi doğrusu.
Aydın bir ozanın şiirini bestelemek kolay bir iş değil.
Şiir, müziğin öğeleri içinde olumsuz anlamlar kazanıp gücünü
yitirebilir. Gürültüye gelebilir, hatta gülünç olabilir. Sözgelişi,
'''' Hava kurşun gibi ağır'''' dizesiyle başlayan bir şiir, ''''Darıldın
mı cicim bana, hiç bakmıyorsun bu yana'''' kantosundaki müzikle
ya da buna benzer başka bir müzikle söyleyemeyiz. Müzikle söz
arasındaki zıtlıklardan yararlanmak bu değildir.
Müzik, sözdeki duygusallığı abartır, ortaya çıkarır.
Bu nedenle de yanlış bir yorum abartılmış olacağından,
kolayca anlaşılır. Şiirin kuruluşundaki denge bozulur. Müzik,
şiirdeki bu dengeyi bozmadan geliştiriyor, etkisini arttırıyorsa
işe yarar. Ben bunlardan korktuğum için, şiirin dizelerine
uygun müziği bulamadığımız zaman, şiiri müziksiz okumayı
yeğ tutuyorum. Besteci değilim, ama bunları düşünmekte
yarar görüyorum.', 'Gerek geçmişte, gerek şimdiki zamanda çeşitli açılardan toplumumuzu etkileyen büyük olayların halk türkülerine, aydın kişinin rahatına ve dü...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hikmet']::text[], 8.5, '{"poet":"Nâzım Hikmet","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EL TUTUŞA TUTUŞA', 'el-tutusa-tutusa-can-yucel-6uxwe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kadar çok elimiz varmış meğer!
İlkin, senin elinle tutuşan benimki
Sonra çocuklarınki
Gençlerinki
Tekel İşçilerininki
Sonra, ellerin elleri...
Ne kadar çok elimiz oldu, baksana,
Tutuşa tutuşa
Bir orman yangını gibi', 'Ne kadar çok elimiz varmış meğer! İlkin, senin elinle tutuşan benimki Sonra çocuklarınki Gençlerinki Tekel İşçilerininki Sonra, ellerin elle...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELBET ANLAMI OLABİLİRDİ', 'elbet-anlami-olabi-li-rdi-ingeborg-bachmann-qoj2m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elbet anlamı olabilirdi: geçip gitmekteyiz dünyadan,
sormamışlar gelirken, çekilmeliyiz şimdi yavaştan.
Ama konuşmamıza karşın, birbirimizi anlamadan
ve karşımızdakinin ellerine bir an bile ulaşamadan,
yıkım bu işte: Çıkamayacağız bu sınavdan.
Denemek bile kalkılmaz bir şey altından,
ve bir çarmıh dikilmiş, kendimizi tanıyamadan,
yalnızlığımızda, silinip gidelim diye dünyadan.
Ingeborg BACHMANN', 'Elbet anlamı olabilirdi: geçip gitmekteyiz dünyadan, sormamışlar gelirken, çekilmeliyiz şimdi yavaştan. Ama konuşmamıza karşın, birbirimizi ...', ARRAY['Türk Edebiyatı','Şiir','Ingeborg Bachmann']::text[], 8.5, '{"poet":"Ingeborg Bachmann","poet_slug":"ingeborg_bachmann","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELBET ÖNCE TANRI SONRA AMERİKA BEN', 'elbet-once-tanri-sonra-ameri-ka-ben-edward-estlin-cummings-c4cwt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"elbet önce tanrı sonra amerika ben
seviyorum seni gezginlerin ülkesi ve diğerlerinin ey
söyle görebilir misin gün erkenden doğarken benim
yurdumda yüzyıllardır böyle gelmiş böyle gider
ve çok görme bize bunu nesine üzülmeli
her dilde hatta sağırvedilsizcede bile
oğulların alkışlar şanlı adını tanrı aşkına
vallahi billahi tallahi ağızda sakız olmuş
neyin güzelliği konuşulan kim daha güzel-
dir ki bu kahraman mutlu ölülerden
arslanlar gibi atıldılar kükreyen kırıma
durup düşünmediler bile onlar öldüler uğruna
ne yani özgürlüğün sesi mi kısılaydı?"
Adam konuştu.        Ve bir dikişte içti bir bardak suyu
Edward Estlin CUMMINGS', '"elbet önce tanrı sonra amerika ben seviyorum seni gezginlerin ülkesi ve diğerlerinin ey söyle görebilir misin gün erkenden doğarken benim y...', ARRAY['Türk Edebiyatı','Şiir','Edward Estlin Cummings']::text[], 8.5, '{"poet":"Edward Estlin Cummings","poet_slug":"edward_estlin_cummings","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELDE VAR HÜZÜN', 'elde-var-huzun-attila-i-lhan-1yhf7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'söyleşir
evvelce biz bu tenhalarda
ziyade gülüşürdük
pır pır yaldızlanırdı kanatları kahkaha kuşlarının
ne meseller söylerdi mercan köz nargileler
zamanlar değişti
ayrılık girdi araya
hicrana düştük bugün
ah nerde gençliğimiz
sahilde savruluşları başıboş dalgaların
yeri göğü çınlatan tumturaklı gazeller
elde var hüzün
o şehrâyin fakat çıkar mı akıldan
çarkıfeleklerin renk renk geceye dağılması
sırılsıklam âşık incesaz
kadehlerin mehtaba kaldırılması
adeta düğün
hayat zamanda iz bırakmaz
bir boşluğa düşersin bir boşluktan
birikip yeniden sıçramak için
elde var hüzün', 'söyleşir evvelce biz bu tenhalarda ziyade gülüşürdük pır pır yaldızlanırdı kanatları kahkaha kuşlarının ne meseller söylerdi mercan köz narg...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELELE GİTTİĞİMİZ', 'elele-gi-tti-gi-mi-z-adnan-azar-in198', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'biliyor musun giderek azalıyoruz böyle
sen bir susuşa doğru kırılarak
ben senin susuşunun ardında
nereye gitsek orada olmuyoruz
biliyor musun giderek azalıyoruz muyuz böyle
akmaktadır günler belki bunlar son rüzgârlardır
çünkü neye değsek ellerimiz yanıyor
yaz kimliksiz bir gülle orda kalakalmış
yaz kalsın orda çocukluğum ağlasın
burda bakışlarımızı sular boğmaktadır', 'biliyor musun giderek azalıyoruz böyle sen bir susuşa doğru kırılarak ben senin susuşunun ardında nereye gitsek orada olmuyoruz biliyor musu...', ARRAY['Türk Edebiyatı','Şiir','Adnan Azar']::text[], 8.5, '{"poet":"Adnan Azar","poet_slug":"adnan_azar","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EĞLEN HOCAM EĞLEN, BİR SUALİM VAR', 'eglen-hocam-eglen-bi-r-suali-m-var-karacaoglan-ibvbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğlen hocam eğlen, bir sualim var
Edep nedir erkân nedir yol nedir
Benim Karac''oğlan olduğum belli
Dede nedir abdal nedir kul nedir
Yıkılmaz Mevlâ''nın yaptığı yapı
Hak Muhammed dini, taptığım tapı
On iki bahçede kırk şekiz kapı
Eşiğin bekleyen iki kul nedir
Gayet ince derler Sırat''ın yolu
Yarın ana varanın nic''olur halı
Üç yüz altmış altı selvinin dalı
Arasında açılan iki gül nedir
İkimiz de bir göğnekte dururuz
Göğnek perde, başka başka yürürüz
Biz de anamız, evde od ururuz
Ataş nedir tütün nedir kül nedir', 'Eğlen hocam eğlen, bir sualim var Edep nedir erkân nedir yol nedir Benim Karac''oğlan olduğum belli Dede nedir abdal nedir kul nedir Yıkılmaz...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİF', 'eli-f-karacaoglan-qugng', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İncecikten bir kar yağar,
Tozar Elif, Elif deyi...
Deli gönül abdal olmuş,
Gezer Elif, Elif deyi...
Elif’in uğru nakışlı,
Yavrı balaban bakışlı,
Yayla çiçeği kokuşlu,
Kokar Elif, Elif deyi...
Elif kaşlarını çatar,
Gamzesi sineme batar.
Ak elleri kalem tutar,
Yazar Elif, Elif deyi...
Evlerinin önü çardak,
Elif''in elinde bardak,
Sanki yeşil başlı ördek
Yüzer Elif, Elif deyi...
Karac''oğlan eğmelerin,
Gönül sevmez değmelerin,
İliklemiş düğmelerin,
Çözer Elif, Elif deyi...', 'İncecikten bir kar yağar, Tozar Elif, Elif deyi... Deli gönül abdal olmuş, Gezer Elif, Elif deyi... Elif’in uğru nakışlı, Yavrı balaban bakı...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİFE GÜZELLEME', 'eli-fe-guzelleme-yusuf-altunel-hcr2h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'elif dal gibi bir kızdır
gökten aydınlığını hırsızlamış kayan yıldızdır
aşk bahçesinin rüzgarında sallanan gemici feneri
hiç yaşlanmayacakmış gibi diridir memeleri
karnı dümdüz sevişmelerden başka hayat taşımayan
sağdan sola akar da yeni suvarmış ceylan
salınır, incecik boynu
arslana yem olmayacakmış sanki
köy düğünüdür kalbinin derinlikleri
yakışıklı delikanlılar tey tey çeker
sevinçten kemerleri
gümüş mertlik işlemeli
yaprak yaprak süzülür saçları taze rüzgarda
misk taşır küflü yüreklerin güneşsiz ulaşılmamışlıklarına
gülüşü pırıltılı yansımalardır
buzlu sularda sevişen alabalıkların
çağırır cihanı öpülmemiş sevinçler paylaşmaya
sabah ışığı ile titreyen duru göllerin tazeliği teni
zaptedemez hiçbir savaşçı başkaldırınca göğüsleri
atları çıldırtan taze saman kokusu terledikçe avuçları
kendini koyvermez, şahlanır, yorulmaksızın koşar
taydan hafif nazları
elif baharla uyanmış çiçekli erik dalıdır
beyazlar içinde gelinliğe bürünmüş
sevinçlere nikahlıdır
gözleri yağmur öncesi bulutların nemini içmiş
arılar zülüflerine çiçek diye gelmiş
esrar ve nazen çekmişler, döktükleri ballar
yağmurdan sonra edepsiz topraga geçmiş
çimen sarhoşu kuzu sevinci
dökülmüş parmaklarından
ölüyü geri çağıran bahar esintisi
saçılmış göğüs uçlarından
elif yitik bir cennettir
nafiledir peşinden koşmalar
tüm bulmalar kaybetmektir', 'elif dal gibi bir kızdır gökten aydınlığını hırsızlamış kayan yıldızdır aşk bahçesinin rüzgarında sallanan gemici feneri hiç yaşlanmayacakmı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİF''İN BABASI', 'eli-f-i-n-babasi-rifat-ilgaz-rwcx3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yürekli kişiydi
Elif''in babası bir aydın kişi
Er kişi niyetine el bağladılar sağlığında
Kıblesini şaşıranlar
Amerikan gemilerine karşı diri diri
Kıldılar namazını Dolmabahçe''de
Bir öğle üzeri
Demir atmış bağımsızlığımıza
Gemiler gemiler çirkin gemiler
Kış ortasında bir güneşli pazardı
Sağdı henüz
Vardır böyle pazarlar yaşantılarımızda
Ama hiç bir pazar böylesine utanç verici
Böylesine aşağılık olamazdı çağımızda
Elif''in tutup elinden babası
Gemiler gösterecekti dizi dizi
Tutsaklığın kirli duvarlarına çizilmiş
Sonra ışıklı yüzler gösterecekti gencecik
Işıklı yüzlerde parça parça bulut
Sonra satılmışlık sonra kahpelik
Sonra yeniden sevinç yeniden umut
Sonra cop sonra şiş bıçak kanca
Benzin patlaması gaz kokusu kan
Köpekliğin köleliğin zincir şakırtısı
Ne varsa öğretecekti Elif''çiğine
Çocuklar değil miydi büyük yüzdelerle
Bütün borçlarımızı üzerlerine alan
Ne varsa tutsaklık adına öğretecekti
Ne varsa uygarlık adına sunulan
Bırakıp bütün bildiklerini bir yana
Bize alanlarda ölmesini öğretti.
(1970)
Güvercinim Uyur mu adlı şiir kitabından 1974
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Bir yürekli kişiydi Elif''in babası bir aydın kişi Er kişi niyetine el bağladılar sağlığında Kıblesini şaşıranlar Amerikan gemilerine karşı d...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELHAMDÜLİLLAH', 'elhamduli-llah-yunus-emre-53y1e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haktan gelen şerbeti içtik elhamdülillah
Şol kudret denizini geçtik elhamdülillah
Şol karşıki dağları meşeleri bağları
Sağlık sefalık ile geçtik elhamdülillah
Kuruyuduk yaş olduk ayak olduk baş olduk
Kanatlandık kuş olduk uçtuk elhamdülillah
Vardığımız illere şol sefa gönüllere
Baba  Tapduk ma''nisin saçtık elhamdülillah
Beri gel barışalım yâd isen bilişelim
Atımız eğerlendi eştik elhamdülillah
İndik Rum''u kışladık çok hayr ü şer işledik
Uç bahar geldi geri göçtük elhamdülillah
Dirildik pınar olduk ırıldık ırmak olduk
Aktık denize daldık taştık elhamdülillah
Taptuğun tapusunda kul olduk kapusunda
Yunus miskin çiğ idik piştik elhamdülillah', 'Haktan gelen şerbeti içtik elhamdülillah Şol kudret denizini geçtik elhamdülillah Şol karşıki dağları meşeleri bağları Sağlık sefalık ile ge...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇELİŞKİ', 'celi-ski-huseyin-atabas-mvtiu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm varsa anlamsızdır çelişki,
ne yolumuz belli ne yordamımız.
Senin koruduğun saçakaltı var ya
iki kırlangıç birlikte girsek
dışarda kalır leylek boynumuz!..', 'Ölüm varsa anlamsızdır çelişki, ne yolumuz belli ne yordamımız. Senin koruduğun saçakaltı var ya iki kırlangıç birlikte girsek dışarda kalır...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atabaş']::text[], 8.5, '{"poet":"Hüseyin Atabaş","poet_slug":"huseyin_atabas","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELLER İLAHİSİ', 'eller-i-lahi-si-gulten-akin-4hk1g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerini görsem oğlumun
Uzun esmer parmaklı ellerini
Onları özlüyorum
Üç yaşına yağan karda
Kızarmış, ısıttım öpe hohlaya
Ozanda el-ücra çağrışımı yapan
Alucra kışları
Bir elim elinde sabaha dek
Öteki yorganının üstünde
Üşümezdi artık örttüm sardım ya
Görsem ellerini oğlumun
Ardında bağlı durmasa
Kalmasa Alucra sisler içinde
Gevaş''a kurtlar inmese
Cano kızak yap oğluma
Uçar gider göle doğru
Çığ düşer, Artos''a salma
Ellerini görsem oğlumun
Dizgini tutarken atının üstünde
Sağrısı yelesi al ürpermede
Ferhan usul usul titrese
Ellerini görsem oğlumun
Yeşil söğüt dalını incelikle
Kuş sesleriyle değiştiğinde
Beş yaşında çalışkan ellerini
Uçtu gitti kitapların ardında
Uçtu gitti kalemlerin ardında', 'Ellerini görsem oğlumun Uzun esmer parmaklı ellerini Onları özlüyorum Üç yaşına yağan karda Kızarmış, ısıttım öpe hohlaya Ozanda el-ücra çağ...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELLERİ VAR ÖZGÜRLÜĞÜN', 'elleri-var-ozgurlugun-oktay-ri-fat-horozcu-fte6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1
Köpürerek koşuyordu atlarımız
Durgun denize doğru.
2
Bu uçuş, güvercindeki,
Özgürlük sevinci mi ne!
3
Öpüşmek yasaktı, bilir misiniz,
Düşünmek yasak,
İşgücünü savunmak yasak!
4
Ürünü ayırmışlar ağacından,
Tutturabildiğine,
Satıyorlar pazarda;
Emeğin dalları kırılmış, yerde.
5
Işık kör edicidir, diyorlar,
Özgürlük patlayıcı.
Lambamızı bozan da,
Özgürlüğe kundak sokan da onlar.
Uzandık mı patlasın istiyorlar,
Yaktık mı tutuşalım.
Mayın tarlaları var,
Karanlıkta duruyor ekmekle su.
6
Elleri var özgürlüğün,
Gözleri, ayakları;
Silmek için kanlı teri,
Bakmak için yarınlara,
Eşitliğe doğru giden.
7
Ben kafes, sen sarmaşık;
Dolan dolanabildiğin kadar!
8
Özgürlük sevgisi bu,
İnsan kapılmaya görsün bir kez;
Bir urba ki eskimez,
Bir düş ki gerçekten daha doğru.
9
Yiğit sürücüleri tarihsel akışın,
İşçiler, evren kovanının arıları;
Bir kara somunun çevresinde döndükçe
Dünyamıza özgürlük getiren kardeşler.
O somunla doğrulur uykusundan akıl,
Ağarır o somunla bitmeyen gecemiz;
O güneşle bağımsızlığa erer kişi.
10
Bu umut özgür olmanın kapısı;
Mutlu günlere insanca aralık.
Bu sevinç mutlu günlerin ışığı;
Vurur üstümüze usulca ürkek.
Gel yurdumun insanı görün artık,
Özgürlüğün kapısında dal gibi;
Ardında gökyüzü kardeşçe mavi!', '1 Köpürerek koşuyordu atlarımız Durgun denize doğru. 2 Bu uçuş, güvercindeki, Özgürlük sevinci mi ne! 3 Öpüşmek yasaktı, bilir misiniz, Düşü...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":56}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELLERİME SIĞMAYAN', 'elleri-me-sigmayan-meti-n-findikci-winj3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırık bir testidir eşikte duran.
Ovaya yayılan acı bir sudur.
Oysa sığmaz gecenin gözleri yanan
mumlara, ellerime sığmaz
bir yara içinde büyüyorum
akan suyun tadı kaplanın gözlerinde durur
gitgide organlarıma karışıyor talan edildikçe kadim yerler.
Mumlarda tükenen gecenin gözlerine bakıyorum
sen büyüyen bir fısıltıyla çıkıyorsun
geceden gündüze
dağılan nar tanelerini örtüyorsun
karanlıktan aydınlığa açılıyorsun.
Çocuk giysiler içinde mavi bir gecede
ağaç dibinde telaşlı bir karınca yuvasında
koyu ve diri kokunu duyuyorum.
Ellerimde suyun
asi yüzü
kınında terli
bir bıçak.', 'Kırık bir testidir eşikte duran. Ovaya yayılan acı bir sudur. Oysa sığmaz gecenin gözleri yanan mumlara, ellerime sığmaz bir yara içinde büy...', ARRAY['Türk Edebiyatı','Şiir','Meti̇n  Findikçi']::text[], 8.5, '{"poet":"Meti̇n  Findikçi","poet_slug":"metin_findikci","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELLERİMİZ GİBİ', 'elleri-mi-z-gi-bi-melih-cevdet-anday-i6l91', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayvanlar konuşmadıkları için
Kimbilir ne güzel düşünürler,
Tıpkı ellerimiz gibi.
Ah, okumaya başlamadan önce
Çiçeklere su vermek lazımdır.', 'Hayvanlar konuşmadıkları için Kimbilir ne güzel düşünürler, Tıpkı ellerimiz gibi. Ah, okumaya başlamadan önce Çiçeklere su vermek lazımdır....', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELLERİN AVUCUMDA İKİ ATEŞDAMLASI', 'elleri-n-avucumda-i-ki-atesdamlasi-nihat-behram-d4pfe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'DAMLASI
Çiçeğinde
yeni yeni kamaşan zerdalisi ömrümün,
gülüşümde çekirdeği sertleşmemiş ilk çağlam,
kızım benim, nazım benim,
gurbetelde sazım benim,
yalazlanmış can tanem,
körpe dalım bir tanem..
Sisini gözlerimin, içimdeki dumanı
seziverdin de sanki
acılandın uykunda,
sızlandın huysuzlandın..
Dudakların kurumuş, ter içindesin yavrum!
Kolsuz kanatsız kalmış
geceden beri başucundayım..
Çırpınarak anlamını arayan binlerce sözcük
kabukları koparılmış yaralar gibi
uğulduyor beynimde..
itiraf etmeliyim ki yavrum
çekip gitse de bir bir
ekmeğe, özgürlüğe, insanlık ve hayata dair
içimi dişleyen düşünceler,
senin bir gülücüğün şimdi
yaşamam için bana yeter.
Geceden beri başucundayım..
İşte, sabaha dayandı gün!
Aşsız, işsiz, kuruşsuz
bir ıssız bayırdayım.
Bebeğim, canımın kıvırcığı,
boranda fırtınada sürgün vermiş tomurcuk,
üzüm tanem, nar tanem,
acar yanım, bir tanem..
Kim kime, dum duma bir tufandayız;
günlerin ağzında kara bir gül
dikenleri tenimize dayanmış;
ürkütülmüş, sarılmış, acıyla
sınanmışız..
İnim inim uykunda nasıl da yalnız
yanıyor yüzün yavrum,
yüreciğin kaşlarında tütüyor,
ellerin avcumda iki ateş damlası,
tutuşmuş rüyaların, sesin duyulmaz,
kendi kollarımızdan başka
saranımız yok bizim..
Yazım benim, güzüm benim,
yemin olmuş sözüm benim;
sana kuş bulmalıyım
sana düş bulmalıyım
gidip iş bulmalıyım..
Koynunda çırpınırken böyle çaresiz
kahrınla tanıştırdın bizi ey hayat
zehrinle tanıştırdın;
alışılmaz bildiğimiz nefrete alıştırdın!
Onurumuz:
senin için sakladığım tek servetim bu yavrum;
süt olmaz, aş olmaz, iş olmaz onurumuz..
sızım benim, gizim benim,
gurbetelde izim benim;
ateş almış taş altında kalmışız,
gün olur hesabını sorarız elbet.
Nihat', 'DAMLASI Çiçeğinde yeni yeni kamaşan zerdalisi ömrümün, gülüşümde çekirdeği sertleşmemiş ilk çağlam, kızım benim, nazım benim, gurbetelde saz...', ARRAY['Türk Edebiyatı','Şiir','Nihat
behram']::text[], 8.5, '{"poet":"Nihat\nbehram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":63}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİMİ ÇEKEN EL', 'eli-mi-ceken-el-berin-tasan-igs07', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Omzundan havalanan martılar
Konacak yer bulamıyor
Önümde bir çam
Bir apartman
Sarmaşıklı sokağın solundan
Biraz sonra bir motor indireceğim denize
Biraz sonra ayak sesleri..
Açıktan trançaların yuvalarından
Seni çeke çeke getirdim kıyılara
İzmir Körfezi biraz açılsın
Elimden düşen yüzük görünsün diye.
Küçükyalı''da bir pencereden bakılınca
O martılar mı senin omzundan havalandı
Şimdi bir yerlere konamıyorlar.', 'Omzundan havalanan martılar Konacak yer bulamıyor Önümde bir çam Bir apartman Sarmaşıklı sokağın solundan Biraz sonra bir motor indireceğim ...', ARRAY['Türk Edebiyatı','Şiir','Berin Taşan']::text[], 8.5, '{"poet":"Berin Taşan","poet_slug":"berin_tasan","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇELİM!', 'i-celi-m-rifat-ilgaz-altgf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte bir aradayız!
Sağlığından haber beklediklerimiz yanımızda,
Ve aramızda uzun zamandır
Yüzünü görmediklerimiz!
Kimimiz mahpustan dönmüşüz
Kimimiz sürgünden!
Bu akşam keyfimiz yerinde,
Günlük dertlerimizden sıyrılmışız,
Nasıl kazanıldığını unutmuşuz paranın
Elimiz o kadar açık;
Harcayalım neşemiz için!
İyisi gelsin şarabın,
Yüklü olsun mezeler!
Nöbetçisiz geçiyor akşamımız demek,
Kilitsiz, demir parmaklıksız;
İstersek burda keser konuşmamızı,
Çıkarız kol kola, kelepçesiz.
Dolaşırız canımızın çektiği sokakta.
Özlemini çekmişiz uzun zaman
Dostların ve aydınlığın.
Duymuşuz her çeşit yanızlığı
Tek başımıza.
İki çift lâf etmenin karşılıklı,
Ne demek olduğunu öğrenmişiz.
Konuşalım,
Bir suç olduğunu bilerek her sözümüzün.
Güzel günlerin yaklaştığını söyleyelim,
Dört yanımızı kollayarak.
Ne olacak, bilir miyiz birazdan?
Belki hesabı sorulacak neşemizin.
Kaldıralım son kadehleri,
Ayrılalım arkadaşlar,
Ayrılırken öpüşelim!
Yaşadıkca adlı şiir kitabından 1948
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'İşte bir aradayız! Sağlığından haber beklediklerimiz yanımızda, Ve aramızda uzun zamandır Yüzünü görmediklerimiz! Kimimiz mahpustan dönmüşüz...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİN BOZUĞU', 'eli-n-bozugu-mustak-erenus-i6l53', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen karanlıkta hiç türkü söyledin mi
Türkü söyledin mi hiç karanlığa
Hiç yemin ettin mi gönülden
Katıldın mı bir inanca
Yürek dolusu binlerle
Hiç sevdin mi ha
Sevdin mi?
Hadi be.', 'Sen karanlıkta hiç türkü söyledin mi Türkü söyledin mi hiç karanlığa Hiç yemin ettin mi gönülden Katıldın mı bir inanca Yürek dolusu binlerl...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİNDE SENİN', 'eli-nde-seni-n-sukran-kurdakul-msiz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında bir yol bul
Sokağımı ara, yokuşumdan in
Gölgemi görürsen penceremi vur
Anıların feneri elinde senin.
Bezginlik mi saran kentimi,
Burama kadar dayandı işte...
Mağaralara kapanmış gördüm kendimi
Haramiler arasında bütün gece.
Neyi bildik acılarla gelen,
Kapattı kapımı, penceremi...
Işığını söndürdü, tuttu elimden,
Sayrılıksa bu, n''apacağı belli mi?
Gecenin karanlığında bir yol bul
Sokağımı ara, yokuşumdan in.
Gölgemi görürsen penceremi vur,
Umarların feneri elinde senin.', 'Gecenin karanlığında bir yol bul Sokağımı ara, yokuşumdan in Gölgemi görürsen penceremi vur Anıların feneri elinde senin. Bezginlik mi saran...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELİNLE', 'eli-nle-sabahattin-kudret-aksal-xs3rs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle sabahların aydınlığı otların ışıyışı seninle
Sonsuzlukta arınmış ovada çığlıkları koşup giden atların
Kirimi pasımı suyu sabunu sol bir teknede yudun yıkadın
Aldın kaba doğayı düzenledin yeni baştan bir güzel elinle
Su kuşlarıyla allı pullu donanma fenerleriyle ardıçlarla
Bezedin düşsel gelinler örneği bir boydan öbür uca evreni
Adım atmak yeniydi seninle uyumak uyanmak solumak yeni
Mutlulukların çiçek açan denizi göz gördüğünce giden tarla
Kanat vurur başının üstünde döner durmadan bir mavi güvercin
Aydınlığında gecemin boy atan yabancıl bitkilerime azık
Yaşantımı sürdürme gücüm benim günüm geceme düşen ışık
Özgür dileğim kara ağaçlar değin köklü ölüm isteğim', 'Seninle sabahların aydınlığı otların ışıyışı seninle Sonsuzlukta arınmış ovada çığlıkları koşup giden atların Kirimi pasımı suyu sabunu sol ...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"sabahattin_kudret_aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELOĞLU', 'eloglu-metin-eloglu-tx4sd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eloğlu binlik bozdurur
Ben bozduramam
Eloğlu başını yastığa kor komaz uyur
Ben uyuyamam
Eloğlu sofrasında dokuz türlü
Benim aç yattığım olur bazen
Benim evim gecekondu
Eloğlunda apartıman
Eloğlunda ince müzik
Benimkisi aman aman
Benim kuru başım bana yeter
Eloğlunda karı kızan
Ben keçileri kaybettim
Eloğlunda usta çoban
Bu soyadı bana haram', 'Eloğlu binlik bozdurur Ben bozduramam Eloğlu başını yastığa kor komaz uyur Ben uyuyamam Eloğlu sofrasında dokuz türlü Benim aç yattığım olur...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin_eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EĞİLİP SUYUNU İÇTİĞİMİZ ÇEŞME', 'egi-li-p-suyunu-i-cti-gi-mi-z-cesme-mehmed-kemal-i7nyc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani büyük korkular başlayınca insanda,
Sıkılır yüreği, ölecek gibi olur;
Ne dost sevgisi, ne yar sevgisi,
Ne varsa hepsini bırakıp gitmek ister
Nereye, kime, niçin? Demeden.
Ölüme benzer, ölüme yakın,
Bir şeyler duyar içinde açıklayamaz,
Yumuşak, yavaş, ılık
Nerdeyse uzatsa elini dokunacak,
Belli, besbelli kumaş gibi,
Yorumlanamayan, birikmiş, toplu,
O bildiğimiz düşüncele benzeyen
Birçok sorulardan örülmüş;
Kırmızı mı, mavi mi, yeşil mi?
Ne idüğü belirsiz gibi görünen
Her şeye yakın, aşk içinde
Yaşama gibi, macera kıvamında,
Sevilen, tapılan, yanıp yakınılan
Nerdeyse yanıbaşında, selam verecek
O, omzuna dokunup geçen,
Akşamları çileden çıkaran
Her şeyi büyük azgınlığına alıştıran
Bizim bildiğimiz, bizim duyduğumuz,
Yayan yapıldak peşinde koştuğumuz,
Bozlağa, uzunhavaya, mayaya benzer,
Bir Anadolu türküsü, yanık, hazin
Eğilip suyunu içtiğimiz çeşme...', 'Hani büyük korkular başlayınca insanda, Sıkılır yüreği, ölecek gibi olur; Ne dost sevgisi, ne yar sevgisi, Ne varsa hepsini bırakıp gitmek i...', ARRAY['Türk Edebiyatı','Şiir','Mehmed Kemal']::text[], 8.5, '{"poet":"Mehmed Kemal","poet_slug":"mehmed_kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELSA''NIN GÖZLERİ', 'elsa-nin-gozleri-louis-aragon-5tmq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle derin ki gözlerin içmeye eğildim de
Bütün güneşleri pırıl pırıl orada gördüm
Orada bütün ümitsizleri bekleyen ölüm
Öyle derin ki herşeyi unuttum içlerinde
Uçsuz bir denizdir bulanır kuş gölgelerinde
Sonra birden güneş çıkar o bulanıklık geçer
Yaz meleklerinin eteklerinden bulutlar biçer
Göklerin en mavisi buğdayların üzerinde
Karanlık bulutları boşuna dağıtır rüzgâr
Göklerden aydındır gözlerin bir yaş belirince
Camın karılan yerindeki maviliğini de
Yağmur sonu semalarını da kıskandırırlar.
Ben bu radiumu bir pekbilent taşından çıkardım
Benim de yandı parmaklarım memnu ateşinde
Bulup bulup yeniden kaybettiğim cennet ülke
Gözlerin Peru''mdur benim Golkond''um Hindistan''ım
Kâinat param parça oldu bir akşam üzeri
Her kurtulan ateş yaktı üstünde bir kayanın
Gördüm denizin üzerinde parlarken Elsa''nın
Gözleri Elsa''nın gözleri Elsa''nın gözleri.
Louis ARAGON', 'Öyle derin ki gözlerin içmeye eğildim de Bütün güneşleri pırıl pırıl orada gördüm Orada bütün ümitsizleri bekleyen ölüm Öyle derin ki herşey...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis_aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELVEDA SEVGİLİ DOSTUM', 'elveda-sevgi-li-dostum-sergey-yeseni-n-vmaci', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elveda sevgili dostum elveda,
Sen kökleri içimde uzanan..
Ayrılık yazılmış alnımıza
İlerde gene karşılaşırız inan..
Elveda dostum, el sıkışmadan
Sessizce.. Ne keder ne tasa gerek:
Ölmek yeni bir şey değildir bu dünyada
Ama yaşamak da yeni bir şey olmasa gerek.
Sergey YESENİN', 'Elveda sevgili dostum elveda, Sen kökleri içimde uzanan.. Ayrılık yazılmış alnımıza İlerde gene karşılaşırız inan.. Elveda dostum, el sıkışm...', ARRAY['Türk Edebiyatı','Şiir','Sergey Yeseni̇n']::text[], 8.5, '{"poet":"Sergey Yeseni̇n","poet_slug":"sergey_yesenin","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EMANUEL KARASU EFENDİ SÜRGÜNDE', 'emanuel-karasu-efendi-surgunde-roni-margulies-u7h5f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başmabeyincisinin anılarında okumuştum.
&quot;Yıldız''a gelen Heyet-i Mebusan''dan
Emanuel Karasu''yu hiç unutamıyorum.
En çok&quot; demiş Hamit, &quot;bana dokunan,
o mason taslağı Yahudi''nin
bildirmesi olmuştur devrildiğimi.&quot;
Ben de unutamam o mutlu günleri!
Hemen ilk toplantısında Meclis''in,
31 Mart olayları yatıştıktan sonra,
hal'' kararı alınmıştı Abdülhamit''in.
Seçilen heyette kararın tebliği için saraya
Draç Mebusu Esat Paşa, Ayan''dan Hikmet,
Aram Efendi, bir de ben vardım.
Tanrım, heyecanımdan ölüyorum sandım!
Dava vekilliği günlerimde Selanik''te,
Mithat Şükrü, Cavit ve Talât''la
oturup akşamüzerleri Cemiyet''te,
tam da bu günü düşlemiştik adeta.
İşte, bizim oluyordu Dersaadet,
nihayet kavuşuyorduk hürriyete.
Ve ben bildirecektim bunu Hamit''e!
İstanbul''da kalmak istiyordu,
Çırağan''da otururum dedi, rica etti,
bırakmadık, sürgüne gitmesi daha uygundu.
Apar topar Selaniğe gönderildi.
Birkaç yıl sonra da öldü gitti zaten.
Düşünün, o günü nasıl unutabilirim?
Ben ki on yıldır kendim sürgündeyim!', 'Başmabeyincisinin anılarında okumuştum. &quot;Yıldız''a gelen Heyet-i Mebusan''dan Emanuel Karasu''yu hiç unutamıyorum. En çok&quot; demiş Hami...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇEMBER', 'cember-rifat-ilgaz-glpkc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Büyük kentlerde artık
Çocuklar çember çevirmiyorlar…
Yazık!
Sokaklar tıklım tıklım
Çocuklara yer yok ki çevirsinler
Ama büyüklerin altında dört teker
Bir gidip bir geliyorlar!
İş mi yaptıkları sanki!
Belki iş… Kim bilir,
Belki de gösteriş…
Nerde bu hoyratça dönen tekerlekler
Gösteriş için…
Nerde o başımızı döndüren
Şıkır şıkır çemberin güzelliği!
Kulağımız Kirişte  adlı şiir kitabından 1983
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Büyük kentlerde artık Çocuklar çember çevirmiyorlar… Yazık! Sokaklar tıklım tıklım Çocuklara yer yok ki çevirsinler Ama büyüklerin altında d...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EMEĞİN ÖYKÜSÜ', 'emegi-n-oykusu-sukran-kurdakul-onj7q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kitaplar ellerimle öykülendi
Düşlerim vurdu şiirler denizine
Eski ezgilerle coşkulanan
Sesimdir, çağları delip geldi.
En güzelle en yaşayan
Gözlerimden aldı rengini
Meriç köprülerinde
Alın terim karıştı suya
Santim santim ellerimde büyüdü
Süleymaniye ve Aya Sofiya.
Kaç iklimin toprağı bağrına bastı beni
Ustalığıma kefil olur tarihler,
Kaç dönem içimde savaş verdi.
Utkularım çağımın türküsünü söyler,
O türküler tezgâhında dönüyor şimdi.', 'Kitaplar ellerimle öykülendi Düşlerim vurdu şiirler denizine Eski ezgilerle coşkulanan Sesimdir, çağları delip geldi. En güzelle en yaşayan ...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EMİNE', 'emi-ne-necati-cumali-5ubet', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Abanoz''daki Emine
On yedisinde düştü
Afro''nun eline
Şimdi yaşı yirmi bir
Eridi gitti dört senede
İpek saçları, vücudu bozuldu
Ela gözlerinin ateşi söndü
Kalmadı eski neşesi
Alıştı zamanla küfre, tütüne
Zamanla etrafına uydu
Isındı evin âdetlerine
O içimizden birinin kızı
Birinin kardeşi
Âşık birine', 'Abanoz''daki Emine On yedisinde düştü Afro''nun eline Şimdi yaşı yirmi bir Eridi gitti dört senede İpek saçları, vücudu bozuldu Ela gözlerinin...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞEMSİYE', 'semsi-ye-sunay-akin-vohzs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tozlu bir şemsiye durur
çatı katındaki odanın
kuytu bir köşesinde
kumaşındaki eski yağmurların
hüzünlü kokusuyla
anımsar mısın bilmem
yağmurun bardaktan
boşanırcasına yağdığı o günü
hani şemsiyeyi iyice çekip başımıza
dudaklarımla hesaplamıştım
yüz ölçümünü
nicedir sokağa çıkarmıyorum
şemsiyeyi
korkuyorum çünkü
kapısı açık kafesinden
uçan bir kanarya gibi
beni ikinci kez terk etmenden
yanıt alamayacağımı bilsem bile
yanına gidip
sorarım hergün şemsiyeye
altında elele
nasıl görünürdük diye', 'tozlu bir şemsiye durur çatı katındaki odanın kuytu bir köşesinde kumaşındaki eski yağmurların hüzünlü kokusuyla anımsar mısın bilmem yağmur...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akin']::text[], 8.5, '{"poet":"Sunay Akin","poet_slug":"sunay_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞEMSİYELİLER', 'semsi-yeli-ler-kemal-ozer-nym7d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İncecik bir ilkyaz yağmuru
altında yürüyen şemsiyeliler
o kadar güveniyoruz ki birbirimize
dinip dinmediğini anlamak için yağmurun
bakacağımız yerde bir cama, bir su birikintisine
bakıyoruz birbirimizin şemsiyesine.', 'İncecik bir ilkyaz yağmuru altında yürüyen şemsiyeliler o kadar güveniyoruz ki birbirimize dinip dinmediğini anlamak için yağmurun bakacağım...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EN GÜZEL BEN ÖLÜRÜM!..', 'en-guzel-ben-olurum-bulent-ozcan-76z01', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Böyle umut doluyken tepeden tırnağa
Böyle seviyorken seni amansız
Böyle değerliyken
Böyle yüceyken sevda
En güzel ben ölürüm
K e s i n!..', 'Böyle umut doluyken tepeden tırnağa Böyle seviyorken seni amansız Böyle değerliyken Böyle yüceyken sevda En güzel ben ölürüm K e s i n!.....', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EN GÜZEL KIZIL', 'en-guzel-kizil-onan-gunoz-a2s0n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'parlak imgeler satılıyor köşebaşlarında
her avuç açana gelecek vaat ediyor falcılar
medyatik serseriler bağırıyor hep bir ağızdan
"cebimde metelik yok ama… yırtıcı bir imajım var"
çalıntı sözcükler satılıyor kuytu masalarda
ve şampuanını değiştiren herkese
mutluluk vaat ediyor reklamlar
fonda Karl Marx, elinde bir fırça
"en güzel kızıl, bizim boyada"', 'parlak imgeler satılıyor köşebaşlarında her avuç açana gelecek vaat ediyor falcılar medyatik serseriler bağırıyor hep bir ağızdan "cebimde m...', ARRAY['Türk Edebiyatı','Şiir','Onan Günöz']::text[], 8.5, '{"poet":"Onan Günöz","poet_slug":"onan_gunoz","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EN GÜZELİ ŞİİRLERİN', 'en-guzeli-si-i-rleri-n-bulent-ozcan-99sry', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözcükler değil ama
O''nu bana bir ana
doğurdu
En güzeli şiirlerin
Canım kızım Şiirsu!
Işığı düşüncemin
H
o               .
ş            .
g         .
e      n
l   i
d', 'Sözcükler değil ama O''nu bana bir ana doğurdu En güzeli şiirlerin Canım kızım Şiirsu! Işığı düşüncemin H o               . ş            . g ...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EN UZUN MARATON', 'en-uzun-maraton-aziz-nesi-n-9gbg3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüz metrede beni herkes geçer
Dörtyüz metrede pekçokları
Geçer çoğu sekizyüz metrede
Ama ben bırakmam yarışı
Beni bin metrede geçersin
Ben yine koşarım
Onbin metrede öndesin
Koşarım ben yine
Yirmi kilometrede geçersin
Hep koşmaktayım
Otuz kilometrede
Kırk kilometrede de geçersin
Ben koşuyorum hâlâ
Ama ellinci
Yada altmışıncı kilometrede
Soluğun tükenip bir yerde
Dayanamaz düşersin
Bak koşuyorum hâlâ
Çünkü ben bir yaşam maratoncusuyum
Buyüzden yaşamın en yalnızıyım
Bu sonsuz yarışın sonunda
Beni geçemezsin
Ölümün en büyük ödül olduğunu bilemezsin
Yine ben olurum ilk göğüsleyen ölümü', 'Yüz metrede beni herkes geçer Dörtyüz metrede pekçokları Geçer çoğu sekizyüz metrede Ama ben bırakmam yarışı Beni bin metrede geçersin Ben y...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ENDÜLÜS''TE RAKS', 'endulus-te-raks-yahya-kemal-beyatli-lza2r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zil, şal ve gül. Bu bahçede raksın bütün hızı...
Şevk akşamında Endülüs üç defa kırmızı...
Aşkın sihirli şarkısı yüzlerce dildedir.
İspanya neş''esiyle bu akşam bu zildedir.
Yelpaze çevrilir gibi birden dönüşleri,
İşveyle devriliş, saçılış, örtünüşleri...
Her rengi istemez gözümüz şimdi aldadır;
İspanya dalga dalga bu akşam bu şaldadır.
Alnında halka halkadır aşüfte kâkülü,
Göğsünde yosma Gırnata''nın en güzel gülü...
Altın kadeh her elde, güneş her gönüldedir
İspanya varlığıyla bu akşam bu güldedir.
Raks ortasında bir durup oynar, yürür gibi;
Bir baş çevirmesiyle bakar öldürür gibi...
Gül tenli, kor dudaklı, kömür gözlü, sürmeli...
Şeytan diyor ki, sarmalı, yüz kerre öpmeli...
Gözler kamaştıran şala, meftun eden güle,
Her kalbi dolduran zile, her sineden: "Ole!"', 'Zil, şal ve gül. Bu bahçede raksın bütün hızı... Şevk akşamında Endülüs üç defa kırmızı... Aşkın sihirli şarkısı yüzlerce dildedir. İspanya ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ENVER GÖKÇE', 'enver-gokce-enver-gokce-5hsrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadersizdi
Kadersizliği
Ölümünden sonra da devam etti
Natalie Wood ile
Aynı günlerde ölmeseydi
TRT''de ona da sıra gelecekti
Bir ağlayan
Eğin türküleriydi
Ona da şükretsindi', 'Kadersizdi Kadersizliği Ölümünden sonra da devam etti Natalie Wood ile Aynı günlerde ölmeseydi TRT''de ona da sıra gelecekti Bir ağlayan Eğin...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EPITAPH    I', 'epitaph-i-devrim-di-rli-kyapan-d1dyp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uykudan öncesi çocukluğumuzdu
büyümeye inat süren evcilik oyunlarına
ebe yaptığımız o masal çocukları
iple çekerdik gün batışlarını
ki dadısı adile naşit olan
bir masumluk esnerdi akşamları
akşamlar zoraki uykularla gelirdi oysa
ve hep uykular öncesinde kalırdı masallar
binlerce uyur binlerce kaybederdik
&quot;uçan kaz ve nils&quot;le gezdiğimiz ülkeleri
sonra büyümüştük ya da öyle saymışlardı
alice''in diyarına alınmıyorduk artık
egzotik bulunan bir sislenişti orası
ve unutmuştuk polyanna mıydı sahiden
yalın mutlulukların emektar perisi
simbad da vazgeçmişti düşlerimizden
anıların biriktiği denizlere açılıyordu
bizse yüreğimiz guruldarken
ve hızla &quot;çizgi&quot;sini yitirirken filmlerimiz
yalnızca harçlık biriktirmeyi öğreniyorduk
çocukleyin üzerine çıktığımız ağaçlar bile
saç dökme mevsimlerindeydi artık
kimileri masalsız uyumuşlardı ama
biz uykularımızın deliklerinden kaçırmıştık
sayıklamıyorduk', 'uykudan öncesi çocukluğumuzdu büyümeye inat süren evcilik oyunlarına ebe yaptığımız o masal çocukları iple çekerdik gün batışlarını ki dadıs...', ARRAY['Türk Edebiyatı','Şiir','Devrim Di̇rli̇kyapan']::text[], 8.5, '{"poet":"Devrim Di̇rli̇kyapan","poet_slug":"devrim_dirlikyapan","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇER DIŞLAR', 'i-cer-dislar-umut-taydas-8b27z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içeri hayat kurgu / dışarı hayat belli.
erdem kesmelerin ekstresi uykusuz
cingıl pozlara vesile izmarit
yerler soğuk, buz.
kendimizin yankısı onlar
peşinden gidersen ulaşamazsın
o da seni arıyor, bekle, yerinde,
dönüp doğacağı yer yine kendinsin
hem yürümeye adım lazım
yerler buz, sebep tek.
dışarı hayat, oyun / içerinin aynısıyız
ama çık bakalım dışarı, ne bulacaksan,
yaman oğlan, truman.
menzilde sorun var, herkes oynak,
nükleer iskambil fallar
zehirliyor kaderleri.
bünyeler harman olmuş,
eller, diller zıkkım bulaştırıyor,
yine de can atmıyorum, bil ki satmıyorum,
bizzat dayanamam da,
bir bok yedim ki:hayatım bulanıyor,
karnımda meşk sancısı
el veremiyorum.
ne var ki,
borges''un gözü kör;shakespeare''nin götü delik;van gogh''un kulağı kesik;byron topal,
ve ben, seni seviyorum.', 'içeri hayat kurgu / dışarı hayat belli. erdem kesmelerin ekstresi uykusuz cingıl pozlara vesile izmarit yerler soğuk, buz. kendimizin yankıs...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇERDE', 'i-cerde-orhan-veli-bxruu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pencere, en iyisi pencere;
Geçen kuşları görürsün hiç olmazsa;
Dört duvarı göreceğine', 'Pencere, en iyisi pencere; Geçen kuşları görürsün hiç olmazsa; Dört duvarı göreceğine...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇERDEN IŞIYABİLMEK', 'i-cerden-isiyabi-lmek-tahsin-sarac-6z5i6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin gözlerin mavi
Nerden ve ne sürem baksan
Yıkanır göğün çividi.
Bir filinta genç asılmış gibi acılı bir gece
Bir dağ ozan öldürülmüş gibi allak bullak.
Kanara kaçkını bir susku
Uyusam, kirlenecek uyku.
Ve yakılmış kitap külü döküklüğünde bir duygu
Çiçek ezmiş pis bir pabuç gibi umursamaz, kör.
Işığın kötücül bir uru
Lamba, bir en deligöz namlu.
Duvar delen bir bungunluk, ama içim yeşil başak
Bin demire baskın işte benim evrensığmazlığım.
Ak bir alın, silen korkuyu
Bir sevgi, ışıyan tan boyu.
Senin gözlerin kara
Nerden ve ne sürem baksan
Yıldız ağar karanlığa.', 'Senin gözlerin mavi Nerden ve ne sürem baksan Yıkanır göğün çividi. Bir filinta genç asılmış gibi acılı bir gece Bir dağ ozan öldürülmüş gib...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Saraç']::text[], 8.5, '{"poet":"Tahsin Saraç","poet_slug":"tahsin_sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EĞRELTİOTU', 'egrelti-otu-i-lhan-berk-u55g4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hoşça kal, dedi, eğreltiotu, hoşça kal!
Delta ve Çocuk', 'Hoşça kal, dedi, eğreltiotu, hoşça kal! Delta ve Çocuk...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ERENKÖYÜ''NDE BAHAR', 'erenkoyu-nde-bahar-yahya-kemal-beyatli-7jok3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cânan aramızda bir adındı,
Şîrin gibi hüsn ü âna unvan,
Bir sahile hem şerefti hem şan,
Çok kerre hayâlimizde cânan
Bir şi''ri hatırlatan kadındı.
Doğmuştu içimde tâ derinden
Yıldızları mâvi bir semânın;
Hazzıyla harâb idim edânın,
Hâlâ mütehayyilim sadânın
Gönlümde kalan akislerinden.
Mevsim iyi, kâinât iyiydi;
Yıldızlar o yanda, biz bu yanda,
Hulyâ gibi hoş geçen zamanda
Sandım ki güzelliğin cihanda
Bir saltanatın güzelliğiydi.
İstanbul''un öyledir bahârı;
Bir aşk oluverdi âşinâlık...
Aylarca hayâl içinde kaldık;
Zannımca Erenköyü''nde artık
Görmez felek öyle bir bahârı.', 'Cânan aramızda bir adındı, Şîrin gibi hüsn ü âna unvan, Bir sahile hem şerefti hem şan, Çok kerre hayâlimizde cânan Bir şi''ri hatırlatan kad...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ERGİN GÜNÇE', 'ergi-n-gunce-ergi-n-gunce-p4lcq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çok geç duydum uzak gurbette:
Esenboğa yemiş canlarımızı,
Ateş düştü, yüreğimde koptu tel,
Can dayanmaz, donar kan,
Sisten başka yok mu sorumlu?
Bir türlü varmıyor demeye dilim,
Yüz binlerde seçkindi usuyla,
Yalan, al bulunmazdı işinde
Işık içindeydi çevresi "Günce"
Çam dalını okşarken sevgi dolu
"Buraların altı denizce su" diyordu.
Kördüğümleri çözerdi kıvrak zekası,
Ak güvercinler uçardı gözlerinden.
Bilgin, ozan yetenekli insan,
Yarım kaldı düşleri, kitapları
Yiğit, dost bir yıldız daha kaydı.', 'Çok geç duydum uzak gurbette: Esenboğa yemiş canlarımızı, Ateş düştü, yüreğimde koptu tel, Can dayanmaz, donar kan, Sisten başka yok mu soru...', ARRAY['Türk Edebiyatı','Şiir','Ergi̇n Günçe']::text[], 8.5, '{"poet":"Ergi̇n Günçe","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ERİK AĞACININ ALTINDA', 'eri-k-agacinin-altinda-berrin-tas-senui', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kent neyi anlatır
kanat çırpışlarıyla gelir
bilmediğin bir yaşama doğarsın
kuytularda
kimsesizliğin tarihi yazılır
kimbilir
hangi sancının kıyısında
çağırır seni toprak
kimi kentler meyveleri anımsatır
Malatya denince
yemeye hazır
bir tabak kayısı.
İsmet''in muzip gülüşüyle canlanır
Kayseri
çocukluk anılarımla gelir
üzüm bağları
kayısı ağaçları
mayhoş elmalar arasında
dedemin sevecen yüzü
Antakya
arkadaşlığın kalesidir
Müslüm Cuma Zübeyde
yağmurlu akşamlarla gelir
Ankara''da bir kadın
kardeşim
gelinliğini kıracak
tırnaklarını ekmek parasına batırdı
kimi kentler
depremlerle kazınır evrene...
yer sarsılıyor
tutunacak ne bir dal
ne kaçacak
bir başka gezegen
uyandı
dağ taş uyandı
ayağını bastığın toprak
konuşuyor dalgalarla
çığlıklar sustu
sessizlik
derin
ağır
sessizlik korkunç
sessizlik gebe
Ulucanlar...
hapisaneler örter kimi kentleri
Gebze...
gökyüzü demir halkalarla
güneşi parçalar
Ümraniye...
ağır ağır kanar
bulutlarda yağmur damlası
kepçelerle
tarihin belleğine çizilen
bir fotoğrafa dönüştü Burdur
kepçelerle avlandı bir kol
gövdesinden ayrıldı
Isparta''da
bir köpeğin ağzında
koparılmış bir kol
donar bilinçte
çatlak kafatası
çivilenmiş dizler
morarmış gövdelerle
bir sancı
güneşe
aya
toprağa yayılmış
Sivas''tan Burdur''a
ağıt yakar analar
söyleyin
nasıl dayanmalı bu acıya
biz bu kentlerde doğduk
inildemelerle
bir başka gökyüzüne
oğullar
kızlar doğurduk
aşkı yitirdik
yağmurun alnında
yas türküleri söyleniyor
damla damla yaşama biriken
ezgilerle avunuyorum
yitirdik
yitirdik aşkı
sessizliğin dili yok
beklemek
umarsız bir çığlığın
susmasını dilemektir
dileyişlerin
sokağa açılan penceresi yok
üzünçlerimi biriktirdim
yas tutacağım
türkülerle
şiirlerle
bedenimle yas tutacağım
ötelerde
bir başka gökyüzü
bereketli yağmurlara gebe', 'Bir kent neyi anlatır kanat çırpışlarıyla gelir bilmediğin bir yaşama doğarsın kuytularda kimsesizliğin tarihi yazılır kimbilir hangi sancın...', ARRAY['Türk Edebiyatı','Şiir','Berrin Taş']::text[], 8.5, '{"poet":"Berrin Taş","poet_slug":"berrin_tas","theme":"Türk Şiiri","is_hero":false,"total_lines":99}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇERİK', 'i-ceri-k-tudor-arghezi-dorw4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprak, tarlalar, hasatlar,
Hepsi benim omuzlarımda,
İnsanlar, sürüler ve hayvanlar,
Saban izleri,
Daracık yollar ve saz damlar.
Sis, yağmur ve rüzgâr
Hıçkırıklar, korku ve acı.
Nasıl sığdı içime ülkem?
Nasıl toplandı her şey üzerinde küreğin?
Ormanlar nasıl toplandı köhne vazoda?
Ve bütün deniz bir su bardağında?
Ben de
Aynı çamurdanım onlarla,
Hepimiz paçasıyız Tanrı'' nın.
Tudor ARGHEZI', 'Toprak, tarlalar, hasatlar, Hepsi benim omuzlarımda, İnsanlar, sürüler ve hayvanlar, Saban izleri, Daracık yollar ve saz damlar. Sis, yağmur...', ARRAY['Türk Edebiyatı','Şiir','Tudor Arghezi']::text[], 8.5, '{"poet":"Tudor Arghezi","poet_slug":"tudor_arghezi","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ERKEN TÜRKÜ', 'erken-turku-mubera-pasi-c-xd7nz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Buradayım. Sabah tutuşmuş yanıyor
Şaşkınlık otlarında
temiz bir yerde
sessiz bir sesten alınmışım.
Gene buradayım :
Ama yalnızca benim
bir parçam
kuşlara yol gösteriyor.
Otların Tanrıyla
barıştığı sabah
seni bulamayacağım.
Kişisizlikten gelen bu çağrı
bir döngü etrafında
dağıldığına
iyi bir işarettir.
Saçlarımın yükünü indiriyorum.
Dönence yürekleri ıslatıyor
Ses herkesin olsun.
Ama benim gizli bir parçam
kendine yön arıyor.
Mübera PASİÇ', 'Buradayım. Sabah tutuşmuş yanıyor Şaşkınlık otlarında temiz bir yerde sessiz bir sesten alınmışım. Gene buradayım : Ama yalnızca benim bir p...', ARRAY['Türk Edebiyatı','Şiir','Mübera Pasi̇ç']::text[], 8.5, '{"poet":"Mübera Pasi̇ç","poet_slug":"mubera_pasic","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ERİNÇ', 'eri-nc-mehmet-kiyat-szi0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir taşkınlık gibi bekleyerek
geçip giden günler
Irmağın sesindeki yakarış
hışırtıları ormanın
Durmadan söyleşen ateşböcekleri
tutamadığım söz
Kollarını sabaha açan gelinciklerle
boynu bükük sevinç
Büyüme çağına yetişmeyen
özgürlükler
Ve güneşini ısıttığım gecelerle gelen
sevgilim
Kapalı kapılar ardında
ey umuda sarılan erinç', 'Bir taşkınlık gibi bekleyerek geçip giden günler Irmağın sesindeki yakarış hışırtıları ormanın Durmadan söyleşen ateşböcekleri tutamadığım s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kiyat']::text[], 8.5, '{"poet":"Mehmet Kiyat","poet_slug":"mehmet_kiyat","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
