INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FİZİK YAZ ve PSİŞE', 'fi-zi-k-yaz-ve-psi-se-kagan-kok-s7b1s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SIZI
Bak yavaş yavaş doluyor yaz
Benden arta kalan yere
Akışkan ve inanılmaz bir sızı ile
Bir tek uzak tedirginlik kalacak sanki elimde
TREN
Artık sen kendini yalnız yaza atfet
Bak şimdi bu yaz geçerken
Sen ters yöne giden diğer yazdasın
Böyle çabucak geçmesi sade bu yüzden
BASINÇ
Şimdi yazdır üzerimdeki bu basınç
Aşkları benden dışarı iten kuvvet
Oysa direnmiştim ipin bu ucunda
Ta ki bir gün devrilene dek', 'SIZI Bak yavaş yavaş doluyor yaz Benden arta kalan yere Akışkan ve inanılmaz bir sızı ile Bir tek uzak tedirginlik kalacak sanki elimde TREN...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FİZİKÇİLER İÇİN ŞİİRLER', 'fi-zi-kci-ler-i-ci-n-si-i-rler-mehmet-zaman-saclioglu-yq021', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'NEWTON''A
O elma, cinselliği Âdem''in
Bu yüzden güçlü yerçekimi
Daha yakındık Tanrıya
El ilanlarından önce
Peygamberlerin.
EINSTEIN''A
Bu sabah yüzüme
Dudak izimi taşıdı ilk ışık
Geceyi öperken camda kalan.
FEZA GÜRSEY''E
I
Dördü de zamanda yatar Tanrının beş sureti
Biri eyler zamanı ki ondan alır kuvveti.
II
Bir denizinde bin yunus yüzer dervişin
Su hem bir eder hem ayırır onları.', 'NEWTON''A O elma, cinselliği Âdem''in Bu yüzden güçlü yerçekimi Daha yakındık Tanrıya El ilanlarından önce Peygamberlerin. EINSTEIN''A Bu sabah...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
