INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GALATA KULESİ', 'galata-kulesi-umit-yasar-oguzcan-5u5s4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '6 Haziran 1973
Pırıl pırıl bir yaz günüydü
Aydınlıktı, güzeldi dünya
Bir adam düştü o gün Galata Kulesi’nden
Kendini bir anda bıraktı boşluğa
Ömrünün baharında
Bütün umutlarıyla birlikte
Paramparça oldu
Bir adam benim oğlumdu...
Gencecikti Vedat
Işıl ışıldı gözleri
İçi
Bütün insanlar için sevgiyle doluydu
Çıktı apansız o dönülmez yolculuğa
Kendini bir anda bıraktı boşluğa
Söndü güneş, karardı yeryüzü bütün
Zaman durdu
Bir adam düştü Galata Kulesi’nden
Bu adam benim oğlumdu
“Açarken ufkunda güller alevden”
Çıktı, her günkü gibi gülerek evden
Kimseye belli etmedi içindeki yangını
Yürüdü, kendinden emin
Sonsuzluğa doğru
Galata Kulesi’nde bekliyordu ecel
Bir fincan kahve, bir kadeh konyak
Ölüm yolcusunun son arzusu buydu
Bir adam düştü Galata Kulesi’nden
Bu adam benim oğlumdu
Küçüktü bir zaman
Kucağıma alır ninniler söylerdim ona
“Uyu oğlum, uyu oğlum, ninni”
Bir daha uyanmamak üzere uyudu Vedat
6 Haziran 1973
Galata Kulesi’nden bir adam attı kendini
Bu nankör insanlara
Bu kalleş dünyaya inat
Şimdi yine bir ninni söylüyorum ona
“Uyan oğlum, uyan oğlum, uyan Vedat”...', '6 Haziran 1973 Pırıl pırıl bir yaz günüydü Aydınlıktı, güzeldi dünya Bir adam düştü o gün Galata Kulesi’nden Kendini bir anda bıraktı boşluğ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit_yasar_oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GALWAY AT YARIŞLARINDA', 'galway-at-yarislarinda-william-butler-yeats-vzfwe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Orada, atların yarıştığı çayırda,
Aramızda birlik yaratıyor duyduğumuz sevinç.
Atlılar dörtnala atlarının sırtında,
Yüreği ağızlarında arkadan bakanların:
Bizim de seyircilerimiz vardı eskiden,
Dinleyen, işimizde bizi yüreklendiren;
Yoldaşlık ederdik binicilerle
Yeryüzü tüccarın, kalem efendisinin
Kesik soluklarıyla buğulanmadan.
Sürdürün türkünüzü: bir yerde doğarken yeni bir ay,
Göreceğiz uyumanın ölmek olmadığını,
Duyarak yeryüzünün yeni bir hava tutturduğunu -
Yeryüzü hep delikanlı çünkü -
Sonra bağıranlar çıkacak yarışlardaki gibi,
Ve insanlar olacak bizi yüreklendiren,
Atını sürüp gidenlerden?
William Butler YEATS', 'Orada, atların yarıştığı çayırda, Aramızda birlik yaratıyor duyduğumuz sevinç. Atlılar dörtnala atlarının sırtında, Yüreği ağızlarında arkad...', ARRAY['Türk Edebiyatı','Şiir','William Butler Yeats']::text[], 8.5, '{"poet":"William Butler Yeats","poet_slug":"william_%20butler_yeats","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÂGAPE', 'gape-c-sar-vallejo-y79j7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimse gelmedi bugün bana sorular sormaya;
kimse bir şey istemedi benden bu ikindi.
Bir tek mezarlık çiçeği görmedim
bütün o neşeli fener alayında.
Affet beni, tanrım: ne kadar az öldüm!
Herkes, herkes geçip gidiyor bu ikindi
sorular sormadan bana, beni sormadan.
Bilmiyorum ne unuttular, ellerimde
kalan bu fenalık yabancı bir nesne gibi.
Kapıya çıkıp,
bağırmak istiyorum herkese:
Aradığınız biri varsa, işte burada!
Bütün ikindilerinde hayatımın,
anlatamam ne kapılar kapandı yüzüme,
ve ruhum yabancı bir şeyle doldu.
Kimse gelmedi bugün;
ve çok az öldüm bu ikindi.
César VALLEJO', 'Kimse gelmedi bugün bana sorular sormaya; kimse bir şey istemedi benden bu ikindi. Bir tek mezarlık çiçeği görmedim bütün o neşeli fener ala...', ARRAY['Türk Edebiyatı','Şiir','César Vallejo']::text[], 8.5, '{"poet":"César Vallejo","poet_slug":"cesar_vallejo","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GAYRIDIR HER MİLLETTEN BU BİZİM MİLLETİMİZ', 'gayridir-her-mi-lletten-bu-bi-zi-m-mi-lleti-mi-z-yunus-emre-naba4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gayrıdır her milletten
Bu bizim milletimiz
Hiç dinde bulunmadı
Din ü diyanetimiz
Bu din ü diyanette
Yetmiş iki millette
Bu dünya ol ahrette
Ayrıdır âyâtımız
Zahir suya banmadan
El ayak deprenmeden
Baş sücuda ermeden
Kılınız taatımız
Ne Kâbe ne de mescid
Ne rükû ne de sücud
Hak ile daim becid
Olur münacatımız
Ger Kâbe''ye varalım
Ger mescide girelim
Ger suyuyla yunalım
Çün bile illetimiz
Su ne kadar arıda
Çün yavuz fi''lşin senin
Meğer bizi pâk ede
Hak''tan inayetimiz
Kimin sözün kim bile
Akıl ermez bu hâle
Yarın anda bell''ola
Müslüman mürtedimiz
Yunus canın yenile
Kim dostluğun anıla
Aşk ile dinlerisen
Bilesin kudretimiz', 'Gayrıdır her milletten Bu bizim milletimiz Hiç dinde bulunmadı Din ü diyanetimiz Bu din ü diyanette Yetmiş iki millette Bu dünya ol ahrette ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GAZİ', 'gazi-markos-cirimokos-554da', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gövdesi çelik, yüzü çocuksu
yiğitlik ve sevinç doluydu
aç kurtlar gibi saldıran düşmanı
öldürmek için yola koyuldu.
Altı azizler gibi parladı askerde
alçakgönüllü her yana koştu
birinci atıldı savaşa
sonuncu bıraktı.
Arkadaşları yaydı ününü
dört yana
dağlar, ovalar
hep onu alkışladı.
Karanlık ve korku diyarında
yıllarca bir hayvan gibi
yaşayan bir kahraman
şimdi bir insan paçavrası,
Yüzü sapsarı
saçları omuzlarında
baktım
sanki bir zafer anıtı.
Çakılıp kalmış
yolun ortasında
sağ eli
koltuk değneğine dayalı.
İncil'' den barış ve sevgi üstüne
bir söylev dinliyordu sırıtarak
el yerine
ceketinin boş kolunu sallayarak.
Markos CIRIMOKOS
Çeviri :Y. BOZ /
Refik', 'Gövdesi çelik, yüzü çocuksu yiğitlik ve sevinç doluydu aç kurtlar gibi saldıran düşmanı öldürmek için yola koyuldu. Altı azizler gibi parlad...', ARRAY['Türk Edebiyatı','Şiir','Markos Cirimokos']::text[], 8.5, '{"poet":"Markos Cirimokos","poet_slug":"markos_cirimokos","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GAZEL GİBİ', 'gazel-gi-bi-metin-guven-tc7cj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllardır yağmaladım durdum kendimi
Dünyanın bütün yalanları kendi gerçeğim oldu
Adım artık hiçbir serapla anılmıyor
Ne kendimi tanıdım, ne onu öğrenecek zamanım oldu.', 'Yıllardır yağmaladım durdum kendimi Dünyanın bütün yalanları kendi gerçeğim oldu Adım artık hiçbir serapla anılmıyor Ne kendimi tanıdım, ne ...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GAZEL', 'gazel-faiz-ahmed-fai-z-fhsyv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni aşk nedeniyle suçluyorum, hepsi bu
Bu bir yergi değil, ama bir övgü, hepsi bu
Gönlüm hoşlanır suçlayan sözcüklerinden
Ey sevgililer sultanı, onlar söyler adını, hepsi bu
Eğlendiysem eğlendim, bu bir suç değil
Gönlümün boşa geçen zamanı, ümitsiz bir aşk, hepsi bu
Umudu yitirmedim, yalnızca bir savaş, hepsi bu
Uzayan acıların gecesi, ama yalnızca bir gece, hepsi bu
Zamanın pençesi düzenleyemez yazgımı
Zamanın pençesinin düzenlediği yalnızca günün anı, hepsi bu
Kesinkes bir gün gelecek, gerçeği göreceğim
Güzel sevgilim bir tülün ardındadır, hepsi bu
Gece gençtir, Faiz başlar bir gazel söylemeye
Duyguların fırtınası coşkuya batık, hepsi bu
Faiz Ahmed FAİZ', 'Seni aşk nedeniyle suçluyorum, hepsi bu Bu bir yergi değil, ama bir övgü, hepsi bu Gönlüm hoşlanır suçlayan sözcüklerinden Ey sevgililer sul...', ARRAY['Türk Edebiyatı','Şiir','Faiz Ahmed Fai̇z']::text[], 8.5, '{"poet":"Faiz Ahmed Fai̇z","poet_slug":"faiz_ahmed_faiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖBEK BAĞI', 'gobek-bagi-hulya-deniz-unal-v91d6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kim itecek bakalım
Beni hangi bahane
Hayata benzemeyen
Uğultular cebimde
Zemine kilim
Pestil öncesi çarşafa
Kayısı serer gibi
Yüreğimin askısında demirden
Bir çift eldiven
Arttıkça uzaklaşıp yitti biri
Öteki dirençle asılmakta
Aydınlığa doğru gözleri
Mahzun gömleği burada unutulmuş
Dostun asılı durduğu koltukta
Uçan halı uzak ihtimal
Düşeceğim yakın boşlukta
Süzülürken her kattan
Balkonda saksılardan
Rüzgârıma uzatıp boyunlarını
Vedaya çıkmasın çiçekler, öpmeyeyim
Baharat kokan sesimle gözbebeklerinden
Göbek bağımı getirin
Bağlarsa beni ancak o
Hayatın demir korkuluğuna
Boşluğa karışan mavi katlardan
Beş katlardan, dört katlardan, üç katlardan
İnerken hızla
Lacivert üstüne siyah düşerken gölgem
Gri yaldızlı betona', 'Kim itecek bakalım Beni hangi bahane Hayata benzemeyen Uğultular cebimde Zemine kilim Pestil öncesi çarşafa Kayısı serer gibi Yüreğimin askı...', ARRAY['Türk Edebiyatı','Şiir','Hülya Deniz Ünal']::text[], 8.5, '{"poet":"Hülya Deniz Ünal","poet_slug":"hulya_deniz_unal","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDİCİ', 'gi-di-ci-baris-gulteki-n-2ca3x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '*umutsuzum''a
Zaten
bir otobüs zıplamasında tutabilmiştim elini
düzünden okuyorum seni ;
kAçaK
çevirip tersinden ;
KaçAk.', '*umutsuzum''a Zaten bir otobüs zıplamasında tutabilmiştim elini düzünden okuyorum seni ; kAçaK çevirip tersinden ; KaçAk....', ARRAY['Türk Edebiyatı','Şiir','Barış Gülteki̇n']::text[], 8.5, '{"poet":"Barış Gülteki̇n","poet_slug":"baris_gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDEN SEN', 'gi-den-sen-mehmet-zaman-saclioglu-xil0b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adını koy bir yana uzaklaş...
Ne kaldı sana elinden başka?
Şimdi tut bir ağacı, okşa.
Bak, bulut onca yüksekten
Dala fısıldıyor yağmuru.
Çek elini, gözünle dinle.
At işini bir yana suya gir...
Nehir senin içinde, zaman sensin
Unut gözünü, ten ol, akarsın...
Bırak karga anlatsın seni
Bülbülle aynı sestir duyacağın
Sen aslında sarmal bir deniz kulağısın.
Sevdin mi bu işi? İyi,
Üfle gitsin o zaman elindeki.
Giden, sana geri gelendir belki,
Unutunca anımsarsın.', 'Adını koy bir yana uzaklaş... Ne kaldı sana elinden başka? Şimdi tut bir ağacı, okşa. Bak, bulut onca yüksekten Dala fısıldıyor yağmuru. Çek...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDENLERİ ANLATIYORUM', 'gi-denleri-anlatiyorum-rifat-ilgaz-ws0s3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İştahımın gücünden arta kalan
Yarım dilim ekmekten utanıyorum
Açların boyun büktüğü memlekette
Kişi özgürlükten lâf etmemeli
Sevince alabildiğine sevmeli
Yoksun sevgilerle değil böyle
Bir elmayı dişler gibi diri diri
Ama genç ama ak saçlısın
Evrene bir şey katmalı sevdin mi
İnsan içince tam içmeli
Sıyrılmalı bozukdüzenliğinden
Mutluluktan bir şeyler getirmeli
Sıra sıra yataklardan utanıyorum
Umutsuz sönüp gidenlerden
Gözler bakarken ateş böcekleri gibi
Mayıs gecelerinden ses vermeli
Kişi ölecekse insanca ölmeli
Böyle tutsak böyle utanç içinde değil
Bir sedyede boylu boyunca uzatılmış
İki eli iki yanında gitmemeli
(1961)
Soluk Soluğa adlı şiir kitabından 1962
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'İştahımın gücünden arta kalan Yarım dilim ekmekten utanıyorum Açların boyun büktüğü memlekette Kişi özgürlükten lâf etmemeli Sevince alabild...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDERAYAK', 'gi-derayak-attila-asut-lpebw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umudu öldürüyorlar yavrum
baharda kuşları
balaban düşleri öldürüyorlar
yalansız gülüşleri
balözü öpüşleri öldürüyorlar.
En güzel şeyleri öldürüyorlar yavrum
kitapları ve çocukları öldürüyorlar
bal veren arıları
hamarat karıncaları öldürüyorlar
ışıyan şafağı
gülen düşünceyi
anaç türküleri öldürüyorlar.
Bak işte
geliyorlar
söndürmeye ışığını dünyamızın
güneşini doğanın.
Şimdi namluda karanfil neye yarar
duvarda afiş neye yarar
defterde şiir neye yarar?
Gidiyorum
akşam eve dönmeyebilirim
sana yalnız karanfili
ve bu şiiri bırakarak
ölebilirim.
Gidiyorum
babasız büyümeye hazır ol
hazır ol yavrum.
Ankara, 24 Mart 1978', 'Umudu öldürüyorlar yavrum baharda kuşları balaban düşleri öldürüyorlar yalansız gülüşleri balözü öpüşleri öldürüyorlar. En güzel şeyleri öld...', ARRAY['Türk Edebiyatı','Şiir','Attila Aşut']::text[], 8.5, '{"poet":"Attila Aşut","poet_slug":"attila_asut","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDERSEN EĞER', 'gi-dersen-eger-yusuf-altunel-hhc5q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'emine''ye
gittiğinde
vakitsiz yaprak dökerim
hazana döner her mevsim
yokluğun tineriyle bedenim sarhoş
yaralı hançeriyle sensizliğin
şahdamarımdan vurur beni
benden kopan sen mermileri
sen gittiğinde
göçe döner mutluluklarım
ayrılmalarımız felaketten bulut
yağmuru dökülür hüznün
çaresizliğim ıslak
kayboluşum kanlı döşek
koynumda boyunca uzanır
yalnızlıktan ceset
tüm gidişlerin ayrılık zemherisi
kesilir yollarım ben iflahsız hasta
sensizliğinle yatalak üstü çıplak, üşürüm
terkedilmişlik rüzgarı keskin bıçak
buzdan yokluğun kırar filizlerimi
nöbet çekerim sensizlik ayazında
ağlamalara dökülür kırağıdan yer çekimi
gittiğinde
kurşunlar yalnızlık beni
sensizlik ıslatacak damla damla kenti
kanlı cellat ayrılmalarımız boynumu vurur
hıçkırıklarımda can çekişmeler
ayrılık mezarına atılır leşim
bıraktığın boşluktan dikilir kefenim
her gidişinde
fırlar namlusundan yüreğim
sevmelerim goğsümden damlar
kopar yüreğim dalından
sen celladına olgun meyva
tüm yönelişlerim
gülüşlerin damarlarıma kan
boynum vurulsa da akmayan
sen gitme
bütün hayatlarımı al
köle olsun sana bu gereksiz can
sevdan yükü ile yorgun bu yaşlı hamal
bu aşk delisi, bu sevgiden kudurgan', 'emine''ye gittiğinde vakitsiz yaprak dökerim hazana döner her mevsim yokluğun tineriyle bedenim sarhoş yaralı hançeriyle sensizliğin şahdamar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":45}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDİŞİNİ ANLATIYORUM', 'gi-di-si-ni-anlatiyorum-rifat-ilgaz-i1d4h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gidiyorsun ya işine yetişmek için
Saçlarını, gözlerini, ellerini
Neyin varsa toplayıp gidiyorsun ya
Her seferinde bir şey unutuyorsun sıcak
Termometrede yükselen çizgi çizgi
Kim bilir nerelerde soğuyorsun
Senin gözbebeklerin var ya kadın kadın gülen
İnsan insan bakan gözbebeklerin
Beni tutsa tutsa gözlerin tutar ayakta
Beni yıksa yıksa gözlerin yerle bir eder
Ne gelirse onlardan gelir bana
Çalışma gücü yaşama direnci
Mutluluk gibi kazanılması zor
Mutluluk gibi yitirilmesi kolay
Bir açarsın ki mutluyum
Bir kaparsın her şey elimden gitmiş
(1961)
Soluk Soluğa adlı şiir kitabından 1962
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Sen gidiyorsun ya işine yetişmek için Saçlarını, gözlerini, ellerini Neyin varsa toplayıp gidiyorsun ya Her seferinde bir şey unutuyorsun sı...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇ AZİZİM GEÇ', 'gec-azi-zi-m-gec-rifat-ilgaz-pjatf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz de yaşarız azizim,
Yaşamaya gelince, biz de yaşarız ama,
Olmuyor cebimizden kattığımızla eğlenmek,
Gönlümüzden katalım,
Varlıklı kişileriz neşeden yana.
Pazarımız hoş mu geçecek,
Şart değil Büyükada, Heybeli;
Çok bile gelir kayığı Hristo''nun:
Sekiz arşın iki karış,
Kız gibi Cibali yapısı.
Bir işaretimize bakar
Çıkmazsa balığı alesta,
Aylardan temmuz, günlerden pazar;
Yenikapi açıklarındayız...
Bırakın Hasan geçsin küreğe,
Utandırmaz bu kollar sahibini.
Kabarmaz bu avuçlar
On ikisinden beri nasırlıdır.
Fazla külfet istemez,
Bol sigaramız olsun,
Köfte, ekmek, domates yeter.
Karımız, sevgılımız yanımızda
Başaltında şarap testisi...
Dedik ya bugün pazar
Belki genç arkadaşı
&quot;İlk defa güneşe çıkardılar&quot;,
İsteriz bütün dostlar aramızda olsun;
Kiminin Hanya''dan gelir selamı,
Kiminin Konya''dan
Sandalımız geniş değil, ne çare,
Gönlümüz kadar.
Ne yapalım bol şarabımız var ya,
Onların sağlığına içecek;
Gün ola harman ola!..
Anlarız biz de bu işlerden,
Elimiz değdi de okşamadık mı,
Şu &quot;pür hayal&quot; saçları ?
Kim istemez &quot;yâr&quot;i uyutmasını &quot;sine&quot; de
Batan güne karşı,
&quot;Bâde&quot; içmesini &quot;Yâr eli&quot;nden?
Gözü kör olsun feleğin,
Gelecekten umudumuzu kesmedik,
İçimiz öylesine ferah...
Son kadehlere doğru sorsun,
Sesi en güzelimiz bizden:
&quot;Gam, keder ne imiş?&quot;
Yontulmamış sesimizle cevabı hazır:
&quot;Geç azizim, geç!&quot;', 'Biz de yaşarız azizim, Yaşamaya gelince, biz de yaşarız ama, Olmuyor cebimizden kattığımızla eğlenmek, Gönlümüzden katalım, Varlıklı kişiler...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖĞE BAKMA DURAĞI', 'goge-bakma-duragi-turgut-uyar-rah4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İkimiz birden sevinebiliriz göğe bakalım
Şu kaçamak ışıklardan şu şeker kamışlarından
Bebe dişlerinden güneşlerden yaban otlarından
Durmadan harcadığım şu gözlerimi al kurtar
Şu aranıp duran korkak ellerimi tut
Bu evleri atla bu evleri de bunları  da
Göğe bakalım
Falanca durağa şimdi geliriz göğe bakalım
İnecek var deriz otobüs durur ineriz
Bu karanlık böyle iyi afferin Tanrıya
Herkes uyusun iyi oluyor hoşlanıyorum
Hırsızlar polisler açlar toklar uyusun
Herkes uyusun bir seni uyutmam birde ben uyumam
Herkes yokken biz oluruz biz uyumıyalım
Nasıl olsa sarhoşuz nasıl olsa öpüşürüz sokaklarda
Beni bırak göğe bakalım
Senin bu ellerinde ne var bilmiyorum göğe bakalım
Tuttukca güçleniyorum kalabalık oluyorum
Bu senin eski zaman gözlerin yalnız gibi ağaçlar gibi
Sularım ısınsın diye bakıyorum ısınıyor
Seni aldım bu sunturlu yere getirdim
Sayısız penceren vardı bir bir kapattım
Bana dönesin diye bir bir kapattım
Şimdi otobüs gelir biner gideriz
Dönmiyeceğimiz bir yer beğen başka türlüsü güç
Bir ellerin bir ellerim yeter belliyelim yetsin
Seni aldım bana ayırdım durma kendini hatırlat
Durma kendini hatırlat
Durma göğe bakalım', 'İkimiz birden sevinebiliriz göğe bakalım Şu kaçamak ışıklardan şu şeker kamışlarından Bebe dişlerinden güneşlerden yaban otlarından Durmadan...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇ GENÇ İSTEM SİTEM', 'gec-genc-i-stem-si-tem-baris-gulteki-n-wmuj1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '*baba''ma ve baba''mın kuşağına
Silebilmek için elemi
bu ağılı meyhaneden
ve
devirip her masayı
aşık olabilmek için
dans eden o kızıl saçlı
sonbahar kadınına
çok değil
antik,kırmızı,sağlam bir şarkı
ve
bir yaprak düşüşü
zam/lı an/dı istediğim sizden.', '*baba''ma ve baba''mın kuşağına Silebilmek için elemi bu ağılı meyhaneden ve devirip her masayı aşık olabilmek için dans eden o kızıl saçlı so...', ARRAY['Türk Edebiyatı','Şiir','Barış Gülteki̇n']::text[], 8.5, '{"poet":"Barış Gülteki̇n","poet_slug":"baris_gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇ SAAT', 'gec-saat-ahmet-oktay-gxvg4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgundu. Düş görürken
-ölmüş müydü ölüyor muydu?
fidana dokunduğu an açıvermişti gonca-
elinden düştü kitap
kalem de
şuydu altını çizdiği cümle:
Kierkegaard''tan,
"Üzüntüm, kâl''amdır benim"', 'Yorgundu. Düş görürken -ölmüş müydü ölüyor muydu? fidana dokunduğu an açıvermişti gonca- elinden düştü kitap kalem de şuydu altını çizdiği c...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Oktay']::text[], 8.5, '{"poet":"Ahmet Oktay","poet_slug":"ahmet_oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖÇEBE', 'gocebe-nahit-ulvi-akgun-gzq7d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereye gittiysem yadırgadım yerimi
Canıma tak etti bu göçebe yaşam
Tam alışırken yurduma yuvama
Bir de bakıyorum saat tamam
Yüzümü iyiden iyiye tanıyorum
Elim ayağım benim de
Başkası çıkacakmış gibi karşıma
Aynalardan kaçıyorum şimdi
Zaman içinde böyle darmadağın
Ne mutluluğum belli ne mutsuzluğum
Bir düşteymiş gibi hafif
Sis dağlarından yuvarlanıyorum', 'Nereye gittiysem yadırgadım yerimi Canıma tak etti bu göçebe yaşam Tam alışırken yurduma yuvama Bir de bakıyorum saat tamam Yüzümü iyiden iy...', ARRAY['Türk Edebiyatı','Şiir','Nahit Ulvi Akgün']::text[], 8.5, '{"poet":"Nahit Ulvi Akgün","poet_slug":"nahit_ulvi_akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE BESTESİ', 'gece-bestesi-yahya-kemal-beyatli-4f2iq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O kuş en kuytu bahçelerde öter;
Sarmaşıklarla yüklü vâdîde;
Hiç bir el değmemiş ağaçlarda;
Geceden tâ şafak sökünceye dek
Yükselir perde perde içli sesi;
En uzun nağmesiyle, bir müddet,
Gaşyeder yer yüzünde dinliyeni;
Bir zaman gök yüzünde yalnız o ses,
O terennüm kalır;
Gaşyolur dinledikçe yaldızlar.
O kuş ancak bahâr olunca gelir;
Nerelerden gelir?
Kimse bilmez, bu bir muammâdır;
Bahâr erince sona
Kaybolur, başka bir bahara kadar.
O kuşun ömrü, bir güzel gecede,
Bir güzel beste söylemekle geçer.
O kuş en kuytu bahçelerde öter;
Hayâl içinde yaşar,
Hayâl içinde ölür.', 'O kuş en kuytu bahçelerde öter; Sarmaşıklarla yüklü vâdîde; Hiç bir el değmemiş ağaçlarda; Geceden tâ şafak sökünceye dek Yükselir perde per...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE BİTTİ', 'gece-bi-tti-salvatore-quasimodo-es9yn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece bitti
Ay eriyor doğan günde
Battı batacak sulara
Bu ovada eylül ne kadar diri
Çayırlar yemyeşil
Bahar toprakları sanki güneyde
Bıraktım eşi dostu
Eski bahçelere gittim gizli gizli
Seni anmak için tek başıma
Sen Ay''dan ötelerde bir yerdesin
Burda gün doğarken
Nal sesleri gelirken kaldırımlardan', 'Gece bitti Ay eriyor doğan günde Battı batacak sulara Bu ovada eylül ne kadar diri Çayırlar yemyeşil Bahar toprakları sanki güneyde Bıraktım...', ARRAY['Türk Edebiyatı','Şiir','Salvatore Quasimodo']::text[], 8.5, '{"poet":"Salvatore Quasimodo","poet_slug":"salvatore_quasimodo","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE DÜŞLERİ', 'gece-dusleri-gultekin-emre-fgiri', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece düşleri alır götürür beni
sığınmacı akşamların hüznüne
-ne çok şey anlatılır ya da anlatılamaz
baskının direnmeye davetine
ölümlerin yeniden dirilmelerine
bir kent düşünün her evde bir yaralı
-ya ölüler ya ölemeyenler ya ölümü bekleyenler
düğünlere kan bulaşmış bir kez
-sevgiler tutsak tek kişilik hücrelerde
sular da çürür yetmişiki gün boyunca
gece düşleri alır götürür beni
dimdik yüreklerin yanında nöbete
şarkı, türkü, şiirle dolmaya
kilit vurulmuş denizlerin dilinde
balıkçıların ağında mavi köpük olmaya
yabancı akşamların karanlık gülleri
mektupların yanıtsız kaldığı günler
acı haberler bizleri bekler kuytularda
yapraklar sessizce hıçkırır ezgilerimizi
gözlerin, dost gözlerin sönmeyen sevgisi
gece düşleri alır götürür beni
elimde bir gül fidanı
kaşların namlu gibi çatıldığı sedirlere
dillerin bıçak açmaz suskunluğu
kararlılıklara, antlara, akşamalacalarına
ve sen gelirsin şafağın ilk rengiyle
penceremde kuş olmaya', 'gece düşleri alır götürür beni sığınmacı akşamların hüznüne -ne çok şey anlatılır ya da anlatılamaz baskının direnmeye davetine ölümlerin ye...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Emre']::text[], 8.5, '{"poet":"Gültekin Emre","poet_slug":"gultekin_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE GELEN TELGRAF', 'gece-gelen-telgraf-nazim-hi-kmet-xeu77', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece gelen telgraf
dört heceden ibaretti:
&quot;VEFAT ETTİ.&quot;
İmza yok.
Bu dört hece bile çok.
Bakıyorum duvara:
duvarda bir yara-
duvarda bir resim-
vefat edenin,
elimle çizmişim.
Saat bir.
Saat üç.
Saat beş.
Polis düdükleri, saatlar...
Yatağım bozulmamış.
Çekmecemde kaatlar:
bazıları
onun el yazıları.
Gece gelen telgraf
dört heceden ibaret...
Şafak söküyor-
odam
geceden ibaret.
Avuçlarımda
ellerinin gölgesi dolaşan adam
demir parmaklıklardan gördü son gündüzünü.
Mahpushane doktoru
örterek paltosuyla upuzun yatanın yüzünü:
- Tamam!
dedi.
Bunu belki evvelki akşam
dedi.
Evvelki akşam
ben......
Satıcılar geçiyor mahalleden.
Bakıyorum
gece gelen
telgrafa.
O mükemmel bir kafa
mükemmel bir yürek,
yumruklarıyla erkek
gözleriyle çocuktu.
Hudutsuz ve Allahsız bir baştı o.
Yoldaştı o..
* * *
Düşmanlar kına yaksın
dostlar girsin saflara.
Sen gözyaşı göstermeden ağlıyacaksın
gece gelen telgraflara...', 'Gece gelen telgraf dört heceden ibaretti: &quot;VEFAT ETTİ.&quot; İmza yok. Bu dört hece bile çok. Bakıyorum duvara: duvarda bir yara- duvar...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hi̇kmet']::text[], 8.5, '{"poet":"Nazım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE GELENİN TÜRKÜSÜ', 'gece-geleni-n-turkusu-afsar-ti-muci-n-45sih', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi saatte durur şiir
Hangi saatte başlar
Horozlar hangi saatte öter
Hangi saatte yıkanır ışıkla
Gecenin çamuruna batanlar
Böyle sen mi geldin sabaha karşı
Alkol tütün ve yalnızlık içinde
Böyle sen mi geldin sessiz
Çocukların doğmasından günün ışımasından
Kavgada insanların ölmesinden korkarak
Böyle sen mi geldin kaça kaça
Kaygılar hangi saatte başlar
Hangi saatte yenik düşer
Gecenin bitimi doğan güne
Ve neden güne başlıyor gibi
Bazen çok sevdiklerimiz bile
Yeniden geceye başlarlar
Hangi saatte susar şiir
Hangi saatte yazar ölümün yazgısını', 'Hangi saatte durur şiir Hangi saatte başlar Horozlar hangi saatte öter Hangi saatte yıkanır ışıkla Gecenin çamuruna batanlar Böyle sen mi ge...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE GEÇTİM ÖMRÜMÜN ÜSTÜNDEN', 'gece-gecti-m-omrumun-ustunden-gultekin-emre-ng8bw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir fotoğrafını bile görmediğim kentlerden, kasabalardan, köylerden
Geçtim, adını aklımda tutamadığım konaklama tesislerinde açık çaylar
İçtim, sorsanız haritada gösteremeyeceğim ırmaklardan döküldüm sana
Kötü çekilmiş resimler gibi günlerim, günlerim yanlış resimler gibi
"Güle güle, hayırlı yolculuklar!" beni benle başbaşa bırakan ıssızlığın
Molaya geç kalmış bir otobüs gibi soluk soluğayım sana gelirken
Hayatı yanlış sollayan bir otobüs elimden tuttu bu gece, haydi hayırlısı
Geçmişim göndere çekilecek yarın senin önünde, yarın ben yokum
Telgrafın telleri de "tedavül"den kalktı, kuşlarda kuşak çatışmaları
Yani içime su serp, yüzünde gül açsın, aşksız bir martıya dönmeyeyim
Yavrusunu yitirmiş bir kirpiye dönmesin sensiz günlerim, ortancamda
Ortak kaygılar, bendeki kamburu çıkmış bir azınlık ruhu, şimşeğin
Şaşırdığı yol, El Nino''nun okşadığı haritalardaki renk değişikliği bizi
De ilgilendiriyor, senin tarihin bana doğru ne zaman temel atacak
Çok eskiden de gelmiştim bu heryeri iyice yağmalanmış, ülkeye
Türkiye daha bir Türkiye miydi o zamanlar, sevdiğime yine burada
Şiirler yazmıştım da kimse karışmamıştı işime, ormanlar hep yanmış
Yakılmış, dostlar emekli olmuş, kışında bir karış yeri kalmamış bir
Kıyı şeridi gibiyim, akşam bekliyor beni ne yapacağım ben akşamla
Gece geçtim buralardan uykuna tutunup, düşlerine sarılıp, al işte beni', 'Bir fotoğrafını bile görmediğim kentlerden, kasabalardan, köylerden Geçtim, adını aklımda tutamadığım konaklama tesislerinde açık çaylar İçt...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Emre']::text[], 8.5, '{"poet":"Gültekin Emre","poet_slug":"gultekin_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE KONUŞMALARI', 'gece-konusmalari-metin-guven-gd2h0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırılgan kadınlara
Koşuoyr kalbim
Oysa çoktan bitmişti
Gece konuşmaları
Ve kanser
Ellerini bastır göğsüme
Kırılsın
İçimde yeşeren hançer', 'Kırılgan kadınlara Koşuoyr kalbim Oysa çoktan bitmişti Gece konuşmaları Ve kanser Ellerini bastır göğsüme Kırılsın İçimde yeşeren hançer...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE KİTABININ SAYFASI', 'gece-ki-tabinin-sayfasi-tomas-transtromer-5cgsq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karaya çıktım bir mayıs gecesi
soğuk ay ışığında
çimlerin ve çiçeklerin gri
ama kokunun yeşil olduğu yerde.
Yamaçtan yukarı doğru kaydım
o renkkörü gecede
sinyal gönderirken beyaz taşlar
aya.
Bir zaman boşluğu
birkaç dakika uzunlukta
elli sekiz yaş eninde.
Ve arkamda
kurşun gibi parlayan suyun ardında
karşı kıyı vardı
ve orayı ellerinde tutanlar.
Gelecekleri olan
ama yüzleri olmayan insanlar.
Tomas  TRANSTRÖMER', 'Karaya çıktım bir mayıs gecesi soğuk ay ışığında çimlerin ve çiçeklerin gri ama kokunun yeşil olduğu yerde. Yamaçtan yukarı doğru kaydım o r...', ARRAY['Türk Edebiyatı','Şiir','Tomas  Tranströmer']::text[], 8.5, '{"poet":"Tomas  Tranströmer","poet_slug":"tomas_transtromer","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE ŞİİRLERİ', 'gece-si-i-rleri-kaan-i-nce-s1jr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1. D E V R İ K    Y Ü R E K    S A V U N M A S I
Çiy doladım kasnağına gecenin. Işıksızlığın hep
yoksul  yalnızlıklara çıkması doğurur o rüzgârı.
Giz dizilmiş çardaklar incir kokulu, çiçek hattı
gözlerine doğru. Kokunda korku. Kafka; mürekkebini
içtiğim mevsimsiz aşk. Ölümün önünde yayılan;
çıbanı yüzümün. Devrik yürek savunması ömrüm.
Yaşlı bir adam vurgun yemiş. Kuşlar. Düşler.
Kapılma saatleri, basamaklarında ateş yatan zaman
merdiveninin dik soluğuna. Ve çekip giden bir ben,
aynı denize, irkilen iskeleden.
2. I S S I Z L I K    S Ü R Ü S Ü
Sıcak bir buğu düşürdüler ceplerinden, kışın gelişini
gözlerime yıkan gölgeler, ölüme giderken. Sonuna vardım
ufuk renginin, gündüz rüyalarımda gördüğüm. Gün sayıyor
kör eşgalim. Sönüyor gülüşüm, gülün bağrında ikindi vakti.
Zaman çağlıyor, ömrümü biçmeden. Çölde ıssızlık sürüsü
gecelerim. Pencerelerden akan yollarda usulca büyüyor
hüzün. İsyan dumanları. Bir kıyı, boğulduğum. Suçluyum.
Talan edilmiş sokaklara yeleler taktım, yenilgilerimi
asmak için. Korku salmış düş dudaklarına. Üzgünüm.
3. B U Y R U K
Gecenin deniz kanatlarında, bir kuşun sesine dalmış
düş topluyorum, gözlerime öpücük. Kendine açan bir ışığı
emiyor kalbim. Kara tren, sisler durağında akıntısı
kavuşmanın. Ten, sahili gurbetin. Dalga dalga köpürüyorum
aşka. Buyruk: Tez boynu vurula!
4. H A R İ T A
Haritası parçalandı ellerimde gecenin, bir yitiriş değil
bu, sınırları tutamadım yerinde, gözlerime doldu sular,
şimdi zaman oynak bir gölge. Nasıl başlasak geri dönmemek
için? Hüzünkıran  ardında saklanan kalbimle, artık, okyanuslara
açılmak geçmeli içimden. Biliyorum. Ama kavuşmalar ayrılıktır
bazen.', '1. D E V R İ K    Y Ü R E K    S A V U N M A S I Çiy doladım kasnağına gecenin. Işıksızlığın hep yoksul  yalnızlıklara çıkması doğurur o rüz...', ARRAY['Türk Edebiyatı','Şiir','Kaan İnce']::text[], 8.5, '{"poet":"Kaan İnce","poet_slug":"kaan_ince","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE SİSİ KAPLAMIŞ TEPELERİNİ GÜRCİSTAN''IN', 'gece-si-si-kaplamis-tepeleri-ni-gurci-stan-in-aleksandr-sergeyevic-puski-n-lksey', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gece sisi kaplamış tepelerini Gürcistan''ın;
Karşımda akıyor Aragva uğultulu.
Hem hüzün hem bir hafiflik var içimde; kederliyim,
Seninle dopdolu, aydınlık bir keder bu.
Seninle, sadece seninle... Hiçbir şey
Bozmuyor, tedirgin etmiyor üzgünlüğümü,
Ve yürek yeniden tutuşuyor, seviyor yeniden,
Sevmemesi olanaksız çünkü.
Aleksandr Sergeyeviç PUŞKİN', 'Gece sisi kaplamış tepelerini Gürcistan''ın; Karşımda akıyor Aragva uğultulu. Hem hüzün hem bir hafiflik var içimde; kederliyim, Seninle dopd...', ARRAY['Türk Edebiyatı','Şiir','Aleksandr Sergeyeviç Puşki̇n']::text[], 8.5, '{"poet":"Aleksandr Sergeyeviç Puşki̇n","poet_slug":"aleksandr_sergeyevic_puskin","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE SÖZLERİ', 'gece-sozleri-ahmet-uysal-s8yug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceyle dinlemeli genişleyen
Bir ağacın gövdesini
Üzerine yıldız sekerken
Su vermeli gülün toprağına
Şiir geceyi sever çünkü
Aşk geceyle açıklar kimliğini
Eski bir ırmak yatağında
Yeni bir serüvendir gece
Ve bir kadın sevilmeyi bekler
Gecenin en ince yerinde', 'Geceyle dinlemeli genişleyen Bir ağacın gövdesini Üzerine yıldız sekerken Su vermeli gülün toprağına Şiir geceyi sever çünkü Aşk geceyle açı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE VAKTİ KİMDİR KAPIYI ÇALIP GELEN', 'gece-vakti-ki-mdi-r-kapiyi-calip-gelen-ataol-behramoglu-fptz5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece vakti kimdir kapıyı çalıp gelen
Yitirdiğim bir mutluluk mu
Habercisi mi gelecekteki bir mutluluğun
Gece vakti kimdir kapıyı çalıp gelen
İçimde bağıran acılar mı
Serseri, başıboş bir rüzgar mı
Gece vakti kimdir kapıyı çalıp gelen
Ansızın çıkıp gelen bahar mı
Gece vakti kimdir kapıyı çalıp gelen
Yüreğim mi,damarlarimda hışırdayan kan mı
Bağırarak bu kansız evlerin suratına
Bağırarak bu kansız sokakların suratına
Bağırarak bu kansız insanların suratına
Bağırarak yüreğimdeki kanı
Gece vakti kimdir kapıyı çalıp gelen', 'Gece vakti kimdir kapıyı çalıp gelen Yitirdiğim bir mutluluk mu Habercisi mi gelecekteki bir mutluluğun Gece vakti kimdir kapıyı çalıp gelen...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol_behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE YARISI', 'gece-yarisi-fethi-gi-ray-21u5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gel sen beni affet!
Anam, kardeşim, karım.
Şimdi gece yarısı,
Bu saate ben kaldırımlarda olmalıyım.
Bu saatte,
Alnından öpmeliyim-:
Evine ekmek parası götüren yetim çocuğun
O ufacık, o çıplak ayakların sesinde,
Utanarak
Duymalıyım yokluğu.
Bu saatte,
Derdini bilmeliyim,
Şu köşe başında sızmış olan adamın,
Bu saatte ben,
Gözlerinde yaş olmalıyım,
Her ağlayanın.', 'Gel sen beni affet! Anam, kardeşim, karım. Şimdi gece yarısı, Bu saate ben kaldırımlarda olmalıyım. Bu saatte, Alnından öpmeliyim-: Evine ek...', ARRAY['Türk Edebiyatı','Şiir','Fethi Gi̇ray']::text[], 8.5, '{"poet":"Fethi Gi̇ray","poet_slug":"fethi_giray","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE. ŞEHİR UYUMUŞ.', 'gece-sehi-r-uyumus-aleksandr-blok-ds568', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '* * *
Gece. Şehir uyumuş.
Kocaman pencerenin ardında
Can çekişen bir adam gibi
Sakin, heybetli.
Camın önünde kederli biri
Küsmüş talihine,
Göğsü bağrı açık
Yıldızlarda gözleri.
-Yıldızlar, yıldızlar!
-Nedir kederimin sebebi?
Yıldızlarda gözleri.
-Yıldızlar, yıldızlar!
-Nereden geliyor bu keder?
Ve yıldızlar konuşuyor
Anlatıyorlar her şeyi.
Aleksandr BLOK', '* * * Gece. Şehir uyumuş. Kocaman pencerenin ardında Can çekişen bir adam gibi Sakin, heybetli. Camın önünde kederli biri Küsmüş talihine, G...', ARRAY['Türk Edebiyatı','Şiir','Aleksandr Blok']::text[], 8.5, '{"poet":"Aleksandr Blok","poet_slug":"aleksandr_blok","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECEBİTKİLERİNDEN', 'gecebi-tki-leri-nden-cemal-sureya-74dl0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİTKİLERİNDEN
Gece bitkilerinden korkuyorum,
Hayır, geceleri bitkilerden!
Gizlenirken vurulmuş ulaklara ağıttır
Bana açtığın her telefon.
İki kalp arasında en kısa yol:
Birbirine uzanmış ve zaman zaman
Ancak parmak uçlarıyla değebilen
İki kol.
An ki fıskiyesi sonsuzluğun
Keşke yalnız bunun için sevseydim seni.', 'BİTKİLERİNDEN Gece bitkilerinden korkuyorum, Hayır, geceleri bitkilerden! Gizlenirken vurulmuş ulaklara ağıttır Bana açtığın her telefon. İk...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECEDE AYAK SESLERİ', 'gecede-ayak-sesleri-mahmud-dervi-s-ceviren-tkj3k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her zaman
Ayak seslerini duyarız gecede yaklaşan,
Ve kapı sırra kadem basar odamızdan,
Her zaman,
Bulutlar gibi süzülüp giden.
Her gece yatağından
Senin mavi gölgen mi onu uzaklara götüren?
Senin gözlerin ülkelerdir ve ayak sesleri geliyor,
Sardı bedenimi kolların
Ayak sesleri, ayak sesleri
Ah Şahrazad
Gölgeler niçin kurtuluşumu resmeder?
Gelir ayak sesleri girmez içeri.
Bir ağaç ol,
Görebileyim gölgeni.
Bir ay ol,
Görebileyim gölgeni.
Bir hançer ol,
Görebileyim gölgeni gölgemde,
Küller içinde bir gül.
Her zaman,
Ayak seslerini duyarım gecede yaklaşan,
Ve sen yerim olursun sürgündeki,
Zindanım olursun.
Öldürmeye çalış beni
İlk ve son olsun
Yaklaşan ayak seslerinle
Öldürme beni.
Mahmud DERVİŞ', 'Her zaman Ayak seslerini duyarız gecede yaklaşan, Ve kapı sırra kadem basar odamızdan, Her zaman, Bulutlar gibi süzülüp giden. Her gece yata...', ARRAY['Türk Edebiyatı','Şiir','Mahmud Dervi̇ş


çeviren :']::text[], 8.5, '{"poet":"Mahmud Dervi̇ş\n\n\nçeviren :","poet_slug":"mahmud_dervis","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECEDE KANAT SESLERİ', 'gecede-kanat-sesleri-huseyin-yurttas-ktr7t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.
bir kanat sesidir
ay düşmüş ormanlarda
yankısı yıldızları çağırır
yalayıp geçer dorukları
ıslık gibi duyulur ufkun ardından
bir kanat sesidir
taşır kuzey ovalarının serinliğini
yağmurlarını karadeniz''in
safran buğdaylarını içanadolu''nun
bakar maviye çalan gözleriyle ege''nin
gülümser sevinçler yüklü beyazlığıyla akdeniz''in
2.
gecede kanat sesleri var
akan kuşların çığlıklarıdır
kar ıssızlığında kışlar bırakarak
düzler yokuşlar bırakarak
düşmüşler işte kara afrika yollarına
gecede kanat sesleri var
geçiyorlar terkedilmiş köyleri
yıkılmış kentleri, yok olmuş uygarlıkları
dualar gibi gizem dolu fısıltılarla
karışıyor bulutlara
nasılsa birden katılıyorum onlara
yükseliyorum bir damla su gibi
toprağımın kokusunu taşıyarak
ırmaklarımın coşkusunu taşıyarak
elsiz ayaksız
kolsuz kanatsız
uçmaya çalışarak
ülkem
yağmur emmiş bir tombul çocuk gibi
denizler koynunda
derin, soluksuz bir uykuda
yollarında, ırmaklarında, köprülerinde
damar damar akışan sevinç
dal dal uzanan öfke
yaprak yaprak dökülüyor hışmıyla gecenin
ülkem
belâsını baştacı ettiğim toprağım
deli divane eyliyor beni yücelerde
dönüp duruyorum işte
kanat sesleri arasında
3.
-burdan ötesi
gidilmez bir yolun, varılmaz bir durağıdır ki
aktığım mı, yürüdüğüm mü, uçtuğum mu
bilemediğim
kara afrika yollarında gece yolcusuyum
yoldaşım kuşlar tutmuş elimden
kanatları sırça, ''gagaları gümüş'' kuşlar
karlı sonsuzlukların
tozutan tipilerin tezikmeleriyle
kanat vuruyoruz
burdan ötesi
gidilmez bir yolun varılmaz durağı da olsa
tutkum benim
orda küçük kulübelerdeki zenci çocuklarına
bataklık kuşlarına
geyiklerin seğirttikleri yamaçlara
bir selâm gibi varmak
bir akdeniz rüzgârı gibi onları okşamak
varsın bitmesin yolları! -
kaç yüzyılın demir hevenklerinin sallandığı
şu uygarlık bağından
göçüp giden
bir yavru kuş olayım ben
-ki burdan ötesi
uçulmaz uçurumlar da olsa
verip kendimi boşluklara
sıradan bir ölümün çok ötelerinde
ağmak sonsuza doğru
varmak dünya halklarının
haramiler önündeki sofrasına
bir pençeyle alıp çalınmışı
güldürmek afrika çocuklarını
dünyayı ışıtan o bembeyaz dişleriyle!-
gecede kanat sesleri var
ben ordayım
ne bitkinim ne yorgun
esrimiş esiyorum
yıldızlar bahçesinde', '1. bir kanat sesidir ay düşmüş ormanlarda yankısı yıldızları çağırır yalayıp geçer dorukları ıslık gibi duyulur ufkun ardından bir kanat ses...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Yurttaş']::text[], 8.5, '{"poet":"Hüseyin Yurttaş","poet_slug":"huseyin_yurttas","theme":"Türk Şiiri","is_hero":false,"total_lines":84}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECELEYİN', 'geceleyi-n-ulku-tamer-jv6ve', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceleyin karanlıkta
Suya attım ben sesimi
Türkü oldu birdenbire
Denizinden geçen gemi
Geceleyin karanlıkta
Gülümsedim buluta ben
Saçlarına düşen yağmur
Gökkuşağı oldu birden
Geceleyin karanlıkta
Yıldız tuttum gök içinde
Işığını sana vurdu
Bir gül açtı yüreğinde', 'Geceleyin karanlıkta Suya attım ben sesimi Türkü oldu birdenbire Denizinden geçen gemi Geceleyin karanlıkta Gülümsedim buluta ben Saçlarına ...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku_tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECENİN GEÇ SAATİ', 'geceni-n-gec-saati-ataol-behramoglu-xqnm6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin geç saati, yaklaşan motor sesi, fren
Gülümser uykusunda yavrum, bir düş içinden
Kulağım tetikte, beklerim çağrılmadık konukları
Araba geçip gider kapının önünden
1981', 'Gecenin geç saati, yaklaşan motor sesi, fren Gülümser uykusunda yavrum, bir düş içinden Kulağım tetikte, beklerim çağrılmadık konukları Arab...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol_behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECENİN KANAYAN YERİNDEN', 'geceni-n-kanayan-yeri-nden-ahmet-ozer-uywbt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gece yarısı bir el dokunuyor soluğuma
bir aşkın kan damlası karışıyor yağmura
kitaplardan yüreğime dolan gelincikler
güneşli papatyaları seyreyleyen turnalar
bir yelkenli açılıyor alnımın çatısına.
sizlerin gençliğini taşıdım kanımda
ey güzel çocuklar sesime ses katanlar
şimdi renklerle savruluyorum ardınızdan
adlarınızı unutmadım/yüzünüz silinmiyor aklımdan.
sevincim bir çığlık gibi savruluyor dünyaya
kelebek kanatları/kuş sesleri dökülüyor gömleğime
bir nehir akıyordu gecenin sessizliğine
bütün güneşler kayıp gitmişti ellerimden
her ölüm bir şiiri büyütüyordu dilimde.
çok şey anlatıyordu gecenin yüzü
yağmurlu bir kasım karanlığını geçerek
korkuyu yenen bir aşkın seveniydim
bir gül yaprağıydım rüzgârda.
güzelliğiniz kazılıyor gençliğin mavi ufkuna
yarama tuz basarak geçiyorum günleri
bir ses yankılansa yüreğimi örseleyen
bir fotoğraf dökülse yüzünde solgun çiçekler
göğsümden havalanır martı sürüleri.
şimdi karlar yağar yüzüne dünyanın
istasyonların uykusunu yitirmiş derinliğine
şafakla yırtılan gecenin kanayan bir yerine.', 'gece yarısı bir el dokunuyor soluğuma bir aşkın kan damlası karışıyor yağmura kitaplardan yüreğime dolan gelincikler güneşli papatyaları sey...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECENİN NAL SESLERİ ARASINDA', 'geceni-n-nal-sesleri-arasinda-ingeborg-bachmann-kwuw7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin büyük kapısı önündeki kara beygirin nal sesleri arasında,
hâlâ titriyor yüreğim bir zamanlarki gibi ve uzatıyor eyeri uçarcasına,
Diomedes''in ödünç verdiği yular gibi, kıpkırmızı.
Güçlü rüzgâr öncülüğümü yapmakta
karanlık yollarda ikiye bölerek uyuyan
ağaçların kapkara örgüsünü,
öyle ki, ay ışığıyla yıkanan meyveler
korkuyla sırtlara ve kılıçlara atlamaktalar,
ve ben indiriyorum kırbacımı
sırtına, çoktan sönmüş bir yıldızın.
Yalnızca bir kez yavaşlatıyorum adımlarımı, senin nankör dudaklarını
öpmek için, saçların dizginlere dolanmış
bile, ve pabuçların kumlarda sürükleniyor.
Hâlâ duymaktayım soluğunu
bir de hançer gibi sapladığın
o sözcüğü.
Ingeborg BACHMANN', 'Gecenin büyük kapısı önündeki kara beygirin nal sesleri arasında, hâlâ titriyor yüreğim bir zamanlarki gibi ve uzatıyor eyeri uçarcasına, Di...', ARRAY['Türk Edebiyatı','Şiir','Ingeborg Bachmann']::text[], 8.5, '{"poet":"Ingeborg Bachmann","poet_slug":"ingeborg_bachmann","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECENİN SESİ', 'geceni-n-sesi-enis-batur-7tg2p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaptanın uykusu kaçtı birden;
birden külçe gibi üstüne indi
gece ve yalnızlık, kalktı, bir
havlu aldı sırtına, küpeşteye
tırmandı yavaşça, duydu:
Çocuğu uyutmuştu kadın; uzun,
yılansı bacağını siper etmişti
düşmesin diye dönerken kar
yatakta: uğulduyor, tutuşuyordu
erkeğin başını gömdükçe yinine:
İçinden büyük bir kuş havalanıyor
uzağa süzülüyordu.', 'Kaptanın uykusu kaçtı birden; birden külçe gibi üstüne indi gece ve yalnızlık, kalktı, bir havlu aldı sırtına, küpeşteye tırmandı yavaşça, d...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECENİN TAM ÜÇÜNDE', 'geceni-n-tam-ucunde-fikret-kizilok-pwjeq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düz değil düzen değil az değil ezen değil
Boz değil bozan değil
Bir gül biter içimde içimde içimde
Tam bildiğim biçimde biçimde biçimde
Oy gecenin tam üçünde gecenin tam üçünde
Sevda gibi kanımda can verirken elimde
Pençe gibi düşümde uy değil uyku değil
Uy değil uyku değil
Bir gül biter içimde
Gecenin tam üçünde
Can değil canan değil er değil eren değil
Geç değil erken değil
Bir gül biter içimde içimde içimde
Tam bildiğim biçimde
Oy gecenin tam üçünde gecenin tam üçünde', 'Düz değil düzen değil az değil ezen değil Boz değil bozan değil Bir gül biter içimde içimde içimde Tam bildiğim biçimde biçimde biçimde Oy g...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kizilok']::text[], 8.5, '{"poet":"Fikret Kizilok","poet_slug":"fikret_kizilok","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECİKMİŞ SEVDA', 'geci-kmi-s-sevda-tudor-arghezi-i8iv2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evet, artık karşılık verebilirdim tutkuna senin.
Akıl olmaz, diyordu, olur diyordu gönlüm.
Senin ateşine yanmam için sanıyorum ki
Fırtınalarla sürüklenip gideceğim ben.
Nerden çıktın böyle yalaz yalaz
Ateş yıldızlarıyla sarmak için dört bir yanımı?
Aldırmasan da şimdi ortada ve açık.
Çocuğum yerindesin benim,
Ya da çocuğum olabilirdin.
Aşkın kanatlanıp uçuşu hep birden olur,
Ayrım gözetmez, bir araya toplar insanları,
Önemi kalmaz yaşın, eşitlenir,
Tutkulu, ateşli ve çekici olur kadın.
Sen nasıl da tazesin, fidansın, yaşam dolu.
Senin olmamı istiyorsun, kuşkusuz, endişesiz,
Benimle ilgili ne varsa, seninle ilgili ne varsa.
Kurban edilmiş akşamdan sabaha.
Kendini bana vermek istedin, bırakıp dünyanı,
Benim şiir evrenime.
Birden seni saran sarhoşluk
Seni delice saldırına boyun eğdirmeye kalktı bana,
Yok sayarak bir yasayı ve unutarak
Her eğilenin sırtına bir yük vurulduğunu.
Sana acı çektirdim, biliyorum,
İşin kötüsü seni yaraladım da.
Hele dudaklarını tutkuyla arzulardım
O kıyıcı kırmızı dudaklarını
O güzelim lâl dudaklarını
Yırtıcı küçücük dişlerinle ısırırdın
Isırırdın
Ah sevgilim! Ah merhametsizim benim
İçin el verse. Kirazdır yaban çileğidir
Kızıl ve lâl taşı dudağın.
İsterdim çekici bedenini
Mintanının altında gizlediğin hazineleri
Güzelliklerini bana göstermediğin
Sevgiline sakladığın
Tan ağartısı kadar ak ve lekesiz bedenini.
Tudor ARGHEZI', 'Evet, artık karşılık verebilirdim tutkuna senin. Akıl olmaz, diyordu, olur diyordu gönlüm. Senin ateşine yanmam için sanıyorum ki Fırtınalar...', ARRAY['Türk Edebiyatı','Şiir','Tudor Arghezi']::text[], 8.5, '{"poet":"Tudor Arghezi","poet_slug":"tudor_arghezi","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇEN YILIN EKSİK GAZELİ', 'gecen-yilin-eksi-k-gazeli-mehmet-taner-kf11y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum, kalb çömleğimi al
Kalbimin meyhanesini akşamla al
Kentleri bırakmak yangınlardır ha!
Evim yandı, bu yangın evimi al!
Böyle gece gece mandalını çektim kapının
Geldim ışık içinde hırsızlama Al', 'Seni seviyorum, kalb çömleğimi al Kalbimin meyhanesini akşamla al Kentleri bırakmak yangınlardır ha! Evim yandı, bu yangın evimi al! Böyle g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇEN ZAMAN', 'gecen-zaman-ziya-osman-saba-7lzo4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç olmazsa unutmamak isterdim.
Eski geceler, sevdiklerimle dolu odalar...
Yalnız bırakmayın beni hatıralar.
Az yanımda kal çocukluğum,
Temiz yürekli uysal çocukluğum...
Ah, ümit dolu gençliğim,
İlk şiirim, ilk arkadaşım, ilk sevgilim...
-Doğduğum ev. Rahatlıyacak içim duysam
Bir tek kapının sesini.
Arıyorum aklımda bir ninni bestesini...
Böyle uzaklaşmayın benden, yaşadığım günler.
Güneş, getir bir bayram sabahını.
Açılın açılın tekrar
Çocuk dizlerimdeki yaralar,
Hepiniz benimsiniz:
Mektebim, sınıflarım, oturduğum sıralar...
Yalnız hatırlamak hatırlamak istiyorum
Nerde kaldı sevgilim, seni ilk öptüğüm gün,
Rengine doymadığım o sema,
Ahengine kanmadığım ırmak.
Bırakıp herşeyi nereye gidiyorum?
Neler geçmişti aklımdan,
Nedendi ağladığım, nedendi güldüğüm?
Ah nasıldı yaşamak?', 'Hiç olmazsa unutmamak isterdim. Eski geceler, sevdiklerimle dolu odalar... Yalnız bırakmayın beni hatıralar. Az yanımda kal çocukluğum, Temi...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya_osman_saba","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇEN ZAMANIN TÜRKÜSÜ', 'gecen-zamanin-turkusu-afsar-ti-muci-n-43zwv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir de pisliğin çiçek gibi büyüttüğü
Uyuşuk ve anlamsız otlar var
Ünlü yayınevlerinde
Halka ışık tutan bütün romancılar
Öfkeli öfkesiz bütün ressamlar
Ve bütün ince kemancılar
Büyük adamların anlayışlı eşleri
İnsan pazarının reklam şairleri
Ben gidince geriye kalacaksınız benden
Her zaman böyle olur
Rüzgâr toz bulutları bırakır giderken
İçindeki karmaşayı dünyaya taşıyanlar
Eğri düşünenler doğru konuşanlar
Eli kalem tutanların bütünü
İçki sofralarının eşsiz bilgeleri
Emeğe alkış tutan tembel sürüleri
Ben gidince geriye kalacaksınız benden
Her zaman böyle olur
Rüzgâr toz bulutları bırakır giderken
Gönlündeki yalnızlığı içimize getiren
Bütün kafalılar bütün şakacılar
Felsefeye önem veren düşünür artıkları
Sanat dünyasının doygun yaratıkları
Düşünce toptancıları duygu işportacıları
Ben gidince geriye kalacaksınız benden
Her zaman böyle olur
Rüzgâr toz bulutları bırakır giderken', 'Bir de pisliğin çiçek gibi büyüttüğü Uyuşuk ve anlamsız otlar var Ünlü yayınevlerinde Halka ışık tutan bütün romancılar Öfkeli öfkesiz bütün...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEL DOSTA GİDELİM GÖNÜL', 'gel-dosta-gi-deli-m-gonul-yunus-emre-el26k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoldaş olalım ikimiz
Gel dosta gidelim gönül
Haldaş olalım ikimiz
Gel dosta gidelim gönül
Gel gidelim can durmadan
Suret terkini urmadan
Araya düşman girmeden
Gel dosta gidelim gönül
Gel gidelim kalma ırak
Dost için kalalım yarag
Şeyh''in katındadır durak
Gel dosta gidelim gönül
Terk edelim ili şarı
Dost için kılalım zarı
Ele getirelim yâri
Gel dosta gidelim gönül
Bu dünyaya kanmayalım
Fanidir aldanmayalım
Bir iken ayrılmayalım
Gel dosta gidelim gönül
Biz bu cihandan geçelim
O dost iline uçalım
Arzu hevadan geçelim
Gel dosta gidelim gönül
Kılavuz olgıl sen bana
Yönelelim dosttan yana
Bakmayalım önden sona
Gel dosta gidelim gönül
Bu dünya olmaz payidar
Aç gözünü canın uyar
Olgıl bana yoldaş u yâr
Gel dosta gidelim gönül
Ölüm haberi gelmeden
Ecel yakamız almadan
Azrail hamle kılmadan
Gel dosta gidelim gönül
Gerçek erene varalım
Hakk''ın haberin soralım
Yunus Emre''yi alalım
Gel dosta gidelim gönül', 'Yoldaş olalım ikimiz Gel dosta gidelim gönül Haldaş olalım ikimiz Gel dosta gidelim gönül Gel gidelim can durmadan Suret terkini urmadan Ara...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEL GÖR BENİ AŞK NEYLEDİ', 'gel-gor-beni-ask-neyledi-yunus-emre-zfecz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben yürürüm yana yana
Aşk boyadı beni kana
Ne âkilem ne divane
Gel gör beni aşk neyledi
Gâh eserim yeller gibi
Gâh tozarım yollar gibi
Gâh akarım seller gibi
Gel gör beni aşk neyledi
Akar suların çağlarım
Dertli ciğerim dağlarım
Şeyhim anuban ağlarım
Gel gör beni aşk neyledi
Ya elim al kaldır beni
Ya vaslına erdir beni
Çok ağlattın güldür beni
Gel gör beni aşk neyledi
Ben yürürüm ilden ile
Şeyh anarım dilden dile
Gurbette halim kim bile
Gel gör beni aşk neyledi
Mecnun oluban yürürüm
Ol yâri düşte görürüm
Uyanıp melûl olurum
Gel gör beni aşk neyledi
Miskin Yunus biçareyim
Baştan ayağa yareyim
Dost elinde avareyim
Gel gör beni aşk neyledi', 'Ben yürürüm yana yana Aşk boyadı beni kana Ne âkilem ne divane Gel gör beni aşk neyledi Gâh eserim yeller gibi Gâh tozarım yollar gibi Gâh a...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEL GİTME', 'gel-gi-tme-huseyin-atabas-d4elv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdaya açılan bir penceredir
odaları dolduran güneşli sesin.
Kuraktan sedefi çatlamış tanrıçalar
ve atlar denize inme özlemiyle oysa
her akşam üstü geçerler rahvan.
Bakarsın o an
gökyüzü ufuk çizgisiyle buluşmada,
karnını yükseltmiş hafifçe deniz
gelgit,
gel ve gitme n''olur!..
O an küçücük bir özlemdir
içimize sulardan düşen iz.
Bir yanım dövme bakır,
bir yanım mavi güller;
gözleri ''fındık yeşil'' kızların
el emeği, göz nuru deniz.
Omuzlarının yuvarlaklığı
akıyor avuçlarımdan;
herkes, her şey alesta
ve sessiz!..
Öyle bir gün gelir ki
lâle büyür sedefinde tanrıçaların,
göğü doldurur koynundaki serçeler;
gel gitme n''olur!..', 'Sevdaya açılan bir penceredir odaları dolduran güneşli sesin. Kuraktan sedefi çatlamış tanrıçalar ve atlar denize inme özlemiyle oysa her ak...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atabaş']::text[], 8.5, '{"poet":"Hüseyin Atabaş","poet_slug":"huseyin_atabas","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEL VUR', 'gel-vur-bedri-rahmi-eyuboglu-lg4do', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak şu güneş nasıl geliyor.
Sen de öyle gel be!!!!
Bak şu ışık nasıl vuruyor
Sen de öyle vur be!!!!', 'Bak şu güneş nasıl geliyor. Sen de öyle gel be!!!! Bak şu ışık nasıl vuruyor Sen de öyle vur be!!!!...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyuboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyuboğlu","poet_slug":"bedri_rahmi_eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELDİ GEÇTİ ÖMRÜM BENİM', 'geldi-gecti-omrum-beni-m-yunus-emre-wyjr1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geldi geçti ömrüm benim şol yel esip geçmiş gibi
Hele bana şöyle geldi şol göz yumup açmış gibi
İşbu söze Hak tanıktır bu can gövdeye konuktur
Bir gün ola çıka gide kafesten kuş uçmuş gibi
Miskin âdem oğlanını benzetmişler ekinciye
Kimi biter kimi yiter yere tohum saçmış gibi
Bu dünyada bir nesneye yanar içim göynür özüm
Yiğit iken ölenlere gök ekini biçmiş gibi
Bir hastaya vardın ise bir içim su verdin ise
Yarın anda karşı gele Hak şarabın içmiş gibi
Bir miskini gördün ise bir eskice virdün ise
Yarın anda sana gele Hak libâsın biçmiş gibi*
Yunus Emre bu dünyada iki kişi kalur derler
Meğer Hızır İlyas ola abı hayat içmiş gibi
*Yarın anda karşı gele hulle donun biçmiş gibi', 'Geldi geçti ömrüm benim şol yel esip geçmiş gibi Hele bana şöyle geldi şol göz yumup açmış gibi İşbu söze Hak tanıktır bu can gövdeye konukt...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELECEK ÖLÜM - GÖZLERİ GÖZLERİN OLACAK', 'gelecek-olum-gozleri-gozleri-n-olacak-cesare-pavese-mk7fz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gelecek ölüm - gözleri gözlerin olacak
sabahtan akşama dek, gözünü kırpmadan,
sağırcasına, eski bir vicdan acısı gibi
saçma bir alışkanlık gibi
ardımızdan kovalayan bu ölüm
gelecek bir gün
Boş bir sözden ayrımsız olacak gözlerin
aynada kendini gördüğünden ayrımsız her sabah,
suskun bir çığlık, bir sessizlik olacak.
Ey sevgili umut, o gün biz de bileceğiz
hem yaşam hem hiçsin sen bile, ey sevgili umut!
Herkese birdir bakışı ölümün
Gelecek ölüm - gözleri gözlerin olacak
bir alışkıyı bırakırcasına
ölü bir yüzün belirdiğini görürcesine aynada
kenetli bir dudağı dinlercesine
sessizce ineceğiz o dipsiz burgaca.
Cesare PAVESE', 'Gelecek ölüm - gözleri gözlerin olacak sabahtan akşama dek, gözünü kırpmadan, sağırcasına, eski bir vicdan acısı gibi saçma bir alışkanlık g...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare_pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELECEK OLAN SAVAŞ', 'gelecek-olan-savas-bertolt-brecht-5p8qa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk savaş değil. Ondan önce
Başka savaşlar da oldu.
En sonuncusu bittiğinde
Kazananlarla yenilenler vardı.
Yenilen yanda yoksul halk
Açlıktan kırıldı. Kazanan yanda
Açlıktan kırıldı yine yoksul halk.', 'İlk savaş değil. Ondan önce Başka savaşlar da oldu. En sonuncusu bittiğinde Kazananlarla yenilenler vardı. Yenilen yanda yoksul halk Açlıkta...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt_brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELECEK', 'gelecek-bertolt-brecht-lc8tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ormanlar daha gür olacak, daha gür.
Tarlalar daha çok şey verecek, daha çok şey.
Şehirler daha canlı olacak, daha canlı.
İnsan ömrü daha uzun olacak, daha uzun.
Bertolt BRECHT', 'Ormanlar daha gür olacak, daha gür. Tarlalar daha çok şey verecek, daha çok şey. Şehirler daha canlı olacak, daha canlı. İnsan ömrü daha uzu...', ARRAY['Türk Edebiyatı','Şiir','Bertolt Brecht']::text[], 8.5, '{"poet":"Bertolt Brecht","poet_slug":"bertolt_brecht","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELECEĞİN ŞAİRLERİ', 'gelecegi-n-sai-rleri-walt-whitman-1mu0j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geleceğin şairleri! geleceğin söylevcileri, şarkıcıları, çalgıcıları!
Bugün doğrulayamaz beni, ne istediğimi, neden yana olduğumu bilemez,
anlatamaz bugün,
Ama siz, yeni bir döl, katışıksız, atletik, bu toprağın yetiştirdiği çocuklar,
gelmiş geçmiş döllerin en büyüğü,
Kalkın! çünkü siz doğrulayacaksınız beni.
Ben gelecek için yalnızca bir iki aydınlatıcı sözcük söylerim,
Karanlıkta bir an ileri atılıp yolu gösterir, gene geri çekilirim.
Ben, yavaş yavaş, salına salına yürüyen, ama hiç durmayan bir insanım,
arada bir size kaçamak bir göz atar, sonra hemen başımı çeviririm,
İnandırmayı, anlatmayı size bırakıyorum,
En önemli şeyleri sizden bekliyorum.
Walt WHITMAN
Çeviren : Memet Fuat
Şiirin Aslı :', 'Geleceğin şairleri! geleceğin söylevcileri, şarkıcıları, çalgıcıları! Bugün doğrulayamaz beni, ne istediğimi, neden yana olduğumu bilemez, a...', ARRAY['Türk Edebiyatı','Şiir','Walt Whitman']::text[], 8.5, '{"poet":"Walt Whitman","poet_slug":"walt_whitman","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELECEĞİN ŞAİRLERİNE BİR ÇİFT SÖZ', 'gelecegi-n-sai-rleri-ne-bi-r-ci-ft-soz-dritero-agolli-fts5u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bizim aşkı yazacak zamanımız olmadı hiç
düşünmeden hareket eden âşıklar olduğumuzdan
vatan özgürlük türkülerine gereksinim duyuyordu
vatan tarlalarda olgunlaşan tohumların türkülerine gereksinim duyuyordu
vatan  buyuruyordu bizim yoksul şairlerimize
bilisizlikle savaşmayı öğreniyorduk
ırmaklara baraj yapıyorduk
dağlarda sosyalizmin ışıklarını yakıyorduk
dert etme sen gözünü yeni açan şair
ve yargılama bizi her şeyi tamamlayamadığımız için
kendine benze, biz bakacağız mizacını ve taşınması güç
bukağılar yüklenmiş basit keşişler gibi
uykusuz gecelerimizi çok harcadık
birçok büyük işin tamamladığına tanık olduk
kısacık da olsa bir çift aşk şiiri yazabilir miydik
kekeleyemediysek de ey sevgili aşkım, diye
inanma sen yüreğimizin olmadığına! görebilseydin eğer
neler çektik sevdiğimiz kızlardan neler işittik bir bilsen
ne tatlı şeyler fısıldadık kulaklarına bu ışık saçan gecelerde
ama zamanımız yoktu bu tatlı şeyleri yayımlamaya
yayıncılarımız da meşguldü çok önemli işler yapmakla
Dritero  AGOLLİ', 'bizim aşkı yazacak zamanımız olmadı hiç düşünmeden hareket eden âşıklar olduğumuzdan vatan özgürlük türkülerine gereksinim duyuyordu vatan t...', ARRAY['Türk Edebiyatı','Şiir','Dritero  Agolli̇']::text[], 8.5, '{"poet":"Dritero  Agolli̇","poet_slug":"dritero_agolli","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELGİT', 'gelgi-t-roni-margulies-2bev7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk geldiğimde İngiltere''ye
yıllardan yetmiş iki yılında
ve ilk gördüğümde Thames
nehrini,
&quot;Nasıl da&quot; demiştim, kendi
kendime, &quot;suları kahverengi.
Nerede Boğaz''ın o maviliği,
o berrak sular!&quot;
Yıllar sonra yürüdüğümde
kıyısında nehrin bir akşamüzeri
çekildiğini gördüm suların,
izledim saatlerce.
Akdeniz''de gelgit olmadığını
Londra''da öğrendim o gece.
Öğrendiğim gibi büyük kısmını
tüm öğrendiklerimin.
Sonra kaç defa şu veya bu kadınla
sular çekildiğinde açıkta kalan
yatağında yürüdüm nehrin,
elleri elimde, yanak yanağa.
Ne zaman suların çekildiğini
görsem şimdi, Elsa gelir yine aklıma.
Gelenler geldi, gidenler gitti,
Elsa kaldı yatağı gibi nehrin hayatımda.', 'İlk geldiğimde İngiltere''ye yıllardan yetmiş iki yılında ve ilk gördüğümde Thames nehrini, &quot;Nasıl da&quot; demiştim, kendi kendime, &qu...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELMEDİN', 'gelmedi-n-mahzun-dogan-7y91o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırılmış bir cama döndü gök
evsiz barksızların konakladığı eski bir handa
Kalakaldı ruhumdan koşan atlar
Her sabah gülümseyerek baktığım ufuk
Koparmışlar dillerini çanların
bütün ampulleri kırmışlar
Kurtlar bile ulumuyor, nasıl bulsam yönümü
Gelmedin, bütün kitaplar yarım
Kent bir halı eskisi
aşkla dokunan desenler solmuş
o delifişek sevişmeler, koşturmacası karanfillerin
unutulmuş. Kim
hangi şarkıda dinler beni
İşte gözlerimi bağlıyorum
sevin ey yeryüzü!
kökü çürümüş bir difenbahya
kalbim', 'Kırılmış bir cama döndü gök evsiz barksızların konakladığı eski bir handa Kalakaldı ruhumdan koşan atlar Her sabah gülümseyerek baktığım ufu...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğan']::text[], 8.5, '{"poet":"Mahzun Doğan","poet_slug":"mahzun_dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇİLMEZ DENİZ', 'geci-lmez-deni-z-murathan-mungan-4ic0w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I-
ahreli bir kağıt üstüne simsiyah kapanmışım
kazırım kendimi bir secdeden, ellerimde gizli hattatlar
ve söze gelmez devrik duyarlıklarım
gözlerim -hüznün dilsiz masalcısı-
gözlerimde hiçbir dile çevrilmez intiharlar
oysa saklı hançerimi mağrur bildiniz
kendimin tenha bir yerinde vurulmuşum, yatarım
orası bir denizin gölgesidir, göremezsiniz
(bir peygamberin yanlış ayakları
intihar halinde sevişmektedir)
ölüm üzre bir akrepken menekşelenirsiniz
ve ahreli kağıtlar dürülür ferman diye
yufka ölümlerin hazin tarihleriyle
kar altında kalmış imzasız karanlıklarım
ve azgın sularda kendini arayan deniz
ben konuşmam, susarım
bu aklamaz ki sizi
katilimsiniz
II-
katilimsiniz en azgın sularda
ellerinizde kan mürekkepleri sarhoş
ölüm nasıl bir sarmaşık ki
(deniz gören) en mağrur balkonlarda
bir gün siz de katilleri seversiniz', 'I- ahreli bir kağıt üstüne simsiyah kapanmışım kazırım kendimi bir secdeden, ellerimde gizli hattatlar ve söze gelmez devrik duyarlıklarım g...', ARRAY['Türk Edebiyatı','Şiir','Murathan Mungan']::text[], 8.5, '{"poet":"Murathan Mungan","poet_slug":"murathan_mungan","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELMEZ YOLA GİDİYORUM*', 'gelmez-yola-gi-di-yorum-asik-veysel-satiroglu-ba93v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Selam saygı hepinize
Gelmez yola gidiyorum
Ne şehire ne de köye
Gelmez yola gidiyorum
Gemi bekliyor limanda
Gideceğim bir ummanda
Gözüm kalmadı cihanda
Gelmez yola gidiyorum
Eşim dostum yavrularım
İşte benim sonbaharım
Veysel karanlık yollarım
Gelmez yola gidiyorum
*Aşık Veysel''in son şiiri', 'Selam saygı hepinize Gelmez yola gidiyorum Ne şehire ne de köye Gelmez yola gidiyorum Gemi bekliyor limanda Gideceğim bir ummanda Gözüm kalm...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatiroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatiroğlu","poet_slug":"asik_veysel","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇİLMEZ', 'geci-lmez-necip-fazil-kisakurek-nyfbe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kapıdan kol ve kanat kırılmadan geçilmez;
Eşten, dosttan, sevgiliden ayrılmadan geçilmez.
İçeride bir has oda, yeri samur döşeli;
Bu odadan gelsin diye çağrılmadan geçilmez.
Eti zehir, yağı zehir, balı zehir dünyada,
Bütün fani lezzetlere darılmadan geçilmez.
Varlık niçin, yokluk nasıl, yaşamak ne, topyekün?
Aklı yele salıverip çıldırmadan geçilmez.
Kayalık boğazlarda yön arayan bir gemi;
Usta kaptan klavuza varılmadan geçilmez.
Ne okudun, ne öğrendin, ne bildinse berhava;
Yer çökmeden, gök iki şak yarılmadan geçilmez.
Geçitlerin, kilitlerin yalnız O''nda şifresi;
İşte, işte o eteğe sarılmadan geçilmez!', 'Bu kapıdan kol ve kanat kırılmadan geçilmez; Eşten, dosttan, sevgiliden ayrılmadan geçilmez. İçeride bir has oda, yeri samur döşeli; Bu odad...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELİNCİK TOZLARI', 'geli-nci-k-tozlari-bulent-ozcan-crxlf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Okumadan atladığın sayfalar,
Hayatının kırık notlarıdır...
Anılar, şimdi o yorgun sular;
Bu şiirin kanayan rüzgârıdır...
Her ırmak kendi göğüne yaslanır,
Her kuş kendi göğünü gök sanır...
Sahiplenerek yürüdüğün o ömür var ya;
Havada uçuşan gelincik tozlarıdır...', 'Okumadan atladığın sayfalar, Hayatının kırık notlarıdır... Anılar, şimdi o yorgun sular; Bu şiirin kanayan rüzgârıdır... Her ırmak kendi göğ...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELİNLİK KIZIN ÖLÜMÜ', 'geli-nli-k-kizin-olumu-melih-cevdet-anday-hrebj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Salâ verilirken kalktık kahveden,
Cumaydı, yılın en beklemiş günü,
Yemeni gibi üstünde tabutun,
Gölge veren ağaçsız bir gökyüzü.
Kızın babası yanımızda, boyu uzun,
Zayıf, ağzında mırıltılar.
On köylü, iki subay, bir tezkereci er,
Sıralandık ahşap mescidin avlusunda,
Namaz kılmadı adam, ağlamıyordu da,
Alnı bir uzun sabrın kabaran gelgiti,
Sürgün duvarı bekleyişin,
Dünyaya çok yakın bir gece gibi.
Aldık cenazeyi sarsmadan, iğreti
Ve hafif, gözlerimiz yerde,
Kayıp bir tayın izini süreriz sanki.
Kapılarda başları çatkılı kadınlar
Sallanıyorlardı sisli giysilerinde
Yüklüğe saklanmış çevreler gibi soluk,
Bölünmüş gibi yılın en katı ekmeği
İmece sofrasında hıçkırığın,
Kim bilir kaç ölümden kalma saçı gibi.
Susmuştu çekirgelerin kabuğu,
Toprak kumruları güneşin,
Ve köpeklerin yediği kemiksiz sabah,
Susmuştu göğün sarnıcı, boş.
Cemaat yürüyordu kaplumbağa gibi,
Mezarlığa doğru yüzyıldan,
Sarısabırların yanından, acelesiz.
Ayrık otu yolmaya gidiyor sanırsın,
Davul vurmaya, ay tutulmuş,
Tarladaki yarılmış toprağı görmeye,
Susuzluğun kirli rengini, ayıbını,
Dağa taşa vurmuş açlığı.
Dayanan dayanır, yağsız bulgular ve ahlat,
Gençleri alır ölüm ilk ağızda,
Sabah yıldızının uğrağı.
Böğürtlensiz mezarlığa vardığımızda,
Bir melek lale sümbül dikiyordu,
Lalelerden birini aldı adam,
Girdi kızının mezarına,
Sarıldı, öptü, bıraktı laleyi sonra,
Kefenin üstüne, uykusuz.
Yedi çocuğu gömülüymüş, söylediler,
Bizi aç bırakan bu toprak
Açlıktan ölenlerle beslenir, dediler.
Dönüşün bir kişi omuzladı tabutu,
Toz toprak içinde vardık kahveye,
Yaşlı adam doğru çeşmeye gitti,
Elini yüzünü yıkadı konuşarak
Kendi kendine, duasız, bir tanrı gibi.
1981', 'Salâ verilirken kalktık kahveden, Cumaydı, yılın en beklemiş günü, Yemeni gibi üstünde tabutun, Gölge veren ağaçsız bir gökyüzü. Kızın babas...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":53}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELİRLİ ŞİİR', 'geli-rli-si-i-r-orhan-veli-g321w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul''dan ayva da gelir, nar gelir,
Döndüm baktım, bir edalı yar gelir
Gelir desen dar gelir
Günaşırı alacaklılar gelir.
Anam anam,
Dayanamam,
bu iş bana zor gelir.', 'İstanbul''dan ayva da gelir, nar gelir, Döndüm baktım, bir edalı yar gelir Gelir desen dar gelir Günaşırı alacaklılar gelir. Anam anam, Dayan...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇMİŞ OLA', 'gecmi-s-ola-paul-verlaine-4lsuz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hâtıralar, ne istersiniz benden?.. Sonbahar...
Durgun gökte ardıç kuşları uçuşmadalar,
Güneşten, ölgün ve soluk bir ışık vurmada
İçinde poyrazlar esen sararmış ormana.
Yapyalnızdık, yürüyorduk, türlü hulyalarda;
Saçlarımız ve düşüncelerimiz rüzgârda.
Çevirip güzel gözlerini bana &quot;Hangisi
En güzel günün?&quot; diye sordu o billûr sesi.
Bir melek sesi kadar tatlı, o kadar derin.
Hafif bir gülümseyiş cevap verdi sesine,
Öptüm ellerini, ibâdet edercesine.
-Ah! İlk çiçekler! Ne güzel kokuları vardır!
Ne kadar sevimli bir mırıltıları vardır
Sevilen dudaklardan çıkan ilk   e v e t ''lerin!
Paul VERLAINE', 'Hâtıralar, ne istersiniz benden?.. Sonbahar... Durgun gökte ardıç kuşları uçuşmadalar, Güneşten, ölgün ve soluk bir ışık vurmada İçinde poyr...', ARRAY['Türk Edebiyatı','Şiir','Paul Verlaine']::text[], 8.5, '{"poet":"Paul Verlaine","poet_slug":"paul_verlaine","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEÇMİŞ YAZ', 'gecmi-s-yaz-yahya-kemal-beyatli-ch5bq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rü''yâ gibi bir yazdı. Yarattın hevesinle,
Her ânını, her rengini, her şi''rini hazdan.
Hâlâ doludur bahçeler en tatlı sesinle!
Bir gün, bir uzak hatıra özlersen o yazdan
Körfezdeki dalgın suya bir bak, göreceksin:
Geçmiş gecelerden biri durmakta derinde;
Mehtâb... iri güller... ve senin en güzel aksin...
Velhasıl o rü''yâ duruyor yerli yerinde!', 'Rü''yâ gibi bir yazdı. Yarattın hevesinle, Her ânını, her rengini, her şi''rini hazdan. Hâlâ doludur bahçeler en tatlı sesinle! Bir gün, bir u...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEMİCİLER', 'gemi-ci-ler-enis-behic-koryurek-3ehkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz dalgalar, fırtınalar kahramanı yiğitleriz.
Ufuklardan ufuklara haber sorar, gezeriz.
Güneşlerde uyuklayan yamaçları,
Kalbi durgun tarlaları bıraktık.
Gölge veren ağaçları
Sevmiyoruz biz artık.
Sevgilimiz,
Ey deniz!
İşte biz;
Nihayetsiz
Mavilikler yolcusu!
Ruhumuzun kardeşidir
Güneşlerde parlayan bu yeşil su.
Bayrağımız yeşil sular ateşidir.
Biz bayrağın fedaisi sayısız Türk genciyiz.
Biz hilale şan arayan korku bilmez gemiciyiz.
Ey vatandan müjdelerle bize kadar gelen rüzgâr!
O sarışın sahillerde kara gözlü genç kızlar,
Yaz gecesi mehtap ile konuşurken,
Doğru söyle, sordular mı bizleri?..
Nasıl cevap verdiği gökten
Gemimizin rehberi,
O vefakâr
Yıldızlar?..
Poyraz var;
Yelken dolar.
Gemi sanki kanatlı!
Enginlerde pembe güneş
Gülümserken bu yolculuk ne tatlı!
Çal sazını kalenderce yiğit kardeş!
Nağmelerin yorulmayan dalgalardan bahtiyar.
Gönderelim bu ahengi o sevgili yurda kadar...', 'Biz dalgalar, fırtınalar kahramanı yiğitleriz. Ufuklardan ufuklara haber sorar, gezeriz. Güneşlerde uyuklayan yamaçları, Kalbi durgun tarlal...', ARRAY['Türk Edebiyatı','Şiir','Enis Behiç Koryürek']::text[], 8.5, '{"poet":"Enis Behiç Koryürek","poet_slug":"enis_behic_koryurek","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENÇ OSMAN DESTANI', 'genc-osman-destani-karacaoglan-wlgq7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İbtida yürüyüş oldu Bağdad''a
Sıçradı hendeği geçti Genç Osman
Vuruldu bayraktar, kaptı bayrağı
İrişti bedene dikti, Genç Osman
Kurşunlarım yağmur gibi yağarken
Tütünlerim gök yüzünde dönerken
Yıkılası Bağdad seni döğerken
Şehitlere serdâr oldu, Genç Osman
Eğerlensin kır atımın ikisin
Fethedeyim düşmanların hepisin
Sabah namazları Bağdad kapısın
Mevlâ izin verdi, açtı Genç Osman
Getirdin de Gen�� Osman''ı görelim
Şahbazımız var idüğün bilelim
Taht isterse tahtımızı verelim
Vezirleri posttan indi Genç Osman
Sultan Murat, Sultan Ahmed''in çırağı
Ah edince getirdi ırağı
Kudretten çatılı anın yüreği
Dal kılıç yazıldı, gitti Genç Osman
Karac''oğlan bunu böyle söyledi
Askerleri dağı taşı boyladı
Bir Bağdad''ı da gayet mehdeyledi
Bin yiğide bir baş oldu Genç Osman', 'İbtida yürüyüş oldu Bağdad''a Sıçradı hendeği geçti Genç Osman Vuruldu bayraktar, kaptı bayrağı İrişti bedene dikti, Genç Osman Kurşunlarım y...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENÇ OZAN', 'genc-ozan-abdulkadir-budak-fmfq8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Bu Mecnun Leylâ''sını değişmedi çöl kumuna
Önce Leylâ''nın Adıyla
Leylâ dedim, yanıt verdi yol tozu
Gurbeti sınayan yolcunun yakasında
Hancı tütün sardı, çorba ısıttı
Leylâ dedim, taş dönüştü yastığa
Leylâ dedim, ateş güle dönüştü
Konuklar büyücü sandılar beni
Çok uzakta yırttı ağı bir balık
Leylâ dedim, şerbet ettim zehiri
Leylâ dedim, oturdu sol yanıma
Avcıyı atlatan bir ürkek ceylan
Barut gül tozuydu, mermi oyuncak
Leylâ dedim, damarlarda kaldı kan
Leylâ dedim, dere indi denize
Kuş öğrendi kanadıyla uçmayı
Acının mürekkebine divit bandırıp
Leylâ dedim, bildim şiir yazmayı', '- Bu Mecnun Leylâ''sını değişmedi çöl kumuna Önce Leylâ''nın Adıyla Leylâ dedim, yanıt verdi yol tozu Gurbeti sınayan yolcunun yakasında Hancı...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENCÖLMEK', 'gencolmek-ergin-gunce-gs3b7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay mıdır kar mıdır pencerede
Boğulmuş çocukları martılara taşıyan
Kara köpek karşı kıyıda uluyor
Bence o çocuk öyle gülmemeli
Atları çayıra saldım diş kamaştıran erik ağaçları altına
Nisan toprağı kalbimde ağarıyor
Bence o çocuk öyle gülmemeli
Şimdi bir kadın çay demlese
Bahçemdeki korkuluk nar ağacıdır
Erken ölmüş, iyi giydirilmiş
Sular soğuyor ovada duran ince gölgesinde
Büyük ateşler, kuytu köyler gibi
Alınlarına vişne çiçekleri yağan
O kızlar, delikanlılar ve lohusalar
Oyulmuş bir bebektirler ıhlamurdan
Kestane mangalları, masallar, talikalar
Ölüm alışsın artık bize
Bir dans gibi bahçemize gelsin
Gelsin otursun ılık minderimize
Ben o çocuk öyle gülmemeli
Ay kar gibidir pencerede', 'Ay mıdır kar mıdır pencerede Boğulmuş çocukları martılara taşıyan Kara köpek karşı kıyıda uluyor Bence o çocuk öyle gülmemeli Atları çayıra ...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin_gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENE BÖYLE', 'gene-boyle-afsar-ti-muci-n-hgp69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yürürlükte hava su ateş toprak
Yürürlükte irili ufaklı atomlar
Çürümüş sanıların karşısında
Bu arada yalnızlık sürümden kazanıyor
Uydurma aşkların yanıbaşında
Kuş uçmuyor korku ormanlarında
Sıkıntı denilen timsah uyanık
Erdemi ve inancı savunuyor kendince
Belki güler geçersin belki de
Gülmeyi bile düşünmezsin
Anlatmazsın bile birilerine
O kadar çıplak
Oh olsun yalancı şairlere
Kokuşmuş bilgelere oh olsun
Gene sokaklar baskın
Her iyide her doğruda her güzelde
Kaçak evlerin sanrılı karanlığı
Demek ki çoktan bitti
Şimdi her yerde orada burada
Eşsiz yağmurlar altında
Bütün kara deniz ve gök haritalarında
Zor ve sessiz bir çocukluktan kalma
Serseri şair ruhum geçerlidir
Geçerlidir dayattığım her özlem
İstanbulun bütün sokaklarında', 'Yürürlükte hava su ateş toprak Yürürlükte irili ufaklı atomlar Çürümüş sanıların karşısında Bu arada yalnızlık sürümden kazanıyor Uydurma aş...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENE GELECEĞİZ', 'gene-gelecegi-z-abu-salma-j93g7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gene geleceğiz
karşılaşmanın yollarında.
Bir bülbül kulağıma fısıldadı:
Gene geleceğiz.
Bülbüller oralarda
yaşarlar henüz.
Şakırlar yazılarımızda.
Gene geleceğiz
gölgeleri arasında özlemin,
yadırgamanın mezarlarında
bizim yerimiz de var,
bu kesin.
Yorulma gönül,
dönüşün yollarında
çökme sakın.
Gene geleceğiz,
gene.
Abu SALMA', 'Gene geleceğiz karşılaşmanın yollarında. Bir bülbül kulağıma fısıldadı: Gene geleceğiz. Bülbüller oralarda yaşarlar henüz. Şakırlar yazıları...', ARRAY['Türk Edebiyatı','Şiir','Abu Salma']::text[], 8.5, '{"poet":"Abu Salma","poet_slug":"abu_salma","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENEL AŞK', 'genel-ask-ahmed-samlu-ng94b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözyaşları bir sırdır
gülümseme bir sır
ve bir sırdır aşk.
Aşkımın gülümsemesiydi
gözyaşları, o gecenin.
*
Öykü değilim anlatasın,
nağme değilim söyleyesin,
ses değilim işitesin
değilim öyle bir şey
ki göresin
ki bilesin
ortak bir acıyım ben
haykırsın beni, sesin.
*
Ağaç ormanla konuşuyor
ot ovayla
yıldız kâinatla
ve ben
seninle konuşuyorum
Adını söyle bana
elini ver bana
lafını söyle bana
kalbini ver bana
ben köklerini anladım senin
senin dudaklarınla konuştum tüm dudaklara
tanıdık ellerimle ellerin.
*
Aydınlık tenhalarda seninle ağladım
yaşayanlar için
karanlık mezarlıklarda seninle söyledim
en güzel şarkıları
çünkü bu yılın ölüleri
en aşık yaşayanlardı.
*
Ellerini ver bana
tanıdık ellerimle ellerin
ey, geç bulunmuş!
seninle konuşuyorum
bulutun tufanla
otun ovayla
yağmurun denizle
kuşun baharla
ağacın ormanla konuştuğu gibi
köklerini anladım senin, çünkü
çünkü
tanıdık sesimle sesin.
Ahmed  ŞAMLU', 'Gözyaşları bir sırdır gülümseme bir sır ve bir sırdır aşk. Aşkımın gülümsemesiydi gözyaşları, o gecenin. * Öykü değilim anlatasın, nağme değ...', ARRAY['Türk Edebiyatı','Şiir','Ahmed  Şamlu']::text[], 8.5, '{"poet":"Ahmed  Şamlu","poet_slug":"ahmed_samlu","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENÇLER BİZİ SEYREDİYOR', 'gencler-bi-zi-seyredi-yor-donald-hall-9er9u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Genç kızlar başlarını kaldırıp bize bakıyor
sinema kuyruğunun yanından geçerken
ve dönüp yine tırnaklarını inceliyorlar.
Erkek arkadaşları saçlarını tarıyor,
sakız çiğniyorlar,
bizi aşağılamak isterler gibi.
Bugün saatlerce seviştik.
Sana bakıyorum. Kaldırımda gülümsüyorsun,
sevgili kırışık yüz.
Donald HALL', 'Genç kızlar başlarını kaldırıp bize bakıyor sinema kuyruğunun yanından geçerken ve dönüp yine tırnaklarını inceliyorlar. Erkek arkadaşları s...', ARRAY['Türk Edebiyatı','Şiir','Donald Hall']::text[], 8.5, '{"poet":"Donald Hall","poet_slug":"donald_hall","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GENÇLİK PARKI', 'gencli-k-parki-rifat-ilgaz-13wj3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün sokakları bu kentin Gençlik Parkı''na açılır
Bir sevgi ilkyaz sıcaklığında
Bir türkü yükselir uygarlıktan yana
Halktan yana emekten yana bilimden yana
Alır karamsarlığımızı götürür
Mavilikte açılır tomurcuk
Bir halı dokunur yurt güzelliğinde
Geleceğin yollarına serilir
Genç dediğin boy atmalı özgürlüğe doğru
Büyümeli yılların kısırlığında böyle dik
Gün ışırken yerini almalı en önde
Gençlik Parkı''nda coşkudan bayrak çekilmeli
Nerdensiniz yitik umutlarım hangi çıkmazda
Katılın bu aydınca şenliğe korkusuz
Tükenmiş yalanı tutsak bilimin
Susmuş ayakların sünepe ezgileri
Bütün atılımlar gerçekten yana uyumlu
Gökyüzü kızarmış gençlik ateşinden
Evrene kardeşlik getirmeli bilim dediğin
Yücelik getirmeli halkımıza mutluluk getirmeli
Çözmeli kişiyi paslı zincirinden
İşte beklediğin düş gözlerinin önünde
Uysun adımların çağının gidişine
Uysun adımların çağrısına gerçeklerin
Başının içinde ilkyaz bulutu
Altın toprak üstün yaprak
Gençlik Parkı''ndasın
(1968)
Karakılçık adlı şiir kitabından 1969
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Bütün sokakları bu kentin Gençlik Parkı''na açılır Bir sevgi ilkyaz sıcaklığında Bir türkü yükselir uygarlıktan yana Halktan yana emekten yan...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
