INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜL-ÜŞÜR', 'gul-usur-yusuf-altunel-vu466', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ay
öper
dudaklarını
kadife
yüzünü
gölün
bileğimi kestim
dudaklarımda
ölüm
karanlık
okşar
