INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜL YORDAMI', 'gul-yordami-kemal-ozer-hwuad', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'herkesin başladığı onlar için bir gün
uzatılmış bütün iskemlelerden ayakları
herkesin yolunda onların ayakları
onlar yüzler binler düşmek zorunda olan
kapılarının önünü suluyor aylardan Pazartesi
sarışın kara kumral saçlardan kadınlar
hiç güzellikleri olmadı bakılsa anlaşılır
silâhtandır onların ağlaması bir gün
kuşlar mıdır onlar ki ellerinin altında
her kanatları ayrı   h a b e r
çay evi kapısından tanıyorum girer girmez
kalabalık oluyorlar daha ilk bakışta
şu bizim beğenmediğimiz korku
savaşırlık için onların açılan bir gül aralarında', 'herkesin başladığı onlar için bir gün uzatılmış bütün iskemlelerden ayakları herkesin yolunda onların ayakları onlar yüzler binler düşmek zo...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜL ZAKKUM YA DA SU BOŞLUĞU', 'gul-zakkum-ya-da-su-boslugu-meti-n-findikci-f8lqx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İmgeyi antikacıda rehin bırakan usta
ölüm de artık baştan kokar
nerede kalmışsa su zamanı
üç basamak merdiven indiğim
kalbimin şurasında
bugün de ince bugün de kırıldı kırılacak
gülzakkum (?) saçlar. Aşkın,
miras kalan öyküsüyle yaptığın kahve
Masada unutulan kaysı, buzdolabı
Havada dedikodu tadı
Deniz şortunu giyinmiş
Teninde yorumlar gününü güneş, dilimi çağırıyor
Mermerdeki damarlar, tenin soyuluyor terimle
Bir sinek vuruyor cama
Sokağı yok suboşluğuna inen yolun, uzun zamandır
Unuttum sokak adlarını, kedi gözü, memebaşların
Avucumda kokan ot fıskiye
İstanbul''un tozu alınmamış bir köşesinde içtiğimiz
rakı, aşkımızın açıkta kalan kamburuydu komi,
ölü düşler asılı
duvarda, kılıktan kılığa giren su, kimi ölü kimi uzak
kimi adını bilmediğimiz, zakkumu bırakmıştık
vestiyere gülü alıp gidiyoruz,
tozu alınmamış bir köşesine İstanbul''un
güneşin en yorgun saatinde, suskun ben sen ve
herkes kumun ötesinde
anonslar… anonslar
tenimizde pullanır ayetler
aşkımın gülden zakkuma sızdığı
branda da poyraz, sevişme izleri
döşendiği otlar, anonslar
ben sen alışamadığımız bu şehirde
ne varsa yükümüz denizden çıkan gizliden gizliye
öğrendik yalnızlığı
lodos terimizi ve tenimizi okşadı
güneşten gizlediğimiz beyazlık
aynı yerde buluşmalıyız değmeden bıçağın ucu
koynumuza, sakladığımız aşk bir sur içi, bindiğimiz
gece tramvay, aynı yere gitmeli
aradığımız rüzgârın koyunda
su boşluğu, ''bir savaşın tasviri''nden alıntı bir adrese
sızıyoruz
aşkımız gül kokusu
dalında unutulmuş portakal
bu gecede, baykuş sesine aldandı ay
el çantasında dudak renklerinin iki hali, meçhul
gelişini saptayamıyorum, geceye mi bakıyor
gözlerim gündüze mi? ot kokusu
gözlerim yorgun bakmaktan gülü kuşatan poyraza
karşı pencerenin perdesi çekiliyor
zakkum, zakkum ve zakkum
şimdi
belinden kopmuş karıncayım, başım
kendi merkezi etrafında arıyor dudaklarını, kod adı
bırakıyorum bulamadığım yerde
kasılan zakkumdur terimin birleştiği
ırmakta-gül
gül ve gül
aşkınızla kulaç atıyorum
üç basamak deniz iniyorum
SU BOŞLUĞU', 'İmgeyi antikacıda rehin bırakan usta ölüm de artık baştan kokar nerede kalmışsa su zamanı üç basamak merdiven indiğim kalbimin şurasında bug...', ARRAY['Türk Edebiyatı','Şiir','Meti̇n  Findikçi']::text[], 8.5, '{"poet":"Meti̇n  Findikçi","poet_slug":"metin_findikci","theme":"Türk Şiiri","is_hero":false,"total_lines":63}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜL', 'gul-yasin-erol-hq67x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gül açınca yavrum
Gül açınca
Kelebeklerin kanat çırpışları yeryüzüne saçılınca
yavrum saçılınca
Bilemedim
Bu yaz mıydı
Geçen yaz mı
Ürkek elbiselerin içinde
Başına yıldızlar toplanmıştı
Gençliğini çevirdin hayatın bir yerinden
Işığında kabahatlerin belirdi
Gül açar da yavrum
Gül açar da
Kelebeklerin kanat çıpışları yeryüzüne saçılır da
yavrum saçılır da
Hani sen yoksun ya
Hayat nasıl da kanatıyor
Eski yıllardan söz açılınca', 'Gül açınca yavrum Gül açınca Kelebeklerin kanat çırpışları yeryüzüne saçılınca yavrum saçılınca Bilemedim Bu yaz mıydı Geçen yaz mı Ürkek el...', ARRAY['Türk Edebiyatı','Şiir','Yasin Erol']::text[], 8.5, '{"poet":"Yasin Erol","poet_slug":"yasin_erol","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GLADYATÖR KADIN VE DENİZ LALELERİ', 'gladyator-kadin-ve-deni-z-laleleri-azad-ziya-eren-sxx06', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gençliğim diyor kadın;
salındı nazenin bilekleriyle
düşler kıvrımındaki dünyada
onca fırtına savurdu
aşınmış omzuyla zamanın tortusuna
ve toprağın ahvaline acındım
inleyerek uçmak dedim zerrede
ziyan olmak gökyüzüne
erişkinliğim diyor kadın;
paramparça dolaşırken
dalgaların kanattığı kıyı atlaslarında
özge gladyatör deniz lalesi topluyordu
kalbinin geniş kalibreli gül bahçesine
ve olgunluğa fitillenirken barudî saçlarım
fanusta çırpınan rüzgârın burgusunda
aşkla inildiyordu yapraklar
geçkinliğim diyor kadın;
tazelenen ateştir bilmez miyim
gecenin usanmayan hecesi
murad ki suya eriyen gezgin buluttur
kalbimin serin kumsalında
zamansız açan menekşe
kandilde buğulu aydınlık
rengim diyor kadın;
kanat çırpan en saydam kuzgundur
manifesto veren kaptanı yorgun denizlerin
ve kanıyor tenimdeki adres
sevmekle yakıyor yanmakla kanatlanıyor
maviye düşen kuzgunluğum
özetim diyor kadın; denize
ulaşamayan lale kurusudur
ve gladyatörlerin lirik sonuncusu
gençliğim erişkinliğim
geçkinliğim rengim diyorum
özetim; gladyatör kadın ve deniz laleleri...', 'gençliğim diyor kadın; salındı nazenin bilekleriyle düşler kıvrımındaki dünyada onca fırtına savurdu aşınmış omzuyla zamanın tortusuna ve to...', ARRAY['Türk Edebiyatı','Şiir','Azad Ziya Eren']::text[], 8.5, '{"poet":"Azad Ziya Eren","poet_slug":"azad_ziya_eren","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLİBRİŞİM', 'guli-bri-si-m-ozcan-yalim-x1fja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ergin kedi almam evime
Tohumdan büyümeli toprağımda gülibrişim
İlk görüşte sevda olur mu
Pat diye sevda şiiri
Emek ister kedi çiçek sevmek
Şiir yalnızlıkça uzun yaşanmalı
Kolay değil bunca çizgiler yüzümde
Gıdım gıdım kazandım yaşlılığımı
Bir anını bile ödünç almadan
-Çatla ey ölüm-
Koluna girdiğim ancak uzak anılardır
Hepsi de geçeğen sevdalardan kalan
Uğurlar olsun diyor aynadaki soluk resme
Çiçeklerin güz bulutlarına yansıyan sesi
Uğurlar olsun - uğurlar olsun - güle güle
Ne yerde ne gökte iyeliğim artık
Bedenim benim değil
Bu ozan yitikler rafında bir nesne
Gülibrişim yapraklarınca incecik - tül gibi
Şamdan şamdan çiçeklerince - görkemli hem de
Sen misin bu - hangi sen - ya da siz
Oturdum bahçede dün gece - uzun uzun
Unuttuğum nice elleri özledim
Şamdanların dibindeyim - gölgede
Sevdalar oylum oylum
Ey şiirimce yoktan var ettiğim
Sen eski Leyla - bir de o en eski Leyla
Leylalar Leylalar - Ah Leylalar
Hepinizin adını gülibrişim koydum', 'Ergin kedi almam evime Tohumdan büyümeli toprağımda gülibrişim İlk görüşte sevda olur mu Pat diye sevda şiiri Emek ister kedi çiçek sevmek Ş...', ARRAY['Türk Edebiyatı','Şiir','Özcan Yalim']::text[], 8.5, '{"poet":"Özcan Yalim","poet_slug":"ozcan_yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLE GÜLE', 'gule-gule-necip-fazil-kisakurek-o6wiq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gömlek dikiş tutmaz hep söküle söküle;
Bütüne gel deseler ve gitsek güle güle...', 'Bu gömlek dikiş tutmaz hep söküle söküle; Bütüne gel deseler ve gitsek güle güle......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLER YÜZÜMLE', 'guler-yuzumle-can-yucel-cxznz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Viran bir rum evi adada oturduğumuz ev
Serinliğine serin
Ferah olmasına ferah ya
Tam bir hakuran kafesi.
Bu deyimi aslına döndürmek için mi nedir
Bir çift de kumru gelip
Yuva yapmış çatısına.
Öyle usturubunla yerleşmişler ki
Çürümüş tahtaların arasına
Dışardan görünmüyorlar hiç.
Yalnız
El-ayak çekildikten sonra
Derinden
Ve civan demlerle demlenircesine
Başlıyor dem çekmeleri
Benim de çökmeye yüz tutmuş
Şu can kafesimde
Kadir sevgilim Güler’e sevgim
ÜSKÜDARA GİDELİM diyor hala
ÜSKÜDARA GİDELİM', 'Viran bir rum evi adada oturduğumuz ev Serinliğine serin Ferah olmasına ferah ya Tam bir hakuran kafesi. Bu deyimi aslına döndürmek için mi ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖLGEDEKİ YÜZLER', 'golgedeki-yuzler-tekin-gonenc-8ndni', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sonu gelmez bir kahkaha
devrilir düşer
ıssız odalara
gitgide azalır
adımlarım aranızdan
kollarımı sel sularına eklersiniz
kimbilir nerelere dökülen
ya da
deli bir tabanca
gelir gelir de kurulur
hiç olmadık yerlerine gecenin
hep o yüzü annemin
usulca uzanır düşlerinden
pırıl pırıl güller takılır gider gözyaşlarına
kimbilir nerelere dökülen', 'sonu gelmez bir kahkaha devrilir düşer ıssız odalara gitgide azalır adımlarım aranızdan kollarımı sel sularına eklersiniz kimbilir nerelere ...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin_gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖLGELİ OTOPORTRE', 'golgeli-otoportre-che-guevara-p76zu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Genç bir ülkeden, kökleri otlardan doğan,
(o kökler ki Amerika''nın öfkesini yadsıyan)
sizlere geliyorum, kuzeyli kardeşlerim.
Acılı haykırış, umutsuzluk ve inanç yüklü,
sizlere geliyorum, kuzeyli kardeşlerim.
Biz &quot;homo sapiens&quot;lerin geldiği yerden,
nice yol aldım göçebe ayinleriyle,
bir haç gibi taşıdığım astımımla
ve onun özüme yakışmayan mecazıyla.
Uzundu yol ve çok ağırdı dert
sürmektedir bende avare adımlarımın kokusu,
hala batık bir gemidir derinlerdeki özüm
-kurtarıcı kıyılar görünseler bile-
dalgalara karşı gönülsüz yüzüyorum
batık bir gemi oluşumu koruyarak.
Yalnızım acımasız geceye karşı
ve biletlerin bıraktığı kesin şeker tadına.
Avrupa çağırıyor beni yıllanmış şarabının sesiyle,
sarı etinin soluğuyla, müzedeki eserleriyle.
Yeni ülkelerin neşeli klarnet sesiyle
alıyorum karşıdan geniş etkisini
Lenin''in icra ettiği ve halkların söylediği
Marks ve Engels şarkılarının.
Che GUEVARA', 'Genç bir ülkeden, kökleri otlardan doğan, (o kökler ki Amerika''nın öfkesini yadsıyan) sizlere geliyorum, kuzeyli kardeşlerim. Acılı haykırış...', ARRAY['Türk Edebiyatı','Şiir','Che Guevara']::text[], 8.5, '{"poet":"Che Guevara","poet_slug":"che_guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖLGELER', 'golgeler-kagan-kok-wlk1a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıkarırsam bir gün özetini
Tükenmez bir kalemle yaşadığım bu hayatın
Bir nüshası sendedir mutlaka
Onu al ve onu okuma
Bir hayat bir başka hayatın gölgesidir zira
İşte sendeki nüsha', 'Çıkarırsam bir gün özetini Tükenmez bir kalemle yaşadığım bu hayatın Bir nüshası sendedir mutlaka Onu al ve onu okuma Bir hayat bir başka ha...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖLGESİ İÇİNE DÜŞEN', 'golgesi-i-ci-ne-dusen-huseyin-atabas-60e10', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Son birkaç yıldır içimdeki fırtına dindi,
kıpırdamıyor gözlerindeki yeşil seninse;
Ankara yağmurlarla geçiştiriyor kışlarını!..
Çoktan ayrılığı duyumsadı anlayacağın
saksıdaki karanfilin titreşimleri bile,
özlem beni de vurdu, evin kedisini de.
Ne zamandır seni bekliyor kapının önünde,
bense didiniyorum makinenin başında,
aşk şiirleri yazıyorum, fukara avuntusu.
Aslında bir nedeni yokken biliyorum
hızla ateşim yükseldi nesin nesiyse;
belki de en alıngan yerimden geçiyorsun!
Kötü uyaklara düşüyor söz ne yapsam,
bir zamanlar öptüğüm parmaklarının ucu
hâlâ hüküm süren o uzun sonbahar oluyor.
Gölgesi kendi içine düşen göl gibisin
ovada öylece yayılmış karnın,
yankısını dağın yuttuğu suskunluğumsun.
İncecikten bir kar yağmaya başlasa şimdi
ilkyaz umudu olurdu kaldığımız yerden.
Ankara o eski Ankara olurdu park küçüğü
çimenlerine yatıp yuvarlandığımız,
izi çıkar unuttuğumuz çocukluğun;
anılara sürünüyor evin kedisi, büyüdü!..', 'Son birkaç yıldır içimdeki fırtına dindi, kıpırdamıyor gözlerindeki yeşil seninse; Ankara yağmurlarla geçiştiriyor kışlarını!.. Çoktan ayrıl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atabaş']::text[], 8.5, '{"poet":"Hüseyin Atabaş","poet_slug":"huseyin_atabas","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖLGESİ', 'golgesi-tugrul-asi-balkar-8c25l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hep bir gölgeyle saklandı yüzüm fark edilmedim
kimi mutluluktan derdi kimi umutsuzluktan
bense bilirdim senin gibi, yıllar öncesi
alnımda seken bir kurşunun parlamasından
alnımda seken o kurşunun
beni hayata bağışlamasından
(durur izi sol üst köşesinde alnımın
yaşama atılmış bir çentik gibi)
hep bir gölgeyle saklandı yüzüm fark edilmedim
güneş doğudan doğardı sırtımı ona verirdim
güneş batıdan batardı sırtımı ona verirdim
tepede yükselirdi güneş her öğle vakti
bir saçak altı bulur beklerdim
uzasın diye gölgem – uzardı gölgem
uzasın diye gölgem – uzardı gölgem
(gölgem uzundur günahlarım gibi
gölgem uzundur günahlarım gibi)
öyle de denir - ki doğrudur:
gölgesi uzun olur hayata kısa gelenlerin gövdesi.
istemekle,
insanın başına gelmesi arasındaki fark! işte bu:
hayata kısa kalan bir adamın uzun gölgesi.', 'hep bir gölgeyle saklandı yüzüm fark edilmedim kimi mutluluktan derdi kimi umutsuzluktan bense bilirdim senin gibi, yıllar öncesi alnımda se...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Asi Balkar']::text[], 8.5, '{"poet":"Tuğrul Asi Balkar","poet_slug":"tugrul_asi_balkar","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLLE BÜYÜYECEK ADI', 'gulle-buyuyecek-adi-ali-riza-ertan-ktkbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Denizin maviliği ulaşıyor sana;
O, en kendinden olana.
Geliştireceğiz daha; dünü karanlık olanı,
O, ölümle bir tutulanı,
Yenilmez, girişken bir güne.
Kurtulunması zor günlerden
Eriştiren uykumuzu/ izdüşümsüzlüğüne /
Bir düş gibi giren ozandan
Yeni bir günün hesap soruşunu
Benimseyecek, gülle büyüyecek adı.
Ölüm/ süren hayatı gül muştusuyla kazanacaktı
Der/ kenarında bir tarih yazmasının;
Kaç göçebenin ki defterinde yazılıdır azığı,
Karabinası, mor cepkeni ve abası
Unutulmayacak; anılacaktır adı alkışla!...', 'Denizin maviliği ulaşıyor sana; O, en kendinden olana. Geliştireceğiz daha; dünü karanlık olanı, O, ölümle bir tutulanı, Yenilmez, girişken ...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ertan']::text[], 8.5, '{"poet":"Ali Rıza Ertan","poet_slug":"ali_riza_ertan","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLÜMSE', 'gulumse-kemal-burkay-d41pl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hadi gülümse bulutlar gitsin
İşçiler iyi çalışsın, gülümse
Yoksa ben nasıl yenilenirim
Belki şehre bir film gelir
Bir güzel orman olur yazılarda
İklim değişir, Akdeniz olur, gülümse.
Sazlarım vardı, ırmaklarım vardı çok
Çakıltaşlarım vardı benim
Ama sen başkasın anlıyor musun
Tut ki karnım acıktı, anneme küstüm
Tüm şehir bana küskün
Bir kedim bile yok anlıyor musun
İklim değişir, Akdeniz olur, gülümse.', 'Hadi gülümse bulutlar gitsin İşçiler iyi çalışsın, gülümse Yoksa ben nasıl yenilenirim Belki şehre bir film gelir Bir güzel orman olur yazıl...', ARRAY['Türk Edebiyatı','Şiir','Kemal Burkay']::text[], 8.5, '{"poet":"Kemal Burkay","poet_slug":"kemal_burkay","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLÜŞÜN', 'gulusun-mehmet-kiyat-w4kj0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni biçilmiş çim kokusu gülüşün
Irmakları yola düşüren özlem
Kan kırmızı sancısı yürek atışlarımın
Bakışlarının yargılayan sessizliği
Yanak yanağa duruş
Güneşli içtenliği el sıkışımızın
Kimsesizliğimi kurtaran orman
Yunusların oyunlarındaki deniz şaşkınlığı
Yazını bekleyen gökyüzü
Gülüşün
ilk dizesi şiirlerimin', 'Yeni biçilmiş çim kokusu gülüşün Irmakları yola düşüren özlem Kan kırmızı sancısı yürek atışlarımın Bakışlarının yargılayan sessizliği Yanak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kiyat']::text[], 8.5, '{"poet":"Mehmet Kiyat","poet_slug":"mehmet_kiyat","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜLŞİİR', 'gulsi-i-r-ahmet-erhan-es3q5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceyarısı, karanlık bir bozkırda
Işıklar içinde akan bir tren kadar yalnızım
içinde onca insan, içinde dünya...
Soluk soluğa, demirden bir ırmağa mahkum
Ve bilmeyen sonsuzluk nedir,
Haklı olan kim bu kargaşada?
Ateş ve su, yaşam ve ölüm, irin ve şiir
Ucu bucağı olmayan bu çığlığın
Ortasında nasıl barışılabilir?
Anlamak isterim, hangi yasa
Bir beşikle bir darağacını
Aynı ağaçtan, ne adına varedebilir?
Sorular sormak için geldim şu dünyaya
Yasım acıların yasıdır
Boynumu üzgün bir çiçek gibi kırıp da
Yollara düştüğümde, başımda deniz köpüklerinden
Ya da sabah yellerinden bir taçla
Yürüdüğüme inanırdım - yanılırdım
Geceyi günle, acıyı sevinçle kardığım
Bu söylencenin bir yerinde durakladım
Ve anlatamadım, konuşamadım bir daha.
Acını ödünç ver bana, gözyaşlarını
Damarlarında uyuyan sevinci ödünç ver
Yitirdim çünkü onları da..
İlenmiyorum, el çırpmıyorum artık
Ne aklımda yaşadıklarım üstüne düşünceler
Ne de geleceğime dair bir tasa.
Gelirken çan çalmıyor yalnızlık
Bir adam, bir sokak, bir ev
Yüzle, gülüşler, susuşlar boyunca
Soruların vardı senin, ne çok soruların
Gözlerin dünyayı eleyip dururdu boyuna
Bir fısıltı gibi başladı sevgim
Çığlık oldu, kağıtlarda çiçek açtı sonra
Sonrası...Mutlu bile olduk bazı
Artık sen yadsısan da ne kadar
Ya da ben bilmiyorum mutluluk nedir
Anlatsın yollar, yollar, yollar...
Şimdi gece, soluğumu verdim içime
Az önce kağıtlara gül kuruları serptim
Dolaplardan kekik, nane kokuları çıkardım
Öylece serptim, seni yazacağım diye
Sen ki, deniz görmemiş bir deniz kızısın
Aklımın almadığı bir yerde, öylesin
Şimdi gece, iki kişilik bu yalnızlık
Bize artık yeter de artar bile...
Dünyanın ölümünü gördüm, suyun toprağın
En yakın dostlarımın birer birer
Vakitsiz açan çiçeklerin, vakitli doğan çocukların
Ölümünü gördüm, ama kimse
İnandıramaz beni öldüğüne sevgilerin!
Yaşam ki bir kum saatidir usulca akan
Dolan sevgilerimizdir biz boşaldıkca
Yaşımız biraz da sevgilerimizin akranıdır
Vereceğimiz tek şey budur dünyaya.
Şu dağılgan yüreğimi, şu köpüklere imrenen
Yüreğimi bir gün yollara atarsam
Bir gün bir nehir yataklarına dolarsam, korkarım
Suyumun çoğu senden yana akacak
Bütün sözcüklere adını ekleyeceğim
Güldeniz, Gülekmek, Gülyağmur, Gülsarap
Gülaşk, Gülsiir, Gülahmet, Gülerhan
Ey gül yaşamım, yitip giden düşlerim!
Gecelerdi, solgun - sessiz tüterdi yüzün
Yatağımda bir kımıltıydın, dilimde türkü
Uykusunda konuşurken sesini öptüğüm
Varmak için beyninin kıvrak dağ yollarına
Kokundu, bedenimi saran o ince buğu
Esintisinde usul usul yürüdüğüm
Ki değişmem yaseminlerle, portakal ağaçlarıyla..
Sanki bir kız yürürdü yollarda
Evimin sokağına girer, paspasa ayaklarını silerdi
Kapımı açardı gümüş bir anahtarla
Sanki hep gelirdi, sevişirdik bazı, konuşurduk
Tozlu kitapların yığıldığı odalarda
Kalırdı duvarlarda gülüşünden bir tini
Yatağımda bedeninden bir oyuk.
Benimse ellerim titrerdi, alnının aklığından
Saçlarına saçlarına doğru titrerdi
Şimdi kağıtların üstünde gidip gelen ellerim
Titremiyor artık , yolunu biliyor şimdi
Geceyarılarını çoktan geçti
Bu şiir bitmeyince varolmayacak ellerim
Ellerim uykusuz, ellerim geberesiye yalnız
Süzülüp alçalıyor karanlığa doğru.
Bütün yaşamım seninle geçiyor belleğimden
Seninle var ve seninle sürüp gidecek artık
Bir akdeniz kentinde limon koklayan
Ve hep ufkun ardına bakan çocuk
Acıyı buldu sonunda, kanayan bir gülden
Çaldı yüzünü bir yaşamlık
Geçer şimdi dumanlı bir kentin sokaklarından
Şaire çıkar adı - az buçuk kaçık.
Yeryüzünden silinmiş ırkların sonuncusuyum ben
Oturup da şimdi aşk şiiri yazmam bundan
Gülsün köpek sürüsü, lime lime edip
Bu dizeleri, satsınlar haraç-mezat
Doğru, benden sonra da tufan kopmayacak
Ama haykıracağım laflarını tuzla kesip
Yitip giden bu aşkı, nefesim tükenene dek.
Beynime bir sarkaç gibi vuruyor sorular
Neresinde yanıldık biz bu yaşamın?
Hangi el bozdu büyüyü, hangi yazı
Acılara hüküm verdi, soldan sağa taşarak?
Kalbimde yıllardır kabuk bağladı yaralar
Ödüm kopuyor, bir gün hepsi birden kanamaya başlayacak diye
Yenilmeyeceğim, boyun eğmeyeceğim hiçbir şeye
Hep direnen bir yanım kalacak
Adımın soluk izi, acının seyir defterinde.
şimdi gece, bindokuzyüzseksenikiyle
Üçyüzaltmışbeşi çarp - oradayım işte
Yorgun değilim, umarsızım yalnızca
Geçmişle geleceğin öpüştüğü yerde bir nokta
Gibiyim ve çoktan dürüldü defterim
Uçurumlar üstünde uçuşur dizelerim
Onlara köprü olacak bir beden yoksa da..
Bu benim yalnızlığım, dalsızlığım benim
Kana kana içtiğim çeşmelerden susayarak ayrılmak
Titreyen bir ışık karanlıklarda
Onu kim görebilir, kim tanıyabilir?
Sonuda hep bir soruyla karşı karşıya kalmak
Boynumun borcu bu, ödenmedi yıllardır.
Her aşktan böyle bir şiir kaldı bende
Yaşamımın bir dilimini özetleyen
Unutuşun çiçekleri bunun için hiç açmıyor
Donuyor bir gülüş tek bir dizede
Yaşanmış yüzlerce anı, buruk bir özlem
Çivileniyor beynimin bir yerlerine
Geride -hayır- acılar filan da kalmıyor
Bir boşluk yalnızca, uçurumlara özenen.
Nefret ediyorum ve seviyorum seni
Girdiğin bütün kapıları açık bırak
Birazdan git diyebilirim çünkü..
Çağım yalnız bırakmıyor beni, ellerini
Tutuşumda, usulca öpüşümde dudağını
Çağım aramızda çekilen kanlı bir bayrak
Uzayan, akan bir irin yolu gibi.
Sözcükleri güden çobanları var kalbimin
Beynimin yaşamı saran kıskaçları
Bitsin dediğim yerde bunun için başlıyorum
Yitirdiğim her şeye dönüp de bakmam bundan
Sensin yalnızlığa uzanan yolların düğüm yeri
Ama şu anda içimde öyle çoğulsun ki
Böyle irkilmezdim dünyayı kucaklasam.
Çapraz yalnızlıklar astım göğsüme
Yollarda bir  savaşçı gibi yürüdüğüm doğrudur
Gözlerle, dillerle kuşatılmış bir ülke
kalbimdir ona tek sınır
Susmayı bunun için severim bir çığlık gibi
Donup kalır sesim kendi göğünde
Onu ne anlayan, ne de duyan bulunur.
Yaşamım sonsuz bir hac yolculuğuna dönüşüyor burada
Kendi içimde ya da uzak yollarda
Bulduğum ve yitirdiğim bütün varlıklar
Bir mozayiğe biçim veriyorlar sessizce..
Bende dünyanın acısıyla sevinci öpüşüyor
Irmakların birleştiği o nokta benim
İtilip tekmelendiğim bütün kapılarda
Bana atılan her taş şimdi çiçek açıyor.
Bir gün anlarsın beni neden suskunum
Dünya içimde konuşurken böyle
Bedenimi aşıyor yorgunluğum
Karşında oturduğum masalardan dökülüp saçılıyor
Bu öyle bir çığlık ki, susuşlar kalıyor geride
Ondan öte her söz bir saçmalığı büyütüyor.
Adını çoktan unuttun yüzün aklımda
Ve bu şiiri neden sana adadığımı bilmiyorum
Ama her güzellik nasılsa kendi adını bulur
Bunun için ben Gül dedim sana..
Yine de bir çiçeğe bunca yağmur yağarsa
Kökleri toprağı saramaz olur
Üstüne titrediğim her şeyi yitirmeyi öğrendim çoktan
Söylenecek bir tek sözüm kalmazsa
Çizerim yüzünü kuşların kanatlarına
Her çırpınışta gökyüzüne dağılır
Yüzün, hücrelerine varana dek uçuşur.
Kağıtların aklığına aşkın tortusu çöküyor
Parklar, sokaklar, söylenmiş ya da söylenmemiş sözler
Yazdıkça biraz daha unutuyorum seni
Ve her yerde düş tacirleri, şiirseviciler
Bir şeyleri yorumlayıp duruyorlar aptalca
Büyüteçlerle inceliyorlar şu yitik ömrümüzü
Ben aşkın son hasatçısı, son peygamber
Gülünç, soyu tükenmiş bir varlığı oynuyorum boyuna.
Sana artık bir sığınak olsun bu şiir
Noterlere ver onaylasınlar - her hakkı saklıdır
Düşün, kalemimi sen tuttun yazarken
Yeni okula başlayan bir çocuğa yardım eder gibi
Öyle acemilikler yaptım ki ben
Hiç kalır bu şiir onların yanında ve
Nasıl ayaktayım diye şaşıyorum bazen.
Görüp göreceği son şey bu şiirdir dünyanın
Çığlığımdan arta kalan bunlar olacak
Aklımın son kırıntılarını da burada harcıyorum
Bundan böyle ibreler hep eskiye vuracak
Yakınmıyorum, yerinmiyorum hiçbir şeyle
Kalırsa odalarda unutulmuş birkaç şiir
Bir yeniyetmen in altını çizeceği dizeler benden
Senin adın nasılsa bir gün hepsini tamamlayacak...', 'Geceyarısı, karanlık bir bozkırda Işıklar içinde akan bir tren kadar yalnızım içinde onca insan, içinde dünya... Soluk soluğa, demirden bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Erhan']::text[], 8.5, '{"poet":"Ahmet Erhan","poet_slug":"ahmet_erhan","theme":"Türk Şiiri","is_hero":false,"total_lines":201}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜMÜŞ RÜZGÂR', 'gumus-ruzg-r-metin-guven-5u3im', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay oynuyor geceyle
Akıyor zaman sulardan geçerek
Çanları çaldı bile ırmağın
Güneş uyukluyor
Her yanda salyangoz renkli bulutlar
Geri dönmüyor
Şenlik ateşleri ve
Peleriniyle dolaşan gümüş rüzgâr.', 'Ay oynuyor geceyle Akıyor zaman sulardan geçerek Çanları çaldı bile ırmağın Güneş uyukluyor Her yanda salyangoz renkli bulutlar Geri dönmüyo...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖÇMEN ADAYLAR, LÜTFEN DİKKAT', 'gocmen-adaylar-lutfen-di-kkat-adrienne-rich-q6tqy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu kapıdan
ya geçeceksiniz
ya da geçmeyeceksiniz.
Geçerseniz,
her zaman adınızı hatırlamanız
tehlikesi olduğunu unutmayın.
Her şey gözlerini dikecektir size
siz de onlara öyle bakın
ve bırakın ne olursa olsun.
Eğer kapıdan geçemezseniz,
o zaman
saygın bir hayat yaşamanız
inançlarınıza bağlı
konumunuzu değiştirmeden
kahramanca ölmeniz mümkün
ama pekçok şey kör edecektir sizi,
pekçok şey sizi görmezden gelecektir,
kim bilir ne pahasına?
Kapının kendisi
hiçbir konuda söz vermiyor.
Kapı, sadece bir kapı işte.
Adrienne  RICH', 'Bu kapıdan ya geçeceksiniz ya da geçmeyeceksiniz. Geçerseniz, her zaman adınızı hatırlamanız tehlikesi olduğunu unutmayın. Her şey gözlerini...', ARRAY['Türk Edebiyatı','Şiir','Adrienne  Rich']::text[], 8.5, '{"poet":"Adrienne  Rich","poet_slug":"adrienne_rich","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖÇMEN', 'gocmen-bulent-ecevi-t-wl0tj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiklerimin başında bir bilmediğim
Görmediğim özlemediğim özlediklerimin başında
Yurdum olmadan sıladayım
Kimsem ölmeden yasta
Yollarda gözlediğim ne
Mektuplarda beklediğim ne
Nereden sürmüşler beni buralar nere
buralar nere, buralar nere
Bir bildiğim olmalı, bilmez olmuşum
Bir derdim olmalı, gülmez olmuşum
Buralara konmuş göçmen olmuşum
Bir derdim olmalı, gülmez olmuşum', 'Sevdiklerimin başında bir bilmediğim Görmediğim özlemediğim özlediklerimin başında Yurdum olmadan sıladayım Kimsem ölmeden yasta Yollarda gö...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖMÜLÜ LİMAN', 'gomulu-li-man-giuseppe-ungaretti-38h4w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şair oraya varıyor
sonra ışığa dönüyor şarkılarıyla
ve onları çevresine saçıyor
Bu şiirden
bana kalan
o hiçliği
tükenmez gizin
Giuseppe UNGARETTI', 'Şair oraya varıyor sonra ışığa dönüyor şarkılarıyla ve onları çevresine saçıyor Bu şiirden bana kalan o hiçliği tükenmez gizin Giuseppe UNGA...', ARRAY['Türk Edebiyatı','Şiir','Giuseppe Ungaretti']::text[], 8.5, '{"poet":"Giuseppe Ungaretti","poet_slug":"giuseppe%20ungaretti","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖMÜT ÜZERİNE BİR AVUÇ TOPRAK', 'gomut-uzeri-ne-bi-r-avuc-toprak-fatos-arapi-ybw75', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkes bir avuç toprak atıyor
Bense, onun üzerine
Birkaç parça gökyüzü atıyorum
Birkaç güney Arnavut türküsü
Zeyrin dalları altında o bunaltıcı sıcaklardaki
Birkaç ağustosböceği
İyi yürekli babacığım
Bunları çok severdi.
Fatos ARAPİ', 'Herkes bir avuç toprak atıyor Bense, onun üzerine Birkaç parça gökyüzü atıyorum Birkaç güney Arnavut türküsü Zeyrin dalları altında o bunalt...', ARRAY['Türk Edebiyatı','Şiir','Fatos Arapi̇']::text[], 8.5, '{"poet":"Fatos Arapi̇","poet_slug":"fatos_arapi","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜN EKSİLMESİN PENCEREMDEN', 'gun-eksi-lmesi-n-penceremden-cahit-sitki-taranci-igk0o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne doğan güne hükmüm geçer,
Ne halden anlayan bulunur;
Ah aklımdan ölümüm geçer;
Sonra bu kuş, bu bahçe, bu nur.
Ve gönül Tanrısına der ki:
- Pervam yok verdiğin elemden;
Her mihnet kabulüm, yeter ki
Gün eksilmesin penceremden!', 'Ne doğan güne hükmüm geçer, Ne halden anlayan bulunur; Ah aklımdan ölümüm geçer; Sonra bu kuş, bu bahçe, bu nur. Ve gönül Tanrısına der ki: ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜN GÜN ÜSTÜNE', 'gun-gun-ustune-salvatore-quasimodo-0lq3u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gün üstüne: uğursuz sözler, kan
ve altın. Tanıdım sizi ey benzerlerim
ey yeryüzü canavarları. Dişleriniz
arasında yok oldu acıma, iyi haç bizi bıraktı.
Dönemem artık cennetime.
Mezarlar kaplayacak yaralı toprakları, denize karşı,
kahramanlık anıtı olmayacak ama bir teki bile.
Kaç kere oynadı bizle ölüm: yaprakların
tekdüze hışırtısıydı saran havayı
keşişleme esince fundalıktan bulutlara
yükselir gibi bataklık kuşları.', 'Gün gün üstüne: uğursuz sözler, kan ve altın. Tanıdım sizi ey benzerlerim ey yeryüzü canavarları. Dişleriniz arasında yok oldu acıma, iyi ha...', ARRAY['Türk Edebiyatı','Şiir','Salvatore Quasimodo']::text[], 8.5, '{"poet":"Salvatore Quasimodo","poet_slug":"salvatore_quasimodo","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜN GÜNEŞİ ÖRTMEDEN', 'gun-gunesi-ortmeden-sevgi-kose-xxx50', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gölgenizle konuşabildiğiniz bir saat
boyunuzu ölçün, eninizi ölçün
küçülüp düşebilirsiniz
en yuvarlak gününüzün ortasına
parmak atıp tad almayan duyularınıza
kusun kendinizi
bir kaç kavanoz
başkalarının acılarından serpin üzerinize
ihtimal ısınabilir yüzünüz
sorun o an kendinize
kaç dereceye kadar üşütüldüğünde
katılaşır yüreğiniz
bir bir fırlatıp atın yaşam belirtilerinizi
bedeniniz su almakta
ihtimal bulunabilir tavanda can yelekleri
siz yine de düşünün
ne kadar sürükleyebilecek güçtedir
beyin kaslarınız cesedinizi
ya da tam orada
öylece
güneşe çevirin yüzünüzü
uzak durun gölgenizden
ihtimal gün olur örter güneşi
kendi cesedinizi teşhiste zorlanabilirsiniz o gün', 'gölgenizle konuşabildiğiniz bir saat boyunuzu ölçün, eninizi ölçün küçülüp düşebilirsiniz en yuvarlak gününüzün ortasına parmak atıp tad alm...', ARRAY['Türk Edebiyatı','Şiir','Sevgi  Köse']::text[], 8.5, '{"poet":"Sevgi  Köse","poet_slug":"sevgi_kose","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜN IŞIĞI PEŞİNDE', 'gun-isigi-pesi-nde-hasan-basri-unlu-81n4q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İhanet ve hasret kardeştirler
İzlerini sürdüm de geldim sana
Bakma yanmışlığıma izlerin düşürdüğü
Cehennemlerdendir sen durma renk ver
Sağalt birer birer sızlat yaralarımı
Boş ver eprimişliğine derimin
Sen tez tut elini ey günışığım
Bağbozumunu bekleyen pusular var daha', 'İhanet ve hasret kardeştirler İzlerini sürdüm de geldim sana Bakma yanmışlığıma izlerin düşürdüğü Cehennemlerdendir sen durma renk ver Sağal...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Ünlü']::text[], 8.5, '{"poet":"Hasan Basri Ünlü","poet_slug":"hasan_basri","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜN OLUR', 'gun-olur-orhan-veli-ei5gk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün olur, alır başımı giderim,
Denizden yeni çıkmış ağların kokusunda.
Şu ada senin, bu ada benim,
Yelkovan kuşlarının peşi sıra.
Dünyalar vardır, düşünemezsiniz;
Çiçekler gürültüyle açar;
Gürültüyle çıkar duman topraktan.
Hele martılar, hele martılar,
Her bir tüylerinde ayrı telaş!...
Gün olur, başıma kadar mavi;
Gün olur başıma kadar güneş;
Gün olur, deli gibi...', 'Gün olur, alır başımı giderim, Denizden yeni çıkmış ağların kokusunda. Şu ada senin, bu ada benim, Yelkovan kuşlarının peşi sıra. Dünyalar v...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNAH EKERİM ÖMRÜNE', 'gunah-ekeri-m-omrune-umut-taydas-754hq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '&quot;Mecburiyetine Boyun Eğen''e&quot;
Uzaklaş;
Yoksa sana dokunurum,
Yoksa yasak tanımam,
Günahkâr olurum, günahım olursun,
Kaç, görme,
Görürsen hatırlama,
Hatırlarsan ağlama.
Gelme.
Yoksa sana dokunurum,
Dudaklarına konarım
Gözlerini esir alırım
Kölem olursun,
Gecelerce kölen olurum,
Didik didik ederim hayatını,
Benden başkasına yaşatmam seni,
Tarihini vururum, anılarını asarım,
Yüreğine saplarım kendimi
Bedeninde yatıya kalırım
Teninde beklerim geleceğimi
Yaklaşma;
Seni alırım,
Senin olurum,
Özgürlüğüm yoldaş olur yanına,
Sensiz düşüncelerim toprak olur,
Taparım sana, yatağına tapınak derim,
Yüzünde güneşler beklerim,
Gitmezsen sana dokunurum
Sahiplenirim seni,
Sana aşkı yaşatırım,
Daha küçük aşklara katlanamazsın,
Benimle ölürsün...
&quot;Kavuşamayan iki dağdık, aramızda güneş vardı&quot;', '&quot;Mecburiyetine Boyun Eğen''e&quot; Uzaklaş; Yoksa sana dokunurum, Yoksa yasak tanımam, Günahkâr olurum, günahım olursun, Kaç, görme, Gör...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNAYDIN', 'gunaydin-necati-cumali-v7sql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Nurullah Ataç''a-
Günaydın tavuklar, horozlar
Artık memnunum yaşamaktan
Sabah erkenden kalktığım zaman
Siz varsınız;
Gündüz, işim var, arkadaşlarım,
Gece, yıldızlar var, karım var,
Günaydın tavuklar, horozlar!', '-Nurullah Ataç''a- Günaydın tavuklar, horozlar Artık memnunum yaşamaktan Sabah erkenden kalktığım zaman Siz varsınız; Gündüz, işim var, arkad...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNDÜZ - DIŞ - SOKAK İÇİ', 'gunduz-dis-sokak-i-ci-mehmet-k-zim-4v20n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Oksijen saçlı ve ağzı cikletli kızlar göz süzer, ince favorili bıçkın delikanlılara. Bu  şehir azgın bir kedi gibi kendi çocuklarını yer)
Bir mermi yaşamalı abi
Fırlayıp namludan
Ve nereye gideceğini bilmeden
Gece toz ölüm kadın
Kesilen raconudur harcanmış
Ömrümüze, delikanlılığın
Sevmek yavaşlatır insanı usta
Aşk o siyah-beyaz
Ve acıklı filmlerde kalmalı
Neon içki para erkek
Sıyrılıp bir sustalı gibi
Bu tarihsiz sokaklardan yırtmalı.', '(Oksijen saçlı ve ağzı cikletli kızlar göz süzer, ince favorili bıçkın delikanlılara. Bu  şehir azgın bir kedi gibi kendi çocuklarını yer) B...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kâzim']::text[], 8.5, '{"poet":"Mehmet Kâzim","poet_slug":"mehmet_kazim","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNDÜZ YARASALARI', 'gunduz-yarasalari-oruc-aruoba-5wgxc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I.
Neyiz ki biz?
İlk ışınları görününce güneşin,
Kaparız tepenin gözkapaklarını
Çam değiliz ki, kollarımız açık
Ürpererek karşılayalım donuk ışığı.
Gölgeler kısalınca çıkarız ortaya,
Açıklıktır, aydınlıktır aradığımız,
Parlaklıkta bulur gücünü görüşümüz.
Tanımayız alacakaranlığı delen,
Tepelerin arasından seçen bakışı.
Kör olmuş ışıktan gözlerimiz.
Gündüz yarasalarıyız biz.
II.
Geceyi düşleriz gündüzken,
Geceyken de gündüzü,
Yitirebileceklerimiz yitiktir
Onlardan uzaktayken ama
Özleriz, döneriz yeniden
Yitirmeden
Yitirebileceklerimizi
Yitiremediklerimize.
Yitirebilirdik, deriz;
Ama yalnızca bir fiil çekimi bu
Tutsaklıklara bağlamışız özgürlüğümüzü.
Gündüz yarasalarıyız biz.
III.
Sağlamdır düşünce temellerimiz,
Ama altlarında kist vardır, sonra kum
Dururuz gerçi, sapasağlam, kalın
Taştan duvarlarımızla, dimdik
Ayakta; ama biraz su, bir sızıntı
Kaydırır temellerimizi hemen.
Duyarız yerçekimini hemen,
Titreriz. Sımsıkı, gergin
Bağlar vardır
Düşüncelerimizi ayakta tutan, ama,
Ya temelsizse temeli
Bütün bu bağları
Bağlayan
Bağın?
Bağlantısızca bağlarız bağlarımızı.
Gündüz yarasalarıyız biz.', 'I. Neyiz ki biz? İlk ışınları görününce güneşin, Kaparız tepenin gözkapaklarını Çam değiliz ki, kollarımız açık Ürpererek karşılayalım donuk...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc_aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":45}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞ ŞARKISI', 'gunes-sarkisi-necati-yildirim-ilssk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'büyük yangınım karanlıktaki çoban yıldızım
kanlar sızarken toprağa sımsıcak ölü kanları
aynı inancı taşıdık değişen dünyayı kucaklayarak
sızlıyorsa yüreklerimiz bulut gibi yürüyorsak
kıtlık vardı kıyım oldu sürgün yaşadık
hüznü yarıp gelen şanlı ırmak
usul usul akar usul usul akar
yüzümde büyüyecek şanlı ırmak
ey ölümlerle sulanan kanlı gülüm
acı haberleri unutma yüreğinde biriksin
güzel günlerdir mayalanan budanmış bedenlerle
sen içimde şimdi ağlıyorsan kanlı gülüm
bir ağızdan söylenir yazdığımız şarkılar
karanlığı yıkan güneş şarkısı
usul usul akar usul usul akar
su verdim acılarıma su verdim
ey oğul ağıtlarla büyüyen yaralı kuşum
güneş şarkısıdır ölümlerle yıkılmayan
bir ağızdan söylenirse bir gün bu şarkılar
sular uyanır sevdiğim nice dağ suları
ey oğul ölümlerle yıkılmayan yaralı kuşum
zulmün yenemediği büyük kavga
usul usul akar usul usul akar
su verdim acılarıma su verdim
baharda halk gülleridir savrulan
dal mı kırıldı kuş mu vuruldu çocuk mu
elbet gencecik bedenleri çizeriz sevgilim
elbet yazılır acı bırakan bahar günleri
suskun bir öfke ve umut halk gülleri
zulmün yenemediği büyük şarkı
usul usul akar usul usul akar
gül koydum acılara gül koydum', 'büyük yangınım karanlıktaki çoban yıldızım kanlar sızarken toprağa sımsıcak ölü kanları aynı inancı taşıdık değişen dünyayı kucaklayarak sız...', ARRAY['Türk Edebiyatı','Şiir','Necati Yildirim']::text[], 8.5, '{"poet":"Necati Yildirim","poet_slug":"necati_yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞ DELİSİ', 'gunes-deli-si-necati-cumali-bqk09', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akan suyu severim ben
Işıldayan karı severim
Bir yeşil yaprak
Bir telli böcek
Yeşeren tohum
Güneşte görsem
Sevinç doldurur içime
Bir günü
Güzel bir günü
Güneşli bir günü
Hiçbir şeye değişmem
Onun için savaşı sevmem
Onun için zulümü sevmem
Onun için yalanı sevmem
Bilirim yaşamaz güneşte
Bilirim yaşamaz yanyana aşkla
Ne haksızlık
Ne korku
Ne açlık', 'Akan suyu severim ben Işıldayan karı severim Bir yeşil yaprak Bir telli böcek Yeşeren tohum Güneşte görsem Sevinç doldurur içime Bir günü Gü...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNE ÇIKIŞ', 'gune-cikis-vecihi-ti-muroglu-kfkbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Simin''e
Seni yaşamımıza katan kuş
Kızıl güller diker bahçemize
Yokluğun ötesinden varlığa kayış
İkiyken dört diye yazar güncemize
Kırmızı iri güller her zaman
Büyük acıları çağrıştırır bende
Ölümleri tadılmamış yaşamları
Ve hep yarım kalmış aşkları
Yaşam söylüyor şarkılarını
Şafakla başlayan çekiç sesleri
Girişiyor Şeytan''la alışverişine
Ve ateşe çeviriyor nefesleri', 'Simin''e Seni yaşamımıza katan kuş Kızıl güller diker bahçemize Yokluğun ötesinden varlığa kayış İkiyken dört diye yazar güncemize Kırmızı ir...', ARRAY['Türk Edebiyatı','Şiir','Vecihi Ti̇muroğlu']::text[], 8.5, '{"poet":"Vecihi Ti̇muroğlu","poet_slug":"vecihi_timuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞİ YAKANLARIN SELÂMI', 'gunesi-yakanlarin-sel-mi-i-lhan-berk-ipln9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir zevk duyulmaz oldu, buranın rüzgârlarından
Hayat soldu bir günün enginlerinde yine.
Selâm! Sonsuzların yorgun gönüllerine
Selâm: Güneşi içeren çocukların diyarından!...
Bir ateş yakalım ki geçmesin hatta bir an
Ve sussun kurtlar, kuşlar bir gök gürültüsüyle;
Bir ateş yakalım ki, tutuşsun gökler bile
Ve Güneş içilsin o gün, kızıl çanaklardan!...
Varsın eskisin sesim kaybetsin ahengini
Geceler kıskanmasın aydınlığa süsünü.
Donatsın sonsuzluklar gibi gurubun rengini
Söylesin ve uzaklar baharın türküsünü...
Neler, neler beklenmez nihayetsiz bir yerden
Güneşi içelim mor şafaklar gecesinden.
Selâm! Sonsuzluklara, hasretli gönüllerden,
Selâm, güneşi, göğü yakanlar bahçesinde!...
güneşi yakanların selamı', 'Bir zevk duyulmaz oldu, buranın rüzgârlarından Hayat soldu bir günün enginlerinde yine. Selâm! Sonsuzların yorgun gönüllerine Selâm: Güneşi ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞİN IŞIĞI', 'gunesi-n-isigi-asaf-halet-celebi-0gisr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her şey güneşi seviyor
hattâ denizler bile
denizlerde nefes alan sen bile
ve biz
güneşi değil ışığını seven insanlarız
güneş içime vuruyor
güneşin ışığı var
güneş yok
güneşin ışığını kim anlatabilecek
pazar pazar gezmek
dağ dağ dolaşmak
ve ormanlarda kalmak
güneşin ışığını anlatacak olanı arıyorum
güneş içime vuruyor', 'her şey güneşi seviyor hattâ denizler bile denizlerde nefes alan sen bile ve biz güneşi değil ışığını seven insanlarız güneş içime vuruyor g...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi̇']::text[], 8.5, '{"poet":"Asaf Halet Çelebi̇","poet_slug":"asaf_halet_celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞİN ÖLÜMÜ', 'gunesi-n-olumu-tulay-yener-4h0e9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'doğumgünü de olması gerekmeyen bir anı yaşar gibi
kaybolmakta güneşin suya değen heykeli.
ayın burçlarına tünemiş kuşun kanadında,
huzuruna şapka çıkarıyorum;
seyrederken bir mumun titreyişini hatta bitişini.
birer birer kaybolmakta mavinin,
olabildiğince sessizliğiyle, kuştan delikleri
ve yeşiller yangına, sonra küle döner;
bir güneş daha satar karanlığa gölgesini.', 'doğumgünü de olması gerekmeyen bir anı yaşar gibi kaybolmakta güneşin suya değen heykeli. ayın burçlarına tünemiş kuşun kanadında, huzuruna ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Yener']::text[], 8.5, '{"poet":"Tülay Yener","poet_slug":"tulay_yener","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞTE', 'guneste-melih-cevdet-anday-lu0jn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çünkü saatler dardır, her şeyi almaz
Güneşte çözülür ve kayarlar bir yana.
Mısırlar güçlükle büyürken yağmursuzluk
Kaygılandırır dilsiz bahçıvanı.
Sessiz kuşlar, bir keçi, ağır iğde ağaçları.
Bir araba geçti incelmiş yoldan
El salladı biri, belki tanıdık,
Belki değil, süreksizliğin eşanlamı.
Ve denizin yorgun çağındaydı çocuklar
Çığlıkları titretir balkondaki sarmaşığı,
Çünkü dardır saatler, sığmaz biraraya
Dalgınlık, deniz ve sardunya.
Rüzgâr alıp götürdü balıkçı teknelerini
Uzaktaki kılıçlara, ki bilemeyiz
Hangi derinlikte dölleyerek denizi
Gidiyorlar öyle ağırbaşlı, doğuya.
Ve ocaktan çorbanın kokusu geldi demin
Burun deliğine kedinin ve köpeğin.
Rafta kitaplar, mavi bir şişe ve gül
Donmuş kalmışlar tek başlarına.
Duvarda bir resim, resimde kalabalık
Köy alanı, çocuklar, çember ve zaman.
Breughel nasıl da toplamış bunca
Ortaklığı ve uyumu biraraya,
Çünkü saatler dardır, sığdırılmaz.
Güneşte her şey çözülür gider bir yana.', 'Çünkü saatler dardır, her şeyi almaz Güneşte çözülür ve kayarlar bir yana. Mısırlar güçlükle büyürken yağmursuzluk Kaygılandırır dilsiz bahç...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNEŞTEN UZAK', 'gunesten-uzak-rifat-ilgaz-aebd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Konuklarımız için yıkadık sizin için
Kıyılarımızı bol köpüklü dalgalarla kıştan
Nisan sabahlarının buğusu saçlarınızda
Mavi gözlerinizde sevinç
Telli turnalarla geldiniz
En saydam mavilikleri çektik üstünüze
Toroslar''dan Ağrılar''a kadar
Üzüntülerden arındık sizin için
En güleç yüzümüzle çıktık karşınıza
Papatyalar gibi tekdüze
Erkenden uyardık çiçeklerimizi
Kalkınmamız sizden olacakmış
Başımızın üstünde yeriniz
Izgaralarda lüferler emrinizde
Tabaklarda mayonezli levrekler
Ağız tadıyla yiyemediğimiz
Kirazlar canerikleri çilekler
Bulutun kınalısı denizin mavisi bizde
Yurdumuza bir renk de siz getirdiniz
Esmerler sarışınlar yeşil gözlüler
Hoş geldiniz
Biz bu güneş ülkesinin çocukları
Öfkeyle umutla beslenen
Yaz geldi mi ebegümeci madımak
Kar yağdı mı dağda bayırda
Davarımız sığırımızla yarı tok yarı aç
Biz bu güneş ülkesinin çocukları
Kuru emzikle büyüyen gecekondularda
Odsuz ocaksız
Bu mevsimde sevilerden uzak
Yoksun tüm aydınlıklardan
Sabrımızdır geleceğin harcını özleştiren
Bir tuğla bir tuğla daha
Bir avcumuzda kum
Bir avcumuzda kireç
Günler günler boşuna harcanan
Okunmuş bir mektup kirliliğinde
Buruşturulup atılmış günler
Yazısız kâğıtlarca anlamlı
Alyuvarlarla beslenen özlem
Kum kireç ölçek ölçek zaman
Biz bu güneş ülkesinin çocukları
Güneşi konuklara bırakan
Oysa bardaklarda altın yeşili şarap
Marmara''nın midyeleri soframızda
Olgun domatesler taze soğan
Derilerde Afrikalı yanıklığı
Hoşi Ming''li savaş çocuklarıyla birlik
Garcia Lorca''lı kızlarla bir arada
Karşıda Nâzım''ı dalga dalga getiren deniz
Oturup diz dize bir kıyıda
Aynı balık çorbasını kaşıklayabilirdik
Biz bu güneş ülkesinin çocukları
Güneşi bulutların ötesinde bırakan
Güvercinim Uyur mu adlı şiir kitabından 1974
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Konuklarımız için yıkadık sizin için Kıyılarımızı bol köpüklü dalgalarla kıştan Nisan sabahlarının buğusu saçlarınızda Mavi gözlerinizde sev...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":58}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNÜL BİR GÜZELİ SEVMİŞ', 'gonul-bi-r-guzeli-sevmi-s-asik-veysel-satiroglu-m2rns', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönül bir güzeli sevmiş ayrılmaz
Dolanır peşinde çoban misâli
Hiç kimse bu derdin dermânın bilmez
Azmış yaraları perişan hali
Lokman çare bulmaz yoktur Eflâtun
Yârdan ayrılması ölümden çetin
Elde endaz ettim bu aşkın atın
Terk ettim sılayı vatanı ili
Ferhat Şirin için kestiği taşlar
Benim senin için döktüğüm yaşlar
Seni yaksın beni yakan ateşler
Yaktı bu sinemi savruldu külü
Arılar bal için bekler petekler
Alır her çiçekten verir emekler
Mecnun Leylâ için pınarı bekler
Ben de bir yâr için olmuşum deli
Evvelden var idi bu sevda bende
İlikte damarda cesette canda
Ölünce hû çeksin kemiğim sinde
Dünyada durunca Veysel''in dili', 'Gönül bir güzeli sevmiş ayrılmaz Dolanır peşinde çoban misâli Hiç kimse bu derdin dermânın bilmez Azmış yaraları perişan hali Lokman çare bu...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatiroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatiroğlu","poet_slug":"asik_veysel","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNLÜ GÜVERCİNLİ KADIN', 'gonlu-guverci-nli-kadin-tekin-gonenc-z2eyq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'önce sesin geldi
aralandı kapılarım
ardında şaşkın bulutlar çıkmazı
sonunda sen
gönlü güvercinli kadın
köpüren simsiyah saçlarınla
günler boyu koşuşup durdun
içimin aykırı ırmaklarında
gamzelerinde gizlediğin
o binlerce yıldızı
döküp de şimdi üstüme
söyle nereye
artık herkes
tutsun da elinden kendi şiirinin
tersinden mi girsin
ölü kelebekler sokağına
sen bende daha bitmedin ki
gönlü güvercinli kadın', 'önce sesin geldi aralandı kapılarım ardında şaşkın bulutlar çıkmazı sonunda sen gönlü güvercinli kadın köpüren simsiyah saçlarınla günler bo...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin_gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNÜL KUŞU KALKTI UÇTU HAVAYA', 'gonul-kusu-kalkti-uctu-havaya-karacaoglan-0dxnu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönül kuşu kalktı uçtu havaya
İn gönül dedim de indiremedim
Aşıp aşıp gider karlı dağlara
Dön gönül, dedim de döndüremedim
Hûma kuşu gibi yüksek uçarsın
Pervaz vurup Tercüman''ı geçersin
Bin bir türlü dala konup göçersin
Gönül sana mekân bulduramadım
Âleme sultansın, vezirsin kendin
Aç, dedim, açmadın ak göğsün bendin
Yad ellere gönül verdin de döndün
Gönül sana akıl erdiremedim
Karacaoğlan der, nedir çareye
Cerrah neyler yürekteki yareye
Gönül düştü şimdi kaşı kareye
Akar gözüm yaşın dindiremedim', 'Gönül kuşu kalktı uçtu havaya İn gönül dedim de indiremedim Aşıp aşıp gider karlı dağlara Dön gönül, dedim de döndüremedim Hûma kuşu gibi yü...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNÜL', 'gonul-fikret-kizilok-h9cjq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bunca yıl herkesten kaçtın
En sonunda buldum sandın
Ansızın içini açtın
Yapma dedim yaptın gönül
Gözleri senden uzaktı
Farkedilmez bir tuzaktı
Sana böylesi yasaktı
Yapma dedim yaptın gönül
O bir yolcu sen bir hancı
Gördüğün en son yalancı
İçimdeki derin sancı
Gitmez dedim kaldı gönül
Sen istedin ben dinledim
Senden ayrı olmaz dedim
En sonunda ben de sevdim
Şimdi beni kurtar gönül
Gözlerin bakar da, görmez
Ellerin tutar da, bilmez
Gece gündüz farkedilmez
Demedim mi sana gönül
Sabahın tam üçündesin
Dertlerin en gücündesin
Hâlâ onun peşindesin
Gitme dedim gittin gönül
Böylesi sevdiğin için
Bir kördüğüm oldu içim
Ağlıyorsun için için
Demedim mi sana gönül
Sen istedin ben dinledim
Senden ayrı olmaz dedim
En sonunda ben de sevdim
Şimdi beni kurtar gönül', 'Bunca yıl herkesten kaçtın En sonunda buldum sandın Ansızın içini açtın Yapma dedim yaptın gönül Gözleri senden uzaktı Farkedilmez bir tuzak...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kizilok']::text[], 8.5, '{"poet":"Fikret Kizilok","poet_slug":"fikret_kizilok","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLE DOKUNAN', 'gunle-dokunan-ahmet-ozer-wthm4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yürüdüm gecenin bir yerlerine tutunarak
gökyüzünü dolduran yıldızlar altında
kalbim suçlanışın akıp giden çağlayanı
ellerimde okunmamış mektuplar mürekkep izleri
gecenin geç bir vaktinde uyandırılmak.
kanı çekilmiş yüzlerin/ ağıtların ortasından
kıvılcımlar dağıtan gözlerin erken gidişlerin
şafağın teri alnımda
dilimde buğulu sözler.
çatlıyor bulutlu gökler köpüren ırmaklar
kuşlar bahar nakışını kazıyor dağlara
bir söz tufanı sevincim yüreğimde
yangına tutuluyor solgun sayfalar.
şimdi yolunmuş gül bahçelerinin koynunda
yeşeren çocuk sesleridir dünyayı tutan.', 'yürüdüm gecenin bir yerlerine tutunarak gökyüzünü dolduran yıldızlar altında kalbim suçlanışın akıp giden çağlayanı ellerimde okunmamış mekt...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLER NE KADAR', 'gunler-ne-kadar-hermann-hesse-9hahu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne kadar üzüntülü geçiyor günler
Artık ne ateşler ısıtır beni,
Ne güneşler yüzüme gülümser,
Boş, dünyadaki bütün şeyler,
Bütün şeyler soğuk, insafsız şimdi.
Ve sevdiğim pırıltılı yıldızlar benim
Tesellisiz bakar durur halime.
Tâ sevginin ölebileceğini sezdiğim
Zamandan beri kalbimde.
Hermann HESSE', 'Ne kadar üzüntülü geçiyor günler Artık ne ateşler ısıtır beni, Ne güneşler yüzüme gülümser, Boş, dünyadaki bütün şeyler, Bütün şeyler soğuk,...', ARRAY['Türk Edebiyatı','Şiir','Hermann Hesse']::text[], 8.5, '{"poet":"Hermann Hesse","poet_slug":"hermann_hesse","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLER PERİŞAN', 'gunler-peri-san-arkadas-zekai-ozger-p53mm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yırtarak geçiyor kalbimizden
hayatı da törpüleyen zaman
şuramızda birşey var
acıya benzer
umuda benzer
böyle günlerde hayat
hem acıya, hem acıya benzer
gün ölümle başlatıyor hayatı
her şafak taze bir ölünün üstünde doğuyor
her sabah ölümü anlatıyor gazeteler
sol köşede ölümü kutsallaştıran bir fotoğraf
yeni bir cinayetin röntgenini çıkartıyor gövdeme
beynim sabırla keskin
iğdişliyor haber bültenlerini, yorumları, sahte ölüm ilanlarını
bizim ilanlarımız çoktan verilmiştir
gelirse de bilinir nerden ve nasıl
böyle ölümün yücedir adı
ha kanağacı canım, ha gelincik tarlası
çünki ölümün kanıdır besleyen
bir başka baharın tohumlarını
şuramızda birşey var
bizi onduran şey
acıya saran
umudu kuşatan
kalbim: kalbim mi desem
var kalbim: yaşayan ben
hayatla ölümle cinayetle
gazetelerde, radyolarda, eski üniversitelilerde
eski prof hocalarla
yaşayan ben: geç mi kaldık/kabul edemem
ah benim sevgili annem
oğlunda elbet yurtseverden
birgün bırakırda sizi yüzüstü
yüzüstü değil: elbette bizüstü
bırakır da: kötü sarmaşıkları, yaban güllerini
bırakır da: sekizyüzlük hırtları, şunları, bunları
giriverir senin sıcacık kucağına
yani hem sana karşı, hem senin için
giriverir o yanılmaz tarihçinin yaprağına
ölüm mü dedim annem
ölüm senin gibi güzel annelerin
senin gibi güzel çocuklar feda etmiş
o tarih atlasında
bir kırmızı gül olur ancak
koksun diye çocukların bahçesi
şuramızda, tam şuramızda
kanserli bir virüs gibi kanımıza karışsa da bizi yaşatan günler perişan
işte bir bir kırıyorlar  dalıylan
yeryüzünün olgunlaşan meyvelerini
çünki biliyorlar vakit dar
oysa dalları kırılmayan ölür mü sonsuz ağaç
hayatı pekiştiren kökümüz var
dünyayı emeğe kazandırmak için
hayata ve ölüme sonsuz bir anlam veren
kanağacına sözümüz mü var
biz şimdi gidiyoruz gibi ya dostlar
birgün döneriz elbet
acısız, adsız
ölümsuyu sürünün
sürünün öl��msuyu
bir ölü bir dirinin kanıdır
besler hayatsuyu
şuramızda, tam şuramızda
tarihe nasıl anlatsam
ey anneleri korkutan
bizi yaşatan kan
günler perişan', 'yırtarak geçiyor kalbimizden hayatı da törpüleyen zaman şuramızda birşey var acıya benzer umuda benzer böyle günlerde hayat hem acıya, hem a...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas_zekai_ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":69}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLER SÜPÜRÜYOR AĞITLARI', 'gunler-supuruyor-agitlari-gonca-ozmen-s1rj8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bomba gibi düşüyor
sözcükler usuma ve bir infilâk
Rüzgâr çıkarsa dökülür yapraklarım
Her şiir yeni bir sancıdır
Bir balerin, çiçek kadar
yumuşak adımlarıyla
Okşayıp gidiyor yüreğimi
Günler süpürüyor ağıtları
Kara bir asker botunun altında
çiğnenmiş papatya artığı
İyi ki gökyüzüne basamıyor ayaklarımız', 'Bir bomba gibi düşüyor sözcükler usuma ve bir infilâk Rüzgâr çıkarsa dökülür yapraklarım Her şiir yeni bir sancıdır Bir balerin, çiçek kadar...', ARRAY['Türk Edebiyatı','Şiir','Gonca Özmen']::text[], 8.5, '{"poet":"Gonca Özmen","poet_slug":"gonca_ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLER', 'gunler-adnan-azar-27bsn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasıl eskiyim nasıl eskiyim
ince bıçaklar gezdiriyorum yedeğimde.
Bana eksiklerden söz etme
işte şu deniz şu yürüdüğüm fırtına
bak nasıl taşırıyor günleri
nasıl taşırıyor ve bakışlarım
hangi sular renginde.
Çok yoruldum ne çok yoruldum
hep sulardan çaldım suretini.
Artık kelimeleri unut adını unutturma
ölüm gelir ölüm gelir
bir balkondan avluya-
kalsın bütün beklediklerim.
Sonra beni günler ağlasın
sana ağlasın beni!', 'Nasıl eskiyim nasıl eskiyim ince bıçaklar gezdiriyorum yedeğimde. Bana eksiklerden söz etme işte şu deniz şu yürüdüğüm fırtına bak nasıl taş...', ARRAY['Türk Edebiyatı','Şiir','Adnan Azar']::text[], 8.5, '{"poet":"Adnan Azar","poet_slug":"adnan_azar","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLERDEN EYLÜL, AYLARDAN ERGİN GÜNÇE', 'gunlerden-eylul-aylardan-ergi-n-gunce-ergin-gunce-cf4h3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlük şarabımız var maşrapa içinde
Külde pişmiş patatesler ve eşsiz pilavzerde
Din kitaplarımız, putlarımız, telvelerimiz
Yeleği de köstekli bir amca kahvesinde
Suratı çilli günler, gölgesi uzun günler
İşte bir bağ bozumu, işte bir çıngıl üzüm
Gökyüzüne yaslanıp saatimi kuruyorum
Kimsecikler duymasın bir Tanrı olduğumu
İstersen bu Duayı bir Çınara söylerim
Ben kendi başımdaki en önemli şapkayım
Islıkla her türlü marşı çalan bir Arap
Bazan bizim orada bir yokuştan iniyor
İşte durumlar böyle ey Kandil Simitleri
Bir değirmen bu günler kalbimi öğütürüm
Serentiler kurarım ömrümü kuruturum
Haritamda denizlerin yerleri değişiktir
Günlük peynirinizi bize veriyor
Kızarmış bayat ekmek, suda kaynamış pirinç
Sen ne dersen de yeleği köstekli Kahve
Durup dururken Tanrımı seviyorum
Günlerden Eylül aylardan Uzun Eşek
Bir Tabanca çıkarıp kendimi vuruyorum.', 'Günlük şarabımız var maşrapa içinde Külde pişmiş patatesler ve eşsiz pilavzerde Din kitaplarımız, putlarımız, telvelerimiz Yeleği de köstekl...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin_gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLERDEN ÖYLE BİR GÜN', 'gunlerden-oyle-bi-r-gun-metin-altiok-999sd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerden öyle bir gündü;
Üstüne tarih düştüğüm.
Gözümün önüne geldi birden
Balkıyan güzel yüzün.
Ve yüreğim yandı söndü,
Ter bastı avuçlarımı.
Bir işlek kovan uğultusu
Kapladı kulaklarımı.
Uzandım usulca cigarama;
Yavan ömrüme katık.
Ben o gün öldüm gülüm,
Bir daha ölmem artık.', 'Günlerden öyle bir gündü; Üstüne tarih düştüğüm. Gözümün önüne geldi birden Balkıyan güzel yüzün. Ve yüreğim yandı söndü, Ter bastı avuçları...', ARRAY['Türk Edebiyatı','Şiir','Metin Altiok']::text[], 8.5, '{"poet":"Metin Altiok","poet_slug":"metin_altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLERE DAİR', 'gunlere-dai-r-sevencan-keserkaya-498m0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sevinçler eğreti,
iğnesi kırılmış broş gibi
günler yakamda...
düşündüğüm son konuğu da uğurladı
yüreğim
çekildi oda köşelerine
koltuğum
kitaplarım
camı çizik gözlüğüm
buğulu dudak izli su bardağım.
duvarda
mavi bir düğüm ucunda sarkan tuval.
gece düğümünü çözsün artık
koynuna aldığı gün ışığının
bir gün daha düştü
iğnesi kırılan broş gibi yakmdan
gözleri çapaklı
sesler uyandı
sözlerimi düne bağlayamadan.', 'sevinçler eğreti, iğnesi kırılmış broş gibi günler yakamda... düşündüğüm son konuğu da uğurladı yüreğim çekildi oda köşelerine koltuğum kita...', ARRAY['Türk Edebiyatı','Şiir','Sevencan Keserkaya']::text[], 8.5, '{"poet":"Sevencan Keserkaya","poet_slug":"sevencan_keserkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLERİMİZ', 'gunleri-mi-z-ahmet-hamdi-tanpinar-07g4c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçlenme, beyhudedir, maziyi sakın anma!
O vefasız yavruya benzer ki günlerimiz.
Kendini yuvasından bırakır ki akşama
Benzeyen göle, sessiz...
Ruhundaki susuzluk engin mesafelere
Duyurmadan ne anne ne bir yuva hasreti,
Narin kanatlarıyla uçar orman, dağ, dere
Ve bir gün bir çukurda bulunur iskeleti.', 'İçlenme, beyhudedir, maziyi sakın anma! O vefasız yavruya benzer ki günlerimiz. Kendini yuvasından bırakır ki akşama Benzeyen göle, sessiz.....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hamdi Tanpinar']::text[], 8.5, '{"poet":"Ahmet Hamdi Tanpinar","poet_slug":"ahmet_hamdi_tanpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNLERİN ÇIKRIĞI', 'gunleri-n-cikrigi-metin-cengi-z-n9cp4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gece: akıp gider sularla zaman
Otların saplarını gümüş titreterek
Konarak böceklerin uçma telaşına
Göğü kuşanıp taş, toprak, ışıkla
Girer mahpushane avlusuna
İlk vakit: uyanır anılar bizden önce
İsteğin sıcağındaki iri kuşlar
Belleği yoğurarak bir parça gelecekle
Kaynaması gibi etin kemiğe
Örülür yavaş yavaş ömrümüze
Bir güneş imgesidir işte yolculuklar
Esen rüzgârı uçurum ağzıyla dolanır
Sürtüşüp ipek, demir ve buzla
Akarak nehirleri bir denizden içeri
Islak yapraklardaki ışığı yansır
Bir tren gibidir her an burda sevgilim
İstasyondan istasyona geçip gider
Geçip gider çevirerek günlerin çıkrığını
An gelir, gül gibi sabahları takınır', 'Gece: akıp gider sularla zaman Otların saplarını gümüş titreterek Konarak böceklerin uçma telaşına Göğü kuşanıp taş, toprak, ışıkla Girer ma...', ARRAY['Türk Edebiyatı','Şiir','Metin Cengi̇z']::text[], 8.5, '{"poet":"Metin Cengi̇z","poet_slug":"metin_cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNÜLLÜ ÖLÜ', 'gonullu-olu-charles-baudelaire-llag1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koyu bir çamur bulup solucanlara uysam,
Bir derin çukur kazsam cânım için cihanda,
Serip kart kemikler''mi, bi yatsam, bi uyusam,
Bataklığa gömülmüş timsah gibi nisyanda.
Nefretim vasiyetler, nefretim kabirler tüm.
Avuç açacağama bidamlacık yaş için,
Sağken, akbabaları başıma üşürürüm,
Gölkanlara belensin o cenabet cesetim!
Kurtlar, gözsüz-kulaksız, benim kankardeşlerim,
Bolahenk feylesoflar, daldölleri leşlerin,
İşte size bir ölü, güloynar ve gönüllü!
Örenimin üstünde fırdönün gönlünüzce!
Var mı ölümden öte ölüye bir işkence,
Ölümü seçmiş madem ölülerle bu ölü?
Charles  BAUDELAIRE', 'Koyu bir çamur bulup solucanlara uysam, Bir derin çukur kazsam cânım için cihanda, Serip kart kemikler''mi, bi yatsam, bi uyusam, Bataklığa g...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖNLÜM', 'gonlum-orhan-seyfi-orhon-92qrw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim gönlüm bir kelebek
Dolaşıyor çiçek çiçek.
Tükenecek ömrü böyle
Çırpınarak, titreyerek
Ne şerefli bir adı var,
Ne bir büyük maksadı var.
Her gün biraz zedelenen
İki ipek kanadı var!
Sabırlıdır, gözü toktur,
Zavallının derdi çoktur.
Yorulunca konacağı
Bir yuvası bile yoktur.
Her şey ona karşı durur:
Güneş yakar, kış dondurur.
Bazı tutar kanadından
Bir fırtına yere vurur.
Benim gönlüm bir kelebek
Dolaşıyor titreyerek.
Zavallının bir baharlık
Ömrü böyle tükenecek!', 'Benim gönlüm bir kelebek Dolaşıyor çiçek çiçek. Tükenecek ömrü böyle Çırpınarak, titreyerek Ne şerefli bir adı var, Ne bir büyük maksadı var...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi̇ Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi̇ Orhon","poet_slug":"orhan_seyfi_orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNÜN HERHANGİ BİR SAATİ', 'gunun-herhangi-bi-r-saati-ali-puskulluoglu-fglpx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yıldız, bir karanlık
düştü şavkı suya.
Çok değil burda artık
(ülkem için) gözyaşı
azıcık, birkaç damla.
İşte bir gün daha bitti
çocuğun gözleri doldu.
Kuyunun suyu çekildi,
gidip geliyor (gölgem)
her zaman hiçbir zaman arasında.
Nerde haziranlar nerde temmuzlar
açan her gül?
Bir düş solar
(saati yürür) çünkü,
inceden, acıyla.
Çekilmiş olsam da bir köşeye
gözlerimi yummuyorum
hiçbir şeye,
(hayır, diyorum) hayır
yüz kez, bin kez ve daha.
Yok olmaz, biliyorum
söylenmemiş bir söz bile.
Gün ışığı mı yitecek
gece karanlığı mı (diyorum)
bilinmez ama.
Bir yıldız, bir karanlık
işte bir gün daha bitti,
çok kalmadı sabaha.
Saati yürüyor günün
her zamanla hiçbir zaman arasında.', 'Bir yıldız, bir karanlık düştü şavkı suya. Çok değil burda artık (ülkem için) gözyaşı azıcık, birkaç damla. İşte bir gün daha bitti çocuğun ...', ARRAY['Türk Edebiyatı','Şiir','Ali̇ Püsküllüoğlu']::text[], 8.5, '{"poet":"Ali̇ Püsküllüoğlu","poet_slug":"ali_puskulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNÜN İÇİNDEKİ', 'gunun-i-ci-ndeki-mustak-erenus-5yl4h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu bağışlanmak isteği de
Nerden çıktı şimdi
Cam gerisinde bir başına
Şu kumrunun gözleri
Yeşille karmakarışık
Bir türlü anlayamıyorum
Bu bağışlanmak isteği de
Nerden çıktı şimdi
Bir ömür boyu
Birbirimizi görmediğimiz
Bu güzel başım
Ve sanki bir inada
Yürütüp getirdiğim bu ayaklar
Ve nedense her sarhoşluğumda
Bakıp da özür dilediğim bu ellerim
Bugün benden ayrı ve uzak
Ve güzel güneşe gülüyorlar
Fena yakalandım bu sabah
Göğün mavisine', 'Bu bağışlanmak isteği de Nerden çıktı şimdi Cam gerisinde bir başına Şu kumrunun gözleri Yeşille karmakarışık Bir türlü anlayamıyorum Bu bağ...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GOYA', 'goya-andrey-voznesenski-s7xbp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben Goya''yım!
Çorak bir tarlaya kuzgunlar gibi süzülen düşman
yuvalarından oydu gözlerimi.
Ben acıyım!
Ben iniltisiyim
savaşın. 41 karlarında yanmış
şehirlerim ben.
Ben açlığım!
Ben kırılmış boynuyum
çıplak alana çanlar gibi sallanarak asılmış
bir ihtiyar kadının...
Ben Goya''yım!
Ey gazap üzümleri!
Top sesleriyle yürüdüm Batı''ya,
çağrısız konuğun külleriyim ben!
O unutulmaz göğe tabut çivileri gibi
sert yıldızlar çaktım!
Ben Goya''yım!
Andrey VOZNESENSKİ', 'Ben Goya''yım! Çorak bir tarlaya kuzgunlar gibi süzülen düşman yuvalarından oydu gözlerimi. Ben acıyım! Ben iniltisiyim savaşın. 41 karlarınd...', ARRAY['Türk Edebiyatı','Şiir','Andrey Voznesenski̇']::text[], 8.5, '{"poet":"Andrey Voznesenski̇","poet_slug":"andrey_voznesenski","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖRÜŞ GÜNÜ', 'gorus-gunu-enver-gokce-ltbot', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bugün görüş günümüz
Dost kardeş bir arada
Telden tele
Mendil salla el salla
Merhaba !
İzin olsun hapisane içinde
Seni
Senden sormalara doyamam
Yarım döner cıgaranın ateşi
Gitme dayanamam', 'Bugün görüş günümüz Dost kardeş bir arada Telden tele Mendil salla el salla Merhaba ! İzin olsun hapisane içinde Seni Senden sormalara doyam...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver_gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GRİ MAJÖR SENFONİ', 'gri-major-senfoni-rub-n-dario-w1u8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Deniz cıvalı, uçsuz bir cam gibi
yansıtır levhasını çinko bir gökyüzünün,
uzak kuş sürüleri kirletir
cilalı tabanını solgun grisinin.
Güneş toparlak ve donuk bir vitray gibi
hasta adımıyla yürür doruğa;
dinlenir gölgede deniz rüzgârı
yastığıdır kara trompeti.
Kurşuni karnının dalgaları salınır
iskelenin altında inlercesine.
Düşünür bir denizci, Kaf diyarının,
uzak sisli bir ülkenin sahillerini
bir halatın üstüne oturmuş, tüttürürken piposunu.
Şu ihtiyar deniz kurdu. Kavurmuş yüzünü
Brezilya güneşinin yalaz ışınları;
görmüşler içerlerken bir şişe cinini
Çin denizlerinin yaban tayfunları.
İyot ve güherçileden kökü kokan köpük
tanır öteden beri kırmızı burnunu,
kıvırcık saçlarını, atletik pazularını,
yelken bezinden kepini, pamuklu yeleğini.
Tütünden çıkan duman bulutunun ortasında
görür o ihtiyar uzaklıkları, sisli diyarı,
sıcak ve altuni bir akşam
yelkenleri salınmış çektirgeyle çıktığı.
Tropik siestası. Uyur deniz kurdu.
Ve sarıp sarmalar onu grinin tüm tonları.
Sanki yumuşak devrisi bir gölge kalemi
siler ufuğun kavisli çizgisini.
Tropik siestası. İhtiyar ağustos böceği
dener boğuk sesli, emektar gitarını
ve ses verir çekirge tekdüze bir solodan önce
kemanının tek teli üzerinde.
Rubén DARIO', 'Deniz cıvalı, uçsuz bir cam gibi yansıtır levhasını çinko bir gökyüzünün, uzak kuş sürüleri kirletir cilalı tabanını solgun grisinin. Güneş ...', ARRAY['Türk Edebiyatı','Şiir','Rubén Dario']::text[], 8.5, '{"poet":"Rubén Dario","poet_slug":"ruben_dario","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÉRARD DE NERVAL', 'g-rard-de-nerval-ahmet-oktay-svjbv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Siyahın gezginiyim: Her gün daha derine
Yanar akşamla caddede vebalı lambalar,
Bezgin, sıkıntıyla bakar herkes benzerine;
Redingotlarıyla mumya gibi otururlar
İş yerlerinde, kahvelerde. Ve akar zaman.
-Birden söner uzak bir yıldız gibi yaşaman-
Demek isterim, alımlı kadının birine.
Çünkü kanar &quot;bir mezarda bırakılan aşklar&quot;:
Adrianne! Jenny! Yıllardır bakir bir dulum ben,
Avuntu bilmez. Nafileydi tüm yolculuklar
O arayış: Kara güneş içimdeydi zaten.
Gittim harfin ve sayının bilinmez ucuna:
Ölü yüzüm çekilmişti gecenin burcuna,
Korkmadım sokağa hapsediyorken kapılar.
Adoniram! Hançerle sınandı ustalığın
Ve açıldı gül gibi Toht Kitabı''ndaki giz:
Herkes iki''dir. Ben kimin öteki adıyım?
Söyle: Bulmak mıydı amacın ey yitik ikiz.
&quot;İçimizde bir oyuncu, bir seyirci yaşar&quot;
Ve  &quot;akıl ürünleri delilikten de çıkar&quot;
Kazıyınca pıhtısını o yıkık zamanın.
Melek gülümsemiyor artık Öteki Anam,
Çekil! Çünkü &quot;siyah ve beyaz olacak gece.&quot;
Ulaşır mı yaralı hayvan gibi bağırsam
Sesim bencil, sevgisiz, muhkem ev içlerine?
Onulmazım. Çağcıl kentin yabanıl yitiği.
Tek giysim vebalı ışıklarla melankoli,
Bir redse kurtulmak bile istemem yazgımdan.
İki''yim: Yakalandım sokakta çırılçıplak
Ve giydirildim başkalarının sözleriyle.
Ah! Karanlığa giren görür beyazı ancak,
Hangisiyim? Biliyorum kimin gözleriyle?
Ne yapsak silinmiyor ruhtan geçmişin izi
Yaşamak kadar ölüm de çağırıyor bizi,
Geçiyorum sokağı fenerle konuşarak
Hem yaşamın imidir hem ölümün her fener
MORG KAYDI
Giriş tarihi: 26 Ocak 1885
Adı, Soyadı: Labrunie, Gérard de Nerval deniliyor
Cinsiyeti: Erkek
Yaşı: 47
Doğum yeri: Paris (Seine)
Medenî hali: Bekâr
Mesleği: Edebiyatçı
Giyim/Eşya: Siyah ceket, siyah yakalık, gömlek,
flanel yelek, gri-yeşil pantolon,
kızıl çoraplar, boyalı ayakkabılar,
siyah şapka
Ölüm biçimi: Asılma
İntihar ya
da cinayet: İntihar
Ölüm nedeni: Bilinmiyor
Gözlem: Morga kaldırılmadan önce tanındı.
Cesede Edebiyatçılar Derneği sahip çıktı
NASİPSİZİM', 'Siyahın gezginiyim: Her gün daha derine Yanar akşamla caddede vebalı lambalar, Bezgin, sıkıntıyla bakar herkes benzerine; Redingotlarıyla mu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Oktay']::text[], 8.5, '{"poet":"Ahmet Oktay","poet_slug":"ahmet_oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":57}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GRAVÜR', 'gravur-salih-bolat-m4ybg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bu dağlar o çok öldüğüm dağlar değil
eğri büğrü gülen bu çocuk
bu yamyassı rüzgar
kapının önünde uluyan bu gece
ufukta uyanan bu masmavi kadın cesedi deniz
bu yeni doğmuş tayın ıssız adımları
sığ sularda boğulan bu balık
o değil
bu umutsuzluğun gravürü
umutsuzluk: tabutuma  çakılacak son çivi', 'bu dağlar o çok öldüğüm dağlar değil eğri büğrü gülen bu çocuk bu yamyassı rüzgar kapının önünde uluyan bu gece ufukta uyanan bu masmavi kad...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih_bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GRAVİTASYON', 'gravi-tasyon-kagan-kok-rcp32', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ana rahmidir uçurumun ağzı
Hayata itildiğimiz
Önce içeri doğru -döllenme-
Sonra dışarı -doğum-
Ve ardından başlar düşüş serüvenimiz
Yaşamın ve aşkların üzerinden düşen pas
Sevdalarsa hep kendini göstermiş bir atlas
Oluyorlar orda
Yok odalarında varoldum ya
Ey yaşamak denen mecaz.', 'Ana rahmidir uçurumun ağzı Hayata itildiğimiz Önce içeri doğru -döllenme- Sonra dışarı -doğum- Ve ardından başlar düşüş serüvenimiz Yaşamın ...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİRDAP VE SAFİR', 'gi-rdap-ve-safi-r-cihan-oguz-fjbr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'XVII.
Uyu küçük kalbim
saplandığın girdap
bozbulanık o karmaşa
yeni bir yıldız kümesi
akar
öpüşen iki balığın ortasından
suçtur belki
denizin bir parçası olmak
kara''ya dönüş öncesi
titreterek bağlı kaldığın çemberi.
Yitik zamanıdır güzün
saçılır yapraklar belli belirsiz
bir tokat patlasa akşamları
yankısı sabahı bulur.
Uyu küçük kalbim
çarpa çarpa ulaştığın tünel
bir mavinin derini.
Orada safir yüzlü bir melek
-günahından terk, sevabına bağımlı-
yeni suçlar bulacak sana
dayandığın yeni masallar.
Oysa ömrün
bir defineye adanmış
orada safir yüzlü bir melek
biraz ölüm çağrışımlı
biraz yeni bir aşkı müjdeler gibi
ansızın çırılçıplak...', 'XVII. Uyu küçük kalbim saplandığın girdap bozbulanık o karmaşa yeni bir yıldız kümesi akar öpüşen iki balığın ortasından suçtur belki denizi...', ARRAY['Türk Edebiyatı','Şiir','Cihan Oğuz']::text[], 8.5, '{"poet":"Cihan Oğuz","poet_slug":"cihan_oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖREBİLDİĞİN KADAR MAVİ', 'gorebi-ldi-gi-n-kadar-mavi-mehmet-basaran-0e0gm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sürebildiğin kadar toprak
Sarabildiğin kadar kadın
Bu dünya
Güvenebildiğin kadar dost
Düşünebildiğin kadar güzel
Yaşabildiğin kadar
D ü n y a', 'Sürebildiğin kadar toprak Sarabildiğin kadar kadın Bu dünya Güvenebildiğin kadar dost Düşünebildiğin kadar güzel Yaşabildiğin kadar D ü n y ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GREEN   (YEŞİL)', 'green-yesi-l-paul-verlaine-mz0ro', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte yemişler, çiçekler, yapraklar ve dallar!
İşte kalbim, çarpıntısı yalnız senin için!
O bembeyaz ellerin kalbimi kırmasalar!
Bu küçük armağanı dilerim hoş göresin.
Ben geldim işte, çiğlerle bezenmiş olarak;
Alnımda seher yelinin dondurduğu çiğler,
Yorgunluğumu alsam ayak ucunda bırak!
Hayal etsem o tatlı demleri birer birer.
Bırak unutayım başımı taze göğsünde!
Hâlâ aklımda lezzeti son öpüşlerinin.
Hayırlı fırtınadan sonra sakin, asude,
Uyusam biraz, madem uzanmış dinlenirsin.
Ülkü, 16.7.1945
Paul VERLAINE', 'İşte yemişler, çiçekler, yapraklar ve dallar! İşte kalbim, çarpıntısı yalnız senin için! O bembeyaz ellerin kalbimi kırmasalar! Bu küçük arm...', ARRAY['Türk Edebiyatı','Şiir','Paul Verlaine']::text[], 8.5, '{"poet":"Paul Verlaine","poet_slug":"paul_verlaine","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖRKEMLİ GÖĞ', 'gorkemli-gog-enis-akin-tcb0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onlar at değil bendim
Atların yerine oyuna ben girdim
Islatılmış ve ilgilenilmemiş
At arabasına kendini keyifle koşan bir ıslak
Görülmüşlüğüne bakanlara
Haksızlı ve ilgilenilmiş bir intikam sunacak, değil at bendim
Kurusun diye şafağın en göğüne astım dudaklarımı, gül ve ağlanın arasına.
Soylara çekmemek için babalar değiştirmece oyununa
Dudaksızlığın yerine ben girdim
Ardımda roze bir birikinti bırakıp
Yerçekiminin cazibesine kapılabilirim
Seyisimin içine elimdeki şeyi kilitleyerek
Babamın dudakları gibi bir balığın son titreyişinden öperim
Aşk işenmişti, hayat bizim son şansımızdı
Bir şafak ve üç çöp kovası da ben devirdim', 'Onlar at değil bendim Atların yerine oyuna ben girdim Islatılmış ve ilgilenilmemiş At arabasına kendini keyifle koşan bir ıslak Görülmüşlüğü...', ARRAY['Türk Edebiyatı','Şiir','Enis Akin']::text[], 8.5, '{"poet":"Enis Akin","poet_slug":"enis_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖRÜLMEMİŞ BİR ÇİÇEK AÇMA', 'gorulmemi-s-bi-r-ci-cek-acma-yannis-ri-tsos-lha2p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırmak istiyordu - daha fazla dayanamayacaktı. Sesini
duyabilecek kimse yoktu orada;
kimse duymak istemiyordu. Kendisi de korkuyordu sesinden,
içinde boğuyordu sesini. Patlamak üzereydi susuşu. Birden,
havaya uçtu gövdesinin parçaları. Özenle, sessizce
toplayacaktı bu parçaları,
hepsini bir bir yerlerine yerleştirecekti delikleri kapamak
için.
Ve rasgele bir gelincik, bir sarı zambak bulursa, onları da
toplayacak,
kendisinin bir parçasıymış gibi gövdesine yapıştıracaktı -
böyleydi, delik deşik, görülmemiş bir şekilde çiçek açıyordu
işte.
Çeviren: Cevat Çapan', 'Haykırmak istiyordu - daha fazla dayanamayacaktı. Sesini duyabilecek kimse yoktu orada; kimse duymak istemiyordu. Kendisi de korkuyordu sesi...', ARRAY['Türk Edebiyatı','Şiir','Yannis  Ri̇tsos']::text[], 8.5, '{"poet":"Yannis  Ri̇tsos","poet_slug":"yannis_ritsos","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖRÜNDÜĞÜ GİBİDİR DÜNYA', 'gorundugu-gi-bi-di-r-dunya-miguel-hern-ndez-oqgis', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göründüğü gibidir dünya
sergilenmiş beş duyumun
ve seninkilerin önünde,
benimkilerin kıyıları olan.
Değil bizimkisi
ötekilerin dünyası:
Aynısı değil.
Ben yatağıysam suyun,
seninle ırmağız ikimiz
derinleştikçe daha
usul ve kıpırtısız görünen.
Görüntüleri yaşamın:
aynı anda ulaşır ikimize
ve kendimizi bırakmış bulur bizi,
ikimiz birden aynı ritme.
Ama her şey bizim
kendi çılgınlığımızdan doğar.
Hava, onu soluyan
yüreğimin büyüklüğünde
ve güneş sanki ona
meydan okuduğum ışık gibi.
Gözümüz görmeden kimseyi
hep karanlık hep gönülsüz
yalnızca içimize çevirdik bakışı
en içerdekini görmeye.
Çaba ve aşk gerektiriyor
seni böyle benimle görmek;
nasıl birlikteyse suyla kum
hep bir arada, öyle görünmek.
Ne kimse beni gerçekten görecek
ne de kimse benim gördüğüme benzeyecek.
Göründüğümüzden bir fazlasıyız,
düşünebildiklerimizden bir eksik.
Başımıza gelenlerden biri
fark edilmeden gelir geçer.
Ne kimse gördü bizi, ne de biz
kimseyi, görmeyen gözlerimizle.
Miguel HERNÁNDEZ', 'Göründüğü gibidir dünya sergilenmiş beş duyumun ve seninkilerin önünde, benimkilerin kıyıları olan. Değil bizimkisi ötekilerin dünyası: Aynı...', ARRAY['Türk Edebiyatı','Şiir','Miguel Hernández']::text[], 8.5, '{"poet":"Miguel Hernández","poet_slug":"miguel_hernandez","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖRÜNTÜLENİŞLER XIX. TUNÇTAN BİR YALNIZLIK', 'goruntuleni-sler-xix-tunctan-bi-r-yalnizlik-tugrul-asi-balkar-87whj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ilk o geldi rıhtıma demirlediği umutlarıyla
durdu. artık yaşamaktan yoruldum
diye yanıtladı oğlunu
ufku izledikçe sonsuzluğun çizgileri
yerleşirken alnına
uykusuzluk, soluğunu kesen öksürük nöbetleri ve kan
sığ sularında tekneler yüzdürdüğü kasaba:
bodrum, her insan bir bodrum burada
bir yalnızlık kalesi ve poyraz
poyraz olmalıydı uykularımın son limanı
de oğul kimin ağına takıldı ki
mutluluk, kimin
çekilirken deniz ağlardan.
tunçtan bir yalnızlık kalesi babam
gözleri çakır.', 'ilk o geldi rıhtıma demirlediği umutlarıyla durdu. artık yaşamaktan yoruldum diye yanıtladı oğlunu ufku izledikçe sonsuzluğun çizgileri yerl...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Asi Balkar']::text[], 8.5, '{"poet":"Tuğrul Asi Balkar","poet_slug":"tugrul_asi_balkar","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTANJALİ''DEN', 'gi-tanjali-den-rabindranath-tagore-3zxop', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '3
tanımadığım nice insan tanıttın
nice evde bana da verdin bir köşe
uzağı yakına çevirensin
yabancıyı kardeşe
eski evimden ayrılıp düşünce yollara
düşünürüm ilkin kara kara
eskide de var olan sensin oysa
yenide de var olan sen
uzağı yakına çevirensin
yabancıyı kardeşe
ölümde yaşamda bütün evrende
nereye götürsen beni
tüm doğuşlardan bilinen
sen tanıtacaksın bana herkesi
yabancı yoktur bilene seni
kapılar kapanmaz olur
herkesin bağısın bilen bildirensin
senden ırak kılma beni
uzağı yakına çevirensin
yabancıyı kardeşe
7
türlü türlü ahenklerle gel
kokularla türkülerle renklerle gel
vücudumda duyayım gel seni
başımda duyayım şarap gibi
örtülü gözlerle büyülü renklerle gel
türlü türlü ahenklerle gel
gel pırıl pırıl duru ve güzel
inceliğinle sessizliğinle gel
gel başka başka düzenlerle
acınla gel neşenle gel canevime
gel günümün bütün işlerine
gel işlerden çekince gel
türlü türlü ahenklerle gel
8
çeltik tarlasında güneşle bulutların
saklambaç oyunu var bu kez
mavi gökte ak buluttan sallar
kim yüzdürür bilinmez
arılar ışıkla esrik
balı kovanı unutmuş
ırmak kıyısında bir yığın kuş
neden toplanır bilinmez
girmesek bugün evden içeri dost
girmesek evden içeri
basıversek de göğü bugün
yağma etsek enginleri
sularda köpükler gibi
rüzgârda gülüşler koşuyor bak
boşversek de işi gücü
günü türkülerle harcasak
10
altın tepsisinde bugün sana
gözyaşlarımı sunacağım mücevher gibi
bir gerdanlık dizeceğim onlardan
inciler gibi
ayaklarındaki halkalar
aydan güneşten olabilir
benim acımsa göğsüne
bir değerli taş gibidir
ne varsa senin
olur ne dersen
ister verirsin
alırsın ister
acımsa benimdir ancak
bilirsin taşın temizini
karşılığında bir gülüşün
yeter gönendirmeye beni
11
çelenk ördük çiçeklerden
otlardan demetler derdik
bir sepet sunuyoruz içine
taze başaklar serdik
gel ey güz Lakşimi''si
koşulsun ak buluttan araban gel
duru mavi yollarda gel
gel bütün karanlığı yıkanmış
ışıkla donanmış
ormanlardan tepelerden dağlardan
gel tacın ak nilüferlerle bezenmiş
serin çiğler içinde
Ganj''ın sular basmış kıyısına
kuştu korularda döşek serilmiş
dökülen yaseminlerden sana
kuğu dönüp yaymış kanatlarını
ayak ucuna
fısıltılar yükselir tellerinden
senin altın çalgının
bal gibi tatlı bir vızıltı derinden
eriyiverecek gözyaşlarıyla ansızın
kahkaha taşan ahenk
denektaşıdır pırıldayan
saçının büklümlerinde yer yer
bir an için o esirgeyen yeller
dolaşsa düşüncemizde
altına dönüşür dertlerimiz
karanlıktan ışığı çıkıveririz
20
bir yaz akşamıdır karanlık çöküyor
gün yok olmuştur
kesintisiz boşanır gökten
bir tükenmez yağmur
çekilmişim evin bir köşesine
kurarım kendi kendime
bahçede ıslak esen yel
kimbilir ne konuşur
kesintisiz boşanır gökten
bir tükenmez yağmur
dalgalar yükseldi gönlümde bugün
kıyı görünmez oldu
çiçek kokularından ıslak bahçenin
gözlerime yaş doldu
neylesem bu akşam neylesem
ne türküler söylesem
büyülü bir el değer belleğime
bildiklerim yok olur
kesintisiz boşanır gökten
bir tükenmez yağmur
Rabindranath TAGORE', '3 tanımadığım nice insan tanıttın nice evde bana da verdin bir köşe uzağı yakına çevirensin yabancıyı kardeşe eski evimden ayrılıp düşünce y...', ARRAY['Türk Edebiyatı','Şiir','Rabindranath Tagore']::text[], 8.5, '{"poet":"Rabindranath Tagore","poet_slug":"rabindranath_tagore","theme":"Türk Şiiri","is_hero":false,"total_lines":122}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTME DEDİM', 'gi-tme-dedi-m-mevl-n-lhyfn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oraya gitme dedim sana,
seni belâlara uğratırlar dedim,
dedim ayaklarını bağlarlar.
Gidersen dedim nerden kurtaracaklar seni,
orda tuzaklar içinde tuzaklar var.
Dedim orda ne idüğü belirsiz kişiler
bir sürü ipe sapa gelmez laf ederler.
Dedim bir lokma gibi kapıverirler seni,
atarlar ciğer gibi çorbalarının içine,
gözyaşına bakmazlar.
Dedim hamur yoğurur gibi yoğururlar seni,
havaya uçururlar dedim dağ olsan.
Çekerler dedim derinin içinden pamuk çeker gibi.
Hayale dönersin dedim sonra,
yönsüz hale gelirsin dedim sonra.
O aşağılık herifler hayvan gibi ot yerler dedim,
bir ele geçirdiler mi dedim ananı bellerler.
Oraya gitme dedim,
oraya gitme dedim sana.', 'Oraya gitme dedim sana, seni belâlara uğratırlar dedim, dedim ayaklarını bağlarlar. Gidersen dedim nerden kurtaracaklar seni, orda tuzaklar ...', ARRAY['Türk Edebiyatı','Şiir','Mevlânâ']::text[], 8.5, '{"poet":"Mevlânâ","poet_slug":"mevlana","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTME KAL', 'gi-tme-kal-arif-damar-gdhc1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice nice acıları aklına getir
Bunca yoksulluğu aklına getir
Gözyaşlarını aklına getir
"GİTME KAL" var yok dinlemez bir çocuk isteğidir
Gitme aklına getir
Kıraç mı kıraç toprakların üstüne
Güneşler açar yağmurlar kesilince
Çırılçıplak kayada yeşerir inci ağacı
Dağların kuytusunda bir uslu çiçek
Dağıtır mavisini kendi kendine
Gitme beraberlik içinde
Nasıl sevinirdik aklına getir
Her şeyi her şeyi aklına getir
Gece yarılarını aklına getir
Söylediklerini aklına getir
Sinsi yağmurlar yağıyordu
Soğuktu
Yaktığımız ateşi aklına getir
Nelerden geçiyorsun aklına getir
Gitme dünyamızın her yerinde
Yorgun eller gülleri derleyince
Ellerin sevincini aklına getir
Güllerin sevincini aklına getir
Ne çok severdik seni aklına getir', 'Nice nice acıları aklına getir Bunca yoksulluğu aklına getir Gözyaşlarını aklına getir "GİTME KAL" var yok dinlemez bir çocuk isteğidir Gitm...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTME', 'gi-tme-ayten-mutlu-ihg2z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dur
uyanan güz çiçeklerinin
alazlanan taşların
çalınmış yazgıların ve ıslak hüzünlerin
ülkesi olan
yanımda kal
o vahşi güzelliği gitmelerdeki
bugünlük
çöl rügârlarına bağışla ne olur
kalırsan
akşam ve bulut ve gökyüzü ve çimen
ve gözyaşı ve kahkaha ve hüzün
ve yalnızlık
-o gizi ömrümüzün-
bu eski hikâyede ne varsa yaşanmayan
başlayacak birazdan
gitme', 'dur uyanan güz çiçeklerinin alazlanan taşların çalınmış yazgıların ve ıslak hüzünlerin ülkesi olan yanımda kal o vahşi güzelliği gitmelerdek...', ARRAY['Türk Edebiyatı','Şiir','Ayten Mutlu']::text[], 8.5, '{"poet":"Ayten Mutlu","poet_slug":"ayten_mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖTÜMSER', 'gotumser-can-yucel-d0yom', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün gidiyor limoni, bana kalsa da nezle
Sümüklü deniziyle, bulut mendilleriyle
Hapşırdı hapşıracak burnu morarmış Kıble,
Yaşıycağız demek ki bir eyyam daha böyle
Dün gidiyor limoni, mükedder filleriyle', 'Gün gidiyor limoni, bana kalsa da nezle Sümüklü deniziyle, bulut mendilleriyle Hapşırdı hapşıracak burnu morarmış Kıble, Yaşıycağız demek ki...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTTİ', 'gi-tti-celal-silay-1a79p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşitmek istediğini bir sağırın
Sezdi havamızdan geçen şarkı
Duyuramadı sesini, bu sağıra
Eridi, gitti!
Yürümek hasretini bir kötürümün
Hissetti koltuk değnekleri,
Kaldıramadı yatağından hastasını
Çürüdü, gitti!
Körün görmek arzusunu duydu
Bahçenin kenarında bir çiçek
Gösteremedi yapraklarının rengini
Dağıldı gitti!
Ve duydu bir açın yemek ihtiyacını
Buğday tarlasındaki başak
Utandı büyümesindeki şehvetten
Kurudu, gitti!', 'İşitmek istediğini bir sağırın Sezdi havamızdan geçen şarkı Duyuramadı sesini, bu sağıra Eridi, gitti! Yürümek hasretini bir kötürümün Hisse...', ARRAY['Türk Edebiyatı','Şiir','Celal Silay']::text[], 8.5, '{"poet":"Celal Silay","poet_slug":"celal_silay","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİTTİĞİN HER YER YALNIZLIĞIMDIR', 'gi-tti-gi-n-her-yer-yalnizligimdir-bayram-balci-5lo5h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şiir biter sen gidersin ne kalır geride
yağmur yağar ıslanır kirpiklerim
savurur yüzüme ayrılığı şehir
bir ben yalnız kalırım şiir biterse
senin gittiğin her yerde yağmur yağar üzerime
ateş üşür acı kanatır kendini
sen yine de gidersin
silerek ardındaki ayakizlerini
bir bela olur yaşamak
senin gittiğin her yerde uçurumlar büyür aşka
şiir biter büyür o mavi derinlik
sabah çözer gecenin gizini
ipi kopan bir uçaurtma
yalnızlığına ağlar gökyüzünde
senin gittiğin her yer yalnızlığımdır benim', 'şiir biter sen gidersin ne kalır geride yağmur yağar ıslanır kirpiklerim savurur yüzüme ayrılığı şehir bir ben yalnız kalırım şiir biterse s...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GUGUK KUŞU', 'guguk-kusu-osman-namdar-x8e8k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düze çıkamazdı ya annem. kör kıtlık
çağlarından, genç(liğini) kızlığını bırakıp
sabr''ile seviştiği günlerin ardında;
sarım sarmalak öksüz bir çocuklukla...
öyle çıkmışmış hayata ve sokağa
ama gömüp de gök gözlü erini erkenci
avlusuna doluşan kuşlarını yemlemiş
her akşam, her akşam: tam yedi tane, yani yedi kuş...
bir türlü çıkamamış gül yüzlü bir sabaha
(elinde harlı asasıyla, er düşlere yatan bir adam
er gece vakitleri, su isterken bahçeleri
nur yüzlü bir ihtiyar halinde babam)
annem, guguk kuşu bile olamadan
yıkık yuvasında, kupkuru; pırnal unu,
nohut kavurgası, kangal kahvesi vesselam.
bilemeden dağlardan öte memleket olduğunu...
yaşamaya başlamışlar bu acıhayatı annemle babam.
annem yine; ben eskiz halinde sekiz''inci,
dokuz doğurmuş, yalnızlığını da sayarsak on...
şimdi, bilir misiniz hangi şehre gidemez annem
yalnızlığıyla çocukluğundan.', 'Düze çıkamazdı ya annem. kör kıtlık çağlarından, genç(liğini) kızlığını bırakıp sabr''ile seviştiği günlerin ardında; sarım sarmalak öksüz bi...', ARRAY['Türk Edebiyatı','Şiir','Osman Namdar']::text[], 8.5, '{"poet":"Osman Namdar","poet_slug":"osman_namdar","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GURBET', 'gurbet-kemalettin-kamu-e6jge', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gurbet o kadar acı
Ki ne varsa içimde
Hepsi bana yabancı,
Hepsi başka biçimde.
Eriyorum gitgide;
Elveda her ümide.
Gurbet benliğimi de
Bitirmiş bir içimde.
Ne arzum, ne emelim...
Yaralanmış bir elim
Ben gurbette değilim,
Gurbet benim içimde.', 'Gurbet o kadar acı Ki ne varsa içimde Hepsi bana yabancı, Hepsi başka biçimde. Eriyorum gitgide; Elveda her ümide. Gurbet benliğimi de Bitir...', ARRAY['Türk Edebiyatı','Şiir','Kemalettin Kamu']::text[], 8.5, '{"poet":"Kemalettin Kamu","poet_slug":"kemalettin_kamu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GURBETE', 'gurbete-yasar-mi-rac-9bect', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gurbete kaçacağım
o lâcivert ülkeye
o üzünç denizine
uzayan iskeleye
ansızın sormaksızın
neler kalır geriye
gurbete kaçacağım
o kimsesiz ülkeye
o geri dönülmeze
bağlanan ilk köprüye
umarsız durmaksızın
acılar tüketmeye
gurbete kaçacağım
o duvaksız tepeye
o yolunda gözyaşı
çeşmesi kuru köye
kopup yalnızlığımdan
kopup sonsuzluğumdan
gurbete kaçacağım
gurbete tükenmeye', 'gurbete kaçacağım o lâcivert ülkeye o üzünç denizine uzayan iskeleye ansızın sormaksızın neler kalır geriye gurbete kaçacağım o kimsesiz ülk...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Mi̇raç']::text[], 8.5, '{"poet":"Yaşar Mi̇raç","poet_slug":"yasar_mirac","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖVEL ÖRDEK', 'govel-ordek-karacaoglan-vp9z6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeşil başlı gövel ördek
Uçar gider göle karşı
Eğricesin tel tel etmiş
Döker gider yare karşı
Telli turnam sökün gelir
İnci mercan yükün gelir
Elvan elvan kokun gelir
Yar oturmuş yele karşı
Şahinim var bazlarım var
Tel alışkın sazlarım var
Yare gizli sözlerim var
Diyemiyom ele karşı
Hani Karac''oğlan hani
Veren alır tatlı canı
Yakışmazsa öldür beni
Yeşil bağla ala karşı', 'Yeşil başlı gövel ördek Uçar gider göle karşı Eğricesin tel tel etmiş Döker gider yare karşı Telli turnam sökün gelir İnci mercan yükün geli...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜVERCİN KAYALARI', 'guverci-n-kayalari-muzaffer-i-lhan-erdost-lzztq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cemal Süreya''ya
Şimdi birçok yıldız doğdu
Kekik kokulu okaliptus tepelerinde
Uyanabilirsen uyan bir bak
Silahın parmaklarının biraz yakınında duruyor
Parmaklarının biraz yakınında sen duruyorsun
Uyanabilirsen uyan bir bak
Kirli ayaklarının altında
Yeşeren bu diken biraz Afrikaysa
Sen de biraz Afrikasın
Yavru güvercinler gidiyor dağlarından
Senin kan kokulu ellerine
Bazı kurşunlardan sonra bir parça kan akıyor
Ne olacak bir parça kan işte
İşte bir parça kan
Afrika önünde
Şimdi birçok yıldız doğdu
Uyanabilirsen uyan bir bak
Kopmuş bir dağ gibi ölü yalnızlığına düşüyor
Şehirlerin pis kokusuna
Etinin daha pis kokusuna
Uyan bir bak
Sol yanında yusufçuk kuşları
Umulmadık şiirler söyleniyor
Bir Afrika haritasına yakın
Denizin sabah aydınlığıyla dolduğu yerde
Güvercinlerin gelip gittiği yerde', 'Cemal Süreya''ya Şimdi birçok yıldız doğdu Kekik kokulu okaliptus tepelerinde Uyanabilirsen uyan bir bak Silahın parmaklarının biraz yakınınd...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer İlhan Erdost']::text[], 8.5, '{"poet":"Muzaffer İlhan Erdost","poet_slug":"muzaffer_ilhan_erdost","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜVERCİN', 'guverci-n-melih-cevdet-anday-klpmy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güvercin
Pencerede kopan alkış', 'Güvercin Pencerede kopan alkış...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜVERCİNİM UYUR MU?', 'guverci-ni-m-uyur-mu-rifat-ilgaz-h9e2e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '"Güvercinim uyur mu,
Çağırsam uyanır mı?"
Sömürgen cami güvercinleri sizin olsun
O doyumsuz lapacı güvercinler
Kurşun buğusu güvercinleri severim ben
Kanat uçları çelik yeşili
Kuş dediğin piyerlotisiz yaşamalı
Adaksız avlusuz şadırvansız
Buluttan süzmeli suyunu
Kuşçular çarşısında tüy dökmemeli
Benim güvercinim tunç gagalı
Kimlerin bakışı kardeşçedir
Kimlerin bakışı düşmanca
Kendisi hangi kavganın güvercinidir bilir
Tüneyip acımanın saçaklarına
Miskin sevilerle bitlenmez
Kanadından çok pençesine güvenir
Barış taklaları süzülmeler
Gagalarda zeytin dalı
Perendeler maviliklerde
Tüm gösteriler resimlerde kalmalı
Güvercin dediğin uyanık olmalı
Tüyler duman duman öfkeden
Yanıp tutuşmalı gözbebekleri
Sevgiden tıpır tıpır bir yürek
Özgürlüğünce dövüşken
(1971)
Güvercinim Uyur mu  adlı şiir kitabından 1970
Bütün Şiirleri 1927-1991(Çınar Yayınları)', '"Güvercinim uyur mu, Çağırsam uyanır mı?" Sömürgen cami güvercinleri sizin olsun O doyumsuz lapacı güvercinler Kurşun buğusu güvercinleri se...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZ DİZELERİ', 'guz-di-zeleri-rub-n-dario-3irgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşüncem burculanır sana doğru gitti mi,
iner dibe o tatlı bakışının altında.
Ak, çıplak ayakların aşağ''da köpük gibi,
yeryüzü sevincidir gülen dudaklarında.
Kısa bir büyü vardır geçici sevgilerde,
ki acıya sevince eşit son verse gerek.
Bir saatti, karlara bir adı yazdım yerde,
bir dakikaydı, kumda sevgimi söyleyerek.
Dökülüyor kavaklı yola sarı yapraklar,
içinde sevgililer gidip gelirken yine.
Ve güzün kadehinde belirsiz bir şarap var,
ki güllerin, ey bahar, düşecektir içine.
Rubén DARIO', 'Düşüncem burculanır sana doğru gitti mi, iner dibe o tatlı bakışının altında. Ak, çıplak ayakların aşağ''da köpük gibi, yeryüzü sevincidir gü...', ARRAY['Türk Edebiyatı','Şiir','Rubén Dario']::text[], 8.5, '{"poet":"Rubén Dario","poet_slug":"ruben_dario","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZ GÖMLEĞİ', 'guz-gomlegi-ahmet-uysal-izw6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güz gömleği giydi şiir
Hüzün sanıyor görenler
Açık kalmış bir düğmesi
Ki rüzgâr girsin diyedir
Cebinde yağmur kokusu
Bir tutam kurutulmuş ot
Yeni bir imge arıyor
Onunla, ince akan su
Bir kadın eli değmiştir
Belki de yıllar öncesi
Saklar durur unutamaz
O gömleği giydi şiir', 'Güz gömleği giydi şiir Hüzün sanıyor görenler Açık kalmış bir düğmesi Ki rüzgâr girsin diyedir Cebinde yağmur kokusu Bir tutam kurutulmuş ot...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZ GÖRÜNÜMÜ', 'guz-gorunumu-yannis-ritsos-27c9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O yoğun nem her şeye sindi. Yazlıkçılar gitti.
İki bulutun altına asılı mavi yazılı
sarı otel tabelaları soldu artık.
Temizlikçi kadın her sabah,
uzun perdeli ve yataklarının altındaki
terlikleri soğumamış yeni evlilerin odalarına
giderken
ağır ağır geçecektir oradan.
Yannis RITSOS', 'O yoğun nem her şeye sindi. Yazlıkçılar gitti. İki bulutun altına asılı mavi yazılı sarı otel tabelaları soldu artık. Temizlikçi kadın her s...', ARRAY['Türk Edebiyatı','Şiir','Yannis Ritsos']::text[], 8.5, '{"poet":"Yannis Ritsos","poet_slug":"yannis_ritsos","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİZ SES', 'gi-z-ses-enis-batur-bgwji', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir rüzgârda buldu seni bir rüzgârda yitirdi,
penceresinden baktı sine sine yağan uçarı yağmura
ve essin dedi, bir daha essin, sen çünkü bana eşsizsin,
gökyüzünde karmaşık bir sözdizimiydi kurduğu esin
perisinin -- çekti sinesine koydu bulutlardan bir tortuyu,
uzan dedi, uzan Enis, tam bir gece için biriksin sesin.', 'Bir rüzgârda buldu seni bir rüzgârda yitirdi, penceresinden baktı sine sine yağan uçarı yağmura ve essin dedi, bir daha essin, sen çünkü ban...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZ SONU ŞİİRLERİ', 'guz-sonu-si-i-rleri-ahmet-uysal-f36pt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şey hazır belki
yarın giderim
Yağmurun sesini de
alırım yanıma
Gömleğimin cebindedir
kuruyan otlar
Eski yerinde kalır gene
bozkır kokusu
Herşey hazır kesin
yarın giderim
Kırgın güz sokağı
uğurlar beni
Benim için rüzgâra
bürünür evler
Kapısını açık bırakırım
ıssız avlumun
Her şey hazır olamaz
hayal bunlar
Şehrini bulamaz bulanık
akan nehir
Savrulur derin vadilerden
düşer köpüğü
Kırık bir dal ucuna döner
kırgın şiirler', 'Her şey hazır belki yarın giderim Yağmurun sesini de alırım yanıma Gömleğimin cebindedir kuruyan otlar Eski yerinde kalır gene bozkır kokusu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİZ', 'gi-z-yasin-erol-z9ft4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şey giz içinde
Giz içinde herkesçe bilinen bir gece
Cinlerin cadıların mekanıdır sessiz bir orman
Başkaları duyacağı kadar duysun
Sen bağır
Çığ düşürecek dağlar benim içimde
Tek başına bir çiçek ne kadar anlar sevildiğini
Ah kim öğretti aşkı sana böyle
Kim gösterdi erken olan çiçekleri
Ya kimindi bu bölüştüğümüz yalnızlık
Herşey giz içinde
Giz içinde herkesçe bilinen bir gece
Cinlerin cadıların mekanıdır sessiz bir orman
Başkaları duyacağı kadar duysun
Sen bağır
Çığ düşürecek dağlar benim içimde', 'Her şey giz içinde Giz içinde herkesçe bilinen bir gece Cinlerin cadıların mekanıdır sessiz bir orman Başkaları duyacağı kadar duysun Sen ba...', ARRAY['Türk Edebiyatı','Şiir','Yasin Erol']::text[], 8.5, '{"poet":"Yasin Erol","poet_slug":"yasin_erol","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZALTI ŞİİRLER', 'guzalti-si-i-rler-ahmet-uysal-ppn22', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hüseyin''e, hidayet''e
artık gizlisi kalmadı arka bahçemin
ele verdim saklı orman yolumu
yaşlı kadınlara dağıttım
kurutulmuş otlarımı da
genç şairlere gönderdim, kırk yıldır
biriktirdiğim rüzgârları
seksen öncesi, sonrası,
ben hep bir kırgınlığı yazdım
nasıl olsa bilirdi büyük ustalar,
yalnızca gül alıp satmadığını bir şairin', 'hüseyin''e, hidayet''e artık gizlisi kalmadı arka bahçemin ele verdim saklı orman yolumu yaşlı kadınlara dağıttım kurutulmuş otlarımı da genç ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZDE', 'guzde-salih-bolat-prc6p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sarayburnu aile çaybahçesindeki bir güz öğlesi
sen ben ve adını bile bilmediğimiz bir istanbul
oturmuş konuşuyoruz her şeyden
senin ellerin masanın üstünde
uzun bir koşuya hazırlanıyor
ben geçip giden gemileri kovalamaktan
soluk soluğa kalmışım
istanbul uykusuz gözlerini oğuşturuyor
bir martı beyazlığını düşürüyor masamıza
bir polis kimliğimizi soruyor
zaman geriliyor geriliyor geriliyor
wilhelm tel in eli titriyor ve kalbime saplanıyor ok
hemen ölüyorum orada ama duyuyorum sizi
cesedimin soğumaması için
istanbul güneşini açıyor üstüme
ölümüm dünyanın dengesini bozuyor
başucundaki sarsıntıdan anlıyorsun bunu
ağzındaki öpücüğün düşmesinden
sarayburnu aile çaybahçesii''nde bir güz öğlesi
sen be n ve adını bile bilmediğimiz bir istanbul
oturmuş konuşuyoruz her şeyden
**********************************
ömrüm diyorum
-  bir rüzgar düşüyor gömleğimin yakasına
saramış eskimiş bir rüzgar
usulca uzanıp alıyorsun onu
saatlerce oynayıp duruyorsun elinde
avucundaki terden ıslanıyor yırtılıyor
eriyip gidiyor sonunda
yalnızca bir serinlik kalıyor
ellerinden bana doğru yayılan -
işte böyle başlıyoruz her şeye
masallarına ihanet eden iki masal kahramanı gibi
iki gerçek oluyoruz seninle
yerküreyi masamızın üstüne koyuyoruz debelenip duruyor
gemiler rıhtımlara ayrılık boşaltıyor bugünlerde
istanbul bir yerlerde yaprak döküyor
**********************************************
bu güz gününde herkese yepyeni bir tanrı düşerken
bizim payımıza çok kullanılmış bir tanrı düşüyor
şimdi bu tanrıyı alsak götürsek
sisli bir kent ikindisinde
yedirsek içirsek elini yüzünü yıkasak
ikametgah ilmuhaberi istesek mahalle muhtarından
yalnızlığımızı yasallaştırsak
sonra tanrımızı götürüp bağışlasak
tanrı sevenler vakfına
bütün geliri size aittir desek
biz yalnızız yaralıyız henüz çocuğuz
kendi sularımızda çırpınıyoruz
bu tanrı bize fazla desek
******************************************************
hayatta herkesin mutlaka
bir sarayburnu aile çaybahçesi varsa
hayatta herkesin mutlaka bir istanbulu varsa
hayatta herkesin mutlaka bir tanrısı varsa
ve biz tanrısız kaldığımıza göre
sen benimle mi gelirsin
ben sen de mi kalırım
bunu bırakalım şu geçip giden bulutlar düşünsün', 'sarayburnu aile çaybahçesindeki bir güz öğlesi sen ben ve adını bile bilmediğimiz bir istanbul oturmuş konuşuyoruz her şeyden senin ellerin ...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih_bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":62}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİZDÜŞÜM', 'gi-zdusum-kaan-i-nce-wtv65', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boşlukta kemiklerin kanattığı karanlık: Sürekli,
geceye bölünen saatlerin asıldığı yer. Kıyı boyunca
çalınan sabah: Esrik tin. Sehpada unuttum başımı, us yitik.
Divansızların bembeyaz ayetleri gibi peşin hüküm giydik.
Gözlerim deniziğnesi.
Kırıl benliğimin benli gözenekleri
İçinde, sürgünlerin gizli sessizliği.
Alnıma dayarım güz görümlük ömrümü, seherin cılız eliyle.
Uzaktaki vahşi güle hüzün kokarım. Ve ölüm ardıma leke
düşer, gözlerimden çekilen sıcaklık korkuluk yüzümde
soğur soğur, iki kaş arasında yenilir kendine uzun yol.
Çiçek tüter düşler karanlığı kısıp pencerede
gök uçurtma çeker yıldız çölüne
Bir ışık örtüsü açılacak göğe, acılaşan gecede; suya ateş
düşüp kirpiklerime gömülecek, yüzüme sıkışmış erguvan
ölüleri. Dilenci kızlara serpinti yağmurun kırık sesi.
Ay batışı gözlere iki ezgi gibi hüzün çökerim, tetikte
yalnız kalan gölgemle. Sıkıntımın yıldız sefası, n''olur
kapatma kollarını, sakalıma basma sabah. Denk cepheli
çalışmalar ederi kadar başlık paramız, asmayın bizi.
Güvencin uçuşu, alabildiğine rüzgâr;
gez arpacık göz tetikte.
Ölüm açmazda bekleyen kuş seslerine sağanak: Bakire
umutlar. Görünmez viranlığım. Çiğ damlacıkları...
Soluğunda sevişen fesleğenlerin, üç kulaç kurşuni sudan
gözlerini saran kokusu; sendeleyen hoş bir yaşam,
inanç yüklü gülüşlerde. Gecenin sararmış mühründe billurlaşan
sessizliğe dolunay doğarım.
Düş artık yakamdan
güneş kırıklarına dadanan sevda.', 'Boşlukta kemiklerin kanattığı karanlık: Sürekli, geceye bölünen saatlerin asıldığı yer. Kıyı boyunca çalınan sabah: Esrik tin. Sehpada unutt...', ARRAY['Türk Edebiyatı','Şiir','Kaan İnce']::text[], 8.5, '{"poet":"Kaan İnce","poet_slug":"kaan_ince","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZDÜR', 'guzdur-nevzat-celi-k-780od', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güzdür
yapraklar
ayağa
düştüğünde
ve kuştur
göçmen
gökyüzü
güzdür
göçmez
kalır sızısı
ellerimin
güzdür
çünkü
anımsanır
tarihi
bütün
yenilgilerin
güzdür
ve kürttür
bir
yıldır
sarı
esmer
güzdür
demek ki
söylemeli
güzde
göçeni
ve göçmeyeni
güzdür
her çiçek
kendi
dağınca
alsın
rengini
büyüsün
her çocuk
kendi
dilince
Kasım - Aralık 1989', 'güzdür yapraklar ayağa düştüğünde ve kuştur göçmen gökyüzü güzdür göçmez kalır sızısı ellerimin güzdür çünkü anımsanır tarihi bütün yenilgil...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çeli̇k']::text[], 8.5, '{"poet":"Nevzat Çeli̇k","poet_slug":"nevzat_celik","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZEL AYDINLIK', 'guzel-aydinlik-necati-cumali-nlyib', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akdeniz göklerinden
Köpüklerden, limon çiçeklerinden
Gözlerimde kalan
Güzel aydınlık
-Nesrin''i bir defa öptüm
Beyaz badanalı odam
Annemin yüzüne, soframıza
Gençlik hülyalarıma düşen
Güzel aydınlık
-Ümitsiz kaldıkça seni düşündüm
Biz fakirdik ama iyi insanlardık
Bolluk yıllarında da
Felâket günlerinde de
Seni yanı başımda gördüm
Güzel aydınlık
Tatlı aydınlık', 'Akdeniz göklerinden Köpüklerden, limon çiçeklerinden Gözlerimde kalan Güzel aydınlık -Nesrin''i bir defa öptüm Beyaz badanalı odam Annemin yü...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZEL GEMİ', 'guzel-gemi-charles-baudelaire-ck8nt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey güzeller güzeli, sana demem o ki,
Binbir ışıkla renk bezemiş gençliğini;
Çizmek isterim resmini tez,
Kucak kucağadır orada ilkyaz ve güz.
Andırır havada savrulan eteklerin,
O ince, upuzun, güzel gemilerin
Vuruşunu açığa, uzak;
Ardından bir uyumun, bezgince, yumuşak.
Üstünde boynunun, omuzlarının, dimdik,
Yükselir başın bir alımla görülmedik;
Taçla süslü bir bakış soğuk,
Yürür gidersin yolunda sen, göksel çocuk.
Ey güzeller güzeli, sana demem o ki,
Binbir ışıkla renk bezemiş gençliğini;
Çizmek isterim resmini tez,
Kucak kucağadır orada ilkyaz ve güz.
Göğsün ki başlar ve yuvarlaklaşır gittikçe,
Göğsün ki görülmedik en eşsiz çekmece,
Aydınlık ve yuvarlak bir düş,
İki kalkan onlar, şimşekler vurmuş;
O çıldırtan göğsün süslü pembe güllerle,
Saklandığı gizlerin, dolu nelerle,
Eskimiş şaraplar ve ıtır,
Orada duymak ve düşünmek sayıklamaktır.
Andırır havada savrulan eteklerin,
O ince, upuzun, güzel gemilerin
Vuruşunu açığa uzak
Ardından bir uyumun, bezgince, yumuşak.
O soylu bacakların senin avlamakta,
Çılgınca istekleri, etekler ardında,
Aranan özsuyudur aşkın,
Süzülmüş tortulardan karanlıkların.
Kolların, yeni yetme erkekleri saran,
Başka mı ki uzun ve parlak yılanlardan,
Sarar âşığını sımsıkı,
Hep sende duracak o iz, çıkartma tıpkı.
Üstünde boynunun, omuzlarının, dimdik,
Yükselir başın bir alımla görülmedik,
Taçla süslü bir bakış soğuk,
Yürür gidersin yolunda sen, göksel çocuk.
Charles  BAUDELAIRE', 'Ey güzeller güzeli, sana demem o ki, Binbir ışıkla renk bezemiş gençliğini; Çizmek isterim resmini tez, Kucak kucağadır orada ilkyaz ve güz....', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":43}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZEL HAVALAR', 'guzel-havalar-orhan-veli-0eqv5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni bu güzel havalar mahvetti,
Böyle havada istifa ettim
Evkaftaki memuriyetimden.
Tütüne böyle havada alıştım,
Böyle havada aşık oldum;
Eve ekmekle tuz götürmeyi
Böyle havalarda unuttum;
Şiir yazma hastalığım
Hep böyle havalarda nüksetti;
Beni bu güzel havalar mahvetti.', 'Beni bu güzel havalar mahvetti, Böyle havada istifa ettim Evkaftaki memuriyetimden. Tütüne böyle havada alıştım, Böyle havada aşık oldum; Ev...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZEL IRMAK', 'guzel-irmak-i-lhan-berk-ul9yv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçüğüm, bu senin sesin, güzel ırmak
Önce rüzgârın öptüğü, sonra benim öptüğüm
Bu bitmemiş şiirler senin ayakbileklerin
Soluğun, kokun, karnın, gölgeli gözlerin
Bu böyle çözülü göğsün, enine boyuna dudakların
Sabahlara kadar ki büyük gözlerin böyle
Bu dal gibiliğin, saçların, kırmızı ağzın
Bu üstünde onca seviştiğimiz yatak sonra
Sonra bu benim anı artığı eski yüzüm
Tüylerin, tay boynun, küçücük çocuk ellerin
Böyle yukarıdan aşağı gidiyorum seni
Karışıyor, korkunç, ellerimiz ayaklarımız
Güzel Irmak', 'Küçüğüm, bu senin sesin, güzel ırmak Önce rüzgârın öptüğü, sonra benim öptüğüm Bu bitmemiş şiirler senin ayakbileklerin Soluğun, kokun, karn...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZEL ÜLKE', 'guzel-ulke-osman-namdar-qtfmh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağlarına hazırlanan bir gerilladır kalbim
azar azar büyüyen bir isyan ateşindeysem
unuturum serseriliklerimi, büyürüm.
Biz burada yatar idik, orada kan akardı
susar mıydı zaman amansız kurum ve
is bulaşırken ellere, sis içinde.
Bir yerlere üşürdüm içimde
ağlardım
yüzümle, bedenimle,
dağlarını hazırlayan bir gerilladır kalbim
vişne çürüğü bir dudak içinse.
Usulca öpülecek bir omuzsa omzun
silah taşıyacak bir omuz da olabilir bence
örselenmiş bir yara varsa, kalbim kanamak üzredir
herkes ayrı bir nehri geçse de
varılacak ülke hep aynı ülke diyedir,
çekilen
Eşkâli belirlenmiş bir gerillanın ayak izleri
ipince bir yağmur sesinde. adresim belli
durmuş gibiyse de çarpıyor kalbim
o güzel ülkeyse
kalbimde.', 'Dağlarına hazırlanan bir gerilladır kalbim azar azar büyüyen bir isyan ateşindeysem unuturum serseriliklerimi, büyürüm. Biz burada yatar idi...', ARRAY['Türk Edebiyatı','Şiir','Osman Namdar']::text[], 8.5, '{"poet":"Osman Namdar","poet_slug":"osman_namdar","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZEL, NE GÜZEL OLMUŞSUN', 'guzel-ne-guzel-olmussun-karacaoglan-yl6y1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güzel, ne güzel olmuşsun
Görülmeyi, görülmeyi
Siyah zülfün halkalanmış
Örülmeyi örülmeyi
Bahçende gülün güllenmiş
Şeyda bülbülün dillenmiş
Koynunda memen kirlenmiş
Emilmeyi emilmeyi
Mendilin yudum, arıttım
Gülün dalında kuruttum
İsmin ne idi unuttum
Sorulmayı sorulmayı
Seğirttim ardından yettim
Eğildim yüzünden öptüm
Adın bilirdim unuttum
Çağırmayı çağırmayı
Benim yârim bana küsmüş
Zülfünü gerdana dökmüş
Muhabbeti benden kesmiş
Sevilmeyi sevilmeyi
Çağır Karac''oğlan çağır
Taş düştüğü yerde ağır
Yiğit sevdiğinden soğur
Sarılmayı sarılmayı', 'Güzel, ne güzel olmuşsun Görülmeyi, görülmeyi Siyah zülfün halkalanmış Örülmeyi örülmeyi Bahçende gülün güllenmiş Şeyda bülbülün dillenmiş K...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZELLEME', 'guzelleme-ozcan-yalim-jp80u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aramıza gül girdi
Güvercin geçti aramızdan
Sen ilkyazla gelen oğlak
Bir nabız gibi sıçrayarak
Uç yapraklarısın çay dalımın
Soğumayan külü kış mangalımın
İnce tüten duman boylum
Güvercin taklalım buğday soylum
Kim açardı ormanımda gözlerinden başka
Bir sürümlük yer - yalıtılmamış aşka
Aramıza gül girdi bikez - çıkmaz
Güvercin geçti aramızdan', 'Aramıza gül girdi Güvercin geçti aramızdan Sen ilkyazla gelen oğlak Bir nabız gibi sıçrayarak Uç yapraklarısın çay dalımın Soğumayan külü kı...', ARRAY['Türk Edebiyatı','Şiir','Özcan Yalim']::text[], 8.5, '{"poet":"Özcan Yalim","poet_slug":"ozcan_yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZELLİĞİN ON PAR''ETMEZ', 'guzelli-gi-n-on-par-etmez-asik-veysel-satiroglu-lf1w1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzelliğin on par''etmez
Şu bendeki aşk olmasa
Eğlenecek yer bulaman
Gönlümdeki köşk olmasa
Tâbirin sığmaz kaleme
Derdin dermandır yâreme
İsmin yayılmaz âleme
Âşıklarda meşk olmasa
Kim okurdu kim yazardı
Bu düğümü kim çözerdi
Koyun kurt ile gezerdi
Fikir başka başk''olmasa
Güzel yüzün görülmezdi
Bu şak bende dirilmezdi
Güle kıymet verilmezdi
Âşık ve maşuk olmasa
Senden aldım bu feryâdı
Bu imiş dünyanın tadı
Anılmazdı Veysel adı
O sana âşık olmasa', 'Güzelliğin on par''etmez Şu bendeki aşk olmasa Eğlenecek yer bulaman Gönlümdeki köşk olmasa Tâbirin sığmaz kaleme Derdin dermandır yâreme İsm...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatiroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatiroğlu","poet_slug":"asik_veysel","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİZLİ SEVDA', 'gi-zli-sevda-behcet-necati-gi-l-vuur6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani bir sevgilin vardı
Yedi sekiz sene önce,
Dün yolda rastladım
Sevindi beni görünce.
Sokakta ayaküstü
Konuştuk ordan burdan,
Evlenmiş, çocukları olmuş
Bir kız, bir oğlan.
Seni sordu
Hiç değişmedi, dedim,
Bildiğin gibi...
Anlıyordu.
Mesutmuş, kocasını seviyormuş,
Kendilerininmiş evleri..
Bir suçlu gibi ezik,
Sana selâm söyledi.', 'Hani bir sevgilin vardı Yedi sekiz sene önce, Dün yolda rastladım Sevindi beni görünce. Sokakta ayaküstü Konuştuk ordan burdan, Evlenmiş, ço...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necati̇gi̇l']::text[], 8.5, '{"poet":"Behçet Necati̇gi̇l","poet_slug":"behcet_necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİM MAVİ', 'gozleri-m-mavi-melih-cevdet-anday-glofn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimden çıkıyorsun
Sokağa
Mavi mavi.', 'Gözlerimden çıkıyorsun Sokağa Mavi mavi....', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİM', 'gozleri-m-orhan-veli-ilbol', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerim,
Gözlerim nerde?
Şeytan aldı, götürdü;
Satamadan getirdi.
Gözlerim,
Gözlerim nerde?', 'Gözlerim, Gözlerim nerde? Şeytan aldı, götürdü; Satamadan getirdi. Gözlerim, Gözlerim nerde?...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİN BİR ÇİFT TURNA', 'gozleri-n-bi-r-ci-ft-turna-hamdi-ozyurt-sde2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'karanlık bir nehir akar gider kederli
kulaklarımda yetim çakal sesleri kalır
yıldızlar bile iğreti gökyüzünde
tenimde eriyip dökülen ayın izi kalır
bir düşü örseler gibi uyanıyorum
seni buluyorum çöllerin ceylan kızı
bütün kollarımla kucaklasam diyorum...
öyle kanıyorum ki kasığımdan
fırat hiç kalır
akıttığım kana acımıyorum asla
ama sen sürmelenip gidiyorsun ya
bende kara ayıp, bende ağır utanç
bende suç kalır
yanıtı kekeme bir sorudur gözlerin
kesik bir başı okşar gibi bakar gözlerin
gözlerin bir çift turna gölden su içer
iki bahar gider seninle, kerbela kalır', 'karanlık bir nehir akar gider kederli kulaklarımda yetim çakal sesleri kalır yıldızlar bile iğreti gökyüzünde tenimde eriyip dökülen ayın iz...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Özyurt']::text[], 8.5, '{"poet":"Hamdi Özyurt","poet_slug":"hamdi_ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİN', 'gozleri-n-yasin-erol-3t87g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çok kullanılan bir öğlen sonrasında
doluştu denizin maviliğine
sualtı güzelliğinde gözlerin
çocuklardan daha alımlıydı masumluğu
gözlerin haylaz bir yağmurun el pençe duruşu
hangi uzaklığı denesem
hangi yağmurda sınasam yalnızlığımı
kurulurdu pencereme ıslaklığı seven serçeler gibi
gözlerin ilkbaharın şımarık yaprakları
gözlerin vakitsiz uyanmalarda gördüğüm çocukluğum', 'çok kullanılan bir öğlen sonrasında doluştu denizin maviliğine sualtı güzelliğinde gözlerin çocuklardan daha alımlıydı masumluğu gözlerin ha...', ARRAY['Türk Edebiyatı','Şiir','Yasin Erol']::text[], 8.5, '{"poet":"Yasin Erol","poet_slug":"yasin_erol","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİNDE AKİSLER', 'gozleri-nde-aki-sler-rifat-ilgaz-uap8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir nağme var ufukların sesinden...
Sıyrılsam vücudumun bir gün çerçevesinden
Damla damla karışsam çamların kokusuna.
Yorgun kartallar gibi bir sabah dönsem geri
Martılara bıraksam lacivert enginleri
Sonra dalsam dizinde bir bahar uykusuna.
İklimleri çevirse genişleyen hududum
İçsem bakışlarından geceyi yudum yudum
Damla damla erisem o ılık gözlerinde.
Gel, şimdi önümüzde alevlensin ufuklar
Derin bakışlarına dizinsin sonsuzluklar
Kendini seyredeyim karanlık gözlerinde.', 'İçimde bir nağme var ufukların sesinden... Sıyrılsam vücudumun bir gün çerçevesinden Damla damla karışsam çamların kokusuna. Yorgun kartalla...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİNDE DURULUŞUM', 'gozleri-nde-durulusum-yusuf-altunel-wbk61', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sevgim
senin eksilmez parçan unutma
yitirilmişlikler yitir eksilmelerinde
ayrılıklar birleştirir uzaklıkları canım
yabancı diyarlarda hep ufkuna konayım
sevmenin sıcaklığı ısıtsın
seni tüm üşümelerinde
tut
gözlerinde yakaladığım
acemi kelebekleri
kuş gagasında taşıdım sana
sevinçleri yalnızlıklarda biriktirdiğim
aç mavi gökyüzünü öpüşlerine
sevgiler kaldıran kartal olayım
unutma
ilk heyecan genç yüreğimde
ellerin kelepçe
ellerim erken açan çiçek
bakışlarına vurulmuşum
bak gözlerime
gözlerinde durulmuşum.', 'sevgim senin eksilmez parçan unutma yitirilmişlikler yitir eksilmelerinde ayrılıklar birleştirir uzaklıkları canım yabancı diyarlarda hep uf...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZLERİNİN KUYUSU', 'gozleri-ni-n-kuyusu-yusuf-altunel-no8f9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gönlümü
zülfüne bağlayıp
atmışlar
kuyusuna gözlerinin
berduş
çıkrık
aldırmazlığın
döndükçe
göklere çıkar
karanlıklara
düşerim
usandıkça benden
utanmazlığın
gözlerin
bir kuyu,
derin
hırsız gecelerde
sarhoş
içine
düşerim
gözlerin
yakamoz
kayboluşum
aysız gecelerde,
serin
göğüslerinde
fırtına şafakları
içmişim
her sabah okyanus
her sabah deniz
ben yelkenli
çaresiz
umutsuz yolculuklara
sal
vurmuşum
kıyılarına
yelkenlerimi koynuna
al
aşkın
dolanır boynuma
ekseninden yakalamışım
fırdöndü dünya
ama
yokluk,
ama
çaresizlik
sensizlik
ben amip
ben molekül
ben elektron!
...bile değil!
kendi içine
dökülmüş
evren,
yıkılmış duvar,
yanmış hane.
sensizlik
kör ölüm
sensizlik kış
gülüşlerini içmişim
avuçlarımda kor
ayrılıklar yangısı
dudaklarım kanlı
sevgin koynumda
aşk çığlıkları
ateş böcekleri yakmış,
hasretin
ciğerime yataklanmış
gözlerin
bir nehir,
karsuyu,
serin
çavlanlardan
akarken
hırçın
içine
düşerim.', 'gönlümü zülfüne bağlayıp atmışlar kuyusuna gözlerinin berduş çıkrık aldırmazlığın döndükçe göklere çıkar karanlıklara düşerim usandıkça bend...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":79}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZÜNÜ SEVDİĞİM', 'gozunu-sevdi-gi-m-oguz-tansel-ilhdr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dağ etekleri ağarmak üzere
Tepeleri karanlık
Analar çocuk doğurur
Yiğit ola er ola
Ölenleri kime küsmüş
Batmaz bu gemi yağlı boya
Gömü bulur kimi
Nere konar bu kuyruksuz uçurtma
Zehrinden içirirler
Tadından yenmez dünya', 'Dağ etekleri ağarmak üzere Tepeleri karanlık Analar çocuk doğurur Yiğit ola er ola Ölenleri kime küsmüş Batmaz bu gemi yağlı boya Gömü bulur...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZYAŞLARI DA ÇİÇEK AÇAR', 'gozyaslari-da-ci-cek-acar-abdulkadir-bulut-f7nsz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerimi dokunduğum her yerde
Çığlık çığlığa kıvranıyor hayat
Ve ölen arkadaşların giysilerini
Bir kere daha dürüp koyuyor analar
Çamaşır sandıklarına
Gözyaşları da çiçek açar
Bugün yurtyeri olsa da acılara
Kayaların en sarp yerlerindeki
Kırlangıç yuvalarını andıran alnın
Bir gün terli bir gelecek uçuracak
Sabahlardan akşamlara kadar
Gözyaşları da çiçek açar
Ansızın oyuna başlayan çocukların
Sesleri kadar canlı ve huylu
Sevinçleri kadar taze ve acemi
Bir duruş kuşatır seni o zaman
Gözyaşları da çiçek açar
Başını dayadığın ağaç dalı
Bak hafifçe eğildi toprağa doğru
Uyuyan bir çocuğun soluk alışını
Dinler gibi kendini vererek
Yaklaş yüzünü örse de acılar
Boynundan ter boşalan herkese
Gözyaşları da çiçek açar
Yaklaş, yüzünü örse de acılar
Ve nasıl yakalarsa toprağı kök
Suları renk, dalları kiraz
Sen de öyle yakala hayatı
Yürü kol kola canıma değsin
Gözyaşları da çiçek açar', 'Ellerimi dokunduğum her yerde Çığlık çığlığa kıvranıyor hayat Ve ölen arkadaşların giysilerini Bir kere daha dürüp koyuyor analar Çamaşır sa...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Bulut']::text[], 8.5, '{"poet":"Abdülkadir  Bulut","poet_slug":"abdulkadir_bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÖZYAŞLARI VE RÜZGÂR', 'gozyaslari-ve-ruzg-r-tevfik-el-zeyyad-5wvu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1
Bu gözyaşları ne?
Doğudan esen bir rüzgâr ne?
Yakınmalarıyle yüklü
benim yitik insanlarımın
ve yurt özlemiyle boğazlanmış
ve kaskatı
bu rüzgâr ne?
Toprağı ve ufku doyuran
bu sesler ne?
Ovanın umutsuzluğunu döken,
çırılçıplak,
bu sesler ne?
Yüzüme, gözüme,
yüreğime, boğazıma
çiy gibi, kan gibi yayılan,
kölelik kokusunu boşaltan
bu sesler ne?
Bu gözyaşları ne?
Doğudan esen bu rüzgâr ne?
2
Sizi çağırıyorum sizi.
Sıkıyorum ellerinizi.
Kucaklıyorum ayaklarınızın altındaki toprağı
ve diyorum ki:
Yaşamım sizin.
Sunuyorum size
aydınlığını gözlerimin.
Sunuyorum size
sıcaklığını yüreğimin.
Bendeki bu acılar
düşen acılardır
sizin acılarınızdan
benim payıma.
Sizi çağırıyorum sizi.
Sıkıyorum ellerinizi.
Göze almışım yurdum için her şeyi.
Eğilmemişim karşısından hiç kimsenin.
Direnmişim zorbaya karşı,
yetim, yoksul, çıplak ayak,
direnmişim.
Taşımışım kanımı ellerimle.
Düşürmemişim yere bayrağımı.
Bütün otları korumuşum,
mezarlarındaki otları
atalarımın.
Sizi çağırıyorum sizi.
Sıkıyorum ellerinizi.
Tevfik El ZEYYAD', '1 Bu gözyaşları ne? Doğudan esen bir rüzgâr ne? Yakınmalarıyle yüklü benim yitik insanlarımın ve yurt özlemiyle boğazlanmış ve kaskatı bu rü...', ARRAY['Türk Edebiyatı','Şiir','Tevfik El Zeyyad']::text[], 8.5, '{"poet":"Tevfik El Zeyyad","poet_slug":"tevfik_el_zeyyad","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip Şey Yaşamak', 'garip-sey-yasamak-m-ozer-ci-ravoglu-8rkt6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Garip şey yaşamak
Avluda
Zehir dilli insan
Korkunun bunalan gergefi
Tabancanın kayboluşu
Düşüncenin oylumu
Yaratının odağında
Tersine akan irin
Aldatıcı aşklar
Heyecandan ölüyordum
Alkışlara yönelik
Suskun kentin saatleri
Yol vermez
Kırılan gül
Esrik bahçe
Olmazı içeren sahneler
Tükenik birey
Doluyor kalbime
Yeniden atlası örtüyor
İğrenç yaşamak tadında
Kıskıvrak evrene', 'Garip şey yaşamak Avluda Zehir dilli insan Korkunun bunalan gergefi Tabancanın kayboluşu Düşüncenin oylumu Yaratının odağında Tersine akan i...', ARRAY['Türk Edebiyatı','Şiir','M. Özer Ci̇ravoğlu']::text[], 8.5, '{"poet":"M. Özer Ci̇ravoğlu","poet_slug":"m_ozer_ciravoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HİÇ BARIŞ OLMAYACAK', 'hi-c-baris-olmayacak-wystan-hugh-auden-qp7aq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güldüyse de berrak yumuşak bir hava tekrar
İyi şeyler düşünen varlığının ülkesine,
Döndüyse de renkler... boradan sonra değiştin.
Hayır, unutmayacaksın
Bütün umutları birden silen karanlıkta
Düşeceksin diye kâhinlik eden fırtınayı.
Yaşaman gerek yine kendi bildiğinle:
Yabancılar var uzaklarda, senden ayrı düşen,
Mehtapsız yokluklarda hiç duymadığın;
Oysa onlar seni duymuş, seni öğrenmiştir,
Kaç tane, ne cins, bilmediğin varlıklar,
Bir tanesi olsun seni sevmez.
Ne mi yaptın acaba onlara sen?
Hiç mi? Yok, bir cevap değildir ki hiç:
Evet, akıl yoracaksın, düşünmesen olmaz,
Bir şeyler yaptın mı ki yapmışsındır;
Ah şunları bir güldürebilsem diyeceksin,
Dost olmayı onlarla için isteyecek.
Hiç barış olmayacak:
Öyleyse savaş sende; yiğit ol, kullan
Bildiğin her türlü kalleş hileyi,
Vicdan bakımından rahatın yerli yerinde:
Davaları bitmiş - o da davaları varsa -
Onların nefreti sırf nefret içindir artık.
Wystan Hugh AUDEN', 'Güldüyse de berrak yumuşak bir hava tekrar İyi şeyler düşünen varlığının ülkesine, Döndüyse de renkler... boradan sonra değiştin. Hayır, unu...', ARRAY['Türk Edebiyatı','Şiir','Wystan Hugh Auden']::text[], 8.5, '{"poet":"Wystan Hugh Auden","poet_slug":"wystan_hugh_auden","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HİÇ BİTMEYECEK ÇÜNKÜ', 'hi-c-bi-tmeyecek-cunku-uluer-aydogdu-tcrkr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'saçlarını mesnevi''de kurulamışsın
yeryüzü hüzünde diretiyor
sen diretme
emi
içinde bir hasret
ısırdın
kıpkırmızı kırmızıdan da öte bir şiir et
gövden katık edilmiş hayal seslerine
aşk: sedef kakmalı hançer
önce acısını duyacaksın
sonra gelip ciğerine saplanacak
bir çocuk henüz doğmamış
hayalinde büyüteceksin
samansarısı bir imanla
bir kadın
teninden ayrılmamış henüz
ayrılacaksın
ayrılacaksın
ayrılacaksın
ürperiş ve kahkahalar
teninde geceye yatkın annenin
ninniler emiyorsun
içine
kanına
yayılıyor
devler
cinler
periler
göller ahmet haşim içinde
sır
kan
yoldasın
aryalar söylüyorsun ilahiler:
-ben teşrifatçıyım arkamdan gelin
şehirler var bilmediğin gitmediğin tatmadığın
acılar, onları yalayıp yutuyorsun
tam bitti derken
yeniden
hiç bitmeyecek çünkü
aşk
ve
acı
büyüteceksin
kendini
böyle
böyle', 'saçlarını mesnevi''de kurulamışsın yeryüzü hüzünde diretiyor sen diretme emi içinde bir hasret ısırdın kıpkırmızı kırmızıdan da öte bir şiir ...', ARRAY['Türk Edebiyatı','Şiir','Uluer Aydoğdu']::text[], 8.5, '{"poet":"Uluer Aydoğdu","poet_slug":"uluer_aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HİÇ YOLUNUZ ORMANA DÜŞTÜ MÜ', 'hi-c-yolunuz-ormana-dustu-mu-celal-silay-j1oin', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hiç yolunuz ormana düştü mü
gözgöre küçük bir adam
büyük bir ağaçla döğüştü mü
ağaç büyüktü ama tek
adam küçüktü ama çok
dedelerinin dedeleriyle gelmiş utanmadan
elinde balta sırtında nacak
dedelerinin dedeleriyle gelmiş arlanmadan
kolunda bıçkı belinde ip
dedelerinin dedeleriyle gelmiş sıkılmadan
dengisiz bir boy ölçüşmeydi bu
ağaç büyüktü ama tek
adam küçüktü ama çok', 'hiç yolunuz ormana düştü mü gözgöre küçük bir adam büyük bir ağaçla döğüştü mü ağaç büyüktü ama tek adam küçüktü ama çok dedelerinin dedeler...', ARRAY['Türk Edebiyatı','Şiir','Celal Silay']::text[], 8.5, '{"poet":"Celal Silay","poet_slug":"celal_silay","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HABER', 'haber-oguz-tansel-l0ys8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tadını ben bilirim, rengini kimse bilmez,
Duyunca olduğum yere yığılıverdim.
Rengini yitirmeden çiçeklerimiz,
Acı haber tez ulaştı sevdiğim.
Kesiliverdi elim ayağım,
Dudaklarım çatladı acıdan,
Dağ devirir, düz yolda irkilirim,
Alev alev dünya, duman duman.
Ay devrini iki tamamladı ancak,
Ağulu bıçaklar sokuldu yüreğime.
İçim yanar, bağrım dilim dilim
Gitme karanfil saçlım, esmerim gitme.', 'Tadını ben bilirim, rengini kimse bilmez, Duyunca olduğum yere yığılıverdim. Rengini yitirmeden çiçeklerimiz, Acı haber tez ulaştı sevdiğim....', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HACI BEKTAŞ VELİ', 'haci-bektas-veli-i-lhan-berk-jdzzt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir resimde bağdaş kurmuş oturuyor Hacı Bektaş Veli. Evi gibi
yeryüzü.
Bir bulut düşürmüş başını duruyor. Onunla gidip gelen. Uzakta
bellibelirsiz.
Beyaz, uzun kavuğu. Demek ki güneş var.
Kucağına almış bir ceylanı, bir aslanı. Duruyorlar. Üç kişiler.
Hayvanları mı severdi Hacı Bektaş Veli? Bilmiyoruz. Ama açıktı
hep evinin kapısı.
Çizgili mintanı. Yalın. Düz. Ta bileklerine değin uzuyor, uzayıp
orda kalıyor.
Yüzü?  Uzun yüzü.  Sakallı,  virdi  okur gibi de önüne bakıyor.
Delik değil kulağı ve halkasız.
Yanında yeryüzü: Ağaçlar, sular, gök. Her sabah okuduğu.
Atlas', 'Bir resimde bağdaş kurmuş oturuyor Hacı Bektaş Veli. Evi gibi yeryüzü. Bir bulut düşürmüş başını duruyor. Onunla gidip gelen. Uzakta bellibe...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAK ÇALAB''IM', 'hak-calab-im-yunus-emre-j3miu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hak Çalab''ım Hak Çalab''ım
Sencileyin yoğ Çalab''ım
Günahlarımız yarlığagıl
Ey rahmeti çoğ Çalab''ım
Ben aydıram ki ey gani
Nedir bu derdin dermanı
Zinhar esirgeme beni
Aşk oduna yak Çalab''ım
Ne sultan ne baylardasın
Ne köşk ü saraylardasın
Girdin miskinler gönlüne
Edindin durak Çalab''ım
Gel kogıl beni yanayım
Baştan başa uşatayım
Ol sevdiğin Muhammed''e
Olayım çırak Çalab''ım
Kullar senin sen kulların
Günahları çoğ bunların
Uçmağına koy bunları
Binsinler burak Çalab''ım
Ne ilmim var ne taatım
Ne gücüm var ne takatim
Meger senin inayetin
Kıla yüzüm ak Çalab''ım
Yarlığagıl sen Yunus''u
Günahlı kullarınla
Eğer yarlıgamazısan
Key katı firak Çalab''ım', 'Hak Çalab''ım Hak Çalab''ım Sencileyin yoğ Çalab''ım Günahlarımız yarlığagıl Ey rahmeti çoğ Çalab''ım Ben aydıram ki ey gani Nedir bu derdin der...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAK CİHANA DOLUDUR', 'hak-ci-hana-doludur-yunus-emre-zd3cw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hak cihana doludur
Kimseler Hakk''ı bilmez
Onu sen senden iste
O senden ayrı olmaz
Dünyaya inanırsın
Rızka benimdir dersin
Niçin yalan söylersin
Çün sen dediğin olmaz
Ahret yavlak ıraktır
Doğruluk gey yaragtır
Ayrılık sarp firaktır
Hiç varan geri gelmez
Dünyaya gelen göçer
Bir bir şerbetin içer
Bu bir köprüdür geçer
Cahiller onu bilmez
Gelin tanış olalım
İşi kolay kılalım
Sevelim sevilelim
Dünyaya kimse kalmaz
Yunus sözün anlarsan
Ma''nisini dinlersen
Sana bir amel gerek
Bunda kimesne kalmaz', 'Hak cihana doludur Kimseler Hakk''ı bilmez Onu sen senden iste O senden ayrı olmaz Dünyaya inanırsın Rızka benimdir dersin Niçin yalan söyler...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAKK''IN KANDİLİNDE GİZLİ SIR İDİM', 'hakk-in-kandi-li-nde-gi-zli-sir-i-di-m-karacaoglan-8du09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hakk''ın kandilinde gizli sır idim
Anamın beline indirdin beni
Ak mürekkep idim, kızıl kan ettin
Türlü irenklere yandırdın beni
Anamın karnında ben neler gördüm
Yedi derya geçtim, ummana daldım
Dokuz aylık yoldan sefere geldim
Bir kapısız hana indirdin beni
Ben de bildim şu dünyaya geldiğim
Tuzlandım da çapıtlara belendim
Bir zaman da beşiklerde eğlendim
Anamın sütüne kandırdın beni
Beş yaşında akıl geldi başıma
On yaşında gider oldum işime
Varıp ta değince on beş yaşıma
Bir kuru sevdaya yeldirdin beni
On beş yaşadım, yirmiye yol oldu
Otuzunda çevre yanım göl oldu
Kırk yaşadım, hayrım, şerrim bell''oldu
Hayrımı, şerrimi bildirdin bana
Ellisinde yaşım yarısın geçti
Altmışında yoluna yokuş düştü
Yetmişinde biraz tebdilim şaştı
Mertebe mertebe indirdin beni
Sekseninde beratçığım yazıldı
Doksanında kan damarım üzüldü
Yüz yaşında azalarım çözüldü
Bir sabi masuma döndürdün beni
Karac''oğlan der ki, yaktın yandırdın
Ecel şarabın verdin kandırdın
Emreyledin Azrail''i gönderdin
Hiç de doğmamışa döndürdün beni', 'Hakk''ın kandilinde gizli sır idim Anamın beline indirdin beni Ak mürekkep idim, kızıl kan ettin Türlü irenklere yandırdın beni Anamın karnın...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HALK RÜZGÂRLARI TAŞIYOR BENİ', 'halk-ruzg-rlari-tasiyor-beni-miguel-hern-ndez-hwf4i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Halk rüzgârları taşıyor beni,
halk rüzgârları götürüyor
ekerek yüreğimi,
yayarak sesimi dört bir yana.
Öküzler, sopa görünce,
alınlarını büzerler
uysal mı uysal:
aslanlarsa kafalarını dikip
cezalandırırlar
kararlı pençeleriyle.
Öküz türünden gelmiyorum ben,
aslanlar yatağı
bir halktanım,
kartallar topluluğundan,
boynuzları dimdik, onurlu
boğalar sürüsündenim.
İspanya topraklarında
hiç çoğalmıyor boğalar.
Kim demiş boyunduruk vurmayı
boğaların boynuna?
Var mı kasırgayı önleyebilen
boyundurukla, halatla?
Hiç görülmüş müdür
yıldırımı tutup bir kafese kapatan?
Sizler, yiğit Asturyalılar,
çakmaktaşından Basklılar,
şen Valensialılar,
derin ruhlu Kastilyalılar,
toprak gibi işlenmişler,
kanat gibi rüzgârlılar;
şimşekten Endülüslüler,
gitarlar arasında doğup
örslerde dövülmüşler,
gözyaşı dökerek sel gibi;
çavdar soyundan Estremaduralılar,
Galiçyalılar, yağmurdan, dinginlikten,
taş gibi Katalonyalılar,
soylu Aragonlar,
dinamitten Mursiyalılar
Leonlular, Navarrolular, açlığın
ustaları, baltanın, terin,
maden ocaklarının efendileri,
kralları ekip biçmenin,
kökler arasında, çalımlı
kökler gibi giden insanlar
yaşamdan ölüme,
hiçlikten hiçliğe doğru;
size boyunduruk vurmayı
istiyor kötü ot adamları,
ama siz onların omuzlarında
kıracaksınız o boyundurukları!
Tanyerini gösteriyor
Öküzlerin alacakaranlığı.
Ahır korkusuyla, sünepelikle
giyimli öküzler ölecek:
kartallar, aslanlar, boğalar
kibirden ölecek,
ama arkalarındaki gök
değişmeyecek, son bulmayacak.
Öküzlerin can çekişmesi
ufacık bir yüzü gösterir,
yiğit bir hayvanın can çekişmesiyse
daha genişletir dünyayı.
Ölürsem başım dimdik
öleyim ben
Ölü, bin kez ölü,
ağzım ayrıkotuna karşı,
dişlerimi sımsıkı tutup
ve çenemi kararlı, dimdik.
Şarkılarla bekliyorum ölümü,
ötüşen bülbüller var
tüfekler üzerinde
tam ortasında savaşın.
Miguel HERNÁNDEZ', 'Halk rüzgârları taşıyor beni, halk rüzgârları götürüyor ekerek yüreğimi, yayarak sesimi dört bir yana. Öküzler, sopa görünce, alınlarını büz...', ARRAY['Türk Edebiyatı','Şiir','Miguel Hernández']::text[], 8.5, '{"poet":"Miguel Hernández","poet_slug":"miguel_hernandez","theme":"Türk Şiiri","is_hero":false,"total_lines":76}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HALK', 'halk-pablo-neruda-qu132', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Halkım ben,
hani şu sayılamayan,
hani şu çok halk.
Soluğumun öyle bir gücü var ki
sessizliği deler geçerim, dinlemem,
filiz verir, boy atarım,
zifiri karanlık demem.
Zulüm, acı, ölüm, şu  bu
bir anda gizlerse de tohumu,
ölmüş gibi görünürse de halk,
döner gelir elbet bir gün nisan ayı,
kavuşur baharına toprak,
kızgın eller dağıtır atar ağır havayı.
Ölümün içinden yeşerir yaşamak.
Pablo NERUDA', 'Halkım ben, hani şu sayılamayan, hani şu çok halk. Soluğumun öyle bir gücü var ki sessizliği deler geçerim, dinlemem, filiz verir, boy atarı...', ARRAY['Türk Edebiyatı','Şiir','Pablo Neruda']::text[], 8.5, '{"poet":"Pablo Neruda","poet_slug":"pablo_neruda","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HALLAC', 'hallac-kagan-kok-7jt6p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yazın derisini yüzdüler
Gövdesini bana gömdüler
Uçuk renkler uçtu dağ dağa küstü
Şimdi bu yaz daha serin her yer', 'Yazın derisini yüzdüler Gövdesini bana gömdüler Uçuk renkler uçtu dağ dağa küstü Şimdi bu yaz daha serin her yer...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAMBURG''DA', 'hamburg-da-wolfgang-borchert-xrk9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hamburg''da gece
başka kentlerde
o tatlı, mavili kadın
Hamburg''da kül renginde;
yağmurda yağışta başını bekler
Tanrıya uzak kalmışların.
Hamburg''da gece
yeri bütün liman meyhaneleri
eğninde ince, hafif bir giysi
çöpçatandır, bir görüntü, sessiz geçer
parklarda, dar sıralar üstünde
başlamışsa sevişmeler, gülüşler.
Hamburg''da gece
aygın baygın şarkılar söyleyemez
bülbül şakımaları içinde;
bilir bize aynı mutluluğu verir,
vapuk düdüklerinin türküsü
limandan şehre vuran seslerde.
Wolfgang  BORCHERT', 'Hamburg''da gece başka kentlerde o tatlı, mavili kadın Hamburg''da kül renginde; yağmurda yağışta başını bekler Tanrıya uzak kalmışların. Hamb...', ARRAY['Türk Edebiyatı','Şiir','Wolfgang  Borchert']::text[], 8.5, '{"poet":"Wolfgang  Borchert","poet_slug":"wolfgang_borchert","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANİ BENİM GENÇLİĞİM', 'hani-beni-m-gencli-gi-m-yusuf-hayaloglu-95y1l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hani benim sevincim nerede;
Bilyelerim, topacım,
Kiraz ağacında yırtılan gömleğim?
Çaldılar çocukluğumu habersiz..
Penceresiz kaldım anne,
Uçurtmam tel örgülere takıldı..
Hani benim gençliğim nerede?
Ne varsa buğusu genzi yakan,
Ekmek gibi, aşk gibi,
Ah, ne varsa güzellikten yana,
Bölüştüm, büyümüştüm.
İçime sığmıyordu insanlar..
Bu ne yaman çelişki anne,
&quot;Kurtlar sofrasına&quot; düştüm..
Hani benim direncim nerede?
Hani benim övüncüm nerede;
Akvaryumum, kanaryam,
Üstüne titrediğim kaktüs çiçeği?
Aldılar kitaplarımı sorgusuz..
Duvarlar konuşmuyor anne,
Ve açık kalmıyor hiçbir kapı..
Hani benim gençliğim nerede?
Daha kapılmamışken rüzgara,
Tatmamışken rakıyı,
Şiire yeni-yeni başlamışken,
Koştum, dağlara koştum;
Daha öpmemişken hiçbir kızı..
Yağmurları biriktir anne,
&quot;Çağ yangınında&quot; tutuştum..
Hani benim bilincim nerede?', 'Hani benim sevincim nerede; Bilyelerim, topacım, Kiraz ağacında yırtılan gömleğim? Çaldılar çocukluğumu habersiz.. Penceresiz kaldım anne, U...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAN DUVARLARI', 'han-duvarlari-faruk-nafiz-camlibel-ozhtf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Osmanzade Hamdi Bey''e-
Yağız atlar kişnedi, meşin kırbaç şakladı,
Bir dakika araba yerinde durakladı.
Neden sonra sarsıldı altımda demir yaylar,
Gözlerimin önünden geçti kervansaraylar...
Gidiyordum, gurbeti gönlümle duya duya,
Ulukışla yolundan Orta Anadolu''ya.
İlk sevgiye benzeyen ilk acı, ilk ayrılık!
Yüreğimin yaktığı ateşle hava ılık,
Gök sarı, toprak sarı, çıplak ağaçlar sarı...
Arkada zincirlenen yüksek Toros Dağları,
Önde uzun bir kışın soldurduğu etekler,
Sonra dönen, dönerken inleyen tekerlekler...
Ellerim takılırken rüzgârların saçına
Asıldı arabamız bir dağın yamacına.
Her tarafta yükseklik, her tarafta ıssızlık,
Yalnız arabacının dudağında bir ıslık!
Bu ıslıkla uzayan, dönen kıvrılan yollar,
Uykuya varmış gibi görünen yılan yollar
Başını kaldırarak boşluğu dinliyordu.
Gökler bulutlanıyor, rüzgâr serinliyordu.
Serpilmeye başladı bir yağmur ince ince.
Son yokuş noktasından düzlüğe çevrilince
Nihayetsiz bir ova ağarttı benzimizi.
Yollar bir şerit gibi ufka bağladı bizi.
Gurbet beni muttasıl çekiyordu kendine.
Yol, hep yol, daima yol... Bitmiyor düzlük yine.
Ne civarda bir köy var, ne bir evin hayali,
Sonunda ademdir diyor insana yolun hali,
Arasıra geçiyor bir atlı, iki yayan.
Bozuk düzen taşların üstünde tıkırdıyan
Tekerlekler yollara bir şeyler anlatıyor,
Uzun yollar bu sesten silkinerek yatıyor...
Kendimi kaptırarak tekerleğin sesine
Uzanmış kalmışım yaylının şiltesine.
Bir sarsıntı... Uyandım uzun süren uykudan;
Geçiyordu araba yola benzer bir sudan.
Karşıda hisar gibi Niğde yükseliyordu,
Sağ taraftan çıngırak sesleri geliyordu:
Ağır ağır önümden geçti deve kervanı,
Bir kenarda göründü beldenin viran hanı.
Alaca bir karanlık sarmadayken her yeri
Atlarımız çözüldü, girdik handan içeri.
Bir deva bulmak için bağrındaki yaraya
Toplanmıştı garipler şimdi kervansaraya.
Bir noktada birleşmiş vatanın dört bucağı,
Gurbet çeken gönüller kuşatmıştı ocağı.
Bir pırıltı gördü mü gözler hemen dalıyor,
Göğüsler çekilerek nefesler daralıyor.
Şişesi is bağlamış bir lambanın ışığı
Her yüzü çiziyordu bir hüzün kırışığı.
Gitgide birer ayet gibi derinleştiler
Yüzlerdeki çizgiler, gözlerdeki cizgiler...
Yatağımın yanında esmer bir duvar vardı,
Üstünde yazılarla hatlar karışmışlardı;
Fani bir iz bırakmış burda yatmışsa kimler,
Aygın baygın maniler, açık saçık resimler...
Uykuya varmak için bu hazin günde, erken,
Kapanmayan gözlerim duvarlarda gezerken
Birdenbire kıpkızıl birkaç satırla yandı;
Bu dört mısra değil, sanki dört damla kandı.
Ben garip çizgilere uğraşırken başbaşa
Raslamıştım duvarda bir şair arkadaşa;
&quot;On yıl var ayrıyım Kınadağı''ndan
Baba ocağından yar kucağından
Bir çiçek dermeden sevgi bağından
Huduttan hududa atılmışım ben&quot;
Altında da bir tarih: Sekiz mart otuz yedi...
Gözüm imza yerinde başka ad görmedi.
Artık bahtın açıktır, uzun etme, arkadaş!
Ne hudut kaldı bugün, ne askerlik, ne savaş;
Araya gitti diye içlenme baharına,
Huduttan götürdüğün şan yetişir yârına!...
Ertesi gün başladı gün doğmadan yolculuk,
Soğuk bir mart sabahı... Buz tutuyor her soluk.
Ufku tutuşturmadan fecrin ilk alevleri
Arkamızda kalıyor şehrin kenar evleri.
Bulutların ardında gün yanmadan sönüyor,
Höyükler bir dağ gibi uzaktan görünüyor...
Yanımızdan geçiyor ağır ağır kervanlar,
Bir derebeyi gibi kurulmuş eski hanlar.
Biz bu sonsuz yollarda varıyoruz, gitgide,
İki dağ ortasında boğulan bir geçide.
Sıkı bir poyraz beni titretirken içimden
Geçidi atlayınca şaşırdım sevincimden:
Ardımda kalan yerler anlaşırken baharla,
Önümüzdeki arazi örtülü şimdi karla.
Bu geçit sanki yazdan kışı ayırıyordu,
Burada son fırtına son dalı kırıyordu...
Yaylımız tüketirken yolları aynı hızla,
Savrulmaya başladı karlar etrafımızda.
Karlar etrafı beyaz bir karanlığa gömdü;
Kar değil, gökyüzünden yağan beyaz ölümdü...
Gönlümde can verirken köye varmak emeli
Arabacı haykırdı &quot;İşte Araplıbeli!&quot;
Tanrı yardımcı olsun gayrı yolda kalana
Biz menzile vararak atları çektik hana.
Bizden evvel buraya inen üç dört arkadaş
Kurmuştular tutuşan ocağa karşı bağdaş.
Çıtırdayan çalılar dört cana can katıyor,
Kimi haydut, kimi kurt masalı anlatıyor...
Gözlerime çökerken ağır uyku sisleri,
Çiçekliyor duvarı ocağın akisleri.
Bu akisle duvarda çizgiler beliriyor,
Kalbime ateş gibi şu satırlar giriyor;
&quot;Gönlümü çekse de yârin hayali
Aşmaya kudretim yetmez cibali
Yolcuyum bir kuru yaprak misali
Rüzgârın önüne katılmışım ben&quot;
Sabahleyin gökyüzü parlak, ufuk açıktı,
Güneşli bir havada yaylımız yola çıktı...
Bu gurbetten gurbete giden yolun üstünde
Ben üç mevsim değişmiş görüyordum üç günde.
Uzun bir yolculuktan sonra İncesu''daydık,
Bir handa, yorgun argın, tatlı bir uykudaydık.
Gün doğarken bir ölüm rüyasıyla uyandım,
Başucumda gördüğüm şu satırlarla yandım!
&quot;Garibim namıma Kerem diyorlar
Aslı''mı el almış haram diyorlar
Hastayım derdime verem diyorlar
Maraşlı Şeyhoğlu Satılmış''ım ben&quot;
Bir kitabe kokusu duyuluyor yazında,
Korkarım, yaya kaldın bu gurbet çıkmazında.
Ey Maraşlı Şeyhoğlu, evliyalar adağı!
Bahtına lanet olsun aşmadınsa bu dağı!
Az değildir, varmadan senin gibi yurduna,
Post verenler yabanın hayduduna kurduna!..
Arabamız tutarken Erciyes''in yolunu:
&quot;Hancı dedim, bildin mi Maraşlı Şeyhoğlu''nu?&quot;
Gözleri uzun uzun burkuldu kaldı bende,
Dedi:
&quot;Hana sağ indi, ölü çıktı geçende!&quot;
Yaşaran gözlerimde her şey artık değişti,
Bizim garip Şeyhoğlu buradan geçmemişti...
Gönlümü Maraşlı''nın yaktı kara haberi.
Aradan yıllar geçti işte o günden beri
Ne zaman yolda bir han rastlasam irkilirim,
Çünkü sizde gizlenen dertleri ben bilirim.
Ey köyleri hududa bağlayan yaşlı yollar,
Dönmeyen yolculara ağlayan yaslı yollar!
Ey garip çizgilerle dolu han duvarları,
Ey hanların gönlümü sızlatan duvarları!..', '-Osmanzade Hamdi Bey''e- Yağız atlar kişnedi, meşin kırbaç şakladı, Bir dakika araba yerinde durakladı. Neden sonra sarsıldı altımda demir ya...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlibel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlibel","poet_slug":"faruk_nafiz_camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":144}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAN YÜ YAZITI', 'han-yu-yaziti-i-lhan-berk-82qb4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Çin erkeni yaşadığım evin üstündeki gök.
Hey, sıkıntının pencereleri! Beyazsakal. Sığınaklara girin!
Benim ülkemin güney sınırına yakın bir deniz sık sık kabarmakta.
Ölüyor musunuz, büyüyorum?
Sabahın kuyruğunda sizi bekliyorum.
İyi dedim az sonra sevgiye girdik. Kırmızı, rüzgârın elleri.
Çou dukası beyaz.
Hey, yağmur! Doğa, hey! Girin sığınaklarınıza!
Baskıyı yazacağım.
Mısırkalyoniğne', 'Bir Çin erkeni yaşadığım evin üstündeki gök. Hey, sıkıntının pencereleri! Beyazsakal. Sığınaklara girin! Benim ülkemin güney sınırına yakın ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAN', 'han-osman-namdar-dj5gr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senin için!
dalların arasından geçen kuşlar akıtır ırmakları;
göllerin titremesi uzun uçuşlarından.
kuşlar için!
içimde biriktirdiğim su, göğe ektiğim darı.
Bakışlardan geriye kalan
yıkık bir handır yüzün
unutulmuş ağustoslardan,
gönençli okyanuslara taşar gövden
yanıp yakılmış sulardan.
benim için!
çiçekler büyüt yıkıntılarında
ben uğrarım zaman zaman.', 'senin için! dalların arasından geçen kuşlar akıtır ırmakları; göllerin titremesi uzun uçuşlarından. kuşlar için! içimde biriktirdiğim su, gö...', ARRAY['Türk Edebiyatı','Şiir','Osman Namdar']::text[], 8.5, '{"poet":"Osman Namdar","poet_slug":"osman_namdar","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANÇER', 'hancer-mihail-lermontov-k81k1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni çelik hançerim,
Parlak ve soğuk arkadaşım.
Bir Gürcü, öç gününde dövdü seni örste,
Özgür Çerkez, kanlı bir savaşa biledi.
Zambak bir el taşıdı seni bana
Ayrılık anında, anmalık olarak;
Ve ilk kez kan değildi üstünden akan
Acının inciden gözyaşlarıydı, parlak.
O kara gözler, dikilen üstüme,
Gizemli bir tasayla doluydular;
Çeliğin gibi senin, titrek bir alevde,
Ansızın bulanıyor, parlıyordular.
Aşkın dilsiz güvencesi ve yol arkadaşımsın sen,
Seni hep örnek olarak göreceğim;
Değişmeyeceğim ben de, ve ruhum hep
Senin gibi sert kalacak, demirden dostum benim.
Mihail LERMONTOV', 'Seviyorum seni çelik hançerim, Parlak ve soğuk arkadaşım. Bir Gürcü, öç gününde dövdü seni örste, Özgür Çerkez, kanlı bir savaşa biledi. Zam...', ARRAY['Türk Edebiyatı','Şiir','Mihail Lermontov']::text[], 8.5, '{"poet":"Mihail Lermontov","poet_slug":"mihail_lermontov","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANÇERLİ TÜRKÜ', 'hancerli-turku-afsar-ti-muci-n-so5z6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nicedir elimde gül dalıydı
Değişti değişti hançer oldu
Baba bunu kendime mi saplasam
Ya da bir gün doğumuna saklasam
Daha gün ortalığa dağılmadan
Al diye çekip vursam mı adamı
Sevince inanmayanı yaşamı paylaşmayanı
Ekmeği ortadan ikiye bölmeyeni
Aşktan döneni savaştan kaçanı
Kapılara nöbetçiler dikeni
Köpeklerin sofrasında besleneni
İnanç alıp satanların hepsini
Baba bu gümüş hançerle vursam mı
Nicedir elimde gül dalıydı
Değişti değişti hançer oldu
Sardı uzayan yansısıyla
Sardı nar çiçeği kırmızısıyla
Bugünden çekip gidecek olanı
Gül dalıydı hançere dönüştü birden baba
Soframızdan aşımızı çalanı
Çekip bu güzel hançerle vursam mı', 'Nicedir elimde gül dalıydı Değişti değişti hançer oldu Baba bunu kendime mi saplasam Ya da bir gün doğumuna saklasam Daha gün ortalığa dağıl...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İHANET', 'i-hanet-selcuk-yamen-wi7k9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zamanı çaldığımız bedenlerimizde
geçmişin düşlerini büyütüyorduk yeniden
Çay içmek için değildi verdiğimiz molalar.
Issız sokaklardan dönüşlerimde
bensiz bulurdum seni
Bensiz yükselmiş olurdu gözlerinde binalar
Bensiz okunmuş akşam şiirleri
Bensiz bırakıldığın akşamların
rakı sofralarında örgütlediğin suç ortaklarının
yatak odalarında boyanıyordun kırmızıya.
Haydut yanaklarında ıslanan geçmişinin
ağıtlarında yitiremediğin korkularına alış
yağmurdan koruyamazsın yolları.
Bu yüzden kırmızıya boyanıyordun...
Bu yüzden aynalardan bakıyordum sana...
ve aynalar olmadan bakamıyordum artık.', 'Zamanı çaldığımız bedenlerimizde geçmişin düşlerini büyütüyorduk yeniden Çay içmek için değildi verdiğimiz molalar. Issız sokaklardan dönüşl...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yamen']::text[], 8.5, '{"poet":"Selçuk Yamen","poet_slug":"selcuk_yamen","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANGİ GÜNÜN YÜZYILI', 'hangi-gunun-yuzyili-adnan-yucel-6rks9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sancısını yaşıyorsun kaç zamandır
Yeni bir güne sevinçle başlamanın
Yoluna ışık tutan sözcükler
Var mı o günün ışıltılı kanatlarında
Rüzgâra dost olan soluklar var mı
Altını çize çize soruyorsun nedense
Ki hep aldatmış olduğun kendine
Adın çoktan çocuğa çıkmış oysa
Çoktan anlaşılmaz olmuşsun
Şu güzel ömrün tam ortasında
Kuşları sora sora düşen yapraklarda
Ey çılgın
Kanadı kırık her kuşa
Kanat olmaktan yorulmuşsun
Bulutları çarpışa çarpışa yorgun
Bir gökyüzüdür artık gülüşün', 'Sancısını yaşıyorsun kaç zamandır Yeni bir güne sevinçle başlamanın Yoluna ışık tutan sözcükler Var mı o günün ışıltılı kanatlarında Rüzgâra...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANGİ SAATLERDE', 'hangi-saatlerde-oktay-ri-fat-horozcu-abrhj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi saatlerde ve nasıl, ben de bilmem!
Birden, çözülüverir şifresi kilidin
Ve yüzün oturur gözlerimin yivine,
Öpüşür dalgın, tıpatıp erkekle dişi.
Kavaklar sallanır yol boyunda, ay doğar,
Savrulur kanatlı tohumlarım havada,
Yıldızı tüylenir gecemin, sonra kişner,
Büyük dört ayakta beyazlık ve akıtma.
Alsam gitsem seni yataklara! Hey benim
Balta girmemiş ormanlarım, mor dağlarım!
Hangi saatlerde ve nasıl ben de bilmem!
Budarım umutlara sarkan kollarımı.
Ay kızarır ve batar. Yontma taşlarımı
Kaldırıp şileplere, rüzgârlı kıyıda,
Bir mamut iskeleti hızıyla maçuna,
Dağ gibi bulutların öfkesi altında.', 'Hangi saatlerde ve nasıl, ben de bilmem! Birden, çözülüverir şifresi kilidin Ve yüzün oturur gözlerimin yivine, Öpüşür dalgın, tıpatıp erkek...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HANIMELİ', 'hanimeli-arzu-aslan-xlnt4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çaresizliğim ertelenebilir hanımeli
yardım et
bu en berbat anında aşkın
bu artık kanser
yüzünde gözleri olmayan ölümün
önden görünüşüdür
al dizginlerini eline içimden geç
tohumluk sözcükler dersem
en büyük acılarımı kulisten izlesem
eski bir tanıdık uygunsuzluğu
bu en berbat anında aşkın
köprücük kemiklerinde sızlayan şimdi
o konuştukça yüzün gözün kül içinde
murdar eder tutukluğunu
şenliğimdi
kesik bir el gibi yabancılaşan
baykuş uçuşuyla küpeli sabahlara geçerdik
küçük ayrılıklarla zembereklerimizi denerdik
unutkanlığım hoşgörülebilir hanımeli
bu en berbat anında aşkın
bu insan olma tavında
yalnızlığım savuşmuyor söz yordamıyla,
onca gayretli hedefsen
attığını vurur şarkılar
utana sıkıla içlensem
kimse suçlu değil
ben özellikle masumum
bu en berbat anında aşkın
bu çürük çarık öğüt mezatında
gülücüklü bir ad arıyorum pişmanlığıma', 'çaresizliğim ertelenebilir hanımeli yardım et bu en berbat anında aşkın bu artık kanser yüzünde gözleri olmayan ölümün önden görünüşüdür al ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Aslan']::text[], 8.5, '{"poet":"Arzu Aslan","poet_slug":"arzu_aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAPİSHANE ŞARKISI -1-', 'hapi-shane-sarkisi-1-sabahattin-ali-qguyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göklerde kartal gibiydim.
Kanatlarımdan vuruldum;
Mor çiçekli dal gibiydim,
Bahar vaktinde kırıldım.
Yar olmadı bana devir,
Her günüm bir başka zehir;
Hapishanelerde demir
Parmaklıklara sarıldım.
Coşkundum pınarlar gibi,
Sarhoştum rüzgarlar gibi;
İhtiyar çınarlar gibi
Bir gün içinde devrildim.
Ekmeğim bahtımdan katı,
Bahtım düşmanımdan kötü;
Böyle kepaze hayatı
Sürüklemekten yoruldum.
Kimseye soramadığım,
Doyunca saramadığım,
Görmesem duramadığım
Nazlı yarimden ayrıldım.', 'Göklerde kartal gibiydim. Kanatlarımdan vuruldum; Mor çiçekli dal gibiydim, Bahar vaktinde kırıldım. Yar olmadı bana devir, Her günüm bir ba...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali̇']::text[], 8.5, '{"poet":"Sabahattin Ali̇","poet_slug":"sabahattin_ali","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAPİSHANE ŞARKISI -3-', 'hapi-shane-sarkisi-3-sabahattin-ali-lfbst', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Burda çiçekler açmıyor,
Kuşlar süzülüp uçmuyor,
Yıldızlar ışık saçmıyor,
Geçmiyor günler, geçmiyor.
Avluda olta vururum;
Kah düşünür, otururum,
Türlü hayaller görürüm;
Geçmiyor günler, geçmiyor.
Gönülde eski sevdalar,
Gözümde dereler, bağlar,
Aynada hayalim ağlar,
Geçmiyor günler, geçmiyor.
Dışarda mevsim baharmış,
Gezip dolaşanlar varmış,
Günler su gibi akarmış...
Geçmiyor günler, geçmiyor.
Yanımda yatan yabancı,
Her sözü zehir gibi acı,
Bütün dertlerin en gücü;
Geçmiyor günler, geçmiyor.', 'Burda çiçekler açmıyor, Kuşlar süzülüp uçmuyor, Yıldızlar ışık saçmıyor, Geçmiyor günler, geçmiyor. Avluda olta vururum; Kah düşünür, oturur...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali̇']::text[], 8.5, '{"poet":"Sabahattin Ali̇","poet_slug":"sabahattin_ali","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAPİSHANE ŞARKISI -5-', 'hapi-shane-sarkisi-5-sabahattin-ali-wf2yi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başın öne eğilmesin
Aldırma gönül, aldırma
Ağladığın duyulmasın,
Aldırma gönül, aldırma
Dışarda deli dalgalar
Gelip duvarları yalar;
Seni bu sesler oyalar,
Aldırma gönül, aldırma
Görmesen bile denizi,
Yukarıya çevir gözü:
Deniz gibidir gökyüzü;
Aldırma gönül, aldırma
Dertlerin kalkınca şaha
Bir küfür yolla Allaha
Görecek günler var daha;
Aldırma gönül, aldırma
Kurşun ata ata biter
Yollar gide gide biter;
Ceza yata yata biter;
Aldırma gönül, aldırma', 'Başın öne eğilmesin Aldırma gönül, aldırma Ağladığın duyulmasın, Aldırma gönül, aldırma Dışarda deli dalgalar Gelip duvarları yalar; Seni bu...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali̇']::text[], 8.5, '{"poet":"Sabahattin Ali̇","poet_slug":"sabahattin_ali","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAPİSHANEDE BİR AKŞAMÜSTÜ', 'hapi-shanede-bi-r-aksamustu-faiz-ahmed-fai-z-42s4m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adım adım iniyor gece
Takımyıldızların salınan merdivenlerinden;
Yakın, şefkatle fısıldayan bir ses gibi yakın
Esiyor hafif bir rüzgâr;
Avludaki ağaçlar,
Boynu bükük mahkûmlar,
Kayboluyor rüzgârın fırıl fırıl eteğinde.
Ay ışığının ince parmakları merhametle
Işıldıyor çatının tepesinde;
Toza karıştı yıldızların avizesi.
Göğün mavisi akkorlaştı.
Kurşuni gölgeler kaplıyor yeşil kuytuları
Tereddüt içinde hasretin
Acıyla girdaplanışı gibi beyinde.
Bir düşünce dolanıp duruyor yüreğimde-
Öyle bir bengi sudur ki hayat bu anda
Ona zehirlerini katan tiranlar
Ne bugün ne yarın, asla kazamayacaklar.
Ne çıkar aşkın taht odasını aydınlatan
Mumu söndürseler de? Güçlüyseler
Ayı söndürsünler, görelim hele.
Faiz Ahmed FAİZ', 'Adım adım iniyor gece Takımyıldızların salınan merdivenlerinden; Yakın, şefkatle fısıldayan bir ses gibi yakın Esiyor hafif bir rüzgâr; Avlu...', ARRAY['Türk Edebiyatı','Şiir','Faiz Ahmed Fai̇z']::text[], 8.5, '{"poet":"Faiz Ahmed Fai̇z","poet_slug":"faiz_ahmed_faiz","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAPİSHANEDEKİ ARKADAŞIMA', 'hapi-shanedeki-arkadasima-nihat-behram-f4mhl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ULAŞTIRILAMAYAN BİR NOT
Sevgili kardeşim:
Belli ki
gömleğinin yakasında kuruyan
ter
bu bahar
tarlaların tozunu taşımayacak
kasketinin gölgesini
küçük üzümleri andıran gözlerini
bir selvi yaprağı gibi
korumayacak
Sana
tomurcuklu bir dal yollamıştım
bir kaç kitap
bir kilo portakal
Ve
&quot;dostları özlemle
kucaklamayı unutma&quot; dizesini
almadılar
geçen yaz-hatırlarsın-
ilk meyvasını veren bir fidandan
ham zerdaliler toplayıp
uzun yollar boyunca
esaret ve zafer üstüne
marşlar söylemiştik
yaşadığın günlerin hesabını
soranlara
bildiğin marşları söylemeyi
unutma', 'ULAŞTIRILAMAYAN BİR NOT Sevgili kardeşim: Belli ki gömleğinin yakasında kuruyan ter bu bahar tarlaların tozunu taşımayacak kasketinin gölges...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HARÇ ÇEKEN İŞÇİLER', 'harc-ceken-i-sci-ler-oktay-ri-fat-horozcu-b193b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Harcını çekiyorlardı yapının,
kara bir don, belden yukarsı çıplak.
Yıldızlarını çekiyorlardı evin omuzlarında,
pencereden görünecek dallarını, komşunun yarısını,
ağaçların arasında kaybolan yolunu,
durulacak yerlerini çekiyorlardı, bütün o noktaları,
aşkı, ki saklanırız çoğu kez sevişmek için,
köşeleri çekiyorlardı, merdiven başını,
mutfağın sofaya vuracak aydınlığını,
bir kızın ölüşünü ansızın
iki kapı arasında, yaz başlangıcı olabilir,
saksılar olabilir, hasekiküpesi, cezayirmenekşeleri,
yalnızlıkları çekiyorlardı, öpüşleri,
karşı çıkışları, susmalara karışan böğürtleni,
bir denizden uzaklara çıldırmanın sevincini,
bükük beli, koltuktakini, sofada yürüyeni,
kaynayan çaydanlığın mutfağa diktiği
o kokulu ağacı, kabuklarını döktükçe büyüyen,
semizotunu masada, maydanozu, domatesi,
kaşığa uzanmayan eli ve lokmayı boğazda düğümlenen,
doğacak oğlanı ölmeden önce
bir nisan yağmurunda avucunda güneşle.
Çay soğumasın, bu reçeli seversin sen,
orasını çekiyorlardı işte, tam orasını,
umutların ömrümüzden döküldüğü yeri
ve ev yükseliyordu yavaş yavaş kaderine doğru.
Onlarsa gün batmadan gidecekler.', 'Harcını çekiyorlardı yapının, kara bir don, belden yukarsı çıplak. Yıldızlarını çekiyorlardı evin omuzlarında, pencereden görünecek dalların...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HARAÇ', 'harac-mehmet-taner-fqamm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Ey hiçlik! Bana bir
salgını çağrıştırıyorsun.
Yangınları, dinamiti. Bana bir
cinayeti.)
Çünkü Biri hep bir şey alır geçirdiğim günden
gözümü kamaştıranı
geçeni aklımdan yüzümde bir gülümsemeyle
öpüşümün altında uzanan yüzü alır
Elele ayrılığınla ve silinir gibi
gidince silinir gidersin böylece.
İki korkunun sığmadığı inde
benim eşsiz yalnızlığım kalır
Ben ki utanmışım yıllarca sevmekten beyazı
odalarda aynalardan yitik
dokunulmaz bir gül düşünüp fidanlar içinde
dokunulmaz bir güne ayırmışım
Bunu mırıldanırım içimden bir yerinde kalabalığın
sessizce siyaha sürerim tenhada yanımı', '(Ey hiçlik! Bana bir salgını çağrıştırıyorsun. Yangınları, dinamiti. Bana bir cinayeti.) Çünkü Biri hep bir şey alır geçirdiğim günden gözüm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HARP İÇİNDE', 'harp-i-ci-nde-cahit-kulebi-ifo58', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Babalar evlerine mahçup döndü her akşam
Harp içinde.
Anaların sütü kesildi,
Çocuklar ağladı,
Erkekler askere gitti.
Kadınlar bir deri bir kemik.
Harp içinde kızlar sarardı.
Savaşanlardansa
Ancak bir hatıra kaldı.', 'Babalar evlerine mahçup döndü her akşam Harp içinde. Anaların sütü kesildi, Çocuklar ağladı, Erkekler askere gitti. Kadınlar bir deri bir ke...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi̇']::text[], 8.5, '{"poet":"Cahit Külebi̇","poet_slug":"cahit_kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HARP ÇOCUĞU', 'harp-cocugu-oguz-tansel-jmjzv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Devran değişti çocuğum!
Son savaşta oldu bu kötü işler:
Kiminin göğsü kabardı, kudurdu:
Çoğunun gözü doldu.
Devran değişti çocuğum!
Baba, batan bir gemide öldü:
Bir esir kampında kardeşleri,
Anasını zaten bilmiyordu.
Devran değişti çocuğum!
Ekmek kokulu sevgi nerde?
Masal dünyamız bu mu?
İki gözü iki çeşme.', 'Devran değişti çocuğum! Son savaşta oldu bu kötü işler: Kiminin göğsü kabardı, kudurdu: Çoğunun gözü doldu. Devran değişti çocuğum! Baba, ba...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASAN HÜSEYİN', 'hasan-huseyi-n-hasan-huseyi-n-82saa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tohumlar Tuz İçinde, Hasan HÜSEYİN, Bilgi', 'Tohumlar Tuz İçinde, Hasan HÜSEYİN, Bilgi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyi̇n']::text[], 8.5, '{"poet":"Hasan Hüseyi̇n","poet_slug":"hasan_huseyin_korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":3}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASRETİNİ ÇEKERKEN', 'hasreti-ni-cekerken-soysal-eki-nci-j0bgb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kavuşmanın yerindeyiz tam yerinde sevgilim
ele bakıp bu havayı ellerinle iteleme
ellerimi uzatamam dokunamam parmağının ucuna
iki parmaklığın arası iki kolboyundan çok fazla
yine sen gel yine sen gel yine sen gel
omzum olsun başına aradaki paslı engel
açtığını göreyim saçlarını sardığın çiçeklerin
doyumsuzluğunu yaşat, hasretimiz adına birbirimizi uzaktan sevmenin
nevrimi döndürüyor geceme sızdırdığın sevi iksirleri
tırmanıyorum kızgın çöldağlarını
ve tarıyorum kum bayırlarının bakır saçlarını
serabımda, tadılmamış şarapların kurulduğu üzüm bağları
bir de sen KOPAR BENİ diye sarkan olgunlaşmış asma üzüm salkımı göğsünde
ikircimler birbirini kovalıyor içimde
bu salkım benim için HAVVANIN YASAK ELMA''sı
ve benim gücüm yasal mı bu yasağı kırmaya
içimdeki mahzenlerin bordo şişeleriyle
bu yasallık yeter miydi seni şarap kurmaya
ayakların sızısı kalçalara vuran karasularına
merhem taşıyan çarıkların manda gönünden olmasıydı
ve karşılığını hasretimizde arayan bir çileyle
katılmasaydın ilkdirilenler arasına kendiliğinden
küller içinde küllenen sevilerini türkülerken
seslerini öptüğüm alfistanlı kızların vaadleri gibi
seni de silerim serimden
nevrimi döndürüyor geceme sızdırdığın sevi iksirleri
ben yükseldikçe gece küçülüyor gözümde
kızıl şafakların kuşluk sütlerini sulayan ıslıkları çalıyorum
ve tarıyorum parmaklarımla kum bayırlarının bakır saçlarını
belki de hiç silinmeyecek içimden
çöl eşkiyalarının hummalı baskınlarında üstümüze düşen gölgeleri
ve belki de bu yüzdendir yüreğimin
çöken barikatların çürük tahtalarını böyle pervasızca yakmaya çalışması
zaman bile yetmiyor durdurmaya
yüreğimin bu yönde sürüp giden havariliğini
bir yandan da diyorum ki
varsın korksunlar o tahtaları o barikatlara çakanlar
varsın dağlansın
ağzımdan çıkan gül dikenlerine habersizce değmiş gibi elleri
sevgilim yine de biz
kavuşmanın yerindeyiz
tam yerinde
ele bakıp bu havayı ellerinle iteleme
Kasım 87', 'kavuşmanın yerindeyiz tam yerinde sevgilim ele bakıp bu havayı ellerinle iteleme ellerimi uzatamam dokunamam parmağının ucuna iki parmaklığı...', ARRAY['Türk Edebiyatı','Şiir','Soysal Eki̇nci̇']::text[], 8.5, '{"poet":"Soysal Eki̇nci̇","poet_slug":"soysal_ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":46}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASTA DÜŞTÜM HEY AĞALAR', 'hasta-dustum-hey-agalar-karacaoglan-dh96a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasta düştüm hey ağalar
Halim bilmez dağlar şimdi
Düşman gibi dost karşımda
Zülüflerin bağlar şimdi
Etmedim ahd ü zamanı
Geçti mihnetin zamanı
Yitirdim kaşı kemanı
Gözüm yaşı çağlar şimdi
Del''oldum kanman sözüme
Dost hançer vurdu özüme
O yâr bakmıyor yüzüme
Yas çekecek çağlar şimdi
Balaban uçurdum gölden
Tor şahin kaçırdım koldan
Yazık fırsat gitti elden
Mecnun oldum beyler şimdi
Fırkat oldu yaktı canım
Feryatla geçer zamanım
Yaralandım, akar kanım
Karac''oğlan ağlar şimdi', 'Hasta düştüm hey ağalar Halim bilmez dağlar şimdi Düşman gibi dost karşımda Zülüflerin bağlar şimdi Etmedim ahd ü zamanı Geçti mihnetin zama...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASTALIKTAN SONRA', 'hastaliktan-sonra-behcet-kemal-caglar-4hwvt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akacak inci yaş zümrüt oluğa
Gözlerin meyvada elin ateşte
Yokuş çıkar gibi soluk soluğa
Başın karlı dağda bağrın güneşte.
Hırçın fırtınadan örselenmeden dal
Ateş yanar gibi açılan çiçek
Yavrusuna bakan kaplandan uysal
Kaynağa eğilmiş ceylandan ürkek.
Bir büyük çağrının uyup sesine
Dört duvardan göğü soruyor sesin
Süzgünsün haddeden geçmişçesine
İmbikten çekilmiş gibi tazesin.', 'Akacak inci yaş zümrüt oluğa Gözlerin meyvada elin ateşte Yokuş çıkar gibi soluk soluğa Başın karlı dağda bağrın güneşte. Hırçın fırtınadan ...', ARRAY['Türk Edebiyatı','Şiir','Behçet Kemal Çağlar']::text[], 8.5, '{"poet":"Behçet Kemal Çağlar","poet_slug":"behcet_kemal_caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HASTİR LAN', 'hasti-r-lan-enver-gokce-kg9hd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben gider oldum
kardaşlar.
Ve de
kız kardaşlar,
Ben gider oldum,
Gayri
Haram bana
Bu toprak damlar
Bu ağaçlar,
Bu taşlar bana.
Apat dediğin
Şişirilmiş oto lastiği
Ve bir kaç
Tahtadan ibaret
Bir saldır.
Suda yüzer.
Oğul, uşak, bir de karım
Kurt bana
Hastir çeker
Kuş bana
Yılan bana
Hastir çeker
Çiyan bana
Lan kardaş
Bu nasıl yara
Kanar heryerimden.
Döğülmüşüm
Süğülmüşüm
Koğulmuş.
Siktir çekilmişim yani
Kendi öz yurdumda.
Bir meri keklik gibi
Çeker giderim.', 'Ben gider oldum kardaşlar. Ve de kız kardaşlar, Ben gider oldum, Gayri Haram bana Bu toprak damlar Bu ağaçlar, Bu taşlar bana. Apat dediğin ...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver_gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HATİB-İ ŞEHİR''İN TİFÜSTEN ÖLÜMÜ', 'hati-b-i-sehi-r-i-n-ti-fusten-olumu-roni-margulies-483sg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tek bir şey istemişti hayatı boyunca Ömer Naci.
Bab-ı âli baskınında fırlayıp askerlerin önüne,
Açıp ağzını bar bar bir bağırması var ki,
Ağzı açık bakakalmıştı Enver Paşa bile:
&quot;Vurun, karşınızdayım işte, öldürün beni.&quot;
Üstüne gider gibiydi ölümün hep böyle.
Tek bir şey istemişti hayatı boyunca Ömer Naci.
Cemiyet Doğu''ya göndermişti onu bir keresinde.
Bir an evvel o taraflarda örgütlenmek gerekliydi.
Hastayken ve beş kuruş bile yokken cebinde,
O koyu istidbat döneminde kalkıp gittiydi.
Van civarında teşkilat kurulmuştu geri geldiğinde.
Tek bir şey istemişti hayatı boyunca Ömer Naci.
Filozof Rıza Tevfik''le bir tartışması destandı dillere,
Paris''teyken her fırsatta Jean Jaures''yi dinlerdi,
Hem Merkez-i Umumi''nin değişmez üyesi, hem de
&quot;Hatib-i şehir, filozof, şair, mütefekkir&quot; idi.
Ancak, şüphesiz, eylem adamıydı her şeyden önce.
Tek bir şey istemişti hayatı boyunca Ömer Naci:
Ölmek - vatan için ve büyük kalabalıklar önünde.
Kerkük''te bir hastanede oysa yapayalnız gitti.
Duyar gibi oluyorum şimdi son sözlerini:
&quot;Demek böyle Allahın belâsı bir yerde,
Ne yapalım, tifüsten ölmek varmış kaderde.&quot;', 'Tek bir şey istemişti hayatı boyunca Ömer Naci. Bab-ı âli baskınında fırlayıp askerlerin önüne, Açıp ağzını bar bar bir bağırması var ki, Ağ...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HATIRA', 'hatira-enis-behic-koryurek-9rlb3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geçsin günler, haftalar,
Aylar, mevsimler, yıllar...
Zaman sanki bir rüzgâr
Ve bir su gibi aksın...
Sen gözlerimde bir renk
Kulaklarımda bir ses
Ve içimde bir nefes
Olarak kalacaksın...', 'Geçsin günler, haftalar, Aylar, mevsimler, yıllar... Zaman sanki bir rüzgâr Ve bir su gibi aksın... Sen gözlerimde bir renk Kulaklarımda bir...', ARRAY['Türk Edebiyatı','Şiir','Enis Behiç Koryürek']::text[], 8.5, '{"poet":"Enis Behiç Koryürek","poet_slug":"enis_behic_koryurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HATIRLAMA', 'hatirlama-ahmet-hamdi-tanpinar-jnopt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen akşamlar kadar büyülü, sıcak,
Rüyalarım kadar sade, güzeldin,
Başbaşa uzandık günlerce ıslak
Çimenlerine yaz bahçelerinin.
Ömrün gecesinde sükun, aydınlık
Boşanan bir seldi avuçlarından,
Bir masal meyvası gibi paylaştık
Mehtabı kırılmış dal uçlarından.', 'Sen akşamlar kadar büyülü, sıcak, Rüyalarım kadar sade, güzeldin, Başbaşa uzandık günlerce ıslak Çimenlerine yaz bahçelerinin. Ömrün gecesin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hamdi Tanpinar']::text[], 8.5, '{"poet":"Ahmet Hamdi Tanpinar","poet_slug":"ahmet_hamdi_tanpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAVA AKININDAN BEŞ DAKİKA SONRA', 'hava-akinindan-bes-daki-ka-sonra-miroslav-holub-lq3cv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pilsen''de,
Yirmi Altıncı İstasyon Yolunda,
üçüncü kata çıktı
yukarıda, evin tek kalan
katında
kapıyı açtı
tüm göğe karşı,
bakakaldı öylece kenarda.
Çünkü burasıydı
dünyanın bittiği yer.
Sonra
kilidi çevirdi iyice
kimse almasın
Yemen yıldızını
Elderaban''ı
mutfağından,
indi aşağı
oturdu, bekledi
ev gene kurulsun
kocası yükselsin küllerden
çocuklarının elleri, ayakları yerlerine dönsün
Sabahleyin buldular onu
bir taş gibi sessiz,
serçeler ellerini gagalıyordu.
Çeviren: Nermin Menemencioğlu', 'Pilsen''de, Yirmi Altıncı İstasyon Yolunda, üçüncü kata çıktı yukarıda, evin tek kalan katında kapıyı açtı tüm göğe karşı, bakakaldı öylece k...', ARRAY['Türk Edebiyatı','Şiir','Miroslav Holub']::text[], 8.5, '{"poet":"Miroslav Holub","poet_slug":"miroslav_holub","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAVUZ', 'havuz-ahmet-hasi-m-x8o1e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akşam yine toplandı derinde...
Cânân gülüyor eski yerinde
Cânân ki gündüzleri gelmez
Akşam görünür havz üzerinde,
Meh-tâb kemer tâze belinde
Üstünde semâ gizli bir örtü
Yıldızlar onun güldür elinde...', 'Akşam yine toplandı derinde... Cânân gülüyor eski yerinde Cânân ki gündüzleri gelmez Akşam görünür havz üzerinde, Meh-tâb kemer tâze belinde...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAL', 'hayal-necip-fazil-kisakurek-sj2v2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam bir ateş duyup etimde
Kadın, kadın diye içimi oydum.
Ruhuma bir serin yer istedim de
Alnımı mermerin üstüne koydum.
Birden karanlıklar sökülüverdi
Odama bir hayal dökülüverdi,
Karşımda gerindi bükülüverdi,
Onu gözlerimle çırılçıplak soydum.
Artık ben ne günah olsa işlerim,
Yumuşacık yastığa geçti dişlerim,
Bir ân kadar sürdü can verişlerim,
Ey kadın, bu akşam sana da doydum.', 'Bu akşam bir ateş duyup etimde Kadın, kadın diye içimi oydum. Ruhuma bir serin yer istedim de Alnımı mermerin üstüne koydum. Birden karanlık...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT BAHÇESİ', 'hayat-bahcesi-ali-cengi-zkan-9w1sx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bahçe tarumar. Ama gözler önüne serilen
Görüntünün sesi mi olmalı sözler? Serçe
Cıvıltıları, çan sesleri, at pislikleri,
Rüzgârın kuru yapraklarda bıraktığı
Hışırtı yapışıyor sanki yirmi yıldır
Kullanılmayan bahçeye, babanın ölümüyle.
Toplumsal arkeoloji mi ırgalayan beni
Tahrik eden, edilen bir leş kargası gibi?
Meraklıyım. Budanmamış güller çılgın
Palmiyelerin kuru dallarının altında,
Kendiliğinden ölen çiçekleri toplanmamış
Zakkumun. Gübre ve çürüyüş. Tohumdaki ev
Kale gibi gözlüyor şimdiki ve geçmişteki
Yaşantıyı: Kız ve erkek çocuklar burada
Denge buldular nilüfer yapraklarında, çember
Çevirmişti büyükler havuzda, sonra fırladı
Resimden haylaz damat ve gelinler. Ama
Onlar bir kez kapıdan girdiler mi
İçeri, gözleri parlardı babanın, ayrıldılar mı
Bir kaptan bakışını giyer, şapkasını geçirir
Sözüne, kimse evde durmak istemezdi
Tanışmamak için gözü dönmüş yalnızlıkla.
Oysa ölümün görevi ne, gelir padişah
Tekillik. Tek, sonra birden aynı
Merdiven basamakları, aynı işçilik, aynı
Anlamı bulunca evin biçeminde, dünya
Ne kadar acı dolu, herkesin kendi
Kefesine uygun dağılan. Acı aynı,
Zevk de, ama kefen ne kadar geniş
İse, ağırlığın ne kadar fazla ise
O kadar götürüyorsun işte öteye.
İstanbul, Heybeliada, Kasım 1996', 'Bahçe tarumar. Ama gözler önüne serilen Görüntünün sesi mi olmalı sözler? Serçe Cıvıltıları, çan sesleri, at pislikleri, Rüzgârın kuru yapra...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT BASMA YARAMA', 'hayat-basma-yarama-umut-taydas-atxkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen beni arama, bana inanma,
yaşıtlarım "ekmeğini eline aldı"
diye anlatılırken,
ben şarabımı aldım,
annem bilmesin
sen de arama,
hayat basma yarama...
hayyam''ı okumadım, kafka''yı tanımam,
sokak çocuğuyum ben,
sabahlara kadar siner,
çekerim;
daha kendimi kendime anlatmayı
bitiremedim ki,
başkalarına anlatayım...
oysa onlar başkalarına anlatarak
bitirdiler kendilerini...
gezdiğimiz yerlerdeyim,
yerlerdeyim,
gideceğim.
ben deniz olsam, bu "kullanan"
şehri
terk ederdim...
30.06.00 - 19:24
sitambol- bejqtağşh', 'sen beni arama, bana inanma, yaşıtlarım "ekmeğini eline aldı" diye anlatılırken, ben şarabımı aldım, annem bilmesin sen de arama, hayat basm...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT BİR GREVDİ SÜREKLİ KIRILAN', 'hayat-bi-r-grevdi-surekli-kirilan-azad-ziya-eren-ku733', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'evrenin bütün kıygıları zenci bir tenin sırtında
patlayan kırbaç gibi balkıdıkça;
sustuk sustuğunuza benzer
biraz fazla sıkarak vücudun dişlilerini
tiner koklayan bir kuşun iki kanat arası uzadık
ağır yalnız ve en yukarıya kadar güvensiz
&quot;kendini anlatmalıdır herkes&quot;
gülümseyişinin rengini kan gülü
anlatacak neyimiz kaldı
söyleyecek kimimiz uzak ve yakın
tuttuk sonu geldi
kavradıkça gelişen kaslarıyla ayrılığın
temmuz uzak solgun bir çocuğun eylülü içerdeydi
şehirler bitirmiştik
yürüyorduk en uzağına zayıf köylerin
safran ve katran aynıydı; dilimizle bilmiştik
büyüyorduk tapınağa doğru: kanayan toprağa
bilinir ki ortadoğu şehrinde
kolayına çıkmaz sokağın en sevileni ölüyse
beyaz bir kolanmışçasına yağar günün bütün yağmurları
giden su kalan toprak olur
turunç kapta açlık gibi kalın örgüsüyle tıkırdar zaman
manastır gülistanında kanayan sabır taşı
kahır köpürmesi çark inlemesi
şafak söker gece diker diye bütün sökükleri
işte öyle sevdim
bağlanacak biri kurulacak sevgi kalmasın
barınaksız son güzellik de utancın kamçısıyla
yaralansın için ışık söndü kör kaldık
yine de mersinler sardı bütün çocuklarımızı
prusya mavisi gök ender rastlanan bir sevgiyle sızdı
ne yazık nefretle uyanmak ve bir o kadar seninle hür
mum ölür aşk kalır şarkı söyleyen cüssesiyle
kaplar beni küçük dudakların
göğsünde yükselir en güzel devrim şiiri
sustuk sustukları gibi
şehir bitti köy kaldık yitik bir savın hâlâ ılık teninde
taşla
tortuyla
ve mızrakla sakat bırakılmış bir ütopyanın
son sözleriydik: hayat bir grevdi sürekli kırılan
birer grevdi gözlerin', 'evrenin bütün kıygıları zenci bir tenin sırtında patlayan kırbaç gibi balkıdıkça; sustuk sustuğunuza benzer biraz fazla sıkarak vücudun dişl...', ARRAY['Türk Edebiyatı','Şiir','Azad Ziya Eren']::text[], 8.5, '{"poet":"Azad Ziya Eren","poet_slug":"azad_ziya_eren","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT HEPİMİZDEN GENİŞ...', 'hayat-hepi-mi-zden-geni-s-metin-m0cmn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HAYAT HEPİMİZDEN GENİŞ
ÖLÜM HER ÖMÜRDEN UZUN
Ben hep gülümseyerek yaşadım dünyayı
Gülümseyerek ölüyorum her gün sizlerle
Baştan kendime basit bir yüz yakıştırdım
Rüzgârıyla haşır neşir çıplak bir tepe
Bir gök olsun istedim yüzümde, mavi, bulutsuz
Metin olmaktan başka şansı var mıydı yoksulların
Ben oldum işte, oldum ve öldüm
Sorduğum tek soru vardı kendime
(Öbürleri herkese ilişkindi)
şimdi gitsem benden ne kalır geriye?
Kaldı işte, ahdım kaldı dünyada
Yaralı bir alın
Gülümserken unuttuğum dudaklarım
Ve yurdumu dolaşan kanım kaldı sizlere
Kanım her yere bulaşıyor
Aşçının kepçesine, marangozun rendesine
silahın namlusuna, kalemin mürekkebine
yargıcın cübbesine, âşıkların neşesine
çocukların oyununa karışıyor
Dağılıyor, çoğalıyor, yalıyor sokakları
Habere çıkardım, dünyanın yaradılışını görmeye
Alevlerin, kurşunların arasından sekerdim
Ağaca bakar ağaç olurdum, köpeğe, göğe, serçelere
Yaprağa bakar yaprak olurdum, tırtıla, kuşa, yaşlı teyzelere
Umutsuzlara bakar iç çekerdim, hallaçlara, sütçülere, çerçilere
Bütün otobüsler giderdi benle, istanbul-hafik, istanbul-refahiye
Ev içlerine bakar ağlardım, buğday demetlerine, duvardaki ali''ye.
Cemlere, kahvelere, meydanlara bakardım
Herkes gibi çopur yüzlüydü hayat
Kibirliydi yoksullar, kibirli ve atak
Sözcükler hırçınlaştıkça dilsiz ve bataktılar
Böyle bir dünya dermiştim kendime
Hakikat gizlenmişti buralarda bir yere
Ne ölümler gördüm de yaşamak hırsızlık gibi geldi bana
Bulmalı derdim, bulmalı ölümün erken dilini
O da oldu. Gördüm celladımın gözlerini ve gülümsedim
Hepimize benziyordu, şaşırarak öldüm
Bir duvar dibiydi sanırım, ıssızdım ve soğuktu gece
Bir şey öğrendim ki söylemeliyim
Hayat hepimizden daha geniş
Ölüm her ömürden daha uzun sürermiş
Dağları düşündüm, sokakları, ev içlerini
Her şey yaşadığım gibiymiş, basit ve korkunç
Dil susunca kan konuşur, kan konuşurmuş
Kanım yurdumu dolaştıkça öğrendim.', 'HAYAT HEPİMİZDEN GENİŞ ÖLÜM HER ÖMÜRDEN UZUN Ben hep gülümseyerek yaşadım dünyayı Gülümseyerek ölüyorum her gün sizlerle Baştan kendime basi...', ARRAY['Türk Edebiyatı','Şiir','Metin']::text[], 8.5, '{"poet":"Metin","poet_slug":"mahmut_temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAT MAYAT', 'hayat-mayat-necip-fazil-kisakurek-kyf5a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat, mayat diyorlar
Benim gözüm mayat''ta
Hayatın eksiği var
Hayat eksik hayatta,
Takınsam, Kanat, manat
Kuş muş olsam seğirtsem
Bomboş vatana inat
Manata doğru gitsem', 'Hayat, mayat diyorlar Benim gözüm mayat''ta Hayatın eksiği var Hayat eksik hayatta, Takınsam, Kanat, manat Kuş muş olsam seğirtsem Bomboş vat...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
