INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARNAK', 'karnak-eug-ne-guillevic-uecne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'René Massat''ya
Gelir gider taşanıtlar gece
Ve kemirirler birbirlerini.
Yerken gürültü çıkarır ormanlar akşam.
Boynuna takınır yosununu deniz - ve sarınır.
İter kayalıklara adamı soğuk gemiler
Ve sarınırlar.
Eugène  GUILLEVIC', 'René Massat''ya Gelir gider taşanıtlar gece Ve kemirirler birbirlerini. Yerken gürültü çıkarır ormanlar akşam. Boynuna takınır yosununu deniz...', ARRAY['Türk Edebiyatı','Şiir','Eugène  Guillevic']::text[], 8.5, '{"poet":"Eugène  Guillevic","poet_slug":"eugene_guillevic","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARTAL ÖLÜSÜ', 'kartal-olusu-cahit-zari-foglu-eoic4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tabutunuz
Pırıl pırıl çivileri ve talaş kokuyor
Demek taze ölülerdensiniz hemşehrim
Kan akıtılmadan
Kesildi damarlarınızın sıcaklığı
Söyleyin kim yokladı
Bir ateş salmaya içinizi
Şimdi doya doya seyredin gövdenizi
Kalabalıklardan eli mızraklılardan
Otomobillerden nüfus patlamasından
Ve o koca denizlerin kirlenip ağrımasından', 'Tabutunuz Pırıl pırıl çivileri ve talaş kokuyor Demek taze ölülerdensiniz hemşehrim Kan akıtılmadan Kesildi damarlarınızın sıcaklığı Söyleyi...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zari̇foğlu']::text[], 8.5, '{"poet":"Cahit Zari̇foğlu","poet_slug":"cahit_zarifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARTON KULELERDEN', 'karton-kulelerden-rifat-ilgaz-59npy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tükenen bir şey vardı yerine koyamadığınız
Kurşundan bir bulut düşlerinizin üstünde
Sınırları aşıyordu barut dumanları
Tıkalıydı ciğerleriniz duymuyordunuz
Çekirge sürülerini beslerken ulusça
Simitsiz büyüyordu çocuklarımız
Ellerimizde karne, açtık belgeli
Kitaplarda bir şefin resmi vardı büyük
Alfabeyi sökmüş, okuyup yazıyordunuz
Sofralarınızda bolluk
Kuşsütüne karışmıştı yalanlar
Yiyordunuz içiyordunuz
Yaşamıyordunuz ki
Serçenin kursağında tohum
Balıktınız martının gagasında
Göreviniz alın terine yergi
Uyurgezerlere dümtekti
Her sokak kendi türküsünü söylerken
Susardınız dört yol ağızlarında
Alanlarda görünmezdiniz
Ustaydınız güpegündüz düş görmekte
Karton kulelerden baktınız gerçeklere
Karataş yosunlanıp yeşeredursun
Siz mermerler gibi aktınız
Ölüm sınırlara gelmiş dayanmıştı
Çağ dışı olmuştunuz gençliğinizde
Mezar taşlarınızla kucak kucağa
Takvimlerde oğlak burcu
Dedenizin belinde kuşaktınız
(1973)
Güvercinim Uyur mu adlı şiir kitabından 1974
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Tükenen bir şey vardı yerine koyamadığınız Kurşundan bir bulut düşlerinizin üstünde Sınırları aşıyordu barut dumanları Tıkalıydı ciğerlerini...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KASABA', 'kasaba-altay-omer-erdogan-4b7nj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sarı sıcak bir ağustos kapımıza dikilmiş
anahtar paslı ve kilit hafif ürkek
şimdi derinlik ile serinlik arasında
söz uçlarından vahşi düzlüklere doğru uçan
zamandır orda, biraz yorgun ve kelebek
zehir zemberek bakışlarında doğanın kül olmuş
kırların öfkesi, taşın sancısı, suların dansı
nerdeyse uzak ile yakın arasında
buğday tenine güzellemeler yakan
bir şiirdir ağaçtan düşen elmanın yarısı
öteki yarısı dağlı ağrılardan göze süzülmüş
bahçelerin kuşkusunda gölgesini büyüten ay
kaldı ki bilinç ile sezgi arasında
yıllanmış bir şarabı suni teneffüsle yaşatan
gövdemi bu kahpe ömrün bekçisi say
sırça saray viran kulübelere düşman olmuş
eğri yağmurların alfabesinde koşan at
bir zamanlar şiir ile düzyazı arasında
yaslı paslı kasabaları her sabah kuşatan
esmer ekmekler gibi bayattır ya hayat
ey rahat ölüler söyleyin kim uyuttu yazı
kumdaki yazıları kim sildi hangi ırmak
çok sonra yaşam ile ölüm arasında
eskilikleri birer eksiklikmiş gibi sunan
bir yer var tutkuyla tutunulacak
sefil ile ahmak arasında bir fark olmalı
y u t k u n m a k
(Varlık, Haziran 2003 )', 'sarı sıcak bir ağustos kapımıza dikilmiş anahtar paslı ve kilit hafif ürkek şimdi derinlik ile serinlik arasında söz uçlarından vahşi düzlük...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KASABAMIZ', 'kasabamiz-rifat-ilgaz-30bj6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Martıların düşürdüğü tohumdan
Filizlendiğine inandığım kasabamız
Yosun kokardı evleri
Çarşıları midye kokardı
Çekirdeği çölden gelen mesçitin
Boy attığına şaşardım
Bu deniz yüklü havada
Nedense gelişemedi bir türlü
En şirin yerine dikilen
İrili ufaklı mezar taşları
Belki de ölüler böyle istiyor.', 'Martıların düşürdüğü tohumdan Filizlendiğine inandığım kasabamız Yosun kokardı evleri Çarşıları midye kokardı Çekirdeği çölden gelen mesçiti...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KASAP', 'kasap-orhon-murat-ariburnu-ba4tb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İşlerin yolunda gidiyor kasap
İşlerin yolunda
Satırın saldırman belinde
Elin hayvanı emrinde
Yere yatırıp biçersin
Çengele asıp yüzersin
Mal derdinde kasap
Can derdinde koyun
Ne çirkin oyun
Ne berbat kafiye!', 'İşlerin yolunda gidiyor kasap İşlerin yolunda Satırın saldırman belinde Elin hayvanı emrinde Yere yatırıp biçersin Çengele asıp yüzersin Mal...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Ariburnu']::text[], 8.5, '{"poet":"Orhon Murat Ariburnu","poet_slug":"orhon_murat_ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAV', 'kav-sezai-karakoc-xvwuq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Otomobil birden çıkıyor yoldan
Bir deniz kıyısında duruyor
Büyü bıçağı koparıyor onu gri harmanili kayalardan
Yalnız sırtlarından sezilen haçlı erleri kayalardan
Kayalar kapatıyor onun arkasını som
Düşünceyle şekerlendirilmeden
Günse eriyor yön yön Van Gogh''su bir kırmızılık
Kirazların ve güllerin tifoya kardeş çıkan rengi
Kokuları bile kıpkırmızı olan güllerin
Ve otomobilden inen sensin iki avcunda deniz
Çevrene üşüşen zeytin ağaçları
Arkandan inenler o kimlerdir ki avuçlarına gülüyor
Oluşa gülüyorlar kuşlara çocuklara
Ki senin ellerini görmek bir kurtuluştur çocuklara
Sen yüzünde Akdeniz memnunluğu sen Truvalı Helen
Sana gelmiş bütün yunanlılar atlı arabalarla
Atlarla otomobillerle uçaklarla
Bütün kiraz yangını çocukları andıktan sonra
Evrenin akşamından döndünüz evlerin parmaklarına
Almışsın üstüne örtücülüğünü siyah kahverenginin
Ağaç gövdelerinin kavların rengini
Tabiat seninle canlı ve yeni
Tabiatı duruşun ve bakışınla verimlendirmişsin
Ey geçmez gençliğin telâşsız sesi
Sesinle ölümü ürkütmüş terletmişsin
Bir piknik yer altı gençliğine gözlerin
Saçların bir başlangıç eski zaman leylâklarına
Bir vakit gelse ki kapansam ayaklarına
Geçen zamanı yanlış bir rüya gibi yorumlasam
Resmini yunanlılardan kalma kayalara oysam
Gitsem Bergama Tiyatrosunda seslensem ismini
Benimle birlikte tabiat çağırsa seni
Eski çağ çağırsa seni
Yeni çağ çağırsa seni
Her piknik gezintisinde yaptıkları gibi
Çiçek kuş arı ve mavi gökte güneş
Seninle donanırlar çocuk oyunlarında dağ düğünlerinde
Ve kayalar ilk olarak atalardan arınmış
Büyümüş denizden gelen sabırsız seslerle
Sonbahar papirüslerini birer birer atmış
Kentse yüzyıllarca ilerde ve ötede
Sen halk ve çocuklar ve bir portatif çadır
Ve kalakalmış bir oto uçurum kenarında
Hafta içi gel gitleri denizde kanayıp ıslanış
Güneş sevinçli yaşlarla kararmış
Tabiatla konuşmaya başlarsın bardakların derinliğinde
Çin çay bardaklarının
Birbirinizi yitirirsiniz tabiatın sisinde
Biriniz Kafdağında biriniz Çinseddinde
Deniz yüreğinizin telâşsızlığından aydınlığını emer de
Akşamın üstüne boşanır yanar beyaz gecelerde
İyot kokulu yalnızlık panayırlarında
Ben bir peri masalı gibi anılırım o anda
Gelip geçen bir nöbet gibi o anda orada
Saçılan eşya toplanır otomobil çalıştırılır dönüş başlar
Tabiatla son alışverişi yapar çocuklar
Deniz yavaş yavaş siyah bir kabuk bağlar
Çayırlar üzerinde soğan yumurta kabukları büzülmüş kâğıtlar
Sende kadınlığın o sonsuz  gülümsemesi ve toparlanışı var
Gözler hep arkadadır acaba unutulan bir şey mi var
Mutlaka unutulan bir şey var
Gün bir  bomba gibi düşer ve batar
Arkaya son bir göz atılır otomobile doluşulur
Şimdi sizi tabiattan koparan geri alan bir asfalt
Şehrin düşüncelerini yayınlayan kalorifer bacaları
Oraya buraya koşuşan insanlar
Ve bütün ışıklar yanar', 'Otomobil birden çıkıyor yoldan Bir deniz kıyısında duruyor Büyü bıçağı koparıyor onu gri harmanili kayalardan Yalnız sırtlarından sezilen ha...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":69}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAVAK AĞACI', 'kavak-agaci-oguz-tansel-fyy7y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk ışık saygıyla selamlar dallarını,
Başın ufuklar ötesinde güler.
Rüzgârların dilinden yaprak yaprak anlarsın,
Üstünde sevgisi cıvıl cıvıl serçeler.
İnsanlara örnek duruşun,
Uzak diyarlardan selam getirir leylek
Tavında toprak gibi gücün yeter yaza, kışa
Bizimkinden başka, aydın dünyan gerçek.
Yeryüzünün süsü, onuru
Işıl ışıl türkü söyler toprağa gölgen.
En temizi sevgilerin en arısı
Çalışanların hayatına yakın düşüncen.
Vücudun çelik gibi kavak ağacı
Seni kucaklamak gelir içimden
Topraklarımda biriniz bin olsun,
Bütün iyi dilekler yürekten.', 'İlk ışık saygıyla selamlar dallarını, Başın ufuklar ötesinde güler. Rüzgârların dilinden yaprak yaprak anlarsın, Üstünde sevgisi cıvıl cıvıl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAVAKLARIN SİLİNİŞİ', 'kavaklarin-si-li-ni-si-ren-char-aeg93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kasırga buduyor ağaçları.
Uyuyorum, ben, sevecen gözlü şimşek.
Titrediğim büyük rüzgarı bırakın
Birleşsin çoğaldığım toprakla.
Esintisi bileyliyor gözcülük nöbetimi.
Nasıl da alt üst tuzağın
Kirli katmanlı kaynağın çukuru!
Kendini yüreğin onayladığı bir ateş gibi gösteren
Ve havanın pençelerinde çınlattığı
Bir anahtar yuvam olacak.
René CHAR', 'Kasırga buduyor ağaçları. Uyuyorum, ben, sevecen gözlü şimşek. Titrediğim büyük rüzgarı bırakın Birleşsin çoğaldığım toprakla. Esintisi bile...', ARRAY['Türk Edebiyatı','Şiir','René Char']::text[], 8.5, '{"poet":"René Char","poet_slug":"rene_char","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAVUŞTUKÇA', 'kavustukca-metin-cengi-z-aj8i8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuz ve ılık bir ülke soluğum
Yabanıl ve makul ağzına
Çünkü dehşet seviyorum, aşk mültecisiyim, çünkü
Her yere yasaklıyım, yalnız serbestim sana
Sana dokunuyorum kalaylanıyor gök
Adını koyamadığım sessiz ihtilaller oluyor
Fırtınalar oluyor, kasırgalar
Çıldırtan bir güz yeşili örterken istek kipini
Değdi değerken deniz kaçkını o mavi
Çatılara, bulutlara, dumanına vapurların
Şarkılar söylüyorum senin için değişik dillerde
Bütün sevdalılar nehirler atlıyor, mevsimler
Hele ana dilimle ki patlar oldum olası
Sıkışmış mağma gibi yeraltında kaynayan
Sana dokunuyorum, rastlantı olmaktan çıkıyor anlam
Sana varıyorum, sular durmaz oluyor yataklarında
Ki savunmalıyım diyorum güzel olan ne varsa
Şu karıncalarla, günlerin yükünü taşıyan
böceklerle belki
Bak çipolar çekiliyor Gemiler
Uzaklara çağırıyor düşü
Sen mendil sallanışı gibi
Dişil çiylerle kaplıyorsun denizi
Ve açıkta, dalgada, sandallar gibi okşuyor suları
sözcüklerim
Seninle aynı anlamda kavuştukça.', 'Sonsuz ve ılık bir ülke soluğum Yabanıl ve makul ağzına Çünkü dehşet seviyorum, aşk mültecisiyim, çünkü Her yere yasaklıyım, yalnız serbesti...', ARRAY['Türk Edebiyatı','Şiir','Metin Cengi̇z']::text[], 8.5, '{"poet":"Metin Cengi̇z","poet_slug":"metin_cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAYA', 'kaya-ozlem-tezcan-dertsi-z-olpz7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmurunu linç eden bir ülkede,
suçun damla olmaktı
çiçekli bir saksı koymak,
düzenin balkonuna
sütten kesilince sevmeler,
zenci bir hüzün oluyor kadınlığım
yeşile küs duvarlar arasında
sıkışıp kalırken sürgün veren dal
bahar, mayısına kıyar mı?
karalıyorum durmadan defterimi,
eskizimde eğreti bir Nijerya
büyük bir kaya alsam
fırlatsam kalbinize
taş taşı yıkar mı?', 'yağmurunu linç eden bir ülkede, suçun damla olmaktı çiçekli bir saksı koymak, düzenin balkonuna sütten kesilince sevmeler, zenci bir hüzün o...', ARRAY['Türk Edebiyatı','Şiir','Özlem Tezcan Dertsi̇z']::text[], 8.5, '{"poet":"Özlem Tezcan Dertsi̇z","poet_slug":"ozlem_tezcan_dertsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAYALAR''DAN', 'kayalar-dan-eug-ne-guillevic-u9uc3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I
Kayalar bilmez
Konuşur durursunuz onlardan
Avuçlarında başlayıp biten
Büyüklüktür yalnız
Ve unutmak gelip gidişini yanıp sönüşünü denizin
Güneşlerin kırmızı
II
Gülmek ağrısını duymazlar
Yahut sarhoş olmak
Karanlık ortasında
Ateş yakmazlar
Çünkü hiç mi hiç
Korkmazlar ölümden
Korku bir konuk
Yuvalarında
Onlar deli ve çılgın
Gerçeği çırılçıplak görürler
III
Ve sonra sevinç
Düşmanı bilmekten
Yaşayabilmekten doğan
Kıyılarda
Taşların çekmesine rağmen
Dalga ve rüzgârların
Öğle uykusunda oldukları zaman
VI
Tapınak olmak istemez kayalar
Orda huzur rahat ve gurur
Düşmanla karşı karşıya
Düşmanla çevrili olmak
Adıyla sanıyla sevinci
Onlara yalnızlık getirir yalnızlık yalnız
Deniz ister kapkara olsun ister bulanık
İster masmavi
VIII
Bazen onların gecesi içinde
Bir ses duyulur bir ses
Uzun uzun çınlayan
Ve kaybolur her zerresi onların
Korkunç bir korkunun içinde
Bir sesten ibarettir
Artık onlar
X
Felaket ne orda ne burda
Kendi kendinin dışında olmakta
Çılgınlığın kör olduğu
Boz bulanık gördüğü zaman
Bir kayanın hatırası olmak
Ve uzanmak dışa dalgalara
Eugène  GUILLEVIC', 'I Kayalar bilmez Konuşur durursunuz onlardan Avuçlarında başlayıp biten Büyüklüktür yalnız Ve unutmak gelip gidişini yanıp sönüşünü denizin ...', ARRAY['Türk Edebiyatı','Şiir','Eugène  Guillevic']::text[], 8.5, '{"poet":"Eugène  Guillevic","poet_slug":"eugene_guillevic","theme":"Türk Şiiri","is_hero":false,"total_lines":53}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAYIP OĞLUNU ARAYAN BİR BABA İÇİN ŞİİR', 'kayip-oglunu-arayan-bi-r-baba-i-ci-n-si-i-r-i-lhan-berk-3w4li', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Bu oğlan, dedi, daha ne kadar kaçacak?
On ikisinde kaçtı, on altısında kaçıyor.''
Böyle deyip sustu. Ağzının sol yakasında
Toplayıp uzun mu uzun bıyıklarını.
Erzurum''dan mı Tunceli''den mi geliyordu?
Ve dünya şimdi ne kadar büyüktü,
ilk anlıyordu
Havada dönüp duran bir kuşa çevirdi,
sonra gözlerini
Çekilip içine.
Sustuk biz de,
kapanıp her birimiz içine.
Deniz Eskisi', '''Bu oğlan, dedi, daha ne kadar kaçacak? On ikisinde kaçtı, on altısında kaçıyor.'' Böyle deyip sustu. Ağzının sol yakasında Toplayıp uzun mu ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAYSERİ KAYSERİ', 'kayseri-kayseri-abdulkadir-budak-lluyv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana bir Kayseri bulun, kırık dalın ucundan
Yere düşüp ezilmiş bir çiçeğe benzesin
Su içen ata benzesin, kanat tazeleyen kuşa
Ayna olup göstersin en yaralı dönemimi
Zaten kan kaybetmeye alışkın bir adamım
Bana bir Kayseri bulun, o yitik hançerimi
Bir dergiden söz açın, kitap çıkarmalardan
Yarışır gibi şiirler yazdığımız günlerden
O şehir o yanda kaldı burada bırakıp beni
Çivisini arıyor, yüreğime asılacak
Erciyes''in önünde çekilen hatıra resmi
Bana bir Kayseri bulun, akşam üstü çay içerken
Elimden düşürdüğüm bir bardağa benzesin
Yıkanmış ütülenmiş masa örtülerine
Bana bir Kayseri bulun, burada çok üşüyorum
Yorgan niyetine atıverin üstüme
Adımı şaire çıkaran bir Kayseri bulun bana
Şiir yazmayı bırakmış dostlar da olsun içinde
Bana bir Kayseri bulun, gecikmeniz halinde...', 'Bana bir Kayseri bulun, kırık dalın ucundan Yere düşüp ezilmiş bir çiçeğe benzesin Su içen ata benzesin, kanat tazeleyen kuşa Ayna olup göst...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KİBAR HIRSIZIN TÜRKÜSÜ', 'ki-bar-hirsizin-turkusu-can-yucel-3b89s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anamın ipiyle indim gökdelen damınızdan
Kelebek gibi girdim kelebek camınızdan
Taksinize mülkünüze dairenize...
Heceleyerek üzerinde ayak ve el uçlarımın
Belledim seyyarenizi ve kelimelerinizi...
Gözlerinize baktım, mukaddes ciltlerinize, büfelerinize
Vesairenize...
Şiir fenerimle de baktım, son çığlık!
Aşk yokmuş sizde beş paralık!
Gidiyorum ben boşçakallar
Sıçmışım ortalık yerinize
Kıçımın fosforuyla aydınlanın siz artık', 'Anamın ipiyle indim gökdelen damınızdan Kelebek gibi girdim kelebek camınızdan Taksinize mülkünüze dairenize... Heceleyerek üzerinde ayak ve...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEÇİ', 'keci-umberto-saba-t4ug6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir keçiyle konuştum
yalnızdı çayırda
bağlıydı
doymuştu otla
ıslanmıştı yağmurla
meleyip duruyordu orda.
Meleyişi
kardeşti acıma
yanıtladım onu
ilkin şaka yoluyla
sonra düşündüm ki
sonrasızdır acı
tektir, değişmezdir sesi.
Bu sesin inlediğini duyuyordum
yalnız bir keçide.
Her derdin
her yaşamın
yakındığını duyuyordum
Sami yüzlü bir keçide.
Türkçesi: Bedrettin Cömert', 'Bir keçiyle konuştum yalnızdı çayırda bağlıydı doymuştu otla ıslanmıştı yağmurla meleyip duruyordu orda. Meleyişi kardeşti acıma yanıtladım ...', ARRAY['Türk Edebiyatı','Şiir','Umberto  Saba']::text[], 8.5, '{"poet":"Umberto  Saba","poet_slug":"umberto_saba","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEDİ AKLI', 'kedi-akli-arif-damar-qmfjg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir diyeceğim yoktu hüzünden yana
Yıpranıyordu kötü kadınlarda aşkım pis karanlıklarda
Yetmiyorum yeni insanlara yetişemiyordum
Ölür kalırdım belki de sokak aralarında bir kenarda
Kimin umurunda dedi ama kendimi inandıramadım buna da
Yakışmıyordum eski pencerelere yosunlu sulara
Ölür kalırdım belki de sokak aralarında bir kenarda
Uyandırılacak çocuklarım vardı uyuyorlardı uykularında
Çok mu yaşamıştım az mı ölmek hakkım mıydı yıl varken akşamlara
Bu kedi nerden çıktı demeyin kapı aralıktı  ben bıraktım da
Okşayacak bir şey ister ellerimiz kendi sıcaklığında
Yıpranıyordu kötü kadınlarda aşkım pis karanlıklarda
Ne iyi etmişim aldım düşündüm kedilerin yarı ak yarı kara aklında
Kedi işte kedi boğuyordu yavruyu engel görünce aşkında
Çekilmemişti denizlerim
Döndüm hırpalanmış geceden dayanıklı aydınlıklara
Ağlanır kedi yavruların çocuksuz anaların arasında
Bu kedi nerden çıktı demeyin kapı aralıktı  ben bıraktım da
Uyandırılacak çocuklarım vardı uyuyorlardı uykularında
Ne iyi etmişim uyur uykularında', 'Bir diyeceğim yoktu hüzünden yana Yıpranıyordu kötü kadınlarda aşkım pis karanlıklarda Yetmiyorum yeni insanlara yetişemiyordum Ölür kalırdı...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEDİ', 'kedi-aydin-hati-poglu-b7sga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Usulca okşuyor sesi sabahı
Güne ulanan bebek uykusu
İğdiş sevinçlere hazırlanıyor
Usulca geriniyor düş günlerine
Eşkiya doğası çiziyor sınırları
Sağıyor sevginin memelerini
Usulca sofalara sızıyor korkusu
Özgürlüğü bilmiyor kuşatılmış
Kıyısında hiç yaşamadığı sevda
Müstevli ordulardan arta kalmış nefer
Yalnız ve içedönük kimi zaman da
Usulca çıkıvermiş mısır tarihinden', 'Usulca okşuyor sesi sabahı Güne ulanan bebek uykusu İğdiş sevinçlere hazırlanıyor Usulca geriniyor düş günlerine Eşkiya doğası çiziyor sınır...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEDER', 'keder-vladimir-mayakovski-15hon', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgâr, umutsuz, boşuna
dövünüp durdu insafsızca.
Karartarak damlayan kanı
ürpertip damların omurgasını.
Ve bir yalnızlık düşkünü yine
doğdu dulkalmış ay gecede.
Vladimir MAYAKOVSKI', 'Rüzgâr, umutsuz, boşuna dövünüp durdu insafsızca. Karartarak damlayan kanı ürpertip damların omurgasını. Ve bir yalnızlık düşkünü yine doğdu...', ARRAY['Türk Edebiyatı','Şiir','Vladimir Mayakovski']::text[], 8.5, '{"poet":"Vladimir Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEDİLERİ SEVERKEN AĞLAYINIZ', 'kedi-leri-severken-aglayiniz-i-smail-uyaroglu-kuyyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kedim ve ben
Ölüyoruz yavaş yavaş
Karşılıklı, köşemizde
Elenirken eleğinde sıkıntının saatler
Mutad olduğu üzre
Bazen o benim kucağımda
Bazen ben onun
Avutuyoruz birbirimizi
Özlerken aynı şeyleri gizlice
Nasıl tırmalardık hayatı
Bir zamanlar şehvetle
Gittikçe bozuluyor yazım benim
Bozuluyor resmi onun gittikçe
Yaptığı eskiden özenle
Döşemelerine koltukların, kanepelerin
Esin geldikçe pençeleriyle
Derim ki ben
Kedileri severken ağlayınız
Beyaz değil aslında mahzundur kediler
Bu şiiri okurken de ağlayınız
Görüldüğü gibi
Kemiriyor İsmail''i keder', 'Kedim ve ben Ölüyoruz yavaş yavaş Karşılıklı, köşemizde Elenirken eleğinde sıkıntının saatler Mutad olduğu üzre Bazen o benim kucağımda Baze...', ARRAY['Türk Edebiyatı','Şiir','İsmail  Uyaroğlu']::text[], 8.5, '{"poet":"İsmail  Uyaroğlu","poet_slug":"ismail_uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEDİLER', 'kedi-ler-altay-oktem-ky7en', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'krallara yakışır asılmak
bir tüyün usulca düşüşü yere
gibi sessizce gelir karanlık
son sığınak da terk edilir
kediler ölmeden önce
üstüme gül koklayan bu kenti bırakırım
bırakır giderim, kentler kuşatılırken
kuşlar ölürken gökyüzü yalnızdır
ancak krallara yakışır asılmak
bir tüyün usulca düştüğü yerde
peygamberler gül koklamaz, yalan
çocuklar büyümek istemiyor işte
biz aşınıp küçüldükçe
son sığınak da terk ediliyor
kediler ölmeden önce
kafka, kutsa beni bu gece', 'krallara yakışır asılmak bir tüyün usulca düşüşü yere gibi sessizce gelir karanlık son sığınak da terk edilir kediler ölmeden önce üstüme gü...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay_oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEDİM', 'kedi-m-halit-fahri-ozansoy-6upx2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kedim henüz bir yaşında;
Uyur hep soba başında.
Hem cesurdur, hem de kurnaz.
Bir tıkırtı duyar duymaz.
Uyanır, aslan kesilir;
Gözleri volkan kesilir.
O geldiği günden beri
Bizim evin fareleri
Damdan, tavandan indiler,
Birer deliğe sindiler.
Koşup yakalıyor hemen
Yuvasından, deliğinden
Çıkanları diri diri.
Artık bunlardan hiç biri
Dolaplarıma girmiyor,
Kitapları kemirmiyor.', 'Kedim henüz bir yaşında; Uyur hep soba başında. Hem cesurdur, hem de kurnaz. Bir tıkırtı duyar duymaz. Uyanır, aslan kesilir; Gözleri volkan...', ARRAY['Türk Edebiyatı','Şiir','Halit Fahri Ozansoy']::text[], 8.5, '{"poet":"Halit Fahri Ozansoy","poet_slug":"halit_fahri_ozansoy","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEŞKE HİÇ . . .', 'keske-hi-c-c-hakki-zari-c-htv60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir de anlamını yansıtan sorular: Gözlerin
KEŞKE HİÇ . . .
Ayazdım, azdım... Azıksızdım
İçimde sırasına koşan şiirler vardı
Zamansız çalmasaydın kapımı
Esmer gülüşünle mıh çakmasaydın günlerime
gelmeseydin
Zift ile karıyordu kendini gece
Gitmek uçurum, dönmek aramamanın yalvarısı
Vazgeçmek senden, pişman olmak
Yarını göremeyenlerin kör tanrısıyla zar atmaktı
gelmeseydin
Sarışın rüzgârlarda soluk benizli şiir eskizleri
Çorak zamanlarda kendisi için kanayamayan aşklar vardı
Yanılsamaların sonbahar yüzünden geçiyordum
Hilebazdı siyah dokunuşlar, cinayet kokuyordu
gelmeseydin
Tenimdeki kilim deseni yaralara
Kıymık gibi saplanan yağmur damlaları
Pembe kokusuna dikenini saplayan gül
Elgin sözcüklerden payıma düşen kül
Bakır şimşekleriyle kahkaha atan
Gökyüzüydü tek paylaştığımız
gelmeseydin
Mezatta hırpani bir sözcüktü vefa
Yokluğunun tadı kusursuz ve gölgesiz gri
Unutmak çağımızın en masum duldasıydı
İntiharı ve hiçliği anımsatıyordu unutulmak
gelmeseydin
Yine de yeniden gelmeseydin
Hafif tebessüm iç kanamalı yüzümle
Serçeler gibi sabahı bekletmeseydin bana
Ayazdım, azıksızdım... azdım
gelmeseydin
Gözlerimdeki forsaya toprak tadında mavi bakmasaydın
Keşke hiç!..', 'Bir de anlamını yansıtan sorular: Gözlerin KEŞKE HİÇ . . . Ayazdım, azdım... Azıksızdım İçimde sırasına koşan şiirler vardı Zamansız çalmasa...', ARRAY['Türk Edebiyatı','Şiir','C. Hakkı Zari̇ç']::text[], 8.5, '{"poet":"C. Hakkı Zari̇ç","poet_slug":"zaric","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KELEBEK', 'kelebek-yusuf-altunel-rowf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kelebekler
büyütürüm
öpüşlerim
meneviş
yanaklarına
barışçık kuşları
gülücük  tohumum
taşır sedef kentime
seni taşır
avuçlarımda
kaybolmuşluklar
beslediğim renksiz
dokunuşlar
bülbül
ötüşlü ölürüm
hasret
çiçeğim dizelerimde
bastırır asi tomurcuk
yakamoz tadında
göğüslerinin
ayaklanışını gömülüşüm
hoyrat ağzım
yönünü bilmez kelebek', 'kelebekler büyütürüm öpüşlerim meneviş yanaklarına barışçık kuşları gülücük  tohumum taşır sedef kentime seni taşır avuçlarımda kaybolmuşluk...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Altunel']::text[], 8.5, '{"poet":"Yusuf Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KEŞİŞLER GEÇTİ ÖLÜMDEN', 'kesi-sler-gecti-olumden-bejan-matur-ro4vk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüm eskiydi
Zaman sonrasız, unutkan
Yatağım öyle derin
Onca batık hüznü taşıyan
Keşişler geçti ölümden
Kan ve tufan
Ses ve susuş
Yankı ve buz
Karaya bağlayan
Batmak için kara göründü
Kıyıya sağır dalga durmaz', 'Yüzüm eskiydi Zaman sonrasız, unutkan Yatağım öyle derin Onca batık hüznü taşıyan Keşişler geçti ölümden Kan ve tufan Ses ve susuş Yankı ve ...', ARRAY['Türk Edebiyatı','Şiir','Bejan Matur']::text[], 8.5, '{"poet":"Bejan Matur","poet_slug":"bejan_matur","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KELİMELER...', 'keli-meler-ozdemir-asaf-scpky', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yarıda kalmış aşklarının hesapları içinde
Denizlere açıldı içimizden biri
Niçin gittiğini söylemeden.
Doyulmamış arzularla doluydu yelkenleri.
Yıpranmış kelimelerin verdiği güvenden.
Bulacak sanıyordu yenilikleri.
Her an bir yeni su vardı,
Her yeni suda bir yeni an.
Deniz, dalgalarıyla gösteriyordu dışından
Yaşananla düşünülenler arasındaki farkı.
Bitmiyordu köpüklerle renkler
Bir başka damlada, bir başka ışıkta başlamadan.
Gözlerinin önünde bir oyun, ardında bir oyun.
Dışında ne varsa yeni, ne varsa gerçek.
Yeni manzaralarla gelen yeni duygular
Hani, eski kelimelerle olmasa
İnsanın ömrünce devam edecek.
Gözlerinin önünde bir oyun, ardında bir oyun.
Anladı,ölmekle yaşamanın birleştiği noktada
Yeni rüzgarlarla esen yeni korkulara
Yeniliklerini bağışlamayan kelimelerin
Nasıl düşman sığınaklar halinde direndiğini.
Anladı, bütün olmuşlarla olanların
Ve bütün olacakların
O kelimelerin içinde
Kendisine varmadan eskidiğini.', 'Yarıda kalmış aşklarının hesapları içinde Denizlere açıldı içimizden biri Niçin gittiğini söylemeden. Doyulmamış arzularla doluydu yelkenler...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir_asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İŞKENCE TUTANAĞI', 'i-skence-tutanagi-yusuf-altunel-behph', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bilgisayarımın katil vantilatörü
öldürüyor sessizliğini gecenin
yüreğimi teslim almış korkular
fırlıyor yırtık göğsümden
sokakta her araba geçişinde
ölüm coğrafyası okuyor
öğretmenler gözleri kanlı
işkencede inliyor gözaltında
kaybolan zanlı
silah ve miğfer dökülüyor dizeye
hece nasırlı
dersimiz edebiyat
utanç içinde sanat
tecavüzcülerin elinde
dökülür tohumu kanın
buz renkli geceye
tuzlu gözyaşları karışır kurbanın
gece yükseltir sesini
yüreğimi kelepçelerim
apoletler didikledikçe beynimi
ormanda infaz edilmiştir
pırpır alacalı düşler
orospunun birine sunulur
sorgu sonrası gülüşler
sigara, rakı ve esrar kokar
sokakları işkencehanenin
ışığın kaynağı elektrik aşağılıktır,
askısı elbisenin aşağılık
gözyaşları boğar geceyi
inleyen, bağıran, haykıran sanık
boşunadır çırpınışlar,
tüketir söz kimliğini
şarjör boşalır
ufuktan boy veren
güneşin başına
sonra
sonra derin
sonra uzun
sonra vicdan kadar ağır
sonra ekmek kadar keskin
sonra işte
öylesine bir ölüm
toprak altından kemikler boy verir
ayaklanır insan hakları
bulutlar öfkeye gebedir
avrupanın bir kentinde
ölümün sayılarına alışkın görevliyi çarpar
taburun birinde çevrilen karanlık manyetolar
doktor kontrolündedir işkence
yüzünü gizler
diplomalı bir günde erkanın önünde
hipokrat adına edilen yeminler
kurşunlanır beden
yakılır kemik
tutuşur halay
tilililer kıvılcımlanır
bir şahini kopartır
güvercin maviden
usulca soyunur
suya girer
dal gibi ince ,
gelin
sonra derin
cehennem kadar derin
muştu tohumları ekerim
kışı yaza vuran alıcı kuşlar
birazcık da bu taraflara çıkın gelin', 'bilgisayarımın katil vantilatörü öldürüyor sessizliğini gecenin yüreğimi teslim almış korkular fırlıyor yırtık göğsümden sokakta her araba g...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":69}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İŞKENCECİYE BİR SORU', 'i-skenceci-ye-bi-r-soru-i-smail-uyaroglu-mgd8t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocuğun var mı ey cellat?
Öpebiliyor musun onu herkes gibi sen de
Yüzün gölgelenmeden, lekesiz bir sevinçle
Akşamları "iş"ten eve döndüğünde?', 'Çocuğun var mı ey cellat? Öpebiliyor musun onu herkes gibi sen de Yüzün gölgelenmeden, lekesiz bir sevinçle Akşamları "iş"ten eve döndüğünde...', ARRAY['Türk Edebiyatı','Şiir','İsmail  Uyaroğlu']::text[], 8.5, '{"poet":"İsmail  Uyaroğlu","poet_slug":"ismail_uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KENDİ ŞARKIM', 'kendi-sarkim-walt-whitman-3xpxb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I
Kendimi övüyorum, kendimi anlatıyorum,
Bende olanlar sizde de olacak,
Çünkü bendeki her atom benim olduğu kadar sizindir de.
Sere serpe ruhumu çağırıyorum,
Eğilip koyveriyorum kendimi yeşeren yaz çimenini gözleyerek.
Dilim, kanımın her atomu, bu topraktan oluşma, bu havadan,
Burada doğmuş ana babalardan doğma, onların da ana babaları
burada doğmuş, onların da, onların da,
Ben, otuz yedi yaşımda bugün, sağlık içinde başlıyorum,
Ölünceye kadar durmama umuduyla.
İnançlar, mezhepler ara verdi,
Geri çekilip öylece kaldılar, ama hiç unutulmayacaklar,
Ben hem iyinin, hem kötünün limanıyım, ne pahasına olursa
olsun izin veriyorum konuşmaya,
Denetlenmeyen doğa, özgün enerjisiyle.
Walt WHITMAN
Çeviren : Memet Fuat
Şiirin Aslı :', 'I Kendimi övüyorum, kendimi anlatıyorum, Bende olanlar sizde de olacak, Çünkü bendeki her atom benim olduğu kadar sizindir de. Sere serpe ru...', ARRAY['Türk Edebiyatı','Şiir','Walt Whitman']::text[], 8.5, '{"poet":"Walt Whitman","poet_slug":"walt_whitman","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
