sen yoksan', 'tartılır söz terazisinde gözlerinin ne zamandır değiş tokuş bakışlarımız bir kuş ucumu gider geliriz ben sana sen bana o dudak senin bu duda...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin_gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KUŞUM VE BEN', 'kusum-ve-ben-nilgun-marmara-2j9ff', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşum ve ben bir aynada
