INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜ EBE', 'olu-ebe-volkan-i-pek-3u2et', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'EBE
Bir deri
bir kemiğin eline dokunurken…
Yerim,
Göğüm,
Günüm,
Gecem,
Sobe…
Elim,
Dilim,
Göz bebeğim,
Ebe…
Üç yüz dersem
Öl,
Üç yüz bir dersem
Ölme…
Bir romana imrenip,
Yattığından beri tozlu döşeğe
Uğultularımızı sayıyorum,
Doksan sekiz
Doksan dokuz
Yüz
Önüm,
Arkam,
Sağım,
Solum,
Güz.
Burada adalet
İnsanların
Etinden,
Umudundan,
Sigarasının dumanından
Sağlanırken…
Sağırlığımızı sayıyorum…
Yüz doksan dört dersem
Öl
Yüz doksan beş dersem
Ölme…
Utancımızı sayıyorum,
En hafifinden beş yıl yatıran
Bir asiliği
Dökerken önündeki kâğıda
Şair,
Titreyen ellerimizi sayıyorum…
İki yüz doksan yedi dersem
Öl
İki yüz doksan sekiz dersem
Ölme…', 'EBE Bir deri bir kemiğin eline dokunurken… Yerim, Göğüm, Günüm, Gecem, Sobe… Elim, Dilim, Göz bebeğim, Ebe… Üç yüz dersem Öl, Üç yüz bir der...', ARRAY['Türk Edebiyatı','Şiir','Volkan İpek']::text[], 8.5, '{"poet":"Volkan İpek","poet_slug":"volkan_ipek","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜ ÇOCUKLARA NİNNİ', 'olu-cocuklara-ni-nni-sait-maden-68j90', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah, bulur mu yeni bir kucak
sizden yerde kalan oyuncak,
gömleğiniz üşümez mi, loş
köşelerde sessiz, içi boş
n''eyler, ah çocuklar, yalınız
topunuzla ayakkabınız,
ya cebinizde kalan şeyler,
az bir sicim, kırık bir şeker,
saçınızdan kayan kurdele
sizi en son okşayan ele?
Bunlar işte benim tek varım,
hergün alır alır okşarım,
öperim göğüs geçirerek,
yanağıma sürerim tek tek;
ah çocuklar, hayıflanmayın,
kendinizi yanımda sayın...
Saçlarını bir güzel ördüm
bozduğunuz bebeklerin tüm,
diktim özenle mini mini
yırtık ya da söküklerini;
iç çekmeyin çocuklar, susun,
hepsi derin derin uyusun...
Boyadım sizin yerinize
yüzlerce kuş defterinize,
sizin sesinizle şakırlar,
aynı gülüş onlarda da var,
yüzleri hep sizin yüzünüz,
ses etmeyin, ürkütürsünüz...
Onardım inceden inceye
trenleri işleyinceye
vapurları yüzünceye dek,
arkalarından üfleyerek;
ah çocuklar, üflemeyin siz,
birdenbire kabarır deniz.
Çemberiniz koşuyor yine
boş arsada kendi kendine,
uçurtmanız gökte sarı mor
pır pır ipildeyip uçuyor,
ilişmeyin çocuklar sakın,
oldukları yerde bırakın.
Topacınız dönüp durmada
şu dönmesi bitmiş dünyada,
sallanıyor yine bir çıplak
dalda usul usul salıncak;
hep böyle gidip gelse gerek
çocuklar siz dönünceye dek.
Göz göz olmuş bakıyor ıssız
bir köşeden zıpzıplarınız,
koşuyor gölgeniz sokakta
binmiş de bir değnekten ata
oynarken sessiz iki ağaç
karanlık avluda saklambaç
ve ay, çenesinde elleri,
seyrederken uzak bir yeri...
Bir şeyler arar gibisiniz
bir körebe oyununda siz,
alnınızda ah gündüz gece
o gözbağı kalsın öylece;
ah çocuklar ilerlemeyin,
önünüzde kuyu var, derin...
Ah çocuklar uyuyun artık,
başınızı okşar karanlık,
durur durur öper o dalgın
yüzünüzden, kımıldamayın.
Örtü örttüm üzerinize
ışık düşmesin diye size,
üşümesin diye göğsünüz
serincene başlayınca güz,
dağıtmasın diye çocuklar
saçınızı gizli bir rüzgâr;
mışıl mışıl uyuyun işte
siz bu geleceksiz geçmişte,
bir sürü tavşan, bir sürü kuş
gelmiş, yanınıza doluşmuş,
seyrederler başından beri
yüzünüze konan düşleri.', 'Ah, bulur mu yeni bir kucak sizden yerde kalan oyuncak, gömleğiniz üşümez mi, loş köşelerde sessiz, içi boş n''eyler, ah çocuklar, yalınız to...', ARRAY['Türk Edebiyatı','Şiir','Sait Maden']::text[], 8.5, '{"poet":"Sait Maden","poet_slug":"sait_maden","theme":"Türk Şiiri","is_hero":false,"total_lines":78}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİLİ ONBEŞİNCİ KIŞINDA', 'si-li-onbesi-nci-kisinda-erik-stinus-ly888', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşlerimizi çiziyoruz duvarlara.
Hiç acelemiz yok - gün ışığında:
bütün renkler haklarını almalı,
bütünüyle yazılmalı şiir, her sözcüğüyle
başlangıçtan geleceğe kadar;
nasıl ki mutfaktaki soğan, patates,
fasulye ve ekmeğin gücü ve tadı,
bölgedeki en karanlık köçelerden
bir araya getirecektir çocukları;
o kadar acı çektirmesin diye
kurdukları düşler,
biraz ısınsınlar diye ateşin yanında
ve ilk şeftalinin çiçek açtığı,
küstümotlarının
çekinmeden güneşi yansıttıkları gün
koşarlarken sokaklarda,
bahçelerde, tarlalarda
artık kimse yenemesin diye onları.
Erik STINUS', 'Düşlerimizi çiziyoruz duvarlara. Hiç acelemiz yok - gün ışığında: bütün renkler haklarını almalı, bütünüyle yazılmalı şiir, her sözcüğüyle b...', ARRAY['Türk Edebiyatı','Şiir','Erik Stinus']::text[], 8.5, '{"poet":"Erik Stinus","poet_slug":"erik_stinus","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜ SİRENLER', 'olu-si-renler-edip-cansever-tw8xg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gerçekte duymadığım sesler
bitti
Öğleye doğru bir
gökgürültüsü yalnız
Karıştırdı ortalığı bir
süre
Gök akıttı bir parça
yağmurunu
Ve deniz kuşları umutsuz
Arıyorken kokularını
gölgelerinde
Sıyırdı bir iki bulutu güneş
de
Yığılıp kaldı yorgun
Denizin gözbebekleri üstünde.
Bir uyum muydu durgunluk,
fırtınayı
Gökgürültüsünü de
barındıran içinde
Duyuyorum o tanıdık sesi yeniden
Tiz bir çıngırağı andıran
Benzeyen zil sesine de
Daha önce unutmuşum gibi denizde
Yankılanıp durdu ara vermeden.
Hangi dili öğreniyordum?
Mutluluk
İki tek ağustosu çarpıştıran
Sızdıran kanını bu yaz
gününe
Yaşayan bir mutluluk? Ve işte
kaç yerinden kesilmiş ki ellerim
Bekletip durdu da acısını
bunca yıl
Şimdi bir gülümseme gibi sindi
yüzüme.
Görmüşüm daha önce de bir
Lidya kralının boynunda
Bilmekti yazgısını ölümünü,
gene de
Yıllarca beklemişti kendini
Yeşimden sapı olan bir
kılıçla
Bense ne içimi yakan rüzgarı
Ne denizdeki yangını, ne
gökgürültüsünü
Duymuş gibi olduğum sesleri de
değil
Yaşamın gövdesini arıyordum
yalnızca
Bir çürük dişle alnımdaki
İki üç kırışığı yedeğine
takmış da.
Özledim ilkelliğimi
dalgalarında
Buldum savaşı bitmez
derinliklerini
karıştırdıkça bir kargının
ucuyla
Gördüm, bekliyordu kendini de o
da
Germiş de al kıskacını Lidya
kıralı gibi
O turuncu ruh, değişken
İzledim onda ilk oluşumu sanki
Hafifçe kesilmiş gibi oldu
dudağım bir yerinden.
İşledim payıma düşen her
görüntüyü
Kamaştı gözlerim kıyıya
varınca
Rüzgarın itişiyle kumlarda
Durmadan yer değiştiren
Sayısız siren iskeleti
Çın çın ötüyordu sessizlik
kaburgalarında
Dedim, besbelli başıboş
bırakmışlar da korkuyu
Tarihin onlara bağışladığı
Bu garip raslantıdan
Doğma bir rahatlıkla
parıldıyorlar şimdi
Kemikleri som altından.
Sığındım çatısına bu yok
olmuş şehrin.
Şehir ki herkesin bir şehir
düşündüğü gibiydi
Tanrım! tunç bir kapı kilidi
Bronz bir sokak
Kumlar içindeydi. Ve bu çakıl
taşı
Kimbilir kimin külrengi kalbi
Tanrım!
Neden herkes başka tarafa
bakıyor
Neden herkes başka biriydi.
Yıkıntılardan geçtim, eski
mezarlardan
Şimdi artık bir anımsamada yeri
olmayan
Arı kümeleri taşların
arasında
Ve yukarıda kuşlar yanmış
kağıt parçaları gibi
Uçuşuyordu da
Ağır ağır yanıyordu da şehir
Yanmayan kadınlar gördüm
Nasıl görünürse dünya
gözyaşının altından
Tam öyle, dönüp duruyorlardı
bu cehennem oyununda
Ve büyümeyen adamlar gördüm,
hiç şaşırmadım.
Konuşuyorlardı sırayla, ilgisiz
Ağaçlara asılmışlardı bir
yandan da
Bir kapı kirişine
asılmışlardı ve ufka
Ölüm müydü konuştukları?
Ölümdü anlaşılan
Silince bir aynayı çıkıveren
karşılarına
Bir ölümdü ki, işte bir muska
asılı dururdu duvarda
Bir büyü gösterilirdi
Bir kuyu sezdirilirdi
Hiç yoktan bir zincir
boşalırdı avluda.
Akşam geri verince bana
gözlerimi
Şehir de kayboldu, denizin
durgunluğu da
Bir anka kuşu yeniden karıyorken
küllerini
Bir kaya oyuğu kendini
alıştırıyorken boşluğa
Dedim, deniz de bendim, düşleyen
de denizi
Ve sabah olur olmaz üstünde
derinliğimin
Bir gülümseme gibi bulacağım
kendimi.', 'Gerçekte duymadığım sesler bitti Öğleye doğru bir gökgürültüsü yalnız Karıştırdı ortalığı bir süre Gök akıttı bir parça yağmurunu Ve deniz k...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip_cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":143}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇÖL VE SORULAR', 'col-ve-sorular-hi-lmi-yavuz-wh8cu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kimbilir nereden gelirim?
soldu tenimde büyü;
yıkasam çıkmıyor kirim;
gövdem otuz kuşun tüyü;
atsam içimden örtüyü;
sayrıya benzerdi dirim.
neden böyle acıyor etin?
sen Çöl''le Kitab''ın arası;
heybende incir ve zeytin;
hani nerde çarmıh yarası?
çöl sarsıldı, çöl sarası
tutuyor gülünü mahremiyetin.
o çiviyi çakan kim?
ve benim çarmıhım kimde?
ne Söz''üm ben, ne de Dil''im...
kalbim en büyük gerilim;
niye ben çarmıhta değilim,
çarmıh benim içimde?', 'kimbilir nereden gelirim? soldu tenimde büyü; yıkasam çıkmıyor kirim; gövdem otuz kuşun tüyü; atsam içimden örtüyü; sayrıya benzerdi dirim. ...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇÖL ÖYKÜSÜ', 'col-oykusu-hi-lmi-yavuz-jmmy2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''çöl'' denilen o öyküsü
yazmak için konuşurken
sustum içimdeki türküyü...
anlasın doğan gün seni:
bir aşk ötekinden mi kalır?
âh, şiirin altın tüyü!...
hangi yalnızlık kapatır beni
var mıdır iyi bir gül, ki kovsun
o yazın içindeki ''kötü''yü?', '''çöl'' denilen o öyküsü yazmak için konuşurken sustum içimdeki türküyü... anlasın doğan gün seni: bir aşk ötekinden mi kalır? âh, şiirin altı...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜ', 'olu-fazil-husnu-daglarca-m19uq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hangi mahallede imam yok,
Ben orada öleceğim.
Kimse görmesin ne kadar güzel,
Ayaklarım, saçlarım ve her şeyim.
Ölüler namına, azade ve temiz,
Meçhul denizlerde balık;
Müslüman değil miyim, haşa,
Fakat istemiyorum, kalabalık.
Beyaz kefenler giydirmesinler,
S��zlamasın karanlığım havada.
Omuzlardan omuzlara geçerken sallanmayayım,
Ki bütün azalarım hülyada.
Hiçbir dua yerine getiremez,
Benim kainatlardan uzaklığımı.
Yıkamasınlar vücudumu, yıkamasınlar,
Çılgınca seviyorum sıcaklığımı...', 'Hangi mahallede imam yok, Ben orada öleceğim. Kimse görmesin ne kadar güzel, Ayaklarım, saçlarım ve her şeyim. Ölüler namına, azade ve temiz...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca.']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca.","poet_slug":"fazil_husnu_daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LALELİ', 'laleli-orhon-murat-ariburnu-qwx6t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Lalelim
Lalelide oturur
Laleli lale olur lalelimden.
Laleliden geçilir
Lalelimden geçilmez!..', 'Lalelim Lalelide oturur Laleli lale olur lalelimden. Laleliden geçilir Lalelimden geçilmez!.....', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Ariburnu']::text[], 8.5, '{"poet":"Orhon Murat Ariburnu","poet_slug":"orhon_murat_ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LAMİA', 'lami-a-bayram-balci-dnzqe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I.
damarında siyanür dolaşıyor şehrin
aşk bizden güçlü. bizden uzak
cinnetli bir cinayet saklı gelen her günde
eksiliyor bizim olan zaman. kederli sarsak
ben öyle uzak durmayı bilmezdim
insanlar geçerdi kalbimden
acıtarak düşlerimi geçerdi
bakır bir sürahide kanardım
iflah olmaz gençliğimi
gölgesi vuruyor şimdi sağılmayan bir yaranın
yalnızlığın üstüne uzak bir şarkı gibi düşüyor
kalbi kanıyor şehirlerin lamia
avucuma akan sudan anlıyorum bunu
bilmezdim ben sofraya erdemle gelen ekmek gibi
uzak durmayı sevdiğim şehirlerden
II.
sana hayatı tutsak alan acılardan söz ediyorum
adli tıp morglarına takılı kelebekşarkısı
dalından koparılan yaprakağrısı
sana yüzünü dağlara dönmüş hayattan sözediyorum
şehir sansartuzağı kondular ağıt halkotobüsleri üryan
sabah felaketlerle çalıyor kapıları
kadavrasız yaşamın çağıldayan sevdası
aşk bana kahır lamia. bana serkeş
sana oğlu kaybedilmiş bir annenin acısıyla sesleniyorum
ben ölürüm lamia
nefes alarak kalbim çarparak
şehrin belleğini zonklatarak ölürüm
salgın vebadır şehre kayıpoğulsancısı
bitirim mahçup gayriresmi
yıkar tahtını saltanatın
korku öde çığlık anamın sancısına karışır
ben yeniden doğarım lamia
bir avuç et üç gram kanpıhtısı
sonrasız canhavli
çağötesinden kalma bir fosilim
anamın evlat deyip bağrına bastığı
III.
çocuk yanıma tetik çekiyor hayat
her sabah başka yerimden vuruluyorum
uyumsuzluğun kahredici sessizliği
şehirler teslim alınmış lamia
aşka ayakbağı şehirler
ankara: yürüyen bir sürgün salyangoz burunlu
sıvas: yüreğimin tuncunu eriten yangın
istanbul: iki yakası biraraya köprülerle getirilen zavallı
ne verebilir ki hayata karavana yaptıran bir aşka
ben sabahı vuran sürmanşet haberim lamia
&quot;teslim ol çağrısına&quot; aşkla karşılık veren
adını kurşunkırığı camlara çizen
dilinin ucunda patlayan ateşim
dağla kuşanmış bir bildiri gibi
parçalanırım şehrin koynunda
IV.
benim aşk dediğim lamia. aşk bildiğim
bombalar arasında yiten
tozbulutlarının taneciklerindeki günışığı
dağın koynundan kopup gelen
rahmine akıp giden ateştohumu
kefensiz gömütsüz meçhul denizler kervanı
benim aşk dediğim aklı çürüten tez
dağdan kopan ezgi
ben bir deprem uğultusuyum lamia
yağmurlu bir kırlangıç kanadı
kaynağını arayan ırmak
semah duran turnadirenci
inerim birgün şehrin koynuna
gecenin yıldızını koparan sabahın ilkışığı gibi
şehrin cenderesinde yangınlara sarılmış bir annenin
ateşli yüreği gibi inerim
yakarak yokluğun acısını
sığmaz şehre içimden kopan fırtına
çünkü aşk değil bu lamia. herşeydir
parçalanır şehrin rutinağrısı sel olurum
oyunlarda unutulmuş afet bir çocuk
varoşlardaki delikanlılığın vitrine vuran hıncı
gençkızların kitabaralarında kuruttuğu falpapatyası
sabahına kahır düşmüş kalpağrısı
devinen ve kirlenen bir yalnızlıktır şehirkalabalığı
acılarını bas yarama lamia. yoksa vurur beni de
aşka kasdeden bu çaresiz hayat
V.
sana sabahın sisini kalbine sarıp şehri süpüren
genç bir çöpçünün aklından geçirdiklerini sesleniyorum
hergün dolup boşalan sırça bir okyanustur şehir dediğin
yağmursuz riyakar ölümkurusu
ah... lamia
sen umuttan daha güzel şeyler de olduğunu öğrenemedin
dolarla markla tercüme ediliyor yaşam sanılan yanılsama
artık aşkını leylekler kanatır senin
diplomatik ihanetlerde ziyan olur bahar
dellenmiş bir tetikçi düşürür korkusunu şehrin ihanet dolu avuçlarına
lamia... güzelim aşkarasında unutulmuş gültadım
şehri kuşatan hayatın gücü erişmez aşkın doruklarına
zehir bir hançerdir saklı durur yaranda
ağla...ağla... ağla
karışsın gözlerin dağların kıvrımlarında çoğalan tozkabarcıklarına
ben artık şehirlerde yaşayamam lamia', 'I. damarında siyanür dolaşıyor şehrin aşk bizden güçlü. bizden uzak cinnetli bir cinayet saklı gelen her günde eksiliyor bizim olan zaman. k...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":101}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LAR LER', 'lar-ler-kemal-ozer-yiknx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir o mu bırakmış yıldızlarını damlara
avutmaya çıkmış dağ başlarını
bir o mu silâhın çamurunda yatan
elinin parmakları yüreğine doğru
öldüğü gün kadar kimse güzel olmadı', 'bir o mu bırakmış yıldızlarını damlara avutmaya çıkmış dağ başlarını bir o mu silâhın çamurunda yatan elinin parmakları yüreğine doğru öldüğ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LAV', 'lav-enis-batur-m3c86', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akdenizli sesini seviyordu; geniş,
tuzlu gövdesini. Eğiliyor, kokluyor,
kadınlığını unutup içine girmek
istiyordu.
Akan, devinen bir düştü erkek:
Volkanın ortasında kıpırdıyordu', 'Akdenizli sesini seviyordu; geniş, tuzlu gövdesini. Eğiliyor, kokluyor, kadınlığını unutup içine girmek istiyordu. Akan, devinen bir düştü e...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LAVINIA İÇİN SONNET', 'lavinia-i-ci-n-sonnet-hi-lmi-yavuz-281ph', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sana da yas yaraştığı söylenir, öyle değil!...
birden bir dal kırılır, hani düşer ya suya,
sen o akarsusun...akma!...kendine eğil,
orda gördüğün dalı, ey solgun lavinia,
sanki tanır gibisin...belki eski yerinden
göçmüş bir yaz sözünde unutulan zakkumu
usulca büyüttündü, akarak ta derinden;
anımsa, öpüşlerdeki taşı, çakılı, kumu...
nerde bir yaz olduysa o dalı taşır şimdi;
ah! al götür, al götür...bırakma bir kuytuda;
sen onu bıraktıkça ona yaraşırım şimdi
yas...ansızın köpüklerle sevişen bir duyguda...
kırık...o yaz aynalarda durulsun diye güyâ
sana yas değil elbet, yaz yaraşır lavinia...', 'sana da yas yaraştığı söylenir, öyle değil!... birden bir dal kırılır, hani düşer ya suya, sen o akarsusun...akma!...kendine eğil, orda görd...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LAVİNİA', 'lavi-ni-a-ozdemir-asaf-pd2oa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana gitme demeyeceğim
Üşüyorsun ceketimi al
Günün en güzel saatleri bunlar
Yanımda kal
Sana gitme demeyeceğim
Gene de sen bilirsin
Yalanlar istiyorsan yalanlar söyleyeyim
İncinirsin
Sana gitme demeyeceğim
Ama gitme Lavinia
Adını gizleyeceğim
Sen de bilme Lavinia', 'Sana gitme demeyeceğim Üşüyorsun ceketimi al Günün en güzel saatleri bunlar Yanımda kal Sana gitme demeyeceğim Gene de sen bilirsin Yalanlar...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir_asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇÖLDE SUSSUZ KALMIŞ', 'colde-sussuz-kalmis-yusuf-altunel-etr2r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'havada yeniye başlamanın kokusu
toprakta telaşla çözülen su gibi yüzün
zeytin ağaçlarından firari kara gözlerin
yüreğim çılgın atlardan hızlı
pençelerini kapatmış uslu bir kediyim
avuçlarında kavuşmaları yakaladığımdan beri
çölde sussuz kalmış deliyim
gel ey duru bakışlım
fırtınalı denizlerde limanım ol
sakin koylarında demir atayım
yeni kıtalar saklı gözlerin
bir soluk dinlenip koynunda
okyanuslar açayım
kömür karası saçlarına
devrimden güller tak
çocuksu yüzünde
taze günün ışınlarını saçarak
çöllerine direnç kervanları sürmeliyim
damla damla süzüp sabır taşından seni
dudakların vahasından aşk iksiri içmeliyim
gel ey sevgili
çölde susuz kalmış bir deliyim', 'havada yeniye başlamanın kokusu toprakta telaşla çözülen su gibi yüzün zeytin ağaçlarından firari kara gözlerin yüreğim çılgın atlardan hızl...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇÖLDE YALNIZ', 'colde-yalniz-hi-lmi-yavuz-2dird', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çöl saydamdır, güz de...
herşey o kadar üstüste
ki yalnızlık kime bindi bilmiyoruz!
kimine kat kat kumaş ve biniş.
çöl bir imâ idi, güz bir serzeniş;
ve önümüzde
geçen aşklar, duran aşklar!
onlar da üstüste top top ve belki
bir aşkı mı taşıyordur öteki?
öyle ki, var Zaman, her sözümüzde...
bak a yalnızlık, kim bu teni
sana ısmarladı?
bu harap kumaşla böyle nereye?
âh, kağşamış bu teni sen
hangi divâneye
giydirdin de yüzünü açtı aynalar?
ve yüzümüzde
hangi aynanın izi kaldı; -ve niye?
âh, sır bitti, sır bitti, eriye eriye!', 'çöl saydamdır, güz de... herşey o kadar üstüste ki yalnızlık kime bindi bilmiyoruz! kimine kat kat kumaş ve biniş. çöl bir imâ idi, güz bir ...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLDÜRME ÖZGÜRLÜĞÜ', 'oldurme-ozgurlugu-yevgeni-yevtusenko-1gaiq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlük Anıtı''nın rengi şimdi
Bir ölümcül donuklukla eşittir
Kurşunlandı özgürlük, onun sevgili adı
Sandı alındı bağımsızlığı geri -
Amerika, kendi kendini vuran!
Tam da öyle işte, kendi kendini!
Sıkıysa çık dışarı bu korkulu
Her taşına kâbuslar sinen ülkede
Ve daha korkuncu bu gidişle
Ormanlara kaçıp gizlenmek sonu.
Toprakta o bildik koku
Şu evrensel ünü olan Dallas''tan,
Yaşamak nasıl da tekinsizlik dolu
Ve işte senin en büyük utancın bu.
Kim inanır masallara, hangi çağdayız
O soylu fikir zevahirinin ardından
Silah yağının fiyatı yükselirken
Yaşamın düşürdüğün bedeline bak sen!
Katillerdir cenazende yas tutanlar da
Hissedar olmaya her karış toprağına
-İşte yine, bir daha, hadi bir daha-
Başaklarında kurşun tanelerinin
Dalgalandığı Teksas tarlalarına.
Şapkalarının altında haince
Tarıyor gözleri karanlığı
Senin o katil çetelerinin
Tutmuşlar her kapıyı
Ve işte cesedi bir ikinci Kennedy''nin...
Amerika nedir bu, oğullarını koru!
Ve çocukları, başka ülkelerdeki
Ve onların kulübelerini küle döndüren
Yakıyor tıpkı onlar gibi, ateş ve bombaların
İnsan hakları bildirini senin de.
Bilinci olmaya söz verdiydin dünyanın
Şu hale bak, dipsiz utancın kıyısında
Vurduğun, kral değil sözündür
Onurundur, Vietnam''a attığın her bombada.
Bir ulus çıldırıyorsa, yaptıklarını
Mümkün müdür kınamak el kadar
Üstünkörü barış sözleriyle.
Tek yol senin için yine utançtır
Tarih çamaşırhanede aklanmaz ki
-Yok henüz, keşfedemedin
Böyle bir çamaşır makinesini-
Kan hiç paklanır mı Amerika!
Nerendedir Amerika utancın senin
Söyle nerede saklı o
Sanki kaçan bir köle
Kölelerin içinde.
Tut ki Raskolnikov''dur dolaşan baştan başa
Deliliğin kanlı baltası elinde
Kendisini yine kendi yargılayan
Planlı katliamlarıyla
Canilerden geçilmiyorsun Amerika.
Hey Abe, iyi ihtiyar
De bana ne yapıyor ülkendeki insanlar?
Kaçıncıdır sıralıyor tek bir gerçeği:
Anlaşılır ancak kesildiğinde
Yüce bir ağacın yüceliği.
Lincoln oturuyor güneşe karşı
Mermer sandalyesinde kanayarak.
Aslında odur canavarların
Bu kaçıncı kez vurduğu.
İşte o kurşun delikleridir
Amerika
Yıldız diye koydukların da
bayrağına.
Urbası kurşunlarla lime lime
Özgürlük Anıtı, ey sen
O kadın, o ana yüreğinle
Kaldır başını ölümlerden
Aç ağzını, yum gözünü
Toptan lanetle bu
Kahrolası öldürme özgürlüğünü.
Hey Özgürlük Anıtı, sen, kaldır şu
Yeşile kesmiş yüzünü boğulduğun kandan
Kafa tut özgürlüğün cellatlarına
Ve ama alnından artık
Bir damla kan akıtmadan.
1968
Yevgeni  YEVTUŞENKO', 'Özgürlük Anıtı''nın rengi şimdi Bir ölümcül donuklukla eşittir Kurşunlandı özgürlük, onun sevgili adı Sandı alındı bağımsızlığı geri - Amerik...', ARRAY['Türk Edebiyatı','Şiir','Yevgeni  Yevtuşenko']::text[], 8.5, '{"poet":"Yevgeni  Yevtuşenko","poet_slug":"yevgeni_yevtusenko","theme":"Türk Şiiri","is_hero":false,"total_lines":83}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLDÜRMEYECEKSİN', 'oldurmeyeceksi-n-necati-cumali-b1npc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '&quot;Asla öldürmeyeceksin&quot;
Tevrat, Göç 20
&quot;Senden önce inenlere, sana inen kitaba da inanırlar...Onlar
Tanrının gösterdiği doğru yoldadır, onlar kurtulurlar...&quot;
Kur''an, Bakara Suresi
Dinlerin buyruğuydu
Öldürmeyeceksin
Tapınaklarda çaktılar çarmıhları
Elleri kanlı camilerden çıktılar
Kalem kırdılar yargı yerlerinde
Peygamberlerini dinlemediler
Kudurgan dalgalar
Tekneleri yutar denizlerde
Çöllerden esen yeller
Ekinleri kurutur
Bil ki umut yeşildedir
Yenilmeyen yeşilde
Benim küçük serçem
Kanaryam bülbülüm
Kuru dal çalı diken
Konmuş ötersin
Öt sen, öt, kardeş sesin
Sulara rüzgârlara karışsın
Zalim ürksün sağır işitsin
Öldürmeyeceksin!', '&quot;Asla öldürmeyeceksin&quot; Tevrat, Göç 20 &quot;Senden önce inenlere, sana inen kitaba da inanırlar...Onlar Tanrının gösterdiği doğru ...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇİLE', 'ci-le-necip-fazil-kisakurek-3ue3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gaiblerden bir ses geldi: Bu adam,
Gezdirsin boşluğu ense kökünde!
Ve uçtu tepemden birdenbire dam;
Gök devrildi, künde üstüne künde...
Pencereye koştum: Kızıl kıyâmet!
Dediklerin çıktı ihtiyar bacı!
Sonsuzluk, elinde bir mâvi tülbent,
Ok çekti yukardan, üstüme avcı.
Ateşten zehrini tattım bu okun,
Bir anda kül etti can elmasımı.
Sanki burnum, değdi burnuna "yok"un,
Kustum öz ağzımdan kafatasımı.
Bir bardak su gibi çalkandı dünyâ;
Söndü istikamet, yıkıldı boşluk.
Al sana hakikât, al sana rûyâ!
İşte akıllılık, işte sarhoşluk!
Ensemin örsünde bir demir balyoz,
Kapandım yatağa son çâre diye.
Bir kanlı şafakta, bana çil horoz,
Yepyeni bir dünyâ etti hediye.
Bu nasıl bir dünyâ, hikâyesi zor;
Mekânı bir satıh, zamânı vehim.
Bütün bir kâinat muşamba dekor,
Bütün bir insanlık yalana teslim.
Nesin sen, hakîkat olsan da çekil!
Yetiş körlük, yetiş, takma gözde cam!
Otursun yerine bende her şekil;
Vatanım, sevgilim, dostum ve hocam!
.
.
.
.
Aylarca gezindim, yıkık ve şaşkın,
Benliğim bir kazan ve aklım kepçe.
Deliler köyünden bir menzil aşkın,
Her fikir içimde bir çift kelepçe.
Niçin küçülüyor eşyâ uzakta?
Gözsüz görüyorum rûyâda, nasıl?
Zamânın raksı ne, bir yuvarlakta?
Sonum varmış, onu öğrensem asıl?
Bir fikir ki, sıcak yarada kezzab,
Bir fikir ki, beyin zarında sülük.
Selâm, selâm sana haşmetli azâb;
Yandıkça gelişen tılsımlı kütük.
Yalvardım: Gösterin bilmeceme yol!
Ey yedinci kat gök, esrârını aç!
Annemin duâsı, düş de perde ol!
Bir asâ kes bana, ihtiyar ağaç!
Uyku kaatillerin bile çeşmesi;
Yorgan, Allahsıza kadar sığınak.
Tesellî pınarı, sabır memesi;
Size şerbet, bana kum dolu çanak.
Bu mu, rûyâlarda içtiğim cinnet,
Sırrını ararken patlayan gülle?
Yeşil asmalarda depreniş, şehvet;
Karınca sarayı, kupkuru kelle...
Akrep, nokta nokta rûhumu sokmuş,
Mevsimden mevsime girdim böylece.
Gördüm ki, ateşte, cımbızda yokmuş,
Fikir çilesinden büyük işkence.
.
.
.
.
Evet, her şey bende bir gizli düğüm;
Ne ölüm terleri döktüm, nelerden!
Dibi yok göklerden yeter ürktüğüm,
Yetişir çektiğim  mesâfelerden!
Ufuk bir tilkidir, kaçak ve kurnaz;
Yollar bir yumaktır, uzun, dolaşık.
Her gece rûyâmı yazan sihirbaz,
Tutuyor önümde bir mavi ışık.
Büyücü, büyücü, ne bana hıncın?
Bu kükürtlü duman, nedir inimde?
Camdan keskin, kıldan ince kılıcın,
Bir zehirli kıymık gibi, beynimde.
Lûgat, bir isim ver bana halimden;
Herkesin bildiği dilden bir isim!
Eski esvablarım, tutun elimden;
Aynalar, söyleyin bana, ben kimim?
Söyleyin, söyleyin, ben miyim yoksa,
Arzı boynuzunda taşıyan öküz?
Belâ mîmârının seçtiği arsa;
Hayattan muhâcir; eşyâdan öksüz?
Ben ki, toz kanatlı bir kelebeğim,
Minicik gövdeme yüklü Kafdağı,
Bir zerreciğim ki, Arş''a gebeyim,
Dev sancılarımın budur kaynağı!
Ne yalanlarda var, ne hakîkatta,
Gözümü yumdukça gördüğüm nakış.
Boşuna gezmişim, yok tabîatta,
İçimdeki kadar iniş ve çıkış.
.
.
.
.
Gece bir hendeğe düşercesine,
Birden kucağına düştüm gerçeğin.
Sanki erdim çetin bilmecesine,
Hem geçmiş zamânın, hem geleceğin.
Açıl susam, açıl! Açıldı kapı;
Atlas sedirinde Mâverâ Dede.
Yandı sırça saray, İlâhî Yapı,
Binbir âvizeyle uçsuz maddede.
Atomlarda cümbüş, donanma, şenlik;
Ve çevre çevre nûr, çevre çevre nûr.
İçiçe mîmârî, içiçe benlik;
Bildim seni ey Râb, bilinmez meşhûr!
Nizâm köpürüyor, med vakti deniz;
Nizâm köpürüyor, tâ çenemde su.
Suda bir gizli yol, pırıltılı iz;
Suda ezel fikri, ebed duygusu.
Kaçır beni âheng, al beni birlik!
Artık barınamam gölge varlıkta.
Ver cüceye, onun olsun şâirlik,
Şimdi gözüm, büyük sanatkârlıkta!
Öteler, öteler, gayemin malı;
Mesâfe ekinim, zaman mâdenim.
Gökte saman-yolu benim olmalı!
Dipsizlik gölünde, inciler benim.
Diz çök ey zorlu nefs, önümde diz çök!
Heybem hayat dolu, deste ve yumak.
Sen, bütün dalların birleştiği kök;
Biricik meselem, Sonsuz''a varmak...', 'Gaiblerden bir ses geldi: Bu adam, Gezdirsin boşluğu ense kökünde! Ve uçtu tepemden birdenbire dam; Gök devrildi, künde üstüne künde... Penc...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":126}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇİLEŞKİ', 'ci-leski-sevgi-kose-qbeh8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ölü gerçek diri düş arası gelgitlerinde
gelip gitmeler, gidip gelmeler...
üçüncü bir olasılıkla yırtılıyor
düşle gerçeği ayıran perde
tetik parmağım seyriyor
üç ayaklı demir çelişkiyi alıp sudan
açsam da yelkenlerimi
ah! rotası şaşmış aklım benim
dümeni kırık kalbim...
gitsem
şiirler çekilecek damarlarımdan
ters akacak denize hasret ırmak
tikle tak arsına sıkışacak
sevgi sözleri. düşler
kapalı kapılardaki yırtık
tek kollu matadoru olacağım
iki uyku arası ömrümün...
kalsam
devrik imgelerle eğrilmiş bir şiirin
son mısrasından tırmanabilirsek yukarı
yüzümüzdeki harita yol gösterecek
yanağındaki uçurumdan düşeceğiz sonra
kanla karışık yağmurlardan
kanatlarımızı kurtarabilirsek
yaralı ele geçireceğiz yaşamı
tetik parmağım hala seyrimekte
ah! düşe açık bir midye kabuğunun
içinde kalabilseydim keşke', 'ölü gerçek diri düş arası gelgitlerinde gelip gitmeler, gidip gelmeler... üçüncü bir olasılıkla yırtılıyor düşle gerçeği ayıran perde tetik ...', ARRAY['Türk Edebiyatı','Şiir','Sevgi  Köse']::text[], 8.5, '{"poet":"Sevgi  Köse","poet_slug":"sevgi_kose","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLEN ÖMER''İN KARISININ AĞIDI', 'olen-omer-i-n-karisinin-agidi-necati-cumali-bepqq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evimizin önü dere kenarı
Dere kenarında ak kavakları
Ömer''im dikti
Evimizden dereye inen yolu
Ömer''im açtı.
Ömer''im aşladı avlumuza
Itırı, fesleğeni, katmeri
Yıllar yılı
Ömer''in yüzü gülerse
Ocağımız tüter, gazımız yanarsa
Kavaklar bayram eder,
Ömer''im sıkkın
Mahsul kötü, eli dar unumuz kıtsa
Kavaklar kararır giderdi.
Yıllar yılı
Eve girsem yüzüme Ömer''in nefesi değer
Avluya çıksak yan yana akşamları
Bir hoş kokardı, ıtır, fesleğen, katmer.
Bakamam incecik dere yoluna!
Bakamam ak kavaklara!
Penceremden kapımdan
Güne bakamam! aya bakamam
Gayri eve girsem içim ezilir
Avluya çıksam
Itır, fesleğen, katmer kokusu
Bana haram!', 'Evimizin önü dere kenarı Dere kenarında ak kavakları Ömer''im dikti Evimizden dereye inen yolu Ömer''im açtı. Ömer''im aşladı avlumuza Itırı, f...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LEVNİ', 'levni-aydin-hati-poglu-g7qm6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şeyin bir rengi vardır bilirsiniz
Özgürlüğün rengini bilir misiniz ya umudun
Korkuya boyanmasın yüzünüz
Bulaşmasın yılgınlığın karası üstünüze
Sevincin rengini hatırlayın bir
Hatırlayın çocukluğun şeker pembesini
Delikanlı günlerin nar çiçeğini
Hayata ısındığımız turuncuyu ve şehveti
Sonra kızılın hüzne karıştığı yer
Şimdi uzak bir ülkedir nefti hiç gidilmeyen
Sarı sarhoştur daima ve yılgındır hep
Durmadan tükenmenin şarkısını söyler
Eski bir sevda yaşar limonküfünde
İncecik bir sızı yayılır damarlara
Sessizce sezersiniz haki ölümün rengidir
Hüznün rengini biliriz zulmün rengini
Kahrın rengini biliriz adımız gibi
Adımız gibi biliriz inancın rengini', 'Her şeyin bir rengi vardır bilirsiniz Özgürlüğün rengini bilir misiniz ya umudun Korkuya boyanmasın yüzünüz Bulaşmasın yılgınlığın karası üs...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LEYLÂ', 'leyl-kemal-ozer-hymjv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'taşlığına uzanmış zayıf terliklerinin leylâ
ay gibi leylâ gibi ay gibi leylâ
arkası budala memeleri orta budala
kimsenin kimseye git demediği leylâ
inmiş yukardan kirlenmiş ağızları yangında
yeninin yeni olan gözlerine sokulgan
ayakları adımlı saçları taşkın sokulgan
vardıkça leylâ soğuklara seğirten adamlar
her biri bir başka günle karşı duvarda
gözlerine kadar yorgun adamlar
gözleri ne kadar yorgun adamlar', 'taşlığına uzanmış zayıf terliklerinin leylâ ay gibi leylâ gibi ay gibi leylâ arkası budala memeleri orta budala kimsenin kimseye git demediğ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LEYLAKLARINI ANLATIYORUM', 'leylaklarini-anlatiyorum-rifat-ilgaz-evlcr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Leylak getiriyorsun bana güneşli bir gün
Onu saçlarından topladığın belli
Bir leylak bahçesisin karşımda
Böyle kucağında kalsa daha iyi
Bir vazoya bırakıp gidiyorsun
Sen gidiyorsun leylaklar kalıyor mu sanki
Önce renkleri gidiyor arkandan
Nesi varsa gidiyor soyunarak
Her vazoya baktıkça karşımdasın ne tuhaf
Her kokladıkça dönüp dönüp geliyorsun
Düşünceler gibi filizleniyorsun gün geçtikçe
Yaprak yaprak gelişiyorsun
Leylak leylak bakıyorsun gözlerimin içine
Ölümsüz bir mevsim oluyorsun
(1961)
Soluk Soluğa adlı şiir kitabından 1962
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Leylak getiriyorsun bana güneşli bir gün Onu saçlarından topladığın belli Bir leylak bahçesisin karşımda Böyle kucağında kalsa daha iyi Bir ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LEYLİM LEY', 'leyli-m-ley-sabahattin-ali-r873y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Döndüm daldan kopan kuru yaprağa
Seher yeli dağıt beni, kır beni
Götür tozlarımı burdan uzağa
Yarın çıplak ayağına sür beni
Ayın şavkı vurur sazım üstüne
Söz söyleyen yoktur sözüm üstüne
Gel ey hilal kaşlım dizim üstüne
Ay bir yandan sen bir yandan sar beni
Yedi yıldır uğramadım yurduma
Dert ortağı aramadım derdime
Geleceksen bir gün düşüp ardıma
Kula değil, yüreğine sor beni', 'Döndüm daldan kopan kuru yaprağa Seher yeli dağıt beni, kır beni Götür tozlarımı burdan uzağa Yarın çıplak ayağına sür beni Ayın şavkı vurur...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali̇']::text[], 8.5, '{"poet":"Sabahattin Ali̇","poet_slug":"sabahattin_ali","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LEYLİM LEYLİM', 'leyli-m-leyli-m-fikret-kizilok-eqqiq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kara tren katar katar
Derdime derdini katar
Kimi alır kimi satar
Senin aşkın bana yeter
A leyli leyli
Ayrılık ölümden beter
A leyli leyli
İndim pınarın başına
El ettim dudu kuşuna
Dedi uğraşma boşuna
Nazlı yarim ele gitmiş
A leyli leyli
Hasan emmi gelin etmiş
A leyli leyli
Çayır çimen koşa koşa
Vardım anamın yanına
Kardeş bacı hep bir olmuş
Hiçbirinin dilleri yok
A leyli leyli
Böyle aşkın dermanı yok
A leyli leyli', 'Kara tren katar katar Derdime derdini katar Kimi alır kimi satar Senin aşkın bana yeter A leyli leyli Ayrılık ölümden beter A leyli leyli İn...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kizilok']::text[], 8.5, '{"poet":"Fikret Kizilok","poet_slug":"fikret_kizilok","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLHAN İÇİN', 'i-lhan-i-ci-n-tali-p-apaydin-62xix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç bu kadar kararmadı gökyüzü
Hiç bu kadar kirlenmedi sular
İnsan insana bu kadar uzak değildi
Böyle kaçırmazdık birbirimizden gözümüzü
Küçük bir kız şimdi babasını sorar
Hadi yanıtlayın kızartıp yüzünüzü', 'Hiç bu kadar kararmadı gökyüzü Hiç bu kadar kirlenmedi sular İnsan insana bu kadar uzak değildi Böyle kaçırmazdık birbirimizden gözümüzü Küç...', ARRAY['Türk Edebiyatı','Şiir','Tali̇p Apaydin']::text[], 8.5, '{"poet":"Tali̇p Apaydin","poet_slug":"talip_apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLHAN''IN SON BEŞ GÜNÜ İÇİN FOTOĞRAFLAR', 'i-lhan-in-son-bes-gunu-i-ci-n-fotograflar-muzaffer-i-lhan-erdost-fs6qz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlhan gelir Türküler''le
Türküler''le biz elele
Güleriz güzel günlere
İlhan uzatmış kadehi
Güler gözlerinin içi
Çağıldar cümle sevinci
İlhan''la biz nezarette
Yanyana bir kanepede
Akar gündüz uçar gece
İlhan''ı gördüm düşüyor
Yanım ateşe düşüyor
Elim kolum yetişmiyor
İlhan''ı gördüm yaralı
Gözleri kandan hareli
Yüzü güllere çevrili
İlhan''ın paltosu kanlı
Alazlanmış tüter canı
Düşmüş omuzdan kolları
İlhan İlhan, İlhan İlhan
Sular çavlan kuşlar pervan
Gittin mi can gittin mi can', 'İlhan gelir Türküler''le Türküler''le biz elele Güleriz güzel günlere İlhan uzatmış kadehi Güler gözlerinin içi Çağıldar cümle sevinci İlhan''l...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer İlhan Erdost']::text[], 8.5, '{"poet":"Muzaffer İlhan Erdost","poet_slug":"muzaffer_ilhan_erdost","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LIBERTÉ', 'libert-paul-luard-dyg5a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sur mes cahiers d''écolier
Sur mon pupître et les arbres
Sur le sable sur la neige
J''écris ton nom
Sur toutes les pages lues
Sur toutes les pages blanches
Pierre sang papier ou cendre
J''écris ton nom
Sur les images dorées
Sur les armes des guerriers
Sur la couronne des rois
J''écris ton nom
Sur la jungle et le désert
Sur les nids sur les genêts
Sur l''écho de mon enfance
J''écris ton nom.
Sur les merveilles des nuits
Sur le pain blanc des journées
Sur les saisons fiancées
J''écris ton nom.
Sur tous mes chiffons d''azur
Sur l''étang soleil moisi
Sur le lac lune vivante
J''écris ton nom
Sur les champs sur l''horizon
Sur les ailes des oiseaux
Et sur le moulin des ombres
J''écris ton nom
Sur chaque bouffée d''aurore
Sur la mer sur les bateaux
Sur la montagne démente
J''écris ton nom
Sur la mousse des nuages
Sur les sueurs de l''orage
Sur la pluie épaisse et fade
J''écris ton nom
Sur les formes scintillantes
Sur les cloches des couleurs
Sur la vérité physique
J''écris ton nom
Sur les sentiers éveillés
Sur les routes déployées
Sur les places qui débordent
J''écris ton nom
Sur la lampe qui s''allume
Sur la lampe qui s''éteint
Sur mes maisons réunies
J''écris ton nom
Sur le fruit coupé en deux
Du miroir et de ma chambre
Sur mon lit coquille vide
J''écris ton nom
Sur mon chien gourmand et tendre
Sur ses oreilles dressées
Sur sa patte maladroite
J''écris ton nom
Sur le tremplin de ma porte
Sur les objets familiers
Sur le flot du feu béni
J''écris ton nom
Sur toute chair accordée
Sur le front de mes amis
Sur chaque main qui se tend
J''écris ton nom
Sur la vitre des surprises
Sur les lèvres attentives
Bien au-dessus du silence
J''écris ton nom
Sur mes refuges détruits
Sur mes phares écroulés
Sur les murs de mon ennui
J''écris ton nom
Sur l''absence sans désirs
Sur la solitude nue
Sur les marches de la mort
J''écris ton nom
Sur la santé revenue
Sur le risque disparu
Sur l''espoir sans souvenirs
J''écris ton nom
Et par le pouvoir d''un mot
Je recommence ma vie
Je suis né pour te connaître
Pour te nommer
Liberté.', 'Sur mes cahiers d''écolier Sur mon pupître et les arbres Sur le sable sur la neige J''écris ton nom Sur toutes les pages lues Sur toutes les p...', ARRAY['Türk Edebiyatı','Şiir','Paul  Éluard']::text[], 8.5, '{"poet":"Paul  Éluard","poet_slug":"paul_eluard","theme":"Türk Şiiri","is_hero":false,"total_lines":87}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK GÜNÜN ARDINDAN', 'i-lk-gunun-ardindan-turgay-fi-sekci-ist18', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutluyum
Oturduğun semti
Ev arkadaşını öğrenmekten
Yaşını
İşlerini
Okulunu
Zamanı nasıl geçirdiğini
Hepsi düşündüğüm gibi çıktı
Uzaktan güzel bir çiçektin
Yanına geldim
Çiçekten bir insan gördüm
Yüzündeki beyazlık
Bahar sabahlarının ıslakçiği
Doğduğun kentin dağlarındaydı o saflık
Çamların dibinde açmış fulyaların yüzünde
Bir de sende gördüm
Gözlerinin derin göller gibi durduğu
Temiz
Beyaz
O insan yüzünde
Mutluyum
Bir saat karşında durup
Yüzüne bakabildiğime
Hayatta tek isteğim buydu
Mutluyum seni sevdiğime.
Turgay FİŞEKÇİ
---------------------------------------------------------------------------------------
“Karda Işıltılar” , 1981', 'Mutluyum Oturduğun semti Ev arkadaşını öğrenmekten Yaşını İşlerini Okulunu Zamanı nasıl geçirdiğini Hepsi düşündüğüm gibi çıktı Uzaktan güze...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK KISSA', 'i-lk-kissa-soysal-eki-nci-dme64', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırkına kadar ne aşk ne ölüm umrundadır insanın
Her şey hayvani bir intikam duygusuyla harcanır
Düşüncenin ince denizinden güneşe serilmemiş bedenler
Durmadan kendine sıcak bir yatak aranır
Kırkından sonra bütün ibadetler US''lu bir dost içindir
Her anı başka bir pişmanlıkla yaşanır
Ki soysuzlar aklanırken kamuda soylular karalanır', 'Kırkına kadar ne aşk ne ölüm umrundadır insanın Her şey hayvani bir intikam duygusuyla harcanır Düşüncenin ince denizinden güneşe serilmemiş...', ARRAY['Türk Edebiyatı','Şiir','Soysal Eki̇nci̇']::text[], 8.5, '{"poet":"Soysal Eki̇nci̇","poet_slug":"soysal_ekinci","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK NİŞANLI', 'i-lk-ni-sanli-mehmet-zaman-saclioglu-ew8h5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Suları kirletmeden yıkanır
Çıplak uzanır yanımıza
Kızlığını son soluğa saklayan
Eski nişanlımızdır zaman.
Genç yıllarımızın alışkanlığıydı
İnce rüzgârlara tutunurdu çiçekler
Hangi yanağı okşasak ay ışığında
Elimizde uyuyan kediydi zaman.
Kıyılmayıp torunlara saklanan
Sararmış çeyizlerde soluklanır
Biliriz oradadır ararsak
Bizimle uğraşmadıkça zaman.', 'Suları kirletmeden yıkanır Çıplak uzanır yanımıza Kızlığını son soluğa saklayan Eski nişanlımızdır zaman. Genç yıllarımızın alışkanlığıydı İ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK SEVGİLİLER', 'i-lk-sevgi-li-ler-g-rard-de-nerval-4a69d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerde bizi seven kızlar?
Hepsi kara topraklarda.
Daha şen daha gamsızlar;
Daha güzel bir diyarda.
Meleklerle beraberler,
Mavi semanın dibinde;
Meryem Ana''yı öğerler;
Coşkun ilâhilerinde.
Sen ey bembeyaz nişanlı!
Baharındaki bakire.
Sararmış, garip sevdalı,
Verip kendini kedere.
Gözlerimizde bir derin
Ebediyet vardı gülen.
Sönmüş ışıkları yerin,
Yanın göklerde yeniden.
Gérard De NERVAL', 'Nerde bizi seven kızlar? Hepsi kara topraklarda. Daha şen daha gamsızlar; Daha güzel bir diyarda. Meleklerle beraberler, Mavi semanın dibind...', ARRAY['Türk Edebiyatı','Şiir','Gérard De Nerval']::text[], 8.5, '{"poet":"Gérard De Nerval","poet_slug":"gerard_de_nerval","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK TÜRKÜ', 'i-lk-turku-afsar-ti-muci-n-44xbd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Otur da konuşalım
Gelmeyen bahardan
Sıcak uzun yazlardan
Yeşil rüzgârlardan
İki çift söz edelim
Otur da konuşalım
Olmadık mutluluklar biçip
Olmadık zamanlardan
İçimizde anlatılamayanı
Yarım kalan sevinci
Otur da konuşalım
Bu şehir kurtlar şehridir
Büyük korkaklar şehridir
Kuşkular kuyusudur
Açlık deliliğidir
Otur Ahmet kardeşim
Otur da konuşalım', 'Otur da konuşalım Gelmeyen bahardan Sıcak uzun yazlardan Yeşil rüzgârlardan İki çift söz edelim Otur da konuşalım Olmadık mutluluklar biçip ...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLK', 'i-lk-sezai-karakoc-2cyfs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlış trenden indin seni şehrin aynasından geçirdiler
Sana baktım yıllarca hep ayni özlem penceresinden
Yürüyen ve kaçan yalın ve çocuksu özlem penceresinden
Denize karşı küçüle küçüle giden evleri
İnce ince karşılardın olağan karşılardın
Şen dünya içinde şen dünya içinde bir avuç şen dünyaydın sen
Bahar bilgisi güneş rengi at soluğu ve sen
Seni çağırıyorum geç gel ağlayan son bâkireler içinden
Kadınlar taş heykeller gibi gelip geçer sarı kayalardan
Hangisine baksam sen kımıldar sen seslenirsin içerlerden
Çekil karşımdan sultanı cariyelerde aramak körlüğü diyorum
Körlük güneşe ve gözlerime doğru gelen
Sen bir el uzanışıyla aydınlanan yeni ay mısın
Geyik resimleriyle kabarık her köşen
Geyik derisinde akan ilk nehir
Bir el uzanışıyla
İlk sokağın ağzında kaybolursan ağlıyacağım
Leylâklarla akrepler gözlerine bakıp insan olurlarsa
Çocuk cennetinde günahların ilkini sen işliyorsun demektir Suna
Parlayan denizler gürültüsüz şiirler kapanan kapılar sana gök taşlarını getiriyorlar
Seni sayıklıyor
Denemesi yanlış yapılmış ilk ok', 'Yanlış trenden indin seni şehrin aynasından geçirdiler Sana baktım yıllarca hep ayni özlem penceresinden Yürüyen ve kaçan yalın ve çocuksu ö...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜLKESİ AĞIDİSTAN', 'ulkesi-agidi-stan-sukran-kurdakul-061rg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uykulardan sıçradığım her gece
Kuşku, doğasına yürüdü gerçeğimin.
Ya senin gözlerindeki ışık sönmüşse,
Ya damarlarımdaki kan donmuşsa benim
Ya da yangın sonrası bir orman
Gibi ıssız ve hüznüne alışık...
Ölümün rengine sözcükler arıyorsa şimdi
Ülkesi ağıdistana dönmüş bir ozan', 'Uykulardan sıçradığım her gece Kuşku, doğasına yürüdü gerçeğimin. Ya senin gözlerindeki ışık sönmüşse, Ya damarlarımdaki kan donmuşsa benim ...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜLKEYE DÖNÜŞ', 'ulkeye-donus-breyten-breytenbach-mxcos', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anne
düşünüyorum da
eve dönersem bir gün
habersiz sabahın erken saatlerinde dönerim
yılların birikimi zenginlikler
demir atların sırtında
her yer, her şey mavidir hâlâ
usulca açarım kapısını arka avlunun
yaşlı Wagter havlar
sonra sallar kuyruğunu beni tanıyınca
ipince bir keman çalacaktır Fritz Kreiser
nasıl da iyi bilirsin anne
bu havaların getirdiği Viyana valslerini
pencerelere toplanmaya başlayacak insanlar
belki de uzaktan uzağa
gülümseyerek eğilecekler gecelikleri içinde
dirsekleri bir zamanlar üzerinde tepindiğim dizleri üzerinde
içerde çatlarcasına atacak annenin kalbi
(peki gözlüklerim nerede?)
birden uyanacak rüzgârın sersemlettiği baba
ama anne çoktan dışardadır
sabahlığı içinde ve al aldır yanakları
Anne
düşünüyorum da tıpkı böyle olacağım
Noel sabahında bir melezler korosu gibi
ağlayacağımızı ve çay içeceğimizi düşünüyorum
anne.
Breyten BREYTENBACH', 'Anne düşünüyorum da eve dönersem bir gün habersiz sabahın erken saatlerinde dönerim yılların birikimi zenginlikler demir atların sırtında he...', ARRAY['Türk Edebiyatı','Şiir','Breyten Breytenbach']::text[], 8.5, '{"poet":"Breyten Breytenbach","poet_slug":"breyten_breytenbach","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLKİN', 'i-lki-n-turgut-uyar-4tlj1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bunu kimse söylemedi belki düşündü
çünkü vardır insanın yaşamasında
uyku ve öfke gibi vardır
kimse söylemedi
tuzunu çoğaltan bir denizde
nasıl batarsa güneş öyle
bende kaçırdım
ki gözüm bütün gün
günboyu lekelerde
kaçırdım ama şöyle de söylenebilir
şiirin bütün geçmişinin dışında
önceden açıklanan her şeyin dışında
örneğin en sıcak ülkelerin yazında
en soğukların kışında
yanarım üşürüm berbat olurum
hiç bir şeye yaramam
ama yinede seni severim
o zaman sende beni sev
evet', 'Bunu kimse söylemedi belki düşündü çünkü vardır insanın yaşamasında uyku ve öfke gibi vardır kimse söylemedi tuzunu çoğaltan bir denizde nas...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLKYARDIM BİLGİSİ', 'i-lkyardim-bi-lgi-si-temizyurek-li-mahmut-a-tvzj2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'temizyürek''li mahmut''a
bütün bir aşkyılı kapıştın siniruçlarınla
güneşe, kış geldiğinde yer açmak için
damarlarını ürküterek vücudunu dolaşan kanın
umurunda olmadı başka hayatları sürçmesi
cesaretin, alay konusu oldu
elini korkak alıştıranlar arasında
sen de cesur sandın onları
korkunu anlayacak kadar
göğüs kafesimdeki yetimim!
artık balmumu gibi keman yaylarına sürtüyorlar seni
sen ki hazırdın buna da:
jangarbarek milesdavis hacıtaşan ve yaylılar
bir bir boğulurken "bırakırsan ölürüm" gürültülerine
hazırdın sadece bir ses için aldanmaya
böylece dünya derin oyuklar açtı sende
kendi kalplerini bile stetoskopla dinleyenler
buna derinyara diyerek katkı yaptılar literatüre
ve güncelleşti ilk yardım çantası
gazetelerin eki olacak kadar
hem aşk, bazen sargı bezi olmanı ister üçüncü kişiye
bir başkasının doktoru olmak
kaldı ki en ciddi yoludur sağlığımızı korumanın
"neyin var" sorusunu ilk soran
bir bilen olur: kim ne kadar aşk ve güçten kalmış
kabul defteri açılır, kayıt yapılmış, gözlük camı buğulanmıştır
beyaz önlüklerin vilayetin önünde legale çıktığı bu saatlerde
tababetin temel bilgisidir, gözyaşlarını yeraltında tutmak
avucumuzun içinde oynadığımız iki taş bile ezebilir belki bizi
yine de her zaman huzur verir
psikiyatri kliniklerinde ziyaretçi olmak
çünkü acımak duygusu da bir haraç değil midir
bıçağı sapından tutmaya alışmış olanlar
ağzında yaşayanlardan bir armağan gibi alırlar bunu
gözler göstere göstere doldurulur
ve boşalır patlayan flaşlarla
patlar kalb
boşalır başını oraya koymuş doktor', 'temizyürek''li mahmut''a bütün bir aşkyılı kapıştın siniruçlarınla güneşe, kış geldiğinde yer açmak için damarlarını ürküterek vücudunu dolaşa...', ARRAY['Türk Edebiyatı','Şiir','Temizyürek''li Mahmut''a']::text[], 8.5, '{"poet":"Temizyürek''li Mahmut''a","poet_slug":"akif_kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLKYAZ TÖRENİ', 'i-lkyaz-toreni-huseyin-atabas-pxgbi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özlemler biriktiriyorum nicedir
yüzümü çevirip içtenliğin eski güneşlerine,
Eros''un bağbozumu sofrasında yüreğim.
Ah, böyle bir anda karıma inat
cenazeme gelse sevdiğim bütün kadınlar;
gözleri cıvıl cıvıl kuş seslerinden
çocuklar avluyu doldursa bana inat!..
Bir buluşma-buluşmama ikircimi içinde
üstelik herkes kendini arıyor olabilir o anda
"sen arama, ben buldum" teranesiyle.
Uykulara dalınınca bütün bir kış
ne bir ışık belirir sabahlar üzre,
ne bir sevgi, ne bir aşk;
belli, yaşam bir yalnızlıksa suç kimin!..
Ve dağlar duysa da duymasa da
delik delik deler geceleri
şairin kendini kanırtan sesi.
Sesler içinde suskun
yoksunluğun homurtusu posta trenleri
o sıra geçiyor olabilir bizim köyden.
Bir de cemre düşmeye görsün sevdalara
erkenci horoz olmaya yekinir de kalemim:
-Yaz, der, yaz;
bir daha bulamayabilirsin bu töreni.
Eskiden böyle düşünmezdi doğrusu
belleğim yanıltmıyorsa beni.
İmgelere nereden bulaştı bu hüzün peki,
bu geçmiş özlemi yüreklere, nereden?
Ey şair, hangi iklim hükmünde olursan ol,
başladığın eylemi sürdürmelisin!', 'Özlemler biriktiriyorum nicedir yüzümü çevirip içtenliğin eski güneşlerine, Eros''un bağbozumu sofrasında yüreğim. Ah, böyle bir anda karıma ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atabaş']::text[], 8.5, '{"poet":"Hüseyin Atabaş","poet_slug":"huseyin_atabas","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLKYAZ', 'i-lkyaz-gulten-akin-mqh1y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah, kimselerin vakti yok
Durup ince şeyleri anlamaya
Kalın fırçalarını kullanarak geçiyorlar
Evler çocuklar mezarlar çizerek dünyaya
Yitenler olduğu görülüyor bir türküyü açtılar mı
Bakıp  kapatıyorlar
Geceye giriyor türküler ve ince şeyler
"Memelerinde biraz irin, biraz balık ve biraz gözyaşı
Bir dev oluyorsun deniz deniz deniz
sisin dere ağızlarından sokulup akşamları
Fındıklarımızı basıyor
Neyleriz kararan tomurcukları
Çocuklarımıza yalvarıyoruz: Aç durun biraz
Tecimenlere yalvarıyoruz:
Bir "Hotel" bir gizli evlenme az çiziniz
Bir banka az çiziniz bir yalvarma
Bizden size ve sizden dışardakilere
Karılarımızı yolluyoruz tırnaklarını kesmeye ve demeye
-Evet efendim-
Çocuklarımızı yolluyoruz dilenmeye
Bizler gidiyoruz yatağımız tanrıya emanet
Yazların motorlu çingeneleri
Ah, kimselerin vakti yok
Durup ince şeyleri anlamaya
Baba evleri, ilk kez girilen ırmağa dönüş
Toprağa tutku, kendinden dolayı
Kulaklarımızı tıkıyoruz: Para para para
Kulaklarımızı açıyoruz: Kavga kavga kavga
Sorar belki biri: Kavga ama neden kavga
Komşumuza sonsuz balta, karımıza yumruklar içinde
-Bilmiyoruz neden kavga.
Sonra kasabanın cezaevinde
Silgimizi göz önüne yerleştiriyoruz
Günlerimiz iterek genişletiyoruz
Yer açıyoruz karılarımızı düşünmeye
Bizsiz geçen menevşeyi düşünmeye
Durup ince şeyleri anlatmaya
Kimselerin vakti olmasa da
Okulların kadın öğretmencikleri
Tatil günlerini çoğaltsalar da
Kutsal nemiz varsa onun adına
Gözlerimiz için bağlar dokusalar da
Birikimler ve çizgiler gitgide gitgide
Açmaya ilkyaz çiçekleri
Bir gün birileri öte geçelerden
Islık çalar yanıt veririz', 'Ah, kimselerin vakti yok Durup ince şeyleri anlamaya Kalın fırçalarını kullanarak geçiyorlar Evler çocuklar mezarlar çizerek dünyaya Yitenle...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LİLİ''CİĞİM', 'li-li-ci-gi-m-vladimir-mayakovski-sjz65', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(Mektup yerine)
Tütün dumanı kemiriyor havayı.
Oda
Kruçyonıh''ın Cehennem'' inden bir bölüm gibi.
Anımsıyor musun
İlk kez
ardında bu pencerenin
tutkudan çıldırmışçasına
okşamıştım ellerini.
Şimdi
oturuyorsun aynı yerde,
yüreğin
demirden bir kılıf içinde.
Ve yarın
paralayan sözlerle
kovacaksın belki beni
Ve loş antrede
uzun süre
titreyişlerle sarsılan bir kol
bulamayacak
ceketteki yerini.
Çıkacağım, ezilmiş.
Fırlatacağım vücudumu sokağa.
Yabanıl
çılgın
umutsuzlukla paramparça.
Hayır
gerek yok buna,
sevgilim,
biriciğim,
gel
vedalaşalım şimdiden.
Ağır bir gülle gibi
aşkım
nereye kaçarsan kaç
asılıdır sana
nasıl olsa.
Bırak
son bir haykırışla uluyayım
horlanmışlığın acı yankısını.
Çalışmaktan
anası ağladığında öküzün
gider
salar kendini soğuk sulara.
Aşkından başka
deniz yok bana,
ve gözyaşları da
bir erinç
koparamıyor ondan.
Yorgun fil
sessizliği aradığında
yatar
kızgın kumlara saltanatla.
Aşkından başka
güneş yok bana.
Ve bilmiyorum bile
neredesin şimdi ve kiminle.
Eğer
bir başka şair olsaydı
böylesine üzdüğün,
onarırdı acısını
parayla ve ünle.
Fakat
sevinç vermiyor bana hiçbir çınıltı
senin sevgili adının
çınıltısından başka.
Atmayacağım
bir boşluğa kendimi,
zehir içmeyeceğim.
Ve dayayıp
şakağıma namluyu
çekmeyeceğim tetiği.
Ağzı hiçbir bıçağın
bakışların kadar senin
kesemez beni.
Yarın unutacaksın
seni taçlandırdığımı,
ve yakıp tükettiğimi
çiçeklenmiş bir ruhu
aşkla.
Ve uçarı günlerin fırtınalı karnavalı
dağıtacak
sayfalarını kitaplarımın.
Sözlerimin kurumuş yaprakları mı
durduracak seni
çırpınan soluğuyla.
Bırak hiç değilse
son bir sevgi dalgası sereyim
beni bırakıp giden adımlarının altına.
Vladimir MAYAKOVSKI', '(Mektup yerine) Tütün dumanı kemiriyor havayı. Oda Kruçyonıh''ın Cehennem'' inden bir bölüm gibi. Anımsıyor musun İlk kez ardında bu pencereni...', ARRAY['Türk Edebiyatı','Şiir','Vladimir Mayakovski']::text[], 8.5, '{"poet":"Vladimir Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":92}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLLERİ VAR BİZİM İLE BENZEMEZ', 'i-lleri-var-bi-zi-m-i-le-benzemez-karacaoglan-8ubvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İndim seyran ettim Firengistan''ı
İlleri var, bizim ile benzemez
Levin tutmuş goncaları açılmış
Gülleri var, bizim güle benzemez
Göllerinde kuğuları yüzüşür
Meşesinde sığınları böğrüşür
Güzelleri türkü söyler, çığrışır
Dilleri var, bizim dile benzemez
Seyr edüben gelir Karadeniz''i
Kanları yok, sarı sarı benizli
Öğün etmiş, kara domuz etini
Dinleri var, bizim dine benzemez
Akılları yoktur, küfre uyarlar
İmanları yoktur, cana kıyarlar
Başlarına siyah şapka geyerler
Beyleri var, bizim beye benzemez
Karac''oğlan eydür, dosta darılmaz
Hasta oldum, hatırcığım sorulmaz
Vatan tutup bu yerlerde kalınmaz
İlleri var, bizim ile benzemez', 'İndim seyran ettim Firengistan''ı İlleri var, bizim ile benzemez Levin tutmuş goncaları açılmış Gülleri var, bizim güle benzemez Göllerinde k...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜLER', 'oluler-haydar-ergulen-ir6i0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.
cesetleri toplamak bana düştü
ölülerimin ardından iyi konuşacağım
II.
karanlık gecede beş ölü
biraz çocuk biraz delikanlı tümü
umutla umutsuzluk arasında yaşarken
ölümleriyle iyiden koyulaştı acının rengi
kırıldı da düşlerinin en güzel yeri
şarkılarını bıraktılar giderken belki bir anı
III.
anımsıyorum
düğüne giden çocuklar da böyle gülerdi.', 'I. cesetleri toplamak bana düştü ölülerimin ardından iyi konuşacağım II. karanlık gecede beş ölü biraz çocuk biraz delikanlı tümü umutla umu...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar_ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜLERİMİZ', 'oluleri-mi-z-nihat-behram-uwthi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sabah
her sabah
o kusursuz acının kollarında
o kusursuz acının kollarında öpüştüğüm gökyüzü
artık
çırpınan yüreğimi yatıştırmıyor. Ve onun
koparıp dizginlerini
uçarcasına boylu boyunca
sakınmasız çarpışı
heyecanlandırıyor beni.
Bir serçe kümesinin konması karşıki dala
belki hiçbir şeydir,
ama sevgilimin mektubunda bir kuş resmi
beni coşkulandırabilir.
Milyarla yıldız arasında tanırım onu
çünkü seyredince güzelleşir sevginin ışıltısı;
binlerce gözüm var
binlerce şafak halindeyim
anlamak istediğim şeyin karşısında
çünkü anlamak zorundayım;
her sevinç kolayca ele geçmez
insan her acının sahibi değildir;
gökyüzü ve nehirler olmasa toprak da anlaşılmaz
ve hayatın kararı kesin:
son ana kadar onuru koruyanlar yaşayacak
söylenecek son söz kahramanca olmalıdır.
Vurgunum
inceliğinim senin
eyy
yapraklarda bir kuş hafifliğinde sürüp giden
titreyiş
vurgunum
bir nehri besleyen suların uyumuna,
taşlara hırsla vuruşuna dalganın.
Ölüm seni yanıltmasın...
Nasıl ki yığılır yüzüne gecenin karanlığı
gözlerinle bir başına kalırsın
ölüm öylesine gözuçlarında
savun, kavuştur yüreğini
minicik bir çiçeğin bile kökleri
yaşamak hırsıyla uykusuzdur.
Ölülerimiz...
İşte Stevan Flipoviç.
Bir kahraman.
Faşistler sarmış çevresini.
Sehpada.
Boynunda ip.
Ve o son nefesiyle dalayıp ciğerini
bir bıçak gibi vuruyor kelimeleri dişleri arasından
haykırıyor: &quot;Kahrolsun faşizm; Yaşasın mücadelemiz...&quot;
Steven Flipoviç
onurun bekçisi
direnmenin.
Ölüm seni yanıltmasın...
Bir bir düşün yaşayanları
alnını korkusuzca kaldır
kimin yanındasın
yerin neresi
ve senin en çaresiz anında
tek silahın nedir?
Ölüm seni yanıltmasın...
Usanma hayata yaraşan sesi aramaktan
her kuşun palazlandığı bir yuva vardır,
her dal güneşin ve rüzgarın avuçlarında
kendi hevesince boyanır;
çünkü yaşaması gerekiyor bir şeylerin
bir şeylerin bir şeylerin: senin olan
Bak: kollarını bağlıyorlar;
son defa bakıyor dünyaya Nguyen Van Troi
Birazdan göğsünü parçalayacaklar.
Ama kan onu geriletmiyor.
Başlıyor şarkısına:
&quot;Yaşasın Ho Chi Minh: Yaşasın Vietnam...&quot;
Damarlarım damarlarına bağlı yaralarından
çünkü öldürülmek istenen benim de
sevincimdir
Nguyen onun siperi...
Bir buğday tanesi midir
aynı titreyişle
toprağa düşer düşmez kıpırdayan
o şarkı... bir buğday tanesi mi?
Ölülerimiz...
Sesleri dünyamız kadar bilge.
Birazdan kalkacaklarmış gibi
uzanıp bir sipere
koyulaşan...
Ölülerimiz...
Bakışları
uçmaya hazırlanan bir kartal kadar çevik,
vurgunum
gizleyemem.
Sen bağrımı amansızca zorlayan siyahlık
unutma
öldürmekten daha kuvvetlidir ölebilmek.', 'Her sabah her sabah o kusursuz acının kollarında o kusursuz acının kollarında öpüştüğüm gökyüzü artık çırpınan yüreğimi yatıştırmıyor. Ve on...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":96}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLLET', 'i-llet-i-lhan-sevket-aykut-b2x54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Molla sordu, illet nedir?
Hallac etti, illet yoktur.
İllet olsa gereği ne?
Molla etti, illetlerin illeti var.
Hallac etti, illetlerin illeti yok,
İlk illetin illeti ne, sebebi ne?
Molla sordu gerek nedir?
Hallac etti, tanrı olsa gereği ne?
Molla etti, yaratmak tanrı gereği.
Hallaca etti, tanrı nedir?
Tanrıya, gerek gerekse.
Canım sana kurban Mansur,
Tanrı nedir, tanrı nedir,
Adam tanrıya gerekse?', 'Molla sordu, illet nedir? Hallac etti, illet yoktur. İllet olsa gereği ne? Molla etti, illetlerin illeti var. Hallac etti, illetlerin illeti...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şevket Aykut']::text[], 8.5, '{"poet":"İlhan Şevket Aykut","poet_slug":"ilhan_sevket_aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LİLİYAR', 'li-li-yar-sezai-karakoc-f1m4o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kuklaların kukla olmadığı besbelli
Ne söyledilerse tıpıtıpına gerçek besbelli
Altın saçlarını yana atışı yok mu Lilinin
Lilinin yağdan kıl çekercesine inanışı
Lilinin yağdan kıl çekercesine yaşayışı yok mu
Kuklalar titremesin ne yapsın
Kuklaların kukla olmadığı besbelli
Lilinin çekip gideceği besbelli
Lilinin dönüp geleceği besbelli
Ekmek ha bakkalın olmuş ha Cabaret de Paris''nin
Sen herhangi bir ekmek yiyeceksin işte Lili
Ekmek ne kadar Allahınsa Lili de o kadar Allahın Lili
Yüzün ruhun kadar aydınlık ya Lili
Gönlün soğuk sular güzel aynalar gibi ya Lili
Anladın ya kutunun içinden çıkan mendil
Olamaz Üstüdardan geçeriken bulduğun mendil
-Bizi bırakıp nereye gidiyorsun Lili
Demek bizi bırakıp gidiyorsun Lili
Sen daima güzeller güzelini bulursun Lili
Sen istesen de taş yürekli olamazsın
Sen daima güzeller güzeli olursun Lili
Demek gideceksin arkana dönüp bakmayacaksın
Hangi kuş hangi şafakta ölecek görmeyeceksin
Öyleyse al bu kürkü bu veda kürkünü Lili
Tüyleri şiirler olan bu mahcup kürkü
Sen daima Sultanlar Sultanı olursun Lili
Demek sen gidiyorsun Lili
Bizi öpmeden mi gideceksin Lili
Lilinin güneşin altında duruşu yok mu
Perdeleri sıyırıp çirkin adamı burnundan yakalayışı yok mu
Eline bavulunu alışı yollara koyuluşu yok mu
Çirkin adamın güzel adam oluşu yok mu
Yaklaşıp onu saçlarından yakalayışı
Uzaklaşıp yollarda yol oluşu yok mu
Lilinin bir tavşan gibi koşuşu
Keklik gibi dönüp bakışı ve yıldırım gibi koşuşu yok mu
Adam da tam o zaman kapıdan çıkmaz mı dışarı
Lilinin adamın boynuna çocukça ve çılgınca atılışı yok mu
Ben konuşmasını bilmem Lili', 'Bu kuklaların kukla olmadığı besbelli Ne söyledilerse tıpıtıpına gerçek besbelli Altın saçlarını yana atışı yok mu Lilinin Lilinin yağdan kı...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM FÜGÜ', 'olum-fugu-paul-celan-49msm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam vakitlerinde içmekteyiz sabahın kapkara sütünü
ve öğlenlerle sabahlarda bir de geceleri
hiç durmaksızın içmekteyiz
bir mezar kazıyoruz havada rahat yatılıyor
Bir adam oturuyor evde yılanlarla oynayıp yazı yazan
hava karardığında Almanya''ya senin altın saçlarını yazıyor Margarete
bunu yazıp evin önüne çıkıyor ve yıldızlar parlıyor
köpeklerini çağırıyor ıslıkla
sonra Yahudilerini çağırıyor ıslıkla toprakta bir mezar kazdırıyor
bize buyruk veriyor haydi bakalım şimdi dansa
Gece vakitlerinde içmekteyiz sabahın kapkara sütünü
ve sabahlarla öğlenlerde bir de akşamları
hiç durmaksızın içmekteyiz
Bir adam oturuyor evde yılanlarla oynayıp yazı yazan
hava karardığında Almanya''ya senin altın saçlarını yazıyor Margarete
senin kül olmuş saçlarını Sulamith bir mezar kazıyoruz
havada rahat yatılıyor
Adam bağırıyor daha derin kazın toprağı siz ötekiler
şarkılar söyleyip dans edin
tutup palaskasındaki demiri savuruyor havada gözlerinin
rengi mavi
sizler daha derine sokun kürekleri ötekiler devam edin
çalmaya ve dansa
Gece vakitlerinde içmekteyiz sabahın kapkara sütünü
ve sabahlarla öğlenlerde bir de akşamları
hiç durmaksızın içmekteyiz
bir adam oturuyor evde senin altın saçların Margarete
senin kül saçların Sulamith adam yılanlarla oynuyor
Sesleniyor daha tatlı çalın ölümü çünkü o Almanya''dan
gelen bir ustadır
sesleniyor daha boğuk çalın kemanları sonra sizler
duman olup yükseliyorsunuz göğe
sonra bir mezarınız oluyor bulutlarda rahat yatılıyor
Gece vakitlerinde içmekteyiz sabahın kapkara sütünü
sonra öğlen vakitlerinde ölüm Almanya''dan gelen bir ustadır
akşamları ve sabahları içmekteyiz hiç durmadan
ölüm bir ustadır Almanya''dan gelen gözleri mavi
bir kurşunla geliyor sana tam göğsünden vurarak
bir adam oturuyor evde senin altın saçların Margarete
köpeklerini salıyor üstümüze havada bir mezar
armağan ediyor
yılanlarla oynuyor ve dalın düşlere ölüm Almanya''dan
gelen bir ustadır
senin altın saçların Margarete
senin kül olmuş saçların Sulamith
Çeviri: Sevil Eryaşar', 'Akşam vakitlerinde içmekteyiz sabahın kapkara sütünü ve öğlenlerle sabahlarda bir de geceleri hiç durmaksızın içmekteyiz bir mezar kazıyoruz...', ARRAY['Türk Edebiyatı','Şiir','Paul Celan']::text[], 8.5, '{"poet":"Paul Celan","poet_slug":"paul_celan","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM GELECEK VE SENİN GÖZLERİNLE BAKACAK', 'olum-gelecek-ve-seni-n-gozleri-nle-bakacak-cesare-pavese-tihbz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm gelecek ve senin gözlerinle bakacak -
sabahtan akşama dek, uykusuz,
sağır, eski bir pişmanlık
ya da anlamsız bir ayıp gibi
ardını bırakmayan bu ölüm.
Bir boş söz, bir kesik çığlık,
bir sessizlik olacak gözlerin:
Böyle görünür her sabah
yalnız senin üzerinde
kıvrımlar yansıtırken aynada.
Hangi gün, ey sevgili umut,
bizler de öğreneceğiz senin
yaşam olduğunu, hiçlik olduğunu.
Herkese bir bakışı var ölümün.
Ölüm gelecek ve senin gözlerinle bakacak.
Bir ayıba son verir gibi olacak,
belirmesini görür gibi
aynada ölü bir yüzün,
dinler gibi dudakları kapalı bir ağzı.
O derin burgaca ineceğiz sessizce.
Cesare PAVESE', 'Ölüm gelecek ve senin gözlerinle bakacak - sabahtan akşama dek, uykusuz, sağır, eski bir pişmanlık ya da anlamsız bir ayıp gibi ardını bırak...', ARRAY['Türk Edebiyatı','Şiir','Cesare Pavese']::text[], 8.5, '{"poet":"Cesare Pavese","poet_slug":"cesare_pavese","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM HAYATI KUŞATALI BERİ', 'olum-hayati-kusatali-beri-i-smail-uyaroglu-bxqqh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kül yağıyor gökten
Kül renginde güneş
İki şey örtüyor kırları
Kül ve leş
Neye uzatsam elimi dağılıyor
Bütün eşyalarda ölümün tozu
Aynı anda yakıyor genizleri
Öfkenin ve göz yaşının tuzu
Kimi kanla besleniyor kelimelerin
Kimi kelimeler paslı
Ne kadar kafiyesi varsa hayatın
Hepsi de ölümle cinaslı
Ve ölüm hayatı kuşatalı beri
İki şey yan yana gelişiyor evlerde
Babalar bıçak biliyor
Analar yaslı', 'Kül yağıyor gökten Kül renginde güneş İki şey örtüyor kırları Kül ve leş Neye uzatsam elimi dağılıyor Bütün eşyalarda ölümün tozu Aynı anda ...', ARRAY['Türk Edebiyatı','Şiir','İsmail  Uyaroğlu']::text[], 8.5, '{"poet":"İsmail  Uyaroğlu","poet_slug":"ismail_uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLİM KENDİN BİLMEKTİR', 'i-li-m-kendi-n-bi-lmekti-r-yunus-emre-cj7ub', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlim ilim bilmektir
İlim kendin bilmektir
Sen kendini bilmezsin
Ya nice okumaktır
Okumaktan murat ne
Kişi Hak''kı bilmektir
Çün okudun bilmezsin
Ha bir kuru ekmektir
Okudum bildim deme
Çok taat kıldım deme
Eğer Hak bilmez isen
Abes yere gelmektir
Dört kitabın mânâsı
Bellidir bir elifte
Sen elifi bilmezsin
Bu nice okumaktır
Yiğirmi dokuz hece
Okursun uçtan uca
Sen elif dersin hoca
Mânâsı ne demektir
Yunus Emre der hoca
Gerekse bin var hacca
Hepisinden iyice
Bir gönüle girmektir', 'İlim ilim bilmektir İlim kendin bilmektir Sen kendini bilmezsin Ya nice okumaktır Okumaktan murat ne Kişi Hak''kı bilmektir Çün okudun bilmez...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM ŞİİRİ', 'olum-si-i-ri-arif-di-no-e98xb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşamın gürültüleri suskunluklarını bulandırdı
buna gülüyorsun simdi çünkü boş kafanda
yer alan yanlızca tutsaklık', 'Yaşamın gürültüleri suskunluklarını bulandırdı buna gülüyorsun simdi çünkü boş kafanda yer alan yanlızca tutsaklık...', ARRAY['Türk Edebiyatı','Şiir','Arif Di̇no']::text[], 8.5, '{"poet":"Arif Di̇no","poet_slug":"arif_dino","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM VE ATEŞ', 'olum-ve-ates-ozgur-ozmeral-i0isb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce toprak bozuldu
aklımızdaki toprak.
(A.Cengizkan)
aynasıyla yürüyorum sokakların
bayat yağmur ölmüş iklimlere ağıt
katarcasına
saçma bulutu başımın üstünde
Ey insan kapattın ellerini
avuçlarını yaktın bilemedin heyecanın tonunu
Ey ateş yürek kanamasına bıraktın kendini
ve eti soysuz insanın yanar yanar dedin
ben suyla kardeş oldukça', 'Önce toprak bozuldu aklımızdaki toprak. (A.Cengizkan) aynasıyla yürüyorum sokakların bayat yağmur ölmüş iklimlere ağıt katarcasına saçma bul...', ARRAY['Türk Edebiyatı','Şiir','Özgür  Özmeral']::text[], 8.5, '{"poet":"Özgür  Özmeral","poet_slug":"ozgur_ozmeral","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM', 'olum-francois-villon-jh5p6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu yokluk yedi bitirdi bizi
Ağlayıp sızladık yürekten:
"Adam sende... deyip geçmeli
Ne bulduk sanki inlemekten
Ne sen varlıklı ne de ben,
Çul giyinip ömür sürümek
Hoş değil mi o beylerden?"
Neler göçtü şu dünyadan,
Ne uslusu kaldı ne delisi,
Göçüp gitmişler tümü buradan
Çoluğu çocuğu, alisi velisi
En güzeli, dekoltelisi.
Dulu, zengini ayırmaksızın,
Şıkını, orta hallisini
Ölüm gelir bulur ansızın.
İster Paris olsun, ister Hèléne,
Acıdır acı ölümün kancası.
Son demde soluğundur kesilen
Yüreğine acılar dolası
Tanrı bilir terden yanası
Lokman Hekim bulamaz çare
Artık ne kardaş kavgası
Düşecek herkes başı derdine.
Bir burnumuzdu ezilmeyen,
Ölüm okudu canımıza,
Şimdi ne can kalır, ne ten
Ölüm dayandı kapımıza,
Bir kez yazılmış alnımıza,
Kız da kadın da yalan bütün
Ölüm almış gemiyi azıya
Ölüp gideceğiz bir gün.
François VILLON', 'Bu yokluk yedi bitirdi bizi Ağlayıp sızladık yürekten: "Adam sende... deyip geçmeli Ne bulduk sanki inlemekten Ne sen varlıklı ne de ben, Çu...', ARRAY['Türk Edebiyatı','Şiir','François Villon']::text[], 8.5, '{"poet":"François Villon","poet_slug":"francois_villon","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LİMAN TABLOSU', 'li-man-tablosu-salih-bolat-80w8q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'alo santral
bana otel müdürünü bağlayın lütfen
şu liman tablosunu kaldırsınlar hemen
odamın duvarından
ben ne zaman binmek istesem o gemilere
sessizce kaçmak istesem acının adalarından
biliyorum bütün martılar maviyi ağlar
bir yağmur tutuşur kirpiklerinde şu kederli kaptanın
ilkyazın bütün kapıları mühürlenir
alo santral
şu liman tablosunu odamın duvarından
söyleyin kaldırsınlar', 'alo santral bana otel müdürünü bağlayın lütfen şu liman tablosunu kaldırsınlar hemen odamın duvarından ben ne zaman binmek istesem o gemiler...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih_bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMDEN SONRA', 'olumden-sonra-cahit-sitki-taranci-yl226', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öldük, ölümden bir şeyler umarak.
Bir büyük boşlukta bozuldu büyü.
Nasıl hatırlamazsın o türküyü,
Gök parçası, dal demeti, kuş tüyü,
Alıştığımız bir şeydi yaşamak..
Şimdi o dünyadan hiçbir haber yok;
Yok bize arayan, soran kimsemiz.
Öylesine karanlık ki gecemiz,
Ha olmuş ha olmamış penceremiz;
Akarsuda aksimizden eser yok.', 'Öldük, ölümden bir şeyler umarak. Bir büyük boşlukta bozuldu büyü. Nasıl hatırlamazsın o türküyü, Gök parçası, dal demeti, kuş tüyü, Alıştığ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMDEN...', 'olumden-ahmed-samlu-z1w0d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümden korkmuş değilim hiç
pespayeliğinden
kırılgan gerçi
elleri.
Tek korkum
insan özgürlüğünün
mezarcının ücretinden
ucuz olduğu
bir ülkede
ölmek.
Aramak
bulmak ve
karar vermek
özgürce
ve
bir
kale yapmak
kendi özünden.
Değil mi ki ölüm daha
değerli bütün bunlardan
hiç ama hiç korkmuş
değilim
ölümden ...
Ahmed  ŞAMLU', 'Ölümden korkmuş değilim hiç pespayeliğinden kırılgan gerçi elleri. Tek korkum insan özgürlüğünün mezarcının ücretinden ucuz olduğu bir ülked...', ARRAY['Türk Edebiyatı','Şiir','Ahmed  Şamlu']::text[], 8.5, '{"poet":"Ahmed  Şamlu","poet_slug":"ahmed_samlu","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜME EĞİLMEK', 'olume-egi-lmek-aziz-nesi-n-94avj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyumaya değil
Rüyalarıma gidiyorum
Orada yaşayacağım isteğimce
Uyanıkken hiç yaşayamadığım
Hepsi de gençti güzeldi
Sevdim sevildim diye aldanarak
Son gördüğüm onlar olacak
Bunca yıldır sevgiye dayanamadığım
Ölüme değil
Sonsuzluğa gidiyorum
Orda dinleneceğim gönlümce
Yaşarken hiç mi hiç dinlenemediğim
Kalemim yine elimde
Kağıtlarım da önümde
Son uykusunda düşecek başım
Sağlığımda hiç eğmediğim', 'Uyumaya değil Rüyalarıma gidiyorum Orada yaşayacağım isteğimce Uyanıkken hiç yaşayamadığım Hepsi de gençti güzeldi Sevdim sevildim diye alda...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLMEK KONUSUNDA', 'olmek-konusunda-ziya-osman-saba-tyqkw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ha üç gün önce, ha beş gün sonra.
Geldiğin gibi gidişin.
Nereye gittiyse anan, baban,
Peşinden kardeşin.
Bir yaprak dökümüdür dört yandan.
Bir dostun, seninle ağlamış gülmüş,
Bir sabah gazeteyi açarsın ki:
Ölmüş!
Daha dün gibidir hepsi.
Evlendiğin gün çekilmiş resim.
Mesutsun bak, çoluk çocuğunla.
Geçti kaç mevsim...
Gençtin, dinçtin... hepsi bir zamanlar.
Nerende şimdi ağrın, sızın?
Yatakta mı, yavaş yavaş
Ya sokakta ansızın?
Birkaç bahar, bir o kadar kış.
Ömürdür; uzun, kısa.
Ne ise göreceğin;
Kısmet ne kadarsa.
Hangi yılsa o, hangi ayın hangi günü,
Saati çalınca, gelince sıran.
Nasıl yaşadıysa habersiz,
Nasıl öldüyse bunca insan...', 'Ha üç gün önce, ha beş gün sonra. Geldiğin gibi gidişin. Nereye gittiyse anan, baban, Peşinden kardeşin. Bir yaprak dökümüdür dört yandan. B...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya_osman_saba","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLMEMEKTEN ÖLMEK', 'olmemekten-olmek-paul-eluard-g92fz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözkapaklarımın üzerinde ayakta duruyor
Ve saçları saçlarımın içinde
Biçimi ellerimin biçiminde
Gözlerinin rengi gözlerimin renginde
Gölgemde yitip gidiyor
Tıpkı bir taş gibi gökyüzünde.
Gözleri var her zaman açık
Ve bir an olsun uyutmaz beni.
Düşeri var apaydınlık
Güneşler buharlaştıran
Güldürür, ağlatır beni ve güldürür
Konuşturur beni söyletmeksizin tek bir söz.', 'Gözkapaklarımın üzerinde ayakta duruyor Ve saçları saçlarımın içinde Biçimi ellerimin biçiminde Gözlerinin rengi gözlerimin renginde Gölgemd...', ARRAY['Türk Edebiyatı','Şiir','Paul Eluard']::text[], 8.5, '{"poet":"Paul Eluard","poet_slug":"paul_eluard","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLMEYE VAKİT YOK', 'olmeye-vaki-t-yok-mustak-erenus-9ovrc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnanmak gerekir güne
Bütün dertleriyle dün
Durmayın çaba getirin güne
İnsanlar güzeldir
İnsanlar iyidir
İnsanlar güçlüdür
İnanmak gerekir güne.
Kocaman bir yürek taşıdım getirdim
Bütün umacılardan korkusuz
Gelincikler der güzel
Sınırlardan üste
Tüm bayraklardan renkli
Yaşamın temel direği
İnanmak gerekir güne.
Gelincikler toprakta gelindin
İnsanın umudu insanda.
Gerçek korkmadan soyunur
Güzelim güneş alnında.
Kocaman bir yürek taşıdım getirdim
Tüm bayraklardan renkli
Peter Con Pietro Petrovna
Ali', 'İnanmak gerekir güne Bütün dertleriyle dün Durmayın çaba getirin güne İnsanlar güzeldir İnsanlar iyidir İnsanlar güçlüdür İnanmak gerekir gü...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLMEZLİK KUŞU', 'olmezli-k-kusu-osman-namdar-raq22', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşünü görür düşünür: resne''den çıkar niyazi,
balkana bakar güne tutup elini, ovaya bakar; dört bir yana:
eğriceli tay gibi huzursuzdur memleket
belki hurriyyet bir geyiğin alaca göğsündedir,
dağlarda ya da niyazi''nin geyiğe sözündedir:
ama artık ne niyazi ottur, ne bu geyik ettir,
niyazi ve geyik  saf sevgiden ibarettir.
kuşlardan mütevellit bir kuştur Zümrüdüankâ;
bir şair ağlamaklı olur atını sürer azgın sulara
pus olur pusu olur, geyiklerin gezdiği dağlarda
silah sesleri çın çın öter sehere karşı ovalarda
yankılanır çöl olur sonra, insan hurriyete susadıkça
geyiğim vurulur döşünden, sekisinden, sakarından:
Tren istasyonlarında bekler ölüm kahpece
Niyazi dayanır elbette sırtındaki hançere
Ölünür mü sandın ten tabuta girince
Geyiğim meler dağlarda niyazi diye diye.
niyaziler ölmez, geyikler ölmedikçe!
geyikler ölmez, niyaziler ölmedikçe!', 'Düşünü görür düşünür: resne''den çıkar niyazi, balkana bakar güne tutup elini, ovaya bakar; dört bir yana: eğriceli tay gibi huzursuzdur meml...', ARRAY['Türk Edebiyatı','Şiir','Osman Namdar']::text[], 8.5, '{"poet":"Osman Namdar","poet_slug":"osman_namdar","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMLÜ ÖLÜMSÜZ', 'olumlu-olumsuz-salvatore-quasimodo-8cmak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(Thanatos Athanatos)
Ve şimdi seni yadsımak zorunda mı kalacağız
urların tanrısı, canlı çiçeklerin tanrısı
bir hayırla mı yanıtlayacağız o karanlık
kayayı ki benim özbenliğimdir, ölüme razı mı olacağız?
Ve her mezartaşına kazıyacak mıyız
tek kesin gerçeğimizi: thanatos athanatos!
Apaçık sorulara yenilmiş şu adamın
düşlerini, gözyaşlarını, öfkelerini
yorumlayacak bir addan yoksun.
Diyaloglarımız da değişmiş şimdi bak
saçmalıklar da mümkün olmada.
Orada sislerin dumanların ötesinde, ağaçların içinde
yaprakların gücü uyanmada
doğrudur ırmağın kıyılarına basınç yaptığı.
Hayat düş değil. Doğrudur insan
ve onun kıskanç yakınışı sessizlikten.
Susku tanrısı, açık yalnızlık.', '(Thanatos Athanatos) Ve şimdi seni yadsımak zorunda mı kalacağız urların tanrısı, canlı çiçeklerin tanrısı bir hayırla mı yanıtlayacağız o k...', ARRAY['Türk Edebiyatı','Şiir','Salvatore Quasimodo']::text[], 8.5, '{"poet":"Salvatore Quasimodo","poet_slug":"salvatore_quasimodo","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMLÜ YÜZ', 'olumlu-yuz-yves-bonnefoy-5mz2g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eğiliyor gün geçmişin ırmağına
Yeniden ele geçirmeye çalışıyor
Erken yitmiş silahları
Mücevherlerini o derin çocuksu ölümün
Göze alamıyor öğrenmeyi
Gerçekten gün müdür
Ve sevebilir mi bu tan sözünü
Onun için günün duvarlarını delen
Bir meşale taşındı külrengi günde
Ateş parçalıyor günü.
Bir saydamlığı var ki alevin
Acı acı yadsıyor günü
Yves BONNEFOY', 'Eğiliyor gün geçmişin ırmağına Yeniden ele geçirmeye çalışıyor Erken yitmiş silahları Mücevherlerini o derin çocuksu ölümün Göze alamıyor öğ...', ARRAY['Türk Edebiyatı','Şiir','Yves Bonnefoy']::text[], 8.5, '{"poet":"Yves Bonnefoy","poet_slug":"yves_bonnefoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÇÜMLER SÖZLÜĞÜ', 'olcumler-sozlugu-ahmet-uysal-wvhkj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hüzün/ölçer
rüzgâr: hüzün ölçeridir eylülün,
ürpertir geceyi öptüğü yerden
acı/ölçer
şiir:acı ölçeri kanlı yüzyılın
yaralı bir temmuz atlasında
aşk/ölçer
hançer:ah, onunla ölçülür bütün
ölümcül, yasak aşkları ülkemin
güz/ölçer
şair:güz ölçümüyle yazan şiirini
uyaklar düşüren uzak rüzgârlara', 'hüzün/ölçer rüzgâr: hüzün ölçeridir eylülün, ürpertir geceyi öptüğü yerden acı/ölçer şiir:acı ölçeri kanlı yüzyılın yaralı bir temmuz atlası...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMLERİN DÜŞÜNDÜRDÜĞÜ TÜRKÜ', 'olumleri-n-dusundurdugu-turku-afsar-ti-muci-n-q80je', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir akşamüstü balçık kuşları
Sessiz dökülürler yorgun akşama
Zehirli saatler emzirir suları
Günün ardından uzanıp dağlara
Yağmacılar doruklarda yıldızları çalarlar
Zamanın örgüsünü dişler gece kuşları
Uykunun kanını emer vampir
Güzelliğe kezzap döker karanlık
Sevinci tutsak eder korsanlar
Yavaş yavaş açılır yılan yumurtaları
Düşleri eksik imgelerle bozar
Kirpiler kuzgunlar kokarcalar
Geceye çakılır eskiyen kasımpatı
Uzaklardan boş kahkahalar gelir
Çocuğun boynunu takarlar ipe
Çirkinleştirerek yalnızlıkları
Bu cellatları kim besliyor
Kim yerleştiriyor çiçek diye
Kente bu gülünç sehpaları
Kim doğruyu kime benimsetiyor', 'Bir akşamüstü balçık kuşları Sessiz dökülürler yorgun akşama Zehirli saatler emzirir suları Günün ardından uzanıp dağlara Yağmacılar dorukla...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜMSÜZ', 'olumsuz-oktay-ri-fat-i2dt8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski bir zaman doğru, gerisin geri,
Uçtuklarını devşiren kuş.
Evimizin kapısında
Denizi çalan çıngırak.
Merhaba karabaş,
Olmayan köpeğim!', 'Eski bir zaman doğru, gerisin geri, Uçtuklarını devşiren kuş. Evimizin kapısında Denizi çalan çıngırak. Merhaba karabaş, Olmayan köpeğim!...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat']::text[], 8.5, '{"poet":"Oktay Ri̇fat","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜNCE İNSAN', 'olunce-i-nsan-henrik-nordbrandt-3czh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölünce insan
çevresi kalır geriye:
Uzaktaki dağlar
mahallenin evleri
ve yol
Pazarları tahta köprüden geçip
kent dışına gidilen.
Ve bahar güneşi
öğleden sonra bir vakitte
ulaşan bir raf dolusu kitaba, dergiye
hepsi de bir zamanlar kuşkusuz yepyeni olan.
Hiç de tuhaf değil.
Ama yine de
hep şaşırtıyor beni.
Henrik NORDBRANDT', 'Ölünce insan çevresi kalır geriye: Uzaktaki dağlar mahallenin evleri ve yol Pazarları tahta köprüden geçip kent dışına gidilen. Ve bahar gün...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LODOS', 'lodos-mehmet-zaman-saclioglu-g2t7f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Son parçasını giysimin
Al, gökyüzüne savur
Akıl ışık gibidir çıplak
Ardından gelen yağmur.
Denizin hırçın çocuğu
Köpüklü atlarınla gel
Önümde dur! Uzak
adadan gelen şişeyi
taşlara vur! Hazır ruhum
yanıtlamaya mektupları.
Ey iki anneli yaratık
Suskunların soluğu
Denizin yıkadığı lodos
Toprağın kuruttuğu
Getir bütün kıyılarını
Göğsümde uyu.', 'Son parçasını giysimin Al, gökyüzüne savur Akıl ışık gibidir çıplak Ardından gelen yağmur. Denizin hırçın çocuğu Köpüklü atlarınla gel Önümd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LORCA KARDEŞİM', 'lorca-kardesi-m-mustak-erenus-wue7n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölmek istemiyorum diyordu içinden.
İri taşlı kirli bir duvar önünde
Fazla bekletilmeden
İki beyaz bulut geçti
Ve iki beyaz kelebek
Mavi bir diken üstünde
Sevişemeden uçtular.
Her şey ortada soğuktu
Ve güneş
Sabahları bilerek dikine çıkıyordu.
Biz bütün bu olanları
Anlaşılmaz bir uzaktan seyrettik
Kapılarımız inadına üzerlerimize çiviliydi.
Korkak sokaklarda sarı ışıklar
Geceler boyu çekinmeden umutları yedi.
Bilinen bir dua için eğri çıkıyordu tepeyi.
Berikiler orta yerde durup
Bir başka şarkı tutturdular
Ve sabahları boşuna erkende
Budalaca düşlerini anlatıyorlardı.
Biri bir kuyu dibinde
Dipten yukarı ışıklara bakıyordu
Yukarda çırpınan bir böcek
Boşuna suyu karıştırıyordu.
İki beyaz bulut
Ve iki beyaz kelebek
Mavi bir diken üstünde
Sevişemeden uçtular
Gün ertesi
Çirkin bir ışıkta
O yıkık taşlı kirli duvar önünde
Koca kafalı bir koyun otlattılar.', 'Ölmek istemiyorum diyordu içinden. İri taşlı kirli bir duvar önünde Fazla bekletilmeden İki beyaz bulut geçti Ve iki beyaz kelebek Mavi bir ...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LİRİK ŞARKI', 'li-ri-k-sarki-ceyhun-atuf-kansu-rdkmw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öt, güzel serçe, öt yeşil çalıda,
Sabahın sesini duyayım senden,
Şarkınla beraber gir penceremden,
Oyununu oyna renkli halıda.
Meşe dallarından uçup bana gel,
Gel, güzel serçem gel, böğürtlenlerden,
Saksılarım, baygın fesleğenlerden,
Ve güllerim bütün güllerden güzel.
Bir delice sevinç, çocuk sevinci
Ötüyor dallarda, gel güzel sevinç!
Ruhum bir şadırvan, eğil eğil iç,
Çınar yaprağıyla dokunmuş içi.
Sabahı taşıyan o en güzel kuş,
Şarkısiyle göçmüş uzak kırlara,
Veda et bu bahar o şarkılara,
Senin pencereni serçen unutmuş.', 'Öt, güzel serçe, öt yeşil çalıda, Sabahın sesini duyayım senden, Şarkınla beraber gir penceremden, Oyununu oyna renkli halıda. Meşe dalların...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun_atuf_kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LİRİK TEZLER', 'li-ri-k-tezler-adnan-satici-epwpu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I/ Ç o ğ u   K e z   K a y b e t m e k
Büyük konuşmamalı insan birgün yenilebilir
ıssız bir patikanın dar bükümünde
neler bekler insanı kimler karşılar
belki güneş yağmuru belki çığ
Mızıkmasın kimse; kağıtlar eşit dağıtılıyor
zardır bu; herkese altı yüzü var
tek yumurta ikizidir her olasılık
çoğu kez kaybetmek iyidir kazanmaktan
Ne diye taşımalı gurur denen urbayı
masada bırakmalı yük sayılan ne varsa
eşeğini sırtlamış Nasıralı''dan
herkesin alacağı bir ders olmalı
II/ S e n d e n   B i r   A d ı m   S o n r a   A n c a k
Diyorum ve seni izliyorum hiç erinmeden
dokunduğun her çalıya bir tutam yapağı bırakarak
soyunup serildiğin kumsala ulaşıyorum
senden bir adım sonra ancak
Kâşif dediğin sevdiğinin acemisidir
daha önce yürümediği yoldur aşk
daha önce görmediği düştür gövdesi
höyük altında gömülü şehir
Ki her kalbin mimarı kendisidir
örneksiz çizer sevda projesini
aksak bir kalemle ilerler sayfalarda
yaşamaktır gönyesi iletkisi
Aynı dili konuşabilseydi adaş dağlar
Büyük Ağrı''da da işe yarardı
Küçük Ağrı''ya çıkma deneyi
Şirin sarptır Leyla engin. Aslı dik
Bundandır Kerem''in Ferhad''a benzemediği
III/ B u l a n ı k   A ş k,  Y a r ı m   T ü m c e...
Bu benim esrik yazım durmadan yalpalıyor
derinliği bulandıran kıpkızıl mürekkebim
çağırır gibi sessiz bir gülümseyişle
bir şeyler mırıldanıyor anlamıyorum
Sanki gelme diyor, sanki gel diyor
varınca kapısından kovuyor beni
umudunu kesme diyor falıma bakan teyze
başka türlü düşünüyor kalbin telvesi
Bulanık aşk, yarım tümce, böyle de iyi
keskin ışıklara sırtını dönmüş ayna
geri çeviriyor saygıyla sunulan giysileri
yapyalnız, çırçıplak bir belirsizlik
Bir şeyler görünüyor yine de çift taraflı aynada
bir yüzünde ergimiş ruhun ötekine aktığı
ne demektir bu, hayra yoramıyorum
bir yüzünde ellerimi bıraktığını
IV/ K a v u ş m a k   G i b i   A y r ı l m a k  d a...
Kıyıya set çeken kayaların üstünde
yırtıcı bir hayvanın kanlı ayak izleri
vurmuş da biri; biri yarasına sarmış da gibi
takılıp kalmış acılı bakışları geriye
Ve hançer ürpertisi ipeğin yüreğinde
bir zamanlar dağlandığımı anımsatıyor bana
geriniyor kendini içimde unutmuş pençe
hayli karışık rüya sona eriyor
Gerçi bir an olsun aklımdan geçirmedim
neye varır diye bu işin sonu
yenildiğim için pişman değilim
yerlerde sürüklediğim için gururumu
Biraz üzgün biraz kırgınım ama
kavuşmak gibi ayrılmak da senin eserin
sormasın mı, yakınmaya da mı hakkı olmasın
korkusunu saklayan kör cesaretin
Aşkım... aşkım... niçin beni bıraktın.
(...)', 'I/ Ç o ğ u   K e z   K a y b e t m e k Büyük konuşmamalı insan birgün yenilebilir ıssız bir patikanın dar bükümünde neler bekler insanı kiml...', ARRAY['Türk Edebiyatı','Şiir','Adnan  Satici']::text[], 8.5, '{"poet":"Adnan  Satici","poet_slug":"adnan_satici","theme":"Türk Şiiri","is_hero":false,"total_lines":69}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LİSAN', 'li-san-ziya-gokalp-giqoq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel dil Türkçe bize,
Başka dil gece bize.
İstanbul konuşması
En sâf, en ince bize.
Lisanda sayılır öz
Herkesin bildiği söz;
Ma''nâsı anlaşılan
Lûgate atmadan göz.
Uydurma söz yapmayız,
Yapma yola sapmayız,
Türkçeleşmiş, Türkçedir;
Eski köke tapmayız.
Açık sözle kalmalı,
Fikre ışık salmalı;
Müterâdif sözlerden
Türkçesini almalı.
Yeni sözler gerekse,
Bunda da uy herkese,
Halkın söz yaratmada
Yollarını benimse.
Yap yaşayan Türkçeden,
Kimseyi incitmeden.
İstanbul''un Türkçesi
Zevkini olsun yeden.
Arapçaya meyletme,
İran''a da hiç gitme;
Tecvîdi halktan öğren,
Fasîhlerden işitme.
Gayrılı sözler emmeyiz,
Çocuk değil, memeyiz!
Birkaç dil yok Tûran''da,
Tek dilli bir kümeyiz.
Tûran''ın bir ili var
Ve yalnız bir dili var.
Başka dil var diyenin,
Başka bir emeli var.
Türklüğün vicdânı bir,
Dîni bir, vatanı bir;
Fakat hepsi ayrılır
Olmazsa lisânı bir.', 'Güzel dil Türkçe bize, Başka dil gece bize. İstanbul konuşması En sâf, en ince bize. Lisanda sayılır öz Herkesin bildiği söz; Ma''nâsı anlaşı...', ARRAY['Türk Edebiyatı','Şiir','Ziya  Gökalp']::text[], 8.5, '{"poet":"Ziya  Gökalp","poet_slug":"ziya_gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LUCCA', 'lucca-giuseppe-ungaretti-2ko0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mısır''daki evimizde, akşam yemeğinden, Dua''dan
sonra annem buraları anlatırdı bize.
Bundan, şaşırmalar şaşırmalarla geçti çocukluğum.
Sakınan, körce bir gelgit var kentin sokakları arasında.
Burda amaç yola çıkmaktır.
İkindi serinliğinde meyhanenin önünde, California''dan
kendi mülkleriymiş gibi söz eden insanlarla
oturdum.
Dehşetle kendimi buluyorum bu insanların
davranışlarında.
Sımsıcak aktığını duyuyorum şimdi damarlarımda
ölmüşlerimin kanının.
Bir kazma aldım ben de.
Toprağın tüten kalçalarında güler yakalıyorum
kendimi.
Elveda istekler, sıla özlemleri.
Bir insanın bilebileceği kadar biliyorum geçmişi
ve geleceği.
Yazgımı tanıyorum artık ve köklerimi.
Artık bir şey kalmıyor bana kehanette bulunacak,
düşünü görecek.
Her şeyi tattım, acısını çektim.
Ölüme rızadan başka bir şey kalmıyor bana.
Huzur içinde çocuk yetiştireceğim demek.
Yaşamı överdim, kötücül bir iştah
ölümlü aşklara iten beni.
Aşkı, ben de türün bir güvencesi saydığım
şu an, ölümü görüyorum.
Giuseppe UNGARETTI', 'Mısır''daki evimizde, akşam yemeğinden, Dua''dan sonra annem buraları anlatırdı bize. Bundan, şaşırmalar şaşırmalarla geçti çocukluğum. Sakına...', ARRAY['Türk Edebiyatı','Şiir','Giuseppe Ungaretti']::text[], 8.5, '{"poet":"Giuseppe Ungaretti","poet_slug":"giuseppe%20ungaretti","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LUMUMBA', 'lumumba-lumumba-vv6ws', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aldandın sen Lumumba
Aldandım ben.
Aldattılar aklı ve özgürlüğü.
Bilmem gerekliydi ya, bunu
Ben kurtuluş savaşı çocuğu
Tanımalıydım bu eski yüzü
İzmirden Ankaraya yangınlar alazında
Çocukların çığlığından, anaların acısından.
Aldattılar seni Lumumba
Aldatıyorlar beni.
Aldanıyoruz düpedüz
Tutsak halkların sunduğu tepsi
Belçikalı sofralara (amanın adı özgür ekonomi)
Bakır uranyum ve altın madeni
Kauçuk tarlalarında sömürge şapkaları
En ucuz zenginlik el emeği.
Aldandın sen Lumumba
Aldandım ben.
Aldatıyorlar gazetelerle, televizyonlarla.
Batı - O, Eflatunda kaldı - Batı? neymiş Batı?
Anamalın sömürgeci saltanatı,
Veren bir elle, alan bin elle
Bağımsızlıklar satılan çarşılar Çombelerle
Ve kanlı yumruğu bekçilik edenlerin
Tefeci konaklarına Batılı Brükselin.
Aldattılar seni Lumumba
Aldatıyorlar beni.
Güçlüdür o yargıçlar yargılıyız aldanmaya
Bankalardan uçaklarla roketlerle geliyorlar
Uyandığını duydular mı halkın gerinerek
İniveriyorlar ossaat tepesine
Tutulmuş paralı askerlerle.
Kongo bir halk ormanı değil artık
Kanlı sürgün avı doyumsuz çıkarların.
Vurdular seni Lumumba
Vururlar bizi.
Vuruyorlar o karanlık ırmaklarda
Ormanları delip geçen namuslu hançer ışıltıyı
Kara sıcak senin kanın akar Afrika gecesinden
Yağlı pırıl pırıl yüzleriyle iş adamları
Çil paralar atıyorlar dünya radyolarından
Düpedüz dilini tutmuş insanlığa.
Güçlüdürler, güçlü onlar: Kongo zengin,
Ezilmişlikle yoksulluk her yerde dilsizdir,
Dilsizdir fakir beyazlar ve zenci milyonlar
Aldanıyoruz durmadan, elimizde ne var?
Asyada, Afrikada, Güney Amerikada,
Perulu kızlar, Viyetnamlı oğullar
Ve sen Lumumba
Bedeni delik deşik zenci baba!', 'Aldandın sen Lumumba Aldandım ben. Aldattılar aklı ve özgürlüğü. Bilmem gerekliydi ya, bunu Ben kurtuluş savaşı çocuğu Tanımalıydım bu eski ...', ARRAY['Türk Edebiyatı','Şiir','Lumumba']::text[], 8.5, '{"poet":"Lumumba","poet_slug":"ceyhun_atuf_kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":52}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'LUXOR', 'luxor-umut-taydas-mnf6d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '"saz''a"
dalgın ifadelerle diktim yüzümü şehrine,
algın bir iç çekişle, ölümü kanıksadım,
yalpa düşüncelerde, boğuldum varlığına,
gelmezsin.
arasam ve gel desem, biliyorum gelmezsin.
iç yakan, el rüzgarlarda, sabah umudundayım,
kinlendim beynime, söz geçiremedim,
uykuyu duvara vurdum, karanlığı biledim.
ama gelmezsin.
arasam ve gel desem, buraları bilmezsin.
şüphesiz, sıkıntıdan benim ölümsüzlüğüm,
yürüdüğün caddeleri arşınladım, büyüdüm,
bu kahpe aşksızlığa dişlerimle saldırdım,
oysa gelmezsin.
arasam ve gel desem, isyanımı sezmezsin.
devirdim uzaklıkları, yakınına iliştim,
törpüledim geceleri, sabahı besteledim,
ellerine uzanırken, umursamazlıkla vuruldum,
lâkin gelmezsin,
arasam ve gel desem;
demem...
13.07.00 - 23:37', '"saz''a" dalgın ifadelerle diktim yüzümü şehrine, algın bir iç çekişle, ölümü kanıksadım, yalpa düşüncelerde, boğuldum varlığına, gelmezsin. ...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İLYA AVGİRİ''NİN KARISININ ACI TÜRKÜSÜ', 'i-lya-avgi-ri-ni-n-karisinin-aci-turkusu-i-lhan-berk-00nh0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim günlerim Soğanağa''da geçti
Bir pencere, avuç kadar bir gök
Sevim Matilda Hayrünnisa Eleni
Her Allahın günü daha bir sevmek
Daha bir cumhuriyeti, İlya Avgiri''yi
Benim gençliğim güzeldir bakın
Her gün elele denizle rüzgârla
Her şiirde seçme mısra güzelliğim
Her evde yatakların andığı ben
Mis gibi her gün hikâyem ağızlarda
Ne Cumhuriyet ne İlya Avgiri umrumda
Ben eskiden hayvan gibi yaşardım
Bir karanfil iki memem arasında
Gökyüzünü ayna yerine kordum da
Geçer ayıp yerlerime bakardım
Benim gençliğimde kimse ama kimse
Ayla, güneşle, cumhuriyetle uğraşmazdı
Gökyüzü, deniz dünyayı koyup gitmezdi
İlk çıkıyor balıklar daha denizden
Bunların biri olmazdı benim zamanımda
Galile Denizi', 'Benim günlerim Soğanağa''da geçti Bir pencere, avuç kadar bir gök Sevim Matilda Hayrünnisa Eleni Her Allahın günü daha bir sevmek Daha bir cu...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİMİ BOYAR', 'i-ci-mi-boyar-yusuf-altunel-c5p3s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'olsaydı tatlılığın kanadı
teninin sümbülüne konardı
öpülmenin yaramaz şehveti
göğüslerinde birdirbir oynardı
mutluluğu yakalasa sevinç tuzaklarım
yüreğinin saatleri nabzımda atardı
bal olup damlasa yorgunluğun
sevişmelerin peteğinde yatardı
ölümün keskin dili
varlığınla susardı
tanyerinin aydınlığı
alevinin ışığında solardı
baharda zahter alsam koynuma
terin kokardı
dağ çiçeklerinin melteminde
boynuna tomurcuklar doğardı
elin çırpınan serçe
avuçlarımda kanat açardı
okşamaların hırçın pençe
yüreğim darbelerinle coşardı
dudaklarım çatlasa sensizlik kurağından
dilin ağzımda kutsal bereketler sulardı
gidişin cehenneminde yansam kavrulsam
gelişin cennetinde hasretler kanardı
çiçeğe dursa bir ağaç
varlığın arısına döker ballar
akyanus mavisi sevmeler
içim dünyasını rengarenk boyar', 'olsaydı tatlılığın kanadı teninin sümbülüne konardı öpülmenin yaramaz şehveti göğüslerinde birdirbir oynardı mutluluğu yakalasa sevinç tuzak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İŞİM', 'i-si-m-i-lhan-sevket-aykut-lejev', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah güneşi,
Uyandı, karşı tepede taranmakta,
Altın altın esnemekte.
Kolları, kucakları altın uykularının kırpıntıları dolu,
Kaftanı sularda.
Sabah güneşi,
Yok ekmeği,
Yok ekmeğim.
Yok işi,
Yok işim.
İşim güneşin işsizliği.', 'Sabah güneşi, Uyandı, karşı tepede taranmakta, Altın altın esnemekte. Kolları, kucakları altın uykularının kırpıntıları dolu, Kaftanı sulard...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şevket Aykut']::text[], 8.5, '{"poet":"İlhan Şevket Aykut","poet_slug":"ilhan_sevket_aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAĞARA', 'magara-bulent-ecevi-t-fwusi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mağaranın duvarına
hayvanları taştan oydum
kükrediler karanlıkta
türkülerle karşı koydum
karanlıktı mağara
ışığı taştan oydum
üşüyordum
bir de güneş koydum
aşk oydum mağaranın duvarına
aşk oydum
ağrıdı taşlar
yarıldı mağara
1970', 'mağaranın duvarına hayvanları taştan oydum kükrediler karanlıkta türkülerle karşı koydum karanlıktı mağara ışığı taştan oydum üşüyordum bir ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '''MACARLAR'' FİLMİNİ SEYREDERKEN', 'macarlar-fi-lmi-ni-seyrederken-kemal-ozer-9hdgx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fısıldaştığını duydum
ardımda iki gevezenin.
Bu nasıl ağa
-dedi biri
çiftlik sahibi için-
bir kamçısı bile yok elinde
dolaşırken çizmelerini dövmeye.
Fırsat da çıktı
-dedi öteki
fırsat da çıktı ama
çekip almadı yatağına
onca kadından birini.
İzleyen iki geveze
düşen görüntüleri perdeye
bir büyük gölgenin
titreştiğini görmeden
görüntülerin üstünde.', 'Fısıldaştığını duydum ardımda iki gevezenin. Bu nasıl ağa -dedi biri çiftlik sahibi için- bir kamçısı bile yok elinde dolaşırken çizmelerini...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MACERA', 'macera-orhan-veli-5qizb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçüktüm, küçücüktüm,
Oltayı attım denize;
Bir üşüşüverdi balıklar,
Denizi gördüm.
Bir uçurtma yaptım, telli duvaklı;
Kuyruğu ebemkuşağı renginde;
Bir salıverdim gökyüzüne;
Gökyüzünü gördüm.
Büyüdüm, işsiz kaldım, aç kaldım;
Para kazanmak gerekti;
Girdim insanların içine,
İnsanları gördüm.
Ne yârdan geçerim, ne serden;
Ne denizlerden, ne gökyüzünden ama...
Bırakmıyor son gördüğüm,
Bırakmıyor geçim derdi.
Oymuş, diyorum, zavallı şairin
Görüp göreceği.', 'Küçüktüm, küçücüktüm, Oltayı attım denize; Bir üşüşüverdi balıklar, Denizi gördüm. Bir uçurtma yaptım, telli duvaklı; Kuyruğu ebemkuşağı ren...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MADEN OCAĞININ DİBİNDE', 'maden-ocaginin-di-bi-nde-aldo-severi-ni-h59eo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maden ocağının dibinde
ışık yok.
Hava yok
maden ocağının dibinde.
Maden ocağının dibinde
besin yok.
Karın yok
maden ocağının dibinde.
Oğlun bile yok
maden ocağının dibinde.
Ayırdılar seni dünyadan,
aldılar elinden ışığını, havanı, besinini,
sevdiğin kadını,
taptığın oğlunu
aldılar elinden.
Bir sen varsın
maden ocağının dibinde,
direnen.
Aldo  SEVERİNİ', 'Maden ocağının dibinde ışık yok. Hava yok maden ocağının dibinde. Maden ocağının dibinde besin yok. Karın yok maden ocağının dibinde. Oğlun ...', ARRAY['Türk Edebiyatı','Şiir','Aldo  Severi̇ni̇']::text[], 8.5, '{"poet":"Aldo  Severi̇ni̇","poet_slug":"aldo_severini","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MADENCİ', 'madenci-yusuf-altunel-lqfbu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yığılın çığlar üstüme dedi
gökyüzü döküldü yerlere
dizeleri ayıkladılar göçüğün içinden
geriye dökülememiş gözyaşları kaldı
bir de
söylenmemiş bir çift söz', 'yığılın çığlar üstüme dedi gökyüzü döküldü yerlere dizeleri ayıkladılar göçüğün içinden geriye dökülememiş gözyaşları kaldı bir de söylenmem...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAESTA ET ERRABUNDA', 'maesta-et-errabunda-charles-baudelaire-job2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Agathe, uçtuğu var mı ruhunun arasıra,
Büyülü, mavi, derin ve ışıl ışıl yanan
Bambaşka denizlere, bambaşka semalara,
Şu kahrolası şehrin simsiyah havasından?
Agathe, uçtuğu var mı ruhunun arasıra?
Hey trenler, vapurlar beni burdan götürün!
Ne var gözyaşlarından çamurlar yuğuracak?
Arasıra der mi ki Agathe''ın ruhu, üzgün,
"Nedametten, azaptan ve ıstıraptan uzak
Hey trenler, vapurlar, beni burdan götürün."
Ne kadar uzaktasın ey mis kokulu cennet,
Ey, sadece sevincin, aşkın ürperdiği yer,
Ey her ruhun içinde bulunduğu saf şehvet,
Ey bir ömür boyunca gönül verilen şeyler!
Ne kadar uzaktasın ey mis kokulu cennet!
Ah o yeşil cenneti, çocuksu sevdaların,
O koşuşlar, şarkılar, o demetler, buseler,
İnildeyen kemanlar arkasında sırtların,
Akşam, korkuluklarda şarap dolu kâseler,
- Âh o yeşil cenneti çocuksu sevdaların!
O bilinmez zevklerin yüzdüğü mâsum belde?
Çok daha uzakta mı yoksa Çin''den, Maçin''den?
Beyhude bir arzu mu inildeyen dillerde,
Canlanan bir hayal mi billûr sesler içinden,
O bilinmez zevklerin yüzdüğü mâsum belde?
Charles  BAUDELAIRE', 'Agathe, uçtuğu var mı ruhunun arasıra, Büyülü, mavi, derin ve ışıl ışıl yanan Bambaşka denizlere, bambaşka semalara, Şu kahrolası şehrin sim...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'M''AGAPAS?', 'm-agapas-roni-margulies-8hzhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kanada romanını öğrendim,
benim kalemimden Külebi okuyan
Selanikli bir küçük kızdan.
Ortak paydamızdı dil bizim.
İki dilde oyunlar oynar,
bir üçüncüsünde konuşurduk.
Rumca öğretirdi bana,
ben ona Türkçe, becerebildiğimce.
Çekilir İngilizce sevişirdik sonra.
Yarım kaldı gerçi Rumcam ama,
tüm sevgi sözlerini öğrendim.
Geri kalanınıysa sözcüklerin
söylemek gelmiyor zaten içimden,
ne İngilizce, ne Türkçe,
ne de artık öğrenmeyeceğim herhangi bir dilde.', 'Kanada romanını öğrendim, benim kalemimden Külebi okuyan Selanikli bir küçük kızdan. Ortak paydamızdı dil bizim. İki dilde oyunlar oynar, bi...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAHALLE KAHVESİ', 'mahalle-kahvesi-mehmet-akif-ersoy-n03mh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çamurlu bir kapı, üstünde bir değirmi delik;
Önünde tahta mı, toprak mı? sorma, pis bir eşik.
Şu gördüğün yer için her ne söylesen câiz;
Ahırla farkı: O yemliklidir, bu yemliksiz!
Zemini yüz sene evvel döşenme malta imiş...
"İmiş"le söylüyorum, çünkü anlamak uzun iş.
O bir karış kirin altında hangi maden var?
Tavan açık kuka renginde; sağlı sollu dıvar,
Maun cilâsına batmış tütünlü nargileden;
Duman ocak gibi çıkmakta çünkü her lüleden.
Dikilmiş ortaya boynundan üstü az koyu al.
Vücudu kapkara, leylek bacaklı bir mangal.
Kenarda, peykelerin alt başında bir kirli
Tomar sürükleniyor, bir yatak ki besbelli:
Çekilmiş üstüne yağmurluğumsu bir pırtı,
Zavallının güveden hep liyme liyme sırtı.
Kurur bir örtünün üstünde yağlı bir mendil:
Ki "ben tependen inersem" diyen hasır zembil
Onun hizasına gelmez mi? Bir döner şöyle;
Sicimle kulpuna ilmikli çifte mestiyle!
Duvarda eski ocaklar kadar geniş bir oyuk,
İçinde camlı dolap var ya, raflarında ne yok!
Birinci katta sülük beslenen büyük kavanoz;
Onun yanında kan almak için beş on boynuz.
İkinci katta bütün kerpetenler, usturalar...
Demek ki kahveci hem diş tabibi, hem perukâr,
İnanmadınsa değildir tereddüdün sırası;
Uzun lâkırdıya hâcet ne? İşte mosturası:
Çekerken etli kemiklerle ayrılıp çeneden,
Sonunda bir ipe, boy boy, onar onar dizilen
Şu kazma dişleri sen mahya belledinse, değil;
Birer mezâra işaret düşün ki her kandil!
Seyirciler mütefekkir, güzide bir tabaka;
Düşünmelerdeki şiveyse büsbütün başka:
Kiminde el, filân asla karışmıyorken işe,
Kiminde durmadan işler benân-ı endîşe!
Al işte: "Beyne burundan gerek" demiş de "hulûl"
Tahharriyat-i amîkayla muttasıl meşgul!
Mühendis olmalı mutlak şu ak sakallı adam!
Zemine, daire şeklinde yaydı bir balgam:
Abanmış olduğu bir yumru yumru değnekle,
Mümâslar çizerek soktu belki yüz şekle!', 'Çamurlu bir kapı, üstünde bir değirmi delik; Önünde tahta mı, toprak mı? sorma, pis bir eşik. Şu gördüğün yer için her ne söylesen câiz; Ahı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet_akif_ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAHKUMLAR', 'mahkumlar-orhon-murat-ariburnu-9q90j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekseriya sabaha karşı
Kurşuna dizilir mahkumlar
Bir sünger taşına döner
Anne sütünden yapılan heykel
Bari şu trampetler çalmasa,
İnsan gürültüye gitmese!..', 'Ekseriya sabaha karşı Kurşuna dizilir mahkumlar Bir sünger taşına döner Anne sütünden yapılan heykel Bari şu trampetler çalmasa, İnsan gürül...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Ariburnu']::text[], 8.5, '{"poet":"Orhon Murat Ariburnu","poet_slug":"orhon_murat_ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAHZUN DOĞAN', 'mahzun-dogan-annelerin-sesi-mavi-pu0dv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annelerin Sesi Mavi,
M.Mahzun DOĞAN, Altın Portakal Kültür ve
Sanat Yayınları, Nisan 2002
Annelerin Sesi Mavi, Mahzun Doğan''ın anne şiirleri
seçkisi. Seçkinin yıllar süren titiz bir çalışmanın ürünü olduğu hemen
anlaşılıyor. Seçilen şiirler zamana meydan okuyan türden. Kitabın
sayfalarını çevirdikçe, anne sıcaklığında dizelerle karşılaşacaksınız.', 'Annelerin Sesi Mavi, M.Mahzun DOĞAN, Altın Portakal Kültür ve Sanat Yayınları, Nisan 2002 Annelerin Sesi Mavi, Mahzun Doğan''ın anne şiirleri...', ARRAY['Türk Edebiyatı','Şiir','Annelerin Sesi Mavi']::text[], 8.5, '{"poet":"Annelerin Sesi Mavi","poet_slug":"mahzun_dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAJÜSKÜL BİR KADIN YÜZÜNE', 'majuskul-bi-r-kadin-yuzune-refik-durbas-0dwsp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eski yazma kitaplarda aranan
saçları kadifeli ipek bir kadın
gittiği her yeri bir majüskül sanarak
yüzünün bir yanını yazlık sinemalara
bir yanını bekâr adamlara uyduruyor
Sokak sesli eskürbacı mı bu kadın
el kadar bir tiren taşıyor koynunda
ki onu herkes soyguncu bilmektedir
vampir diye yazıldığı kitaplarda
bir sansarla evlendiği de söyleniyor
İçinde aşkın hurda bisikleti
nereye gitse bir harf uçuyor yüzünden
tenha ve gizli takvimlerde
şimdi yapma bir gül kalmıştır elinde
tahta atıyla geçtiği günlerden', 'Eski yazma kitaplarda aranan saçları kadifeli ipek bir kadın gittiği her yeri bir majüskül sanarak yüzünün bir yanını yazlık sinemalara bir ...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MALDOROR''UN ŞARKILARI''NDAN', 'maldoror-un-sarkilari-ndan-lautr-amont-hi5mo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, ey okur, bu yapıtın başında kine başvurmamı istersin belki de! Güzel  ve kara bir  havada,
tıpkı köpekbalığı gibi engin bir kösnüye gömülmüş durumda sırt üstü  devrilip, gururlu,  geniş ve
ince burun deliklerinle istediğin kadar kini içine  çekemeyeceğini  kim  söyledi  sana,   eğer  bu
eylemin önemi kadar senin o kızıl kokulara olan haklı iştahının önemini de ağır ağır ve görkemle
anlıyorsa? Daha önce eğer Tanrı''nın lânetli vicdanını arka arkaya  üç  bin kez  içine   çekmeye
kendini kaptırmazsan, inan bana ey canavar, çirkin suratının o iki biçimsiz deliğini eğlendirecektir
o kokular. O sözle anlatılmaz hazlardan alabildiğine hoşnut kalacak olan burun deliklerin, güzel
kokulardan, buhur kokularından başkasını duymak istemeyecekler bir daha;  çünkü,  o   cânım
göklerin görkeminde ve dinginliğinde yaşayan melekler gibi eksiksiz mutlulukla tıkabasa doymuş
olacaklar.
§§§
Maldoror''un mutlu yaşadığı o ilk yıllarda nasıl iyi yürekli biri olduğunu anlatacağım birkaç satırda.
Daha sonra, kötü ruhlu doğmuş olduğunu fark etti: Ne garip yazgı! Kişiliğini elinden  geldiğince
gizledi uzun yıllar, ama sonunda, şu alışık olmadığı gerilim yüzünden, her gün kan beynine çıkmaya
başladı; böylesine bir yaşama artık katlanamadığı için de, sonunda,  kararlı  bir biçimde kötülük
mesleğine adandı… bu tatlı dünyaya! Pembe yanaklı küçük bir çocuğu sevip dururken yanaklarını
usturayla kesip koparmak isteyeceği kimin aklına gelir, ve eğer Adalet''in türlü türlü cezaları gözünün
önüne gelmemiş olsaydı kim bilir kaç kez yapardı bu işi.Yalancı biri değildi, gerçeği kabul ediyor ve
kendisinin bir kan dökücü olduğunu söylüyordu. İnsanlar, duydunuz mu? Bu  titreyen kuş teleği
kalemle de aynı şeyi tekrarlamaktan utanmıyor. Sanki istençten de güçlü yetke… Bir lânet! Yerçekimi
yasalarına karşı koyabilir mi taş? Olanaksız. Kötülük, iyilikle bağlaşma yapmak isterse, olanaksızdır.
Yukarıda söylediğim de buydu benim zaten.
§§§
İmgelemin yarattığı ya da sahip oldukları, soylu duygular sayesinde insanların övgülerini kazanmak
için yazar kimileri. Ben, kan dökücülüğün tadını betimlemek için kullanıyorum dehâmı! Gelip geçici,
yapay zevkler için değil; ama insanla başlamış,  insanla  sona  erecek  olanlar  için.  Tanrı''nın  gizli
kararlarına uygun olarak kan dökücülükle bağlaşma yapamaz  mı dehâ?  Ya  da,  kan dökücü biri
dehâ sahibi olamaz mı? Bunun kanıtını  benim  sözlerimde  bulacaksınız;  isterseniz,  beni  dinleyip
dinlememek sizin elinizde. Bağışlayın, bana öyle geliyor ki  saçlarım diken diken oldu; ama, önemli
değil, çünkü, elimle, kolayla eski durumlarına getirebilirim onları.  Bu,  şarkı   söyleyen kişi, tek sesli
parçalarının bilinmedik  şeyler  olduğunu ileri  sürmüyor;  aksine,  kahramanının  kibirli  ve  kötücül
düşüncelerinin bütün insanlarda bulunmasına alabildiğine seviniyor.
§§§
Yaşamım boyunca, istisnasız hepsi de budalaca işler yapan dar omuzlu insanlar gördüm ve çoğu
türdeşlerini şaşkına çevirip ruhları türlü şekilde baştan çıkarırlardı. Eylemlerine gerekçe olarak "ün"ü
gösterirler. Onları görünce herkes gibi gülmek istedim ben de; ama böylesine tuhaf bir  öykünme
olanaksızdı benim için. Keskin ağızlı bir bıçak aldım, dudaklarımın birleştiği yerlerde etimde yaralar
açtım. Amacıma ulaştığımı sandım bir an. Kendi elimle yara açtığım bu ağıza baktım aynada!  Bir
yanılgıydı! İki yaradan akan kan, gerçekten başkalarının gülüşü olup olmadığını anlamama engel
oluyordu aslında. Ama, bir süre karşılaştırma  yaptıktan  sonra,  gülüşümün  insanların  gülüşüne
benzemediğini gördüm, yani gülmüyordum ben, gülüşüm yoktu benim. Çirkin suratlı, gözleri karanlık
gözevlerine gömülmüş insanlar gördüm; kayanın sertliğini, dökme çeliğin katılığını, köpekbalığının
kan dökücülüğünü, gençliğin küstahlığını, canilerin mantıksız öfkesini, iki yüzlülerin ihanetlerini, en
olağanüstü oyuncuları, rahiplerin kişilik gücünü ve dışardan bakınca en içe kapalı, dünyaların ve
göklerin en soğuk yaratıklarını aşıp geride bırakmışlardı; ahlâkçılar bitkin düşmüştü, yüreklerindekini
görmeye, Tanrı''nın amansız öfkesini başlarına yağdırmaya çalışırken. Hepsini bir arada gördüm; kimi
zaman, belki de bir cehennem cini tarafından kışkırtılmış, dondurucu bir sessizlikte gözlerine hem
yakıcı hem kinli bir pişmanlık acısı sıvanmış durumda, annesine daha şimdiden başkaldıran bir çocuk
benzeri en sıkı yumruklarını havaya kaldırdıklarını, bağırlarının gizlediği o alabildiğine adaletsiz ve
dehşet yüklü, tutkulu ve düşman düşüncelerini ortaya çıkarma yürekliliğini gösteremediklerini ve
bağışlayıcı Tanrı''yı merhametten kederlendirdiklerini gördüm; kimi zaman, günün her anında, yediden
yetmişe insanlara, soluk alan her şeye, kendilerine ve Tanrı''ya karşı mantıksız ve akıl almaz lânetler
yağdırırlarken, kadınları ve çocukları kötü yola düşürürlerken, vücudun edep yerlerini kirletirlerken
gördüm onları. O zaman, sularını yükseltir deniz, tekneleri dipsiz derinliklerinde yutar; kasırgalar ve
depremler yerle bir ederdi evleri; veba, türlü türlü hastalıklar kırıp geçirirdi yakaran ailelerini. Ama
insanlar anlamaz bunları. Yeryüzündeki davranışları yüzünden utançtan kızarırken, sararırken de
gördüm onları; ama pek ender. Kasırgaların kız kardeşi fırtınalar; güzelliğini kabul etmediğim mavi
gökkubbe; yüreğimin imgesi iki yüzlü deniz; bağrı gizemli dünya; öteki gezegenlerin halkları; bütün
evren; onu cömertçe yaratan Tanrı, sana yakarıyorum: İyi bir insan göster bana!.. Lûtfun on katına
çıkarsın doğal güçlerimi; çünkü, bu canavarı görünce şaşkınlıktan ölebilirim:
Daha azı için bile ölünebilir.
LAUTRÉAMONT', 'Sen, ey okur, bu yapıtın başında kine başvurmamı istersin belki de! Güzel  ve kara bir  havada, tıpkı köpekbalığı gibi engin bir kösnüye göm...', ARRAY['Türk Edebiyatı','Şiir','Lautréamont']::text[], 8.5, '{"poet":"Lautréamont","poet_slug":"lautreamont","theme":"Türk Şiiri","is_hero":false,"total_lines":64}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAMUDU DİYOR Kİ RİMBAUD''YA', 'mamudu-di-yor-ki-ri-mbaud-ya-mahmut-temi-zyurek-84xq8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzülme ey, Saf Aşırı
Korur seni dizelerin
Nasıl yaşadın, tanığım
İndiğine taşa hançerin
Sapladın onca varlığını
Bu musalla dünyaya
Gözlerindedir öylece
Eyleminden saçılan ateş
Rimbaud, dostum, varlığım
Zavallı ateş böceğim
Anımsa, ne yürekler acıdı sana
Ne şaraplar içti seni
Acıydın önceden önce
Mutsuzluk tanrın oldu
Ölüm yaladıkça enseni
Kaçışı yok aşktan başka
Gitme uzaklara, her yer cehennem
Cinnetinle kal, öyleyiz nasılsa
Sözlerim avutmuyorsa da kal
Gitmesen, içkiler benden olsa
Üzülme ey, Saf Aşırı
Ey enginden yüce
Yine gelecek aşkın çağ
Rüzgâra adanmış atlarla', 'Üzülme ey, Saf Aşırı Korur seni dizelerin Nasıl yaşadın, tanığım İndiğine taşa hançerin Sapladın onca varlığını Bu musalla dünyaya Gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Mahmut  Temi̇zyürek']::text[], 8.5, '{"poet":"Mahmut  Temi̇zyürek","poet_slug":"mahmut_temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMAN', 'i-man-vladimir-mayakovski-3gq9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstediğiniz kadar uzatın bekleyişi
gördüğüm şey öylesine berrak
ve bu berraklık bir masal gibi
öylesine bırakmıyor ki beni
şu uyağı koyunca
çok daha güzel bir hayata tırmanacağım
ikinci dize uyunca.
En basit bir soruya bile ihtiyacı yok artık:
Tüm ayrıntılarıyla görüyorum işte
nağme nağme yükseliyor
taş taş üstünde yükselir gibi
ve ne bir pislik ne de bir toz zerresi
tüm hatlarıyla görüyorum yükseliyor
pırıl pırıl yüzyıllardan katlarıyla
insanları diriltme atölyesi...
İşte
geniş alınlı kimyager
deneylerin kırışıklığı
çehresinde.
Kitaptan
-"Bütün Dünya''dır adı kitabın-
şöyle bir sayfa açıyor:
Yirminci Yüzyıl...
"Kimi diriltsek acaba?...
Mayakovski''yi?...
Yok canım! Yeni baştan yaşatmaya değmez o şair...
Daha güzel daha değerli daha iyi
birini arayalım..."
Ve nasıl haykırıyorum bilseniz
nasıl haykırıyorum avazım çıktığı kadar
buradan
Bitirmek üzere olduğum şu sayfadan:
"Boşuna karıştırma ilerki sayfaları!
Dirilmeyi hakkeden sadece ben varım!"
Vladimir MAYAKOVSKI', 'İstediğiniz kadar uzatın bekleyişi gördüğüm şey öylesine berrak ve bu berraklık bir masal gibi öylesine bırakmıyor ki beni şu uyağı koyunca ...', ARRAY['Türk Edebiyatı','Şiir','Vladimir Mayakovski']::text[], 8.5, '{"poet":"Vladimir Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMANA GELDİM', 'i-mana-geldi-m-can-yucel-c37mn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kız buldu beni akşam üstünde
Bâkire değil ama kızmış
Allahına kadar
O ne memeler o
O ne uyluklar o
Ooo
Hele o engebesiz aşağlara
İnen o göbeği o
O müselles o müselles o
Hiç ağda görmemiş ayda
Allahıma güzel
İşte o zaman imana geldim', 'Bir kız buldu beni akşam üstünde Bâkire değil ama kızmış Allahına kadar O ne memeler o O ne uyluklar o Ooo Hele o engebesiz aşağlara İnen o ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANASTIR KUŞÇUSU', 'manastir-kuscusu-nihat-behram-8g88l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'zor bir nakış gibi işliyorum
liseyi ve aşkı
hüzünden bir kanaviçeye
Üveyikler ibibikler arıyorum
kandillerle gece çullukları
bana bir salgını çağrıştıran
bıldırcınlar
lise öğretmenlerinin dolduğu
odalardan
sarı asmalar ürküyor koştuğumda
kim bilir kuşların öldüğünü
rüzgar geçerken selviler arasından
sepetime diken gülleri toplayıp
annemin güzelliğine üzgün
kuşlar vurduğumu benim
çağlalar çaldığımı
kim bilir hala nasıl süslüyor
beni
o yusufçuk sesleri
şimdi kumruların angutların
kaçıştığı
çocukların mavi serçeler topladığı
aile albümünden bir yüreği
hızla soyunuyorum
hızla soyunuyorum karanlık
koynumdan
liseli kitaplarımı
Nihat', 'zor bir nakış gibi işliyorum liseyi ve aşkı hüzünden bir kanaviçeye Üveyikler ibibikler arıyorum kandillerle gece çullukları bana bir salgın...', ARRAY['Türk Edebiyatı','Şiir','Nihat
behram']::text[], 8.5, '{"poet":"Nihat\nbehram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANDEPSİYE UYANIŞ-KAS GEVŞETİCİ-UZLAŞMA', 'mandepsi-ye-uyanis-kas-gevseti-ci-uzlasma-umut-taydas-5fi0m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I - Mandepsiye Uyanış
karasın, karanlıksın;
kerelerce kara çıkardım senden,
bu sadece cımbızla tüy çekmek gibi oldu,
yerlerine yenileri büyüdü,
asıl köklerin yerlerini,
karalığın sebebini hiç bulamadım.
karasın, kara kalacaksın,
aydınlanmak yok,
kandırdığın ben''lerle, kanmayan bir ben yaratacaksın,
soğuk duşlardan kaçarken göstereceksin cesaretini,
kımıldamayışınla ortaya çıkacak kurguların gerçeği
yüzünü pudralarsın ve silinir zamanla,
yüzünü göstereceksin...
karasın, gözlerinin beyazı yok.
ülkü getirdim, en temizlerinden,
tepkimeye giremedin,
seninle yürümek istiyorum,
çabuk yoruluyorsun.
beni korkutuyorsun,
sen beni korkuttukça, seni kaybetmekten korkmuyorum,
seninle konuşmaktan takatim kalmadı seninle konuşmaya,
bir kere sızmıştın, çok uzun uyumuştun,
yanında en rahat olduğum gün o oldu.
karasın, zararlısın, doymazsın,
göğüslerinin sarkıklığından anladım.
II - Kas Gevşetici
seni hiç sevmedim ki ben,
kim olduğunu çok iyi biliyordum,
seninle çok yalnız kalıyordum,
sana dokunmaya muhtaçtım,
sıcaklığına bakışlarının, sırlarına,
ışığını yitirmiş ayasına ellerinin, alnıma değen,
seni hiç sevmedim ki ben,
sadece seni sevmeye muhtaçtım,
ve mahkumuydum buraların,
ve sen ne kadar da karaydın,
kendimi sana düşürdüğümden beri
kendimi arıyorum.
III - Uzlaşma
senin hep boynun bükük,
çocukluğunun gölgesinde uyuyorsun,
bıyıklı bıyıklı bakıyorsun bana,
kessen onları sanki, herkes herşeyi bilecek,
kimse sana el sürmeyecek,
en büyük hataların,
kendini suçladığın günlerde,
kendine yaptığın işkencelerdi;
onların yüzünden artık karasın,
seni çok fazla anlıyorum,
ve seni anlamaktan ölesiye korkuyorum,
seni anladıkça tükeniyor gücüm,
tiksiniyorum,
seni anladıkça,
herkesten ve herşeyden nefret etmeye başlayıp,
seni sevmeye bir ben kalmamasından korkuyorum.
öyleyse sen kendine bir bak,
bu kadar masum musun ?
kendini masumlaştırışın,
benim seni, suçsuzmuş gibi göğsüme basışım,
hepsini bitirdim, hepsini geçtim,
karanlık;
beni de kandırıyor olmaktan rahatsız olmuyor musun ?
bunu kim bilebilir,
kim bilebilir en son ne zaman gerçek olduğunu,
karanlığım, konuşma,
sana artık sadece zorunluluktan yaşayabilirim,
ikimiz de bu meczup oyunu kazanmak için yaşıyoruz,
sonunda,
ikimiz de kaybeden olacağız...
14.06.01 - 22:08
"yoksa herşeyimizi birbirimizden,
hiç tanımadığımız birilerine kuytularda elletmek için mi saklıyoruz yıllarca ?"', 'I - Mandepsiye Uyanış karasın, karanlıksın; kerelerce kara çıkardım senden, bu sadece cımbızla tüy çekmek gibi oldu, yerlerine yenileri büyü...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":75}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANDOLİN', 'mandoli-n-ergin-gunce-mol6r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eski bir mandolindi ölümdü anlatılan
Kır kahvesinde çocuklara çalardı
Temmuz örerken evini sarmaşıkla
Çan çiçekleri göğsünde kuru kalbi
Serilince bahçeye rakı sofrası
Kucağında mandolin, mandolin ve parmakları
Ne yalnızlık kalır ne aşk
Ne gizlice bildiği av şarkıları
Ay dudağında kuruduğu zaman
Ve ne zaman görse çocukları
Serin yaz geceleri penceresinden
Balkona akınca gölgesi
Saçlarında deniz ve uçuşan şapkası
Eski bir mandolindi ölümdü anlatılan
Şimdi kış ve uykusuz çocuklar
Uzak bir mandolin kulaklarında kalan', 'Eski bir mandolindi ölümdü anlatılan Kır kahvesinde çocuklara çalardı Temmuz örerken evini sarmaşıkla Çan çiçekleri göğsünde kuru kalbi Seri...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin_gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANGAL', 'mangal-necip-fazil-kisakurek-4ibgl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana tül gibi ince
Bir hülya verir mangal.
Küllerini deşince,
Titrer, ürperir mangal.
Şikâyetsiz âşıklar
Gibi içinden yanar,
Fâni günleri anar,
Sabaha erir mangal...', 'Bana tül gibi ince Bir hülya verir mangal. Küllerini deşince, Titrer, ürperir mangal. Şikâyetsiz âşıklar Gibi içinden yanar, Fâni günleri an...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİK OBSESİF', 'mani-k-obsesi-f-umut-taydas-3zq60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '"kendi kendine konuşmak''lara..."
bulmuştur, bölmüştür;
olmuştur ya da oldurulmamış,
kafam çatlak, bulaşık çok,
ellerim keneften yeni çıkmış,
frengi meçhul.
döndüm beriye, uzandım seyirlik,
"anlam" için gelmişim stampol''a,
hiç bir yer evim değil dedim,
aklından ve altından başka;
oysa onlar da rest çekti aşka.
stampol ya bu, kelek aldım bolca,
-en çok inandığın, güvendiğin insan,
stampol''da 6 ay kalsın, tanıyamazsın-
olsun dedim, varsın;
o yeter, anlam yine aklın,
altından olmasa da, düşlemişiz bir geleceği,
pek de fiyakalı değil, dilenciye versen beğenmez,
olsun dedim kalsın; istiyorsun,
niceliğin ne önemi war,
yıl 2000''li ve sen sevdaya inanıyorsun..
aynı odada, aynı bakışla kalakaldım yüzyıllarca,
stampol''du bu, kelek aldım,
aldırmadım; "geçer" dedim, alışılır,
inancım tam, sevdam aklımı aşmış, beni bastırmış,
anlamım, beklemek olsun boşver.
gördüm de olanları "tiskindim",
acemi tezcanı, sağa bastım ayağımı, illet,
onun bunu, diğerinin ötekisi olmuş,
berikinin öbürü de, bunun orasında muamelede.
sola kaçtım apansız, şirret,
oradakinin orasında oynaşmamış bir ben kalmışım,
şuradaki de adımımı attığımdan beri, salyalar akıtarak takip ediyor beni.
kaçtım ortaya, kustum.
yürüdüm. sustum.
hep ortadan yürüdüm, ne çevirdim başımı "essalamü aleyküm" sağa,
ne solun zerresini gördü gönlüm.
ihanet zehrinin kumpas şehri stampol''da,
sana ihanetten uzak tutmak için kendimi,
kendime ihanettimden aklın bulanmasın diye,
hazmedemeyeceğim hiç bir şeyi yememek için;
"bu ben"i bozdurmadan, azdırmadan, yardırmadan,
sana getirebilmek için -sana saf gelebilmek için-
hep ortadan yürüdüm.
çok yol yürüdüm, yokça çok yoruldum.
karşıla beni artık, ses ver, konuşmayı unuttum.
saflığımı sana getirdim, al, öp, okşa, sırtımı kaşı.
beğenmediysen söyle, sırtıma asıp gideyim,
sana getirdiğim, sana esirgediğim ne varsa.
ses ver, çık ortaya, burada olacaktın,
bekleyecektin.
şimdi var mısın ?
şimdi nerede, sağda mı, sol da mısın,
stampol''un yalanına mı kandın,
bindiğin bir takside mi unuttun,
"biz"li yalnızlıkları.
günüm zifir, geleceğim katranlı,
kaç yaşındayım bilmiyorum,
yaşımda olamadım hiç,
yaşım, başkalarınındı.
sevdiğimi yaşamaya çalıştım hep,
misal dedem ölüyordu,
senli, beraber 3-5 saat için,
varsın ölsün dedim, o öldü,
senli en fazla 2 saatim oldu.
çok yürüdüm ortalardan ya,
yoruldum, ayaklarıma ortacılık battı,
"ah" çıkarmadım,
yorgunum diye, benden uzakta uyumandan korktum.
her "gele" kızdın sen,
hepsi ağlamak oldu,
göz yaşım, aşka dargınlığımdı.
şimdi bana, "sana yetmez" diyorsun,
istediğim sadece "seninle olmak"ken,
sözlerini, "illallah"a bulayıp, intizar ediyorsun.
susmaktan, uyumaktan, kaçmaktan,
ağlamaktan, solo yalnızlıklardan, göz yummaktan,
sindirmekten sonra bana,
seni istememeyi öğretiyorsun.
olsun.
seni beklemeye başladığımda,
kaderimin beklemek olduğunu biliyordum;
frengi makbul...
ve sen şiyyir misin nesin,
ne zaman kendi "kendime" seni yazmaya başlasam,
onunla bitiyorsun.', '"kendi kendine konuşmak''lara..." bulmuştur, bölmüştür; olmuştur ya da oldurulmamış, kafam çatlak, bulaşık çok, ellerim keneften yeni çıkmış,...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":88}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİLER', 'mani-ler-orhan-seyfi-orhon-eqvyv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gül dalında gonca,
Ben dağ yolunda yonca.
Sen açılıp gülersin,
Ben sararıp solunca!
* * *
Sevdi aldattı beni;
Güldü, ağlattı beni!
Gittim kölesi oldum;
Götürdü sattı beni!
* * *
Can işte... Canan hani?
Dert işte!... Derman hani?
Gönül sarayı bomboş,
Beklenen sultan hani?', 'Sen gül dalında gonca, Ben dağ yolunda yonca. Sen açılıp gülersin, Ben sararıp solunca! * * * Sevdi aldattı beni; Güldü, ağlattı beni! Gitti...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi̇ Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi̇ Orhon","poet_slug":"orhan_seyfi_orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANZARA GÜLÜŞLÜ KIZ', 'manzara-guluslu-kiz-enver-ercan-pmgyy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'öpüşmekte güçlük çeken bir kızdı işte
üstelik düşlerimden ödü kopardı
ne zaman farlar geceyi çizse
teni sakallarımda yanardı
soruları rahatlatan bir yanıttı belki
şimdi evde olsak
ne güzel
yatıp uyumazdık derdi
ev türkçesi ışırdı sesinde
dilime dolaştıkça sözcükleri
acıyı andıran bir anı artık
odamın şaşkınlığı bundan
düştutan akşam saatlerine
usul usul damlıyor zaman
gökyüzünde tuhaf bir başdönmesi', 'öpüşmekte güçlük çeken bir kızdı işte üstelik düşlerimden ödü kopardı ne zaman farlar geceyi çizse teni sakallarımda yanardı soruları rahatl...', ARRAY['Türk Edebiyatı','Şiir','Enver Ercan']::text[], 8.5, '{"poet":"Enver Ercan","poet_slug":"enver_ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANZARA', 'manzara-oktay-ri-fat-78q8w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçük bir lavanta çiçeği
Sarışın arı
Ve alabildiğine gelincik
Düşünmeden sevdiğimiz bu anda
Birdenbire başlayan gökyüzü', 'Küçük bir lavanta çiçeği Sarışın arı Ve alabildiğine gelincik Düşünmeden sevdiğimiz bu anda Birdenbire başlayan gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat']::text[], 8.5, '{"poet":"Oktay Ri̇fat","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MARİFET', 'mari-fet-bedri-rahmi-eyuboglu-hn9sz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Marifet hiç ezilmemek bu dünyada
Ama biçimine getirip ezerlerse
Güzel kokmak
Kekik misali
Lavanta çiçeği misali
Fesleğen misali
Itır misali
İsâ misali
Yunus misali
Tonguç misali
Nâzım misali', 'Marifet hiç ezilmemek bu dünyada Ama biçimine getirip ezerlerse Güzel kokmak Kekik misali Lavanta çiçeği misali Fesleğen misali Itır misali ...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyuboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyuboğlu","poet_slug":"bedri_rahmi_eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MARŞIMIZ', 'marsimiz-vladimir-mayakovski-xuxn3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İsyanın ayak sesi, alanları döv!
Yukarı, gururlu başlar dizisi!
Biz, ikinci Nuh tufanıyla
Yeniden yıkayacağız dünyanın tüm kentlerini.
Günlerin öküzü hantal,
Yılların kağnısı ağır,
Tanrımız koşudur bizim
Yüreğimizse davul.
Altınımızdan daha yücesi var mı?
Kurşun vızıltısı mı bizi sindirir?
Çınlayan sesimizdir o altın;
Silahımızsa türkülerimizdir.
Yeşilliklerle örtülsün kırlar
Serilsinler günlerin altına
Gökkuşağı koşum olsun
Yılların Küheylanına.
Gök pek sıkkın görünmede nedense,
Onsuz dalgalandıralım türkülerimizi,
Hey büyük Ayı! söyle de
Oraya yaşarken alsınlar bizi!
Mutluluğu iç! Türkünü söyle!
Bahardır akan damarlarımızda
Vursun savaş temposunu yürek
Bakır bir trampet olan bağrımızda.
Vladimir  MAYAKOVSKI', 'İsyanın ayak sesi, alanları döv! Yukarı, gururlu başlar dizisi! Biz, ikinci Nuh tufanıyla Yeniden yıkayacağız dünyanın tüm kentlerini. Günle...', ARRAY['Türk Edebiyatı','Şiir','Vladimir  Mayakovski']::text[], 8.5, '{"poet":"Vladimir  Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MARTILAR', 'martilar-baris-pi-rhasan-v219x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kar yağınca
Benek benek rüzgârlar
Haydarpaşa kuşluğunda
Güvertelerden
Bayıltırlar suya bakanı
Karanlık suya
Deniz gökyüzüdür
Kara bulutlar
Dalgalandıkça
Kuşlar alçalıp durur
Çatlayan bir bulutsun
Konuverirler sırtına', 'Kar yağınca Benek benek rüzgârlar Haydarpaşa kuşluğunda Güvertelerden Bayıltırlar suya bakanı Karanlık suya Deniz gökyüzüdür Kara bulutlar D...', ARRAY['Türk Edebiyatı','Şiir','Barış Pi̇rhasan']::text[], 8.5, '{"poet":"Barış Pi̇rhasan","poet_slug":"baris_pirhasan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MARİYYA', 'mari-yya-asaf-halet-celebi-m5yld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Preguntias que significa
Saudade; voute dizer
Saudade e tudo o que fica
Depois de tudo morrer
Maria Barbas
çin kadar uzaklardan
can kadar yakından
sen bir masal kızısın
dün
çinden gelmiştin
bu gün
lizboa''dan
yüzünde tarçın kokusu
gözünde cîn
bir gün buradan gidersin
mariyya
can kadar yakın
çin kadar uzak
lizboa boyalı haritalarda kapanır
bir gün buradan gidersin
mariyya
aynalarda seni ararım
bu şehirde seni ararım
bu dünyada seni ararım
mariyyaaa', 'Preguntias que significa Saudade; voute dizer Saudade e tudo o que fica Depois de tudo morrer Maria Barbas çin kadar uzaklardan can kadar ya...', ARRAY['Türk Edebiyatı','Şiir','Asaf Halet Çelebi̇']::text[], 8.5, '{"poet":"Asaf Halet Çelebi̇","poet_slug":"asaf_halet_celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASA SARHOŞ', 'masa-sarhos-umit-sener-ta-5mz8t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gitti görüntüler
meyhanenin aynalarından
boşluğun ayakları kaldı
taş plaklarda dönen
masa sarhoş
çiçekci kızın buseleri de gitti
açılan kapının ağız kokusuyla', 'gitti görüntüler meyhanenin aynalarından boşluğun ayakları kaldı taş plaklarda dönen masa sarhoş çiçekci kızın buseleri de gitti açılan kapı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Şener Ta']::text[], 8.5, '{"poet":"Ümit Şener Ta","poet_slug":"umit_sener_ta","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASAL DÜNYASI', 'masal-dunyasi-oguz-tansel-e4a6q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O masaldaki güvercinler mi
Böyle hür dolaşan bu göklerde,
Yıkanırlar maviliklerde;
Bir kral kızı kimi,
Kimi şehzade sevgilisi,
Hatıralar gibi uçtular kanat, kanat...
Bir halk türküsünde kaybederim kendimi
Bir masal dünyasında yaşar,
Bir halk türküsünde bulurum seni.', 'O masaldaki güvercinler mi Böyle hür dolaşan bu göklerde, Yıkanırlar maviliklerde; Bir kral kızı kimi, Kimi şehzade sevgilisi, Hatıralar gib...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASAL KOKUSU', 'masal-kokusu-hasan-huseyi-n-d18ca', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bu kapıları bir bir açarım açmasına ama kırarım
Şehzadelerle gitti ölü devin altın anahtarları
Masallara dönük yüzlerinizde o hiç eksilmeyen kaygu
O donuk maviliği masal cennetlerinin
Bırakın işte gözleriniz alın işte yumruklarınız
ama siz aptalsınız aptalsınız
Birgün masallaşırsam görün işte cüceliğimi
Aktıkca büyüyen sulardı benim şarkılarda aradıklarım
Ben bu kapıları bir bir kırarım kırmasına ama siz korkaksınız
Daha çocuk bile değilsiniz siz
Devler çizersiniz altın sarayların kapılarına
sonra durup ağlarsınız ağlarsınız
Bu kan sizin kanınız , evet ama ya siz kimsiniz
Neden böyle yorgunsunuz neden böyle aldatılmış
Alıcıkuşlar döner ürpertili etlerınize
Mumyaların gölgesinde piramitler dikersiniz
Atı otu iti eti bırakıp gerçek saraylarda
sürülerle kaçarsınız kaçarsınız
Aktıkça büyüyen sulardı benim şarkılarda aradıklarım
Hasan', 'Ben bu kapıları bir bir açarım açmasına ama kırarım Şehzadelerle gitti ölü devin altın anahtarları Masallara dönük yüzlerinizde o hiç eksilm...', ARRAY['Türk Edebiyatı','Şiir','Hasan
                    Hüseyi̇n']::text[], 8.5, '{"poet":"Hasan\n                    Hüseyi̇n","poet_slug":"hasan_huseyin_korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASAL VE TRAMVAY', 'masal-ve-tramvay-mahzun-dogan-ok5s4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Ece Ayhan''a,
"Bir Askeri Şairin Ölümü!" için-
1.
Sultanahmet''te sabah. İlk günışığı
uyku süpürür saçlarından çocuk
ve Allah bir bardak çayın buğusu
Eğilirim kalbine yeryüzünün
güz de eğilir. Uğultusu
yolcusuz ilk tramvayın. Kalkıp yürür
boya sandığından kartpostal kadın
Ardısıra Nisan göğü ve Allah
fısıltısı çınar yaprağının
Masallara inan! Masallara inan! Ey
Mahzun Doğan''ın çocukluğu!
2.
Kadıköy İskelesi''nde öğleüstü. Küflenir
günışığı ansızın. Kuytusunda bir kıraathanenin
yeryüzü küflenir. Çözer palamarlarını çocuk
ve söz, suların köpüklü teni
Yunuslara inan! Yunuslara inan! Ey
Mahzun Doğan. Yunuslara ve aşka!
3.
Sirkeci''de işporta tezgâhından sarkan
bir ikindiüstü. Allah tramvaya biner
Konuş ey
Nisan göğü
- Masalların üstünden tramvay geçti!', '-Ece Ayhan''a, "Bir Askeri Şairin Ölümü!" için- 1. Sultanahmet''te sabah. İlk günışığı uyku süpürür saçlarından çocuk ve Allah bir bardak çayı...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğan']::text[], 8.5, '{"poet":"Mahzun Doğan","poet_slug":"mahzun_dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASAL', 'masal-miroslav-holub-4xxdg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ev kurdu kendine,
Temelleri,
Taşları,
Duvarları,
Başını sokacak damı,
Bacası ve dumanı
Ve penceredeki manzarasıyla.
Bir bahçe yaptı kendine,
Tahta perdesi,
Kekikleri,
Solucanları
Ve akşam çiğleriyle.
Gökten bir parça da kesti, kendine özgü.
Bahçeyi bu gök parçasına sardı,
Evi bahçeye sardı,
Ve bir mendile doldurdu tümünü.
Ve bir kutup tilkisi kadar yalnız,
Dünyanın yolunu tuttu
Soğuk
Sonu gelmez
Bir yağmurun altında.
Türkçe söyleyen: Feyyaz Kayacan', 'Bir ev kurdu kendine, Temelleri, Taşları, Duvarları, Başını sokacak damı, Bacası ve dumanı Ve penceredeki manzarasıyla. Bir bahçe yaptı kend...', ARRAY['Türk Edebiyatı','Şiir','Miroslav Holub']::text[], 8.5, '{"poet":"Miroslav Holub","poet_slug":"miroslav_holub","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASALIMSI', 'masalimsi-sukran-kurdakul-mypd1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onlar bu denizlerin son melekleriydiler
Kaç yıl mavilere karışmamı beklediler
Geldim..yelkenimde kadırgaların görkemi
En belalı dalga bile tutamazdı beni.
Ne külhanbey bıçağı, ne jandarma süngüsü
Göğsümde gizlediğim yüzgörümlüğü.
Evrenin boynunda yanıp sönene değin
Hamlet''i Ofelya''sına götüreceğim.
Benim, sabır kapısındaki ilk çilehan
Su içer gibi geçtim şeytan sofralarından.
Duyarlığı kendinde gelişen öykü
Haram sözcük nedir bilmedi çünkü.
Onlar bu denizlerin son melekleriydiler
Kaç yıl mavilere karışmamı beklediler..', 'Onlar bu denizlerin son melekleriydiler Kaç yıl mavilere karışmamı beklediler Geldim..yelkenimde kadırgaların görkemi En belalı dalga bile t...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASALLARI UNUTMAK', 'masallari-unutmak-umit-sener-ta-mwjw3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'deniz kabarır,
dalgalar ıslatır derinliği
karşımda bir gemi hazırlanır
bir çocuk görürüm gidemem
sarılır ayaklarıma iskeleler
vurulur gitmelerim
kızdım taşladım denizi
gemilere ulaştıramadım
döndüm gülümseyen çocukluğuma
bırakamam!
büyüdü mü yüreğin?
masalları çabuk unutmuşsun!
gidemedim!', 'deniz kabarır, dalgalar ıslatır derinliği karşımda bir gemi hazırlanır bir çocuk görürüm gidemem sarılır ayaklarıma iskeleler vurulur gitmel...', ARRAY['Türk Edebiyatı','Şiir','Ümit Şener Ta']::text[], 8.5, '{"poet":"Ümit Şener Ta","poet_slug":"umit_sener_ta","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MASUM ÜLKE', 'masum-ulke-huseyin-avni-ci-nozoglu-usmbo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '"Hasta kadınımsın benim
Ürkek ve yenilmiş" (*)
gelir masum ülkeme ırmaklar coştuğunda
gözetir gecenin gözyaşlarını mağlup mahzun anneleri
şehrin zemherisi daha çetin köyün zemherisinden
uzakken daha çok sevilir
bir kadın bir gurbet bir çocuk
ne gurbetim işgal edilsin ne masum ülkem
sonunda sevinç varsa
geceyi aşmalıdır insan
dünya ağlamalıdır bir çocuk ağladığında
acıdan sevinçten ördüm
yüreğimdeki kaleyi
bir deli ağaca bakıp söyledim türkülerimi
dilek tuttum
kavuşmanın büyük sevinci için
niyet kuşları intihar etmesin
Hüseyin Avni CİNOZOĞLU', '"Hasta kadınımsın benim Ürkek ve yenilmiş" (*) gelir masum ülkeme ırmaklar coştuğunda gözetir gecenin gözyaşlarını mağlup mahzun anneleri şe...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avni Ci̇nozoğlu']::text[], 8.5, '{"poet":"Hüseyin Avni Ci̇nozoğlu","poet_slug":"huseyin_avni_cinozoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MATEMATİK BİLGELİĞİ', 'matemati-k-bi-lgeli-gi-karl-marx-17zwl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I
Herşeyi özetleyip indirgedik imlere,
Kesin matematik imlerle artık Uslamlama.
Tanrı bir noktaysa eğer, silindir sayılamaz,
İnsan - üstü otururken, kafa üstü duramaz.
II
a Sevilense eğer ve b de Seven,
Öç tutarım gömleğimin on keresiylen
Ki a ile b toplandığında
Sevişen bir Çift çıkar ortaya.
III
Ölç çizgilerle Dünyanın dört yanını,
Yine de boşaltmazsın onun Canını.
a''yla b''yle kavgalar yatışsaydı eğer,
Ne işe yarardı Mahkemeler.
Karl MARX', 'I Herşeyi özetleyip indirgedik imlere, Kesin matematik imlerle artık Uslamlama. Tanrı bir noktaysa eğer, silindir sayılamaz, İnsan - üstü ot...', ARRAY['Türk Edebiyatı','Şiir','Karl Marx']::text[], 8.5, '{"poet":"Karl Marx","poet_slug":"karl_marx","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MATEMATİK ŞİİR GÖZLERİN', 'matemati-k-si-i-r-gozleri-n-arif-di-no-013tz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'iki matematik nokta
iki büyük yuvarlar siyah
iki göz siyah
simsiyah
genede siyahlığı olmayan
kızkardeş gözleri
sevgili gözleri
donuk yuvarlaklar
kenetlenen
baş döndürücü bir yarışta
en büyüğe doğru
en küçüğü doğru
yakalamak için sonsuzluğu', 'iki matematik nokta iki büyük yuvarlar siyah iki göz siyah simsiyah genede siyahlığı olmayan kızkardeş gözleri sevgili gözleri donuk yuvarla...', ARRAY['Türk Edebiyatı','Şiir','Arif Di̇no']::text[], 8.5, '{"poet":"Arif Di̇no","poet_slug":"arif_dino","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ GEZİ', 'mavi-gezi-bedri-rahmi-eyuboglu-1dliw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi gezi bir ağaçtır
Dalları deniz.
Mavi gezi bir bahçedir
Gülleri deniz.
Mavi gezi bir gelindir
Telleri deniz.
Mavi gezi bir beşiktir
Bebeği deniz.
Bebeğimin:
gözleri deniz
elleri deniz
dişleri deniz.
Mavi gezi bir rüyadır
görülmemiş.
Mavi gezi bir cennettir
ellenmemiş
dillenmemiş.
Mavi gezi bir masaldır
söylenmemiş
yazılmamış
çizilmemiş.
Mavi gezi bir mavidir, adı yok.
Ağam sensiz bu mavinin tadı yok.
Ağlamak yok, sızlamak yok mavi var
Dünya boyunca yürek dolusu
İman boyunca Allah dolusu
Otur çakıllarını boya mavi yavrusu
Hey betine bereketine, kalınlığına
Etine buduna kurban olduğum, dibi görünen su.
Bir kızım olursa adı DURUSU.', 'Mavi gezi bir ağaçtır Dalları deniz. Mavi gezi bir bahçedir Gülleri deniz. Mavi gezi bir gelindir Telleri deniz. Mavi gezi bir beşiktir Bebe...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyuboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyuboğlu","poet_slug":"bedri_rahmi_eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ GÖZYAŞLARI', 'mavi-gozyaslari-fethi-gi-ray-xvzao', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '"Yaslamış başını bir yosun taşına balık,
Ağlıyordu...
Gözlerimle gördüm:
Gözyaşları maviydi..."', '"Yaslamış başını bir yosun taşına balık, Ağlıyordu... Gözlerimle gördüm: Gözyaşları maviydi..."...', ARRAY['Türk Edebiyatı','Şiir','Fethi Gi̇ray']::text[], 8.5, '{"poet":"Fethi Gi̇ray","poet_slug":"fethi_giray","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ LİMAN', 'mavi-li-man-n-zim-hi-kmet-ydozk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok yorgunum, beni bekleme kaptan.
Seyir defterini başkası yazsın.
Çınarlı, kubbeli, mavi bir liman.
Beni o limana çıkaramazsın...', 'Çok yorgunum, beni bekleme kaptan. Seyir defterini başkası yazsın. Çınarlı, kubbeli, mavi bir liman. Beni o limana çıkaramazsın......', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ, MAVİYDİ GÖKYÜZÜ', 'mavi-mavi-ydi-gokyuzu-ahmet-hamdi-tanpinar-153qa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavi, maviydi gökyüzü
Bulutlar beyaz, beyazdı
Boşluğu ve üzüntüsü
İçinde ne garip yazdı...
Garip, güzel, sonra mahzun
Işıkla yağmur beraber,
Bir türkü ki gamlı, uzun,
Ve sen gülünce açan güller,
Beyaz, beyazdı bulutlar,
Gölgeler buğulu, derin;
Ah o hiç dinmeyen rüzgâr
Ve uykusu çiçeklerin.
Mor aydınlıkta bir çınar
Veya kestane dibinde;
Mahmur süzülen bakışlar
İkindi saatlerinde...
Birden gülümseyen yüzün
Sabahların aynasında
Ve beni çıldırtan hüzün
İki bakış arasında.', 'Mavi, maviydi gökyüzü Bulutlar beyaz, beyazdı Boşluğu ve üzüntüsü İçinde ne garip yazdı... Garip, güzel, sonra mahzun Işıkla yağmur beraber,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hamdi Tanpinar']::text[], 8.5, '{"poet":"Ahmet Hamdi Tanpinar","poet_slug":"ahmet_hamdi_tanpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ MENDİLİN TÜRKÜSÜ', 'mavi-mendi-li-n-turkusu-afsar-ti-muci-n-ix4c3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sandığa koy bu mendili kullanma
Üstünde martılar uçuşuyor
- Her biri bir mavinin telaşçısı -
Başedilmez bir deniz demektir bu
Kimseye gösterme sandığına koy bunu
Onu benden daha genç
Daha dirençli daha umutlu
Bir savaşçıya sakla
Kavuştuğunuz en güzel sabahta
Çıkarırsın sandıktan
Bu deniz yıllarca seni bekledi dersin
Söz bilmez söz anlamaz kuşlarıyla
Seni karşıladı dersin bu mendil
Hiç ıslanmadı boş bir anıyla
Ya da sen başka mendil ver ona
Denizi daha mavi kuşları daha çılgın
Kıyıları daha temiz ve güzel
Bu da kalsın sandığında öylece
Kimindi nedendi nasıldı bilinmeden', 'Sandığa koy bu mendili kullanma Üstünde martılar uçuşuyor - Her biri bir mavinin telaşçısı - Başedilmez bir deniz demektir bu Kimseye göster...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ RANDEVU', 'mavi-randevu-celal-silay-azb2k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mavi bir elbiseyle gelmiştin, gökyüzü maviydi..
Getirdiğin rüzgarla ev kokuyordun..
Kolun koluma değiyordu, omzun omzuma..
Mendilin maviydi, gökyüzü maviydi..
Bin dokuz yüz kırk iki baharıydı
Bahçeli pencereler önünde geziyorduk,
Gözlerimiz buluşuyordu, ürperiyordum
Gökyüzü maviydi, mendilin maviydi
Sıcak nefesin yüzüme değiyordu
&quot;Evlenebilir miyiz&quot; diye sormuştum,
Yürüyüşün değişmiş, yüzün penbeleşmişti;
Mavi elbiseler içindeydin, gökyüzü maviydi.
Elini elime verdin, ayrılıyorduk,
Gözlerin gözlerimde, dudakların ıslak,
&quot;Sık sık konuşalım&quot; demiştin; gittin..
Mendilin maviydi, gökyüzü maviydi..', 'Mavi bir elbiseyle gelmiştin, gökyüzü maviydi.. Getirdiğin rüzgarla ev kokuyordun.. Kolun koluma değiyordu, omzun omzuma.. Mendilin maviydi,...', ARRAY['Türk Edebiyatı','Şiir','Celal Silay']::text[], 8.5, '{"poet":"Celal Silay","poet_slug":"celal_silay","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ SEVİNCİM', 'mavi-sevi-nci-m-yasin-erol-ukyu4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin
Benim bu esrik maviyi
Bir seferde sevişim
Şimdi yanımda olmasalar da
Ve sen bazen unutsan da birilerinde
Bu yağmurlar
İnce eleyip sık dokudukça
Yeryüzünde yeşillikleri
Nasıl yok sayabilirim ki
Halen sevdiğimsin
Ne olursun
Bir başka yol bul
Artık uğrama uzaklarıma
Bir tek yağmur tanesini bile ürkütmeden
Gizli gizli sokul yanıma
Şaşırt beni korkut
Seni tanıyacak kadar
Aklım kalsın yeter
Çünkü ben aşkı
Sadece sen varsın diye yaşadım
Gözlerin
Bunlar benim mavi sevinçlerim
Şimdi yanımda olmasalar da
Ve sen bazen unutsan da birilerinde
İnan sadece onlar için
Bütün şiirlerimi evlatlıktan reddedebilirim', 'Gözlerin Benim bu esrik maviyi Bir seferde sevişim Şimdi yanımda olmasalar da Ve sen bazen unutsan da birilerinde Bu yağmurlar İnce eleyip s...', ARRAY['Türk Edebiyatı','Şiir','Yasin Erol']::text[], 8.5, '{"poet":"Yasin Erol","poet_slug":"yasin_erol","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ YAĞMURLUK', 'mavi-yagmurluk-aleksandr-blok-bswr9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yiğitliği, kahramanlığı, şânı
Bu kahpe dünyada unuturdum ben
Yanlı bir çerçevede ışıdı mı
Yüzün önümdeki masa üstünden.
Gün geldi ve sen gidiverdin.
Geceye attın aziz yüzüğünü.
Yazgını bir başkasına verdim,
Unuttum ben o güzel yüzünü.
Günler geçti, hep telaş içre,
Hayatımı yıktı şarap ve tutku…
Birden hatırladım ben seni ve
Gel dedim, gençliğime çağrıydı bu…
Çağırdım ama gelmedin nedense,
Çok gözyaşı döktüm, ilgisiz kaldın,
Mavi yağmurluğunu mahzun giyindin de
Yağışlı gecede benden ayrıldın.
Bilmem, gururun nereyi tuttu mesken.
Tatlımsın, sevgilimsin, her şeyimsin…
Mavi yağmurluğunla düşe daldım ben,
Yağışlı gecede giyip gittiğin…
Düş kurulmaz, yok artık şefkat ve ün.
Her şey bitti, geldi gençliğin sonu!
Yok artık yalın çerçevede yüzün,
Elimle masadan kaldırdım onu.
1908
Aleksandr BLOK', 'Yiğitliği, kahramanlığı, şânı Bu kahpe dünyada unuturdum ben Yanlı bir çerçevede ışıdı mı Yüzün önümdeki masa üstünden. Gün geldi ve sen gid...', ARRAY['Türk Edebiyatı','Şiir','Aleksandr Blok']::text[], 8.5, '{"poet":"Aleksandr Blok","poet_slug":"aleksandr_blok","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVERAÜNNEHİR DÖKÜLMEZ!', 'maveraunnehi-r-dokulmez-altay-oktem-sr362', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'belki seni severim umurumdasın
yalnızsın, yaralısın, sarışınsın
bir kedi yavrusunun damdan düşüşü
kadarsın, ılıksın, suçlusun
çocuklar kızmazlar bana gidersem
susarlar derslerde -bu iyi- denklem çözmezler
fatih istanbul''u alır mı bilmem
ama maveraünnehir dökülmez!
önce ben öperim gizli yerlerinden
sıcak yerlerinden, buruk yerlerinden, korkak yerlerinden
sonra bütün mahalle öper umurumdasın
çocuklar kızmazlar bana dönersem
nasılsa maveraünnehir dökülmez!
bileyciler, çingeneler, teneke tamircileri...
her sözcük bir mermi gibidir bana
bir kadını bir kadın gibi izinsiz sevemem
belki umurumdasın evet umurumdasın
bir yaprak düşer yere; çıt. işte sonbahar
gibisin, ıslaksın, çok uzaktasın', 'belki seni severim umurumdasın yalnızsın, yaralısın, sarışınsın bir kedi yavrusunun damdan düşüşü kadarsın, ılıksın, suçlusun çocuklar kızma...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay_oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİYE MEKÂN', 'mavi-ye-mek-n-meti-n-findikci-trsfq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yolumu kırıp dar odalar içinde kaldım
ipek yolunu serdin sıcak kavrulmuş tenin kaldı
bu kadar güzel durduğun denize baktıkça
kaldı kirpiklerim sırtında yaşanmış günlerin
hangi mavinin avlusunda soluksuz söyle
göster beni bıraktığın bu duvarları ören çakıl taşlarını
talanı görmeden içini okşayan kumları şimdi söyle
şaşıyorum şaşırıyorum
bir göçebe gibi biriktirdiğim koyuna
öylece dolaşıyorum denize dağıtmadan
tenine şaşıyorum
güz denizinin sürüklediği kırık hançeri
hiçbir maviye mekân olmadı biliyorum
bunu da biliyorum...', 'yolumu kırıp dar odalar içinde kaldım ipek yolunu serdin sıcak kavrulmuş tenin kaldı bu kadar güzel durduğun denize baktıkça kaldı kirpikler...', ARRAY['Türk Edebiyatı','Şiir','Meti̇n  Findikçi']::text[], 8.5, '{"poet":"Meti̇n  Findikçi","poet_slug":"metin_findikci","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAYIS NOTLARI', 'mayis-notlari-necati-yildirim-gdytu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1
beynine sağılan gazetenin yüzü
çıplak kadın resimleri
ve çapraşık cinayet haberleri
beynine sağılan gazetenin yüzü
dünyayı kucaklar mı kanlı ölüleri
toprakta boylanan bir tohumu
"çanakkale içinde vurdular beni
ölmeden mezara koydular beni"
kentsoylu yaşantıyı ırgalamıyor
vurulup düştü mü şahan kuşları
bulut gibi kaynasa da allı kızlar
rahat döşeğinde sızlamıyor yüreği
unutmam ölüleri unutmam ölüleri
2
tomurcuk gibi uyanan sesiyle
"bak baba" diyor
"onların adını söyledi"
kanlı fotoğrafları tanıyarak
acılarla büyüyen çocuğum
yeni doğan çocuklar
kavga gülü umut filizi
tütün pamuk maden işlenirken
basma dokunurken demir dövülürken
mayıs sabahında kopan umut gülleri
adınızı taşıyor yeni doğan çocuklar
3
sındırgı yokuşu
bigadiç yokuşu derken
balıkesir
dayan karda fırtınada kardeşim
halklara sevdamızı taşırken
zulümlerde
hücrelerde
darağaçlarında
ölüm yolumuzdan döndüremesin
on sekizinde
yirmisinde
yirmi yedisinde
ölüm yolumuzdan döndüremedi
mitinglerde kavgalarda grevlerde
marşlarını söylerken halkların
ırmaklara benzer şarkımız
dağlardan çağlayarak
ovaları dolanarak
vadileri yararak
yatağını besler
karla yağmurla fırtınayla
uzun yollardan
dar boğazlardan
akıp gelen ırmaklara benzer
şarkımız
umudumuz
kavgamız
halkların yüreğine yayılırken
uğultusunu duyarım karanlıklarda
4
türkülerini bıraktığın dağlarda
hoyrat rüzgârlar saçlarımı savurur
silah sesi
çiçek kokusu
orman uğultusu
yüreğimi sarsan ürperti
isyana benzer
mayıs günlerini konuşursunuz
sivas sabahından pir sultan gelir
omuz omuza vuruştuğun yiğit arkadaşlar
arkadan vurulmuş delikanlı gövdeler
voltada çeteci günleri konuşursunuz
umutlar
acılar
ayrılıklar
yüreğini demir gibi döver hücrende
şarkını söylersin acıları düşünürsün
isyana benzer baharı kucaklayamadınsa
sigaranı bir soluk daha çekersin', '1 beynine sağılan gazetenin yüzü çıplak kadın resimleri ve çapraşık cinayet haberleri beynine sağılan gazetenin yüzü dünyayı kucaklar mı kan...', ARRAY['Türk Edebiyatı','Şiir','Necati Yildirim']::text[], 8.5, '{"poet":"Necati Yildirim","poet_slug":"necati_yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":78}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAYIS', 'mayis-azer-yaran-usdh8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dirilişin nöbet günleri
Yitiyor ihtiyar yosma
Gökte bir bulut ve güvercin
İle mavi ova
Sevgi tutuşur ellerimizde
Gözlerinde oynak ateşler götürürler
Mayıs kızları bizde
Beri gel güzel kız
Yitti buzlar zamanı
Soğuk yıldızlar zamanı
Açtırayım da dereyim
Gönlünde gülistanı
Şiirler vereyim inceliğine
Beri gel güzel kız
Sıcak bir yel tadından koşarak
Yollara çıktım zakkum kokuluyum
Deli ağu ve duygu dokuluyum
Kül olmaya birikimim var
Tenimde eritiyorum heyecanı
Kız yanıt ver
Nerden tutuşturalım zamanı', 'Dirilişin nöbet günleri Yitiyor ihtiyar yosma Gökte bir bulut ve güvercin İle mavi ova Sevgi tutuşur ellerimizde Gözlerinde oynak ateşler gö...', ARRAY['Türk Edebiyatı','Şiir','Azer  Yaran']::text[], 8.5, '{"poet":"Azer  Yaran","poet_slug":"azer_yaran","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAYKU', 'mayku-oguz-tansel-e8etr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aylardan kiraz ayı
Gözlerime uyku girmez oldu
Karanlıkların ürpermesi dolar içime
Yüreğime ateş düştü Mayku.
İğde dallarından altınlar yağar
Testisi omuzunda, belinde eli
Kırlangıçların sevinci eteklerinde
Sevince dağlar dillenmeli
Burda taş olmuş gelinler kızlar
"Ayrılık var bir yandan" dudaklarında
Salla saçlarını öldür beni
Aklımı bıraktım sulara
Bahar sabahlarının tatlı yağmuru
Sendedir mânaların en güzeli
Ay akşamladı gözlerinde.', 'Aylardan kiraz ayı Gözlerime uyku girmez oldu Karanlıkların ürpermesi dolar içime Yüreğime ateş düştü Mayku. İğde dallarından altınlar yağar...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMBİK', 'i-mbi-k-enis-batur-q3t7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ve erken kalktı adam, çayı
sürdü, ince bir dilim limon
yedi, uzun uzun karanlık suya
baktı - doludingin bir gün için
güç topladı önce, radyoda dalgın,
inatçı bir ezgi buldu sonra,
sırtını yelken direğine dayayıp
eline bir kitap aldı.
Kadın uyandığında şiir
okuyordu hâlâ - sırtını kurtarıp
ona bakarken bilge bir sevgi
yayıldı gözünde: Sabah ve şiir
yaşamın tohuma döndüğü
o  sonsuz imbikte toplanıyordu.', 'Ve erken kalktı adam, çayı sürdü, ince bir dilim limon yedi, uzun uzun karanlık suya baktı - doludingin bir gün için güç topladı önce, radyo...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİMDİ ÖLME ANNE', 'si-mdi-olme-anne-hidayet-karakus-ajf34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.
bu kış yine pencereler esiyor
nereden doğduğunu bilmediğim
bir öç dalgası geliyor üstümüze
yolumuzda haramiler çengi kıyamet
kurşun izlerinde yitiriyorum
günlerin mavi saydamlığını
ekmek yarım
su kirli
toprak bitkin
ben soluksuz kaldım
yalnızlığın ihtilal yaptığı odalarda
2.
sen ilacını içtin mi
sarısı yorgun yüzünün
beni sevgiyle beklediğin günlerden kalan
biraz sıcaklığın varsa
sar anne beni
konuş benimle
sar beni
kokun dağılsın yüreğime
mercanköşk kurulmuş
zaman yüzsüz
günler yalan
akşamlarımı parçalıyor bu filmler
sinirlerim bozuk
yüzüm kırışmış
gözlerim halkalı
arkana biraz bulut koydum
hadi canım uyu biraz
kuru çalılara benziyor bu dünya
dallarında etim dikenlere takılı
9.
cennet bahçelerinin suyu kesik anne
yine
yolsuzluk sarmış mahşer ülkelerini
altın kurnalardan akan kevserlerden
umut yok
biçimsiz düşlerime dökülüyor
büyüsü yalanların
sen
hep böyle mi bakardın anne
beni görmeden mi bakardın
gözlerin gri yeşil
tenin durulmuş
ellerin saydam
bakışlarında ovalar uzanmış sabırla
konuş benimle
anlattığın masallardan
bir şehzade bırak bana
taze bir aşk mayala
sağlık karnemi ver yanıma', '1. bu kış yine pencereler esiyor nereden doğduğunu bilmediğim bir öç dalgası geliyor üstümüze yolumuzda haramiler çengi kıyamet kurşun izler...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Karakuş']::text[], 8.5, '{"poet":"Hidayet Karakuş","poet_slug":"hidayet_karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":54}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİMDİ NERDEYSE', 'si-mdi-nerdeyse-kemal-ozer-hanin', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Böyle değildi bu kentte
sokaklar, şarkılar ve insanlar.
Yürüyüp giderdik birlikte
bir heyecanı paylaşarak.
Bir gergefe girip çıkan
iğneler gibi ayaklarımız
işlerdi yürüdüğümüz yollara
coşkulu saatlerin nakışını.
Alınlarımıza biriken güneş
şimdi nerdeyse soğuyacak.', 'Böyle değildi bu kentte sokaklar, şarkılar ve insanlar. Yürüyüp giderdik birlikte bir heyecanı paylaşarak. Bir gergefe girip çıkan iğneler g...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİMDİ SEVİŞME VAKTİ', 'si-mdi-sevi-sme-vakti-sait-faik-abasiyanik-84s16', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıplak heykeller yapmalıyım.
Çırılçıplak heykeller
Nefis rüyalarınız için
Ey önünden geçen ak sakallı
kasketli,
Yırtık mintanından adaleleri
gözüken
Dilenci
Sana önce
Şiirlerin tadını
Aşkların tadını
Kitaplardan tattırmalıyım
Resimlerden duyurmalıyım,
resimlerden...
Şu oğlan çocuğuna bak
Fırça sallıyor
Kokmuş manifaturacının ayağına
Dörtyüzbin tekliğinden
On kuruş verecek.
Seni satmam çocuğum
Dörtyüzbin tekliğe.
Ne güzel kaşların var
Ne güzel bileklerin
Hele ne ellerin var, ne ellerin
Söylemeliyim
Yok
Yok... meydanlarda
bağırmalıyım,
Bu küçük
Güllerin buram buram tüttüğü
Anadolu şehri kahvesinde
Kiraz mevsiminin
Sevişme vakti olduğunu.
Resimler seyrettirmeli, şiirler
okutturmalıyım.
Baygınlık getiren şiirler.
Kiraz mevsimi, kiraz
Küfelerle dolu pazar.
Zambaklar geçiriyor bir kadın.
Bir kadın bir bakraç yoğurt
götürüyor
Sallıyor boyacı çocuğu fırçasını
Belediye kahvesinde hakla o eski,
o yalancı
O biçimsiz bizans şarkısı.
Sana nasıl bulsam, nasıl bilsem
Nasıl etsem, nasıl yapsam da
Meydanlarda bağırsam
Sokak başlarında sazımı çalsam
Anlatsam şu kiraz mevsiminin
Para kazanmak mevsimi değil
Sevişme vakti olduğunu...
Bir kere duyursam hele
güzelliğini, tadını,
Sonra oturup hüngür hüngür
ağlasam
Boş geçirdiğim bağırmadığım
sustuğum günlere
Mezarımda bu güzel, uzun kaşlı
boyacı çocuğunun
Oğlu bir şiir okusa
Karacaoğlan''dan
Orhan Veli''den
Yunus''tan, Yunus''tan...', 'Çıplak heykeller yapmalıyım. Çırılçıplak heykeller Nefis rüyalarınız için Ey önünden geçen ak sakallı kasketli, Yırtık mintanından adaleleri...', ARRAY['Türk Edebiyatı','Şiir','Sait Faik Abasıyanık']::text[], 8.5, '{"poet":"Sait Faik Abasıyanık","poet_slug":"sait_faik_abasiyanik","theme":"Türk Şiiri","is_hero":false,"total_lines":66}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİMDİ YOKSUN', 'si-mdi-yoksun-i-smail-uyaroglu-yrve1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar öyleydi
Diyelim duruyordun bir ağacın yanında
Kış oluyordu diyelim, tek yaprak olmuyordu dallarda
Şimdi kimse inanmaz buna ama
Çiçekle donanıyordu ağaç bir anda
Kuşu bile oluyordu hatta
Değdiriyordun diyelim parmağını
Hüzne yavaşça
Eriyip rengârenk bir uçurtma
Oluyordu o an
Hüzün dokunmanla
Diyelim bakıyordun ağlayan bir çocuğa
Donup kalıyordu gözyaşları çocuğun
Akarken yanağında
Bir zamanlar öyleydi
Şimdi yoksun
Mevsim kış, vakit hüzün
Ve bütün çocuklar ağlıyor', 'Bir zamanlar öyleydi Diyelim duruyordun bir ağacın yanında Kış oluyordu diyelim, tek yaprak olmuyordu dallarda Şimdi kimse inanmaz buna ama ...', ARRAY['Türk Edebiyatı','Şiir','İsmail  Uyaroğlu']::text[], 8.5, '{"poet":"İsmail  Uyaroğlu","poet_slug":"ismail_uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİMDE BİR LÛT GÖLÜ TAŞIYOR(UM) EHİDNA', 'i-ci-mde-bi-r-l-t-golu-tasiyor-um-ehi-dna-serkan-isin-ppnbx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Soysoz bir orospu gibi dolanıyorum bilinçaltımda
Her damarda irin vanalarını açıyor kahpe ellerim
Bekleyişin tüm kapılarında paslı transistörler çalışıyor
“ya hep ya hiç”, “ya hep ya hiç”, “yahephapiç” “yahep hapiç”
saatimi ölü evinde rahim bıraktım
parçalanıyor iş gücüm
darbukalar peşisıra bir atlı
içimde bir Lût gölü dölleniyor Ehidna,
sen bunu anlar mısın, Lût döllenmesini yani?
Bıçakla yâr alnını
Seferler düşler arası katarlar…
Noktadan, virgülden sıyrılışımın milâdına girdim
Böbreklerim kanıyor ehidna
Susuşum rehin kaldı dudağında
DUR!
Bakışlarınla durdurdun
Zaman’ı!', 'Soysoz bir orospu gibi dolanıyorum bilinçaltımda Her damarda irin vanalarını açıyor kahpe ellerim Bekleyişin tüm kapılarında paslı transistö...', ARRAY['Türk Edebiyatı','Şiir','Serkan Işin']::text[], 8.5, '{"poet":"Serkan Işin","poet_slug":"serkan_isin","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİMDE BİR SIKINTI', 'i-ci-mde-bi-r-sikinti-akgun-akova-i6etb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- Ümit''e-
işin doğrusu
önce sarıyı gördüm, sonra hepsini birden
düşe dalmış bebekti gök oyuncağıyla
ilerde adamla çocuk
yürüyorlardı ikisi de tavşan uykusunda
uzaktan yakından ilgileri yoktu gökkuşağıyla
yemin ederim
içimde bir sıkıntı o günden beri
çocuğa yedi rengi
bir arada işaret edemediğimden', '- Ümit''e- işin doğrusu önce sarıyı gördüm, sonra hepsini birden düşe dalmış bebekti gök oyuncağıyla ilerde adamla çocuk yürüyorlardı ikisi d...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun_akova","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİMDEKİ DANSINA ARA VERDİ İSPANYA', 'i-ci-mdeki-dansina-ara-verdi-i-spanya-abdulkadir-budak-xpdvt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyük Umutlar Caddesi''ndeki hiçbir ev benim değil
Hindistanım yok benim, bende Nil kıyısı yok
Adım yok afişinde çok tutulan bir filmin
Bana değil tufanı andıran bu alkışlar
Her zaman iyi gelirdi Ülkü Tamer okumak
O da iyi gelmiyor nedense şu sıralar
Ankara manzaralı Çankaya sırtlarım yok
Gitaristi değilim ünlü bir topluluğun
Bisikletle dünya turu düşlemiyorum artık
Sallamayı bilmiyor bindiğim kör salıncak
Karada yüzmesini öğrenemeyen gemiyim
Bu yüzden trenlerim İstanbul''a kalkacak
Çok isterdim Çin Seddinin mimarıyla konuşmayı
Kanat ile pençe arasına sıkışmış kartal ağzıyla
Bütün bunlar olmadı Madrit''e gidemedim
İçimdeki dansına ara verdi İspanya
Haydar gel çay içelim konuşalım aşklardan
Seni bilmem ama ben çok kötüyüm
Moskova kışı gibiyim bu yaz gününde
Taşla doldurulmuş bir kuyu göğsüm', 'Büyük Umutlar Caddesi''ndeki hiçbir ev benim değil Hindistanım yok benim, bende Nil kıyısı yok Adım yok afişinde çok tutulan bir filmin Bana ...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇÖMÇE GELİN I', 'comce-geli-n-i-aydin-hati-poglu-0ezk6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sokaklar boyunca çeşmeler kurdum
Gürül gürül gücüm aktı damarlarıma
Kuru çatlak toprakta açlık ve umut
Yeşil bir özlem gibi yöneliyor tanrıya
Oysa tükenmiş çeşmelerde su
Yanık bir ekmek gibi yağız yüzlerin
Ezik isyanı kımıldar damarlarında
Seslenirken çocuklar tarlalarda
Çömçe gelin nar ister
Tarlaya yağmur ister
Bir esmer bulut uğruna eller
Bir tutam ıslak toprak kokusuna havada
Bulut ve toprakta yoğunlaşır yaşamak
Gâvur bir çalım sarı kuru otlarda
Çaresiz açılır tanrıya eller
Seslenirken çocuklar tarlalarda
Ver allahım ver
Yağmur ile sel
Belki düşer belki düşmez yağmur toprağa
Geçir parmaklarını geçir toprağa
Sökülsün tırnaklar diren ha diren
Fışkırır su gibi kanı toprağın
Seslenirken çocuklar tarlalarda
Çömçe gelin nar ister
Tarlaya yağmur ister
Ver allahım ver
Yağmur ile sel', 'Sokaklar boyunca çeşmeler kurdum Gürül gürül gücüm aktı damarlarıma Kuru çatlak toprakta açlık ve umut Yeşil bir özlem gibi yöneliyor tanrıy...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇÖMÇE GELİN II', 'comce-geli-n-ii-aydin-hati-poglu-ivoxe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi bir yumruk gibidir çömçe gelin
Bin yıllık yazgıyı bozmak için sıkılmış
Gidip gelip takılıyorduk silip yeni baştan başlıyoruz
Dikenler batıyor ellerimize
Dikenli tellerde güller düşünmek
Susup yeni baştan başlıyoruz
Tutup meşaleler yakıyoruz karanlıkta
Bazı sözcüklerden korkuyoruz
Yumruk mu aşk mı ne bu
Saksılar köklere dar geliyor
Aşk dedikse açlığıydı bir yerlerde sancılar
Korkular bir yönüydü yaşamımızın
Korkular korkular korkular
Tanrıyı bir kez daha kurşuna diziyorlar
Bu savaş hep böyle sürüyor bu kavga hep böyle
Bir büyük aldatmacanın son kozunu oynuyoruz
Ölü bir el karanlıkta gevşiyor
Çömçe gelin pis kentlerde çarmıha geriliyor
Bir çoğul kişidir çömçe gelin
Adımıza geriliyor çarmıha
Ellerinde anlam bulup çocukların
Adımıza yöneliyor allaha', 'Şimdi bir yumruk gibidir çömçe gelin Bin yıllık yazgıyı bozmak için sıkılmış Gidip gelip takılıyorduk silip yeni baştan başlıyoruz Dikenler ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MÜEBBETLİK KAVGA', 'muebbetli-k-kavga-bayram-balci-jdz32', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'herhangi bir kıyısında tanışıp dünyanın
iki hırçın güvercin telaşıyla sevdik
hayatı ve kavgayı
ay düştü. yıldız koptu. güneş doğdu yüzümüze
karanfil kokulu düşler yaşadık mapusluğumuzda
yakarak avucumuzda özgürlük ateşini
-a-
yastığımı ver cürüm. başım ağrıyor
gece duyabilmek için dünyanın bütün seslerini
gökyüzüne bakıyorum koğuşun penceresinden
kadife bir ayın önünde yıldızlar oynaşıyor
ve birden
pencerenin camında buğulanıyor suretin
-gazetecilerin flaşlarında
yorgun yüzüyle hayata gülümseyen
bir ''terörist'' kız oluyorsun-
ellerin çiçeğe durmuş
güneş vurmuş alnına
dimdik ayaktasın
işkencehanelerde ölmüş yoldaşların anısına
yastığımı ver cürüm. başım ağrıyor
-b-
nişanlayıp uzak bir yıldıza gözlerimi düşünüyorum
sahi nerede tanıştık biz
ne zaman böyle kaynaştık
ve ne çok şey
böyle ne çok şey paylaştık
o günleri biz yaşadık
gördüğümüz düş değildi
kan sıçradı beynimize
gererken kaslarımızı elektrik
çırılçıplak yandı etimiz
beton gibi çarparken vücudumuza su
ve sildik gizleyerek kendimizden bile
yüzümüzden akan iğrenç kirimizi
hücrenin duvarlarına
o günleri biz yaşadık
gördüğümüz düş değildi
ihanetin ve direncin ateşi içinde
korktuk kendi gizimizi gizlemekten
çatladı direncin iğbirar çiçekleri avucumuzda
düşünüyorum uzak bir yıldıza nişanlayıp gözlerimi
-c-
ihanet değil belki bu. yüzünü gizleme
fareli köyün çobanlarının utancı
yüreğimi yakmıyor artık
alnım açık
elegüne karşı başım dik
içim kavga ve sevda dolu
müthiş kendimle barışık
oysa içten içe yiyip bitiriyor kendini en yakınım
ve göstererek azı dişlerini ağzınca saldırıyor
aldırmayıp diyorum ki ona
ayakları yere sağlam basmak
artık iş değil bu çağda
toprak da kayıyor dostum
insanın ayakları altında
toprak da kayıyor
toprak da
toprak
bastığın yere iyi bak
ihanet değil belki bu. yüzünü gizleme
-d-
bir bardak su verir misin. içli bir türkü
yüreğimde ince yağmurlar çiseliyor şimdi
bu doğurgan yüzlü gecelerinde nisanın
tahliye muştusu geliyor uzaktaki bir dostun
çığlıklarla uçuyor gecekuşları başımın üstünde
morkanatlarına takıyorum kirpiklerimi
afacan bir çocuk gibi sevinip
ben de çıkıyorum onunla
özgürlük şarkıları söylemeye
lacivert dağların kurşuni yamaçlarında
-ve ikimiz birden
durmuşuz da sanki dalgaların kıyısında
ellerimizi uzatıyoruz yakamozlara
ansızın portakal çiçekleri açıyor avucumuzda
konuşmadan öylece duruyoruz yanyana
sen gökyüzüne dikiyorsun gözünü
ben suya düşürüyorum yüzümü
ve birden gelincikler yağıyor
martıların kanatlarından
karışıyor sularına akdenizin-
bir bardak su verir misin. içli bir türkü
-e-
saat kaç oldu şimdi. neden herkes uyuyor
sessizce açıp yeniden okuyorum
yazdığın bütün mektupları
kök salıyor yüreğimde gizli bir sarmaşık
aralıyorum geçmişin tülperdesini
o zamanlar orada herkesin adı ULAN''dı
ve her asker KOMUTAN''dı
oysa şimdi burada
onların hamlamış ezgilerinde
yoksul bir direncin türküsünü dinliyorum
o günleri biz yaşadık
gördüğümüz düş değildi
a blok. zemin. birikiüçdört
aslankafesi tecrit
ve bilcümle mamakta
yüzlerce insanın içinde
42. güne erişen bir avuç insandı
ki yüzakıydılar mamağın
o günleri biz yaşadık
bir düş olamaz bu haydarım
bir düş olamaz bu sezai
ve adlarını unutup yüzlerini unutmadığım dostlarım
bir düş olamaz bu
sorun raci tetikin korkularına
ayrılık ve ölüm nasıl gerçekse
ve acıları ne denli büyükse
öylesine gerçekoğlu gerçekti herşey
ve öylesine büyüktü acı
ve utanç çırılçıplaktı
saat kaç oldu şimdi. neden herkes uyuyor
-f-
-arif acar''a
çayı avluda içsek. yarın hava güzel olacak
yitirilmiş bir duygunun dayanılmaz kederidir bu
o zamanlar yaralıydı yaşdığımız aşklar
şimdi bedeli ödenmiştir yıllarımızın
kanımızla ödenmiştir canımızla
ve ansızın bir sigara yakar gibi
uzun bir şiir söylercesine
içli bir türkü dinler gibi
usul ince bir kadın severcesine
sürüp gidiyor işte kavga
en haklı ve güzelini yaşıyoruz sevdaları
&quot;hüzünlü bir şiir yaz&quot; diyor ranza arkadaşım
&quot;karıma göndereyim&quot;
boşver diyorum hüznü
sırasımı şimdi efkarlanmanın
ve ona
kadınlar koğuşundan gönderilen
kurutulmuş karanfilleri veriyorum
çayı avluda içsek. yarın hava güzel olacak
-g-
gece çok mu kısa. yoksa bana mı öyle geliyor
avluda volta atıyorsun yıldızlarla
okşayabilmek için saçlarını
özenle açıyorum pencereyi
ve yıldızlar doluyor içeri
dördüncü koğuşta herkes koynunda bir yıldızla uyuyor şimdi
ve ben ranzama astığım bir fotoğrafın
çocukca yanan gözlerine nişanlayıp yüreğimi
düşünüyorum
sahi nerede tanıştık biz. unuttum
ve ne zaman böyle kaynaştık. bilmiyorum
ve ne çok şey
böyle ne çok şey paylaştık
ah...seni nasıl da seviyorum
gece çok mu kısa. yoksa bana mı öyle geliyor', 'herhangi bir kıyısında tanışıp dünyanın iki hırçın güvercin telaşıyla sevdik hayatı ve kavgayı ay düştü. yıldız koptu. güneş doğdu yüzümüze ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":154}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEDENİYET', 'medeni-yet-melih-cevdet-anday-wx7ku', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu haline bak da utan
Ne okuma bilirsin ne sayı
Ne üstünde var ne başında
Ne midende ne kursağında
Bari gel de görgünü arttır
Medeniyet öğren ayı.
Yemek masası nedir, peçete nedir,
Çatal bıçak nedir gör!
Giymek şart değil ya,
Ayakkabı gör, gömlek gör,
İngiliz kumaşı gör, naylon çorap gör,
Jartiyer bile görsen faydası var.
Tarak deyip de geçme
Saçını tara da gör
Kafan nasıl işlemeye başlar.
Kanalizasyon gördün mü sen hiç?
Gel de kanalizasyon gör,
Yemek şart değil ya,
Döner kebap gör, su böreği gör,
Ekmek gör be ekmek,
Ne görsen faydası var!', 'Şu haline bak da utan Ne okuma bilirsin ne sayı Ne üstünde var ne başında Ne midende ne kursağında Bari gel de görgünü arttır Medeniyet öğre...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEDENİYYET', 'medeni-yyet-ziya-gokalp-ujm5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Avrupa bir akademi âzaları milletler;
Her biri bir nurlu deha, çünkü ayrı harsı var.
Avrupa bir darülfünun, hocaları milletler;
Her birinin ihtisası, bir örneksiz dersi var.
Bu nurlardan biri sönse medeniyyet loş kalır;
Derslerinden biri durur, bir kürsüsü boş kalır.
Medeniyyet, beynelmilel yazılacak bir kitap;
Her faslını bir milletin harsı teşkil edecek.
Medeniyyet bir konser ki birçok çalgı, saz rübap
Birleşmekle bir ahengi ancak tekmil edecek.
Bu kitabın bir mebhasi eksik olsa okunmaz;
Bir âleti yoksa, ahenk gönüllere dokunmaz.', 'Avrupa bir akademi âzaları milletler; Her biri bir nurlu deha, çünkü ayrı harsı var. Avrupa bir darülfünun, hocaları milletler; Her birinin ...', ARRAY['Türk Edebiyatı','Şiir','Ziya  Gökalp']::text[], 8.5, '{"poet":"Ziya  Gökalp","poet_slug":"ziya_gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEÇHÛL', 'mech-l-necip-fazil-kisakurek-4h1i1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sordular: Adresi ne?.. Çeşmeye karşı, dedim;
"Çanakkale içinde aynalı çarşı" dedim.', 'Sordular: Adresi ne?.. Çeşmeye karşı, dedim; "Çanakkale içinde aynalı çarşı" dedim....', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEHLİKA SULTAN', 'mehli-ka-sultan-yahya-kemal-beyatli-ic42y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mehlika Sultan''a âşık yedi genç
Gece şehrin kapısından çıktı:
Mehlika Sultan''a âşık yedi genç
Kara sevdalı birer âşıktı.
Bir hayâlet gibi dünya güzeli
Girdiğinden beri rü''yâlarına;
Hepsi meshûr, o muammâ güzeli
Gittiler görmeye Kaf dağlarına.
Hepsi, sırtında aba, günlerce
Gittiler içleri hicranla dolu;
Her günün ufkunu sardıkça gece
Dediler: ''''Belki bu son akşamdır''''
Bu emel gurbetinin yoktur ucu;
Daimâ yollar uzar, kalp üzülür:
Ömrü oldukça yürür her yolcu,
Varmadan menzile bir yerde ölür.
Mehlika''nın kara sevdalıları
Vardılar çıkrığı yok bir kuyuya,
Mehlika''nın kara sevdalıları
Baktılar korkulu gözlerle suya.
Gördüler: ''''Aynada bir gizli cihân..
Ufku çepçevre ölüm servileri.....''''
Sandılar doğdu içinden bir ân
O, uzun gözlü, uzun saçlı peri.
Bu hâzin yolcuların en küçüğü
Bir zaman baktı o viran kuyuya.
Ve neden sonra gümüş bir yüzüğü
Parmağından sıyırıp attı suya.
Su çekilmiş gibi rü''yâ oldu!..
Erdiler yolculuğun son demine;
Bir hayâl âlemi peydâ oldu
Göçtüler hep o hayâl âlemine.
Mehlika Sultan''a âşık yedi genç
Seneler geçti, henüz gelmediler;
Mehlika Sultan''a âşık yedi genç
Oradan gelmeyecekmiş dediler!..', 'Mehlika Sultan''a âşık yedi genç Gece şehrin kapısından çıktı: Mehlika Sultan''a âşık yedi genç Kara sevdalı birer âşıktı. Bir hayâlet gibi dü...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEÇHUL ÖĞRENCİ ANITI', 'mechul-ogrenci-aniti-ece-ayhan-78llg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Buraya bakın, burada, bu kara mermerin altında
Bir teneffüs daha yaşasaydı
Tabiattan tahtaya kalkacak bir çocuk gömülüdür
Devlet dersinde öldürülmüştür
Devletin ve tabiatın ortak ve yanlış sorusu şuydu:
-Maveraünnehir nereye dökülür?
En arka sırada bir parmağın tek ve doğru karşılığı:
-Solgun bir halk çocukları ayaklanmasının kalbine!dir.
Bu ölümü de bastırmak için boynuna mekik oyalı mor
Bir yazma bağlayan eski eskici babası yazmıştır:
Yani ki onu oyuncakları olduğuna inandırmıştım
O günden böyle asker kaputu giyip gizli bir geyik
Yavrusunu emziren gece çamaşırcısı anası yazdırmıştır:
Ah ki oğlumun emeğini eline verdiler
Arkadaşları zakkumlarla örmüşlerdir şu şiiri:
Aldırma 128! İntiharın parasız yatılı küçük zabit okullarında
Her çocuğun kalbinde kendinden daha büyük bir çocuk vardır
Bütün sınıf sana çocuk bayramlarında zarfsız kuşlar gönderecek.', 'Buraya bakın, burada, bu kara mermerin altında Bir teneffüs daha yaşasaydı Tabiattan tahtaya kalkacak bir çocuk gömülüdür Devlet dersinde öl...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKİK', 'meki-k-metin-altiok-rvho4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi aşk kaçmış bir ilmektir gövdenin örgüsünde,
Uykusuz bir gecenin çitlerine takılan.
Sökülür durmadan uzayan ipliğiyle,
Sarılır mekiğine sabahın
Ürkek bir güvercin halinde.
Ve sen eksildikçe o güvercin tamlanır,
Kanatlanır böylece köpüren özlemiyle.
Uçar gider geçmiş bir günün ardından,
Bir tüy kalır geriye senin bittiğin yerde.', 'Şimdi aşk kaçmış bir ilmektir gövdenin örgüsünde, Uykusuz bir gecenin çitlerine takılan. Sökülür durmadan uzayan ipliğiyle, Sarılır mekiğine...', ARRAY['Türk Edebiyatı','Şiir','Metin Altiok']::text[], 8.5, '{"poet":"Metin Altiok","poet_slug":"metin_altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜŞÜMEKTEN DEĞİL KORKU', 'usumekten-degi-l-korku-gulten-akin-le1nv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgun savaşçılarız, yengiler eskitti bizi
Utanırız tadına varmaktan içkilerimizin
Biri bütün güneşleri toplar, vermeye bekletir
Üşümekten değil korku, ısınır olmaktan
Yorgun savaşçılarız, sevgiler ürküttü bizi
Tutulmuş dağ yolları oklar ve tuzaklar
Biri dostluk adına bağışlar çirkinliğimizi
Düz yollara düşeriz yeniden oksuz ve tavşansız
Yılgın savaşçılarız, sevgiler ürküttü bizi', 'Yorgun savaşçılarız, yengiler eskitti bizi Utanırız tadına varmaktan içkilerimizin Biri bütün güneşleri toplar, vermeye bekletir Üşümekten d...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKTUP', 'mektup-turgay-fi-sekci-fu5t9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nefret ediyorum kendimden
Erken yattığım akşamlar
Günün kurşun yorgunluğuna yenilip
Bir patates çuvalı gibi devrilince yatağa
Yaşadığımız hayat başkalarının da
Bizim için ölenlerin
Bizim için yaşayanların
Gün gün , dakika dakika
Tüm hayatlara borçlu yaşıyoruz
Belki bundan ter içinde fırlamak yataktan geceyarıları
Sarılmak bir kitaba
Sarılır gibi susuz gecelerde yare
Başımdan aşağı döktüğüm soğuk suların
Vücudumda cazlaması bundan
Belki O beni uyutmayan
Çelik ışıklı insan gözleriyle
Bir hayata nelerin sığabileceğini anlatan
Akan terler
Kimsenin geçmediği
Bembeyaz yollar açıyor yüreklerde
Tüm bilim , yaşam ve sanat
Geçmeli bu yollardan
Yürürken sevdiğime.
Turgay FİŞEKÇİ
“Karda Işıltılar” , 1981', 'Nefret ediyorum kendimden Erken yattığım akşamlar Günün kurşun yorgunluğuna yenilip Bir patates çuvalı gibi devrilince yatağa Yaşadığımız ha...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKTUPLAR ALIRIM', 'mektuplar-alirim-metin-demi-rtas-1ryq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mektuplar alırım
Allı-karalı
Üstünde görülmüştür
Yiyecek alınmaz damgaları
Açarım
Birden, kuş ve şiir sürüleri
Havalanır içinden.
Kimi kanadı kırma
Düşe kalka
Kimi zıpkın gibi
Yetkin ve güzel!
Tutmaz çocuğun ayakları
Yaralıdır her bir yanları
Dar geçitlerden geçmişler
Acıları aşıp gelmişlerdir
Yeşile, güneşe hasret
Bir yürek çarpar
Her zarf içinde
Okurum
İçim daralır
Bakamam göğe, utanırım
Alır mektuplarımı
Havalandırmaya çıkarım
Dışarıda deli bir lodos
Esrik bir sonbahar
Aylardan aralık
Adrasan üstünde mor bulutlar
Tahtalı''da kar vardır
Yasemin kokar ortalık
Dostlar ki gurbette
Dostlar ki hapistedir
Mektuplarıyla yetinirim artık', 'Mektuplar alırım Allı-karalı Üstünde görülmüştür Yiyecek alınmaz damgaları Açarım Birden, kuş ve şiir sürüleri Havalanır içinden. Kimi kanad...', ARRAY['Türk Edebiyatı','Şiir','Metin Demi̇rtaş']::text[], 8.5, '{"poet":"Metin Demi̇rtaş","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKTUPLAR', 'mektuplar-sina-akyol-gmsbo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'B i r i n c i     M e k t u p
Umutla bakan
Dünyaya
Herşeye
ve sevgiye
umutla bakan
yüzün senin.
Beni sıcak
bir güneş gibi güzelim
vahşî
çılgın
ve âsî
bir ruhla coşturan
ve çatık tüfenkler gibi mağrur
bir inancı taşıyan
bacım benim!
Sana gökyüzünün
mavi bir inatla çalkanan rengini iletir
selam ederim.
İ k i n c i    M e k t u p
Günüm gecem evim barkım.
Durmadan şavkıyor aydınlık.
Sabahla yaylaya çıkıyorum.
Dere tepe düz gidiyorum.
Fatmacık adlı küçük
kıvırcık
ve sabah yeline benzeyen
bir çocukla birlikte
çitlenbikleri geçiyorum.
Gürültüyle tarla
vermede ürününü
kuzular ve keçiler
melemede sabahla.
Sabahla güzelim
ışıl ışıl sevdalar büyüyor alnımızda
ve kalabalık
şekilleniyor.
Doğurgan bir ağız halinde
kalabalık şekilleniyor.
Ve seni
unutamıyorum!
Ü ç ü n c ü    M e k t u p
Baharla geldi
yüzüme sevinç.
Dinç
ve sabırsız bir merakla
geleceği arıyorum.
İlyas''ın ve Durmuş''un
gözlerini arıyorum.
Sonra nasıl da kalkıyorum
herşeyi kutsamaya
yani vahşî
bir kunduz
gibi bağırmaya
kalkıyorum.
Ve göreceğim:
yeryüzünü ve halkları
göreceğim!
Sesimin çeliğine
bazı kinler katarak
ve haykırarak:
ey insanlar!
Çünkü durmadan işliyor yüreğim
çünkü güzelim,
hırsın
inadın
ve kavganın
kahramanca içindeyim!
D ö r d ü n c ü    M e k t u p
Günlüğüme silâh
ve çiçek figürleri çiziyorum.
Pos bıyıklı bir işçiyi
günlüğüme çiziyorum.
işçinin gömleğinde siyah
ince
ve uzun
çizgiler var
demek ki günlüğüme
bir mahpusu çiziyorum.
Terekli şapkasını giyen
gözlerini bileyen
ve düşünceli bir tavırla
hayatı izleyen
bir işçiyi
günlüğüme çiziyorum.
Ona mikrofon veriyorlar
konuşması için.
İşçi çağıldıyor
durmadan çağıldıyor halk.
Ama yetmiyor bize bu kadarı
düşün ki güzelim
bir gün yüksek
bir yere çıkıyor bir konuşmacı
görkemli eşyalarla dolu, yüksek
bazı insanlara bakan
ve arkası camla kaplı olan
bir yere çıkıyor bir konuşmacı.
Ve tüfenkli askerler koşuşurlarken
püskürtmek için halkı
aydınlık yüzüyle gelen konuşmacı
kaptığı gibi yerden büyükçe bir taşı
kırıp parçalıyor camları
ve dönüp sırtını, tören
kıyafetleriyle biriken baylara
ve diyor ki konuşmacı halka:
Yüreğim
Sizinledir!
B e ş i n c i    M e k t u p
Yüreğim seninledir güzelim
seninledir ve
herkesledir yüreğim.
Derin bir ağıt yakaraktan
ve içten içe
devrimi söylemektedir.
Gün
doğmaktadır sevgiye
acılar
ve sabırlar çekerek kalbim
bir atlının yüzüme vahşî
ve çılgın sevinçler dizerek
ve sesime çelik özlü
sevdalar çekerek
kükremesiyle gelen devrim
çatlamaktadır!
İnanç
ve kurşun uğruna gövdem
çatlamaktadır.
Mutlaka çatlamaktadır benim alnım.
Dağ çiçeklerinin
kavga kokan sularında
bir ordu gibi biriken
ve çoğalan sularında
devrim çatlamaktadır!
A l t ı n c ı    M e k t u p
Ağaçlar ve yapraklar
birer tadla besleniyorlar.
dünya
bütün zorluklarını yenip
inatla çoğalıyor.
Ve inatla insanlar
yüzlerine serin
sabahlar çiziyorlar.
Bütün bunları görmemek
elde mi?
Elde mi gizlemek
sevincini baharın?
Bir kuşun
-ufacık başlı ve
tüy gibi hafif bir kuşun-
bazı uçmalar büyüterek içinde
ve canı nereyi isterse
oraya gittiğini görmemek
elde mi?
Elde mi güzelim
-güvencin
büyük bir gürültüyle üstüme
ve omuzbaşlarıma yığıldığını
görmemek?
Sıcak
ve hoyrat duran nefesimle
bunu mutlaka görmek
mutlaka tanımlamak aşkı
onu çekip kurtarmak
bir yaz öğlesinden
onu çekip, dağların yüksek
ve kahraman bir bölgesinden
kakışlamak.
Coşkuyla:
Bunu çözümlüyorum: Mavi
bir inatla büyüyor gök.
Kalbim
yeni yeni yorumlar katıyor güne.
Direncini işliyor tabiat.
-Çünkü kış
kovulmuş bir adam gibi gitmektedir.
Ve kalbim,
soyunan
ve kendini serin
sulara atan bir adamın
göğe büyük
bir halka çizerekten
koştuğunu görmektedir.
Y e d i n c i    M e k t u p
Çünkü hayat
sevgiyle uyanır.
Bunu görüp yazarım.
Kanım çoğalır durmadan, damarlarım
-benim yaşamakla dolanan damarlarım-
Oysa zaman zaman toprağın
sıcak ve nemli kokusunu duyamadığım
küçük ve karanlık odamın ortasındayım.
Oturmuş, şiirler yazıyorum
uzak
puslu
ve yılgın bir köy üstüne.
-Acılar birikiyor içimde,
masamdan kalkmalıyım-
Çünkü ben
kahraman bir kalemşorun
kuru sıkıya atıp gerindiği
mermilerden uzakta
köyü
ve halkı yazacaksam eğer
köyü
ve halkı
bilmeliyim.
Bilmeliyim dostumun
yaşamakla taşan yüreğini
ve demeliyim ki ona güneş
bir gün ağartacak başakları
onlar yayılıp çoğalacaklar
ve rüzgâr serin
kokular getirecek etrafa.
Çünkü hayat
sevgiyle uyanan bir sabah gibi
başımızda.
Ve bizim her şeye karşı
inancımız var!
İnancımız var güzelim,
doğan güne karşı
namus
ve sevgi barındıran
inancımız var!
Alınlarına durmadan
yeni yeni yaralar katan
ve bir gün patlayacak olan
halka
inancımız,
ve yaşamayı kutsayıp
onu felâketle bizlerin
omuzlarına bırakan
bir takım adamlara
kinimiz var!
S e k i z i n c i    M e k t u p
Bütün bunları derken,
günler
ve zaman
geçip gidiyor.
Sana sevimli bazı anlar veremiyorum.
-Varsın veremeyim, ne çıkar-
Çünkü diyorum ki ben:
Nefis bir yaz düşünüp, ona otları
ve rüzgârı da ekleyip
ve kelebekleri
ve güneşi de ekleyip
birden içlenmek mi?
HAYIR!
Kavganın
ve zorluğun içinden gelip
iletmek yüreğimi sana
ve seni böylecene sevmek!', 'B i r i n c i     M e k t u p Umutla bakan Dünyaya Herşeye ve sevgiye umutla bakan yüzün senin. Beni sıcak bir güneş gibi güzelim vahşî çılg...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina_akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":253}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKTUP''TAN', 'mektup-tan-ercument-behzad-lav-d1o8r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bir asmasın,
küpe salkımlarla asma bellim..
Elim değmesin,
değmesin dilim sana, asma bellim..
Küpe salkımlarında, kütür kütür,
buğulu üzüm başlar, asma bellim..
Niye kendini sevdiğin zamanlar;
daha olmadan başkasınının,
öper dudakların suda,
dudaklarını,
Niye sana benziyor köpükler, güneşe sarılırken?
Niye şu bulut, kaçırmıyor seni
ve kaçmıyor senden balıklar?
Niye çarpınca mantılar sana kanat,
niye ağzımda yüreğim,
niye içerim göz göz,
niye gözlerim pervane?', 'Sen bir asmasın, küpe salkımlarla asma bellim.. Elim değmesin, değmesin dilim sana, asma bellim.. Küpe salkımlarında, kütür kütür, buğulu üz...', ARRAY['Türk Edebiyatı','Şiir','Ercüment Behzad Lav']::text[], 8.5, '{"poet":"Ercüment Behzad Lav","poet_slug":"ercument_behzad_lav","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MELEK SIRTI', 'melek-sirti-jean-cocteau-lilez', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayale dalmış bir sahte sokak
Ve gerçek olmayan şu piston
İkisi de yalan
Gökten gelen bir melek çıkardı.
İster rüya olsun ister olmasın
Yukardan bakıldı mıydı
Yalan apaçık görülür
Çünkü melekler kamburdur.
Hiç değilse gölgeleri kambur
Odamın duvarı üstünde.', 'Hayale dalmış bir sahte sokak Ve gerçek olmayan şu piston İkisi de yalan Gökten gelen bir melek çıkardı. İster rüya olsun ister olmasın Yuka...', ARRAY['Türk Edebiyatı','Şiir','Jean Cocteau']::text[], 8.5, '{"poet":"Jean Cocteau","poet_slug":"jean_cocteau","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MELÂHAT GEÇİLMEZ', 'mel-hat-geci-lmez-ece-ayhan-l1o7z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1.Gazetelerde ak kara bir resmi otuz yıllık. Arkasında mülki taksimatlı bir harita.
Komiserin odasında ağırlanırmış.
2.Ve imparatoriçeliğinde bir vesikalık. Tombalacı Ceylan renkli çekmiş.
Delikleri balmumuyla örterler.
3.Gönderilen çelenklerde ''Geçilmez'' yazılmıştı soyağacı. Küçük harflerle de
''fuhşun anısına''.
4.Çanakkaleli Melâhat''ın törenine polis bandosu da katılmıştır.', '1.Gazetelerde ak kara bir resmi otuz yıllık. Arkasında mülki taksimatlı bir harita. Komiserin odasında ağırlanırmış. 2.Ve imparatoriçeliğind...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MELÂNKOLİ', 'mel-nkoli-mustafa-i-lhan-gecer-d0fe6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O şehirde gene şarkılar söyleniyordur
Karşılık görmemiş sevgiler üstüne
Işıkları sönmüş odamda
Yarım kalmış şarkımı duyuyor musun
Beni sorarsan gene yapayalnızım
Sen sıcak döşeğinde rahat uyuyor musun
Boş kalan yastığımı başkası mı doldurmuş
Ellerini okşayan o yabancı kim
Öyle uzak bakma yüzüme
Seni artık yolundan döndürecek değilim
Ne o gözlerin dolmuş yoksa ağlıyor musun
Kırk yılda bir olsun beni anıyor musun
Özlediğin hayatı buldun mu bilmem
Gözlerinde hâlâ hüzün var gibi
Gene yüzün gülmüyor anlat nedendir
Gene aşksız gene bomboş mu için
Niye ellerin soğuk yoksa üşüyor musun
Mutluluğun peşinde hâlâ koşuyor musun
Kar mı yağdı güvendiğin dağlara
Seni de bir türlü umdurmadı mı kader
Üzme kendini her şeye rağmen
Dünya yaşanmaya değer
Bu yerler bu âlem her şeyden yoksun
Sana sesleniyorum duyuyor musun', 'O şehirde gene şarkılar söyleniyordur Karşılık görmemiş sevgiler üstüne Işıkları sönmüş odamda Yarım kalmış şarkımı duyuyor musun Beni sorar...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan  Geçer']::text[], 8.5, '{"poet":"Mustafa İlhan  Geçer","poet_slug":"mustafa_ilhan_gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEMLEKET İSTERİM', 'memleket-i-steri-m-cahit-sitki-taranci-u1nkw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Memleket isterim
Gök mavi, dal yeşil, tarla sarı olsun;
Kuşların çiçeklerin diyarı olsun.
Memleket isterim
Ne başta dert, ne gönülde hasret olsun;
Kardeş kavgasına bir nihayet olsun.
Memleket isterim
Ne zengin fakir, ne sen ben farkı olsun;
Kış günü herkesin evi barkı olsun.
Memleket isterim
Yaşamak, sevmek gibi gönülden olsun;
Olursa bir şikâyet ölümden olsun.', 'Memleket isterim Gök mavi, dal yeşil, tarla sarı olsun; Kuşların çiçeklerin diyarı olsun. Memleket isterim Ne başta dert, ne gönülde hasret ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEMLEKETİM', 'memleketi-m-omer-faruk-toprak-9sdmu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'usandım artık hazin mısralar okumaktan
neyleyim akşam yaklaşıyor dostum
kuşların cıvıltısı dinecek birazdan
yitecek yeşil yapraklar taze güller
ağır bir makamla başlayacak şarkısına
afyon çekmiş zavallı mısır radyosu
sen kütahya sen samsun sen istanbul
sırtını dayayıp o bereketli toprağa
diniliyorum çukurova''nın sesini
sürüyor tarlaları traktör kardeşim
avuçlar serpmeyecek artık tohumu
kaç yıldır özlüyor bu topraklar bilir misin
ağır uykusundan uyanmış kalkıyor
bafralı tütüncüler haliç kıyıları ve toroslar
benim insanlarım öğrenmişler yeryüzünü
ilk kurşunu atan antepli şahin''e kadar
dağlarda bellerde onları tek tek tanımışım
yamalı mintanları ve ağızlarını örten bıyıkları
öfkeyi cesareti bilen gözleriyle
taş taşımışlar ekmeği bölerek yemişler
yıllar var ki hüznü kederi sevmiyorum
yalnız insanlar için şiir yazdığımı bilirler
sen kütahya sen samsun sen istanbul
asfalt yollara çıkan dar sokakları
köprüleri ambarları ve akarsularıyla
düşünmüşümdür on sekiz saat yol boyunca
bir sabah erken yola çıktım
gâvur dağlarında bıraktım türkümü
avuçlarım delik deşik dudaklarım çatlak
yağmurda ıslanmış saçlarım
yıllardır görmediğim ak saçlı anam
özlem türkülerini ezberler olmuş
bilirim çamaşırdan delinmiş parmakları
saçlarımı okşar her gece uykumda
"gurbet gurbet" diye dizlerini dövme
onu çoktandır kardeş bilmişim ben
mektuplarımda adı torbamda ekmeği var', 'usandım artık hazin mısralar okumaktan neyleyim akşam yaklaşıyor dostum kuşların cıvıltısı dinecek birazdan yitecek yeşil yapraklar taze gül...', ARRAY['Türk Edebiyatı','Şiir','Ömer Faruk Toprak']::text[], 8.5, '{"poet":"Ömer Faruk Toprak","poet_slug":"omer_faruk_toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEMLEKETİMDEN İNSAN MANZARALARI''NDAN', 'memleketi-mden-i-nsan-manzaralari-ndan-n-zim-hi-kmet-2u3my', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haydarpaşa garında
1941 baharında
saat on beş.
Merdivenlerin üstünde güneş
yorgunluk ve telâş
Bir adam
merdivenlerde duruyor
bir şeyler düşünerek.
Zayıf.
Korkak.
Burnu sivri ve uzun
yanaklarının üstü çopur.
Merdivenlerdeki adam
-Galip Usta-
tuhaf şeyler düşünmekle
meşhurdur:
&quot;Kâat helvası yesem her gün&quot; diye düşündü
5 yaşında.
&quot;Mektebe gitsem&quot; diye düşündü
10 yaşında.
&quot;Babamın bıçakçı dükkânından
Akşam ezanından önce çıksam&quot; diye düşündü
11 yaşında.
&quot;Sarı iskarpinlerim olsa
kızlar bana baksalar&quot; diye düşündü
15 yaşında.
&quot;Babam neden kapattı dükkânını?&quot;
Ve fabrika benzemiyor babamın dükkânına&quot;
diye düşündü
16 yaşında.
&quot;Gündeliğim artar mı?&quot; diye düşündü
20 yaşında.
&quot;Babam ellisinde öldü,
ben de böyle tez mi öleceğim?&quot;
diye düşündü
21 yaşındayken.
&quot;İşsiz kalırsam&quot; diye düşündü
22 yaşında.
&quot;İşsiz kalırsam&quot; diye düşündü
23 yaşında.
&quot;İşsiz kalırsam&quot; diye düşündü
24 yaşında.
Ve zaman zaman işsiz kalarak
&quot;İşsiz kalırsam&quot; diye düşündü
50 yaşına kadar.
51 yaşında &quot;İhtiyarladım&quot; dedi,
&quot;babamdan bir yıl fazla yaşadım.&quot;
Şimdi 52 yaşındadır.
İşsizdir.
Şimdi merdivenlerde durup
kaptırmış kafasını
düşüncelerin en tuhafına:
&quot;Kaç yaşında öleceğim?
Ölürken üzerimde yorganım olacak mı?&quot;
diye düşünüyor.
Burnu sivri ve uzun.
Yanaklarının üstü çopur.
Denizde balık kokusuyla
Döşemelerde tahtakurularıyla gelir
Haydarpaşa garında bahar
Sepetler ve heybeler
merdivenlerden inip
merdivenlerden çıkıp
merdivenlerde duruyorlar.', 'Haydarpaşa garında 1941 baharında saat on beş. Merdivenlerin üstünde güneş yorgunluk ve telâş Bir adam merdivenlerde duruyor bir şeyler düşü...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":66}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEMNUNUM DİYEMEM', 'memnunum-di-yemem-cahit-irgat-xklv7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Memnunum diyemem yaşadığıma,
Bana bir şey söylemiyor
Bu deniz parçası, bu taka.
Gün bitti, yollara düştü kahır
Ötme vapur, gelemem
Dört duvara sarılmışım.
Sarmadı gitti beni
Bu yandan çarklı dünya;
İki yakam bir araya gelmiyor
Ivırı zıvırı caba.
Parmak parmak çürüdü
Bir karış ömrüm,
Yalan şeyleri özlemişim, nâfile
Nâfile şiir yazmış, kahırla yıkanmışım,
Gülmüşüm söylemişim, boşvermişim her şeye,
Senin için yaşamışım insanoğlu, nâfile!', 'Memnunum diyemem yaşadığıma, Bana bir şey söylemiyor Bu deniz parçası, bu taka. Gün bitti, yollara düştü kahır Ötme vapur, gelemem Dört duva...', ARRAY['Türk Edebiyatı','Şiir','Cahit Irgat']::text[], 8.5, '{"poet":"Cahit Irgat","poet_slug":"cahit_irgat","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEMNUNİYET', 'memnuni-yet-rustu-onur-o3nlj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benden zarar gelmez
Kovanındaki arıya
Yuvasındaki kuşa;
Ben kendi halimde yaşarım
Şapkamın altında.
Sebepsiz gülüşüm caddelerde
Memnuniyetimden;
Ve bu çılgınlık delicesine
İçimden geliyor.
Dilsiz değilim susamam
Öyle ölüler gibi
Bu güzel dünyanın ortasında
(Yeni Zonguldak, sayı 34, 23.09.1942)', 'Benden zarar gelmez Kovanındaki arıya Yuvasındaki kuşa; Ben kendi halimde yaşarım Şapkamın altında. Sebepsiz gülüşüm caddelerde Memnuniyetim...', ARRAY['Türk Edebiyatı','Şiir','Rüştü Onur']::text[], 8.5, '{"poet":"Rüştü Onur","poet_slug":"rustu_onur","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MENDİLİMDE KAN SESLERİ', 'mendi-li-mde-kan-sesleri-edip-cansever-v1mbd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yere yetişilir
Hiçbir şeye geç kalınmaz ama
Çocuğum beni bağışla
Ahmet Abi sen de bağışla
Boynu bükük duruyorsam eğer
İçimden öyle geldiği için değil
Ama hiç değil
Ah güzel Ahmet abim benim
İnsan yaşadığı yere benzer
O yerin suyuna, o yerin toprağına benzer
Suyunda yüzen balığa
Toprağını iten çiçeğe
Dağlarının, tepelerinin dumanlı eğimine
Konyanın beyaz
Antebin kırmızı düzlüğüne benzer
Göğüne benzer ki gözyaşları mavidir
Denize benzer ki dalgalıdır bakışları
Evlerine, sokaklarına, köşebaşlarına
Öylesine benzer ki
Ve avlularına
(Bir kuyu halkasıyla sıkıştırılmıştır kalbi)
Ve sözlerine
(Yani bir cep aynası alım-satımına belki)
Ve bir gün birinin adres sormasına benzer
Sorarken sorarken üzünçlü bir görüntüsüne
Camcının cam kesmesine, dülgerin rende tutmasına
Öyle bir cıgara yakımına, birinin gazoz açmasına
Minibüslerine, gecekondularına
Hasretine, yalanına benzer
Anısı işsizliktir
Acısı bilincidir
Bıçağı gözyaşlarıdır kurumakta olan
Gülemiyorsun ya, gülmek
Bir halk gülüyorsa gülmektir
Ne kadar benziyoruz Türkiye''ye Ahmet Abi.
Bir güzel kadeh tutuşun vardı eskiden
Dirseğin iskemleye dayalı
-- Bir vakitler gökyüzüne dayalı, derdim ben --
Cıgara paketinde yazılar resimler
Resimler: cezaevleri
Resimler: özlem
Resimler: eskidenberi
Ve bir kaşın yukarı kalkık
Sevmen acele
Dostluğun çabuk
Bakıyorum da simdi
O kadeh bir küfür gibi duruyor elinde.
Ve zaman dediğimiz nedir ki Ahmet Abi
Biz eskiden seninle
İstasyonları dolaşırdık bir bir
O zamanlar Malatya kokardı istasyonlar
Nazilli kokardı
Ve yağmurdan ıslandıkça Edirne postası
Kıl gibi ince İstanbul yağmurunun altında
Esmer bir kadın sevmiş gibi olurdun sen
Kadının ütülü patiskalardan bir teni
Upuzun boynu
Kirpikleri
Ve sana Ahmet Abi
uzaktan uzaktan domates peynir keserdi sanki
Sofranı kurardı
Elini bir suya koyar gibi kalbinden akana koyardı
Cezaevlerine düşsen cıgaranı getirirdi
Çocuklar doğururdu
Ve o çocukların dünyayı düzeltecek ellerini işlerdi bir dantel gibi
O çocuklar büyüyecek
O çocuklar büyüyecek
O çocuklar...
Bilmezlikten gelme Ahmet Abi
Umudu dürt
Umutsuzluğu yatıştır
Diyeceğim şu ki
Yok olan bir şeylere benzerdi o zaman trenler
Oysa o kadar kullanışlı ki şimdi
Hayalsiz yaşıyoruz nerdeyse
Çocuklar, kadınlar, erkekler
Trenler tıklım tıklım
Trenler cepheye giden trenler gibi
İşçiler
Almanya yolcusu işçiler
Kadınlar
Kimi yolcu, kimi gurbet bekçisi
Ellerinde bavullar, fileler
Kolonyalar, su şişeleri, paketler
Onlar ki, hepsi
Bir tutsak ağaç gibi yanlış yerlere büyüyenler
Ah güzel Ahmet Abim benim
Gördün mü bak
Dağılmış pazar yerlerine benziyor şimdi istasyonlar
Ve dağılmış pazar yerlerine memleket
Gelmiyor içimden hüzünlenmek bile
Gelse de
Öyle sürekli değil
Bir caz müziği gibi gelip geçiyor hüzün
O kadar çabuk
O kadar kısa
İşte o kadar.
Ahmet Abi, güzelim, bir mendil niye kanar
Diş değil, tırnak değil, bir mendil niye kanar
Mendilimde kan sesleri.', 'Her yere yetişilir Hiçbir şeye geç kalınmaz ama Çocuğum beni bağışla Ahmet Abi sen de bağışla Boynu bükük duruyorsam eğer İçimden öyle geldi...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip_cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":102}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MENDİREK', 'mendi-rek-roni-margulies-9nwpl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Antik mendireğin ucunda
vaktinden evvel kararıyor hava,
denize doğru iniyor bulutlar,
ince bir yağmur başlıyor birden.
Palamut iskelesiymiş burası
milattan önce kimbilir kaç yılında.
Arkamda yalçın bir tepe,
birkaç sütun, zeytinlikler.
Yavaşça, denizin derinliklerinden
volkanik bir ada yükselircesine,
Elsa geliyor yine aklıma.
Nasıl yenilebildim koşullara!
Gemilere palamut yükleyenler,
palamutu toplayanlar, gemiciler,
hiç biri yok artık.
Sadece mendirek ve zeytinlikler.', 'Antik mendireğin ucunda vaktinden evvel kararıyor hava, denize doğru iniyor bulutlar, ince bir yağmur başlıyor birden. Palamut iskelesiymiş ...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MENEKŞELİ ACILAR', 'menekseli-acilar-attila-asut-2un4c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özen''e
Bir kadın… karda kışta
Yürüyordu gizli düşte
Bir yakada açık görüş
Öbür yaka direnişte.
Bir kadın… düşleri karabasan
Çıkıyor merdivenlerinden acının
Çok ince bir hüznü menekşeliyor
Soğuk gölgesinde darağacının.
Bir kadın… yaşamın terkisinde
Ardı sıra doludizgin atlılar
Ceylanlar gezinir gözlerinde
Heybesinde menekşeli acılar.
Mamak, Eylül 1983', 'Özen''e Bir kadın… karda kışta Yürüyordu gizli düşte Bir yakada açık görüş Öbür yaka direnişte. Bir kadın… düşleri karabasan Çıkıyor merdiven...', ARRAY['Türk Edebiyatı','Şiir','Attila Aşut']::text[], 8.5, '{"poet":"Attila Aşut","poet_slug":"attila_asut","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MENFİS', 'menfi-s-necati-cumali-0p7xb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saçların Eski Mısır
Bakışların Nil
Beyaz ketenler giyin
Menfis''liler gibi sen de
Menfis''e gidelim
Bir gün olsun Menfis''te
Kalsam seninle
Kuru taş bir otelde
Çözerim gizini
Hiyeroglifin', 'Saçların Eski Mısır Bakışların Nil Beyaz ketenler giyin Menfis''liler gibi sen de Menfis''e gidelim Bir gün olsun Menfis''te Kalsam seninle Kur...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MENZİL', 'menzi-l-refik-durbas-p118l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onlar ki aydınlık üzre
ecel toprağına
umut
ektiler. Ay dolandı vay deli gönlüm
Ölüm şaşırdı menzilini
Onlar ki karanlık üzre
korku mazgalına
zulüm
serdiler. Ay dolandı vay deli gönlüm
Ölüm şaşırdı menzilini
Onlar ki cehennem üzre
yürekten
cennet
süzdüler. Ay dolandı vay deli gönlüm
Ölüm şaşırdı menzilini', 'Onlar ki aydınlık üzre ecel toprağına umut ektiler. Ay dolandı vay deli gönlüm Ölüm şaşırdı menzilini Onlar ki karanlık üzre korku mazgalına...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERİÇ', 'meri-c-ulug-turanlioglu-zdbaw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlüm gibi dalgın, kanlı sularında,
Bir gam dünyasını yıkılırken gördüm.
Rüyaya dalarken yeşil ''Bülbül Ada''
Ağlıyan seslerle ben besteler ördüm.
Solgun bir çehreydi kâinat o akşam,
Maziyi anarak inledim sessizce,
Gölgeler erirken ufku sarmıştı gam
Ve gönül dalmıştı uyuyan Meriç''e.', 'Gönlüm gibi dalgın, kanlı sularında, Bir gam dünyasını yıkılırken gördüm. Rüyaya dalarken yeşil ''Bülbül Ada'' Ağlıyan seslerle ben besteler ö...', ARRAY['Türk Edebiyatı','Şiir','Uluğ Turanlioğlu']::text[], 8.5, '{"poet":"Uluğ Turanlioğlu","poet_slug":"ulug_turanlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERAK', 'merak-aziz-nesi-n-9e2er', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir merak öyle bir merak
Ölümümden bir ay sonra bir güncük yaşamak
Ve dostu düşmanı
Suçüstü yakalamak', 'İçimde bir merak öyle bir merak Ölümümden bir ay sonra bir güncük yaşamak Ve dostu düşmanı Suçüstü yakalamak...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERDİVEN', 'merdi-ven-ahmet-hasi-m-wo0to', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağır, ağır çıkacaksın bu merdivenlerden,
Eteklerinde güneş rengi bir yığın yaprak,
Ve bir zaman bakacaksın semâya ağlayarak...
Sular sarardı... yüzün perde perde solmakta,
Kızıl havâları seyret ki akşam olmakta...
Eğilmiş arza, kanar, muttasıl kanar güller;
Durur alev gibi dallarda kanlı bülbüller,
Sular mı yandı? Neden tunca benziyor mermer?
Bu bir lisân-ı hafîdir ki ruha dolmakta,
Kızıl havâları seyret ki akşam olmakta...', 'Ağır, ağır çıkacaksın bu merdivenlerden, Eteklerinde güneş rengi bir yığın yaprak, Ve bir zaman bakacaksın semâya ağlayarak... Sular sarardı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERDİVENLERDEN DÜŞER BABAMIN SESİ', 'merdi-venlerden-duser-babamin-sesi-umit-sener-ta-r5h7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yanlışlını duyuyorum yüzümün
bomboş
ne kadar da benziyor ölüme
bardaklar düşüyor merdivenlerden
soğuk kışlar
teneke kutuları
ısıtamadığım kadınlar
babam düşüyor ardı sıra
anneme kıyardı
öldürürdüm her gece
titremesi düşerdi elerimin', 'yanlışlını duyuyorum yüzümün bomboş ne kadar da benziyor ölüme bardaklar düşüyor merdivenlerden soğuk kışlar teneke kutuları ısıtamadığım ka...', ARRAY['Türk Edebiyatı','Şiir','Ümit Şener Ta']::text[], 8.5, '{"poet":"Ümit Şener Ta","poet_slug":"umit_sener_ta","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERHABA CANIM', 'merhaba-canim-arkadas-zekai-ozger-mdx86', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben az konuşan çok yorulan biriyim
şarabı helvayla içmeyi severim
hiç namaz kılmadım şimdiye kadar
annemi ve allahı da çok severim
annem de allahı çok sever
biz bütün aile zaten biraz
allahı da kedileri de çok severiz
hayat trajik bir homoseksüeldir
bence bütün homoseksüeller adonistir biraz
çünki bütün sarhoşluklar biraz
freüdün alkolsüz sayıklamalarıdır
siz inanmayın bir gün değişir elbet
güneşe ve penise tapan rüzgârın yönü
çünki ben okumuştum muydu neydi
biryerlerde tanrılara kadın satıldığını
ah canım aristophones
barışı ve eşek arılarını hiç unutmuyorum
ölümü de bir giz gibi tutuyorum içimde
ölümü tanrıya saklıyorum
ve bir gün hiç anlamıyacaksınız
güneşe ve erkekliğe büyüyen vücudum
düşüvericek ellerinizden ellerinizden ve
bir gün elbette
zeki müreni seviceksiniz
(zeki müreni seviniz)', 'ben az konuşan çok yorulan biriyim şarabı helvayla içmeyi severim hiç namaz kılmadım şimdiye kadar annemi ve allahı da çok severim annem de ...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas_zekai_ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERHABA, GUATEMALA!', 'merhaba-guatemala-miguel-angel-asturias-dwn4c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba, yumuşak kanatlı, kumral Guatemala!
Sevginin, kardeşliğin toprağı, merhaba!
Merhaba, sessizliğin,yalnızlığın türküsü, Guatemala!
Merhaba, iyiliğin eli!
Tanrının eli, merhaba!
Evlâtlarının sırtları birer kapı,
kapar o kapılar dünyanın giriş yerini,
bu etten kemikten kapıların ardına bakma!
Çığlıklar göklere ağar, ve ölüm askerleri
orda parlatır çizmelerini kanla.
İnsan dolu zındanlar, tıklım tıklım, yıkılacak gibi,
tıklım tıklım zındanlara bakma!
Tekmil duvarlar delik deşik kurşunlarla,
delik deşik duvarlara bakma!
Almış başını kaçar korkudan tekmil yollar,
korkudan kaçan yollara bakma!
Kapasın önünü bu kapı senin,
bu kapı bunların hiç birini sana göstermesin,
zincire vurulmuş insanın sırtı, bu kapı.
Tarlalara, yeşermiş taze bitkilere bakma!
Boyunduruğa, darağacına bakma!
Kiliselere, kutsal eşyaya bakma!
Körüz biz, kör olmasına körüz ama,
kızımız, anamız, avradımızsın sen bizim,
ne olur, uzak kalma gözümüzden.
Bugün kızımız ellere satılık.
Cezası yok mu bunun! Nerdesin, ceza?
Ağzının açmaz kimse, kıpırdatmaz dudağı
ama herkes, gece gündüz, ve inanmadan,
senin görmediğini görür, ey vatan,
görür şölen yemekleri yediğini
iri kemikli, et yiyici büyük korsanın,
senin memelerinden yapılmış yemekler,
senin pütürlü memelerinden,
ey canım toprak!
Seni satanları görür, hepsi bekçilik eder, hepsi nöbette:
Yersin yumruğu, tekmeyi, kırbacı, kurşunu,
bu altın şölenin tadını hiç kimse kaçırmayacak.
Şu rüzgâr söndürecekse söndürsün artık
senin göklerini ışıklarıyla boyayan çırağıyı,
kaplasın gün ışığını sonsuz karanlıklar;
Büyük korsan, şu hayvan gözlü,
evinde, toplamış eşini dostunu,
hart hart yer durur vatanı,
nasıl oynarsa bir top oyuncusu topla,
öyle okşar durur ötesini berisini,
bekler kendinden geçsin, koyversin kendini,
kolları arasında, utancından.
Hâlâ neden kararsız gökyüzü?
Tanrı bu kadar kötü mü ki?
Bunca şirinliği, birikmiş güzelliği silip süpürmek için
yürürken deniz karalara, göllere doğru,
öç alan bir deprem atarken her şeyi ölümün ağzına,
büyük korsan tükürürken tütününü,
titrek sesiyle tırmalar dururken
perişan vatanın kokulu kulağını!
Hâlâ neden kararmaz gökyüzü?
Tanrı bu kadar kötü mü ki?
Köleliğin kısır, verimsiz kumsalında
zaman diye bir şey yok.
Zaman yapraklarda, dallardaydı,
gövdelerindeydi ağaçların, ve köklerinde,
cıvıl cıvıl bir şeydi zaman, yaşayan, canlı,
zaman yaşamıydı yani insanoğlunun.
Bir gün vatan yurdun bütün saatlerinde yaşamıştı bu zamanı.
Ama bugün gelin görün ki,
doyurmak için koca korsan aç karnını,
bir bir kendisi saymakta bu zamanın günlerini.
Ateş, kasırga, şimşek, nerdesiniz, çabuk olun!
Vatan ki bir dilber, bir içim suydu,
belindeki kemer parçalanmış bir menteşe!
O sülün boy, o su testisi, o başının tacı,
dilberliğini yapan şeyler değil de neydi?
O güzelim papuçlar değil miydi alımını arttıran?
Çıkın alevler, sarılın ağaçların, ürünlerin boğazına,
yansın büyük korsanın önünde toprak yalım yalım!
Ölüm zamanı sarmakta!
Ölüm sarmakta dünyayı!
Yok olsun bütün hayat adası!
Yok olsun bütün hayal adası!
Vatan satılmıştır büyük korsana!
Uyur ağaçlar kışın.
Vatanda uyusun ağaçlar gibi.
Peşinde bir sürü kuyruğuyla
büyük korsan saltanat sürsün,
vatan da uyusun bu köle haliyle,
yıldızlara,haydi parlayın, diyeceğimiz güne dek,
yansıtın gökyüzüne bu çınlayan sevinci,
diyeceğimiz güne dek sulara,
haydi uyanın, diyeceğimiz güne dek ölülere,
işte o gün geldi, diyeceğimiz güne dek,
evlerimiz kurtuldu cellâtlardan,
hayat zulümden ve korkudan kurtuldu,
kurtuldu yabancılardan toprak,
haydi, ekelim tohumu,
altın buğdayı devşirelim, tam zamanı,
açalım kollarımızı, sarılalım sevgili vatanın boynuna,
gözlerimizde mutluluğun yağmuru;
evlâtlarının arasındasın işte,
evlâtların işte seninle sarmaşdolaş,
diyeceğimiz o mutlu güne dek,
vatan uyusun!
Miguel Angel ASTURIAS', 'Merhaba, yumuşak kanatlı, kumral Guatemala! Sevginin, kardeşliğin toprağı, merhaba! Merhaba, sessizliğin,yalnızlığın türküsü, Guatemala! Mer...', ARRAY['Türk Edebiyatı','Şiir','Miguel Angel Asturias']::text[], 8.5, '{"poet":"Miguel Angel Asturias","poet_slug":"miguel_angel_asturias","theme":"Türk Şiiri","is_hero":false,"total_lines":105}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERHABA HOŞ GELDİN', 'merhaba-hos-geldi-n-seyyi-d-nesi-mi-42aqr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Merhabâ hoş geldin ey rûh-i revânım merhabâ
Ey şeker-leb yâr-ı şirîn lâ-mekânım merhabâ
Çün lebin câm-ı Cem oldu nefha-i Rühu''l-Kudüs
Ey cemilim ey cemâlim bahr u kânım merhabâ
Gönlüme hîç senden özge nesne lâyık görmedim
Sûretim aklım ukûlüm cism ü cânım merhabâ
Ey melek sûretli dil-ber cân fedâdır yoluna
Çün dedin lahmike lahmi kana kanım merhabâ
Geldi yârım nâs ile sordu Nesîmî neçesin
Merhabâ hoş geldin ey rûh-i revânım merhabâ', 'Merhabâ hoş geldin ey rûh-i revânım merhabâ Ey şeker-leb yâr-ı şirîn lâ-mekânım merhabâ Çün lebin câm-ı Cem oldu nefha-i Rühu''l-Kudüs Ey cem...', ARRAY['Türk Edebiyatı','Şiir','Seyyi̇d  Nesi̇mi̇']::text[], 8.5, '{"poet":"Seyyi̇d  Nesi̇mi̇","poet_slug":"seyyid_nesimi","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERHABA YERYÜZÜ', 'merhaba-yeryuzu-mustak-erenus-4zwef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eşref saati hayra dolu
Bir cömert günün ortasında
Dönüp de yaşar mısın deseler
Uzayası şu güdük ömrünü
Ve verseler elime anahtarlarını
Tüm geçmiş günlerimin
İstemem derim.
Kalsın eksiğinde o kullanılmış günler
Bir su damlası telaşında
Elini öptüğüm ilk sevgilim
Düşlerimle oynaşan o haşarı renkler
Ve Şükriye anamın ölümü ile yalnayak
Eskişehir istasyon yolu..
İstemem derim
İstemem.
Kalsın eksiğinde o tükenmiş günler
Ama bugün
Yaşamın bu şaşkın destursuz cümbüşünde
Cenklisi cefalısı
Mutlusu belalısı
Benim hepsi bütün günlerim
Hepsi benim
Geceye ateş yakmış
Dağ başındaki bir keşiş inadıyla', 'Eşref saati hayra dolu Bir cömert günün ortasında Dönüp de yaşar mısın deseler Uzayası şu güdük ömrünü Ve verseler elime anahtarlarını Tüm g...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERMER', 'mermer-steinn-steinarr-ew90i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gök kamaştıran YUNAN
Ve ROMA yüceliği
Toza dönüşür yeryüzünde.
Alır götürür bir gün
Onları esen rüzgâr
Ben kalırım:
İnsan eli değmemiş gibi hiç
Beklerim
Yaratıcı ustamı.
Steinn  STEINARR', 'Gök kamaştıran YUNAN Ve ROMA yüceliği Toza dönüşür yeryüzünde. Alır götürür bir gün Onları esen rüzgâr Ben kalırım: İnsan eli değmemiş gibi ...', ARRAY['Türk Edebiyatı','Şiir','Steinn  Steinarr']::text[], 8.5, '{"poet":"Steinn  Steinarr","poet_slug":"steinn_steinarr","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERMERLERİ GÜNÜMÜZE KALAN KADINLAR', 'mermerleri-gunumuze-kalan-kadinlar-kemal-ozer-bhcq8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gül kokan odalarda aynalara karşı
hakkını vermişler beyazın
mermerleri günümüze kalan kadınlar
dövme tenli kıvırcık dudaklı
bir köle sabaha kadar yataklarında
utanarak yazdığı eski kitapların', 'gül kokan odalarda aynalara karşı hakkını vermişler beyazın mermerleri günümüze kalan kadınlar dövme tenli kıvırcık dudaklı bir köle sabaha ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERNUŞ''UN TÜRKÜSÜ', 'mernus-un-turkusu-gulten-akin-3knko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tomurcuk patlarken dağıttığı ışığı
Tay büyürken dağıttığı ışığı
Gülü gül diye sevmeyi
Çok var dostum gibi özledim
Güz geldi geçti
Sarı yaprak kuru dal derlendi
Sırtını ağaca verdi bahçıvan
Oturdu kendine tütün sardı
İnce sular yatağını buldu
Gök duruldu
Ben güzü görmedim
Göğü görmedim
Dalı bahçıvanı görmedim
Sonuncu Roma da eskidi
Taşa kesti Mernuş, Tebernuş, Kıtmir
Oysa çıldırmanın çağıdır
Aç sımsıkı çektiğin perdeleri
Ölümlerle zulumlarla
Sarsma bedenimi öyle
Daldığım kan uykudan
Usul usul uyandır', 'Tomurcuk patlarken dağıttığı ışığı Tay büyürken dağıttığı ışığı Gülü gül diye sevmeyi Çok var dostum gibi özledim Güz geldi geçti Sarı yapra...', ARRAY['Türk Edebiyatı','Şiir','Gülten Akin']::text[], 8.5, '{"poet":"Gülten Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MERYEMANA''YA DUA BALADI', 'meryemana-ya-dua-baladi-francois-villon-v5zmc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deyin İsa Peygambere benim''çün,
Bağışlasın suçlarımı birer birer:
İyilik gören papaz Theophilus''ün
Hani o Mısırlı Kadın''ın dostlar,
Bağışlanması gibi.. değil mi kader..
Şeytana vâdedilmişti bilirsiniz,
Beni beterinden esirgeyiniz,
Paraymış, şöhretmiş boyun eğmiyorum,
Arasında o kutsal bildiklerimiz,
Bu ruhla yaşamak, ölmek istiyorum.
Bir ihtiyarcağızım ben yoksul, üzgün
Ne okuma, ne yazma.. ben de ne gezer,
Ben bir yanık âşık bir köşede her gün
Neylerin çalındığı cânım cennetler,
O fıkır fıkır kaynayan cehennemler,
Birinde sevinç, birinde kederimiz
Ulu Tanrıça, huzuruna gelmişiz.
Tüm suçlularla işte baş eğiyorum,
Senin yoluna kul kurban serilmişiz
Bu ruhla yaşamak, ölmek istiyorum.
François VILLON', 'Deyin İsa Peygambere benim''çün, Bağışlasın suçlarımı birer birer: İyilik gören papaz Theophilus''ün Hani o Mısırlı Kadın''ın dostlar, Bağışlan...', ARRAY['Türk Edebiyatı','Şiir','François Villon']::text[], 8.5, '{"poet":"François Villon","poet_slug":"francois_villon","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MESAİ BİTTİ', 'mesai-bi-tti-arzu-aslan-oktj1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'mesai bitti akşam hafiften dayılanıyor
kaçılsın tezayaklar ağzına bile sürmemişler
ciddiyetle hep aynı macerayı
danışıklı bir şaşkınlıkla eğiren
eli sıkı memurlar
tıkır tıkır dönüyor akşam
çay üstüne çay
düğüm düğüm üstüne
şakır şukur olasılıklar kararmış ıstakada
kirli bir elliikiden yasak heyecanlar devşiriyor
muvakkat işçiler
sinema çıkışında bekleyen akşamlar gibi ansızın
ama ağırdan geçilir işrete
sigara kokusu ancak bu kadar yakışır
şakşakçı garsonlar doldurur karnesini
cıvıl cıvıl alkolik çıraklarının
pespaye bir akşamı gıdıklıyor ruhunun onulmazı
ana avrat çoluk çoçuk bir yana
çoktan vazgeçmiş kendinden
birkaç saatliğine sarılmış yalnızlığına
gözünde büyüdükçe büyüyor sabah', 'mesai bitti akşam hafiften dayılanıyor kaçılsın tezayaklar ağzına bile sürmemişler ciddiyetle hep aynı macerayı danışıklı bir şaşkınlıkla eğ...', ARRAY['Türk Edebiyatı','Şiir','Arzu Aslan']::text[], 8.5, '{"poet":"Arzu Aslan","poet_slug":"arzu_aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'METAMOSMORİS', 'metamosmori-s-can-yucel-z6846', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlkin ELİFBA''ydı
