INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'METİN ALTIOK`A', 'meti-n-altiok-a-yusuf-altunel-kbb5x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'odanın
ortasında
yanarbiri
üç gülüm
mum
dönerbiri
üçkülüm
mum
sönerbiri
üçölüm
mum', 'odanın ortasında yanarbiri üç gülüm mum dönerbiri üçkülüm mum sönerbiri üçölüm mum...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'METROPOL AŞKLARI II', 'metropol-asklari-ii-serkan-isin-d9g75', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Firdevs''e
"Geceyi burada geçirdiler
Rıhtım''ın karşısında
Martıların sabah şarkısında uyanan
Su ile yaralanacakmış gibi duran
Dudakları hala -öldüklerinde bile- çatlak
Tenleri hala biraz kırmızı utancın tatlı ateşiyle
Uyuduklarında şehir sustu
Geceyi burada geçirdiler
Rıhtım''ın karşısında, penceresinden deniz görünen
Apartman katında"
Şehri dolanıyorlar şimdi
Sormuyorlar Kadıköy''de neden pencereleri merakla açılır aşkın
Soğukluğu ve durgunluğu nasıl aşılır gecenin
Tenleri ucuz viski ile sarhoş
Akılları yalnız bir adanın yalnızlığında
Özenle seçilmiş hüzünlerde tüketirler
Eksiltirler düşleri hep, hep düşleri eksiktir
Sonra birden öpüşmeye başlarlar,
İki dudak, dudaklar, içlerinde sevgisizliğin açık tehtidi
Bazen susmazlar, konuşurlar, kadıköyde rıhtımın karşısında
deli bir piyangocunun parmaklarının dolandığı
ve bizim kader dediğimiz o amortinin
kendilerine vurmasını isteyen küçük çocuklar
parayı kazandıklarında
ilk işleri bir martı evi açmak olan
mutsuz gece bekçileri sevdanın
onlar olmasa ne güneş doğacak
ne çiçek açacak
ne şehir katran karası irininden sıyrılacak
ne de beyaz olacak
onlar
metropol''un aşkını kınından sıyırır, dirençle taşırlar
sevişmeleri eksikse bize ne
önümüze koyarlar yırtılmış dillerini ve damaklarını
öpüşlerini sererler gizliden gizliye
oysa biz onları hiç sevmezdik
kadıköyde bir evde
öldüklerinde
öldüklerinde
rıhtım''ın karşısında geçirdiler
geceyi
sonra soğuk
birden
çöktü
metropol bindi üzerlerine
aniden aşk
birden ayrılık
ve baki kalan sevgilerinin en derin yerinde
susuş
en sevdiğiydi bu kadının, beyaz tenine taparcasına
susuş
sözcükler, bu sözcükler işte
anlamıyorlar ki bir tanem
dağınık imgelerde ortada gün gibi duran
ah yalnızlık
gece kağıda bıraktığımız
her sabah biraz daha silinen umutlarımız
kendimizi kanatarak canlı tuttuğumuz
sevda.', 'Firdevs''e "Geceyi burada geçirdiler Rıhtım''ın karşısında Martıların sabah şarkısında uyanan Su ile yaralanacakmış gibi duran Dudakları hala ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Işin']::text[], 8.5, '{"poet":"Serkan Işin","poet_slug":"serkan_isin","theme":"Türk Şiiri","is_hero":false,"total_lines":62}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEVLÛT', 'mevl-t-attila-asut-e1cw8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I.
Bir yenik gecemden sesleniyorum sana
Saçlarımda ıslaklığı nisan yağmurlarının
Umutsuzlar Parkı''nda yitirdim gözlerimi
Bırak şimdi mutlu yaşantıları
Van Gogh''un buğday tarlasını unut,
Tut elimden
düşeceğim
Mevlût!
II.
O günah akşamının serüvenini düşün
Delidolu hulo hoop''çu kızları…
Hani bir bel kıvırmaları vardı çılgın ezgileri arasında gecenin
Bir çember çevirmeleri vardı…
Dönüp duruyorlardı ıslak ağızlarına karşı esriklerin,
Dudaklarında pembe günahlar,
Ellerinde hula hoop çemberleri.
-Ve sonunda kalçaların konuştuğu bir saat-
Geçirdi boynumuza halkaları
Delidolu hula hoop''çu kızları
Esrik gecelerin özgürlüğüne inat.
III.
Şimdi bir park köşesinde yapayalnızım
Hep Âdem''in yasak yemişine uzanır böylesi gecelerde eller
Bütün kapılar günah akşamlarına açılır
İnsan böyle gecelerde cinayet işler.
Korkuyorum, bu yalnızlık öldürecek beni,
Yüreciğim bölük  pörçük bugece…
Gelmek istiyorum, gelemiyorum
Bak, bu yenik geceden sesleniyorum:
Tut elimden
düşeceğim
tuuut,
Garibistan''lı Mevlût!
(1959)', 'I. Bir yenik gecemden sesleniyorum sana Saçlarımda ıslaklığı nisan yağmurlarının Umutsuzlar Parkı''nda yitirdim gözlerimi Bırak şimdi mutlu y...', ARRAY['Türk Edebiyatı','Şiir','Attila Aşut']::text[], 8.5, '{"poet":"Attila Aşut","poet_slug":"attila_asut","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEVSİM SONBAHAR', 'mevsi-m-sonbahar-timucin-ozyurekli-64j4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmur dindi, rüzgâr esmiyor
mevsim sonbahar, aylardan eylül
sarı yüzün hüzünlü bir çağrı
koklasam: tenin nane kokmuyor
rüzgâr esmiyor, yağmur dindi
bu deniz bizim mavi denizimiz değil
telefonum çalmıyor, mektubun gelmiyor
günler akıp gidiyor, evler sessiz
yağmur dindi, rüzgâr esmiyor
"ayva sarı nar kırmızı sonbahar..."
hisarönü kahvesi: çiçek ve kilim
aramız uzak, bakışım dağları aşmıyor
rüzgâr esmiyor, yağmur dindi
fotoğrafın solgun, sis içinde kâlbim
bir şarkı mırıldansam sensiz olmuyor
dokunsam: anılar kırılıp dağılıyor
yağmur dindi, rüzgâr esmiyor
şimdi sadece korkunç sessizlik
duvarda boş bir çerçeve duruyor
istasyon''da bıraktım gölgemi.
ölüm kadar yakınsın bana
hayat kadar uzak, ah sonbahar...', 'yağmur dindi, rüzgâr esmiyor mevsim sonbahar, aylardan eylül sarı yüzün hüzünlü bir çağrı koklasam: tenin nane kokmuyor rüzgâr esmiyor, yağm...', ARRAY['Türk Edebiyatı','Şiir','Timuçin Özyürekli̇']::text[], 8.5, '{"poet":"Timuçin Özyürekli̇","poet_slug":"timucin_ozyurekli","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEVSİM', 'mevsi-m-wole-soyi-nka-o8jz7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pas olgunluktur, pas
Ve benzi sarı mısır tüyleri;
Çiçek tozları çiftleşmek üzeredir
Kırlangıçlar dansa durduğu zaman
Okun ucundaki tüy gibi
Uçuşmakta mısır saplarının iplikçikleri
Işığın hizasında. Ve biz işitmekten sevinçli
Rüzgârın toplu yürüyüşünü, işitmek
Ovadaki bıçkı sesini, mısırların bırakıldığı yerde
Bambu kıymıkları gibi içine işlediği.
Biz toplayıcılar, şimdi
Püsküllerin üstündeki pası beklerken, çekilir
Alacakaranlıktan uzun gölgeler, kaplanır çelenk gibi
Sazdan samandan arabalar tütsüler içinde. Su yüklü saplar
Tohumun çürüğüne yürürler - biz bekleriz
Pasın söz verdiğini.
Wole SOYİNKA', 'Pas olgunluktur, pas Ve benzi sarı mısır tüyleri; Çiçek tozları çiftleşmek üzeredir Kırlangıçlar dansa durduğu zaman Okun ucundaki tüy gibi ...', ARRAY['Türk Edebiyatı','Şiir','Wole Soyi̇nka']::text[], 8.5, '{"poet":"Wole Soyi̇nka","poet_slug":"wole_soyinka","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEYDAN OKUMAK', 'meydan-okumak-hasan-i-zzetti-n-di-namo-sg4ju', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bizde neden ağlayan bir Fuzulî çıkmış
Şimdi anlıyorum bunu derinden.
Kaç Fuzulî, Fuzulî olmadan önce
Kahrolup gitmiştir üzüntülerinden.
Öyle çekmişim ki
Artık benden sonra
Birkaç satırımın yaşaması bile
bana vızgeliyor.
Artık bahçemdeki yemişlere
ne güleryüzlü bir dost
ne hırsız geliyor.
Demek, diyorum, bu duruma gelirmiş
budana budana bir şair.
Ölümsüzlüğe sırtını dönmüş şiir
Artık acıya meydan okuyabilir.', 'Bizde neden ağlayan bir Fuzulî çıkmış Şimdi anlıyorum bunu derinden. Kaç Fuzulî, Fuzulî olmadan önce Kahrolup gitmiştir üzüntülerinden. Öyle...', ARRAY['Türk Edebiyatı','Şiir','Hasan İzzetti̇n Di̇namo']::text[], 8.5, '{"poet":"Hasan İzzetti̇n Di̇namo","poet_slug":"hasan_izzettin_dinamo","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEYHANE', 'meyhane-salah-bi-rsel-pbg61', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ozan Andre Chenier yi
İkiye böldüğünden beri giyotin
Kurum satıyorsa meydanlarında Paris in
Ozan kardeş hadi hop
Sende uzat boynunu
Eş dost akraba beklemesin
Hadi hop sayın cellatlar da
Kavuşsun erkenden çoluk çocuğuna
Tarihten anlaşıldığına göre
Sırası suyu yok bu işin
Sokakdan el ayak çekildimi
Sen de tırt sepete
Ozana kardeş hele hele
Sepete düşdükden sonra da
Tut ki sakallarını öyle dipten
Genç sıska dul ihtiyar
Tümü meraklı yurttaşların
Tıraşlı bir baş görsün
Hadi kuzular da meyhaneye', 'Ozan Andre Chenier yi İkiye böldüğünden beri giyotin Kurum satıyorsa meydanlarında Paris in Ozan kardeş hadi hop Sende uzat boynunu Eş dost ...', ARRAY['Türk Edebiyatı','Şiir','Salah Bi̇rsel']::text[], 8.5, '{"poet":"Salah Bi̇rsel","poet_slug":"salah_birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEZAR TAŞLARI', 'mezar-taslari-philippe-soupault-lm1pv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'FRANCIS PICABIA
Niçin
Seni mezarına dört köpeğinle
Bir gazeteyle
Ve şapkanla gömmelerini istedin
İstedin ki taşına şunu yazsınlar
İyi seyahatler
Bir şey değil öteki dünyada da deli zannedileceksin.
THÉODORE FRAENKEL
Öldüğün vakit harikulâde bir hava vardı
Mezarlık o kadar güzeldi ki
Hiç kimse mahzun olamadı
Epeydir de senin artık orda olmadığını sanıyorlar
Homurdanmalarını duymuyorum
Susuyorsun
Yahut omuz silkiyorsun
Cenneti görmeyi asla istemezdin
Nereye gideceğini artık bilmiyorsun
Ama sen işin alayındasın
MARIE LAURENCIN
Kafesteki bu güzel kuş
Senin mezardaki gülüşündür
Yapraklar dans ediyor
Uzun uzun yağmur yağacak
Bu akşam hareketimden evvel
Ağaçların çiçek açtığını görmek istiyorum
Bir dişi geyik sessizce yaklaşacak
Bulutlar biliyorsun pembe ve mavidir
LOUIS ARAGON
Dostların küçük kızlar halka oldular
Sana çelenkler ördüler
Ufacık yalanlarınla
Sana kâğıt getirdim
Ve çok iyi bir kalem
Ebediyette şiirler yazacaksın
Koruyucu melek seni teselli eder
Kravatını bağlar
Ve sana gülmesini öğretir
Artık beni unuttun
Allah benden çok daha güzeldir
PAUL ÉLUARD
Oraya bastonunu ve eldivenlerini de götür
Düz dur
Gözler kapalı
Pamuk bulutlar uzaklarda
Ve bana Allahaısmarladık demeden gittin
Bir yağmur
Bir yağmur
Bir yağmur
TRISTAN TZARA
Kim o
Bana elini uzatmadın
Ölümünü duydukları vakit çok güldüler
Ebedî olmandan öyle korkmuşlardı ki
Son nefesin
Son gülüşün
Ne çiçek ne de çelenk
Sadece küçük otomobiller
Ve beş metre boyunda kelebekler
ANDRÉ BRETON
Bakışını gördüm
Gözlerini kapattığın zaman
Mahzun olmama izin vermedin
Ve ben bir şey yapmasam bile bol bol ağladım
Artık bana hiçbir şey söylemeyeceksin
Hiç ama hiç
Bir sürü adam çiçekler getirdi
Nutuklar bile söylendi
Ben hiçbir şey söylemedim
Seni düşündüm.
Philippe SOUPAULT', 'FRANCIS PICABIA Niçin Seni mezarına dört köpeğinle Bir gazeteyle Ve şapkanla gömmelerini istedin İstedin ki taşına şunu yazsınlar İyi seyaha...', ARRAY['Türk Edebiyatı','Şiir','Philippe Soupault']::text[], 8.5, '{"poet":"Philippe Soupault","poet_slug":"philippe_soupault","theme":"Türk Şiiri","is_hero":false,"total_lines":73}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEZARTAŞI ÇİÇEKLERİ', 'mezartasi-ci-cekleri-cemal-sureya-pj2or', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '70.000 aşk ve 90.000.000 dize:
Ünlü şair İlhan Berk burda yatıyor!
N''olur yolcu, sevaptır, sakın üşenme,
Yukardaki sayıya bir sıfır da sen ekle.', '70.000 aşk ve 90.000.000 dize: Ünlü şair İlhan Berk burda yatıyor! N''olur yolcu, sevaptır, sakın üşenme, Yukardaki sayıya bir sıfır da sen e...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MÜGE VE MİNE VE MENEKŞE VE MAYIS', 'muge-ve-mi-ne-ve-menekse-ve-mayis-edward-estlin-cummings-bl1ui', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'müge ve mine ve menekşe ve mayıs
indiler kumsala(bir gün oynamaya)
ve müge bir istiridye kabuğu buldu şarkı söyleyen
öyle sevimliydi ki anımsamıyordu dertlerini ve
mine arkadaş oldu karaya vurmuş bir yıldızla
ordaydı denizyıldızı beş yorgun parmağıyla;
ve menekşeyi korkunç bir şey kovaladı
kaçtı kıyıya üfleyerek hava kabarcıklarını:ve
mayıs döndü eve her yanı düzgün bir kaya ile
dünya gibi küçücük yalnızlık gibi kocaman
Yitirdiğimiz ne olursa olsun(bir sen ya da bir ben gibi)
denizde bulduklarımız hep  kendimiziz değil mi
Edward Estlin CUMMINGS', 'müge ve mine ve menekşe ve mayıs indiler kumsala(bir gün oynamaya) ve müge bir istiridye kabuğu buldu şarkı söyleyen öyle sevimliydi ki anım...', ARRAY['Türk Edebiyatı','Şiir','Edward Estlin Cummings']::text[], 8.5, '{"poet":"Edward Estlin Cummings","poet_slug":"edward_estlin_cummings","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MIRILDANDIĞIM ŞEYLERSİN', 'mirildandigim-seylersi-n-haydar-ergulen-31w1m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin Harflerin İçin
1.
Mırıldandığın her şeysin, sesinden öpüyorum
sessizliğine de eğiliyorum fakat neredesin
kapanınca harflerinin kapısı: Adın
şiirim!
Heceler gibi öpüyorum işte iki hecesin
adından başlıyorum öpmeye kırlara çıkmış
harflerinin arasından öpüyorum: Ağzın
cennetim!
Dilin hâlâ çocukluğun suyuyla terli
ve haylaz suyundan öpsem küskün
bir çeşmenin harflerin susuz. Dilin
cehennemim
2.
Mırıldan dur bana, senin üstüne harf
getirmem daha, ağız ağıza duruyor
harflerin: Sevmenin birinci hâli gibi
telaşlı duruyor da ben utanıyorum
üçü bakarken birini öpmeye senin!
3.
Harflerin aralanmış
sesliler sevişiyor
sessizlere bu cümlede
sıra gelmeyecek gibi
Harflerin yatışınca
belki duyarsın içinde
sessizlerin uykusuz
kaldığı o cümleyi
Aşkı seslendirirken
unuttuğun mırıltı
bizi sessizliğimizden
doğru bağışlar belki
4.
Bir ses sesini öpse
harflerin uykusuz kalır
5.
Dün sabah önünden geçtim
kağıt gibiydi harflerinin yüzü
araları açılmış olmalı
bütün gece sevişmekten
6.
Mırıldandığımız şeyler
kalmayınca aramızda
ağızda söz, gövdede ter,
bir aşk bunlarla biter
7.
Harflerin gülüştüğünü senin adında gördüm!', 'Senin Harflerin İçin 1. Mırıldandığın her şeysin, sesinden öpüyorum sessizliğine de eğiliyorum fakat neredesin kapanınca harflerinin kapısı:...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar_ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MIRILDANDIKLARIM', 'mirildandiklarim-murathan-mungan-nwlec', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırdın mı incittin mi birilerini
Kimleri kazandım, yitirdiklerim kimler?
Kendimi yeniledim mi yazdıklarımda?
Yeniden düşünmeliyim
Dostluklarımı, ilişkilerimi
Gözlerim çocukluk fotoğraflarında mı kaldı
Yitirdim mi yoksa masumiyetimi?
Borçlarımı ödedim mi?
Doğru seçtim mi soruların fiillerini?
Tırnaklarım kesilmiş, dişlerim fırçalanmış, saçlarım taranmış,
Giysilerim ütülü, odam düzenli mi?
Geri verdim mi aldıklarımı:
Aşkları, dostlukları, sevgileri, güvenleri, bağları,
Kitaplara, sayfalara, satırlara borcumu ödedim mi?
Yokladım mı duygularımı
Hâlâ sevebiliyor muyum insanları?
Ovmalı gümüşleri, bakırlarımı; cila geçmeli ahşaplarıma
Ovmalı umutları
Saklı tutmalı gelecek inancını, yarınları eksik etmemeli ağzımızdan
Ey uzak akrabalarım, üvey aşklarım
Mevsim sonu dostlarım, işporta malı ayrılıklar
Arkadaş ölümleri, dost hançerleri, talan ettiğimiz zulalar
Gece telefonları, ıssız konuşmalar
Mağrur incelikler, vurgun yemiş ilişkiler
Uçurum duygusuyla yaşadığımız hayat ey
O kadar çok anlattım ki
Kendime kaldım anlatmaktan...
Bunaldım kendisiyle boğuşmasını
Başkalarında çözmeye çalışan insanlardan
Usandım sözcük oynamalarından, tılsımlı sıfatlardan,
Ofset duyarlılıklardan
Kaç zamandır duru, yalın, çalışkan, iyi insanlar özlüyorum
''İçtenliğin'' ya da ''dünya görüşünün'' kirletmediği
Kendime bir yeni yıl kartı yazarak bunları diliyorum
Aranıp duruyorum adresini yitirdiğim insanları
Vitrin camlarına yansıyan yüzlerde
Bilmiyorum kalmış mıdır adresini yüzlerinde taşıyan insanlar
Hâlâ bir umut var mıdır
Çıkmaz bir sokağa benzeyen bu avare avunması vitrinlerde
Ne çıkmaz sokaktayım ne de mutsuz
Sadece rüzgârlardan daha güçlü olmak istiyorum o kadar
Açık denizlerde nice yolculuklara yelken açarken
Kış güneşinin mutlu ettiği bir kedi gibi mutlu, emin, tasasız
Sere serpe ve keyifli olmak tek isteğim ve dileğim
Senin ve benim , yani bizim için...', 'Kırdın mı incittin mi birilerini Kimleri kazandım, yitirdiklerim kimler? Kendimi yeniledim mi yazdıklarımda? Yeniden düşünmeliyim Dostluklar...', ARRAY['Türk Edebiyatı','Şiir','Murathan Mungan']::text[], 8.5, '{"poet":"Murathan Mungan","poet_slug":"murathan_mungan","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMKANSIZ AŞK', 'i-mkansiz-ask-umit-yasar-oguzcan-30w03', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Falcı kadın yalan söylüyor yalan
Bizi birbirimiz için yaratmış Tanrımız
Nasıl mümkün değilse
Yıldızları toplamak gökyüzünden
Öylesine imkansız bir şey aşkımız
Kurudu gölgesinde oturduğumuz ağaçlar
Bahçelerde sevdiğin çiçekler kalmadı
Sadece hatıralarda ebedi olan
Vazgeçemediğimiz, unutamadığımız
Onlar bile bize yar olmadı
Unut benden kalan ne varsa
Unutmak tesellidir yalnızlığın
Güneşi bir kadeh şarap gibi içip
Delicesine sarhoş olmak
En güzel tarafı imkansızlığın
Ümitlerimiz fırtınalı denizler ortasında
Bir hurda teknedir şimdi
Dalgalar dünden daha zalim
Rüzgar daha hoyrat
Ne bulut var ufuklarda ne gemi
Mevsimler toz pembe değil
Gündüzler gecedir, geceler zindan
Güneşin doğmasını beklemek boşuna
Boşuna artık medet ummak
Taş kalpli zamandan
İnan ki! Kırılmış bir ayna gibi
Paramparça, kırık dökük aşkımız
Çaresizliğin, ümitsizliğin türküsü
Türkülerin en içlisi, en hüzünlüsü
Büyük aşkımız', 'Falcı kadın yalan söylüyor yalan Bizi birbirimiz için yaratmış Tanrımız Nasıl mümkün değilse Yıldızları toplamak gökyüzünden Öylesine imkans...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit_yasar_oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MÜKEMMEL OLMAYAN İNSANLARIN SIRADAN ÇATIŞMALARI', 'mukemmel-olmayan-i-nsanlarin-siradan-catismalari-enis-akin-rvpt9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İNSANLARIN SIRADAN ÇATIŞMALARI
evet ben değersiz biriyim be şekerim
sen bunu söylerken bilmediğin kadar
suçlarımla, yalan vaadlerimle,
burun karıştırma huyumla, çorapsız ayaklarımla
ezilmesine izin verenlerden intikam almaya
bu çocuk
bir sabah erken kalkacak
hepsi hepsi
sorularının zavallılaşmasını seyretmeye bir bir
nası da sevmiyosn beni di mi?
bahane şey be, şu hayat, şu sen, şu ucu
kıvrık gülüşün ve şu sokmayı beklemek
ve madem ki
seviştik ateşle oynadık
intikam keyifli duyguymuş be şekerim
ve acemilikle birden önerdiğim
dolu bir hayat, düzenli gardroplar hayat
veya sadece soğanın cücüğü masada hayat
yanlışmış
onun yerine bir sabah aryasında
iskeleye yanaşan bir şehir hatları vapuru gibi
titreyişimi seyredişini seyretmek
yuuuuuuuuuuuuuh be
tevazu muydu kalçalarının büyümesini beklemek
bir bir
şimdi bağıracaksın
ama bağırmakla sorunlar çözülmez ki
göm yastığa başını
madem ki
kendinden umut kesilmeyecek adam olamadım
içtiğin her sigarayı bundan böyle ben çekerim,
ciğerime, be şekerim', 'İNSANLARIN SIRADAN ÇATIŞMALARI evet ben değersiz biriyim be şekerim sen bunu söylerken bilmediğin kadar suçlarımla, yalan vaadlerimle, burun...', ARRAY['Türk Edebiyatı','Şiir','Enis Akin']::text[], 8.5, '{"poet":"Enis Akin","poet_slug":"enis_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MÜLEMMA', 'mulemma-cemal-sureya-ea9a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Cemal Süreya''ya
Kaçıncı seferberliği bu şiirin
Fizan yemen Kokayin
Bu ters çizilmiş yürek
Bu götyüzü
Kediye verdim yemiyor
Kedimin adı gece
Âşık bir tosbağa sazınnan
Kahvesi kapandığı için
Uçuyor yakin bir uzaya
Habire
Maydanozu muyum ben papahanın
Neden hiçdurma dâvet ediyor beni
Türkçesinden tutuşmuş ormana
Pır ediyor sinir uçlarım
Gümlese ya
Ve nerde o
Nerde o nedircik
O hiç üzülmeyen nüzül
Utanmadan gülüyorum hâlâ
Dayamış başını sevgi duvarına
Amamonyak helânın
Yaşamaktan başka çarem yok ki
Topa tutmak için dostum Kristofu
Bütün balyemezlerimi verirdim oysa
Terbiyeli bir köfteye
Canfeda
Buluşuruz yarın sabah
Saat beşte bre timsah
Bre yeşil
Bre güneş', 'Cemal Süreya''ya Kaçıncı seferberliği bu şiirin Fizan yemen Kokayin Bu ters çizilmiş yürek Bu götyüzü Kediye verdim yemiyor Kedimin adı gece ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MÂNÂ EVİNE DALDIK', 'm-n-evi-ne-daldik-yunus-emre-jvivc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mânâ evine daldık
Vücut seyrini kıldık
İki cihan seyrini
Cümle vücutta bulduk
Yedi yer yedi göğü
Dağları denizleri
Uçmağ ile tamuyu
Cümle vücutta bulduk
Gece ile gündüzü
Gökte yedi yıldızı
Levhte yazılı sözü
Cümle vücutta bulduk
Musa ağdığı Tûr''u
Yoksa Beyt_ül Mü''mur''u
İsrafil çalan sûru
Cümle vücutta bulduk
Tevrat ile İncil''i
Furkan ile Zebur''u
Bunlardaki beyanı
Cümle vücutta bulduk
Yunus''un sözleri hak
Cümlemiz dedik sadak
Nerd''istersen orda Hak
Cümle vücutta bulduk', 'Mânâ evine daldık Vücut seyrini kıldık İki cihan seyrini Cümle vücutta bulduk Yedi yer yedi göğü Dağları denizleri Uçmağ ile tamuyu Cümle vü...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MOHAÇ TÜRKÜSÜ', 'mohac-turkusu-yahya-kemal-beyatli-d0y9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizdik o hücûmun bütün aşkıyla kanatlı;
Bizdik o sabah ilk atılan safta yüz atlı.
Uçtuk Mohaç ufkunda görünmek hevesiyle,
Canlandı o meşhûr ova at kişnemesiyle!
Fethin daha bir ülkeyi parlattığı gündü;
Biz uğruna can verdiğimiz yerde göründü.
Gül yüzlü bir âfetti ki her bûsesi lâle;
Girdik zaferin koynuna, kandık o visâle
Dünyâya vedâ ettik, atıldık dolu dizgin;
En son koşumuzdur bu! Asırlarca bilinsin!
Bir bir açılırken göğe, son def''a yarıştık;
Allâh''a giden yolda meleklerle karıştık.
Geçtik hepimiz dört nala, cennet kapısından;
Gördük ebedî cedleri, bir anda yakından!
Bir bahçedeyiz şimdi şehidlerle berâber;
Bizler gibi olmuş o yiğitlerle berâber.
Lâkin kalacak doğduğumuz toprağa bizden;
Şimşek gibi bir hâtıra nal seslerimizden.', 'Bizdik o hücûmun bütün aşkıyla kanatlı; Bizdik o sabah ilk atılan safta yüz atlı. Uçtuk Mohaç ufkunda görünmek hevesiyle, Canlandı o meşhûr ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MOLA', 'mola-adnan-azar-fsav8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'saçlarımı erken rüzgârlarla dağıttım
alnımdaki lekeler eylül ıslıklarından
yüzüm kör bir aydınlıkta nedensiz şimdi
yani nedensizim, yani yolum uzun, gün kısa
alıştım, artık çiçeklerle deniyorum kendimi
son kimliğim de aşınmıştı geceye karışmaktan
gülüşümün adını bulamayacaklar, biliyorum
çocukluğum yaşlanmayacak uğultularda
eskiyen günlerde bir ilenç var, bunu da biliyorum
resimler yırtılırdı bakışlarımdan, yine de üşümezdim
yine de uzanırdım sabahın buğusuna
unuturdum göğsümü delen ışıkları
seni artık yaz sularında aramıyorum
burda geceler yoksul, çocuklar suskun
ve binlerce söz ölüsü ellerimde
ben de susuyorum, sustum artık
sustum ve yüzüm kanamıyor hiç bir güle', 'saçlarımı erken rüzgârlarla dağıttım alnımdaki lekeler eylül ıslıklarından yüzüm kör bir aydınlıkta nedensiz şimdi yani nedensizim, yani yol...', ARRAY['Türk Edebiyatı','Şiir','Adnan Azar']::text[], 8.5, '{"poet":"Adnan Azar","poet_slug":"adnan_azar","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MONA ROSA', 'mona-rosa-sezai-karakoc-xjww6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mona Rosa. Siyah güller, ak güller.
Geyve''nin gülleri ve beyaz yatak.
Kanadı kırık kuş merhamet ister.
Ah senin yüzünden kana batacak.
Mona Rosa. Siyah güller, ak güller.
Ulur aya karşı kirli çakallar,
Ürkek ürkek bakar tavşanlar dağa.
Mona Rosa bugün bende bir hal var.
Yağmur iri iri düşer toprağa,
Ulur aya karşı kirli çakallar.
Açma pencereni perdeleri çek,
Mona Rosa seni görmemeliyim.
Bir bakışın ölmem için yetecek.
Anla Mona Rosa ben bir deliyim.
Açma pencereni perdeleri çek.
Zeytin ağaçları, söğüt gölgesi,
Bende çıkar güneş aydınlığına.
Bir nişan yüzüğü bir kapı sesi.
Seni hatırlatır her zaman bana.
Zeytin ağaçları, söğüt gölgesi.
Zambaklar en ıssız yerlerde açar
Ve vardır her vahşi çiçekte gurur.
Bir mumun ardında bekleyen rüzgar,
Işıksız ruhumu sallar da durur.
Zambaklar en ıssız yerlerde açar.
Ellerin, ellerin ve parmakların
Bir nar çiçeğini eziyor gibi.
Ellerinden belli olur bir kadın,
Denizin dibinde geziyor gibi.
Ellerin, ellerin ve parmakların.
Zaman ne de çabuk geçiyor Mona.
Saat onikidir söndü lambalar
Uyu da turnalar girsin rüyana,
Bakma tuhaf tuhaf göğe bu kadar.
Zaman ne de çabuk geçiyor Mona.
Akşamları gelir incir kuşları,
Konarlar bahçemin incirlerine.
Kiminin rengi ak kiminin sarı.
Ah beni vursalar bir kuş yerine.
Akşamları gelir incir kuşları.
Ki ben Mona Rosa bulurum seni
İncir kuşlarının bakışlarında.
Hayatla doldurur bu boş yelkeni.
O masum bakışların su kenarında.
Ki ben Mona Rosa bulurum seni.
Kırgın kırgın bakma yüzüme Rosa.
Henüz dinlemedin benden türküler.
Benim aşkım uymaz öyle her saza.
En güzel şarkıyı bir kurşun söyler.
Kırgın kırgın bakma yüzüme Rosa.
Artık inan bana muhacir kızı,
Dinle ve kabul et itirafımı.
Bir soğuk, bir mavi, bir garip sızı
Alev alev sardı her tarafımı.
Artık inan bana muhacir kızı.
Yağmurdan sonra büyürmüş başak,
Meyvalar sabırla olgunlaşırmış.
Bir gün gözlerimin ta içine bak
Anlarsın ölüler niçin yaşarmış.
Yağmurdan sonra büyürmüş başak.
Altın bilezikler o kokulu ten
Cevap versin bu kuş tüyüne.
Bir tüy ki can verir gülümsesen,
Bir tüy ki kapalı geceye güne.
Altın bilezikler o kokulu ten.
Mona Rosa. Siyah güller, ak güller.
Geyve''nin gülleri ve beyaz yatak.
Kanadı kırık kuş merhamet ister,
Ah senin yüzünden kana batacak.
Mona Rosa. Siyah güller, ak güller.', 'Mona Rosa. Siyah güller, ak güller. Geyve''nin gülleri ve beyaz yatak. Kanadı kırık kuş merhamet ister. Ah senin yüzünden kana batacak. Mona ...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":72}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MONNA ROSA', 'monna-rosa-sezai-karakoc-ecjpu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I- AŞK VE ÇİLELER
Monna Rosa, siyah güller, ak güller;
Gülce''nin gülleri ve beyaz yatak.
Kanadı kırık kuş merhamet ister;
Ah, senin yüzünden kana batacak,
Monna Rosa, siyah güller, ak güller!
*
Ulur aya karşı kirli çakallar,
Bakar ürkek ürkek tavşanlar dağa.
Monna Rosa, bugün bende bir hal var,
Yağmur iğri iğri düşer toprağa,
Ulur aya karşı kirli çakallar.
Zeytin ağacının karanlığıdır
Elindeki elma ile başlayan...
Bir yakut yüzükte aydınlanan sır,
Sıcak ve minnacık yüzündeki kan,
Zeytin ağacının karanlığıdır.
Zambaklar en ıssız yerlerde açar,
Ve vardır her vahşi çiçekte gurur.
Bir mumun ardında bekleyen rüzgâr,
Işıksız ruhumu sallar da durur,
Zambaklar en ıssız yerlerde açar.
Ellerin, ellerin ve parmakların
Bir nar çiçeğini eziyor gibi...
Ellerinden belli olur bir kadın.
Denizin dibinde geziyor gibi
Ellerin, ellerin ve parmakların.
Açma pencereni perdeleri çek:
Monna Rosa, seni görmemeliyim.
Bir bakışın ölmem için yetecek;
Anla Monna Rosa, ben öteliyim...
Açma pencereni, perdeleri çek.
Zaman çabuk çabuk geçiyor Monna;
Saat on ikidir söndü lâmbalar.
Uyu da turnalar gelsin rüyana,
Bakma tuhaf tuhaf göğe bu kadar;
Zaman çabuk çabuk geçiyor Monna.
Akşamları gelir incir kuşları,
Konarlar bahçemin incirlerine;
Kiminin rengi ak, kiminin sarı.
Ah, beni vursalar bir kuş yerine!
Akşamları gelir incir kuşları...
Ki ben, Monna Rosa, bulurum seni
İncir kuşlarının bakışlarında.
Hayatla doldurur bu boş yelkeni
O mâsum bakışlar...Su kenarında
Ki ben, Monna Rosa, bulurum seni.
Kırgın kırgın bakma yüzüme Rosa:
Henüz dinlemedin benden türküler.
Benim aşkım uymaz öyle her saza,
En güzel şarkıyı bir kurşun söyler...
Kırgın kırgın bakma yüzüme Rosa.
Yağmurlardan sonra büyürmüş başak,
Meyvalar sabırla olgunlaşırmış.
Bir gün gözlerimin ta içine bak:
Anlarsın ölüler niçin yaşarmış,
Yağmurlardan sonra büyürmüş başak.
Artık inan bana muhacir kızı,
Dinle ve kabul et itirafımı.
Bir soğuk, bir garip, bir mavi sızı
Alev alev sardı her tarafımı,
Artık inan bana muhacir kızı.
Altın bilezikler, o korkulu ten,
Cevap versin bu kanlı kuş tüyüne;
Bir tüy ki, can verir bir gülümsesen,
Bir tüy ki, kapalı geceye, güne;
Altın bilezikler, o korkulu ten!
*
Monna Rosa, siyah güller, ak güller,
Gülce''nin gülleri ve beyaz yatak.
Kanadı kırık kuş merhamet ister;
Ah, senin yüzünden kana batacak,
Monna Rosa, siyah güller, ak güller!
(1952, Bahar)
II- ÖLÜM VE ÇERÇEVELER
Bir lâmba yanıyor, hafif ve sarı;
Garip bir yolculuk, tren ve Gülce.
Bir hançer bölüyor, ah, rüyaları:
Bir rüya, bir hançer, bir el; ve, ve, ve...
*
Lâmbalar yanıyor, hafif ve sarı;
Gece kar yağacak sabaha kadar.
Toprakta et, kemik çıtırtıları...
Yarı ölüleri bir korku tutar
Değince bir taşa kafatasları.
-Ölüler ki yalnız tırnakları var,
Ve yalnız burkulmuş diz kapakları...-
*
Bir lâmba yanıyor, hafif ve sarı,
Açıyor elini göğe bir kadın.
Uzuyor, uzuyor altın saçları
Uğrunda ölünen güzel kızların...
*
Bir lâmba yanıyor, hafif ve sarı;
Esmer delikanlı, hatıra ve kan.
Yeşil gözlü kızın hıçkırıkları
Sızıyor bir kapı aralığından;
Lâmbalar yanıyor, hafif ve sarı.
*
Lâmbalar yanıyor, hafif ve sarı;
Çocuklara açar mağaraları
Gün görmemiş kuşlar ve örümcekler.
İlân-ı aşk eden dil balıkları
Aşina suları çabuk terkeder...
Lâmbalar yanıyor, hafif ve sarı;
Bakıyor ateşe, küle böcekler.
Köpekler parçalar kanaryaları,
Mektupları bir boz ağaç kurdu yer.
Baykuşlar ötüyor harabelerde;
Yanıyor lâmbalar, hafif ve sarı.
Bir kaza kurşunu bulur her yerde
Süvarisiz şaha kalkan atları...
Bir ruhun ışığı vardır göklerde,
Lâmbalar yanıyor, hafif ve sarı;
Ötüyor baykuşlar harabelerde.
*
Bir lâmba yanıyor, hafif ve sarı;
Titriyor yıldırım düşmüş gibi yer.
Bekledi arzuyla karanlıkları
Anneler, babalar, erkek kardeşler.
Ta içinde duyar ani bir ağrı,
Bir hüzün şarkısı tutturur gider
Anneler, babalar, erkek kardeşler.
Lâmbalar yanıyor, hafif ve sarı;
Her yatak dopdolu, bir yatak bomboş.
Bir neşe şarkısı tutturur gider
Birinci, ikinci, üçüncü sarhoş;
Kurşunlar sıkılır göklere doğru,
Serçe yavruları yuvada titrer.
Lâmbalar yanıyor, hafif ve sarı...
*
Bir lâmba yanıyor, hafif ve sarı;
İnce yelkenleri alıyor yeller.
Titretir kalpleri ve bayrakları
Gemiden toprağa uzanan eller.
Lâmbalar yanıyor, hafif ve sarı,
Bir yosun köküne hasret kalacak
Gizli hazineler, su yılanları....
*
İnce yelkenleri alıyor yeller;
Bir lâmba yanıyor, hafif ve sarı.
Beyaz pelerinli hür tayfaları
Kendine bağlıyor siyah kediler;
Titriyor gönüller ve kara bayrak,
Bir yosun köküne hasret kalacak
Gemiden toprağa uzanan eller.
Bir lâmba yanıyor, hafif ve sarı.
*
Bir lâmba yanıyor, hafif ve sarı,
Garip bir yolculuk, tren ve Gülce.
Bölüyor bir hançer, ah, rüyaları:
Bir rüya, bir hançer, bir el; ve, ve, ve...
(1952,Yaz)
III- PİŞMANLIK VE ÇİLELER
Rüzgâr eser, yağmur yağar, tilkiler üşür;
Bir odun parçası aydınlatır ocağı.
Anne ateşin önünde perişan,
Anne ateşin içinde hür...
Rüzgâr eser, yağmur yağar, tilkiler üşür.
Yağmurlar sırtıyla sırtımın arasındadır;
Şarkılar dudaklarıyla dudaklarımın.
Bin parçaya böldü beni bir divane sır,
Sesi geliyor sesi günahkâr çocukların;
Şarkılar dudaklarıyla dudaklarımın arasındadır.
Gönüller yanarak kavuşacaktı;
Yüzdeki ıstırap, çile ocağı,
Onun bu ocakta yanan toprağı,
Bir gece rüyamda avuçlarımı yaktı;
Gönüller yanarak kavuşacaktı.
Benim gözlerim yeşildir, onun gözleri kara;
Ben günah kadar beyazım, o tövbe kadar kara.
*
Annenin başı elleri arasında,
Parmağında aydınlık günlerden kalma yüzük.
Bir fotoğraf asılıdır duvarda:
Aynaya, geceye, maziye dönük;
Annenin başı elleri arasında,
Bir tüfeğin burnu havadadır,
Ateş almak üzredir, mermisiz.
Ben bir küçük kızım, ben bir deli kızım,
Siz beni ne anlarsınız siz!
Bir tüfek ateş almak üzredir, mermisiz...
Bir saman çöpüne tutunmuş kızların
Eteğini ben çektim.
Neyleyim göğsümü kara dağın sert rüzgârı doldurmuş,
Annemden ilk sütü Gülce''de içtim.
Ankara''ya, çatal kara bir zindandan gün vurmuş:
Az kalsın yerine ben ölecektim
Bir saman çöpüne tutunmuş kızların...
Kediler halıları parçalıyor,
Kırmızı bir ışık düşüyor yere.
Annenin dizinde derman yok,
Annenin kafası iki parçadır.
Hükmedemiyor insan ruhuna ateş,
Rüzgâr hükmedemiyor incecik perdelere;
Kediler halıları parçalıyor.
Ateşte sarı gül açan saksılar,
Kızarmış bir ekmek gibi duruyor;
Kulağıma garip sesler geliyor.
Kuş yumurtasından çıkan insanlar
Ahırda bir ata eğer vuruyor,
Kulağıma garip sesler geliyor.
Ben bir şarkı, ben bir tüyüm;
Ben Meryem''in yanağındaki tüyüm.
Beni bir azizin nefesi uçurur,
Kalbimde Allah''ın elleri durur.
Cici ayaklarım iplikle bağlı,
Ben onun sılası, kendimin gurbetiyim;
Ben bir azizin hasreti,
Ben Meryem''in yanağındaki tüyüm.
Benim gözlerim yeşildir, evet evet, onun gözleri kara;
Ben günah kadar beyazım, o tövbe kadar kara...
*
Ocak sönüyor, ateş kül oluyor.
Annenin saçları beyaz,
Anne saçlarını yoluyor.
Ateşin içinde gül açar, servi büyür, ardıç büyür, çocuk büyür;
Ocak sönüyor, ateş kül oluyor,
Anne ruhunda ruhuma eğiliyor.
Yaralı kuş kanadını ısıtan
Bir güneş toprağı yarıp çıkacak.
Kadınlar sansa da yaşadığını,
Şarkısız kaldıkça yaşamayacak.
Kadınları şarkılar, geceler aydınlatır.
Kadınları şarkılar, akrepler aydınlatır.
Kadınları şarkılar, zehirler aydınlatır...
*
Artık ben gideceğim, ata eğer vuruyorlar.
Hatırlarımı birer birer yakacağım.
Entarimi parça parça edip
Zehirli kirpilere bırakacağım.
Beyaz bir kayanın üstüne çıkıp
Göğsüme siyah bir gül takacağım.
Batan güne doğru kurşunlar sıkıp
Kendimi boşluğa bırakacağım.
Ayaklarımın altından geçiyor bir deniz...
Ben bir küçük kızım, ben bir deli kızım,
Siz beni ne anlarsınız siz!
Artık ben gideceğim atım kişniyor;
Bir bebek mum istiyor, bir ölü şarkı istiyor,
Ayaklarımın altından geçiyor bir deniz, bir deniz;
Beni onun gözleri çağırıyor, duramam duramam.
Benim gözlerim yeşildir, ah, onun gözleri kara;
Ben günah kadar beyazım, o tövbe kadar kara...
(1952, Güz)', 'I- AŞK VE ÇİLELER Monna Rosa, siyah güller, ak güller; Gülce''nin gülleri ve beyaz yatak. Kanadı kırık kuş merhamet ister; Ah, senin yüzünden...', ARRAY['Türk Edebiyatı','Şiir','Sezai  Karakoç']::text[], 8.5, '{"poet":"Sezai  Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":247}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MOR HÜZÜN', 'mor-huzun-timucin-ozyurekli-hefp2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şafaklar kirli, göl suları bulanık
çıkık yanakların ne zamandır çöl
parmakların dikenli tellerde kanar
alıp başını gider bakire kalbim
"-servise geç kalacağım..."
yasak kitaplar yaprak aralarında
sümbül kokulu mektuplar gizler
savrulan hayat, anla beni, sorgula
yorgun gözlerine baksam sağanak
"-daha yeni iş buldum,
biliyorsun..."
kırılgan bir ses, bir çığlık
ter sızdıran dağınık yatak
günlere gecelere kilit gövden
dudaklar hazır aykırı maceraya
"-kartı zamanında basamazsam,
mahvolurum..."
üzerine koştukça uzaklaşan hayal
bürümcük ipeklerde kuş figanı
penceremden görünen gülün dalı
yıkılan kale kaybedilen direniş
"-kimbilir belki akşama..."
güzel değerler adına yolculuk
avcumdan kayıp günlere karışan
ah, hiç büyümeyen sevgilim hayat
olduğun yerde kal, ben giderim', 'şafaklar kirli, göl suları bulanık çıkık yanakların ne zamandır çöl parmakların dikenli tellerde kanar alıp başını gider bakire kalbim "-ser...', ARRAY['Türk Edebiyatı','Şiir','Timuçin Özyürekli̇']::text[], 8.5, '{"poet":"Timuçin Özyürekli̇","poet_slug":"timucin_ozyurekli","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MOR KÜLHANİ', 'mor-kulhani-ece-ayhan-1i4zr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.Şiirimiz karadır abiler
Kendi kendine çalan bir davul zurna
Sesini duyunca kendi kendine güreşmeye başlayan
Taşınır mal helalarında kara kamunun
Şeye dar pantolonlu kostak delikanlıların şiiridir
Aşk örgütlenmektir bir düşünün abiler
2.Şiirimiz her işi yapar abiler
Valde Atik''te Eski Şair Çıkmazı''nda oturur
Saçları bir sözle örülür bir sözle çözülür
Kötü caddeye düşmüş bir tazenin yakın mezarlıkta
Saatlerini çıkarmış yedi dala gerilmesinin şiiridir
Dirim kısa ölüm uzundur cehennette herhal abiler
3.Şiirimiz gül kurutur abiler
Dönüşmeye başlamış Beşiktaşlı kuşçu bir babanın
Taşınmaz kum taşır mavnalarla Karabiga''ya kaçan
Gamze şeyli pek hoş benli son oğlunu
Suriye hamamında sabuna boğmasının şiiridir
Oğullar oğulluktan sessizce çekilmesini bilmelidir abiler
4.Şiirimiz erkek emzirir abiler
İlerde kim bilir göz okullarına gitmek ister
Yanık karamelalar satar aşağısı kesik kör bir çocuğun
Kinleri henüz tüfek biçimini bulamamış olmakla
Tabanlarına tükürerek atış yapmasının şiiridir
Böylesi haftalık resimler görür ve bacaklanır abiler
5.Şiirimiz mor külhanidir abiler
Topağacından aparthanlarda odası bulunamaz
Yarısı silinmiş bir ejderhanın düzüşüm üzre eylemde
Kiralık bir kentin giriş kapılarına kara kireçle
Şairlerin ümüğüne çökerken işaretlenmesinin şiiridir.
Ayıptır söylemesi vakitsiz Üsküdarlıyız abiler
6.Şiirimiz kentten içeridir abiler
Takvimler değiştirilirken bir gün yitirilir
Bir kent ölümünün denizine kayar dragomanlarıyla
Düzayak çivit badanalı bir kent nasıl kurulur abiler?', '1.Şiirimiz karadır abiler Kendi kendine çalan bir davul zurna Sesini duyunca kendi kendine güreşmeye başlayan Taşınır mal helalarında kara k...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMÜR HANIMLA GÜZ KONUŞMALARI', 'omur-hanimla-guz-konusmalari-sukru-erbas-7dfz9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...Ve güz geldi Ömür hanım. Dünya aydınlık sabahlarını
yitiriyor usul usul. İnsanın içini karartan bulutların seferi var
göğün maviliğinde. Yağmur ha yağdı ha yağacak. İn-
cecik bir çisenti yokluyor boşluğunu insan yüreğinin.
Hüznün bütün koşulları hazır. Nedenini bilmediğim bir
keder akıyor damarlarımdan. Kalbimin üstünde binlerce
bıçak ağzı... ve yüzüm ömrümün atlası; düzlükleri bunaltı,
yükseklikleri korku, uçurumları yıkıntılarımla dolu bir
engebeler atlası. Yaşamak bir can sıkıntısı mıdır Ömür
hanım?
Her şeyi iyi yanından görmeyi kim öğretti bize? Acıyı
görmeyen insan, umutsuzluğu yaşamayan, iliklerine dek
kederin işleyip yaralamadığı bir insan, mutluluktan,
umuttan, sevinçten ne anlar? Göğü görmeden, denizi gör-
meden maviyi anlamaya benzemez mi bu? Bir güz dü-
şünün ki Ömür hanım, ilkyazı olmamış, yazı yaşanmamış,
böyle bir güzün hüznü hüzün müdür? Başlamanın bir
anlamı varsa bitişi göze almak, bitişin bir anlamı varsa
başlangıcı olmak değil midir? Yaşamı düz bir çizgide tut-
mak tükenmektir. Yaşamak zorunda olduğumuz şunca yılı
aykırı uçlar arasında gezdirip geçirmedikçe, alışkanlıkların
sınırlarını aşmadıkça zaman zaman, yaşamak nasıl yenilik
olur tükenmek değil de?
Yağmur yağıyor Ömür hanım...gökten değil, yüreğimin
boşluğundan ömrümün ıssız toprağına...Ve ben sonsuz
bir düzlükte bir küçücük, bir silik nokta gibi eriyip gi-
diyorum. Seslensem kim duyar sesimi yalnızlıklar ka-
tından?
Dönelim...Dönmek yenilmektir biraz da, yarım kalmasıdır
çıkışlarımızın, korkaklıktır, alışkanlıkların güvenli küflü
kabuklarına sığınmaktır...Olsun dönelim biz yine de. Bi-
lincinde olmadan üstlendiğimiz sorumluluklarımız var.
Evlere dönelim, sırtımızın kamburu evlere, cılızlığımızın
görkemli korunaklarına, yalnızlığımızın kalelerine dö-
nelim. Ölçüsüz yaşamak bize göre değil Ömür hanım.
Büyürken geniş ufuklarımız olmadı bizim. Küçücük
avuçlarımızla sınırlarımızı genişletmek istedikçe yaşamın
binlerce engeli yığıldı önümüze. Hangi birini yenebilirdik
bunca olanaksızlık içinde. Umutsuzluğu tanıdık, yenilgiyi
öğrendik böylece.
Yaşama sevinci adına bir tutamağım kalmadı Ömür hanım.
Bir garip boşlukta çiviliyim günlerdir gözbebeklerimden.
Sahi nedir yaşamın anlamı? Geriye dönüyorum sık sık
yanıt aramak adına, yüreğimin silik izler bırakıp, ağır
yükler aldığı zamanın derin denizlerine. Bakıyorum umut
karamsarlığın, sevinç acının azıcık soluk almasından başka
ne ki? Yaşamsa gerçekle düşün umutsuz bir savaşı, her şeyi
içine alan kocaman bir yanılsama... Değil mi yoksa?
Öyle büyük umutlarım olmadı benim, büyük düşlerim,
özlemlerim, büyük beklentilerim olmadı. Koşullarım beni
oluşturdu ben acılarımı buldum. Herkes gibi yaşasaydım
eğer, yaşamı onlar gibi görebilseydim çarşılar yeterdi
avutmaya beni. Bir gömlek, bir ayakkabı, bir elbise; bir
yemek lokantalarda; televizyon, halı, masa ve daha nice
eşya yeterdi yalnızlığı örtmeye, kendimi göstermeye, va-
rolmaya, ''dar çevre yitikleri''nde önem kazanmaya...
Oysa ben bir akşamüstü oturup turuncu bir yangının
eteklerine, yüreği avuçlarımda atan bir can yoldaşıyla
dünyayı ve kendimi tüketmek isterdim. Öyle bir tüketmek
ki, sonucu yepyeni bir "ben"e ulaştırırdı beni, kederli dal-
gınlığımdan her döndüğümde...Bir ben ki tüm ilişkilerin
perde arkasını görür de gülerdim sessizce yapay ya-
kınlıklarına insanların. Kim kimi ne kadar anlayabilir
Ömür hanım?
Susmak yalnızlığın ana dilidir, Ömür hanım, şiiridir, beni
konuşmaya zorlama ne olur. Sözün sularını tükettim ben,
kaynağını kuruttum. Geriye bir büyük sessizlik kaldı yü-
reğimde, kalabalıklar, kalabalıklar kadar büyük...Yalnızım
Ömür hanım, geceler boyu akıp giden ırmaklar gibi ka-
ranlıklar içre, öyle yitik, öyle üzgün, yalnızım...Sularım
toprağa sızıyor bak. Yüzümü geceler örtüyor. Binlerce taş
saklanıyor içimde. Kim kimin derinliğini görebilir, hem
hangi gözle?
Kendilerinin olan tek sözcük yok dillerinde, öyle çok ko-
nuşuyorlar ki...Bir söz insanın neresinden doğar dersiniz?
Dilinden mi, yüreğinden mi, aklından mı? Düşlerinden
mi yoksa gerçeğinden mi? Ve kaç kapıdan geçip yerini
bulur bir başka insanda? Yerini bulur mu gerçekten? Sözü
yasaklamalı Ömür hanım yasaklamalı...Kimsenin kimseyi
anlamadığı bir dünyada söz boşluğu dövmekten başka ne
işe yarıyor ki? Olanağı olsa da insanların yürekleri ko-
nuşabilseydi dilleri yerine, her şey daha yalansız, daha içten
olurdu. Aklı silmeli diyorum insan ilişkilerinden. Yanılıyor
muyum? Olsun. Yanıldığımı biliyorum ya...
Yeni bir şeyler söyle bana ne olur, yeni bir şeyler. Kurşun
aktı kulaklarıma hep aynı sözleri, aynı sesleri duymaktan.
Belirsizlik güzeldir, de örneğin, kesinlik çirkin. Sessizlik
sesten -hele de güncel ve kof-  her zaman iyidir; düş gücü,
iç zenginliği verir insana. Dünyanın usul usul ağaran o
puslu sabahları ve günün turuncu tülleriyle örtünen dingin
akşamları bu yüzden etkiler bizi, duygulandırır, de. Anlık
izlenimler sürekli görünümlerden her zaman daha güçlü,
kalıcı ömürlüdür...Alışkanlıklar öldürür güzelliğimizi,
bizi değişmek çirkinleştirir de.
Kimse düşlerine yetişemez ve kimse geçemez gerçeğini bir
adım bile; bu yüzden sıkıntı verir zaman, kısa kalır, sonsuz
olur, insanın küçücük ömrünün karşısında. İstemenin kuralı
yoktur, de, açıklaması sınırı suçu yoktur; istemek ya-
şamın kendiliğinden sonucudur, ne haklı ne haksız,
ne yerinde ne yersiz...
Biz hepimiz dikenli tellerle sarılıyız, her ilişkide bir par-
çamız kalır ve bölüne bölüne biteriz de. En büyük hü-
nerimiz kendimize karşı olmak, aykırı yaşamaktır, acı
kaynaklarımızı ellerimizle yaratarak...Kıyılarımız duy-
gularımızın boyunda, derinliğimiz aklımızın ölçüsündedir;
ufuklarımızsa sisler içinde...O kıyısız gökyüzü nasıl sığar
küçücük gözlerimize, bir bardak suya, demirli bir pen-
cereye...Nasıl gizleriz ağız dil vermez bir geceye? Ve nedir
ki gizi, daraldığımız her yerde bir genişlik duygusu verir
içimize. Çözemeyiz, de, bu güdük bilinç, bu sığ yürek,
bu ezbere yaşamla.
Dünya bir testidir, de, Ömür hanım, ömür bir su...Sızar
iğneucu gözeneklerinden zamanın, bir içim serinlik bir
yudum mutluluk için. Ve bir gün ölümün balkonundan...
dökülür toprağa el içi kadar bir su. Yerde birkaç damla
nem, bir avuç ıslaklık...Ölümü bilerek nasıl yaşar insan,
geride dünyanın kalacağını bilerek nasıl ölür; bilmek bütün
acıların anasıdır, de...
Sars aklımın cılız ayaklarını, kuşat beni. Değişik şeyler
söyle ne olur, yeni bir şeyler söyle. Yıldım ömrümün ka-
lıplarından. Beni duy ve anla.
Yağmur dindi Ömür hanım. Gökyüzü masmavi gülümsedi
yine. Doğa aynı oyununu oynuyor bizimle. Umudun
ucunu gösteriyor usulca, iyimserliğin ışığını süzüyor mavi
atlasından. Ne aldanış! Bulutların rengi mavi-beyaz mıdır,
kurşuni-külrengi mi yoksa?
Gökyüzünü öpmek isterdim Ömür hanım, gözlerimle değil
dudaklarımla. Yoruldum bulutları kirpiklerimde taşı-
maktan. Delilik mi dedin? Kim bilir...Belki de yerde sü-
rünmenin bir tepkisidir bu, ya da ne bileyim bilinçsiz bir
aykırı olmak duygusu. Gökyüzü de olmak isteyebilirdim
değil mi? Kim ne diyebilir ki?
Kimseler görmedi Ömür hanım, bu dünyadan ben geçtim.
İçimde umudun kırk kilitli sandıkları, elimde bir avuç düş
ölüsü yüreğim -içinde senin ve benim ağırlığım- benim
olmayan bir garip gülümsemeyle yüzümde, incelik adına,
ben geçtim...Yerini bulmamış bir içtenlik, yanılmış bir
saygı ve bir hüzün eğrisi olarak ilişkilerin gergefinde,
ördüm ömrümün dokusunu ilmek ilmek. Beni cam kı-
rıklarıyla anımsasın insanlar, savrulan bir yaprak hüznü
ve dağınıklığı ile... Yükümü yanlış bedestanlara çözdüm.
Ezilmiş bir gül hüznü var yüreğimde. Saatlerce dayak
yemiş bir sanığın çözülmesi içindeyim. Ürperiyorum. Bir
at kestanesi durmadan yaprak döküyor yalnızlığın so-
kaklarında, örtüyor ömrümün ilk yazını. İçimde bir çocuk,
yalın ayak koşuyor yaşlılığa doğru, binlerce kez yenilmiş
umut ölülerini çiğneyerek. Sahi yaşlılık, derin bir iç çekiş,
yanılmış bir çocukluk olmasın Ömür hanım?
Ankara, Güz/1983', '...Ve güz geldi Ömür hanım. Dünya aydınlık sabahlarını yitiriyor usul usul. İnsanın içini karartan bulutların seferi var göğün maviliğinde. ...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru_erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":151}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMÜR TÖRPÜSÜ', 'omur-torpusu-metin-eloglu-iwf24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak istiyorum
Yaşamak istiyorsun
Yaşamak istiyor
Böyle şiir olmaz, diyeceksin; biliyorum.
Ama böyle dünya olur mu?
Böyle barış olur mu?
Böyle hürriyet olur mu?
Böyle kardeşlik olur mu?
Biliyorum ki, katlanıver, diyeceksin;
Ama böyle yaşamak olur mu!', 'Yaşamak istiyorum Yaşamak istiyorsun Yaşamak istiyor Böyle şiir olmaz, diyeceksin; biliyorum. Ama böyle dünya olur mu? Böyle barış olur mu? ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin_eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMÜR', 'omur-enis-behic-koryurek-j8fks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şen günler, bir kırlangıç
Gibi vuruyor kanat.
Kederli günler, sanki
Kurulmamış bir saat.
Birinde, rüya tadı
Biri, kan içen cadı
İkisinin de adı:
Ömürden bir gün...Heyhat!', 'Şen günler, bir kırlangıç Gibi vuruyor kanat. Kederli günler, sanki Kurulmamış bir saat. Birinde, rüya tadı Biri, kan içen cadı İkisinin de ...', ARRAY['Türk Edebiyatı','Şiir','Enis Behiç Koryürek']::text[], 8.5, '{"poet":"Enis Behiç Koryürek","poet_slug":"enis_behic_koryurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİRAS', 'mi-ras-erdogan-alkan-4fqgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşılıksız sevdalardan usandım
Artık unutacağım bankadaki kızı
Beni seven birisini bulacağım,
Varsın cüce boylu olsun;
Çipil gözlü, yumuk gözlü,
Varsın saz benizli olsun.
Paşa gönlüm dileyince
Kolları boynuma dolansın yeter.
Alacağım ellerini ellerime
Parmak uçlarını sevdiğim çitlenbiğim
Çipil yüzlü, çirkin yarim.
Cüce boylum, iki gözüm gel diyeceğim.
Ona sevdalardan yana, mutluluktan yana
Oynak türküler söyleyeceğim
Sonra gerdeğe gireceğim çirkin yarimle.
Eğer yine unutamazsam bankadaki kızı
Kafayı çekip de bir akşam
Kapısına gideceğim,
Gel işte gör diye, gözünün önünde
Üç kurşun sıkıp bu kara sevdayı öldüreceğim.
Biliyorum bankadaki kız
Beni sevmediğine pişman olacak.
Kalbinde ince bir sızı
Dudaklarında mısralarım
Ulu bir sevdadan miras kalacak.', 'Karşılıksız sevdalardan usandım Artık unutacağım bankadaki kızı Beni seven birisini bulacağım, Varsın cüce boylu olsun; Çipil gözlü, yumuk g...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Alkan']::text[], 8.5, '{"poet":"Erdoğan Alkan","poet_slug":"erdogan_alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİREBEAU KÖPRÜSÜNDEN GEÇERKEN', 'mi-rebeau-koprusunden-gecerken-metin-demi-rtas-1gj4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mirebeau Köprüsünden geçtim
Anarak Apollinaire''i
Yukarıda kirli bir gökyüzü
Aşağıda algın, alımlı Seine akıyordu
Bir dal kasımpatı bıraktım
Paul Celan''ın kendini attığı yere
Kınayamadım
Neye yarar kınasam da
Kaç şair gidip durdu
O uçurumun kıyısında
Bir acı aşılamamıştır
Bir sorun çıkmazda
Ve bir hasret
Kanatır ince bir yüreği
Yalanla da yaşanılmaz bu dünyada
Sarışın bir imge
Aralar anıları
Solgun bir anne yüzü
Erir mum gibi
Faşizmin zindanlarında
&quot;Akçakavak yaprağında ak-pak bakarsın karanlığa
Ak düşmemişti hiç annemin saçlarına&quot;
Acı dinmez
Hasret eksilmez
Susar da türkülü bir yürek
Seine''in serin sularında
Paris bunu bilmez.', 'Mirebeau Köprüsünden geçtim Anarak Apollinaire''i Yukarıda kirli bir gökyüzü Aşağıda algın, alımlı Seine akıyordu Bir dal kasımpatı bıraktım ...', ARRAY['Türk Edebiyatı','Şiir','Metin Demi̇rtaş']::text[], 8.5, '{"poet":"Metin Demi̇rtaş","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMRÜM, BANA BAĞIŞLA BU ŞİİRİ', 'omrum-bana-bagisla-bu-si-i-ri-i-smail-uyaroglu-qufue', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyük bir şiir yazmak istiyorum
Patlayan bir fırtınanın ardından
Kayalardan fışkıran hayat
Gibi büyülü ve vahşi
Ömrüm, bana bağışla bu şiiri
Kumsalı döven denizlerden
Nasıl beyaz ve ince
Köpükler doğarsa, öyle
Beyaz ve vahşi
Vahşi ve ince
Ömrüm, bana bağışla bu şiiri
Bileğimden hışımla doğan
Kelimelerin güneşi
Aydınlatmalı birden yangın hızında
Hayatın gölgeli, kuytu yerlerini
Ömrüm, bana bağışla bu şiiri
Ağlayan bir bebeğin sesi
Buluşmalı vurulan bir gencin haykırışıyla
Ve bir damla kan sıçramalı
Bu buluşmada bebeğin alnına
Sıçramalı ki...
Ömrüm, bana bağışla bu şiiri
Akan bir ırmak sessizce
Girince o şiire
Akan bir ırmak olmalı gene
Ama bir farkla
Kabarıp coşarak ve
Sürükleyerek birlikte kayaları bile
Ömrüm, bana bağışla bu şiiri
Bir kelebek
Küçük bir kelebek
Kanatları koparılmış, ölüm renginde
Uçabilir mi eski inceliğiyle
Uçabilmeli o şiirde
Kırlarda değil, ateşin üstünde hem de
Ömrüm, bana bağışla bu şiiri
Büyük bir şiir yazmak istiyorum
Ağlayan bebek, vurulan genç kadar sahici
Kelebek ve ölüm kadar güzel ve korkunç
Hayat kadar, hayat kadar
Büyülü, ince ve vahşi
Ömrüm, bana bağışla bu şiiri', 'Büyük bir şiir yazmak istiyorum Patlayan bir fırtınanın ardından Kayalardan fışkıran hayat Gibi büyülü ve vahşi Ömrüm, bana bağışla bu şiiri...', ARRAY['Türk Edebiyatı','Şiir','İsmail  Uyaroğlu']::text[], 8.5, '{"poet":"İsmail  Uyaroğlu","poet_slug":"ismail_uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMRÜM', 'omrum-mahzun-dogan-1j3jo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tıka basa dolu sayfaları
Harfleri eğri büğrü
İmlası bozuk
Taşrada basılmış bir kitap
Ömrüm ah!..
Okuduğum en uzun yalnızlık', 'Tıka basa dolu sayfaları Harfleri eğri büğrü İmlası bozuk Taşrada basılmış bir kitap Ömrüm ah!.. Okuduğum en uzun yalnızlık...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğan']::text[], 8.5, '{"poet":"Mahzun Doğan","poet_slug":"mahzun_dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMRÜMCE', 'omrumce-mehmet-basaran-g357w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben ömrümce köylere gittim
Taşlar arasından ıssız yollardan
Garip akşamlar içine
Tek başına ışıdığı yere okulların
Avuçlarımda yüreğimi götürdüm
Nedir çekisi kişinin
Gördüm orada gördüm
Eğildim kardeşçe toprağa
Yüzlerini çizdim öğrencilerin
Gözlerini yıldız yıldız
Bir umut sardı gönlümü
Dağbaşlarını ısıttı sevgim', 'Ben ömrümce köylere gittim Taşlar arasından ıssız yollardan Garip akşamlar içine Tek başına ışıdığı yere okulların Avuçlarımda yüreğimi götü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMRÜMDE SÜKUT', 'omrumde-sukut-cahit-sitki-taranci-sf8yn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıngıraksız, rehbersiz deve kervanı nasıl,
İpekli mallarını kimseye göstermeden,
Sonu gelmez kumlara uzanırsa muttasıl,
Ömrüm böyle esrarlı geçecek ses vermeden,
Ve böylece bu ömür, bu ömür her dakika,
Bir buz parçası gibi kendinden eriyecek.
Semada yıldızlardan, yerde kurtlardan başka,
Yaşayıp öldüğümü kimseler bilmeyecek!', 'Çıngıraksız, rehbersiz deve kervanı nasıl, İpekli mallarını kimseye göstermeden, Sonu gelmez kumlara uzanırsa muttasıl, Ömrüm böyle esrarlı ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMRÜN BİR ÂNI', 'omrun-bi-r-ni-mahmut-temi-zyurek-ur7r4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrün bu yakasında
Anılar öreni dünya
Yaşadıklarım umarsızca geri
Döndürüyor beni, günlerim eski
Günlerin solgun defteri
Bu yazı kimden kalma
Anlaşılır mı buralarda bu dil
Bu yürek nasıl direnmiş kuşatıldığında
Ne kaldı yüzyıllarımdan
Birkaç hayat dersi
Bozukdüzen bir ses
Acı veren gururdan başka
Bazı ânların altında
Ölü kelebek mezarları
Ahdlar, anıtlar, ukdeler...
Arasında yaprakların
Kalbim, güzel başlangıç
O resimli mağara
Bir göçükte ağzı kapanır mı onun da
Kazancımmış yitirdiklerim
Bir ömrüm olduğuna inandığımdan bu yana
Gezin ruhumda
Ellerin dokunuşların
Nefesin ısıtıyor dünyamı
Kavuşturuyor
O yakayı bu yakaya', 'Ömrün bu yakasında Anılar öreni dünya Yaşadıklarım umarsızca geri Döndürüyor beni, günlerim eski Günlerin solgun defteri Bu yazı kimden kalm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut  Temi̇zyürek']::text[], 8.5, '{"poet":"Mahmut  Temi̇zyürek","poet_slug":"mahmut_temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖMRÜNE YAN KUZUM', 'omrune-yan-kuzum-necmettin-halil-onan-jayuk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık hayatı ışıklandıran
Tutuşmuş bir kalbin alevleridir;
Kızıllık görmeyen ufku andıran
Bir yürek bahtına yansa yeridir.
Vah o boş kalbe ki aşkı tatmadı!
Ah o tat, duydukça doyulmayan tat!
Yanmanın lezzeti, acının tadı;
Yerine başkası konulmayan tat!
Ömrüne yan kuzum, bir çift göz için
Canını o korla dağlamadınsa!
Bir güzel yüz için, bir tek söz için,
Bir tutam saç için ağlamadınsa!', 'Karanlık hayatı ışıklandıran Tutuşmuş bir kalbin alevleridir; Kızıllık görmeyen ufku andıran Bir yürek bahtına yansa yeridir. Vah o boş kalb...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Halil Onan']::text[], 8.5, '{"poet":"Necmettin Halil Onan","poet_slug":"necmettin_halil_onan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİRÈİO''DAN', 'mi-r-i-o-dan-frederic-mistral-pm96g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Provence''lı bir kız anıyorum.
Gençliğimin aşklarında.
Crau ovasında, denize doğru buğdaylarda,
Büyük Homeros''un alçak gönüllü öğrencisi olarak,
Onu izleme istiyorum. Sadece
Köylü bir kız olduğundan
Crau''nun dışında çok az bahsetmişler ondan.
Alnı,yalnız gençliği ile göz kamaştırıcı
Ne altın tacı, ne Şam kaftanı vardı,
Fakat istiyorum ki onun şanı yükselsin
Tıpkı bir kraliçeninki gibi
Ve hor görülen güzel dilimiz onu okşasın
Ey çobanlar ve çiftçiler, çünkü şiirimi yalnız size söylüyorum.
Sen, vatanımın yüce Tanrısı,
Ki çobanlar arasında doğmuşsun,
Sözümü ateşle doldur, güç ver bana!
Biliyorsun: Yeşillik içinde
Güneşte ve jalede
İncirler olgunlaşınca
Tamamını toplamak için meyvelerin
Kurt gibi aç olan gelir.
Fakat budaklarını kestiği ağaçta
Hırslı insana elini atmak fırsatı vermeyen
Sen mutlaka yükseklere bir dal koydun.
Körpe güzel bir filizdir o
Misk kokan ve bakire bir fidedir.
Altın sikke gibi olgun bir meyvedir,
Göklerin kuşları doymak için ona konar.
Ben şu küçücük dalı görürüm
İçimi kıpırdatır onu tazeliği!
Görürüm: Sabah rüzgârında
Gökte sallanmakta olduğunu ölümsüz yapraklarının ve meyvelerinin....
Ey, Güzel Allah''ım, ey Dost.
Provence dilimizin kanatlarının üstünde
Kuşların dalını koparmak fırsatı ver bana!
Frederic MISTRAL', 'Provence''lı bir kız anıyorum. Gençliğimin aşklarında. Crau ovasında, denize doğru buğdaylarda, Büyük Homeros''un alçak gönüllü öğrencisi olar...', ARRAY['Türk Edebiyatı','Şiir','Frederic Mistral']::text[], 8.5, '{"poet":"Frederic Mistral","poet_slug":"frederic_mistral","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMRU''L KAYS', 'i-mru-l-kays-huseyin-ferhad-y2pfg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(Necid, 520 - Ankara, 565)
Atların lisanını bilirim
kadınların gizli tarifesini
itin hergelenin biriyim
muhabbet tellâllarına göre
Kalmadı yatmadığım hane
üryan girmediğim bahçe
İmru''l Kays''ı öldüren zehir
bana da sunuldu kaç kere
Doludizgin geçtim Yesrib''i
Mekke''yi kona göçe
görmek için şairin ülkesini
indim kadim Yemen''e
Yemen : Mısır ketenine
nakşedilmiş bir kaligrafi :
yüz bin sağmal deve
bir o kadar soru işareti
Yemen : çölün eteğine
serilmiş bir pösteki :
yüz bini çini kâse
bir o kadar cırcırböceği
Kahvenin yeşilini severim
sütün çivit mavisini
halden anlamazın biriyim
hayal tacirlerine göre
Necid bir kök hatmi
Aden bir dal defne
gözlerim şakaklarıma çekilir
güneş batarken Kızıldeniz''e
Nicedir dudaklarımda gezinir
Cemal Süreya''nın iki dizesi :
"İki şey : aşk ve şiir
bunlar kuşkuyla çiftleşir"
Boynundan sarkan gümüş zincir
sol kulağındaki pagan küpe
yine Kays''ı ele verir
dünyaya tekrar geri gelse
Her aşk bir şehir
gibi şiirin gri tipisine gizlenir
bir gün benim de kalbim
Ankara''da idam edilir', '(Necid, 520 - Ankara, 565) Atların lisanını bilirim kadınların gizli tarifesini itin hergelenin biriyim muhabbet tellâllarına göre Kalmadı y...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin  Ferhad']::text[], 8.5, '{"poet":"Hüseyin  Ferhad","poet_slug":"huseyin_ferhad","theme":"Türk Şiiri","is_hero":false,"total_lines":43}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİS!', 'mi-s-mehmet-taner-1mxcz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mis gibi şeftalinin sırasıdır şimdi
Haziran maziran derken o da çıkacak
Aldatılmış ruhum çıkacak
Adım deliye çıkacak', 'Mis gibi şeftalinin sırasıdır şimdi Haziran maziran derken o da çıkacak Aldatılmış ruhum çıkacak Adım deliye çıkacak...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİSAFİR', 'mi-safi-r-cahit-sitki-taranci-yd289', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gece misafirim olsan yeter,
Dolar odama lavanta kokusu;
Soğur sevincinden sürahide su.
Ay pencerede durup durup güler.
Havva kızlarının en dilberini
Görsün diye aya karşı soyunsan!
Okşasam, öpsem, koklasam bir zaman,
Vücudunun ürperen her yerini.
Teneffüs eder gibi seviştikçe,
Doğacak çocuğum aklıma gelir;
Şiir söylerim saadete dair,
Odama misafir olduğun gece.', 'Bir gece misafirim olsan yeter, Dolar odama lavanta kokusu; Soğur sevincinden sürahide su. Ay pencerede durup durup güler. Havva kızlarının ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİSKİNLİK İLE GELSİN', 'mi-ski-nli-k-i-le-gelsi-n-yunus-emre-glp1k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Miskinlik ile gelsin
Kimde erlik var ise
Merdivenlerden iterler
Yüksekten bakar ise
Gönül yüksekte gezer
Daima yoldan azar
Dış yüzüne o sızar
İçinde ne var ise
Aksakallı bir koca
Hiç bilmez ki hâl nice
Emek yemesin hacca
Bir gönül yıkar ise
Gönül Çalab''ın tahtı
Çalap gönüle baktı
İki cihan bedbahtı
Kim gönül yıkar ise
Sağır işitmez sözü
Gece sanır gündüzü
Kördür münkirin gözü
Âlem münevver ise
Az söz erin yüküdür
Çok söz hayvan yüküdür
Biline bu söz yeter
Sende gevher var ise
Sen sana ne sanırsan
Ayruğa da anı san
Dört kitabın mânâsı
Budur eğer var ise
Bildin gelenler geçmiş
Konanlar geri göçmüş
Aşk şarabından içmiş
Kim mânâ duyar ise
Yunus yoldan ırasın
Yüksek yerde durmasın
Sinle sırat görmesin
Sevdiği didar ise', 'Miskinlik ile gelsin Kimde erlik var ise Merdivenlerden iterler Yüksekten bakar ise Gönül yüksekte gezer Daima yoldan azar Dış yüzüne o sıza...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUHABBET', 'muhabbet-can-yucel-6mrwy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir fasulye çimleniyordu
Çiseledikçe yağmur.
Koştum vardım ki yanına
Anlasın ne nimet olduğunu
Sen git yerine! dedi Ayşa Kadın
Böyle kibar erkeyin ayağ’na
Ben kendi ayağ’mnan gelirim
Bu muhabbeti görünce uzaktan
Kıpkırmızı oldu biberiye
Bayram nedir ki dedim kendi kendime
Bayram bir ömürdür ben gibi bir deliye', 'Bir fasulye çimleniyordu Çiseledikçe yağmur. Koştum vardım ki yanına Anlasın ne nimet olduğunu Sen git yerine! dedi Ayşa Kadın Böyle kibar e...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUHAREBE GÖRMÜŞ BİR ADAM ANLATIYOR', 'muharebe-gormus-bi-r-adam-anlatiyor-necati-cumali-ms8ty', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Muharebede ne ölüm korkusu gelir
İnsanın aklına
Ne, evi barkı düşünürsün
Gezin üst kenarın ortasından
Arpacığın tepesinden
Beğendiğin yerini seçersin hedefin
Tetiği elin titremeden çekersin
Artık karşındaki sana benzemez
O da küçük bir dükkân işletir memleketinde
O da karısını sever
Onun da senin gibi
Küçük bir çocuğu var
Aklına bile gelmez
Artık senin yaşaman için
Onun ölmesi lâzımdır.', 'Muharebede ne ölüm korkusu gelir İnsanın aklına Ne, evi barkı düşünürsün Gezin üst kenarın ortasından Arpacığın tepesinden Beğendiğin yerini...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUHAYYER', 'muhayyer-attil-i-lhan-qlbzl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'önemli gizli boyutlarıyla yeryüzündeki yaşantımız
ne kadar azdır yaşadığımızdan yaşadığımızı sandığımız
söylediklerimizle değil söylemediklerimizle varız
o gün ki ölümün perdesine yapayalnız yansırız
ne kadar azdır yaşadığımızdan yaşadığımızı sandığımız
bir incesaz ki süreklidir yaprak döken korularda
çılgınlıkları oluşturur en çapraşık duygularda
büyük çıkmaz akla gelip de sorulmayan sorularda
bazı insan içten içe düşünür hesaplar da
ne kadar azdır yaşadığımızdan yaşadığımızı sandığımız
üflediğimiz sustuğumuz tutkuların düşlerimizi çokçadır
çocukluktan çıktığımızı sanmak aslında çocukçadır
gerçi gençlik bir uçta yaşlılık bir uçtadır
birleştikleri gerçek o müthiş sonuçtadır
ne kadar azdır yaşadığımızdan yaşadığımızı sandığımız
tutuklunun günlüğü', 'önemli gizli boyutlarıyla yeryüzündeki yaşantımız ne kadar azdır yaşadığımızdan yaşadığımızı sandığımız söylediklerimizle değil söylemedikle...', ARRAY['Türk Edebiyatı','Şiir','Attilâ  İlhan']::text[], 8.5, '{"poet":"Attilâ  İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUHTEŞEM AYIPLAR', 'muhtesem-ayiplar-abdulkadir-budak-dq3vy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göğsümün yelkenini şişirecek bir rüzgâr
Yüzüme çarpılacak bir kapı bulmalıyım
Dışlanmak nasıl bir şey, öğrenmek için
Ruh halini metale yenik düşen ahşabın
Katliamdan kılpayı kurtulan günün sonunda
Hissemden çoğunu almak muhteşem ayıplardan
Öpen dudaklar ahşap, okşanan metal ise
Sevişmeyi ayıp saymak mümkündür kaptan
Tekne şizofren öyle mi, kayalara yöneliyor
İlk celsede beraat ettiriliyor deniz
Soru metal, yanıt ahşap; asılan bir sokağa
Cadde adını verecek kadar incelikliyiz
Midye çıkarma konusunda usta olsam ne çıkar
İnci bulamadıktan, inci bulamadıktan...
Zıtların birliği çok can yakıcı tanrım!
Gövdem metal, ruhum ise ahşaptan
Ağaç ile dâr sözcüğü yer değişmiş, aldanma
Sallanan bedenlere bakınca göreceksin
Yoruldum, uykum geldi, sözlerim kapanıyor
Terzi ahşap, kumaş metal; kırılmış bir iğneyim
Tanrım! Bu orantısızlık beni çok korkutuyor
Şehrin elleri ne büyük, ne kadar küçük başı
Kanın sızdığını gördüm bir çivinin sesinden
Karıştırmak zorundayım metal ile ahşabı', 'Göğsümün yelkenini şişirecek bir rüzgâr Yüzüme çarpılacak bir kapı bulmalıyım Dışlanmak nasıl bir şey, öğrenmek için Ruh halini metale yenik...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUKADDİME', 'mukaddi-me-ahmet-hasi-m-b2znj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karaosmanzâde Câvide Hayri Hanımefendi''ye
Zannetme ki güldür, ne de lâle
Âteş doludur, tutma yanarsın
Karşında şu gülgûn piyâle...
İçmişti Fuzuli bu alevden,
Düşmüştü bu iksir ile Mecnûn
Şi''rin sana anlattığı hâle...
Yanmakta bu sagârdan içenler,
Doldurmuş onunçün şeb-i aşkı
Baştanbaşa efgân ile nâle...
Âteş doludur, tutma yanarsın
Karşında şu gülgûn piyâle!..', 'Karaosmanzâde Câvide Hayri Hanımefendi''ye Zannetme ki güldür, ne de lâle Âteş doludur, tutma yanarsın Karşında şu gülgûn piyâle... İçmişti F...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUKAYESE', 'mukayese-necip-fazil-kisakurek-v1b4s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıbanımız çok derin, işletemez yakılar;
Nerde bizim şarkımız, nerde öbür şarkılar?', 'Çıbanımız çok derin, işletemez yakılar; Nerde bizim şarkımız, nerde öbür şarkılar?...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUM GİBİ ERİYORSUN GİT GİDE', 'mum-gi-bi-eri-yorsun-gi-t-gi-de-gyorgy-faludy-b4c55', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mum gibi eriyorsun git gide, tükeniyorsun
sabahleyin. Saçlarını taradığımda
dağılıyorlar.
Kolların beyaz şarap gibi apak.
Kanser kozaları boynunda belirmiş.
Pencerenin önünde mavi gökyüzü.
Taş duvarda merhamet yok.
Bugün acı hissetmiyorsun. Tünüyorum
yatağına ve karıştırıyorum kahve bardağını.
Göğüslerinin sertleşmiş yerlerinde, yeşil dikişler
morarmış yara izleri. Düşlere dalıyorum.
Terk etmemişsin. Yaşamımın
öteki yarısında da yanımda mısın?
Sevgili, yetmiş yaşın ruhu,
ne diyebilirim ki? Selamlıyorum ışığı
çünkü boz bulanık gözleri hâlâ sevi dolu.
Enkaza dönmüş gövden yaşamakta.
Bu iyi bir yol.
Ve daha iyisi de yok.
György  FALUDY', 'Mum gibi eriyorsun git gide, tükeniyorsun sabahleyin. Saçlarını taradığımda dağılıyorlar. Kolların beyaz şarap gibi apak. Kanser kozaları bo...', ARRAY['Türk Edebiyatı','Şiir','György  Faludy']::text[], 8.5, '{"poet":"György  Faludy","poet_slug":"gyorgy_faludy","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUMLARI SÖNDÜREN PALYAÇO', 'mumlari-sonduren-palyaco-umit-sener-ta-hqv4t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öldü doğum günüm
palyaçolar geçti birer birer
mumları söndürerek
elleri gördüm beni alkışlayan
babam!
taş bir yürek her gün bana atan
öldü
hatırlardım doğum günlerini
mum dikerdim duvarlara
kayıp şimdi suratlar
konuşmayan duvarlarda', 'Öldü doğum günüm palyaçolar geçti birer birer mumları söndürerek elleri gördüm beni alkışlayan babam! taş bir yürek her gün bana atan öldü h...', ARRAY['Türk Edebiyatı','Şiir','Ümit Şener Ta']::text[], 8.5, '{"poet":"Ümit Şener Ta","poet_slug":"umit_sener_ta","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUSTAFA KEMAL', 'mustafa-kemal-attila-i-lhan-6fgzr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dağ başını efkâr almış
gümüş dere durmaz ağlar
gözyaşından kana kesmiş gözlerim
ben ağlarım çayır ağlar çimen ağlar
ağlar ağlar cihan ağlar
mızıkalar iniler ırlam ırlam dövülür
altmış üç ilimiz altmış üç yetim
yıllar gelir geçer kuşlar gelir geçer
her geçen seni bizden parça parça götürür
mustafa''m mustafa kemal''im
diz dövdüm
gözlerim şavkı aktı sakarya''nın suyuna
sakarya''nın suları nâmın söyleşir
hemşehrim sakarya öksüz sakarya
ankara''dan uçan kuşlar
kemal''im der günler günü çağrışır
kahrolur bulutlara karışır
gök bulut yaşmak bulut
uca dağlar dev boyunlu morca dağlar
divan durmuş bekleşir
mustafa''m mustafa kemal''im
nasıl böyle varıp geldin hoşgeldin
çıngı kaymış yalazlanmış gözlerin
şol yüzünde güneş südü sıcaklık
ellerinden öperim mustafa kemal
senin dalın yaprağın biz senin fidanların
biz bunları yapmadık
sen elbette bilirsin bilirsin mustafa kemal
elsiz ayaksız bir yeşil yılan
yaptıklarını yıkıyorlar mustafa kemal
hani bir vakitler kubilay''ı kestiler
çün buyurdun kesenleri astılar
sen uyudun asılanlar dirildi
mustafa''m mustafa kemal''im
karalar kuşanmış karadeniz akmam diyor
dokunmayın ağlamaktan bıkmam diyor
bu gece kıyamet gecesi bu vapur bandırma vapuru
yattığı yer nur olsun mustafa kemal
ben ölümden korkmam diyor
korkmam diyen dilleri toz oldu toprak oldu
değirmen döndü dolandı yıllar oldu
bir kusur işledik bağışlar mı kimbilir
o bize öğretmedi kazan kaldırmasını
günahı vebali öğretenin boynuna
erdirip oldurana ana avrat sövmesini
yüreğim kırıldı kanım kurudu
var git karadeniz var git başımdan
mızıka çalındı düğün mü sandın
bir yol koyup gideni gelir mi sandın
mustafa''m mustafa kemal''im
ankara''nın taşına bak
tut ki baktım uzar gider efkârım
çayır ağlar çimen ağlar ben ağlarım
gözlerimin yaşına bak
ankara kalesi''nde rasattepe''de
bir akça şahan gezer dolanır
yaşın yaşın mezarını aranır
şu dünyanın işine bak
mustafa''m mustafa  kemal''im', 'dağ başını efkâr almış gümüş dere durmaz ağlar gözyaşından kana kesmiş gözlerim ben ağlarım çayır ağlar çimen ağlar ağlar ağlar cihan ağlar ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":61}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLAKA BURSA', 'mutlaka-bursa-metin-guven-g3t2c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'durdum ve kayboldum sonra
durdum ve yürüdüm
şehrin kenarlarına
şehrin rüzgarına
/senin gözlerin için
şehrin dalgınlığına
ve ufkuna sonra
/senin gözlerin için
sen ve
dağlarda bekleyen çocuklar
için/
yürüdüm
çaresiz bir nehrin
kenarlarına
(nerde bir eski sevgili dursa
orada başlıyor yurdum
ve mutlaka Bursa)
durdum ve kayboldum sonra
uzaklara sarkan
bir hançer gölgesinde', 'durdum ve kayboldum sonra durdum ve yürüdüm şehrin kenarlarına şehrin rüzgarına /senin gözlerin için şehrin dalgınlığına ve ufkuna sonra /se...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLU AŞK YOK Kİ DÜNYADA', 'mutlu-ask-yok-ki-dunyada-louis-aragon-mvws4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aslında hiçbir şey kâr değil insana
Ne gücü ne zayıf yanları ne de yüreği
Gölgesi bir haç gölgesidir kollarını açsa
Ve kırar göğsüne bastırırken sevdiği şeyi
Tuhaf bir ayrılıktır hayatı kapkara
Mutlu aşk yok ki dünyada
Hani giydirilmiş erler bir başka yazgıya
İşte o silahsız askerlere benzer hayatı
Sabahları o yazgı için uyanmış olsalar da
Tükenmiştirler ve kararsızdırlar akşamları
Söyle yavrum şu sözleri ve sakın ağlama
Mutlu aşk yok ki dünyada
Güzel aşkım tatlı aşkım çıbanım derdim
Yaralı bir kuş gibi taşırım seni şuramda
Ve görmeden bakanlar şu halimize bizim
Süzdüğüm sözleri söylerler benden sonra
Ve her şey der demez ölür iri gözlerin uğruna
Mutlu aşk yok ki dünyada
Yaşamayı öğrenmek bizimçin geçti çoktan
Ağlasın gece içinde kalplerimiz yan yana
En küçük şarkıyı mutsuzluktur kurtaran
Her ürperiş borçlu baştan bir hayıflanmaya
Ve her kitar havası beslenir hıçkırıkla
Mutlu aşk yok ki dünyada
Acılara batmamış bir aşk söyle bana
Yıkmamış kıymamış olsun bir aşk söyle
Bir aşk söyle sarartıp soldurmamış ama
İnan ki senden artık değil yurt sevgisi de
Bir aşk yok ki paydos demiş gözyaşlarına
Mutlu aşk yok ki dünyada
Ama şu aşk ikimizin öyle de olsa
Louis ARAGON', 'Aslında hiçbir şey kâr değil insana Ne gücü ne zayıf yanları ne de yüreği Gölgesi bir haç gölgesidir kollarını açsa Ve kırar göğsüne bastırı...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis_aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLU AŞK YOKTUR', 'mutlu-ask-yoktur-louis-aragon-9gxf9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsan her şeyi elinde tutamaz hiç bir zaman
Ne gücünü ne güçsüzlüğünü ne de yüreğini
Ve açtım derken kollarını bir haç olur gölgesi
Ve sarıldım derken mutluluğuna parçalar o şeyi
Hayatı garip ve acı dolu bir ayrılıktır her an
Mutlu aşk yoktur
Hayatı Bu silahsız askerlere benzer
Bir başka kader için giyinip kuşanan
Ne yarar var onlara sabah erken kalkmaktan
Onlar ki akşamları aylak kararsız insan
Söyle bunları Hayatım Ve bunca gözyaşı yeter
Mutlu aşk yoktur
Güzel aşkım tatlı aşkım kanayan yaram benim
İçimde taşırım seni yaralı bir kuş gibi
Ve onlar bilmeden izler geçiyorken bizleri
Ardımdan tekrarlayıp ördüğüm sözcükleri
Ve hemen can verdiler iri gözlerin için
Mutlu aşk yoktur
Vakit çok geç artık hayatı öğrenmeye
Yüreklerimiz birlikte ağlasın sabaha dek
En küçük şarkı için nice mutsuzluk gerek
Bir ürperişi nice pişmanlıkla ödemek
Nice hıçkırık gerek bir gitar ezgisine
Mutlu aşk yoktur
Bir tek aşk yoktur acıya garketmesin
Bir tek aşk yoktur kalpte açmasın yara
Bir tek aşk yoktur iz bırakmasın insanda
Ve senden daha fazla değil vatan aşkı da
Bir tek aşk yok yaşayan gözyaşı dökmeksizin
Mutlu aşk yoktur ama
Böyledir ikimizin aşkı da', 'İnsan her şeyi elinde tutamaz hiç bir zaman Ne gücünü ne güçsüzlüğünü ne de yüreğini Ve açtım derken kollarını bir haç olur gölgesi Ve sarıl...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis_aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLU BİR HAYAT', 'mutlu-bi-r-hayat-czeslaw-milosz-x3pm6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bereketli hasatların olduğu yıllara rastladı yaşlılığı.
Ne depremler vardı, ne kuraklık, ne de sel baskınları.
Sanki bir düzene girmişti mevsimlerin değişmesi,
Yıldızlar daha parlak, güneş daha güçlüydü.
En uzak illerde bile savaşlar sürmüyordu artık.
Birbirleriyle dost geçinen kuşaklar yetişmişti.
Alay konusu olmaktan çıkmıştı insanın akılcı yanı.
Acı geliyordu ona böyle yenilenmiş bir dünyaya veda etmek.
Utanç ve kıskançlık duyuyordu kuşkusundan,
Yaralı belleği de kendisiyle yok olacak diye mutluydu.
Ölümünden iki gün sonra bir kasırga kavurdu kıyıları.
Yüz yıldır sönmüş duran yanardağlardan dumanlar tüttü.
Lavlar yayıldı ormanlara, bağlara, kasabalara.
Ve savaş başladı adalardaki bir çatışmayla.
Czeslaw  MILOSZ', 'Bereketli hasatların olduğu yıllara rastladı yaşlılığı. Ne depremler vardı, ne kuraklık, ne de sel baskınları. Sanki bir düzene girmişti mev...', ARRAY['Türk Edebiyatı','Şiir','Czeslaw  Milosz']::text[], 8.5, '{"poet":"Czeslaw  Milosz","poet_slug":"czeslaw_milosz","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLU SEVİ YOKTUR', 'mutlu-sevi-yoktur-louis-aragon-055l2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir şeyi sürgit elinde tutamaz kişioğlu
Ne gücünü ne güçsüzlüğünü ve ne de yüreğini
Kollarını açtı sanırken bir haç olur gölgesi
Bir tuhaf bir acılı kopmadır günleri
Sıkı sarılmak isterken ezer mutluluğunu
Mutlu sevi yoktur
Yaşamı şu silahsız askerlere benzer
Ki başka bir yazgıyla donatmışlardır onları
Neye yarar sabah erken uyanıp kalkmaları
Çaresiz ve kararsız kalırlar akşamları
Söyle bunları canım gözyaşını tutuver
Mutlu sevi yoktur
Sevgilim güzelim yürekte yaram benim
Bir yaralı kuş gibi taşırım içimde seni
Ve şunlar ki bilmeden izler geçmişimizi
Yineler hep arkamdan ördüğüm sözcükleri
Ve ölmeye can atar koca gözlerin için
Mutlu sevi yoktur
Vakit geç artık çok geç yaşamı öğrenmeye
Ağlasın yüreklerimiz topluca karanlıkta
Bunca mutsuzluk ah küçük bir türkü uğruna
Bir ürperti uğruna bunca sıkıntı bunca
Ve de bunca hıçkırık bir gitar ezgisine
Mutlu sevi yoktur
Hiçbir sevi yoktur ki yoğrulmasın acıyla
Ve hele yurt sevgisi hele özellikle sen
Hiçbir sevi yoktur sarartıp soldurmayan
Ve hele yurt sevgisi hele özellikle sen
Hiçbir sevi yoktur beslenmesin gözyaşıyla
Mutlu sevi yoktur
Ama ikimizin sevisi budur.', 'Hiçbir şeyi sürgit elinde tutamaz kişioğlu Ne gücünü ne güçsüzlüğünü ve ne de yüreğini Kollarını açtı sanırken bir haç olur gölgesi Bir tuha...', ARRAY['Türk Edebiyatı','Şiir','Louis Aragon']::text[], 8.5, '{"poet":"Louis Aragon","poet_slug":"louis_aragon","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLULUK', 'mutluluk-valeri-petrov-v4nrj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceydi, Vitoşa’dan geliyordum
Arabanın içindeydim tek başıma.
Çevrede sıra sıra şaşkın yayalar
Gitar sesleri, şarkılar.
Koyu karanlığın içinde
Küçük bir yıldız gibi birden
Farların yansısı parladı
Genç bir adamın omuzunda.
Hepsi bu kadar, bir saniye ancak
Ama neler vermezdim uğruna
Nişan yüzüklü bir kadının elinin
Böyle konması için omuzuma.
Valeri PETROV', 'Geceydi, Vitoşa’dan geliyordum Arabanın içindeydim tek başıma. Çevrede sıra sıra şaşkın yayalar Gitar sesleri, şarkılar. Koyu karanlığın içi...', ARRAY['Türk Edebiyatı','Şiir','Valeri Petrov']::text[], 8.5, '{"poet":"Valeri Petrov","poet_slug":"valeri_petrov","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTSUZ KRALİÇE', 'mutsuz-krali-ce-bejan-matur-gle8y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Etekleri buz tutmuş
O mutsuz kraliçe
Artık inanmıyor
Gözün büyüsüne
Günlerdir beklediği ses
Gizlenmiş tepelerin ötesine
Arasıra buluşup
Kervanların sığacağı darlıktaki
Sokaklardan sözeden adam artık yok
Anlayan yok
Baharat satılan hanların
Kokulu yalnızlığından
Bir ses bekliyor ısrarla
İnce parmaklı tütün kokusundan
Ormanda fısıldayan
Güz kadar yaşlı kraliçe
Dökülüyor
Buzdan ve siyah eteğiyle', 'Etekleri buz tutmuş O mutsuz kraliçe Artık inanmıyor Gözün büyüsüne Günlerdir beklediği ses Gizlenmiş tepelerin ötesine Arasıra buluşup Kerv...', ARRAY['Türk Edebiyatı','Şiir','Bejan Matur']::text[], 8.5, '{"poet":"Bejan Matur","poet_slug":"bejan_matur","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİZAH', 'mi-zah-yevgeni-yevtusenko-5aawo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Krallar,
imparatorlar ve çarlar,
tüm evrenin hükümdarları,
buyrukları altında bulundurmuşlar orduları
ama becerememişler hiç
mizahı.
Ezop, yayan yürüyüp yolları
uğradığında ünlü kişilerin her gün
rahatlık içinde yüzen saraylarına,
onları dilenciden daha üstün görmemişti.
iki yüzlülerin
ayak izlerini damga gibi bastığı
evlerde, toplantılarda
Nasreddin Hoca,
iğneli şakalarıyla,
altüst etti
kafalarını
kahkahalarıyla
bir dizi paytak gibi!
Kimileri
ısmarlama
mizah istedi-
ama mizah parayla satın alınmaz ki!
Kimileri
tuttu mizahı
katletti
ama mizah ölmedi,
kaatillerine
keskin dişlerini gösterdi!
Çünkü durup ahmak ahmak
güçtür
mizahla
savaşmak.
Tekrar tekrar idam ettiler mizahı
ama o,
koltuğa alıp gövdeden ayrılmış kafayı
alay etti, savaştı.
Mumyacıların kavalları çalmaya başlar başlamaz
alaylı bir havayı,
mizah da şaştı, ve bir
meydan okuyuşla haykırdı:
"İşte geldim geri, buradayım gene"
Keyifle, görseniz, hem de nasıl oynardı.
Tuttular tekrar hapsettiler mizahı
Şimdi o,
lime-lime olmuş eski bir palto içinde,
sarkık bir suratla
ve bir yapmacık pişman maskesiyle
siyasal bir suçlu
hem de tutuklu
yürür
ama özgür
idam sehpasına.
Dış görünüşüyle i��ine çekilmiş, biraz da pişman,
sanki de hayattan öte hayat olduğuna inanmış,
ama apansız
kayıverir
giydiği paltonun içinden,
ve el sallayarak
yağlayıverir tabanı.
Mizah şimdi taş duvarlardan, demir parmaklıklardan
dalmış içeri
onlar gösteredursun dar hücreleri,
ve zindanı
o bayağı bir insan gibi öksürüp
yürür cesurca öne doğru
dudağında bir türkü,
elde tabanca, Kış Sarayının üstünden.
Alışıktır o kaş çatmalara,
çünkü bilir ki bir zarar getirmez onlar;
ve zaman olur mizaha
kaş çatar
mizah.
Ölümsüzdür o,
Hafif ve çabuktur.
İçinden geçemiyeceği eşya
ve insan yoktur.
Öyleyse-
mizaha hem şeref dileyelim, hem şan
Çünkü-
odur en cesur insan.
Yevgeni YEVTUŞENKO', 'Krallar, imparatorlar ve çarlar, tüm evrenin hükümdarları, buyrukları altında bulundurmuşlar orduları ama becerememişler hiç mizahı. Ezop, y...', ARRAY['Türk Edebiyatı','Şiir','Yevgeni Yevtuşenko']::text[], 8.5, '{"poet":"Yevgeni Yevtuşenko","poet_slug":"yevgeni_yevtusenko","theme":"Türk Şiiri","is_hero":false,"total_lines":84}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MİZANA', 'mi-zana-roni-margulies-4rptv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Basit şeyler oldu istediklerim hep:
Çok çeşitli içkiler içmek;
serserilik etmek uzak limanlarda;
bumbayla seren arasındaki farkı bilmek;
çok yelkenli bir kalyonu tek başıma götürmek;
muazzam paralar kazanıp bir anda,
bir gecede tümünü yitirmek;
herkesin bir görüşte sevdiği kadınları
en çok ve başkaca sevmek.
En başta ama ve onulmazca
Elsa''yı sevmek, her sabah ona dönmek.
Olamadı elbet.
Tümü çelişti bunların Elsa''yla.
Seçmem gerekti. Seçtim.
Bu seçimi sorgularım belki yaşlandıkça,
kuşkum yok şimdilik ama.
Ve ilginç yönü şu ki üstelik bu öykünün:
Ne bir mizanaya tırmandım ömrümde,
ne de tırmanacak olsam bir gün
Elsa''ya dönebileceğim artık indiğimde.', 'Basit şeyler oldu istediklerim hep: Çok çeşitli içkiler içmek; serserilik etmek uzak limanlarda; bumbayla seren arasındaki farkı bilmek; çok...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMZASI GÜL', 'i-mzasi-gul-abdulkadir-budak-tzq75', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İmgeydi gül, kan sızdıran yerinde
Bahçıvan ekmeği bançe düşleri
Uzun yol sürücüsü, otel kâtibi
Kıskançlığın alfabesi örneğin
Sözgelimi bir cinayet nedeni
İmgeydi gül derin avcı izinde
Ezilmiş ceylan bakışı imgesi
İmgeydi gül, elyazması kitaptı
Sığ okumaların göremediği
Gül imgesi sırı dökülmüş ayna
Nasıl göstersindi inceliğini?
İmgeydi gül, yani hekim çantası
Bir ecza dükkânı yaralarına
Büyümeyi öğretirken sudaki halkalara
İmgeydi gül, bileğine çiviydi
Göndermeydi çarmıhtakı İsa''ya
İmgeydi gül, yenik zafer gününde
Özenle büyütülen sevişme vakitleri
Diyorum ki karbonuydu kimliğin
Ceketinin cebindeki bir gözyaşı mendili
İmzası gül, bir hançere oyulmuş
Kanayan bir kalbin üzerindeki
Yazmıyorum ölüyorum diyerek
Güllerle örtüyor bir şair cesedini', 'İmgeydi gül, kan sızdıran yerinde Bahçıvan ekmeği bançe düşleri Uzun yol sürücüsü, otel kâtibi Kıskançlığın alfabesi örneğin Sözgelimi bir c...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İMZASIZ MEKTUP', 'i-mzasiz-mektup-kostas-pigadiotis-8hj8d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anasına yazdığı
mektubu buldular
askerin alnında,
bitiremeden daha
kapmıştı rüzgar.
Şaşırdılar hangisine vereceklerini
bekleyen bunca ananın
imzasızdı çünkü.
Kostas PIGADIOTIS
Çeviri : Marianna YERASIMOS,', 'Anasına yazdığı mektubu buldular askerin alnında, bitiremeden daha kapmıştı rüzgar. Şaşırdılar hangisine vereceklerini bekleyen bunca ananın...', ARRAY['Türk Edebiyatı','Şiir','Kostas Pigadiotis']::text[], 8.5, '{"poet":"Kostas Pigadiotis","poet_slug":"kostas_pigadiotis","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medyada ''şiir'' savurganlığı', 'medyada-siir-savurganligi-necip-fazil-689ay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''şiir'' savurganlığı
YayIm&quot; ve &quot;yayın&quot; sözlü ve
yazılı medyada yazım karışıklığına yol açan iki kelime... Başta Türk Dil
Kurumu''nun &quot;Türkçe Sözlük&quot;ü olmak üzere birçok sözlük &quot;yayım&quot;ı &quot;Kitap, gazete
gibi okunacak şeylerin basılıp dağıtılması veya radyo ile dinlenecek şeylerin
yayılması&quot; olarak tanımlıyor ve &quot;neşir&quot; karşılığını veriyor. &quot;Yayın&quot; ise
&quot;Basılıp ortalığa sürülen kitap, gazete gibi okunan veya radyo ile her yana
yayılıp dinlenen şeyler&quot; demek ve yani &quot;neşriyat&quot;...
Mustafa Nihat Özön de &quot;Osmanlıca-Türkçe Sözlük&quot;te &quot;neşr&quot; karşılığı olarak dört
tanım veriyor: &quot;1.Dağıtma, yayma. 2.Herkese duyurma. 3. Gazeteye yazma,
yazdırma. 4. Kitap, gazete bastırıp çıkarma.&quot; Özön''e göre &quot;neşriyyat&quot;ın
karşılığı ise sadece &quot;yayım&quot;...
Melih Cevdet Anday, &quot;Dili yazarlar yapar&quot; derdi, &quot;sözlüklerin koyduğu kurallar
değil&quot;... Bu yüzden mesela konuşurken &quot;hastane&quot; dese de, fakat &quot;hastahane&quot; diye
yazardı.
&quot;Basın&quot;dan &quot;medya&quot; aşamasına geçilirken dil de değişip gelişti.
Okurumuz ÖZGÜR TÜRKEŞ mektubunda diyor ki: &quot;Ben bu zamana kadar yayının
televizyon, radyo gibi medya organları tarafından, yayımın ise gazete, dergi,
kitap gibi basılı organlar tarafından yapıldığını zannederdim. Acaba bu konuda
bizleri aydınlatabilecek bir yazı yazabilir misiniz?&quot;
Sayın Türkeş''in aklının karışması biraz da kavramları tersinden okumasından
kaynaklanıyor. Bildiğinin tam tersine uzunca bir zamandır &quot;yayın&quot; gazete, dergi,
kitap gibi basılı organlar için kullanılmakta... Bunun içindir ki &quot;Türkiye
Yayıncılar Birliği&quot;nin adında &quot;yayım&quot; değil &quot;yayın&quot; kelimesi yer almakta...
Bunun içindir ki &quot;yayımevi&quot; değil de &quot;yayınevi&quot; diyoruz. Ben, &quot;yayım&quot;ı
televizyon, radyo; &quot;yayın&quot;ı da gazete, kitap için kullanmayı yeğliyorum.
Eskiden de &quot;radyo neşriyatı&quot; denmez miydi?
Ankara''dan yazan RIFAT YÖRÜK adlı okurumuz da SABAH gazetesinin öncelikle pazar
günleri vermeye başladığı &quot;Dünya Klasikleri&quot; için teşekkürlerini ilettikten
sonra 22 Şubat 2004 tarihli gazetemizde yer alan dört &quot;hata&quot;yı işaret ediyor.
Ahmet Hakan''ın 3-4 ay önce yayınlanan yazısı bilgisayardaki &quot;kod&quot;lamadan
kaynaklanıyordu, ki ertesi gün özrü bildirildi. İlker Sarıer''in yazısında RTÜK
üyesi D.Mehmet Doğan yerine Mustafa Doğan, televizyon sayfasında da Mehmet
Barlas''ın programı tanıtılırken AK Parti İstanbul İl Başkanı Mehmet Müezzinoğlu
yerine Mehmet Müderrisoğlu yazılması okurumuzun da belirttiği gibi
yazarlarımızın bir dalgınlığının eseriydi. Uyarısı için teşekkürler...
Rıfat Yörük, aynı gün &quot;Hıncal''ın Yeri&quot;nde yayımlanan &quot;Koşma&quot; başlıklı şiiri
Necip Fazıl''ın yazdığını ve adının da &quot;Veda&quot;
olduğunu belirtiyor. Benden de bu konuda bir açıklama bekliyor, ki gerçekten de
adı geçen şiir Necip Fazıl Kısakürek''indir ve üstat bu şiiri 1923 yılında &quot;Veda&quot;
adıyla yayınlamıştır. Hatta bu ilk biçiminde birinci mısraı &quot;Akşamı getiren
sesleri dinle&quot; değil &quot;Elimde, sükutun nabzını dinle&quot;dir, ikinci dörtlük ise
şöyledir: &quot;Yürü, gölgen seni uğurlamakta, / Küçülüp küçülüp kaybol ırakta, /
Yolu tam dönerken arkana bak da, / Köşede bir lahza kalıver gitsin!&quot; (Çile,
Büyük Doğu Yayınları, s: 200.) Oysa aynı şiir, &quot;Ayrılık Vakti&quot; adıyla Necip
Fazıl''ın ilk kitabı &quot;Örümcek Ağı&quot;nda (Halk Kitaphanesi, 1925, s: 21) ile &quot;Ben ve
Ötesi&quot;nde (Sühulet Kütüphanesi, 1932, s: 16) SABAH''ta yayımlanan biçimiyle yer
almıştır.
Elbette Hıncal Uluç''un bütün bu kaynaklara bakma olanağı yok, olamaz da... Fakat
şiiri gönderen okur Neşet Üstündağ, şiirin Necip Fazıl''a ait olduğunu
belirtebilirdi.
Eskiden özellikle doğum günlerinde &quot;kilitli&quot; hatıra defterlerine yazılırdı
şiirler ve &quot;miri malı&quot; olduğu için de elden ele dolaşırdı. Şimdilerde ise nice
sözüm ona &quot;internet&quot; ya da ehil kişilerce hazırlanmayan şiir antolojilerinde
Yahya Kemal''den
Orhan Veli''ye,
Nazım Hikmet''ten
Cemal Süreya''ya Türkçe''nin yüz akı
şairlerinin eserleri &quot;serseri mayın&quot; misali, hiçbir denetimden geçmeden elden
ele, dilden dile geziniyor.
Ben dahi kendi şiirlerimi tanıyamıyorum.', '''şiir'' savurganlığı YayIm&quot; ve &quot;yayın&quot; sözlü ve yazılı medyada yazım karışıklığına yol açan iki kelime... Başta Türk Dil Kurum...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl']::text[], 8.5, '{"poet":"Necip Fazıl","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":63}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Murathan MUNGAN Üzerine Bir Anlatı Denemesi', 'murathan-mungan-uzerine-bir-anlati-denemesi-selcuk-yamen-w7c78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir Anlatı Denemesi
Selçuk YAMEN /
Seyirdefteri
Yaşantısı arabada geçenlerin, kimi şeyleri
kaçırdığını düşünürüm sıklıkla. Bu, benim için de geçerli ne yazık ki... Bu
duygunun eksilmesini ne kadar sağlar dinlenilen müzik, bilmiyorum.
Arabada olmadığım şanslı günlerimden birinde, kulağıma çalınan sesle
irkildim. Kızılordu Korosu’nun düzenlediği bir konserdeymişim gibi duyumsadım
birden kendimi. Sese doğru yürümeye başladım, ses bir ilkokulun bahçesinden
geliyordu. Şarkı söyleyen yüzlerce çocuk... Okulun dış duvarlarını doldurarak
konseri izleyen, kadınlarla çocukların arasındaydım artık. Çocuklar neşe
içindeydi, koroyu yöneten öğretmenin gözlerindeki pırıltı bana kadar geliyordu.
Neydi beni böylesine şaşırtan? Yaşamda karşılaştığımız güzelliklerin, günden
güne azalması duygusu mu? Sevinçli gözlere duyulan özlem mi?
‘Telli telli telli şu telli turnam
sanma ki yaralı uçmaz bir daha...’
Kızılordu Korosu bu şarkıyı söylerken dalmışım. Bu şarkının sözlerinin
yazarı Murathan MUNGAN düşüyor birden aklıma. Eve döndüğümde, kulağımdan gitmeyen
o güzelim seslerle bir kez daha bakıyorum Mungan’ın yazdıklarına. İlk önce şarkı
sözlerinden tanıdık onu. Şair olduğunu bilenler de vardı. Öykülerini, film
senaryolarını, oyunlarını okuduk. Karşımızda sürekli yazan biri vardı. Küçükken
en çok kaldırım taşlarına oturmayı severmiş, bir de geyikleri. Mardin
sokaklarında çamura bulanmış bu çocuğun ileride şair-yazar olacağını bilen
çıkmış mıdır?
Murathan MUNGAN, bu gün bir marka artık. Çok okunan, çok satan kitapların
yazarı, şairi. İmza günlerinde uzun kuyruklar oluşuyor, kaleminden çıkan
neredeyse her şey kapışılıyor. Yazdıkları, okurlarının ruh hallerine,
davranışlarına yansıyan kitaplara dönüşüyor.
Ülke hızla kentleşiyordu, kitaplarda çoğunlukla, birlikte yapılabilecek
şeylere dokunuluyordu. Bireyin tekil hali, yalın hali nicedir diye soran pek
yoktu. Mungan yazdıklarıyla, birey olarak kendine ait bir dünya kurarken,
bireyselleşmeye başlayan geniş bir kitleyi de oraya çekiyordu. Orada herkesin
kendine yakın bulacağı bir yer vardı; çünkü Mungan çok yazıyor, her yere
uğruyordu. Sözcüklere de hakimdi, formülün tamamlanması için simgeler gerekliydi
ve o simgeler bir süre sonra kendiliğinden geldi:
‘Maske’ ki, var olan kaba dünyanın bireyi anlayamayacağını imliyordu. İç
dünyasının sergilenmemesi için takınılması zorunluydu.
‘Sahtiyan’ ki, serpilmiş, boyanmış, cilâlanmış deri anlamına geliyordu.
Yani bireyin var olan kaba alanda bedeninden soyulduğu, kendisinden geriye
yalnızca reklamasyon, ölü, var olmayan bedeninin derisinin kalabileceği
imleniyordu.
‘Ayna’ ki, bireyselleşmenin en güç durağıydı. Ya var olan kaba alan
-toplum- içine dönülecekti ya da kendi doğrularının peşinde hesaplaşmanın acısı
kabul edilerek yola devam edilecekti.
‘Geyik/kunduz vb’ ki, bireyselleşmeyi kabul ederek derisi ile birlikte kaba
alandan kendini soyutlamanın imgesi olarak çıkıyordu karşımıza. Ramis Dara, “yer
altı, gizil, kale, sarnıç, tutsak, zula, mahpus, post vb” sözcüklerle, Mungan’ın
sürekli olarak örtünme, kapanma durumlarına
göndermeler yaptığının altını çizer. Buna kendini, kendi özgür bireysel alanını
korumayı da eklemek gerekir.
&quot;...Siz ey! kimliklerini maskelerine gömenler...&quot;
&quot;...başkalarını giyinmekle başlar cinnet...&quot;
&quot;...haydi gidin aynalara gömün maskelerinizi...&quot;
&quot;...kendinden başkasını kuşanma sakın
&quot;yol senin, iz senin, menzil senindir...&quot;
derken, ya da:
&quot;...fantazilerini koru,ölümü kolla,anılarını sakla...
ey ölüme hudut yaşayan, olmadı! tehlikeyi tekrarla...
hem bu kadar umutsuzken, mutsuz olunur mu hiç...&quot;
derken neyi önermektedir Mungan, buna bakmak gerektiğini düşünmüşümdür hep.
Kalabalığın içinde erimiş, yenilmiştir. Kalabalıkla birlikte çıkılan yolun varıp
yenilgilere dayanacağını imletiyor Mungan ve kendi çözümünü dayatıyor. Tam da bu
noktada emir kipleri giriyor devreye ve okurla birlikte çoğalıyor yazdıkları.
&quot;...ya dışındasındır çemberin
ya da içinde yer alacaksın...&quot;
Yani, mutluluklar yoksa da mutsuzlukları azaltmanın formülü: kendini
saklayacaksın, kalabalıkların maskeli balolarında asla soyunmayacaksın.
Geçmişinin ve anılarının oluşturduğu değerli dünyana yalnızca incitmeyenleri
alacaksın, dışarıdaki kaba kalabalığın yaptıklarını önemsemeyeceksin. Var
olduğun dünyada, en az incinmenin yolu bu....
Sonuçta, masallarla, efsanelerle, özlemlerle, yanılgılarla, yenilgilerle
dolu bir dünyanın kapısından içeri sokuyor bizleri. Yazdıkları kimi zaman
dağınık, kimi zaman oldukça özenli; ama hep kendini gizleyen bireyin formüle
edilmiş aşkları, yalnızlıkları... &quot; Yaşam seni çok mu incitti Murathan?&quot; diye
seslenmek geliyor kimi zaman içimden. Mungan’ı çok seveceksiniz, bundan eminim;
ama bir intihar yelkenlisinde yolculuk yapmak istemiyorsanız dikkatli okumak
zorundasınız!
Kimi zaman, neden bu kadar çok yazdığını düşünürüm Mungan’ın. Yazdıklarını
bekleyenleri bekletmeme kaygısı diyorum kimileyin... Bekleyenlerini yitirme
kaygısı ya da. O artık bir peygamber gibi sürekli yazmak zorunda. Yazdıkları ile
sürekli olarak kendini çoğalta çoğalta, formüle edilmiş kelimelerin yerleri ile
oynayarak bunu yapıyor artık. “Başkalarının gecesinde’’ yem olan yaşamlar,
ıskalanışlar, haksızlığa uğrayışlar çok yakın duruyor bir yanı doğulu, kente
uyumsuz bireylerde; o artık bu şiiri yazmak ve sürdürmek zorunda. Çünkü böylesi
bir dünya içine soktuğu, emirlerle yönlendirdiği kitleler onunla acı çekiyor,
kendini soyutluyor ve yeni emirler için çok uzun zaman beklemeyecek kadar
sabırsız artık.
Yetenekli ve zeki bir şair/yazar Mungan. Oluşturduğu kültün peşinde mi
yazıyor, kült mü Mungan’a yazdırıyor, Mungan kurduğu dünyanın devamını mı
tamamlıyor, bu açık değil. Bundan sonra ne mi olacak, ben de merak etmiyor
değilim hani.
“...Bazı sözler karanlıkta söylenir diyorum uykularımın birinde bazı sözler
hiçbir zaman...” Söylediklerini biliyoruz da söylemediklerinin ne olduğu ya da
söyleyecek sözünün kalıp kalmadığını bilmiyoruz. “...Sonuna dek proleteryanın
yanındayız / çünkü biliyoruz ki –biz devrim mecburları – hiçbir yere kaçamayız /
bir yere kaçamayız / kaçamayız...” Bana öyle geliyor ki Mungan, sol gösterip
sağı iyi vuruyor. Detaylı bir incelemeden geçme çizgisinden sürekli uzaklaşıyor,
çünkü sürekli yazıyor yazıyor. Şimdiden yirmiyi geçti kitaplarının sayısı.
Her
yeni aşkta ‘kendini temize çeken aşkların’ şairini, ne çevre kirliliği, ne
emek/sermaye çelişkisi, ne kıstırılan köleci yaşam o kadar ilgilendirmiyor. Bir
geri hizmet işçisi; ama işini gerçekten iyi yapıyor. Ne olursanız olun, nasıl
düşünürseniz düşünün, kaygılarınız, sevinçleriniz, hüzünleriniz, kimliğiniz ne
olursa olsun, Mungan’da çok şey bulacaksınız; metafizik ve kendi içinde tutarlı', 'Bir Anlatı Denemesi Selçuk YAMEN / Seyirdefteri Yaşantısı arabada geçenlerin, kimi şeyleri kaçırdığını düşünürüm sıklıkla. Bu, benim için de...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yamen']::text[], 8.5, '{"poet":"Selçuk Yamen","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":106}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇİN ASKERİ AH DEVRAN', 'ci-n-askeri-ah-devran-egemen-berkoz-tmt60', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçim. Yeşil sarı ovada
İlkyaz selleri, gecenin
hüznü olur ve sığmaz, sığmaz
odama. İçim. Binlerce
hasır şapka, güneş
yakar ve divan sazı kırmızı şarap.
Türkümü söyler. İçim.
Benim türkümü söyler.
Karanlığı deler kırmızı. Yanar
toprak yanar toprak
sigaramın ucunda
karanlığı deler kırmızı.
Hoşça kal
derim günışığına. Gecem
benim gecem başlar, yağmuru
ve Vivaldiyi gecem
alır gelir. Susarım. Şiir yazarım.
Karanlığı deler kırmızı
sigaramın ucunda, yanar ellerin
yanar toprak ve alnım.
İçim. Dereboyunda çocuklar
çılgın çocuklar dereboyunda
ben uzağın türküsünü söylerim
döner devran ve binlerce
olur ah çocuk olur içim.
İçim. Ezgilenir.
Hoşça kal
derim yağmura ve sana
karanlığı deler kırmızı
sigaramın ucunda, yanar ellerin
yanar toprak ve alnım.
İçim. Çin askeri uzağı
ben uzağı bilirim. Bilirim.', 'İçim. Yeşil sarı ovada İlkyaz selleri, gecenin hüznü olur ve sığmaz, sığmaz odama. İçim. Binlerce hasır şapka, güneş yakar ve divan sazı kır...', ARRAY['Türk Edebiyatı','Şiir','Egemen Berköz']::text[], 8.5, '{"poet":"Egemen Berköz","poet_slug":"egemen_berkoz","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİN', 'i-ci-n-veysel-colak-k2y23', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir gecede yokum, artık bilemem
uykularını kırdığın yeri, ışığın karanlık
gözlerin kül içinde, bir yasemin gömülü
kalbinin arkasına, dağları çizen bir ayrılık kokusu
sonra sen, yırtılan yerlerinden görünen yüzüm
daha ne olsun, her gündür ah, acıyla biten
Genç ölümlerin biçtiği gizem, çocukluğundan beri
biriktirdiğin çığlık; toprağın öfkeli, ağzın çamur
kent uyanıyor, gerinerek yalnızlık. Gövdesi kör,
sesi mazot tadında, günleri kan çanağı, yalanı gölgeli
seninle yarılan gökyüzü ve yeşeren boynun... Kalbin
var olacak inlemekle, artık boğulan bir sestin, terden
doğmuştun, o günden sonradır
kasabaları gürültü basar;
zaman denilen yanılgı, zaman denilen rüzgâr
dünyaya inat, sen için için göğsünde çocuklar oynat
Açılan bir çiçek gördüğünde
yumuldun, yüzünü karıştıran turaç sürüsü
işte o, boşluğun; işte o, hayatın, işte o senin olan
ısırgan gizem. Bu uzaklık böyle ne kadar diken
üstüne basıp kaçtın seni çağıran ömrün
aldattın şarkılarını, şaşıran kuşlar biriktirdin dünyaya
bağırarak eksildin ama ne zaman düşlesek seni
dumandı için, bulanıktı denizin
gene de bizimdi
kimsesizliğin.
Bir alan edin kendine, bir dağ arkası
gürültüyle yürüyen adamlar göğsüne itsin seni
ellerinde üşüyen demir, öksüren yaşamaklar
aşkla kırılan kemençeler ve ilk anlam, bana açılan
için.', 'Hiçbir gecede yokum, artık bilemem uykularını kırdığın yeri, ışığın karanlık gözlerin kül içinde, bir yasemin gömülü kalbinin arkasına, dağl...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel_colak","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NABIZ', 'nabiz-enis-batur-azjfs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '"Ben ölümün teğmeniyim", diyordu
sonradan postalanan mektubunda,
BM''nin 25 Şubat tarihli müzakeresini
esas alan Güvenlik Konseyi''nin
bindörtyüzellibir sayılı kararına dayalı
biçimde altı gün önce bölgeye gönderilen
tabur sembolik bir nitelik taşıyacaktı
şehrin hemen dışındaki tampon bölgede,
miğferi iyice sıkışmış kulağıyla boynu
arasında sımsıkı sızı - onca kararlı
parmağın tetikten yolladığı top mermisi
arasında kimse bilemez artık gerçekten
serseri bir kurşun mu sessizliği delen,
zihninin tam dibinde, son, gelmeden
genzinden göğsüne yayılan şarabın kanı,
"teğmenim öldü", diyor nabzı bekleyen
çocuk yüzlü asker.', '"Ben ölümün teğmeniyim", diyordu sonradan postalanan mektubunda, BM''nin 25 Şubat tarihli müzakeresini esas alan Güvenlik Konseyi''nin bindört...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNADIN GÜZELİ', 'i-nadin-guzeli-mustak-erenus-8h916', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuzguncukta nenemin evi
Nazarlığı yumurtadan çiçekler
Telaş toplardı nenemin elleri
Şeftali yemiş kardeşim
Ağzı pembe bulaşık
Ben daha oynayacağım derdi.
Bazen insanın aklına gelmiyor değil
Hani gidip de şöyle
Gül fesliğen olup dönmek diyorum
Yok öyle yağma şey
Güzelim umutlar içindeyim bu dünyada
Yaşayacağım diyorum.', 'Kuzguncukta nenemin evi Nazarlığı yumurtadan çiçekler Telaş toplardı nenemin elleri Şeftali yemiş kardeşim Ağzı pembe bulaşık Ben daha oynay...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NAGAZAKİ''DE YAĞMUR', 'nagazaki-de-yagmur-i-lya-ehrenburg-hrji1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur volta vuruyor Nagazaki''de, sinirli, öfkeli
Küçük kız korku içinde tutuyor elinde kör bir oyuncak bebeği
İstenmeyen bir yağmur bu, ağaçlar hoşlanmıyor ondan
Vişneler çiçekte, başlamış bile çiçek dökümü.
Külle karışık bir yağmur bu, sessiz ölümle dolu bir yağmur
Kör olmuş oyuncak bebek, küçük kız da kör olacak yarın
Zehir yapılacak bir çocuk tabutunun tahtasından
Tasa ve uzun süren kötülükten baharat yapılacak
Kötülük yağmur gibidir, kaçıp gizlenmek olanaksız ondan
Balıklar çıldırıyor, gökten yere düşüyor kuşlar
Güvercinler karga sesi çıkarmaya başlayacak birazdan
Suskun sazan balıkları birbirlerini ısırmaya ve ulumaya başlayacaklar
Kır çiçekleri dişlerini geçirecek etine insanların
Hava inleyecek göğüste, yüreği emecek, kemirecek
Bu yağmur gibi kötülüğe de dayanmaya gücü yok artık Nagazaki''nin
Senin ölmene göz yummayacağız Nagazaki!
Ey uzak, yeşil ve sakin kentlerin parklarındaki çocuklar
Bir şeye inanmak ya da inanmamak değil artık burada söz konusu olan
En yalın anlamıyla insan yaşamıdır söz konusu olan burada
Dinsin bu yağmur, vişnelere yağmasın bir daha...
1957
İlya EHRENBURG', 'Yağmur volta vuruyor Nagazaki''de, sinirli, öfkeli Küçük kız korku içinde tutuyor elinde kör bir oyuncak bebeği İstenmeyen bir yağmur bu, ağa...', ARRAY['Türk Edebiyatı','Şiir','İlya Ehrenburg']::text[], 8.5, '{"poet":"İlya Ehrenburg","poet_slug":"ilya_ehrenburg","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NALBANT', 'nalbant-seamus-heaney-jx7hq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tek bildiğim karanlığa açılan bir kapı.
Dışarda, eski dingiller, paslanan demir çemberler;
İçerde, dövülen örsün kesik çınlayışları,
Şaşırtıcı yelpaze kuyruğu kıvılcımların
Ya da su verildikçe sertleşen nalın çıkardığı ıslık.
Ortada bir yerde olmalı örs,
Bir ucu dört köşe, öbür ucu tek boynuzlu bir hayvan,
Çakılı duruyor orda: önünde, nalbantın
Biçimi ve müziğiyle büyüdüğü bir sunak.
Bazan, deriden önlüğü, kıllı burnuyla
Kapının pervazına yaslanıp hızla akan trafikte
Toynakların çıkardığı sesleri hatırlıyor,
Sonra hırsla gerçek demiri dövmek
Ve ateşi körüklemek için içeri giriyor homurdanarak.
Seamus HEANEY', 'Tek bildiğim karanlığa açılan bir kapı. Dışarda, eski dingiller, paslanan demir çemberler; İçerde, dövülen örsün kesik çınlayışları, Şaşırtı...', ARRAY['Türk Edebiyatı','Şiir','Seamus Heaney']::text[], 8.5, '{"poet":"Seamus Heaney","poet_slug":"seamus_heaney","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NALINCI', 'nalinci-mile-verhaeren-7ydvk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuklar okuldan çıkar şen şatır
Çılgın sürüsünü hatırlatır
Bir şıkırtıdır gider kaldırım kaldırım
Ah siyah nalın! Vah beyaz nalın!
-Gidin piç kuruları şamatayı kesin
Ortalıkta böyle gürültü etmeyin
Hele can alıp verirken komşuda, yağız
Ölüm döşeğinde bir adamcağız.
-Söylenip durma öyle kadın kişi
Kanadın açmak üzere can kuşu
Şıkırdasın bırak kaldırım kaldırım
Ah siyah nalın! Vah beyaz nalın!
Dinlerim uzaktan halka halka olmuşlar
Devranla ruhumla bir döner dururlar
Şıkırdasın bırak kaldırım kaldırım
Ah siyah nalın! Vah beyaz nalın!
Émile VERHAEREN', 'Çocuklar okuldan çıkar şen şatır Çılgın sürüsünü hatırlatır Bir şıkırtıdır gider kaldırım kaldırım Ah siyah nalın! Vah beyaz nalın! -Gidin p...', ARRAY['Türk Edebiyatı','Şiir','Émile Verhaeren']::text[], 8.5, '{"poet":"Émile Verhaeren","poet_slug":"emile_verhaeren","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NAMLANIŞ DESTANI', 'namlanis-destani-umut-taydas-dwfd9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '"ayrılıklara"
boş boş dururken manzara olsun diye yaratmak kolay,
ve yarattığınla gururlanmak,
oturduğun yerden anlatmak kendini, kurallar koymak,
kader belirlemek kolay,
çağrışımlarını şekle bürümek an meselesi,
çaresizlik, iki ucu boklu değnekle uğraşmak nedir bilmezsin;
sözler savurmak, itaate zorlamak, vaadetmek işten değil,
tatmadın,
senin annen ağlamıyor sana,
kurşunlar geçmiyor başının üzerinden,
özlemiyorsun çocukluğunu, babanın yaşlanışını görmüyorsun,
kardeşlerini öldürmüyor bu zorba hayat,
dostlarını yolcetmiyorsun bilinmezlere,
ellerin buz değil, titremiyorsun, çalışmaktan öte
gözlerin kanamıyor uykusuzluktan,
ağlamayı saklamaya çalışmak, hıçkırığını bastırmak nasıl zor,
yaşamadın,
tahtına kurulup, yormadan kendini,
gerinerek, güvenerek sesinin şahlığına,
kaynağı belli olmayan, sınırsız gücünün şehvetiyle
ahkâm kesmek kolay;
kolay "çarpmak" beni,
sefil görmek yarattıklarını, dedikodusunu yapmak,
sınırlamak, ensesine tokat, kaderine sille, aklına ziyan vurmak
mesele değil,
şimdi bunlar olurken,
biz, bu "değmez" oyuncaklar, cebelleşir didinirken,
istemediğimiz halde insan olmakla yargılanıp,
ne menem olduğunu yaşamadan bilemeyeceğin,
hayat illetiyle yorulur, tüketilir, denenirken,
aklımıza yazdığın cennet-cehennem ikileminde,
gidip geldikçe, hiç oluyorken yaşlarımız,
eserin, patlayan ütopyalar emdikçe direncimizi,
senin de bunları hissetmeni, bunlara dayanmanı,
biz olmanı istiyorum,
çaresizliği, güçsüzlük ebedi hastalığıyken insanlığımızın,
güçlü olmaya çalışmanın ne demek olduğunu,
imkânsızlıklar dehlizinde yitirirken tüm varlığı,
kahretmenin, isyanın, utancın, beklemenin, uykunun,
hiç bir işe yaramayacağını bilmenin ıstırabını,
yoksulluğu, sessizliği, yorgunluğu, hiçliği,
görmeni istiyorum,
sana bunları yazmak nafileliğiyle,
bunları yazmaya gelirken geçilen dermansızlıklarla,
karşılaşmanı...
en neticesinde, hepsini geçtim,
hepsini bitirdim,
aşık olmanı istiyorum tanrı''m,
"ayrılık" bukağı ne çetrefil,
hiç olan arzular neye kadir,
katlanmak, çekmek, kabullenmek,
sevdiklerini kaybetmek,
tanrı''nın yalnızlığının acısını,
senden çıkarmasına boyun eğmek ne demek
görmeni istiyorum...
20.12.00 - 21:38
"yer serildi uçsuz bucaksız, insanoğlu serpildi üzerine, gökle örtüldü üstü, bazı canlılar da garnitür olsun, afiyet olsun"', '"ayrılıklara" boş boş dururken manzara olsun diye yaratmak kolay, ve yarattığınla gururlanmak, oturduğun yerden anlatmak kendini, kurallar k...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":60}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NİŞAN', 'ni-san-aydin-hati-poglu-k48p0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Suların uzak denizlere vardığı yerde
Uçsuz zamanlar çiçeği
Lanetli zakkum
Sağıyor yitirilmiş maviyi ıtırlardan
Yüzüm bulutlara boyanıyor
Ey çocuk aklım
Savruk bir yağmur sonrası
İçe kapanış
Duyarsızlığı sürüyor üstümüze
Sekerek bir küfürden geçiyor pırıltısı
Ne yağmur duyuyor sesi
Ne pencereler
Her şey yarım yamalak
Yarım yamalak sevi
Bir kadın köpeğini salıyor özgürlüğe
Koşup bütün zamanlara sığıyor sevincini
Gizemli perdeler sarmalıyor evi
Tanığımdır yaşlı çam
Sarmaşık sömürgesi
Hayatı savunan nefesin nefesimde
Bir sese nişanlıyorum solgun bir sesi
Yalnızlık bakıyor aynadaki resimde', 'Suların uzak denizlere vardığı yerde Uçsuz zamanlar çiçeği Lanetli zakkum Sağıyor yitirilmiş maviyi ıtırlardan Yüzüm bulutlara boyanıyor Ey ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNANÇLI BİR SAVAŞÇININ TÜRKÜSÜ', 'i-nancli-bi-r-savascinin-turkusu-afsar-ti-muci-n-142sr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kendimi hiç akşam olmayacak
Bir gün doğumu için saklıyorum
Kendime kendim olmamayı yasaklıyorum
Yasak artık bana çaresiz kalmak
Yasak bana bocalamak
Olmayanda eriyip gitmek yasak bana
Yasak bana geceysem gündüzmüşüm gibi
Bir gül pembeliğinde kendimi uyumak
Zor bir şeyi umduğumu biliyorum
Yasak bana tükenmişi korumak
Her çeşit umutsuzluk yasak bana
Durmuşum umudumu sürdürüyorum
Bir ağaç altında göğü seyrediyorum
İçimde ne ölüm ne yaşam korkusu var
Korku bütün yasak bana yasak bana bitmişlik
Bütün yol kavşaklarında dönemeçlerde
Kendimi bir namlu gibi dosdoğru çiziyorum.', 'Kendimi hiç akşam olmayacak Bir gün doğumu için saklıyorum Kendime kendim olmamayı yasaklıyorum Yasak artık bana çaresiz kalmak Yasak bana b...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NARA BENZERDİN', 'nara-benzerdi-n-oktay-ri-fat-horozcu-p36pn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nara benzerdin bir zamanlar, çoktun! N''oldu
Sana! Kırk atlı çıkardın dağa, yüz atlı
İnerdin dağdan. Kurşun bitmez tabancanda,
Atın şahlanır, kırbacın ıslık çalardı.
Miçoydun isteyince, kaptandın, korsandın;
Martıydı, buluttu, engindi yamacında.
Şarap fıçılarına yaslanır limanda,
Doğudan batıya usulca kayıp giden
Mavna dizilerine bakardın Zaman''ın.
Avcıydın, eski taşlara sinmiş günleri,
Tavşan yakalar gibi, çeker çıkarırdın
Kulağından. Bizans surları doruğundan
Bir Osmanlı vakti düşerdi ellerine.
Aşınmış tahtalara sürerdin yüzünü.
Hani paslı kancalarla çiviler! N''oldu
Damında kediler sevişen ev, rüzgârın
Tuzlu tüylerini döktüğü arka sokak!
Yitirdi çoktan düşlerindeki çocuklar,
Kumsala çekilmiş ölü kayıklar gibi,
Gecesiz gözlerinde yeşil ya da mavi
Bir güneşe benzer o öfkeyi! Kırıldı
İnce belli bardaklar. Küpeçiçekleri
Kavruldu gitti tozlu camların ardında.
Kenar semtleri İstanbul''un! Sisli, ılık
İlkyaz günleri! Cumbalar, şahnişler! Kızın
Yüzü, atın boynu, arabanın dingili
Bir kahve peykesinde verirdi kendini.
Duvar sürüp gider sessizliğin boyunca.
Ordan bir perdenin gülü, burdan bir zakkum
Dalı, sevinçler, aşklar toplardın torbana.
Üstüne serçe sürüsü inmiş, o mutlu
Ağaca benzerdin, deniz kokan yollarda
Şiirler düştü mü aklına! N''oldu sana!
Boşaldın, susuz değirmene döndün şimdi!', 'Nara benzerdin bir zamanlar, çoktun! N''oldu Sana! Kırk atlı çıkardın dağa, yüz atlı İnerdin dağdan. Kurşun bitmez tabancanda, Atın şahlanır,...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NÖBETÇİNİN ÖĞÜDÜ', 'nobetci-ni-n-ogudu-ren-char-u91or', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bıçaktan fışkıran meyve,
Tadı yankı olan güzellik,
Kerpeten ağızlı tansökümü,
Dağıtılmak istenen sevgililer,
Önlük takınmış kadın,
Surları tırmalayan tırnak,
Arazi olun! Arazi olun!
René CHAR', 'Bıçaktan fışkıran meyve, Tadı yankı olan güzellik, Kerpeten ağızlı tansökümü, Dağıtılmak istenen sevgililer, Önlük takınmış kadın, Surları t...', ARRAY['Türk Edebiyatı','Şiir','René Char']::text[], 8.5, '{"poet":"René Char","poet_slug":"rene_char","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜÇÜNCÜ ŞAHSIN ŞİİRİ', 'ucuncu-sahsin-si-i-ri-attila-i-lhan-dfkuw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözlerin gözlerime değince
felâketim olurdu ağlardım
beni sevmiyordun bilirdim
bir sevdiğin vardı duyardım
çöp gibi bir oğlan ipince
hayırsızın biriydi fikrimce
ne vakit karşımda görsem
öldüreceğimden korkardım
felâketim olurdu ağlardım
ne vakit maçka''dan geçsem
limanda hep gemiler olurdu
ağaçlar kuş gibi gülerdi
bir rüzgâr aklımı alırdı
sessizce bir cıgara yakardın
parmaklarımın ucunu yakardın
kirpiklerini eğerdin bakardın
üşürdüm içim ürperirdi
felâketim olurdu ağlardım
akşamlar bir roman gibi biterdi
jezabel kan içinde yatardı
limandan bir gemi giderdi
sen kalkıp ona giderdin
benzin mum gibi giderdin
sabaha kadar kalırdın
hayırsızın biriydi fikrimce
güldü mü cenazeye benzerdi
hele seni kollarına aldı mı
felâketim olurdu ağlardım', 'gözlerin gözlerime değince felâketim olurdu ağlardım beni sevmiyordun bilirdim bir sevdiğin vardı duyardım çöp gibi bir oğlan ipince hayırsı...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNCE BİR HANÇER', 'i-nce-bi-r-hancer-ahmet-uysal-ssplu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Issız bozkırda usul esen
yaz yelidir hançer
Bütün eski kalıtların yanılmaz
belleğidir hançer
Ayrı kalınca kınından yitik
gümüş kabzasıyla
Zaman içinde çürüyüp gidecek
eğri demirdir hançer
Yıkım günlerinde odur öfkeli
imgesi şairlerin
Pul pul döker pasını birden
umutla devinir hançer
Ay ışığını sever ne de olsa
gecenin dostudur
En çok bir kadın koynundaysa
sevinir hançer
Islak bir parıltı ya da kan
izi bırakır ardında
Yasak sevişmelerin ölümcül
bedelidir hançer
Ne zaman kaygan bir kın
içinde düşünsem onu
Şiirin ipeksi dokusuyla
kendine bilenir hançer', 'Issız bozkırda usul esen yaz yelidir hançer Bütün eski kalıtların yanılmaz belleğidir hançer Ayrı kalınca kınından yitik gümüş kabzasıyla Za...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNCE BİR SIZIYLA UYANIYORUM', 'i-nce-bi-r-siziyla-uyaniyorum-ender-sariyati-6e4kj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidelim.
bizi çağıran gündüze
dağları, denizleri,
ve bir heybeyi ceket yaparak,
Gidelim.
O anamdı, ip eğirmesini bilirdi.
bir merakı yenemeyerek, sinemalarda
geçen güz öldü.
sırtında,
Pirinçlerin ve pancarların suladığı bir kol
Neler düşündürdü bunca yıl
bir ezikliği alıp içimden
neler düşündürdü
Kılıfından çıkan bir geceyi susturan
ferman.
artık büyüdüm.
işte geçiyorum,
tütün mağazalarının açtığı devirden
elimde iş bulma ilanları
Üzümcüler,
Yemişçiler.
Fabrikatörlerden dev bir soluğu yırtarak
geçiyorum.
yıllarca penceremi örten o büyük karları.
işte geçiyorum,
yüreğimdeki korkuyu yırtarak
elimde ahlat ve ardıçlardan bir silah
yüksek bir tepeden doyarak
elimde sigaram,
Bir gün keyifle çekeceğim,
ölümün çizdiği gül resimlerinden
gövdem.
Bunca yılın çakısıyla vurduğu
Göz yaşlarımdan bir ırmağı,
akıtarak avuçlarıma
ağladığımı, ama niçin
kimse sormadı...
sevincim defnedilmesi güç bir ölü
işte geçiyorum
korkuyu bir ter yaparak avuçlarıma
dağları ve denizleri
göğü dolduran sesimle
varım.
yüreğimde ince bir sızı
ölüm sancılı anam
Sevinçten bir tülbentle sarıyor yaramı
VARIM......', 'Gidelim. bizi çağıran gündüze dağları, denizleri, ve bir heybeyi ceket yaparak, Gidelim. O anamdı, ip eğirmesini bilirdi. bir merakı yenemey...', ARRAY['Türk Edebiyatı','Şiir','Ender Sariyati']::text[], 8.5, '{"poet":"Ender Sariyati","poet_slug":"ender_sariyati","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNCE ELEK', 'i-nce-elek-metin-eloglu-zrjcu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçtikçe içesim geliyor gayrı ne bilgi ara ne hüner
Beni bu rakıyla baş başa bırakma
Adam olayım çalışıp para kazanayım
Beni böyle işsiz güçsüz bırakma
Beni uslandır beni yüreklendir
Beni deli edip bırakma
Bilsen nereleri var kalk gidelim
Beni hep buralarda bırakma
Beni aç bırak evsiz urbasız bırak
Beni sensiz bırakma
Beni ne yap biliyor musun
Beni yont beni arıt beni ayıkla', 'İçtikçe içesim geliyor gayrı ne bilgi ara ne hüner Beni bu rakıyla baş başa bırakma Adam olayım çalışıp para kazanayım Beni böyle işsiz güçs...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin_eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNCECİKTEN BİR KAR YAĞAR', 'i-nceci-kten-bi-r-kar-yagar-karacaoglan-y1qdb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İncecikten bir kar yağar
Tozar Elif Elif diye
Deli gönül abdal olmuş
Gezer Elif Elif diye
Elif''in uğru nakışlı
Yavru balaban bakışlı
Yayla çiçeği kokuşlu
Kokar Elif Elif diye
Elif kaşlarını çatar
Gamzesi sineme batar
Ak elleri kalem tutar
Yazar Elif Elif diye
Evlerinin önü çardak
Elif''in elinde bardak
Sanki yeşil başlı ördek
Yüzer Elif Elif diye
Karac''oğlan eğmelerin
Gönül vermez değmelerin
İliklemiş düğmelerin
Çözer Elif Elif diye', 'İncecikten bir kar yağar Tozar Elif Elif diye Deli gönül abdal olmuş Gezer Elif Elif diye Elif''in uğru nakışlı Yavru balaban bakışlı Yayla ç...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NİCEDİR', 'ni-cedi-r-sukran-kurdakul-xf16a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nicedir soluğum rüzgârlıyor
Delinmiş yelkenleri.
Siz bana bakıyorsunuz,
Bırakıp ölenleri.', 'Nicedir soluğum rüzgârlıyor Delinmiş yelkenleri. Siz bana bakıyorsunuz, Bırakıp ölenleri....', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİNDE', 'i-ci-nde-vicente-huidobro-f4dmf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuşun yüreği
Kuşun içinde parlayan yürek
Gecenin yüreği
Kuşun gecesi
Gecenin yüreğinin kuşu
Gecenin içinde kaybolan göğün içinde
Göğün içinde kaybolan kuşun içinde
Kuşun içinde şakırsa gece
Söylerdim sana
Kuşun içinde parlar
Yüreğin içinde ne varsa
Göğün içinde kaybolan gece
Kuşun içinde kaybolan gök
Kuşun unutkanlığı içinde kaybolan kuş
Gecenin içinde kaybolan gece
Göğün içinde kaybolan gök
Ama yürek yüreğin yüreğidir
Yüreğin ağzından konuşur
Vicente  HUIDOBRO', 'Kuşun yüreği Kuşun içinde parlayan yürek Gecenin yüreği Kuşun gecesi Gecenin yüreğinin kuşu Gecenin içinde kaybolan göğün içinde Göğün içind...', ARRAY['Türk Edebiyatı','Şiir','Vicente  Huidobro']::text[], 8.5, '{"poet":"Vicente  Huidobro","poet_slug":"vicente_huidobro","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇİNDEN DOĞRU SEVDİM SENİ', 'i-ci-nden-dogru-sevdi-m-seni-edip-cansever-o7w43', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçinden doğru sevdim seni
Bakışlarından doğru sevdim de
Ağzındaki ıslaklığın buğusundan
Sesini yapan sözcüklerden sevdim bir de
Beni sevdiğin gibi sevdim seni
Kar bırakılmış karanlığından.
Yerleştir bu sevdayı her yerine
Yüzünde ter olan su damlacıklarının
Kaynağına yerleştir
Her zaman saklamadığın, acısızlığın son durağına
Gül taşıyan cocuğuna yerleştir
Ve omuzlarına daracık omuzlarına
Üşümüş gibisin de sanki azıcık öne taşırdığın
Tam oraya işte, uçsuz bucaksız bir düzlükten
Bir papatya tarlasıyla ayrılmış göğüslerine yerleştir
Ve esmerliğine bir de, eski bir yangının izlerinin renginde
Saçlarının yana düşüşüne, onları bölen ikiliğe
Alnından başlayan ve ayak bileklerinde duran
Yani senin olmayan, seni bir boşluk gibi saran hüzne Yerleştir onu bir kentin parça parça aklında tuttuğun
Kar taneleri gibi uçuşan
Ve her gün biraz daha hafifleyen semtlerine
Yerleştir bu sevdayı her yerine.
Ekledim ben tattığım her şeyi denizlere
Bildiğim ne varsa onlar da hep denizlerden
Sen de bir deniz gibi yerleştir onu istersen
Sevdayı
Ve köpüklendir
Ve yaşlandır ki işte kederi anlamasın
Ama dur, her deniz yaşlıdır zaten
Öğrenmez ama öğretir mutluluğu
Bizim sevdamız da öyledir, iyi şiirler gibi
Biraz da herkes içindir. Ve gelinciğin ikinci tadına benzemeli
Var eden kendini birincisinden
Yani bir sevdayı sevgiye dönüştüren.
Ben şimdi bir yabancı gibi gülümseyen
Tanımadığın bir ülke gibi
İçinde yaşamadığın bir zaman gibi
Tam kendisi gibi mutluluğun
Beni bekliyorsun
Ve onu bekliyorsun beni beklerken.', 'İçinden doğru sevdim seni Bakışlarından doğru sevdim de Ağzındaki ıslaklığın buğusundan Sesini yapan sözcüklerden sevdim bir de Beni sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip_cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖNDEYİŞ', 'ondeyi-s-metin-altiok-wovk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bedenim üşür, yüreğim sızlar.
Ah kavaklar, kavaklar...
Beni hoyrat bir makasla
Eski bir fotoğraftan oydular.
Orda kaldı yanağımın yarısı,
Kendini boşlukla tamamlar.
Omuzumda bir kesik el,
Ki durmadan kanar.
Ah kavaklar, kavaklar...
Acı düştü peşime ardımdan ıslık çalar.', 'Bedenim üşür, yüreğim sızlar. Ah kavaklar, kavaklar... Beni hoyrat bir makasla Eski bir fotoğraftan oydular. Orda kaldı yanağımın yarısı, Ke...', ARRAY['Türk Edebiyatı','Şiir','Metin Altiok']::text[], 8.5, '{"poet":"Metin Altiok","poet_slug":"metin_altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE ANLATIR YUNAN ŞARKILARI', 'ne-anlatir-yunan-sarkilari-ataol-behramoglu-6uis8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne anlatır Yunan
şarkıları
Geceye dair, aşka dair
Ne anlatır Yunan şarkıları
Hayatımıza dair
Ne anlatır Yunan şarkıları
İnsanı tepeden tırnağa saran bu hüzünle
Sanki hep anlatılmayan bir şey kalmıştır
İçimizi ne kadar döksek de
Ne anlatır Yunan şarkıları
Biten bir aşk mı, başlayan bir aşk mı
Bir kız mı, yüzünü hiç görmeyeceğimiz
Çayırlarına hiç uzanamayacağımız kırlar mı
Ne anlatır Yunan şarkıları
Bu sürekli, bu yumuşak ısrarla
Ne anlatır Yunan şarkıları
Yüreğimize işleyen tempolarla
Ne anlatır Yunan şarkıları
Sonsuzluğa güzelliğe, sonsuz barışa dair
Acılarla dolsak da ne kadar
Sımsıcak yaşamaya dair
Ne anlatır Yunan şarkıları
Bir gün birleşeceğini mi bütün şarkıların
Ne anlatır Yunan şarkıları
Bu kadar uzak...ve bu kadar yakın', 'Ne anlatır Yunan şarkıları Geceye dair, aşka dair Ne anlatır Yunan şarkıları Hayatımıza dair Ne anlatır Yunan şarkıları İnsanı tepeden tırna...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol_behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE BÖYLE SEVDALAR GÖRDÜM', 'ne-boyle-sevdalar-gordum-i-lhan-berk-rjyye', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '"NE BÖYLE SEVDALAR GÖRDÜM
NE BÖYLE AYRILIKLAR"
Ne zaman seni düşünsem
Bir ceylan su içmeye iner
Çayırları büyürken görürüm.
Her akşam seninle
Yeşil bir zeytin tanesi
Bir parça mavi deniz
Alır beni.
Seni düşündükçe
Gül dikiyorum elimin değdiği yere
Atlara su veriyorum
Daha bir seviyorum dağları.
Köroğlu', '"NE BÖYLE SEVDALAR GÖRDÜM NE BÖYLE AYRILIKLAR" Ne zaman seni düşünsem Bir ceylan su içmeye iner Çayırları büyürken görürüm. Her akşam seninl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE DELİYİM', 'ne-deli-yi-m-resul-hamzatov-shaaj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne deliyim ne körüm
Ne sağırım ne sayrı
Mutluyum kısacası
Ve hiçbir şey istedigim yok
Senden felek
Ama yine de
Ucuz olsun ekmek
Ve pahalı olsun insan hayatı
Resul HAMZATOV', 'Ne deliyim ne körüm Ne sağırım ne sayrı Mutluyum kısacası Ve hiçbir şey istedigim yok Senden felek Ama yine de Ucuz olsun ekmek Ve pahalı ol...', ARRAY['Türk Edebiyatı','Şiir','Resul Hamzatov']::text[], 8.5, '{"poet":"Resul Hamzatov","poet_slug":"resul_hamzatov","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE DESEM YALAN OLUR', 'ne-desem-yalan-olur-veysel-colak-zwrxv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyası olmamış, duyguları ayaklanmamış hiç
onunduk oysa, tutuşurduk; ama üşürdük gene.
Unutmak derin, seni düşünmek soğuk
gövdenin bir yanı yangın bir yanı su
yolunu çok sev, tenhalığına şaşır
dilini ov, sözünü parlat, anılara saygılı ol.
Bu senin sırtın, madem öyle
ellerine koş, alıp götüren rüzgârlara yaslan
düş gördüren bir hayat edin, unutma
en çok kim ölürse gelir kendini sorar
sen orada aranan mavileşen bir aşkla
ebette delirmeden o çınlayan boşlukta
aldatan uzaklıkta aşınıp durdun.
Uzunca susup birden kalkıp gitmeler var ya
ah o dalgınlıklar... Buruşur yalnızlık, saklanır gece
dağılır alnın, kan kesilir, daralır gövde
gökyüzü çatlar birden, bahçe yorulur ve sonra:
Yitirilen patika çok uzakta, çoğalır merak
taş yenilir, dağlar susar, paslanır o Sürmene bıçağı
ateş kendine iter sizi, ay küser arkadaşların gidişine
ayrılık boğar, cam patlar, toprakta çoğalır ses
gövdenize tırmanır öfke ve sonra
bulaşıcı bir aşkla ne desem yalan olur.', 'Dünyası olmamış, duyguları ayaklanmamış hiç onunduk oysa, tutuşurduk; ama üşürdük gene. Unutmak derin, seni düşünmek soğuk gövdenin bir yanı...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel_colak","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE GİTTİ NE KALDI', 'ne-gi-tti-ne-kaldi-c-a-kansu-n6jml', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'C. A. Kansu''nun anısına
Yaprak dökülür, omcalar soyunur
güz çimenleri yeşerir toprakta
bir asmada
bağbozumundan kalma bir salkımla karşılaşır insan
Ne gitti, ne kaldı
Tüm artıklar gitti
boyamalar, bezemeler, abartmalar gitti
bir küçük çeşme kaldı, bir bağ yolunda
güze bakan
Seni sordum dünyanın bütün çocuklarına
kuşlara, çiçeklere, ağaçlara seni sordum
seni çalıştım gün ağarırken, şafakla
bir ince şırıltı olup sabaha akmak için', 'C. A. Kansu''nun anısına Yaprak dökülür, omcalar soyunur güz çimenleri yeşerir toprakta bir asmada bağbozumundan kalma bir salkımla karşılaşı...', ARRAY['Türk Edebiyatı','Şiir','C. A. Kansu']::text[], 8.5, '{"poet":"C. A. Kansu","poet_slug":"adnan_azar","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE Kİ HİÇHaikular', 'ne-ki-hi-chaikular-oruc-aruoba-xhm0t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haikular
86.
Aceleyle gelip geçer Martı
oysa
biryere gitmez.
10 Kasım''94
Çiftehavuzlar
87.
Lodos geldi--
belirsiz:
hangisi Yaprak, hangisi Yağmur...
11 Kasım''94
Çiftehavuzlar
92.
Yeşil pencereler
sarı pencereler --
benimki, beyaz...
