INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE ÇOK', 'ne-cok-kucuk-iskender-w2gu4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni ne çok kedi tırmalamış anne
camlara baktım ordamısın hala
dün akşam haydutlar bıçaklamış bir karanfil
kaçamamış vurmuşlar ölememiş solmuş
seni ne çok iğfal etmişler anne
her yerin delik deşik
ağlayışın bile yamuk yumuk
bakışların kısık
ve bilhassa değişik
ne çok isyanlanmışım ne çok gitmemişim meğer
bağırdıkça etlenmiş sesim
etlenikçe sesim, kanamış elmas liğme liğme
seni ne çok öldürmüşler anne
beni ne çok dövmüşler
artık evlenelim anne hayata karşı
ve gel, beraber kaybedelim mor savaşı
benimle birlikte intahar et anne', 'Seni ne çok kedi tırmalamış anne camlara baktım ordamısın hala dün akşam haydutlar bıçaklamış bir karanfil kaçamamış vurmuşlar ölememiş solm...', ARRAY['Türk Edebiyatı','Şiir','Küçük Iskender']::text[], 8.5, '{"poet":"Küçük Iskender","poet_slug":"kucuk_iskender","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE RENK?', 'ne-renk-nicolas-guillen-1ncu6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derisi karaydı, ama kar kadar beyaz,
çok katıksız bir ruhu vardı.
Yevtuşenko, Martin Luther King''in
katledilmesinden sonra, bir telgrafta.
Öyle beyaz bir ruhu vardı ki, diyorlar
o soylu papazın.
Derisi öyle kara, diyorlar.
derisi o kadar kara renkliydi,
içerisi kar gibiydi ama,
beyaz bir zambak,
taze süt,
pamuk.
Öyle kirlenmemiş.
Tek bir leke yoktu,
kusursuzdu içi-dışı.
(Kısacası, güzel buluş:
"Ruhu beyaz olan zenci,"
oldukça çekici.)
Ama yine de başka biçimde söylenebilir:
Ne güçlü bir kara ruh
papaz ruhlarının en naziği.
Ne gururlu kara bir tutkuydu
onun yüreğinde yanan.
Ne katıksız kara düşünceler
yetişmişti onun verimli beyninde.
Ne kadar bir sevgiydi,
öyle, renk karıştırmadan,
gösterdiği.
Hem niye olmasın,
bu kahraman papaz niye
kara ruhlu biri olmasın?
Kömür gibi kara bir ruh hem de.
Nicolas  GUILLEN', 'Derisi karaydı, ama kar kadar beyaz, çok katıksız bir ruhu vardı. Yevtuşenko, Martin Luther King''in katledilmesinden sonra, bir telgrafta. Ö...', ARRAY['Türk Edebiyatı','Şiir','Nicolas  Guillen']::text[], 8.5, '{"poet":"Nicolas  Guillen","poet_slug":"nicolas_guillen","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE SÖZCÜKLERDEN SÖZ EDİYORUM', 'ne-sozcuklerden-soz-edi-yorum-pedro-tamen-jsmrr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'NE SÖZCÜKLERDEN SÖZ EDİYORUM,
NE DE GÜLLERDEN
Ne sözcüklerden söz ediyorum, ne de güllerden
boynuma bağlı saatlerden söz ediyorum.
Sevgili olabilmektir gerçek şiir:
meyveyi soyup çekirdeğini atabilmek,
her gün yüz yüze geldiğimiz o küçük ölümler
arasında, yarı bitkin yarı uyanık,
içimizdeki kuyuları ve çölleri çekip çıkaracak
o son ölüm çığlığını atmasını bilmek.
Bu yüzden sevgilim, sana verebildiğim,
parlak ve canlı bedenindeki o öpülmüş öpücük
daha anlamlıdır bütün o dizelerden,
bağlaçlarla vurgulardan, yinelemelerden.
Her şey ona bağlı, istesek de istemesek de,
Irmak yaratır şiiri, aynanın karşısında
Hayran hayran kendine bakmak değil,
İşte, bütün sözlerin ötesinde, yanı başımdasın sen.
Pedro  TAMEN', 'NE SÖZCÜKLERDEN SÖZ EDİYORUM, NE DE GÜLLERDEN Ne sözcüklerden söz ediyorum, ne de güllerden boynuma bağlı saatlerden söz ediyorum. Sevgili o...', ARRAY['Türk Edebiyatı','Şiir','Pedro  Tamen']::text[], 8.5, '{"poet":"Pedro  Tamen","poet_slug":"pedro%20tamen","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE TUHAF', 'ne-tuhaf-sabahattin-kudret-aksal-4hiel', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne tuhaf ömrümün sonuna kadar
Kelimelerle yaşamam.
