INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOĞALMAK', 'cogalmak-aziz-nesi-n-lrgpi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalabalıkta kalabalıkça yalnızlık
Yalnızladıkça birbirimizi
Haydi çoğalalım
Çoğaltarak kendimizi
Bir canım çoğal da bin can ol
Isıt yaşlıların yalnızlıklarını ilinsin üşümüşlüğü bırakılmışların
Çoğalın dudaklarım çoğalın sonsuz
Öpün bütün ağlayan çocukları kimsesiz
Çoğal gözlerim çoğal
Gör bütün görmeyenlerde yapayalnız
Ellerime tutunun ellerime çoğalın
Okşayın sevecenlikle çocukları
Hıçkırırlarken uykularında bile', 'Kalabalıkta kalabalıkça yalnızlık Yalnızladıkça birbirimizi Haydi çoğalalım Çoğaltarak kendimizi Bir canım çoğal da bin can ol Isıt yaşlılar...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOBAN ÇEŞMESİ', 'coban-cesmesi-faruk-nafiz-camlibel-2mal4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Derinden derine ırmaklar ağlar,
Uzaktan uzağa çoban çeşmesi,
Ey suyun sesinden anlıyan bağlar,
Ne söyler şu dağa çoban çeşmesi.
&quot;Göynünü Şirin''in aşkı sarınca
Yol almış hayatın ufuklarınca,
O hızla dağları Ferhat yarınca
Başlamış akmağa çoban çeşmesi...&quot;
O zaman başından aşkındı derdi,
Mermeri oyardı, taşı delerdi.
Kaç yanık yolcuya soğuk su verdi.
Değdi kaç dudağa çoban çeşmesi.
Vefasız Aslı''ya yol gösteren bu,
Kerem''in sazına cevap veren bu,
Kuruyan gözlere yaş gönderen bu...
Sızmadı toprağa çoban çeşmesi.
Leyla gelin oldu, Mecnun mezarda,
Bir susuz yolcu yok şimdi dağlarda,
Ateşten kızaran bir gül arar da,
Gezer bağdan bağa çoban çeşmesi,
Ne şair yaş döker, ne aşık ağlar,
Tarihe karıştı eski sevdalar.
Beyhude seslenir, beyhude çağlar,
Bir sola, bir sağa çoban çeşmesi...', 'Derinden derine ırmaklar ağlar, Uzaktan uzağa çoban çeşmesi, Ey suyun sesinden anlıyan bağlar, Ne söyler şu dağa çoban çeşmesi. &quot;Göynün...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlibel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlibel","poet_slug":"faruk_nafiz_camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOBAN MERYEM', 'coban-meryem-ali-yuce-qzliu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Havalı Meryem havalı
Gel hele gel hele gel
Almış eline kavalı
Çal hele çal hele çal
Sekili oğlak sekili
Ho gele ho gele ho
Gözleri sürme çekili
Ho gele ho gele ho
Sekili atım sekili
Dah gele dah gele dah
Alnına akmış kakili
Dah gele dah gele dah
Ak kuşlar kara kuşlar
Geh cücü geh cücü geh
Kar altında donmuşlar
Vah cücü vah cücü  vah', 'Havalı Meryem havalı Gel hele gel hele gel Almış eline kavalı Çal hele çal hele çal Sekili oğlak sekili Ho gele ho gele ho Gözleri sürme çek...', ARRAY['Türk Edebiyatı','Şiir','Ali  Yüce']::text[], 8.5, '{"poet":"Ali  Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOBAN TÜRKÜLERİ', 'coban-turkuleri-sureyya-berfe-0ar0g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '3.
Dağdan indimse kurt sanma beni
Soğuk vurdu inceldi boynum
Yükseklere çıktım küçüldü yaşım
Ay karanlık gel beri
Dudağından emzir beni
Şu dağın başı da kar ile boran
Emmimin sözleri tümüyle yalan
Ölür mü dünyada dengini saran
Ay karanlık gel beri
Dudağından emzir beni
Ben ta ezelden yangınım sana
Tomurcuk memeler koktu burnuma
Gül döşenmiş şalvarının ağına
Ay karanlık gel beri
Dudağından emzir beni
Köyümü özledim görmeğe geldim
Ağzının içini öpmeğe geldim
Yorganı üstünden atmaya geldim
Ay karanlık gel beri
Dudağından emzir beni
Gün gelecek çıkacağım dağlara
Belki yem olacağım canavarlara
Kanım karışacak yayla toprağına
Dökmeli donlum gel beri
Dudağından emzir beni', '3. Dağdan indimse kurt sanma beni Soğuk vurdu inceldi boynum Yükseklere çıktım küçüldü yaşım Ay karanlık gel beri Dudağından emzir beni Şu d...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOBANIL', 'cobanil-ali-puskulluoglu-q6a05', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey tarlakuşlarının titreşip durduğu masmavi geniş alan,
Güz geldi mi çiylerle ıslanan kırlar,
Ey kül renkli ve iyi niyetli gökyüzü!
Bulutlarını yola çıkar
Ve kurşuni bir sessizliğe boğ toprağı.
Yine de
Ve yalnızca
İpince
Bir yolda, uzak bir çavlanın sesiyle gürle.
Bir adam soruyor bana: Ata binmeyi unutmadın ya?
Bir dağ doruğu gibiydi, karlı
Ve çığ salacak,
Sonsuz, diri fırtınalarla yüklü
Tepelerde, otların üstünde ilk kar
Ve sevdiğim şıvgacık fidan, yolun üstünde.
Güz yeliyle savrulup duruyor
Ve toprağa
İyice
Yaslanıyor, dökülüyor yaprakları, güzle.
Bir adam soruyor bana: Ata binmeyi unutmadın ya?
Kim bilebilir, bir tek ağaç bile olmazsa
O eski, sonsuz ormanı? Sular
Oluklardan teknelere dökülse de.
Atlar
Yeni bir koşu tuttursa da.
Kim durdurabilir düşleri, ey gece
Gözler
Açık olsa da?
İşte yanıtım:
Ey tarlakuşlarının titreşip durduğu masmavi geniş alan', 'Ey tarlakuşlarının titreşip durduğu masmavi geniş alan, Güz geldi mi çiylerle ıslanan kırlar, Ey kül renkli ve iyi niyetli gökyüzü! Bulutlar...', ARRAY['Türk Edebiyatı','Şiir','Ali̇ Püsküllüoğlu']::text[], 8.5, '{"poet":"Ali̇ Püsküllüoğlu","poet_slug":"ali_puskulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OCAK KATIRI ALAGÖZ', 'ocak-katiri-alagoz-rifat-ilgaz-xaxj6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Pelit ovasında,
Nanepınar''da bir ocak…
Taştan değil,
Tuğladan değil,
Dört duvarı taşkömür,
Tabanıysa çamur, çökek…
Kaya kömür, taşkömür,
Nanepınar, dağ, taş kömür,
Kara toprak, kara elmas…
Yüz yirmi beş kara amele
Kömür karası yüz, göz…
Kiminde kazma, kiminde kürek,
Sökebilirsen, sök!
İster Lâver(*) lerde yıka,
İster kok''a çevir fabrikasında,
İstersen maltızında yak!
Bir ocak, Pelitovası''nda
Bir uçtan bir uca dekovil,
Vagonlar salkım saçak…
Tek başına
Çeker götürür vagonları, Alagöz!
At değil, eşek değil,
Alagöz, ocağın soylu katırı!
Yer altında,
Pir aşkına
Taaa Jerminal''lerden beri çalışır,
Bir avuç arpa hatırı.
Kendi inadına güvenmez de Alagöz,
Tutar kendi dayısına güvenir.(*)
Bütün gün üç vardiya
Oysa anası bellenir!
Yeter bu ocak ağzı aydınlığı,
Alaca karanlık!
Bir menzile bin kez
Ulaşıp ulaşıp dönmek…
Yeter ışısın ortalık
Ne bir avuç arpa
Ne bir tutam ot…
Ocak Katırı Alagöz  adlı şiir kitabından 1987
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Pelit ovasında, Nanepınar''da bir ocak… Taştan değil, Tuğladan değil, Dört duvarı taşkömür, Tabanıysa çamur, çökek… Kaya kömür, taşkömür, Nan...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUK İŞİ', 'cocuk-i-si-afsar-ti-muci-n-0trtz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün sokakların tozu var ellerinde
İçin bir su birikintisi
Üstünde kağıttan bir kayık
Biz deriz ki savaşlar savaşları izliyor
Sen dersin ki kaydırak oynasaydık
Akşam iner günün son uçlarına
Sular bütün değişti
Çiçek açtı karanlık
Sen dersin ki gece de gündüzdendir
Sen dersin ki gök size
Masmavi bir umuttur
Uzar gider sonsuza
Ben gök nedir anlamam
Bildiğim
Gök olmasa uçamazdı uçurtma', 'Bütün sokakların tozu var ellerinde İçin bir su birikintisi Üstünde kağıttan bir kayık Biz deriz ki savaşlar savaşları izliyor Sen dersin ki...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUK KUŞ', 'cocuk-kus-fazil-husnu-daglarca-2y2ou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kuştu,
Allı allı bir kuş.
Her tüyüne bir çiçek bağladılar
Uçmadı o.
Bir kuştu,
Mavili mavili bir kuş.
Her tüyüne bir boncuk bağladılar
Uçmadı o.
Bir kuştu,
Yeşilli yeşilli bir kuş.
Her tüyüne bir çocuk kordelası bağladılar
Uçtu o.', 'Bir kuştu, Allı allı bir kuş. Her tüyüne bir çiçek bağladılar Uçmadı o. Bir kuştu, Mavili mavili bir kuş. Her tüyüne bir boncuk bağladılar U...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil_husnu_daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUK NAZLI BİR ÇİÇEK', 'cocuk-nazli-bi-r-ci-cek-bulent-ozcan-9lwtp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kızınca üzülecek,
Kırılıp incinecek,
Sevilince gülecek,
Çocuk nazlı bir çiçek...
Çocuklar ilgi ister,
Dosdoğru bilgi ister,
Çoçuğu sevgi besler,
Çocuk nazlı bir çiçek...
Onlarındır bal-petek,
Onlarındır gelecek,
Zamanla büyüyecek,
Çocuk nazlı bir çiçek...
Bülent ÖZCAN', 'Kızınca üzülecek, Kırılıp incinecek, Sevilince gülecek, Çocuk nazlı bir çiçek... Çocuklar ilgi ister, Dosdoğru bilgi ister, Çoçuğu sevgi bes...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUK VE VEBA', 'cocuk-ve-veba-kagan-kok-5fv1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşklarsa baglanmak için iyidir
-ne farkeder ?
Hilmi YAVUZ
Deklanşör ve tetik
Durdururlar hayatı bir anda
Ey çocuk !
Sen çocuktun büyüdün
Artık zamanda sallanma
Ne bulduysam sanki
Şu tauna yakalanmış hayatımda
Yırt her şeyi, beşiğini parçala
''İyi aşklar'' güzel aşklar bir yana.
Deklanşör ve tetik
Durdururlar hayatı bir anda.', 'aşklarsa baglanmak için iyidir -ne farkeder ? Hilmi YAVUZ Deklanşör ve tetik Durdururlar hayatı bir anda Ey çocuk ! Sen çocuktun büyüdün Art...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUK', 'cocuk-nevzat-celi-k-pqooq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ağlardı gözlerin
mavi yeşil kara
gülerdi gözlerin
mavi yeşil kara
ağla çocuk gül çocuk
ama usul usul değil
ama usul usul değil', 'ağlardı gözlerin mavi yeşil kara gülerdi gözlerin mavi yeşil kara ağla çocuk gül çocuk ama usul usul değil ama usul usul değil...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çeli̇k']::text[], 8.5, '{"poet":"Nevzat Çeli̇k","poet_slug":"nevzat_celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLAR AĞLAMASIN', 'cocuklar-aglamasin-mustak-erenus-o69f4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuklar Ağlamasın
Hiç ağlamasın
Güneşte yunmuş bir damla su.
Ama siz ağlayın payınıza düşeni
Bilerek, ederek
Ve de hiç hak geçirmeden
Şu perişan rahatlığınıza
Ne hale getirdiğiniz bu dünyaya
Namusluca, utanarak ağlayın
Ama çocuklar ağlamasın
Hiç ağlamasın', 'Çocuklar Ağlamasın Hiç ağlamasın Güneşte yunmuş bir damla su. Ama siz ağlayın payınıza düşeni Bilerek, ederek Ve de hiç hak geçirmeden Şu pe...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLAR GÖÇLER BALIKLAR', 'cocuklar-gocler-baliklar-ruhi-su-mg70v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu benim onuncu uzuncalarım; Sanatta ise kırkıncı
yılım
Şimdiye dek binlerce türkü derledim. Bunun ancak
birkaç yüzünü söyleyebildim. Bir foklor enstitüsü ya da etnomüzikoloji
çalışması değildi benim çalışmam. Bir sanat çalışması idi. Sanat ise, bir
ayıklama işidir. Bulduklarımı bu yönde değerlendirdim. Ezgisi, tartımı, özü ve
biçimi ile, halkı en iyi hangisi anlatabilmişse onu aldım.
Bunları seslendirirken, halkın söyleyişinden çok
yararlandım ama halkın ağzına öykünmekten ve özenmelerden sakındım. Şehirli
olduğumu, bir sanat kültürü aldığımı unutmadım. Hem halkın yaptığını ben
nasıl yaparım diye düşündüm; hem benim yaptığımı halk nasıl karşılar diye
düşündüm. Bir türkü, söylenildiği dilin doğrusu ve güzeli ile söylenmeli.
Dildeki yöresel değişimleri, etnik nedenlerle meydana gelen bozulmaları
sürdürmemeli. Söyleyişte ulusal birliğe ancak böyle varılır. Sanatsal açıdan
ise, mutlaka böyle olmalı.
Gerçi, nasıl söylenirse söylensin, yine de birşeyler
kalır türküden ama, yanlız birşeyler mi kalmalı? Birşeyler de getirmeli bir
söyleyiş. Birşeyler getirmiyor, ileriye doğru birşey değiştirmiyorsa, yaşıyor
sayılmaz bir sanat. Gelenekler bile yaşayanla zenginleşir. Bu söylediklerim, Türk
sanat müziği sanatçıları içinde geçerlidir, bence. Yaptığımız iş, hem halkın
özlemlerini gerçekleştirmeli, hem de halkın özlemlerini geliştirmeli.', 'Bu benim onuncu uzuncalarım; Sanatta ise kırkıncı yılım Şimdiye dek binlerce türkü derledim. Bunun ancak birkaç yüzünü söyleyebildim. Bir fo...', ARRAY['Türk Edebiyatı','Şiir','Ruhi Su']::text[], 8.5, '{"poet":"Ruhi Su","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLAR HİÇ GELMİYOR', 'cocuklar-hi-c-gelmi-yor-ozgur-ozmeral-3x10s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I
ben de ıssız bir buluşma olabilecek kadar gül kokuluyum
yaşamın keskin boşluğu ve damgalanmış yanına yansıyan
ben de koparırken içimdeki şeytanı onursuz bir diken gibi
bir kaba sıkıştırıyorum çırpınan yalnızlığı
maymunlar çağında bir göz ve aşk... yalan hep yalan
sonra ağrılı son derece ağrılı bir sancı oluyorum.
kokladığım güller avucumda bir damla kan. kan ruhun aynası
otlar yoluyorum yine de bütün çöl yüzlerinde
caddeler boyu uzanıyorum asfaltın el değmemiş yanına
ne saadet ne şefkat. billur bir duvara ağlıyorum
yıkılıyor sesim yıkılıyor yağmur... düşmüş son hecem
bir pusulanın kırılmış yönünde aranırım. yaşımı da unuttum
II
şimdi gitsek yine o saraylar dolusu gözlerin de gelse
gitsek de şehrin kalabalığını toplasak mağdur soframıza
dönsen belki mutsuzluğu üleştiririz kabuk çalan kuşlara.
sesimi de bilmiyorum sen sorgusuz çekip gittiğinden beri
yerimi de bilmiyorum bağlaçlarımı da. azgın dizelerde
boğuluyor yaşam. kitaplar yetmiyor, bakışlara siniyor çocuklar.
-çocuklar hiç gelmiyor-
şimdi sen kokuyorsun. toprak senin gibi kokuyor
dişlerinin arasına gömülüyorsun, tebessümün fidana duruyor
yolumu da bilmiyorum azgın dizelerle seviştiğimden beri
aceleci bir aşk bu ölüm gibi bir aşk. bir suçlu gibi', 'I ben de ıssız bir buluşma olabilecek kadar gül kokuluyum yaşamın keskin boşluğu ve damgalanmış yanına yansıyan ben de koparırken içimdeki ş...', ARRAY['Türk Edebiyatı','Şiir','Özgür  Özmeral']::text[], 8.5, '{"poet":"Özgür  Özmeral","poet_slug":"ozgur_ozmeral","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLAR ÖLEBİLİR YARIN', 'cocuklar-olebi-li-r-yarin-n-zim-hi-kmet-uvwa5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuklar ölebilir yarın,
hem de ne sıtmadan ne kuşpalazından
düşerek te değil kuyulara filân;
çocuklar ölebilir yarın,
çocuklar sakallı askerler gibi ölebilir yarın,
çocuklar ölebilir yarın atom bulutlarının ışığında,
ne bir santim kemik, ne bir damla kan,
çocuklar ölebilir yarın atom bulutlarının ışığında
arkalarında bir avuç kül bile değil
arkalarında gölgelerinden başka bir şey bırakmadan.', 'Çocuklar ölebilir yarın, hem de ne sıtmadan ne kuşpalazından düşerek te değil kuyulara filân; çocuklar ölebilir yarın, çocuklar sakallı aske...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLARA DÜŞEN', 'cocuklara-dusen-afsar-ti-muci-n-2jqeu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herkesin her yaşta
Dizinde ağlanacak bir annesi olmalı
Oradan bilinmedik uzaklara doludizgin
Çocuklardan da çocuk tahta atlarla
Aşılmaz dağları geçip ulaşmalı
Kapalı kapıların arkasında
Bekleşir ölü gözlü adamlar
Çocukluğu çarmıha germek için
Bunu bilen her çocuk annesinin dizinde
Tek o adamlara inat olsun diye
Bitmeyen sevinçleri uyumalı', 'Herkesin her yaşta Dizinde ağlanacak bir annesi olmalı Oradan bilinmedik uzaklara doludizgin Çocuklardan da çocuk tahta atlarla Aşılmaz dağl...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLARIMA', 'cocuklarima-aziz-nesi-n-6466e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Diyelim ıslık çalacaksın ıslık
Sen ıslık çalınca
Ne ıslık çalıyor diye şaşacak herkes
Kimse çalamamalı senin gibi güzel
Örneğin kıyıya çarpan dalgaları sayacaksın
Senden önce kimse saymamış olmalı
Senin saydığın gibi doğru ve güzel
Hem dalgaları hem saymasını severek
De ki sinek avlıyorsun sinek
En usta sinek avcısı olmalısın
Dünya sinek avcıları örgütünde yerin başta
Örgüt yoksa seninle başlamalı
Say ki hiçbir işin yok da düşünüyorsun
Düşün düşünebildiğince üç boyutlu
Amma da düşünüyor diye şaşsın dünya
Sanki senden önce düşünen hiç olmamış
Dalga mı geçiyorsun düşler mi kuruyorsun
Öyle sonsuz sınırsız düşler kur ki çocuğum
Düşlerini som somut görüp şaşsınlar
Böyle bir dalgacı daha dünyaya gelmedi desinler
Dünyada yapılmamış işler çoktur çocuğum
Derlerse ki bu işler bişeye yaramaz
De ki bütün işe yarayanlar
İşe yaramaz sanılanlardan çıkar', 'Diyelim ıslık çalacaksın ıslık Sen ıslık çalınca Ne ıslık çalıyor diye şaşacak herkes Kimse çalamamalı senin gibi güzel Örneğin kıyıya çarpa...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLARINIZ İÇİN', 'cocuklariniz-i-ci-n-rifat-ilgaz-f27bt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Savaş sonrası sayımlarda
Şu kadar ölü, şu kadar yaralı
Kadın, erkek sayısız kayıp…
Elden ayaktan düşmüş
Geride bir o kadar da sakat,
O kara günleri anımsayalım diye…
Zorumuz ne insan kardeşlerim,
Amacınız kökümüzü kurutmaksa,
Yetmiyor mu tayfunlar, taşkınlar,
Bunca aç, bunca sayrı, kırım, kıyım,
Sayısız işkence kurbanları…
En kötüsü,
Güngünden başımıza inen bu gökyüzü!
Bu toplanıp dağılmalar ne oluyor
Yüksek düzeylerde?
Neden alçakgönüllü değilsiniz,
Sözünüz mü geçmiyor birbirinize,
Hangi dilden konuşuyorsunuz?
Barışsa eğer istediğiniz
Uçaklardan başlayın işe
Önce çirkinleşen savaş uçaklarından…
Ya insanları bir yana bırakıp
Sivrisineklerin kökünü kurutun
Ya da bataklıkları!
Sonra geçin karasineklere!
Ne kadar da çoğaldılar son sıcaklarda
Yer gök tüm karasinek,
Yaşamımızı karartmak için.
Bir güç denemesi yapsanız da,
Onların yaşamını siz karartsanız!
Yoksa siz de mi barıştan yanasınız,
Onların özgürlüğünden yana?
Kolay değil, barıştan yana olmak
Özveri gerek yüksek düzeylerde.
Gene de bir nedeni olmalı, diyorum.
Bu toplanıp toplanıp dağılmaların.
Phantom''ların pazarlanması değilse
Denizaltıların sığınmasıdır
Dost limanlara
Ya sağcı gerillaların barındırılması…
Ah uzak görüşlü yetkililer,
Bıraksanız da büyük sorunları bir yana,
Biraz da ulusunuz için,
Halkınız için konuşsanız…
Çocuklarınız için…
Kökleri kuruyup gitmeden!
Ocak Katırı Alagöz  adlı şiir kitabından 1987
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Savaş sonrası sayımlarda Şu kadar ölü, şu kadar yaralı Kadın, erkek sayısız kayıp… Elden ayaktan düşmüş Geride bir o kadar da sakat, O kara ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLUK AŞKI', 'cocukluk-aski-ceyhun-atuf-kansu-dhu0z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşün, düşün ki anne ben daha çok küçüğüm,
Ilık ellerimden tut, beraber götür beni,
Oyuncakçıda büyük mavi bir gemi gördüm,
İşlenmiş, dalgaların köpüğüyle yelkeni.
Şu renk renk toplara bak, anne, ne güzel renk renk
Dönüyor içimde bir bayram yeri dönüyor,
Yuvarlanıyor gönlüm şu uçan toplara denk,
Bir yokuştan koşarak kalbim sana iniyor.
Kan değil, zafer akar benim savaşlarımda,
Hürriyet için ölür genç kurşun askerlerim,
İnsanlığın cenneti saklı göz yaşlarımda,
Yeni bir bahar çağı getirecek zaferim!
Korkma, korkma kaçmam ben, tahta atımla dağa,
Senden daha güzel bir dağ var mı rüyalarda?
Niçin uğraşsın küçük kuş yurdundan kaçmağa,
Yaşarken annesinin yeşerttiği kırlarda?
Kırılır, bütün iyi oyuncaklar kırılır,
Çocuk kalblerinden mi yaparlar hep onları,
Niçin oyun biterken en sonra hatırlanır,
Hâtıralarımızın en tatlı oyunları?
Satılır mı zengin bir oyuncakçıda söyle,
Anne, dün okuduğun masaldaki güzel kız?
Yeter, altın bir kalbim olsun, Tanrıdan dile,
Bütün zenginliğimi verir onu alırız.', 'Düşün, düşün ki anne ben daha çok küçüğüm, Ilık ellerimden tut, beraber götür beni, Oyuncakçıda büyük mavi bir gemi gördüm, İşlenmiş, dalgal...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun_atuf_kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLUK MEVSİMİ', 'cocukluk-mevsi-mi-bulent-ozcan-bmf03', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukluk mevsimi ne çabuk geçti,
Hayaller güzeldi, düşler güzeldi...
Annelerin yüzü daha güleçti,
Baharlar güzeldi, kışlar güzeldi...
Bulutlar üstüne ne düşler kurdum,
Sapanla devleri gözünden vurdum,
Gece Kaf Dağı''na çıkıp oturdum,
Zümrüt Anka denen kuşlar güzeldi...
Bir çağı yürürdüm iki adımla,
Kişnerdi dal atım bağladığımda,
Kaybolan bilyeme ağladığımda,
Gözümden süzülen yaşlar güzeldi...', 'Çocukluk mevsimi ne çabuk geçti, Hayaller güzeldi, düşler güzeldi... Annelerin yüzü daha güleçti, Baharlar güzeldi, kışlar güzeldi... Bulutl...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLUK', 'cocukluk-cahit-sitki-taranci-8exd8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Affan Dede''ye para saydım,
Sattı bana çocukluğumu.
Artık ne yaşım var, ne adım;
Bilmiyorum kim olduğumu.
Hiçbir şey sorulmasın benden;
Haberim yok olan bitenden.
Bu bahar havası, bu bahçe;
Havuzda su şırıl şırıldır.
Uçurtmam bulutlardan yüce,
Zıpzıplarım pırıl pırıldır.
Ne güzel dönüyor çemberim;
Hiç bitmese horoz şekerim!', 'Affan Dede''ye para saydım, Sattı bana çocukluğumu. Artık ne yaşım var, ne adım; Bilmiyorum kim olduğumu. Hiçbir şey sorulmasın benden; Haber...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLUĞUM', 'cocuklugum-ziya-osman-saba-ia2xp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocukluğum, çocukluğum...
Uzakta kalan bahçeler.
O sabahlar, o geceler,
Gelmez günler çocukluğum.
Çocukluğum, çocukluğum...
Gözümde tüten memleket.
Artık bana sonsuz hasret,
Sonsuz keder çocukluğum.
Çocukluğum, çocukluğum...
Habersiz ölen kardeşim,
Mezarı bilinmez eşim,
Her bir şeyim çocukluğum.
Çocukluğum, çocukluğum...
Bir çekmecede unutulmuş,
Senelerle rengi solmuş,
Bir tek resim çocukluğum...', 'Çocukluğum, çocukluğum... Uzakta kalan bahçeler. O sabahlar, o geceler, Gelmez günler çocukluğum. Çocukluğum, çocukluğum... Gözümde tüten me...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya_osman_saba","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLUĞUMU GÖMDÜM', 'cocuklugumu-gomdum-yusuf-altunel-w1990', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir bardak hayat içişi
peşine düştüğümüz uzaklıklar
dondurma için sakladığımız bozuk para
şeytanın satamadığı harcanmışlıklar
kargacık şiir defterinin dibine düşülmüş not
kuru menekşe yaprağı
ve evcilik oynama hazları
bir köşe başında beklediğimiz çapkınlıklar
karanfil çocuklar dizilir dar sokakların kuytularında
adım attıkça düşürdüğümüz unutuluşlar
ayaklarımızda toz kalmış birahanenin birinden
bir yudum alıp bıraktığımız ayaklanışlar
teğellenmiş kaneviçeler örülü çocukluğumuz
güveler sofrasının tatsız yemişi
başımızı eğip öpemeden geçtiğimiz o kızlar
oyalar dünyasının fiili uzak geçmişi
kömür tozunda kaldı minik arkadaşlarımız
ne büyük bir dünyaydı paylaştığımız oysa ne kocaman
oynadığımız elim sende saklambaç ve birdirbirler
sokak aralarında kış akşamı üşümüşlüğünde evlere dağıldı
kedileri kovalamıştık mahalle aralarında
sonra çocukluğumuzu kesti soğuk demirden tren yolu
belediye otobüsleri taşıdı uykulu mahmurluğumuzu
kelepçeledi ayaklanışları okul müdürü sıralara sığmayan
öğretmen tutup kulaklarından haylazlığımızın
öldürdü sonra bahçeye gömdü sınırsızlığımızı
köpekler eşeledi mezarı ama ne kemik ne de et
ölesiye tekmelediğimiz
uyduruk toplar kaldı geriye bir tek
çocukluğumu o harap bostana
ezilmiş köpeğimin yanına gömdüm.
cinayeti kaçırdılar okuldan kapatıp bilincimi
gözlerimi açtığımda iş işten treni geçmişti', 'bir bardak hayat içişi peşine düştüğümüz uzaklıklar dondurma için sakladığımız bozuk para şeytanın satamadığı harcanmışlıklar kargacık şiir ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLUĞUMUZ', 'cocuklugumuz-sezai-karakoc-g06cm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Annemin bana öğrettiği ilk kelime
Allah, şahdamarımdan yakın bana benim içimde
Annem bana gülü şöyle öğretti
Gül, Onun, o sonsuz iyilik güneşinin teriydi
Annem gizli gizli ağlardı dilinde Yunus
Ağaçlar ağlardı, gök koyulaşırdı, güneş ve ay mahpus
Babamın uzun kış geceleri hazırladığı cenklerde
Binmiş gelirdi Ali bir kırata
Ali ve at, gelip kurtarırdı bizi darağacından
Asyada, Afrikada, geçmişte gelecekte
Biz o atın tozuna kapanır ağlardık
Güneş kaçardı, ay düşerdi, yıldızlar büyürdü
Çocuklarla oynarken paylaşamazdık Ali rolünü
Ali güneşin doğduğu yerden battığı yere kadar kahraman
Ali olmaktan bir sedef her çocukta
Babam lambanın ışığında okurdu
Kaleler kuşatırdık, bir mümin ölse ağlardık
Fetihlerde bayram yapardık
İslam bir sevinçti kaplardı içimizi
Peygamberin günümüzde küçük sahabileri biz çocuklardık
Bediri, Hayberi, Mekkeyi özlerdik, sabaha kadar uyumazdık
Mekkenin derin kuyulardan iniltisi gelirdi
Kediler mangalın altında uyurdu
Biz küllenmiş ekmekler yerdik razı
İnanmış adamların övüncüyle
Sabırla beklerdik geceleri
Şimdi hiçbirinden eser yok
Gitti o geceler o cenk kitapları
Dağıldı kalelerin önündeki askerler
Çocukluk güzün dökülen yapraklar gibi', 'Annemin bana öğrettiği ilk kelime Allah, şahdamarımdan yakın bana benim içimde Annem bana gülü şöyle öğretti Gül, Onun, o sonsuz iyilik güne...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUĞUN VE KAPTANIN TÜRKÜSÜ', 'cocugun-ve-kaptanin-turkusu-afsar-ti-muci-n-64126', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaptan amca beni geçerken
Karşı kıyılara bırakır mısın
Oralarda ne mi var her şey
Çocuklar sesler ışıklar var
Bayramlar ve her türlü uzaklar
Kaptan amca ben bırakır mısın
Gittiğin kıyıların ötesine
Oralarda ne mi var her şey
Oralarda çalgı var sevinç var
Kaptan amca beni götürmez misin
Gittiğin güzel yerlere şimdi
Uzakların tutkusu nicedir
Çöller gibi yakıyor içimi', 'Kaptan amca beni geçerken Karşı kıyılara bırakır mısın Oralarda ne mi var her şey Çocuklar sesler ışıklar var Bayramlar ve her türlü uzaklar...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ODALAR VE SOFALAR', 'odalar-ve-sofalar-sabri-esat-si-yavusgi-l-dcor8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evler, bir nara benzer,
Nar tanesi, sofalar,
Akşam, yol gibi gezer;
Sükûn, su gibi odalar.
Odada bir pancurun
Sofadadır güneşi;
Camlarda yanan korun
Düşer içime eşi.
Odada yığın yığın
Gölgenin salkımları;
Sofada yalnızlığın
Duyulur adımları.
Oda, içinden duyar
Oluktan düşenleri;
Sofa, geceyi oyar,
Dinler merdivenleri.
Toplar odam kuş gibi
Sofamın lâflarını.
Birer bibloymuş gibi
Süsler boş raflarını.
Beni duvar boyunca
Bir kum gibi ufalar
Odam uyku dolunca
Uyumayan sofalar.', 'Evler, bir nara benzer, Nar tanesi, sofalar, Akşam, yol gibi gezer; Sükûn, su gibi odalar. Odada bir pancurun Sofadadır güneşi; Camlarda yan...', ARRAY['Türk Edebiyatı','Şiir','Sabri Esat Si̇yavuşgi̇l']::text[], 8.5, '{"poet":"Sabri Esat Si̇yavuşgi̇l","poet_slug":"sabri_esat_siyavusgil","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ODAM VE AZYALNIZLIK ÜLKESİ HAKKINDA UZUN ŞİİR', 'odam-ve-azyalnizlik-ulkesi-hakkinda-uzun-si-i-r-serkan-isin-tj944', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ODA İÇİN EPİLOG
gri ve macunlu pervazından üzüntüyle yüzüne bakıyor
bekçinin koca elleri küçük tabutu bir kenara koyarken
elleri siyillerle kaplanmış Zaman üzerine siniyor eşyalar arasında
bu yazılar, bu eldeğmemiş gülümseme, sırları ile saklı odam’da
odam ki azyalnız ülkemin sarnıcından çekiyor divanı ve yorganları
fildişi tarakları, soya/ahşap kapıları…
birden giriyor odaya gün, birden köşede
gölgeler uzuyor elbet, makas paslanıyor aynı yerde
kültablasını azgınca emiyor küller ve mânâsı kaybolan
birçok şey gibi ben de siniyorum yatağın üzerine.
Kirişi çatlak, sıvası benden ve tavanı fresk odam
EVET EVET BİR ŞİİRİ KURMANIN ERSİKLİĞİ İLE
Siz hiç, küçük hanımları pencerelerin, siz hiç şiir kurdunuz mu
Dün dağlarda dolaşıp, kapıya CUMA’ya gidiyorum kağıdı astınız mı
Dumanı genzinizle beraber yuttunuz mu
Ceset öptünüz mü siz küçük hanımları pencerelerin.
“evet evet bir şiiri kurmanın esrikliğiyle
tüm bunları yaptık”
ben sanıyordum ki, siz dizleriniz üzerinde her gece
bir sevişme yaşardınız, başlayan ve biten her şey gibi biraz aç biraz tok
ölür giderdiniz küllerine bulanmış Nil gibi ölülerin
çocuk kokardınız sokaklarında Babil’in Kelâmsız
bilmediğim Paris’te herhangi bir kafeste intihar kokardınız, hassiktirin
bu imgeler biraz nası’desem: bir az
düşündüklerinizden ve yaşadıklarınızdan
soyaçekim bu bayanlar, içinize girdiğimde hep aynı terane
:bir fazla
ve kapanan bir şiirin en hüzünlü yanına dokunacağız şimdi
böbrekleri parçalanmış bir ada vapurundan tarçın kokarak
hayal-I süküta uğrattığımız tüm moda martıları adına
üç kere fatiha diyeceğiz
bir şiiri kurmanın rahatlığıyla
ve nasılsa ‘herşey eskisi gibi olacak’
değil mi küçük bayanlar…
bir şiiri kurmanın ve çatmanın ve dermenin ve delmenin
sıfatıyla.
İLK KEZ AŞIK OLMANIN DAYANILMAZ APTALLIĞI ÜZERİNE
Çobandı babam benim, ve verevine işlenmiştir tüm hayatı
‘ıslak gömlekle yatmak’ şiirinde, ince ve paslı bi telle, kalın kalemle.
Sondan başlayarak şimdi siz tekrar anlatacak değilim elbet
Ama ilk kez aşık olmanın dayanılmaz aptallığı üzerine
Derince ve kuyudibi söyleşeceğiz biraz.
Öncelikle efendim, varolun şu sahlep gibi sıcak yüzlerinizle
Sıcak göğüslü eşleriniz ve pamuk suret’li bebelerinizle
Etrafımda oturduğunuzda kelli, anlıyorum ve biliyorum
Dişlerinizi parlatan dantelli şehvettir: dantelalı şehvet
Tanımadığımız ise yalandır elbet, freudyen mantığına göre
Efendim şu muhim mesele, oidipus kompleksi meseli.
(Her nasılsa  yahudi uleması’ndan çıkar bu çatlak sesler,
En çabuk uydurmuşlardır akıllarını Analitqua denilen canavara.)
Tarçın kokarak şu anda, işbu dudaklarıma bakın beyler.
Siz de aşkı oyun sanan dalavereciler, siz de sandık cinleri, siz de kapı tokmakları vs.
Nasıl her ayet sizin içinse, nasıl her selâ bir ölüm bekçisiyse
Aşk da farzdır üzerimize.
Ve elbet bu freudyen mantığı hulesasına göre mümkün değildir,
Annemizin salyalı dudaklarından, memelerinden ve babamızın uzun penisinden, kıllarından
Kurtarmak kendimizi. bilin ki bundan mürekkep bu Aşk denilen kimya-I sâadet.
beyimiz Gazali’ye kaydı gözleriniz, kaysın. Bakın dörtlerinizle ve tüm ışıklı
Reklam panolarınızla, cübbesine yüzünü süreceğimiz bi’o kaldı ortada. Ortada. Ortada.
Aşk üzerine asla Yayınlanmayacak bir şiir için buradasınız ağalar, babalar, kardeşler ve azalar.
Farkında mısınız acaba?
JEL
yapışıktır suratı kelimenin
az bulunur bi’kauçuk, az bunulur bi’salya
ve bulaştı mı
korkunç bir helezonla önce kağıda
sonra da böcek tutmuş tutkularına
yapışır.
Bu yüzden her şair
Biraz balicidir, LSD bulunmayan toplumsokaklarında.', 'ODA İÇİN EPİLOG gri ve macunlu pervazından üzüntüyle yüzüne bakıyor bekçinin koca elleri küçük tabutu bir kenara koyarken elleri siyillerle ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Işin']::text[], 8.5, '{"poet":"Serkan Işin","poet_slug":"serkan_isin","theme":"Türk Şiiri","is_hero":false,"total_lines":73}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ODASINDA BİR EVİN', 'odasinda-bi-r-evi-n-metin-altiok-zmg0h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kentin ortasında,
Odasında bir evin
Serilir ayaklarının ucuna
Bozkır ıssız ve derin.
Ne zaman yanına konsa
Ayrılık bir özlemin.
Adından bir güvercin
Sesim, sesim, sesim
Takılıp kara bir çalıya,
Çırpınır kurtulmak için.
Bir kentin ortasında,
Odasında bir evin.', 'Bir kentin ortasında, Odasında bir evin Serilir ayaklarının ucuna Bozkır ıssız ve derin. Ne zaman yanına konsa Ayrılık bir özlemin. Adından ...', ARRAY['Türk Edebiyatı','Şiir','Metin Altiok']::text[], 8.5, '{"poet":"Metin Altiok","poet_slug":"metin_altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ODE', 'ode-mihail-eminescu-7hv1v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gelip ölümü öğreneceğimden kuşkuluydum!
Ölümsüzcesine genç, paltoma sarılmış
Düşçü gözlerimi yalnızlığın yıldızına
Kaldırırdım.
Birdenbire sen çıktın yolumun üzerine
Acı, sen, o baldan da tatlı acı...
İçtim dizginsiz ölümün şerbetini son damlasına
Kadar.
Diri diri yanıyorum, kıvranarak Nessus gibi.
Zehir içmiş yiğit giysili Herkül gibi ya da.
Söndüremem ateşimi artık bütün denizlerin
Sularıyla.
Kendi düşümle, gözyaşlarımla tükeniyorum.
Kendi yaktığım ateşle, yalımlarla eriyorum.
Dirilir miyim, bir gün parıltılar içinde tıpkı
Bir Anka gibi?
Yok olup gitsin artık o baş döndüren gözler!
Geri dön yüreğime sen ey kederli kayıtsızlık!
Sakin sakin ölebileyim diye, ver bana, bana
Kendimi ver.
Mihail EMINESCU', 'Bir gün gelip ölümü öğreneceğimden kuşkuluydum! Ölümsüzcesine genç, paltoma sarılmış Düşçü gözlerimi yalnızlığın yıldızına Kaldırırdım. Bird...', ARRAY['Türk Edebiyatı','Şiir','Mihail Eminescu']::text[], 8.5, '{"poet":"Mihail Eminescu","poet_slug":"mihail_eminescu","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ODUN', 'odun-metin-eloglu-zwdsc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul''un ortasında bir bahçe
Silme güvercin tavanı
Yeşeren ekinlerin muştusunca
Eylül bitiminin aydınlık günü
Sıcacıktın aşklıydın bence
Sensizlikte bir yoksuldum yavandın
Şuramda saklı o sıcacık ekmeği
Senin doyumluk aşına bandım
Bakmakla doyulmaz çeşniden
Özlemlerle ışımış bir yüzün vardı
Gayrı çil çil düzen yokluğunda kül kesilir
Bunca ömrüm varlığınla uzardı
Salt sana vergi umudu aşılamak
Dipdiri aklın fikrin yüreğince uluydu
İçin dışın boz ela gümrah gözlerin
Güzeli yeniydi İstanbul''luydu
Hayatı bölüşürken güleçtik dobradobraydık
Sana ekli yaşamak elbet içime sindi
Hani yüzümüzü ağartacak günlere teşne
Yoksun çağlar dost çağanlar içiydi
Sen vardın son yaz vardı bitişiğimde
Bambaşka gördüm ülkeyi halkı acunu
Gerçekliğin bacasında kopkoyu tüttün
Gürül gürül yanası ocağımın odunu
Kıvancım sensin ergem sensin bilgim sen
Kuşandıkça beni ben eden kılık
Barışta hürlükle sevdayla gelen
O cayılması ayıp mutluluk.', 'İstanbul''un ortasında bir bahçe Silme güvercin tavanı Yeşeren ekinlerin muştusunca Eylül bitiminin aydınlık günü Sıcacıktın aşklıydın bence ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin_eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOK GÜZEL ŞEY', 'cok-guzel-sey-melih-cevdet-anday-hgvq7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak güzel şey doğrusu
Üstelik hava da güzelse
Hele gücün kuvvetin yerindeyse
Elin ekmek tutmuşsa bir de
Hele tertemizse gönlün
Hele kar gibiyse alnın
Yani kendinden korkmuyorsan
Kimseden korkmuyorsan dğnyada
Dostuna güveniyorsan
İyi günler bekliyorsan hele
İyi günlere inanıyorsan
Üstelik hava da güzelse
Yaşamak güzel şey
Çok güzel şey doğrusu.', 'Yaşamak güzel şey doğrusu Üstelik hava da güzelse Hele gücün kuvvetin yerindeyse Elin ekmek tutmuşsa bir de Hele tertemizse gönlün Hele kar ...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOK GÜZEL', 'cok-guzel-nilgun-marmara-dv05z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Durma artık burada uysal âşık!
Aydınlık milinin yatağında.
Bilemiyoruz belki de meşe o ağacın adı,
Anlayamıyoruz varolduğumuzu gölgesinde
ağırbaşlılığının.
Veda geliyor şimdi, öğretmek için
sergilenmeyi, uçuşan geriye dönen
vakitte.
Kime, kime gönderiyor incelen yapraklarını
yüzün, kavisin beyaz yanağıyla?
Bu aklıkta, minarem mavi benim.
Işığım denize kayıyor, bir sayıklama
izleğiyle, bir zamanlar pay verdiğimiz
insanlığa!', 'Durma artık burada uysal âşık! Aydınlık milinin yatağında. Bilemiyoruz belki de meşe o ağacın adı, Anlayamıyoruz varolduğumuzu gölgesinde ağ...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Marmara']::text[], 8.5, '{"poet":"Nilgün Marmara","poet_slug":"nilgun_marmara","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOK YAŞASIN SAYILAR''DAN', 'cok-yasasin-sayilar-dan-i-lhan-berk-x9857', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '3''dür sayıların en güzeli.
Biçimler biçimi.
Hiçbirine de benzemez.
Bir
daire
çiziyor
gibidir
ama
(alttan alta yatık iki açı da diyebiliriz)
iki çengel de
(gene
alttan
alta.)
Asıl da iki yarım dairedir: Dikey.
(Dikeyin
güzelliğini
düşünün!)
3''ün güzelliği salt biçimden de gelmez: esrik doğmuştur.
Uzaktan da olsa etikçi (etik şeylerin sorunu değildir) olduğunu da söyleyebiliriz.
Hazcı bir etikçi. Kaynağını aramaya çıkmış gibidir sevincin.
Hiç mi hiç asmamıştır yüzünü.
Hem sayılar içinde yalnız 3''ün canından söz edilebilir belki de.
''SAYILARIN CANI YOKTUR''
sonra da, güzel huyludur 3. Bu da yetmelidir bize.
Ama sayıların gizli tarihçisi sevgi Borges''e yetmez bu.
3''e 1''i de katarak 3 için özel bir varlık kütüğü de biçecektir.
Varlık tutkunu Eskimolar da 3''ü belki de bu yüzden severler.
Eskimo dilinde üçten çoğu yoktur, yalnızca koca bir
ÇOK
vardır.
Her şey üç ile ve çok''la biter.
Dünya da 3 ile anlatılır.
3 gelecektir hem.
Büyük uzaklık!
(Hem 3''le öğrenmedik mi biz uzaklığı?)
çok yaşasın sayılar', '3''dür sayıların en güzeli. Biçimler biçimi. Hiçbirine de benzemez. Bir daire çiziyor gibidir ama (alttan alta yatık iki açı da diyebiliriz) ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOKLUKTA BİRLİK', 'coklukta-bi-rli-k-charles-baudelaire-l0nkg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tapınaktır doğa, sütunları canlı;
Anlaşılmaz sözler duyulur zaman zaman.
Sembol ormanları içinden geçer insan;
Tanıdık bakışlar süzer gibidir sizi.
Bir derin, bir karanlık birlik içinde,
Aydınlık kadar sonsuz, gece kadar geniş,
Uzaktan söyleşen uzun yankılar gibi,
Renkler, sesler, kokular karışır birbirine.
Kokular vardır çocuk tenlerinden taze;
Obua sesinden tatlı, çayır gibi yeşil;
Kokular da vardır azgın, zengin, gürül gürül.
İnsana sonsuz şeylerin tadını veren,
Misk, amber, aselbent, buhur gibi kokular,
Duyuları, düşünceyi alıp götüren.
Charles  BAUDELAIRE', 'Bir tapınaktır doğa, sütunları canlı; Anlaşılmaz sözler duyulur zaman zaman. Sembol ormanları içinden geçer insan; Tanıdık bakışlar süzer gi...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOKSESLİLİK ÜZERİNE', 'coksesli-li-k-uzeri-ne-ruhi-su-ecxms', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Batı müziği, bizim halkımızın çoğunluğunca daima
bir yabancıdır, anlaşılması güç bir dildir. Kültürümüzün kökleriyle başka
dünyalarda oluşumuz bunun nedenlerinin başında gelir. Bizim geleneğimizde
çokseslilik yoktur. Biz bu aşamaya batı kültürüne yöneldiğimiz bir anda geldik.
Batı kültürüne yönelişimizin tarihi de iki yüzyılı bulur. Yanlız müzik değil,
bir uygarlık yaratılabilirdi bu süre içinde. Demek ki giysilerin ya da faydası
kolayca anlaşılan diğer araçların değiştirilmesi gibi kolay olmuyor, müzikte
değişiklik. Onun gelişebilmesi daha köklü dönüşümlerle ilgili. Bir toplumun
müziği, konuştuğu dil kadar hayatına bağlıdır. Ve bundan dolayı da konuştuğu
dil kadar kendisine anlamlı ve sıcak gelir. Bunda ayıplanacak bir şey yok: İnsan,
tamamıyla yabancılaşmadıkça ne dilinden, ne de müziğinden kopabilir. Toplum ileri
bir toplumsa, müziği de ilerlemiş olur. XIII.- XIV. yüzyıl batı müziği, bizim
bugünkü alaturkadan daha yeterli bir müzik değildi. Bugünkü batı müziği ise bilim
ve teknikte Rönesans''la uzay çağı arasındaki gelişmeyle orantılıdır. Bilimin ve
tekniğin yanlız ürünlerini alıp da dünyada uygar olabilmiş bir toplum yok. Marifet,
bu ilerici bilimin ve tekniğin içinde olabilmekte...
Armoni, bugünkü batı müziğine gücünü
kazandırmış olan çokseslilik kurallarının bilimidir. Armonize etmek, mevcut bir
melodi çizgisini çoksesli bir hale getirip, zenginleştirmek demektir. Çokseslilik
nedir bilmeyen bizim gibi bir toplumda bunun, halkı da, sanatçıyı da yetiştirici iki
yönlü bir faydası vardır. Çoksesliliğe kendi türkülerinin eşliğinde girmesi hem
halka daha ilginç gelir, hem de sanatçıya bu kurallar içinde kendi diliyle
düşünmeyi öğretir. Gerçi sadece türkülerin armonize edilmesi batı müziği, ya da
bir müziğin geleceği demek değildir ama, bu anlamdaki bir müziğe hem yolunu açan,
hem kişiliğini kazandıran bir çabadır. Zira bir sanat, kural ve teknik bir yabancı
ya da yabancı bir unsur olmaktan çıktığı zaman, kişiliğini bulur. Yanlız
kişiliğini değil, kişiliğinin kurallarını da bulur. Edebiyatımızdaki gelişmeyi
düşünelim: Destandan, masaldan, halk hikayelerinden ve halk şiirinden bugün ki batı
romanına, batı hikayesine ve batı şiirine geçerken batıdan neler aldığımızın
bir okuyucu olarak farında mıyız? Batı tekniği ile işlenmiş müziğimizi dinlerken
de kendi dilimizi ve kendi yaşantılarımızı bula bula çoksesliliğin tadını
anlamaya alışacağız ve böylece batı müziği içindeki yerimizi alacağız.', 'Batı müziği, bizim halkımızın çoğunluğunca daima bir yabancıdır, anlaşılması güç bir dildir. Kültürümüzün kökleriyle başka dünyalarda oluşum...', ARRAY['Türk Edebiyatı','Şiir','Ruhi Su']::text[], 8.5, '{"poet":"Ruhi Su","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OKUL', 'okul-aziz-nesi-n-ja460', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mapus damı bana çok şey öğretti
Ama en çok sabretmeyi
Yalnızken kalabalık olmayı
Kalabalıktayken de kendimle kalmayı
Ve sürekli kavga edip
Durmadan kendimle barışmayı
Hiç gocunup yüksünmeden
İhanetlere katlanmayı
Beş metrede beşbin metreyi yürümeyi
Ve duvarların darlığında
Dünyaları dolaşmayı
Ve hepsinden de çok
Bütün yuvarlakları yüreğimde bileyip sivriltmeyi
İnsan olmayı insan olmayı', 'Mapus damı bana çok şey öğretti Ama en çok sabretmeyi Yalnızken kalabalık olmayı Kalabalıktayken de kendimle kalmayı Ve sürekli kavga edip D...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OKULLAR DİNLENCEDE', 'okullar-di-nlencede-rifat-ilgaz-o94b4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağıldaydınız sanki çocuklar,
Yaz geldi mi açılacak kapılar,
Dağlara, bayırlara, kıyılara
Köylere, pınarbaşlarına,
Bir avuç darı gibi dağılacaksınız!
Ama nerelerdesiniz kuzucuklarım,
Hangi yangın yerinde?
Ne oldu o tatlı dilli,
Güler yüzlü öğretmenler,
Onlar da mı dinlencede
Oh, oh, ne güzel!
Ama bu işportacı da kim?
Bu simit tablası da ne?
Nerden çıktı bu boya sandığı?
"Hani ya demli çaydan içen!"
"Taze simit, gevrek simit!.."
"Bayanlar, buyrun!
Sutyenler, don lastikleri,
Çengelli iğneler, yorgan iğneleri!"
"On halka yüz lira,
Şansınızı deneyin!"
"Taze ayran, soğuk gazoz!
Buyrun baylar,
Salonumuz da var yukarıda!
Buyrun öğretmenim!"
Ocak Katırı Alagöz  adlı şiir kitabından 1987
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Ağıldaydınız sanki çocuklar, Yaz geldi mi açılacak kapılar, Dağlara, bayırlara, kıyılara Köylere, pınarbaşlarına, Bir avuç darı gibi dağılac...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OKUMAK GEREK', 'okumak-gerek-bulent-ozcan-4esfr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha çok şey bilmek için,
İleriyi görmek için,
Gerçekleri görmek için
Daha çok okumak gerek.
Daha güçlü devlet için,
Huzur için, servet için,
Daha mutlu millet için
Daha çok okumak gerek.
Tembellikten vazgeçelim,
Okumayı yol seçelim,
Okumak, bilmektir derim,
Daha çok okumak gerek...
Bülent ÖZCAN', 'Daha çok şey bilmek için, İleriyi görmek için, Gerçekleri görmek için Daha çok okumak gerek. Daha güçlü devlet için, Huzur için, servet için...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OKUTMA ÜZERİNE', 'okutma-uzeri-ne-rifat-ilgaz-i4hm0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SINIF''ın ozanıyım mimli,
HABABAM SINIFI''nın yazarıyım ünlü.
Kim ne derse desin,
Çocuklar için yazdım hep.
Canım yansın diye
İşimden atarlar sık sık,
Acısını hep çocuklar çeker…
Kendi öz çocuklarım,
Benden önce.
Şunu demek istiyorum!
İki iş tuttum ömür boyu köklü.
Çocukları okutmaktı ilk işim,
İkincisi,
Yazdığımı çocuklara okutmak.
Ne gençlerden, ne çocuklardan
Bir yakınmam yok
Arap''ın dediği doğru:
"Çocuk mazbut…"
Memleketse görülüyor işte,
Güllük gülistanlık…
Ne var ki güllerin dikeni çok!
Ocak Katırı Alagöz  adlı şiir kitabından 1987
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'SINIF''ın ozanıyım mimli, HABABAM SINIFI''nın yazarıyım ünlü. Kim ne derse desin, Çocuklar için yazdım hep. Canım yansın diye İşimden atarlar ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OKUYUCUNUN BANA ŞİİRİ', 'okuyucunun-bana-si-i-ri-henrik-nordbrandt-f2yin', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyuyorum, bir geçen var evin önünden;
biraz durup, yoluna devam ediyor.
Paylaşıyor yüzünü ayak sesleri
benim uğraşım olan gizemle.
Aşk şiiridir bütün şiirler,
ama kaç kişi durup okur onları!
Ben önünden geçtiğimde bu şiirin,
Sen unu yazmıştın bile.
Henrik NORDBRANDT', 'Duyuyorum, bir geçen var evin önünden; biraz durup, yoluna devam ediyor. Paylaşıyor yüzünü ayak sesleri benim uğraşım olan gizemle. Aşk şiir...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OKYANUSLARA SÜRÜKLE', 'okyanuslara-surukle-yusuf-altunel-g5kzf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'pervaneler sevda taşıyor (t)uzaktaki yıldızlara
doğumlar tanyerinde yanmalara gebe
tutku cehenneminde pusuya düşmüş yaşamak
perdeler sarhoş rengi
üzüm kokuyor bütün camlar çıplak
süzülüyor pencerelerden çiğit mavisi
söğüt damarlarında toplanıyor damıtılmış yaşam
saat sabahın beşi, çiğ damlası olmuşum
ıslatmışım tüm sevişmeleri geceden kalan
işliyorum güneşi zeytin yaprağından tulumum
baharın yükünü taşıyorum kışlardan hırsızladığım
kavuşmalar beklemişim terkedilmelerde bıraktığım
hayat akıp gidiyor kum gibi avuçlarımdan
ellerim öyle küçük yaşamaksa kocaman
ıslıklar sunmuşum tren yollarında
çağırmışım seni gömmek için beynime mahremini
sen akıp gitmişsin
iğde kokulu resimden sulara
özlemindir hareket ettiren çarkları
doğayı çıldırasıya savuran
yemişlere kutsal can
bir duru özlem olmuşum canım
dirilmeler biriktirmişim, kekikler dağların eteklerinden
çekingenim, göllenmişim, kuytulukta durmuşum
gel çek beni, okyanuslarına sürükle', 'pervaneler sevda taşıyor (t)uzaktaki yıldızlara doğumlar tanyerinde yanmalara gebe tutku cehenneminde pusuya düşmüş yaşamak perdeler sarhoş ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞOL CENNETİN IRMAKLARI', 'sol-cenneti-n-irmaklari-yunus-emre-knp46', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şol cennetin ırmakları
Akar Allah deyü deyü
Çıkmış İslam bülbülleri
Öter Allah deyü deyü
Salınır tuba dalları
Kur''an okur hem dilleri
Cennet bağının gülleri
Kokar Allah deyü deyü
Kimi yiyip kimi içer
Hep melekler rahmet saçar
İdris nebi hülle biçer
Diker Allah deyü deyü
Altındandır direkleri
Gümüştendir yaprakları
Uzandıkça budakları
Biter Allah deyü deyü
Aydan arıdır yüzleri
Misk ü amberdir sözleri
Cennette huri kızları
Gezer Allah deyü deyü
Hakk''a âşık olan kişi
Akar gözlerinin yaşı
Pür nur olur içi dışı
Söyler Allah deyü deyü
Ne dilersen Hak''tan dile
Kılavuzla gir bu yola
Bülbül âşık olmuş güle
Öter Allah deyü deyü
Açıldı gökler kapısı
Rahmetle doludu hepisi
Sekiz cennetin kapısı
Açar Allah deyü deyü
Rıdvandürür kapı açan
İdrisdürür hülle biçen
Kevser şarabını içen
Kanar Allah deyü deyü
Miskin Yunus var dostuna
Koma bugünü yarına
Yarın Hakk''ın divanına
Varam Allah deyü deyü', 'Şol cennetin ırmakları Akar Allah deyü deyü Çıkmış İslam bülbülleri Öter Allah deyü deyü Salınır tuba dalları Kur''an okur hem dilleri Cennet...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞOL DERGÂHTAN DÖNSÜN YÜZÜM', 'sol-derg-htan-donsun-yuzum-karacaoglan-4gwhs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şol dergâhtan dönsün yüzüm
Ölünce sevmezsem seni
Kan ağlasın iki gözüm
Ölünce sevmezsem seni
Muradıma ermeyeyim
Hak didârın görmeyeyim
Gonca gülün dermeyeyim
Ölünce sevmezsem seni
Olsun hey efendim olsun
Her kişi ettiğin bulsun
Gözlerim kanlı yaş döksün
Ölünce sevmezsem seni
Sırrım âleme faş olsun
Bağrında biten taş olsun
Gözlerim kanlı yaş olsun
Ölünce sevmezsem seni
Karac''olan olur mürde
Sen düşürdün beni derde
Muhtaç olayım nâmerde
Ölünce sevmezsem seni', 'Şol dergâhtan dönsün yüzüm Ölünce sevmezsem seni Kan ağlasın iki gözüm Ölünce sevmezsem seni Muradıma ermeyeyim Hak didârın görmeyeyim Gonca...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLAĞAN', 'olagan-samih-el-kasim-y6ai9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Değişen bir şey yoktu evrende
Öylesine ürkütücü bir gün
Hayfong''da binlerce ölü vardı
Aden Körfezi''nde, çocukları öldürmüşler
Ve İsrail''de yas başlar yeniden
Anılarda yenilgisi Nazizm''in yeniden
Hani kıyım diye ezberlediğimiz
Gene tehdit savurur Amerikalı komutan
Hedefte bu kez kardeş Suriye
Samih El KASIM', 'Değişen bir şey yoktu evrende Öylesine ürkütücü bir gün Hayfong''da binlerce ölü vardı Aden Körfezi''nde, çocukları öldürmüşler Ve İsrail''de y...', ARRAY['Türk Edebiyatı','Şiir','Samih El Kasim']::text[], 8.5, '{"poet":"Samih El Kasim","poet_slug":"samih_el_kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OĞLANIN TÜRKÜSÜ', 'oglanin-turkusu-gulten-akin-ntiyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim erkeklerimiz
Dört mevsim bahar gibidir
Sevişirken yeniden doğar gibidir
Al atla savaşa girer gibidir
Güzel olur çocuklarımız
Çokturlar, çabuk boylanırlar
Bir aylıkken güler, ikisinde türküye dururlar
Beşinde sığırtmaç, yedisinde sevdalıdırlar
On birinde düğüne ve rakıya ve mavzere
Olursa kır, olmazsa doru.
Yirmisinde, dokusu bir meydanlarda ölürler
Ey gerçek sesimiz ey büyük kavga
Umut iki midir, bir midir?
Düşman şaşkın mıdır, kör müdür?
Kurşun yediveren gül müdür?
Vurulan ölmüyor, bu nasıl vurma?
Ey gerçek sesimiz en büyük kavga
Dağlarda suskunluk sürmeli midir?
Hayınlara aman vermeli midir?
Marşlar alanlarda durmalı mıdır?
Sesi iletmiyor, bu nasıl hava?
Derken, mutlu uykulara yatamayanlar
Yirmilerde yar elini tutamayanlar
Dağa başlarlar.
Dağa başlarlar, çete düşlerler
Burda olmazsa orda
Vurur gider yadellere varırlar
Bu gerçek sanımız, bu büyük seva
Sabah ılımında üveyik midir?
Akar suda kayık mıdır?
Bir alaca geyik midir?
Çeker götürür kana.
Haksızlık nerde olursa olsun
Zulüm nerden gelirse gelsin
Barışla, sevgiyla olmayacaksa
Ey gerçek sesimiz, ey büyük kavga
Yankılan dağdan dağlara
Yankılan dağdan dağlara', 'Bizim erkeklerimiz Dört mevsim bahar gibidir Sevişirken yeniden doğar gibidir Al atla savaşa girer gibidir Güzel olur çocuklarımız Çokturlar...', ARRAY['Türk Edebiyatı','Şiir','Gülten Akin']::text[], 8.5, '{"poet":"Gülten Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLGUNLUK', 'olgunluk-turgay-fi-sekci-nk8ja', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşin altında
Kara toprağın üzerinde
Olgun bir domates gibiyim.
Güneş kokuyor bedenim
Çıplak ayaklarım toprakta
Hep burdaymışlar gibi yerleşik.
Güneş ve toprakla beslenir yıllardır
En güzel meyvesine hazırlanan dilim.', 'Güneşin altında Kara toprağın üzerinde Olgun bir domates gibiyim. Güneş kokuyor bedenim Çıplak ayaklarım toprakta Hep burdaymışlar gibi yerl...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLMACA', 'olmaca-ali-yuce-e5frq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben çocuk olsaydım eğer
Kav çakmak satardım
Bulut amcalara
Pamuk şekeri alırdım yerine
Patlamış mısır alırdım
Ben çiçek olsaydım eğer
Hiç saksı giymezdim ayağıma
Ödünç kanat alırdım
Güvercin teyzemden
Barış uçardım üstünüze
Ben ırmak olsaydım eğer
Altıma saklamazdım ayaklarımı
Öyle yaklaşmazdım denize
Düşmana yaklaşır gibi
Sürüne sürüne
Ben tüfek olsaydım eğer
Patlamazdım kimsenin üstüne
Bir tetiğimden utanırdım
Bir de eğri parmağından
İnsan amcaların', 'Ben çocuk olsaydım eğer Kav çakmak satardım Bulut amcalara Pamuk şekeri alırdım yerine Patlamış mısır alırdım Ben çiçek olsaydım eğer Hiç sa...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüce']::text[], 8.5, '{"poet":"Ali Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLMADI', 'olmadi-ozgur-ozmeral-scj35', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'düşerken kar tanesi bir sözü ikiye bölmüştük
içimden kopup giden bir şeydi tanrı
eşitti her şey ya da bir eşitliğin gölgesinde(n) sızmıştı zaman
sen tutup papatyaların mesnevisini yazdın
kırıldı masamdaki vazo
devrildi bin yıllık kitap
koptu üzerimize teyellenen düğmeler
ve bir taş ansızın öldü
sen bir gözün derinliğine daldın
ben gözlerinde o kar tanesini aradım
köpüklenmişti marmara uzun uzun beklemiştik
bir bebeğin huysuzluna sarılıp uyumak yakışıyordu sana
hırstı, adanmaktı sancıydı hepsine lanetler etmiştim
göçünü tamamlayamamış bir şehre sürgündüm
kuyusunu dolduran, bıçağını körelten cellat zaman
nevrine küfürler yağdırmış üstümüze düşerken
uzun uzun hüzünlenmek sevdası da kalmamıştı
sonsuzluğun pırlanta hissi ve görüntüsü
yakarış çarpıntısı belleğimizde
kör bir limanın son çıkışı
hangi fırtına intiharını gizler artık
tülleri yandı şiirimin, onaramadık bu çocuğu
istanbul kürdili hicazkar kaldı
sahilde tekneler yandı, soyuldu kemancılar
isyanlar çıktı akşamının içine etti rakı
izini bulamadı uzun yol şoförleri
aynası kırıldı gözlerimin bakırköy kan ağladı
parmak izleri buldu mektubumda onlarca polis
bir eski fotoğrafla bekledim hep seni
parmaklarım tutuştu, kalyonunda gizlendi pencerem
serçeler ağıtlarını bıraktı
tutsağı oldum tüm başlangıçların.', 'düşerken kar tanesi bir sözü ikiye bölmüştük içimden kopup giden bir şeydi tanrı eşitti her şey ya da bir eşitliğin gölgesinde(n) sızmıştı z...', ARRAY['Türk Edebiyatı','Şiir','Özgür  Özmeral']::text[], 8.5, '{"poet":"Özgür  Özmeral","poet_slug":"ozgur_ozmeral","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLMAK BAŞLADIĞIMIZ HAYATTI, ON', 'olmak-basladigimiz-hayatti-on-enis-akin-lk9bx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '6:15 vapurunun önünde jeton satan bir çocuktan ders almalı
oysa bir devrim ¾¾
eğer buysa bir devrim ¾¾
mavi giymeli pazar akşamları ve paradan hiç sözetmemeli
ve başlatabilmeli ve bitirebilmeli kendini
ve ağzının kıvrımlarını bir SEK şişesi gibi açabilmeli kapatabilmeli
Açık Kalan Kapılar İmparatorluğundan kalma, ölmün bir oyun olduğu günleri
bence iyi bir devrim çok önemlidir sabah evden çıkmadan
günde en az dört saatini ayna karşısında geçirmeli
cançekişen devrimleri kaldırım kenarında vurmalı, unutmalı
çünkü her devrim hâlâ bir yokuş aşağıya mümkündür, kendinden karşıya
ve bir kafa karışıklığıdır hepsi hepsi ¾¾
olmamalıdır ve yeniden doğmamalıdır
başkasını başlatmaya
oysa biz mesela nasıl alnımızı kullanırken
duvarlara, salatalara ve üretim araçlarının özel mülkiyetine karşı
nasıl korkaktı bu bizim devrimler, hayal dünyasında gezer
televizyonda ele geçen isimler, beddualar, nazarlar sergisi
banknotlara kendi resmini basan kalpazan terziler, kuyumcular, hA!
oysa bir devrim ¾¾
buysa bir devrim ¾¾ tarihin altını ellerdi ¾¾ gencölelim!  ¾¾  gencölelim!
babamsa bir devrim, sadece müziğe doğru ilerlemeli
çünkü doğarken başlar ölmek, çünkü puşttur ahali
iyi bir devrim direnmez karısına ve mezarlığın büyük çağrısına ve
mesela o gece sarhoş olup oynadıysa masada, ertesi sabah utanmaz
ve biriktirdiği gazete kuponlarından ve cinnetinden
çünkü eskimişse mini etekleri çünkü
başlamışsa bir devrim, bitmeye de başlamıştır bir yaşlı sarışın kadın gibi
önce palyaçoyu alın aşağı! önce palyaçoyu alın!
ne ki işte biz kendimize karşı giriştiğimiz
bu aslanlı düelloda hile yaparken
nasıl yeniliriz
ki her takıntı nasıl olsa bir gün el değiştirir
oysa geçen zamandan başka bir devrim yok ¾¾ ve deniz! ¾¾ ve deniz!
ki bu ağızlar hep böyle gıcırtılarla açılır kapanır¾¾ken
işte bu bir devrim, bir
birahanede masaya çarpılan bir şişeyle nasıl başlardı
ve yokuşlardan alaşağı sarsıntılarla edilen dolmuşlarda planladığımız
nasıl ay bizi seyrederken gençliğini hatırlardı
ve biz gümüş atlarımızı sürerken ölmün peşinden ¾¾¾¾.
(adam derin bir nefes aldı ve topyekûn bir karşı saldırıyı başlattı
mona liza''da kol gibi yürek vardı)', '6:15 vapurunun önünde jeton satan bir çocuktan ders almalı oysa bir devrim ¾¾ eğer buysa bir devrim ¾¾ mavi giymeli pazar akşamları ve parad...', ARRAY['Türk Edebiyatı','Şiir','Enis Akin']::text[], 8.5, '{"poet":"Enis Akin","poet_slug":"enis_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLMALI', 'olmali-suat-taser-kktb7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yâr güzel olmalı
Olunca civelek olmalı
Bahar olmalı bahar
Baharda akşam olmalı
Bir pencere olmalı
Denize karşı
Ve her şeyden evvel insan
Âşık olmalı
Pişman değil
Perişan değil
Ümitsiz de değil
Âşık dediğin
Sabırlı olmalı', 'Yâr güzel olmalı Olunca civelek olmalı Bahar olmalı bahar Baharda akşam olmalı Bir pencere olmalı Denize karşı Ve her şeyden evvel insan Âşı...', ARRAY['Türk Edebiyatı','Şiir','Suat Taşer']::text[], 8.5, '{"poet":"Suat Taşer","poet_slug":"suat_taser","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OĞLUM, CELLADIM', 'oglum-celladim-donald-hall-ff1n7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oğlum, celladım,
Kollarıma alıyorum seni,
Ve ısıtıyorum sessiz, küçük,
Yataktan henüz çıkmış gövdeni.
Sevgili ölüm, küçük oğlum,
Ölümsüzlük gerecimiz,
Ağlama ve acıkmaların kaydını tutuyor
Çürüyüp giderken biz.
Yaş yirmi beş, yaş yirmi iki,
Sanki sonsuzca yaşayacaktık.
Hayatın gayretini gördük de sende
Birlikte ölmeye başladık.
Donald HALL', 'Oğlum, celladım, Kollarıma alıyorum seni, Ve ısıtıyorum sessiz, küçük, Yataktan henüz çıkmış gövdeni. Sevgili ölüm, küçük oğlum, Ölümsüzlük ...', ARRAY['Türk Edebiyatı','Şiir','Donald Hall']::text[], 8.5, '{"poet":"Donald Hall","poet_slug":"donald_hall","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OĞLUM', 'oglum-rifat-ilgaz-v022e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'IV
Seni saksıda gül yetiştirir gibi
Yetiştirmedik, tek başına
Bir limonlukta büyütmedik seni.
Kırağı çalmaz diye acı patlıcanı
Salıverdik sokağa;
Düşecektin eninde sonunda
İlk günlerde çok hırlaştınız,
Sonra sokuldunuz birbirinize,
Kaynaştınız karıncalar gibi.
Büyümedin bir dadının dizleri dibinde,
Kucaklarında sütninelerin.
Ne kaf dağındaki peri kızlarına tutuldun,
Ne kurtarmayı düşündün
Şehzadeyi, devler elinden.
Tanımadan Keloğlan''ı
Düştün macuncunun arkasına,
Dolaştın mahalleyi.
Yağmurlu bir günde tanıdın
Göl tutarken bekçinin oğlunu,
Recep''le taşladınız
Atkestanesini, cami avlusunda,
Attınız Emin''le kedi yavrusunu,
Kireç kuyusuna.
Bunlar mahallemizin çocukları;
Henüz bilmiyorsun,
El tarlasında koza düşürürken anası
Sıtma nöbetleri geçirenleri,
Kuzuları doğup
Çoban köpekleri ile büyüyenleri,
İki gözünde heybenin
Çeltiğe giden Yeşilırmak döllerini.
Tanımıyorsun,
Benzi tütün yaprağından soluk
Çocuklarını Sakarya''nın.
Demirindesiniz ayni bıçağın,
İlerde kucaklaşacaksınız, nasıl olsa;
Hazır olsun kalbin onları sevmeye
Daha şimdiden!', 'IV Seni saksıda gül yetiştirir gibi Yetiştirmedik, tek başına Bir limonlukta büyütmedik seni. Kırağı çalmaz diye acı patlıcanı Salıverdik so...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLVİDO', 'olvi-do-ahmet-muhip-dranas-le5cz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hoyrattır bu akşamüstüler daima.
Gün saltanatıyla gitti mi bir defa
Yalnızlığımızla doldurup her yeri
Bir renk çığlığı içinde bahçemizden,
Bir el çıkarmaya başlar bohçamızdan
Lavanta çiçeği kokan kederleri;
Hoyrattır bu akşamüstüler daima.
Dalga dalga hücum edip pişmanlıklar
Unutuşun o tunç kapısını zorlar
Ve ruh, atılan oklarla delik deşik;
İşte, doğduğun eski evdesin birden
Yolunu gözlüyor lamba ve merdiven,
Susmuş ninnilerle gıcırdıyor beşik
Ve cümle yitikler, mağlûplar, mahzunlar...
Söylenmemiş aşkın güzelliğiyledir
Kağıtlarda yarım bırakılmış şiir;
İnsan, yağmur kokan bir sabaha karşı
Hatırlar bir gün bir camı açtığını,
Duran bir bulutu, bir kuş uçtuğunu,
Çöküp peynir ekmek yediği bir taşı...
Bütün bunlar aşkın güzelliğiyledir.
Aşklar uçup gitmiş olmalı bir yazla
Halay çeken kızlar misali kolkola.
Ya sizler! ey geçmiş zaman etekleri,
İhtiyaç ağaçlı, kuytu bahçelerden
Ayışığı gibi sürüklenip giden;
Geceye bırakıp yorgun erkekleri
Salınan etekler fısıltıyla, nazla.
Ebedi âşığın dönüşünü bekler
Yalan yeminlerin tanığı çiçekler
Artık olmayacak baharlar içinde.
Ey, ömrün en güzel türküsü aldanış!
Aldan, geçmiş olsa bile ümitsiz kış;
Her garipsi ayak izi kar içinde
Dönmeyen âşığın serptiği çiçekler.
Ya sen! ey sen! Esen dallar arasından
Bir parıltı gibi görünüp kaybolan
Ne istersin benden akşam saatinde?
Bir gülüşü olsun görülmemiş kadın,
Nasıl ölümsüzsün aynasında aşkın;
Hatıraların bu uyanma vaktinde
Sensin hep, sen, esen dallar arasından.
Ey unutuş! kapat artık pencereni,
Çoktan derinliğine çekmiş deniz beni;
Çıkmaz artık sular altından o dünya.
Bir duman yükselir gibidir kederden
Macerası çoktan bitmiş o şeylerden.
Amansız gecenle yayıl dört yanıma
Ey unutuş! kurtar bu gamlardan beni.', 'Hoyrattır bu akşamüstüler daima. Gün saltanatıyla gitti mi bir defa Yalnızlığımızla doldurup her yeri Bir renk çığlığı içinde bahçemizden, B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dranas","poet_slug":"ahmet_muhip_dranas","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OMAYRA', 'omayra-murathan-mungan-4pwhm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cevabı ömür süren bir soru bıraktım sana
Mendili kan kokan sevgili arkadaşım
Usta bakışların keşfettiği rahatlıkla arkama yaslandım
elimde şah mat yüzüğümde tek taş siyanür
adınla bulanan bir aşkın, bir maceranın
macerasında
yolun sonunu söylüyordu
günahkâr iki melek olan sağdıçlarım
Al birkaç bulutlu sözcük
atlasını sırtında taşıyan çalınmış bir zaman
mekik, taflan, kar kesatı bir iklim
aşk mı, macera mı dersin bu uzun seferberlik
bu ilişkinin topografyasını
mezhepler tarihinden bulup çıkardım
adanan boynunda o gümüş zincir
bilmiyorsun arması sallanıyor ucunda
işte yazgının kara zırhlısı!
Kork! kutsal kitaplardaki kadar kork!
Çünkü hiçtir bütün duygular
Korkunun verimi yanında
Benim ruhum nehirler kadar derin!
Kızıl kısraklar gibi üstümden geçeceksin!
Arı bir sessizlik duruyor
şiddetimizin armaları arasındaki uzaklıkta
gövdenin demir çekirdeği
kalkan teninin altında
sana okunaksız bana saydam giz
içindeki uğultunun izini sürüyorum
bir açıklığa taşıyorum ele vermez yerlerini
harabeler diriliyor
heykeller tamamlanıyor
kendi kehanetinden büyülenmiş gözlerimin önünde
başka çağlara gidip geliyoruz
aşk tanrısı için
seviştiğimiz ve uyuduğumuz sahillerde
aşkın kaplan ve yılan düğümüyle
Öpüyorum seni boynundaki yaradan
iniyorum kaynağına
aydınlanmamış yanların ışığa çıkıyor
dokunuşlarımın parıltısında
düğümlü mendilin, gümüş zincirin
sımsıkı mühürlendiğin bütün kilitler
çözülüyor avuçlarımda
Tılsım tamamlanıyor
ortaçağ kentlerinden geçiyoruz dönüşte
indiğim kaynakların mezhep değiştiriyor
zamanın ve uzamın kilitlendiği kara kutuda benim kelimelerim
tılsım tamamlanıyor
dudaklarımdan sızan erkek sütünün kara büyüsüyle
sevgilim oluyorsun
uyuyor ve yıkanıyoruz ay ışığında
bakıyorum güneş iniyor yüzünün alacakaranlığına
Adın yoktu tanıştığımızda
eksiğini de duymadık
bazen bir rüzgârı, bazen birkaç zeytini
adının yerine kullandık
Adın yoktu tanıştığımızda
sonra da olmadı
çünkü başka biri oldun zamanla
Şimdi adın var
şimdi ruhumun sislere sarılı derinlikleri
yükseliyor ve tehdit ediyor
kıstırılmış varlığımın bütün cephelerini
yüzümün pususunda geziyor
sularda bilenmiş bıçaklar
uyandırılmış acılarım, bulanmış sarnıcım
etimle ruhum arasında çelişen ilke
geri döndü bana
kendi ellerimle kurduğum kara büyüden
içimdeki tarih bitti
siliyorum bir aşkı var eden her ayrıntıdaki parmak izlerini
ve şimdi adın var
ve şimdi
ikimizin vaktinde
intikam saati geldi
Omayra, bu adı verdim sana
ve mevsimleri bütün anlamlarıyla
iki çakılına bir deniz vereyim
hayallerine mavi buğday
dokuz yaşamın olsun tek tek öldüreyim
esmer ve çırılçıplak bir gecede
bütün düşmanların gelecek
koynumdaki cenazene
Seni saran efsane çürüyüp toprağa karışırken
kucağımda başın
gümüş bir tarakla tarayacağım saçlarını
kendi enkazımın üstünde
kurtlar, çakallar gibi uluyarak ağlayacağım acıdan
öldürerek yaşatacağım seni kendimde
Ocağın parıltısıyla aydınlanan yüzün
gücünden habersiz sakin gülüşün
kamçılıyor içimdeki bütün köleleri
ben ki hileli bir oyun,
birkaç kırık zar
ve kara muskalı tılsımlarla
almışken seni kaderinden, kıyasıya bağlamışken kendime
asıl sen tutsak etmişsin beni
dünyaya kapalı kapıların ardındaki
içi boş sessizliğine
sığlığın, sevgisizliğin
o sonsuz kendiliğindenliğin
dünyanın sana değmeyen yerleri
nasıl da çekici yapıyor seni
o kadar bağlandım ki
tutkusuz bedenine
ya öldüreceğim seni
ya tunç çağından heykeller indireceğim dökümüne
Sayıklayan bir ağaç gibiyim Omayra
uğultusu geliyor ta derinden
gövdemin geçtiği masalların
içimdeki deprem ayakta tutuyor beni
geri dönüp vuruyor çalınmış zaman
bak sana korkaklığımı veriyorum
var olmanın bütün varoşlarından
ben yenildim, işte silahlarım
tılsım tamamlandı
sonuna geldim çizgilerini sildiğim
bir büyük haritanın
aşkım ölümün sınırında Omayra
olduğun yerde kal kımıldama!', 'Cevabı ömür süren bir soru bıraktım sana Mendili kan kokan sevgili arkadaşım Usta bakışların keşfettiği rahatlıkla arkama yaslandım elimde ş...', ARRAY['Türk Edebiyatı','Şiir','Murathan Mungan']::text[], 8.5, '{"poet":"Murathan Mungan","poet_slug":"murathan_mungan","theme":"Türk Şiiri","is_hero":false,"total_lines":122}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OMURGANIN KAVALI', 'omurganin-kavali-vladimir-mayakovski-smm8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dumanlar içinde mavi olmayı unutan
gökyüzü,
paçavralar giyinmiş
sığıntı gibi bulutlar,
son aşkımla tutuşacaksınız bütün!
Sevinç çığlıklarımla bastıracağım
ordular
gürültünüzü!
Siz ki bir yuvanın sıcaklığını unutmuşsunuz,
dinleyin !
Ve çıkın artık siperlerden:
bitirmeseniz de olur
savaşı..
Ne en korkunç dövüşlerin,
ne de
kan tüten yaraların en derini
solduramaz aşk sözlerini!
Bilmez olur muyum hiç
sevgili Almanlar!
Dudaklarınızın ucunda hep
Goethe''nin
Gretchen''i var...
Ama o,
yüzyıllardır sayıkladığınız
tombul
pembe tenli kız,
neme gerek benim!
Seni söylüyorum türkülerimde
şimdi ben,
makyajlı
kızıl saçlı sevgilim!
Bu kasatura uçları gibi
sivri
günlerden,
yaşadığımız,
yüzyılların sakalı ağardığında
kalacak olan
sensin yalnız!
Bir de ben...
o kentten
bu kente...
senin ardında!
Londra''nın
kalın
sisinde yitirsem seni,
alev dudaklarıyla
gece lambalarının
gene de uzanır
öperim..
Dalgın
ve hüzünlü,
köprüden geçsen:
"Aşağısı da güzel" diye düşünerek,
"Ve ölmek
de belki güzeldir !" diyerek,
bil ki benim
köprünün altında akan,
benim la Seine,
benim çağıran seni
çürümüş dişlerini göstererek..
Güçlüyüm ben,
gerekliyim çünkü onlara.
"Sıran geldi!"
deseler günün birinde,
savaşa itseler beni,
vurulsam:
Kan değil
adın fışkırır
yırtık dudaklarımdan..
İster
taç giydirsinler,
ister -
se Sainte - Hélène ''e sürsünler:
Hayat fırtınalarının dalgalarını
gene de
ben
mühürlerim!
Ellerim
kelepçelidir evet
ama evrenin
tahtıdır yerim!
Siz
ürkek çocukları
hüznün,
ve siz
gökyüzünün
mavi olduğunu unutanlar!
Dinleyin artık
susun da!
Belki de
son
aşkıdır
bu
gökyüzünün:
onulmaz yarası
kanar da kanar
veremli ciğerlerimin dokusunda.
Vladimir MAYAKOVSKI', 'Dumanlar içinde mavi olmayı unutan gökyüzü, paçavralar giyinmiş sığıntı gibi bulutlar, son aşkımla tutuşacaksınız bütün! Sevinç çığlıklarıml...', ARRAY['Türk Edebiyatı','Şiir','Vladimir Mayakovski']::text[], 8.5, '{"poet":"Vladimir Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":100}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ON YIL ÖNCE', 'on-yil-once-turgay-fi-sekci-xav20', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimlerin dışımızda değiştiği zamanlardı
Hep korunarak geçen günler
Kalkık yakalar , düşük omuzlar
Her an belki bir…
Erguvanların görülmediği bir Nisan’dı
Süs kirazlarının bilinmediği
“Bugun kim?” diye açılan sabahlar
Erguvansız , gri bir Nisan’dı
Ölmemek
Bir insanın sevdiklerine verebileceği tek armağan.
Server Hoca’nın resmiyle açıldı gün
On yıl öncesinin bir Nisan sabahı
Ak çarşaflar içindeydi
Papatya tarlasında uyur gibi.
Ne sevinç , vurulup ölmemek!
Yitse de bedenin bir parçası.
Hocam değildi , derslerine girerdim
Shakespeare tragedyasında bir oyuncu
En çok sesi ve elleriyle oynayan.
Ona en yakışan söz :
“…Ve yükseliyordu proleterya!”
O an kürsünün altından çıkıp
Parmak uçlarında yükselen
Koca yumruğu başının yanında bir ikinci yüz
Yeniden doğar gibi söylenen o söz…
XVIII. yüzyılın sonları
Aydınlanma. Aydınlandık.
Bahçesinde erguvanlar açmıştı okulun
Bir kızla öpüşmek kadar güzeldi dalında oturmak
Kiraz çiçekleri , rüzgârda dağılıveren ilkgençlik
Sesi kulağımda Server Hoca’nın
“Ve yükseliyordu proleterya!”
Bir gün ziyaretine gitmiştim
Yaşayan , yani çalışan ve üretendi
Maddenin en canlısı yürekti
Bu dizemi söyledi bana ve başkalarına.
Turgay FİŞEKÇİ
---------------------------------------------------------------------------------------', 'Mevsimlerin dışımızda değiştiği zamanlardı Hep korunarak geçen günler Kalkık yakalar , düşük omuzlar Her an belki bir… Erguvanların görülmed...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O''NA', 'o-na-aleksandr-sergeyevic-puski-n-5hcgg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anımsıyorum o büyülü ânı
Karşımda beliriverdiğin,
Uçup gidici bir hayal gibi,
Dehası gibi saf güzelliğin.
Bunluklarında ümitsiz hüznün,
Telâşın yorucu tasalarında,
Çınlardı o tatlı ses uzun uzun,
O güzelim çizgiler görünürdü bana.
Yıllar geçti. İsyancı dalgalarında fırtınaların
Dağılıp söndü eski hayaller,
Unuttum tatlı sesini senin
Ve silindi Tanrısal çizgiler.
Issızlıkta, karanlığında tutsaklığın
Sessizce uzayıp gidiyordu günlerim
Tanrısız, esinsiz, gözyaşsız,
Yaşamsız ve sevgisizdim.
Ve bir an geldi, uyandı ruhum:
Ve işte sen yeniden belirdin,
Bir hayal gibi, uçup giden,
Dehası gibi saf güzelliğin.
Ve yürek çarpıyor bir esrimeyle,
Ve yeniden canlanıyorlar onda
Tanrısallık da, esin de,
Yaşam da, gözyaşı da, aşk da.
Aleksandr Sergeyeviç PUŞKİN', 'Anımsıyorum o büyülü ânı Karşımda beliriverdiğin, Uçup gidici bir hayal gibi, Dehası gibi saf güzelliğin. Bunluklarında ümitsiz hüznün, Telâ...', ARRAY['Türk Edebiyatı','Şiir','Aleksandr Sergeyeviç Puşki̇n']::text[], 8.5, '{"poet":"Aleksandr Sergeyeviç Puşki̇n","poet_slug":"aleksandr_sergeyevic_puskin","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONAR MISRA', 'onar-misra-yasar-nabi-nayir-tev46', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'II
Ayırma gözlerini gözlerimden benden bu akşam,
Böyle saatlerce bak, böyle asırlarca bak.
Gözlerine yavaşça, yavaşça doldu akşam...
Göklerin ateşini kalbime boşaltarak
Benim içimde yaktı sanki gurubu akşam.
Senin kirpiklerinde bir damla oldu akşam.
Gündüzden, gürültüden ve kâinattan ırak,
Akşamı seyredeyim bakışlarında bırak,
Ayırma gözlerini gözlerimden bu akşam,
Böyle saatlerce bak, böyle asırlarca bak.', 'II Ayırma gözlerini gözlerimden benden bu akşam, Böyle saatlerce bak, böyle asırlarca bak. Gözlerine yavaşça, yavaşça doldu akşam... Gökleri...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Nabi Nayir']::text[], 8.5, '{"poet":"Yaşar Nabi Nayir","poet_slug":"yasar_nabi_nayir","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONBİRİNCİ SONNET', 'onbi-ri-nci-sonnet-hasan-i-zzetti-n-di-namo-yde0b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendimi varisi sanırdım şiir imparatorluğunun
Belki de bu yüzden ömrüm boyunca sürgünlerde gezdim.
İçimdeki altın yeleli arslanı görmeseydi kanun
Bir canavar gibi gurbet gurbet böyle sürülmezdim.
Güzel bir Türkiye hayali ve mutlu insanlar
Oturdu yazamadığım şiirlerime boydan boya.
Katakomplardan kalkan düşüncelerin döktüğü kanlar
Çaldı en uysal düşünceme bir kanlı boya.
Dikildi karşıma demirden yumruğuyla felek
Yol verdi birer birer geçsin diye cücelere
Sürdü beni taşından altın yapılmayan gecelere.
Beni demir kazıklara bağlarken sürgünler
Ve geçip giderken kaplumbağa gibi günler
Böğürüp dururdu danalar gibi salhanede gerçek!', 'Kendimi varisi sanırdım şiir imparatorluğunun Belki de bu yüzden ömrüm boyunca sürgünlerde gezdim. İçimdeki altın yeleli arslanı görmeseydi ...', ARRAY['Türk Edebiyatı','Şiir','Hasan İzzetti̇n Di̇namo']::text[], 8.5, '{"poet":"Hasan İzzetti̇n Di̇namo","poet_slug":"hasan_izzettin_dinamo","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONLAR BAŞKA', 'onlar-baska-afsar-ti-muci-n-2cvf3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onlar herşeyi yalan yazar
Şiirleri masalları bile
Sen beni dinle çocuğum
Sakın korkma
Kan denizi yok gökte
Hiç korkmadan uyu sabaha kadar
Gümüş aylar birden batıp
Yemyeşil bulutlarda
Sarı güneşler doğsun
Gülüm menekşem papatyam
Öğrenince güleceksin
Kan denizi yok gökte', 'Onlar herşeyi yalan yazar Şiirleri masalları bile Sen beni dinle çocuğum Sakın korkma Kan denizi yok gökte Hiç korkmadan uyu sabaha kadar Gü...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONLAR', 'onlar-sait-maden-ywh5n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onlar onlar ışıyıp gecemizde ay kadınları,
ay kadınları,
onlar aşka örs alınları...
Onlar gecemizde ay kadınları,
ay kadınları,
ey sevinç testileri, ey ışığın en yalınları!
Onlar gecemizde ay kadınları,
ay kadınları,
Sedef kutularda kitlendi hep yarınları.
Onlar ay kadınları,
ay kadınları,
öfkemizin ifritine gebeyken saf karınları.
Ay kadınları,
ay kadınları,
oldular âh ölümün, zor demirin sırça kınları!', 'Onlar onlar ışıyıp gecemizde ay kadınları, ay kadınları, onlar aşka örs alınları... Onlar gecemizde ay kadınları, ay kadınları, ey sevinç te...', ARRAY['Türk Edebiyatı','Şiir','Sait Maden']::text[], 8.5, '{"poet":"Sait Maden","poet_slug":"sait_maden","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONLARIN SESLERİYLE', 'onlarin-sesleri-yle-kemal-ozer-1oq1j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'buluşuncaya kadar orda burda savrulup duran
binlerce başıboş anı
kimi çoktandır çağrışımı eksik sözlerle
söyleyenden yoksun bir şarkı
kimi darmadağın bir düş
belli değil hangi göze nasıl bir uyanıştan yansıdığı
niye bırakıldığı unutulmuş bir karanfilden
kiminin bir kaldırıma sızıyor ışığı
kiminde her darağacından bir şafak
her ağıttan biz dize, her yıldönümünden bir yankı
artık ne darmadağın ne unutulmuş ne eksik
hiçbiri sahipsiz değil onların sesleriyle buluşalı', 'buluşuncaya kadar orda burda savrulup duran binlerce başıboş anı kimi çoktandır çağrışımı eksik sözlerle söyleyenden yoksun bir şarkı kimi d...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONLARSIZ', 'onlarsiz-tekin-gonenc-5qdmu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benim güzel olduğum yerlerde
siz hiç olmadınız
gölgemdi o
değip geçen gözlerinize
soluklarımla taşıdım hep
sancısını sokakların
ondandır dağbaşlarına
o tavşansı
o rüzgâr kaçışlarım
bir gemi ellerimi getirir
bir fırtına saçlarımı uzaklardan
bu ben böyle olur muydum hiç
hep sizinle olsam
ondandır dağbaşlarına
o tavşansı
o rüzgâr kaçışlarım
bir gün sizi tutup buralara getirsem
diner mi bilmem
sancısı sokakların
ama yok
sizin güzel olduğunuz yerlerde
ben hiç olmayacağım', 'benim güzel olduğum yerlerde siz hiç olmadınız gölgemdi o değip geçen gözlerinize soluklarımla taşıdım hep sancısını sokakların ondandır dağ...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin_gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ONUN ÇÖLÜNDE', 'onun-colunde-bejan-matur-89mph', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onun çölüne gittim.
Konuğum,
Duvardaki kan pıhtısında.
Onun bulduğu damar beni çağırdı.
Ve ruhum eski bir kanla yıkandı.
Onun çölüne düştüm, oturdum çadırında.
Eski bir kavmin buluşması ve töreni.
Bir yaban kuş gibi tüneyip kıyıya
Dedi ki bana  "ölümsün sen"
Mutlak
Mutlak olan.
Onun çölünde gece kımıldar.
Yılan ve akrep karanlığıyla.
Hayat bir zehre gizlenir
Çoğalır sabırla.
O bıraktı beni.
Çöldeki kızıl sularda
Balıklara bakacak
Nefesimi tutarak
Uyuyacağım.
Onun çölünde her gece
Fısıldadım kumlara.
Sordum nasıl yaptıklarını çölü,
Boğmadan koyun koyuna.
Onun çölünde ölüyüm ben.
Gelin ve kaldırın beni.
Gittiği yolda bulutlara değen bir gölge bırakılmış sanki.
Bir sesle uyandıracak beni
Kahra kan olan bir aldanışla yakaracak
Tanrıya söylendim.
Nasıl da zalim gövdede varlığı onun.
Güzellik acıya kavuştuğunda yorulur ve
Hep yaşlı kalacak bir gözün ışığıyla bakar;
Her yüz bir işarettir tanrıdan.
Bunu yaşlı bir adam söylediğinde
Gözleri yoktu.
Annem öyle inanmış olmalı ki ona,
Yüzümü kederli çizdi.
Ve uzayıp tanrıya
"işte" dedi
"benim annem yeniden doğdu
annem varlığıma döndü"
Gece paslı bir kafesle durdu önümde
Dua için zaman istedim tanrıdan.
Onun varlığına adanacak hiçlik
Düş için,
O büyüde kalbime saplanan acıyla
Bağırdım;
Başka adamlar, başka dillerde dua etsinler. Bizim için.
Ölümü tanıdığımız ve sessiz olduğumuz için
Kutsasınlar.
Ölü bir yaprağın sürüklenişi gibi rüzgârda
Gövdem yitirdi yerini.
Ağır bir uykuyla gizlendi tohuma varlık.
Ağır bir istekle.
Kızıl kan pıhtısı. Tül sabah. Ört üstümü.
Koyu gücünü yüzünün nasıl çizdiyse tanrı
Ve ne gizlediyse kıvrımına gülüşünün.
Gördüm ben.
Tüllere sarılmış çölde ölümümü bekliyorum. Sakinim.
Yok bir gece bu.
Sabah uyanacak aşkı konuşacağız.
Ne çok sürdü diyecek bana.
Ne uzun sürdü hayat.
O uzun günün sabahında
Sesini duydum gün ve gecenin çakışmasının.
Bir tül işleniyormuş gibi aralarında
Kavuştular usulca.
Uyu ağır uykunu
Taşların altında ve su isteğinle kal.
Geniş bir avluda gece kapanan kapıların ağırlığı.
Sürecek olan dilsizlik.
Rüzgâr tırmalıyor kapını
Aşk uzakta.
Ne tuhaf inanmaman.
Sırtıma dokundun ve orada ayla ışıyan çizgilerin
Bir acıdan artan masumiyet olduğuna şaşırdın.
Gideceğini söyledin
İnanmadım sana.
Oysa ben daha doğmadan biliyordum.
Acılı bir ruhta oyalanan bir gövde bu.
Saf ve çocukça bir düşün yatağında.
Kan ve susuşla dinlenen ten kabullenir.
Beyaz tül yatağında başucuma
Camdan bir göz bırakıp gittin.
Ona fısıldanan sözlerin
Aşk olan varlığı
O gidince karardı.
Yüzeyinde göğün
Beyaz ve kıpırtısızım.
Acıdan bir okla çıktım
Bekleyiş yatağından.
İçimde siyah bir taş.
Atları gördüm.
Kapı önlerinde oturan insanı, sözü.
Çok yaşanmış bir çığlıkla hayat.
Bir sırrın bana verilmediği yerden
Sordum ona
Bana ne söyleyeceksin?
Çölün söylemediği ne?
Ruhumu orada tutan ağırlıkla
Geceye ilendi tenim.
Ve çağırmadı çölü varlığım
Ondan sonra.
Aynaya dönüyorum
Değişmiş gözlerim.
Çölde kumlara bakan kadın
Kedere bakan
Artık benim.
Gördüm çizgilerini avuçlarının
Çöl her şeyi söyledi bana.
Anladım nerede bitti aşk
Kan pıhtılı odanda uyanan gövdem
Neden sığmadı varlığa.
Seni yaprakların gölgeli yalnızlığına bırakıyorum.
Gün doğumunda uyanan nefese ve sana dönen gözlerin
Yakaran çizgisine.
Çölden aldığını çöle ver
Hayattan aldığını hayata.
Artık beklemiyorum
Kal orada.
Geride, tepelerin art arda dizilmekle
Var ettikleri dünya bir hiçlik ahtı gibi.
Bir hiç ve gölge.
Gece ay
Gece tül ve yokluk.
Yok gece.
Çölden aldığını çöle ver
Hayattan aldığını hayata.', 'Onun çölüne gittim. Konuğum, Duvardaki kan pıhtısında. Onun bulduğu damar beni çağırdı. Ve ruhum eski bir kanla yıkandı. Onun çölüne düştüm,...', ARRAY['Türk Edebiyatı','Şiir','Bejan Matur']::text[], 8.5, '{"poet":"Bejan Matur","poet_slug":"bejan_matur","theme":"Türk Şiiri","is_hero":false,"total_lines":131}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORADA DURAN', 'orada-duran-vecihi-ti-muroglu-woihj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün gece gördüm seni
Ay doğarken oradaydın
Bir içim suydu çocukluğun
Keşke o gün içseydim seni
Dün gece ay doğarken
Ormanda ışıkla oynaşan
Bir mor menekşeydi çocukluğun
Keşke o gün koklasaydım seni
Ay ışığı saçılırken geceye
Oradaydın saçların omuzlarında
Fırınlanmış bir meşe tahtasında
Yıkasalardı seni yeşerirdi
Keşke o gün öpseydim seni', 'Dün gece gördüm seni Ay doğarken oradaydın Bir içim suydu çocukluğun Keşke o gün içseydim seni Dün gece ay doğarken Ormanda ışıkla oynaşan B...', ARRAY['Türk Edebiyatı','Şiir','Vecihi Ti̇muroğlu']::text[], 8.5, '{"poet":"Vecihi Ti̇muroğlu","poet_slug":"vecihi_timuroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORADAKİ', 'oradaki-sukran-kurdakul-ln91b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kendi uzaklığımdan kurtularak
Hüküm giymiş bir mısra gibi
Çıktım parmaklığımdan
Kendimde duydum ellerimi.
Nicedir sessizliğimde kanayan
Acımın yorgun yüreği
Dirençlerin, yıkımların ardından
Eski kaygılara götüremedi beni.
Defterlerim, kitaplarım, kalemim
Güzelliğin ustası, umudun da ustası olan
Açıldı düşlerin çocuk bahçeleri
Geceye doğru ranzamdan.', 'Kendi uzaklığımdan kurtularak Hüküm giymiş bir mısra gibi Çıktım parmaklığımdan Kendimde duydum ellerimi. Nicedir sessizliğimde kanayan Acım...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORAMAR', 'oramar-onat-kutlar-ftch1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Telefon direğinde bir yeni yaprak
Yaralı, gergin bir dişi tayın yelesi
Kiraz çalgısının dalıydı sesin
Bir bahar vuruşuyla titreyen
Unutma bana ve tüm yeryüzüne
Yepyeni sevinçler vereceksin
Bir tek kiraz yesen çekirdeğini
Karnının tarlasına eken sen
Kale yollarından geçtik yıllardır
Bir düş ülkesine ulaşmak için
Bırak bütün düşlerini ırmağa
Adı senin olan yere gel hemen', 'Telefon direğinde bir yeni yaprak Yaralı, gergin bir dişi tayın yelesi Kiraz çalgısının dalıydı sesin Bir bahar vuruşuyla titreyen Unutma ba...', ARRAY['Türk Edebiyatı','Şiir','Onat Kutlar']::text[], 8.5, '{"poet":"Onat Kutlar","poet_slug":"onat_kutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORANLAMA', 'oranlama-hasan-huseyi-n-0kzzh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sen eksiktin sarıyıldız hoşgeldin
Geç bakalım karşıma benimle içer misin
Ağlar mısın içince burnuna çeker misin
Gözyaşların yakabilir mi dudaklarımı
Ama neden titriyorsun öyle sarıyıldız
Bak ben su taşıyorum ince elekle
İğne deliğinden dünyayı geçiriyorum
Bak ben aklıma uyup sarıyıldız
Durmadan aklımı şaşırıyorum
Sen beni kaçıncı binden tanıyorsun ki
Hadi bana çelik mavisi bir gece getir
Hadi dostlukları tek tek koparıp getir
Alnımdan öp beni e mi, yitik sıcaklığımı getir
Gençliğimi çılgınlığımı deli günlerimi getir
Ne o sarıyıldız sen de mi ağlıyorsun', 'Bir sen eksiktin sarıyıldız hoşgeldin Geç bakalım karşıma benimle içer misin Ağlar mısın içince burnuna çeker misin Gözyaşların yakabilir mi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyi̇n']::text[], 8.5, '{"poet":"Hasan Hüseyi̇n","poet_slug":"hasan_huseyin_korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORDA BİR KÖY VAR UZAKTA', 'orda-bi-r-koy-var-uzakta-ahmet-kutsi-tecer-z47tg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Orda bir köy var, uzakta,
O köy bizim köyümüzdür.
Gezmesek de, tozmasak da
O köy bizim köyümüzdür.
Orda bir ev var, uzakta,
O ev bizim evimizdir.
Yatmasak da, kalkmasak da
O ev bizim evimizdir.
Orda bir ses var, uzakta,
O ses bizim sesimizdir.
Duymasak da, tınmasak da
O ses bizim sesimizdir.
Orda bir dağ var, uzakta,
O dağ bizim dağımızdır.
İnmesek de, çıkmasak da
O dağ bizim dağımızdır.
Orda bir yol var, uzakta,
O yol bizim yolumuzdur.
Dönmesek de, varmasak da
O yol bizim yolumuzdur.', 'Orda bir köy var, uzakta, O köy bizim köyümüzdür. Gezmesek de, tozmasak da O köy bizim köyümüzdür. Orda bir ev var, uzakta, O ev bizim evimi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kutsi Tecer']::text[], 8.5, '{"poet":"Ahmet Kutsi Tecer","poet_slug":"ahmet_kutsi_tecer","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORDA BİR KÖY YOK UZAKTA', 'orda-bi-r-koy-yok-uzakta-a-hicri-i-zgoren-n1j2m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerimi kanatıyor her gece
Dudaklarında donmuş gülümsemesi
O muhacir evde asılı duruyor hâlâ
Yitirilmiş bir arkadaş sureti
Anılar mı yakın bana acı mıdır en eski
Bir sağnak yıkasa yaralarımı belki
Yumuşayacak gecenin mimikleri ağrılarım dinecek
Ya da korunak olacak karanlığın kendisi
Hava su ve toprak kirlendi artık
Tuz ve ekmeğe karışıyor yüksek gerilim
Yeryüzünün bütün koordinatları
Barınacak bir yer arıyor
Haritadan silindi yüreğimin meskûn yerleri
Her gün kütüklerden aşklar düşüyor hayat
Artık  "ölü sayısı..." belirliyor gündemi', 'Düşlerimi kanatıyor her gece Dudaklarında donmuş gülümsemesi O muhacir evde asılı duruyor hâlâ Yitirilmiş bir arkadaş sureti Anılar mı yakın...', ARRAY['Türk Edebiyatı','Şiir','A. Hicri İzgören']::text[], 8.5, '{"poet":"A. Hicri İzgören","poet_slug":"a_hicri_izgoren","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORDA BİR ÇOCUK... BURDA BEN', 'orda-bi-r-cocuk-burda-ben-yavuz-bulent-b-ki-ler-qyxyu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ana gülümserken yorgun ve güzel
Yüreği müjdelerle tüy gibi hafiflerken,
Orda, bir çocuk doğar sımsıcak dünyamıza
Burda ben...
Dal nasıl, yaprak nasıl, ekin nasıl büyürse
Toprak nasıl uyanırsa bir incecik yağmurdan
Orda bir çocuk büyür yumak yumak bir nurdan,
Burda ben...
Koştuğu, atladığı, durduğu, uzandığı,
Düşüp kaldığı yerlerde gözbebeğim var.
Orda, toz-toprak içinde bir çocuk ağlar,
Burda ben...
Ne oyun oynamak ister, ne uyku ne su,
Ne elişi resimleri gönlünü alır.
Orda, bir uzak evde bir çocuk yetim kalır,
Burda ben...
Dokunsam, martı gibi uçup gidecek sanki,
Solgun yüzlü bir avuç kar.
Orda, bir gece yarısı, bir hasta çocuk sayıklar,
Burda ben...
Birden bire uyanır bir ana uykusundan,
Sapsarı bir korkuyla bakakalır nefessiz.
Orda, sabaha karşı bir çocuk ölür sessiz,
Burda ben...', 'Bir ana gülümserken yorgun ve güzel Yüreği müjdelerle tüy gibi hafiflerken, Orda, bir çocuk doğar sımsıcak dünyamıza Burda ben... Dal nasıl,...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bâki̇ler']::text[], 8.5, '{"poet":"Yavuz Bülent Bâki̇ler","poet_slug":"yavuz_bulent_bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORHAN VELİ KANIK', 'orhan-veli-kanik-sait-maden-dnxid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu çay, bu simit, bu nisan günü sokakta!...
Yaşamın özünü buldum sokakta.', 'Bu çay, bu simit, bu nisan günü sokakta!... Yaşamın özünü buldum sokakta....', ARRAY['Türk Edebiyatı','Şiir','Sait Maden']::text[], 8.5, '{"poet":"Sait Maden","poet_slug":"sait_maden","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORHAN VELİ', 'orhan-veli-orhan-veli-6k36a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bütün Şiirleri, Orhan VELİ,
Adam Yayınları
Hey gidi Orhan Veli,
Denizlerin ve İstanbul''un şairi!
Seni bir kitaba sığdırmak mümkün mü?', 'Bütün Şiirleri, Orhan VELİ, Adam Yayınları Hey gidi Orhan Veli, Denizlerin ve İstanbul''un şairi! Seni bir kitaba sığdırmak mümkün mü?...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORMAN', 'orman-arkadas-zekai-ozger-4vcd6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yusufçuğum
kanadından mı vuruldun
ben vuruldum.
av erken başlamadı
hanidir yaslı dağlar
bu tüy kimden düştü
hangi avcı, hayın avcı
gergin kanatlarının gölgesinde avlanır da
görmez mi ki, bilmez mi ki
kendi ormanıdır
usu gelişirken büyüyen tüylerinde
okşanır onlar yalnız, arınır, parlanır
çoğalsın diye kanadının ormanı
yolunmaz ki, koparılmaz ki
yusufçuk, yusufçuğum
kanadından mı vurdular, vursunlar
gün tanlayınca gövertisini
halk ormanı ışıyacak
bin yusufçuk uçucak
bin yusufçuk konuşacak', 'yusufçuğum kanadından mı vuruldun ben vuruldum. av erken başlamadı hanidir yaslı dağlar bu tüy kimden düştü hangi avcı, hayın avcı gergin ka...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas_zekai_ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORMANDA BÜYÜYEN ADAM AZGINI', 'ormanda-buyuyen-adam-azgini-kazak-abdal-10czr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ormanda büyüyen adam azgını
Çarşıda pazarda insan beğenmez
Medrese kaçkını softa bozgunu
Selâm vermek için kesen beğenmez
Âlemi ta''n eder yanına varsam
Seni yanıltır bir mesele sorsan
Bir cim çıkmaz eğer karnını yarsan
Câmiye gelir de erkân beğenmez
Elin kapısında kul kardaş olan
Burnu sümüklü hem gözü yaş olan
Bayramdan bayrama bir tıraş olan
Berbere gelir de dükkân beğenmez
Dağlarda bayırda gezen bir yörük
Kimi tımar sipah kimi ser-bölük
Bir elife dili dönmeyen hödük
Şehristâna gelir ezân beğenmez
Bir çubuğu vardır gayet küçücek
Zu''m-ı fâsidince keyif sürecek
Kırık çanağı yok ayran içecek
Kahvede fağfuri fincân beğenmez
Yaz olunca yayla yayla göçenler
Topuz korkusundan şardan kaçanlar
Meşe yaprağını kıyıp içenler
Rumeli bohçasını duhân beğenmez
Aslında neslinde giymemiş hâre
İş gelmez elinden gitmez bir kâre
Sandığı gömleksiz duran mekkâre
Bedestene gelir kaftan beğenmez
Kazak Abdal söyler bu türlü sözü
Yoğurt ayran ile hallolmuş özü
Köyden şehre gelen bir köylü kızı
İnci yakut ister mercân beğenmez', 'Ormanda büyüyen adam azgını Çarşıda pazarda insan beğenmez Medrese kaçkını softa bozgunu Selâm vermek için kesen beğenmez Âlemi ta''n eder ya...', ARRAY['Türk Edebiyatı','Şiir','Kazak Abdal']::text[], 8.5, '{"poet":"Kazak Abdal","poet_slug":"kazak_abdal","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORMANIZ BİZ', 'ormaniz-bi-z-rifat-ilgaz-x1aqe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşayıp gidiyoruz bir arada
Meşe, çam, köknar, kayın…
Bırakın kirli kentlerinizi,
Biraz da aramızda yaşayın!
Varsın derinde olsun köklerimiz
Yükselmek için yarış bizde.
Görülmüş mü ağacın ağaca kıydığı,
Sevgiyle yaşamak barış bizde!
Mutluyuz birlikte yaşamaktan
Meşe, çam, köknar, kayın…
Sarılın toprağınıza bir çınar gibi
Bize de kendinize de kıymayın.
Ne demiş en büyük ozanımız
Neden kulak vermiyorsunuz sesine
Bir ağaç gibi hür yaşayın dememiş mi,
Ve bir orman gibi kardeşçesine?
Kulağımız Kirişte  adlı şiir kitabından 1983
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Yaşayıp gidiyoruz bir arada Meşe, çam, köknar, kayın… Bırakın kirli kentlerinizi, Biraz da aramızda yaşayın! Varsın derinde olsun köklerimiz...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORTA İKİDEN AYRILAN ÇOCUKLAR İÇİN ŞİİRLER', 'orta-i-ki-den-ayrilan-cocuklar-i-ci-n-si-i-rler-ece-ayhan-jbkb0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sivil ölümden konuşuyoruz dağılan neftilikler
arkadaşlar Makedonyalı kalın usta marangozlar.
Kapaklanır bir adam daha kaçıncı, aktığımızı görünce
ters çevrilmiş kente karşı işte onun denizlerine
delikanlı kostaklarımızı çıkarmış ve ırmaktır.
Erkek ölümden konuşuyoruz yeni ormanlardan
dahi "dikeni seven gülüne katlanır bir kadın"dan.
Haramiler ki kırkın üstünde artık sayıları
bir küçük tabut tabakada gezdirirler ölüleri fakfon
burunları çekmek üzre, ince çağrışımlıdır.
Ey orta ikiden ölerek ayrılan çocuklar! aslında başlayan
askerler tabiatta hâlâ tramvaydan Sirkeci''de mi inerler?
süsüne kaçılmamış bir cenaze törenine gitmek için.', 'Sivil ölümden konuşuyoruz dağılan neftilikler arkadaşlar Makedonyalı kalın usta marangozlar. Kapaklanır bir adam daha kaçıncı, aktığımızı gö...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORTANIN DOĞUSU', 'ortanin-dogusu-yusuf-altunel-hs0yr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'tutup cımbızla
yerleştirmişler ortaya
karnımıza açlık
sırtımıza sopa
yorganımıza bit doğmuş
aramıza kin…
ortanın solu gibi birşey bu
aramız o kadar derin', 'tutup cımbızla yerleştirmişler ortaya karnımıza açlık sırtımıza sopa yorganımıza bit doğmuş aramıza kin… ortanın solu gibi birşey bu aramız ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORTOPEDİ', 'ortopedi-ender-sariyati-y21xr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.
o bir kayaya oydu yazıtını
kemah''ta yontulmamış bir akşamüstü
görsün diye güneş
tezeğin mimarlığını et ve kemik üstünde
kışın
o
elini nasıl kurtarır korosundan bataklık ve sazın
saz ki her gün durgun sulara çizer yüzünü
çocuklar koşar sesinde
yürekler iyimserlik avlusu
erkekçil kuşlar uçar fesinde çarıklı amcanın
evlat
pipom kaçak tütünüm
yüreğimin içli yanıdır
gözleri kızının olduğunda dolar
çifte namussuzdur
ve bir mart üzümünü özler
bu sakallılar hangi ülkenin kâşifi
ya bu yüreğimi ısıtan bozkır akşamı
uzat avcunu
gitsin şehir kuşları dolar
6x6 revo
yarın ayakta durabilmek deneyine
tanrı yazıtını
ihtiyara ve piposuna işler
II.
ey şairler doğu bir şölen kurdu sizlere
açlığa
açıklığa savaşa
çizmelerinize uygarlık için
III.
soyun gökyüzü
soyun şiir
kuşan şair
bu uzun yayla kâğıtları
size besili ceylanlarını sunacak
ve duraklarda koşan gazetelerde
general halk için konuştu
IV.
doğu ortopedi koridoru
kırık çıkık kuşlar
yaşam oyuncak heykel
heykele koşuyor eli karnında kadın
biçimlendirmek için
doğanın doğusunu
tanrı
yaşlı dev gülüyor
eli önünde her gün geçen bu bandolu şölene', 'I. o bir kayaya oydu yazıtını kemah''ta yontulmamış bir akşamüstü görsün diye güneş tezeğin mimarlığını et ve kemik üstünde kışın o elini nas...', ARRAY['Türk Edebiyatı','Şiir','Ender Sariyati']::text[], 8.5, '{"poet":"Ender Sariyati","poet_slug":"ender_sariyati","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ORUÇ', 'oruc-enis-batur-esw5b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tabak tarhana koydu
önüne, bir avuç maydanoz;
parmaklarını tuttu, bileğini,
kolunun içini öpüp bıraktı,
soğanı kırdı, böldü ekmeği ve
bekledi: Zaman hızla içine
akıyordu.
"Bu seferî gövde sana birikti"
dedi, duyulur duyulmaz
bir sesle.', 'Bir tabak tarhana koydu önüne, bir avuç maydanoz; parmaklarını tuttu, bileğini, kolunun içini öpüp bıraktı, soğanı kırdı, böldü ekmeği ve be...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTAĞ', 'otag-kemal-ozer-27s95', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen benim korkum musun uyuyup uyanmayan
sorulsa nerden nasıl günlerin yatağına
düzelmez kıvrımıyla bir daha kalkmamanın
kaşlarını getiren çizilmiş bir adama
bir tutup bir çekerek yüzünü yargıçların
yüzünü sana borçlu her akşam bir kadının
yüzünü sana borçlu her akşam bir kadının
korkuma çıplaklığı beyazlığı yakışan
sen benim dargınımsın sevişme otağına
babası aşk bıkkını annesi buzlu camdan
kaç kereler diz çökmüş diz çökmüş yalvarmaya
ya da bu ilk ölüsü elimdeki bıçağın
havamda kelimeler onun kelimeleri
bana da silâhı var ona gelen düşmanın
sen beni suya iten incecik yaz öğlesi
yangınını öğrettin açtığım her yaranın
sen bana bir yakınlık bir ateş yakınlığı
kendi kendine yanmış kimseyi ısıtmayan
desinler ona kaçtı bırakıp yalnızlığı
daha hiçbir kaçağın işlemediği suçtan
alarak şapkasını sonsuzluğa asılı', 'sen benim korkum musun uyuyup uyanmayan sorulsa nerden nasıl günlerin yatağına düzelmez kıvrımıyla bir daha kalkmamanın kaşlarını getiren çi...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTEL ODALARI', 'otel-odalari-necip-fazil-kisakurek-8zisr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir merhamettir yanan, daracık odaların,
İsli lâmbalarında, isli lâmbalarında.
Gelip geçen her yüzden gizli bir akis kalmış,
Küflü aynalarında, küflü aynalarında.
Atılan elbiseler, boğazlanmış bir adam,
Kırık masalarında, kırık masalarında.
Bir sırrı sürüklüyor, terlikler tıpır tıpır,
İzbe sofalarında, izbe sofalarında.
Atıyor sızıların, çıplak duvarda nabzı,
Çivi yaralarında, çivi yaralarında.
Kulak verin ki, zaman, tahtayı kemiriyor,
Tavan aralarında, tavan aralarında.
Ağlayın, âşinasız, sessiz, can verenlere,
Otel odalarında, otel odalarında!...', 'Bir merhamettir yanan, daracık odaların, İsli lâmbalarında, isli lâmbalarında. Gelip geçen her yüzden gizli bir akis kalmış, Küflü aynaların...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTEL YORGUNU', 'otel-yorgunu-altay-omer-erdogan-f021h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hitit babacan güneşler ağartırdı
kardeş kanı toprağa karıştığında
ikinciye kullanılmayan bilgelik damıtırdı
safdil akıl ruh ile yarıştığında
körlüğüyle övünen halklar gördük
tarihin kanlı parmaklarında birer tespih tanesi
biz de en az onlar kadar kördük
en gür haykıranımızın en önce kısıldı sesi
ısırgan otları ve zakkumlar arasından
yanık tenlere sonuçsuz denklemler eğiren
bir yüzü vardı ayvanın sarısından
gözüydü otel yorgunluklarını seğiren
kuma gömüp müzmin evsizliğimizi
sayıklar o büyük yalnızlığı geceler
otellere yapıştırdı gölgemizi
hayatı sorgulayan külden heceler
bir kibritlik yol aldık
dev aynasında cüceler
(Akatalpa, Temmuz 2003 )', 'Hitit babacan güneşler ağartırdı kardeş kanı toprağa karıştığında ikinciye kullanılmayan bilgelik damıtırdı safdil akıl ruh ile yarıştığında...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTOBÜS', 'otobus-cahit-kulebi-lsosk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hey yol üstündeki otobüs
Karoserin ne yeni!
Kız gibi motorun var,
Benzin kokuyorsun
Lastiklerin sağlam.
Uçup gider misin şoförün olsam!', 'Hey yol üstündeki otobüs Karoserin ne yeni! Kız gibi motorun var, Benzin kokuyorsun Lastiklerin sağlam. Uçup gider misin şoförün olsam!...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi̇']::text[], 8.5, '{"poet":"Cahit Külebi̇","poet_slug":"cahit_kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTOBİYOGRAFİ', 'otobi-yografi-azer-yaran-ufl9h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşadım
yer yüreğinin atışında taş kanadı
yaşadım
toprak damarlandı,
ömrümün aktı kanı
dokundum ve sardım sonsuz
fiilinde tanrıların tanık
tanık oldum.
Yaşadım
ölümlü olduğumun hüzün gözyaşlarıyla
yaşadım
doyamadığım destan tadıyla
güz yangınının göğ kefeninde közlendim
yaşadım
ölümlülüğümün damladı kederi,
gün tırmandı buharlandı çiy
gün indi düştü çiyi ölümün.
Güneş
yaz boyunca günbatımının sırtında
denizin aynasında dönence payı yuvarlandı
ve güz boyunca dönence payı toparlandı
evrenin miri peşkiriyle yüzünü kuruladı
güneş.
Biliş çavlanında
dirilişin devrelerinde yüreğin vuruşuyla
yaşadım
bir dokunuştan fışkıran anlam, duy
estim kubbede, mavi büklümde silindim.
Yaşadım
dolamadığım şarkı tadıyla
aktım gurubun gözyaşlarıyla.', 'Yaşadım yer yüreğinin atışında taş kanadı yaşadım toprak damarlandı, ömrümün aktı kanı dokundum ve sardım sonsuz fiilinde tanrıların tanık t...', ARRAY['Türk Edebiyatı','Şiir','Azer  Yaran']::text[], 8.5, '{"poet":"Azer  Yaran","poet_slug":"azer_yaran","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTOPSİ', 'otopsi-halim-sefik-guzelson-20v36', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '- Orhan Veli''ye ağıt -
Morgda açılınca kafatası
Doktor beyler beyin gördüler
İndirince tenkafesine neşteri
Doktor beyler yürek gördüler
Yürekte ne gördüler dersiniz
Yürekte memleket gördüler
Dünya gördüler
Bir de dost gördüler
Ama bu işte doktor beyler
Doğrusu geç kaldılar
Çok geç kaldılar', '- Orhan Veli''ye ağıt - Morgda açılınca kafatası Doktor beyler beyin gördüler İndirince tenkafesine neşteri Doktor beyler yürek gördüler Yüre...', ARRAY['Türk Edebiyatı','Şiir','Halim Şefik Güzelson']::text[], 8.5, '{"poet":"Halim Şefik Güzelson","poet_slug":"halim_sefik_guzelson","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTUZ BEŞ YAŞ ŞİİRİ', 'otuz-bes-yas-si-i-ri-cahit-sitki-taranci-w0f8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaş otuz beş! yolun yarısı eder.
Dante gibi ortasındayız ömrün.
Delikanlı çağımızdaki cevher,
Yalvarmak, yakarmak nafile bugün,
Gözünün yaşına bakmadan gider.
Şakaklarıma kar mı yağdı ne var?
Benim mi Allahım bu çizgili yüz?
Ya gözler altındaki mor halkalar?
Neden böyle düşman görünürsünüz,
Yıllar yılı dost bildiğim aynalar?
Zamanla nasıl değişiyor insan!
Hangi resmime baksam ben değilim.
Nerde o günler, o şevk, o heyecan?
Bu güler yüzlü adam ben değilim;
Yalandır kaygısız olduğum yalan.
Hayal meyal şeylerden ilk aşkımız;
Hatırası bile yabancı gelir.
Hayata beraber başladığımız,
Dostlarla da yollar ayrıldı bir bir;
Gittikçe artıyor yalnızlığımız.
Gökyüzünün başka rengi de varmış!
Geç farkettim taşın sert olduğunu.
Su insanı boğar, ateş yakarmış!
Her doğan günün bir dert olduğunu,
İnsan bu yaşa gelince anlarmış.
Ayva sarı nar kırmızı sonbahar!
Her yıl biraz daha benimsediğim.
Ne dönüp duruyor havada kuşlar?
Nerden çıktı bu cenaze? ölen kim?
Bu kaçıncı bahçe gördüm tarumar?
Neylersin ölüm herkesin başında.
Uyudun uyanamadın olacak.
Kimbilir nerde, nasıl, kaç yaşında?
Bir namazlık saltanatın olacak,
Taht misali o musalla taşında.', 'Yaş otuz beş! yolun yarısı eder. Dante gibi ortasındayız ömrün. Delikanlı çağımızdaki cevher, Yalvarmak, yakarmak nafile bugün, Gözünün yaşı...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Taranci']::text[], 8.5, '{"poet":"Cahit Sıtkı Taranci","poet_slug":"cahit_sitki_taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTUZÜÇ MENEKŞE', 'otuzuc-menekse-tahsin-sarac-0uexn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir morlukta alabora oldu gök
Tan söktü
Güneş dik doruklara konan bir öpücüktü.
¦
Yürüyordu
Yürüyordu değil, sürülüyordu
Bir ak ölüme suçsuzlar, öbek öbek;
Korkunç bir önseziyle tanık tepeler
Utançtan eriyip küçülüyordu.
Yatağında sütlü kahve içerken
Karıcığı kırıtarak geçerken
Paşa orasını kaşıdı derken.
Otlar daha bir diridir şu an
Koyak daha bir can kokulu.
Öte yandan süngü, candarma, namlu
Bir de o paşadan gizli buyrultu;
Bir alçaklık göz kesilmiş, namludan
Gelincik yüreklere nişan alıyordu.
At üstünde geçer başkent sırtından
Ülkeyi kurtarmış derler yağıdan
Daha bir yağı mı olurmuş ondan?
Göz bağlı, diz bağlı, dil bağlı
Sıralandı yanyana otuzüç karaltı
Ve nişancılar çöktü.
Şu ılık dağ yellerinde sabahın, mermiler
Bir kılıç komutla, yağmurca boşanıp
Koca çınarları biçti yere döktü.
Ne horoz sesi, ne ezan, ne koyun
Ala bir acılıkta tüm doğa suskun
Bitti demir ağırlığı uykusuzluğun.
Bu dağ ne kıyımlar görmüştür bu dağ
Bu yöre ne açlıklar, kavgalar, kanlar...
Ve bu su, ne canlar almıştır bu su
Ne gelinler yutmuş, ne taylar, boğalar...
Ama bu kan var ya, otuzüç damla kan
Varan şu otuzüç sıcak pınardan
Akıp ezgi ezgi artık çağlara
Onu tüm kirlerinden arıtıyordu.
Buyurdu ölenler: kin tutulmaya
Son bula bu acı, bu kan, bu kıya
Mutlulukta yaşana koyun koyuna.
¦
Bir kızılda alabora oldu gök
Gün söktü
Ve otuzüç menekşe günle boyun büktü.', 'Bir morlukta alabora oldu gök Tan söktü Güneş dik doruklara konan bir öpücüktü. ¦ Yürüyordu Yürüyordu değil, sürülüyordu Bir ak ölüme suçsuz...', ARRAY['Türk Edebiyatı','Şiir','Tahsin Saraç']::text[], 8.5, '{"poet":"Tahsin Saraç","poet_slug":"tahsin_sarac","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTUZ SEKİZ', 'otuz-seki-z-i-lhami-bekir-tez-yfdwu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üçüncü sınıf mezarlık.
Kayıt tarihi:
6.8.932
Mezar numarası:
9
Eşya pusulası:
1 şilte
1 masa, 1 gardrop,
telli bir yemek dolabı;
anasının sağlığında
mahalleli kadınlara don ve blûz diktiği
boyasız eski bir dikiş makinesi...
Ve hatıralar
ve üç beş yemin
ve birkaç demet yazı:
"İki canım olaydı
iki kere öleydim."', 'Üçüncü sınıf mezarlık. Kayıt tarihi: 6.8.932 Mezar numarası: 9 Eşya pusulası: 1 şilte 1 masa, 1 gardrop, telli bir yemek dolabı; anasının sa...', ARRAY['Türk Edebiyatı','Şiir','İlhami Bekir Tez']::text[], 8.5, '{"poet":"İlhami Bekir Tez","poet_slug":"ilhami_bekir_tez","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTUZ YAŞ ŞİİRİ', 'otuz-yas-si-i-ri-jean-cocteau-13znu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bak yarısına ulaşıverdi ömür,
Evimin damında bir at üstündeyim;
İki yandan da bir manzara gürünür,
Ama apayrı giyindikleri mevsim.
Bağ kütükleriyle boynuzlu yeryüzü
Al bir karaca. İpteki çamaşırlar
Gülüp el ederek karşılar gündüzü;
Kışım da şerefim de burada başlar.
Gene söyle bana beni sevdiğini,
Venüs. Her vakit seni söylemeseydim,
Şiirlerimle kurmasaydım bu evi,
Onu boş sayıp damdan düşüverirdim.', 'Bak yarısına ulaşıverdi ömür, Evimin damında bir at üstündeyim; İki yandan da bir manzara gürünür, Ama apayrı giyindikleri mevsim. Bağ kütük...', ARRAY['Türk Edebiyatı','Şiir','Jean Cocteau']::text[], 8.5, '{"poet":"Jean Cocteau","poet_slug":"jean_cocteau","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OTUZ YIL ÖNCE TERK ETMİŞTİN BENİ', 'otuz-yil-once-terk-etmi-sti-n-beni-gyorgy-faludy-d97uw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Otuz yıl önce terk etmiştin beni. Hâlâ aşığım sana.
Anımsa nasıl öpmüştüm cansız dudaklarını boşuna?
Sekiz çocuğumuz olacaktı, ama yalnızca biri geldi dünyaya.
Sefalet ve acıyla lanetlenmişti sürgün yaşamı.
Aşkımız kaya gibiydi, boynu bükük çiçek tarhları değil.
Tam on beş yıl onurla ve büyüyerek sürdü,
sonra aşkımız incindi, dayanılmaz oldu, dedin.
İğrendin, benim sana verdiğim onca eziyet için.
Ama önce, henüz ölmeden çok önce, karanlık gecede,
kollarını boynuma sardın, kucakladın sıkıca
benim gibi. Şimdiyse ölmektesin, kanserli, hastalıklı.
"Bu gerçek olamaz. Bu bir düş, sanki cennet!" inildedin
ve orada uyuyakaldın. Yatağa çöktüm, bir ruh gibi.
Yaşamımda ilk kez oluyordu bu. Ağladım. İlk kezdi bu ve son oldu.
György FALUDY', 'Otuz yıl önce terk etmiştin beni. Hâlâ aşığım sana. Anımsa nasıl öpmüştüm cansız dudaklarını boşuna? Sekiz çocuğumuz olacaktı, ama yalnızca ...', ARRAY['Türk Edebiyatı','Şiir','György Faludy']::text[], 8.5, '{"poet":"György Faludy","poet_slug":"gyorgy_faludy","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OĞUL KOŞMASI', 'ogul-kosmasi-umit-yasar-oguzcan-5zakl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zirve seni bekliyor
Dağın kıymetini bil
Sanma ki yükselmek zor
Çağın kıymetini bil
Üşenme emek için
Mutluyum demek için
Üzümü yemek için
Bağın kıymetini bil
Yokluk göründüğü an
Çabuk yıkılır insan
Azı beğenmiyorsan
Çoğun kıymetini bil
Elin, ayağın, başın
Annenin,arkadaşın,
Suyun,toprağın,taşın
Göğün kıymetini bil
Oğlum benim, bir düşün
Değeri var mı dünün
Yarın çok geç ömrünün
Bugün kıymetini bil.', 'Zirve seni bekliyor Dağın kıymetini bil Sanma ki yükselmek zor Çağın kıymetini bil Üşenme emek için Mutluyum demek için Üzümü yemek için Bağ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit_yasar_oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OĞUL', 'ogul-dritero-agolli-xk4za', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin uzak akraban falan değilim ben
Ben senin oğlunum
Arnavutluk!
Köklerimi senin doruklarına saldım
Ve içtim sütünü
Onlardaki pınarlardan...
Böyle tutundular işte benim atalarım da
Benim atalarım da işte böyle içtiler.
Üstlerine karlar kopup devrildi
Karlar eridi gitti
Üstlerine kasırgalar saldırdı
Kasırgalar sonunda dindi.
Arnavutluk, sevgili!
Dritero  AGOLLİ', 'Senin uzak akraban falan değilim ben Ben senin oğlunum Arnavutluk! Köklerimi senin doruklarına saldım Ve içtim sütünü Onlardaki pınarlardan....', ARRAY['Türk Edebiyatı','Şiir','Dritero  Agolli̇']::text[], 8.5, '{"poet":"Dritero  Agolli̇","poet_slug":"dritero_agolli","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OVADA', 'ovada-erik-stinus-b0o7j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eve dönmekte sarışın sesler tarlanın üzerinden
Tek bir ağaç toplanmış gökteki kuşları
Paslanmış, dünyayı bölen bıçak
İri çıngıraklarını çalıyor bir at
Ürküntüyle geceye karşı.
Erik STINUS', 'Eve dönmekte sarışın sesler tarlanın üzerinden Tek bir ağaç toplanmış gökteki kuşları Paslanmış, dünyayı bölen bıçak İri çıngıraklarını çalı...', ARRAY['Türk Edebiyatı','Şiir','Erik Stinus']::text[], 8.5, '{"poet":"Erik Stinus","poet_slug":"erik_stinus","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OY REİS! KOCA REİS!', 'oy-rei-s-koca-rei-s-walt-whitman-d8rhp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oy reis, koca reis, alnımızın akıyla döndük seferden.
Savuşturup onca belâ, onca fırtınayı, sonunda murada erdin.
İşte liman, bak, çanlar çalıyor, bayram ediyor ahali,
Gördüler pupa yelken geliyor, gözüpek, gözü yeşil yelkenli.
Neyleyim, neyleyim ki ama...
Bu kan damlalarını nideyim?
Gayri uzanmış güverteye reis,
Soğumuş ellerini mi öpeyim?
Oy reis, koca reis, kalk da şu çanları dinle bari!
Baksana, senin bayrağın çekilen, senin şarkın söyledikleri!
Senin için bu çiçekler, senin için toplaştılar sahillerde,
Seni çağırıyorlar, bak, senin adın geziyor dillerde!
Gel, reis ağacığım benim,
Kolumun üstüne yatırayım seni.
Çoktan öldüğünü unuttum ama,
Bu kan damlalarını nideyim?
Reis cevap vermiyor sözüme, dudakları söylemez olmuş,
Ağam kolumu duymuyor bile, ne yüreği ne kalbi kalmış.
Sağ salim demir attı gemi, bitti artık sona erdi sefer,
Savuşturup onca belâyı, kazanılan bir güzelim zafer.
Bayram etsin sahil, çalsın davullar!
Yalnız bırakın beni gideyim!...
Reisin yattığı güvertenin üstünde
Böyle dolaşmayıp da nideyim?
1865
Walt WHITMAN
Çeviren : Can YÜCEL', 'Oy reis, koca reis, alnımızın akıyla döndük seferden. Savuşturup onca belâ, onca fırtınayı, sonunda murada erdin. İşte liman, bak, çanlar ça...', ARRAY['Türk Edebiyatı','Şiir','Walt Whitman']::text[], 8.5, '{"poet":"Walt Whitman","poet_slug":"walt_whitman","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYNUYOR AY', 'oynuyor-ay-ercument-behzad-lav-lfi31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oynuyor ay
Mor salkımlı suda
Oynuyor ay
Üşüyor kalp
Şehvet durunca
Üşüyor kalp
Düşüyor baş
Kara taş yastığa
Düşüyor baş
Çekiyor su
Örümcek uykusu
Çekiyor su
Geçiyor tren
Hecin katarlı
Cin düdüklü tren', 'Oynuyor ay Mor salkımlı suda Oynuyor ay Üşüyor kalp Şehvet durunca Üşüyor kalp Düşüyor baş Kara taş yastığa Düşüyor baş Çekiyor su Örümcek u...', ARRAY['Türk Edebiyatı','Şiir','Ercüment Behzad Lav']::text[], 8.5, '{"poet":"Ercüment Behzad Lav","poet_slug":"ercument_behzad_lav","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYUN', 'oyun-ozcan-yalim-zl99w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ay tutulmuş gibi
Bir kapı sürgülü
Bulutların arkasında
Bengör gülü
Bir kız göremez - karanlık
Kirpiği yaş örgülü
Bu nasıl oyun ey ozan
Yanlış kurgulu
Çek sürgüyü açılsın kapı
Al gülü - ver kıza - gülsün
Bu oyun mutlu sona yargılı', 'Ay tutulmuş gibi Bir kapı sürgülü Bulutların arkasında Bengör gülü Bir kız göremez - karanlık Kirpiği yaş örgülü Bu nasıl oyun ey ozan Yanlı...', ARRAY['Türk Edebiyatı','Şiir','Özcan Yalim']::text[], 8.5, '{"poet":"Özcan Yalim","poet_slug":"ozcan_yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYUNA DÖNÜŞ', 'oyuna-donus-kuvvet-yurdakul-kcs7q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmur camdan bakan Arap Kızıydı
Oyuna dönüştü sonra her şey ihtilal
Bu kentte birileri mendil bırakıyor arkamıza
Bırakıp kaçıyorlar
Ustamın failini
Yalan şarkılarla avutuyorlar
Oyuna katılmalımum şart
Gönüllüyüm avucumda yakın
Çünkü gece bu halimle taşımıyor beni
Parmak uçlarımızda uğur böcekleri bulunduruyoruz
Onlar da uçar böylesi iyi
Terlik pabuç alacak annem yok benim
Kuğulu bir parktayız şimdi
Boynu uzun bir gecede
Kurtarılmış bölgesinde sabahın
Taşıdığım din
Oyuna dönüştü sonra herşey yağmur
Görmedim ama inandım
Kuytu gözlerinde mevsimsiz yağmur nöbetleri
Saçlarından seller akıtan bir kız vardır mutlaka', 'Yağmur camdan bakan Arap Kızıydı Oyuna dönüştü sonra her şey ihtilal Bu kentte birileri mendil bırakıyor arkamıza Bırakıp kaçıyorlar Ustamın...', ARRAY['Türk Edebiyatı','Şiir','Kuvvet Yurdakul']::text[], 8.5, '{"poet":"Kuvvet Yurdakul","poet_slug":"kuvvet_yurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYUNCAKÇI AMCA', 'oyuncakci-amca-abdulkadir-bulut-hcdk8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oyuncakçı amca,
Ne çok oyuncakların var;
Top, tank, tüfek, tabanca...
Gövdem titriyor,
Onlara bakınca!
N''olursun oyuncakçı amca,
Bundan böyle bizlere,
Oyuncak tüfekler yerine,
Ak yelkenli bir gemi,
Bir de süslü bebekler getir,
Unutma emi?
Sonra oyuncakçı amca,
Senden aldığım tüfekleri,
Bozarak onlardan kuş yaptım,
Bana kızmazsın değil mi?', 'Oyuncakçı amca, Ne çok oyuncakların var; Top, tank, tüfek, tabanca... Gövdem titriyor, Onlara bakınca! N''olursun oyuncakçı amca, Bundan böyl...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Bulut']::text[], 8.5, '{"poet":"Abdülkadir Bulut","poet_slug":"abdulkadir_bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OYUNUNA GELDİN YAŞAMIN', 'oyununa-geldi-n-yasamin-tekin-gonenc-p30tc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'koparıp da yüreğinin pırpırlarından
katlayıp cebine koyduğun körkütük birkaç dize
bir de düştü mü önüne
oyununa gelirdin gece yarılarının
şu sendeki sevda
uzak dağ köylerinden buralara taşıdığın
yitik kuşların ikincil düşleri
boşuna yer arardı kendine
sen hep o kadınlara giderdin
sözlerin gözlerle söylendiği kaldırımlarda
çoktan kim vurduya gitmiş
o kadınlara
yırtık bir merhaba
ağzının karanlığından saçılırken ortalara
duyan bile olmazdı seni
umudun yangın yeri odalarda
bir de koğuş arkadaşların
içlerinde aykırı rüzgârlar esen
jilet bakışlı üç beş serseri
hatırlar mısın
abanıp abanıp da
ranzalara
kapanın elinde kalıyordu ipleri
biri inmeden daha
öbürü kalkıyordu perdelerin
bir başladı mı vurmaya
kötü vururdu bu istanbul
sen nerden bilecektin
olmadı işte
yağamadın bir türlü
şöyle doyasıya
kendi bulutlarından
yanlış bir köşesine koymuşlardı seni
oyununa geldin yaşamın', 'koparıp da yüreğinin pırpırlarından katlayıp cebine koyduğun körkütük birkaç dize bir de düştü mü önüne oyununa gelirdin gece yarılarının şu...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin_gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OZA''DAN', 'oza-dan-andrey-voznesenski-zakh2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'XIV
Selam Oza, evde, geceleyin
Ya da uzakta bir yerde, neresi olursa olsun,
havlarken köpekler,yalarken kendi göz yaşlarını
Senin soluğundur duyduğum ses.
Selam Oza!
Nasıl bilebilirdim, sinik ve gülünç
Bir kişi gibi, ürkerek giren bir göle,
Gerçekte korku olduğunu aşkın, söyle?
Selam Oza!
Ne korkunç, bir başına düşünmek şimdi seni?
Daha da korkunç,bir başına değilsen oysa:
Şeytan öylesine doyumsuz bir güzellik vermiş ki sana.
Selam Oza!
Ey - insanlar, lokomotifler, mikroplar
Gerin kanatlarınızı elinizden geldiğince ona.
Harcatmam onun, dokundurtmam kılına.
Selam Oza!
Yaşam bir bitki değilse aslında,
Neden dilimliyor, parçalıyor insanlar onu
Selam Oza!
Ne acı bu denli geç rastlamak sana
Ve böylesine erken ayrı kalmak sonunda.
Karşıtlar getiriliyor bir araya
Bırak çekeyim kahrını ve acını kendime
Çünkü acılı kutbuyum mıknatısın ben,
Sense sevinçli. Dilerim sonuna dek kalırsın öyle.
Dilerim hiç bilmezsin ne denli hüzünlüyüm.
İnan, kendimle üzmeyeceğim seni.
İnan, ders olamayacak sana ölümüm.
İnan, yük olmayacağım sana yaşamımla.
Selam Oza, dilerim ışıl ışıl kalırsın hep
Bir sokak fenerinden sızan bir ışık gibi.
Suçlayamam bırakıp gittiğin için beni.
Şükür ki girdin yaşamıma.
Selam Oza!
Andrey VOZNESENSKİ', 'XIV Selam Oza, evde, geceleyin Ya da uzakta bir yerde, neresi olursa olsun, havlarken köpekler,yalarken kendi göz yaşlarını Senin soluğundur...', ARRAY['Türk Edebiyatı','Şiir','Andrey Voznesenski̇']::text[], 8.5, '{"poet":"Andrey Voznesenski̇","poet_slug":"andrey_voznesenski","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OZAN VE SESLER', 'ozan-ve-sesler-i-lhan-berk-848i2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün böyle gelip dünyadaki yerini alıyor.
''Zor olan, diyor, şiirin hayatını yaşamaktır.
Yazmak sonra gelir hep.'' Bir bardak su ister
Gibi kolay çıkıyor bu sözler ağzından.
Kendiyle daha bir içli olmak için sonra
Her zamanki eski koltuğuna gidip oturuyor.
Göz göze geliyor ağaçlarla denizle gökle. Bir top
Karanfilde gezdiriyor ellerini. Burnuna götürüyor.
Sesleri dinliyor sonra. İyi akşamlar diyen
Yoldan  geçen bir sesi. Gürültülerle inen sabahı.
Sessiz otları. Düşen günü.
Sesleri.Sesleri.Sesleri.
Böyle bütün gün sesleri dinleyip
Çekiliyor sonra,
dünyadaki yerine.
Deniz Eskisi', 'Her gün böyle gelip dünyadaki yerini alıyor. ''Zor olan, diyor, şiirin hayatını yaşamaktır. Yazmak sonra gelir hep.'' Bir bardak su ister Gibi...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OZANA ÖĞÜTLER', 'ozana-ogutler-philippe-soupault-mkbho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Su gibi ol
Pınar suyu bulut suyu
Renk renk olabilirsin ya da renksiz
Durdurmasın ama seni hiçbir şey
Zaman bile
Yollar pek uzun değildir öyle
Değildir pek uzak denizler
Korkma ne yelden
Ne soğuktan ne sıcaktan
Öğren türkü çağırmasını
Bıkmadan usanmadan
Türkü mırıldan ve kayar gibi git
Ya da kopar itip kak
Zıpzıp zıpla fışkır ya da
Durgun su ol
Koşan oynayan
Arıtan su ol
Tatlı ve duru bir su
Çünkü arınmışlığın ta kendisidir su
Canlılar için yaşamdır o çünkü
Kazaya uğramışlar için ölüm.
Philippe SOUPAULT', 'Su gibi ol Pınar suyu bulut suyu Renk renk olabilirsin ya da renksiz Durdurmasın ama seni hiçbir şey Zaman bile Yollar pek uzun değildir öyl...', ARRAY['Türk Edebiyatı','Şiir','Philippe Soupault']::text[], 8.5, '{"poet":"Philippe Soupault","poet_slug":"philippe_soupault","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OZANIN AŞKI', 'ozanin-aski-alain-bosquet-oeet1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ozan seviyor sizi
dişi bir meşe olmak
hakkı tanıyor size
yüz tapınaklı bir ırmak
gezgin bir kuyrukluyıldız
bir ozan seviyor sizi
alıştırmak için sizi
kenar mahallelerine
siz olacak evrenin
bir ozan seviyor sizi
ve sorumlu tutuyor sizi
çok uzun bir sonsuzluktan
uysal tanlardan
uçan balıklı göllerden
bir ozan seviyor sizi
ve her şey izinli size
mutlu böcek
kutsalın kutsalı günah
bir ozan öldürüyor sizi
daha çok sevmek için
sizinle besleyeceği sözcükleri
Alain BOSQUET', 'Bir ozan seviyor sizi dişi bir meşe olmak hakkı tanıyor size yüz tapınaklı bir ırmak gezgin bir kuyrukluyıldız bir ozan seviyor sizi alıştır...', ARRAY['Türk Edebiyatı','Şiir','Alain Bosquet']::text[], 8.5, '{"poet":"Alain Bosquet","poet_slug":"alain_bosquet","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OZANIN GÖZÜ', 'ozanin-gozu-kemal-ozer-y8z82', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman titreşen küçük bir alev görsem
anımsarım Devrim Müzesi''ni Sofya''nın,
Sofya''da Devrim Müzesi''nde
bakmaktadır bir camın ardından
Leo Milev''in gözü dünyaya.
Koskoca bir tarihi aydınlatır
o gözdeki küçücük alev,
titreşip durmuştur yıllarca
bir çukurun dibinde
ha söndü ha sönecek.
Görürüm yenik düşenleri aydınlığa,
görürüm boğmak isteyen
kanlı elleri kıyıcıların,
ve sırtımı ürpertir
bir alevin direnmesi
yıllarca toprak altında.
İşte ozan
--sökmüş ve sökecek tüm şafakların habercisi-
baktığı vakit yıllarca uzaktan
--boynu ipte
ve yanıbaşında cellât
ve dudaklarında "eylül mayısa dönüşecek" dizesi-
baktığı vakit gözlerimize
yansıtmaktadır o alevi.
Ozan öldürülse bile
öldürülemez çünkü tanıklığı
maddenin ışığıdır çünkü
ozanın gözü evrende.', 'Ne zaman titreşen küçük bir alev görsem anımsarım Devrim Müzesi''ni Sofya''nın, Sofya''da Devrim Müzesi''nde bakmaktadır bir camın ardından Leo ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onaysız', 'onaysiz-m-ozer-ci-ravoglu-dpe9n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ceketim dolapta
seni astılar
üzüm yedim
dağıldım
çıplak ova benim
en çok sevdiğim gerçek
klinikte gözlerimin olması
koridor
beyaz yangın, zor sevda
ruhuma inen örgü
dolgun tabut
üzüm yedim
memelerim üşüdü
onaysız annemle', 'ceketim dolapta seni astılar üzüm yedim dağıldım çıplak ova benim en çok sevdiğim gerçek klinikte gözlerimin olması koridor beyaz yangın, zo...', ARRAY['Türk Edebiyatı','Şiir','M. Özer Ci̇ravoğlu']::text[], 8.5, '{"poet":"M. Özer Ci̇ravoğlu","poet_slug":"m_ozer_ciravoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İPİ DEĞİL DENGEYİ DÜŞÜN!', 'i-pi-degi-l-dengeyi-dusun-altay-omer-erdogan-y5fc5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İPİ DEĞİL DENGEYİ DÜŞÜN! CAMBAZHANE PARASIYLA ÜÇ
ÇOCUK OKUTTU AHMET AMCA. KÖPÜKLÜ ORTA KAHVE
SEVERDİ, SALYANGOZLARI VE SÜHEYLA YENGE''Yİ. DEDİ Kİ
ÖLÜMÜNDEN AZ ÖNCE; HAKKINI HELÂL ET SEVGİLİ İPİM
körebe mutluluklara sarılırdı en soylu sıcaklığıyla ilkyaz
koşulsuz dost kuytuluklarıydı çocukluğumun yarısından fazlası
Kızılçullu''da (şimdi Şirinyer) üç hane öte komşumuzdu Ahmet Amca
Nazilli basması gibi renkli bir insandı, işi ip ve denge
cambazhanede lâkabı "maskot", "akkor" diye seslenirdi Süheyla Yenge
bulutsu dünyamın baş kahramanlarındandı Maskot Akkor Amca
bir fotoğrafı bile yok elimde
tren yoluna bakardı selamsız sabahsız pencereleri evlerin
makas keserdi taşralı umutlar bohçası dürülmüş yaşamdan
petunyaların ve salyangozların da gurbeti o bizden tutunmuşlukta
kefildik yıldızların parlaklığına şarkıların sarhoşluğuna
ışık süzerdik, ekmek isterdik, tümceleri dizip sıraya anlam işlerdik
isterdik ki onurlu ve içtenlikli yaşasın tek varsıllığımız insanlığımız da
çocuktum, o kadar gerçekti ki düşler, o kadar düştü ki gerçekler
ayın üstünde bir tavşanın yaşadığına inanırdım bir çokları gibi ben de
"inanmak sahip olmanın yarısıdır" derdi Filozof Ahmet Amcam
iç çekerek söylerdi; "bizim tavşanlar beklemiyor ayın yarısını"
panayır panayır dolaşırdı Şen Kardeşler Kumpanyası''yla ve de düğünleri
üç çocuk okuttu cambazhane parasıyla, dengesini yitirmeden canını okuttu
bir o tavşanla bir de yaşlı cambazla paylaşırdım gizlerimi
o kadar düştü gerçekler, o kadar gerçekti düşler, o kadar çocuktum
kamçısı omuzlarda bir mevsim burukluğuydu kendine düşman
ip bağlamak içindi, çözmek için kullandı gündelik sıkıntılarını
ölüm yatağında, "doğanın dengesi" dedi, "ipin dengesinden yeğdir
hem ip şaşırdı dengesini, dolandı körpecik fidanların boynuna"
son sözleri "hakkını helâl et sevgili ipim" oldu
bir tek darağacında sevmedi ipi
(Adam Sanat, ; Adam Şiir Yıllığı, Mehmet H. Doğan, 1998,  Taş(ra) Baskısı, 2003)', 'İPİ DEĞİL DENGEYİ DÜŞÜN! CAMBAZHANE PARASIYLA ÜÇ ÇOCUK OKUTTU AHMET AMCA. KÖPÜKLÜ ORTA KAHVE SEVERDİ, SALYANGOZLARI VE SÜHEYLA YENGE''Yİ. DED...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖPÜŞ TADINDA', 'opus-tadinda-ahmet-uysal-453zv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir şiir
Tek bir şiir yazmalıyım
Uyağı rüzgâr olan
Yağmura bürünmüş soluğu
Bir gün
Tek bir gün kalmalı
Benden kalacaksa geriye
Bir öpüş tadı dudağımda
Ve bir öpüş tadında
Olmalı o şiir de', 'Bir şiir Tek bir şiir yazmalıyım Uyağı rüzgâr olan Yağmura bürünmüş soluğu Bir gün Tek bir gün kalmalı Benden kalacaksa geriye Bir öpüş tadı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'P.L.M. (MARSİLYA TRENİ)', 'p-l-m-marsi-lya-treni-v-tezslav-nezval-wtmy1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgun bir trende gördüm Marsilya''lı denizcileri
İlk defa bavullar fileler torbalar arasında
Balkı sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Kafa tutmakta birinci bahriye cakası bütün
Besbelli kolu sırmalı kaptan olacaklar
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Limana dönüyor bunlar gemilerine kışlalarına
Çakılıp selâm durmağa önünde afili kaptanların
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Kimisi şarkı söyler uykusunda kimi dünyayı iplemez
Gördüğüm korsan tayfası mı deniz eşkiyası mı
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Ortalığı dumana vermişler ki bir ağır tütün
Gözgözü görmez olmuş sağnak mı hortum mu
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Tepeden tırnağa dövmeli yaşlısı genci
Bunlar mı onları korur uzun yollarını açar
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Karaya oturmak var mı denizci güçlü olacak
Yüreklilik konusunda en baskını en utangaç
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Ozan olmasaydım şaşmaz denizci olurdum
Sözcüklerle boğuşmak yerine göğüs verirdim dalgalara
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Gemide isyan mı çıktı ilk ateş eden benim
Yakışıklı kaptanımın gözünü çıkaran
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Bu onuncu dörtlüğüm içiniz rahatlasın diye
365 inci karımdan yarın boşanacağım
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
İşte onbirinci dörtlük Alın bu da cabası
Gemiciler aydınlık gelecekler grevlerinize bağlı
Balık sırtı mavi sakal Az bi''şey ürktüm
Denizin eli kulağında Kokusunu taşıyorlar
Vítezslav  NEZVAL', 'Yorgun bir trende gördüm Marsilya''lı denizcileri İlk defa bavullar fileler torbalar arasında Balkı sırtı mavi sakal Az bi''şey ürktüm Denizin...', ARRAY['Türk Edebiyatı','Şiir','Vítezslav  Nezval']::text[], 8.5, '{"poet":"Vítezslav  Nezval","poet_slug":"vitezslav_nezval","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PİA', 'pi-a-attila-i-lhan-0labw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne olur kim olduğunu bilsem pia''nın
ellerini bir tutsam ölsem
böyle uzak uzak seslenmese
ben bir şehre geldiğim vakit
o başka bir şehre gitmese
otelleri bomboş bulmasam
içlenip buzlu bir kadeh gibi
buğulanıp buğulanıp durmasam
ne olur sabaha karşı rıhtımda
çocuklar pia''yı görseler
bana haber salsalar bilsem
içimi büsbütün yıldız basar
bir hançer gibi çıkıp giderdim
ben bir şehre geldiğim vakit
o başka bir şehre gitmese
singapur yolunda demeseler
bana bunu yapmasalar yorgunum
üstelik parasızım pasaportsuzum
ne olur sabaha karşı rıhtımda
seslendiğini duysam pia''nın
sırtında yoksul bir yağmurluk
çocuk gözleri büyük büyük
üşümüş ürpermiş soluk
ellerini tutabilsem pia''nın
ölsem eksiksiz ölürdüm', 'ne olur kim olduğunu bilsem pia''nın ellerini bir tutsam ölsem böyle uzak uzak seslenmese ben bir şehre geldiğim vakit o başka bir şehre gitm...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PANDELİS GUTİS', 'pandeli-s-guti-s-necati-yildirim-iqxlg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hoş geldin pandelis gutis*
yurduna, izmir''e hoş geldin
cömert, sevecen yüreğimiz
savaş için tutmaz kin
barış için dostluk için
hoş geldin pandelis gutis
yurduna, izmir''e hoş geldin
rüzgârı tutabilir mi sis
izmir''e hoş geldin pandelis
açıkça değilse de inan ki yasak
bir gün yapışır yakana polis
zordur bizde barışı savunmak
hoş geldin pandelis gutis
izmir''e hoş geldin barış neferi
bizi doyurmaz yalnız ekmek ve sosis
yüreğimiz yanan bir deniz feneri
biz süt emdik aynı memeden
sevincimiz bir, acımız bir
açlığa, korkuya, karanlığa rağmen
ayrılık biter, kırılır zincir
* Pandelis Gutis: Yunanistan Barış Konseyi üyesi.
Babası, İzmir''in işgali sırasında öldürülür.
Pandelis''i bir Türk kadını emzirir.
67 yıl sonra, 24-30 Temmuz 1989 tarihlerinde
IV. Dikili Kültür ve Sanat Festivali''ne katıldı.', 'hoş geldin pandelis gutis* yurduna, izmir''e hoş geldin cömert, sevecen yüreğimiz savaş için tutmaz kin barış için dostluk için hoş geldin pa...', ARRAY['Türk Edebiyatı','Şiir','Necati Yildirim']::text[], 8.5, '{"poet":"Necati Yildirim","poet_slug":"necati_yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PANTER YUMURTASI', 'panter-yumurtasi-umut-taydas-s81tu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '"memelerine..."
bırak kurusun orda gözyaşın, kalsın, ben yalarım yüzünü,
bir 70''lik yaparız odanın ortasına,
kadeh tokuşturmayalı çok oldu,
kulaklarımızın yası açılsın, ben sana domates ezeyim,
sen bana; göbek salatandan öpeyim,
beyaz peyniri de tatlandıran sensin,
sarhoşluğu anlamlandıran da, en güzel uykum da,
kapat gözlerini, sarhoşluğumdan korkma, dudakların aralı kalsın,
can çekişmek nedir hissetmeni istiyorum,
yok yatma, yok dur uzanma, açılan bir şişe mutlaka bitsin,
dur dur uyuma, bir fıkra anlatayım,
bir çok düşündüm gelmedi ama,
zaten ben fıkraya gülmem, sert mizaçlıyım,
zaten ben komik şeylere de gülmem,
lan var ya çok komiksin, burnun akıyor,
hem şişe de bitti zaten, bir marul yaprağı daha alayım,
sana da bir yeşil zeytin tanesi,
bir de anason kokusu değeyim dudaklarına,
dur dur yatma, yok aman uzanma öyle,
arkanı dön,
sırtını dön bana,
sarılayım da amman, ya bi dilim diline değsin,
tamam, başka kımıldanma olmasın,
dur ama göğüslerinden öpeyim birer tane,
sırtını dön, kapat onları üşümesinler,
iyi geceler...
15.01.01 - 07:37
"özenti, bir elbisedir başkalarına kendimizi sevdirmek için sürekli giydiğimiz"', '"memelerine..." bırak kurusun orda gözyaşın, kalsın, ben yalarım yüzünü, bir 70''lik yaparız odanın ortasına, kadeh tokuşturmayalı çok oldu, ...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PANTOLONLU BULUT''DAN', 'pantolonlu-bulut-dan-vladimir-mayakovski-mzjpu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'PANTOLONLU BULUT''dan (Giriş)
Pelteleşmiş beyninizde
kirden parlayan bir kanepede yan gelip yatan semiz bir uşak gibi
hayal kuran düşüncenizi,
kanlı bir yürek parçasıyla tedirgin edeceğim,
dalga geçeceğim, geberesiye küstah ve zehir dilli.
Tek bir ak saç yok ruhumda,
yaşlılığın çıtkırıldımlığı yok onda!
Dünyayı bozguna uğratarak sesimin gücüyle
yürüyorum - yakışıklı,
yirmi iki yaşında.
Çıtkırıldımlar!
Kemana yatırırsınız aşkı siz.
Kabalar, onu trampete yükler.
Fakat, tersyüz edebilir misiniz, kendinizi benim gibi,
Öyle ki, dudaklar kalsın ortada, salt dudaklar!
Çık da gel konuk odasından
gel de bir adam tanı,
kibirli, patiskadan ve melek soylu memur karısı.
Sen ki dudaklar çevirirsin aynı kayıtsızlıkla,
bir aşçı kadın nasıl çevirirse yemek kitabının sayfalarını...
İster misiniz
ten kudurtsun beni,
- ve gök gibi, renk değiştirerek ansızın -
ister misiniz
öylesine yumuşayım, sevecen olayım ki öylesine
hani, erkek değil de, pantolonlu bir bulut desinler bu!
İnanmıyorum çiçekli Nice diye bir yerin var olduğuna!
Benimle göklere çıkarılacaktır yeniden
hastane gibi bayatlamış erkekler,
ve atasözleri gibi yıpranmış kadınlar da...
Vladimir MAYAKOVSKI', 'PANTOLONLU BULUT''dan (Giriş) Pelteleşmiş beyninizde kirden parlayan bir kanepede yan gelip yatan semiz bir uşak gibi hayal kuran düşüncenizi...', ARRAY['Türk Edebiyatı','Şiir','Vladimir Mayakovski']::text[], 8.5, '{"poet":"Vladimir Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAPATYA FALI', 'papatya-fali-baris-gulteki-n-12pq9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '*saçları gece yüzü gündüz bir kadın''a
kıyıma vuran son dalganın getirdiği
beni kuşlardan daha çok seven
saçlari gece yüzü gündüz bir kadın
tek anlamlı yeri gözleri ile
sıkılmamış gülücükler mandallıyor gözlerime
bir sevişme sonrasında
kendine güvenen ellerinden
fısıltılar içinde yatağa
soğumuş papatya yaprakları düşerken.
en kenarına çekilip bir aşkın
üzerine "sevmiyor" kazıdığım
elinden yüzsüzlüğüme süzülen
son beyazlığı izliyorum.
tek duyduğum kesintisiz yutkunmalar.
bir gün batımı uzağımda ağlıyor şimdi
saçları gündüz yüzü gece bir kadın,
artık kuşları benden daha çok sevdiği
ağlarken kuş tüyü yastığına  sarılışından belli.', '*saçları gece yüzü gündüz bir kadın''a kıyıma vuran son dalganın getirdiği beni kuşlardan daha çok seven saçlari gece yüzü gündüz bir kadın t...', ARRAY['Türk Edebiyatı','Şiir','Barış Gülteki̇n']::text[], 8.5, '{"poet":"Barış Gülteki̇n","poet_slug":"baris_gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAPATYALI ŞİİR', 'papatyali-si-i-r-yusuf-altunel-pcm4e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'masada bir demet papatya
bardağından naz gibi bira içer
narin yapraklarını okşar usulca
öpüşürcesine nefesler cigarasını
içine dolar mutlululuklardan şeker
ben mutlulukları içime çekemem ki...
çekiverir papatyalardan birini
alır eline öper
sever mi, sevmez mi bilinmez
papatyadır, ne dese çingene falı
kıskançlık denizine yıkarım öfkeden bulutları
bakışlarımda hüzünden içki
ben hiç papatya olamam ki...
o yudumlarken birasını
vızıldar, bardağına düşerim
bira gibidir dudaklarının tadı
bira öpülmüş papatya kokmaz ki...', 'masada bir demet papatya bardağından naz gibi bira içer narin yapraklarını okşar usulca öpüşürcesine nefesler cigarasını içine dolar mutlulu...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARÇALANIRIM', 'parcalanirim-yusuf-altunel-882ov', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dolmuşum bu gece
steplerde dörtnala efkar atım
Cengizhan akını bütün bıraktıklarım
sıkar boğazımı babam ha sıkar
geceler der radyoda kart sesli bir şarkıcı
lüfer olsaydı meze yapardım onu dinime
ağlayıp inledikçe unutulma şarkılarıyla meyhane
sevda sarhoşlarına her ezgi hasret
her hasret içmek için bahane
içmişim içmişim arsız sırnaşmalar dolmuşum
sevda badeleri çekmişim arlanmazlık testilerini kırıp
dolunaylı geceleri şiir şarabıyla çekmişim
coşku kayığım parçalanmış hasret kayalıklarında
ıssız aşk adacığında mahsur kalmış gemim
ayrılık zemherisi gecelerde üstüm açılmış,
hayırsız sevgilililerden bana mahzunluğum kalmış
şehrin orta yerinde polise inat açan çiçek seviyorum seni
saçlarını duru gecelerde ayışığına dola
24:30 katarıyla sensizliğinle boş odama yolla
uslanmaz sarhoşuyum aşk kentinin, döşeksiz yatarım
bir çift gül memedir yekpare gecelerde sayıkladığım
uyuz itler siğer terkedilmişliğime
asılır da her güzele kırılgan utanmazlığım
her güzel çalar beni yere parçalanırım', 'dolmuşum bu gece steplerde dörtnala efkar atım Cengizhan akını bütün bıraktıklarım sıkar boğazımı babam ha sıkar geceler der radyoda kart se...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARÇALANMIŞ ZAMANLAR', 'parcalanmis-zamanlar-adnan-azar-acfe5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1
unuturum akıp gittiğin
yüzünü unuturum
geceye yaslanırım
yaslanırım ince uzak bir sese
senin sesin o
alır beni bilirim
her şiirle birlikte
senin adın
alır beni bilirim
senin kumral susuşun
senin kırık susuşun
kime varsam geceler
kimi sevsem yine seni
yine seni severim
unuturum akıp gittiğin
artık yeni bir pusuda beklenirim', '1 unuturum akıp gittiğin yüzünü unuturum geceye yaslanırım yaslanırım ince uzak bir sese senin sesin o alır beni bilirim her şiirle birlikte...', ARRAY['Türk Edebiyatı','Şiir','Adnan Azar']::text[], 8.5, '{"poet":"Adnan Azar","poet_slug":"adnan_azar","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARAMPARÇA', 'paramparca-yusuf-altunel-ervg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kurşunlanan her beden insanlık
çiçeğinden koparılan bir taç yaprağıdır
tililidir
çıkar
dağlara
buz
koyak
acı
rüzgar
yasak
lisan
tetiktir
parmak
gelir de
rastlarsa
kalleş
kimyasal
kulağı
burnu
kesik
tecavüz
cesedim
kafam
kopar
ülkem
paramparça', 'kurşunlanan her beden insanlık çiçeğinden koparılan bir taç yaprağıdır tililidir çıkar dağlara buz koyak acı rüzgar yasak lisan tetiktir par...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARANOYA KIRLANGICIM PARANOYA', 'paranoya-kirlangicim-paranoya-mahmut-temi-zyurek-jjpts', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan güneşle dünyanın arasındadır
Senin sağında, benim solumda
hep ortasındadır ölümün
Durur bir nefesle bir nefes
arasında bir yerde, sabahla akşam
arasında her şeyi şaşırabilir
Yaprağa düşen yağmurdur
yapraktan düşen damla
Ne yapabilir, rüzgârından
merhamet dilemekten başka.
İnsan şaşırdıkça
delinir şüphe torbası
zehirler gözü.
Seni var ya, inleyişinden tanırım
kiminle öpüşsen duyarım sesini
teninin duygusu bulaşır, ateşi, kokusu
bacaklarının arasından ürperti
dudaklarına dolaşır
seğirir damar gibi
İnsanla herkes arasında nahoş tecrübe
Kırlangıcın zamansız göç nedenidir
O yüzden tizdir gagasından fışkıran
Bir daha dönmez yurduna.
Kalp, inleyişinden tanınır
Bir öpünce, bir de kırılınca.', 'İnsan güneşle dünyanın arasındadır Senin sağında, benim solumda hep ortasındadır ölümün Durur bir nefesle bir nefes arasında bir yerde, saba...', ARRAY['Türk Edebiyatı','Şiir','Mahmut  Temi̇zyürek']::text[], 8.5, '{"poet":"Mahmut  Temi̇zyürek","poet_slug":"mahmut_temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARANTEZ', 'parantez-mahmut-temi-zyurek-xegkh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Parantezim ol sevgilim
Yaşamla ölüm arasında kısa mı kısa
Dudakların arası bir parantez
Eksik kalan her şey dökülsün boşluğa
Söylemeyi unuttuğun sözler mesela
Kirpiklerinden oluşan bir parantez
Bu tufandan kurtulacak ne varsa sığmalı
Kuşlar yeniden uçmalı sarp kayalarda
İlgisiz kaldığın her şey dökülsün boşluğa
Başarmak, ün, para, güç ve daha…
İki kaşın arasındaki o boşluk kadar
Değil mi ki kısacık bir dilim dünya
Sağ yana yaslasam hayata alınan yanımı
Sol yanda ''hemen şimdi!'' diyen duygular
Seninle doymadığım her şey dökülsün boşluğa
Suyu bulandıran boğa
Alnını kırıştıran dağlar
Parantezim olsan sevgilim
Beni bu dışardan atsalar
İçinde ömrüm kalsa.', 'Parantezim ol sevgilim Yaşamla ölüm arasında kısa mı kısa Dudakların arası bir parantez Eksik kalan her şey dökülsün boşluğa Söylemeyi unutt...', ARRAY['Türk Edebiyatı','Şiir','Mahmut  Temi̇zyürek']::text[], 8.5, '{"poet":"Mahmut  Temi̇zyürek","poet_slug":"mahmut_temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARILTI', 'parilti-ahmet-hasi-m-e1dob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Âteş gibi bir nehir akıyordu
Rûhumla o rûhun arasından
Bahsetti, derinden ona hâlim
Aşkın bu unulmaz yarasından.
Vurdukça bu nehrin ona aksi
Kaçtım o bakıştan, o dudaktan,
Baktım ona sessizce uzaktan
Vurdukça bu aşkın ona aksi...', 'Âteş gibi bir nehir akıyordu Rûhumla o rûhun arasından Bahsetti, derinden ona hâlim Aşkın bu unulmaz yarasından. Vurdukça bu nehrin ona aksi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARK', 'park-cemal-sureya-mgocv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle sevdim ki seni
Öylesine sensin ki!
Kuşlar gibi cıvıldar
Tattırdığın acılar.', 'Öyle sevdim ki seni Öylesine sensin ki! Kuşlar gibi cıvıldar Tattırdığın acılar....', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARMAKLIĞIN ÖTESİNDEN - II -', 'parmakligin-otesi-nden-ii-rifat-ilgaz-h5dix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu sefer bayrağını çekmiş vapur
Bizim Karadeniz''e gider.
Beni alıp götürmese de,
Alır, düşüncemi çocukluğuma götürür,
Çocukluğumun memleketine.
Kıyıcığında doğmuşum Kastamonu''nun
Fener fener bilirim Karadeniz''i.
Kahrını çekmişim yıldızının, poyrazının,
Ecel terleri dökmüşüm karayelinde.
Kim bilir ne haldedir,
Benim frengisiyle meşhur memleketim,
Şimdi ne halde ?
Ekmekleri mısır bazlaması mı,
Bulgurlu mancar mı hala bayram yemekleri ?
Çok sıkıntı çektik Seferberlik''te,
Çok mısır koçanı yedik, vesikalı;
Bu sefer de vesikasız yemişler,
Gazsız, sabunsuz kalmışlar.
Kim gider, kim sorar hallerini ?
Bilirim ne vapurun büyükleri uğrar,
Ne insanların büyükleri;
Memurlar gelir ufak tefek,
Büyüyünce giderler.
Balıklardan bile hamsiler vurur,
Vursa vursa karaya.', 'Şu sefer bayrağını çekmiş vapur Bizim Karadeniz''e gider. Beni alıp götürmese de, Alır, düşüncemi çocukluğuma götürür, Çocukluğumun memleketi...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARMAKLIĞIN ÖTESİNDEN - III -', 'parmakligin-otesi-nden-iii-rifat-ilgaz-lba51', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göremedik sıkıntısız yaşandığını,
Rahatın şiirini yazamadık,
Ne kadar uzak
Heveslerimle içli dişli yaşamak,
Üzmek hastalıklı şiirlerle
Eşimi, dostumu;
Mezar taşları kadar, ölçülü
Beyitler düzmek boy boy.
İçliyimdir herkes kadar,
Düşündürür beni de şu gökyüzü,
Kuş cıvıltısı, nar çiçeği...
Geçtik bir kalem üzerinden.
Huyumdan ettiniz, Cibali Kızları,
Sekiz düğününden önce
Penceremin altından geçenler,
Saçları dağınık, gözleri uykulu,
Çoraba, tütüne gidenler,
Beni huyumdan ettiniz!
Yorgun gözlerinizdeki acıyı
Dert edindim kendime.
Saçlarını tezgahına yolduranları,
Sıtma gebesi tazeleri görmeseydim,
Boşuna harcayacaktım sevgimi.
Şimdi şu parmaklığın ötesinde kaldı
Bütün çalışanlar;
Teker teker sökülmüşüz toprağımızdan,
Havamızdan, suyumuzdan olmuşuz.
Yaşamaktayız aynı çatının altında
Daha mahzun, daha hesaplı.
Rahat günlerin işçisi olacaktık,
Rahat günlerin şairi:
Bir çift sözümüz vardı
Nar çiçeği, gül dalı üstüne,
Dudaklarımızda kaldı!', 'Göremedik sıkıntısız yaşandığını, Rahatın şiirini yazamadık, Ne kadar uzak Heveslerimle içli dişli yaşamak, Üzmek hastalıklı şiirlerle Eşimi...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PARİS''TEN GEÇTİ SONBAHAR', 'pari-s-ten-gecti-sonbahar-endre-ady-8u7aw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün, sessizce geçip gitti Paris''ten sonbahar.
Saint-Michel''e çıkan bir sokağı iniyordu
Yürüyordu sıcaktan uyuklayan ağaçların altında,
Kararlı, bana doğru geliyordu.
Ağır adımlarla yaklaşıyordum Seine nehrine.
İçimde ölmüş ormanların ateşi şarkı söylüyordu.
Garip bir şarkı, acımasız, kan rengi
Bana kendi ölümümden söz ediyordu.
Yanıma geldi sonbahar. Bir şeyler söyledi kulağıma
Saint Michel Bulvarı korkudan tir tir titriyordu
Ve yol boyunca şen şakrak yapraklar
Neşe içinde dans ediyordu.
Bir an sürdü. Umarsamadı yaz, tınmadı bile,
Ve güz gülerek ayrıldı Paris''ten ruh gibi bir anda.
Geçip gitti. Ama bilen kimse yok olan biteni
O ağır ağaçların altında benden başka.
Endre ADY', 'Dün, sessizce geçip gitti Paris''ten sonbahar. Saint-Michel''e çıkan bir sokağı iniyordu Yürüyordu sıcaktan uyuklayan ağaçların altında, Karar...', ARRAY['Türk Edebiyatı','Şiir','Endre Ady']::text[], 8.5, '{"poet":"Endre Ady","poet_slug":"endre_ady","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PASAPORT KAHVESİ', 'pasaport-kahvesi-ahmet-telli-wy04g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyıda, taşın üstünde
oturmuş denize bakıyor
Kimse konuşmuyor onunla
ne rüzgâr ne de izmir
Gün bitiyor ve lacivert
sözcükler çekiliyor
susuşların ipek ağıyla
Az ötede pasaport kahvesi
- Gel, bir bardak çay içelim
diyor bütün gün beklenen
Bulut suya değiyor
su zamana
ve yalnız çakıltaşları
değil aşınmakta olan
Batık bir gemi
gibi uzaklaşırken ordan
yakamozlar kalıyor geride
balkıyan acılar gibi
Eskiyen neydi günboyu
yaşanan neydi
hangi bıçağı biledi deniz
Işıklar sönüyor kıyıda
ve burkulan bir yürekle
çekip gidiyor bu kentten
Ahmet', 'Kıyıda, taşın üstünde oturmuş denize bakıyor Kimse konuşmuyor onunla ne rüzgâr ne de izmir Gün bitiyor ve lacivert sözcükler çekiliyor susuş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet
telli̇']::text[], 8.5, '{"poet":"Ahmet\ntelli̇","poet_slug":"ahmet_telli","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAUL KLEE''DE UYANMAK', 'paul-klee-de-uyanmak-i-lhan-berk-e1mzu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyanmak çiçek gibi dayanılmaz güzel kızlar
Ad Marginem''den asma köprüler kurmuşlar İstanbul''a
Nehirler, aylar çevirmişler o Ayla''lar, Münibe''ler
Tümü bir uzak denizde A''lar, V''ler, U''larla
Gece sarı bir evde bir iki yaprak evlerinin önünde
Açtı açacaklar dünyamızı açtı açacaklar
Bu denizi Ayla ayaklarını soksun diye getirdim
Bu dünyaları onun için açtım bu balıkları tuttum
Bir sabah çıkmak güneşler, aylar bir sabah çıkmak
Bir ağacı bu evleri sarı ters bir kuşu düzeltmek
Edibe bu sokağı al götür görmek istemiyorum
Edibe bu evleri Edibe bu göğü bu güneşleri Edibe
A''lar V''ler U''larla olmak Paul Klee''de uyanmak
Galile Denizi', 'Uyanmak çiçek gibi dayanılmaz güzel kızlar Ad Marginem''den asma köprüler kurmuşlar İstanbul''a Nehirler, aylar çevirmişler o Ayla''lar, Münibe...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAY', 'pay-ozdemir-i-nce-jf86o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ev kurmak için bir zaman
tarla açmak için bir zaman
sevişmek için bir zaman
bakmak için bir zaman
görmek için bir zaman
anlamak için bir zaman
duymak için bir zaman
ayaklanmak için bir zaman
konuşmak için bir zaman
ekim için bir zaman
bağbozumu için bir zaman
kalmak için bir zaman
doğmak için bir zaman
yaşamak için bir zaman
çalışmak için bir zaman.
-Ölüm mü? demiştin?
Ölüme yer yok ülkemizde,
ölüme zaman yok.', 'Ev kurmak için bir zaman tarla açmak için bir zaman sevişmek için bir zaman bakmak için bir zaman görmek için bir zaman anlamak için bir zam...', ARRAY['Türk Edebiyatı','Şiir','Özdemir İnce']::text[], 8.5, '{"poet":"Özdemir İnce","poet_slug":"ozdemir_ince","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAYIMA DÜŞEN', 'payima-dusen-salih-bolat-b6udk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'herkes işinde gücünde
tohumu alınıp bostanda bırakılmış bir salatalık
gibi sararmış kurumuş elleriyle yün eğiren
şu nine işinde gücünde
arsa alım-satımıyla uğraşan profesör
ve öğrenmediği şeylerle sürekli sınanan
öğrenci işinde gücünde
saymakla bitiremediği paralarla
ellerinin ilişkisini araştıran veznedar
ve büyük kızını dün evlendiren
banka müdürü işinde gücünde
yeni bir sefere hazırlanan pilot
ve onun bir çok ülke dolaşmış olan çantası
kazasız belasız bir gün geçiren itfaiyeci
ve onun yangınlarla ilgili anıları
gece vardiyasına uyanan işçi
ve uyanmayan öfkesi
işinde gücünde şu çöplükteki tavuk
ki pamuk şekeri gibi civcivler hazırlanıyor
bana da oturup şiir yazmak kalıyor', 'herkes işinde gücünde tohumu alınıp bostanda bırakılmış bir salatalık gibi sararmış kurumuş elleriyle yün eğiren şu nine işinde gücünde arsa...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih_bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAZAR AKŞAMLARI', 'pazar-aksamlari-orhan-veli-cbak3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi kılıksızım, fakat
borçlarımı ödedikten sonra
ihtimal bir kat da yeni esvabım olacak
ve ihtimal sen
yine beni sevmeyeceksin.
bununla beraber pazar akşamları
sizin mahalleden geçerken,
süslenmiş olarak,
zannediyor musun ki ben de sana
şimdiki kadar kıymet vereceğim ?', 'Şimdi kılıksızım, fakat borçlarımı ödedikten sonra ihtimal bir kat da yeni esvabım olacak ve ihtimal sen yine beni sevmeyeceksin. bununla be...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PAZAR GÜNÜ TAKSİLERİ', 'pazar-gunu-taksi-leri-cevahir-si-pahi-41d7o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durakta çamların altında yirmi yedi taksi
Bekliyor sessizce bu yağmurlu gecede
Yarın yeniden karışacaklar kentin karmaşasına
Kahverengi yağmurluğumdaki damlalar gibi.
Ne bekliyor bu seferde onları? Ve nedir düşlerindeki?
Bu taksilerin, uyurlarken neon ışıkları altında?
Onların metalik düşleri kamaştırır farlarını
Yaşamın, yarın kesişir bir başkasının yoluyla.
Kimilerini kavuşturur gerçek aşklara,
Ötekiler çöpçatanların kurbanı, ağlamaklı.
Anlasaydım taksiye gözyaşlı birinin bindiğini,
Atardım kendimi durana dek tekerleri altına.
Cevahir  SİPAHİ', 'Durakta çamların altında yirmi yedi taksi Bekliyor sessizce bu yağmurlu gecede Yarın yeniden karışacaklar kentin karmaşasına Kahverengi yağm...', ARRAY['Türk Edebiyatı','Şiir','Cevahir  Si̇pahi̇']::text[], 8.5, '{"poet":"Cevahir  Si̇pahi̇","poet_slug":"cevahir_sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İPEK BİR MENDİL', 'i-pek-bi-r-mendi-l-zerrin-taspinar-u0mni', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ipek mendili olmadı hiç
yakasına takılan bir karanfil
yatağında gül yaprakları.
Tam öğrenirken şehrin çıkmaz sokaklarını
dükkân adlarını, güleryüzlü satıcıları
-Çünkü ürkekti ve çatık kaşlardan kekelerdi hemen -
tam öğrenirken bir şehri...
Her yolculuğa umut ve hüzünle başlardı
kocaman saksılarda taşırdı kirazlarını
nazarlıklar asardı dallarına, yumurta kabukları
paslı anahtarlar, önceki evin bırakılmışlığı
isli baca, çatlamış fayans, her şey
her şey bir ipek mendil özlemenin tadında.
Yeni komşular benimserdi severek gülümsemeyi
taş balkonları süslerdi renk renk
bıkmadan silip parlatırdı eski pirinç mangalları
bir ipek mendil özlemenin tadını ekleyerek
reçeller kaynatırdı sağaltım günlerinde.
Şiir yazmak ister de ağlardı her bahar
-Çünkü aşklar yanılgıyla gelirdi
ipek bir mendildi bütün dileği oysa -
ipek bir mendil için taramak saçlarını.
Bir ipek mendili olmadı hiç
ne de yatağında gül yaprakları.', 'Bir ipek mendili olmadı hiç yakasına takılan bir karanfil yatağında gül yaprakları. Tam öğrenirken şehrin çıkmaz sokaklarını dükkân adlarını...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Taşpinar']::text[], 8.5, '{"poet":"Zerrin Taşpinar","poet_slug":"zerrin_taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PELERİN', 'peleri-n-metin-guven-lo0s1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir adın pelerin, diğer yalnızlık
Siyah kadifeler içindesin
Kırmızı bir satenle astarlanıyor kalbin
Duyguların yok, belki daha doğmadın
Uğramıyor yıldızlar geceleri düşlerine
Sönüyor uykuyla beslenen kandil.', 'Bir adın pelerin, diğer yalnızlık Siyah kadifeler içindesin Kırmızı bir satenle astarlanıyor kalbin Duyguların yok, belki daha doğmadın Uğra...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PELİKAN', 'peli-kan-robert-desnos-dz8df', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizim serüvenci kaptan,
On sekizinde olduğu zaman,
Bir adadan, Uzakdoğu''dan
Alıp geliyor bir pelikan.
Gelgelelim bizim pelikan,
Yumurtluyor sonradan
Ve tıpatıp aynı olan
Bir yavru çıkıyor yumurtadan.
Sırası gelince yumurtlayan
Bu ikinci pelikandan
Yenisi çıkıyor, aman aman,
Bir başka yumurtlayan.
Bu iş böylece sürer gider uzun zaman
Yavru çıkmadan önce omlet yapılmazsa yumurtadan.
Robert DESNOS', 'Bizim serüvenci kaptan, On sekizinde olduğu zaman, Bir adadan, Uzakdoğu''dan Alıp geliyor bir pelikan. Gelgelelim bizim pelikan, Yumurtluyor ...', ARRAY['Türk Edebiyatı','Şiir','Robert Desnos']::text[], 8.5, '{"poet":"Robert Desnos","poet_slug":"robert_desnos","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PEMBE ARALIK', 'pembe-aralik-oktay-taftali-55raa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sabaha karşıydık
ya da geceden yana biz
darmadağınık rumuzunda bir kadın
saçları çeyrek, ilikleri kurumuş
alın yazısı gibidir cam parçaya bölünmüş insan
gençliğine doğru bir lale çeşmesi
terk etmek
seni de böyle düşlüyorum, mektuplarını iki yüzlü
iki yüzlü dün/koldemirleri bilek kalınlığı
ikincisi yıllar önce yazılmış/yere yakın pembe aralık
bir başka büyük yalan
duvar panoları
bildiğim en son kadın 93''lerde ağlamış
sonra ''anneler''
çok hızlı barbarların boyun eğdiği
kutsaldır ''bâkireler'' diyor
faili meçhul bir çocuğun
tanrıları utandıran çığlığı', 'sabaha karşıydık ya da geceden yana biz darmadağınık rumuzunda bir kadın saçları çeyrek, ilikleri kurumuş alın yazısı gibidir cam parçaya bö...', ARRAY['Türk Edebiyatı','Şiir','Oktay Taftali']::text[], 8.5, '{"poet":"Oktay Taftali","poet_slug":"oktay_taftali","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PEMBE YALI', 'pembe-yali-oktay-ri-fat-horozcu-kmah7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızlar vardır kıvırcık salata gibi
Ağızları burunları kıvır kıvır
Bacak bacak üstüne vapurlarda
Rüzgâr eser oraları buraları görünür
Baktıkça fık fık eder adamın içi
Vay canına tükürdüğümün İstanbul''u
Bir oynak olur Fındıklı önlerinde
Elimde yüz iğnelik çapari
Poyraz gibi dalarım palamutlara
Altımda Turgut Reis motoru
Rumelihisarı''nda Orhan''ın mezarı
Ne gittim ne gördüm gitmek de istemem
Taze ekmek bir parça beyaz peynir
Şimdi olsa şuracıkta rakı içer
Denize mi bakar kim bilir
Ben rıhtımdan suya atlarım
Altımda balıklar
Üstümde bulutlar
Ağzımın kenarında çırpıntılı Boğaz suyu
Pembe yalıya doğru yüzerim', 'Kızlar vardır kıvırcık salata gibi Ağızları burunları kıvır kıvır Bacak bacak üstüne vapurlarda Rüzgâr eser oraları buraları görünür Baktıkç...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PENCERE', 'pencere-arkadas-zekai-ozger-8uykc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'pencereyi kapama
gök dolabilir içeri
sen neyi görebilirsin
ıslak bir bulutun ağışını mı
pencereyi kapama
kuş dolabilir içeri
sen neyi taşıyabilirsin
kırık bir dalın yükünü mü
Pencereyi aç
soluğun çıksın dışarı
sen büyütmedin mi ciğerinde onu
Kokusu hayatı yıkasın diye
Pencereyi aç
sesin sarsın dünyayı
duyulur elbet ta ötelerden
Yürek kendini tanır', 'pencereyi kapama gök dolabilir içeri sen neyi görebilirsin ıslak bir bulutun ağışını mı pencereyi kapama kuş dolabilir içeri sen neyi taşıya...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas_zekai_ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PENCEREDE KADINLAR', 'pencerede-kadinlar-salah-bi-rsel-z7ras', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlkin bir sarışın açtı pencereyi
Sonra bir hallicesi bir dillicesi
Daha sonra güldü kaçtı
Kadınların en incesi
Derken sıra esmere geldi
Bir etlicesi bir sütlücesi', 'İlkin bir sarışın açtı pencereyi Sonra bir hallicesi bir dillicesi Daha sonra güldü kaçtı Kadınların en incesi Derken sıra esmere geldi Bir ...', ARRAY['Türk Edebiyatı','Şiir','Salah Bi̇rsel']::text[], 8.5, '{"poet":"Salah Bi̇rsel","poet_slug":"salah_birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PEŞİNDEN KOŞMALAR', 'pesi-nden-kosmalar-yusuf-altunel-wp9qh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmur yüklü bulutlar
gözlerinin karasını yakmış
düşkırıklığı sallamışsın yitirilmişlikler beşiğinde
yanaklarına tuzlu özlemler yağmış
rüzgarlar taşımamış adını
karlardan süzülen dereler seni hiç taşımamış
siyah saçlarını dökmüşsün gözlerine
ıslatmış yaralarını yağmurlar narin
sevmeler ellerinde cansız kalmış
toplar tüfekler ilgilendirmez seni
küçücük özlemler dolu dünyanda
dünya kırmış filizlerini
gizemlisin
ıssız kayalarda biten ağaç
dört mevsim boralara karşı koyarsın
ayışığında dalga dalga saçların
gözlerinin üstüne yıkarsın
önümden yağmur yüklü bulutlar geçer
usanmadan peşlerinden koşarsın', 'yağmur yüklü bulutlar gözlerinin karasını yakmış düşkırıklığı sallamışsın yitirilmişlikler beşiğinde yanaklarına tuzlu özlemler yağmış rüzga...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PENÇE', 'pence-ren-char-62d2f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kambur yürüyen gökyüzü soluk soluğa kalıyor çabucak;
Arabulucu, duyulmadı;
Onu mavi üstüne mavi, siyah üstüne altın rengi boyuyorum.
Bu gök bir ilkokullu çantası,
Dutların lekelediği.
René CHAR', 'Kambur yürüyen gökyüzü soluk soluğa kalıyor çabucak; Arabulucu, duyulmadı; Onu mavi üstüne mavi, siyah üstüne altın rengi boyuyorum. Bu gök ...', ARRAY['Türk Edebiyatı','Şiir','René Char']::text[], 8.5, '{"poet":"René Char","poet_slug":"rene_char","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERA''LI BİR AŞK İÇİN GAZEL', 'pera-li-bi-r-ask-i-ci-n-gazel-onat-kutlar-cu8oe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merhaba güzelim, bak nasıl doldurdu
-Dur önce şu sigaramı yakayım-
Kırmızı bir güneş bardağımızı
Dışarda kararan rum kilisesinin
Gürültüyü yapraklara çeviren
Çan sesleriyle yüklü ve karmakarışık
Saatlerden geçiyoruz umut, ayrılık
Günleri. Yüzünün gülü kapalı
Acı eylül geçiyor köklerimizden
-Sanırım değişen bir şey olmalı-
Biliyoruz öğle sonu mavi perdesi
Gözlerinin yıldızıyla ışıyan
-Dur güzelim yüzüne dokunacağım-
Ve aklı yetmeyen tarlakuşuna
Öpüşlerle derinleşen bir halı
Yeni gelin bahçeleri dokuyan
-Bu kör eylül karanlığından uzak-
Bir ölümsüz yaz ülkesi olmalı
Çıkalım buradan hemen gidelim
-Ben önce şu hesabı vereyim-
Avluda fatihin ormanlarından
Kesilmiş çamlara bakan rum yetim
İçimi yalnızlıkla dolduruyor
Kapıda sadakor bir dalgınlığın
Ardından bize bakan şu delikanlı
-Nasıl benim gençliğime benziyor-
Şiirimiz bitince ve solduğunda
Sarı gül yaprağına yazdığım divan
Alıp götürecek bir sahaf olmalı', 'Merhaba güzelim, bak nasıl doldurdu -Dur önce şu sigaramı yakayım- Kırmızı bir güneş bardağımızı Dışarda kararan rum kilisesinin Gürültüyü y...', ARRAY['Türk Edebiyatı','Şiir','Onat Kutlar']::text[], 8.5, '{"poet":"Onat Kutlar","poet_slug":"onat_kutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERDELER', 'perdeler-necip-fazil-kisakurek-xgjsu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Perdeler, hep perdeler...
Her yerde, her yerdeler.
Pencerede, kapıda,
Geçitte, kemerdeler...
Perdeler, hep perdeler...
Ya benim sevdiklerim,
Şimdi nerde, nerdeler?
Önü bomboş perdenin;
İçerde, içerdeler!
Perdeler, hep perdeler...
Gönülde asıl perde;
Onu hangi göz deler?
Surat maske altında,
Sis altında beldeler.
Perdeler, hep perdeler...
Perdeye doğru akın;
Atlılar, piyadeler.
Yollar, yönler dolaşık;
Değişik ifadeler.
Perdeler, hep perdeler...
Bir tohumda bin gömlek.
Giyim giyim fideler.
Kalbler dilini yutmuş;
Bangır bangır mideler.
Perdeler, hep perdeler...
Son noktada son perde;
Çevrilmiş seccadeler.
Orada işte işte,
Ölümden âzadeler!
Perdeler, hep perdeler...', 'Perdeler, hep perdeler... Her yerde, her yerdeler. Pencerede, kapıda, Geçitte, kemerdeler... Perdeler, hep perdeler... Ya benim sevdiklerim,...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERÇEM', 'percem-kemal-ozer-gykp9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'açılmış bir uykudur gözleri masada
çocuğun böyle baktığı harita
kusacak gibi olduğu korkudan
en yakın elini tuması annesinin
ölmüşler çizgileri çizilmiş ne bilsin
ölmüşler ölüme arkalarını dönerek
çizgileri çizilmiş kızların ardahan''ın
gözleri görünmez olunca uykudan ağlamaktan
kan mı geçmiş artık bu kadar beyaz
taşlar örtüler bu kadar beyaz
kan mı geçmiş aydınlığından sokakların
çocukların bulaşmış bı kadar ellerine
her çocuk bir şehrin saat kulesi
içinde cambazlar sallanıyor ölüme
ölüm saatlerinin korkunç kulesi
bir ayağı annesine bir ayağı ölüme', 'açılmış bir uykudur gözleri masada çocuğun böyle baktığı harita kusacak gibi olduğu korkudan en yakın elini tuması annesinin ölmüşler çizgil...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERÇEMLİ SOKAK''TAN', 'percemli-sokak-tan-oktay-ri-fat-horozcu-dgn1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I
Bulutların çıkınında
Mis kokulu güvercinleri gökyüzünün
Çıldırtırlar insan gözlü kedileri
Ay doğar kuyulara yalınayak
Telgrafın tellerinde gemi leşleri
II
İşte kara dutları güneşin
Papatyaların renkli camları
Başakları evlerin
Kan rengi kız çocukları yelesiz
Lokma lokma ağaçların altında
Tren yolunda eğri büğrü
Damları doğrayan makas
Gel bulutsuz masalara yaslan
Elimi tut büyüsün
Yüzüme bak çalsın
İçimdeki çalar saat
Dönüş yollarında sarmaş dolaş
Vapurlar geçsin aramızdan
X
Güneşimi arılar yedi gecesiz kaldım
Dört köşe taşların üstünde
Denizin çarşısında yeşil zeytin
Balıklar geçti düdük çala çala
Yaşamaya başladım kaldığı yerden
Yosunlu kapıların ardında gizli
İkiz martıları bulmak için
XLI
Beyaz mendiller vardı havada
Çalgılı gemiler balkonlarda açık saçık
Bir kız vardı yok gibi öyle güzel
Ne yerde ne gökte belki tuzda
Acısında ekmeğin dilim dilim buğusunda
Kendine göre evlerin damı çatanası
Bacaların şakırtısında akşam akşam
Saksılar sedirler tahtaların güvercini
Otursa kısa çoraplarını çekse dilenmese
Beş çocuk anası el
Eciş bücüş maydanoz bahçeleri
Düğümlü balıkları bekleyişin
Uzun etme iki gözüm biraz da bize uğra
Bu lambanın karpuzu benim işte
Benim işte bu testi
Benim işte bu soysuz sevdaların musluğu', 'I Bulutların çıkınında Mis kokulu güvercinleri gökyüzünün Çıldırtırlar insan gözlü kedileri Ay doğar kuyulara yalınayak Telgrafın tellerinde...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERİLİ DERE', 'peri-li-dere-ali-yuce-es6nd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Köyün altında bir dere
Cıvıl cıvıl peri
Besmelesiz geçilmez ha
Geçer miyiz hiç
Akmaya üşenir suyu
Yüzünde bir karış saman
Üflemeden içilmez ha
İçer miyiz hiç
Bir varmış bir yokmuş
Çok  eski zamanlarda
Bir peri kızı varmış
O zamanlar bu dere
Akarmış köpüre köpüre
Masal bu ya
Kız ırmakta yıkanırken
Gamzesini düşürmüş suya
Çok üzülmüş peri kızı
Yalvarıp yakarmış ırmağa
Ver gamzemi demiş
Irmak da ırmakmış ha
Almış kızın gamzesini
Geri vermemiş bir daha
Sen misin bunu yapan
Peri kızı bu ya
Her gözünden bir damla yaş
Damlatıvermiş ırmağa
Kuru bir dere olmuş ırmak
Hiç akmamış bir daha', 'Köyün altında bir dere Cıvıl cıvıl peri Besmelesiz geçilmez ha Geçer miyiz hiç Akmaya üşenir suyu Yüzünde bir karış saman Üflemeden içilmez ...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüce']::text[], 8.5, '{"poet":"Ali Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PERİLER AŞKA UÇAR', 'peri-ler-aska-ucar-haydar-ergulen-1pqah', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne güzel çarşaflar sererdin aşka
üstünde serin kanatların yelken açardı
bir gün kim bağırdıysa uyandık birbirimizden
-deniz bitti, boğuluyorum, camı açsana!
denizin üstünde uyku yasaklandığından beri
karadayım, boğulsam da kırpmıyorum gözlerimi
her zaman benim gözlerim değil uykusuz
görüyorum beni okşayan gözlerindeki geceyi
yakılacak öyle çok sır var ki bu ormanda
yine sen tutuştur, yine bir avuç suyun
uslandırsın deli çiçekleri ezen kötü sözleri
derim ki: - aşk varmış o perinin çırptığı her kanatta!', 'ne güzel çarşaflar sererdin aşka üstünde serin kanatların yelken açardı bir gün kim bağırdıysa uyandık birbirimizden -deniz bitti, boğuluyor...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar_ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PEYNİR GEMİSİ', 'peyni-r-gemi-si-i-lhan-demi-raslan-adlkc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu paradır, anlıyor musun,
Arada geçer elime,
Et alırım, ekmek alırım,
Evime.
Bu paradır işte, yüzü tatlı,
Dünya dediğin üstünde durur,
Bir gece sayılır eline,
İnsan orospu olur.
Bu paradır, boru değil,
Gün kazanılır, gün biter,
Peynir gemisi bununla yürür,
Düdük bununla öter.
Bu paradır işte, kokla bunu
Her işin başı budur,
Seni katil etti bu,
Beni memur.', 'Bu paradır, anlıyor musun, Arada geçer elime, Et alırım, ekmek alırım, Evime. Bu paradır işte, yüzü tatlı, Dünya dediğin üstünde durur, Bir ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Demi̇raslan']::text[], 8.5, '{"poet":"İlhan Demi̇raslan","poet_slug":"ilhan_demiraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PIRPIRLI ŞİİR', 'pirpirli-si-i-r-orhan-veli-r5rkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyandım baktım ki bir sabah,
Güneş vurmuş içime;
Kuşlara, yapraklara dönmüşüm,
Pır pır eder durur, bahar rüzgârında.
Kuşlara, yapraklara dönmüşüm;
Cümle âzâm isyanda;
Kuşlara, yapraklara dönmüşüm;
Kulşara,
Yapraklara.', 'Uyandım baktım ki bir sabah, Güneş vurmuş içime; Kuşlara, yapraklara dönmüşüm, Pır pır eder durur, bahar rüzgârında. Kuşlara, yapraklara dön...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PÜLÜMÜRÜN YAŞSIZ KADINI', 'pulumurun-yassiz-kadini-bulent-ecevi-t-dh0yy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pülümürün bir dağ köyünde gördüm onu
yaşını sordum bir giz gibi güldü
kimi seksen dedi köylülerden kimi yüz
yüzüne baktım bir giz gibi güldü
bir asa vardı elinde
bir solmuş kırallığın
kadifeden harmanisi üzerinde
bir hititliydi o bir selçukluydu
bir ermeniydi bir kürttü
bir türk
yaşını sordum bir giz gibi güldü
koluma girdi bir soylu kadınca
tozlu köy yolunda sürüyerek eteğini
beni tek gözlü sarayına götürdü
köy yapısı kulübesinin
zamanı onda yitirdim ben
yitik zamanlara onda eriştim
en soylu yoksulluğun toprak döşeli sarayında
bir taç gibi kondu başıma Türkiyeliliğim
Bülent ECEVİT
Bilgi : Pülümür Doğu Anadolu''nun en yoksul yörelerinden biridir.', 'Pülümürün bir dağ köyünde gördüm onu yaşını sordum bir giz gibi güldü kimi seksen dedi köylülerden kimi yüz yüzüne baktım bir giz gibi güldü...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'POETİKA', 'poeti-ka-mehmet-taner-oqciv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nasıl mı bir şiir,
Yeryüzünü yürüyen burgaçlar gibi
İki omuzları ortasında üryan bir şiir
Merdivenden çıkan
bir şiir
Merdivenden inen
bir şiir
Merdivensiz bir şiir, merdivenden
bir şiir
Bir şiir
Kara balık yumurtası gibi
Bir şiir
Acı soğan sofrası gibi
Kıldan Sırat, Sırf''tan Edat
Yaralı gıdadan ibaret, yaralı tekrardan bir at
Ve kıvılcım ve yele
Ve homurtu, ve kişneme
Ölçülü bir şiir,
Ona rağmen ölçülü bir şiir
Eve gelen bir şiir,
Ama evde olmayan
Yüzüme taktım mı yüzüm kalan
İki omuzları ortasında nihan bir şiir', 'Nasıl mı bir şiir, Yeryüzünü yürüyen burgaçlar gibi İki omuzları ortasında üryan bir şiir Merdivenden çıkan bir şiir Merdivenden inen bir şi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PORTRE', 'portre-charles-baudelaire-20zho', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hastalık ve ölüm çevirir küle
Bütün ateşleri bizim''çin yanan.
Aşk ve şevk dolu bu iri gözlerle,
Kalbimin boğulduğu bu ağızdan,
Bu öpüşten merhem gibi etkili,
Bu coşkudan bir ışık kadar keskin,
Ne kalır? Ruhum, bu dehşet verici!
Sadece üç çizgi, soluk bir resim,
Ölür, benim gibi bir yalnızlıkta,
Ve zaman, o küfürbaz ihtiyar ki,
Sürtünüyor her gün sert kanadıyla...
Hayat ve Sanatın kara katili,
Öldürmeyeceksin bende kalanı
Zevkim ve şanım olan kadını!
Charles  BAUDELAIRE', 'Hastalık ve ölüm çevirir küle Bütün ateşleri bizim''çin yanan. Aşk ve şevk dolu bu iri gözlerle, Kalbimin boğulduğu bu ağızdan, Bu öpüşten me...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'POSTACI', 'postaci-n-zim-hi-kmet-z3z0n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanın, dünyanın, yurdun haberini,
ağacın, kuşun, kurdun haberini,
seher vakitlerinde
yahut
gecenin ortasında
taşıdım insanlara yüreğimin çantasında,
şairlik ettim
bir çeşit postacılık yani.
Çocukken postacı olmak isterdim,
şairlik filân yoluyla değil ama
basbaya, sahici postacı.
Renkli kalemlerle çizilirdi bin türlü resim
hep aynı postacının, Nâzımın resmi,
Jül Vernin romanlarıyla coğrafya kitaplarına.
İşte, köpeklerin çektiği kızağı
sürüyorum buzun üzerinde,
Işıldıyor kuzey şafağı
konserve kutularıyla posta
paketlerinde.
Bering boğazını geçiyorum.
Yahut işte bozkırda gölgesinde ağır bulutların
asker mektubu dağıtıp ayran içiyorum.
Yahut da büyük şehrin uğultulu asfaltındayım,
çantamda yazıları yalnız müjdelerin
yalnız umutların.
Yahut çölde, yıldızların altındayım.
Bir küçük kız ateşler içinde hasta.
Kapı çalınıyor gece yarısı:
-posta!
Küçük kızın gözleri açıldı mavi mavi.
Babası yarın akşam dönüyor hapislikten.
O karda kıyamette bendim bulan o evi,
komşu kıza bendim telegrafı getiren.
Çocukken postacı olmak isterdim.
Oysaki, Türkiyemde postacılık zor sanattır.
Telegraflarda envai türlü acı
mektuplarda satır satır keder taşır
o güzelim memlekette postacı.
Çocukken postacı olmak isterdim.
Muradıma, Macaristan''da erdim, ellisinde.
Çantamda bahar,
Çantamda Tuna''nın pırıltısıyla
kuş cıvıltısıyla,
taze çimen kokusuyla dolu mektuplar.
Moskova''ya Budapeşte''den,
çocukların çocuklara mektupları.
Çantamda cennet...
Bir zarfın üzeri:
&quot;Memet,
Nâzım Hikmet''in oğlu,
Türkiye&quot;
diye yazılı.
Moskova''da mektupları birer birer
kendim dağıtırım adreslerine.
Yalnız Memedin mektubunu götüremem yerine.
hattâ yollıyamam.
Nâzım''ın oğlu,
haramiler kesmiş yolu,
mektubunu vermezler.', 'İnsanın, dünyanın, yurdun haberini, ağacın, kuşun, kurdun haberini, seher vakitlerinde yahut gecenin ortasında taşıdım insanlara yüreğimin ç...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":61}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PİPO', 'pi-po-i-lhan-berk-cgu6f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pipo üstüne kimler kitaplar
yazmıştır, bilmiyorum. Daha çok aksoylu, şato adamı, ihtiyar bir İngilizden
beklenmelidir bu. Şatosuna çekilmiş, pipolarını dizmiş, koltuğuna gömülmüş,
tütününü yavaş yavaş hazırlayan,
dalıp gitmiş, ocak
başı adamı bir İngilizden.
Ya da inekler gibi rahat, uzun
boylu bir Hollandalı da olabilir bu. Ama neden az buçuk bir pipo adamı olan
ben olmayayım?
Öyleyse?
Ben en çok uzun saplı, geniş karınlı pipoları severim. Avuç içini
dolduran, ilkel, yabansı, ağır pipoları. Şiirin elini sımsıkı tutan,
kendi halinde, sessiz, emektar, çileli pipoları.
Benim gibi yaşını başını
almış bir adamdan da bu beklenir elbet. Hem pipo dalıp gitmesini bilen, düş
adamlarına vergidir: İhtiyar, evcil, masa başı adamlarına. En çok da
ozanlara.
Pencere, masa başıdır piponun yeri.Ordan oraya taşınmayan nesneler
gibi belli bir yeri, belli bir yurdu olan. Bir kötürüm, bir yatalak hayatı.
Dünyayı bir pencere gören, dünyayı bir pencere bilen. Tekdüzeli bir yaşam
adamlığı: Sinirli, mızmız, kargılı. Benim gibi. Yine benim gibi ilençli,
sıkıntılı, çılgın. Bir ortaçağ adamı: Suyu üfleyerek içen.
Altı büyük
küçük pipom içinde ben en çok sessiz, gösterişsiz VEDO’yu,
VEDO
POPULAR’ı
severim. Büyük, uzun boylu, uzun yüzlüdür. Ne
Pompei’nin o ünlü fresklerine geçmiş, ne de Saint Claude’ın yüzünü görmüştür.
Alçakgönüllü ağaçlar soyundandır. Ağırbaşlı, yalın, som. Halk kökenlidir.
Halk gibi süssüz püssüz, sıradan. Ama yine onun gibi dayanıklı, sağlıklı,
sevecen. Haşarı, haytacı, müsrif değildir. Tütünü seçmeyen, sessiz, içten
içe yanan, ölçülü, tutumlu, dengelidir. Benim gibi bilisiz, tezcanlı, tıknefes
birinin elinde soluğunu sürdürmesini, ayarlamasını, denetlemesini bilir. Kızmaz.
Benim gibi duygularını, heyecanını, heyheylerini bastırmasını bilmeyen
birine karşı alevlenip, hırçınlaşayım demez. Hep bir evliya tavrı takınır.
Bütün huysuzluklarıma, tersliklerime karşı güler,susar. Bekler önümdeki
şiir hele bir etlenip budaklansın, kıvamını bulsun diye. Bilir ki mızmız,
cenabet bir adamımdır. Bunun için susar, susar, sonra da yavaş sessiz içine
çekilir.
VEDO’yu
işte bütün bu huyları için severim. Benim gibi birine dayandığı için.
kül', 'Pipo üstüne kimler kitaplar yazmıştır, bilmiyorum. Daha çok aksoylu, şato adamı, ihtiyar bir İngilizden beklenmelidir bu. Şatosuna çekilmiş,...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PİR SULTAN', 'pi-r-sultan-hi-lmi-yavuz-n0k5j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'alçacıktan uçarken yaza dokunan
sessizliktir belki ahşap kanatlı
kulluğa acı tuz vuran son atlı
bir hüznün soyadıdır pir sultan
kalın turnalarda balkıyan gizle
gök ekin çilerken geceye sazı
bir gül derneğinin börklü sonyazı
köpükten gömleği, yensiz denizde
şimdi derin doğumlara koşan kim
ey bin çiçek soluyan yağız dokuma
sorguçlu düşlerle çattığın ova
kızıl gülde konaklasın isterdin', 'alçacıktan uçarken yaza dokunan sessizliktir belki ahşap kanatlı kulluğa acı tuz vuran son atlı bir hüznün soyadıdır pir sultan kalın turnal...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PRENS', 'prens-kuvvet-yurdakul-2y277', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni yazsam artık
Belki dinerdi her şey
Uyurdum
Sandıklı bir kız bulurdum
İstemediği izinler kadar kısa
Tutmadığım sözler gibi aramızda
Başlar biterdi günler
Artık seni yazsam
Böyle uzamazdı saçlarım
Kapı almaz gele atmazdım
Dantel bir atlı gibi sandıkları gezerdim
Her iş gelen ellerinden gelip
Bir terzi gibi keskin
Bütün düşlerimden geçerdim
Bu tesbih beni mutlu etmedi
Dağıt
Bir gün basar düşeriz
Her sabah kötü bir şarkıya
Nakarat oluyorsak
Bana sorma dünyada mı bütün gezegenler
Ne bilmek marifet ne şaşırmak
Bu tesbih beni mutlu etmedi
Onu dağıt
Otuz üç kez öp beni
Seni yazsam okusam
Bir ben mi eksilir yaşamaktan
Aynı evin içinde
Üç oda bir salon kere
Ayrıldık birbirimizden
İşlensin fen bilgisi bunca öptün
Kaç tesbih dağıldı
Bir prens bile olamadım', 'Seni yazsam artık Belki dinerdi her şey Uyurdum Sandıklı bir kız bulurdum İstemediği izinler kadar kısa Tutmadığım sözler gibi aramızda Başl...', ARRAY['Türk Edebiyatı','Şiir','Kuvvet Yurdakul']::text[], 8.5, '{"poet":"Kuvvet Yurdakul","poet_slug":"kuvvet_yurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PROMETE KENTTE', 'promete-kentte-bulent-ecevi-t-bs3ow', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'promete şimdi kentte
kayalara bağlı değil
beton duvarlarla çevrilidir
kartalların giremiyeceği bir semtte
kendi kendini kemirir', 'promete şimdi kentte kayalara bağlı değil beton duvarlarla çevrilidir kartalların giremiyeceği bir semtte kendi kendini kemirir...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PROVA', 'prova-can-yucel-fumcq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava cehennemi sıcaktı
Daltaşak yatıyordum sedirde
Bir esinti çıktı birden
Göğsümün kıllarını
Sikimin tellerini titretti.
Böyle olsun benim ölümüm dedim
Soğuktan önce serinlemek
Yaylı bir tambur taksimi sanki', 'Hava cehennemi sıcaktı Daltaşak yatıyordum sedirde Bir esinti çıktı birden Göğsümün kıllarını Sikimin tellerini titretti. Böyle olsun benim ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PÜSKÜRTME', 'puskurtme-ali-cengi-zkan-t8apr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşey yerli yerindeydi, masalar, sandalyeler
tabldot tepsileri, tabaklarda yemekler
Tütüyordu hâlâ. Kabukları soyulmuş bir portakal
Duruyordu orda, üstünde bir kızın parmaklarının sıcaklığı
yanında yarım bardak su
havada gülüşmeler, çatal bıçak sesleri...
Herşey yerli yerindeydi, ve kuşkusuz onlar da
Toplamışlardı işlerine gelenleri ve gelmeyenleri,
afişleri, pankartları, duvar gastelerini
kırık camları, kurşun kovanlarını, sopaları
kanlı bir ayakkabı tekini
gözleri yuvalarından fırlayan gasteciyi.
Herşey yerli yerindeydi, öğrenciler yemekhaneye
döndüklerinde.', 'Herşey yerli yerindeydi, masalar, sandalyeler tabldot tepsileri, tabaklarda yemekler Tütüyordu hâlâ. Kabukları soyulmuş bir portakal Duruyor...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İPUCU', 'i-pucu-mehmet-kiyat-1evqx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğun ipucunu buldum
yanına aldı bizi
Sabahın ağzına açılan kapılarda
kuşların sesiyle uyanan
İlkyazın renklerine sarındım sonra
güneşe komşu
Fildişi evler kurdum seninle
Bakışların
seviyi damıtırken içimizde
İkimizle birlik
yüzyüze
Sevincinden
susuzluğunu unuttu toprak', 'Sonsuzluğun ipucunu buldum yanına aldı bizi Sabahın ağzına açılan kapılarda kuşların sesiyle uyanan İlkyazın renklerine sarındım sonra güneş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kiyat']::text[], 8.5, '{"poet":"Mehmet Kiyat","poet_slug":"mehmet_kiyat","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PUSULA', 'pusula-refik-durbas-bsh5z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Annemin öldüğü yaşı çoktan geçtim
suyun vefası ve acılar
-bir de gökyüzü
çocuklarım olsa da
Babamın öldüğü yaştayım artık
gurbeti sıla, sılası hicran
Bir de yalnızlık
arkadaşım olsa da
Rüzgârlar yazsın aşkımı
Ama gönlüm hâlâ
oğlumun âşık olduğu yaşta
-sevdanın pusulası
anılarım olsa da
İki güvercin ey ömrüm
yılların omuzuna tünemiş
biri hayat, öteki ölüm
yaşadığım olsa da
Biri Refik, öteki Durbaş aslında', 'Annemin öldüğü yaşı çoktan geçtim suyun vefası ve acılar -bir de gökyüzü çocuklarım olsa da Babamın öldüğü yaştayım artık gurbeti sıla, sıla...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PİYANOLU ASES', 'pi-yanolu-ases-salah-bi-rsel-efc4d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben piyano çalıyorum sen orada kaç yıl
Saçlarını at sevmeyi değiştiriyor çünkü
Ellerini at gözlerini at dudaklarını at yoksa
Ben seni okşuyorum senin esmerliğinle yoksa
Senin gökyüzün benim gökyüzümden piyanolu
Kirpiklerini at gözlerini öpüyorum çünkü
Kaşlarını at ağzını at kulaklarını at
Ben seni okşuyorum senin esmerliğinle yoksa
Ben senin dişlerinle gülüyorum daha ne
Senin yıldızların her gece Beethoven li
Piyanoyu al seni düşünmeyi tutuyor çünkü
Ben seni sevdalıyorum sen orada kaç yıl', 'Ben piyano çalıyorum sen orada kaç yıl Saçlarını at sevmeyi değiştiriyor çünkü Ellerini at gözlerini at dudaklarını at yoksa Ben seni okşuyo...', ARRAY['Türk Edebiyatı','Şiir','Salah Bi̇rsel']::text[], 8.5, '{"poet":"Salah Bi̇rsel","poet_slug":"salah_birsel","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİR ALDATMASI', 'si-i-r-aldatmasi-melih-elhan-wqvwd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'henüz
erken
ergen olmaya
ama
dün akşam
ne gördüyse artık rüyasında
şiir aldatmış onu
bir de baktık ki
sabah,
kağıtlar
sırılsıklam
sözcük
sırılsıklam
imge', 'henüz erken ergen olmaya ama dün akşam ne gördüyse artık rüyasında şiir aldatmış onu bir de baktık ki sabah, kağıtlar sırılsıklam sözcük sır...', ARRAY['Türk Edebiyatı','Şiir','Melih Elhan']::text[], 8.5, '{"poet":"Melih Elhan","poet_slug":"melih_elhan","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİR ÇALIŞMALARI', 'si-i-r-calismalari-sureyya-berfe-znt2n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '20.
Olduğum yerden başlasam yaşamağa;
olduğumu sandığım yerden.
22.
Her geçen yıl eşyasızlığa alıştırıyor
eşyasızlığı bana.
Soğuyoruz günümüzün gözdelerinden
ısınıyoruz yalına, yalınlığa.
23.
Sordum yeni doğmuş bir bebeğe:
-Boş zamanlarını nasıl değerlendiriyorsun?
-Annemin sütünü düşleyerek.
Bir mezarlıktan geçerken sordum ölülere:
-Affedersiniz. Boş zamanlarınızı nasıl
değerlendirirsiniz?
-"Gelecek"leri düşünerek.', '20. Olduğum yerden başlasam yaşamağa; olduğumu sandığım yerden. 22. Her geçen yıl eşyasızlığa alıştırıyor eşyasızlığı bana. Soğuyoruz günümü...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
