INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİR GİBİ', 'si-i-r-gi-bi-yusuf-altunel-3keyj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'her ay yüz kere
ölüm çizerim kağıda
yüz kez hayat
işkence, cansız beden
haykırışları dizerim önüme
ayıklanır bahar çiçeği gibi
yüz kere adımı yazarım
silerim yüz kere
beğenmeme silgisiyle
her ay yüz inci dizerim
çapkın kızların boynuna
kendi elim ile takarım
yüz şiirden kız
salınır rüzgarında coşkunun
yüz sevişme dökerler dizelere
her sevişmeyi etek diye giyerler
yel savursun diye
tuzlu rüzgar gibi konar
dalına bir denizin
anısına yitik gemicilerin
her ay yüz kere
aya çıkar adım
kırmızı bir lekedir yatağım
hilalde yıldız
dolunayda kız
hilal bakışlı
gül yüzlü bir yalnız
her ay düşerim yollara
ne bulmuşsam dolu çıkınım
renkli şekiller
anlam ki yenidoğan
alamaçlar bulamaçlar
isimsiz yiyecekler
karın doyuran cinsinden değil
yedikçe aç bırakan
kan kusturan kurt düşüren
köpek öldüren
onun için beğenmez tanrılar
zehirimi zıkkımımı
yılanlar bile uzak durur
ilk kendini sokmalı akrep ne çare ki
cehennem alırım koynuma
veririm nefesimi
her ay yüz şiir
yazılır ve atılır çöpe
ya da yakılır her yazılan
şiir mi istediniz?
alın size şiir
ister boynuna asın şairin
idam fermanı diye
ister gece alın koynunuza
büyütmek için gündüzleri
ya siz en iyisi
boşverin gitsin
basarsınız sonra her şiiri
nasılsa yaşlanacak şairler
olgunlaşacak akları saçların
o zaman sayfaları açın
şimdi erken
çok erken
üşenip kalkmayın yatağınızdan
kapıcı getirecek ekmeğinizi nasılsa
şairlerin pişirdiği fırından
kahvaltınızı hazırlayacak eşiniz
yumurtanızı imge suyunda
pişirecek ve tostlarınızın arasına
şiir katacak kaşar niyetine
siz afiyetle yiyin
nöbet tutar genç şairler kapınızda
rahatsız etmesin diye sizi
sabah güneşinin keskin dişleri
şiir istiyorsunuz ya
hani genç işi
ama ustam yapma
hangi eşek beğenmiş ki
ilk giydiğinde semeri?
en iyisi binmek rüzgara
akmak gökyüzüne bulutçasına
belki girer bir gün
evinizden şiir gibi içeri', 'her ay yüz kere ölüm çizerim kağıda yüz kez hayat işkence, cansız beden haykırışları dizerim önüme ayıklanır bahar çiçeği gibi yüz kere adım...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":82}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜŞÜR ÖLÜM BİLE', 'usur-olum-bi-le-ulku-tamer-mxdxo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ormanda tutup onu
Bağladılar ağaca
Yumdu sanki uyur gibi
Gözlerini usulca
Bir soğuk yel eser
Üşür ölüm bile
Anlatır akan kanı
Beyaz sesiyle
Diz çöktüler karşısında
Sonra ateş ettiler
Parçalanan yüreğine
Yuva kurdu mermiler
Bir soğuk yel eser
Üşür ölüm bile
Anlatır akan kanı
Beyaz sesiyle
Gelip kondu bir güvercin
Ellerine o gece
Kırmızı bir çelenk oldu
Bileğinde kelepçe
Bir soğuk yel eser
Üşür ölüm bile
Anlatır akan kanı
Beyaz sesiyle', 'Bir ormanda tutup onu Bağladılar ağaca Yumdu sanki uyur gibi Gözlerini usulca Bir soğuk yel eser Üşür ölüm bile Anlatır akan kanı Beyaz sesi...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku_tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİR; ÇÜNKÜ', 'si-i-r-cunku-tulay-yener-k34sg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 've tanrı, önce şiiri yarattı,
şiiri yaşayacak yalnızlıkları;
...
yaşıyorduk
üşüyorduk;
yalnızlığımıza yamadık gökyüzünü;
karanlığa ay''ı yam(a)ıyorduk
biliyorduk;
benzemiyordu biri ötekine;
''tanrı'' şekilli kurabiyeler yapıyorduk
korkmuyorduk;
dokunup kendi gerçekliğimize;
...
şaşıyorduk
solu''yorduk;
şiiri, nefesimizle maviye boyuyor,
tanrı''ya isyan ediyorduk
çünkü,
eşi yoktu yalnızlığımızın;
anlaşılmak için kıvranıyorduk
...
yazıyorduk', 've tanrı, önce şiiri yarattı, şiiri yaşayacak yalnızlıkları; ... yaşıyorduk üşüyorduk; yalnızlığımıza yamadık gökyüzünü; karanlığa ay''ı yam(...', ARRAY['Türk Edebiyatı','Şiir','Tülay Yener']::text[], 8.5, '{"poet":"Tülay Yener","poet_slug":"tulay_yener","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
