INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU ISIT SEVGİLİM', 'su-isit-sevgi-li-m-turgay-fi-sekci-bgnl6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Su ısıt sevgilim yıkanayım
Üzerimde dünyanın tüm kirleri
Onlardan arınmadan sana sarılma’yım
Su ısıt sevgilim yıkanayım
Şimdi dışardan geldim
Yalanlar söyledim , iftira ettim
Onurum yitti , para kazandım derken
Su dökmeden ekmeğe el sürme’yim
Alın terim bugün de soğuk , kuşkulu aktı
Gömleğim ıslandı ama tenim soğuktu
Tedirgin bu hayatın sınırlarından
Bekledim soluklanmaya akşamı
Sevgilim , kırlarda bir gece senin kokun
Beyaz yüzün , sarı gözlerin
İnsan yürekleri yetiştirdiğin toprak
Ben sana su , ekmek getiren
Sen böyle olmasan , böyle beyaz
Gözlerin böyle sarı bakmasalar
Hep ilk kez sarılıverecekmiş gibi
Ben başkası olurdum o zaman
Su ısıt sevgilim yıkanayım
Üzerimde dünyanın tüm kirleri
Bir sen varsın kalbimi koruyan.
Turgay FİŞEKÇİ
---------------------------------------------------------------------------------------
“Kuşkuluyum Yaşadığımdan” , 1983
“Yitik Bahar” , Haziran 1995 , 2. Bası ,', 'Su ısıt sevgilim yıkanayım Üzerimde dünyanın tüm kirleri Onlardan arınmadan sana sarılma’yım Su ısıt sevgilim yıkanayım Şimdi dışardan geldi...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU, RÜZGÂR VE NAMUS', 'su-ruzg-r-ve-namus-s-ndor-petofi-6mure', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha çocukluğumda,
Dinlemiştim bu masalı:
Su, rüzgâr ve namus
Bir gün saklambaç oynamışlar.
Önce su saklanmış;
Fakat çabuk bulunmuş
Derin vadiler arasında...
Sonra rüzgâr saklanmış,
Onu da bulmak kolay olmuş
Yüksek dağların tepesinde...
Sıra namusa gelmiş
O da şöyle söylemiş:
Dinleyin bir kere,
Ben kaybolursam
Bulunmam hiçbir yerde...
İşte, o günden beri namus kaybolunca,
Bulunmaz hiçbir yerde.
Sándor PETOFİ', 'Daha çocukluğumda, Dinlemiştim bu masalı: Su, rüzgâr ve namus Bir gün saklambaç oynamışlar. Önce su saklanmış; Fakat çabuk bulunmuş Derin va...', ARRAY['Türk Edebiyatı','Şiir','Sándor Petofi̇']::text[], 8.5, '{"poet":"Sándor Petofi̇","poet_slug":"sandor_petofi","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU TADINDA', 'su-tadinda-sina-akyol-c53aj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Yalnız değilim ki orda...
O çıplak
göğün altında,
sabahtı! ormana karışan
bir sabah
gibi indim
nice güzel duyguyla...
Çoğaltarak beni, yan yana
geçtiler, tuhaf bir tıpırtıyla
giden süre
uzakta, bir çizgi olunca,
yazdım erken
başlayan günü:
Mavidir
diye yazdım.', '-Yalnız değilim ki orda... O çıplak göğün altında, sabahtı! ormana karışan bir sabah gibi indim nice güzel duyguyla... Çoğaltarak beni, yan ...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina_akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU', 'su-cahit-zari-foglu-azmax', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1.
Taşlanan kadınlar yankır
Girdap duvarda ve sırları çözük aynalar
Bir aynanın civarda hayvan otlağındaki benzeri
Yüzler kuyuya inen gözü terkeder
Sıcaktır örfe yaklaşır
Kavalsız ve çılgınca döner kaderine bir kez daha bakar
Açlığa üşümeye kartalın alnında duran yıldıza
Bir kere daha daha yalnızlığa
Kati ve aşk geçerliğini ortaya koyarak
Ulusal ve benci iki çingene arasında
Bir kere daha yalnızlığa
Atılarak
Yerin içinde yüzlerle hücum
Bütün özentili yekinmelere doğru karşı
Bütün nedensiz gençliklere doğru karşı
Aç olan karın
Soylu olan yoksulluk
Ve mızrakla gelen alın
Yerin gezisinde insan vardır
Ağulu bir diş put taşında
Doğacak çocukların toplandığı çadır taşında
Ava çıkmıştır
Aşk tunç çekmiştir bizle olan sırtına
Birbirini çaresiz bırakan çehrelerin
Yaralı ceylanı bulup tepindiği
(Fırat birdenbire kaybolur bir mağarada)
sevenin kurbanla alınıp kurbanla ödendiği
güneşin aşktan sudan ve topraktan
daha hızlı yöneldiği
raskolnikof
müthiş bir iman ağrısı çekmektedir.
Güvercinler toplandı sofralar kuruldu
Ağaçlar bahçede kızgın güneşle çatıldı
Elma tadları ağır ayrılık tadları
Yalnızlıkla toprağa savruldu
Katerin açık kollarıyla yaklaştı üç tuzaklı odalarıyla
Mükemmel bir karpuza yaslanmak
Suya çağrılmak
Bir de içindeki ziynetleri hor görmek iyice
Oysa güneş ağırlaşsın siyah saçımız uzayan başımızda
Alnımızın dibinde kalsın seçkin ve Horasanı kayıran gözlerimiz
Hiç akla gelmedi
Bereber kırları hüznü atmaya yarayan bir annenin
Dallara takılıp ağrıyan yaralarıyla yattığı
Gerçekten canlı göğsü boğucu çaylarıyla
Akşam suyundan bir sütun mermer içmiş
Her erkeğe bir yılan üfürmüş
2.
Ciğerlerde ölüm akar
Çeşme
İnsan hesapsız çocuk üfürük
Kendinde olmayan gürz kapanan ayna
Mektep taze ekmek dilimi zeytinin içindeki bağırgan
Ölüm
Sıkışmış aramıza
Sandalyenin dibinde mi
Dudak sıcak çay bardağına kapanırken
Salıncak onunla içten içe anlaşma
Cevizin ipi tutan çocuğu kayıran dallarında
Yeşil yaprakta veba
Ölüm evin hangi bilinmezinde ya da açıkça
Küçük kardeşin avucunda mı
Uzak insan sahillerine
Kelimeyi dolanan dillere
Taşıdılar zeytin
Kahvaltı ve zeytin
Sofrada üç büyük zeytin üç kanlı bakış
Ölünün ağzına zeytin kondu
Şiş dudakların arasına
Sonra geniş omuz yaralarında
Adamlar kırılan camlar taktılar
3.
İnanç yiğit ev sorardı bulup konaklardı
Kanlı göz ufuk tarardı
Cürümlü başta her geyik akışında
Örtülür dudaklar çünkü kalble çarpılırlar
El gezer tenhaları dolanır ufak tüyler
Ve tüyler ki ateşle diklenirler
Kendi namlarına ağemen olarak
Üşüme kabarcıkları tad kabarcıkları
Ürpermelerle unutkanlık
Yerin bir zaferle doğrulması cürme katık olarak
Dantel kalb vurması su kapları
Islak naylon örtü ve ıslak cimrilikle
Ustalıkla yaprağa ilave peçete
Yorgun ve evvelden haber
Sonra saralar
Sıradadırlar
Kapılar baskıyla kapalıdır
Onlar yontup hamam kapılarını
Kulaklara ses kutuları
Ormanlar avazlarıyla parke taşlar
Kurtlar
Yıldırım
Avizeler
Orada köşelere düşler yerleşir yatakları kollar
Uyku canavar kıvrımlı batarlı saldırır
Ev tilkiyle sarılır kuşatılır
Yorgun bir masal uzakta kaybolur
Kulaklarına yosun ve balık biriken çocuklar
Toprağın rengine katılan
Hızla yorgana atılan
Göğsümüze sırtımıza ateş bastıran
Örtünen çıldıran çocuklar
La onlarla alev açıyor her yanımız
Anlaşalım
4.
Denizde büyüyen av hayvanı
Suları derin denizleri boyayan mürekkep hayvanı
Uzatır gözlerini ince çalgılar içinde savaşlarla
Tiz sesli yuvarlak ağızlarıyla
Bu kez bu alçıyı donduranla
Kapalı denizlere kapılıp açık okyanusta
Kayalardan inen hızlı koşan bağırlar
Ayakta durlar
KALK lar
Oturun babamı
Ben güvercin saçlı çocuktum
Buzlardan başlayıp vurdular
Dağların yabani timsahında
Sanatın fiziksel geçerliğine kadar
Vurdular
Babam upuzun yatandı kumda
Ölü ve uzaması birden duran saçlarıyla
Çünkü öylesine kendi ölümü
Başını yastıklardan kaçıran uykulu başını cümle odalardan
Hep kumlar vardı çünkü uykuya yaklaşırken
Üzülecek ve sevinç duyacak yerlerde
Dudakların içinde kulak yollarında
Adamın öldürülüş sesi
Sofradan sokak kapısından
Pencereden kumluğa okyanusa
Ahrete olan dostluğumuza yakınlığımıza', '1. Taşlanan kadınlar yankır Girdap duvarda ve sırları çözük aynalar Bir aynanın civarda hayvan otlağındaki benzeri Yüzler kuyuya inen gözü t...', ARRAY['Türk Edebiyatı','Şiir','Cahit Zari̇foğlu']::text[], 8.5, '{"poet":"Cahit Zari̇foğlu","poet_slug":"cahit_zarifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":136}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUDA YİTEN AYIŞIĞI', 'suda-yi-ten-ayisigi-nihat-behram-wsncd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kırk sevginin baygınıyım
- belki de yüzkırk -
yine de yalnızlık yalazlanır kırık kalbimde
Otların tutuklusu
haylazı ağzım
şimdi tutlusu kara suların.
Her şeye yeniden başlayabilseydim eğer
aşkımı acıyla anmazdım artık.
Ben ki delisiyim suların, oysa bu sular
çöl rüzgarı kadar bulanık.
Akar gibi geçiyorum dünyadan, ısınıp bakınmadan,
sarhoş
sıkılgan
sırılsıklam...
Kırk diyarda kırkbin öpüşün bitkiniyim
dudağında kırkbin kekik tadı kamaşır
yine de kalbim ısırgan mı ısırgan.
Eşini çağlayana kaptırmış balığıyım bu nehrin;
aydır, geceden beri dişlenmiş kelebeğin
her sabah ağzımda ölümüyle buluşan.
Nihat', 'Kırk sevginin baygınıyım - belki de yüzkırk - yine de yalnızlık yalazlanır kırık kalbimde Otların tutuklusu haylazı ağzım şimdi tutlusu kara...', ARRAY['Türk Edebiyatı','Şiir','Nihat
behram']::text[], 8.5, '{"poet":"Nihat\nbehram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUDA', 'suda-can-yucel-ca0jw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çift yaprakmış dalında yumuşacık,
Tutmuşum tutmuşum ellerinden senin;
Düşmüşüz yavaşça bir sâkin derenin
İçindeymişik, yeşilmişik, sazmışık.
Balıklar gibiymiş, sessiz ve karanlık,
Yüzermiş saçların, yüzermiş nefesin;
Susarmışız öyle, bir sâkin derenin
İçindeymişik, yeşilmişik, sazmışık.', 'Bir çift yaprakmış dalında yumuşacık, Tutmuşum tutmuşum ellerinden senin; Düşmüşüz yavaşça bir sâkin derenin İçindeymişik, yeşilmişik, sazmı...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUDAKİ ANKÂ', 'sudaki-ank-tugrul-tanyol-sgg8k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '"biz bülbül-i muhrikde mi gülzâr-ı fırâkız
âteş kesilir geçse sabâ gülşenimizden"
II. Selim
özlemin soğuk kışı, ırmağa karışan arzu
dallarda, üşüyen kanatlarından soyunmuş
sudaki billuru düşleyen ankâ
seslerimiz seslerimizi arıyor uzaklarda
ardımızda uzanan yollarda unuttuğumuz
kayıklar dolusu altın şarkı, mücevher, akik
ve kehribar ırmağın usulca yüzdürdüğü
eski bir şarabı taşıran esrik anılar
bahçelerden akardı ince bir kanûn renginde
güller ve güllere sürtünüp tutuşan rüzgâr
ağaç yağmurun biçimini alırdı uzaktan baksak yanılırdık
günlerin karaya çıktığı yerde dururdun
sıcak falında izlerin ve kumun
bir ses bir sese yansıtırdı pırıltısını
bir dağ bir dağı gölgelerdi ve o ıssız sürünün
tozları dağılınca başlardı gün
uzayıp giderdi yollar boyunca
ağacın ağaca fısıldadığı sürgün
zaman sesini yükseltiyor şimdi seyrelmiş otların arasından
kıyıya yanaşan kayıklardan iniyor
kalabalık, gölgesini ardında bırakıp
usulca bir imgeye dönüşüyor
ırmağın buzları erirken ötelerde
son kez dönüp bak, geride bıraktığın izleri topluyor çocuklar
eski bir evden, zümrüt bir kuleden
sevdiğimiz ve unuttuğumuz kadınların sözlerini uçuruyor rüzgâr
yaşamın acısı geçmiş buradan bir iz gibi sürüp toprağı
geçtik biz de çatısında binlerce ses çınlayan o ıssız geceden
karşılamak için seni: bilinmeyeni
artık susmalıyız, konuşsak bile
bizim acımızı kim anlayabilir
sen, sudaki rengine külünü savuran ankâ
ırmak akıp gitti, çoktan
küllerimiz küllerimizi arıyor hâlâ', '"biz bülbül-i muhrikde mi gülzâr-ı fırâkız âteş kesilir geçse sabâ gülşenimizden" II. Selim özlemin soğuk kışı, ırmağa karışan arzu dallarda...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul  Tanyol']::text[], 8.5, '{"poet":"Tuğrul  Tanyol","poet_slug":"tugrul_tanyol","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SULARDA GÜNEŞ OLMAK', 'sularda-gunes-olmak-rifat-ilgaz-c37u4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I
Kıyıda kum çakıl yosun. Gidenlerden
Boşuna değil martıların hırçınlığı
Köprülerin altından geçen sular var ya
Kürsülerde lâfını ettiğimiz
Biraz da köprülerin üstünden akmalı
II
Yeşilin sarıya dönüşü korkutmasın seni
Morarıp silinmesi maviliklerin
Kırmızının akıp gitmesi damarlarından
İşimiz kolay değil o denli
Kargaların içgüdüsel ölmezliğine inat
İnsanca ölebilmeli
III
Ne ilkyaz bulutlarında yıkanan
Bir mezar taşısın uzun ömürlü
Ne kış güneşinde silkinen selvisin
Bir mezarlık değilsin anıların gömüldüğü
Yeşilin bitkiselliğini sürdürmeye gelmedin
IV
En güzel sarılarda düşsel
Bir ayçiçeği güneşte tek başına
Bir de karanlık sularda güneş olmak
Bu daha güzel
Güvercinim Uyur mu adlı şiir kitabından 1974
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'I Kıyıda kum çakıl yosun. Gidenlerden Boşuna değil martıların hırçınlığı Köprülerin altından geçen sular var ya Kürsülerde lâfını ettiğimiz ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SULARDAN ÜRKÜ', 'sulardan-urku-turgut-uyar-bugai', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'suların çoğaltığı seslerden ürküyorum
yorgunluk veriyor ürkü¹
alacakaranlık gibi anlamsız bir şey
bir çoban kepeneği gibi ya da
gelip çakılıyor aklıma
sonra hiç bir şeye benzemiyor
bir saat iki saat üç saat gibi şeyler oluyor
ama
hiç bir şeye benzemiyor
tutturduğum türkü
nedendir bilmem
Edip le söylediğimiz zaman
oluyordu halbuki
_______________
¹ türkü ye kafiye aradığımı sandınız,yanıldınız!', 'suların çoğaltığı seslerden ürküyorum yorgunluk veriyor ürkü¹ alacakaranlık gibi anlamsız bir şey bir çoban kepeneği gibi ya da gelip çakılı...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SULARIN DURULDUĞU YERDE YALNIZ ASKERLER', 'sularin-duruldugu-yerde-yalniz-askerler-oktay-taftali-7fknr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gamze Ongan için
gecenin bir ağır kalkışı vardır, umutları üstüne
&quot;açıl ey ömrümün varı açıl&quot;
haziranda bir gece durulsun için sular
duru sular gecenin en ağır umutları
hani unuttum sanırdın postal bağlamayı, palet şakırtısını
ve askeri ilimlere olan eğilimini gönlümün,
ki bıçkın ve delikanlı sen
savaşsız yapamazdın
görüldüğün yerde durulurdu sular
sen, duru suların barbar ve hüzünlü kurmayı
bakakalırdı gurbet elleri
yüreğinde atılırken 105''lik mermiler
bugün kederli ve çok öfkeliyim
elimde ahir zaman savaşları haritası
şans tanımıyorum sarışın kavimlere
ve münzevi bir sevgi olarak sen
hiç bilmeyeceksin, o ağacın yanında niye duruyorum
ancak eğer terk etmezsen bizi bu haziranda
söz verebilirim
herkesin en uygunsuz gördüğü bir zamanda
inançsızlık ve korkuya bir avuç barut değişeceğim
dili tutulacak parayı ve silahı tedavüle koyan bir yahudinin
ve görüldüğü yerde durulacak sular
birçokları dolaşırken ortalıkta sivil ve yavşak
ince sanatkârların tavrıyla ağır bir işçilik olarak
bir dülger, bir cam ustası
veya patetik bir asker cesaretiyle basılacak
bu dünyadaki en beter harami zulası, senin evin...
gecenin bir ağır kalkışı vardır, umutların üstüne
&quot;açıl ey ömrümün varı, has bahçenin gonca gülü&quot; ulan açıl
ve sanma ki bu söylediklerim birer lejyon hatırası
yalnızca gurbetteyiz dedim
burası ne çad, ne zengibar, ne de fransız guyanası
haziranda sana asker doğmuş çocuklar armağan edeceğim
hepsi pala ve gürbüz
hepsi paramiliter
yoksa benden geriye ne kalırdı öfkenin anlamında
ben duru suların
barbar ve hüzünlü kurmayı', 'Gamze Ongan için gecenin bir ağır kalkışı vardır, umutları üstüne &quot;açıl ey ömrümün varı açıl&quot; haziranda bir gece durulsun için sul...', ARRAY['Türk Edebiyatı','Şiir','Oktay Taftali']::text[], 8.5, '{"poet":"Oktay Taftali","poet_slug":"oktay_taftali","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SULTAN-I YEGÂH', 'sultan-i-yeg-h-attila-i-lhan-hg9wz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şamdanları donanınca eski zaman sevdalarının
başlar ay doğarken saltanatı sultan-ı yegâhın
nemli yumuşaklığı tende denizden gelen âhın
gizemli kanatları ruhta ölüm karanlığının
başlar ay doğarken saltanatı sultan-ı yegâhın
yansıyan yaslı gülüşmelerdir karasevdalı suda
bülbüller kırılır umutsuzluktan yalnızlık korusunda
eylem dağılmış gönül tenha çalgılar kış uykusunda
ölümün tartışılmazlığı nihayet anlaşılsa da
başlar ay doğarken saltanatı sultan-ı yegâhın
bir başkasının yaşantısıdır dönüp arkamıza baksak
çünkü yaşadıklarımız başkasının yargısına tutsak
su yasak rüzgâr yasak açık kapılar yasak
belki bu karanlıkta yasakları yasaklasak
başlar ay doğarken saltanatı sultan-ı yegâhın', 'şamdanları donanınca eski zaman sevdalarının başlar ay doğarken saltanatı sultan-ı yegâhın nemli yumuşaklığı tende denizden gelen âhın gizem...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUNİ DENGE', 'suni-denge-oktay-taftali-gfw7m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatla ilgisi insanın
yaşını vurur yüzüne
her ölümün ardından bir mutluluk dengeler hayatı
zaman en doğru soyutlamadır
ve ölüm en bireysel olanı
sen âlemlerin delikanlı şairi
sahi sen dahil
herkes bir gün yetim kalır
ve tersine dengeler hayatını', 'Hayatla ilgisi insanın yaşını vurur yüzüne her ölümün ardından bir mutluluk dengeler hayatı zaman en doğru soyutlamadır ve ölüm en bireysel ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Taftali']::text[], 8.5, '{"poet":"Oktay Taftali","poet_slug":"oktay_taftali","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUNU', 'sunu-ahmet-telli-hy3q4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Filler mezarlığında fil ölüleri
Ve belki birkaç da şiir bulursunuz
Ki o şiirler kendi ölümlerini sezen
Birer kuğuydular kuytu sularda', 'Filler mezarlığında fil ölüleri Ve belki birkaç da şiir bulursunuz Ki o şiirler kendi ölümlerini sezen Birer kuğuydular kuytu sularda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli̇']::text[], 8.5, '{"poet":"Ahmet Telli̇","poet_slug":"ahmet_telli","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SU''RE', 'su-re-altay-omer-erdogan-tcfa6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'su hangi kanı yıkayan temiz akıcı boşlukta
hangi aynaya baksam kırık sahibi sözsüz su
yara da kapanmayacak çirkinim hep konuşkan
tutsam bir kent düellosu ucundan hem unutkan
su tarihi ve kibri arıtan sabırdan saraylar kadar
kendini ve aşkını ilkel kavimlerde arar su
tutkunum sarhoşum kıyasıya kaybolmuşum tenimde
hem kendimden başkayım hem kendime
civar adresler eskiten majiskül adımların
eskici yalnızlığıyla yalayan hurda sokakları
kendini kendinden soran takvimlerden ödünç
kimsesiz bir aşkın kimsesi olmak istiyorum!
su zamane bahaneler provası isteğin kıyısında
neye dokunsam bir ihtilâlin ilksözü su
yüzün tüm çağlara utangaç bir pusula hüznü
hüzün kırsal bir gelgit çizgisi kaçıran yüzünü
su sahici ve gururlu okşayan yollar gibi
arar gurbette ve sılada kendini su
yok aldanmanın hakkı susmaksa hiç
hem ayrımsız olana hem aykırıya
(Evrensel Kültür, Kasım 1995; Kent Düellosu, 1996)', 'su hangi kanı yıkayan temiz akıcı boşlukta hangi aynaya baksam kırık sahibi sözsüz su yara da kapanmayacak çirkinim hep konuşkan tutsam bir ...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SURET', 'suret-yucel-kayiran-7tcxz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dil kapalıydı kendimi ifade için
sözden yazıya döndüm
rüyama giren hayale ruhumdan
bir tüneli kazmak için
kendimi içimdeki mağaraya aldım
Sol kapalıydı hayallerime firar için
batıdan sağa söndüm
zamanın ufunetinden çocukluğuma
giden bir otobüs için
kendime bir bilet aldım
Suretim kapalıydı ruhuma ten için
kendime giden uzaklığa döndüm
içime, mağaraya, oradaki hayale
indim, çünkü indikçe
yaklaşıyor her ruh kendi suretine
[Hayaline Firar Edemeyenlerin Afsunu]', 'Dil kapalıydı kendimi ifade için sözden yazıya döndüm rüyama giren hayale ruhumdan bir tüneli kazmak için kendimi içimdeki mağaraya aldım So...', ARRAY['Türk Edebiyatı','Şiir','Yücel  Kayiran']::text[], 8.5, '{"poet":"Yücel  Kayiran","poet_slug":"yucel_kayiran","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSAMAK ÖZGÜRLÜĞE', 'susamak-ozgurluge-philip-larkin-gk402', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık ayrılmak gerek, sevdiğim; ne yıkıcı,
Ne de acı gelsin bu bize. Eskiden
Pek çok ay ışığı vardı, pek çok kendimize acıma;
Bitirelim bunu burda; çünkü gün
Hiç böyle yiğitçe dolaşmadı gökyüzünde,
Yürekler hiç böyle susamadı özgürlüğe,
Dünyaları yıkmaya, ormanları yakmaya.
Tutamayız bunları, biz şimdi kabuklar gibiyiz
Tohumların büyüdüğünü gören bir başka iyiliğe.
Böyle olmasaydı, diyeceğiz; böyle söylenir hep.
Ama çözülsün daha iyi yaşamlarımız birbirinden,
Kendini rüzgârlara bırakmış, ışıklarla ıslak,
Rotaları çizili iki koca gemi, nasıl kopup
Uzaklaşırlarsa el sallayıp bir limandan,
El sallayıp nasıl kaybolurlarsa gözden.
Philip  LARKIN', 'Artık ayrılmak gerek, sevdiğim; ne yıkıcı, Ne de acı gelsin bu bize. Eskiden Pek çok ay ışığı vardı, pek çok kendimize acıma; Bitirelim bunu...', ARRAY['Türk Edebiyatı','Şiir','Philip  Larkin']::text[], 8.5, '{"poet":"Philip  Larkin","poet_slug":"philip_larkin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSARAK', 'susarak-aziz-nesi-n-d1p9e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneş altında söylenmedik söz yokmuş..
Bu yüzden geceleri söylüyorum sevdiğimi..
Ne gece ne gündüz yokmuş söylenmemiş söz..
Bende söylenmişleri söylüyorum yeni biçimde..
Hiç bir biçim kalmamış dünyada denenmedik...
Bende susuyorum sevgimi saklayıp içimde....
Duyuyorsun değilmi suskunluğumu nasıl haykırıyor...
Susarak sevgisini ilan eden çok var sevgilim ...
Ama bir başka seven yok benim sustuğum biçimde .....', 'Güneş altında söylenmedik söz yokmuş.. Bu yüzden geceleri söylüyorum sevdiğimi.. Ne gece ne gündüz yokmuş söylenmemiş söz.. Bende söylenmişl...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSKUN', 'suskun-a-hicri-i-zgoren-qcjl8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Susardın ve kar yağardı
Gözlerinde başlardı gece
Yarım kalmış kitaplarda biterdi.
Alnımızda bilenen kör bir bıçaktı zaman
Kırılmış aynalardı
Susardın, durmadan susardın
Ve kar yağardı
Ocak ağaran saçlarımdı
Şubat hayırsız bir evlattı, kaçaktı
Ve uzaktı yaz bir anaydı
Mart''ın izlerini taşırım bedenimde
Aynı masalın ikizleri gibiydi günler
Nisan saçlarımda ıslanırdı hep
Susardın, durmadan susardın
Ve yağmurlar başlardı
Çok bekletti bizi,
Hiç vaktinde gelmedi mayıs
Haziran Aram''dı ya da öyle biriydi
Temmuz bir düştü belki
Yaraları sarar gibiydi
Ağustos yıldızlarla basardı gecemizi
Bir gül suçüstü yakalanırdı
Eylül bir çocuğun çığlıklarıydı
Susardın, durmadan susardın
Ve rüzgârlar başlardı
Yolunu yitirmiş bir gezgin gibiydi ekim
Sürgünlere uğurlardık kendimizi
Kalan mı bizdik, giden mi
Bilinmezdi
Kasım rüzgârda bir yapraktı
Ve biraz ıtri
Kendi sesiyle irkilirdi
Aralık günlerin son neferi
Soluk bir düş geçse de
Hiçbir mevsim gözlerin kadar
Acımasız kullanmadı neşteri
Susardın ve kar yağardı', 'Susardın ve kar yağardı Gözlerinde başlardı gece Yarım kalmış kitaplarda biterdi. Alnımızda bilenen kör bir bıçaktı zaman Kırılmış aynalardı...', ARRAY['Türk Edebiyatı','Şiir','A. Hicri İzgören']::text[], 8.5, '{"poet":"A. Hicri İzgören","poet_slug":"a_hicri_izgoren","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSTURULMUŞ ŞARKI', 'susturulmus-sarki-yusuf-altunel-8vthg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bulutlansa da gözlerini ayırma benden
bırak resmini çizeyim
sesinle besle türkümü
nefesini taşımak için
uzak ülkelere gideyim
avuntularını kat gülüşlerime
dudaklarında menevişler işleyeyim
baharı yaprak yaprak taşı göğüslerinde
teninde karanfil öpüşler çiçeklendireyim
göç mevsiminde yanımda kal
çilekler iliştirip zülüflerine
ışıklar dökeyim
bulutlanıncaya kadar gözlerini ayırma benden
bırak
''mutluluğun resmini'' çizeyim
çocuksu gülücükler mevsiminde ayaklanıp
akarsu çağıltısında beslenmiş narin sevinçler dereyim', 'bulutlansa da gözlerini ayırma benden bırak resmini çizeyim sesinle besle türkümü nefesini taşımak için uzak ülkelere gideyim avuntularını k...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSUZLUK', 'susuzluk-tali-p-apaydin-evfh7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Susadım
Bozkırlar ortasında
Kurudu dudaklarım
Çağırmayın gelemem
Bir tas su uzatın
Çabuk olun biraz
Beni kurtarın', 'Susadım Bozkırlar ortasında Kurudu dudaklarım Çağırmayın gelemem Bir tas su uzatın Çabuk olun biraz Beni kurtarın...', ARRAY['Türk Edebiyatı','Şiir','Tali̇p Apaydin']::text[], 8.5, '{"poet":"Tali̇p Apaydin","poet_slug":"talip_apaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUYU BEKLEYECEĞİM', 'suyu-bekleyecegi-m-zubeyir-kindira-guupk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ardıç kuşu
Düşmeyeceğim peşine
Gölgeler kendi kuyusuna düşsün
Cellat kemendinin mezarına
Ben suyu bekleyeceğim
Gözleriniz iki ateş köpüğüyken geceye
Cellat kemendi yanıbaşınızda
Siz uyurdunuz
Ben şiir yazardım', 'Ardıç kuşu Düşmeyeceğim peşine Gölgeler kendi kuyusuna düşsün Cellat kemendinin mezarına Ben suyu bekleyeceğim Gözleriniz iki ateş köpüğüyke...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Kindira']::text[], 8.5, '{"poet":"Zübeyir Kindira","poet_slug":"zubeyir_kindira","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUYU ŞİİR BİLDİM SUSUZLUĞU AŞK', 'suyu-si-i-r-bi-ldi-m-susuzlugu-ask-azad-ziya-eren-0u96n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sesinin kokusu var
şiir parlatan ince parmakları
gerekçeli bir rüzgârın
tende belâgat burcusu
dünyayı hep unuttum
bütün dillerini yuvarlanmış karanın
suyu şiir bildim susuzluğu aşk
nedensiz bir terk edişti suya aşınmak
eskiciye devredilen kullanılmış ırmak
kirpik gibi kardeş gibi
sessizce döküldükçe göğsüne ormanın
anneyi yakan uzun esmerlikti
sesinin kokusu var
kalbimi titreten mahcup itibarı
boşluğu hep unuttum
içimde büyüyen sökülme arzusunu
sadakati şiir bildim
sadakatsizliği kâğıda dağılmayan mürekkep
dönüşsüz bir yolculuktu suya göçmek
kerpiç evde kavlayan kimsesizlik
dem gibi kuytuluk çöl gibi
büyüdükçe ayak dibinde sıtmalı çocuğun
babayı yıkan ıslak suskunluktu
sesinin kokusu var
sağdığım her gülün yanaklarında
benzersiz gümbürtüsü
gülü şiir bildim
gülsüzlüğü gücünü yitirmiş en elzem sihir
böyle de güzelsin yok/su dil..!
sadakatsizliği kâğıda dağılmayan mürekkep', 'sesinin kokusu var şiir parlatan ince parmakları gerekçeli bir rüzgârın tende belâgat burcusu dünyayı hep unuttum bütün dillerini yuvarlanmı...', ARRAY['Türk Edebiyatı','Şiir','Azad Ziya Eren']::text[], 8.5, '{"poet":"Azad Ziya Eren","poet_slug":"azad_ziya_eren","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUYUN BİLGE YÜZÜNDE', 'suyun-bi-lge-yuzunde-altay-omer-erdogan-r9okh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hiç anlaşılmamış olan hiç anlatılmamıştır
bir maşrapadan dökülmemiştir su, yalvaran köküne inancın,
dönülmemiştir hiç gidilmemiş olan yerlerin serinliğinden
hep yaşamaya tutsak olunmuş cehennemin sıcaklığına,
toprağı delip yeryüzüne, yeryüzündeki yüzüne sığınan
kentli bir derviştir olsa olsa zaman,
evleri kesik kesik çizgiler gibi boş kağıtlara
boş kağıtları yanıtsız sorular gibi kesif mutluluklara
çıkaran hangi dar sokaklar ki, yıkanır günlerin köpüğünden
gecelerin kentsoylu bir havluyla kurulanmışlığına
hangi bizim sokaklar
bizim tuzlu yalnızlıklarımızdır her şiirin biraz biraz soluduğu
ve bizim biraz biraz solduğumuz takvim yapraklarıdır
kör kaldırımlara dökülen güzün herkese kardeş olduğu
yollarla ölçülür, darası zaman olan her tutku
yıllarla biçilir, tutkusu zaman olan her daralmışlık
içimdeki ırmağın ılık ılık aktığı
ve gözlerinde dünyalar büyüyen taşralı çocukların
o ırmaktan uçsuz denizlere baktığı
sırasız sırsız bekleyişleri en güzel yolculukların
uzar, uzadıkça yeni bir dünya avuçlarından taşar
kırılır, en ince yeri, en dokunulmamış olanı
rüzgârın bile okşamaktan korktuğu
hangi eşsiz sözcük ki, en dokunaklı anlatır talanı
bilinemezlik denklemlerinde eskir yüzü
zaman, kenti apansız adımlayan eskici
çıkar bir umudun körpe bohçasından
sarılır ilk öptüğü boynun sıcaklığına sahici
kirlenmeyen bir nesne olsun
yitirdikçe anlamını bir sonrakine devşiren
gururla okunsun sözcük, övünürken eklendiği tümcede
varsın hiç olmasın, koparmasın gülüşlerimizi yüzümüzden
hiç anlatılmamış olan hiç anlaşılmamıştır
(Agora Temmuz-Ağustos 2001; Taş(ra) Baskısı, 2003)', 'hiç anlaşılmamış olan hiç anlatılmamıştır bir maşrapadan dökülmemiştir su, yalvaran köküne inancın, dönülmemiştir hiç gidilmemiş olan yerler...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİVİL AŞK YOKTUR', 'si-vi-l-ask-yoktur-oktay-taftali-xsr9e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu kentte senin yaşadığını bilmedim
ne temizlikçi kadın söz etti, ne bekâr odam
böyle giderse de bilmeyeceğim
ne zeytin bahçesi gördüm burada
ne doğru bir hüzün ne sahici bir yalan
ben bu kenti terk edeceğim
çok acı olacak hava
belki yine sis ve duman
belki de veba
ölümüne olacak bu işler
alçakgönüllü şairlerin ağzında deli bir gül gibi patlayacak
bir avuç kan
kan akacak kanallardan
ben gidince
ellerindeki yaraların izlerini silemeyeceğim
rüzgâr kokusu yitecek saçlarında kıran
camlara vereceksin kendini
ben bilemeyeceğim
sivil aşk yoktur diyeceksin
hep terör hep kavga
hep yağma ile geçti ömrüm
en son bu kentte aşk şiiri denedim
baktım hâlâ utanıyorum
bu kentte senin yaşadığını bilmedim yıllarca
şimdi geçti mi zaman
şimdi yine &quot;bahar yorgunluğu&quot;
yine sis ve duman', 'Bu kentte senin yaşadığını bilmedim ne temizlikçi kadın söz etti, ne bekâr odam böyle giderse de bilmeyeceğim ne zeytin bahçesi gördüm burad...', ARRAY['Türk Edebiyatı','Şiir','Oktay Taftali']::text[], 8.5, '{"poet":"Oktay Taftali","poet_slug":"oktay_taftali","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÜVÂRÎ', 'suv-r-ahmet-hasi-m-a6df8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu bakır zirvelerin ardından
Bir süvârî geliyor kan rengi.
Başlıyor şimdi melûl akşamda
Son ışıklarla bulutlar cengi!
Bir bakır tasta alev şimdi havuz,
Suya saplandı kızıl mızraklar.
Açılıp kıvrılarak göklerde
Uçuyor parçalanan bayraklar!', 'Şu bakır zirvelerin ardından Bir süvârî geliyor kan rengi. Başlıyor şimdi melûl akşamda Son ışıklarla bulutlar cengi! Bir bakır tasta alev ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖYLE GÖKYÜZÜ', 'soyle-gokyuzu-ali-cengi-zkan-ylex4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acıyı kim neyler
Neyler kasabayı şehirli düşünceler,
Acı, yığından bir tel çeker gibi
Kayıp gider götürerek kendi nedenlerini.
Aşktır, acıyı kim neyler
Peçe altında gezer sevişerekten,
Ben çok gördüm çok gezdim çok sevdim
Gönlümde sen olan kuyuyu bildim.
Gönlünde kuyuyla acıyı kim neyler
Süzersin acıyı gövdende bırakarak,
Tortu atılmaz, yanık onmaz, toz yunmaz
Çıkrık çalışır bir eğlentiyle.
Kuyu kalır çölde bir olanak olarak
Yer altı sularını birleştirir gibi
Acı, katmandan katmana kuyudan kuyuya
Gelenek olur ve alışkanlık yaratır.
Çıkrığın gıcırtısı müzik gibi inler
Kova deliktir lafolsun diye işte,
Eskil bakışların tirşesi yeter
Aşktır, söyle, acıyı kim neyler?
Ankara, 4 Ocak 1994', 'Acıyı kim neyler Neyler kasabayı şehirli düşünceler, Acı, yığından bir tel çeker gibi Kayıp gider götürerek kendi nedenlerini. Aşktır, acıyı...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖYLE YÜZÜM TANIĞIMSIN', 'soyle-yuzum-tanigimsin-ahmet-ozer-tz9gv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşk eskidi/yollar uzun
bir dalga kırıldı yüzümde
kar sesinde uçan çiçek
yüreğimde gülüşündür
sevgi bitmez/düş yaşatır.
bir gün olur gurbet başlar
saat durur/deniz biter
sesim aranır yılları
ömrümüz bir yangın yeri
çiçek solar/bulut kaynar.
söyle yüzüm/tanığımsın
kaç bahara göğüs gerdin
bir çocuğun sevincini
gidişini bir babanın
tarih yazar/dünya okur.
şiirim bir atardamar
yaşıyorum dizelerde
gömleğimde bin bir nakış
bir ağlama/uykuya dur
kuşlar gider/sonbahardır.', 'aşk eskidi/yollar uzun bir dalga kırıldı yüzümde kar sesinde uçan çiçek yüreğimde gülüşündür sevgi bitmez/düş yaşatır. bir gün olur gurbet b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖYLEŞİ', 'soylesi-charles-baudelaire-xm0t3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siz aydınlık, kızıl bir güz göğüsünüz,
Benimse içimde hüzün dalga dalgadır.
Ve üzgün dudaklarımın üstünden deniz
Çekilirken buruk anılar bırakır.
-Cansız göğsümde elin boşa dolanıyor;
Yaralı... ve sızlıyor dokunduğun o yer,
Kadınlar pençeleyip dişledi, kanıyor,
Arama, hayvanlar yüreğimi yedi.
Davul gibi gümleyen bir saray bu yürek,
Ayyaşların, canilerin hora teptiği!
-Tadıyor çıplak boynunu koku, yüzerek!..
Ey güzellik, ruhların çakıllı düveni!
Diyorsun, bu kanlı yürek yok olup bitsin,
Kalanı alev gözlerin yakıp kül etsin!
Charles  BAUDELAIRE', 'Siz aydınlık, kızıl bir güz göğüsünüz, Benimse içimde hüzün dalga dalgadır. Ve üzgün dudaklarımın üstünden deniz Çekilirken buruk anılar bır...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖYLENCELER (çok sesli sevgililerden çok sesler)', 'soylenceler-cok-sesli-sevgililerden-cok-sesler-i-smail-onat-pg54g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘sevgili’ numero 1
dedi ki:
ellerimi tut,
tut öylece
gözlerini
yüreğime akıt.
sıcakça, sımsıcak.
[konuşayım dediydim bir kere ve ilk kere uzun uzun]
dedim ki:
ellerimde hep eller
gözlerim,
zaten erimiş yüreklerde.
ama,
birisi de sensen eğer
dostluklarin selamcısı
cesur
korkaklığında karanlıklar hükmeden...
...tutarım ellerini senin de.
‘sevgili’ numero 2 öğrendi bunu
dedi ki:
saçlarımı okşa
üfür...
yavaşça enseme enseme
terim buz olmadıkça
tenim seninle
densizliğimde bunca zaman
karanlık korkaklığımda hüküm yiyen.
‘sevgili’ numero 3 heyecanlıydı, çok heyecanlı
dedi ki:
koş benimle rüzgâr yamaçlarda
peşimi bırakma sakın
ya da peşinde olduğumu
farketmeden uzaklaşma
ayağım
yerde değil artık.
bir başkası, bir öbür sevgili
dedi ki:
özlediğim içimde
sanki kendim o şehirde
uç benimle gidelim
ya dostlarım kalmamışsa
beni yalnız bırakma
şehrime küsmeyeyim.
çingene ruhlu sevgili ve de numarasız
dedi ki:
renkler cümbüş
çingeneler dans ediyor
beni bekle ben de dönerken
gözlerin izlesin
şarkıya katıl şakraklıkta
sesin
nağmeler getirsin.
küskün sevgili numero bilmemkaç
dedi ki:
yaram derin kan yok
hayat bensiz ben hayatsız
yaşam zevksiz onlar
yaşamsız varoldukça
kendi kendine karanlıkta
ışık söndüren bir mumsuz gibi.
ve ben kendi kendime
dedim ki:
saygıdan sözcükler
sevgiden destanlar...
dut yapraklarında tırtıllar
artık kelebek olsalar
uçsalar hafif hafif
rengârenk konsalar
günışığı yakmasa
mum hiç erimese
eller tutuşmaktan
terlemese
taşısak birşeyleri
birlikte biryerlere.
o ütopya ...
erişilmez...
erişilse...
[hepsi-ne- birden tek tek/ayrı ayrı, çok sesli -solo halinde-]
dedi ki: bekle(me)!
dedim ki: bekleme!', '‘sevgili’ numero 1 dedi ki: ellerimi tut, tut öylece gözlerini yüreğime akıt. sıcakça, sımsıcak. [konuşayım dediydim bir kere ve ilk kere uz...', ARRAY['Türk Edebiyatı','Şiir','İsmail Onat']::text[], 8.5, '{"poet":"İsmail Onat","poet_slug":"ismail_onat","theme":"Türk Şiiri","is_hero":false,"total_lines":82}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖYLEYECEK BİR ŞEY YOK', 'soyleyecek-bi-r-sey-yok-philip-larkin-20818', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uluslar için, ayrık otları denli cılız,
Göçebe kavimler için, kayaların arasında,
Kısa boylu, asık yüzlü kabilelere
Ve parke taşları gibi kenetli ailelere
Fabrika kentlerinde karanlık sabahlarda
Ağır ağır ölmektir yaşam.
Ve tüm ellerindeki
Yaratma ya da kutsama,
Sevgi ya da para ölçme yolları
Ağır ağır ölmek yollarıdır.
Mızrakla domuz avlayarak ya da
Garden parti vererek geçen gün,
Tanık iskemlesinde ya da
Doğum masasında saatler
Hep ağır ağır ilerler ölüme doğru.
Ve kimine bunu söylemek
Hiçbir şey demez, kimine de
Hiçbir şey bırakmaz söyleyecek.
Philip  LARKIN', 'Uluslar için, ayrık otları denli cılız, Göçebe kavimler için, kayaların arasında, Kısa boylu, asık yüzlü kabilelere Ve parke taşları gibi ke...', ARRAY['Türk Edebiyatı','Şiir','Philip  Larkin']::text[], 8.5, '{"poet":"Philip  Larkin","poet_slug":"philip_larkin","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİZ AŞK''TAN N''ANLARSINIZ BAYIM?', 'si-z-ask-tan-n-anlarsiniz-bayim-di-dem-madak-uzsyv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok şey öğrendim geçen üç yıl boyunca
Alt katında uyumayı bir ranzanın
Üst katında çocukluğum...
Kâğıttan gemiler yaptım kalbimden
Ki hiçbiri karşıya ulaşmazdı.
Aşk diyorsunuz,
limanı olanın aşkı olmaz ki bayım!
Allah''la samimi oldum geçen üç yıl boyunca
Havı dökülmüş yerlerine yüzümün
Büyük bir aşk yamadım
Hayır
Yüzüme nur inmedi, yüzüm nura indi bayım
Gözyaşlarım bitse tesbih tanelerim vardı
Tesbih tanelerim bitse gözyaşlarım...
Saydım, insanın doksan dokuz tane yalnızlığı vardı.
Aşk diyorsunuz ya
Ben istemenin Allahını bilirim bayım!
Çok şey öğrendim geçen üç yıl boyunca
Balkona yorgun çamaşırlar asmay
Ki uçlarından çile damlardı.
Güneşte nane kurutmayı
Ben acılarımın başını
evcimen telaşlarla okşadım bayım.
Bir pardösüm bile oldu içinde kaybolduğum.
İnsan kaybolmayı ister mi?
Ben işte istedim bayım.
Uzaklara gittim
Uzaklar sana gelmez, sen uzaklara gidersin
Uzaklar seni ister, bak uzaklar da aşktan anlar bayım!
Süt içtim acım hafiflesin diye
Çikolata yedim bir köşeye çekilip
Zehrimi alsın diye
Sizin hiç bilmediğiniz, bilmeyeceğiniz
İlahiler öğrendim.
Siz zehir nedir bilmezsiniz
Zehir aşkı bilir oysa bayım!
Ben işte miraç gecelerinde
Bir peygamberin kanatlarında teselli aradım,
Birlikte yere inebileceğim bir dost aradım,
Uyuyan ve acılı yüzünde kardeşimin
Bir şiir aradım.
Geçen üç yıl boyunca
Yüzü dövmeli kadınların yüzünde yüzümü aradım.
Ülkem olmayan ülkemi
Kayboluşumu aradım.
Bulmak o kadar kolay olmasa gerek diye düşünmüştüm.
Bir ters bir yüz kazaklar ördüm
Haroşa bir hayat bırakmak için.
Bırakmak o kadar kolay olmasa gerek diye düşünmüştüm.
Kimi gün öylesine yalnızdım
Derdimi annemin fotoğrafına anlattım.
Annem
Ki beyaz bir kadındır.
Ölüsünü şiirle yıkadım.
Bir gölgeyi sevmek ne demektir bilmezsiniz siz bayım
Öldüğü gece terliklerindeki izleri okşadım.
Çok şey öğrendim geçen üç yıl boyunca
Acının ortasında acısız olmayı,
Kalbim ucu kararmış bir tahta kaşık gibiydi bayım.
Kendimin ucunu kenar mahallelere taşıdım.
Aşk diyorsunuz ya,
İşte orda durun bayım
Islak unutulmuş bir taş bezi gibi kalakaldım
Kendimin ucunda
Öyle ıslak,
Öyle kötü kokan,
Yırtık ve perişan.
Siz aşkı ne bilirsiniz bayım
Aşkı aşk bilir yalnız!', 'Çok şey öğrendim geçen üç yıl boyunca Alt katında uyumayı bir ranzanın Üst katında çocukluğum... Kâğıttan gemiler yaptım kalbimden Ki hiçbir...', ARRAY['Türk Edebiyatı','Şiir','Di̇dem Madak']::text[], 8.5, '{"poet":"Di̇dem Madak","poet_slug":"didem_madak","theme":"Türk Şiiri","is_hero":false,"total_lines":71}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZ! DIŞARI ÇIKMA SAATİ', 'soz-disari-cikma-saati-sait-maden-y4m0x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söz! dışarı çıkma saati. Giyin üstünü.
Söz! dışarı çıkma saati. İşte gong.
Uçtu güneş-karga. Ateşte
ve taşta gong. Tutuşmuş çizmelerini
sıyırdı bir gölge ve bulutlara
astı kılıcını. Bu saat
dışarı çıkma saati. Giyin üstünü.
Söz! öfkeni giy bacağına. Al çividen
kırbacını. İşte hergünkü
biçimleri gizemli bir el
sildi göz önünden parıltısıyla. Artık
dışarı çıkma saati. İşte yollarda
aynı kalıba dökülmüş yüz ayak, aynı
ipe geçirilmiş yüz kol koşmada
günlük sofrasına zırvanın. Artık
dışarı çıkma saati. İşte yollarda
birbirini çiğneyip çığrışır sesler
çekirgeler gibi sıçrayıp... İşte
kızıl bir ipliğe gelişigüzel dizilmiş
gözler sallanıyor havada, amaçsız bir el
evden ev kor gezdirirken
ve yıkıntı ve çığlık ve kül... Alçalan kuyu
ve yükselen baca üstüne şimdi
kapanıyor büyük bir çene
ve çıplak ağacından günlük edimlerin, kimbilir,
kopup savruluyor kimlerin yüzü.
Söz! dışarı çıkma saati. Giyin üstünü.
Söz! giyin üstünü. Koy cebine
çıplak çeliğini hıncının.
Çiğne eski biçimleri bir bir ökçenle.
Resmini duvardan al aşağı tanrının. İndir
çağdaş yalvaçları çivilerinden. At
başını bir yana, gövdesini bir yana
bütün edebiyatın. Saat
dışarı çıkma saati. Fırla öfkenle
ölü yüzlerinden yapılma serin çarşaflar
üzerinde geviş getiren kente.
Söz! dışarı çıkma saati. Giyin üstünü.
Bir sarnıça sonsuz hunilerden akıyor akşam...
Akıyor akşam... Akıyor akşam ve alarm.
Kızıl dilleri dışarda lambalar koşuşuyor
alanlarda. Savuruyor ölü göğün kâğıtlarını
minareler. Ve rıhtımlara
ağır sandıklara boşaltıyor karanlığı
vinçler, ağır çatırtılarla... Alarm!...
Ve süzülüp indi çatılara son peygamberi
felâketin bir büyük karga.
Söz! dışarı çıkma saati. Giyin üstünü.', 'Söz! dışarı çıkma saati. Giyin üstünü. Söz! dışarı çıkma saati. İşte gong. Uçtu güneş-karga. Ateşte ve taşta gong. Tutuşmuş çizmelerini sıyı...', ARRAY['Türk Edebiyatı','Şiir','Sait Maden']::text[], 8.5, '{"poet":"Sait Maden","poet_slug":"sait_maden","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİZ NE GÜZELDİNİZ BENİMLE BİLEMEZSİNİZ', 'si-z-ne-guzeldi-ni-z-beni-mle-bi-lemezsi-ni-z-i-lhan-berk-1bzjd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siz ne güzeldiniz benimle bilemezsiniz
A harfinden bir çarşı güneşi yüzünüzde
Hèlene uyruklu bir rüzgârdınız her şiirde
Benimdi, Ronsard''ın bir ülkesiydi yeriniz.
Şimdi kim bilir İstanbul''sunuz değilsiniz
Bir f''diniz Önasya''larda o şey evlerde
Şimdi nasıl bir yalnızlık eser yüzünüzde
Uzun sular olur duymak gibi bir şeydiniz.
Şimdi h, şimdi M sesi ilk nasıl karanlık
İpek gibiydiniz iyisi mi anlatmamalı
Ben yokum ya yoksunuz bakın nasıl artık.
Şimdi bakın nasıl bir yalnızlık vuran benden
Şimdi şiirlerde benim yazdığım sıkıntı
Bayılırsınız bir rüzgâr oynatsam ülkemden.
Çivi Yazısı', 'Siz ne güzeldiniz benimle bilemezsiniz A harfinden bir çarşı güneşi yüzünüzde Hèlene uyruklu bir rüzgârdınız her şiirde Benimdi, Ronsard''ın ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZ', 'soz-aziz-nesi-n-oheyg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilirsiniz sözümde hep durmuşumdur duracağım
Sevgilime sözverdim ben yirmi yıl yaşayacağım
Düşmanlarım sevinmesin yirmi yıl sonra yok diye
Belli değil yirmi yıla ne zaman başlayacağım', 'Bilirsiniz sözümde hep durmuşumdur duracağım Sevgilime sözverdim ben yirmi yıl yaşayacağım Düşmanlarım sevinmesin yirmi yıl sonra yok diye B...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZCÜKLER ACIMIZI DOLDURMAYACAK', 'sozcukler-acimizi-doldurmayacak-bejan-matur-t5vhp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siyah örtüyle kapatılmış, ölme hazırlanan bir gelin gibi duran
masada, konuştum onlarla.
Yanımızdan bir şair hırsız gibi geçti. Sözün uçurduğu gövdesiyle.
Şairlere baktım. Hepsi bir gölgeyi dolaştırıyor.
Bir köpeği dolaştırır gibi.
Sözcükler acımızı doldurmayacak.
Casablanca/temmuz/2001', 'Siyah örtüyle kapatılmış, ölme hazırlanan bir gelin gibi duran masada, konuştum onlarla. Yanımızdan bir şair hırsız gibi geçti. Sözün uçurdu...', ARRAY['Türk Edebiyatı','Şiir','Bejan Matur']::text[], 8.5, '{"poet":"Bejan Matur","poet_slug":"bejan_matur","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZCÜKLER', 'sozcukler-roque-dalton-ncrzq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Som sözcükler istiyoruz
ki dirensin gecenin ortasına
dünyanın yeni rüzgârlarına
sözcükler doğar temellerden
sözcükler doğar bina temellerinden
kaya gibi sert
boyun eğmez sözcükler.
Sözcükler yetmez konuşmaya hazırlık için
bizim tez canlı dünyamızda
ama susuzluğun nedenlerini gösterir,
çığlık,
duyurur "Yeter!" diye açlığı
sömürünün karanlığına karışırken
öfkesinin ışığı.
Sözcükler istiyoruz uyanışın şarkısı için.
Türkçesi: Kenan HANOK', 'Som sözcükler istiyoruz ki dirensin gecenin ortasına dünyanın yeni rüzgârlarına sözcükler doğar temellerden sözcükler doğar bina temellerind...', ARRAY['Türk Edebiyatı','Şiir','Roque  Dalton']::text[], 8.5, '{"poet":"Roque  Dalton","poet_slug":"roque_dalton","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZCÜKLERİN KİMLİĞİ', 'sozcukleri-n-ki-mli-gi-metin-cengi-z-xqlli', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tam bu vakit kayığına biner aşk
Dalgalarıyla süslenip girer gönlüme
Gönderirim umutlarımı sevgiliye bir mektupla
Banaysa satır sonları kalır hüzünden, bir de dayanmak
Bir de, görüldülü mektupları yeniden okumak
Çiğdem tadıyla varır mektubum, yağmur öncesi
Kokusuyla, duygularının kuytu kıyılarına
Bilirim hangi acıları duyacağını, hangi sevinçleri
Çiftçilerin yorganlarını tarlalara serdiği
İnce ince tüttüğü zeytin ağaçlarının
Söyleşilerin tütün ve gülüşlerle derinleştiği
Geçmişin gelecekle birleştiği bir günde
Dalgalara dönüşür kimliği sözcüklerin
Eyleme taşınır umutlar, defterler
Kitaplar yaprakları açık kalır
Resimler oluşur zamanın köpüklerinde
Düşlerin düşlerimle birleşir kalır
Bir gezintidir bu görüldü mektuplarıyla
Zaman geçer geriye aykırı izler kalır
Ve yaşayacaklarımız sevgilim
Eskinin yerini alır', 'Tam bu vakit kayığına biner aşk Dalgalarıyla süslenip girer gönlüme Gönderirim umutlarımı sevgiliye bir mektupla Banaysa satır sonları kalır...', ARRAY['Türk Edebiyatı','Şiir','Metin Cengi̇z']::text[], 8.5, '{"poet":"Metin Cengi̇z","poet_slug":"metin_cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZDÜŞÜ METİNLER', 'sozdusu-meti-nler-ahmet-uysal-4ghqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ki bir sözdüşüydün
Ulaşan en eski aşklara
Kırık testimde biriken su
İlk yazılı taşı söylencemin
Sendin bulduğum büyü
Bozkır buğulu bedenimle
Tuzuna inandığım çöl kumu
Kuşlar uçurtan susuzluk
Yollar ayrımı yüreğim
Zaman dokuyan çıkrıktı
Dönen ışık hızıyla
Boşluğa düşen sarmal
Aşk ki bir sözdüşüdür
Çıkar en eski yazmalara', 'Sen ki bir sözdüşüydün Ulaşan en eski aşklara Kırık testimde biriken su İlk yazılı taşı söylencemin Sendin bulduğum büyü Bozkır buğulu beden...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZDE BİR ŞEYİN AĞARMIYOR', 'sozde-bi-r-seyi-n-agarmiyor-enes-ki-sevi-c-0pad5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün sözde güneşli
sen sözde neşeli
geçiyorsun sözde gören yok
herkes sözde güzel
herkes sözde rahat
herkes sözde çılgın
sen de sözde mutlu
sözde her yerde barış
sözde kuşlar özgür
sözde yarınlar elimizde
vicdan sözde tertemiz
sözde bunu güneş de biliyor
sözde yürek türkü söylüyor
sözde herkes herkesi düşünüyor
sözde herkes birbiriyle dost
sözde herkes düşünüyor
seni
ve dünyayı
ve sözde gün ağarıyor
ve sözde sen gülüyorsun
ve sözde hiçbir şeyin ağarmıyor
Enes KİŞEVİÇ', 'Gün sözde güneşli sen sözde neşeli geçiyorsun sözde gören yok herkes sözde güzel herkes sözde rahat herkes sözde çılgın sen de sözde mutlu s...', ARRAY['Türk Edebiyatı','Şiir','Enes Ki̇şevi̇ç']::text[], 8.5, '{"poet":"Enes Ki̇şevi̇ç","poet_slug":"enes_kisevic","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİZDEN SAKLI', 'si-zden-sakli-murathan-mungan-hluxe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gelmediniz, ben hep sizi bekledim
eksilen yanlarımla
sizden saklı eskidim
her şeyden önce aşk verilmiş bir sözdü benim için
gün, ay, saat, hafta; takvimişi zaman yani
Aldıkça dönemeçleri  değişmedi  hiçbir şey
yalnızca ufuklar yeniledim
Kaç  aşktan oluşmuş  bir şeydi aşk
her sevgiliyle biraz daha
biraz daha sizden saklı eskidim', 'gelmediniz, ben hep sizi bekledim eksilen yanlarımla sizden saklı eskidim her şeyden önce aşk verilmiş bir sözdü benim için gün, ay, saat, h...', ARRAY['Türk Edebiyatı','Şiir','Murathan Mungan']::text[], 8.5, '{"poet":"Murathan Mungan","poet_slug":"murathan_mungan","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİZDEN SONRA', 'si-zden-sonra-ahmet-ozer-igll2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'önümüzde sonsuzluğu toprağın
taşları ve dikenleri ve gökyüzünü iterek
girdiğimiz düşünceden bir gölge kalıyor geride
simsiyah saçlarını rüzgâra vermiş uzun koşucu
tetiği düşmeye hazır bir yüreği dayıyor
kısacık ömrüne dolan güz güneşine
yağmur yağıyor bütün zamanlarına dünyanın
bir taş kemerin altından geçiyor koşarak
kemer bir gökkuşağıdır/yedi rengin kilimini taşıyan
otlar rüzgârın ellerindeki beşikte
toprak güneşe teslim olmuş
günler bir kurşun gibi fırlıyor yatağından
ölüm ve yaşam kıskacında
sevgi ve korkusuzluk damlıyor genç adamın yüzünden
uzaktan turaçlar geçiyor/çoban ateşleri yansıyor ufkun alnına
suyun sesi kanıyor ağıtları anlatan mektuplarda
uykuyu unutmuş iki göz dalıyor şafağa
ölümün kıyısında bir çığlık: gençliğimiz kalıyor afişte.', 'önümüzde sonsuzluğu toprağın taşları ve dikenleri ve gökyüzünü iterek girdiğimiz düşünceden bir gölge kalıyor geride simsiyah saçlarını rüzg...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİZE BAKMANIN TARİHİ', 'si-ze-bakmanin-tari-hi-hi-lmi-yavuz-jkbw1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'size bakmanın tarihi! siz
bir gonca kadar kendiliğinden
yazılmış olmalısınız
derin, korkunç  ve ergen
kalbim, sevdalara sığmayan kalbim
bir dağı içeriyor geçerken
siz o dağa sanki kış
ve sanki bıldır yağan karsınız
umarsız sözcüklere bulanmış
size bakmanın tarihi! siz
bir keteni köpürten yaz
ve inanılmaz
yalnızlıklarsınız; sadece
sizin olan o vahim, o beyaz
ve kuytu gurbet sesleriyle
işlenmiş yazdıklarınız
ve yanık, kavrulmuş dizelersiniz
kimbilir hangi sevdalara dolanmış
size bakmanın tarihi! bir
kalbime güvensem sizi hep
okurdum ben...ama nedense
hep aynı hüzün ve
hep aynı tutkuyla
bakmayı bilmediğimden, ne yapsam
bir ilenç, bir kargış
gibi ardımsıra geliyor şairliğim
o solgun yolculuğa adanmış', 'size bakmanın tarihi! siz bir gonca kadar kendiliğinden yazılmış olmalısınız derin, korkunç  ve ergen kalbim, sevdalara sığmayan kalbim bir ...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZLEŞME', 'sozlesme-ozgur-ozmeral-4ph2c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sana tülden kokularla geldi yaşam
uzlaştın
sana bir damla suda kabarcıktı
tortusu yakabilirdi avuçlarımızı
ışıksız dar odalarda tecrit etmeyi düşündüğün
yüreğin sana sırtını dönecekti elbet
aldırmadın
bir köşeye huzur bıraksaydın yeni doğmuş
meydanlarda resmedecektin kaybolan zamanı
sevişmedin
çetelesini tutmaktı işin yok ettiğin zamanların
ilmeksiz teyelsiz terzim benim
uzaktın
yitirdin', 'sana tülden kokularla geldi yaşam uzlaştın sana bir damla suda kabarcıktı tortusu yakabilirdi avuçlarımızı ışıksız dar odalarda tecrit etmey...', ARRAY['Türk Edebiyatı','Şiir','Özgür  Özmeral']::text[], 8.5, '{"poet":"Özgür  Özmeral","poet_slug":"ozgur_ozmeral","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZLER, YAPRAK', 'sozler-yaprak-murathan-mungan-044id', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bazı sözler karanlıkta söylenir, diyorum uykularımın birinde
bazı sözler hiçbir zaman, diyorum kendi sesime uyanırken
bazı sözler karanlıkta söylenir
bazı sözler hiçbir zaman
diyorum armaların birinde
öyledir, iki yanı ağaçlı yollar, arasından
geçip gitmektir şiir
ağaçla, yolla, ne tarafa
ve hangi zaman
imgenin şiddetiyle çoğalır anlam
parçalana parçalana
geçtiğimiz yollardan
onca yaprak düşer
birkaç şiir kalır yalnızca
o derin ağaçlardan
kendi sesimize uyandığımız rüyalarda', 'bazı sözler karanlıkta söylenir, diyorum uykularımın birinde bazı sözler hiçbir zaman, diyorum kendi sesime uyanırken bazı sözler karanlıkta...', ARRAY['Türk Edebiyatı','Şiir','Murathan Mungan']::text[], 8.5, '{"poet":"Murathan Mungan","poet_slug":"murathan_mungan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZLÜK', 'sozluk-ahmet-uysal-rfz6x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'leylâk: yağmurlu günlerde
mora boyar gecenin örtüsünü
poetika: yağmur sözlüğüyle yazılır
burada rüzgârların şiiri
rüzgâr: küçük orospu çiçeklerinin
kokusunu sürükler gizli bohçasında
gece: güz ırmağına düşürür
tülünü, koynuma girmeden önce', 'leylâk: yağmurlu günlerde mora boyar gecenin örtüsünü poetika: yağmur sözlüğüyle yazılır burada rüzgârların şiiri rüzgâr: küçük orospu çiçek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SÖZÜMÜZ VAR', 'sozumuz-var-nevzat-ustun-c1gv4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolumuz var
Gözlerimin bebeği
Hürriyetin yeşerdiği yerde
Gelin yürüyün siz de
Ağaçlar taşlar insanlar
Yolumuz var
Kan rengi dalgaların oluştuğu yere
Kara saçlı
Dik göğüslü
Kızlardan kadınlardan bizim de isteğimiz var
Bre var
Gelecek çağlara kalan
Bir büyük kavga
Bir uzun yol
Fırtınanın toprağı yediği yerde', 'Yolumuz var Gözlerimin bebeği Hürriyetin yeşerdiği yerde Gelin yürüyün siz de Ağaçlar taşlar insanlar Yolumuz var Kan rengi dalgaların oluşt...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Üstün']::text[], 8.5, '{"poet":"Nevzat Üstün","poet_slug":"nevzat_ustun","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİZİN İÇİN KESTİM SAÇLARIMI', 'si-zi-n-i-ci-n-kesti-m-saclarimi-enis-batur-2pe39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I
Femme vous suis-je, et de grand sens.
Sizin için kestim saçlarımı.
Yıllardır uzattığım.
Sizin için durdum ilk, dinlendim.
Yıllardır yorduğum.
Açtım sizin için, açıldım.
Yıllardır kapadığım, kapandığım.
Sizin için bekledim,
Sizin için bekledim,
sizin için güldüm bir tek, sustum.
Yıllardır durduğum boşlukta
femme vous suis-je, et de grande songe
indiğim merdivende
gecelere tuttuğum ışıkta
sizin için umdum, umursadım.
Sizin için yaktım bu ateşi,
besledim yıllardır.
Esirgediğim zaman,
gizlediğim tortu
ve tortuda ayrışan bu hayat
sizin için
kamaştığım gün
titrediğim mum
aktığım yatak.
II
Sizin için hazırladım bu masayı,
İki kelimenin ortasında dinsin fırtına.
Sizin için hazırladım bu döşeği,
İki fırtınanın ortasında kuyu uyku.
Sizin için hazırladım bu yemeği,
İki açlığın ortasında körelmez açlık.
Sizin için hazırladım bu bakışı,
bu sözü, bu sessizliği - sizin için
hazırlandım.
Sizin için uzattım saçlarımı,
kestiğim.
Sizin için söndürdüğüm bu ateşi,
yandığım.
Kurduğum bu çadır, bu saat
arındığım su
soyunduğum gece: Sizin için.
Devrilirken tutunduysam
tutuşurken susmam
zemberekte bu Eyyub
hem cellât hem kurban
sizin için
bir tohum.', 'I Femme vous suis-je, et de grand sens. Sizin için kestim saçlarımı. Yıllardır uzattığım. Sizin için durdum ilk, dinlendim. Yıllardır yorduğ...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancının toprağında filizlenen Bir tohum da sayabilirsin bu dizeleri Sarışın bir son yaz yaprağı da', 'sancinin-topraginda-filizlenen-bir-tohum-da-sayabilirsin-bu-dizeleri-sarisin-bir-son-yaz-yapragi-da-c-hakki-zari-c-u8buj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tohum da sayabilirsin bu dizeleri
Sarışın bir son yaz yaprağı da
GÖZLERİNDE REHİN KALSIN GÖZLERİM
Bu haklı isyan sürdükçe
Ölenlere ağlamak usandırmaz insanı
Ama her gün aynı tonda
Gül-eme-mek bıktırır
Kalırsan
Muhasebecinin oğlundan çaldığım uçurtmayı
Uçuramadığım gökyüzünün masum rengini
Anlatırım sana
Gidersen
Şulesi mengeneye alınmış
Çoğul düşler diyarında
Kırık dal aryaları kucaklar seni
Şaşırırsın
Müphem bir karanlık cöker içine
Hiçbir (kapalı) mekanın yüzölçümü
Yeterince geniş değildir
(hayvanlar için bile)
Kalırsan ayakkabısının bağcıklarını
Sokakta bağlayarak eyleme koşan gencin
Hapishanede yazdığı şiirleri okurum sana
Gidersen
Yanağındaki elma şekeri sevinçlerin
Talan edilir haramilerce
Tavan arasındaki ilk patiğini bile
Anımsamaya firsatın olmaz
Yalnızlığın sana abanır
Sen halvet mekanlara abanırsın', 'Bir tohum da sayabilirsin bu dizeleri Sarışın bir son yaz yaprağı da GÖZLERİNDE REHİN KALSIN GÖZLERİM Bu haklı isyan sürdükçe Ölenlere ağlam...', ARRAY['Türk Edebiyatı','Şiir','C. Hakkı Zari̇ç']::text[], 8.5, '{"poet":"C. Hakkı Zari̇ç","poet_slug":"zaric","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle...', 'seninle-m-ozer-ci-ravoglu-7iife', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölü eti yedim
Tövbem kabul mü
Döndüm sana
Gariplerin
Mağrur padişahına
Ey! Göklerin
ve yerin padişahı
Döndüm sana
Biz ki
Seninle dökmedeyiz
gözyaşımızı!', 'Ölü eti yedim Tövbem kabul mü Döndüm sana Gariplerin Mağrur padişahına Ey! Göklerin ve yerin padişahı Döndüm sana Biz ki Seninle dökmedeyiz ...', ARRAY['Türk Edebiyatı','Şiir','M. Özer Ci̇ravoğlu']::text[], 8.5, '{"poet":"M. Özer Ci̇ravoğlu","poet_slug":"m_ozer_ciravoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-m-ozer-ci-ravoglu-g5w32', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnan
ölçüsü yok yaşamın
Toprağın altı
göğün üstü sensin
Ne acı
Pırıltılı mavi özlemi
hiç
yaşamamış güzeller
Arkadaşım yok
sevgili
kır kokusu yok
Artık anlamıyorum kendimi
Sen misin o!', 'İnan ölçüsü yok yaşamın Toprağın altı göğün üstü sensin Ne acı Pırıltılı mavi özlemi hiç yaşamamış güzeller Arkadaşım yok sevgili kır kokusu...', ARRAY['Türk Edebiyatı','Şiir','M. Özer Ci̇ravoğlu']::text[], 8.5, '{"poet":"M. Özer Ci̇ravoğlu","poet_slug":"m_ozer_ciravoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sylvia PLATH', 'sylvia-plath-sylvia-plath-0kx7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ABD''li şair Sylvia Plath, 27 Ekim1932''de Massachusettes Eyaleti Boston''da doğdu, 11 Şubat', 'ABD''li şair Sylvia Plath, 27 Ekim1932''de Massachusettes Eyaleti Boston''da doğdu, 11 Şubat...', ARRAY['Türk Edebiyatı','Şiir','Sylvia Plath']::text[], 8.5, '{"poet":"Sylvia Plath","poet_slug":"slyvia_plath","theme":"Türk Şiiri","is_hero":false,"total_lines":3}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İT DALAŞI', 'i-t-dalasi-cihan-oguz-9qi1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalbinle giriştiğin bir haksız mücadele bu
Kendi yüzüne attığın pençedir aşkın mührü
Tut ki yaralısın, iyileşmeyecek kadar, çaresiz
Uzaktaki kar tanelerine tutunmak için yarışır mı serçeler
Özlemenin imkansızlık olduğunu bile bile.
Durmadan meşgul çalan bir telefonun ucundasın
Bileklerin yanlış ibreye ayarlı: Tam 12''den vuruldun!
Hedef tahtasının bile ''artık yeter'' dediği andır
Kursağında suskunluk, senin o soylu suskunluğun,
kimbilir hangi kayıp haritayı çıldırtır...
Çarpışmayan hiçbir tanrı kalmadı bu hikayede
Yaşadığımız ''atlatma haber''e sıradan bir başlık uyduracak kadar
cakalıyız
Darmadağın ayak izlerime bakıp da nasıl biteceğini hesaplama bu yolun
Kalbimle it dalaşındayız, hiçbir atlas kucak açmıyor içimdeki ülkeye
Ölüme yıllardır küs olmasam bir akrebe sevda büyüteceğim.
İçimden geçen her şeyin günlüğü tutuldu
Rahat olabilirsiniz, size de yer var bu oyunda
Taburu yanlış patikaya süren acemi bir rütbeliydim
Hepimiz o coğrafyanın ortasında kaybolduk
Şimdi falcıların önünde tek sıra hizadayız
Bizim için açılıyor sinek, papaz, kız,
aşk, ayrılık, unutma mecburiyeti,
semalar üstü inatlaştığımız tanrı...
Durulduk sonunda, morfine uğramış zır deli kadar özgürüz
Biletimiz kesildi, cehenneme kadar bütün yollar açık
Varsa sıratın üstünde de sürüp gider bu it dalaşı
Bir ağızdan çekilen yuhlara da katlanırız
Kıyamete ne kaldı aşk bittikten sonra?
Ömür mü? Yük kervanıdır, geçtiği her adımda biraz daha derinleşir iz
Gökyüzüne darılıp kalır anılara yetişemeyen o evcil akbaba', 'Kalbinle giriştiğin bir haksız mücadele bu Kendi yüzüne attığın pençedir aşkın mührü Tut ki yaralısın, iyileşmeyecek kadar, çaresiz Uzaktaki...', ARRAY['Türk Edebiyatı','Şiir','Cihan Oğuz']::text[], 8.5, '{"poet":"Cihan Oğuz","poet_slug":"cihan_oguz","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÂ MAVERÂDAN', 't-maver-dan-necip-fazil-kisakurek-lfh8n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgâr öyle esti, öyle esti ki,
Her şey uçup gitti, kaldı Yaradan.
Ayna düştü, hayal, perdelerdeki
Bir akiscik gibi çıktı aradan.
Sırtımı uykuda dürtüyor bir el;
Fırla yatağından koşar adım gel!
O bir minicik zar, kabuğunu del!
Seni çağıran var, tâ maverâdan!', 'Rüzgâr öyle esti, öyle esti ki, Her şey uçup gitti, kaldı Yaradan. Ayna düştü, hayal, perdelerdeki Bir akiscik gibi çıktı aradan. Sırtımı uy...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAŞ DA ÇÜRÜR', 'tas-da-curur-ali-cengi-zkan-89den', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Böyle dedi kaya mezarını temizleyen Rüstem Usta.
Taş da çürür.
İncir kokuşlu dar sokakları aştınsa, görmüşsündür
Kıyıda, küçük bir çocuk taş atıyor suya
Taş da çürür.
Eğil biraz, paslanmış kıyı babasına tutunarak sark
Suyla rıhtımın birleştiği yerlere bak
Taş da çürür.
Kumsalda, çam tahtasını astarlıyor sandalcı baba
Çocuk büyümüş; yüzmeyi biliyor, denizle oynamasını da
Yüreğim çürümez; gözyaşları işlemez, kurşunlarınız da
Taş çürüsün.', 'Böyle dedi kaya mezarını temizleyen Rüstem Usta. Taş da çürür. İncir kokuşlu dar sokakları aştınsa, görmüşsündür Kıyıda, küçük bir çocuk taş...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAŞ DAMLALAR', 'tas-damlalar-enis-batur-m87vr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana çölün arkasından gelecek topraklardan,
simsiyah gökkubbeyi delip geçecek bir sabahtan
söz açsın, bir bilici istiyorum: Avucundan altı yüzü
kutlu bir zar düşsün, kemerindeki kemikte susuzluk,
korku ve karabaht yerine kurtuluş harfleri yazsın,
çadırımdan çıktığımda sağanak karşılasın beni,
atıma binmeden bakayım: Gözlerinden kaybolmuş
güven ışığı geçsin, yakınlar beni öylesine bezdirdi,
uzaklar rüzgârını getirip etrafında çevireceği billûr
sesle dolsun - kırıldım,yenildim, bozbulanığım
yıllardır: Bir bilici bulun, geceme yıldız, ağsın.
Böyle uzandım döşeğime gece, gece bitmemişti
böyle uyandım. Beldem baştan uca çiğnendi, kim
oturuyor sarayımda biliyorum, biliyorum kimdir
kadınlarımın koynuna giren: Ağır bir koku,pes
bir kösnü, köpük köpük taşan bir öfke ile kaplandı
odalarım, şehirlerim, hükmettiğim uzun ovalarla
sisin çöktüğü dağlar: Issız bir imparator taşıdım
buraya, tuzla buz gurur getirdim yanımda, bir de
zakkumdan tane tane bir imbiğin doldurduğu şişe,
hiçbir şeyden korkmadım bildim bileli: Ne yazgı,
ne kargış, ne ölüm: Bir tek şüphedir, esirgensin.
Büyük, taşlaşmış damlalardır Zaman, bende
bana ne var ne yok kilitler. Çıkıp uçsuz bucaksız
bir ateş yaksam: Onlar erirler mi? Çıkıp bir ateş
yakacak olsam sanırlar ki çağrıdır, çağırmam,
rüzgârı arkasına almış bir yangındır, korkarlar,
ben kimseyi korkutmak için doğmadım. Bir anlam
yok yaradılışımda, bir giz bir gizem yok kimseden
beri - kendiliğinden an gelir erirse damlalarım,
geçmiş günleri kaskatı geleceğimden ayıran âraf
çizgisinden yürür geçerim: Bir bilici bekliyorum,
muskamdan düğüm çözsün, suskumdan söz yağsın.', 'Bana çölün arkasından gelecek topraklardan, simsiyah gökkubbeyi delip geçecek bir sabahtan söz açsın, bir bilici istiyorum: Avucundan altı y...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TABANCA', 'tabanca-cemal-sureya-0nivp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sigara içenlere ateş etmeyiniz
Evli bir kadınla rakı içerken
Rozet gibi göğsüne takmış cesaretini
Ben Mitridat''tan sözettim siz etmeyiniz
Eski bir Osmanlı paşası gibi
Feodaliteyi süpüren bıyıklarıyla
İstanbul, İstanbul uzakta
İstanbul''a ateş etmeyiniz
Tutalım yanılıp ateş ettiniz
Şeker Ahmet Paşa''nın resimlerini
Eski hececilerin şiirlerini bir de
Ben çok seviyorum siz de seviniz', 'Sigara içenlere ateş etmeyiniz Evli bir kadınla rakı içerken Rozet gibi göğsüne takmış cesaretini Ben Mitridat''tan sözettim siz etmeyiniz Es...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TABİAT ODAM', 'tabi-at-odam-ahmet-kutsi-tecer-bj3u4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Severim kırlarda ben yaşamayı,
On iki ayı.
Severim kırların yeşil göğsünü,
Bütün süsünü.
İstemem başımın üzerinde dam,
Tabiat odam.
İstemem topraktan başka bir yatak,
Kehkeşanlar tak.
Kuşlardan savrulan bir incecik tüy,
Üstümde örtü.
Ve aydan kırpılan bütün yıldızlar,
Rüyamda kızlar.
Her sabah neşeyle uyanan bir eş,
Koynumda güneş.
Dallarda ötüşen kuşlar kabilem,
Bilmezler elem.
Ağlarsak bizimle beraber olur,
Hemşirem yağmur.
Sızlarsak bizimle beraber sızlar,
Kardeşim rüzgâr.
İsteyen toplasın binlerce arşın,
Karlardan kışın.
Mutlaka öptürür bağlarda temmuz,
Çıplak bir omuz.
Severim kırlarda ben yaşamayı,
On iki ayı.
Severim kırların yeşil göğsünü,
Bütün süsünü.
Ölürsem istemem ne yas, ne kefen,
Ne başka bir fen.
Üstümden kalkmasın çimen, çiy, yosun,
Ruhum uyusun.', 'Severim kırlarda ben yaşamayı, On iki ayı. Severim kırların yeşil göğsünü, Bütün süsünü. İstemem başımın üzerinde dam, Tabiat odam. İstemem ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kutsi Tecer']::text[], 8.5, '{"poet":"Ahmet Kutsi Tecer","poet_slug":"ahmet_kutsi_tecer","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TABUT', 'tabut-necip-fazil-kisakurek-7tnjk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tahtadan yapılmış bir uzun kutu;
Baş tarafı geniş, ayak ucu dar.
Çakanlar bilir ki, bu boş tabutu,
Yarın kendileri dolduracaklar.
Her yandan küçülen bir oda gibi,
Duvarlar yanaşmış, tavan alçalmış.
Sanki bir taş bebek kutuda gibi,
Hayalim, içinde uzanmış kalmış.
Cılız vücuduma tam görünse de,
İçim, bu dar yere sığılmaz diyor.
Geride kalanlar hep dövünse de,
İnsan birer birer yine giriyor.
Ölenler yeniden doğarmış; gerçek!
Tabut değildir bu, bir tahta kundak.
Bu ağır hediye kime gidecek,
Çakılır çakılmaz üstüne kapak?', 'Tahtadan yapılmış bir uzun kutu; Baş tarafı geniş, ayak ucu dar. Çakanlar bilir ki, bu boş tabutu, Yarın kendileri dolduracaklar. Her yandan...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAFLAN', 'taflan-hi-lmi-yavuz-kvsli', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne zaman dinecek, ne zaman
bu taflan, bu taflan?
ey uçurum gözlü sevgilim!
ne zaman baksam
bir ''hiçlik tadı''
ve ağzından
yıldızlar uçuran
ergin, yeşil ve yabanıl
bir yaz gecesi gibisin
yüzünde yolların gülüşü
ve yaz göğüne ilişkin
bir esenlik üretiyorsun
geçip giden fırtınalardan
ey uçurum gözlü sevgilim!
ne zaman baksam
aşkların büyük yarlarıyla
kuşatılmış görüyorum kendimi
safran
ve ezilmiş yazlardan
bakışlarının kıyısız
açıklarına
gurbet ve cevahir taşıyan
bir gülüş söylencesi
geçer bir yazdan ötekine
derin anlatılardan
ey uçurum gözlü sevgilim!
ne zaman baksam
bir dağın yırtmacından
ince bir dere yatağı
gibi kayan
yeşil tenini görüyorum
akşam
nasıl da yakışıyor yüzüne
ve sanki bir kayalığın içine
durmadan kendi kendini oyan
bir ferhâd gibiyim ben
ya da pusuda, karanlık
bir gül gibi
hem solan hem solmayan
ne zaman dinecek, ne zaman
bu taflan, bu taflan?
ey uçurum gözlü sevgilim!', 'ne zaman dinecek, ne zaman bu taflan, bu taflan? ey uçurum gözlü sevgilim! ne zaman baksam bir ''hiçlik tadı'' ve ağzından yıldızlar uçuran er...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAHATTUR', 'tahattur-ahmet-hasi-m-div6f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir Acem bahçesi, bir seccâde,
Dolduran havzı ateşten bâde...
Ne kadar gamlı bu akşam vakti...
Bakışın benzemiyor mu''tade.
Gök yeşil, yer sarı, mercân dallar,
Dalmış üstündeki kuşlar yâda;
Bize bir zevk-i tahattur kaldı
Bu sönen, gölgelenen dünyâda!', 'Bir Acem bahçesi, bir seccâde, Dolduran havzı ateşten bâde... Ne kadar gamlı bu akşam vakti... Bakışın benzemiyor mu''tade. Gök yeşil, yer sa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAHRİP TANESİ', 'tahri-p-tanesi-oktay-taftali-v7v70', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kimse gelmedi bu sabah, yalnız ben
geçmiş uygarlıklardan sille tokat kovuldum
yoldaydım
saçlarım üç numara, elbisem çizgi çizgi
korkumun ortağı silahlarım
yüreğimdeki bakır damla, maça kızım
künyemin gerçek sahibi, göçebe ordum
sen sevgili tahrip tanesi
bir iyilik yap bana
kimse girmesin sularıma bırak çakmasın fenerim
başlatma yalnızlık nöbetimi küfür bela
ve beni tahtadan sil, nöbeti sevenler tutsun
oysa ben kimseyi sevmedim, kimseyi sevmedim ben
gözümde büyüttüm sevgiyi, mutluluğa da inanmadım
böylece öğrendim kovulmadan gitmesini
ve sanırım çekip gitmek
kalabalık bir güne başlamaktan iyidir
beklediğim: sürünmekten ölmüş yılan derisi
deve kemiği tarağım
cinayet ihbarlarım benimle kalsın
taşa sarıp kuraklığı burada bırakıyorum
kıl, tüy, sopa
ayrıca zincir
şimdilik bu kadar yeter
senin elin sevgili tahrip tanesi
benim yerime, kendini nöbete yazar
korkma sakın yalnızlığın uzun sürmez
inan her ânında ölümün
binlerce devriye kolluk değişir
saçlarım üç numara elbisem çizgi çizgi
gitmeliyim
bu halimle bana yalnız gurbet yakışır.', 'kimse gelmedi bu sabah, yalnız ben geçmiş uygarlıklardan sille tokat kovuldum yoldaydım saçlarım üç numara, elbisem çizgi çizgi korkumun ort...', ARRAY['Türk Edebiyatı','Şiir','Oktay Taftali']::text[], 8.5, '{"poet":"Oktay Taftali","poet_slug":"oktay_taftali","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAHTA, KÜRSÜ, ÇOCUKLAR', 'tahta-kursu-cocuklar-behcet-necati-gi-l-kry4j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tahta sınıfa karşı
Kürsü tahtanın yanında
Sınıfta otuz çocuk vardı.
Tahtanın önünde silgi
Üç dört tebeşir
Öğretmen içeri girdi
İlk ders cebir.
Tahta tahtadır ama
İnsanlardan anlayışlı
Hiç sevmediği halde
Tahta cebiri kavradı.
İkinci dersin öğretmeni
Geçti kürsüye oturdu
Tahta yan gözle ilgili
Öğrendi Auguste Comte''u.
Üçüncü derste tahtaya
Bir öğrenci kalktı fakir
Yaz dedi öğretmen yazdı:
&quot;Hayata neş''e güneştir
Melal içinde beşer
Çürür bizim gibi...&quot;
Tahta şairin halini
Çocuğunkine benzetti
Üzüntüler, yoksulluklar elinde
Çocuk da çürüyüp gitmişti.
Dördüncü ders boş geçti
Zil çalsın bekle çalmaz
Tebeşiri kaptığı gibi
Bir çocuk geldi haylaz
O canım mısralara
İki çizgi çizdi çapraz
Yazdı iri iri:&quot;Yuha!&quot;
Kayboldu tahtanın nuru
Kayboldu tahta
Sonraki çizgiler altında.', 'Tahta sınıfa karşı Kürsü tahtanın yanında Sınıfta otuz çocuk vardı. Tahtanın önünde silgi Üç dört tebeşir Öğretmen içeri girdi İlk ders cebi...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necati̇gi̇l']::text[], 8.5, '{"poet":"Behçet Necati̇gi̇l","poet_slug":"behcet_necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAHTA KUTU', 'tahta-kutu-kagan-kok-kihw9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde sihirli tahta bir kutu var
İçine atılır temiz kirli acılar
Zaman söz anahtar
Ve aşklarla kapanır
İçimdeki sihirli tahta kutuya bir yol var
İzi zor bulunan kardan
Kendimden mahrum ediyor beni
Zaman zaman
İçimde sihirli tahta bir kutu var
Güneşli günlerde şeffaf karamsar
Sanki üzerinde bir gül durur
Öyle günlerde pembe bir koku dışavurur
Buram buram
İçimde sihirli tahta bir kutu var
Bazen kendine bir parmakla vurur
İçimde anlatılmaz tıkırtılar
Çevremde tuhaf tuhaf gözler olur
Soran soran
İçimde sihirli tahta bir kutu var
Dediysem yalan
Kutular.......kutular.......kutular', 'İçimde sihirli tahta bir kutu var İçine atılır temiz kirli acılar Zaman söz anahtar Ve aşklarla kapanır İçimdeki sihirli tahta kutuya bir yo...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAŞI KAVRIYOR ÇOCUKLAR', 'tasi-kavriyor-cocuklar-mahmut-temi-zyurek-dop39', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'taşı
kavrıyor
çocuklar
göğe yükseliyor taş
taş, kıvançla dönüyor avuçta
kumları yara yara fışkırıyor çakıllar
körpe gövde
çeliğe direniyor
toy ruh, katil akla
korku tünelindeyiz, sesler şirret, yol zifiri
tanklar geçiyor çocukların üstüne
keskin nişancı, kalbine yansıtıyor lazeri,
kırmızı bir lekeyle düşüyor çocuk, elinde sapan
robokop asker, elinde lav silahı,
bakmıyor bile alevleri çizmeleri yalayan
sihirli lamba hevesli molotof şişelerine
ağır toplar kuşatılmış ortaçağ
kalesinin önünde mancınık dekoru sanki
kale dersen küçücük avuçlarda yığma taş yapı
herkesin rolü kusursuz bu ölüm oyununda
... ... ...
Auschwitz, Dachau, Treblinka
orman da değişti, av da
toprak unuttu insan sıcaklığını
yoruldu soğumuş bedenleri sarmaktan
kuşlar kayboldu kül dağlarında
El Halil, Ramallah, Dünya
kin, o kendini mazlum sanan irinli akıl
akıyor çöl sıcağına
sızıyor gözyaşıyla dolu Lut''a
dostum, yoldaşım Primo Levi
ağır yaşadın bu cehennemi
hızlı terk ettin
herkesin katil olduğunu gördüğün anda
İntifada!
sırnaşanlar için hayat
bıraktığın gibi
araftayız daha', 'taşı kavrıyor çocuklar göğe yükseliyor taş taş, kıvançla dönüyor avuçta kumları yara yara fışkırıyor çakıllar körpe gövde çeliğe direniyor t...', ARRAY['Türk Edebiyatı','Şiir','Mahmut  Temi̇zyürek']::text[], 8.5, '{"poet":"Mahmut  Temi̇zyürek","poet_slug":"mahmut_temizyurek","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
