INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAKA', 'taka-bulent-ecevi-t-5c4b1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'takalar geçiyor allı yeşilli
takalar geçiyor dümenleri lâzlı
takalar geçiyor en nazlı
yelkenlilerden de güzel
güvenli sularda işsiz dönenen
