INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAŞLI YAZI', 'tasli-yazi-mustak-erenus-fei5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Üç el yamanmıştı geceye sivri
Korkunun ötesinde ateş yakmıştı çocuk
Kimse bir şey diyemedi
Önce bir yerinden başladı
Kocaman kara kırmızı mor
Kımıldadı deli taşlar, denizler bitti
Çıldırıyordu yağmursuz toprak
Kaynadı ağaçlar kuşlar bulutlar
Doğa yarattıklarını yedi
Sustu insansız dağ taş yorgun
Delinmiş göklerde yıldızlar yerlerine dönüyorlardı
İşte bu upuzun sersemlikte
Çatladı bir küçük taşın sabrı
Daha küçük bir böcek çıktı güne
Yaşamı müjdeledi
Utandı önce o korkusuz kara kırmızı mor
Boşluklara çakılı ışıklar
Doğacak çocuklara sevindi
Açıldı hemen koca gökler
İnatçı bir son bitiyordu
Tüm yağmurlar indi
Üç el yamanmıştı geceye sivri
Ateş yakmıştı çocuk geceye
Kimse bir şey diyemedi
Şimdi yine döndük geldik
Atomlarla
Bu bitmeyen son
Nagazakide kırmızı elbiseli çocuk
Okşarken parlak düğmelerini
Bir anda yamandı göklere
O küçücük güzel elleri
Ve işte görüyorsunuz
Kimse bir şey diyemedi.', 'Üç el yamanmıştı geceye sivri Korkunun ötesinde ateş yakmıştı çocuk Kimse bir şey diyemedi Önce bir yerinden başladı Kocaman kara kırmızı mo...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAMAM YAVRUM,', 'tamam-yavrum-charles-bukowski-a1oct', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'METELİĞİMİZ YOK; AMA YAĞMURUMUZ VAR
sera etkisi deyin ne derseniz deyin
eskisi gibi yağmıyor işte yağmur.
özellikle büyük kriz zamanındaki
yağmurlar geliyor aklıma.
kuruş para yoktu ama bolbol
yağmur vardı.
öyle bir gece veya bir gün
değil,
7 gün ve 7 gece
YAĞARDI
ve Los Angeles''in yağmur ızgaraları
bu kadar çok yağmuru emebilecek
şekilde yapılmamıştı
ve yağmur KALIN
ve KARARLI
ve DÜZENLİ yağardı
ve damlaların çatılara çarpışını
oradan da oluk oluk
toprağa akışını DUYARDINIZ
ve DOLU,
büyük BUZDAN KAYALAR
patlayan
oraya buraya saçılan havada uçuşan;
ve yağmur
kısaca
DURMAZDI
ve bütün çatılar akardı -
evin her tarafına
tencereler,
kapkacaklar serilir
TIP TIP sesleri bütün eve yayılırdı;
ve kaplar boşaltılır,
boşaltılır
ve tekrar boşaltılırdı.
kaldırımların üstünden geçerdi yağmur,
bahçelerin içinden; ve merdivenleri tırmanıp
evlere girerdi.
el bezleri vardı, banyo havluları,
ve yağmur genelde
tuvaletlerden girerdi: köpüre köpüre, kahverengi, küçük girdaplarla
ve külüstür arabalarla dolu olurdu sokaklar
güneşli bir günde
marş basmayan arabalarla,
ve işsiz adamlar
sanki canlılarmış gibi duran o eski arabaların
can çekişmelerine bakarlardı
pencereleri önünden;
işsizler,
yenik bir zamanın yenik insanları
hapsolurdu evlerine
karıları ve çocukları
ve kedi köpekleriyle.
kediler ve köpekler
dışarı çıkmamak için diretir
evin garip garip yerlerine
pisliklerini bırakırlardı.
işsiz adamlar
bir zamanlar güzel olan karılarıyla
evde tıkılıp kalmış olmaktan
çıldırırlardı.
korkunç tartışmalar yaşanırdı
haciz ihtar mektupları
kondukça posta kutularına.
yağmur ve dolu, bezelye kutuları,
yavan ekmekler; kızarmış
yumurta, rafadan yumurta, haslanmış
yumurta; fıstık ezmesi
sandviçleri, ve her tencerede
görünmez bir tavuk.
babam, kesinlikle iyi biri olmayan babam
her yağmurda, en iyi ihtimalle,
annemi döverdi,
kendimi üzerlerine atardım,
bacaklar, dizler,
çığlıklar
ta ki
birbirlerinden
ayrılana kadar.
&quot;Gebertic''em seni, &quot; bağırırdım &quot;Bi'' kez
daha vurursan ona öldürürüm seni!&quot;
&quot;Çabuk bu orospu çocu''unu
çıkar burdan!&quot;
&quot;hayır, Henri, annenin
yanında kal!&quot;
evet, bütün evler kuşatma altındaydı
fakat sanırım bizim evdeki dehşet
ortalamanın üstündeydi.
ve geceleri
uyumaya çalıştığımızda
yağmur yağmaya devam ederdi
ve karanlıkta
suların odama girmemesi için
cesurca direnen penceremden
ayın yağmur sularıyla bulanık
görüntüsünü seyrederken
Nuh''u hayal ederek
ve Gemisini
tekrar oluyor galiba
diye düşünürdüm.
hepimiz düşünürdük
bunu.
ve sonra, birdenbire,
dinerdi yağmur.
galiba hep
sabaha doğru
5, 6 sularında dinerdi,
huzur çökerdi her yere,
ama tam bir sessizlik değil
çünkü hala devam ederdi
tip
tip
tip
sesleri
ve sonra sis ve duman
dağılırdı
ve sabah 8''de
gözleri kamaştıran sapsarı bir güneşışığı
düşerdi yeryüzüne,
Van Gogh sarısı -
çılgın, köredici!
ve ardından
sağanaktan kurtulan
çatı olukları
güneş altında
genleşmeye başlardı:
PENG!PENG!PENG!
ve herkes kalkıp dışarı bakardı
hala yağmuru içine çeken
bahçeler
hiç bu kadar yeşil olmamış
bir yeşil içinde
ve kuşlar
bahçelerde
deli gibi cıvıldayan kuşlar,
7 gün 7 gecedir
yere konup da
adamakıllı bir şey yiyememiş
tohum yemekten
bıkmış kuşlar
solucanların
toprak üstüne çıkmasını beklerlerdi,
yarı boğulmuş solucanların.
kuşlar solucanları önce topraktan çekip
havaya kaldırır
sonra da midelerine indirirlerdi;
karatavuklar ve serçeler olurdu.
karatavuklar serçeleri uzaklaştırmaya
çalışır
ama serçeler,
açlıktan delirmiş,
daha küçük ve çabuk,
kendi paylarını
kotarırlardı.
erkekler verandada durur
sigaralarını içerlerdi,
şimdi kapı kapı dolaşıp
büyük olasılıkla hiç bir kapı ardında
bulamayacakları bir
iş arayacaklarının,
büyük olasılıkla çalışmayacak arabalarını
çalıştırmaya uğraşacaklarının
bilincinde.
ve bir zamanlar güzel olan
karıları
banyoya girer
saçlarını tarar,
makyajlarını yapar,
dünyalarını tekrar
biraraya getirmeye çalışırlardı,
onları saran korkunç mutsuzluğu
unutmaya çalışarak,
kahvaltı için
ne hazırlasam diye
telaşlanarak.
ve radyo
okulların
açıldığını söylerdi.
ve
ardından
işte ben
yine okul yolundaydım,
yollarda kocaman
su gölcükleri,
tepemde yeni bir dünya gibi
güneş,
evde annemler,
okula
zamanında vardım.
Bayan Sorenson bizi
&quot;bugün tenefüs yok,
yerler çok ıslak&quot;
diyerek karşıladı.
çocuklar &quot;AOF&quot;
bağırdı bir ağızdan.
&quot;fakat tenefüs saatinde
çok farklı birşey
yapacağız,&quot; dedi,
&quot;ve çok zevkli
bir şey!&quot;
hepimiz merak ettik
bu çok zevkli şeyin
ne olduğunu
ve o iki saat
Bayan Sorenson
dersini anlatmaya
devam ederken
bir türlü geçmek bilmedi.
Küçük kızlara baktım,
çok tatlı ve temiz ve
dikkatli görünüyorlardı,
uslu ve dik
oturuyorlarken sıralarında
ve saçları
Kaliforniya
güneşi altında
çok güzeldi.
sonra tenefüs zili çaldı
ve hepimiz eğlenceyi
beklemeye koyulduk.
ardından Bayan Sorenson sınıfa seslendi:
&quot;şimdi ne yapacağız
biliyor musunuz, birbirimize
yağmur sağanağı sırasında
neler yaptığımızı anlatacağız!
en ön sıradan başlayıp
arka sıralara doğru devam edeceğiz!
hadi Michael, sen başla!...&quot;
ve hepimiz
hikayelerimizi
anlatmaya başladık, Michael başladı
ve herkes sırayla kalkıp devam etti,
ve sonra farkettik ki
hepimiz yalanlar söylüyorduk, tamamen
yalan sayılmaz ama
çoğunlugu yalandı
ve oğlanlardan bazıları pis pis
gülmeye başladığında kızlar onlara
kötü bakışlar fırlattı ve
Bayan Sorenson &quot;tamam!&quot; diye bağırdı
&quot;tam bir sessizlik istiyorum!
Siz merak etmeseniz de
ben
neler yaptığınızı
öğrenmek istiyorum!&quot;
böylece biz de hikayelerimize
devam ettik
ve hepsi de hikayeydi.
bir kız gökkuşağı
ilk çıktığında bir ucunda
Tanrı''nın yüzünü
gördügünü söyledi.
bir tek hangi ucu olduğunu söylemedi.
bir oğlan oltasını
pencereden sarkıtıp
bir balık yakalayıp
kedisini
beslediğini söyledi.
hemen hemen herkes
bir yalan uydurdu.
gerçek
fazla acı
ve utandırıcıydı.
sonra zil çaldı
ve tenefüs bitti.
&quot;teşekkür ederim,&quot; dedi Bayan
Sorenson, &quot;hepsi çok
hoştu.
yarına kadar
yerler
kurur ve
kullanılabilecek
hale gelir.&quot;
çocuklardan bir
gürültü koptu.
küçük kızlar
dimdik ve uslu
oturuyorlardı,
çok tatlı ve
temiz ve
dikkatli,
saçları dünyanın bir daha
asla göremeyeceği bir güneşin
ışıkları altında
çok güzel
görünüyordu.
ve
Charles BUKOWSKI', 'METELİĞİMİZ YOK; AMA YAĞMURUMUZ VAR sera etkisi deyin ne derseniz deyin eskisi gibi yağmıyor işte yağmur. özellikle büyük kriz zamanındaki y...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles_bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":290}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAN OLMAK', 'tan-olmak-alain-bosquet-sxbxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tan olmak
kutsamak için tanı;
kuş olmak
hayran olmak için kuşa;
çimen olmak
yaraşmak için çimen yaşamına:
yitmekti sevmek
sevilende.
Yele oldum
(günaydın, kısrak!)
Taşyaprağı oldum,
(iyi akşamlar, gelincik!)
ve şu yassı çakıl
öteki çakılların arasında
dalgaların çarptığı.
Değişim,
artık değişmek istemiyorum:
seviyorum.
Aşk,
artık sevmek istemiyorum:
değişiyorum.
Alain BOSQUET', 'Tan olmak kutsamak için tanı; kuş olmak hayran olmak için kuşa; çimen olmak yaraşmak için çimen yaşamına: yitmekti sevmek sevilende. Yele ol...', ARRAY['Türk Edebiyatı','Şiir','Alain Bosquet']::text[], 8.5, '{"poet":"Alain Bosquet","poet_slug":"alain_bosquet","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TANIK GÜNLER', 'tanik-gunler-ahmet-ozer-mtuyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler
Hüznü yüklenip
Ağır prangalar gibi
Sancıyı taşıyarak
Uçsuz bucaksız gökyüzünün altında
Bizlere
Dev parmaklarıyle
Gelecek
getirdiler.
Günler
Ayrı düşmeyi sevdiğimizden
Sevdiğimiz çocuğumuza dokunamamayı
Açık sarflarla mektuplar göndermeyi
Öğrettiler.
Günler
Tanık oldular ölümlere
Gördüler vurulup öleni
Öldüreni
Hayatla taşınan ölümü
Ölümle başlayan dirimi.
Günler
Oldular en büyük lokomotif
Acımayı öğrenmeyen tarihe.', 'Günler Hüznü yüklenip Ağır prangalar gibi Sancıyı taşıyarak Uçsuz bucaksız gökyüzünün altında Bizlere Dev parmaklarıyle Gelecek getirdiler. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
