INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TANRI BABA', 'tanri-baba-pierre-jean-de-b-ranger-4nrn6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tanrı Baba, bir sabah uyanınca,
Biz insanları düşündü nasılsa,
Gitti pencereye: "Kim bilir, dedi;
Belki o gezegen yok oldu gitti.
Ama baktı, uzakta, çok uzakta,
Bir köşecikte fır dönüyor dünya.
Şeytan canımı alsın, dedi Tanrı,
Alsın vallahi bir şey anlıyorsam
Bu dünyalıların tutumlarından.
Ey benim minnacık yaratıklarım,
Ak ve kara, donuk ve yanıklarım,
Dedi Tanrı, en babacan haliyle;
Sizi ben yönetiyormuşum sözde.
Oysa, görüyorsunuz, Allah''a şükür,
Benim de sürüyle bakanlarım var,
Şeytan canımı alsın, dedi Tanrı,
Alsın vallahi, çocuklar, bu bakanları
İkişer üçer atmazsam kapı dışarı.
Boşuna mı kızlar verdim, şarap verdim size?
Güzel güzel yaşayasınız diye.
Nasıl olur da siz benim inadıma
Orduların Tanrısı dersiniz bana?
Ne yüzle adımı alıp dilinize
Top atarsınız birbirinize?
Şeytan canımı alsın, dedi Tanrı;
Alsın vallahi, çocuklar, bir tek
Orduyu kumanda ettiysem bugüne dek.
Şu süslü püslü zibidilerin işi ne
Yaldızlı tahtlar üstünde?
Nedir o kasılmaları, böbürlenmeleri?
Beslediğimiz bu karınca beyleri
Sözden benden kutsal haklar almışlar
Benim inayetimle kral olmuşlar
Şeytan canımı alsın, dedi Tanrı;
Alsın vallahi, benden geldiyse eğer
Sizleri böyle kötü yönetenler.
Hiç bana kızmayın artık, çocuklar;
Temiz yürekli olun, bana yeter.
Sevişin, güle oynaya yaşayın,
Sizi yakar makarım diye korkmayın
Kralına da, yobazına da basın kalayı...
Ama keselim, Allahaısmarladık
Curnalcılar duyarsa yandık
Şeytan canımı alsın, dedi Tanrı
Alsın vallahi, o yüzsüz herifleri
Sokarsam kapımdan içeri.
Çeviren: Sabahattin Eyüboğlu', 'Tanrı Baba, bir sabah uyanınca, Biz insanları düşündü nasılsa, Gitti pencereye: "Kim bilir, dedi; Belki o gezegen yok oldu gitti. Ama baktı,...', ARRAY['Türk Edebiyatı','Şiir','Pierre-jean De Béranger']::text[], 8.5, '{"poet":"Pierre-jean De Béranger","poet_slug":"pierre_jean_de_beranger","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TANRI KARAR VERİNCE YARATMAYA', 'tanri-karar-veri-nce-yaratmaya-edward-estlin-cummings-obq6m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'tanrı karar verince yaratmaya
her şeyi bir soluk aldı
bir sirkçadırından daha büyük
ve her şey başladı
insan karar verince yok etmeye
kendisini topladı geleceğin
geçmişini ve bulduğu tek nedeni
parçaladı çevirdi çünküye
Edward Estlin CUMMINGS', 'tanrı karar verince yaratmaya her şeyi bir soluk aldı bir sirkçadırından daha büyük ve her şey başladı insan karar verince yok etmeye kendis...', ARRAY['Türk Edebiyatı','Şiir','Edward Estlin Cummings']::text[], 8.5, '{"poet":"Edward Estlin Cummings","poet_slug":"edward_estlin_cummings","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TANRININ ADI', 'tanrinin-adi-endre-ady-yt1o3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bırakıldığım
Ruhumu - ağırlığı altında çökerek- taşıdığım zaman
Sessizce, beklenilmeksizin
Tanrı beni kucakladı.
Boru çalarak değil,
Dilsiz, gerçek bir kucaklayışla geldi.
Güzel, alev alev bir gün değil,
Bir savaş gecesi geldi.
Körleştiler
Nafile gözlerim: Öldü gençliğim.
Ama, onu, o ışıl ışıl o görkemliyi
Sonsuzluğa değin göreceğim.
Endre ADY', 'Bırakıldığım Ruhumu - ağırlığı altında çökerek- taşıdığım zaman Sessizce, beklenilmeksizin Tanrı beni kucakladı. Boru çalarak değil, Dilsiz,...', ARRAY['Türk Edebiyatı','Şiir','Endre Ady']::text[], 8.5, '{"poet":"Endre Ady","poet_slug":"endre_ady","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TANRININ ANTONIUS''U BIRAKMASIDIR', 'tanrinin-antonius-u-birakmasidir-constantino-kavafi-s-9brfm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birdenbire duyarsan geceyarısı
görünmeyen bir alayın geçtiğini
eşsiz ezgilerle, seslerle-
artık boyun eğen yazgına başarısız
yapıtlarına, tasarladığın işlere
hepsi aldanışlarla biten-
ağlamayasın boş yere.
Çoktan hazırmış gibi bir yiğit gibi
hoşçakal de ona, giden İskenderiye''ye.
Hele kendini aldatmayasın demeyesin:
bu bir düştü, kulaklarım iyi duymadı;
böyle boş umutlara eğilmeyesin.
Çoktan hazırmış gibi bir yiğit gibi
böyle bir kente erişmiş sana yaraşırcasına,
kesin adımlarla yaklaş pencereye,
dinle duygulanarak, ama
yanıp yıkılmalarıyla değil korkakların-
son bir kez, dinle doya doya ezgileri,
o gizli alayın eşsiz çalgılarını,
hoşçakal de ona, yitirdiğin İskenderiye''ye.
Constantino KAVAFİS', 'Birdenbire duyarsan geceyarısı görünmeyen bir alayın geçtiğini eşsiz ezgilerle, seslerle- artık boyun eğen yazgına başarısız yapıtlarına, ta...', ARRAY['Türk Edebiyatı','Şiir','Constantino Kavafi̇s']::text[], 8.5, '{"poet":"Constantino Kavafi̇s","poet_slug":"constantino_kavafis","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAŞRA KIZININ DELİCELERİ', 'tasra-kizinin-deli-celeri-turkan-i-ldeniz-z6ckp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1.
Gözlerim seni görünce güzel
Saçlarım senin için uzun
Tenim seninle sıcak böyle.
Sakınmaklar gereksiz bunu yeni anladım
kırıp dikenli telleri geldim yanına.
Dört tarafımda elle tutulan karanlıktı-bilirsin
raylarca uzuyordu yalnızlığım
körkandil kısır anlayışlara
bir kinim vardı , zamanın eritemeyeceği
bir sancım vardı öylesine belirgin
yokluğun özlü çıbandı sanki
Duramadım.
Duramadım dayanılmaz isteklere
bütün bağlardan kurtulup bir an
gözlerinin büyüsüne geldim
ellerinin ateşine
Yak beni.
Sen uykusun vazgeçilmiyorsun
Seni kendim kadar seviyorum
Günlerden bir gün duysam acısını
Beni ilk öpenin sen olmasını istiyorum
Beni ilk öpenin sen olmasını.', '1. Gözlerim seni görünce güzel Saçlarım senin için uzun Tenim seninle sıcak böyle. Sakınmaklar gereksiz bunu yeni anladım kırıp dikenli tell...', ARRAY['Türk Edebiyatı','Şiir','Türkan İldeniz']::text[], 8.5, '{"poet":"Türkan İldeniz","poet_slug":"turkan_ildeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARAFSIZ AYDINLAR', 'tarafsiz-aydinlar-otto-ren-castillo-od6o8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1
Tarafsız aydınları
yurdumun
sorguya çekilecek
günün birinde
en basit insanları
tarafından
halkımızın.
Soracaklar onlara
ne yaptılar diye
ağır ağır ölürken
ulusları,
tatlı bir ateş gibi
ufacık, bir başına.
Kimse sormayacak onlara
giysilerini,
uzun öğle uykularını
yemek sonrasında,
bilmek istemeyecek kimse
anlamsız uğraşlarını,
hiçlik konusunda görüşlerini,
nasıl para kazandıklarını
felsefe yaparak.
Sorguya çekilmeyecekler
yunan mitolojisi konusunda,
nasıl iğrendikleri konusunda
kendi kendilerinden,
korkuyla ölürken içlerinde bir şeyler.
Sormayacaklar
nasıl vardıklarını
doğrulara
yalanın gölgesinde.
2
O gün
basit insanlar,
tarafsız aydınların
kitaplarında, şiirlerinde
yer almayanlar,
her gün ekmek getirenler onlara,
süt getirenler,
çörek ve yumurta getirenler,
giysilerini dikenler,
arabalarını sürenler,
köpeklerine, bahçelerine bakanlar,
onlar için çalışanlar,
gelip soracaklar:
"Ne yaptınız
acı çekerken yoksullar
içlerindeki sevgi
ve yaşam sönüp giderken?"
3
Tarafsız aydınları
güzel yurdumun,
cevap veremeyeceksiniz.
Yiyip bitirecek sizi
bir sessizlik kuzgunu.
Yüreğinizi kemirecek
zavallılığınız.
Susup kalacaksınız
kendi utancınızla.
Otto René CASTILLO', '1 Tarafsız aydınları yurdumun sorguya çekilecek günün birinde en basit insanları tarafından halkımızın. Soracaklar onlara ne yaptılar diye a...', ARRAY['Türk Edebiyatı','Şiir','Otto René Castillo']::text[], 8.5, '{"poet":"Otto René Castillo","poet_slug":"otto_rene_castillo","theme":"Türk Şiiri","is_hero":false,"total_lines":63}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARİH KÖTÜDÜR', 'tari-h-kotudur-baris-pi-rhasan-u6h41', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte gençliğimin şiirleri
İlk gençliğimin
Güzel şeyler
Deli saçmaları
Beceriksizlikler
Şehvetle titreyen parmaklarla yazmışım onları.
Bir çocuk için
En güzeli
Belki bütün yazdıklarımın en güzeli
Gövdemi ılık
Kirli
Pırıl pırıl bir havuzda düşlerdim
Göğsümde nilüferler
Su çiçekleri
Garip bir çocuk dediler bana
İçine kapalı
Güçlü
Onun koluna girerdim
Zayıflığı çekerdi beni
Acımasız pırıltısı
Geceleyin kendini sevmesi
Organları
Çocukluğumun şiirleri
Hepsinde umarsız bir çığlık
Zavallı
Traji-komik
Şanlı tarihim:
Ne zorbalar geçmiş beynimden
Ne haksız kıyımlar olmuş gövdemde
Kimler can vermiş hapishanelerde
Hangi sınıf egemen?
İlk şiirlerim
Alaycı bir göz
Kirpiklerinde tohum
Düzensiz patlamalar
Yaralı omuzlarım
Biri kavga türküsü
Acemi
Çığlık çığlığa
Yarım
Bütün bunlar şimdi geçmişte kaldı
Çocukken yazdıklarım beni yüreklendiriyor
Bir budala gibi
Yoksul bütün halklar gibi
Şaşkın bir el yazısıyla
Ayaklanmalar tasarlıyorum.', 'İşte gençliğimin şiirleri İlk gençliğimin Güzel şeyler Deli saçmaları Beceriksizlikler Şehvetle titreyen parmaklarla yazmışım onları. Bir ço...', ARRAY['Türk Edebiyatı','Şiir','Barış Pi̇rhasan']::text[], 8.5, '{"poet":"Barış Pi̇rhasan","poet_slug":"baris_pirhasan","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARİH', 'tari-h-cevahir-si-pahi-870d2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kan damladı ve  kök saldı kayada,
Sildik kanı kılıçlardan ince beyaz yenlerimize,
Artık silahımız kalmadığında
Kaburgalarımızdan birini çıkaracağız
Ve bir kılıç yapacağız ondan.
Cevahir SİPAHİ', 'Kan damladı ve  kök saldı kayada, Sildik kanı kılıçlardan ince beyaz yenlerimize, Artık silahımız kalmadığında Kaburgalarımızdan birini çıka...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Si̇pahi̇']::text[], 8.5, '{"poet":"Cevahir Si̇pahi̇","poet_slug":"cevahir_sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARHANA', 'tarhana-ali-yuce-zbzjx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökte bulut ufacık
Hem ufacık hem akçacık
Böldüm oldu kırk parçacık
Ebem tarhana sermiş göğe
Tarhanamı yemeyin kuşlar
Söylerim sizi ebeme', 'Gökte bulut ufacık Hem ufacık hem akçacık Böldüm oldu kırk parçacık Ebem tarhana sermiş göğe Tarhanamı yemeyin kuşlar Söylerim sizi ebeme...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüce']::text[], 8.5, '{"poet":"Ali Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARİHİMİZ', 'tari-hi-mi-z-cevahir-si-pahi-to6qt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kılıcın keskin ağzına atılan bizdik korkusuzca.
Kılıçtı yaran bizi tez elden boylu boyunca.
Cevahir SİPAHİ', 'Kılıcın keskin ağzına atılan bizdik korkusuzca. Kılıçtı yaran bizi tez elden boylu boyunca. Cevahir SİPAHİ...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Si̇pahi̇']::text[], 8.5, '{"poet":"Cevahir Si̇pahi̇","poet_slug":"cevahir_sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARLA', 'tarla-mehmet-basaran-6dynq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklımda genişleyen hep o tarla
Güneşle tüter ince ince
Dinmiş sınırlardaki ağrı
İlk tutkuların adı
Korkusunda serinliğinde
Hele yağmur sonları
Hele sürüldüğünde
Sanırsın insan yüreği
Diriliğin gücü sevinci
Kıpır kıpır derinlerde
Çatlamış güzel günlerin tohumu
Bir mavi şavk içinde
Daya kulağını toprağa dinle
Özsuda sütte kandaki coşkunluğu
Uyanışı dinle dünya kırında', 'Aklımda genişleyen hep o tarla Güneşle tüter ince ince Dinmiş sınırlardaki ağrı İlk tutkuların adı Korkusunda serinliğinde Hele yağmur sonla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TASLAK', 'taslak-cevahir-si-pahi-r6pri', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lombardy kavakları geçirdi kışı
Boz-bulanık göğün altında,
Ne kuş kalmış,
Ne bir esinti,
Oradaki ve buradaki
Yuvaların
Tümü
Yaralı sanki.
Cevahir SİPAHİ', 'Lombardy kavakları geçirdi kışı Boz-bulanık göğün altında, Ne kuş kalmış, Ne bir esinti, Oradaki ve buradaki Yuvaların Tümü Yaralı sanki. Ce...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Si̇pahi̇']::text[], 8.5, '{"poet":"Cevahir Si̇pahi̇","poet_slug":"cevahir_sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAŞTIN YİNE DELİ GÖNÜL', 'tastin-yi-ne-deli-gonul-yunus-emre-dci7f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taştın yine deli gönül
Sular gibi çağlar mısın
Aktın yine kanlı yaşım
Yollarımı bağlar mısın
Nidem elim ermez yâre
Bulunmaz derdime çare
Oldum ilimden avare
Beni bunda eğler misin
Yavı kıldım ben yoldaşı
Onulmaz bağrımın başı
Gözlerimin kanlı yaşı
Irmağ olup çağlar mısın
Ben toprak oldum yolunda
Sen aşırı gözetirsin
Şu karşıma göğüs geren
Taş bağırlı dağlar mısın
Harami gibi yoluma
Aykırı inen karlı dağ
Ben yârimden ayrı düştüm
Sen yolumu bağlar mısın
Karlı dağların başında
Salkım salkım olan bulut
Saçın çözüp benim içün
Yaşın yaşın ağlar mısın
Esridi Yunus''un canı
Yoldayım illerim kanı
Yunus düşte gördü seni
Sayru musun  sağlar mısın', 'Taştın yine deli gönül Sular gibi çağlar mısın Aktın yine kanlı yaşım Yollarımı bağlar mısın Nidem elim ermez yâre Bulunmaz derdime çare Old...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAVAF', 'tavaf-kagan-kok-yk2ed', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah o tenha deneyimhanede
Zamanın ipini çeke çeke
Hem yazdım hem eskittim o şiiri
Aşklar ki gördüler, oysa kördüler, neyi
Binbir eza ve cefanın şehri
Orda dil büyüdü, zaman karardı
Çoğalan kanserli bir yurt iklimi
Ben kendimi taşladım kendi tavafımda
Yüzümün derisini yüzdüm
Gördüğüm bir kördüğüm ve yalnız zamanın etrafında
Dolandı şu yüzüm
Ey kendini daha da derine iten kök
Farkında mısın sanki sözüm sana', 'Ah o tenha deneyimhanede Zamanın ipini çeke çeke Hem yazdım hem eskittim o şiiri Aşklar ki gördüler, oysa kördüler, neyi Binbir eza ve cefan...', ARRAY['Türk Edebiyatı','Şiir','Kağan Kök']::text[], 8.5, '{"poet":"Kağan Kök","poet_slug":"kagan_kok","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TAZE TAZE', 'taze-taze-bedri-rahmi-eyuboglu-zi288', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dondurma kutusu üstünde
Üç kırmızı çiçek
Canımın içi kadar sıcak
Dilediğim kadar kırmızı
Özlediğim kadar gerçek.
Dondurma kutusu üstünde yaz gelmiş meğer
Neler getirdi kim bilir neler
Neler götürecek.', 'Dondurma kutusu üstünde Üç kırmızı çiçek Canımın içi kadar sıcak Dilediğim kadar kırmızı Özlediğim kadar gerçek. Dondurma kutusu üstünde yaz...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyuboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyuboğlu","poet_slug":"bedri_rahmi_eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İŞTE BU İŞ', 'i-ste-bu-i-s-can-yucel-vvu37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Shakespeare
Beatiful is terrible
Terrible is beatiful demiş
Bu söz Türkçe şöyle söylenir mi acep?
Güzelden güzeldir gazel
- O düşen sonbahar yaprağı-
Ve müthiş
Benim şiirden anladığım işte bu iş', 'Shakespeare Beatiful is terrible Terrible is beatiful demiş Bu söz Türkçe şöyle söylenir mi acep? Güzelden güzeldir gazel - O düşen sonbahar...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
