INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TECELLİ', 'tecelli-oktay-ri-fat-horozcu-ddotb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir bu benim çilem
Hesap bilmem
Muhasebede memurum
En sevdiğim yemek imam bayıldı
Dokunur
Bir kız tanırım çilli
Ben onu severim
O beni sevmez', 'Nedir bu benim çilem Hesap bilmem Muhasebede memurum En sevdiğim yemek imam bayıldı Dokunur Bir kız tanırım çilli Ben onu severim O beni sev...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEŞEKKÜR', 'tesekkur-i-lhan-berk-jfbsi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Evet hep açık gidip gelen ağzın içindi;
Gökyüzünün o huysuz maviliği içindi;
Elma kokan bir Türkçeyle konuştuğun içindi;
Ölümün sefil, kötü belleği içindi;
Her gün Pazar kurulan o sokaklar içindi;
Saçında uykusu kaçmış çiçekler ıslattığın içindi;
Çocuklar okuldan dönüyormuş gibi sesin içindi;
İşte bütün ama bütün bunlar için sana teşekkür derim.
Güzel Irmak', 'Evet hep açık gidip gelen ağzın içindi; Gökyüzünün o huysuz maviliği içindi; Elma kokan bir Türkçeyle konuştuğun içindi; Ölümün sefil, kötü ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEHLİKE', 'tehli-ke-metin-guven-95onm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unut beni
Denizlere karşı ağlayan
Kirli beyazlar giyen
Kendi cehenneminde boğulan
Fahişe
Yaslanarak gölgesine
Uyarıyor yavrularını anne kedi:
- Sulardan uzak durun
Yaşamakatır en büyük
Tehlike.', 'Unut beni Denizlere karşı ağlayan Kirli beyazlar giyen Kendi cehenneminde boğulan Fahişe Yaslanarak gölgesine Uyarıyor yavrularını anne kedi...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEK BAŞINA', 'tek-basina-melih-cevdet-anday-98kwu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölürken çocuklarımı unuttum
Küçük deniz kirpileriyle sabah
Denedim bütün sabahları.
Sana sürgünümün şarabını bıraktım
al
Mumlarını güzelliğin ve hiçliğin
Bir de kaygumun soluk ellerini.
Denedim bütün ölümleri
Ama görmedim büyülü ağaç
Ezilmiş sevdaların giysileri.
Sana ayrılığın yayını bıraktım al
Bir de adını bilmediğim gökyüzünü
Lamalar gibi koşar bozkırda.
Oysa ölümsüzlük şuracıkta, kar
Güneşi gibi doldurmuş odayı, basit,
Anlamsız ve tek başına.
Ayaklarım hayvan, üstüm başım bitki
Denedim bütün vakitleri al
Başka türlü geçmeyen bir vakitti.', 'Ölürken çocuklarımı unuttum Küçük deniz kirpileriyle sabah Denedim bütün sabahları. Sana sürgünümün şarabını bıraktım al Mumlarını güzelliği...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEK SESLİ ŞİİRDEN ÇOK SESLİ ŞİİRE', 'tek-sesli-si-i-rden-cok-sesli-si-i-re-edip-cansever-r4un8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mısra işlevini yitirdi;
şiiri şiir yapan bir birim olarak yürürlükten kalktı. Eski rahatlığını, o
sessiz, kıpırtısız düzenindeki rahatlığını boşuna arıyor şimdi. Öfkelerin,
bunlukların, başkaldırmaların dışında kendini yineliyor daha çok. Ne denli
güçlü olursa görünürse görünsün, duygularımızı, gerilimlerimizi, düşünce
coşkularımızı başlatıcı öğe, bir ölçü olmaktan çoktan çıktı. İnsanı,
insanla gelen en çağdaş sorunları karşılayamaz oldu. Öylesine durallaştı ki, onca
bir sözcük yılı da uzak kaldı bize.
Öyleyse şiiri okumalı,
şiiri, usla biriktirmeli artık; mısra ile değil. Diyeceğim, ille de bir ölçü
gerekliyse bu, düşünsel-ussal bir ölçü olmalı. Tek sesli şiirden, çok sesli
bir şiire yönelişteki en kapsamlı ölçü de budur sanırım.
Nicedir şiiri soyut
bir kavrammış gibi düşünemiyoruz. Her toplumun kendine özgü bir şiiri ya da
şiirleri olduğu için böyle düşünemiyoruz. Ülkemiz de bir mucizeler ülkesi değil.
Bizim de gereksinmesini duyduğumuz bir şiir anlayışı var. Hatta bir bakıma
uygulanıyor da bu. Düşünü şiiri diye adlandırabileceğimiz bu şiir
biçimini(tarzını) yerleştirirken, en azından şiire bakma ölçülerimizi de
değiştirmek zorundayız.
Örnekler ortada.
Yapacağı işin bilincine varmış ozanlar kabına sığamıyor artık. Hiç değilse
zorlanıyor şiir, seçkin, soy bir anlatım yolu bulmak için savaşılıyor. Örneğin
cümleler parçalanıyor; söze yeni bir devinim katılıyor böylelikle. Bir bakıma
cümle tavır takınıyor, insanlaşıyor. Derken bir satır başı, bir parantez,
bir dialog...Bakıyorsunuz düzyazıya geçmiş ozan; anlatıyor, açıyor, anlamı
genişletip yoğunlaştırıyor. Mısra yerine devinim , mısrayı ölçü yapmak yerine
usu ölçü yapmak! Güç şiir burdan çıkıyor, şiir okuma zorluğu burdan doğuyor.
Ya peki mısra nedir?
Bir tanımı yok mu onun? Bence yok! Olsa olsa sezilmesi var, şiiri tekilleştirmesi var,
şiiri tekilleştirmesi, kolay ustalıklara araç olması, çağdaş anlayışın
gerisinde kalması var. Mısra da sağduyu gibi bir şey... Sağduyu ise, Einstein'' in
anlayışına göre, &quot;İnsanın on sekiz yaşına gelmeden önce zihnine yerleşen
önyargıların tortusu&quot;ndan başka bir şey değil. İşte mısra da sağduyu gibi,
beğeni eğitimi, töre anlayışı gibi, bize önceden aşılanmış bir öngüzellik
duygusu.
Bu öngüzellik
duygusunu nasıl aşmalı? Önce, mısranın mısraya örnek tutulmasıyla sağlanan iyi
işçilik görünüşü yerine, dirimsel bir şiir anlayışını gerçekleştirmekle...
Buna karşılık şöyle bir soru sorulabilir : Bugüne dek yazılan şiirler, dirimsel
olana bunca uzak mıydılar? Bir bakıma öyle. Düşünürsek, yalnızca kendi
olanaklarıyla yetinen ozan çok azdır bizde. Daha çok deneyler vardır; katkısız bir
sahihlik(authenticite) ve bu sahihliğin pekiştirilmesi yerine, başka başka yaşam
biçimlerine öykünme vardır. Gene de, bu deney bolluğunun, şiirimizi çeşitlendirmek
bakımından yararlı olduğunu söyleyenler çıkabilir. Ama şunu da unutmamalı ki
çeşitlemenin, ozan sayısıyla oranlı olarak değil de, tek tek ozanlarda incelenmesi,
çoğu kez en güçlü kişilikleri bile tehlikeye düşürmüştür. Kısacası, kuramın
yaşamla birleşerek yarattığı gerçek şiir alanı, Fethi Naci''nin deyişiyle,
tümdengelimle tümevarımın çakıştığı nokta, bir iki ozan ayrı tutulursa, hiç
denenmemiş, bir &quot;Çorak Ülke&quot; gibi cansız, yaşamsız kalakalmıştır.
Öyleyse şiirin
yapısında şiirin dokusunda bilinçli, özgün vurucu bir düşünce-yaşam
birliğinin yer alması gerekiyor. Burdan da araştırıcı, eytişimsel bir sıçrama...
Dışavurumcu bir düzanlatım...Aruza, heceye, genel olarak da mısraya sığdırılmaya
çalışılan şiirin, yerellikten doğacak bir bütünselliğe, bir evrenselliğe
yerleştirilmesi.
Oysa biz
mısraya göre yaşıyoruz hala. Mısra sanki bir yaşama biçimi, aşılması olmayan bir
nesne. Nedeni ortada bunun : Halk, Saraya, tek elden yönetime, yazgıya inanırken, bu
arada bir üst-yapı kurumu olan şiire de inanmazlık edemezdi. Ama hangi şiire?
Yukarudan gelen, hiçbir şey söylememeyi görkemle dile getiren, soyluluk gösterisi,
mısracı şiire...Bugün bile çok şey değişmiş değil. Geleneğe saygı yüzünden,
belki de hep aynı çıkmazlarla dolaşıp duruyoruz. Kim bilir, belki de koşullar
değişmedi ya da koşulları zorlayan, güçlü kişiler çıkmadı. Yeni bir akımın
öncüsü olan Orhan Veli bile, halkın beğenisini alıp, onun toplumsal-ekonomik
gerçeklerini şiir dışı ederken, şiirin öz sorunlarına ne denli yabancı
kaldığını, hiç değilse her şeyden bağımsız bir şiir düşünmekle ne denli
yanıldığını ortaya koyalı kaç yıl geçti aradan? İşte her söylediğini şiir
diye söyleyen, adı ustaya çıkan, gerçekte çelişmeler ustası Cahit Sıtkı nerede?
Ya Cahit Külebi? Acaba Yeşeren Otlar''daki gizemciliğine hangi deneylerden
geçtikten sonra varabildi? Hiçbir deneyden! Çünkü o, eskiden de bir görüş
bütünlüğüne varamamıştı. Örnek mi? İşte kadınları övdüğü kısa bir
şiirden kısa bir şiirden son iki satır : &quot;Ben yine insanlığı severim / Bütün
kadınlardan ziyade.&quot; Kadınları insanlık dışı tutan kof ve yanlış bir
toplumculuktan başka nedir ki bu? Ayrıca şiirimizin bugünkü bunluğu da, hep bu
mısracı tutumun kılık değiştirmesinde aranmalıdır.
Yukarıda da
belirttiğimiz gibi, değişmesi gereken, bir bakıma değişmekte olan şiire, yeni bir
ölçü bulmak zorundaysak, bu hiç şüphesiz u dışı bir ölçü olmayacaktır. Bunun
için de alışkanlıklarımızı yenmemiz, eskimiş mantık kurallarından kurtulmamız
gerekir. Çünkü ussal bir coşku olan şiiri, ancak usun ölümsüzlüğüyle
denetleyebiliriz. Usun ölümsüzlüğü ise, onun durmadan değişmesi, durmadan
yenilenmesi, kuşak kuşak, çağ çağ bir gelişmeye, bir yüceliğe aracılık
etmesidir. Şiiri, tarihsel - toplumsal koşullarından soyutlamayı
düşünmedikçe, mısra da işlevini yitirmiş sayılır.', 'Mısra işlevini yitirdi; şiiri şiir yapan bir birim olarak yürürlükten kalktı. Eski rahatlığını, o sessiz, kıpırtısız düzenindeki rahatlığını...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":86}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEK YASAK', 'tek-yasak-cemal-sureya-8dwj8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlüğün geldiği gün
O gün ölmek yasak!', 'Özgürlüğün geldiği gün O gün ölmek yasak!...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEKNE', 'tekne-mehmet-taner-618si', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir coşkun bir an''ı kucaklamak içindi
Yaşam da fırtınanın arayışı
Yitik tekneleri
İstek sönünce
Mırıltılar da işitilmez oldu
Sessizlik de çekildi
Beni arayan bir su damlası
Gecenin kursağında
Ve yalnız kendi iniltisi', 'Şiir coşkun bir an''ı kucaklamak içindi Yaşam da fırtınanın arayışı Yitik tekneleri İstek sönünce Mırıltılar da işitilmez oldu Sessizlik de ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TELEFON', 'telefon-oktay-ri-fat-horozcu-is0tv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin var ya çekik kara kara
Önce gözlerindi en güzel ışık
Beyaz dişlerindi bacakların omuzun
Damalı örtüde bir kâse çorba gibi
Buğulu bir lezzetti karıkocalık
Şimdi bir çınar yeşeriyor içimde
Bir şarkı söyleniyor uzun uzun
Hürriyetin rüzgârlı bayrağı oldu
Bize yeten aydınlığı sevdamızın
Aman dayanamazsam ne etmeli
Bütün pencereler üstlerine açık
Kimler soyar çocukları kimler örter
Biri on bir yaşında öteki küçük
Ya anne diye bağırırsa uykusunda
Belki korkmuş belki de susamıştır
Geceleri su içmeye alışık
Çorap öyle mi giydirilir don öyle mi bağlanır
Gömleği bir tuhaf sarkıyor arkasında
Çocuklara bakma dayanırım
Gide gide çoğaldım halkım ben artık
Dağ taş kalabalık kalabalık
Satar mıyım onları onlar da çocuklarım
Ben kadınım çocuklarımla varım
Telefon nafile açmam seni
Söylemez dillerim yarınla bağlı
Tutmaz parmaklarım kocamdan belli
Telefon benim ki de analık
Çocuklara bakma dayanırım
Sevgiydim önce bir çeşit incelik
Şimdi işe yarıyorum kaba saba
Tuzlu bir deniz kokusu havada
Benimle başladı bu müthiş tazelik
Benimle yaklaştı güzel günler
O günlerin eşiğinde beni hatırlayın
Hatırlayın onların vahşetini
Her telefon çalışta kesik kesik', 'Gözlerin var ya çekik kara kara Önce gözlerindi en güzel ışık Beyaz dişlerindi bacakların omuzun Damalı örtüde bir kâse çorba gibi Buğulu bi...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TELGRAFHANE', 'telgrafhane-melih-cevdet-anday-mhk5z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uyumayacaksın
Memleketinin hali
Seni seslerle uyandıracak
Oturup yazacaksın
Çünkü sen artık o sen değilsin
Sen şimdi ıssız bir telgrafhane gibisin
Durmadan sesler alacak
Sesler vereceksin
Uyuyamayacaksın
Düzelmeden memleketin hali
Düzelmeden dünyanın hali
Gözüne uyku giremez ki...
Uyumayacaksın
Bir sis çanı gibi gecenin içinde
Ta gün ışıyıncaya kadar
Vakur metin sade
Çalacaksın.
1952', 'Uyumayacaksın Memleketinin hali Seni seslerle uyandıracak Oturup yazacaksın Çünkü sen artık o sen değilsin Sen şimdi ıssız bir telgrafhane g...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TELÂKKİ', 'tel-kki-yahya-kemal-beyatli-wh1k0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yollarda kalan gözlerimin nûrunu yordum,
Kimdir o, nasıldır diye rüzgârlara sordum,
Hulyâmı tutan bir büyü var onda diyordum,
Gördüm: Dişi bir parsın elâ gözleri vardı.
Sen miydin o âfet ki dedim, bezm-i ezelde
Bir kanlı gül ağzında ve mey kâsesi elde,
Bir sofrada içtik, ikimiz aynı emelde,
Karşımda uyanmış gibi bir baktı sarardı.', 'Yollarda kalan gözlerimin nûrunu yordum, Kimdir o, nasıldır diye rüzgârlara sordum, Hulyâmı tutan bir büyü var onda diyordum, Gördüm: Dişi b...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TELLİ TELEFON', 'telli-telefon-oktay-ri-fat-horozcu-2akr6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne ettim de bâd-ı saba ile yolladım
Gurbet elden nazlı yâra selâmı
Yetiş imdadıma telli telefon
Ayağına düştüm posta tatarı
Aya bakar mektubunun gelmesi
Kara bahtım söyler kahve telvesi
Bir şey değil verem olup ölmesi
Üstümden hasretliği atamıyorum
Sensiz döşeklerde yatamıyorum', 'Ne ettim de bâd-ı saba ile yolladım Gurbet elden nazlı yâra selâmı Yetiş imdadıma telli telefon Ayağına düştüm posta tatarı Aya bakar mektub...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEMMUZ AYINDA ANNEM', 'temmuz-ayinda-annem-mahzun-dogan-mjgo7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Temmuz ayında annem uykuya daldı
Ekinler sarışındı tarlada. Gök
çekti küreklerini bulunmaz bir limana
Unutulmuş bir köyde
küçücük mutfak pencereleri
el salladı. Babam
uzun uykusundan uyandı
Ladik''de bir jandarma, dayayıp başını
nöbetçi kulübesinin soğuk camına
sevdiği kadını anımsadı
kalbini banıp ayışığı mürekkebine
geceye mührünü bastı
Yürüdü posta katarı
Raylar şafağın şahdamarından fırladı
Temmuz ayında yeryüzü öksüz kaldı', 'Temmuz ayında annem uykuya daldı Ekinler sarışındı tarlada. Gök çekti küreklerini bulunmaz bir limana Unutulmuş bir köyde küçücük mutfak pen...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğan']::text[], 8.5, '{"poet":"Mahzun Doğan","poet_slug":"mahzun_dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEMMUZA KARŞI', 'temmuza-karsi-turkan-ildeniz-agefs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Acının ağzından öpüyorsun yine
yine cehennem yürek
yine hüzne gönüllü devriye.
Turaçlar amansız iklimde kanat açmadı ama
ağaçlar zamansız açtı çiçek
kar vurdu birden , pusudaymış fırtına
ardından bir yağmur , bir yağmur ki
yağmur değil sanki kezzap...
heba oldu onca heves , onca emek
onca kitap.
Söylemeye gerek yok , zaten herkes farkında.
Ey nice cendereden süzülen direnç
hangi acı denenmedi ki bizde
kitap yakılan yıldan ,
insan yakılan yıla vardık
katliam katladık , çağ atladık.
Gel de içlenme.
Bu şiir bir büyük VAH - Temmuza karşı
Ağustos kapısı nerede , nereye çıkar bu çarşı
Nereye çıkar bu çarşı
ki...
hem kalabalık , hem karanlık.
Tehlikeden geçiyoruz - belli etme - ilerle', 'Acının ağzından öpüyorsun yine yine cehennem yürek yine hüzne gönüllü devriye. Turaçlar amansız iklimde kanat açmadı ama ağaçlar zamansız aç...', ARRAY['Türk Edebiyatı','Şiir','Türkan Ildeniz']::text[], 8.5, '{"poet":"Türkan Ildeniz","poet_slug":"turkan_ildeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İÇTEN İÇE', 'i-cten-i-ce-eray-canberk-yp7af', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sevdam seni durmadan
can evinde yeşertir
çiçekçe ve çocukça
sıralı sırasız ikide bir
nice yıkım nice ılgar
geçer iz bırakarak
nice geç kalmış bahar
acımıza eklenir
çocukları da alan
ölüm sıra beklemez
yara üstten kapanır
sızı içerden dinmez
ölüm yıkım ve sevda
yaşamakla başa baş
başlangıç belli belirsiz
bitim belirli nokta', 'sevdam seni durmadan can evinde yeşertir çiçekçe ve çocukça sıralı sırasız ikide bir nice yıkım nice ılgar geçer iz bırakarak nice geç kalmı...', ARRAY['Türk Edebiyatı','Şiir','Eray Canberk']::text[], 8.5, '{"poet":"Eray Canberk","poet_slug":"eray_canberk","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖTENAZİ', 'otenazi-umut-taydas-uf18x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '&quot;bitiririm kendimi&quot;
Bu günü de bitirdim görmeden seni,
bu gün de gözlerim, sensiz boş sokaklara aktı,
dalıp gittim hüzünlü şarkılarla,
bu gün de yine sensiz kapandı.
Ağlamak çare olmuyor ama ağlamamak için de tutmuyorum kendimi,
sessizce ağlıyorum sensizliğimi
içime döktüğüm gözyaşlarının içinde,
sessizce akıyor zaman,
sensiz geçiyor bilmesen de kahpe günler,
çekip gitmek var ya,
bilmediğim, bilmediğin yerlere,
çekip vurmak var ya kendimi,
yüreğimden, seni son gördüğümde,
buruk acılara terk ettiğim sevgilerimi,
bölemesinler diye,
vurup düşürmek var ya kendimi,
yapamam ki, belki bir gün daha görürüm seni.
Susarım, bilmezsin ve susarsın,
kaçarım, gelemem yanına, kendime sığınırım,
konuşmam, konuşamam ölsem de,
herkes anlar ama sen anlamazsın,
anlamadın diye kızamam sana,
anlatmadım diye ağlarım kendi içimde.
Siktir çekip vurmak var ya kendimi, bekliyorum nedense...', '&quot;bitiririm kendimi&quot; Bu günü de bitirdim görmeden seni, bu gün de gözlerim, sensiz boş sokaklara aktı, dalıp gittim hüzünlü şarkıla...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TENHÂ', 'tenh-hi-lmi-yavuz-ryb2x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her şiir boydanboya
bir ıssızlıktır artık
dizelerse giderek daha tenhâ
acının düzyazısı olmaya
hazır mı sözlerin kışı?
aşklar! onları yazan yaşasın
sarışı
n atlas kâğıtlarda yaz
ne güz okunur ağaçlar güyâ
sen sussan da susmasan da bir
tutup tutuştuğun hayale
ağırdan iri güller ve lale
düşer düştüğün melale
ve hüznü yeniden-okumak
için bir kitap olur dünya
ve her şiir boydanboya
bir ıssızlıktır artık
dizelerse giderek daha tenhâ', 'her şiir boydanboya bir ıssızlıktır artık dizelerse giderek daha tenhâ acının düzyazısı olmaya hazır mı sözlerin kışı? aşklar! onları yazan ...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TENİMDE ŞİMDİ', 'teni-mde-si-mdi-yusuf-altunel-vv111', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yayılır sesinin cıvıltıları ardısıra barışçıl kuşlar
kestaneler taşır gözlerinin ışıltısına haylaz bakışlar
şakayıklar uçuşur bala kesmiş uçlarında göğüslerinin
dudaklarını kana boyar köşe başlarından kalan kaçamaklar
bilirim, hüzün rüzgarı savurur kırık düşlerini
gümüşlü kavuşmalar kopup fırtınalı okyanuslardan
yanaklarına tuz yüklü sevişmeler yağar
yatağına aldığın o ürkek, çapkın sığınışlar
mutluluğu beklemektedir çimen kokulu tenimde şimdi', 'yayılır sesinin cıvıltıları ardısıra barışçıl kuşlar kestaneler taşır gözlerinin ışıltısına haylaz bakışlar şakayıklar uçuşur bala kesmiş uç...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TER VE KIRBAÇ', 'ter-ve-kirbac-nicolas-guillen-nb2wl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kırbaç,
ter ve kırbaç.
Güneş erkenden uyandı
ve buldu yalınayak Zenciyi.
Çıplak gövdesi kırbaçlanmış
meydanda.
Kırbaç,
ter ve kırbaç.
Rüzgâr haykıra haykıra esti:
Kara bir çiçektir her yumruk!
Kan dedi ki ona, Haydi git!
O kana dedi ki, Haydi git!
Al kanlar içinde gitti, yalınayak.
Titreyerek, kamış tarlası
Açıldı yol verdi ona.
Sonra, gökyüzü sessizliğe büründü,
ve göğün altında bir köle
her yanı boyandı efendinin kanıyla.
Kırbaç,
ter ve kırbaç,
her yanı boyandı efendinin kanıyla;
kırbaç,
ter ve kırbaç,
her yanı boyandı efendinin kanıyla,
her yanı boyandı efendinin kanıyla.
Nicolas  GUILLEN', 'Kırbaç, ter ve kırbaç. Güneş erkenden uyandı ve buldu yalınayak Zenciyi. Çıplak gövdesi kırbaçlanmış meydanda. Kırbaç, ter ve kırbaç. Rüzgâr...', ARRAY['Türk Edebiyatı','Şiir','Nicolas  Guillen']::text[], 8.5, '{"poet":"Nicolas  Guillen","poet_slug":"nicolas_guillen","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TERLETEN KELİMELER', 'terleten-keli-meler-veysel-colak-yka55', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kalabalık bir aşk bu, ortasından bir halk geçiyor
başlatarak kentleri alacakaranlıktan. Ama konumuz gökyüzü
eski bir uygarlık gibi insan. Çağ denilen morg zamanı.
Şimdi bu uykudan ayrılsam; yaşatan yanılgılar
küflü bir tarih, anıları yoran fotoğrafın arabı
duygusal kaçak tütün. Buluşur acılar değişiriz
yanlışımız aşk, konumuz bir kaçağın korkusu
oturur bir yangının dibine, terli sözcükler düşünürüz.
Kalabalık bir aşk bu, ortasından bir halk geçiyor
Yanağı karanfil bir annemi sevmiştim küçükken
alanlar kucakladı onun yerine, çocuklara büyüdük
hep öğrenciydik. Lisede şiir defteri, fakültede slogan
ölümle selamlaşırdık caddelere çıkarak.
Bütün camlarda akan kanın buğusu, özlemin koyu gölgesi
şimdi yalnız bir güvercin annem, daha çok bir kemençe sesi
Yanılgımız aşk, bir halkın yüzünden siliniyor
hızlanıyor hayat, savruluyoruz, dağılıyor yeryüzü.
Denizdeki son yunus da ölüyor. Çalılıkta bir iki serçe
öksürerek ötüyor. Tüccar, işçilere bir günü kırdırıyor
kovalıyor beni yaşadıklarım, o bahar yorgunluğu
bulduğum anlamsızlık, arkadaşlarımın keskin yanılgıları.
Yanlışımız aşk, tam ortasından bir halk geçiyor.', 'Kalabalık bir aşk bu, ortasından bir halk geçiyor başlatarak kentleri alacakaranlıktan. Ama konumuz gökyüzü eski bir uygarlık gibi insan. Ça...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel_colak","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TERSİNE MÜSLÜMAN', 'tersi-ne-musluman-sureyya-berfe-l760w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bulanık bir sabah
Güneş çoktan doğmuş ama parlamıyor
Metropolümüzün dışına - varsa - yürüyorum
Yanımdan arabalı, çoluklu çocuklu aileler geçiyor
İmanına kadar dolu trenler, vapurlar, minibüsler geçiyor
Herkes o yana gidiyor
Ben eve dönüyorum', 'Bulanık bir sabah Güneş çoktan doğmuş ama parlamıyor Metropolümüzün dışına - varsa - yürüyorum Yanımdan arabalı, çoluklu çocuklu aileler geç...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TERTEMİZ YÜREK', 'tertemi-z-yurek-attila-j-zsef-o8ben', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne anam var, ne babam.
Ne yurdum var, ne tanrım.
Ne beşiğim var, ne kefenim.
Ne sevgilim, ne aşkım, ne evim barkım.
Tam üç gün var açım,
komadım ağzıma bir lokma.
Veririm ömrümün yirmi yılını,
gücümü kuvvetimi, varımı yoğumu.
Kim alacak onları? Hiç kimse.
Şeytan isteyecek onları benden.
Bu tertemiz yüreği, bu iyi kalbi
Ne diye çalıp öldürmemeli?
Alacaklar gelip bir gün beni,
koyacaklar kutsal, karanlık toprağa.
Gelecek bir ot uzanacak alacak
şu güzelim yüreğimden gücümü.
Attila JÒZSEF', 'Ne anam var, ne babam. Ne yurdum var, ne tanrım. Ne beşiğim var, ne kefenim. Ne sevgilim, ne aşkım, ne evim barkım. Tam üç gün var açım, kom...', ARRAY['Türk Edebiyatı','Şiir','Attila Jòzsef']::text[], 8.5, '{"poet":"Attila Jòzsef","poet_slug":"attila_jozsef","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TESELLİ', 'teselli-umut-taydas-oz3c4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“en büyük tesellim, ölüme...”
Ağlamak değil ki bu, kanamak,
Yüzüme bak,
Ben ağlarken yüzüme bak.
Keskin dişleri saplandı hayatıma yokluğun,
Aslında bu hayat bit’miş çoktan,
Aslında göbek bağım, kök salmışlığımdı ölüme,
Oysa “sana doğmak” ne kadar zor
Ve bir o kadar zor doymak
Bilmez arzunun altında ezilir taze aşık,
Ne biliyorsa almış yanına, ne biriktirdiyse saklamış ceplerine,
Aşk değil bu kaçamak...
Ve sarılmak ihtiyaçtan sadece, yok bir başka özel amaç,
Çağırıyor küpeli zindan bekçileri,
Sessizliğinin diyetini ödesin diye; razı,
“Bir kere sarıldım ya” diyor, inan ölüyor,
Kimbilir nasıl da ölüyor,
Bu kış kıyamette,
Bekçilerin canı kimbilir nasıl işkence istiyor;
Ölümdür bu ve yok olmak.
Çünkü ben gördüm onları,
Kaldır başını yerden, yer yer yeme içini, yüzüme bak,
Ağlamak değil ki bu yok olmak,
Çığlıkları labirentte kaybolmuş bir çocuk gibi
Dolanıyor beynimde,
Oysa “sana doymak” ne kadar zor,
Ve bir o kadar zor doğmak
Bilmez bir bebeğin tecrübesizliğine bürünür taze aşık,
Üstelik onu öldüreceklerini bile bile
O saklanırken, sen ışık tuttun yüzüne,
Sen sevişirken o ağlıyordu,
Sen dinlenirken o ağlıyordu,
Sen giderken ağlıyordu o,
Oysa ağlamak değildi bu, çünkü
Böyle bir ağlamak bilinmiyordu,
Gelseydin, arkanı dönseydin, görseydin,
Sesine baksaydın, gözünü duysaydın,
İşte geliyor sesi,
Ağlamak değil bu yenilmek...
Kurda kuşa, eşe dosta, her halükârda yenilmek bu
Yenilmek hep aynı zaten, yok tesellisi.
Ürkek değildi arzunun süründüren bakışları,
Bin mevsimdi, kara yeldi, dinmez seldi,
Kattı kendine ne biriktirdiyse,
Harcadı seveni, bilip de bilmeyeni,
Yaşamak bir pirinç tanesinin boğaza tıkanması gibiydi,
İtelemezsen gidemezdi, itelesen belki değemezdin,
Sevdanın böbrek taşlarıydı, yetememezlik
Ve her dakika duvarlara tırnak izleri ekleniyordu taze sevenin;
Kilitliyordu kendisini.
Herkesten gizli düş biriktirdiği odaya gidiyordu,
Düşlerin
Kimini çerçeveleyip duvara asıyordu,
Kiminden makasla kendini ayırıyordu,
Kimi hastalıklı bir beden gibi can çekişiyordu,
Onları görünce oturup ağlıyordu, biliyordum,
Ağlamak değildi bu yıkılmak,
Senin o sıralar bıkmışlığın söz konusuydu,
Ayaklarına kapanıp “sana “seviyorum””
Demekten başka bir şeye gücü yetmiyordu,
Gururunu her sabah bir köpek gibi zehirliyordu,
Oysa kudurmuştu gururu bir kere,
Zindanın bekçileri onu götürmeden önce,
Paslı bir jiletle kesmiş bileklerini
Ben bulduğumda yanağı henüz ıslaktı,
Ağlamak değildi bu
Seviyordu...', '“en büyük tesellim, ölüme...” Ağlamak değil ki bu, kanamak, Yüzüme bak, Ben ağlarken yüzüme bak. Keskin dişleri saplandı hayatıma yokluğun, ...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":69}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TESTİ', 'testi-ahmet-muhip-dranas-67gpa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dolu bir testiydim ben,
Başaşağı ettiniz beni;
Eh, boşalıverdim derken...
İyi mi ettiniz yani?
Sevgiler vardı içimde
Ezgiler vardı, iyilikler...
Boşaltıverdiniz, hem de
Düşürüp kırmaktan beter.
Hoş, yine bir testiyim ben,
Yine varım ama bomboş.', 'Dolu bir testiydim ben, Başaşağı ettiniz beni; Eh, boşalıverdim derken... İyi mi ettiniz yani? Sevgiler vardı içimde Ezgiler vardı, iyilikle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dranas","poet_slug":"ahmet_muhip_dranas","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEZGAHTAR NEBAHAT', 'tezgahtar-nebahat-yusuf-hayaloglu-s3mp7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tezgahtar bir kızdı o,
Perma kırığı saçlarıyla.
Kime baksa gülümserdi,
Prova ettiği bakışlarıyla.
Haftalığından ne düşerse,
Koparıp anasının elinden,
Konserlere giderdi,
Çılgın haykırışlarıyla.Kır çiçekli bluzuyla
Poz-poz resimler çektirirdi.
Keşfedilmek için belki de,
Hep Beyoğlu''nda gezerdi.
Her akşam o pop şarkıcı,
Duvardaki posterden,
Uzanıp bir rüya gibi,
Dudağından öperdi.
Ah Nebahat, hiç görmedi rahat.
Düşünür, bulamazdı;
Kimdeydi bu kabahat?
Tezgahtar bir kızdı o,
Evi, bir kenar mahallede.
Altı kardeş, bir de ana-baba.
Babası, bir iş kazasından
Kötürüm kalmış bir usta.
Karı-kumar peşinde,
Boş vermiş abisi.
Devlete karşı gelmiş,
Diğer abisi mahpusta.
O kır çiçekli bluzuyla,
Artık resim çektirmese de
Zaman her şeyi eskitti.
Duvardan söküp posteri,
Rüyasını sandığa kilitledi.
Derken, mahalleden biriyle
Heveslendi evlenmeye;
Hayırsız çıktı oğlan,
Zengin bir dula gitti.
Ah Nebahat, ona gülmedi hayar.
Sonunda anladı ki,
Kendindeydi kabahat.', 'Tezgahtar bir kızdı o, Perma kırığı saçlarıyla. Kime baksa gülümserdi, Prova ettiği bakışlarıyla. Haftalığından ne düşerse, Koparıp anasının...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TEZGÂHTAR KIZLAR', 'tezg-htar-kizlar-refik-durbas-ogoys', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahı onlar uyandırır
çıplak yüzlerinin ufkundan
eksik yaşanmış bir rüyadan
gün doğar karanlığı kalır
Erkenden açılır dükkân
sevda ile yalnızlıktan başka
dizilir uykusuz tezgâha
ince tül, gamlı ruj ve hazan
Mevsimlik ders programları
ucuzluk, damping, tek fiyattır
sattıkları ipek pazen değil
harcanmış gençlik yıllarıdır
Günlerce raflarda kalayım
çürürse sevdanın kumaşı
aşkımı yaşatmaya yeter
tezgâhtar kızların rüzgârı
Sabahı onlar uyandırır
alınterinden, aşktan önce
bitmeden başlar gece
akşam, onlarla kararır', 'Sabahı onlar uyandırır çıplak yüzlerinin ufkundan eksik yaşanmış bir rüyadan gün doğar karanlığı kalır Erkenden açılır dükkân sevda ile yaln...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İTHAF', 'i-thaf-czeslaw-milosz-uppps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni kurtaramamıştım,
Sen kulak ver bana.
Bu yalınkat sözlerimi anlamaya çalış
Çünkü bir başkası utandırır beni.
İnan bana, söz sihirbazlığı yok bende.
Beni güçlendiren, ölüm demekti senin için
Bir çağa veda ile bir yeni çağın başlangıcını karıştırdın,
Ve nefretin ilhamı ile şiirsel güzelliği,
Kaba kuvvetle narin düzeni.
İşte sığ Polonya ırmaklarının vadisi. Apak sisin içine
Atılmış upuzun bir köprü. İşte yıkık bir kent.
Rüzgâr senin mezarına martı çığlıkları serpiyor
Ben konuşurken seninle.
Şiir nedir ki kurtarmazsa
Ulusları, insanları?
Resmi yalanların suç ortağıdır,
Az sonra gırtlakları kesilecek ayyaşların şarkısı,
Liseli kızlara eğlencelik
Güçlü şiire özlem duydum ya ne olduğunu bilmeden,
Yararlı amacını geç öğrendim ya.
Kurtuluşumu işte bunda buldum, yalnız bunda.
Darı ve haşhaş tohumları dökerlerdi mezarların üstüne
Kuş biçiminde gelen ölüleri beslemek için.
Bu kitabı buraya ben senin için koydum.
Sen eskiden yaşamıştın.
Bir daha bizi ziyaret etme diye.
Czeslaw  MILOSZ', 'Seni kurtaramamıştım, Sen kulak ver bana. Bu yalınkat sözlerimi anlamaya çalış Çünkü bir başkası utandırır beni. İnan bana, söz sihirbazlığı...', ARRAY['Türk Edebiyatı','Şiir','Czeslaw  Milosz']::text[], 8.5, '{"poet":"Czeslaw  Milosz","poet_slug":"czeslaw_milosz","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TIRAŞ OLURKEN', 'tiras-olurken-roni-margulies-a3f11', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüme dokunurdu Elsa.
Oturmuş ben kitap okumaya çalışırken.
Metroda seyrederken karşımda oturanları.
Denizden çıkmış rüzgârda üşürken.
Elsa yüzüme dokunurdu.
Rahatsız olurdum ben.
Tıraş olurken dün aynanın karşısında
aklıma geldi birden.
Duyar gibi oldum parmaklarını yüzümde,
yanaklarımda, dudaklarımda.
Düşündüm de sonra,
üç yıl olmuş;
o yüz başka yüzdü,
bu yüz başka.', 'Yüzüme dokunurdu Elsa. Oturmuş ben kitap okumaya çalışırken. Metroda seyrederken karşımda oturanları. Denizden çıkmış rüzgârda üşürken. Elsa...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜKETECEKSİN', 'tuketeceksi-n-bulent-kumral-dz88d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sevgiyi anlamak
Bir ömrü tüketir
Tüketeceksin', 'Bir sevgiyi anlamak Bir ömrü tüketir Tüketeceksin...', ARRAY['Türk Edebiyatı','Şiir','Bülent Kumral']::text[], 8.5, '{"poet":"Bülent Kumral","poet_slug":"bulent_kumral","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TİLKİLER', 'ti-lki-ler-cevahir-si-pahi-t7pni', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir akşam servileri gözlüyordum:
Güzel,
Zarif.
Birdenbire gördüğümü sandım
Yeraltına gizlenmiş tilkileri
Rüzgâr kıvırıyordu dışarı çıkmış kuyruklarını...
Tilkiler, niçin sizi düşündüm ki?
Belki de herdaim dikiliydi serviler orada
Tapılanların yanında,
Tapınakların yanında!
Cevahir  SİPAHİ', 'Bir akşam servileri gözlüyordum: Güzel, Zarif. Birdenbire gördüğümü sandım Yeraltına gizlenmiş tilkileri Rüzgâr kıvırıyordu dışarı çıkmış ku...', ARRAY['Türk Edebiyatı','Şiir','Cevahir  Si̇pahi̇']::text[], 8.5, '{"poet":"Cevahir  Si̇pahi̇","poet_slug":"cevahir_sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İTİNİZ', 'i-ti-ni-z-mustak-erenus-a471j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıraselvilere yeni dikilen
Beşyıldızlı otelin koca kapısına
''Push it'' diye yazmışlar
Elin amerikanı
İt''e puş der
Oysa bizde puşt
İki okka gaza
Koca dünyayı çocuklarıyla
Ölüme satan it''e derler', 'Sıraselvilere yeni dikilen Beşyıldızlı otelin koca kapısına ''Push it'' diye yazmışlar Elin amerikanı İt''e puş der Oysa bizde puşt İki okka ga...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOGLIATTI', 'togliatti-ahmed-ari-f-6n61q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Palmiro, Palmiro şanlı işçi
Sıcak yaralarındaki barut kokusu
kesik, anaların sütü
Ve kaçmıştır bebelerin uykusu
Koku katedrallerinde yarımadanın
Gün görmüş meydanları Roma''nın
Bizimledir
Mavi mavi eser deniz meltemi
Sicilya''nın güneşli kalçaları
Bizimle kartpostal dalgınlığında Napoli bahçeleri
Bizden yanadır hava
Bizden yanadır su
Bizden yanadır Sinyor de Gasperi''nin
Ve bütün sinyorların korkusu
Ürkmüştür manastır fareleri.
Ahmed ARİF
Şiir Refik Durbaş''ın &quot;Ahmed Arif Anlatıyor: KALBİM DİNAMİT KUYUSU&quot; adlı kitabından alınmıştır.', 'Palmiro, Palmiro şanlı işçi Sıcak yaralarındaki barut kokusu kesik, anaların sütü Ve kaçmıştır bebelerin uykusu Koku katedrallerinde yarımad...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOHUM', 'tohum-melih-cevdet-anday-ffd67', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dörtnala haberci ilkyazdan
Aşağıdan inceden beyazdan
Dumanı tüten sıcak tohum
Dolan kara toprağı dolan
Ulaş yeryüzüne ak tohum
Hay gücüne kurban olduğum
Dağ taş dinlemezim hey aman
Göster o gül yüzünü göster
Önce yeşil yeşil bak tohum
Sonra sarı sarı gülüver
Donansın donansın daneler
Kız oğlan kız, alaca kına
Tarlalar sebil tek bedava
Ver güzelim ver yiğitim ver
Pir aşkına fakir aşkına
Anladım farkı neden sonra
Tohumdan başka şeymiş bitki
Bu küçük deli fişekteki
Ne ki? Ağaç mı allı pullu
Yoksa ayrık mı, başak mı ki?
Kim bilecek... kapalı kutu
Ama bulut, yağmur bulutu
Gelir kararır nerdeyse
Tohum altta nefes nefese
Kulağı gök gürültüsünde.', 'Dörtnala haberci ilkyazdan Aşağıdan inceden beyazdan Dumanı tüten sıcak tohum Dolan kara toprağı dolan Ulaş yeryüzüne ak tohum Hay gücüne ku...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOMAS''LA VEDALAŞMA', 'tomas-la-vedalasma-che-guevara-q5hv7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanadır, kuşatılmış arkadaşım,
ak dağların berrak sularına,
batık gemi düşünün seni bağladığı yere
gider ayrılık şarkım.
Uyandım bugün
yelkenlerimde kanatlanma arzusuyla,
haberleşme mumları tutuyorum
duygusuz pusulanın gösterdiği
zaman limanına giderken gemi.
Dilimi rüzgara veriyorum
sözcüklerini gergin gergin tutmak,
taze acılarından bir şeyler alıp götürmek için
yaşamakta olduğun şaşkınlıkları paylaşmaya.
Yastığını yeşerten
bahar da yitti gitti.
Ayrılışımı kastetmiyorum,
artık yol almayan gemin için diyorum.
Anlıyorum seni kırık kanatlı kırlangıç,
isterdim Kastilya çeşmesine götürmek,
başa çıkabileceğin güçle donatmak.
Olaylara eğilmiş bir doktor olsam bile
onları değitiremiyor, ancak anlayabiliyorum.
Bununla birlikte sihirli bir çözümüm var,
Bolivya''da bir madende,
belki de Şili''de, Peru veya Meksika''da
ya da yıkılmış Sonora İmpataratorluğunda,
Afrika Brezilya''sının siyahi bir limanında ya da
belki de her noktada bir kelime
öğrendiğimi sanıyorum.
Bu çözüm çok basit,
etrafıyla ilgilenme, saldır tepeye.
Birleştir genç ellerini yaşlı kayayla,
günden güne ufak dalgalar halinde
kıpırdayan kırmızı mercanlara nabzını daya.
Günün birinde, hatıram ufuğun ötesinde
bir yelkenli olsam bile
ve senin hatıran belleğimde demirleyen
bir gemi olsa bile
geleceğe doğru neşeyle yürüyen
ufuktaki kızıl yoldaşları gördüğümde
şaşkınlıkla haykırmaya başlayacak kuşluk vakti.
O korkunç ve beyaz soğukkanlı kötüler
şaşkınlığa uğramış gece gibi gerisin geri dönecekler.
İşte o zaman, dört duvar arasında
solgun şair,
evrenin şarkıcısı olacaksın
ve sen bahtı kara, ince ruhlu, hasta şair
halkın güçlü şairi olacaksın.
Che GUEVARA', 'Sanadır, kuşatılmış arkadaşım, ak dağların berrak sularına, batık gemi düşünün seni bağladığı yere gider ayrılık şarkım. Uyandım bugün yelke...', ARRAY['Türk Edebiyatı','Şiir','Che Guevara']::text[], 8.5, '{"poet":"Che Guevara","poet_slug":"che_guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":51}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOMORROW WILL BE ANOTHER DAY', 'tomorrow-will-be-another-day-nilgun-marmara-mgff5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-sevim''e-
Belki ona gideriz yarın,
Belleksiz sevgiliye,
Poplin elli korkak çocuğa,
Duyarlığı, unutkanlığının kanı
anaya-
Ona belki gideriz yarın,
Gören gözlü kör güzele,
Çılgın gülüşlü bebeğe,
Yüreği, sızlanan ruhunun göğü
yavrucağa-
Yarın gideriz belki ona,
Unutuşun türküsü, bekleyiş
tortusunda,
Esnek kokulu çiçeğe,
Kaynak bakışlı Venüs''e-
Ya nasıl dönüş sonra?', '-sevim''e- Belki ona gideriz yarın, Belleksiz sevgiliye, Poplin elli korkak çocuğa, Duyarlığı, unutkanlığının kanı anaya- Ona belki gideriz y...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Marmara']::text[], 8.5, '{"poet":"Nilgün Marmara","poet_slug":"nilgun_marmara","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOMURCUK', 'tomurcuk-sabahattin-kudret-aksal-h228g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vazgeçmededir aşkın güzelliği
Boy atarken alabildiğine gür
Düzlerde ırmaklar örneği yürür
Yeşerirken ak bademin çiçeği
Güzelliği vazgeçmededir aşkın
Dur kapısında bu masal ülkenin
Suyun ışığı kokusu yeşilin
Bırak bir deli tomurcukta kalsın
Aşkın güzelliği vazgeçmededir
Bilmediğin suların yaman dibi
Başında ilk yazın ağaçlar gibi
Bir gün daha beter büyür güçlenir.', 'Vazgeçmededir aşkın güzelliği Boy atarken alabildiğine gür Düzlerde ırmaklar örneği yürür Yeşerirken ak bademin çiçeği Güzelliği vazgeçmeded...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"sabahattin_kudret_aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOPHANE ŞİİRİ', 'tophane-si-i-ri-i-lhan-demi-raslan-k9uhq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tophane dediğim bir uzun yol
İki yanı iki sıra meyhane
Yüz insan gördüm yüzü de başka
Benzetemedim birbirine.
Biri terlemiş ter kokuyor
Alacalı mendil sarmış başına
Biri kadın demiş bir akşam
Türlü işler açmış başına.
Biri çingenedir keman çalar kahvede
Biri oyuncudur zilli maşa takınır
Biri Trabzon''dan gelmiştir
Durur bakınır.
Biri kaptandır poyraz yemiş yüzüne
Marangozdur, çıraktır, demircidir.
Biri keyfimin kâhyasıdır
Biri bilmem necidir.
Biri şarkıcıdır Aile bahçesinde
İyi kızdır, namusludur
Biri türkü söyler sarhoşluk üstüne
Gönlümüz olur.
Biri der ben vuruldum ölmedim
Hekim gelsin sarsın benim yaramı
Gidi kâfirin sevdası
Can üzredir meramı.
Biri benim komşumdur
Geceleri erkek alır koynuna
Biri orospudur vazgeçmez
Günahı boynuna.
Yoldan geçenler daha başka
Bilmiyorum nereye gittiklerini.
Ama kör çalgıcıyı tanıyorum.
Yahut terzi kızları, hizmetçileri.
Bu kızlar niye çok güler anlamıyorum
Ne konuşurlar akşama kadar.
Yahut neden böyle hepsi birden
Pencerelerden bakar.
Onların gülmelerine bayılıyorum
Kim bilir ne güzel şeyler düşünürler
İlahi terzi kızlar
İlahi hizmetçiler.
Tophaneden çıktım yola selamet
Girdim kahvelerden birine
Ben bu şiiri böyle duydum söyledim
İnsanlar üzerine.', 'Tophane dediğim bir uzun yol İki yanı iki sıra meyhane Yüz insan gördüm yüzü de başka Benzetemedim birbirine. Biri terlemiş ter kokuyor Alac...', ARRAY['Türk Edebiyatı','Şiir','İlhan Demi̇raslan']::text[], 8.5, '{"poet":"İlhan Demi̇raslan","poet_slug":"ilhan_demiraslan","theme":"Türk Şiiri","is_hero":false,"total_lines":46}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOPRAĞA DÜŞEN', 'topraga-dusen-ataol-behramoglu-lt0dr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ona &quot;Haydi
Savaşa dediler
Başkaca birşey
Söylemediler
Aldılar köyünden
Davulla zurnayla
Geride üç çocuk
Bir eş ve bir ana
Eline bir silah
Tutuşturdular
Ve karşılaştı
Düşman ordular
Vurulup düştü
İlk çatışmada
Göğsünde bir oyuk
Üç delik alnında
&quot;Ey bu topraklar için
Toprağa düşen&quot;
Bir karış toprağın
Var mıydı yaşarken?', 'Ona &quot;Haydi Savaşa dediler Başkaca birşey Söylemediler Aldılar köyünden Davulla zurnayla Geride üç çocuk Bir eş ve bir ana Eline bir sil...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol_behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOROS DAĞLARI', 'toros-daglari-henrik-nordbrandt-5gzvs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neyi yeğleyeyim, bilmiyorum:
Seni mi, sevgilim, Toros Dağlarına,
Toros dağlarını mı yoksa güllere.
O kadar güzel ki Toros Dağları;
Gülleri o kadar al, o kadar kokulu ki!
İşte seni tam o kadar seviyorum.
Henrik NORDBRANDT', 'Neyi yeğleyeyim, bilmiyorum: Seni mi, sevgilim, Toros Dağlarına, Toros dağlarını mı yoksa güllere. O kadar güzel ki Toros Dağları; Gülleri o...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOROSLAR', 'toroslar-henrik-nordbrandt-cys1o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem hangi birini yeğlemeli
Seni mi sevdiceğim, Toroslara
yoksa Torosları mı güllere
öyle güzel ki Toros dağları
öyle kırmızı ve mis kokuyor ki güller.
Seviyorum seni öylesine.
Henrik NORDBRANDT', 'Bilmem hangi birini yeğlemeli Seni mi sevdiceğim, Toroslara yoksa Torosları mı güllere öyle güzel ki Toros dağları öyle kırmızı ve mis kokuy...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOSCANA MAREMMA''SINDAN GEÇERKEN', 'toscana-maremma-sindan-gecerken-giosu-carducci-lfd9p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tatlı kasaba, senden aldım
gururumu, yüce şiirimi
nefret ve sevginin tükenmediği gönlümü
seni yeniden görmek hoplatıyor yüreğimi.
Hep aynı sıcaklığı görüyorum sende
gülmekle ağlamak arasında bocalayan gözlerimle
o sıcaklıkta buluyorum düşlerimin izlerini
gençliğin büyüsünde yitik.
Ah sevdiğim, düşlediğim boşunaymış;
hep koştum eremeden hedefe,
yarın düşeceğim artık. Ama uzaktan
barış diyor yüreğime tepelerin
kat kat bulutları, yeşil çayırıyla
sabah yağmurlarında gülerek.
Giosuè CARDUCCI', 'Tatlı kasaba, senden aldım gururumu, yüce şiirimi nefret ve sevginin tükenmediği gönlümü seni yeniden görmek hoplatıyor yüreğimi. Hep aynı s...', ARRAY['Türk Edebiyatı','Şiir','Giosuè Carducci']::text[], 8.5, '{"poet":"Giosuè Carducci","poet_slug":"giosue_carducci","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOTEMLER İÇİN GECE MÜZİĞİ', 'totemler-i-ci-n-gece-muzi-gi-huseyin-ferhad-yd2wp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tamtamlar çalıyordu. Akdeniz hışımla  Adana kıyılarına  çarpıyordu,
geceyi kanırtıyordu.  Ayın kızıl benzi atıyordu.   Mîr Hüseyin  a f r o
Asya''yı harita ve metod defterine çiziyordu,  atını Toror cangıllarına
sürüyordu, putperest atalarını arıyordu.  Aptal çocuk; Türkmenlerin
de bir kalbi  olduğunu, televizyon  kanalları  çoğaldıkça  "numune
klan"ların semavî yükselişini durdurmaya Cin Ferhad''ın medusa gü-
cünün bile yetmeyeceğini düşünemiyordu. Yıkılıyordu;  bar bar ağlı-
yordu. Hıçkırıkları tamtam seslerine karışıyordu. Görmüyordu,  ama
biliyordu/
Sihirli küre kırılıyordu. Totemler yerinden kımıldıyordu, yürüyordu.
Dünyanın dengesi bozuluyordu, sağa kayıyordu.
Oysa ''sağ'' diye bir nota yoktu ki tamtam makamlarında.', 'Tamtamlar çalıyordu. Akdeniz hışımla  Adana kıyılarına  çarpıyordu, geceyi kanırtıyordu.  Ayın kızıl benzi atıyordu.   Mîr Hüseyin  a f r o ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin  Ferhad']::text[], 8.5, '{"poet":"Hüseyin  Ferhad","poet_slug":"huseyin_ferhad","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOZ-DEM', 'toz-dem-nilgun-marmara-f82ei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kısacıktı
karşı yolculuklarımız kara
ve deniz üzerinde-
Şafağın bodrumuna inerken sen,
Hançerin ivmesiyle yükselirdim
dul pencerelere.
Azıcıktı
köpük boz
denizde ve karada
Koyu bir saatin içinden
çıkılamadı
bir an yine de!
Belki gülden
kalma bir iz yanağındaki,
Eski sabahın sarı gülünden
üzerine deli gözünü bıraktığın...
Öldüğünde,
çekmecemde duran bu göz,
incelikle çıkarılacak,
bir jiletin enginliğine,
Çözülecek gizi
O çarpık retinanın, ağ tabakanın...
Kasım, 1985', 'Kısacıktı karşı yolculuklarımız kara ve deniz üzerinde- Şafağın bodrumuna inerken sen, Hançerin ivmesiyle yükselirdim dul pencerelere. Azıcı...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Marmara']::text[], 8.5, '{"poet":"Nilgün Marmara","poet_slug":"nilgun_marmara","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOZDAN ÖNCE', 'tozdan-once-hasan-basri-unlu-om1p0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adın gitmek olalı yol kokuyorsun kadın
Ben çıplağım şimdi sen de soyunacaksın
Vakti geldi sevişeceğiz ulu orta
Son defa dokunacağım gizli güzelliğine
Korkularımla sarılacağım sana son defa
Sakınmadan abanacağız şahdamarlarımıza
İkimiz de fena kanayacağız birer damla
Sonra alacağım yangın ellerimi koynundan
Toza fırlatacağım yüzümü yolların tozuna
Ne ben olacağım ne sen ne sırların sonra', 'Adın gitmek olalı yol kokuyorsun kadın Ben çıplağım şimdi sen de soyunacaksın Vakti geldi sevişeceğiz ulu orta Son defa dokunacağım gizli gü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Ünlü']::text[], 8.5, '{"poet":"Hasan Basri Ünlü","poet_slug":"hasan_basri","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İTİRAF', 'i-ti-raf-rustu-onur-k12bn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I
Size açabilmeliydim içimi
Geceler yalnız size
Ve yüzüm kızarmadan
Çocukluğumun küçük aşklarını
Anlatabilmeliydim
Geceler yalnız size.
II
Benim de aşklarım oldu
Ve alabildiğine günahlarım.
Halbuki bigünah olmak istedim
Bütün ömrümce.
III
Anam,
Ben topaç çevirirken sokakta,
Benim güzel oğlum,
Paşa olacak derdi...
Halbuki ben hâlâ
Topaç çeviriyorum sokakta.', 'I Size açabilmeliydim içimi Geceler yalnız size Ve yüzüm kızarmadan Çocukluğumun küçük aşklarını Anlatabilmeliydim Geceler yalnız size. II B...', ARRAY['Türk Edebiyatı','Şiir','Rüştü Onur']::text[], 8.5, '{"poet":"Rüştü Onur","poet_slug":"rustu_onur","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TRAFİK MEMURLARI', 'trafi-k-memurlari-n-zim-hi-kmet-ehsby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Trafik memurları dikilmiş durur
el kol kımıldar kaşlar çatık
sopalarının ucunda hürriyetimiz
trafik memurları dikilip duracak
sokaktakiler birbirlerini sevmeği öğreninceye kadar.', 'Trafik memurları dikilmiş durur el kol kımıldar kaşlar çatık sopalarının ucunda hürriyetimiz trafik memurları dikilip duracak sokaktakiler b...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÖREN GİYSİLERİ', 'toren-gi-ysi-leri-bejan-matur-nzfdj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çürümüş donuk kalbinde bu toprakların
Gözleri gördüm.
Herkes sesiyle vardı
Ve duruşuyla gövdesinin.
Bir insanı en iyi sevişirken tanırız.
Kalbimizi birlikte çürütürken.
Ağırlaşan gövdemiz
Gece uyandırır.
Mezar gibidir avlulu evler.
Çocukluk bir uykudur. Uzun sürer.
Ve dokunmak için bir arzu
Bir arzu sürükler bizi ölüme.
Ben kendimi sınadım her gövdede
Ben kendimi bıraktım her şehirde
İçime aldım göğünü ülkelerin
Ve boşluğunu görünce kalbimin
Gitmeli dedim.
Çürümüş tören giysileri içinde
Askıda salınan kökler.
Biz denize düşürsek de ateşi
O hep yanar.
Issızlık bahşeder karanlığa. Yanar.
Tarih bir yanılgı olabilir diyor şair
İnsan bir yanılgıdır diyor tanrı.
Çok sonra
Bu toprakların kalbi kadar
Çürümüş bir sonrada
İnsan bir yanılgıdır diyor tanrı.
Ve düzeltmek için varım
Ama geciktim.
Ölü kızıl suyun dalgası
Gece yürünen yol
Ve yolcuların dağıldığı zavallı yeryüzü
Salınan beyaz kefenler
Tören giysileri.
Ve bir koşu için gerekli tek şey
Atın yelesidir.
Aslolan,
Şimdi ve burada
Çürüyüp kaldık.
Tanrı görmesin harflerimi
İnsan bir hata diyor durmadan
Ve hatasını düzeltmek için
Acı veriyor
Sadece acı.
Şubat 97,Berlin', 'Çürümüş donuk kalbinde bu toprakların Gözleri gördüm. Herkes sesiyle vardı Ve duruşuyla gövdesinin. Bir insanı en iyi sevişirken tanırız. Ka...', ARRAY['Türk Edebiyatı','Şiir','Bejan Matur']::text[], 8.5, '{"poet":"Bejan Matur","poet_slug":"bejan_matur","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TREN SESİ', 'tren-sesi-orhan-veli-243ds', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Garibim
Ne bir güzel var
Avutacak gönlümü
Bu şehirde,
Ne de tanıdık bir çehre;
Bir tren sesi
Duymaya göreyim
İki gözüm iki çeşme.', 'Garibim Ne bir güzel var Avutacak gönlümü Bu şehirde, Ne de tanıdık bir çehre; Bir tren sesi Duymaya göreyim İki gözüm iki çeşme....', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli̇']::text[], 8.5, '{"poet":"Orhan Veli̇","poet_slug":"orhan_veli_kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TRESTLE-WORK', 'trestle-work-blaise-cendrars-yaqv4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir akarsu, bir vadi çıkar önünüze bir gün bakarsınız
Tahta köprünün üstünden geçerken ileride şirket gelişir de, bunu
elbet taştan ya da demirden yapar dersiniz
Bakın böyle köprüler yapmakta Amerikalıların üstüne yoktur
Önce sağlam bir sıra taş döşenir
Sonra ilk kemer kurulur
Arkasından bir ikinci bir üçüncü bir dördüncüsü gelir
Son kemerin üstüne iki kalas atılır
İki kalas üstüne de iki ray
Bu tip sağlam yapıların ne Ermiş André''nin haçlarına ne de demirden
T çubuğuna ihtiyacı vardır
Bunlar kemerleri tutan birkaç kirişçik birkaç destekle dururlar
Hepsi bu kadar.
Al sana bir köprü
Köprülerin şahı.
Blaise  CENDRARS', 'Bir akarsu, bir vadi çıkar önünüze bir gün bakarsınız Tahta köprünün üstünden geçerken ileride şirket gelişir de, bunu elbet taştan ya da de...', ARRAY['Türk Edebiyatı','Şiir','Blaise  Cendrars']::text[], 8.5, '{"poet":"Blaise  Cendrars","poet_slug":"blaise_cendrars","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRK-YUNAN ŞİİRİ', 'turk-yunan-si-i-ri-bulent-ecevi-t-l4lh9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sıla derdine düşünce anlarsın
yunanlıyla kardeş olduğunu
bir rum şarkısı duyunca gör
gurbet elde istanbul çocuğunu
türkçenin ferah gönlünce küfretmişiz
olmuşuz kanlı bıçaklı
yine de bir sevgidir içimizde
böyle barış günlerinde saklı
bir soyun kanı olmasın varsın
damarlarımızda akan kan
içimizde şu deli rüzgâr
bir havadan
Bu yağmurla cömert
bu güneşle sıcak
gönlümüzden bahar dolusu kopan
iyilikler kucak kucak
bu sudan bu tattandır ikimizde de günah
bütün içkiler gibi zararı kadar leziz
bir iklimin meyvasından sızdırılmış
bir içkidir kötülüklerimiz
aramızda bir mavi büyü
bir sıcak deniz
kıyılarında birbirinden güzel
iki milletiz
bizimle dirilecek bir gün
Ege''nin altın çağı
yanıp yarının ateşinden
eskinin ocağı
önce bir kahkaha çalınır kulağına
sonra rum şiveli türkçeler
o Boğaz''dan söz eder
sen rakıyı hatırlarsın
Yunanlıyla kardeş olduğunu
sıla derdine düşünce anlarsın
Londra, 1947', 'sıla derdine düşünce anlarsın yunanlıyla kardeş olduğunu bir rum şarkısı duyunca gör gurbet elde istanbul çocuğunu türkçenin ferah gönlünce ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKÜ', 'turku-miguel-hern-ndez-365p5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Su kenarına götürmek istiyorum seni,
fışkıran denizi andıran türkünü dinlemeyi.
Su kenarına gideceğim sarılıp sana.
Coşup taşacaksın su gibi, coşkuyla.
Su kenarında öpüp koklamak isterim seni.
Suyun köpüğü sana gülmeyi öğretmeli.
Suyun kenarında sevmek için seni kadınım,
görmek, kucaklamak, sana sahip olmak muradım.
Denizde yitip gitmiş suyun kenarında,
ne yitirir kendini, ne çıkar ortaya.
Miguel HERNÁNDEZ', 'Su kenarına götürmek istiyorum seni, fışkıran denizi andıran türkünü dinlemeyi. Su kenarına gideceğim sarılıp sana. Coşup taşacaksın su gibi...', ARRAY['Türk Edebiyatı','Şiir','Miguel Hernández']::text[], 8.5, '{"poet":"Miguel Hernández","poet_slug":"miguel_hernandez","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKÇE''MİZ', 'turkce-mi-z-rifat-ilgaz-fm1mc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Annenden öğrendiğinle yetinme
Çocuğum, Türkçe''ni geliştir.
Dilimiz öylesine güzel ki
Durgun göllerimizce duru,
Akar sularımızca coşkulu…
Ne var ki çocuğum,
Güzellik de bakım ister!
Önce türkülerimizi öğren,
Seni büyüten ninnilerimizi belle,
Gidenlere yakılan ağıtları…
Her sözün en güzeli Türkçe''mizde,
Diline takılanları ayıkla,
Yabancı sözcükleri at!
Bak, devrim ne güzel!
Barış, ne güzel!
Dayanışma, özgürlük…
Hele bağımsızlık!
En güzeli, sevgi!
Sev Türkçe''ni, çocuğum,
Dilini sevenleri sev!
Ocak Katırı Alagöz  adlı şiir kitabından 1987
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Annenden öğrendiğinle yetinme Çocuğum, Türkçe''ni geliştir. Dilimiz öylesine güzel ki Durgun göllerimizce duru, Akar sularımızca coşkulu… Ne ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKÜLERLE YÜRÜMEK', 'turkulerle-yurumek-aydin-hati-poglu-cp27i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Coşkunun yağız atları dörtnala damarlarımda
Sarışın elleriyle yüzümü okşuyor akşam
Yağmurlu düşlere doğru yürüyoruz
Sırtımda cop böğrümde sevda yarası
Çiğ düşmüş yapraklara sevgiye ve güzel günlere
Karanlık geçiyor yüzümüzden - açlık
Sevişen kaplumbağaların çığlığını duyuyoruz
Bir türkünün ezgisine uyuyoruz
Evlerinin önü üzüm asması
Yarimin giydiği hürriyet basması
Gözlerimiz gözlerimiz bir çift mavzer namlusu
Yürüyoruz böceklerin karanlığından
Kozasını delen kelebeklerin dünyasına
Ağlamak benim insan yanımdır
Sırtımda cop böğrümde sevda yarası
İnceden ince daha söyleyemediğim bir sızı
Yürüyoruz buğulu bir fotoğrafa ve güzel günlere
Bir motor gürültüsü bir tren sesi - ayrılık
Çatlayan tohumun sesini duyuyoruz
Bir türkünün ezgisine uyuyoruz
Gün olur devran döner
Ben de sararım yari
Gözlerimizde sarı başakları umudun gözlerimizde keder
Yürüyoruz denizlerin ve bulutların üzerinden
Bütün duvarların tel örgülerin
Doğal ve yapay sınırları üzerinden
Üzerinden bütün ten renklerinin bütün kan renklerinin
Ağlayan bir gelinin rüyasına ve güzel günlere
Bahçemde bir gül kızarıyor
Sırtımda cop böğrümde sevda yarası
Doğan günün sevincini duyuyoruz
Bir türkünün ezgisine uyuyoruz
Şu karşı yaylada göç katar katar
Bir güzel sevdası serimde tüter
İnsanın insanın yüreği yumruğu kadar
Yürüyoruz yürüyoruz yürüyoruz', 'Coşkunun yağız atları dörtnala damarlarımda Sarışın elleriyle yüzümü okşuyor akşam Yağmurlu düşlere doğru yürüyoruz Sırtımda cop böğrümde se...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKİYE ŞARKISI', 'turki-ye-sarkisi-i-lhan-berk-mdc7p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin üstündedir
Ne varsa yalnızlık, fakirlik namına
Sevmek, yaşamak aşkına
Devam eden ve edecek olan adına
Nasırlı elden sarı yüzden yana
Yani ne varsa yorgun, fakir halkım adına
Senin üstünedir.
Sen âhı ekenin biçenin
Sen âhı taş kıranın, şarkı söyleyenin
Trenler ki senden geçer
Başı açık yalnayak halkım senden geçer
Türkülerin en hazinleri senin üzerinedir
Anamın, kardeşimin, kavmimin göz yaşı senin üzerinedir
Halkım arabacısı, köylüsü, ırgatıyla senindir
Ben bütün şiirlerimle halkımın.
O ovalar ne öyle, birbiri arkasına akıp durur?
O yorgun o soluk o namuslu yüzler o erkek bakışlar
O gökyüzü, sarı, kırmızı, mavi say sayabildiğin kadar
Ya o şehirler, vefakâr Antep, zalim İstanbul, kanlı Zonguldak?
Köyler, bozkırlar, kasabalar?
İnsanlar ki çıkık elmacık kemikleri acayip elleri, ayaklarıyla
durmuşlar veya yürüyorlar
Zile''de kör bir adam gelip geçen trenlere türkü söylüyor
Sıvas''dan bıçak satıcılarının sesleri geliyor
Pis, fakir o canım Kürt köyleri arkalarını dağlara dayayıp
görünmez olmuşlar
Peşleri sıra tuz gölleri, nehirler gökyüzü kayıyor.
Sen bir kenara durmuş bakıyorsun
Dağlar senin önünde gelip durur
Yol senin serine görünür
Kötüsü sana vurur rüzgârın
Eğrisi sana yağar yağmurun
Ekmeğin karası sana düşer.
Sen şu koca Türkiye toprağı
Sen Yunus''un, Karacaoğlan''ın, Pir Sultan Abdal''ın vatanı
Sen kimsesizliğimizin, büyük yalnızlığımızın, alın terinin
memleketi
Gözümüzün içindeki sarılık
Avucumuzun içindeki yara
Sen her gün biraz daha bağlandığımız
Her gün bizi bağlayan hayata
Tuzu ekmeği şiirimizin
Sen çarık, potur, kuşak
Sen çavdar ekmeği, mısır ekmeği, buğday ekmeği
Dinlenmekten yorulmuş toprak, durgun sular, ihtiyar dağlar
Karakollar, hapishaneler, okullar
Yani yirmi milyonun kederi
Yani yirmi milyonun ümidi
Sen büyük kederimiz
Sen büyük ümidimiz
Düzülse sana düzülür destan
Yakılsa sana yakılır türkü
Ama şüphesiz en insancası işin
Devam etmektir yaşamaya.
Türkiye Şarkısı', 'Senin üstündedir Ne varsa yalnızlık, fakirlik namına Sevmek, yaşamak aşkına Devam eden ve edecek olan adına Nasırlı elden sarı yüzden yana Y...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":57}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKİYE KADAR BİR ÇİÇEK', 'turki-ye-kadar-bi-r-ci-cek-ergin-gunce-n4c94', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soğuk suda çarpa çarpa yıkadım
Yüzümün niyeti bir aşk şiiri
Ayçiçeği
Gümüş çiçeği, Kavun Karpuz Mevsimi
Çiğdem: yağmur sonu çiçeği
İlk cemreden sonra bulduğumuz çiçekler
Gül güldür, Gül de güldür
Ben bu kadar anlarım bu işten
Ekinler sarardı biçtik güz geldi
Eskiden sevdiğim kızlar çiçeği
Öpemedik birbirimizi işte bunun çiçeği
Tay gibi dururdu tay gibi bir kız çiçeği
Benim poliste kaydım varmış, hohho
Poliste kaydı olmanın çiçeği
Bir dâvet olan çiçek
Süslerler eteklerini kikirdeyerek
Kaymakam evlerinde yastık çiçeği
Diz çiçeği. Türkçenin en ayıp kelimeleri
Dul, Baldız, Bizim Güveyi
Bacanak çiçeği, ayıp çiçekler
Yüzünün ve taranmanın çiçekleri
Entarin düzelirken açan çiçek
Bir dâvettir çiçek ve çok kere gidilemez
İnsanın dairede işi vardır çünkü
Amerikan polisinde bile fotoğrafım var, hah
Hangi hırsızın polisi, hani ev sahibi
İyisin sevgilim, aceleci ve sabırlı
Belki de barışa bir savaşla varılır
Çünkü işleten sevgiyi
Öfkenin kurucu meclisidir
Tarihi hızlandırmanın çiçeği
Senin saçlarında bir Macar kırmızı var
El yazması Kur''anlar
ve Benim yanaklardaki Çerkeslik
Daha bir sürü çiçekler
Senin de bir kaydın bulunmalı loy
İyisin, demek ki iyisin, sabırlı ve aceleci
Kadınlar Mevlûdu, şerbet çiçeği
Geldibirakkuşkanadıylarevân ve benim uykum
Ki güzel çiçektir her zaman
Hâfız kadınların fingirdekleri
Tüccar, telsizciler, terlikçiler
Aklımda bir kasabanın çiçeğini tamamlar
Hamamı hergün turşu kokar
Demek, düğünlerde böyle oynarlar
Gözleri duvarlara, tavana bakar
Köylerin solgun aşk çiçeği
Düğün ne kadar uzundur, Sağdıç çiçekleri
Güveyi pencereden bir silâh atar
Kızevi utanarak tarar sakalını
Göğe bir duman çiçeği salınır
Kaydımız olsa da olmasa da sevgilim, ohho
Kaç kere yıkadık birbirimizi
Ayçiçeği
İş becermişlerin yüzündeki çiçek
Kurtuluş Savaşının kaşındaki çiçek
Asyada kabaran ekmek çiçeği
Beş bin yaşından bir komutan
Sen bu kadar yüreklisin
İnce çekingenlik çiçeği
Ha dediklerinde dağda olursun
Ha diyeceklerin ağzındaki çiçek
Umudun çiçeği
Türkiye kadar bir çiçek
Yüzünün niyeti bir aşk çiçeği
Bir kalkışma yüreğindeki çiçek', 'Soğuk suda çarpa çarpa yıkadım Yüzümün niyeti bir aşk şiiri Ayçiçeği Gümüş çiçeği, Kavun Karpuz Mevsimi Çiğdem: yağmur sonu çiçeği İlk cemre...', ARRAY['Türk Edebiyatı','Şiir','Ergin Günçe']::text[], 8.5, '{"poet":"Ergin Günçe","poet_slug":"ergin_gunce","theme":"Türk Şiiri","is_hero":false,"total_lines":68}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKİYE''DEN SELÂM', 'turki-ye-den-sel-m-kemal-ozer-rbx8f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Selâm getirdim Türkiye''den
kattığı sesten dünya şarkısına
kattığı acılı sesten
acılı ve onurlu sesten selâm
1920''lerden selâm getirdim
silahlanıp dağa çıkan Anadolu''dan
şahlanan atlarından Kurtuluş Savaşı''nın
sıkılan ilk kurşundan emperyalizme
Selâm getirdim 1977''den
İstanbul''da Taksim Alanı''nda
pusuya düşenlerden 1 Mayıs''ta
selâm otuz dört ölüden
Namuslu omuzlarında geleceği
taşıyan insanlarından Türkiye''nin
grevdeki kırk bin işçiden
kırk bin maden işçisinden selâm
Paylaşanlara selâm getirdim
salkım salkım ürettiği güneşi
selâm getirdim dostuna omuzdaşına
halkımın büyük özleminden', 'Selâm getirdim Türkiye''den kattığı sesten dünya şarkısına kattığı acılı sesten acılı ve onurlu sesten selâm 1920''lerden selâm getirdim silah...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKİYEM, ANAYURDUM, SEBEBİM, ÇAREM!', 'turki-yem-anayurdum-sebebi-m-carem-yavuz-bulent-b-ki-ler-r3qjz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben, kağnılarla yaylılarla büyüdüm geldim
Çocuk yüreğimi yakan türküler dinleye dinleye.
Mahzun kağnılarla, nazlı yaylılarınla
Ve tozlu yollarınla sevdim seni Türkiye!
O tezek topladığım kırlar, yaylalar...
Başına oturduğum, yemek yediğim atandır.
Türkiye''m, anayurdum, sebebim, çarem...
Taşına toprağına vurgunluğum bundandır...
Akşam karanlığıyla başlardı kurbağalar
Susar gökyüzü kadar, dinlerdim biteviye.
Gecemi besteleyen cırcır böceklerinle.
Kurbağa seslerinle sevdim seni Türkiye!
Bir Peygamber sofrasıydı soframız:
Biraz tandır ekmeği, biraz çökelek...
Yoksulluğunla da bağlandım kaldım sana
Mecnunlar gibi üstelik.
Yağmurlar başlayınca, odalarımız damlardı
Dizlerini döve döve ağlardı anam.
Şimdi kırkikindiler boyunca sırılsıklam
Küçük kerpiç evlerin çıkmaz aklımdan!
Türkiye''m! Hasretim! Kınalı türküm!..
İç içe güzellik, uc uca kahır
Yüreğimi bin parçaya bölseler
Her parçası yine seni çağrışır.', 'Ben, kağnılarla yaylılarla büyüdüm geldim Çocuk yüreğimi yakan türküler dinleye dinleye. Mahzun kağnılarla, nazlı yaylılarınla Ve tozlu yoll...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bâki̇ler']::text[], 8.5, '{"poet":"Yavuz Bülent Bâki̇ler","poet_slug":"yavuz_bulent_bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRKİYE''NİN RUHU', 'turki-ye-ni-n-ruhu-altay-omer-erdogan-602xv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '"Uzaklarda, benim gibi yalnız ve ümitsiz
birine bırak bu mektubu oğlum;
benim gibi birisi olsun, çünkü bizim gibiler
birbirlerine ancak kötülük edebilirler."
Oğuz Atay, Korkuyu Beklerken
her şey Türkiye kadar gerçek
her şey Türkiye kadar yalan
kavanozlarda parmak izleri ve talan
tanımsız keder boşluğunda yaşanıyor her aşk
her aşk, biraz da kuşak çatışmasına kurban
bozulan dengenin hesabını tutuyor herkes
siz alışkanlıklarınızdan sorumlusunuz
ben tuhafım kendi geçmişime
pencerede gülümseyen her ses
anlatıyor bu ilkellik iklimini de
bıyıklarıyla konuşuyor provalar
pruvasında yoksulluk ve emek taşıyan gemilerde
"bu gemi nereye?" sorusuyla yıkadığın yüzün de
mektuplar dokuyor parmakları yanan bir türkünün
gömleğini kuş desenleriyle süslediği mevsimde
kentli bir akrep kuşkularıyla tutunuyor
hiç kimsenin tutunamadığı bu tutkunun
sudan nedenler dışında kalan tortusuna
hiç kimseler anlamıyor niye karanfil
yanık kokuyor kapının her kapanışında,
odalarda babasını arayan bir tarih
felsefesini ciğerlerine dolduran bir toplumun ayak izleri
öksüremediği bir aksan ile yazılıyor
ve bir kuş kanadında kırılan aşk sözleri...
her şey Türkiye kadar güzel
her şey Türkiye kadar çirkin
belki de en büyük nedeni bu sessizliğin
rüyalarıyla büyüyor yoksulların
ve dualarıyla yoksulluğu içine sindirenlerin
teraziler hüzün tartıyor
satıcıların bakışlarından kuşku imi hiç eksilmiyor
poyrazla dolduruyorum torbamı karayellerle bir bir
ve akıyor damarlarımdan kalbime doğru
o en sıcak ve öldüren zehir
bir ülkenin bilinçaltından akan ırmak
"Telâşsız görünmeye çalışan bir Kafka gibi" (1)
geçtiği her düzlemi yıkayarak ve yıkarak
ulaşıyor gözün dehlizle boy ölçüştüğü
ışığın kendi gibiliğinin bir fazlasına,
"Acıkmış bir karanlık oyuluyor önünde" (2)
herkes kendi sofrasına düşman bir pusuda
sıralanıyor heceleri aşkın, birden sonrası palavra
yolları ve yolcuları eşitliyor ayrılıklar
aynanın yoldan kısa, yolculuktan uzun olduğu
ve Türkiye adlı çiçeğin an be an solduğu
bir hava ki uzunluktan başlayıp konuşmaya
kısalıklardan kapatıyor her sözünü
yüzünden denize doğru çizgiler dökülüyor
bir hava ki bir başka aşk için gizliyor özünü
şimdi kuzeyden ya da güneyden hep yukarı bir yakarı
kuluçka ılımanlığıyla dokunuyor öfkelerin küfesine
köhne günlerden güzel gelecekler yontan marangoz gerek
zamirli tümcelere gerdanlık takan bir bakış ki aykırı
kimse açık değil kimliğine, kimse güvenmiyor cüssesine
geçiyor geçiciliğini anımsatan aynalardan tiksinerek
şimdi başka alfabelerden besleniyor herkes
"Bu bizim yatay talihimiz." (3)
kargacık burgacık tarihler düşülüyor
imzasız kefillikler gibi, borçlarımızdan utandığımız
gökyüzü kimsenin yüzüne uymuyor
hep geleceğimizi ipotek edip geçmişte rehin kaldığımız
her şey Türkiye kadar yalın
her şey Türkiye kadar karmaşık
labirentler dolaşıp sabahlara ulaşan ışık
kırılıyor en sert duyguların prizmasında
bir oyun çığlığı gibi;  - vuruldun çık!
bu köşe kapmaca oyununda kim kime denk
ortada yalandan bir kibirle oyalanan
ey Türkiye, ölümün soluğu ne renk
kırık telden kırık bir şarkı gibiyiz
meyhane masalarında kendi kanımızı içtiğimiz
ne vefalı bir yar bize, ne de şarkılarda ahenk
kırılır gideriz en ince tel gibi telve gibi biz
suçlarımızla eğitilmiş ömrün en güzel salıncağı
dostluklar sallanırdı richter kanımıza girmezden de önce
bir gece ki oturmuş hesaplaşmak için geçmişiyle
"bağışlamaya hakkımız yok geçmiş günleri" (4)
kapı açılır sonuna kadar sonsuza kadar istemsizce
içeri giren bir gölge, bir de fener gölgesinden ince
savrulur boşluğun dilinden hep ileri, hep ileri
sıtmadan ve aşktan söz açardı tüm insaflı bilgeler
sıtmadan ve aşktan korkardı o kaküllü çocuk
bir tek yüreğini savurmadı uçurum bekleyedursun
temmuz ağustosdan ve geçmiş yazlardan da soğuk
sen işte yalnız bu yüzden, sırf bu yüzden çocuksun
avuçlarında bir karınca ölüsünü andıran mutluluk
okunur en yetim harfin gündelik ürpertisiyle
bir özlemi bir şiir, bir şiri bir nehir gibi okur
unutmamak için, tutmak için bin yıllık sözünü
aşkla yıkar ömrünün bin hüzünlü yüzünü
şimdi aşklar kaldırımlarda yaprak ölüsü
"Ne kadar konuşursak o kadar bir sessizlik olur" (5)
sus ki
patlasın en büyük günün gümbürtüsü
(1) Cemal Süreya, "Göçebe", Göçebe
(2) Mehmet Mümtaz Tuzcu, "Kumulun Gölgesinde", Sevda Adıyla
(3) Can Yücel, "Kare Kökler", Ölüm ve Oğlum - Gökyokuş
(4) Kemal Özer, "Yaşamın Bizden İstediği", Sen de Katılmalısın Yaşamı Savunmaya
(5) Edip Cansever, "Medüza", Nerde Antigone
(Agora, Mayıs-Haziran 2002 )', '"Uzaklarda, benim gibi yalnız ve ümitsiz birine bırak bu mektubu oğlum; benim gibi birisi olsun, çünkü bizim gibiler birbirlerine ancak kötü...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":107}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TROYA''DA SİZ SÖZÜ GÜZELDİ ESKİDEN', 'troya-da-si-z-sozu-guzeldi-eski-den-i-lhan-berk-ighuz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Troya''da siz sözü güzeldi eskiden
Baktım öpüşündü duran baktım bungun.
Benim şimdi Hitit çağı benim yorgun
Benim ey gök çılgın uzaklığın hep ben.
Büyük sularıma sen o hep geç gelen
Beni çıktığınız gecelere tutun.
Beyaz, kağıtlarca gittiniz ya uzun
Güzelliğimde bir yarı geceler sen.
Ellerin bir daha sarı ovalarım.
Sesini dönmeyim bütün yalnızlığım
Bütün gök gök gök, o akşamlara kadar.
Güzel yalnızlığım işte dünya kadar.
Ne denizler gördüm hiç anmamışımdır
Bir sesim ben git git o binlerce yıldır.
Çivi Yazısı', 'Troya''da siz sözü güzeldi eskiden Baktım öpüşündü duran baktım bungun. Benim şimdi Hitit çağı benim yorgun Benim ey gök çılgın uzaklığın hep...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İTTİHAT VE TERAKKİ KÂTİB-İ UMUMİSİ MİTHAT ŞÜKRÜ BEY''İN HÜZNÜ', 'i-tti-hat-ve-terakki-k-ti-b-i-umumi-si-mi-that-sukru-bey-i-n-huznu-roni-margulies-9zy44', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben mebus olmak istemedim.
Malta sürgününden hemen sonraydı,
Paşa Hazretleri Ankara''ya çağırdılar.
Gittim, bitkinliğimi arzettim.
Yılların mücadelesi, esaret hayatı,
en çok da Talât''ın ölümü belki,
yıktı dedim beni, yıprandım, bittim.
Bir küçük zeytinlik alıp İzmir''de,
yerleştik Hatice''yle sessiz sakin.
İnkişaf Şirketi''ne girdim, çalışıyorum.
Uyanıp her sabah horoz sesleriyle,
kalkıp işe gidiyorum Buca''daki evimden,
akşamları da eve dönüyorum doğruca.
El etek çektim artık siyasetten iyice.
Şaşılacak şey, hemen alıştım mutemetliğe.
Ufak da bir arazisi var Selanik''te Hatice''nin,
bir halledilse şu mübadele işleri,
onun parasıyla iyice çıkacağız düzlüğe.
Dile kolay, tam otuz yıldır ilk kez,
ne peşimde Abdülhamit''in polisi var,
ne de Cemiyet''in sorumluluğu üzerimde.
Selaniği düşündüğümde zaman zaman
- o ilk gürültülü günleri Cemiyet''in,
o ateşli korkusuz acemiliğimizi -
yorgun bir hüzün kaplar içimi bir an,
çıkar evimin arkasındaki bahçeye
seyre dalarım yeşil incir ağaçlarını.
Hey gidi koca Mithat! Hey gidi devran!', 'Ben mebus olmak istemedim. Malta sürgününden hemen sonraydı, Paşa Hazretleri Ankara''ya çağırdılar. Gittim, bitkinliğimi arzettim. Yılların m...', ARRAY['Türk Edebiyatı','Şiir','Roni Margulies']::text[], 8.5, '{"poet":"Roni Margulies","poet_slug":"roni_margulies","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUHAF DUYGU', 'tuhaf-duygu-ahmet-oktay-2jqrn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolaşıyorum ne zamandır
kalbimde bir gül kesiği;
ıslak bir tülbent koy göğsüme
emsin büyüyen o siyah lekeyi;
çoktan döndüm gittiğim gurbetlerden
yine de
içimde kanayan bir sılanın sesi.', 'Dolaşıyorum ne zamandır kalbimde bir gül kesiği; ıslak bir tülbent koy göğsüme emsin büyüyen o siyah lekeyi; çoktan döndüm gittiğim gurbetle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Oktay']::text[], 8.5, '{"poet":"Ahmet Oktay","poet_slug":"ahmet_oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TURAN EMEKSİZ', 'turan-emeksi-z-enver-gokce-7j1ev', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yürüyüş eylediler sabahtan
Ilgıt ılgıt kan gider loy loy!
Dayan dizlerim dayan!
Ağla gözlerim ağla!
Namlu puşt olmuş, atayağı puşt.
Yine düşman elindeydi vatan
Bir oğul çıktı Malatya''dan:
Anası Yılmaz çağırırdı
Haram süt emmemişti anadan.
Ve Beyazıt derler bir büyük alan
Düşman sarmıştı sağı solu
Düşman çok, cephane yoktu.
Yetişmemişti daha Cemal Paşa kolu
Amandı el aman!
Tank paletleriydi alanda dönen
Kusan namlularda, kalleş ölümcül
Ve vuran ve kıran ve haykıran
Malatyalı şöyle baktı  bir
Ana baba günüydü herhal
Her yönde toz duman!
Vay anam vay!
Bu belalı başınan
Kime ne diyem
Kime ne diyem
Nerelere gidem
Ya derdime derman
Ya katlime ferman!
Başı daralınca Yılmaz''ın
Baktı atacak taşı yoktu
Baktı eli durmuş, ayağı durmuştu
Vurulmuştu.
Çıkardı yüreğini kan içinde
Çarptı kötünün kafasına
Hay bu nasıl devran?
28
Nisandı
Yavri
Hey!
Ham
Meyveyi
Kopardılar
Dalından.', 'Bir yürüyüş eylediler sabahtan Ilgıt ılgıt kan gider loy loy! Dayan dizlerim dayan! Ağla gözlerim ağla! Namlu puşt olmuş, atayağı puşt. Yine...', ARRAY['Türk Edebiyatı','Şiir','Enver Gökçe']::text[], 8.5, '{"poet":"Enver Gökçe","poet_slug":"enver_gokce","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TURAN', 'turan-yavuz-bulent-b-ki-ler-g3ob6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Sadık Kemal Tural kardeşimize-
Ben Altay dağlarından koparak geldim
Yüreğimde Türkistan''dan binbir nakış var
Çok şükür aslım da neslim de belli
Türküm müslümanım o dağlar kadar.
Dokuz tuğ taşıdım ben, dokuz davula vurdum
Dokuz evliya gücüyle yürüdüm geldim
Büyüdü benimle mübârek yurdum
Ebed-müddet bu devleti ben kurdum.
Nevruz toylarımızda ateşler tutuşturdum
Orhun''dan, Seyhun''dan, Ceyhun''dan geçtim
Yol gösterdi kükreyerek bana Bozkurt''um
Atımla hep yan yana gözelerden su içtim
Baykal''da da çimdim ben, Hazar Denizi''nde de
Toprağıma bağdaş kurup oturdum.
Ben ki Alper Tunga''ya gönül verenlerdenim
Yurt uğruna dolu dizgin göğüs gerenlerdenim
Sonra durgun sulara Bismillâhlarla
Kilim seccadesini serenlerdenim
Yani hem Alplerdenim, hem Alperenlerdenim.
Ben Türkmen''im, Özbek''im, Kazak''ım, Kırgız''ım ben
Azerbaycan Türkleriyle aynı kandanım
Kıpçakları, Uygurları aşkla duyanlardanım
Ben ki Tatarlardan, Gagavuzlardan
Çuvaşlardan, Bozkurtlardan, Oğuzlardanım.
Kalem de tuttum çok şükür, kılıç da, gül de
Güvercin bakışlı sıcak türküler de söyledim
Anlayan anladı kim olduğumu
Aman dileyeni sevdim, öfkemi yendim
Övdü büyük peygamber İstanbul Başbuğumu
Kur''an''la da müjdelendim.
Sevsem gözbebeğim olur ne varsa
Öfkelensem öfkem dağları ezer
Dilim bazan sularım çağlamasına
Bazan da bülbüllerin şakımasına benzer.
İşte bilge Tonyukuk, Kültikin, Bilge Kağan
Hepsi birbirinden daha mübârek
Süzme asaletimin nurdan kefili
İşte Dede Korkut, kaftanı ipek
Soyumun-sopumun bin yıllık dili.
Ve Yusuf Has Hacib, Mahdum Kulu, Fuzuli
Hepsi de peygamber soyunca asil
Sonra Kaşgarlı Mahmut; gönlüme düşen cemre
Ali Şir Nevaî, Gaspıralı İsmail
Şiiri bir bakraç süt gibi Yunus Emre.
Cengiz Aytmatov ki, Cengiz Dağcı ki
Ayın ondördünden sağılan huzur
Sabir Rüstemhanlı... ruh kadar eski
Ve daha binlerce nur üstüne nur.
Servetim Buhari''nin, Yusuf Hamedanî''nin
Ahmet Yesevî''nin nur servetinden
Güzelliğim, merhametim, şefkatim
Hep Şah-ı Nakşibent hazretlerinden.
Hunlardan, Göktürklerden alıp getirdim
İpek ipliğimi altın tığımı
Mintanıma minyatürler işledim durdum
Selçuklu çinisine gönül mührümü vurdum.
Osmanlı ebrusuyla süsledim yastığımı
Mustafa Kemâllerle yeni baştan doğruldum
Kim demiş 75 yaşıma bastığımı.', '-Sadık Kemal Tural kardeşimize- Ben Altay dağlarından koparak geldim Yüreğimde Türkistan''dan binbir nakış var Çok şükür aslım da neslim de b...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bâki̇ler']::text[], 8.5, '{"poet":"Yavuz Bülent Bâki̇ler","poet_slug":"yavuz_bulent_bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":62}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TURGUT UYAR', 'turgut-uyar-turgut-uyar-n65h2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ak odada oturur
Kapısı penceresinden çok
Gözlerinde yıldızlar
Serin yerde durur
Bir elinde kadeh
Öbürünü yarasına bastırır
İnşaattan ses gelir
Bir şeyi okşar gibidir
Uzanıp durmuş mahçup
Işığagöçerin şarkısı
Dönülmez dizeler içinde
Onunkiler gülaçılır
Öldüğü gün
Hepimizi işten attılar', 'Ak odada oturur Kapısı penceresinden çok Gözlerinde yıldızlar Serin yerde durur Bir elinde kadeh Öbürünü yarasına bastırır İnşaattan ses gel...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TURKUAZ', 'turkuaz-zerrin-taspinar-byttu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşlerin mavi sağanağında bir gece
sordu cesur ve yılgın
bakışıyla bir kaçak:
Seni nasıl sevmeli?
İpeksen çıldırır yüzlerce tırtıl kıvrımı
suysan tutulmaz bir uçarı nem
gülüşsen tam ortasından parçalanan bir çelik
seni nasıl sevmeli?
Düşlerin mavi sağanağında bir gece
soluğun soluğu susturduğu Afganistan
Karanlık kayalarda saklı turkuaz
kuytu mağaralarda gizemli bir fısıltı
ateşi üfleyen dudak kadar kırılgan
her damla terin pusata dönüştüğü
dünyanın gözyaşı ve isyan.
Toprağa gömülmüş kesik kollu bir heykel
renk, ses ve tatlarla yıkılan idol
akılla duygu ve çatışma ve cansıkıntısı
en ince ayrıntılarla yeniden yaratılan
çağdaş bin tanrı... bin tanrı daha.
Seni nasıl sevmeli..?
İnsanın insanı doğurduğu bir öğle vakti
- kil ya da kaburga kemiğinden değil -
mermer serinliğinden
bir ırmak akışından
kuşların ötüşünden
ışık selinden
insanın insanı doğurduğu...
Sordu cesur ve yılgın
bakışıyla bir kaçak:
Turkuaz nerden ulaşır çarşılara bilmeden
sorgulamadan geçitsizliği
seni nasıl sevmeli?
Düşlerin mavi sağanağında bir gece
anladım ne zaman düşürdüğümü
göğsünde ürküntüsüz tek denizi taşıyan
o güvercini.
Dağları da yitirdim
vitrinlerle kuşatılmış bir şehrin
salgınına kaptırıp kendimi.
Kimbilir kaç kadından birikmiş turkuaz
güneşin tutsak yanı
seni nasıl sevmeli..?', 'Düşlerin mavi sağanağında bir gece sordu cesur ve yılgın bakışıyla bir kaçak: Seni nasıl sevmeli? İpeksen çıldırır yüzlerce tırtıl kıvrımı s...', ARRAY['Türk Edebiyatı','Şiir','Zerrin Taşpinar']::text[], 8.5, '{"poet":"Zerrin Taşpinar","poet_slug":"zerrin_taspinar","theme":"Türk Şiiri","is_hero":false,"total_lines":45}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUĞRUL ASİ BALKAR', 'tugrul-asi-balkar-tugrul-asi-balkar-nt64t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Sevinç Depremi, Tuğrul Asi BALKAR, Serendip Yayınları, Ocak', 'Bir Sevinç Depremi, Tuğrul Asi BALKAR, Serendip Yayınları, Ocak...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Asi Balkar']::text[], 8.5, '{"poet":"Tuğrul Asi Balkar","poet_slug":"tugrul_asi_balkar","theme":"Türk Şiiri","is_hero":false,"total_lines":3}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUT Kİ BEN', 'tut-ki-ben-turgut-uyar-71dlb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tut ki sen bir şiiri çok iyi yazsan
ya da çok iyi bir şiir yazsan
bir saatin aralıksız işleyişi
bir çocuğun bir sokak kedisini sevişi
bilmem ki sanki güzel bir akşam gibi
onun için her akşamı iyi yaşamalıyım
yani kıskanılan onu
demek istediğim hepsi', 'tut ki sen bir şiiri çok iyi yazsan ya da çok iyi bir şiir yazsan bir saatin aralıksız işleyişi bir çocuğun bir sokak kedisini sevişi bilmem...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTKAL', 'tutkal-ali-yuce-66sqe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyandım baktım
Düşüm yastığıma yapışık
Şiir yazarken ölmüşüm
Dilime yapışık sözcükler
Çığlığım tavana yapışık
Eğilip baktım pencereden
Rüzgar damlara yapışık
Gözlerim yapışık Antakya
Ölü götürüyor üç beş kişi
Ayakları yola yapışık
Kime küsmüş nar ağacı
Çiçeklerini yere atar
Cellat üşür gölgesinde
Tere batmış darağacı
Ayakları köze yapışık
Sen nasıl baharsın böyle
Bütün kuşların tek kanatlı
Korkuları tüylerine yapışık
Ağaçların çiçek açmış
Acıları dallarına yapışık
Sen ne biçim uygarlıksın
Parmağın tetiğe yapışık
Özgülük beslersin kafeste
Kadınların çiçek açmış
Sıcaklığı vitrinlere yapışık
Bir sabah uyandım baktım
Çürük bulutların altında
Takla atıyor kirli sular
Işığa sövüyor üç beş kişi
Kimlikleri yüzlerine yapışık', 'Bir sabah uyandım baktım Düşüm yastığıma yapışık Şiir yazarken ölmüşüm Dilime yapışık sözcükler Çığlığım tavana yapışık Eğilip baktım pencer...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüce']::text[], 8.5, '{"poet":"Ali Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTSAĞIN TÜRKÜSÜ', 'tutsagin-turkusu-oguz-tansel-82c70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne korkunçtur hatırlamak uçuşunu,
Gönlünce uçan bir kuşun.
Anlamı bu mu insan oluşun?
Ayak izi, dil yankısı kirletmemiş bir dağ başına,
Bir tanrı gibi göçmek murat taşına
İçimdeki dağları birbirine vurmak;
Kalbsiz bir tanrı gibi şöyle kenarda durmak;
Özlenip aranmamak, aranıp bulunmamak.', 'Ne korkunçtur hatırlamak uçuşunu, Gönlünce uçan bir kuşun. Anlamı bu mu insan oluşun? Ayak izi, dil yankısı kirletmemiş bir dağ başına, Bir ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTSAKLAR', 'tutsaklar-ernest-hemingway-o2x7j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimisi geldi zincire vurulmuş
Pişman değil ama yorgun.
Çok  yorgun, sendeleyecek gücü bile yok.
Düşünmek ve nefret etmek bitmiş
Düşünmek ve savaşmak bitmiş.
Geri çekilmek bitmiş ve ümit etmek bitmiş.
Devası budur uzun süren bir savaşın,
Konuverir ölüm kolayca.
Şikago 1920
Ernest  HEMINGWAY', 'Kimisi geldi zincire vurulmuş Pişman değil ama yorgun. Çok  yorgun, sendeleyecek gücü bile yok. Düşünmek ve nefret etmek bitmiş Düşünmek ve ...', ARRAY['Türk Edebiyatı','Şiir','Ernest  Hemingway']::text[], 8.5, '{"poet":"Ernest  Hemingway","poet_slug":"ernest_hemingway","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTUK KULESİ', 'tutuk-kulesi-azad-ziya-eren-hg5br', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'parıldayan bir diyardı avutulan
çığlığımı bırakıp göğüne
ellerimi uzatamadığım boynuna
loş bir zamandı sunulan
sedef kemerinin
sırtı dönük siyahlığında yaşadım boyuna
yosun sürüldü suyundan
ömrünü tüketti balık dökülen pullarla
yanardağın sönmüş tanıklığıyla
ovada yel, tende ateş unutuldu
bitti toprak
yeni bir adres yaratarak
çorak sokakları terk edip eski duraklara
gitti toprak
ve kendimi bir tutuk kulesine sunarak
içime akan yeşil ovaları
çocukluğun uzak gönül kokusunu
kırık sevinçlerde unutulmuş
eski bir aşkla duyarak eksik büyüdüm!
suya üç renk düştü sabahı / üç metafor yükseldi sudan
tarihe işleyen siyah çelenk / eksilmedi kule kapımdan
su çözdü renk çözüldü
yeni bir deriyi işleyip sızlayan kemiklere
alıp başı akıtıp yaşı gitmeli
bu zaman da görüldü...', 'parıldayan bir diyardı avutulan çığlığımı bırakıp göğüne ellerimi uzatamadığım boynuna loş bir zamandı sunulan sedef kemerinin sırtı dönük s...', ARRAY['Türk Edebiyatı','Şiir','Azad Ziya Eren']::text[], 8.5, '{"poet":"Azad Ziya Eren","poet_slug":"azad_ziya_eren","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTUKLU', 'tutuklu-ahmed-ari-f-hu5z7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birden
Kurşun yemiş gibi susar
Gözbebeklerime karşı
Susar da
Açılıp yol verir şehir
Sade radyolarda bir gamlı hava
&quot;Elaziz uzun çarşı&quot;
Firarda gözüm yok
Namussuzum yok
Yok pişmanlık bir halim
Yaslanıp
Bir cigara yakmak isterim
Dumanı cevahir değer
Mağlup mu desem mahcup mu
Ama ikisi de değil
Ben garip sen güzel
Dünya umutlu
Öyle bir tuhafım bu akşamüstü
Sevgilim
Canavar götürür gibi
İki yanım
İki süngü
Ahmed ARİF', 'Birden Kurşun yemiş gibi susar Gözbebeklerime karşı Susar da Açılıp yol verir şehir Sade radyolarda bir gamlı hava &quot;Elaziz uzun çarşı&q...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTUKLUNUN GÜNLÜĞÜ''NDEN', 'tutuklunun-gunlugu-nden-attila-i-lhan-76ij4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '/ salı gecesi /
kara bir balta buldu akşam vuracak noktayı
hücreler doldu bir ıslık en yakın maçka tramvayı
kim bırakmış yalnızlığıma bu hüzzâm şarkıyı
kimin bu karanlık kimler sürgülemişler kapıyı
insan olan bağlar her koptuğu yerden yaşamayı
daktilolar camları bulutlu sorgu odalarında
didiklemez mi özgürlüğünü sansaryan hanı''nda
küflenir suyun bir bakır çalığı birikir ağzında
kendini öldürmeyi belki bin kere tasarlarsın da
bir kere aklından geçmez bitirmeden ölmek şarkıyı
gönlünde büyüttüğün o müthiş ünlem içindir ki
seni kapattıkları öyle rezil o kadar çirkindir ki
çıplak bir lâmba mısın dört duvar içindeki
ne lâmbası/söndürülen bütün ilk gençliğindir ki
gözlerin zehirlense de suç sayarsın ağlamayı
görülmez dev böceklerdir sanki büyülü duyargalar
uçaksavar ışıldakları gökyüzünde bir yanlış arar
tophane rıhtımı''nda acı acı gemiler kalkar
hücreleri akşam olur haydut öfkeleri kaplar
ezerim sanırsın vurursan tek bir yumrukta dünyayı
tutanak 2
elektrik elletirler kıvılcım yalatırlar
tuzruhu damlatırlar kulak boşluğuna
çekip alınlar kerpetenle tırnaklarını
öğrenmek istedikleri aslında bildikleridir
geceleri rüyalarına girip uykularını kaçıran
insanın insanı soyduğu derisini yüzdüğü
duruşma arası
( o varsa kırılır buzlu camları kışın
anlamı yoğunlaşır anlamsız bir yaşayışın
gerçi farkındayız adı belirsiz bir yanlışın
acaba ben çok mu esmerim o çok mu sarışın
yansımaz oldu aydınlığı yüzüme haftalardır
yazdıklarında bile gizli bir uzaklık vardır
eylem bir dağıldı mı bütün boğazlar daralır
ben başka bir erkek olurum o başka bir kadın)
gereği düşünüldü
mahcup yaseminler son balkonların süsü
özgürlük özlemleridir genişletir gönlümüzü
savcılar ağır sürgünlerden yankılansa da
bir yer gelir ki artık ne savunma içgüdüsü
ne heyecandır kalır ne de yürek üzüntüsü
yalnız bir daktilo çıplak bir masada
toplumcularız karakollarda açtık gözümüzü
verirse halklar verir tarihte hükmümüzü
gizle de yargılansak 3.ağırceza''da', '/ salı gecesi / kara bir balta buldu akşam vuracak noktayı hücreler doldu bir ıslık en yakın maçka tramvayı kim bırakmış yalnızlığıma bu hüz...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUTUNMADAN AKIYORUM', 'tutunmadan-akiyorum-tevfik-akdag-j2wft', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim en güzel annemsin
Sevinç doğuran yüreğime
Gözlerimsin benim en tatlı ışığı ile
Aydınlığı alıştıran düşünceme
Yüzümsün en duyarlı inceliğim
Onunla bakıyorum uzaktaki benliğime
Ellerimsin beyaz ipekten
Isınıyorum birden dokunsam neye
Zamanım sensin yerim de
Bir sözcükten başka neyim kendime
Neredeysem sen nasılsan
Ben de seninle cisimleniyorum öyle
Sen benim irademsin
Bıraktım aklımı sana her şeyimle
Bir gerçek arayıcısıyım ben
Tutunmadan akıyorum sevgin içinde', 'Sen benim en güzel annemsin Sevinç doğuran yüreğime Gözlerimsin benim en tatlı ışığı ile Aydınlığı alıştıran düşünceme Yüzümsün en duyarlı i...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Akdağ']::text[], 8.5, '{"poet":"Tevfik Akdağ","poet_slug":"tevfik_akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TUZAK', 'tuzak-refik-durbas-wsz34', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nefretin adresini mi soruyorsun
cinnet yağmurunda kimsesiz kuşların
rüzgârı çalınmış yalnızlığımı mı
sevdanın adresini mi soruyorsun
ayrılığı mavi, hüznü beyaz uçan
Yüzüne ay doğmakta. Seviyorum seni
sensin çılgınlığımın zalım kaynağı
elemin aşktan damıtılmış alevi
taşarken yüzünden hicranın ırmağı
zulmetin vahasını mı arıyorsun
bakışı gül sesi, gülüşü yaz açan
Yüzüne ay doğmakta. Seviyorum seni
Fırtınası çalınmış işte umudun
gençliğimin şafağı da haczedilmiş
acının ve aşkın tarihini yazmadan
su menzilinde akşam mı avlıyorsun
ikindisi kumral, baharı az olan
Yüzüne ay doğmakta. Seviyorum seni
Çile kuşatılmaz demedim mi sana
nur heykeli, gün avcısı, ay alevi
yüzü bereketli sevdalar tuzağı
kalbimin adresini mi soruyorsun
soyadı hüzünlü, adı naz anılan
Yüzüne ay doğmakta. Seviyorum seni', 'Nefretin adresini mi soruyorsun cinnet yağmurunda kimsesiz kuşların rüzgârı çalınmış yalnızlığımı mı sevdanın adresini mi soruyorsun ayrılığ...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TİZ BİR MELODİ', 'ti-z-bi-r-melodi-ozgur-ozmeral-94p0a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ses ve buhur
ardımız tiz bir melodidir
esner içimizdeki sızı
bir çocuk sesini bırakır
şehiresrik bir ses sonrası
sallanır
kırılır en ince yerinden
gök en mavi...
en can alıcı...
ve çıldırtan bir şehvetle kalır.
ölü  saatler de büyür
çocukların ayak sesleri duyulur
mevsim yangındır
sussam
tırnaklarım o kazının altında kalır
sebepsiz kapaklanır belleğim/siperim dağılır
muhbiri yok gözyaşının
ardımız tiz bir melodidir', 'ses ve buhur ardımız tiz bir melodidir esner içimizdeki sızı bir çocuk sesini bırakır şehiresrik bir ses sonrası sallanır kırılır en ince ye...', ARRAY['Türk Edebiyatı','Şiir','Özgür  Özmeral']::text[], 8.5, '{"poet":"Özgür  Özmeral","poet_slug":"ozgur_ozmeral","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜZE', 'tuze-yves-bonnefoy-112n4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ama sen, ama sen, çöl! İndir daha bir
Karanlık örtülerini o senin.
İşle şu yüreğe, ki durmasın
Bir masalsı neden gibi sessizliğini.
Gel. Kopar bir düşünce, kalır burada.
Yolu yok artık burada güzel bir ülkenin.
İlerle kıyısında şu buz kesmiş tanın,
Pay olarak aldığın düşman bir güneşten.
Ve şakı. Ağladığın iki kez ağlamaktır senin.
Şakımağa kalkınca büyük yadsımayla bir.
Gülümse, ve şakı. Sensin ona gereken,
Karanlık ışık, suları üzre onun eskiden olduğunun.
Yves BONNEFOY', 'Ama sen, ama sen, çöl! İndir daha bir Karanlık örtülerini o senin. İşle şu yüreğe, ki durmasın Bir masalsı neden gibi sessizliğini. Gel. Kop...', ARRAY['Türk Edebiyatı','Şiir','Yves Bonnefoy']::text[], 8.5, '{"poet":"Yves Bonnefoy","poet_slug":"yves_bonnefoy","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuğrul Asi BALKAR', 'tugrul-asi-balkar-tugrul-asi-balkar-wf65m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '&quot;Artık
vakit geldi! Gömleği
giydirelim,
ha, ne dersin?&quot;
Deniz''in ardında bıraktığı geçmiş
Hüseyin''in inancı
Yusuf''un aslanı
&quot;ve bir gün mutlaka&quot;
Hepsi o!
Yusuf''un ardında bıraktığı aslan
Deniz''in geçmişi
Hüseyin''in inancı
&quot;baba, her biri oğlun sayılır&quot;
Hepsi o!
Hüseyin''in ardında bıraktığı inan
Deniz''in geçmişi
Yusuf''un aslanı
&quot;ben şimdi savaşmasam,
ilerde kimse...&quot;
Hepsi o!
Artlarında bıraktıkları
Ben sen o biz siz onlar
Yaşayan
Yok kimse başka
Yok kimse artık
-Duydum Deniz''in sesini:
&quot;Türkiye''nin üç tarafı denizlerle çevrili&quot;
Yanıtladım ben de:
&quot;Türkiye''nin üç tarafı...&quot;
Hepsi o!', '&quot;Artık vakit geldi! Gömleği giydirelim, ha, ne dersin?&quot; Deniz''in ardında bıraktığı geçmiş Hüseyin''in inancı Yusuf''un aslanı &quot;...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Asi Balkar']::text[], 8.5, '{"poet":"Tuğrul Asi Balkar","poet_slug":"tugrul_asi_balkar","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU DA VAR', 'su-da-var-cemal-sureya-zfu1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir de sen koynumda yatıyorsun
Güzelsin güzelliğin mutlak amenna
Kızlığın masanın üstünde
Kocana saklıyorsun
Oysa koca da ne benim kollarım var
Soy bir portakal yedir bana dilim dilim
Ben Uzunminareliyimdir doğma büyüme
Ne yapıp yapıp denizi görmek isterim', 'Bir de sen koynumda yatıyorsun Güzelsin güzelliğin mutlak amenna Kızlığın masanın üstünde Kocana saklıyorsun Oysa koca da ne benim kollarım ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU GÖNLÜM EĞLENMEZ OLDU, VARAYIM', 'su-gonlum-eglenmez-oldu-varayim-karacaoglan-emhp3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu gönlüm eğlenmez oldu, varayım
Yollar, beni sevdiğime ulaştır
Merhaba eyleyip tavaf ettiğim
Beller, beni sevdiğime ulaştır
Gelen gider imiş şu kara yere
Mansur cana kıydı, çekildi dâra
Hakk''ın kelâmını söyleyip bile
Diller, beni sevdiğime ulaştır
Oniki imam gülbengine erişem
Anda keramet var, Hakk''a yetişem
Baharda açılıp bülbül ötüşem
Güller, beni sevdiğime ulaştır
Karac''oğlan der ki, doğru yürürler
Tamuya girmez, uçmağa girerler
El kavşurup Hakk''a karşı dururlar
Kullar, beni sevdiğime ulaştır', 'Şu gönlüm eğlenmez oldu, varayım Yollar, beni sevdiğime ulaştır Merhaba eyleyip tavaf ettiğim Beller, beni sevdiğime ulaştır Gelen gider imi...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU KALABALIKTA GÖRDÜĞÜN HERKESİN', 'su-kalabalikta-gordugun-herkesi-n-necati-cumali-k08s7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sinemalarda kalabalık sahneler görürsün
Eski esir pazarlarını hatırlatır
Güney Pasifik''te ya da Afrika''da bir liman
Kocaman gemilerin yanaştığı kıyıda
Tektük beyazın karıştığı yerli halk
Kurulmuş tezgâhların arasında dolaşır
Çarşıda pazarda her gün
Sayısız insanlarla yanyanasın
Bölük bölük geçen askerler görürsün
Hastaneler mahpusaneler önünden geçersin
Her biri kalabalığın arasına katılmış
Kiminin tramvay sürücüleri gibi ayak üstü
Kiminin hamurcular gibi tavan aralarında
Küçük yaştan katlanmakla her türlü kahra
Her türlü mihneti yüklenmekle omuzlarına
Bir gün göz açmaya kalmadan geçer ömrü
Sen ki bir âlem bile olsan tek başına
Sonunda o kalabalıktan bir kişisin
Şu kalabalıkta gördüğün herkesin
Bir kalbi var senin gibi, ya da düşünür
Herbiri bir can taşır
Sen onları tanısan da tanımasan da
Sonunda her biri ne senden iyi
Ne senden daha fena
Senin gibi bir insandır bütün kusurlarıyla', 'Sinemalarda kalabalık sahneler görürsün Eski esir pazarlarını hatırlatır Güney Pasifik''te ya da Afrika''da bir liman Kocaman gemilerin yanaşt...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU SEN', 'su-sen-tekin-gonenc-aesud', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'şu sen
içinde darağaçları büyüten
dayayıp camlara başını
şimdi ağlarsın
bilmez miyim
üstünde ay dolanır gecenin
az sonra sıyrılır çıkar kınından
o vurdumduymaz kent
ve içinde
seni terkeden çocuk
ardarda yangınlar başlar
içinin fırdönen aynalarında
her kareden fırlar bakışları
yumsan gözlerini o
açsan o
siz ki
yaylım ateşinden çıkmış
ne sevdalar yaşadınız
hiç de melez bir aydınlık değildi
bölüştüğünüz
bilinmezlere açılan o anafor
şimdi neden zorluyor sınırlarını
düşgücünün
şu sen
beti benzi kül
uçursan mı pencerelerden
hep ona sakladığın kendini
yoksa
sarsak bir hançerin ucunda
gidip gidip gelsen mi
kendi çıkmaz sokaklarında', 'şu sen içinde darağaçları büyüten dayayıp camlara başını şimdi ağlarsın bilmez miyim üstünde ay dolanır gecenin az sonra sıyrılır çıkar kını...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin_gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU SIRALAR', 'su-siralar-gurkan-kesi-ci-s1dyu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Neler geliyor neler
Aklıma şu sıralar
Şu sıralar:
Beyinlerimizin yıkandığı
Milli sıralar.
Üzerlerine
Kopyalar, şiirler
Sevgili isimleri yazıp
Altlarına sakızlarımızı
Yapıştırdığımız sıralar.
Gözleri resmi tarih
ve coğrafyadan
Başka bir şey görmeyen sıralar.
Kapılara barikatlar kurduğumuz,
Atlayıp üzerlerinden
Kavgalara girdiğimiz sıralar.
Neler geliyor aklıma
neler şu sıralar.
1996 Berlin', 'Neler geliyor neler Aklıma şu sıralar Şu sıralar: Beyinlerimizin yıkandığı Milli sıralar. Üzerlerine Kopyalar, şiirler Sevgili isimleri yazı...', ARRAY['Türk Edebiyatı','Şiir','Gürkan  Kesi̇ci̇']::text[], 8.5, '{"poet":"Gürkan  Kesi̇ci̇","poet_slug":"gurkan_kesici","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU VARNA''DA', 'su-varna-da-kemal-ozer-wou83', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I
Şu Varna''da unutmanın yolu yok
çakıl taşları gibi duracak
belleğimin dibinde
baktığı yerden denize bakmak Nâzım''ın
ellerini yakan vapuru beklemek
bir daha geçsin diye Varna önünden
ve duymak geceleri uyutmayan o özlemi
bunca yıl sonra sesinde
&quot;anayurda selâm&quot; diyen yoldaşın
II
Kurda kuşa yedirmeden getirdim
şu Varna''da yüklendiğim selâmı
şu Varna''da havuzun başında
Bir daha düşer mi oralara yolum
görür müyüm sahibini kimbilir
görür de söyler miyim ilettigimi
Tanık olsun bu şiiri okuyanlar
yazıyorum üzerimde kalmasın diye
III
Şu Varna''ya gelip de
görmemek olmaz Dikilitaşları
ve dolaşmamak aralarında,
içinizde sinsi bir umut
çıkıverecekmiş gibi Nâzım
birinin arkasından
Dikilitaşları görüp de
çevresine toplanmamak olmaz
ve fotoğraf çektirmemek içlerinden biriyle,
aramamak olmaz hangisiydi
Nâzım''la yan yana duranı
Korucu Adil''i tanıyıp da
çağırmamak olmaz çekilecek fotoğrafa
ve şaşırmamak görünce telâşını
silahı bırakmak için elinden', 'I Şu Varna''da unutmanın yolu yok çakıl taşları gibi duracak belleğimin dibinde baktığı yerden denize bakmak Nâzım''ın ellerini yakan vapuru b...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞU YALAN DÜNYAYA GELDİM GELELİ', 'su-yalan-dunyaya-geldi-m-geleli-karacaoglan-u0y3u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu yalan dünyaya geldim geleli
Tas tas içtim ağuları, sağ iken
Kahbe felek vermez benim muradım
Viran oldum, mor sünbüllü bağ iken
Aradılar, bir tenhada buldular
Yaslandılar, şıvgalarım kırdılar
Yaz bahar ayında bir od verdiler
Yandım gittim, ala karlı dağ iken
Farımaz da deli gönlüm farımaz
Akar gözlerimin yaşı kurumaz
Şimden geri benim hükmüm yürümez
Azil oldum, güzellere bey iken
Karac''oğlan der ki, bakın geline
Ömrümün yarısı gitti talana
Sual eylen bizden evvel gelene
Kim var imiş, biz burada yoğ iken', 'Şu yalan dünyaya geldim geleli Tas tas içtim ağuları, sağ iken Kahbe felek vermez benim muradım Viran oldum, mor sünbüllü bağ iken Aradılar,...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'U', 'u-i-lhan-berk-mqh0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İstanbul''da kadınlar uzun boylu
U gibi güzel.
Taşbaskısı', 'İstanbul''da kadınlar uzun boylu U gibi güzel. Taşbaskısı...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇAK YOLCULUĞU', 'ucak-yolculugu-cahit-kulebi-7u11p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir uçağım olmalı benim,
Binip üstüne, binip üstüne,
Şu dünyayı gezmeliyim,
Gidip Akdeniz kıyılarına.
Merhaba demeliyim,
Sıcak sıcak denizlerde,
Çimen gemici çocuklara.
Bir uçağım olmalı benim.
Binip üstüne, binip üstüne,
Daha uzaklara gitmeliyim,
Ta Fransa''ya, Berlin''e
Selam demeliyim dört iklimden.
Özgürlük için dövüşmeye gelenler
Ölümlü günler bitti mi?
Ölen tüfekler sustu mu?
Kazanlarda sıcak aşlar pişti mi?
Bir uçağım olmalı benim,
Binip üstüne, binip üstüne,
Diyar diyar gitmeliyim...', 'Bir uçağım olmalı benim, Binip üstüne, binip üstüne, Şu dünyayı gezmeliyim, Gidip Akdeniz kıyılarına. Merhaba demeliyim, Sıcak sıcak denizle...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi̇']::text[], 8.5, '{"poet":"Cahit Külebi̇","poet_slug":"cahit_kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇAKLAR', 'ucaklar-oktay-ri-fat-npbud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçaklar gelecekmiş
Korkum yok benim
Kâğıt gemilerim
Kurşun askerlerim hazır
Hem bunlar bozulursa
Babam yenilerini alır', 'Uçaklar gelecekmiş Korkum yok benim Kâğıt gemilerim Kurşun askerlerim hazır Hem bunlar bozulursa Babam yenilerini alır...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat']::text[], 8.5, '{"poet":"Oktay Ri̇fat","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇANALI ZÜLFİKÂR BEYE AĞIT*', 'ucanali-zulfi-k-r-beye-agit-necati-cumali-6p9u7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sağlığında yüzüne gülenler
Sofrasında ekmeğini yiyenler
Uykusunda pusu kurdular
Zülfikâr Beyi vurdular
Zülfikâr Beyi vuran Uçanalı İsmail
Cellat olmasına cellat, çingene değil
Zülfikâr Bey mertti yiğitti
Fakir ağlatmadı, mazlum ezmedi
Hile nedir, kuşku nedir bilmezdi
Korkusuz uyudu, korkusuz gezdi
Var git İsmail var git, namert kişisin
Hem sen düşün, hem de sana yol gösteren düşünsün
Varmayın üstüme yeter, beni söyletmeyin
Ben bilirim dost kim, düşman kim
Bilirim kim sinsi adımlarla peşimizde gezer de
Göz göze gelince başını eğer
Nolaydın Zülfikâr Bey nolaydın
İsmaile güvenmeyip teslim olaydın
Bu dağlar Uçana dağlarıdır
Manastır''dan Florina''ya kadar uzanır
Uçana dağlarında akan sular, uçan kuşlar
Zülfikâr Bey diye ağlaşır
Gayri İsmail netse neylese
İçine korku düşmüştür, yüzü karadır
Uçana dağlarına gözü pek, yüreği pek
Zülfikâr Bey gibi adam yaraşır
*Zülfikâr Bey, Birinci Dünya Savaşı''nda Batı Trakya''yı işgal eden düşman kuvvetlerine karşı
dağa çıkmış; savaşın sona ereceği günlerde bir gece evinde konakladığı eski kâhyası Uçanalı
İsmail tarafından uykusunda mavzerle öldürülmüş.', 'Sağlığında yüzüne gülenler Sofrasında ekmeğini yiyenler Uykusunda pusu kurdular Zülfikâr Beyi vurdular Zülfikâr Beyi vuran Uçanalı İsmail Ce...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UFAK TEFEK ŞEYLER', 'ufak-tefek-seyler-hamdi-ozyurt-rxajp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'adının yeşil olması içindeki küfünden
her sokağı çıkmaz sokak
her durağı son durak
kâbuslardan inilen bir tatil kasabası
denizleri çekilmiş, kumları hâlâ ıslak
babasız evin külfeti çürük omuzlarında
sıcak bir yatağı düşlemesi bile yasak
boyacı bir çocuk üşüyor vicdanlarda
ayakkabılara bakmaktan gözbebekleri akacak
taşrada bir istasyon, kuytular aşk buğusu
böyle giderse rayları tez aşınacak
bir damak çikolataya tav
mahallenin orospusu
kaç kişi dilini emdi, çok çabuk unutacak
burnumda gül bacısı kirli kâğıt kokusu
dost kazığı oynamaktan çuha yırtık
masa çatlak
kahveci çay suyuyla tarıyor saçlarını
ömrü yaş duvarını aştı aşacak
aklımda şifre gibi çözdüğüm komşu kızı
serseriler de olmasa kalçalarını unutacak
yanağı gamzeliydi tertemiz ışıl ışıl
terleyen kimin eliydi şimdi anımsadım bak', 'adının yeşil olması içindeki küfünden her sokağı çıkmaz sokak her durağı son durak kâbuslardan inilen bir tatil kasabası denizleri çekilmiş,...', ARRAY['Türk Edebiyatı','Şiir','Hamdi Özyurt']::text[], 8.5, '{"poet":"Hamdi Özyurt","poet_slug":"hamdi_ozyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UFKA DAMLAYAN ALINTERİ', 'ufka-damlayan-alinteri-turkan-ildeniz-hf4il', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asıl adın neydi - unutturdun
zaten ben sana hep Abbas diyordum
bir ayağın eşikteyse , tetikteydi diğeri hep.
Evet Abbas , Abbas yolcu
yine hangi iklime böyle - hangi mevsime
bu kez hangi serüvene olacaksın özne.
Çözülüp bin sevdadan
bir mavi uğruna dolaştın her çağı
karanlık sayfalarını kargılayıp , kargışlayıp dünyanın
İNSAN için - yeniden yeniden - İNSAN
durma sefer eyledin , MUT dedin , UMUT dedin
ne çok sevdim seni ben , ah sen bunu hiç bilmedin
boşladın gönül yurdunda ocağı , kucağı.
Gurbetin soykütüğünde yazılıdır adın.
Seyir defteri , zirve defteri
kaçıncı bu , kaçıncı cilt Abbas
UFKA DAMLAYAN ALINTERİ
Çölde ARUZ yürürsün , kervanın kumda KUMA
- müstef''ilün failan -
her sahrada bir vaha bulursun mutlaka ama
bulunduğun her yer sana uzak...
Böyle gidip gidip nice - sonra ki eyvah
yine aynı noktaya varmak
ve görmek işte : barış çubuğunun bir ucu silah
tanımla - yorumla - anlatımla olmaz
hüsranı yaşayan anlar ancak.
Acının ve gecenin rengi siyah
diye yolları astarlama ömrüne
siyaha inat - kendi içinde değilse
nerde aradığın SABAH...', 'Asıl adın neydi - unutturdun zaten ben sana hep Abbas diyordum bir ayağın eşikteyse , tetikteydi diğeri hep. Evet Abbas , Abbas yolcu yine h...', ARRAY['Türk Edebiyatı','Şiir','Türkan Ildeniz']::text[], 8.5, '{"poet":"Türkan Ildeniz","poet_slug":"turkan_ildeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UFUNET', 'ufunet-metin-guven-iz8dj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç kere öldüm
Doğduğum günden bu yana
Ürktüm uçurumlara benzeyen kadınlardan
Kaç kere yıkıldı cesedim onların kollarına
"Kadınlar!" diye haykırdım
- Bölük pörçük ettiniz hayatımı
Artık sadece bir ufunet arıyorum
Gelsin, sevgilim olsun yeter.', 'Kaç kere öldüm Doğduğum günden bu yana Ürktüm uçurumlara benzeyen kadınlardan Kaç kere yıkıldı cesedim onların kollarına "Kadınlar!" diye ha...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇUKUR', 'cukur-sunay-akin-yayxe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilerek mi yanına
almadın giderken
başının yastıkta
bıraktığı
çukuru
Güveniyordum
oysa ben sevgimize
vapur iskelesi
ya da tren istasyonundaki
saatin doğruluğu kadar
Beni senin gibi
bir de annem terketmişti
ki göbeğimde durur
onun yokluğundan
bana kalan
çukur', 'Bilerek mi yanına almadın giderken başının yastıkta bıraktığı çukuru Güveniyordum oysa ben sevgimize vapur iskelesi ya da tren istasyonundak...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akin']::text[], 8.5, '{"poet":"Sunay Akin","poet_slug":"sunay_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇUKUROVA', 'cukurova-arif-di-no-gg7v2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çukurova sabır ovasıdır
Lokmasını
Göç edenleri
bilir
Yakmasını
yıkmasını
boğmasını
bilir.
Çukurova sabır ovasıdır', 'Çukurova sabır ovasıdır Lokmasını Göç edenleri bilir Yakmasını yıkmasını boğmasını bilir. Çukurova sabır ovasıdır...', ARRAY['Türk Edebiyatı','Şiir','Arif Di̇no']::text[], 8.5, '{"poet":"Arif Di̇no","poet_slug":"arif_dino","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UMUMİYETLE DOĞRU HABER ALAN', 'umumi-yetle-dogru-haber-alan-suat-taser-ynzyq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UMUMİYETLE DOĞRU HABER ALAN
BİR KAYNAKTAN ÖĞRENİLDİĞİNE GÖRE
Bir yağmur
bir yağmur
bir yağmur ki
yağacakmış
Yağsa da kurtulsak', 'UMUMİYETLE DOĞRU HABER ALAN BİR KAYNAKTAN ÖĞRENİLDİĞİNE GÖRE Bir yağmur bir yağmur bir yağmur ki yağacakmış Yağsa da kurtulsak...', ARRAY['Türk Edebiyatı','Şiir','Suat Taşer']::text[], 8.5, '{"poet":"Suat Taşer","poet_slug":"suat_taser","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UMUT', 'umut-kazi-nazrul-islam-xv25m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki rastlarım sana, sevgilim,
Ufukların bir ucunda
Gökyüzünün çekildiği ve kucakladığı
Ağaç kümelerinin koyu yeşilinde
Issız çayırda
Şu uzak kulübede
Ya da köy havuzunun sakin kenarında
Belki de yapayalnız
Hafifçe gülümseyerek
Ellerimi ellerine almak için
Çıkagelirsin
Bu gökyüzü mavisinden de ötede
Peçesiz yüzün ışıldıyor
Ve bu güney rüzgârı
Senden haberler getiren
Gizli bir elçidir
Ormanlara kaçan
Yaramaz bir afacansın
Birdenbire çıkıverirsin karşıma
Ve sevgiyle öpersin gözlerimden
Orada o uzak ufukta
Görkemli ışınlarıyla güneş
Haber veriyor bütün bunları.
Kazı Nazrul ISLAM', 'Belki rastlarım sana, sevgilim, Ufukların bir ucunda Gökyüzünün çekildiği ve kucakladığı Ağaç kümelerinin koyu yeşilinde Issız çayırda Şu uz...', ARRAY['Türk Edebiyatı','Şiir','Kazı Nazrul Islam']::text[], 8.5, '{"poet":"Kazı Nazrul Islam","poet_slug":"kazi_narul_islam","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUT GECE BİTİNCE', 'unut-gece-bi-ti-nce-rabindranath-tagore-mlnjg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hadi son türkünü de söyle
Söyle son türkünü de gidelim
"Gece bitti" de - unut her şeyi
unut bunu da gece bitince.
Ben kimi sarmak isterim öyle kollarımla
Hangi düşler onlar
Tutsak edilmeyen hangi?
İşte o onmaz tutkuda ellerim
Yüreğime boşluğunu bastırıyor
Çürük çarık göğsüm bağrım
Sensiz.
Rabindranath TAGORE', 'Hadi son türkünü de söyle Söyle son türkünü de gidelim "Gece bitti" de - unut her şeyi unut bunu da gece bitince. Ben kimi sarmak isterim öy...', ARRAY['Türk Edebiyatı','Şiir','Rabindranath Tagore']::text[], 8.5, '{"poet":"Rabindranath Tagore","poet_slug":"rabindranath_tagore","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTMA!', 'unutma-egemen-berkoz-8kht7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşten korurken kendini
gölgeye çarpılma.
Ağaç büyür büyür büyür
tohum olur.
Sevgi büyür büyür büyür
gülümser.
Sevgi kabarır kabarır kabarır.
Perdeyi indir. Saati kur.
Saati kur, unutma
kendinle
buluşacaksın.
Eğleniyor musun?
Yüreğin sıcak mı?', 'Güneşten korurken kendini gölgeye çarpılma. Ağaç büyür büyür büyür tohum olur. Sevgi büyür büyür büyür gülümser. Sevgi kabarır kabarır kabar...', ARRAY['Türk Edebiyatı','Şiir','Egemen Berköz']::text[], 8.5, '{"poet":"Egemen Berköz","poet_slug":"egemen_berkoz","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTMAK YOK', 'unutmak-yok-pablo-neruda-868xf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerelerdeydin diye sorarsan
"Hep eskisi gibi", diyeceğim.
Toprağı örten taşlardan söz edeceğim,
sürdükçe kendini harcayan ırmaktan;
ben yalnız kuşların yitirdiklerini bilirim,
gerilerde kalan denizi bilirim, bir de ağlayan
ablamı.
Neden ayrı adlarla anılıyor ülkeler, neden
günler
yeni günleri izliyor? Neden koyu bir gece
birikiyor ağızda? Neden ölüler?
Nereden geliyorsun diye sorarsan bölük pörçük
kelimelerle konuşmak zorundayım,
ağzı zehir gibi yakan araçlarla,
çoğu çürümeye yüz tutmuş hayvanlarla
ve avutamadığım yüreğimle.
Andaç değil yanımızda götürdüklerimiz
unutuşta uyuklayan sarımsı kumru değil,
yaşlarla kaplı yüzler,
boğazımıza yapışan eller
ve yapraklardan sıyrılan şey:
aşınmış bir günün karanlığı
acıyı kanımızda tatmış bir günün.
İşte menekşeler, işte kırlangıçlar
bize sevinç veren ne varsa,
geçici ve küçük duyarlıkların
yan yana göründüğü süslü kartpostallarda.
Ama bu sınırın ötesine geçmeliyim,
dişlemeliyim sessizliğin çevresindeki kabuğu,
ne karşılık vereceğimi bilemem:
öyle çok ki ölüler,
ve öyle çok ki al güneşle yarılmış hendekler,
ve öyle çok ki gemilere vuran miğferler,
ve öyle çok ki öpüşlerle kilitli eller,
ve öyle çok ki unutmak istediklerim.
Pablo  NERUDA', 'Nerelerdeydin diye sorarsan "Hep eskisi gibi", diyeceğim. Toprağı örten taşlardan söz edeceğim, sürdükçe kendini harcayan ırmaktan; ben yaln...', ARRAY['Türk Edebiyatı','Şiir','Pablo  Neruda']::text[], 8.5, '{"poet":"Pablo  Neruda","poet_slug":"pablo_neruda","theme":"Türk Şiiri","is_hero":false,"total_lines":38}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTTUM', 'unuttum-i-lhami-bekir-tez-t3ib4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haydi Allahaısmarladık!
Siz gelemezsiniz benimle beraber,
Güneşlerin battığı yere gideceğim.
Bitişlerin yeniden başladığı yer.
Ne aldımsa onu doğadan aldım,
Neyim varsa doğaya vereceğim,
Kuşlar, böcekler, arılar, dalgalar,
Selamlar olsun! Aranıza geleceğim!
Tutku dinmez, susuzluğu insanın,
Hangi çeşme olursa açıp içiniz,
Değmez düşünmeye öğretilenleri,
Sevişiniz, sevişiniz, sevişiniz!
İstemem toprağa gömüldüğümü,
Yakın beni ve savurun külümü,
Baharda badem ağaçlarının üstüne,
Ben yine döneceğim yeryüzüne!', 'Haydi Allahaısmarladık! Siz gelemezsiniz benimle beraber, Güneşlerin battığı yere gideceğim. Bitişlerin yeniden başladığı yer. Ne aldımsa on...', ARRAY['Türk Edebiyatı','Şiir','İlhami Bekir Tez']::text[], 8.5, '{"poet":"İlhami Bekir Tez","poet_slug":"ilhami_bekir_tez","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTULAN', 'unutulan-mehmet-zaman-saclioglu-7wyla', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine açıldı rüzgârın kapısı
Önce kuşlar esti içeri
Havada unutulan kuşlar.
Mevsimler isim değiştirdi
Yeni karları topladı yaz
Kış çıplak kadınları.
Yatak odasının aynası
İlkin aşkı gösterdi
Sonra uzun bir kavgayı.
Kimse üzülmesin artık
Bütün şarkıları bilir ölüler
Unutulan bütün şarkıları.', 'Yine açıldı rüzgârın kapısı Önce kuşlar esti içeri Havada unutulan kuşlar. Mevsimler isim değiştirdi Yeni karları topladı yaz Kış çıplak kad...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTULAN''DAN', 'unutulan-dan-meti-n-findikci-b2t13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I
Unutulan gölgelerle başlamıştık
Aşklar yerinde durmuyor ki, açsan
Arkabahçeye bakan pencereyi
Kedi değil çocuk değil, çağırsan
Yakın bir harabeden.
Unutulan gölgelerle unuttuk
Bağdaş kurduğumuz döşekte
Baktıkça küçülüyoruz zamana
Gün boyu avluya açılan.
Unutulan avluda unutulmuş
Çamurlu çiçekler, kuşların gagası
Gözü kanlı nar ağacı ve ben
Kadim bir şehirde.
Artık unutulan çıplaklığını
Çocuk yatağımdan toplamıyorum
-Orda mısın?
Şuramda duran harabeden
Bir daha seslensen.', 'I Unutulan gölgelerle başlamıştık Aşklar yerinde durmuyor ki, açsan Arkabahçeye bakan pencereyi Kedi değil çocuk değil, çağırsan Yakın bir h...', ARRAY['Türk Edebiyatı','Şiir','Meti̇n  Findikçi']::text[], 8.5, '{"poet":"Meti̇n  Findikçi","poet_slug":"metin_findikci","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTULMAYANLAR', 'unutulmayanlar-umit-yasar-oguzcan-chscw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum, unutamayacaksın!
Ağır ağır geçecek mevsimler,
Bir bir ağıracak saçının telleri
Solacak albümde eski resimler.
Beni hatırladıkça için ürperecek,
Boşanan gözyaşlarını tutamıyacaksın.
Boşuna zorlama kendini, sevdiğim;
Biliyorum, unutamayacaksın.
Ve biliyorsun, ben de unutamayacağım,
Eskimeyecek içimde sana ait ne varsa
Şöhretmiş, servetmiş herşey geçiyor, inan
Dostluklar ve sevgiler kalıyor, kalırsa.
Sen benim gökyüzümdün, denizim, toprağımdın,
Şimdi bir hatıra olamazsın belirsiz, uzak
Biliyorsun bazı şeyler vardır elimizde olmayan
İşte öyle imkansız birşey seni unutmak.
Zannetme ki herşey bitti sevdiğim;
Birgün yeşerecek şu sararmış yapraklar.
Ve bundan sonra kim severse dünyada;
Seni ve beni hatırlayacaklar.', 'Biliyorum, unutamayacaksın! Ağır ağır geçecek mevsimler, Bir bir ağıracak saçının telleri Solacak albümde eski resimler. Beni hatırladıkça i...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit_yasar_oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTULMUŞ BİR YAZ İÇİN', 'unutulmus-bi-r-yaz-i-ci-n-haydar-ergulen-drm2q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'anımsa bizim unutulmuş bir yazımız vardı
kıyısından çocukların dokunarak geçtiği
yaz kirli denizlerin körfezine çekildi
biten o yaz mıydı düşün istersen
bir taşra melankolisine kaptır kendini
-şimdi anımsanması gereken birşeyler vardır
bir çığlık kadar sessizlik de anımsanır
hoyrat sevinçlerle sularında yüzülen
olağan duygularla yüreği örten
bir aştan geriye suskunluk kalır-
yazdan ne kaldı sana yazdan ne kaldı
birkaç dize ölü ozanların gezindiği
kimsesiz romanlara sığınan yürek ağrısı
denizle aranızda ortak dil gibi
usulca çoğalan yaz kederleri
-her zaman paylaşılan duygular vardır
yeri gelince ölümler de paylaşılır
bölüşmek bir ölümü dostluğu ve şiiri
benzemez beyaz evlerden mavi sulara
aynı pencereden iki yabancı gibi bakmaya-
yaz bitti mi diye sorma yaz çoktan bitti
yedeğinde karartılmış sevgiler taşıyarak
nasıl özlendiğine tutkunlar gibi şaşarak
korkarak geldiği yollardan geri dönmeye
sıradan geçen bir yazın yanına gitti
-bir aşkta sıradan yazlara da yer vardır
sıradan bir aşkın sözlüğü gittikçe daralır
artık ne fısıltı gibi ilk ürpertiler
ne geceyarısının büyülü güzelliği
ayrılıklar gelir kapımıza dayanır-
incelik gibi bu şiiri bıraktı yaz giderayak
bir ozan olsam bana sorulmaz derdim
sorulsa da o yazdan inceliğin hesabı
yazık ödenmemiş bir borç gibi karşımda
uçucu bir yazdan kalanların toplamı
-de ki o umutsuz duruşunun ardında
kendinden bile sakladığı yaraları
gün gelir onulmaz özlemler gibi
ıslıkla söylenen bir aşk türküsü olur
unutulmuş yazın kırgın yolcusu
sevdalı yüreğini kıyıya vurur.
1980', 'anımsa bizim unutulmuş bir yazımız vardı kıyısından çocukların dokunarak geçtiği yaz kirli denizlerin körfezine çekildi biten o yaz mıydı dü...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar_ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTULMUŞ KENT', 'unutulmus-kent-onat-kutlar-un13i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vermeme olanak yok bana verdiklerini
Ama ayrılırken bir hesaplaşma da gerekli
Geçmiş bunca güzellikten bir anı olarak
Ben seni alayım istersen sen de beni', 'Vermeme olanak yok bana verdiklerini Ama ayrılırken bir hesaplaşma da gerekli Geçmiş bunca güzellikten bir anı olarak Ben seni alayım isters...', ARRAY['Türk Edebiyatı','Şiir','Onat Kutlar']::text[], 8.5, '{"poet":"Onat Kutlar","poet_slug":"onat_kutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UNUTURSA', 'unutursa-mehmet-kiyat-4trv4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuş uçmayı
tavşan kaçmayı unutursa
Yağmur ve tohum
toprağı unutursa
Unutursa sıcaklığını güneş
Sevişmek silinirse sözcüklerden
büyür mü defne
Zeytin ağaçları denizden keserse umudunu
Gökyüzü düşmezse ırmağa gölgelerle
Ziller çalarak
ölüm kapımızda demek', 'Kuş uçmayı tavşan kaçmayı unutursa Yağmur ve tohum toprağı unutursa Unutursa sıcaklığını güneş Sevişmek silinirse sözcüklerden büyür mü defn...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kiyat']::text[], 8.5, '{"poet":"Mehmet Kiyat","poet_slug":"mehmet_kiyat","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'URLA', 'urla-necati-cumali-5pwjx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Diyelim bir masa var önümde
Elimde bardak
Oturmuş içiyorum
Bardak mı Urla mı tuttuğum?
Bardağı masaya
Tak!
Vurdum mu vurdum
Masaya dönüyorum
Urla, uzak, uzak, uzak
Diyelim oturmuş yazıyorum
Birden duruyor kalem
Bir görüntü ak kâğıtlarda
Ev ev sokak sokak
Yine Urla oluyor konum
Bir ağız mızıkam var
Üflüyorum
Re mi fa sol la
Bir es mi giriyor araya
-Ya Urla?
Bardak değil o baylar
Tak!
Masaya vurduğum
Hak arıyorum
Düpedüz hak!
Bütün mahpus kasabalar
Küçük ölü kentler
Soyulan tarla tarla
Onlardan biridir Urla!
Yavaş yavaş sarhoş oluyorum...', 'Diyelim bir masa var önümde Elimde bardak Oturmuş içiyorum Bardak mı Urla mı tuttuğum? Bardağı masaya Tak! Vurdum mu vurdum Masaya dönüyorum...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'USANDIK', 'usandik-hi-lmi-yavuz-33n7m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaz günü! sen yine kendini anlat
sense kendini yinele ey gök!
sanki akıp gitmeyen bir su
bendini
zorlar gibidir...yararsız!
kalbimse üstüste nice sevdalar
görmüş bir höyüktü ki usandık
yaz günü! ölgün ve umarsız
işte hep burdayız, ne alır
ne satarız
hangi durak, hangi subaşı,
hangi konak
yetti o kadar...yorguna yol vermeye?
dağ yolları öyle yörüktü ki usandık
yaz günü! hep aynı ve yağız
atlar çıksın diye tek düze
dolanıp dururuz
sanki tepelerde durmayıp döner
gibi akşam gibi bitkin ve kararsız
bir kuştur şimdi buruk bengisu
ve gül şiire bir yüktü ki usandık', 'yaz günü! sen yine kendini anlat sense kendini yinele ey gök! sanki akıp gitmeyen bir su bendini zorlar gibidir...yararsız! kalbimse üstüste...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'USANDIM', 'usandim-fethi-gi-ray-w6sv0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Usandım,
Yeşermemiş umutsuz bahçeyi beklemekten
Usandım,
Tarla kuşunun sesinden
Usandım,
Bu yürekten, kendimden
Usandım,
Durup durup, seni özlemekten!..', 'Usandım, Yeşermemiş umutsuz bahçeyi beklemekten Usandım, Tarla kuşunun sesinden Usandım, Bu yürekten, kendimden Usandım, Durup durup, seni ö...', ARRAY['Türk Edebiyatı','Şiir','Fethi Gi̇ray']::text[], 8.5, '{"poet":"Fethi Gi̇ray","poet_slug":"fethi_giray","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'USTA İŞİ', 'usta-i-si-ece-ayhan-ap1jr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1.Fakir kuş hiç unutmaz, kitapların yakıldığı yıldı
Kırk kapıdan birden devletle girdiğini gördük
Başsız bir at ve içindeki solgun süslü binicisinin
Dervişlere göre parçalanmış ölüm doğudan dönüyordur
Onun için ki acı bir suyla üçe bölünmüştür bir kent
2.Fakir kuş hiç unutmaz, ustaları ölmüş oğlan çocukları
Denizden çıkınca birbirlerinin saçlarını tararlardı
Ah karpuzun içindeki kesmece delikanlım İstanbul
Yüreğini utanarak saklıyor ve çürümüş çiçek kokuyorsun
Okuma parçası bir kentin üstünde kara güvercinler uçuşuyor.
3.Fakir kuş hiç unutmaz şu altın eytişimsel yasayı da
Tarihte nice ve nite şehzade bilmeden atını taşımıştır
İşte onların sandukalarında usta işi gazeller oyuludur.', '1.Fakir kuş hiç unutmaz, kitapların yakıldığı yıldı Kırk kapıdan birden devletle girdiğini gördük Başsız bir at ve içindeki solgun süslü bin...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UT', 'ut-ercument-ucari-akt0e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben yaşarsam utlar gibi yaşarım
Eski zamanlarda gül bahçelerinde
Bir orman aydınlığını getirir meyvaların
Aşkın eğilmiş mor ağzından
Ben gözlerini severim ceylanların
Kalbimi duyarım balıklar soluyunca mavilerde
Hanımelleri mantarlar kuzukulakları
Unutulmuş aşkları kırların
Ben ellerimi severim sabahleyin uyanınca
Büyülü masallar limanında
En erken kalkan gemi benim
Rüzgârımda deniz kızları', 'Ben yaşarsam utlar gibi yaşarım Eski zamanlarda gül bahçelerinde Bir orman aydınlığını getirir meyvaların Aşkın eğilmiş mor ağzından Ben göz...', ARRAY['Türk Edebiyatı','Şiir','Ercüment Uçari']::text[], 8.5, '{"poet":"Ercüment Uçari","poet_slug":"ercument_ucari","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UTANCIMI ANLATIYORUM', 'utancimi-anlatiyorum-rifat-ilgaz-cizxi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölüm hiç özenilecek şey değil
Sevgilim ölümün güzeli yok
Bir çirkin oluyor insan görme
Sevmeyi düşünmeyi unutuyor
Ölecek misin ya bir meydanda öl
Ya da dağ başında kavgan için
Böyle yatakta miskince ölme
Önce ellerden başlıyor ölmek
Hiç yarım kalmış bardak gördün mü
Kurulmuş kol saati komodinin üstünde
Kitap gördün mü az önce okunmuş
Görmedin değil mi ben çok gördüm
Bu yüzden ölemiyorum kolay kolay
Hem ölmek de nerden aklıma geliyor
İnsanlar uzayda dolaşırken
Bütün ilaçları içiyorum yarım kalmasın diye
Bütün kitapları okuyup bitiriyorum
Boyuna kuruyorum saatimi
Getirdiğin portakalları yiyorum
Sana beğendirmek zorundayım kendimi
Bilmiyorsun direnmek zorundayım
Utanırım karşında ölmekten
Yaşıyorum böyle daha iyi
(1961)
Soluk Soluğa adlı şiir kitabından 1962
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Ölüm hiç özenilecek şey değil Sevgilim ölümün güzeli yok Bir çirkin oluyor insan görme Sevmeyi düşünmeyi unutuyor Ölecek misin ya bir meydan...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UTANGAÇ KALBİM', 'utangac-kalbi-m-cenk-koyuncu-f2kps', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O. Alkaya''ya
Bak bu gece bitmezse ölüm gelir uçurumun başına
yürek söken heybetli edasıyla şu utangaç kalbimde
aşklarımı bahane edemem, aşklarım adamcasına
sözüm geçmez artık içimden gideni götüren Azrail''e!
Dünyalının işi ölümlü olmak, zaman nedensiz bir bahane
suça çekiliyor gel-gitim, kendine doğru ve içeriye tırmanıyor
devrimlerden silkindi arkadaşlarım artık sosyalizm şahane
bir bir kırıldı eski umutlar ; şimdi herkes şiirden saklanıyor!
Atlaslar değişti, atlasım postal izleriyle dolu bir Anadolu
kıvrıldım dizlerime doğru yeni bir ses için inledim
sessiz herkesin devrimi kimsesizdi, orada yalnız kaldı insanoğlu
kahraman kalktı sözlüklerden, sahi çok özledim neredesiniz?
.Altı-yedi Eylül''dü, Orhan''ı aradım ; ağlıyordu!...', 'O. Alkaya''ya Bak bu gece bitmezse ölüm gelir uçurumun başına yürek söken heybetli edasıyla şu utangaç kalbimde aşklarımı bahane edemem, aşkl...', ARRAY['Türk Edebiyatı','Şiir','Cenk  Koyuncu']::text[], 8.5, '{"poet":"Cenk  Koyuncu","poet_slug":"cenk_koyuncu","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇUŞ', 'ucus-yahya-kemal-beyatli-9kgbs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uçmakta, konmadan, kıyısız bir denizde rûh;
Benzer mi böyle bir kuşa Tufan içinde Nuh?
Üstünde gök, sürekli bulutlarla, yüklüdür;
Altında gür deniz ki ezelden köpüklüdür.
Çalkantısında dalgası bilmez nedir sayı;
Milyonca dalga sürmede milyonca dalgayı;
Hiç durmayan gürültüsü bir türküdür, geniş,
Milyonca haykırış dolu, milyonca sesleniş.
Yıldızlar ülkesinde açıldıkça yükseğe,
Başlar hayâl edindiği âlem görünmeğe.
Bir rûhu besliyen hava yalnız yukardadır.
Hulyâyı dâima uçuran duygulardadır.
Yalnız bu katta mümkün olur dâimi uçuş.
Her hamlesiyle, rûh, o çelikten kanatlı kuş,
Ufkunda bir dakika görünmeksizin kara,
Hür gökte, hür denizde uçar, hür ufuklara.', 'Uçmakta, konmadan, kıyısız bir denizde rûh; Benzer mi böyle bir kuşa Tufan içinde Nuh? Üstünde gök, sürekli bulutlarla, yüklüdür; Altında gü...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatli']::text[], 8.5, '{"poet":"Yahya Kemal Beyatli","poet_slug":"yahya_kemal_beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇUN KUŞLAR', 'ucun-kuslar-riza-tevfik-bolukbasi-d8edg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçun kuşlar uçun doğduğum yere;
Şimdi dağlarında mor sünbül vardır.
Ormanlar koynunda bir serin dere,
Dikenler içinde sarı gül vardır.
O çay ağır akar, yorgun mu bilmem?
Mehtabı hasta mı, solgun mu bilmem?
Yaslı gelin gibi mahzun mu bilmem?
Yüce dağ başında siyah tül vardır.
Orda geçti benim güzel günlerim;
O demleri anıp bugün inlerim.
Destan-ı ömrümü okur dinlerim,
İçimde oralı bir bülbül vardır.
Uçun kuşlar, uçun burda vefa yok;
Öyle akar sular, öyle hava yok;
Feryadıma karşı aks-i seda yok;
Bu yangın yerinde soğuk kül vardır.
Hey Rıza, kederin başından aşkın,
Bitip tükenmiyor elem-i aşkın,
Sende -derya gibi- daima taşkın,
Daima çalkanır bir gönül vardır.
(Serab-ı Ömrüm)', 'Uçun kuşlar uçun doğduğum yere; Şimdi dağlarında mor sünbül vardır. Ormanlar koynunda bir serin dere, Dikenler içinde sarı gül vardır. O çay...', ARRAY['Türk Edebiyatı','Şiir','Rıza Tevfik Bölükbaşi']::text[], 8.5, '{"poet":"Rıza Tevfik Bölükbaşi","poet_slug":"riza_tevfik_bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇURTMA', 'ucurtma-rifat-ilgaz-xjj5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocuklarımız neleri sevmiyorlar ki…
Uçurtmayı seviyorlar sözgelişi,
Bir havalandı mı uçurtmaları
Daha da güzelleşiyorlar.
Maviliklerde gözleri
Özgürlüğü yaşıyorlar
Uçurtmalarla birlikte.
Koparıp da iplerini hele
Bir kurtuldular mı ellerinden,
Öylesine seviniyorlar ki,
Gidiş o gidiş, bile bile…
Kızalım mı umursamayışlarına?
Kendi yaşamlarını izliyorlar boşlukta.
Onlar da birer uçurtma değil mi?
Bizim de ne süslü uçurtmalarımız vardı,
Alıp başlarını gitmediler mi?
Gözümüzden bile esirgedik
Hangi birinin ipi kaldı elimizde?
(1981)
Kulağımız Kirişte  adlı şiir kitabından 1983
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Çocuklarımız neleri sevmiyorlar ki… Uçurtmayı seviyorlar sözgelişi, Bir havalandı mı uçurtmaları Daha da güzelleşiyorlar. Maviliklerde gözle...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇURTMANIN TÜRKÜSÜ', 'ucurtmanin-turkusu-afsar-ti-muci-n-n54wf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uçurtmam geceye takıldı kaldı
Gece onu kapkara etmiş midir
Ya da götürmüş müdür uzaklarda
Sinsi sinsi parlayan bataklığa
Uçurtmamı gece yitirmiş midir
Gece uçurtmamı pisletmiş midir
Bırakmış mıdır tankların altına
Çirkin uçaklara vermiş midir
Götürün demiş midir onlara
Çocukların sevincini yaşatan
Hiçbir şey kalmasın buralarda
Baba gece uçurtmamı ne yaptı
Buraya koymuştum götürdü mü
Yoksa rüzgârlara verdi de
Onlar da olmadık bir yere mi bıraktı', 'Uçurtmam geceye takıldı kaldı Gece onu kapkara etmiş midir Ya da götürmüş müdür uzaklarda Sinsi sinsi parlayan bataklığa Uçurtmamı gece yiti...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇURUM, SU, KIRLANGIÇ', 'ucurum-su-kirlangic-sureyya-berfe-pg6k0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alnın bir uçurum
önce gözlerimin
sonra dudaklarımın düştüğü
ve her seferinde
saçlarına takılıp kaldığı bir uçurum
Serin bir su alnının kokusu
Bu çok sıcak şehirde
birdenbire önüne çıkan
yenileyen dirilten
serin bir su
Gözlerin
yükü ağır iki kırlangıç
Bana doğru kalbime doğru
uçan uçan iki kırlangıç
Kimi zaman değip geçen
kimi zaman çarpıp kalan
karanlık şeylerden aydınlıklar taşıyan
sevinçle kederi
aşkla çileyi
bugünle yarını yansıtan
iki kırlangıç', 'Alnın bir uçurum önce gözlerimin sonra dudaklarımın düştüğü ve her seferinde saçlarına takılıp kaldığı bir uçurum Serin bir su alnının kokus...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇURUM', 'ucurum-edip-cansever-8c6xf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ağaç sürüsünün
üstünden
Çok ağaçlı bir ağaç
sürüsünün üstünden
Kesilmiş limon dilimleri gibi
düşüyor güneş
Votka bardağımın içine
Benim olmayan bir sevinç
duyuyorum.
Kesiyorum durduğumuz yeri
ortasından
Ey görünüş! seni bir yerinden
hiç anlamıyorum
Dibimde değil ayaklarımın,
damarlarında
Derinliğini orda tutan, orda
harcayan
Uçsuz bucaksız bir uçurum.
Zamanla değil, bir yerde
Benim olmayan bir şeyle
yaşlanıyorum
Geçiyorum ilk şeklimi
tüketerekten
Ağır ağır yanan bir tuğla
harmanını
Billurdan sarkaçlarıyla.
Kalbim, sersemliğim benim..
Edip', 'Bir ağaç sürüsünün üstünden Çok ağaçlı bir ağaç sürüsünün üstünden Kesilmiş limon dilimleri gibi düşüyor güneş Votka bardağımın içine Benim ...', ARRAY['Türk Edebiyatı','Şiir','Edip
        Cansever']::text[], 8.5, '{"poet":"Edip\n        Cansever","poet_slug":"edip_cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UÇURUMUN YALNIZ YÜZÜNDE', 'ucurumun-yalniz-yuzunde-altay-omer-erdogan-o7alt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'maske yalnızlığı bu bizimki,
çevre denizlerden balık kokusu, korsan mavisi takıştıran
biraz solan bir çiçek, biraz açan bir dize,
hayli bizden önceki, hayli tutunmuş ve biraz somurtkan
bayılıyor çarşafı yorganı Dante ile Beatrice''e
sonra bozlakla misket arasında nice nice kamyonlarla
uğradığı her eve biraz Çalıkuşu, biraz  Picasso laciverti aşılıyor
yeniden yeniden tutuluyor  aynadaki aya
kırlangıçlar, sukuşları, karabataklar üleşiyor, roller ve kuşatmalar kitabından
"sırası gelmişken"i oynuyor, beklerken
bekleyişleri derinleştiren  bir kuyu, bir elinden tutuyor
yanıtsız sorular terkisinde ünlemler konduruyor sokak başlarına
acıyla karanfil, dostluk anımsatan tiradlardan,
ama sizi hep ben öldüm satır aralarında
ama siz hep o konuşkan sözlüğün ikiziydiniz,
kekemeydiniz yaşanmamış mutluluklardan
"kuşağımın sancısıyım,
Mardinkapı hancısıyım" yazılı bir duvardan
çokça bir çocuk sorusuyla yılkılanan tasası geçmişimin,
sizinle her çoklukta azdık, azlığımızın coşkusuydu yürümek
yürüdükçe bir okyanus yıkardı  yüzümüzü, yıkılan atlasın terzisiydi zaman,
kırık zarlarla başlamıştım oyuna
yitirmek umrunda olmayan göçebeler gibi kördüm,
sahipsiz bir kitabın karasında gölgesiyle dans eden bu provada
alışkanlıkları sonuçlara bağlayan  ne kördüğümler gördüm
uçuruma biz yakıştırdık tüm sıfatlarını
oysa molalardan alınacak çok ders vardı
kanatlarında masum ve ikircikli bir aşkı başka aşklara uçuran
şimdi kırılıyor bir öksürük alfabesiyle tüm harfler,
bir de paylaşamadığımız korkularımızdan sorumluyuz
bizden hesap sorarken tutku vebasına tutulmuş saatler
bu yalnızlığın tarihi çok eskidi
bozuk plakları güncellleştiren bir şifre gibi boynumuzda
giyotin acısıyla mayalanan şaraplar, şarabi mutluluklar eğiren
bir tadı vardı tüm yaşadıklarımızın;
uçurum bize kendini verdi.
(Adam Sanat, Mayıs 2000;Taş(ra) Baskısı, 2003)', 'maske yalnızlığı bu bizimki, çevre denizlerden balık kokusu, korsan mavisi takıştıran biraz solan bir çiçek, biraz açan bir dize, hayli bizd...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYAN', 'uyan-onan-gunoz-2yi66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uyan sevgilim, uyan!
biz burada uyurken
son sevişmemize
dipnot yapmış aşkımızı yazarlar
kar gecelerinde okunacak
mutsuz hikâyelere
uyan!..
kalbimizi çalıp
kitap kapaklarında
elele tutuşan çocuklara vermişler
daha bir sıkı tutuyorlarmış
birbirlerinin elini
ve gözlerin gibi bakıyormuş her biri
saçların gibi kokuyormuş her cümle
virgüller öyle söyledi…
U
Y
A
N
!', 'uyan sevgilim, uyan! biz burada uyurken son sevişmemize dipnot yapmış aşkımızı yazarlar kar gecelerinde okunacak mutsuz hikâyelere uyan!.. k...', ARRAY['Türk Edebiyatı','Şiir','Onan Günöz']::text[], 8.5, '{"poet":"Onan Günöz","poet_slug":"onan_gunoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYANMAYA GEÇ KALMAK', 'uyanmaya-gec-kalmak-cevahir-si-pahi-f1gd8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyanmaya geç kaldın demektir
Kurumuş çiçekleri bulduğunda, başlar boyun bükmüş.
Uyanmaya geç kaldın demektir
Aşk ardında soluk bir iz bırakıp gitmişse.
Uyanmaya geç kaldın demektir
Ölüm, kağıtlarına uzun imzasını atmışsa.
Ama uyanmalısın, yolu yok.
Cevahir  SİPAHİ', 'Uyanmaya geç kaldın demektir Kurumuş çiçekleri bulduğunda, başlar boyun bükmüş. Uyanmaya geç kaldın demektir Aşk ardında soluk bir iz bırakı...', ARRAY['Türk Edebiyatı','Şiir','Cevahir  Si̇pahi̇']::text[], 8.5, '{"poet":"Cevahir  Si̇pahi̇","poet_slug":"cevahir_sipahi","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYGARLIK', 'uygarlik-turgay-fi-sekci-urzwx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Temelinde toplugömütler
İnsan derisinden abajurların aydınlattığı odalar olan
Aç çocuk gözlerinin
Çan sesleri gibi rüzgârlarda dağılıp unutulduğu
Bir uygarlık bizimki
Bu yüzden
Kuşku duymadan sevemez kimse kimseyi
Sevinç sınırsız
Mutluluk karşılıksız
Refah, karın ve göz tokluğundan öte bir şey olamaz.
Işıklı vitrinler hiç değil
Ne de dakik işleyen hızlı trenler
Tertemiz caddelerin altı genç kemiklerle örülü
Uygarlık bize daha çok uzak
İlk insandan bu yana
Acı çektirdiğimiz kadar insanı
Mutlu kılmadıkça', 'Temelinde toplugömütler İnsan derisinden abajurların aydınlattığı odalar olan Aç çocuk gözlerinin Çan sesleri gibi rüzgârlarda dağılıp unutu...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYKU', 'uyku-ulku-tamer-su6zn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana çiçek gönderme
Bir kuş ağacı gönder
Dallarında gezinsin
Kül rengi güvercinler
Konsunlar yastığıma
Uyutmak için beni
Sırtlarında kuş tüyü
Gagalarında ninni
Kaldırıp yatağımı
Uçursunlar göklere
Kendimi yıldızlarda
Bulayım birdenbire
Bana çiçek gönderme
Bir kuş ağacı gönder
Alnıma dokunanlar
İyileşmiş desinler', 'Bana çiçek gönderme Bir kuş ağacı gönder Dallarında gezinsin Kül rengi güvercinler Konsunlar yastığıma Uyutmak için beni Sırtlarında kuş tüy...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku_tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYKULARDA', 'uykularda-enis-batur-cqk1m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '- Enis Batur''a
Neden sonra geldiler
Beklenen yağmur gibiydiler
Geldiler ve durdu bütün trenler
Soğan için zar
Kedi için fare oldular
Geldiler ve gittiler
Uykularda,
Düşlerin kuşattığı ülkelerde gezdiler
Gerildi dikenli teller.', '- Enis Batur''a Neden sonra geldiler Beklenen yağmur gibiydiler Geldiler ve durdu bütün trenler Soğan için zar Kedi için fare oldular Geldile...', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYUM', 'uyum-bulent-ecevi-t-m1wih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'halk ozanı Levnî''ye özen
boşluğa bulut buluta yağmur
yağmura toprak ne güzel uymuş
gündüze güneş güneşe tarla
tarlaya başak ne güzel uymuş
başağa buğday buğdaya insan
insana emek ne güzel uymuş
emeğe eylem eyleme yürek
yüreğe sevgi ne güzel uymuş', 'halk ozanı Levnî''ye özen boşluğa bulut buluta yağmur yağmura toprak ne güzel uymuş gündüze güneş güneşe tarla tarlaya başak ne güzel uymuş b...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYUR İKEN UYARDILAR', 'uyur-i-ken-uyardilar-ruhi-su-5l3sq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşar Kemal''in anlatımıyla, Yunus Emre, Pir Sultan
Abdal gibi şiirimizin büyük ustalarından biridir Karacaoğlan. Kökünün daha da
derinlerde olduğunu sanıyorum. Dede Korkut''tan koşma''ya ne zaman geçilmişse,
Karacaoğlan o zamandan beri sürüp gelen bir havadır. Bir söyleyiş, bir duyuş
biçimidir.
17. yüzyılda yaşadığı sanılıyor. Söylediği
sözlere, kullandığı deyimlere, türkülerinde geçen bitki ve yer isimlerine
bakılırsa, onun Adana, Kayseri, Maraş ve Gaziantep arasında yaşayan Türkmenlerden
olduğu kolayca anlaşılır. Hele bu sınır Saimbeyli, Kadirli ve Haruniye''ye doğru
daraldıkça Karacaoğlan hakkındaki bilginin daha da yoğunlaştığı görülür.
Oralarda hemen herkes Karacaoğlan hakkında birşeyler bilir.
Kadirli''nin Kırmacılı köyünde şöyle bir fıkra
dinlemiştim: Karacaoğlan bir gün, sazı sırtında, eşeğiyle giderken, karşısından
da Kars''ın kadısıyla Sis''in müftüsü gelmekteymiş. Kars, Kadirli''nin eski ismi, Sis
de Kozan''ın eski ismidir. Kars''ın kadısı Karacaoğlan''ı görünce, Sisin müftüsüne
dönmüş: ''''Bak, bunlar cehennemin itleri işte, cehennemi bunlar dolduracak, çalıp
çağırmaktan başka işleri yok bunların'''', demiş. Karacaoğlan ermiş bir kişi
olduğundan, bu sözleri duymuş. Onlara yaklaşınca başlamış eşeğini dövmeye.
Sis''in müftüsü bunu görünce dayanamamış, Karacaoğlan''a: ''''Be adam, bu hayvanın
suçu ne de bu kadar dövüyorsun onu'''', diye kızmış. Karacaoğlan da: '''' Ah müftü
efendi, ah! siz bilmezsiniz onun ne inatçı bir yezit olduğunu; ben ona yalvarıyorum:
Çal çağır da adam ol diye, o inat ediyor, ya Kars''a kadı olacam, ya Sis''e müftü
olacam diye'''', demiş.
Karacaoğlan düğünlere derneklere de çağrılır,
geleceği duyulunca sazına püsküller, sırtına çamaşırlar hazırlanırmış; konuk
olduğu yerin gelinleri kızları, ''''Karacaoğlan, çamaşırlarını çıkar da
yıkayalım'''', derler çamaşırlarını yıkarlar, arasına da gizlice hazırladıkları
yeni çamaşırları dürüp korlarmış.', 'Yaşar Kemal''in anlatımıyla, Yunus Emre, Pir Sultan Abdal gibi şiirimizin büyük ustalarından biridir Karacaoğlan. Kökünün daha da derinlerde ...', ARRAY['Türk Edebiyatı','Şiir','Ruhi Su']::text[], 8.5, '{"poet":"Ruhi Su","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYUSUN DA BÜYÜSÜN', 'uyusun-da-buyusun-rifat-ilgaz-40bxi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tüketme nefesimi, maviş kızım,
Bildiğin Türkçe kıt gelir masallarıma.
Sözden sazdan anlamazsın,
Kuştan, yapraktan haberin yok.
Biz yaşlılar neler de bilmeyiz,
Hele sen belle dilimizi.
Biliriz de güzel güzel lâf etmesini,
Çekiniriz konuşmaktan;
Yazmasını bilir, yazamayız.
Üzme beni, yum gözlerini,
Uyutacak ninnilerim yok.
Türküler mi istersin benden,
Bağrı yanık memleket türküleri,
Ne arasın bizde o ses.
Islıkla söylenir
Kaçak şarkılar mı istersin;
Bunlar size gelmez
Uykusunu kaçırır çocukların.
Sana hazır ninniler söylesem
Bahçeye kurdum, desem, salıncak,
İnanır mısın?
Ne bahçe var, ne beşik…
Bir arabacık da mı istemezdi şu asfalt?
Yorganın, yatağın iğreti,
Doğdun doğalı, ne oyun gördün,
Ne oyuncak!
Uyu benim maviş kızım.
Dem geçecek, devran geçecek,
Keloğlan murada erecek,
Sökülecek Hasbahçe''nin çitleri
Ağlayan nar gülecek!
Yaşadıkca adlı şiir kitabından 1948
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Tüketme nefesimi, maviş kızım, Bildiğin Türkçe kıt gelir masallarıma. Sözden sazdan anlamazsın, Kuştan, yapraktan haberin yok. Biz yaşlılar ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UYUYAN GÜZEL ANNEYE', 'uyuyan-guzel-anneye-ceyhun-atuf-kansu-nx5eh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anne, bahar geliyor uyansana
Çık altın eşikte bekle beni,
En güzel tılsımları buldum sana
Koklayabilmek için nefesini.
Yeni açmış şu erik hatırlatır
Bana ağaçları çok sevdiğimi,
Sevginle mi ıslanmış şu sonsuz kır,
O kara bırakmışsın gözlerini.
Gül güzel annem benim, benim rüyam
İçimden çiçekli bir yol var sana,
Senin yerine biraz ben uyusam
Anne bahar geliyor uyansana.', 'Anne, bahar geliyor uyansana Çık altın eşikte bekle beni, En güzel tılsımları buldum sana Koklayabilmek için nefesini. Yeni açmış şu erik ha...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun_atuf_kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK BİR YAZ AKŞAMINDAN GELEN MIZIKA SESİ (*)', 'uzak-bi-r-yaz-aksamindan-gelen-mizika-sesi-sabahattin-kudret-aksal-24ds7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Babamdı o… Belki de gözlerinin yemyeşil olduğunu on yedi yaşımda fark ettiğimdi. Atatürk kaşlarının altındaki ışıltılı gözleriyle sevenimdi. Hissettirmeden kollayan, koklayan, bayramdan bayrama alnımdan öpenimdi.
"Ölü mü denir şimdi O''na?" (**) O hâlâ benim babam…
"Karmaşık bahçe, güller / Kuşlar damda diziyle / Güneş mavi yüzüyle / Bakarak mayıs güler."
Sabahattin Kudret Aksal, bir şiirinde mayıs ayından böyle söz eder. Benim de en sevdiğim ay mayıs, en sevdiğim yer Didim''di bir zamanlar… Bir 19 Mayıs günü - bir bayram günü - yıldızlara uğurladım babamı Didim''de. Doğa dirilirken, babam nasıl ölürdü? Ölümden çok hayata yakışan tek insan babam, ölümün hiç yakışmadığı tek mevsim ilkbahardı bana göre… Ya
küçük İskender şu muhteşem dizeleriyle neler anlatıyor:
"…bazı sevdalarda hafızasını kaybeder ya insan / telaşlanır, ağlar / babasını sorar çevresindekilere / öldüğünü bildiği halde / adını unutur, yolunu kaybeder oturduğu evin / bir titreme gelir yerleşir ya ortasına mayısın" (***)
Bu kitabın oluşum serüvenini sizlerle paylaşmak isterim. 2001 yılında babam sesiyle, bedeniyle duyulmaz, görülmez olduktan sonra, günlerim babayla ilgili yazılar ve şiirler okumakla geçer olmuştu. Derken kızımın bir cümlesiyle bu derleme kitabına girişiverdim. O yıl, yedi yaşındaki kızımla kabristana gitmiştik. Kızım, bir rengârenk çiçeklere, bir de yanı başındaki dedesinin içinde olduğunu söylediğimiz toprak yığınına baktı ve dedi ki:
"Dedemi neden toprağa ektiler anne?" Ne diyebilirdim ki? Bu söz o gün yanıtlayamadığım bir soruyken, zamanla bu seçkinin oluşmasını sağladı. Ancak, salt acılı bir insanın babasına adadığı sıradan bir kitap olmasını istemedim. Kaynak kitap olacak düzeyde,
''baba'' bir araştırma kitabı olmalıydı.
Çağdaş Türk şiirinde baba yoğun dizeleri tararken bir gözlemim oldu.Anne ve çocuk imgelerinin çokluğuna karşın, baba o kadar sık işlenen bir konu değildi. Bu durum bende hatırı sayılır bir burukluk yarattı. Belki de beni bu seçkiyi hazırlamaya iten nedenlerden biri de budur. Seçkideki şiirlerin çoğu, baba imgesini tüm şiirde hissettiriyor. Ancak, bazı şiirlerde yalnızca bir-iki dizede baba imgesi işlenmesine karşın öyle güçlü dizelerdi ki tüm şiiri seçkiye almayı arzu ettim. Kimi şiirlerinse, uzunluğu dolayısıyla, ancak bazı bölümlerini alabildim. Tematik bir antoloji hazırlamanın zor yanlarından biri de bu olsa gerek.
Baba gibi babalar, uzaktaki babalar, sevecen babalar, bağıran babalar, artık göremediğimiz babalar… Elbet size içlerinden biri sesleniyordur. Şiirleri okurken uzak bir yaz akşamından gelen mızıka sesine kulak vermeyi unutmayın n''olur…
Vakitsiz ölümler, savaş, deprem… Yeter… Bir dirsek vursun artık buluta güneş… dileklerimle, tüm babaları saygıyla selamlıyorum.
(…)
(*) F. L. Oskay''ın, Alfa Yayınları''ndan çıkan "Hep Babam İçin" adlı Türk Edebiyatında Baba Şiirleri Antolojisi''nin Önsöz''ünden.
(**) Edip Cansever, ''Ölü mü Denir'' şiirinden.
(***) küçük İskender, ''Kanlı Masal'' şiirinden.', 'Babamdı o… Belki de gözlerinin yemyeşil olduğunu on yedi yaşımda fark ettiğimdi. Atatürk kaşlarının altındaki ışıltılı gözleriyle sevenimdi....', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK DEĞİL', 'uzak-degi-l-rifat-ilgaz-5qx4r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çaresizlik akşamında düşünülmüş
Bakıp bakıp kör pencereden
Bir yudum suyun bir solukluk havanın
Sudan da havadan da üstün dost yüzünün özleminde
Alıp başımı gitmek. Atsız arabasız
Alıp başımı düşlerin çıkmazından
Karışmak taşa toprağa. Yolculuk…
Bir sabah… Zeytin yeşili Ege kıyılarında
Nemli bakışlarında çoban köpeklerinin
Başakların ağırlığınca verimli
Savrulan harmanların bereketinde
Savrulan alın teri insan emeği
Beni yaşamla içli dışlı eden
Yaşamla güçlü yaşamla bilinçli
Yol boyu adımladığım mutluluk
Sabah sisinde Havran yolunda
Katırtırnaklarında gülüş alev sarısı
Toprakta coşkusu tava gelmenin
Dal uçlarında duyarlık
Ulu çamlara köknarlara karşı
Yaşıyorum diyebilmek göğüs dolusu
Bir otuyum diyebilmek bu toprağın
Menekşe değil bir ardıç eğilmezliğinde
Özsuyunda üreme varolma tutkusu
Ne kişiye boyun eğme ne kula kulluk
Gene de bitkiselliğin körlüğüne değil
İlkel ışımanın ezgisinde insanca
Bir aydın başıboşluğunca sorumlu
Bilinçsiz doğa kadar ustan yana
Bilinçli bir insan duyarlığınca doğal
Salt kurallarına bağlı yerçekiminin
Öylesine özgür
Küf yeşili Anadolu''m ayaklar altında
Tüm yalanlara açık ardına kadar
Gerçeklere tabut gibi örtük
Bir gün böyle yadsı böyle tutsak değil
Köy bizim yol bizim yolcu bizden
Dost yüreği sıcaklığında bir yolculuk
Uzak değil
(1968)
Karakılçık adlı şiir kitabından 1969
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Çaresizlik akşamında düşünülmüş Bakıp bakıp kör pencereden Bir yudum suyun bir solukluk havanın Sudan da havadan da üstün dost yüzünün özlem...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK HAZİRAN', 'uzak-hazi-ran-necati-cumali-k0fl0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki dudak arası bir zaman
Gözgöze geldikse geçerken
Mayıs''la Haziran arasında
Yağmurlu bir saçak altından
Aşktı uçup giden üstümüzden
Aşktı değip geçen yanımızdan
Uyanıp kış uykularından
Şubat''la Mart arasında
Eylül''le Ekim arasında
Yaz sularından kıyıya çıkan
İki adım arası bir zaman
Gözgöze geldikse geçerken
Günlük güneşlik bir kaldırımdan
Aşktı uçup giden üstümüzden
Aşktı değip geçen yanımızdan
Aşktı görmedik bilmedikse
Kimbilir hangi Eylül bir daha
Hangi uzak Haziran', 'İki dudak arası bir zaman Gözgöze geldikse geçerken Mayıs''la Haziran arasında Yağmurlu bir saçak altından Aşktı uçup giden üstümüzden Aşktı ...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK KADERLER İÇİN', 'uzak-kaderler-i-ci-n-turgut-uyar-q1krb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün, bir yağmurla garip garip
-Çoluğu çocuğu terk edeceğim.-
Bir sevgiyle doymayacak kalbim, anladım
Alıp başımı gideceğim.
Asır yirminci asırdır, amenna
Bir yanımda sevgilerim, bir yanımda sancım
Neon lambaları büsbütün karartır gecemizi
Uzaklar daha uzaklaşır
Bir define çıkarır gibi kayalardan, Ademden beri
Sımsıcak sevgilere muhtacım.
Bir gün alıp başımı gideceğim
-Yıldızlar ışısın, yollar üşüsün, yollar...-
Belimi bir ılık şal sarsın, mavi
Hüzünlü bir serencamın ardından, şarkısız
Rüyalarım unutulmuş bir handa pes desin
Görmüş geçirmiş bir çift duygulu dudak karşısında.
Kendi kendine çekilmez oluyor ömrüm
Her insanın ayrı ayrı yaşayabilsem kaderinde
Diyarı gurbette kanlı bir aşk
Bahtsız bir çocukluk uzak köylerin birinde
En uzak beyazlar,
En yakın ikindilerde, duygulu
Ve bir sahil meyhanesinde bir akşam
İçip içip ağlasam...
Nasıl kısa kesmeli bilmiyorum?
Herkesin derdinden pay isterken.
Uzak kaderlerin suları çağlar simdi
Yıldızlar dökülür sonsuza içimizden.
Birgün, bir parkta otururken, biliyorum
Bir el yağmurla dokunacak omuzuma
Bir çift göz, bir davet, bir kalp
Çoluğu çocuğu terk edeceğim.
Yapraklar dökülecek, çiçekler solacak
Bir sonbahar, bir sabah ve bir yağmur olacak
Toprak ve insan kokularıyla,
Uğultulu bir sarhoşluk içinde, yıllar için
Başımı alıp gideceğim.', 'Birgün, bir yağmurla garip garip -Çoluğu çocuğu terk edeceğim.- Bir sevgiyle doymayacak kalbim, anladım Alıp başımı gideceğim. Asır yirminci...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut_uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK TANIK', 'uzak-tanik-azad-ziya-eren-ptr7r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'uzak tanıklarıyız
kulağımızda seken hayatların ...
matarasında damlasız
çöllere serilmiş adamlardık
gözlerinin ferine bu şehrin
yeni surlar dikmeye sevdalandık
demirci zırhlarımıza giydirdik sabrı
kalkanlarımıza çığlıklar sürdük de
sıyrılamadık yüzümüzdeki esmer lekelerden
tanıklarıydık uzak cinayetlerin
görülmeyen
gömülmeyen cesetlere ağlattık gözlerimizi
uzak durdu sıcaklığı yeminli dillerin
şehirler batıyordu
şehrimiz, batacağı sabaha geceden bakıyordu
duyulmuyordu içimizdeki matem
metamatiksel kaoslardan
içimizde zenci bir ülke kara kara düşünüyordu!
madem duyulmuyorduk
bağırmalıydık katılmalıydık
da katlanmamalıydık demek
sesimiz uzak tanıklarımızda ses mi buluyordu?', 'uzak tanıklarıyız kulağımızda seken hayatların ... matarasında damlasız çöllere serilmiş adamlardık gözlerinin ferine bu şehrin yeni surlar ...', ARRAY['Türk Edebiyatı','Şiir','Azad Ziya Eren']::text[], 8.5, '{"poet":"Azad Ziya Eren","poet_slug":"azad_ziya_eren","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZAK', 'uzak-giuseppe-ungaretti-jdz4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak uzak bir ülkeye
bir kör gibi
götürdüler beni tutup elimden', 'Uzak uzak bir ülkeye bir kör gibi götürdüler beni tutup elimden...', ARRAY['Türk Edebiyatı','Şiir','Giuseppe Ungaretti']::text[], 8.5, '{"poet":"Giuseppe Ungaretti","poet_slug":"giuseppe%20ungaretti","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZANIŞI İNCEYDİ ÜLKEMİN', 'uzanisi-i-nceydi-ulkemi-n-ahmet-uysal-7m81u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuşların uçtuğunu
görmedik
Güneşin sıyrıldığını
buluttan
Görmedik yağmurun
yağışını
Çok erken geldiğini
ölümün
Görmedik çocukların
gülüşünü
Uzun akan nehrin
sularını
İncecikti uzanışı
ülkemin
Sonsuz gökyüzüydü
görmedik', 'Kuşların uçtuğunu görmedik Güneşin sıyrıldığını buluttan Görmedik yağmurun yağışını Çok erken geldiğini ölümün Görmedik çocukların gülüşünü ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZANMAK GÖLGESİNE, SOLUK VE DALGIN', 'uzanmak-golgesi-ne-soluk-ve-dalgin-eugenio-montale-fqq8d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzanmak gölgesine, soluk ve dalgın,
güneşten kızgın bir bostan duvarının,
dinlemek böğürtlen dikenlerinin arasından
tarlakuşlarının şakımasını, hışırtısı yılanların.
Toprağın çatlağında, burçakotlarında ya da
izlemek kırmızı karınca dizilerini,
kâh dağılan, kâh toplaşıveren
başak kümeciklerinin üzerine.
Gözlemek dallar arasından, çırpınışını
denizin uzaklarda, pul pul,
yükselirken ağaçsız tepelerden
ağustos böceklerinin titreyen şarkısı.
Ve dolaşırken göz kamaştıran güneşte
hissetmek hüzünlü bir hayretle
nasıl da benzediğini, hayatın ve acılarının,
üstü cam kırıklarıyla kaplı
şu duvar boyunca yürümeye.
Eugenio MONTALE', 'Uzanmak gölgesine, soluk ve dalgın, güneşten kızgın bir bostan duvarının, dinlemek böğürtlen dikenlerinin arasından tarlakuşlarının şakıması...', ARRAY['Türk Edebiyatı','Şiir','Eugenio Montale']::text[], 8.5, '{"poet":"Eugenio Montale","poet_slug":"eugenio_montale","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZUN HAVA', 'uzun-hava-ceyhun-atuf-kansu-9yr8f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dumanlı dağın çobanı garip yıldız
yağmurlar yağmasına yağıyor
rüzgârlar esmesine esiyor
ben ölmüşüm sen ölmüşsün kime ne
kimsecikler derdimizi bilmiyor
kemah pazarında sıra sıra testiler
jandarmalar anacığım evimizi bastılar
al kanlarım bulaştı kelepçenin demirine
üstelik on sekiz ay ceza kestiler
ya ben neyleyim neyleyim
dumanlı dağın çobanı garip yıldız
şimdi ben burda yalnızım sen orda yalnız
kuş değilim lodos poyraz uçamam
demirlerin gölgesi yüreğimi karartır
ecel şerbetini yirmisinde içemem
ben ölmeylen kahpe dünya yıkılır
feranenin kapısında demir parmaklık
hey gidi bulutlar! hey kemah yolları!
ayağımda zincir kolumda zincir
bu meret mapusluk bu ince hastalık
bilir miyim nedendir nedendir nedendir
dumanlı dağın çobanı garip yıldız
ciğerim parçalanır dağlarda akşam oldu mu
garibim zincirlerim boynuma ağır gelir
anacığım ağlamaya durdu mu
kör talih bu kimi gider kimi kalır
ben ölmeylen kahpe dünya yıkılır', 'dumanlı dağın çobanı garip yıldız yağmurlar yağmasına yağıyor rüzgârlar esmesine esiyor ben ölmüşüm sen ölmüşsün kime ne kimsecikler derdimi...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun_atuf_kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZUN İNCE BİR YOLDAYIM', 'uzun-i-nce-bi-r-yoldayim-asik-veysel-satiroglu-peync', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun ince bir yoldayım
Gidiyorum gündüz gece
Bilmiyorum ne haldayım
Gidiyorum gündüz gece
Dünyaya geldiğim anda
Yürüdüm aynı zamanda
İki kapılı bir handa
Gidiyorum gündüz gece
Uykuda dahi yürüyom
Kalkmaya sebep arıyom
Gidenleri hep görüyom
Gidiyorum gündüz gece
Kırk dokuz yıl bu yollarda
Ovada dağda çöllerde
Düşmüşüm gurbet ellerde
Gidiyorum gündüz gece
Düşünülürse derince
Irak görünür görünce
Yol bir dakka miktarınca
Gidiyorum gündüz gece
Şaşar Veysel işbu hâle
Gâh ağlaya gâhi güle
Yetişmek için menzile
Gidiyorum gündüz gece', 'Uzun ince bir yoldayım Gidiyorum gündüz gece Bilmiyorum ne haldayım Gidiyorum gündüz gece Dünyaya geldiğim anda Yürüdüm aynı zamanda İki kap...', ARRAY['Türk Edebiyatı','Şiir','Aşık Veysel Şatiroğlu']::text[], 8.5, '{"poet":"Aşık Veysel Şatiroğlu","poet_slug":"asik_veysel","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZUN ŞİİR -KISA ŞİİR', 'uzun-si-i-r-kisa-si-i-r-melih-cevdet-anday-itho7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KISA ŞİİR
Geçende bir ozan
arkadaşım, yeni yazdığı dört beş dizelik güzel
bir şiirini okudu bana; o şiir üzerine
konuşurken, uzun şiir-kısa şiir konusuna değindik. Şunu
merak ediyordum ben : Arkadaşımın, o dört beş dize
ile verdiği, vermek istediğinin tümü
müydü? Başka bir değişle, onu bu dört
beş dizeyi yazmaya iten düşünce daha da
geliştirilmeye elverişli değil miydi? Bir
ozan, niçin kimi zaman düşüncelerinin ardına
takılıp gidebildiğince gidiyordu da, kimi zaman az
sözle yetiniyordu? Konuların (salt anlaşma
kolaylığı sağlamak için kullandığım bu cözcükten
ötürü bağışlanmamı dilerim, yoksa konulu şiir değildir
sorunumuz) geliştirilmeye elverişli olanı, olmayanı mı
vardı ve bunlar ne yoldan ayırd edilebilirdi? Konuşmamızın
sonunda anlaşıldı ki o ozan tanıdığım, sadece çok
vakti olmadığı için kısa kesmiş, dört beş dize ile
yetinmişti. Demek kısa şiirler, vakitsizlikten ötürü
kısa şiirdiler. Bunun gibi, tembellikten ötürü,
yorgunluğuna katlanamamaktan ötürü geliştirilmeden
bırakılmış şiirler bulunduğunu da düşünebiliriz.
Bütün bunların dışında kısa
şiiri, salt kısa şiir için yazmak
diye anlatabileceğimiz bir tutum da var ki, bu tutum,
&quot;Şiir kısa olur!&quot; savını içinde taşımaktadır.
(...) Bugün bizim
kısa şiirleri uzun şiirlere, ya da uzun şiirleri kısa
şiirlere yeğlememizin ne gibi nedenlere dayandığı
sorusu kolay kolay çözülemez. Uzun bir şiiri, kısa
bir şiir gibi sevmemize hiçbir engel yoktur. Ama
daha ileri gidersek, &quot;Uzun şiir nedir, kısa
şiir nedir?&quot; sorusunu sormak gerekir; kaç
dizeye kadar kısa şiir de kaçıncı dizeden sonra
uzun şiir başlar? İşte bu soruyu karşılamadan
konuyu aydınlatamayız sanırım.
Edgar Allan Poe,
31 Ağustos 1850'' de yayımlanan, From the Poetic
Principle adlı yazısının bir
yerinde şöyle diyor : &quot;Şu kanıya vardım
ki, uzun şiir diye bir şey yoktur. Uzun şiir
sözünün sadece apaçık bir çelişki olduğunu
ileri sürüyorum.&quot;
Uzun şiire
karşı ilk başkaldıran Edgar Allan
Poe''dur, diye düşünmekte büyük bir yanlışlık olmasa
gerektir. Başka bir deyişle, kısa şiiri, yeni bir
şiir anlayışı olarak ortaya süren
çağdaş şiirdir ve onun babası sayılan da Edgar Allan
Poe'' dur. Ancak Poe'' nun, sözgelişi Raven şiiri 108
dizeliktir. Şimdi 108 dizelik bir şiiri kısa
şiir mi sayacağız, uzun şiir mi?
Burada yapılacak ilk
iş, konuyu dize sayısına bağlı görmekten
kurtulmak olmalıdır, sanıyorum. Çağdaş şiir
anlayışı, şiirden öyküyü atmak amacından doğmuştur,
denilebilir; bu ise sözgelişi, Homeros''un, Dante'' nin,
Fransız klasik ozanlarının ve bir
anlamda romantik ozanlarının şiir anlayışına
karşı çıkmak demektir. Gerçekten de, Homeros''
u alırsak, o iki büyük koçaklamanın onca
uzun olması, bütün ayrıntıları ile
bir savaşı ve bir deniz
yolculuğunu anlatmasından, giderek bir parçayı
önce ozanın, sonra kişilerden birinin diliyle, daha
sonra da başka bir kişinin diliyle olmak üzere birkaç kez
anlatmasındandır. Öyküyü, tarihi, dini, ansiklopedik
bilgileri çıkarıp atınca, yeni şiir ister istemez, eski
şiire bakarak kısa olacaktır.
Bu açıdan bugün
uzun şiir - kısa şiir tartışması, bana
gelir ki, baştan başa gereksizdir. O tartışma, yeni
şiirin, çağdaş şiirin ortaya çıkışı sırasında,
yüz yıl önce gerekliydi. Bugün kısa şiir sözünden, beş
altı dize içinde dönüp durmayı anlamak, bu bakımdan
, sadece yanlış olmakla kalmaz, bir şiirin
geliştirilmesine, bu yoldan görütlemeye de karşı
durmak olur, vakit darlığından ya da değil, tembelliği
yerleştirir, fantaziyi nükteye indirir ve ozanlığı
kolay göstererek şiirin eğitimsel yanını çürütür.', 'KISA ŞİİR Geçende bir ozan arkadaşım, yeni yazdığı dört beş dizelik güzel bir şiirini okudu bana; o şiir üzerine konuşurken, uzun şiir-kısa ...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":83}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'UZUN YAĞMURLARDAN SONRA', 'uzun-yagmurlardan-sonra-gulten-akin-hkk4o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen yağmurlu günlere yakışırsın
Yollar çeker uzak dağlar çeker uzak evler
Islanan yapraklar gibi yüzün ışır
Işırsa beni unutma
Alır yürür sıcak mavisi gökyüzünün
Kuşlar döner uzun yağmurlardan sonra bir gün
Bir yer sızlar yanar içinde büsbütün
Her şeye rağmen ellerin üşür
Üşürse beni unutma
Yeni dostlar yeni rüzgârlar gelir geçer
Yosun muydum kaya mıydım nasıl unuttular
Kahredersin başın önüne düşer
Düşerse beni unutma', 'Sen yağmurlu günlere yakışırsın Yollar çeker uzak dağlar çeker uzak evler Islanan yapraklar gibi yüzün ışır Işırsa beni unutma Alır yürür sı...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş doğum günlerinden bilinmezliğine ölümünBir yanardağ patlamasıdır içerde zona', 'unutulmus-dogum-gunlerinden-bilinmezligine-olumunbir-yanardag-patlamasidir-icerde-zona-c-hakki-zari-c-gnrq7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yanardağ patlamasıdır içerde zona
ZONA
Uysal bir ormanın uğultusunda kaybedilmiş
patikayı kim arar
Herhangi bir mevsimin sonuna doğru
kim özler ilk şiirlerini
Baş dönmesi, karmaşa bir de kör olma isteği
Zona; sırtımda taşıdığım bıçak izleri sıkıntımın
Karşı kıyıdan gelen ışık seslerinin içindeki gizin tılsımı
Uzaktan görülene olan kemirgen merak,
nereye dökülür ırmaklar
Kim koydu bu ömrü müziksiz bu kentin kupkuru yerine
Zona; göğsümün duvarına asılı yaraları sıkıntımın
Yine deniz çekilmesi boğazımda, çaresizliğimin armağanı
Rıhtımlar, yokolmak için gitmenin sağanaklı duldaları
Avlulardan yükselen kuşların ürküttüğü yaprakları serinliğin
Zona; ürpertili uçuk izleri sıkıntımın
Şehvetli bir kadının tanrısı ve imzasız mektupları
Sokaktan gelen ayak sesleri ve kokuları ıslak çiçeklerin
Bakmayan, dokunmayan, sevişmeyen yalnızlığım benim
Zona; okşayamadığım yara izleri sıkıntımın
Bağırmaktan başka dil bilmeyen tiranlar
Reklamlardan aşırılmış çok sevimli gülüşler
Yapaylık, adına ben''ini sormayanlar
Zona; sustukça çoğalan kabuksuz yaraları sıkıntımın
Günün ilk dakikalarında dikilen bir fidan gibi
Bir Ege türküsüyle yan yana olmak gibi
Bir intihar girişiminden sonraki ilk duyuş gibi
Bir çift dudağın dokunuşuyla iyileşir kimi yaralar
Hatta zona !..', 'Bir yanardağ patlamasıdır içerde zona ZONA Uysal bir ormanın uğultusunda kaybedilmiş patikayı kim arar Herhangi bir mevsimin sonuna doğru ki...', ARRAY['Türk Edebiyatı','Şiir','C. Hakkı Zari̇ç']::text[], 8.5, '{"poet":"C. Hakkı Zari̇ç","poet_slug":"zaric","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VARA VARA VARDIM OL KARA TAŞA', 'vara-vara-vardim-ol-kara-tasa-karacaoglan-665my', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vara vara vardım ol kara taşa
Hasret ettin beni kavim kardaşa
Sebep ne, gözden akan kanlı yaşa
Bir ayrılık, bir yoksulluk, bir ölüm
Nice sultanları tahttan indirdi
Nicesin gül benzini soldurdu
Nicelerin, gelmez yola gönderdi
Bir ayrılık, bir yoksulluk, bir ölüm
Karac''oğlan der, kondum, göçülmez
Acıdır ecel şerbeti, içilmez
Üç derdim var, birbirinden seçilmez
Bir ayrılık, bir yoksulluk, bir ölüm', 'Vara vara vardım ol kara taşa Hasret ettin beni kavim kardaşa Sebep ne, gözden akan kanlı yaşa Bir ayrılık, bir yoksulluk, bir ölüm Nice sul...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VARIŞ', 'varis-philip-larkin-l633x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Orda yaklaşmakta bir akşam
Kırların üstünde, kimsenin daha önce görmediği,
Hiçbir lambada ışık yok.
Uzaktan ipekten gibi görünür, ancak
Dizlerin ve göğsün üstüne örtüldüğünde
Huzur getirmiyor hiç.
Nereye gitti o ağaç, kilitleyen
Yeri göğe? Nedir ellerimin altındaki,
Bir türlü duyumsayamadığım?
Nedir ellerimi külçe gibi kılan?
Philip  LARKIN', 'Orda yaklaşmakta bir akşam Kırların üstünde, kimsenin daha önce görmediği, Hiçbir lambada ışık yok. Uzaktan ipekten gibi görünür, ancak Dizl...', ARRAY['Türk Edebiyatı','Şiir','Philip  Larkin']::text[], 8.5, '{"poet":"Philip  Larkin","poet_slug":"philip_larkin","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VARLIĞININ TÜRKÜSÜ', 'varliginin-turkusu-afsar-ti-muci-n-b15r4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiirler yazdırdı bana bakışın
Eline kırk yıl kalem almamışlara
Soğuk yürekleri ısıttı aşkın
Kendini büsbütün bitmiş sayanlara
Duyurdu yaşadığını içten içe
Utandırdı yoksunlukları renk renk dünyan
Suskunluktan başka şeyi kalmamışlara
Doğanın dinmeyen sesini getirdi
Şarkılar söyletti duruşun
Sevinmeyi unutmuşlara
Yılgınlığa sürükledi kimini
Kimini ölüme attı
Uykusunu kaçırdı kiminin
Kimine sensizliğin
Bıçak gibi acısını sapladı
Çok zaman güç kattı inanmışlığa
Saçların gibi dindirdi sancıyı
Durup kalmışlıkları kamçıladı
Sarstı hiçliğin saltanatını
Yangınlar getirdi donmuşluklara', 'Şiirler yazdırdı bana bakışın Eline kırk yıl kalem almamışlara Soğuk yürekleri ısıttı aşkın Kendini büsbütün bitmiş sayanlara Duyurdu yaşadı...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VARTAN''IN ÖLÜMÜ', 'vartan-in-olumu-ahmed-samlu-r47er', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"-Bak!! gülümsedi bahar, erguvan tomurcuk verdi
evde, pencerenin altında, çiçeklendi yaşlı yasemin
boş ver hayalleri
var olmak yok olmaktan iyi
baharda hele....."
Vartan konuşmadı
başı dik
öfkeli
sıktı dişini
ve
gitti
*
"Vartan !! konuş!!
Sessizliğin kuşu
korkunç bir ölüm yavrusu
kuluçkasında..."
Vartan konuşmadı
güneş gibi
çıktı karanlıktan
kana boğuldu
ve
gitti
*
Vartan konuşmadı
yıldızdı sanki
parladı zulmette
kaydı
ve
gitti
*
Vartan konuşmadı
Vartan menekşeydi sanki
çiçek açtı
"-kış bitti": müjdeledi
ve
gitti
Ahmed  ŞAMLU', '"-Bak!! gülümsedi bahar, erguvan tomurcuk verdi evde, pencerenin altında, çiçeklendi yaşlı yasemin boş ver hayalleri var olmak yok olmaktan ...', ARRAY['Türk Edebiyatı','Şiir','Ahmed  Şamlu']::text[], 8.5, '{"poet":"Ahmed  Şamlu","poet_slug":"ahmed_samlu","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VASİYET', 'vasi-yet-luigi-pirandello-sqtdo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öldüğümü kimseye söylemeyin
Dostlar ve düşmanlar
Yalvarıyorum, çıkmasın benim için
Bir haber gazetede
Hiç söz edilmesin
Ne bir anış ne bir duyuru
Öldüğümde kefenlemeyin beni
Bir çarşafa sarın çırçıplak
Çiçek filan da istemez
Yatağımın üstünde mum bile yanmamalı
Sıradan ikinci sınıf bir cenaze arabası, yoksullar için olanından, sade,
Gelmesin peşimden kimse
Ne akrabalar ne eş dost
Yalnızca cenaze arabası, at ve arabacı
Olmasın başka biri ardımda istemem
Bırakın yakılsın cesedim savrulsun küllerim
Çünkü benden
Kalmamalı hiçbir şey geriye
Küllerim bile
Ama yapamazsınız bunu
Gönderin küllerimi Sicilya''ya
Doğduğum Girgenti kasabasında
Gömün alelâde bir kayanın altına
Luigi  PIRANDELLO', 'Öldüğümü kimseye söylemeyin Dostlar ve düşmanlar Yalvarıyorum, çıkmasın benim için Bir haber gazetede Hiç söz edilmesin Ne bir anış ne bir d...', ARRAY['Türk Edebiyatı','Şiir','Luigi  Pirandello']::text[], 8.5, '{"poet":"Luigi  Pirandello","poet_slug":"luigi_pirandello","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VATAN', 'vatan-ziya-gokalp-tiqpm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ülke ki camiinde Türkçe ezan okunur,
Köylü anlar mânasını namazdaki duanın...
Bir ülke ki mektebinde Türkçe Kuran okunur
Küçük büyük herkes bilir buyruğunu Huda''nın...
Ey Türk oğlu, işte senin orasıdır vatanın!
Bir ülke ki toprağında başka ilin gözü yok,
Her ferdinde mefkûre bir, lisan, adet, din birdir...
Mebusânı temiz, orda Boşo''ların sözü yok,
Hududunda evlâtları seve seve can verir,
Ey Türkoğlu, işte senin orasıdır vatanın!
Bir ülke ki çarşısında dönen bütün sermâye
Sanatında yol gösteren ilimle fen Türkündür
Hirfetleri birbirini dâim eder himâye
Tersâneler, fabrikalar, vapur, tren Türkündür
Ey Türkoğlu işte senin orasıdır vatanın!', 'Bir ülke ki camiinde Türkçe ezan okunur, Köylü anlar mânasını namazdaki duanın... Bir ülke ki mektebinde Türkçe Kuran okunur Küçük büyük her...', ARRAY['Türk Edebiyatı','Şiir','Ziya  Gökalp']::text[], 8.5, '{"poet":"Ziya  Gökalp","poet_slug":"ziya_gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VATANIN BU YANI', 'vatanin-bu-yani-berin-tasan-fizkk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vatanın her köşesi aziz
Çamlıca, Erenköy, Maçka
Vatanın bu yanında biz.', 'Vatanın her köşesi aziz Çamlıca, Erenköy, Maçka Vatanın bu yanında biz....', ARRAY['Türk Edebiyatı','Şiir','Berin Taşan']::text[], 8.5, '{"poet":"Berin Taşan","poet_slug":"berin_tasan","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VAZİFE', 'vazi-fe-oktay-ri-fat-horozcu-soglg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rengi üzümden kara
Beli iğneden ince
Bu yükle çıkılır mı
Yokuşlardan karınca
Nedir bu dünya hali
Nedir bu bozuk düzen
Dün çıktı yumurtadan
Bugün sevdalı kumru
Kaşla göz arasında
Şahin kapar kırlangıcı
Ceylân kanına girer
Su başında canavar
Bütün yük benim üstümde
Düşünmek lâzım hepsini ayrı ayrı
Dünyasından habersiz
Dünyaya gelen yavru
Güneşin şarktan doğmasını sağlamalı
Şaşırmaya gelmez
Sonra bana düşer tasası
Çocuğu soksa arı
Ayağı kanasa tilkinin
Bir hal olsa kuzuya
Oktay şu kurdun kuşun
Sana lâzım mı derdi', 'Rengi üzümden kara Beli iğneden ince Bu yükle çıkılır mı Yokuşlardan karınca Nedir bu dünya hali Nedir bu bozuk düzen Dün çıktı yumurtadan B...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VAZGEÇEMEDİĞİM', 'vazgecemedi-gi-m-bedrettin-aykin-c11te', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ayna bulundur yanında benim için
Görmemi sağla unuttuğumda yaşlı yüzümü
Çekilsin taşkın sularım yeniden göletine
Dokundurmasın beni el değmemiş güzelliğine
Kapat güneşime perdelerini yapabilirsen
Işığı söndür başlat bir yangını giderken
Şimdiden acılarlayım güz bahçesi yüreğim
Hazırım bekliyorum bir hüznü ağırlamaya ben
Ne zaman onaracaksın yanılgının yıktığını
Dağlarına bir gün karlar yağdığında mı
Baş kaldırmayacak mı kardelenlerin karakışa
Düşledim seni hep ben çiçeklerle kuşlarla
Yazık öpmemişsin hiç sevdanın dudağını
Bırak dokunsun gözlerim güzelliklerine
Tutayım kuş kanadı ellerini sevinsin ellerim
Solmasın koklanmadan o gül orada öylece
Günüdür bitti artık delibozuk ilkyaz düşleri
Uyandım karlar yağmış üstüne kasımpatılarının
Kurtuldu sonunda koruyamadığımız kimsesiz sevgi
Dinliyorum içimde şimdi acının nal seslerini
Yaşayabilecek misin türküsüz bir yalnızlıkla
Dayanabilecek mi yokluğuna benim yorgun yüreğim
Oysa sevincimdin bir zamanlar rastlaşmada
Bir sevgili dosttun ortağımdın yaşamı paylaşmada', 'Bir ayna bulundur yanında benim için Görmemi sağla unuttuğumda yaşlı yüzümü Çekilsin taşkın sularım yeniden göletine Dokundurmasın beni el d...', ARRAY['Türk Edebiyatı','Şiir','Bedrettin Aykin']::text[], 8.5, '{"poet":"Bedrettin Aykin","poet_slug":"bedrettin_aykin","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VİDALAR', 'vi-dalar-oktay-ri-fat-horozcu-23wcg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşçi demir dikmeleri boyuyor duvarın üstüne binmiş,
boya kutusuna banarak usulca fırçayı. Gündeliği kaça?
Doyarlar mı dersiniz çoluk çocuk! Tahtaları çakmak için
usta vida almaya gitti motosikletle, kavakların altından.
Bir toz bulutu yükseliyor upuzun ardında. Kasabaya vardığında
nalbura girecek: "Vida, diyecek, beşlik," küf kokan dükkânda.
Bir kutunun içinden vidalar çıkaracak nalbur, uzatacak.
Alışverişle dönüyor dünya, mevsimler gelip geçiyor.
Tahtalar dökülüyor ne denli sağlam çakılsa yıllardan sonra
ve otlar, dikenler, ısırganlar bürüyor duvar diplerini.
Ama şu bulutlar, maviliğin içinde,yıllardan sonra da
gelip geçecek göçük ya da yeni duvarların üstünden.
-Beşlik vida kısa düşer, ustam, altılık ister bu tahtalara,
günün birinde yine çürür düşerler ya, şimdilik.', 'İşçi demir dikmeleri boyuyor duvarın üstüne binmiş, boya kutusuna banarak usulca fırçayı. Gündeliği kaça? Doyarlar mı dersiniz çoluk çocuk! ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VE BURDA', 've-burda-che-guevara-jj6z1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haykırır paleti tutuşan ressam, &quot;melezim ben&quot;,
haykırırlar bana kovalanan hayvanlar, &quot;melezim ben&quot;,
sızlanırlar gezgin şairler, &quot;melezim ben&quot;,
tekrarlar her köşenin günlük acısında
rastladığım insan, &quot;melezim ben&quot;
ve altın kaplamalı tahtadan bir bakireyi okşayan
ölü bir ırkın gizemine varır bu:
&quot;melezdir benden doğma bu acayip çocuk&quot;.
Melez değil miyim ben de bir yandan
çarpışmasında (birleşip, ayrılan)
aklımı karıştıran iki gücün,
o güçler ki ağaçta daha olgunlaşmadan
hapsolmuş meyvenin garip tadını
hissettiğinde beni çağıran.
Dönüyorum İspanyol Amerika''sının sınırına,
kıtayı saran bir geçmişi tatmaya.
Kayıp gitmektedir hatıra silinmez bir yumuşaklıkla
bir çan sesiyle ta uzakta.
Che GUEVARA', 'Haykırır paleti tutuşan ressam, &quot;melezim ben&quot;, haykırırlar bana kovalanan hayvanlar, &quot;melezim ben&quot;, sızlanırlar gezgin ş...', ARRAY['Türk Edebiyatı','Şiir','Che Guevara']::text[], 8.5, '{"poet":"Che Guevara","poet_slug":"che_guevara","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VE KOMİSER KOLOMBO', 've-komi-ser-kolombo-can-yucel-rjsnz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haldun Taner’e
Vay hafiye rüzgar vay!
Sıcakların nereye taşındığını
efendice tahkike yanaşmış
Hafiften zatülcenp muşambasıyla
Havadan sudan
dereden tepeden
hoşbeşti derken
sabah beri
Yaprak izlerini alıyor çınarın
Yandın çavuş yandın!
Böyle bir sonbahar iptidasında
Tutuklanmıştı zavallı Amerika’da', 'Haldun Taner’e Vay hafiye rüzgar vay! Sıcakların nereye taşındığını efendice tahkike yanaşmış Hafiften zatülcenp muşambasıyla Havadan sudan ...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VE', 've-aydin-hati-poglu-ggpn8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haydi tut ellerimi sıcacık yürüyelim
Bulanık bir sonbaharı saçlarına sindirerek
Eski coşkular yoldaşı çınar gölgelerine
Bastırılmış tutkuların deprem kuşaklarına
Hırslı çocukların yürüdüğü sokaklara
Al kurumuş yapraklar gibi sakla bu hüznü
Ölümle oynayan çocuklardık daha
Alaca gömleklerimiz sızıyordu tenhalara
İşte yine pencereden atılmış
İntihar süsü verilmiş bembeyaz bir yüz
Bir kadının sevdasını bıçaklıyor güz
Herkes dulbaşına kalıyor
Çiçekler çürüyor
Çürüyor solgun dostluklar
Bir nabız vuruşu duyulsun tut
Ölü kentin aylak karıncaları saklasın suskusunu
Devinsin sarhoş yosunlar durmadan
Edilgen kaygıların burgacını tırmanalım
Tutunalım karanlık dallarına selvilerin
Kimselerin duymadığı çığlıklarımız
Ulansın birbirine
Tut ellerimi sıcacık tut.', 'Haydi tut ellerimi sıcacık yürüyelim Bulanık bir sonbaharı saçlarına sindirerek Eski coşkular yoldaşı çınar gölgelerine Bastırılmış tutkular...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VEDÂ', 'ved-orhan-seyfi-orhon-mhhjv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hani, o bırakıp giderken seni
Bu öksüz tavrını takmayacaktın?
Alnına koyarken vedâ busemi,
Yüzüme bu türlü bakmayacaktın?
Hani, ey gözlerim bu son vedâda,
Yolunu kaybeden yolcunun dağda,
Birini çağırmak için imdada
Yaktığı ateşi yakmayacaktın?
Gelse de en acı sözler dilime,
Uçacak sanırım birkaç kelime...
Bir alev halinde düştün elime,
Hani, ey gözyaşım akmayacaktın?', 'Hani, o bırakıp giderken seni Bu öksüz tavrını takmayacaktın? Alnına koyarken vedâ busemi, Yüzüme bu türlü bakmayacaktın? Hani, ey gözlerim ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi̇ Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi̇ Orhon","poet_slug":"orhan_seyfi_orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VEDA', 'veda-huseyin-ferhad-qp9wl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün güneşi paramparça gördüm pencerenden perdeleri çektiğimde
siyah bir seccade gibi önüne serdim yüzümü ben de.
Eğildim nehrine mataramı mengü suyunla doldurmak için
gördüm âşık sûretimi kırık camında elimdeki fenerin.
Sarsıldım ve ürperdim beynimden parmak uçlarıma dek
baktım, şıra küpüne batırılmışçasına sararmakta bedir.
Ehram giyip tavaf ettiysem de ayak izlerini kıblem sayıp
karaldı yine ''sol mememin altındaki cevahir''.
Toprağı dinledim, patikalarda koştum,yalnayak aştım koruları
o mutad işaretini yine bulamadım vaad ettiğin cennetin.
Yaşlı kelebeklere özgü bilgelikle dolandım ışık hâlende
fakat yitirdim yıldız kuşağımı zaman koridorunda gecenin.
Kurtulamadım bir türlü ulu kemanının ses kasırgasından, ey Aşk
artık zerkeyle damarıma yeşil zehrini gözlerinin.', 'Dün güneşi paramparça gördüm pencerenden perdeleri çektiğimde siyah bir seccade gibi önüne serdim yüzümü ben de. Eğildim nehrine mataramı me...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin  Ferhad']::text[], 8.5, '{"poet":"Hüseyin  Ferhad","poet_slug":"huseyin_ferhad","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VERSAİLLES', 'versai-lles-vladimir-mayakovski-h1okw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Krallar korurdu Versailles''i
tarih gözbebeğini.
bu yollardan koşarken
saraydan saraya
binerdi her Lui ve her Ludovik
yaylı, rahat
arabaya
yaldız, ipek
arasında
pelte gbi titreterek
on batmanlık göbeğini
ve sonra...
güvenerek bacakların
piston kollarına
Marseilles''in eşliğinde
ve bir yandan lanet,
lanet taca da, saraya da,
sapmıştı Versailles yollarına
külotunu toplayan
Kapet.
Bugün
aynı yolda yarışıyor
Paris otoları
Paris gürültülü, çalkantılı ve
şen
rantiyeler, Paris kokotları
dolaşıyor
Amerikan turistleri
bir de ben.
İşte Versailles. İlk hayret ünlemi:
Vay anasını! Soyarak el âlemi
amma da yaşamışlar
bu eski krallar
ne gaile, ne tasa!
Binden fazla salon
yüz yatak odası
ve her odada
hem bir yatak
hem bir masa.
Böyle bir sarayın
ikincisi yapılamaz
çalsan çırpsan hazineden
ömür boyunca
Sarayın arkasında
uzunca
havuzlar
Hayatları taze,
serin olsun diye
fışkırıyor sular akşam olunca
her yer havuz... kameriye, şadırvan
ve fıskiye.
"Gentille",
yani zevkli hayat için dümdüz
koru yollarında
sıralanmış Tanrı heykelleri
hem Apollonlar, hem de Venüs
ama kiminin kolu kopuk
kiminin burnu ve elleri
Pompadur''un apartmanı
az ötede
Büyük ve Küçük Triyanon
şurası
duşlar ve Pompadur hamamları
burası
bu dokuz on
oda, bir arada
Pompadur''un yatak odaları.
Bu mu hayat?
basit, adi,beylik,
ye, iç ve yat
Benois''nın
suluboya tablosuna istersen
kat
Ahmatova''dan
tatlı birkaç dörtlük.
Ortalığa bakındım
bütün eşya arasında
bir Antuvanet''in gece masasında
koca çatlağı beğendim.
İşte, devrim tarihinden bir an:
paldır küldür kaba botlar.
Marseilles inletiyor
Versailles Sarayı''nı
ve derken
çakıyor devrim kazığını
sankülotlar:
Küüüüt! Diye yaldızlı masaya
bir darbe
şaka niyetine
kraliçeyi giyotine
saçlarından sürüklerken.
Versailles bahçeleri güzel.
Güller türlü türlü
Bizde böyle kültür olsa,
gül değil, geniş makine kültürü
müzelere tıkılsa
eski ve gereksiz şeyler.
Emekçilere
bu bahçeye
hem çelikten hem de camdan
bir de Kültür Sarayı kondurulsa
gözü kamaştırsa
yeni stilde bir ihtişam
ve sarayın hacmi
bin iki bin değil,
milyona ulaşsa!
... Krala, markilere ve çarlara ibret,
unutmasın diye geçmişini
halk sırtından çalınan
varlıklarıyla öğünmesin diye
attı semaların giyotini
Antuvanet''in kellesini atar gibi
attı
yuvarladı akşam güneşini
Paris damları üstünde
ağır ağır ölsün diye.
Titreşiyor
yapraklar ince ince
dağılıyor
ıhlamur, atkestanesi kalabalığı
gölgeler siliniyor
Ay
göklerde ince bir yay
Akşam oldu.
Ve başına geçiriyor
saydam camdan gece kalpağını
bu saatte kapanan müze: Versailles
Vladimir MAYAKOVSKI', 'Krallar korurdu Versailles''i tarih gözbebeğini. bu yollardan koşarken saraydan saraya binerdi her Lui ve her Ludovik yaylı, rahat arabaya ya...', ARRAY['Türk Edebiyatı','Şiir','Vladimir Mayakovski']::text[], 8.5, '{"poet":"Vladimir Mayakovski","poet_slug":"vladimir_mayakovski","theme":"Türk Şiiri","is_hero":false,"total_lines":130}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VESPERAL', 'vesperal-rub-n-dario-kdnq9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siesta geçti,
akşam saati yaklaşıyor,
kıyıda sessizlik var,
tropik güneşinin yaktığı kıyıda.
Deniz meltemi usulca esiyor,
batıda bir orman
mor alevlerle yanıyor sanki.
Okunaksız bir yazı oluşturmuş
kumlarda yengeçlerin izleri.
Pembe deniz kabukları,
yaldızlarla yansıyan kabuklar,
küçük salyangozlar, deniz yıldızları
basıldıkça çıtırdayan bir halı yaratmış
ezgilerle donanmış kıyıda.
Venüs ışıdığı zaman,
kutsal akşamın o yüce sevgisi,
lir sesleri duyuyorum dalgalarda,
deniz kızlarının türkülerini.
Ve içimde Venüs gibi bir yıldız ışıldıyor.
Rubén DARIO', 'Siesta geçti, akşam saati yaklaşıyor, kıyıda sessizlik var, tropik güneşinin yaktığı kıyıda. Deniz meltemi usulca esiyor, batıda bir orman m...', ARRAY['Türk Edebiyatı','Şiir','Rubén Dario']::text[], 8.5, '{"poet":"Rubén Dario","poet_slug":"ruben_dario","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VİETNAM', 'vi-etnam-arif-damar-j5oo7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vietnam için yazmadın dedi Akşit
Vietnam için şiir yazılmaz
Vietnam için döğüşülür
Vietnam için ölünür
Yapraktan kömür
Kirpikten kül
Gözlerin yandığı Vietnam
Dağ ol dağlarına katıl
Başak ol
Tüfek ol çatıl
Tuz ol ekmeğini bansın
Göreyim
Ağlamayı bilmiyor Vietnam
Şiir ne ki
Gözyaşı
Çocuklar doğmadan öldürülüyor
Git Vietnam''da ana ol', 'Vietnam için yazmadın dedi Akşit Vietnam için şiir yazılmaz Vietnam için döğüşülür Vietnam için ölünür Yapraktan kömür Kirpikten kül Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Arif  Damar']::text[], 8.5, '{"poet":"Arif  Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖVGÜ MEKTUBU', 'ovgu-mektubu-derek-walcott-czbur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sallanır beşiğimiz iki büyük uçta
Amerika kuzeyde, güneyde Amerika
Büyüttüğümüz özlem sendin özgürlük
Uzanır delik-deşik orada Che Guevera
Ölümler bitip-tükenmiştir şimdi
Beyaz düşlerden beliren yığıntı
Saklanmaz yüzü acının gördünüz
Hep anıtlarda biçimlenen gömütler
O delişmen kızgınlık çoğalır gözlerinde
Hangi sözcüklerdir anımsatır geceyi
Bir karaduyguda özgülerden oluşan
Unutmuş açılmayı bahçelerde leylaklar
Derek WALCOTT', 'Sallanır beşiğimiz iki büyük uçta Amerika kuzeyde, güneyde Amerika Büyüttüğümüz özlem sendin özgürlük Uzanır delik-deşik orada Che Guevera Ö...', ARRAY['Türk Edebiyatı','Şiir','Derek Walcott']::text[], 8.5, '{"poet":"Derek Walcott","poet_slug":"derek_walcott","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖVGÜ', 'ovgu-can-yucel-j7p9c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Komünizm kızılcıktır
Kabza iyi gelir
Ne güzeldir daneleri
Ne güzel reçeli olur
Şurubu da
Yemiştir ama yenilmiş değildir', 'Komünizm kızılcıktır Kabza iyi gelir Ne güzeldir daneleri Ne güzel reçeli olur Şurubu da Yemiştir ama yenilmiş değildir...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VIZILDAYAN SİNEK', 'vizildayan-si-nek-erik-stinus-0luma', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya küçüldü, ben
nerdeyse kıpırdayamaz oldum,
diyorum ki karıma: Kendimi
hem Avrupalı hem Amerikalı gibi
duyumsuyorum aynı anda,
yüksek basınç denebilir buna,
kanım, etim ve insanlığımın ağırlığı,
kocaman bir ağırlık kafamın üzerinde.
Ve
mor yüksükleri, lastik emzikler gibi,
pencereye yapışmış saksı bitkisine
diyorum ki yabancı bir sesle:
Öp dünyayı, gökyüzünü, ışığı,
bu nimetler tüketilmeden önce.
yaşamak için, birazcık olsun
gergin olmalı insan,
gevşeklik etme!
Erik STINUS', 'Dünya küçüldü, ben nerdeyse kıpırdayamaz oldum, diyorum ki karıma: Kendimi hem Avrupalı hem Amerikalı gibi duyumsuyorum aynı anda, yüksek ba...', ARRAY['Türk Edebiyatı','Şiir','Erik Stinus']::text[], 8.5, '{"poet":"Erik Stinus","poet_slug":"erik_stinus","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖVÜNEREK AŞKIN İLE', 'ovunerek-askin-i-le-attila-asut-ekum6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdiceğim, övdüceğim, en ince dalımsın benim,
Aşkın yediveren gülü, karasevdalımsın benim.
Ardım sıra götürdüğüm, sürgünlerde büyüttüğüm
Özlem kuşum çığlık çığlık, suskun zerdalimsin benim.
Bitsin diye ayrılıklar ceylan gözlü can yoldaşım,
Sevgi katına sunulmuş arzuhalimsin benim.
Doludizgin koşulardan, kesintisiz acılardan
Duldasına sığındığım dingin yalı''msın benim.
Gün geçse de eskimeyen, tiril tiril hep genç kalan,
Hep genç kalan kavga gücüm, direnç balımsın benim!
Ankara, 19 Şubat 1978', 'Sevdiceğim, övdüceğim, en ince dalımsın benim, Aşkın yediveren gülü, karasevdalımsın benim. Ardım sıra götürdüğüm, sürgünlerde büyüttüğüm Öz...', ARRAY['Türk Edebiyatı','Şiir','Attila Aşut']::text[], 8.5, '{"poet":"Attila Aşut","poet_slug":"attila_asut","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VOLTADA BİR TÜRKÜ', 'voltada-bi-r-turku-metin-demi-rtas-az4gs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Günün dolar bir gün sen de
Özgürlüğü bir gelin gibi takıp koluna
Çıkarsın.
Başlar yeni maceran güneşte
Başlar işsizlik
O en büyük hapishane.
Hergün kapanan kapılar önüne
Başkaldıran öfkenle dikilsen de
Kâr etmez
Çünkü birşeyler almak çarşılardan evlere
Çünkü çocuklar dur bilmez
Havasız koğuşlara alışılır
Yatılır of demeden hücrelerde
Hiçbirşey öldürmez insan yüreğini
Öldürür eğilmek bir ekmek uğruna
Üç kuruşluk adamlar önünde', 'Günün dolar bir gün sen de Özgürlüğü bir gelin gibi takıp koluna Çıkarsın. Başlar yeni maceran güneşte Başlar işsizlik O en büyük hapishane....', ARRAY['Türk Edebiyatı','Şiir','Metin Demi̇rtaş']::text[], 8.5, '{"poet":"Metin Demi̇rtaş","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VİRAJ', 'vi-raj-ozlem-tezcan-dertsi-z-fqbb1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ateşi söndür, bu sesi tanıyorum
ilk dudaklar unutuyor, büyüsünü öpmenin
yağmaladık sözcükleri, korsanlık bitti
mevsimidir, gemiyi terketmenin.
durgunsun, suyum bulanık
terliyim, sözlerin soğuk
pencereyi açmak bazen mumları söndürebilir
bir zarf atılır eşikten,
günlerce kimse açmaz,
bir bakarsın içeri almışsın bulutları
kışı en iyi balkonlar anlatabilir
çocuksun, salıncağım kopuk
yalnızım, ışığın sönük
gitmek, hep gitmek sarhoş yönlere
virajlıdır bazı yaşlar, dalgınlığı affetmez
turnasını yitirmiş göç gibi darmadağın
boşuna, sağlaması hep yanlış çıkıyor aşkın
baharsın, günlerim kısa
yorgunum, yolların uzun', 'ateşi söndür, bu sesi tanıyorum ilk dudaklar unutuyor, büyüsünü öpmenin yağmaladık sözcükleri, korsanlık bitti mevsimidir, gemiyi terketmeni...', ARRAY['Türk Edebiyatı','Şiir','Özlem Tezcan Dertsi̇z']::text[], 8.5, '{"poet":"Özlem Tezcan Dertsi̇z","poet_slug":"ozlem_tezcan_dertsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VİTRİNDEKİ BEBEK', 'vi-tri-ndeki-bebek-ali-yuce-qzr0k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O vitrindeki bebeğin
Annesi yok dedin anne
Acıkınca kim meme verir
Kim ninni söyler ona
Altını kim değiştirir
Ateşi yükselince
Kim kor elini alnına
Sen görmedin anne
Arkamdan bir bakışı var
Bir iç çekişi derinden
Boynunu bir büküşü var
Öyle acıyorum ki ona
Bir daha geçmiyorum
O vitrinin önünden', 'O vitrindeki bebeğin Annesi yok dedin anne Acıkınca kim meme verir Kim ninni söyler ona Altını kim değiştirir Ateşi yükselince Kim kor elini...', ARRAY['Türk Edebiyatı','Şiir','Ali Yüce']::text[], 8.5, '{"poet":"Ali Yüce","poet_slug":"ali_yuce","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VUR', 'vur-refik-durbas-ehwet', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Buğdayın, petrolün ve alınterin
yabancı ırmaklara akıyorsa
su dursa bile sen durma
alnından kaderini çalanı vur
ağzından alınmış olsa da sözün
can, yüreğinden damıtılsa da
-acılar kardeşindir senin
kan sussa bile sen susma
hayından zalımdan doğanı vur
gönülden doğan acıyı vurma', 'Buğdayın, petrolün ve alınterin yabancı ırmaklara akıyorsa su dursa bile sen durma alnından kaderini çalanı vur ağzından alınmış olsa da söz...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VİYETNAM', 'vi-yetnam-oguz-tansel-ghddo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir güvercin uçurdum Ağrı''dan,
Kanlar içinde anlattılar, dönünce:
Kulağım gözüm tutuştu, sonra
Yandım, yüreğimi sardı bir alev
Milyonla tutsak, seksen bin ölü,
Soysuz zorbalar, soyguncu uşakları
Köyleri, ormanları, örene döndürdü,
Sakırgalar, tonla pirinç... yağmaladı.
Haziran ayı, yeşil bulutlar altında,
Evleri yanıp yıkılmış binlerce yaralı,
Dokuz milyon aç, döküldü yollara.
Kurudu anasütü, ölü doğdu bebeler
Altı ayın korkunç dökümü bu
"Yeni Yaşam Bölgesi" cehennemin adı.
Kana buladılar mart güneşini Viyetnam''da,
Canavarlar, kurşunladı ilkyazı.
Neresinde olursa, bizimkileyin
Bağımsızlık, onurlu yaşam savaşı,
Halk çeliğine su verilir her yerde
Kesin konuşur halkla Hoşimin:
"Yıkılıp gider reziller sonuçta."
Savaştı kadınlar, yaşlılar, çocuklar...
Her ilkyaz badem ağacı gibi çiçeklenir
Onurlu şehitlerin kızıl toprakları.', 'Bir güvercin uçurdum Ağrı''dan, Kanlar içinde anlattılar, dönünce: Kulağım gözüm tutuştu, sonra Yandım, yüreğimi sardı bir alev Milyonla tuts...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜWEY', 'uwey-umut-taydas-iokx8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"uzaklaşmana"
Bir sen, bir ben
Bir-liktelik
fasılasız beraber, bir ömür,
Bağımlı, tutkun, tutsak,
Bilsen bir ben,
Sana kaç kadar muhtaç.
Oysa sen beni
Hiç kadar sevsen,
Ben bir daha
Hiçbir şeyi
Hayal etmek ihtiyacı duymam.
Bilmem, bir ben
Bunları söylerken
Seni hep severken
Yıl 2002 olsa da
Bu dünyada sevmek diye bir anlam
Aşk diye bir dürşünlük kalmasa da
Ben, aldırmadan
Sevmekten, aşktan bahsederken,
Kördüğüm senin,
Defalarca halini,
Her şeye ve hiçbir şeye rağmen
Hayatın,
Adı, ölüm olan hayatın,
Derdinde oluşunu;
Hiçbir şeyin, hiçbir benin,
Seni hiçbir şey istemeyecek kadar,
Mutlu edemediğini bilmeyi,
Nasıl da sevmiyorum.
Seni nasıl da seviyorum.
Oysa senin sevişin başka,
Seni tatmin ediyor, ya,
Beni ?
Beni hiç kadar sev sen,
Ben sana her kadar müptela,
Hiç kadar sevsen beni,
Başka bir şey istemem.
07.06.2002; 23:49
"aşığım diyen birinin en büyük suçu;
vaat ettiklerini verememek değil, vaat etmek ve vermemek"', '"uzaklaşmana" Bir sen, bir ben Bir-liktelik fasılasız beraber, bir ömür, Bağımlı, tutkun, tutsak, Bilsen bir ben, Sana kaç kadar muhtaç. Oys...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":43}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'WITTGENSTEIN', 'wittgenstein-cevat-capan-aogub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimin içime sığmaması
Canevimde çırpınan
Küçücük bir kuş
Olmasından mıdır aklın?', 'İçimin içime sığmaması Canevimde çırpınan Küçücük bir kuş Olmasından mıdır aklın?...', ARRAY['Türk Edebiyatı','Şiir','Cevat Çapan']::text[], 8.5, '{"poet":"Cevat Çapan","poet_slug":"cevat_capan","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'XAVIER CUGAT', 'xavier-cugat-metin-eloglu-qk9aa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Amma da yaptın şıllık kız,
Dağlıysak, insan değil miyiz yani?
Koyunları sattık, vurduk üçbini;
Öküzleri sattık, vurduk beşbini;
Bu parayı mezara mı götüreceğiz?
Hele gel, seni vizon pöstekilere saram;
Koluma takıp Kervansaray''a gidem;
Sana Chat-Noir''lar  alam mı;
Kokluyanın burnu düşsün.
Joze İturbi''den, Xavier Cugat''tan
Sana pilâk alam mı?
O çalsın, sen tepinedur...
Seni eşek sütünden banyolara yatırıp,
Camel''ini binliklerle yakam mı?
Naylon''una ne verem?', 'Amma da yaptın şıllık kız, Dağlıysak, insan değil miyiz yani? Koyunları sattık, vurduk üçbini; Öküzleri sattık, vurduk beşbini; Bu parayı me...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin_eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'XIII', 'xiii-philip-larkin-e5dxp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağzımı yanaştırarak
Dedim akan suya :
Kuzeye ak, güneye ak,
Ne fark eder sonunda?
Sevgi olmayacak bulduğun.
Anlattım rüzgâra uzun uzun,
Sözlerimi aldı gitti :
Sevgi olmayacak bulduğun,
Salt kuşlar parlak dilli,
Salt bir ay, hep yolcu.
Sevgi olmayacak bulduğun:
Yok dinginlik özlemiyle
Yanan kolların, yok usun
Titreyen meleklerle,
Yok senin için ölüm korkusu.
Philip  LARKIN', 'Ağzımı yanaştırarak Dedim akan suya : Kuzeye ak, güneye ak, Ne fark eder sonunda? Sevgi olmayacak bulduğun. Anlattım rüzgâra uzun uzun, Sözl...', ARRAY['Türk Edebiyatı','Şiir','Philip  Larkin']::text[], 8.5, '{"poet":"Philip  Larkin","poet_slug":"philip_larkin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İYİ ADAMLAR ÖLMÜŞ', 'i-yi-adamlar-olmus-ernest-hemingway-wx7mh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onlar yuttu bizi içine;
Kral ve yurt,
Mesih Tanrı
Ve ölüm.
Vatanseverlik,
Demokrasi,
Onur-
Sözcükleri ve deyimleri,
Onlar soktu ve öldürdü bizi.
Paris 1922
Ernest  HEMINGWAY', 'Onlar yuttu bizi içine; Kral ve yurt, Mesih Tanrı Ve ölüm. Vatanseverlik, Demokrasi, Onur- Sözcükleri ve deyimleri, Onlar soktu ve öldürdü b...', ARRAY['Türk Edebiyatı','Şiir','Ernest  Hemingway']::text[], 8.5, '{"poet":"Ernest  Hemingway","poet_slug":"ernest_hemingway","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇİY OLURUM EĞER', 'ci-y-olurum-eger-s-ndor-petofi-0he9q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ağaç olurum eğer ağacın çiçeği isen...
Sen çiy isen ben çiçek olurum
Çiy olurum eğer güneş ışığı isen...
Sırf birleşelim diye.
Ey güzel kız, sen sevmek isen,
Ben bir yıldız olurum.
Ey güzel kız, sen cehennem isen;
Ölürüm birleşelim, diye...
Sándor PETOFİ', 'Ağaç olurum eğer ağacın çiçeği isen... Sen çiy isen ben çiçek olurum Çiy olurum eğer güneş ışığı isen... Sırf birleşelim diye. Ey güzel kız,...', ARRAY['Türk Edebiyatı','Şiir','Sándor Petofi̇']::text[], 8.5, '{"poet":"Sándor Petofi̇","poet_slug":"sandor_petofi","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İYİ ZAMANLAR İÇİN', 'i-yi-zamanlar-i-ci-n-osman-namdar-pgg8h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen uçurumumsun, eskizlerden devşirdiğim
resmi bir başlangıcım olmadığından tazeyim böyle,
eski kadırgaların kırık kaburgaları ve kanlı kumsallardı geldiğim.
Sen uçurumumsun; tadım buruk ve iyi
salkım saçak akdeniz''im, yüzüm çiçek bozuğu
ay zamanlarında çiçek tarhlarında öpeydin beni.
Poetikamız güzel olacak sevgilim,
en güzel kromozomlarımla döllendi kalbim.', 'Sen uçurumumsun, eskizlerden devşirdiğim resmi bir başlangıcım olmadığından tazeyim böyle, eski kadırgaların kırık kaburgaları ve kanlı kums...', ARRAY['Türk Edebiyatı','Şiir','Osman Namdar']::text[], 8.5, '{"poet":"Osman Namdar","poet_slug":"osman_namdar","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Y.S. YÖNTEMİ İLE', 'y-s-yontemi-i-le-yorgo-seferis-k2bch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nereyi gezsem Yunanistan yaralar beni.
Pilyo''da kestane ağaçları arasında Sentavr''ın gömleği
vücuduma sarılmak için yapraklar içinde kayardı,
yokuşu tırmanırken deniz izlerdi beni:
o da tırmanırdı termometrenin cıvası gibi
dağ sularına ulaşıncaya kadar.
Batık adalara elimi değdirirken Sandorini''de
sünger taşlarında çalınan kavalı dinlerken,
elimi küpeşteye çiviledi
yitik bir gençliğin uzak sınırlarından
ansızın atılan bir ok.
Büyük taşları, Atpidonlar''ın hazinesini kaldırdım Mikine''de
ve yanyana yattım "Menelaos''un Güzel Helen''i" otelinde onlarla;
Ancak sabah olup da kara boynuna asılı bir horozla
ötünce Kassandra kayboldular.
Bıktım midem bulandı gemici türkülerinden
Speçes''te, Pros''ta, Mikonos''ta.
Ne isterler acaba Atina ya da Pire''de
bulunduklarını söyleyen bütün bu insanlar?
Biri Salamina''dan gelip "Omoniya''dan mı geliyorsun" diye sorar ötekine,
"Hayır, Sintagma Alanı''ndan geliyorum" diye yanıtlar öteki, memnun
"Yani''yi gördüm, dondurma ikram etti bana."
Yunanistan geziyor bu arada
hiçbir şey bilmiyoruz, nasıl dışında kaldık sefere çıkan gemilerin, bilemiyoruz,
bütün gemiler seferdeyken denizlerde limanın çektiği acıyı bilmiyoruz
ve alay ediyoruz bu acıyı tanıyanlarla.
Atik''te bulunduklarını söyleyen ve hiçbir yerde olmayan garip insanlar;
insanlar;
evlenmek için şekerlemeler alırlar
resim çektirirler ellerinde saç ilaçlarıyla,
Bugün kumrulu, çiçekli bir perde önünde otururken gördüğüm adam
ses çıkarmıyordu yaşlı fotoğrafçının
gökteki bütün kuşların yüzünde bıraktığı kırışıkları düzeltmesine.
Yunanistan geziyor bu arada durmadan geziyor Yunanistan,
ve eğer "cesetlerle çiçek açmış Ege''yi görürsek"
yüzerek yüce gemiyi yakalamak isteyenlerin cesetleridir
kımıldamayan gemileri beklemekten usanmış olanlardır:
ELSİ''yi, SAMOTRAKİ''yi, AVRAKİKOS''u.
Pire''de akşam olurken vapur düdükleri öter,
durmadan öter, öter, ama tek bir baba kımıldamaz yerinden
kaybolan ışıkta hiçbir zincir ıslanıp parıldamaz,
beyaz ve altın renkler içinde mermerleşerek durur kaptan.
Nereyi gezsem Yunanistan yaralar beni,
Dağ perdeleri, takımadalar, çıplak granitler...
AG ONİA 937 sefere çıkan geminin adı.
M/S Aulis, demir almasını beklerken,
Yaz, 1936
Yorgo SEFERIS', 'Nereyi gezsem Yunanistan yaralar beni. Pilyo''da kestane ağaçları arasında Sentavr''ın gömleği vücuduma sarılmak için yapraklar içinde kayardı...', ARRAY['Türk Edebiyatı','Şiir','Yorgo Seferis']::text[], 8.5, '{"poet":"Yorgo Seferis","poet_slug":"yorgo_seferis","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞ DOLAR YÜREĞİME', 'yas-dolar-yuregi-me-arthur-rimbaud-xiutn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Yağmur çiseliyor kente''
Arthur Rimbaud
Yaş dolar yüreğime
Yağan yağmur misali.
Nedir bu usanç söyle
Yerleşen canevime?
Ey tatlı yağmur sesi
Damlar üstünde, yerde!
Bungun kalp hediyesi,
Ey yağmurun türküsü!
Sebepsiz dolduruşu
Tiksinti duyan kalbi,
İhanet değil, ne bu?
Sebepsiz bir kuruntu.
Odur en kötü tasa
Bilmemek niçin''ini.
Ne bir kin, ne bir sevdâ,
Kalbimde bunca cefâ.
Paul VERLAINE', '''Yağmur çiseliyor kente'' Arthur Rimbaud Yaş dolar yüreğime Yağan yağmur misali. Nedir bu usanç söyle Yerleşen canevime? Ey tatlı yağmur sesi...', ARRAY['Türk Edebiyatı','Şiir','Arthur Rimbaud']::text[], 8.5, '{"poet":"Arthur Rimbaud","poet_slug":"paul_verlaine","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YA KİMDİR GİDEN ORADA?', 'ya-ki-mdi-r-gi-den-orada-yanko-kupala-uf6ks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ya kimdir, kimdir giden orada
Böyle büyük bir kalabalıkla?
-Beloruslar.
Ya nedir taşıdıkları sıska omuzlarında
Kanlı ellerinde, çarıklı ayaklarında?
-Uğradıkları zulüm, haksızlık.
Ya nereye taşıyorlar zulmü, haksızlığı
Ya kimi dökecekler acılarını?
-Tüm dünyaya.
Ya kimden öğrendi bu milyonlarca insan
Yola düşmeyi, kim uyandırdı onları uykudan?
-Yoksulluk, dert.
Ya nedir, nedir istediği onların
Çağlardır hor görüşmüşlerin, körlerin, sağırların?
-Adam yerine konulmak.
Yanko KUPALA', 'Ya kimdir, kimdir giden orada Böyle büyük bir kalabalıkla? -Beloruslar. Ya nedir taşıdıkları sıska omuzlarında Kanlı ellerinde, çarıklı ayak...', ARRAY['Türk Edebiyatı','Şiir','Yanko Kupala']::text[], 8.5, '{"poet":"Yanko Kupala","poet_slug":"yanko_kupala","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞADIK MI?', 'yasadik-mi-ozcan-yalim-24hcf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dinçer Sezgin''e
Yenilen bir ordunun demirbaşından
Silindi silinecek
Bir asker kaputu sırtında
Sol kolu katlanmış iğnelenmiş
Ağarmış rengi her geçen yazla
Güz güz dökülmüş düğmeleri
İçinde - ıssızlığın bile koyup gittiği -
Koyaklar boyu peribacaları
Sevginin güzelliğin peribacaları
Dostlukların peribacaları
Silindi silinecek
Yenilen bir ordunun demirbaşından
Üstünden akadursun sular zamanın
Elini gülüne koy - de bana
Üzüle üzüle aşına aşına
Sonunda ne kalır yaşamaktan?
Yaşamdı yaştı derken
Bir lokma aşa indirgenince - de bana
Geriye ne kalır yaşamaktan?', 'Dinçer Sezgin''e Yenilen bir ordunun demirbaşından Silindi silinecek Bir asker kaputu sırtında Sol kolu katlanmış iğnelenmiş Ağarmış rengi he...', ARRAY['Türk Edebiyatı','Şiir','Özcan Yalim']::text[], 8.5, '{"poet":"Özcan Yalim","poet_slug":"ozcan_yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞADIKÇA', 'yasadikca-nihat-behram-mkg2v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah benim aşkla beslediğim
sevgilim
kalbimi zorlayan heyecanla sana
savaşın gitgide yaklaşan uğultusuyum
Günler
sazlarla çevrili göl kıyısında
suyun inanılmaz berraklığıyla çalkalanıp geçti
serçeler karla yıkadı tüylerini
taşların oyuklarına doluşan kertenkeleler
düşlerimde zamanla silikleşti
Bazan düşünmek acı veriyor bana
içimde yırtılarak uzaklaşan çayırları
Ah, benim aşkla beslediğim sevgilim
bütün güzel şarkıları sanki ben bestelemişim
üstelik merakla bakıyorum tanıdık her yüze
Çayırları düşün
anamdan emdiğim sütün tadı
yırtarak uzaklaşan çayırları
Artık tek afiş kan kokusu şehrin sokaklarında
gerisi düşmanın kurduğu pusu
kan kokusu diyorsam
ah, benim aşkla beslediğim sevgilim
kalbimi zorlayan heyecanla sana
savaşın gitgide yaklaşan uğultusuyum
Nihat', 'Ah benim aşkla beslediğim sevgilim kalbimi zorlayan heyecanla sana savaşın gitgide yaklaşan uğultusuyum Günler sazlarla çevrili göl kıyısınd...', ARRAY['Türk Edebiyatı','Şiir','Nihat
behram']::text[], 8.5, '{"poet":"Nihat\nbehram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAM', 'yasam-yusuf-altunel-ryqgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'arzunun küllerini dağıtır
kırık ansımalar rüzgarı
kovalar yorgunluklar bulutları
fırtınalardan kaçak doluluklar
yüklerini istekler ateşine boşaltırlar
havalanır arzulardan kıvılcım
karanlık geceleri
yaldızlı ciltlere sararım
umutsuz haykırışlar düşer
uçurumun dibinde anılardan leşler
bir gülün dudaklarında uyanır
çiğ damlası yalnızlık
yorganına işlenmiştir yıldızlar
havalanır bakışlarımın güvercini
ayın öptüğü
dudaklarına yumuşacık konar
hazırdır kendini vermeye
yorgun orospu korkular
ama ayrıntılara bölünmüştür
eli kanlı düş-katili yaşam
ayrılıklar taşır ileriye
ileriye hep her an
ve paramparçadır
bizi kendine zincirlemiş
vakitsiz acılar yüklü zaman
birazcık
gözlerimizin kestanesinden
havalanan öpüşleri düşlemektir yaşam
can alacası renklere boyalı
elde edilememişliklere
konan haylaz kelebek
kartal bakışlarca yaralı
kanayan yumuşaklık
hiç ulaşılmayan
yol kenarına düşmüş
can çekişen bedenler
farkına varmadan yaşanılan
dağınık anılardan dikenler
soluk geçmişi iletiyor
düş-renkli geleceğe
elimizde yitik anahtar
arıyoruz olmayan kapıları
poyraz esiyor üstümüze
hep poyraz
yaşanmamış mutluluklardan zaman', 'arzunun küllerini dağıtır kırık ansımalar rüzgarı kovalar yorgunluklar bulutları fırtınalardan kaçak doluluklar yüklerini istekler ateşine b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":47}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMA SANCISIYLA', 'yasama-sancisiyla-eugenio-montale-dm7fr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç kez karşılaştım yaşama sancısıyla:
yolu kesilmiş, dereydi, uğuldayan,
kıvrılmasıydı yanan kâğıdın,
yere çökertilmiş attı.
Mucizeydi tanıdığım tek iyi şey
tanrısal ilgisizliği başlatan:
yontuydu o, öğleden sonra ağırlığında
ve buluttu ve yükseklerde süzülen doğan.
Eugenio MONTALE', 'Kaç kez karşılaştım yaşama sancısıyla: yolu kesilmiş, dereydi, uğuldayan, kıvrılmasıydı yanan kâğıdın, yere çökertilmiş attı. Mucizeydi tanı...', ARRAY['Türk Edebiyatı','Şiir','Eugenio Montale']::text[], 8.5, '{"poet":"Eugenio Montale","poet_slug":"eugenio_montale","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMA SEBEBİ', 'yasama-sebebi-kaan-i-nce-z0xwm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sıkmışım dişlerimi gözlerim kanayana kadar
çeyizimizde hüzün motifleri
göçebe bir ağıt göğsümün derinliklerinde
bu aşkın dönüşü yoksa
duman kırığı gözlerinde gecenin hıçkırıkları
kırık keman sesi ve adağım var
moraran hercai düşlerim ateşi delip ıslatır mendilimi
kalbime dolar -sonsuz uykuma- korkuya susamış yasadışı bir rüzgâr
bu aşkın dönüşü yoksa
suya düşer kokusu menekşelerin
deniz her zamankinden daha köpüklü
serçeler bi garip ötüşlüdür
martıları mavnalarla başka türlü danseder hamuruna sevgi katılmış bu dünyanın
küflü yüzler yok hiçlik de
hani ne derler gözlerinden öperim çocuk,gamlı sevda, şiir
ne''m kalır geriye gülüm seni alırlarsa benden
tiksintiler toplamı umutsuzluk sapağında ölüm', 'sıkmışım dişlerimi gözlerim kanayana kadar çeyizimizde hüzün motifleri göçebe bir ağıt göğsümün derinliklerinde bu aşkın dönüşü yoksa duman ...', ARRAY['Türk Edebiyatı','Şiir','Kaan İnce']::text[], 8.5, '{"poet":"Kaan İnce","poet_slug":"kaan_ince","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMAK ARTIYOR', 'yasamak-artiyor-eug-ne-guillevic-qo8n1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman bize derler:
Yaşamakta bir artış var,
Demek istemezler kadınların
genişledi bedenleri.
Demek istemezler boyu uzun
ağaçların bulutlardan.
Yolculuk edilebilir
demek istemezler
birazcık bir çiçekte.
Sevişenler her gün sabahtan
akşama dek sarmaş dolaş
demek istemezler.
Demek isterler ki düpedüz
zorlaşmada gittikçe
insanca yaşamak.
Eugène  GUILLEVIC', 'Ne zaman bize derler: Yaşamakta bir artış var, Demek istemezler kadınların genişledi bedenleri. Demek istemezler boyu uzun ağaçların bulutla...', ARRAY['Türk Edebiyatı','Şiir','Eugène  Guillevic']::text[], 8.5, '{"poet":"Eugène  Guillevic","poet_slug":"eugene_guillevic","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMAK GİBİ', 'yasamak-gi-bi-ali-cengi-zkan-cqjlh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-C.A. Kansu''nun anısına-
Küçük şeyleri sevmeliyim,
Dedem Ceyhun öğütledi.
Çolak amcamın demlediği
Bergamut tütsülü çayları,
Zından demirlerinde akşam
Karanlığı gözaltında tutanı,
Ay çevrende dinlenirken
Sürmeli kızımın bakışını,
Dışarda elleri bahar,
İçerde deli eden âşıkları,
Simit yemeyi yürürken,
Sevdiğimi sokakta öpmeyi,
Bir çiçek duruşunda dimdik
Kavgada ön safta gitmeyi,
Tıkız bebeleri kucaklarken
Doksanlık ninemce ağlamayı,
Gülü, reyhanı, nergisi,
Bir de maddeci diyalektiği,
Küçük şeyleri seviyorum,
Dedem Ceyhun yol gösterdi.
Son ıpıl bakışında gördüm,
Dedem ölümü de sevdi.', '-C.A. Kansu''nun anısına- Küçük şeyleri sevmeliyim, Dedem Ceyhun öğütledi. Çolak amcamın demlediği Bergamut tütsülü çayları, Zından demirleri...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMAK VE SEVMEK ÜSTÜNE', 'yasamak-ve-sevmek-ustune-kutsiye-bozoklar-z48as', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçli bir ezgi tadında yaşamak istiyorum.
-her söylenişte güzelleşen-
Şarap tadında sevilmek
-en iyi bağ bozumlarının ürünü-
ve sevmek şiircesine
Yepyeni bir dünya için
değişmek ve değiştirmek hiç durmadan
ve usulca ölmek sonra
-tohuma durmuş çiçek gibi-
İNSAN olmanın sevinciyle
ve sonsuz hüznüyle ardında
aydınlık bir sabah bırakmanın', 'İçli bir ezgi tadında yaşamak istiyorum. -her söylenişte güzelleşen- Şarap tadında sevilmek -en iyi bağ bozumlarının ürünü- ve sevmek şiirce...', ARRAY['Türk Edebiyatı','Şiir','Kutsiye Bozoklar']::text[], 8.5, '{"poet":"Kutsiye Bozoklar","poet_slug":"kutsiye_bozoklar","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMAK', 'yasamak-zubeyir-kindira-2cqs9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşamak için kendimize
Ne bir gökyüzü ne denizler
Yaşamak için yetiyor bize
Sahte hüzünler', 'Yaşamak için kendimize Ne bir gökyüzü ne denizler Yaşamak için yetiyor bize Sahte hüzünler...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Kindira']::text[], 8.5, '{"poet":"Zübeyir Kindira","poet_slug":"zubeyir_kindira","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMANIN EN TEHLİKELİ ÂNI', 'yasamanin-en-tehli-keli-ni-c-sar-vallejo-k49jn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir adam dedi ki:
En tehlikeli an yaşamımda, Marne çarpışmasındakiydi.
bir kurşun saplanmıştı göğsüme.
Bir başka adam dedi ki:
En tehlikeli an yaşamımda, Yokohama''daki bir mette
bir boyacı dükkânının saçağı altına
bir mucize gibi sığınışımdı.
Ve bir başka adam dedi ki:
En tehlikeli an yaşamımda,
eğer gündüzün uyuyorsamdır.
Ve bir başkası dedi ki:
En tehlikeli an yaşamımda,
en yalnız olduğum zamandı.
Ve bir başkası dedi ki:
En tehlikeli an yaşamımda,
Peru''daki tutukluevinde ikendi.
Ve bir başkası dedi ki:
En tehlikeli an yaşamımda,
babamı ansızın yandan yakalamamdı.
Ve sonuncu adam dedi ki:
En tehlikeli an yaşamımda,
henüz gelmedi.
César VALLEJO', 'Bir adam dedi ki: En tehlikeli an yaşamımda, Marne çarpışmasındakiydi. bir kurşun saplanmıştı göğsüme. Bir başka adam dedi ki: En tehlikeli ...', ARRAY['Türk Edebiyatı','Şiir','César Vallejo']::text[], 8.5, '{"poet":"César Vallejo","poet_slug":"cesar_vallejo","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMI', 'yasami-kazi-nazrul-islam-k6bmp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '24 Mayıs 1899''da Batı Bengal''de Bardhaman bölgesinde Churulia köyünde doğdu,
29 Ağustos 1976''da Dhaka''da öldü.', '24 Mayıs 1899''da Batı Bengal''de Bardhaman bölgesinde Churulia köyünde doğdu, 29 Ağustos 1976''da Dhaka''da öldü....', ARRAY['Türk Edebiyatı','Şiir','Kazı Nazrul Islam']::text[], 8.5, '{"poet":"Kazı Nazrul Islam","poet_slug":"kazi_narul_islam","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞAMIM', 'yasamim-baris-gulteki-n-3cf28', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yaşamım
eğreti bir ev taslağı
karalanmış kağıtlar üzerinde
temeli olmayan.
yaşamım
yapayalnız kalmış
ölümcül bir eylem
düşünülmeden kurulmuş devrik cümlelerin ortasında.
yaşamım
bir tanrı hüznü
yaptıklarının
yarattıklarının umursanmazlığına.
yaşamım
kuyruksuz bir sokak itinin
kendini kuyruklu gördüğü
yalancı bir rüya.
aslında benim yaşamım da sizinkisi gibi
nereye çarpacağı belirsiz
yuvarlanıp giden bu küçücük dünya
başka birşey değil ........', 'yaşamım eğreti bir ev taslağı karalanmış kağıtlar üzerinde temeli olmayan. yaşamım yapayalnız kalmış ölümcül bir eylem düşünülmeden kurulmuş...', ARRAY['Türk Edebiyatı','Şiir','Barış Gülteki̇n']::text[], 8.5, '{"poet":"Barış Gülteki̇n","poet_slug":"baris_gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞANMAMIŞ ÇOCUKLUĞUN TÜRKÜSÜ', 'yasanmamis-cocuklugun-turkusu-afsar-ti-muci-n-4l1oe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir de onlar inancı örer gibi
Kendilerini gererler boşluğa ölüm gibi
Bir günlük çocukluğa bin yılını verirdin
Artık çocuk değilsin büyüdün artık
Yolda yürürken kendine dikkat et
Yemek yerken sakın üstüne dökme
Kömür mü taşıdın kapkara tırnakların
İyi bir işin olsun gösterişli bir çantan
Güzel bir ceket pantolon yaptır
Annenin elini öp dostlarına telefon et
Bir sözün bir sözünle çelişmesin
Sokakta türkü söyleme ayıptır
İçinden gelmese de
Her zaman bir şeyler yapacakmış gibi dur
Şiir ve aşk üstüne konuşmayı bil
Donla denize girme çok içme rakıyı
Ne olursun o berbat kasketi değiştir
Bir günlük çocukluğa bin yılını verirdin
Ama çocuk olmadın bir gün bile
(Büyük insan gibidir benim yavrum)
Sen şimdi sessiz bir deniz kıyısında
Dönüşsüz büyümüşlüğünle durmadan
Panayırlar balonlar kayıklar özlüyorsun', 'Bir de onlar inancı örer gibi Kendilerini gererler boşluğa ölüm gibi Bir günlük çocukluğa bin yılını verirdin Artık çocuk değilsin büyüdün a...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞARKEN', 'yasarken-sukran-kurdakul-4abr0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cehennem yarasaları gibi vurdular cama
Örgütlenmiş hüzünlerin askerleri.
Ölümsüz sözcüklerle tuttum siperi,
Güzellendi yüreğim, deli oldum yazgıma.', 'Cehennem yarasaları gibi vurdular cama Örgütlenmiş hüzünlerin askerleri. Ölümsüz sözcüklerle tuttum siperi, Güzellendi yüreğim, deli oldum y...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YABAN BALI ÖZGÜRLÜK KOKAR', 'yaban-bali-ozgurluk-kokar-anna-ahmatova-3vwap', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaban balı özgürlük kokar,
Toz, güneş ışını kokar,
Bir kızın ağzı -menekşe
Ve altın -hiçbir şey kokmaz altın.
Tereotu su kokar,
Aşk ise elma,
Ama biz, biliyoruz artık
Yalnız kan kan gibi kokar…
Romalı yöneticinin halkın önünde
Topluluğun ölüm bağırtıları altında,
Ellerini yıkaması boşunadır,
İskoçya kraliçesinin* sıska avuçlarını
Oğuşturması boşunadır
Kan damlalarını silmek için
Kral sarayının boğucu karanlığında…
1933
* Lady Macbeth
Anna AHMATOVA', 'Yaban balı özgürlük kokar, Toz, güneş ışını kokar, Bir kızın ağzı -menekşe Ve altın -hiçbir şey kokmaz altın. Tereotu su kokar, Aşk ise elma...', ARRAY['Türk Edebiyatı','Şiir','Anna Ahmatova']::text[], 8.5, '{"poet":"Anna Ahmatova","poet_slug":"anna_ahmatova","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YABANCI DİL', 'yabanci-di-l-cemal-sureya-m7icz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beş dil biliyormuş ünlü kişi
Ünlü ve saygıdeğer
Bir de Türkçe öğrense
Altı eder', 'Beş dil biliyormuş ünlü kişi Ünlü ve saygıdeğer Bir de Türkçe öğrense Altı eder...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal_sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YABANCI KALAN', 'yabanci-kalan-sukran-kurdakul-o7y7d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her dakikasında ayrı ayrı
Gözlerime doğru büyüyor zaman
Bir anlam yüz anlama doğru bende
Bin çağrışımın altında ezilen başım
Hangi aydınlığı bularak kendi kendinde
Harfleri, sözcükleri, kavramları
Nereye ulaştıracak.
"E" harfleri şapkalı "A" larla teker-meker
Durmuyor tutsak karanlığı
Durmuyor çember.
Varım işte, her gece, varla yok arası
Matrisler dağılırken ses olarak
Kendi usumda bir soru işareti gibi
Ve harflerin çemberinde çırılçıplak
Sanki özgür, sanki insan,
Ve sanki üç çocuk babası.
Varım işte,
Her gece yeniden dizmeye mahkûm
Beliklerimde zincir, makinaya tutsak.
Haberler geliyor,
Artık kendine bile yabancı bir dünyadan
Azgın ve biraz daha eski
Diziyorum, Sisif''in kayasına bırakılmış gibi
Haberler geliyor
İçimdeki yangına biraz olsun su...
Hece bir düşman gibi alıyor gözlerimi
Sonsuz bir yıldız gibi akıp duran
Yirmi dokuz silah ellerimin varlığına.
Bildirisinde, eyleminde, demecinde,
Kan içinde Vietnam haberleri
İnsanı bölen, insanı ağrıyan.
"E" harfleri şapkalı "A" larla teker-meker
Durmuyor tutsak karanlığı
Durmuyor çember.
Sözcüklerin ne kadar birleştiği,
Bu çark söylemeli artık.
Neden döndüğünü yazılarda.
Düşünceler, düşünceler, düşünceler,
Hangi gerçek, kimin gerçeği.
"E" harfleri şapkalı "A" larla teker-meker
Durmuyor tutsak karanlığı
Durmuyor çember.', 'Her dakikasında ayrı ayrı Gözlerime doğru büyüyor zaman Bir anlam yüz anlama doğru bende Bin çağrışımın altında ezilen başım Hangi aydınlığı...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":44}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YABANCI', 'yabanci-charles-baudelaire-y6l8q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-En çok kimi seviyorsun garip yabancı?
Anneni mi, babanı mı, kardeşlerini mi?
-Ne annem var, ne babam, ne de kardeşlerim.
-Vatanını mı?
-Nerde olduğunu bile bilmiyorum.
-Yoksa parayı mı?
-Nefret ederim ondan.
-O halde neyi seversin esrarlı yabancı?
-Bulutları severim.
Karşıdan gelen ve karşılara giden bulutları.
Charles  BAUDELAIRE', '-En çok kimi seviyorsun garip yabancı? Anneni mi, babanı mı, kardeşlerini mi? -Ne annem var, ne babam, ne de kardeşlerim. -Vatanını mı? -Ner...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YADİGÂR', 'yadi-g-r-fikret-kizilok-w74r2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne derdi var ne tasası
Dört duvarı çerçevesi
Ortasında sen
Bende hicran yarası
Kendimi içip bardaktan
Tutuşup sigaramdan
Alev alev toz duman
Yangın olurum gece yarısı
Kendine çalar saatler
Kendi bekler acelem
Nereye giderim ki
Kime kapanır pencerem
Kendine söner lambalar
Kendi uyur uykular
Sabaha kalmış gözlerim
Yine de yalnız değilim
Sen varsın
Hasretin var
Bize bizden kalan
Kahrolası acılar
Sen varsın
Yokluğun var
Bize bizden kalan
Kahrolası acılar', 'Ne derdi var ne tasası Dört duvarı çerçevesi Ortasında sen Bende hicran yarası Kendimi içip bardaktan Tutuşup sigaramdan Alev alev toz duman...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kizilok']::text[], 8.5, '{"poet":"Fikret Kizilok","poet_slug":"fikret_kizilok","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞDIĞINI DÜŞÜNÜYORUM', 'yagdigini-dusunuyorum-wole-soyi-nka-mtsmz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağdığını düşünüyorum onun
Kuraklıktan salıverilmiş diliyle
Ağzının açılmamış tepelerinden, dolarak
Yüklü müjdeyle,
Onun yükseldiğini gördüm
O apansız bulutu, küller içinden. Yerleşerek
Buluştular kül rengi bir çemberde, içinde
Durmadan dönen bir ruh.
Ah, o yağmalı elbette
Akıldaki bu kuşatma tutmalı bizi
Tuhaf kederler içinde, öğreterek
Kederin sessizliğini.
Ve onun nasıl çırpındığını
Ürkütüp saydam şeyleri kanatları üstünde
Bizim istediklerimizin, koyu özlemleri yakıp
Kaçınılmaz vaftiz törenlerinde.
Yağmur düdükleridir çalınan
Boyun eğme inceliğinde,buralardan uzakta.
Hâlâ boyun eğmeyen, bu, benim
Çıplak kayaları çöken dünyamın
Buluşmasıdır seninle.
Wole SOYİNKA', 'Yağdığını düşünüyorum onun Kuraklıktan salıverilmiş diliyle Ağzının açılmamış tepelerinden, dolarak Yüklü müjdeyle, Onun yükseldiğini gördüm...', ARRAY['Türk Edebiyatı','Şiir','Wole Soyi̇nka']::text[], 8.5, '{"poet":"Wole Soyi̇nka","poet_slug":"wole_soyinka","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YADSIMA', 'yadsima-yorgo-seferis-fgm8n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir güvercin gibi ak
o gizli kıyıda
susadık öğle üzeri:
ama tuzluydu sular.
Sarı kumların üstüne
adını yazdık onun,
ama bir rüzgâr esti denizden
ve silindi yazılar.
Nasıl bir ruh, bir yürek,
nasıl bir istek ve tutkuyla
yaşadık:yanılmışız!
Değiştirdik öyle yaşamayı.
Yorgo SEFERIS', 'Bir güvercin gibi ak o gizli kıyıda susadık öğle üzeri: ama tuzluydu sular. Sarı kumların üstüne adını yazdık onun, ama bir rüzgâr esti deni...', ARRAY['Türk Edebiyatı','Şiir','Yorgo Seferis']::text[], 8.5, '{"poet":"Yorgo Seferis","poet_slug":"yorgo_seferis","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAHYA KEMAL BEYATLI', 'yahya-kemal-beyatli-sait-maden-ck83c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelsen deniz coşar, kapanır gök ve bir şiir
Alnımda yelken üstüne yelken değiştirir.', 'Gelsen deniz coşar, kapanır gök ve bir şiir Alnımda yelken üstüne yelken değiştirir....', ARRAY['Türk Edebiyatı','Şiir','Sait Maden']::text[], 8.5, '{"poet":"Sait Maden","poet_slug":"sait_maden","theme":"Türk Şiiri","is_hero":false,"total_lines":4}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞIYORUZ', 'yasiyoruz-rifat-ilgaz-vj7x5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Lütfü Erişçi''ye
Ben ölmedim…
Beni öldürmediler de;
Yaşıyorum, yaşıyorum işte,
At kıçında sinek gibi,
Töööbe, töbe!
Kapandı yüzümüze dergi kapakları,
Bir varmış bir yokmuş olduk sağlığımızda.
Şiir… O yosmanın boyuna.
Gazete… Gelene gidene başyazı.
Ara ki bulasın sayfalarda
Şair Rıfat Ilgaz''ı.
Düştükse itibardan
Ölmedik ya, yaşıyoruz işte,
Yaşıyoruz dedik, yaşıyoruz be,
Heeeey, fincancı katırları!
Devam adlı şiir kitabından 1943
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Lütfü Erişçi''ye Ben ölmedim… Beni öldürmediler de; Yaşıyorum, yaşıyorum işte, At kıçında sinek gibi, Töööbe, töbe! Kapandı yüzümüze dergi ka...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAK SEVDANIN ÇIRASINI', 'yak-sevdanin-cirasini-ahmet-telli-0u7q4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne hüzünler kurtarır seni
ne çeyiz sandığının ceviz gölgesi
ve ne de acının ses duvarındaki
yorgun ve bıkkın bekleyişler
Acılar karartmışsa bile günlerin duvağını
düşürmüşse de ilkyazın tomurcuklarını fırtınalar
hayat kendini yeniden yaratan bir bahardır
verecektir en olgun meyvelerini mutlaka
yeter ki hüzünler sarartmasın yüzünü
Yak sevdanın çırasını türkülerle
barajını yıkan bir ırmak gibi katil hayata
hüznün isyana dönsün artık
bitsin bezginliğin ölümcül suskunluğu
evde kalmış bir cinsellik değildir çünkü dünya', 'Ne hüzünler kurtarır seni ne çeyiz sandığının ceviz gölgesi ve ne de acının ses duvarındaki yorgun ve bıkkın bekleyişler Acılar karartmışsa ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli̇']::text[], 8.5, '{"poet":"Ahmet Telli̇","poet_slug":"ahmet_telli","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAKARIŞ', 'yakaris-hristo-botev-ptmxj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey tanrım, ey adalet tanrısı!
Sen değil, göklerde oturan!
İçimizdeki sen, ey tanrım,
içimdeki, yüreğimdeki, ruhumdaki!
Önünde papazların
ve rahiplerin eğildikleri,
Ortodoks sürülerinin mum yaktıkları,
sen değil.
Çamurdan yaratıp kadını erkeği,
sonra da yarattıklarının toprak üstünde
köle gibi yaşamalarına razı olan,
sen değil.
Acı çekmeyi öğreten kölelere,
boş umutlarla besleyen
onları ta mezara dek,
sen değil.
Ey yalancıların tanrısı, sen değil!
alçakların, zorbaların tanrısı,
insanlığın düşmanı, salakların putu,
sen değil.
Sen, ey aklın tanrısı, sen!
Tüm köleleri koruyan!
Çok yakın kurtuluş günü o kölelerin,
tekmil halk yakında kutlayacak o günü!
Uyandır tek tek her insanda, ey tanrım,
gerçek özgürlük sevgisini,
taksın canını dişine, dövüşsün,
halkı ezenlere karşı.
Güç ver benim de koluma, silâhıma,
başkaldırdığı gün köleler!
Güç ver ki, ben de kendi mezarımı
dövüşenler arasında bulayım!
Koma yaban ellerde sönsün
yalım yalım yanan bu yürek.
Sesim boşa gitmesin,
sesim kalmasın çöllerdeki gibi
yankısız.
Hristo BOTEV', 'Ey tanrım, ey adalet tanrısı! Sen değil, göklerde oturan! İçimizdeki sen, ey tanrım, içimdeki, yüreğimdeki, ruhumdaki! Önünde papazların ve ...', ARRAY['Türk Edebiyatı','Şiir','Hristo Botev']::text[], 8.5, '{"poet":"Hristo Botev","poet_slug":"hristo_botev","theme":"Türk Şiiri","is_hero":false,"total_lines":40}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAKILMIŞ', 'yakilmis-yusuf-altunel-vt20m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'suya düşmüş söğüt
kara saçları
ağzı hamarat
hanı umut
göğüsler uçarı
çıplak üşümüş dudakları
kelimeler yola düşmüş
ankara-istanbul katarı
hınzırlık durağında saltanatları
biçmişim saflığında burçaklar
haydut acılardan sakındığım
gözlerinde pırpır
yaramaz kelebekler avlamışım
sığınışlar konağında bıraktığım
avunmalar beklemeler çağırmış
yanağımda kervan kurmuş gözyaşlarım
tatlı muhabbet çayda içtiğimiz
ürkek dokunmalar sıcacık simidimiz
taze kaynatılmış ıhlamur gülüşler
marazlı alınmalara şifa dökülmüşler
düşlerimin sınırsızlığını kavramış
koynundaki engin deniz
gemimiz taşıyor sevgiyi okyanuslara
yalnızlık limanlarında ürettiğimiz
uykuda öptüğün yastığı dişlemişim
bakaya gecelerimde seni beklemişim
gülüşünde ürküttüğün haylaz menevişleri
ıssız kuytularda içime çekmişim
muştuladı alacalı gelişini
şafağı çağıran kuşlar
sevinçleri ayaklandırıp haykırışlar
ayaklarına sedef cıvıltılar serdi
sevdan bıçağıyla parça parça liğme liğme
sana vurgun doğranmış yüreğimi serdi
ödünç verdiğin canı bakışınla dağladım
mesul zülfüne umut atımı bağladım
yakılmış köy yeridir şimdi yüreğim', 'suya düşmüş söğüt kara saçları ağzı hamarat hanı umut göğüsler uçarı çıplak üşümüş dudakları kelimeler yola düşmüş ankara-istanbul katarı hı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":39}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAKILMIŞLAR AĞIDI', 'yakilmislar-agidi-huseyin-yurttas-fd5l7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1.
Şair
gece vezniyle yaz bu şiiri
karanlıkta uğuldasın dizelerin
bilirim, yüreğe yüktür kin dediğin
ki bu senin şair, bu hercai yüreğin
yosun tutmaz bir çakılıdır
anadolu derelerinin
bağışlasın seni asım bezirci
behçet ve metin
bağışlama sen onları öldüreni
çün kanı yerde şiirin
şair
gece vezniyle yaz bu şiiri
karanlıkta uğuldasın dizelerin
2.
külün söylediği yangındır yangının meselidir
onunla uç sen eğer yanmış isen
çığlık dediğin onun en gökselidir
3.
derin derin sustuğum bir zamandı
ıssızdı dilim, kırgındı ilim
rüzgârsızdı yelken, susuzdu telli kavak
gün buluta girmiş gibiydi
yorgunluk duygusuna benzer
kötümser bir hava her yanda
o gündü
bir uzak bir uzak
sivas dedikleri toprak
telefonlar imkansız
iki elim iki böğrümde
ha canım
bir ses veren olsa
tüten dumandan
bir haber veren
sularım durulacak
o gündü
bir uzak
bir uzak
sivas dedikleri toprak
''metin'' olmak elimde değil
''behçet'' engiz şiirler yazmak geliyor içimden
vurmak karanlığa bir yalım gibi
geçip gitmek
onu eriterek
hey gidi
ne çare
yanıyor madımak
4.
sisliyim, sokulma bana
dağlarım kayıp, yamaçlarım yok
yankılanmıyor sesim, silinmiş görüntüm
aynalarım buğulu
yalnızlığa sal beni
kırlangıçlar uçur sularımda
turna katarları geçer göklerimden
gecelerin ürkek aydınlığında
dualar gibi ödenen
taze ölüler vardır hani
için erer onları düşündükçe
soğuk toprakta ilk geceleridir
anımsamaktan korkarsın
işte öyle şimdi
sivas bir mezarlık bana
garip şey, üşüyen yok
ve inadına tütüyor toprak hâlâ
5.
oğlunun kanlı giysilerini saklayan ana gibi
saklıyorum o günlerin gazetelerini
burnumda kokunuz
belli ki çok kanayacak şiirim
en çınçınlı gülüşümün ardında acınız
ağıdım sonsuz
sivas''ta şimdi göğe uzaman
alevden bir ölüm heykeli
içim buz
6.
şairler yakılıyorsa ülkende
daha çok şiir oku çocuk
şairler yakılıyorsa ülkende sende
sen de şiir yaz çocuk', '1. Şair gece vezniyle yaz bu şiiri karanlıkta uğuldasın dizelerin bilirim, yüreğe yüktür kin dediğin ki bu senin şair, bu hercai yüreğin yos...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin  Yurttaş']::text[], 8.5, '{"poet":"Hüseyin  Yurttaş","poet_slug":"huseyin_yurttas","theme":"Türk Şiiri","is_hero":false,"total_lines":83}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAKIN GÜZ', 'yakin-guz-i-lhan-buyukcebeci-mwamj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alnın çizilmiş
"Kıran Resimleri" için
Yüzümde alaca bağışlayış seni
Gülümseyiş bir hoşça kal
Birbirine komşu yüreklerimizin
Küçük gizli bahçesinde açmış
Acı Çekmenin Dargın Çiçeği
Bir başına
Çocukluk
Tozlu bir dükkân camı
Çingene Arastası''nda seyrettiğim
Tahta kaşıklar, boncuklu beşiklerde kaldı
Annemden uzak
Güze yakın bağbozumu bir bakış
Yüzünde sararan kınaçiçekleri
Kırgın bir çocukluktan geçtin
Elma bahçelerinden
Gecikmiş sevdalar için topladığın
Gelincik düşlerinden
Umarsız bir aşkın suskun sabahları
Mutluluğu andıran aldanış
Hoşça kal...', 'Alnın çizilmiş "Kıran Resimleri" için Yüzümde alaca bağışlayış seni Gülümseyiş bir hoşça kal Birbirine komşu yüreklerimizin Küçük gizli bahç...', ARRAY['Türk Edebiyatı','Şiir','İlhan Büyükcebeci̇']::text[], 8.5, '{"poet":"İlhan Büyükcebeci̇","poet_slug":"ilhan_buyukcebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAKIN', 'yakin-altay-omer-erdogan-nal9v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşka yeni bir pencere doktor
açmak gerek gizli öznenin tarihini
yüklemine neden bu kadar uzak
ölüme o kadar yakın
küçük dertlerin büyük şiirleri olsun doktor
susmaya yakın olan neden içinde hayatın
bayat gövdelerle katıldığımız isyan
hangi uzak duygunun ifadesi, hangi farkın
daha da önemlisi çocuklar pusulasız doktor
aşılanmışlar aşk hastalığına karşı
derinliğe hiç dokunmamışlar elleriyle
gözleriyle hiç söylememişler bu marşı
neden doktor hayâlin yaşlı bahçesinde
bir kez olsun dönüp bakmaz arkasına
ölü sesler gibi çınlayan saat
kırık aynalardan eklenirken kanımıza
eski alışkanlıklardan bir taş
taşın içinde bir gölge
gölge büyük olmaya elverişli
tüm yenilikler arasında
durup durup ölüyorum
çardağın altında', 'aşka yeni bir pencere doktor açmak gerek gizli öznenin tarihini yüklemine neden bu kadar uzak ölüme o kadar yakın küçük dertlerin büyük şiir...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALAN', 'yalan-melih-cevdet-anday-n8903', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben güzel günlerin şairiyim
Saadetten alıyorum ilhamımı
Kızlara çeyizlerinden bahsediyorum
Mahpuslara affı umumiden...
Çocuklara müjdeler veriyorum
Babası cephede kalan çocuklara...
Fakat güç oluyor bu işler
Güç oluyor yalan söylemek...', 'Ben güzel günlerin şairiyim Saadetten alıyorum ilhamımı Kızlara çeyizlerinden bahsediyorum Mahpuslara affı umumiden... Çocuklara müjdeler ve...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALANA DA DELİ GÖNÜL YALANA', 'yalana-da-deli-gonul-yalana-karacaoglan-bej1q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalana da deli gönül yalana
Yedi iklim, çar köşeyi dolana
Soğuk sulu yaylalarda sulana
Meğer bu dünyanın sonu yoğ imiş
Bayrak çekip padişahlık sürmedim
Gurbet ilde inim inim inledim
Kulak verdim, dört köşeyi dinledim
Arkam sıra gıybet eden çoğ imiş
Başına bağlamış ibrişim puşu
Her daim böyledir feleğin işi
Tırnağın var ise başını kaşı
Kardaştan kardaşa fayda yoğ imiş
Karac''oğlan der ki, yorup yormadan
Usandım ben el işine yelmeden
Çok yaşayıp mihnet ile ölmeden
Az yaşayıp bir dem sürmek yeğ imiş', 'Yalana da deli gönül yalana Yedi iklim, çar köşeyi dolana Soğuk sulu yaylalarda sulana Meğer bu dünyanın sonu yoğ imiş Bayrak çekip padişahl...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALANCI DOLMA', 'yalanci-dolma-oktay-ri-fat-zej0m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu zeytin yağlı dolma
Yemek değil rezalet
Rezalet rezalet.
HÜRRİYET MÜSAVAT ADALET', 'Şu zeytin yağlı dolma Yemek değil rezalet Rezalet rezalet. HÜRRİYET MÜSAVAT ADALET...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat']::text[], 8.5, '{"poet":"Oktay Ri̇fat","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞLANMIŞ BİR GEMİCİ GİBİ', 'yaslanmis-bi-r-gemi-ci-gi-bi-ali-puskulluoglu-k9r8j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir korsan gemisinde doğup büyüyen
Denizciye benzerim,
Kalbim kavgalara ve fırtınalara alışık;
Tayfalar gibi canım sıkılır karada
Bir hasta gibi eririm.
O dalgalar ki açık denizlerde
Korkunç yolculuklarımda benimle birlikteydi;
Her çığlıkta martılar selamlardı beni
Günlerce yemsiz kalmış martılar.', 'Ben bir korsan gemisinde doğup büyüyen Denizciye benzerim, Kalbim kavgalara ve fırtınalara alışık; Tayfalar gibi canım sıkılır karada Bir ha...', ARRAY['Türk Edebiyatı','Şiir','Ali̇ Püsküllüoğlu']::text[], 8.5, '{"poet":"Ali̇ Püsküllüoğlu","poet_slug":"ali_puskulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAŞLILAREVİNDE', 'yaslilarevi-nde-ozcan-yalim-4zrf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1.Yaşlılık en yorgun atımdır
-dedi yalnızlık -
Anılar uçuşur yelesinde
Kendinden kaçtıkça bana gelir
2.Yalnızlık en son atımdır
-dedi yaşlılık -
O ıssız ülkeye götüren
Acıları acıları
3.Yılkısından ayrı bir yılkı atı
Gün batarken ıssız bozkırda
Gölgesini gerilere uzatıyor
Güz rengi bulutlar geçiyor
Donuk mavi gözlerinden', '1.Yaşlılık en yorgun atımdır -dedi yalnızlık - Anılar uçuşur yelesinde Kendinden kaçtıkça bana gelir 2.Yalnızlık en son atımdır -dedi yaşlıl...', ARRAY['Türk Edebiyatı','Şiir','Özcan Yalim']::text[], 8.5, '{"poet":"Özcan Yalim","poet_slug":"ozcan_yalim","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALINAYAK ŞİİRDİR', 'yalinayak-si-i-rdi-r-ece-ayhan-a37b3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1.Biz tüzüklerle çarpışarak büyüdük kardeşim
Emrazı Zühreviye Hastanesi''ne kapatıldı anamız
Adıyla çalışan ermiş Sirkeci kadınlarındandır
Şeker atar hâlâ mazgallardan Cankurtaran''da
Acı Bacı''nın acı bilmez uçurtma çocuklarına
Yıl sonu müsamerelerine kimler çıkarılmaz?
2.Velhasıl onlar vurdu biz büyüdük kardeşim
Babamız dövüldü güllabici odunlarla tımarhanede
Acaba halk nedir diye düşünür arada işittiği
Dudullu''dan tâ Salacak''a koşarak alkışlayalım
Fazla babalarıyla dondurma yiyen çocukları
Hangi çocukların neye imrenmesi yalınayak şiirdir?', '1.Biz tüzüklerle çarpışarak büyüdük kardeşim Emrazı Zühreviye Hastanesi''ne kapatıldı anamız Adıyla çalışan ermiş Sirkeci kadınlarındandır Şe...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNAYAK VE TELÂŞLI BİR YÜREKLE', 'yalnayak-ve-tel-sli-bi-r-yurekle-huseyin-ferhad-cjcst', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıplak ayaklarını dalar çakırdikenleri,
kanatır yüreğini yaban gece,
sinsi yalnızlıkların soğuk demiri
küs gittiğin yollara gömülünce.
Yüzün solar telâştan ve ayazdan
çiy taneleri buza dönüşür,
yarasalar alır kaçar bohçanı elinden,
rüzgâr seni hendeklere düşürür.
Ay yok. Uzakta yıldızlar. Dön geri
korkarsın tek başına, arkadaşsız.
Ateşböceği kanatlarından bereler ördüm sana
dön geri, dön geri küçük kız.', 'Çıplak ayaklarını dalar çakırdikenleri, kanatır yüreğini yaban gece, sinsi yalnızlıkların soğuk demiri küs gittiğin yollara gömülünce. Yüzün...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin  Ferhad']::text[], 8.5, '{"poet":"Hüseyin  Ferhad","poet_slug":"huseyin_ferhad","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZ BİR OPERA', 'yalniz-bi-r-opera-murathan-mungan-vcmpp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR OPERA
ölü bir yılan gibi yatıyordu aramızda
yorgun, kirli ve umutsuz geçmişim
oysa bilmediğin bir şey vardı sevgilim
Ben sende bütün aşklarımı temize çektim
imrendiğin, öfkelendiğin
kızdığın ya da kıskandığın diyelim
yani yaşamışlık sandığın
Geçmişim
dile dökülmeyenin tenhalığında
kaçırılan bakışlarda
gündeliğin başıboş ayrıntılarında
zaman zaman geri tepip duruyordu. Ve elbet üzerinde durulmuyordu.
Sense kendini hala hayatımdaki herhangi biri sanıyordun, biraz daha
fazla sevdiğim, biraz daha önem verdiğim.
Başlangıçta doğruydu belki. Sıradan bir serüven, rastgele bir ilişki
gibi başlayıp, gün günden hayatıma yayılan, büyüyüp kök salan ,
benliğimi kavrayıp, varlığımı ele geçiren bir aşka bedellendin.
Ve hala bilmiyordun sevgilim
Ben sende bütün aşklarımı temize çektim
Anladığındaysa yapacak tek şey kalmıştı sana
Bütün kazananlar gibi
Terk ettin
Yaz başıydı gittiğinde. Ardından, senin için üç lirik parça
yazmaya karar vermiştim. Kimsesiz bir yazdı. Yoktun. Kimsesizdim.
Çıkılmış bir yolun ilk durağında bir mevsim bekledim durdum.
Çünkü ben aşkın bütün çağlarından geliyordum.
Sanırım lirik sözcüğü en çok yüzüne yakışıyordu
yüzündeki kuşkun kedere, gür kirpiklerinin altından
kısık lambalar gibi ışıyan gözlerine
çerçevesine sığmayan
munis, sokulgan, hüzünlü resimlerine
lirik sözcüğü en çok yüzüne yakışıyordu
Yaz başıydı gittiğinde. Sersemletici bir rüzgar gibi geçmişti
Mayıs. Seni bir şiire düşündükçe kanat gibi, tüy gibi, dokunmak gibi
uçucu ve yumuşak şeyler geliyordu aklıma. Önceki şiirlerimde hiç kullanmadığım
bu sözcük usulca düşüyordu bir kağıt aklığına, belki de
ilk kez giriyordu yazdıklarıma, hayatıma.
Yaz başıydı gittiğinde. Bir aşkın ilk günleriydi daha. Aşk mıydı,
değil miydi? Bunu o günler kim bilebilirdi? &quot;Eylül''de aynı yerde ve
aynı insan olmamı isteyen&quot; notunu buldum kapımda. Altına saat: 16.00
diye yazmıştın, ve saat 16.04''tü onu bulduğumda.
Daha o gün anlamalıydım bu ilişkinin yazgısını
Takvim tutmazlığını
Aramızda bir düşman gibi duran
Zaman''ı
Daha o gün anlamalıydım
Benim sana erken
Senin bana geç kaldığını
Gittin. Koca bir yaz girdi aramıza. Yaz ve getirdikleri.
Döndüğünde eksik, noksan bir şeyler başlamıştı. Sanki yaz, birbirimizi
görmediğimiz o üç ay, alıp götürmüştü bir şeyleri hayatımızdan, olmamıştı, eksik
kalmıştı.
Kırılmış bir şeyi onarır gibi başladık yarım kalmış
arkadaşlığımıza. Adımlarımız tutuk, yüreğimiz çekingen, körler gibi tutunuyor,
dilsizler gibi bakışıyorduk.
Sanki ufacık birşey olsa birbirimizden kaçacaktık.
Fotoromansız, trüksüz, hilesiz, klişesiz bir beraberlikti bizimki.
Zamanla gözlerimiz açıldı, dilimiz çözüldü güvenle ilerledik birbirimize.
Gittin.şimdi bir mevsim değil, koca bir hayat girdi aramıza. Biliyorum ne sen
dönebilirsin artık, ne de ben kapıyı açabilirim sana.
Şimdi biz neyiz biliyor musun?
Akıp giden zamana göz kırpan yorgun yıldızlar gibiyiz.
Birbirine uzanamayan
Boşlukta iki yalnız yıldız gibi
Acı çekiyor ve kendimize gömülüyoruz
Bir zaman sonra batık bir aşktan geriye kalan iki enkaz olacağız yalnızca
Kendi denizlerimizde sessiz sedasız boğulacağız
Ne kalacak bizden?
bir mektup, bir kart, birkaç satır ve benim su kırık dökük şiirim
Sessizce alacak yerini nesnelerin dünyasında
Ne kalacak geriye savrulmuş günlerimizden
Bizden diyorum, ikimizden
Ne kalacak?
Şimdi biz neyiz biliyor musun?
Yıkıntılar arasında yakınlarını arayan öksüz savaş çocukları
gibiyiz. Umut ve korkunun hiçbir anlam taşımadığı bir dünyada bir
şey bulduğunda neyi, ne yapacağını bilemeyen çocuklar gibi.
Artık hiçbir duygusunu anlamayan çocuklar gibi
Ve elbet biz de bu aşkla büyüyecek
Her şeyi bir başka aşka erteleyeceğiz
kış başlıyor sevgilim
hoşnutsuzluğumun kışı başlıyor
bir yaz daha geçti hiçbir şey anlamadan
oysa yapacak ne çok şey vardı
ve ne kadar az zaman
kış başlıyor sevgilim
iyi bak kendine
gözlerindeki usul şefkati
teslim etme kimseye, hiçbir şeye
upuzun bir kış başlıyor sevgilim
ayrılığımızın kışı başlıyor
Giriyoruz kara ve soğuk bir mevsime.
Kitaplara sarılmak, dostlarla konuşmak, yazıya oturup sonu
gelmeyen cümleler kurmak, camdan dışarı bakıp puslu şarkılar mırıldanmak...
Böyle zamanlarda her şey birbirinin yerini alır
çünkü her şey bir o kadar anlamsızdır
içinizdeki ıssızlığı doldurmaz hiçbir oyun
para etmez kendinizi avutmak için bulduğunuz numaralar
Bir aşkı yaşatan ayrıntıları nereye saklayacağınızı bilemezsiniz
çıplak bir yara gibi sızlar paylaştığınız anlar, eşyalar
gözünüzün önünde durur birlikte yarattığınız alışkanlıklar
korkarsınız sözcüklerden, sessizlikten de; bakamazsınız aynalara,
çağrışımlarla ödeşemezsiniz
dışarıda hayat düşmandır size
içeride odalara sığamazken siz, kendiniz
Bir ayrılığın ilk günleridir daha
Her şey asılı kalmıştır bitkisel bir yalnızlıkla
Gün boyu hiçbir şey yapmadan oturup
kulak verdiğiniz saatin tiktakları
kaplar tekin olmayan göğünüzü
geçici bir dinginlik, düzmece bir erinç
suyu boşalmış bir havuz, fişten çekilmiş bir alet kadar tehlikesiz
bakınıp dururken duvarlara
boş bir çuval gibi, çalmayan bir org gibi, plastik bir çiçek, unutulmuş
bir oyuncak, eski bir çerçeve gibi, hani, unutsam eşyanın gürültüsünü,
nesnelerin dünyasında kendime bir yer bulsam, dediğimiz zamanlar gibi
kendimizin içinden yeni bir kendimiz çıkarmaya zorlandığımız anlar
gibi
yeni bir iklime, yeni bir kente, bir tutukluluk haline, bir trafik
kazasına, başımıza gelmiş bir felakete, işkenceye çekilmeye, ameliyata
alınmaya
kendimizi hazırlar gibi
yani dayanmak ve katlanmak için silkelerken bütün benliğimizi
ama öyle sessiz baktığımız duvarlar gibi olmaya çalışırken,
ve kazanmış görünürken derinliğimizi
Ne zaman ki, yeniden canlanır bağışlamasız belleğimizde
bir anın, yalnızca bir anın bütün bir hayatı kapladığı anlar
o tiktaklar kadar önemsiz kalır şimdi
hayatımıza verdiğimiz bütün anlamlar
denemeseniz de, bilirsiniz
hiç yakın olmamışsınızdır intihara bu kadar
Bana Zamandan söz ediyorlar
Gelip size Zamandan söz ederler
Yaraları nasıl sardığından, ya da her şeye nasıl iyi geldiğinden. Zamanla ilgili
bütün atasözleri gündeme gelir yeniden. Hepsini bilirsiniz zaten, bir ise
yaramadığını bildiğiniz gibi. Dahası onlar da bilirler. Ama yine de güç verir
bazı sözler, sözcükler,
öyle düşünürler.
Bittiğine kendini inandırmak, ayrılığın gerçeğine katlanmak, sırtınızdaki
hançeri çıkartmak, yüreğinizin unuttuğunuz yerleriyle yeniden
karşılaşmak kolay değildir elbet. Kolay değildir bunlarla baş etmek,
uğruna içinizi öldürmek. Zaman alır.
Zaman
Alır sizden bunların yükünü
O boşluk dolar elbet, yaralar kabuk bağlar, sızılar diner, acılar
dibe çöker. Hayatta sevinilecek şeyler yeniden fark edilir. Bir
yerlerden
bulunup yeni mutluluklar edinilir.
O boşluk doldu sanırsınız
Oysa o boşluğu dolduran eksilmenizdir
gün gelir bir gün
başka bir mevsim, başka bir takvim, başka bir ilişkide
o eski ağrı
ansızın geri teper.
Dilerim geri teper. Yoksa gerçekten
Bitmişsinizdir.
Zamanlayerleşir yaşadıkların, yeniden konumlanır, çoğalır, anlamları
önemi kavranır. Bir zamanlar anlamadan yaşadığın şey, çok sonra değerini
kazanır. Yokluğu derinve sürekli bir sızı halini alır.
Oysa yapacak hiçbir şey kalmamıştır artık
Mutluluk geçip gitmiştir yanınızdan
Herşeye iyi gelen Zaman sizi kanatır
ölmüş saadeti karşılaştır yaşayan mutsuzlukla
günlerin dökümünü yap
benim senden, senin benden habersiz alıp verdiklerini
kim bilebilir ikimizden başka?
sözcüklerin ve sessizliklerin yeri iyi ayarlanmış
bir ilişkiyi, duyguların birliğini, bir aşkı beraberlik haline getiren
kendiliğindenliği
yani günlerimiz aydınlıkken kaçırdığımız her şeyi
bir düşün
emek ve aşkla güzelleştirilmiş bir dünya
şimdi ağır ağır batıyor ve yokluğa karışıyor orada
ölmüş saadeti karşılaştır yaşayan mutsuzlukla
Bunlar da bir ise yaramadıysa
Demek yangında kurtarılacak hiçbir şey kalmamış aramızda
Bu şiire başladığımda nerde,
şimdi nerdeyim?
solgun yollardan geçtim. Bakışımlı mevsimlerden
ikindi yağmurlarını bekleyen
yaz sonu hüzünlerinden
gün günden puslu pencerelere benzeyen gözlerim
geçti her çağın bitki örtüsünden
oysa şimdi içimin yıkanmış taşlığından
bakarken dünyaya
yangınlarda bayındır kentler gibiyim:
çiçek adlarını ezberlemekten geldim
eski şarkıları, sarhoşların ve suçluların
unuttuklarını hatırlamaktan
uzak uzak yolları tarif etmekten
haydutluktan ve melankoliden
giderken ya da dönerken atlanan eşiklerden
Duyarlığın gece mekteplerinden geldim
Bütünlemeli çocuklarla geçti
gençliğimin rüzgara verdiğim yılları
dokunmaların ve içdökmelerin vaktinden geldim.
Bu şiire başladığımda nerde,
şimdi nerdeyim?
yaram vardı. bir de sözcükler
sonra vaat edilmiş topraklar gibi
sayfalar ve günler
ışık istiyordu yalnızlığım
Kötülükler imparatorluğunda bir tek şiir yazmayı biliyordum
İlerledikçe... Kaybolup gittin bu şiirin derinliklerinde
Aşk ve Acı usul usul eriyen bir kandil gibi söndü
daha şiir bitmeden. Karardı dizeler.
Aşk... Bitti. Soldu şiir.
Büyük bir şaşkınlık kaldı o fırtınalı günlerden
Daha önce de başka şiirlerde konaklamıştım
Ağır sınavlar vermiştim değişen ruh iklimlerinde
Aşk yalnız bir operadır, biliyordum: Operada bir gece
uyudum, hiç uyanmadım.
barbarların seyrettiği trapezlerden geçtim
her adımda boynumdan bir fular düşüyordu
el kadar gökyüzü mendil kadar ufuk
birlikte çıkılan yolların yazgısıdır:
eksiliyorduk
mataramda tuzlu suyla, oteller kentinden geldim
her otelde biraz eksilip, biraz artarak
yani çoğalarak
tahvil ve senetlerini intiharla değiştirenlerin
birahaneler ve bankalar üzerine kurulu hayatlarında
ağır ve acı tanıklıklardan
geçerek geldim. Terli ve kirliydim.
Sonra tımarhanelerde tımar edilen ruhum
maskeler ve çiçekler biriktiriyordu
linç edilerek öldürülenlerin hayat hikayelerini de...
korsan yazıları, kara şiirleri, gizli kitapları
ve açık hayatları seviyordu.
Buraya gelirken
uzun uzak yollar için her menzilde at değiştirdim
atlarla birlikte terledim yolları ve geceleri
ödünç almadım hiç kimseden hiçbir şeyi
çıplak ve sahici yaşayıp çıplak ve sahici ölmek için
panayır yerleri... panayır yerleri...
ölü kelebekler... ölü kelebekler...
sonra dünyanın bütün sinemalarında bütün filmleri seyrettim.
Adım onların adının yanına yazılmasın diye
acı çekecek yerlerimi yok etmeden
acıyla baş etmeyi öğrendim.
Yoksa bu kadar konuşabilir miydim?
ipek yollarında kuzey yıldızı
aşkın kuzey yıldızı
sanırsın durduğun yerde
ya da yol üstündedir
oysa çocukluktan kalma gökyüzünde hileli zar
ölü yanardağlar, ölü yıldızlar
ve toy yaşın bilmediği hesap: ışık hızı
AŞKIN BİR YOLU VARDIR
HER YAŞTA BAŞKA TÜRLÜ GEÇİLEN
AŞKIN BİR YOLU VARDIR
HER YAŞTA BİRAZ GECİKİLEN
gökyüzünde yalnız bir yıldız arar gözler
gözlerim
aşkın kuzey yıldızıdır bu
yazları daha iyi görülen
Ben, öteki, bir diğeri ona doğru ilerler
ilerlerim
zamanla anlarsın bu bir yanılsama
ölü şairlerin imgelerinden kalma
Sen de değilsin. O da değil
Kuzey yıldızı daha uzakta
yeniden yollara düşerler
düşerim
bir şiir yaşatır her şeyi yaşamın anlamı solduğunda
ben yoluma devam ederim. Bitmemiş bir şiirin ortasında
Darmadağınık imgeler, sözcükler ve kafiyeler
yaşamsa yerli yerinde
yerli yerinde her şey
şimdi her şey doludizgin ve çoğul
şimdi her şey kesintisiz ve sürekli bir devrim gibi
şimdi her şey yeniden
yüreğim, o eski aşk kalesi
yepyeni bir mazi yarattı sözcüklerin gücünden
Dönüp ardıma bakıyorum
Yoksun sen
Ey sanat! Her şeyi hayata dönüştüren', 'BİR OPERA ölü bir yılan gibi yatıyordu aramızda yorgun, kirli ve umutsuz geçmişim oysa bilmediğin bir şey vardı sevgilim Ben sende bütün aşk...', ARRAY['Türk Edebiyatı','Şiir','Murathan Mungan']::text[], 8.5, '{"poet":"Murathan Mungan","poet_slug":"murathan_mungan","theme":"Türk Şiiri","is_hero":false,"total_lines":280}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZ BİRİ', 'yalniz-bi-ri-kemal-ozer-ej8kt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yanından geçiyoruz tahta perdenin
her günkü yolumuzda
Yalnız biri, bir genç
sıçrıyor görmek için öte yanını
Bunca bezgin insan arasında
yalnız biri', 'Yanından geçiyoruz tahta perdenin her günkü yolumuzda Yalnız biri, bir genç sıçrıyor görmek için öte yanını Bunca bezgin insan arasında yaln...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZ KARANFİL SOKAĞI', 'yalniz-karanfi-l-sokagi-aydin-hati-poglu-wbfvi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgârın rengi hazan
Yalnızlığa değiyor
Bıçak kesilmiş ufuk
Kavrulmuş un kokuyor
Çocuk gözümde ölüm
Suya düşmüş yaralı kuş
Düşe değiyor ellerim
Umutsuzluğu okşuyor
Kuşlar ki en kadim yerli
Surlarında eski kentin
Giderler bir eski kentten
Bir eski kente giderler
Güneşin rengi sevda
Sesinde papatyalar
Çalar yorgun bir zamanı
Bulut katarı anılar
Parkın sevdiğim yanı bu
Ben gelince herkes gelir
Dokunsa elime elin
Bütün güvercinler uçar
Yüreğin kar beyazı
Titrer gibi güz yaprağı
Kalabalık sokaklardan
Yalnız karanfil sokağı', 'Rüzgârın rengi hazan Yalnızlığa değiyor Bıçak kesilmiş ufuk Kavrulmuş un kokuyor Çocuk gözümde ölüm Suya düşmüş yaralı kuş Düşe değiyor elle...', ARRAY['Türk Edebiyatı','Şiir','Aydın Hati̇poğlu']::text[], 8.5, '{"poet":"Aydın Hati̇poğlu","poet_slug":"aydin_hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZIZ CEMAL ABİ', 'yalniziz-cemal-abi-haydar-ergulen-jaeqg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu rakıyı diyorum Cemal abi
bu rakıyı içmek seninle
Kars''a gitmek gibiydi
Senin şiirinde diyorum Cemal abi
rakı uzun içilirdi
Kars''a uzun gidilirdi
Senden sonra diyorum Cemal abi
Kars''a şiir gitmiyor
Kars kısa, rakı tatsız
senden sonra şiirde
her şey dibe çöküyor
anla, öyle yalnızız', 'Bu rakıyı diyorum Cemal abi bu rakıyı içmek seninle Kars''a gitmek gibiydi Senin şiirinde diyorum Cemal abi rakı uzun içilirdi Kars''a uzun gi...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar_ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIĞA VEDA', 'yalnizliga-veda-adnan-ozer-8e8v9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorum işte
Hayalde gör, düşte gör.
Yalnızlığın da ucuna geldim,
sırtımda kederin hançeri,
saplanmadan hep tehditle yürütür beni.
Bilmem neden ve nasıl çıktım bu yola,
vardır elbet başlangıcı bu halin;
ben de bir harmandan savruldum sonunda,
konmasız uçtum peşinden kadın denilen hayalin.
Hayatmış ama asıl beni kandıran cilve.
Yine de bir şey verdi diyemem bana bu derin tasavvur
ve yeryüzü meridyenlerle kestiğim özlü çamur
kerpici iliğimde kurur, ağrısı yüzüme vurur.
Ah ne vedadır ne vebadır ne vebaldir bu!
Gitmek değil, artık dağılmakbenimkisi
tozuyan aklım ve hafızamla.
Bitsin artık bu şiirler, bu kitap, bu içe dönük cihannüma
Hayalse katili bir insanın
cesedi vurmaz hiçbir kıyıya.', 'Gidiyorum işte Hayalde gör, düşte gör. Yalnızlığın da ucuna geldim, sırtımda kederin hançeri, saplanmadan hep tehditle yürütür beni. Bilmem ...', ARRAY['Türk Edebiyatı','Şiir','Adnan  Özer']::text[], 8.5, '{"poet":"Adnan  Özer","poet_slug":"adnan_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIĞIMI ANLATIYORUM', 'yalnizligimi-anlatiyorum-rifat-ilgaz-gavsm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Koğuşta inceden bir lizol kokusu
Dışarda tam tamına On Sekiz Şubat
Ne üstümdeki örtüler ısıtıyor beni
Ne altımdaki yatak
Ellerini arıyorum sıcak ellerini
Kuruyan dilim tutuşan alnım
Garipliğim nöbet nöbet gecemde
Susuzum, ilaçsızım, sensizim
Sıcak dudaklarını arıyorum
Camlarda karayel acımasız
Nereye baksam can çekişmesi
Gece… Yol boyu memleket memleket
Işıtsın iyimserliğin içimi
Dağılsın ölüm korkum bir görün
Aydın bakışlarını arıyorum
(1961)
Soluk Soluğa adlı şiir kitabından 1962
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Koğuşta inceden bir lizol kokusu Dışarda tam tamına On Sekiz Şubat Ne üstümdeki örtüler ısıtıyor beni Ne altımdaki yatak Ellerini arıyorum s...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIĞIN BUZDAN AYI', 'yalnizligin-buzdan-ayi-metin-altiok-3405e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Islanmış taşlığında suskun bir bekleyişin
Yutar yalnızlığın buzdan ayını,
Akşamsefaları içinde karanlık gözlerin.
Döker çiçeğini sararan rengiyle,
Yaralı bir aşkla seğiren derin.
Ve aklın seni sürgüne gönderir
Yüzüne iğreti gelen isminle,
En yalnız köşesinde donmuş yüreğinin.', 'Islanmış taşlığında suskun bir bekleyişin Yutar yalnızlığın buzdan ayını, Akşamsefaları içinde karanlık gözlerin. Döker çiçeğini sararan ren...', ARRAY['Türk Edebiyatı','Şiir','Metin Altiok']::text[], 8.5, '{"poet":"Metin Altiok","poet_slug":"metin_altiok","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIĞIN EVİ', 'yalnizligin-evi-bedrettin-aykin-7pd8a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçek adresim sanki
Bir yalnızlığın evi
Gömülmeden o sulara götür
Yeni bir ilkyaza beni
Kapısı numaralı odalarda
Kimliği kayıtlara geçmiş
Gözaltında bir sanık gibi
Ne çok geceler geçirdim
Bilsen uykusuz sensiz
Soğuk birer sığınakta üşürdüm
Ellerinin değmediği o evler
Giderdim kaçarcasına erkenden
Sarılıp beni öpemeden
Kanayan yeni yalnızlıklara', 'Gerçek adresim sanki Bir yalnızlığın evi Gömülmeden o sulara götür Yeni bir ilkyaza beni Kapısı numaralı odalarda Kimliği kayıtlara geçmiş G...', ARRAY['Türk Edebiyatı','Şiir','Bedrettin Aykin']::text[], 8.5, '{"poet":"Bedrettin Aykin","poet_slug":"bedrettin_aykin","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIĞIN İÇİNDEN DÜŞÜNCELER', 'yalnizligin-i-ci-nden-dusunceler-verner-von-heidenstam-qoyxs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'XVII
Dünyanın yarısında aradım
en güzel adı verebileceğim o yeri.
Hepsinden daha güzel olsun
olmasın ondan güzeli.
Her şeyi benden al ki, benim olsun onlar
fakat o muhteşem duyarlılığımı esirgeme benden
sevinç duyabileceğim ve söz verebileceğim
bir başka duyarsız geçip giderken!
Verner Von HEIDENSTAM', 'XVII Dünyanın yarısında aradım en güzel adı verebileceğim o yeri. Hepsinden daha güzel olsun olmasın ondan güzeli. Her şeyi benden al ki, be...', ARRAY['Türk Edebiyatı','Şiir','Verner Von Heidenstam']::text[], 8.5, '{"poet":"Verner Von Heidenstam","poet_slug":"verner_von_heidenstam","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIK BİR TARİHTİR', 'yalnizlik-bi-r-tari-hti-r-hi-lmi-yavuz-ewe41', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlık bir tarihtir ikimiz
Dururuz odalarda bir giysi gibi
En kalın soluklarla çekiyor ipi
Kimbilir kimlere kalmışlığımız
Yalnızlık bir tarihtir sen misin
Bir geçmişi sürüp giden ak turna?
Ya benden önceydi ya da çok sonra
Bir halk türküsüne gül olan sesin
Yalnızlık bir tarihtir onlarda
Gök dediğin iki kuşun arası
Ey ilkyazlı gülüşlerin sonrası
Ansızın donuyor gül, bakışlarda', 'Yalnızlık bir tarihtir ikimiz Dururuz odalarda bir giysi gibi En kalın soluklarla çekiyor ipi Kimbilir kimlere kalmışlığımız Yalnızlık bir t...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIK CİNAYETTİR', 'yalnizlik-ci-nayetti-r-altay-oktem-cjnnb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kendime kuytu bir ölüm arıyorum yalnızca kendime
düşlerime sokak kedilerinin gözleri giriyor, korkuyorum
boynunu kendi bileğine dolayıp asılan bir adam
kanını sulandırılmamış alkole banan
sokak satıcıları epey bilir bunu yalnızlık cinayettir
yalnızlık cinayettir bütün notalarda, bütün dillerde
bütün hecelerde, "a" sesinde, re minörde, mors alfabesinde
yalnızlık cinayettir kendi tükürüğüyle
ıslanan bedenlerde eski bir kokudur, yalnızca budur
ıslak paspas kokusudur, gece morudur
bileği tahriş olmuş bir kadının dinmeyen korkusudur
ansızın yakalanmasıdır bir kuşun kapana
trenin gecikmesidir istasyona yalnızlık cinayettir
sevişirken kramp girmesidir, ölürken birdenbire
sıçramaktır başka bir zamana, kadeh tutarken
elinin titremesidir, sesinin duyulmasıdır susarken
karnına saplanan bıçağı sevmektir yalnızlık cinayettir
cinnettir
kendime kuytu bir ölüm arıyorum çok iyi biliyorsun bunu
düşlerime kalabalık bir cadde giriyor. korkuyorum
saçlarını sırtından sallandıran kadınlar kadar
uzayıp gitmesi kadar bir aşkın telaşla
yanlışlıkla, su katılmamış bir sevişmenin ardından
ters yakılması kadar sigaranın, benim kadar
yani ellerim kadar, bedenim kadar, düşüncelerim
sırlarım, kaçışlarım kadar saçmadır yalnızlık cinayettir
cennettir
kendime kuytu bir ölüm arıyorum çok görüyorsun bunu
bütün delillerimi yaktım, beni ötelere götürecek
yollardan zaten uzaktım
her kadına yeni, bir zevk, her kadına
yeni kurulmuş tuzaktım bütün delillerimi yaktım
sonrası yok. sonrası çok gizli bir fotoğrafın arabı
yüzümüz siyah ve anlamsız, dışımız beyaz ve derin
sanki bir diktatör anıtı, kan akıtan bir nehir
işlenmemiş suçlarımız sanki yalnızlık cinayettir
cennettir
cinnettir
cinayettir.
zaman doldu
artık gidiyorum arkama bile bakmadan
arkaya bakmak çok eski huyudur
bazı çirkin adamların
zaman doldu
artık gizlemiyorum kendimi çok kadınla seviştim çoğu buluttu
basbayağı buluttu bildiğimiz buluttu dağılıp gidiyordu ben ço-
ğalttıkça
bir akşam usulca girdim kanıma
kendim karar verdim hep kendim karar verdim
yanlış da olsa sevdim pişman değilim, neden olayım?
bir akşam; üç gün üç gece poker oynamıştım
ne güzel. üç gün üç gece yeterince
içmiştik demek ki onar şişe, belki on beş
yirmi belki de.
abdullah, ah dostum, sevdiğim, çalı yüzlüm abdullah
kaç kurşun sıktı üstüme
yeterince içmiştik. vuramadı
vurdu, ben anlamadım belki de
belki de yavaş yavaş devam ediyorum ölmeye.', 'kendime kuytu bir ölüm arıyorum yalnızca kendime düşlerime sokak kedilerinin gözleri giriyor, korkuyorum boynunu kendi bileğine dolayıp asıl...', ARRAY['Türk Edebiyatı','Şiir','Altay Öktem']::text[], 8.5, '{"poet":"Altay Öktem","poet_slug":"altay_oktem","theme":"Türk Şiiri","is_hero":false,"total_lines":61}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIK', 'yalnizlik-serdar-aydin-4dlvm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'April'' in Paris, sonrasında
tersinen anılar öncesi
bir damla gözyaşıydın sen
ürkek kara kırçıl
gidişinle
akrebinden sızan elveda
anlamanı ararken
boktan bir hayat eskizi gibi
kıvranırdım...
çırpınan acının içinde
bir damla gözyaşıydın sen
kirli kara kırçıl
yokluğun irincesi gibi
sevişebilir miydik
tarihin izdüşümüyle lal
aşkların apış arasında kısa
hoşçakalıyla...baharın
öpüşürken kendine soytarı
bilmeliydin
pörsümüş sözlerinden arta kalandı
aşk
yalnızlıktan kudurmuş
bedeninde leşini arayan aşk
hazzın köpeği aşk
utanç senindi
sevgilim
teninin soytarısı kadın...', 'April'' in Paris, sonrasında tersinen anılar öncesi bir damla gözyaşıydın sen ürkek kara kırçıl gidişinle akrebinden sızan elveda anlamanı ar...', ARRAY['Türk Edebiyatı','Şiir','Serdar  Aydin']::text[], 8.5, '{"poet":"Serdar  Aydin","poet_slug":"serdar_aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIKTAN ÜŞÜYOR İÇİMDE KELİMELER', 'yalnizliktan-usuyor-i-ci-mde-keli-meler-bulent-ozcan-iue5k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kederden kendime köprüler yapıyorum
Kıldan ince kılıçtan keskince köprüler
Her köprüden bir şiir okuyup geçiyorum
Yalnızlıktan üşüyor içimde kelimeler
Yüzünün denizinden atlaslar biçiyorum
Kendimden çok uzağa gitsem de çok kereler
Şiir ki salt coşkuyla yazılmaz biliyorum
Yalnızlıktan üşüyor içimde kelimeler
Çok ölmüş bir şairim yıldızlardan daha çok
Dalında uğuldayan şu rüzgârdan daha çok
Çok ölmüş yoksul ölmüş ama en erken ölmüş
Yalnızlıktan üşüyor içimde kelimeler', 'Kederden kendime köprüler yapıyorum Kıldan ince kılıçtan keskince köprüler Her köprüden bir şiir okuyup geçiyorum Yalnızlıktan üşüyor içimde...', ARRAY['Türk Edebiyatı','Şiir','Bülent  Özcan']::text[], 8.5, '{"poet":"Bülent  Özcan","poet_slug":"bulent_ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR BAŞLANGICI', 'yagmur-baslangici-oktay-ri-fat-horozcu-t9af2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siz bir başlangıç bile değilken
yokken denemez çünkü vardınız
geyikler inerdi gözlerinize
ağaçlarınız fındık ve sincap
bu yüzden omuzlarınız
memeleriniz bir kitap gibi okunaklı
oluklara düşen sessiz damlalardı
bin kez yondum sizi bin kez doğurdum
bir keten buruşukluğu her seferinde
yağacak diye düşünürdüm havalara bakarak
bir serinlik bir kıpırtı otta ve ağaçta
akşamın kanından gecemize yaklaşan
bir gemi gibi önce küçük sonra yakın
iri damlaları o seyrek yağmurun
tüterdi ot çakıl kum
siz bir başlangıç bile değilken
sizi yazdım kotardım
bir başucu kitabı olmanızı istedim
tek tek iri o yabanıl kelimeler
onlar işte renkli zarlarının içinde
olukların çinkosunda yuvarlanan
siz daha bir başlangıç bile değilken
yağmur başlamıştı
ama ne ben ne bahçe ne yaz
hiçbirimiz.', 'Siz bir başlangıç bile değilken yokken denemez çünkü vardınız geyikler inerdi gözlerinize ağaçlarınız fındık ve sincap bu yüzden omuzlarınız...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR DUASI', 'yagmur-duasi-niyazi-akincioglu-d4hi9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Görünmez ellerin sağdığı bulut,
Yağmur ki Allaha bağlanan umut;
Ellerini göğe kaldır açık tut:
Tarlada çamur teknede hamur
Ver Allahım ver sellice yağmur!
Ve bağrını toprak, avuçlarını el
Açıyor göklere; yağmur tek emel.
Ağlanmaz götürse yavruyu bir sel:
Tarlada çamur teknede hamur
Ver Allahım ver sellice yağmur!
Çatlak dudaklarını ıslatmıyor kan,
Toprakta yangın var, toprakta volkan.
Allaha gönderilen elçi: Kurban.
Tarlada çamur teknede hamur
Ver Allahım ver sellice yağmur!', 'Görünmez ellerin sağdığı bulut, Yağmur ki Allaha bağlanan umut; Ellerini göğe kaldır açık tut: Tarlada çamur teknede hamur Ver Allahım ver s...', ARRAY['Türk Edebiyatı','Şiir','Niyazi Akincioğlu']::text[], 8.5, '{"poet":"Niyazi Akincioğlu","poet_slug":"niyazi_akincioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR İÇEN KIZ', 'yagmur-i-cen-kiz-yusuf-hayaloglu-w7ydm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baldırı çıplak bir akşamüstüydü
Kime selam verdiysem yüzüme küstüydü.
Yalnızlığa susmuştum, yağmura üşümüştüm..
Belli belirsiz ve hiçbir makamsız,
Hiçbir kelimesiz ve hiçbir anlamsız,
Kırılgan bir şarkıydı, tılsımına düşmüştüm..
Ve ben sanki ömrümde yaşamadığım
Ve yaşamadan yaşlandığım bütün aşkları
Bu ilk defa karşılaştığım, bu ilk defa yabancı,
Ve bu son defa tutunduğum kızla bölüşmüştüm..
Yağmur içen kız.. gece kuşu
Atmacaya benzer duruşu..
Bir omuzu el-ense çekerken azraile
Bir omuzu sokak lambasından da biçare..
Kimliğini sorarsan;
Barbar sokakların en barbar kızı,
Ve hortumlu karakolların en arsızı..
O destursuz yağmur, taş gibi iniyordu,
O fütursuz cadde, pür-telaş deviniyordu.
Başını çevirip bakıyordu ara sıra
Hiçbir şey sormadan gidiyordum ardı sıra..
Bir karyola, bir sobadan ibaret 102 nolu odada
Buluştu gözlerimiz, sırları dökülmüş tozlu aynada..
Cebimdeki şişeyi yudumlarken sessizce
Saçlarını okşadım yavaşça ve teklifsizce..
Azıcık huylanmıştı, söylemedi ama şaşırmıştı.
Sanırım ki o, hep değişen tiplere
Ve fakat hiç değişmeyen triplere alışmıştı..
Yağmur içen kız.. vahşi kısrak
Göğsü falçata krizi, öfkesi tavlı bıçak..
Soluğunda ıslak çimenlerin buğusu
Soluduğunda kundaklanmış ormanların yalazı.
Güzelliğini sorarsan;
Dişleri kar kuşundan da beyaz
Dudakları vampirden de kırmızı..
Alışkın bir otel odasıydı, kenarda soba yanıyordu,
Tutkunun tasma koparan köpekleri
Arsız bir çarşaf gibi üstümüze abanıyordu..
Küçücük ama çok küçücük bir ağzı vardı,
Küçücük ama çok küçücük bir öpüşte bile
Bir vişne ısırığı gibi kanıyordu..
Çaparinin çengelinde çırpınan çipuranın
Yakaran gözlerindeki o tarifsiz kederle,
Bu küçücük ömründe, belki de ilk defa
Birisinin gözlerine bakmaktan utanıyordu..
Yağmur içen kız.. kaldırım meleği
Hüznün yirmidört saatlik beyhude kelebeği..
Her akşam sunarak kendini hoyrat ağızlara
Ve her sabah yunarak bedenini yağmurla
Ve boğarak o narin göğsünde hıçkırıklarını
Bir çalpara gibi yeniledi kopan yanlarını..
Yağmur içen kız.. çılgın kedi
Komalara girdi, jiletler yedi, ölmedi..
Hiç sormadım adını, kendisi de söylemedi.
Ben şişeyi boşalttım, o ağzını sürmedi.
Gitme vakti gelince uzatıp küçücük elini
Hoşça kal, dedi, almadan o malum bedelini..
Boş bir şişeden daha aptalca ne olabilirdi hediye?
Uzun uzun bakakaldı, bu adam deli mi ne, diye..
İyi ama bu şişe boş be arkadaş, dedi, bu şişe boş!
Her şey boş güzelim, dedim, her şey boş!
Sen de yağmur koyarsın belki bu şişenin içine,
Ve güneşin ışırsa bir gün, bir yerlerde, bir ihtimal,
Düşlerini yudumlarsın artık yağmurun yerine...
Yağmur içen kız.. gönül hırsızı
Hiç kimseler bilmeyecek sırrımızı..
Sen tutunmaya çalışırken gecenin eteklerine
Yine acıtacak güzelliğini, o çirkin maça papazı..
Ve yine kıyacaksın belki, o incecik bileklerine..
Yağmur içen kız.. sahipsiz bebek
Elbette bir gün herkes bir şekilde gidecek.
Ama bu yağmur var ya, bu yağmur, inan ki
Nereye gidersen git, hep ardından gelecek..
Ne zaman tokatlasa yağmurlar penceremi,
NE zaman sersem ve buruşuk bir pardösü gibi
Dökülsem kaldırımlarına bu duman karası kentin;
Hep o kıza rastlarım, aynı kuytu köşede.
Gözyaşlarını biriktirir usanmadan
Düşleriyle aynı şişede..
Hatırını sorarım, sessizce kaldırır yüzünü,
Tablolardan çalınmış gizemli bir gülücüktür.
Yağmur içer yudum-yudum, kanasıya.
Mezesi, eski bir geceden, vişne yarığı kırmızı
Ve hala kanayan o vişne ısırığı öpücüktür..
Yağmur içen kız.. mağrur yürek
Bu yağmurlar yalan ama ölüm gerçek..
Sen yine avucunda sakla, çaldırma cevherini.
Ve sakın gösterme kimseye, o yağmur incilerini
Hep şarkını söyle; hiçbir kelimesiz ve makamsız,
Hep orda bekle; bir akşam belki apansız,
Gelir de alırım şişemi senden geriye:
O biriken yaşlarını içmek için damla-damla
Ve geciken bedelini ödemek için kendi hayatımla...', 'Baldırı çıplak bir akşamüstüydü Kime selam verdiysem yüzüme küstüydü. Yalnızlığa susmuştum, yağmura üşümüştüm.. Belli belirsiz ve hiçbir mak...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":95}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR KAÇAĞI', 'yagmur-kacagi-attila-i-lhan-tl179', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'elimden tut yoksa düşeceğim
yoksa bir bir yıldızlar düşecek
eğer şairsem beni tanırsan
yağmurdan korktuğumu bilirsen
gözlerim aklına gelirse
elimden tut yoksa düşeceğim
yağmur beni  götürecek yoksa beni
geceleri bir çarpıntı duyarsan
telâş telâş yağmurdan kaçıyorum
sarayburnu''ndan geçiyorum
akşamsa  eylül''se ıslanmışsam
beni görsen belki anlayamazsın
içlenir gizli gizli ağlarsın
eğer ben yalnızsam yanılmışsam
elimden tut yoksa düşeceğim
yağmur beni götürecek yoksa beni', 'elimden tut yoksa düşeceğim yoksa bir bir yıldızlar düşecek eğer şairsem beni tanırsan yağmurdan korktuğumu bilirsen gözlerim aklına gelirse...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila_ilhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR SONRASI', 'yagmur-sonrasi-cengiz-bektas-jlvpr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolların karıştığı yerde
Birdenbire
Bardaktan boşanırcasına
Yağdın yüreğime
Toprağın ve benim
Yüreğimiz kabarık
Toprak güneşi düşünüyor ben
Ne güzel düşünüyorum seni bilsen', 'Yolların karıştığı yerde Birdenbire Bardaktan boşanırcasına Yağdın yüreğime Toprağın ve benim Yüreğimiz kabarık Toprak güneşi düşünüyor ben ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Bektaş']::text[], 8.5, '{"poet":"Cengiz Bektaş","poet_slug":"cengiz_bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR YAĞMUR', 'yagmur-yagmur-gulten-akin-5iy2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmur, yağmur... Bu neyi anlatır?
Bunca siste bunca ıslak serçe
Hüznü bir köşesinden tutup kaldırmıştır
Yağmur, yağmur... Bu neyi anlatır?
Son yaz derlenmiş, son ateş sönmüş
Düz yollara inen son kaçkın, son eşkıya
Hüznü bir köşesinden tutup kaldırmıştır.
Yağmur, yağmur... Bu neyi anlatır?
Oyun biter, o kesin güz çizgileri
Sevgi, bir de ölümle örselenmiş
Aklı bir köşesinden tutup kaldırmıştır.', 'Yağmur, yağmur... Bu neyi anlatır? Bunca siste bunca ıslak serçe Hüznü bir köşesinden tutup kaldırmıştır Yağmur, yağmur... Bu neyi anlatır? ...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR YERİNE', 'yagmur-yeri-ne-ahmet-ozer-fb0ul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1935 yazında
nazım/sare teyze
piraye hanım
bir ıhlamur ağacının gölgesinde
bir fotoğrafa döküldüler.
ilk kez yansıyor yüzleri dizelerime
bir haziran sabahını tazeliyor zaman
kollarında savrulacağı yıllar
serilmemiş ufkuna nazım''ın
ne çankırı ne bursa
ne ölümü yenmek karadeniz''de
yer almamış şiirlerinde
aşkları yedeğinde ömrümüzün.
sare teyze hasır koltukta
yüzünde ışıltısı gençliğin
saçlarında yapraklanan bir demet güneş
bir büyük aşka yaslamış yüreğini
piraye hanım
havuzdaki suyu ayaklandırıyor
gökkuşağı
bir bulut çatlıyor birdenbire
yağıyor bir sevgi yağmur yerine
nazım
sarı saçları fırtına
daha düşmemiş şiirlerine
ne çankırı
ne bursa.', '1935 yazında nazım/sare teyze piraye hanım bir ıhlamur ağacının gölgesinde bir fotoğrafa döküldüler. ilk kez yansıyor yüzleri dizelerime bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Özer']::text[], 8.5, '{"poet":"Ahmet Özer","poet_slug":"ahmet_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMUR', 'yagmur-ahmet-hamdi-tanpinar-vhe1f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyu! Gözlerinde renksiz bir perde,
Bir parça uzaklaş kederlerinden.
Bir ruh gülümsüyor gibi derinden,
Mehtabın ördüğü saatler nerde?
Varsın bahçelerde rüzgar gezinsin,
Yağmur ince ince toprağa sinsin,
Bir başka alemden gelmiş gibisin,
Dalmış gözlerinle pencerelerde.', 'Uyu! Gözlerinde renksiz bir perde, Bir parça uzaklaş kederlerinden. Bir ruh gülümsüyor gibi derinden, Mehtabın ördüğü saatler nerde? Varsın ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hamdi Tanpinar']::text[], 8.5, '{"poet":"Ahmet Hamdi Tanpinar","poet_slug":"ahmet_hamdi_tanpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMURA KARIŞAN AŞKIN ÇARESİ YOKTUR', 'yagmura-karisan-askin-caresi-yoktur-bayram-balci-rxlje', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I
yağmurun kederle yağdığı her yerde
üşüyen resimler düşer kalbime
gitmek sızar aklıma sevdiğim her kadından
durmadan kendini yakan ateşin oğluyum
bilinen bütün sözcüklerin anlamına uzak
her kadın bir uzağa çağırır beni
denize karıştıkça çürüyen ırmak
toprağını reddeden çiçek
sığınırım kendi limanıma
acının kalbidir gölgesiz suret
hayata aidat ödentisidir aşk
muhalefet bilmiştir kaçakelektrik kullanmayı
şifresi yitirilmiş bir şiir
kanayarak taşar satırarasından
intihar büyür uçurumlarında
II.
yağmura karışan aşkın çaresi yoktur
çözülür hayatın magması
ve bir kez daha telefonda
annem beni çok sevdiğini söyler
gece kan bulaşır aklıma
yakılacak mektupların cehennemindeyim
kaç şehir akıp gitti ömrümden
depresif bir metropol söyleminde
yağmur dindi kırıldı dalı kalbimin
hiç bir acıdan doğmaz bir başka acı
yaşanamayan aşklar tarar
kendini taşımaktan yorulmuş bir hayatı', 'I yağmurun kederle yağdığı her yerde üşüyen resimler düşer kalbime gitmek sızar aklıma sevdiğim her kadından durmadan kendini yakan ateşin o...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMURDA YÜRÜ SAÇLARINA KARIŞSIN GÖKYÜZÜ', 'yagmurda-yuru-saclarina-karissin-gokyuzu-bayram-balci-3tqox', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yağmurda yürü saçlarına karışsın gökyüzü
kurumuş dere yataklarına aksın
yanlış hüzünleri yüzünün
tutuşsun teleklerin telaşlı adımlarında
bir çiğ buğusu kadar
hüzünlü bulut parçası: işte sevgin
avuçiçinde yanmamış kına tazeliği
yağmurda yürü saçların ıslanırken belki beni düşünürsün
danteline işlediğin yanlışlığında yağmurda yürü
bulutlar ve nemin buğusu. toprağın kokusu yaksın yüzünü
kurtulsun ellerin senden.. uçup gitssin rüzgar kuşları
sadece iki kocaman oluk olsun gözlerin
ve şairler yağmurda ağlanmaz deseler de
sen durma akıt kirpiklerini yüzüne
yağmurda yürü saçların ıslanırken belki beni düşünürsün
yaşanmamış bir duygunun burukluğudur bu
mayıs gülüşlü bir çocuğun
ak kağıttan yaptığı yelkenliler
yüzer yüreğinin süzgün göllerinde
ayrılıkların derin anlamıdır yüzündeki çizgiler
yağmurda yürü saçlarına karışsın gökyüzü
bir sigara içimi değil elbet ayrılık
yağmurda yürü açarken dağlarda gelincik
harman yerinde yüreğinin diner özlemi
boğulur bahar çığlıklarında aklını çıldırtan suskunluk
yağmurda yürü saçların ıslanırken beni düşünürsün', 'yağmurda yürü saçlarına karışsın gökyüzü kurumuş dere yataklarına aksın yanlış hüzünleri yüzünün tutuşsun teleklerin telaşlı adımlarında bir...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMURDA', 'yagmurda-yannis-ritsos-1re1f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurda yürüyor. Hiç acelesi yok.
Islak parmaklıklar parlıyor. Gizli bir
kızıllıkla kararmış ağaçlar. Ağılın
bir köşesinde eski bir otobüs tekerleği.
Mavi ev alabildiğine daha mavi.
Hiçlik böyle aydınlanıyor demek. Taşlar
düşüyor.
Eller kapanıyor. Boş bir dosya
yüzerek yaklaşıyor nehirde. Ama senin adın
belki de dosyanın öbür yüzündedir.
Yannis RITSOS', 'Yağmurda yürüyor. Hiç acelesi yok. Islak parmaklıklar parlıyor. Gizli bir kızıllıkla kararmış ağaçlar. Ağılın bir köşesinde eski bir otobüs ...', ARRAY['Türk Edebiyatı','Şiir','Yannis Ritsos']::text[], 8.5, '{"poet":"Yannis Ritsos","poet_slug":"yannis_ritsos","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMURLU DENİZ', 'yagmurlu-deni-z-necati-cumali-0uya9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırakın beni
Dışarda yağan yağmurlar alsın
Yanısıra yağan yağmurların
Kaldırımların dibinden dibinden
Mutludur denize doğru giden
O her gün oyuklarından yere iner
Yaprak yaprak merdiven bir ağacın
Biraz dudak boyar biraz taranır
Önünde içi yağmur dolu bir aynanın
Çıkar adımlarını yağmurlara bırakır
Açıklarda denizin üstünde yüzen
Yağmurlarlayım ben
Aşk yorgunu dinlenen', 'Bırakın beni Dışarda yağan yağmurlar alsın Yanısıra yağan yağmurların Kaldırımların dibinden dibinden Mutludur denize doğru giden O her gün ...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMURUN ALTINDA', 'yagmurun-altinda-melih-cevdet-anday-87y48', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ertelenmiş bir yüzyıldı bu
Yıkık bir sur yazgımızın uydusu
Bekletir ömrü yürüyen ayla birlikte
Bırakmaz günün adını koyalım.
Yanıtsız bir yaşamdı erdemimiz
Herkes içindi ve kimse içindi
Okunmamış bir yazı, umudu doyuran,
Duaları düşünmek neye yarar
Kurgular tutuşturdu bacalardan.
Yirminci yüzyılı taşıdım
Tedirginliğimizin zorbalığıdır
sanrılar
Ve tohumun beklenmedik gürültüsüyle
Çıplak su gibi yinelenir zaman
Gökyüzünde usumuzun dirliği
Aklın başarısızlığa uğradığı içtenlik
Bir şive gibidir insan, ey öldürülmüş
insan
Bilinmeyen bir hayvana özgü bir
ses gibi
Sabırsız testi, hep dolar gibi
olan
Her şeyin sese dönüşeceği bilinemez
ki!
Yiminci yüzyılı yaşadım
Parlak suyunda boğulmuş sahipsiz
İnsan yeryüzünde durur, bulutlar
Bulutlar düşümüzde doludizgin
Soylu bir çılgınlıktı gündemimiz.
Ellerinde oyuk gözlü idoller
Yüreğimin yalanını besler üç güzel
Bir dağın tepesinde buldum üç güzeli
Ama ses yok, sessizlik yok, önce
erte yok.
Yirminci yüzyılı taşıdım
Golgota'' ya dirilemem ki,
Taşlar arasında yabanıl erinç
Ölümü diriltiyorduk hep
Yaşam tabular arasında bir esinti.
Mevsimler kurgularla oyaladı bizi
Tarlaya bırakılmış bir at gibi
Bağlı, yalnız ve özgür,
Umudumuz sabrın tutamadığı ırmak
Umutsuzluğumuz insan kalmak içindi.
Yirminci yüzyılı yaşadım
Dingin karştlıkların adını bulmalı
Sel gibi kuruyor yaşlılık, gençlik
Sanki melekleri gördük uzun saçları
Tanrının unutkan kuzgunu idik.
Nasıl unuturum ey doğa
Bana bir diyeceğin vardı, kalakaldım,
Vaktim yetmedi, ölüm kalım,
Bütün yüzyılları yaşadım
Vaktim yetmedi anlamaya.
Yirminci yüzyılı taşıdım
Atalardan kalma huysuzluk
Kuşku, yeryüzü deliliği,
Kıralımız doğuştan yarım
Ama tanrımız Ara Ara idi.
Yaşayamadım yirminci yüzyılı
Kim yaşadı ki kendi yüzyılını
Akarsuyun dilinden sezenimiz yok
Orpheus'' tan sonra ben geldim
Giz dönüp baktığımız yerde kaldı.
Görüp de bilenimiz yok.
Ah acımasızdır uykusuz soru
Delice zeytin yerdi atamız Homeros
Biz yemezdik, aşılı zeytindi bizimki
Suskun arpa, uyur uyanık harlı
toprak
Ama yüzyılımız hamdı, delice idi.
Yirminci yüzyılı yaşadık
O çağa bu çağa gömüldük
Bir şey var, susar, bakar durur
Ölümün soluduğu denizle varolan
Gökyüzünden başka çağ yoktur.
Oysa ne cok gecmis var, ne cok zaman
Ne cok gelecek, ne az zaman
Benzerlikle karşılaştık, susalım,
Kapalı bir avuçtur sözcük
Neden açıp da sormak ister insan?
Sorup da dönenimiz yok.
Hiçbir yüzyılı yaşamadım
Tüy kuşun ruhudur, ses teni
Hep anlar gibi oldum duvara vuran
güneşi
Nesne ve bilinç birdir, çağ atlattı
beni
Bir hoş bilmece içinde yaşadım.
dingin ol ruhum, belki uzaklarda
Bir yerde nicedir ilk dizeleri
Yaratılıyor acıklı destanımızın
Çağlar sonra hayranlıkla okunmak
için
Belki benzer umursamazlığımız kahramanlığa.
Kalk dostum ormana gidelim
Geyik sesleri içine çökelim
Yeniden doğuş, kıvanç, uyum
Kurgular bir yana, biz bir yana
İlk kez düşünmeden görelim
Martılar gibi yağmurun altında', 'Ertelenmiş bir yüzyıldı bu Yıkık bir sur yazgımızın uydusu Bekletir ömrü yürüyen ayla birlikte Bırakmaz günün adını koyalım. Yanıtsız bir ya...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":103}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAĞMURUN DANSI', 'yagmurun-dansi-enes-ki-sevi-c-83kq0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yağmurdan kaçarak
ıhlamur ağacı altında
duruverdik bir ara.
Üzerimizde
açan yapraklar arasından
beyaz bulutlar dönüyordu
Nefes nefese,
gülümsedik bir ara
ıhlamur soluyordu.
Yüreğimiz
vücudumuzun
her bir yanında çarpıyordu.
O an belki
Leyla''ya sessizce
bir şey söyleyebilirdim.
Ama dans başladı...
Ve yaz yağmuru
dokundu boğazımda
titreyen sözcüklere.
Enes KİŞEVİÇ', 'Yağmurdan kaçarak ıhlamur ağacı altında duruverdik bir ara. Üzerimizde açan yapraklar arasından beyaz bulutlar dönüyordu Nefes nefese, gülüm...', ARRAY['Türk Edebiyatı','Şiir','Enes Ki̇şevi̇ç']::text[], 8.5, '{"poet":"Enes Ki̇şevi̇ç","poet_slug":"enes_kisevic","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAN YANA BAŞLARIMIZ', 'yan-yana-baslarimiz-oktay-ri-fat-horozcu-3ztx9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yan yana başlarımız yastığın üstünde,
Neyi seyrederiz gözlerimiz yumulu!
Yaklaştır kuşlarını uçurmuş yüzünü,
Tut yüzüme ve avuçlarıma uzan ki,
Ey kısır ayna, yalnızlığımın benzeri,
Büyüsün memelerine kurduğum yapı!
Bir değirmen döner aramızda. Uğuldar
Kanatları gecemde, gıcırdar ipleri.
Süzülürüz, dalgın, zaman dışı düzlükte.
Bir kente varır yol: köprüsü var, geçilmez,
Otları var, biçilmez. Acıdır suları,
Bir tas içilmez. Bilinmez haritada yeri.
Buluruz, kaybederiz, yeniden yaşarız.
Uyuruz çok kollu, çıplak tanrılar gibi.
Yanaşır borda bordaya gemilerimiz,
Sıçrarız. Biz miyiz, yoksa başka biri mi!
Böyledir o, soy kısrak, silkinir ve koşar
Güneşe, bilenmiş bıçaklarıyla diri.
Yan yana başlarımız yastığın üstünde.
Açmış ellerini umutlara, bırakmış.
Yüzer saçlarının gölünde dudakla diş.
Unutulmuş bir bacak bulurum kumsalda
Düşlerle kıpır kıpır. Gündüzden biçtiği
Çavdarı öğütür, döndükçe değirmeni.', 'Yan yana başlarımız yastığın üstünde, Neyi seyrederiz gözlerimiz yumulu! Yaklaştır kuşlarını uçurmuş yüzünü, Tut yüzüme ve avuçlarıma uzan k...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat Horozcu']::text[], 8.5, '{"poet":"Oktay Ri̇fat Horozcu","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAN YANA İKİ ÜLKE GİBİYİZ SENİNLE', 'yan-yana-i-ki-ulke-gi-bi-yi-z-seni-nle-kemal-ozer-5bdoy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yan yana iki ülke gibiyiz seninle,
ayın önünden geçen bulut
önce seni karanlıkta bırakır sonra beni
senden bana eser, yerine göre,
yerine göre benden sana
şakaklarımızı serinleten rüzgâr.
İki kıyı gibiyiz karşılıklı,
hem ayırır bizi hem bağlar birbirimize
aramızda akan ırmak.
İki tarih sayfası gibiyiz art arda
birinde başlayan cümlenin sonu
ötekinde düğümlenir ancak.
Geldiği vakit hasat günleri
iki ayrı ağızda aynı anda
beliren bir gülümseme gibiyiz seninle
ve iki ter damlası gibiyiz alnında
elbirliği ile üretilip
kardeşçe bölüşülen bir dünyanın.', 'Yan yana iki ülke gibiyiz seninle, ayın önünden geçen bulut önce seni karanlıkta bırakır sonra beni senden bana eser, yerine göre, yerine gö...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANAN YÜZ', 'yanan-yuz-steinn-steinarr-701jt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıcak bir yüz yanarak
düşer mavi yağmura
mavi kanatlı günlerden
Aklın nötronunu
patlatır gece
isimsiz bir öykü gibi
Ve neyin çıplaklığıysa o
yiter kendi kıyısızlığında
günler ve geceler boyunca
Steinn  STEINARR', 'Sıcak bir yüz yanarak düşer mavi yağmura mavi kanatlı günlerden Aklın nötronunu patlatır gece isimsiz bir öykü gibi Ve neyin çıplaklığıysa o...', ARRAY['Türk Edebiyatı','Şiir','Steinn  Steinarr']::text[], 8.5, '{"poet":"Steinn  Steinarr","poet_slug":"steinn_steinarr","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANARCA', 'yanarca-huseyin-atabas-futeg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakarken çocuğuna bir anne
gözleri mine mine açar ya işte öyle
hep öyle bakacağım sana dünya.
Günler önemli değil,
aylardan ister nisan olsun
isterse mayıs;
direnmelere inat
hiçbir şeye benzemiyorsa da
ağzımdaki tat
seni unutmayacağım.
Hep bulmayı umarak
ve bir gün mutlaka kavuşarak
gökyüzündeki maviye
yeşilin en güzeliyken yaprak.
Bakarken çocuğuna bir anne
dudakları kıpır kıpır oynar ya
işte öyle yineliyorum adını.
Tam elim eline değecekken
bırakıp gitme...
Biliyor musun yarın anneler günü
çarşılar çarşılar
çarşılar kalabalık;
kimse sevemez günün doğuşunu
annelerin sevdiği kadar.
Seni anımsamıyorum sanma,
ölümün simgesidir unutmak;
ey gecelerin korkulu düşü
ey yürekleri tutuşturan yanarca!...', 'Bakarken çocuğuna bir anne gözleri mine mine açar ya işte öyle hep öyle bakacağım sana dünya. Günler önemli değil, aylardan ister nisan olsu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Atabaş']::text[], 8.5, '{"poet":"Hüseyin Atabaş","poet_slug":"huseyin_atabas","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANGIN YILI', 'yangin-yili-sureyya-berfe-c4r48', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öldürmüşler babamı
Yangın yılında
Dokunmadı kimseye
Yelim yağmurum
Yıllarca uyudum
Kara dağlarda
Ağaç mavzer yine
Ot kurşun bugün
Yeryüzü zulüm
Gökyüzü işkence
Yürüdüler mavzerler
Kan döktüler önümde
Yüreğime erik kurusu
Bastım uyudum', 'Öldürmüşler babamı Yangın yılında Dokunmadı kimseye Yelim yağmurum Yıllarca uyudum Kara dağlarda Ağaç mavzer yine Ot kurşun bugün Yeryüzü zu...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANIK HAVA', 'yanik-hava-ceyhun-atuf-kansu-lp7c9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Maviler içinde gördüm bir gün menevşemi
Yayla tutmuş başlamış aşkımın gül mevsimi.
Zühre olup yol düşmüş çeker beni şavkından,
O ışıldar sevdasından, ben yanarım aşkından,
Ben senin yüzünden güzelim konup göçücü oldum,
Böyle dağdan dağa yoldan yola geçici oldum.
Bir gün yine beyazlar içinde gördüm,
Kastı nedir bilmem, bir kere gönül verdim,
Turna derler böylesine halk türküsünde,
Çifte hasrettir uyuya kalmış göğsünde,
Aşkın dilini öğrenmeye Karacaoğlana varsam,
Diller döksem, güller döksem rüyasına uyandırsam.
Bir gün yine gördüm ki pembeler giyinmiş,
Güllerin aynasına bakıp ta övünmüş,
Sarı saçları düşmüş tel tel olmuş.
Şu garip gönlümü kul eden o ince bel olmuş,
Sorsam razı olur, hoşnut olur darılmaz,
Neyleyim ki inceciktir, dal kırılır, sarılmaz.
Bir gün de baktım giyinmiş macar olmuş,
Göğsünde Budin''in gülleri açar olmuş,
Karmendir güzel çingenelerin hası,
Kanlı olur Troubadour''ların rüyası,
Ah, şol meydanda ölesim gelir,
Bir gün bakarsınız İspanya''dan sesim gelir.
Ah, efendim ben ne diyarlar gezdim,
Türküler içinde bir de bu türküyü yazdım,
Aşktır rüzgârların en hovardası,
Bozulur insanın düzeni yıkılır obası,
Yeniden düzen tutmaya kervan kalkar yol alır,
Beri yanda yanık türkü kalır!', 'Maviler içinde gördüm bir gün menevşemi Yayla tutmuş başlamış aşkımın gül mevsimi. Zühre olup yol düşmüş çeker beni şavkından, O ışıldar sev...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun_atuf_kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANIMDA KAL', 'yanimda-kal-yusuf-altunel-r7hb5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'emine''ye
bu gece ört beni
ayrılık ayazı dışarıda
arar ellerini ellerim
özlem kırağısı düşmüş
ciğerim paramparça
ört beni giderken
kent hayın pusu sermiş
sırtımdan bıçaklar beni
daha sen hoşçakal derken
sensizlik ölümcül boşluk
yatakta oturur beklerim
kentte çıyansı orospuluk
boğazımda düğüm düğüm hıçkırıklar
kırık kayık gibi yalpalar sesim
bıçaklarım sensizlik büyüten kenti
bu şehir yaralı bir kurt kadar tehlikeli
çöpleri karıştırır faşist yalnızlık
arşınlar sokakları sevdanla bulanık
gezgin çingene dilenmeleri
panzerli gitmeler kesmiş sokakları
içimde özleme molotofları saklarım
kestane pişirir Kızılay''da aşkım
Yüksel''de böcek vızıltıları çakarım
tiner çekmişim nefesini bıraktığın kuytularda
rüyalarımda sokak çocuğu olmuşum
Sakarya Caddesi''yle öpüşürken sarhoşluğum
bu gece sev beni
korkarım öpüşmelerimiz
terkedecek şehri
yanında yüreğimden parçalar al
n''olursun gitme
bu şehirde kal.', 'emine''ye bu gece ört beni ayrılık ayazı dışarıda arar ellerini ellerim özlem kırağısı düşmüş ciğerim paramparça ört beni giderken kent hayın...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":35}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANIMDA OLSAYDIN', 'yanimda-olsaydin-yusuf-altunel-gawoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'öpsem kanatırım dudaklarını gecenin
yıldızlar sarhoş olur, düşer sulara sevdalı
mahzunluk meyleri içer dolunayda sevgililer
havalandırır yokluğunu gömütlük kuşları
yitirmelerim gelip camlara çarpar
yol vermez isyan yolculuklarıma korkular
herşey önceden yaşanmış kadar gerçek
bir düdük duyulur, karşı konulmaz istek
açılır gökyüzü, soyunursun çırıldan çıplak
gece hazırdır dörtnala arzular koşturmaya
yanımda olsaydın diye bir türkü fısıldarım
sensizlik çarpar duvarlara parçalanırım
ey yürek dayan babam ha dayan
nabızlar hızlansın, koşsun ayaklanmalar
yanımda olsaydın, olsaydın keşke şimdi şu an
sabaha kadar
nefes nefese kalırdı doyumsuz kavuşmalar
doğu batı olmuş, kuzey güney, pusulalar fırdöndü
fesleğen kokulu hasretler
orta yerinde odamın sereserpe
ben ürkek, çekingen serçe
ben buğday tanesi
sen yerçekimi
sen ayışığı
sen çay bardağım, sıcaklığım, canım
sensizliği dişliyor uyuz gece
yanında olsam
öpsem
kanatırım dudaklarını inan
üstüne gece serperim
biriktirdiğim hasretlerden azılı yorgan', 'öpsem kanatırım dudaklarını gecenin yıldızlar sarhoş olur, düşer sulara sevdalı mahzunluk meyleri içer dolunayda sevgililer havalandırır yok...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANIT', 'yanit-kemal-ozer-8oiji', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nerden geldiğini soruyorsun ya, bir söyleşi kadar kısa-
dır diyorum; ama dünyanın geçmişi kadar da köklü:
Ter döken ilk insan senin soyun, toprağı ilk işleyen,
ilk yapıyı ekleyen doğaya; akşam olurken bir su kıyısında,
belini ağaca verip de ilk türküyü söyleyen.
Diyorum ki acılarla yoğrulmuştur soyunun tarihi, ama
yalnız onun şafağından çıkılır yola, onurlu bir yarına var-
mak için.', 'Nerden geldiğini soruyorsun ya, bir söyleşi kadar kısa- dır diyorum; ama dünyanın geçmişi kadar da köklü: Ter döken ilk insan senin soyun, t...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANLIŞ ANKA DESTANI', 'yanlis-anka-destani-abdulkadir-budak-m6r45', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '3.
Uzun bir öyküdür, anlatanı bulunmalı
Bir dizeyle özetlenir: Koklanmayan gül üşür
Ama açmalı onu, birazcık kanatmalı
Şiiri, sevdayı içerir öykü
Yolcu düşkünü hanları
Söz düşmez hancıya, o ne bilir ki
Bir acı şiirle nasıl örtüşür
Yüzünü ayaz mı yalamış, hancı
Her zaman bir sıcaklığı öpmüştür
Yolcumu ki toz tadını tanısın
Hancıdır o, bu şiirde bir simge
Açıklamak için kimi şeyleri
Araç olacak belki de
(Eski sözdür: Kuşlar kanat açmalı
Bu öyküyü dinleyen bulunmalı)', '3. Uzun bir öyküdür, anlatanı bulunmalı Bir dizeyle özetlenir: Koklanmayan gül üşür Ama açmalı onu, birazcık kanatmalı Şiiri, sevdayı içerir...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir  Budak']::text[], 8.5, '{"poet":"Abdülkadir  Budak","poet_slug":"abdulkadir_budak","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANLIŞ VE YABANCI', 'yanlis-ve-yabanci-devrim-di-rli-kyapan-9plcr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'trenim öldü
akşamdan kalma bir yabancıyım
artık beni bu çağdan topla kalbim
kimsenin beklediği devrim değilim,
ne sevebildim yerimi
ne dirlik yapabildim.
kolay bitmedi gecem
şarkısını yitirmiş çingene bir çocukla
ağır yaralı iki bacak gibi yanyana
sabaha kadar devrildim,
bir göç imgesine saplanıp kaldı ayaklarım
ah yollar, görmediler ki beni gidebileyim.
geceleri altını ıslatan bir bulut muydu o çocuk
kaç damla yağmur yedim de böyle şişmanladım
ki düşlerin kanatlarına bile ağır geldi
bir zamanlar leyleklerin getirdiği bedenim.
ah kalbim, ben asaleti bozuk
tanrılar çağına mı düştüm,
bunca yıldır gezerim
hiç böyle dünya görmedim.
trenim öldü
durdu zaman makinem
öyle çok sonlar buldum ki artık
bilmiyorum nereden başlamalıyım.
hiç bulamadığı kapağıyım tencerenin
bir buluşmalar yabancısıyım,
koskoca yıllar yanlışı...
artık beni bu çağdan topla kalbim
bir şarkıya binip gideyim.', 'trenim öldü akşamdan kalma bir yabancıyım artık beni bu çağdan topla kalbim kimsenin beklediği devrim değilim, ne sevebildim yerimi ne dirli...', ARRAY['Türk Edebiyatı','Şiir','Devrim Di̇rli̇kyapan']::text[], 8.5, '{"poet":"Devrim Di̇rli̇kyapan","poet_slug":"devrim_dirlikyapan","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANYANA DALGINLIK', 'yanyana-dalginlik-melih-cevdet-anday-w9rp8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerine bakıyorum
Denizden çıkarılmış bir tabaktaki kuş resmi
Dağınık köy evleri gibi orda burda
Sepetteki sümbül soğanı gibi gölgeli
Yüreğimiz öylesine aşmış ki düşüncemizi
Yarışı başlatan tabanca sesi gibi
Dudaklarımız koşuya çıktıktan sonra
Duyuyoruz söylediklerimizi', 'Gözlerine bakıyorum Denizden çıkarılmış bir tabaktaki kuş resmi Dağınık köy evleri gibi orda burda Sepetteki sümbül soğanı gibi gölgeli Yüre...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YANYANA', 'yanyana-celal-silay-wespz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gürül gürül otların başında
Ağacın gölgesine deydi değecek
Tam şeftalinin kokusu başlarken
Öpüşmeye kıl kadar bitişik
Akarsuyun burnunun dibinde
Bu zulüm, bu haksızlık, bu işkence', 'Bu gürül gürül otların başında Ağacın gölgesine deydi değecek Tam şeftalinin kokusu başlarken Öpüşmeye kıl kadar bitişik Akarsuyun burnunun ...', ARRAY['Türk Edebiyatı','Şiir','Celal Silay']::text[], 8.5, '{"poet":"Celal Silay","poet_slug":"celal_silay","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAPAMADIĞIMIZ', 'yapamadigimiz-bulent-ecevi-t-sjmzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rahşan''a
akşam kapı eşiğinde bir terli giysi gibi
soyunmak vardı derdinden evrenin
bir entari serinliğini giyinmek
kendi derdini tespih gibi çekmek elinde
yün örmen vardı akşamları koltuğa gömülü
karşında polisiye roman okumak vardı
sorgusuz bakışmak yoruldukça gözlerimiz
sevinçsiz gülmek üzüntüsüz ağlamak
oturmağa konuklar gelmesi bazen
çevresinde bir masanın kaygısız
sıcacık konularda bir demli çay gibi
bilmedik komşularla konuşmak
dünyamızla uyuşmak vardı
oyunda sonunu görmeden oynamak
sevinebilmek kazandığına
yitirdiğine yerinebilmek
düşünmiyebilmek yoruldukça düşünmekten
kamaştıkça örtebilmek gözlerini
düşlerde bile ışıktan sakınarak kendini
uyayabilmek vardı vaktinde rahat', 'Rahşan''a akşam kapı eşiğinde bir terli giysi gibi soyunmak vardı derdinden evrenin bir entari serinliğini giyinmek kendi derdini tespih gibi...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAPI İSKELESİ', 'yapi-i-skelesi-seamus-heaney-p0fh3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duvarcılar, bir yapıya başlarlarken,
İyice gözden geçirirler iskeleleri;
Fazla basılan yerlerdeki kalaslar kaymasın,
Merdivenler sağlam mı, çiviler iyi çakılmış mı.
Gene de hepsi sökülür bunların işleri bitince,
Sağlam, güven veren duvarlar çıkar ortaya.
İşte, sevgilim, bazan bizim aramızdaki köprüler de
Yıkılıyormuş gibi görünseler de,
Hiç aldırma sen. Varsın yıkılsın iskeleler,
Biz duvarımızı ördüğümüze güveniyorsak eğer.
Seamus HEANEY', 'Duvarcılar, bir yapıya başlarlarken, İyice gözden geçirirler iskeleleri; Fazla basılan yerlerdeki kalaslar kaymasın, Merdivenler sağlam mı, ...', ARRAY['Türk Edebiyatı','Şiir','Seamus Heaney']::text[], 8.5, '{"poet":"Seamus Heaney","poet_slug":"seamus_heaney","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAPRAKTI', 'yaprakti-can-yucel-lbfnd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir başka yolculuk dalından düşmek yere,
Yaşadığından uzun;
Bir tatlı yolculuk dalından inmek yere.
Ağacın yüksekliğince,
Dalın yüksekliğince rüzgarda;
Ve bir yeni ö''mü''r
Vardığın çimen yeşilliğince.', 'Bir başka yolculuk dalından düşmek yere, Yaşadığından uzun; Bir tatlı yolculuk dalından inmek yere. Ağacın yüksekliğince, Dalın yüksekliğinc...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAR YÜREĞİM YAR', 'yar-yuregi-m-yar-yunus-emre-33cqe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yar yüreğim yar
Gör ki neler var
Bu halk içinde
Bize güler var
Ko gülen gülsün
Hak bizim olsun
Gâfil ne bilsin
Hak''kı sever var
Bu yol uzaktır
Menzili çoktur
Geçidi yoktur
Derin sular var
Girdik bu yola
Aşk ile bile
Gurbetlik ile
Bizi salar var
Her kim merdâne
Gelsin meydâne
Kalmasın câne
Kimde hüner var
Yunus sen bunda
Meydan isteme
Meydan içinde
Merdâneler var', 'Yar yüreğim yar Gör ki neler var Bu halk içinde Bize güler var Ko gülen gülsün Hak bizim olsun Gâfil ne bilsin Hak''kı sever var Bu yol uzakt...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARA BİR BAŞKASINDA KANAYAN BENİM', 'yara-bi-r-baskasinda-kanayan-beni-m-veysel-colak-cs9vk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir su köpüğünde bulmuşlar beni
artık dünyada sizler kadar esmerim
dinlediğim şarkılarda uzak yerler var
gider tarih konuşurum o şafak kuşlarını.
Gırtlağımda kekre bir tat
içimdeki gül düşer, anılarım incinir
canımız, küçücük adamların dev oyuncağı
yüzüm bir tabanca kılıfı
ne zaman buluşsak anlarlar bunu
çünkü iklim değişir.', 'Bir su köpüğünde bulmuşlar beni artık dünyada sizler kadar esmerim dinlediğim şarkılarda uzak yerler var gider tarih konuşurum o şafak kuşla...', ARRAY['Türk Edebiyatı','Şiir','Veysel Çolak']::text[], 8.5, '{"poet":"Veysel Çolak","poet_slug":"veysel_colak","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARALI  ŞİİR', 'yarali-si-i-r-attila-asut-sn4rc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirim yaralıdır
Çünkü yaralıdır yurdum.
Kınalı kuzularım
-Kızlarım
Oğullarım-
Yaralıdır.
Denizlerim kurudu
Gemilerim battı
Tayfalarım yaralıdır.
Uzun yol yorgunuyum
Söz verdim /
Dönüp bakamam geriye
Çocukluğum yaralıdır.
Genç ölülerin yaşamından çaldık
Düşenlerin ömrü eklendi ömrümüze
Ölenler niye öldü?
Biz niye hayattayız?
Sorularım yaralıdır.
Köprüleri attım
Gemileri yaktım
Atları vurdum
Gençliğim, umudum yaralıdır.
Karanlık bir kuyudayım
Kovam boş /
Su çekmiyor çıkrığım
Yaralı bir ömrün ortasında
Kanıyor şiirim ve yurdum.
Aralık 1998', 'Şiirim yaralıdır Çünkü yaralıdır yurdum. Kınalı kuzularım -Kızlarım Oğullarım- Yaralıdır. Denizlerim kurudu Gemilerim battı Tayfalarım yaral...', ARRAY['Türk Edebiyatı','Şiir','Attila Aşut']::text[], 8.5, '{"poet":"Attila Aşut","poet_slug":"attila_asut","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARASA', 'yarasa-altay-omer-erdogan-ohu6g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'her zaman geceyi yaşar mağara
göz bir işe yarasa, taş olur bakış
buz kesilir kan, tuz ile incelir yara
işte bu güzel sonsuz akış
yakıştırır bizi iyi huylu çağlara...
suyun sesiyle yüzünü yıkayan
arı vızıltısı sürer ekmeğin üzerine
papatya bilinciyle yol sayıklayan
yağlı saydam ipler indirir derine
yarasadır gerçeğin hissiyle uyanan...
hesabı yok bilincin boşlukta kırıldığı anla
istek karartır duvardaki ilkel yosunu
karanlığın ilmini çöz, geceyi anla
kalbine bağışla hayatın çoğaltan tortusunu
varlığını akla getirilmedik sorularla akla;
yarasa neyle emzirir yavrusunu?
(Şiir Ülkesi, 11. sayı)', 'her zaman geceyi yaşar mağara göz bir işe yarasa, taş olur bakış buz kesilir kan, tuz ile incelir yara işte bu güzel sonsuz akış yakıştırır ...', ARRAY['Türk Edebiyatı','Şiir','Altay Ömer  Erdoğan']::text[], 8.5, '{"poet":"Altay Ömer  Erdoğan","poet_slug":"altay_omer_erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARGI', 'yargi-bulent-ecevi-t-5ns8j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'öldürenle katiliz çalanla hırsız
tümümüz sanığız tümümüz savcı
tümümüz suçlu tümümüz yargıç
kimi aklar kimi suçlarız
kimi bağışlar kimi asarız
kendimizi başkasında
hergün bıçak saplı
birinin arkasında
vurulan da biziz vuran da', 'öldürenle katiliz çalanla hırsız tümümüz sanığız tümümüz savcı tümümüz suçlu tümümüz yargıç kimi aklar kimi suçlarız kimi bağışlar kimi asar...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARI HAZIR GÖKYÜZÜ', 'yari-hazir-gokyuzu-tomas-transtromer-0jw6l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koşuyu yarım bırakıyor cesaretsizlik.
Kaygı koşuyu yarım bırakıyor.
Akbaba bırakıyor kaçmayı.
O istekli ışık akmaya başlıyor
Hayaletler bile bir fırt çekiyor.
Her şey çevresinde bakınmaya başlıyor.
Yüzlercemiz güneşe giriyor.
Her insan yarı açık bir kapıdır
Herkes için bir odaya açılan.
Altımızdaki ölümsüz toprak.
Su parlıyor ağaçların arasından.
Göl dünyaya açılan bir pencere.
Tomas  TRANSTRÖMER', 'Koşuyu yarım bırakıyor cesaretsizlik. Kaygı koşuyu yarım bırakıyor. Akbaba bırakıyor kaçmayı. O istekli ışık akmaya başlıyor Hayaletler bile...', ARRAY['Türk Edebiyatı','Şiir','Tomas  Tranströmer']::text[], 8.5, '{"poet":"Tomas  Tranströmer","poet_slug":"tomas_transtromer","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARI YOL', 'yari-yol-ahmet-hasi-m-spi9a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl istersen öyle dinle, bakın:
Dalların zirvesindeyiz ancak,
Yarı yoldan ziyâde yerden uzak,
Yarı yoldan ziyâde mâha yakın.', 'Nasıl istersen öyle dinle, bakın: Dalların zirvesindeyiz ancak, Yarı yoldan ziyâde yerden uzak, Yarı yoldan ziyâde mâha yakın....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşi̇m']::text[], 8.5, '{"poet":"Ahmet Haşi̇m","poet_slug":"ahmet_hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARIDA KALAN BİR BAHAR YAZISI', 'yarida-kalan-bi-r-bahar-yazisi-n-zim-hikmet-5s2di', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vurdu kalın parmaklar
yazı makinamın dişlerine.
Kâğıtta her harfi majiskülle dizilmiş
üç kelime var ;
BAHAR
BAHAR
BAHAR...
Ve ben şair musahhih
ve ben hergün
iki liraya
2.000 kötü satır okumaya
mecbur olan adam,
ve ben
neden
bahar geldi de hâlâ
muşambası kopuk
kara bir koltuk
gibi oturmaktayım?
Kasketini kendi kendine giydi kafam,
fırladım matbaadan
sokaktayım .
Yüzümde mürettiphanenin
kurşunlu kiri,
cebimde 75 kuruşum var.
HAVADA BAHAR...
Berberlerde pudralanıyor
Babıâli paryasının
sarı
yanakları .
Ve güneşli aynalar gibi yanıyor
kitapçı camekânlarında
üç renkli kitap kapakları .
Fakat benim
bu caddede yaşıyan,
kapısında ismimi taşıyan
bir formalık "ALFABE"m bile yok!
Adam sen de ne çıkar!
Başım dönmüyor geri,
yüzümde mürettiphanenin
kurşunlu kiri
cebimde 75 kuruşum var .
HAVADA BAHAR...
Bu yazı yarıda kaldı.
Yağmur yağdı satırları sel aldı .
Halbuki ben neler yazacaktım neler...
3.000 sayfalık 3 cildinin üstünde
aç oturan muharrir
bakmıyacaktı da camına kebapçının,
tombul esmer kızını Ermeni kitapçının
ışıklı gözleri ile taşlıyacaktı...
Deniz kokmaya başlayacaktı .
Terli kızıl bir kısrak gibi
şahlanacaktı bahar,
ve ben onun çıplak sırtına atlar
atlamaz
sürecektim sulara.
Sonra
her adımda peşimden gelecekti
yazı makinam .
Ona diyecektim :
- Etme anam
beni bırak bir saat rahat...
Sonra,
saçları düşmeye başlayan başım
haykıracaktı uzaklara :
ÂŞIKIM...
27 benim yaşım
onun yaşı 17 .
Kör şeytan
topal şeytan
kör topal şeytan
gel bu kızı sev,dedi,
diyecektim;
diyemedim,
derim yine!
Ama yağmurmuş
yağıyormuş,
yazdığım satırları sel almışmış
cebimde 25 kuruşum kalmışmış
ne çıkar...
Bahar geldi bahar geldi bahar
bahar geldi ulan !
Tomurcuklandı içimde kan! !', 'Vurdu kalın parmaklar yazı makinamın dişlerine. Kâğıtta her harfi majiskülle dizilmiş üç kelime var ; BAHAR BAHAR BAHAR... Ve ben şair musah...', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hikmet']::text[], 8.5, '{"poet":"Nâzım Hikmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":85}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARIDA KALAN', 'yarida-kalan-kemal-ozer-p7uop', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Araya hiçbir şey girmemiş gibi
sürüp gider mi yeniden
yarıda kalan söyleşi
birbirine bağlanır mı sözcükler
anımsar mısın ne dediğimi
hışmı geçince karagünlerin', 'Araya hiçbir şey girmemiş gibi sürüp gider mi yeniden yarıda kalan söyleşi birbirine bağlanır mı sözcükler anımsar mısın ne dediğimi hışmı g...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARIM KALDI SON SERÜVEN', 'yarim-kaldi-son-seruven-ahmet-uysal-p798e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen öyle düş içindeyken
Silindi suda sureti
Yarım kaldı son serüven
Döndü durdu rus ruleti
Söz eskidi su bulandı
Nasıl bulmalı yeniden
Ki birbirine karıştı
Bilinenle bilinmeyen
Sendin o yaz parıltısı
Yörüngesiz bir gezegen
Yalnız, umarsız, bulutsu
Karanlık sularda yüzen
Bitti mi o mahur faslı
Ay ışığında söylenen
Ateşin suyla dansıydı
Yarım kaldı son serüven', 'Sen öyle düş içindeyken Silindi suda sureti Yarım kaldı son serüven Döndü durdu rus ruleti Söz eskidi su bulandı Nasıl bulmalı yeniden Ki bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uysal']::text[], 8.5, '{"poet":"Ahmet Uysal","poet_slug":"ahmet_uysal","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARIN        DÜŞÜNCESİ', 'yarin-dusuncesi-melih-cevdet-anday-x61q5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DÜŞÜNCESİ
(...) Salt
toplumcu açıdan bakıldığında, sanatçıya düşen
görevin, günümüzün gerçekleri, bu gerçeklerin
değiştirilmesi biçiminde almak tamamlayıcı olur.
Gerçekte tüm olarak toplumculuk da, yarını kurmanın
çabası değil midir? Ekonomisi, hukuku, sanatı ile
yarını...Yarın, şımarık bir çocuk değildir,
çünkü onu günümüz doğuracaktır.
Ancak şunu
da belirtmek yerinde olacaktır ki, sanatta yarını
kurmak düşüncesi, soyut bir sav olarak kaldıkça,
konumuzun sınırları içine giremez. Burada ilk
ayırdedici öğe, sanatçının doğru sözlüğüdür.
Sanat anlayışı gereği, kendini böyle bir görevle
yükümlü görmeyen sanatçı, yarın düşüncesine bu
anlamda sığınmamalıdır.
Melih', 'DÜŞÜNCESİ (...) Salt toplumcu açıdan bakıldığında, sanatçıya düşen görevin, günümüzün gerçekleri, bu gerçeklerin değiştirilmesi biçiminde al...', ARRAY['Türk Edebiyatı','Şiir','Melih
                    Cevdet Anday']::text[], 8.5, '{"poet":"Melih\n                    Cevdet Anday","poet_slug":"okuma_odasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARIN', 'yarin-bulent-ecevi-t-jr46m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'birşeyler olacak yarın
duruşundan belli
kırdaki atların
bulutların koşuşundan belli
kazışından köstebeklerin toprağı
karıncaların telâşından belli
birşeyler olacak yarın
belki bir tomurcuk
belki bir ağacın düşen yaprağı
belki de bir çocuk
pek o kadar göremesek de uzağı
kuşların uçuşundan belli
birşeyler olacak yarın
öbürgünden önemsiz
yarından önemli', 'birşeyler olacak yarın duruşundan belli kırdaki atların bulutların koşuşundan belli kazışından köstebeklerin toprağı karıncaların telâşından...', ARRAY['Türk Edebiyatı','Şiir','Bülent Ecevi̇t']::text[], 8.5, '{"poet":"Bülent Ecevi̇t","poet_slug":"bulent_ecevit","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARINA AÇAN GÜL', 'yarina-acan-gul-mustak-erenus-ejsu9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gergefte kırmızı bir gül gibiyiz
Umutlu ve keyifli
Onurluyuz bu kavgamızda
Öyle bir güç taşıyoruz ki
Kime ne zaman nerede demeden
İşte buradayız.
Bir çelik ki bu zincirin halkaları
Bilek bilek korkusuz
Yılmayan bu yürek güzelliğinde
Böyle elele.', 'Gergefte kırmızı bir gül gibiyiz Umutlu ve keyifli Onurluyuz bu kavgamızda Öyle bir güç taşıyoruz ki Kime ne zaman nerede demeden İşte burad...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARINA', 'yarina-afsar-ti-muci-n-a4lk2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yakışmıyorum kim ne derse desin
Yakışmıyorum yalnızlığa
Sizde başlamadan bende bitmesin
Benim de olmasın sizin olmayacaksa
Çam kokusunu genzime çekişim
Sizin gülü sevmenize çok benzer
Bizde incinmesin bu dirilik
Bu yağmura dayanıklı saçlar
Bu ayakta durabilme sevinci
(Bu ölüm tiksintisi içimizden gitmesin)
Ben bir ağaç gibi dallarımın kırılıp
Toprağa batırıldığını görmek isterim
Dallarımın yepyeni ağaçlar olması
Tek yüceliğim tek kutsallığım benim
Bir başıma ne işe yararım
Dostum sevgilim kardeşim bacım
Neye yarar bir insan tek başına', 'Yakışmıyorum kim ne derse desin Yakışmıyorum yalnızlığa Sizde başlamadan bende bitmesin Benim de olmasın sizin olmayacaksa Çam kokusunu genz...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARMAŞ', 'yarmas-umut-taydas-bni83', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I
İnsanlar neden ağlarsa, ondan,
Nefes yarım, can tükenik, ciğer duman,
Senli düşlerimi mezun edemedim bu hayattan,
Ne serdengeçtilik bu ayrılışım, ne isyan,
Bırakıp da gidemem nerelere, kaptırıp kaybolamam,
Biliyorum susamam sevdiğimi,
Yine dönerim sana, aylak,
Ama halim duman, gönlüm yarım,
Susup bir kenara çekiliyorum,
İnsanlar neden ağlarsa, ondan...
III
hep beklemedeyim,
kalenin önündeyim,
seni geçemiyorum,
giremiyorum içine.
artık çok sıkıldım burada;
"rızaa... rıza...
muz orta!"
VII
sedef kaplamış rengimi, ben bulanık,
sen "balıklı çermik" ten affını istemiş,
olmadı kaçıp gelmiş bir balık,
sen beni öptükçe, yaladıkça,
kendime oturuyorum...
yala beni,
sana muhtacım,
seni iyileştiririm dedin,
seninle kaldım;
suyuma dönmem lazım diye
tek nefeslik bile olsa çekip gidersen,
lanetine, felaketine tınmam,
balıklı çermiği, tepenize yıkarım...
önce bütün balıkların içine dalar
bir güzel yıkanır,
sonra yıkarım.
IX
romantizma
safsal''larını ağrıtır,
kendine güven,
başkalarını sebep bilmeye alış ki
istersen öküze dönüşebilesin.
yapabileceğin ne varsa yaptın,
çok mühim değil hastalığın,
benim,
git bir zenciyle yat
iyileşirsin.
bu dünyada kimseyle geçinemedin,
hiç kimse anlamadı seni,
hiç bir sevdiğinle sevişmedin,
herkes aldattı seni,
kandırdı, gerçekten sevmedi,
bir elmanın mükemmel bir yarısıydın,
hiç kimseyle varamadın bütüne,
iyisi mi
al kendini,
sok götüne', 'I İnsanlar neden ağlarsa, ondan, Nefes yarım, can tükenik, ciğer duman, Senli düşlerimi mezun edemedim bu hayattan, Ne serdengeçtilik bu ayr...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":59}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAS', 'yas-orhan-saik-gokyay-o8313', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dökün yaprağınızı dallarım dökün,
Akın yaslı yaslı sularım akın.
Bükün boynunuzu bayraklar bükün,
Bir alınmaz kalem vardı yıkıldı...
Durmadan çalkanan bir kızıl deniz
Bir damla yaş gibi duruyor sessiz,
Vatan ufkundaki en güzel çeyiz,
En şanslı süs baktım yarı çekildi.
Kara haber; tipi eser, savrulur,
Bir yanardağ gibi içim kavrulur,
Vatanın kaderi bende yuğrulur,
Yas olup, yaş olup gözden döküldü.
Gökyay''ım derdiyle adını anar,
Bir kararsız kuştur dalına konar
Neresinde bilmez bir yara kanar,
Saran gitti boyuncuğu büküldü.', 'Dökün yaprağınızı dallarım dökün, Akın yaslı yaslı sularım akın. Bükün boynunuzu bayraklar bükün, Bir alınmaz kalem vardı yıkıldı... Durmada...', ARRAY['Türk Edebiyatı','Şiir','Orhan Şaik Gökyay']::text[], 8.5, '{"poet":"Orhan Şaik Gökyay","poet_slug":"orhan_saik_gokyay","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YASAK ÜLKE', 'yasak-ulke-yusuf-altunel-euvhk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ölürse
bir
deli-k-anlı
kanı
düşmeden
toprağa
kopar
yaprağım
filizim
paramparça
eli
tüfekli
gencecik
dikmişler
O''raya
basar
yaygarayı
vefasız
keleş
delinir
gövdem
kanım
y-akar
toprak
yırtılır
gençliğim
paramparça', 'ölürse bir deli-k-anlı kanı düşmeden toprağa kopar yaprağım filizim paramparça eli tüfekli gencecik dikmişler O''raya basar yaygarayı vefasız...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Altunel']::text[], 8.5, '{"poet":"Yusuf Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YASAKLANIR ZAMAN', 'yasaklanir-zaman-yusuf-altunel-3wv1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eser gümüş rüzgarları zamanın
aşılır doruklar, konup göçmeler sürüklenir
abıhayat yüklü mutluluklar taşır bulutlar
davet ediliriz yaşamaya
hayat çilek kokar
kayalara yazılır adımız
mağara kovuklarında ıslattığımız
yankılanır patlamaları direnmenin
korkunun karnına kurşun sıktığımız
iklimlere rüzgarlar veririz, fırtınalar
coşku türküleri çekeriz kısacık hayattan
halaylar terli mutluluklar kokar
iliştiririz zülüflere yıldızlar
gökyüzünü eflatuna boyarız
bulutları mesela kırmızıya
gerçek üstü düşler taşırız ulaşılmazlıklara
güzü yaşamaya davet ediliriz her an
orada yasaklanır mavi ve zaman', 'eser gümüş rüzgarları zamanın aşılır doruklar, konup göçmeler sürüklenir abıhayat yüklü mutluluklar taşır bulutlar davet ediliriz yaşamaya h...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YASTIĞIM YORGANIM', 'yastigim-yorganim-sina-akyol-rjwz9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Epey uzak yıldızda
epey uzak yıldızda
ben sapsarı uyudum
Kim değer bana? Kim-
sevinç olur?.. Kendi-
yastığım!.. Ürkütür.
Ey benim, benden-
derin toprağım!
Ört beni, kurdumla-
böceğim üşür.
Ben ölürken, ey hırkam!
Avluya köz düşer.
Göğsüm kadar söz düşer.
Gümüş olur.', 'Epey uzak yıldızda epey uzak yıldızda ben sapsarı uyudum Kim değer bana? Kim- sevinç olur?.. Kendi- yastığım!.. Ürkütür. Ey benim, benden- d...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina_akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAVAŞ YAVAŞ GEÇTİM', 'yavas-yavas-gecti-m-i-lhan-berk-nss7v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YAVAŞ YAVAŞ GEÇTİM KALABALIKLARIN
ARASINDAN
Yavaş yavaş geçtim kalabalıkların arasından
bir deniz çarpması gibi çoğalta çoğalta geçen
geçtiği yeri
yavaş yavaş çıktım içimden. Dokundum
yavaş yavaş acıya, kuvarsa, şiire
yavaş yavaş tarttım suyu, anladım nedir ağırlık
kokular
coğrafya.
Eğildim sonra gövdeyi tanıdım ve düzenini
gördüm sessizliğin dümdüzlüğünü
gördüm yinelemedi gördüğüm hiçbir şey
böyle yavaş yavaş geçtim insandan insana
insanlaştırdım yavaş yavaş dışımı
böyle karıştım kalabalıklara
kalabalıklaştım böylece.
kül', 'YAVAŞ YAVAŞ GEÇTİM KALABALIKLARIN ARASINDAN Yavaş yavaş geçtim kalabalıkların arasından bir deniz çarpması gibi çoğalta çoğalta geçen geçtiğ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAVAŞÇA', 'yavasca-yannis-ritsos-1kxmh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çukuru ölçtük, kirecin içine attık ölüleri;
sonra en ince ayın altında kayığa bindik,
dördüncü arkadaş demir kutuyu kucağına almış,
sanki içindeki gizli bir ateşten ısınıyormuş gibi
üstüne eğilmişti. Duman yükselmedi,
öylece kaldı suların üzerinde.
Yannis RITSOS', 'Çukuru ölçtük, kirecin içine attık ölüleri; sonra en ince ayın altında kayığa bindik, dördüncü arkadaş demir kutuyu kucağına almış, sanki iç...', ARRAY['Türk Edebiyatı','Şiir','Yannis Ritsos']::text[], 8.5, '{"poet":"Yannis Ritsos","poet_slug":"yannis_ritsos","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAYLADA', 'yaylada-henrik-nordbrandt-zmx2c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavi gökte toplanmaya başlayan
açık renkli, ilk bulutlar
koyu gölgeler salıyor
dizboyu, kuru otlara.
Ağlamak güç,
kolay göründüğü kadar.
Henrik NORDBRANDT', 'Mavi gökte toplanmaya başlayan açık renkli, ilk bulutlar koyu gölgeler salıyor dizboyu, kuru otlara. Ağlamak güç, kolay göründüğü kadar. Hen...', ARRAY['Türk Edebiyatı','Şiir','Henrik Nordbrandt']::text[], 8.5, '{"poet":"Henrik Nordbrandt","poet_slug":"henrik_nordbrandt","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZ GEÇTİ', 'yaz-gecti-necati-cumali-hogbt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün yaz
Kuyunun başında yedik
Akşam yemeklerini
Cevizler iç tuttu
Bademlerin kabukları kurudu
Ayvalara sindi gün ışığı
Yaz geçti
İçeriye aldık
Masayı sandalyeyi
Karıncalar ortalardan çekildi
Kuyunun taşında arılar yok
Boş kova devrik durur şimdi', 'Bütün yaz Kuyunun başında yedik Akşam yemeklerini Cevizler iç tuttu Bademlerin kabukları kurudu Ayvalara sindi gün ışığı Yaz geçti İçeriye a...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZ! SEVGİLİM!', 'yaz-sevgi-li-m-hi-lmi-yavuz-i7ej0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kuş uzuyor dizelerde
kalbimdir,
üretir
dinleyin:
bir zamanlardı, dağlar
ve onların ardı
ve yabanıl bir akarsu
gibi dadandın kalbime...
yaz! sevgilim!
yürürken kekiktin boydanboya
ve yüzün ne kadar gürdü
ah hiçliğe solan gülüm!
işte sürüp bulutlar
ve elmas
ağzından ölüm sözleri
üşürdün kalbime...
yaz! sevgilim!
ve sevda günleri ürettin boydanboya
gözlerin kimbilir ne kadar sürdü?
ah hiçliğe solan gülüm!', 'kuş uzuyor dizelerde kalbimdir, üretir dinleyin: bir zamanlardı, dağlar ve onların ardı ve yabanıl bir akarsu gibi dadandın kalbime... yaz! ...', ARRAY['Türk Edebiyatı','Şiir','Hi̇lmi̇ Yavuz']::text[], 8.5, '{"poet":"Hi̇lmi̇ Yavuz","poet_slug":"hilmi_yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZ TUĞRASI', 'yaz-tugrasi-enis-batur-v4je5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tramvaydı bindiğim mor düş,
yarıda kaldı. Vatman ve biletçi
Ve uçarı çan sesi, çocuk asılıp
kaldı. Bir hayal bu şehir, gece
kuruldu gün çözüldü: Vapurlar
düz bulut, sokaklar âmâ dehliz,
kıpırdıyor heykel: Evler büyük
yangından kaldı. Sis ve duman ve
tütsü ve birkaç kekre soru, durup
durup dururken aklımda kaldı.', 'Bir tramvaydı bindiğim mor düş, yarıda kaldı. Vatman ve biletçi Ve uçarı çan sesi, çocuk asılıp kaldı. Bir hayal bu şehir, gece kuruldu gün ...', ARRAY['Türk Edebiyatı','Şiir','Enis  Batur']::text[], 8.5, '{"poet":"Enis  Batur","poet_slug":"enis_batur","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZ', 'yaz-refik-durbas-cengh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kan fışkırıyor topraktan. Yaz geldi
dağlara. Pınarlarım kurudu.
Yüzümde karanfiller kurudu.
Günler uzun, şehvetim bereketli
Karanlığımın tarihi artık yok. Başımda
aydınlığı tazelenmiş günlerin rüzgârı
Yaz geldi. Kalbim
bembeyaz yüzünde kızların
ve uzun ince bacakları arasında
bir kuş tufanı şimdi', 'Kan fışkırıyor topraktan. Yaz geldi dağlara. Pınarlarım kurudu. Yüzümde karanfiller kurudu. Günler uzun, şehvetim bereketli Karanlığımın tar...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik_durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZIN BİTTİĞİ', 'yazin-bi-tti-gi-ulku-tamer-znsk1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yazın bittiği her yerde söylenir.
Böyle kırmızı kalkan görülmemiştir
Ölüleri örten yapraklardan başka.
Çünkü sahiden yaz bitmiştir,
Göle bakmaktan usanır insan,
Koru tutmaktan, yol gözlemekten;
Çadırlar toplanır, yaralar sarılır;
Durgun bir yolculuk, uzun bir şapka
Artık yaprakları beklemektedir.
Aşk mıdır kış gelince başlayan
Beyaz kılıçla yürüyen aşka...
Bırakmaz olur kuşlarını ülkeler,
Yazın her yerde bittiği söylenir;
Yorgunluklar çoğalır silahlardan sonra;
Kardan mezarları görülür ıssızlığın
Ölü öpüşlerin koyuluğuyla...
Aşk kalmıştır otlarda yılı götüren,
Cesur savaşçıları taşıyan kışa.
Her yerde yazın bittiği söylenir,
Çürür çiçeklere yapışan kanlar;
Belki uzaktan iki atlı yaklaşır,
Belki yakından iki yaprak kalkar;
Akşamın örtüsü derelerde yıkanır,
Gökyüzünü görünce gecenin devi
Çıkarıp şapkasından yıldızlar saçar,
Cüceler bunu bilir, gürgenler bilir,
Aşkın uyumadığı her yerde söylenir.', 'Yazın bittiği her yerde söylenir. Böyle kırmızı kalkan görülmemiştir Ölüleri örten yapraklardan başka. Çünkü sahiden yaz bitmiştir, Göle bak...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku_tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":29}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZIN IŞIKTAN SELİ', 'yazin-isiktan-seli-necati-cumali-4rvx5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tepeden denizi gördük
Üstünde denizin
Yazın ışıktan seli
Patladı birdenbire
Bir söğüdün dibinde
Karpuz kestik yedik
Yazın ışıktan seli
Bıçağımın yüzünde
Uzandık altımızda
Kuru otların Salı
Elimde karımın eli
Yaz sellerini geçtik', 'Tepeden denizi gördük Üstünde denizin Yazın ışıktan seli Patladı birdenbire Bir söğüdün dibinde Karpuz kestik yedik Yazın ışıktan seli Bıçağ...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumali']::text[], 8.5, '{"poet":"Necati Cumali","poet_slug":"necati_cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZIT,I', 'yazit-i-i-lhan-berk-z0k2m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İşte A, D, Z, saçın gecesi,
Geç evim, ey benim eski zaman ırmağım.
Bir yerdeyim, oranı iniyorum.
İşte açık aynasındasın bunluğumun.
Ben size ne dedim rüzgârın atları
Ki oraya çıkıyorum.
Gelin durun benim eksenime
Vardır ölümün büyük evleri çıkarsınız.
Otağ', 'İşte A, D, Z, saçın gecesi, Geç evim, ey benim eski zaman ırmağım. Bir yerdeyim, oranı iniyorum. İşte açık aynasındasın bunluğumun. Ben size...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZIT,II', 'yazit-ii-i-lhan-berk-cubqa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ilk çağıydı göğünün dünyada
Ben geldim senin som akşamını açtım.
Beyaz, bir yerdeydik hani oluruz ya
Alınmış sularım flavtalarım defterlerim.
Otağı topladık en eski bir zamanda
Vaktin neresiydi prenslerim mağralarım?
Eskir korkunç ben şimdi geçiyorum ya
Kuşlarım askerlerim hiyerogliflerim.
Otağ', 'Bir ilk çağıydı göğünün dünyada Ben geldim senin som akşamını açtım. Beyaz, bir yerdeydik hani oluruz ya Alınmış sularım flavtalarım defterl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZLA BİTEN', 'yazla-bi-ten-afsar-ti-muci-n-fzzfp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dışarıda zamanı yürüten kırık bir arabanın
Soluğunda uyur bütün akşam saatleri
Günün yanıbaşında güne uzak kalmanın
Unutmayla kapanır perdeleri
Nasıl beklenmeden gelir yağmur bulutu da
Nasıl ince yağmurlarla sarar serüvenleri
Dünyada bir benzeri olmayan saatleri
Koyar eski sandıkta tozlanmış kutusuna
Hiçbir eksik sağınmanın gölgeleyemediği
Bir yalnız kalmanın son yaprakları dökülür suya
Bitmeyecek güneşleri içen sonbahar var ya
Hem kendini eskitir hem dağda çiçekleri
Eskiyen kurbağalarla sesi çıkmaz suların
Gece bütün bir karanlıkta aralıksız sancılanır
Aynı suları doldurur senin zaman dediğin
Onda hem bir sen olma hem kaçma umudu vardır', 'Dışarıda zamanı yürüten kırık bir arabanın Soluğunda uyur bütün akşam saatleri Günün yanıbaşında güne uzak kalmanın Unutmayla kapanır perdel...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZMADAN EDEMEDİM', 'yazmadan-edemedi-m-behcet-aysan-x468s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rüzgâr bu şiiri sana götürsün
kâğıttan yaptığım
o işlemeli
kayıklar
fırtınalara
dayanan.
koş rüzgâr koş.
yazmadan edemedim', 'rüzgâr bu şiiri sana götürsün kâğıttan yaptığım o işlemeli kayıklar fırtınalara dayanan. koş rüzgâr koş. yazmadan edemedim...', ARRAY['Türk Edebiyatı','Şiir','Behçet Aysan']::text[], 8.5, '{"poet":"Behçet Aysan","poet_slug":"behcet_aysan","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZMAK', 'yazmak-blaise-cendrars-sugk7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düzenli tıkırtılarla vuruyor yazı makinem
Çınlıyor her satırın sonunda
Genizden söylüyor R''leri dişliler
Kimi zaman şöyle bir arkaya kaykılıyorum hasır koltuğumda
Ve halka halka duman üflüyorum ağzımdan
Hiç sönmüyor cigaram
O sırada sesini duyuyorum dalgaların
Gurultularını lavabonun borusuna sıkışmış suların
Kalkıyorum soğuk suya daldırıyorum elimi
Ya da koku sürünüyorum
Örttüm aynalı dolabın aynasını yazarken görmemek için kendimi
Lomboz bir güneş diskidir
Düşündüğüm zaman
Trampet derisi gibi çınlıyor bağırarak konuşuyor.
Blaise  CENDRARS', 'Düzenli tıkırtılarla vuruyor yazı makinem Çınlıyor her satırın sonunda Genizden söylüyor R''leri dişliler Kimi zaman şöyle bir arkaya kaykılı...', ARRAY['Türk Edebiyatı','Şiir','Blaise  Cendrars']::text[], 8.5, '{"poet":"Blaise  Cendrars","poet_slug":"blaise_cendrars","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YAZMASINDA', 'yazmasinda-ulku-tamer-8mvt8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazmasında bozkır uzanır.
Acısını dolar saçlarına.
Kasketinde kar ateşi.
Agilinde kurşun anısı taşır.
Arkadaştır
Doğan günle, batan günle
Güneşin her türlüsüyle
Ayın hilâliyle, ondördüyle
Gökte kalanıyla yağmurun
Selin savrulanıyla
Dikenin tırnak kadar gölgesiyle
Irmağın parmak kamaştıran taşıyla
Arkadaştır dağın efsanesiyle.
Mintanında sürüler otlar.
Rüzgârı yerleştirir derisine.
Yakasında küf böceği.
Sakosunda bebe kaçağı taşır.
Kardeştir
Kuzuyla, canavarla
Yol tüketen merkeple
Devenin resmiyle, kendisiyle
Kanat vuran sevdasıyla şahinin
Cerenin türkülenmiş sesiyle
Kumrunun dem çekeniyle
Yaralı toynağıyla atın
Kardeştir Şahmeran''ın masalıyla.
Çarığında sabır taşı büyütür.
Tohum eker ayağına.
Çorabında dut kurusu.
Şalvarında mayın tarlası taşır.
Candaştır
Sabah gözleyen nineyle
İstasyon görmüş oğulla
Tükenen tarhanasıyla gelinin
Sağdıcın borç bulanıyla
Komşunun ağıt dokuyanıyla
İçine ağu katılmış tuzla
Alın yazısını çatlatan kuraklıkla
Candaştır elinin emeğiyle.
Şiir bilmez, ama şiirin hasını taşır.', 'Yazmasında bozkır uzanır. Acısını dolar saçlarına. Kasketinde kar ateşi. Agilinde kurşun anısı taşır. Arkadaştır Doğan günle, batan günle Gü...', ARRAY['Türk Edebiyatı','Şiir','Ülkü Tamer']::text[], 8.5, '{"poet":"Ülkü Tamer","poet_slug":"ulku_tamer","theme":"Türk Şiiri","is_hero":false,"total_lines":42}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEDİ CANLI OLMAK', 'yedi-canli-olmak-rifat-ilgaz-uk004', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arada bir düşündüğüm oluyor:
Var mıyım, yok muyum ben de,
Bu yeryüzünde?
Baki Hoca''mızın söylediği gibi
Kabuğumdan sıyrılıp
Hakka yönelmediğime göre henüz
Sedef-i şerifimin içindeyim demektir
Yaşayıp gidiyorum, sizin anlayacağınız!
Nasıl mı yaşıyorum?
Bu da mı sorun!
Yaşıyorum ya siz ona bakın!
Gençken bir şiirimde,
"İş doğmakta değil!" demiştim,
"Gelmişken yaşamakta!"
Dekart gibi düşünüp
Dekart gibi konuşursam eğer:
"Yaşıyorum…" Eee şu halde?
Canım anlayıverin gerisini,
Hiç kuşkunuz olmasın ki, "Varım!"
Onun gibi de değil, açıkçası
Ben var olmak için yaşıyorum.
Bırakın düpedüz yaşamayı
Yaşamak için geceli gündüzlü
Direniyorum üstelik!
Çare yok,
Tüm acılara direneceksin önce
Daha çok,
Acınmalara direneceksin, iki,
Yokluğa, yoksunluğa… Üüüç!
Güler yüz göstermeyeceksin
Yüzüne gülenlere, dört!
En önemlisi
Ezenlere karşı direneceksin, beş!
Ezilenlerin yanıp yakınmalarına!
Etti mi altı!
Yedincisi mi, can yoldaşım,
Övgülere direneceksin,
Seni göklere çıkaran övgülere!
Ayakların bir kesildi mi yerden
İşte asıl o zaman,
Sedef-i şerifini terkettin demektir!
Kolay değil, yaşamak!
Saati geldi mi, can yoldaşım,
Canını dişine takıp
Soluk almak için bile direneceksin!
Kulağımız Kirişte  adlı şiir kitabından 1983
Bütün Şiirleri 1927-1991(Çınar Yayınları)', 'Arada bir düşündüğüm oluyor: Var mıyım, yok muyum ben de, Bu yeryüzünde? Baki Hoca''mızın söylediği gibi Kabuğumdan sıyrılıp Hakka yönelmediğ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEDİ KÜÇÜK FOTOĞRAF', 'yedi-kucuk-fotograf-onat-kutlar-tq4eg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok tenha bir kumsala çekilmiş
Bir dilim taze kavun sandalı
Masanın ayağından sular geçiyor
Çıplak memeni okşayan rüzgâr
Bir turunç kokusuyla sarıyor
Buğulu kadehe bakan yüzümü
İkindi güneşi bir pencerenin
İşlemeli demirine vuruyor
İçerdeki kuşlar dağılsın diye
"Aptal" diyor "durma orda yanarsın"
Gölgeye çağırıyor tales eşeğini
Zeytinin dibinde bir ufacık kız
Bir bakır mangaldan iki istavrit
Gizlice göz kırpıyor kedilere
Defneler yaprak kabartıyor
Balıkçılar ağ atıyor durgun denizin
Dibini ışıtan mor yıldızlara
Ve akşam da onlara ağ atıyor
Alıp götürecek ay görününce
Herkes sevdiğini yer yatağına
Yeryüzü sevişince değişiyor', 'Çok tenha bir kumsala çekilmiş Bir dilim taze kavun sandalı Masanın ayağından sular geçiyor Çıplak memeni okşayan rüzgâr Bir turunç kokusuyl...', ARRAY['Türk Edebiyatı','Şiir','Onat Kutlar']::text[], 8.5, '{"poet":"Onat Kutlar","poet_slug":"onat_kutlar","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEŞEREN OTLAR', 'yeseren-otlar-cahit-kulebi-3lz87', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir melek su taşıdı,
Biri serinlik taşıdı uzaktan
Biri yeşillik getirdi.
Yıldırım gibi, ama sessiz
Çimenler sökün etti kara topraktan.
Sonra sen geldin dünya güzelim!
Yürüdün salına salına,
Bastığın yerde güller açtı,
Sarıldı ayaklarına.
Aşk da yeşeren otlara benzer
Günü saati bilinmez.
Bakarım bir gün hepsi solmuş
Dünya güzelim gider gitmez.', 'Bir melek su taşıdı, Biri serinlik taşıdı uzaktan Biri yeşillik getirdi. Yıldırım gibi, ama sessiz Çimenler sökün etti kara topraktan. Sonra...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi̇']::text[], 8.5, '{"poet":"Cahit Külebi̇","poet_slug":"cahit_kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEŞİL ÇAĞ', 'yesi-l-cag-mustafa-i-lhan-gecer-3t588', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sizin yaşınızda olmak ne iyi çocuklar
Ne iyi
Asıp düşünceyi bulutlara
Özgür kelebekler gibi
Sizin eliniz ne ince çocuklar
Ne ince
Solmasın umutlarınız
Deli gibi bir rüzgâr değince
Sizin umutlarınız ne büyük çocuklar
Ne büyük
Değdikçe zamanın eli
Sizin de yaşantılarınız bölük
Sizin gözleriniz ışın ışın çocuklar
Işın ışın
Duymayın körpe yüreklerinizde
Endişesi kışın
Yalnız sizin sevginiz gerçek çocuklar
Yalnız sizin
Sizde mavisi sizde rüzgârı
Gök ve denizin', 'Sizin yaşınızda olmak ne iyi çocuklar Ne iyi Asıp düşünceyi bulutlara Özgür kelebekler gibi Sizin eliniz ne ince çocuklar Ne ince Solmasın u...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan  Geçer']::text[], 8.5, '{"poet":"Mustafa İlhan  Geçer","poet_slug":"mustafa_ilhan_gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEŞİL BAŞLI GÖVEL ÖRDEK', 'yesi-l-basli-govel-ordek-karacaoglan-3jebn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeşil başlı gövel ördek
Uçar gider göle karşı
Eğricesin tel tel etmiş
Döker gider, yâre karşı
Telli turnam sökün gelir
İnci mercan yükün gelir
Elvan elvan kokun gelir
Yâr oturmuş yele karşı
Şahinim var bazlarım var
Tel alışkın sazlarım var
Yâre gizli sözlerim var
Diyemiyom ele karşı
Hanı Karac''oğlan hanı
Veren alır tatlı canı
Yakışmazsa öldür beni
Yeşil bağla ala karşı', 'Yeşil başlı gövel ördek Uçar gider göle karşı Eğricesin tel tel etmiş Döker gider, yâre karşı Telli turnam sökün gelir İnci mercan yükün gel...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEŞİL BİR CEVİZ GİBİ', 'yesi-l-bi-r-cevi-z-gi-bi-metin-guven-3znaz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaz geliyor tutarak elinden güneşin
Yürümek için saldırgan denizlere doğru
Herkes kendi rüyasında yaşıyor
Geçen zaman mı yoksa
Hiç başlamayan uykular mı
Bense dönüyorum yüne yüzümü sana
Çekilerek kabuğuma, yeşil bir ceviz gibi.', 'Yaz geliyor tutarak elinden güneşin Yürümek için saldırgan denizlere doğru Herkes kendi rüyasında yaşıyor Geçen zaman mı yoksa Hiç başlamaya...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YEŞİL YAĞMUR', 'yesi-l-yagmur-i-smail-uyaroglu-kqimi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktınız mı hiç uzun uzun
Yeşil gözlü bir kızın
Çayır çimen ferahlığı doluyor içinize
Ve ipince ıslanıyorsunuz
Sanki yeşil bir yağmur
Yağıyor usul usul üstünüze', 'Gözlerine baktınız mı hiç uzun uzun Yeşil gözlü bir kızın Çayır çimen ferahlığı doluyor içinize Ve ipince ıslanıyorsunuz Sanki yeşil bir yağ...', ARRAY['Türk Edebiyatı','Şiir','İsmail  Uyaroğlu']::text[], 8.5, '{"poet":"İsmail  Uyaroğlu","poet_slug":"ismail_uyaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YELİN KAZDIĞI YERDE', 'yeli-n-kazdigi-yerde-yves-bonnefoy-hmv46', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I
Denir ki bir tanrı aramıştır
Kapalı sular üstünde
Yırtıcı kuşun istemesi gibi
Uzak avını
Ve yinelenen bir bağırışla,
Ki boğuk, ıssız,
Yaratmıştır parlayan zamanı
Orda dalga kazınır.
Gece örter gündüzü
Çekilir sonra,
Köpüğü yayılır
Buranın taşları üstünde.
Nedir Tanrı,
Bir tek zamansa yapıtı,
Yok olmak mı istedi
Doğamadığı için?
Boşunaydı savaşı
Yokluğa karşı.
Attığı ağı.
O tuttu kılıcı.
II
Ama kalır şimşek
Dünyanın üstünde
Bir ırmak geçitindeymiş gibi, arayarak
Taştan taşa.
Acaba güzellik
Yalnızca bir düş müydü,
Gözleri kapalı yüzü mü
Işığın?
Hayır, çünkü yansıması var
Bizde, ve yalazdır
Ölü odunun suyunda
Yıkanan çıplak.
Coşturduğu gövdedir
Bir aynanın
Yanan bir ateş gibi, ansızın,
Taşlar çemberinde.
Ve anlamlıdır sevinç sözcüğü
Ölüme karşın
Kazdığı yerde yelin
Bu parlak korları.
III
Yeterliği günlerin
Ki giderler şafağa
Göz kamaşmalarıyla
Gece göğünde.
Kılıç, ağ
Artık yalnızca bir
Eldir, usulca sarılan
Kısa enseye.
Ruh, aydınlanmış,
Bir yüzücü gibidir
Atlayan, ansızın,
Işığın altına.
Ve gözleri kapalıdır,
Bedeni çıplak,
Ağzı tuzu ister,
Sözü değil.
Yves BONNEFOY', 'I Denir ki bir tanrı aramıştır Kapalı sular üstünde Yırtıcı kuşun istemesi gibi Uzak avını Ve yinelenen bir bağırışla, Ki boğuk, ıssız, Yara...', ARRAY['Türk Edebiyatı','Şiir','Yves Bonnefoy']::text[], 8.5, '{"poet":"Yves Bonnefoy","poet_slug":"yves_bonnefoy","theme":"Türk Şiiri","is_hero":false,"total_lines":62}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ AŞK', 'yeni-ask-sureyya-berfe-ol9f2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanında oturan ben değilim
Zamanla dirilen anılar
Sorular soran ben değilim
Pişman eden merak
Geçmişi kabartan ben değilim
Yeni biten maceralar
Seninle yaşayan ben değilim
Yere düşen yaprak
Duygularını şaşırtan ben değilim
Gelip geçen acımalar
Kolunda uyuyan ben değilim
Uzaktan gülen aşk
Karşında ağlayan ben değilim
Yürekte esen rüzgâr', 'Yanında oturan ben değilim Zamanla dirilen anılar Sorular soran ben değilim Pişman eden merak Geçmişi kabartan ben değilim Yeni biten macera...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ BİR DÜNYA', 'yeni-bi-r-dunya-melih-cevdet-anday-t2uk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünyada geçirdim çocukluğumu
İnsanlardan eşya yaparlar
Kırmızı bir orman iki boyutlu
Kendi başına yağardı kar.
Gör ki, öldüğümde bilmedim,
Elimde bunca sözcük kaldı.
Nerde geçecek benim erginliğim
Bu dünya bir daha olmalı.
Bir dünya daha olmalı, burada
Bir yerde, o kadar yakın ki,
Seslensem duyulacak belki,
Belki başladım onu yaşamaya.', 'Dünyada geçirdim çocukluğumu İnsanlardan eşya yaparlar Kırmızı bir orman iki boyutlu Kendi başına yağardı kar. Gör ki, öldüğümde bilmedim, E...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ ER', 'yeni-er-fazil-husnu-daglarca-tizkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savaş çıkmıştı
Orduya aldılar onu
Tüfek verdiler
Mermi verdiler
Süngü verdiler
Bomba verdiler
Gaz maskesi verdiler
Tanımadığı adını bilmediği
Bütün gereçleri verdiler
Dağ başında gözcüydü o
Aşağıda ırmak sanki bir gelin-
Sanki bir kuş - yeryüzünde akan bir kuş
Orman koyu yeşil - yeşil - açık yeşil
Sanki bilgeler arası çağsal toplantı
Ki mavi söylencelere benzemektedir
Yarısı görünen göl
İşte başaklar sallana sallana
Sürezi yenilemekte evrensel bir devinim
Hepsi bir severlik içinde sessiz
Ötelere ulaşmaktadırlar kendi varlıklarından
Baktı yeni er üstüne başına mırıldandı:
Peki niye
Bunca güzelliklere karşı
Böylesine çirkin giyinmek', 'Savaş çıkmıştı Orduya aldılar onu Tüfek verdiler Mermi verdiler Süngü verdiler Bomba verdiler Gaz maskesi verdiler Tanımadığı adını bilmediğ...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil_husnu_daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ GELİN', 'yeni-geli-n-metin-demi-rtas-96jmu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geldim, konuk oldum evine
Çardak altı serin
Avlun yeni süpürülü, ıslak
Nane kokar
Yeşil soğan, sarmısak
Pencerende saksılar
Penceren kıraçlara bakar
Elinle mi diktin?
Sabah sefaları, gülhatmiler
Böyle güzel kokar...
Sedirde sıra sıra
Çağla çiçeği yastıklar
Üstünde pembe güller
Ve kuş sürüleri
İpekle mi işledin?
Böyle canlı ve serin
Seslensem uçacak
Koklasam solacaklar...
Yerde bir kilim
Kilimde huzur
Bağdaş kurmuş oturur
Sevdayla mı dokudun?
Böyle renk renk
Nakış nakış
Desen dere olup akacak
Sevda türkü olup tütecek...
Testide su
Tepsiyle üzüm getirdin
Üzümle bir olmuş
Taze kına kokar ellerin
Ekmeğini yeyip, suyunu içtik
Mutluca kal, yüzü güleç gelin', 'Geldim, konuk oldum evine Çardak altı serin Avlun yeni süpürülü, ıslak Nane kokar Yeşil soğan, sarmısak Pencerende saksılar Penceren kıraçla...', ARRAY['Türk Edebiyatı','Şiir','Metin Demi̇rtaş']::text[], 8.5, '{"poet":"Metin Demi̇rtaş","poet_slug":"metin_demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ GÖKLER', 'yeni-gokler-afsar-ti-muci-n-khh36', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Büyük kuşların uçmak zorunda olduğu gökleri
Eski sürüngenler bir türlü anlamadılar
Bir kanat vuruşuyla çekip gitmeleri
Yol korkakları her zaman yadırgayacaklar
Ve birden geriye dönüşün kırmızı gülleri
Bizi en olur biçimde uzun uzun anlatmalıdırlar
Giydiğimiz yamalı yorgunluk eskileri
Unutulmuş olmaya artık katlanmalılar
Eğer hiç sarsılmayacak bir yalnızlığımız varsa
O bizi birbirimize doğru iten bir Pazar
Sevişmeler taş devrinden kalmaysa
Utansın mı tarihten önceki zamanlar
Büyük kaptanların geçmek zorunda olduğu denizleri
Balinalar ve buz dağları korkutamayacak
Korku bir yüz karası gibi sancılanacak
Silip attığı için bütün değişmeleri', 'Büyük kuşların uçmak zorunda olduğu gökleri Eski sürüngenler bir türlü anlamadılar Bir kanat vuruşuyla çekip gitmeleri Yol korkakları her za...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ GÜVEYİ', 'yeni-guveyi-sureyya-berfe-qvk16', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Davullar zurnalar arasındaki şaşkın güveyi
Yürümek isterim son yolunu
Uyumak son geceni
Görmek isterim düşünü
Erginliğinde tanıdığın hayvanlarla boğuşmanı
Ah toy güveyi
Gelin geliyor gelin
İç biraz daha
Bir kurşun daha sık
Gelin geliyor gelin
Tayını tanıdığın atla', 'Davullar zurnalar arasındaki şaşkın güveyi Yürümek isterim son yolunu Uyumak son geceni Görmek isterim düşünü Erginliğinde tanıdığın hayvanl...', ARRAY['Türk Edebiyatı','Şiir','Süreyya Berfe']::text[], 8.5, '{"poet":"Süreyya Berfe","poet_slug":"sureyya_berfe","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜŞÜYEN PALTO', 'usuyen-palto-bayram-balci-lwlng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'suyum ıslandı. sesim konuşamıyor beni
kapattım hayatı yüzüme
esmer bir kadın oldu yağmur
ateş neden yakamıyor beni
suyum ıslandı. akşam aklamıyor beni
sicilim bozuk. yüzüm sabıkalı
aklım yokuş. sabahsız bir rüyayım
hayatın nidasında kanıyor kalbim
suyum ıslandı. ateşkes ilan ettim aşka
rüzgar tadında ekmekparasıyım
kapandı kafes. kuş uçtu. nihaventim
yağmur ne zaman vuracak beni
suyum ıslandı. adımı yırttım
üşüyen palto. sarhoş bir A''yım
vurdum yavrusunu yiyen balığı
avucumda kaygıyla çürüdü su', 'suyum ıslandı. sesim konuşamıyor beni kapattım hayatı yüzüme esmer bir kadın oldu yağmur ateş neden yakamıyor beni suyum ıslandı. akşam akla...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÜŞÜYEN SEVİŞME', 'usuyen-sevi-sme-umit-sener-ta-r0vy2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yan yana gelmez bedenler
kusurlu caddeler değil
sana gelemeyişim
beni avutamaz gece sevdaları
günahları seven kadınlar değil
dönmez o çocuk
sevdalı kentlerin kucağına
ellerini tutmaz kibrit satan kızların
sen düşlerini yaz ıslanan yapraklara
seviş günahını unutarak üşümelerin
sıcacık girdiğin yataklarda,
dön-me-yeceğim', 'yan yana gelmez bedenler kusurlu caddeler değil sana gelemeyişim beni avutamaz gece sevdaları günahları seven kadınlar değil dönmez o çocuk ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Şener Ta']::text[], 8.5, '{"poet":"Ümit Şener Ta","poet_slug":"umit_sener_ta","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİ YETENLERE', 'yeni-yetenlere-tugrul-atasoy-mfdvx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ufaklık yavaş büyü biraz
Tadını çıkar uzak olmanın
Yasaktan günahtan
Konuşarak anlaşamazken
Birbirimizle
Kaynaşıverirsin sen
Koca bir gülücükle
Bakıp sımsıcak
Öcülerle bile
Konuşmaz olduk düşünce
Dizlerimizi kanatan taşlarla
Çoktan selamı sabahı kestik
Can verdiğimiz oyuncaklarla
Farklı değil bakınca şimdi sen
Çiçek çiçekten böcek böcekten
Biz güzellikleri göremez olduk
Yarattığımız kötülerin gölgesinden
Kimseler nazımızı çekmez oldu
Bilesin
Hepsini hatırlayamamak inan çok acı
Nasıldı acaba sen yaştaki biz
Sen bilebilirsin daha neler var
Büyümek adına kaybettiğimiz', 'Ufaklık yavaş büyü biraz Tadını çıkar uzak olmanın Yasaktan günahtan Konuşarak anlaşamazken Birbirimizle Kaynaşıverirsin sen Koca bir gülücü...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Atasoy']::text[], 8.5, '{"poet":"Tuğrul Atasoy","poet_slug":"tugrul_atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENENİ SEVMEM YENİLENİ HİÇ', 'yeneni-sevmem-yeni-leni-hi-c-mustak-erenus-lzcva', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Taş kodum taş üstüne
Yedirmedim özüme bu çileyi
Durdum da düşünemedim
Kimlerdi bu eşkıyanın kendileri
Yorulmazlar mıydı bu yağmada
Bıkmazlar mıydı
Hele utanmazlar mıydı hiç.
Nerdeeee..
Oysa ki
Gökteki o cins yıldızlar gibi
Ölümleri çoktan çıktı yola
Ve de hâlâ
Yaşar görürler bu efendiler kendilerini.', 'Taş kodum taş üstüne Yedirmedim özüme bu çileyi Durdum da düşünemedim Kimlerdi bu eşkıyanın kendileri Yorulmazlar mıydı bu yağmada Bıkmazlar...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİLGİ', 'yeni-lgi-nihat-behram-pw4iu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah susuşu o saf yüreğin
ah, acısı acemi çocukluğun
düş kırıklığı, coşkudaki bozgun
Ah yenilginin yorgun kısrağı
kendi içini kavuran kızgın ateş
bekleyişe bağlanan umut, tasası haykırışın
Ah, ardı ardına kenetlenen ölüm
ah, hıncı sabırla bezeyen sır
yazmadaki sırması ağlayışın, tırnaklara oturan kan
Sanki delirmenin eşiğindeyim
boş bomboş gözlerine gömülmüşüm bir köpeğin
mısırların süt taneleri, kestanelerin
bademlerin daha olgunlaşmamış
suyla susuzluk arası kayganlığında
aranıp duruyorum kendimi
Ey yangınlarda patlamaya hazırlanan merak
ey içimi ekşi sularla çalkalayan baş dönmesi
ıssız ıpıssız boşluğu aysız gecenin
ölümle yaşamak arasındaki şerit
naneler, kekikler, ebegümeçleri
ve şifalı bulutu kaynar kükürt deresinin
çekiyor altımdan nemli döşeğimi
Ah, yürekleri toprağa saplanan arkadaşlarım
ah, oğlakların, tayların, buzağıların
acı otlarla kararan damakları
(akşamları barut kokusuyla dönsem
de odama,
sancısı: çaresiz seyrettiğim ölümün
Ah, bir kere daha kederliyim
ah, çılgın bir aşkın kollarında incelen bıçak
seni öperek bilemeliyim
Nihat', 'Ah susuşu o saf yüreğin ah, acısı acemi çocukluğun düş kırıklığı, coşkudaki bozgun Ah yenilginin yorgun kısrağı kendi içini kavuran kızgın a...', ARRAY['Türk Edebiyatı','Şiir','Nihat
behram']::text[], 8.5, '{"poet":"Nihat\nbehram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":34}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YENİYIL', 'yeni-yil-yusuf-altunel-1sq08', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kardan
adam bir ömür bu bizimkisi
zamanın
ışınlarıyla eriyor, yaklaştıkça bitmesi
yüzümüzde çizgiler, saçımızda aklar
hiç
koymaz ama
sızlatıyor derinden dostların uzaklaşıp gitmesi
yaklaştık yeniden elimizle koyduğumuz sınıra
hızlı
geçiyorsa hayat, mutluluktan
yavaşsa
belli ki zor çekmesi
kısacık
bir sene kaldı simdi ardımızda
yaşamaktan korkma, kork ama unutulmaktan
yağsın
üstümüze uçuşan yılların kar taneleri
ki
dökelim üstüne dostluğun gül reçelini
anılar,
hafıza kavanozunda tazecik dursun
yenisi
şu yılın, her çeşniden mutluluk koysun', 'kardan adam bir ömür bu bizimkisi zamanın ışınlarıyla eriyor, yaklaştıkça bitmesi yüzümüzde çizgiler, saçımızda aklar hiç koymaz ama sızlatı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Altunel']::text[], 8.5, '{"poet":"Yusuf Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YER YOK BANA', 'yer-yok-bana-bayram-balci-v1cbq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aklına kuşkonmaz bir yolcuyum
yasak hevesler büyür içimde
sağanaklara tutulur çalarım zamanı
kediler yarışır aşkın atlasında
kuşlar kalkıyor dallarımdan
uzaktan yaralı bir kalple bakıyorum
hangi acıya saracaksan sar yaralarımı
imtina ediyorum hayattan
kuşladım çünkü bütün yuvalarımı
oyalandığım bütün istasyonlarda kalbim oyulur
savurdum kendimi gecenin havzasına
aklımdan kaç kuş havalandı kaç kuş döndü yuvaya
kime ne taşıyorsam kalbimi avuçlarımda
bulsam yalnızlığın biçimini
sever miydim yine de seni
benim avuçlarına sığmayacak bir kalbim var
uzaktan yakın olan herşeyin acısı fazladır
hangi kalp taşıyacak kadar ustadır aşk ağrısını
kentli yalnızlıklardır çoğaldıkça kaybolan
ritminin yarısı senin olsun
bilerek unuttuğum bu şarkının
reddettim bütün kabullerimi
bir kez daha kutsadım kendimi
anladım hiç bir aşta yer yok bana
beklediğim yağmurdan da ümit kalmamıştır', 'aklına kuşkonmaz bir yolcuyum yasak hevesler büyür içimde sağanaklara tutulur çalarım zamanı kediler yarışır aşkın atlasında kuşlar kalkıyor...', ARRAY['Türk Edebiyatı','Şiir','Bayram Balci']::text[], 8.5, '{"poet":"Bayram Balci","poet_slug":"bayram_balci","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YERDELİ', 'yerdeli-cengiz-bektas-jq2fe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Azra Erhat için-
Sığamadım gözümün yettiğine
Yerdeli gökdeli estim estim
Derelerden anacığım
Derelerden taştım
Dardım gürdüm koyaklarda köpük köpük
Düze geldim anacığım
Sevgini sevgini buldum yundum', '-Azra Erhat için- Sığamadım gözümün yettiğine Yerdeli gökdeli estim estim Derelerden anacığım Derelerden taştım Dardım gürdüm koyaklarda köp...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Bektaş']::text[], 8.5, '{"poet":"Cengiz Bektaş","poet_slug":"cengiz_bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YERÇEKİMLİ KARANFİL', 'yerceki-mli-karanfi-l-edip-cansever-fsufb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyor musun az az yaşıyorsun içimde
Oysaki seninle güzel olmak var
Örneğin rakı içiyoruz, içimize bir karanfil düşüyor gibi
Bir ağaç işliyor tıkır tıkır yanımızda
Midemdi aklımdı şu kadarcık kalıyor.
Sen o karanfile eğilimlisin, alıp sana veriyorum işte
Sen de bir başkasına veriyorsun daha güzel
O başkası yok mu bir yanındakine veriyor
Derken karanfil elden ele.
Görüyorsun ya bir sevdayı büyütüyoruz seninle
Sana değiniyorum, sana ısınıyorum, bu o değil
Bak nasıl, beyaza keser gibisine yedi renk
Birleşiyoruz sessizce.', 'Biliyor musun az az yaşıyorsun içimde Oysaki seninle güzel olmak var Örneğin rakı içiyoruz, içimize bir karanfil düşüyor gibi Bir ağaç işliy...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip_cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YERYÜZÜ AĞACI', 'yeryuzu-agaci-arkadas-zekai-ozger-yj6md', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kış geliyor
elim yaprak altında
es ey bad-ı semen
çatlak bedenime çarp kalbimi harmanla
gencelmiş tarih kabartmalarının haklılığı aşkına
beni kendime gebe bırak
kış geliyor
otobüs ne kalabalık
yaslan bana yeryüzü ağacı
dikili gövdenin üretkenliği için
çıldırtan bir gübre mi arıyorsun
kökünü toprağımda dene
kış geliyor
koru gövdemi pardösüm
ağzıma konacak kışlarım nerde
tutsana elimi canikom tarih tekerrürden ibaretmiş
Miş bir geçmiş zaman failiymiş
ey beşeriyet beni beş iftarda öp
şair olmak kolay değil yavrum
uzvun o kadar güzelken
bir yanda yaş ağaca balta vuran çokluk
bir yanda kanımı azdıran bokluk
beni artık hücre çoğaltmaktan da yargılarlar
zahir', 'Kış geliyor elim yaprak altında es ey bad-ı semen çatlak bedenime çarp kalbimi harmanla gencelmiş tarih kabartmalarının haklılığı aşkına ben...', ARRAY['Türk Edebiyatı','Şiir','Arkadaş Zekai Özger']::text[], 8.5, '{"poet":"Arkadaş Zekai Özger","poet_slug":"arkadas_zekai_ozger","theme":"Türk Şiiri","is_hero":false,"total_lines":26}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YERYÜZÜ AŞKIN YÜZÜ OLUNCAYA DEK', 'yeryuzu-askin-yuzu-oluncaya-dek-adnan-yucel-o9ln0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir inancın yüceliğinde buldum seni
bir kavganın güzelliğinde sevdim.
bitmedi daha sürüyor o kavga
ve sürecek
yeryüzü aşkın yüzü oluncaya dek! Aşk demişti yaşamın bütün ustaları
aşk ile sevmek bir güzelliği
ve dövüşebilmek o güzellik uğruna.
işte yüzünde badem çiçekleri
saçlarında gülen toprak ve ilkbahar.
sen misin seni sevdiğim o kavga,
sen o kavganın güzelliği misin yoksa... Bir inancın yüceliğinde buldum seni
bir kavganın güzelliğinde sevdim.
bin kez budadılar körpe dallarımızı
bin kez kırdılar.
yine çiçekteyiz işte yine meyvedeyiz
bin kez korkuya boğdular zamanı
bin kez ölümlediler
yine doğumdayız işte, yine sevinçteyiz.
bitmedi daha sürüyor o kavga
ve sürecek
yeryüzü aşkın yüzü oluncaya dek! Geçtiğimiz o ilk nehirlerden beri
suyun ayakları olmuştur ayaklarımız
ellerimiz, taşın ve toprağın elleri.
yağmura susamış sabahlarda çoğalırdık
törenlerle dikilirdik burçlarınıza.
türküler söylerdik hep aynı telden
aynı sesten, aynı yürekten
dağlara biz verirdik morluğunu,
henüz böyle yağmalanmamıştı gençliğimiz... Ne gün batışı ölümlerin üzüncüne
ne tan atışı doğumların sevincine
ey bir elinde mezarcılar yaratan,
bir elinde ebeler koşturan doğa
bu seslenişimiz yalnızca sana
yaşamasına yaşıyoruz ya güzelliğini
bitmedi daha sürüyor o kavga
ve sürecek
yeryüzü aşkın yüzü oluncaya dek! Saraylar saltanatlar çöker
kan susar birgün
zulüm biter.
menekşelerde açılır üstümüzde
leylaklarda güler.
bugünlerden geriye,
bir yarına gidenler kalır
bir de yarınlar için direnenler... Şiirler doğacak kıvamda yine
duygular yeniden yağacak kıvamda.
ve yürek,
imgelerin en ulaşılmaz doruğunda.
ey herşey bitti diyenler
korkunun sofrasında yılgınlık yiyenler.
ne kırlarda direnen çiçekler
ne kentlerde devleşen öfkeler
henüz elveda demediler.
bitmedi daha sürüyor o kavga
ve sürecek
yeryüzü aşkın yüzü oluncaya dek!', 'bir inancın yüceliğinde buldum seni bir kavganın güzelliğinde sevdim. bitmedi daha sürüyor o kavga ve sürecek yeryüzü aşkın yüzü oluncaya de...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":57}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YERYÜZÜ ŞARKISI', 'yeryuzu-sarkisi-konstantin-biebl-duow7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göklerin ayı,
Aramızdaki anlaşmayı unutma.
O kadar eğilmen doğru değil bence
Saklanmak ister gibi
Ermiş Ludmilla''nın eteği arkasına.
Gidecek öyle kısa yolun kaldı ki
Vinodrady''ye.
İyi düşün.
Önce kilisenin damından in,
Sonra su borularından.
Her yerde savaş var.
İşte Prag, altı aydır bekleyen bir saatli bomba,
İşte Pankrac, acılarımızın Bastille''i.
Ya Terezin?
Bir şair ölüyor orada,
Kurtulmuş Fransa''nın en güzel oğlu,
Robert Desnos,
Aşkı gibi gözleri var.
Meleksi iki yürek gibi gözleri var,
Meleksi iki yürek gibi gözleri var saydam safranlarda,
Saydam safranlarda gözlerin en saydamı.
Konstantin BIEBL', 'Göklerin ayı, Aramızdaki anlaşmayı unutma. O kadar eğilmen doğru değil bence Saklanmak ister gibi Ermiş Ludmilla''nın eteği arkasına. Gidecek...', ARRAY['Türk Edebiyatı','Şiir','Konstantin Biebl']::text[], 8.5, '{"poet":"Konstantin Biebl","poet_slug":"konstantin_biebl","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YERYÜZÜ', 'yeryuzu-i-lhan-berk-z0r24', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Ne yapıyorsun?
Yeryüzünün yaşına çalışıyorum.
Taşbaskısı', '-Ne yapıyorsun? Yeryüzünün yaşına çalışıyorum. Taşbaskısı...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":5}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YETMİŞ İKİNCİ SONNET', 'yetmi-s-i-ki-nci-sonnet-hasan-i-zzetti-n-di-namo-1c367', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen bir dişisin, doğa gibi güçlü bir dişi
Ne güzel okşar insanı ekmek dağıtan ellerin.
Pembe gül yaprağı tırnakların, apak fildişi
Parmakların altında soluk alır sevinç derin derin.
Ardında günlük yemek kokusunu, çay fincanlarının
Yeni tanımış bir durumun var eski bir düşü.
Yeşil çimenlerinde uzanmak için aşk anlarının
İster bir kez daha şiirle gerçeğin dövüşü.
Duyarım seni kovaladığım teke kokusunun
Her gün Pan gibi hırsla meşe ormanında
Aşk çağlar etlerinin gümüş dumanında...
Bir gölgelik kır çiçeklerinin beneklediği
Kalbimin küt küt atarak seni beklediği
Bu yerlere kaçarak gel bir akşamüstü olsun.', 'Sen bir dişisin, doğa gibi güçlü bir dişi Ne güzel okşar insanı ekmek dağıtan ellerin. Pembe gül yaprağı tırnakların, apak fildişi Parmaklar...', ARRAY['Türk Edebiyatı','Şiir','Hasan İzzetti̇n Di̇namo']::text[], 8.5, '{"poet":"Hasan İzzetti̇n Di̇namo","poet_slug":"hasan_izzettin_dinamo","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YETİŞİR', 'yeti-si-r-ziya-osman-saba-qbmkt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beni hatırladıkça,
Arasıra gönlümü al.
Sokakta görünce,gülümse,
Yanıma yaklaş,
Az elin elimde kal.
Evine misafir geleyim,
Kahvemi sen pişir.
Taze doldurulmuş sürahiden
Bir bardak su ver
Yetişir...', 'Beni hatırladıkça, Arasıra gönlümü al. Sokakta görünce,gülümse, Yanıma yaklaş, Az elin elimde kal. Evine misafir geleyim, Kahvemi sen pişir....', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya_osman_saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YIKANMA', 'yikanma-rifat-ilgaz-ioss3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Leğene girdi mi Mine
Kendini ördek sanır
Annesi verir süngeri eline
Hiç ağlamadan yıkanır.
Her yıkanışında Mine
Biraz daha küçülür leğen
Leğen mi küçülür dersiniz
Yoksa Mine mi büyür?', 'Leğene girdi mi Mine Kendini ördek sanır Annesi verir süngeri eline Hiç ağlamadan yıkanır. Her yıkanışında Mine Biraz daha küçülür leğen Leğ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Ilgaz']::text[], 8.5, '{"poet":"Rıfat Ilgaz","poet_slug":"rifat_ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YIKIM', 'yikim-miroslav-holub-47hd1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hurdahaş olmuş parmaklar getiriyorlar bize,
onları iyileştir, doktor.
Millenmiş gözler getiriyorlar,
yüreklerin avlanmış baykuşları,
yüzlerce beyaz beden,
yüzlerce kanlı beden,
yüzlerce kömürleşmiş beden getiriyorlar,
iyileştir onları, doktor,
ambulanslar dolusu getiriyorlar,
kanın çılgınlığını,
etin haykırışını
sessizliğin yanıp kül olmuşunu,
iyileştir onları, doktor.
Ve sararken yaraları
karış karış,
gecelerce,
siniri sinire,
kası kasa birleştirirken,
gözün görmesini sağlarken,
daha uzun hançerler,
daha güçlü bombalar,
getiriyorlar,
daha görkemli utkular kazanıyorlar,
salaklar.
Türkçesi: Sabri Koç', 'Hurdahaş olmuş parmaklar getiriyorlar bize, onları iyileştir, doktor. Millenmiş gözler getiriyorlar, yüreklerin avlanmış baykuşları, yüzlerc...', ARRAY['Türk Edebiyatı','Şiir','Miroslav Holub']::text[], 8.5, '{"poet":"Miroslav Holub","poet_slug":"miroslav_holub","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YILDIZ', 'yildiz-melih-cevdet-anday-7cw64', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evren esrisin diye gövdende
Tuttum elinle bir dünya dokudum
Savatlı ayı taktım bileğine
Bak yaz kıyısından limon çiçeği
Yüklü kızarık gece yükseliyor
Köpeklerin uyuduğu bahçemize
Minderlerimizi ansı, nerdeyse
Doğar o anasonlu yıldız
Kırılmış dağın balkonundan.
Uzanalım, kavağın ve beynimin
Kum saatlarını duyuyor musun
Tenle karışıyor, sürgünlerinle.
Kaktüs bana bir ağıt söyle.', 'Evren esrisin diye gövdende Tuttum elinle bir dünya dokudum Savatlı ayı taktım bileğine Bak yaz kıyısından limon çiçeği Yüklü kızarık gece y...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih_cevdet_anday","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YILDIZLAR', 'yildizlar-oktay-ri-fat-tbkvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kitabın yanında defter
Defterin yanında bardak
Bardağın yanında çocuk
Çocuğun yanında kedi
Ve uzakta yıldızlar yıldızlar', 'Kitabın yanında defter Defterin yanında bardak Bardağın yanında çocuk Çocuğun yanında kedi Ve uzakta yıldızlar yıldızlar...', ARRAY['Türk Edebiyatı','Şiir','Oktay Ri̇fat']::text[], 8.5, '{"poet":"Oktay Ri̇fat","poet_slug":"oktay_rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YILDIZLARDA UYKU', 'yildizlarda-uyku-behcet-necati-gi-l-jidyz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şehre çöken karanlık
Sokakta bir adam gördü.
Kattı adamı önüne
Evine götürdü.
Adam dinlendi biraz,
Sofraya oturdu.
Yemeklerini yediler,
Annesi çocuğu yatırdı.
Şehre çöken karanlık
Her gece başucunda
Yalnız korkan çocuğa
Masallar anlatırdı.
O gece garip bir şey oldu:
Karanlık uzandı göğe,
Gökten bir yıldız aldı,
Odaya getirdi.
Boşlukta dönen yıldız
Işık ışık bölündü.
Renkli maytaplar gibi
Çocuğun üstüne döküldü.
Çocuk hemen uyudu
Uykusunda güldü.', 'Şehre çöken karanlık Sokakta bir adam gördü. Kattı adamı önüne Evine götürdü. Adam dinlendi biraz, Sofraya oturdu. Yemeklerini yediler, Anne...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necati̇gi̇l']::text[], 8.5, '{"poet":"Behçet Necati̇gi̇l","poet_slug":"behcet_necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":24}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YILDIZLARDAN SÖZ AÇAN GERÇEKÇİ ŞİİR', 'yildizlardan-soz-acan-gercekci-si-i-r-kemal-ozer-pkogr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Balkona çıktığımda, gecenin bu saatinde,
gözüme ilişen ilk yıldıza bakarken
aynı anda aynı yıldıza dünyanın bir yerinde
birinin daha baktığı geçerdi içimden.
Bir yıldızda buluşması gözlerimizin
yeterdi bana, daha ötesini istemezdim;
hangi kaygılar var yüreğinde, hangi düşüncenin
rüzgârıyla alevleniyor alnı, şimdi hepsini bilmeliyim.', 'Balkona çıktığımda, gecenin bu saatinde, gözüme ilişen ilk yıldıza bakarken aynı anda aynı yıldıza dünyanın bir yerinde birinin daha baktığı...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YILDIZLARIN ALTINDAKİ KAĞNI', 'yildizlarin-altindaki-kagni-valeri-petrov-89cgf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki köhne bıçkıhane dağın orda.
İner eski Bukova yolu köye doğru.
Gecenin içinde gıcırdar durur
tahta yüklü yedi kağnı.
Arkada, karanlıkta, yan yana,
ilkokul öğretmeniyle arabacı,
yol alırken tütün içer laflarlar,
seyrederek evreni, yıldızları.
"İnanasım gelmez benim sen ne desen,
Samanyolu yıldızlardan nasıl olur.
Tanrıdır rüzgâr estiğinde gökyüzüne biçim veren.
O saat has buğdayın ince çiçeği savrulur."
Susar öğretmen, dinleyerek
yaşlı adamın dediklerini bir bir,
ve tahtalara uzanmış dalar
binlerce yıldıza.
Hep aynı ezgiyi söyler tekerlekler tek düze,
bir rüzgâr eser Balkanlardan, savruk, kaygılı,
ve taşır gecenin içinde reçine ve ot
ve taze tahta ve tütün ve katran kokusu.
Karaltılar içinde her şey bir güzel:
Balkanlar ve kağnı, insanlar ve tahtalar.
Ağır ağır yürüyen mandalar kapkara,
ve gözlerini mavisi ışıl ışıl.
Valeri  PETROV', 'İki köhne bıçkıhane dağın orda. İner eski Bukova yolu köye doğru. Gecenin içinde gıcırdar durur tahta yüklü yedi kağnı. Arkada, karanlıkta, ...', ARRAY['Türk Edebiyatı','Şiir','Valeri  Petrov']::text[], 8.5, '{"poet":"Valeri  Petrov","poet_slug":"valeri_petrov","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YILLAR GEÇİYOR', 'yillar-geci-yor-mihail-eminescu-wlgaj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar geçiyor -ovaların üzerinde upuzun bulutlar-
Ama artık bir daha geri dönmüyorlar.
Artık avutmuyor beni eskiden başımı döndüren ne varsa:
Masallar, çalgılar, oyunlar, boş inançlar.
Çocuk alnıma dinginlik armağanı getiren şeyler.
Anlamakta güçlük çekiyorum, oysa apaçık anlamları.
Bugün boş yere sarıyorsun beni gölgelerinle.
Gizemlerin saati, günün veda saati.
Hayatın geçmişinden bir ses koparmak isterdim,
Tekrar titreyesin diye sen, ruhum, onu duyunca.
Elim dolaşıp duruyor boş yere lirin telleri üzerinde.
Her şey yitip gitti gençliğin ufkunun arkasında
Ama tek sözcük çıkmıyor zamanın güzel ağzından!
Saatler, günler, aylar,yıllar yığılıyor arkamda.
Bense gittikçe gömülüyorum dipsiz karanlıklara.
Mihail EMINESCU', 'Yıllar geçiyor -ovaların üzerinde upuzun bulutlar- Ama artık bir daha geri dönmüyorlar. Artık avutmuyor beni eskiden başımı döndüren ne vars...', ARRAY['Türk Edebiyatı','Şiir','Mihail Eminescu']::text[], 8.5, '{"poet":"Mihail Eminescu","poet_slug":"mihail_eminescu","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖYKÜ', 'oyku-mehmet-basaran-hh16s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıl kırk yediydi sonbahardı
Üstümde başka gök başka bulut
Cebimde param vardı
Tramvaylar taksiler emrime hazır
Durağım İstanbullar Ankaralardı
Yıl kırk yediydi sonbahardı
Demiri büken ellerim
Üzüm gibi saçım vardı
Bir güzel geçse sokaktan
İçim aşkla dolardı
Yıl kırk sekiz mevsim sonbahar
Ankara''nın taşına bak
Neden böyle gözlerim dolar
Neydim n''oldum n''olacağım
Şu feleğin işine bak', 'Yıl kırk yediydi sonbahardı Üstümde başka gök başka bulut Cebimde param vardı Tramvaylar taksiler emrime hazır Durağım İstanbullar Ankaralar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞÖYLE GARİP BENCİLEYİN', 'soyle-gari-p-benci-leyi-n-yunus-emre-9n3o5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acep şu yerde varm''ola
Şöyle garip bencileyin
Bağrı başlı gözü yaşlı
Şöyle garip bencileyin
Gezdim Rum ile Şam''ı
Yukarı illeri kamu
Çok istedim bulamadım
Şöyle garip bencileyin
Kimseler garip olmasın
Hasret oduna yanmasın
Hocam kimseler duymasın
Şöyle garip bencileyin
Söyler dilim ağlar gözüm
Gariplere göynür özüm
Meğer ki gökte yıldızım
Şöyle garip bencileyin
Nice bu dert ile yanam
Ecel ere bir gün ölem
Meğer ki sinimde bulam
Şöyle garip bencileyin
Bir garip ölmüş diyeler
Üç günden sonra duyalar
Soğuk su ile yuyalar
Şöyle garip bencileyin
Hey Emre''m Yunus biçare
Bulunmaz derdine çare
Var imdi gez şardan şara
Şöyle garip bencileyin', 'Acep şu yerde varm''ola Şöyle garip bencileyin Bağrı başlı gözü yaşlı Şöyle garip bencileyin Gezdim Rum ile Şam''ı Yukarı illeri kamu Çok iste...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖYLE GÜNLER GÖRDÜM Kİ', 'oyle-gunler-gordum-ki-sabahattin-ali-ttpfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle günler gördüm ki, aydın gökler kararıp
Bahtım bir bulut gibi üstüme çöker oldu,
Her gözümü yumunca tanıdık yüzler görüp,
Hayaller alev alev beynimi yakar oldu.
Ümitsizlik, gariplik dört tarafımı sarıp
Yüzüm sırıtsa bile, içim yaş döker oldu.
Her sabah ilk ışıklar gözlerimi oyardı,
Uyanan taş duvarlar iniltimi duyardı.
Öyle günler gördüm ki, duvarlar gelir dile,
Gözümde canlanırdı eşkiya masalları.
Varlığımı sarardı, hain bir isteyişle
Görmediğim yumuşak bir düşmanın elleri
Kafada çelik gibi fikirler dursa bile
Kalplerin eksik olmaz böyle zayıf halleri:
Bazen kendi kendimin elinden kurtulurdum,
Kalbimi bir çamurda çırpınırken bulurdum.
Öyle günler gördüm ki, dost dediğim insanlar
Ben yanına varınca dudağını kıvırdı.
Bir zamanlar yanımda ağız açmayanlar
Sırtımı sıvazladı, bana öğüt savurdu.
Silahsız gördüğüne saldıran kahramanlar
En alçak tekmelerle beni yere devirdi.
Ruhum bir heykel gibi düşüp parçalanırdı.
Bu sesleri duyanlar gülüyorum sanırdı.
Öyle günler gördüm ki, tabanca sakağımda
Tasarladım aydınlık dünyayı bırakmayı
Gönlüm acıklı buldu, en ateşli çağımda
Sönük bir yıldız gibi boşluklara akmayı
Tabancanın namlusu ısındı yanağımda,
Parmağım istemedi tetiğini çekmeyi
Bir sonbahar yağmuru gibi içim ağlardı
Bir şeyler fakat beni yaşamağa bağlardı.
Ey bir tane sevgilim, ben bugün yaşıyorsam
Sanma ki hayat tatlı, insanlar hoş olmuştur,
Dağ başında bir kaya gibiyim şöyle dursam
Etrafım eskisinden daha bomboş olmuştur
Yalnız sana borçluyum bugün dünyada varsam:
Seni her andığımda gözlerim yaş olmuştur
Yaşlar ki bir ırmaktır, dertleri sürür gider,
Gözyaşları içinde seneler yürür gider.
Yok olmak isteğiyle kalbim attığı zaman,
Bana: Yaşa der gibi gülen senin yüzündü.
Dizlerim bir batakta yorgun yattığı zaman
Bacaklarıma kuvvet veren senin hızındı.
Yaşaran gözlerimde, güneş battığı zaman
Sıcak bir yuva gibi tüten senin dizindi.
Sen aklıma gelince her şey gülümserdi.
Ağaçlar şarkı söyler, rüzgar tatlı eserdi.
Ey sevgilim, bilirsin benim ne çektiğimi:
Garip başımın derdi bir yürek taşıyorum.
Anlarsın niçin uzak yerlere baktığımı:
İçinde yaşanmaz bir dünyada yaşıyorum.
Görünce gülme sakın çırpınıp aktığımı:
Ilık ve aydınlık bir denize koşuyorum.
Sen benim sevgilimsin, sevsen de, sevmesen de,
Aradığım yerlere benzeyiş buldum sende.', 'Öyle günler gördüm ki, aydın gökler kararıp Bahtım bir bulut gibi üstüme çöker oldu, Her gözümü yumunca tanıdık yüzler görüp, Hayaller alev ...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali̇']::text[], 8.5, '{"poet":"Sabahattin Ali̇","poet_slug":"sabahattin_ali","theme":"Türk Şiiri","is_hero":false,"total_lines":58}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖYLEDİR ÖYLE BAŞLAR', 'oyledi-r-oyle-baslar-boris-pasternak-tfwa4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan iki yaşında da öyle başlar işte
Ezgilerin karanlığına sıyrılır kucaklardan,
Cıvıl cıvıl cıvıldar, mırıldar bir süre,
Derken, üçüne doğru, sözler dökülür ağzından.
Öyledir işte, yavaşça başlarsın anlamaya,
Kapılıp bir türbinin büyük gürültüsüne,
Sen misin bu, bir başkası mı yoksa,
Yabancılaşmıştır evin, bir gölgedir annen de
Bu zalim leylâk parıltısının nedir derdi?
bu dökülen, bu inen bir park kanepesine,
Nedir? çocukları kaçırmak gibi bir şey mi?
Öyledir işte, kuşlar öyle doluşur içine.
Arttıkça artan kıvamını bulan acılardan:
Yüreğinde ulaşılamayanın özlemi, uzak yıldızlar,
Faust gibi olduğun, kafan bulandığı zaman
Öyledir, öyle başlar çingene çalgıcılar.
Uçaraktan yüce yüce gök katlarından
Çevrili alanlar görürsün, evsiz topraklar,
ve denizler bir iççekiş kadar ansızın,
İşte tıpkı öyle doğar heceler ve uyaklar.
Yulafların üstünde, sırtüstü,yaz geceleri,
yakarır durur: her şey yerini alsın diye,
Sakınarak gözünden şafağı ve evreni
Öyle olacaktır, öyledir dalaşımız güneşle.
Öyledir, öyle başlar yaşamak, dizelerle.
Boris PASTERNAK', 'İnsan iki yaşında da öyle başlar işte Ezgilerin karanlığına sıyrılır kucaklardan, Cıvıl cıvıl cıvıldar, mırıldar bir süre, Derken, üçüne doğ...', ARRAY['Türk Edebiyatı','Şiir','Boris Pasternak']::text[], 8.5, '{"poet":"Boris Pasternak","poet_slug":"boris_pasternak","theme":"Türk Şiiri","is_hero":false,"total_lines":28}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖYLESİNE BİR AŞK ŞİİRİ', 'oylesi-ne-bi-r-ask-si-i-ri-attila-asut-hw8f6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Örselenmiş bir yürekle
Çıkıyorum günbatımı
Acının gökdelenine.
Ölülerimiz çoğalıyor yine
Sokaklar kan revan
Canhıraş kuşlar konuyor hüznümüzün antenine.
Yol alırken bu limandan
Sevi yüklü gemimizin
Rüzgâr dolsun yelkenine.
Gazeteci arkadaş
Yetiştir bu acıyı
Ana haber bültenine.
Dışarıda kirletilmiş bir bahar
Yüzümde devedikenleri
Binmeliyim şiirin mavi trenine.
Ey ozan,
Bu ne biçim aşk şiiri
Gir artık izleğin gezegenine!
Önümüzü haramiler kesmişti.
Şiirin engebeli yolundan
Daldık aşkın bedestenine.
İçimin ormanında
Tutuştu karanfiller
Gözlerim değince tenine.
Ne Novalgin, ne Cafergot
Sevgili göğsümdür benim
İyi gelen migrenine.
Yazdım işte bu şiiri
Öylesine bir aşk için
Ayten''ine, Gülten''ine.
Mutlu bitsin masalımız
Onlar ermiş muradına
Biz çıkalım kerevetine.
Ankara, Ağustos 1992', 'Örselenmiş bir yürekle Çıkıyorum günbatımı Acının gökdelenine. Ölülerimiz çoğalıyor yine Sokaklar kan revan Canhıraş kuşlar konuyor hüznümüz...', ARRAY['Türk Edebiyatı','Şiir','Attila Aşut']::text[], 8.5, '{"poet":"Attila Aşut","poet_slug":"attila_asut","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖYLESİNE', 'oylesi-ne-tulay-yener-zcbo2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkın en sesli harfine basıyorsun çocuk
çook sığmadı kalbim cepkenine
kelebekler avucumda ancak uyudum
falından koparılmış kaç yaprağım şimdi
martılar çığlıklarını dökerken denize,
şemsiyesizdim;
sağanaklara tutuldum
uçardı sözler, boş kalırdı yerleri
uzanırdı bir kuytu ayaklarıma.
dizelerle kundaklanmış yangında
ağırlaşan yaprak, düşen kurşundu tenime
sen, öylesine yaşıyordun ki beni
ben böylesine ölüyordum', 'Aşkın en sesli harfine basıyorsun çocuk çook sığmadı kalbim cepkenine kelebekler avucumda ancak uyudum falından koparılmış kaç yaprağım şimd...', ARRAY['Türk Edebiyatı','Şiir','Tülay Yener']::text[], 8.5, '{"poet":"Tülay Yener","poet_slug":"tulay_yener","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İYİMSER BİR GÜL', 'i-yi-mser-bi-r-gul-yusuf-hayaloglu-uh9n6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyandım, seni düşündüm
Birdenbire duvar
Birdenbire gece yarısı
Sonra devriye parolası
Ve rüzgar
Ve birdenbire kalp ağrısı...
Uyandım, seni düşündüm
Ey yar
Ey göğsümün sol yarısı!
Su bulanınca
Meydanlarda sesin yırtılınca
Hiç dostun kalmayınca
Sarsılmış bir ömrün
Basamaklarında
Görüşüme gel ne olur
İyimser bir gül olsun
Dudaklarında...
Dert etme, iyiyim ben
Ara sıra mahşer
Ara sıra yaşama hırsı...
Sonra mazgal altı zulası
Ve mektuplar
Ve ara sıra hasret belası...
Dert etme, iyiyim ben
Ey yar
Ey hüznümün tütün sarısı...
Kan bulaşınca
Yangınlarda yüzün harlaşınca
Saçların tutuşunca
Zorlanmış bir hükmün
Tutanaklarından
Görüşüme gel ne olur
İyimser bir gül açsın
Yanaklarımda...', 'Uyandım, seni düşündüm Birdenbire duvar Birdenbire gece yarısı Sonra devriye parolası Ve rüzgar Ve birdenbire kalp ağrısı... Uyandım, seni d...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİNE DE GÜLÜMSEYEREK', 'yi-ne-de-gulumseyerek-nihat-behram-prhku', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne sağnaklar görmüşüz, yarılan gökyüzünden alnımız
yıldırımlarla ağmış,
ne rüzgarlar çınlamış bağrımızda, coşkusundan kırılmış
kaburgamız,
dişlenip kayaları ne ateşler yakmışız, aşmışız ne zifir
uçurumlar,
yine de ürkütmeden öpmüşüz bir ceylanı gözlerinin
yaşından
incitmeden tutmuşuz ağzımızda yorulan kelebeği;
şimdi asmalardan korukların tadı silinmiş,
sesimizde sendeleyen bir keder,
uykusuzluk serin serin sızıyor acıyan tenimizden;
ziyanı yok, nasıl olsa gönlümüzde aşkın yeri çok derin.
Ne azgın canavarlar üstüne yürümüşüz bir demet
çiçek için,
neyimiz var neyimiz yok vermişiz bir narin dilek için,
yıllarını taş duvara örmüşüz ömrümüzün bir hırçın
yürek için;
şimdi çevremizde yosunlaşmış sessizlik,
yabanıyız gittiğimiz her şehrin, çiğdemsiz, kükremesiz,
kimsecikler sezmiyor boynumuzdan didişen örümceğin
zehrini;
ziyanı yok, nasıl olsa nabzımızda durulanır yaşamanın
iksiri.
Ne güzel sevmişiz, ağzımızda mavi bir tat kekremiş,
ne sızılar sarmışız yumuşacık öpüşlerin çığlığını kuşanıp,
şafaklar tutuşkunu şarkılar yuvalanıp ne mintanlar yırtmışız,
şimdi usulcacık ürpersek kara gece uykumuz kaçacak
kadar delik
üstümüz çimensiz tepeler gibi bereketsiz, örtüsüz, serin;
ziyanı yok, nasıl olsa gönlümüzün çayırları ipekten,
bakışımız lekesiz.
Ne masalar düzmüşüz kıvrımları gümüş, kakmaları sedeften,
ne milyonlar yanından başeğmeden geçmişiz, huyumuz
değişmemiş,
hayatımız günbegün çarpışarak yaşanılan sırların ürünüdür;
şimdi kar altında avcumuz, avurdumuz ilaçsız,
ıssızlaşmış sabahlar, yoksunluk arsızlaşmış,
kaçışır yolumuzdan gölgesini de alıp o şaklabanlar
inildesek açlıktan;
ziyanı yok, nasıl olsa gönlümüzün dağı taşı altından.
Ne devlerle dalaşmış kanımızı göstermeden silmişiz.
ne kudurgan günlerde elimizi dost eline titremeden vermişiz,
bir ömür seğirtmişiz bir nefes beklemeden;
şimdi nice anışların dudağı üşüyen bir çocuk kadar uçuk,
nicesi elsıkışların sahtekar çıkmış.
- Bizi eşkiyalar soymamış abi
muhabbet yıkmış!', 'Ne sağnaklar görmüşüz, yarılan gökyüzünden alnımız yıldırımlarla ağmış, ne rüzgarlar çınlamış bağrımızda, coşkusundan kırılmış kaburgamız, d...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat_behram","theme":"Türk Şiiri","is_hero":false,"total_lines":50}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİNE YAĞMUR ÜSTÜNE', 'yi-ne-yagmur-ustune-n-zim-hi-kmet-et4k3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Serçe kuşları gibi yağmur
çinko dama serptiğim
ekmek kırıntılarını
telâşlı telâşlı, tıkır tıkır.
serçe kuşları gibi yağmur.', 'Serçe kuşları gibi yağmur çinko dama serptiğim ekmek kırıntılarını telâşlı telâşlı, tıkır tıkır. serçe kuşları gibi yağmur....', ARRAY['Türk Edebiyatı','Şiir','Nâzım Hi̇kmet']::text[], 8.5, '{"poet":"Nâzım Hi̇kmet","poet_slug":"nazim_hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOK', 'yok-aziz-nesi-n-fv3xj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kitabımı sana adamak istedim
Gözlerine baktım
Gözlerin yok
Öpmek istedim
Yüzüne baktım
Yüzün yok
Tutmak istedim elini
Elin yok
Isıt sözlerimi yüreğe işleyen kulakların yok
Anlat bana bişey anlat
Dilin yok
Haydi yanyana yanın yok
Kitabımı sana adamak istedim
Adın yok
Güvercin getirdi şiirimi geriye
Bu dünyada anlattığın kadın yok ....', 'Kitabımı sana adamak istedim Gözlerine baktım Gözlerin yok Öpmek istedim Yüzüne baktım Yüzün yok Tutmak istedim elini Elin yok Isıt sözlerim...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLAMA', 'yoklama-kuvvet-yurdakul-eon5f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Silgiyi öğrenmeden bilmezdim yanlış yapmayı
Her akşam gidecek bir yer
Karalamazdım evin üstüne
Geç oldu baba döndü yemek hazır
Anne öldü
Günün anlam ve önemini açıklamalıyız
Kaçsak müfredat bulur ali gel
Al kalemi giriş geliş bir şeyler yap
Defterime bir sayfa imdat yaz
Koş ali koş beni kandır beni oyala
Böyle ister anneler günü
Bir buket önemi
Bir avuç tehlike arasında
Yanıldım
Derse yağmur yağmadı
Tebeşir geciktirdi okulu
Cetvel istemedim acıkınca
Kuşlar silgi taşımadı
Tam kahraman olacaktım
Önlüğümden tuttular
Ali yaz
Hiç bir ölüm karne vermedi
Bir ömrün ilk yarısına
Elektirikler kesildi
Büyümedim
Herkes gitmek diyor
Numaram 1657
Burdayım', 'Silgiyi öğrenmeden bilmezdim yanlış yapmayı Her akşam gidecek bir yer Karalamazdım evin üstüne Geç oldu baba döndü yemek hazır Anne öldü Gün...', ARRAY['Türk Edebiyatı','Şiir','Kuvvet Yurdakul']::text[], 8.5, '{"poet":"Kuvvet Yurdakul","poet_slug":"kuvvet_yurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUN İKLİMİ', 'yoklugun-i-kli-mi-odisseus-eli-ti-s-pwhjy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'I
Dünyanın bütün bulutları günah çıkardı
Yerlerini tasam doldurdu
Ve saçlarımın içinde üzgün düşüverince
Pişmanlık duymayan elim
Bir acının düğümüne bağlandım.
II
Saat unuttu kendini akşam olurken
Anıdan yoksun
Ağacı sessiz
Denize doğru
Unuttu kendini akşam olurken
Kanat çırpmalardan yoksun
Yüzü kımıltısız
Denize doğru
Akşam olurken
Sevgiden yoksun
Ağzı kararlı
Denize doğru
Ve ben içinde, kendime çektiğim durgunluğun.
III
Öğle sonrası
Ve onun imparator yalnızlığı
Ve rüzgârların sevecenliği
Ve atılgan çekiciliği
Hiçbir şey gelmiyor. Hiçbir şey
gitmiyor.
Bütün alınlar çıplak
Ve duygu yerine bir duru cam.
Odisseus ELİTİS', 'I Dünyanın bütün bulutları günah çıkardı Yerlerini tasam doldurdu Ve saçlarımın içinde üzgün düşüverince Pişmanlık duymayan elim Bir acının ...', ARRAY['Türk Edebiyatı','Şiir','Odisseus Eli̇ti̇s']::text[], 8.5, '{"poet":"Odisseus Eli̇ti̇s","poet_slug":"odisseus_elitis","theme":"Türk Şiiri","is_hero":false,"total_lines":32}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUNDA - I', 'yoklugunda-i-serdar-aydin-q8ogy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eskimişti ay
aşklarda
yokluklar yaşlanmıştı
şaşkın ve acemi
bir anlamını bulabilseydik
ihanetin
çürümezdik...
kör bir deniz
yürürken
Ortodoks kokusu
gövdenin
ayrıntısı doğa kadın
sevgilim
bir anlamını bulabilseydik
yokluğunun
ağlamazdık...
ilkel erilliğin
kara kargaları kara
sözcükler
birleştirici ulaklar
memelerin
kendine batan
yatalak kirpi
gülümsemesi metal
kadın
içine al yalnızlığımı
beni ve sokaklarını
kirli sarı kerhane
yankısıdır yalnızlığın
beden
anlamını yaratan
burgaç
sarmal kıvrım ve
kıyı üzünçlü
dram...', 'eskimişti ay aşklarda yokluklar yaşlanmıştı şaşkın ve acemi bir anlamını bulabilseydik ihanetin çürümezdik... kör bir deniz yürürken Ortodok...', ARRAY['Türk Edebiyatı','Şiir','Serdar  Aydin']::text[], 8.5, '{"poet":"Serdar  Aydin","poet_slug":"serdar_aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUNDA - II', 'yoklugunda-ii-serdar-aydin-vm4wt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'adamlar
yürüyorlar
ve kadınlar
ellerinde yağmur
şövalyeleri aglayan
ürkek kentlerde
aşk
tükenik su...
sessizliğin
susku ovaları
boynunda uzanan
bir tanrının gözbebekleri
dilimin ucunda
kaygan ve ötelenmiş
kadınlığın
beni kapsıyorsun
kadınım,
dilin
hiç açmamış bir sardunya
meditasyon yapan
budha sureti
dilin
bir nice anlam
belleyemediğim
gözlerin
kara ay büyüsü
ağzın
ıtırlı mayıs bahçesi
dudakların
iki gece imi
ve kaygı sözü
memelerin
çılgın yurtsuzluğumun
korkulu anları
çocukluğumun
pamuk helva düşleri
sesin
katledilmiş bir halkın
en kederli ezgisi
susuşun
umarsız ağlaşması tanrıların
sonsuz okyanus çayırlarında
mavi gözyaşı
kadınım
varoluşum
tükeniyoruz...
basit bir ayrıntı
bütün sözcükler boyunca
seni sevdiğim
arsız duygulanışım
ve şiir
kendimi gömdüğüm
sen...sizliğim...', 'adamlar yürüyorlar ve kadınlar ellerinde yağmur şövalyeleri aglayan ürkek kentlerde aşk tükenik su... sessizliğin susku ovaları boynunda uza...', ARRAY['Türk Edebiyatı','Şiir','Serdar  Aydin']::text[], 8.5, '{"poet":"Serdar  Aydin","poet_slug":"serdar_aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":55}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUNDA - III', 'yoklugunda-iii-serdar-aydin-b91sh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '(ses...)
susku
putlarıyla bilinmez
uzun bir soru işareti
aşk
yalnızlığı çoğaltan
aşk
ıssız bir köpek leşi
parmak ucunda
dokunduğum kesik
derin ve derin
acı...
geometrik karmaşa
penceresinde beyazın
ay negatif
ışın solungaçları
titreyen boşluk
intihar
artığı aynalardaki
açmaz...ölü kaltak
konuş
iri gözleri belleğin
bir sözcük
umarsız
bir ses
kanarken
usanç
çiçek açıyor
sensiz gibi
iğrenti
tek kuralı yaşananın
umut-cinnetin apışarasında
düzüşen söz''de benliklerden
arta kalan döl atmığı-umut diyesim
deliriyorum
d.e.l.i.r.i.y.o.r.u.z...
iki sıvısı aşkın
döl ve irin
dilsizliğimin sözcükleri
dağlarda dolaşan ölüm
menekşe kokan
sesleniş; celladım ol ey
sevgili
orospu
hayat; ey aşk
gözlerime işeyen hiç''lik...
sonlamasında an''ın
varsıl bir sözcük
saçların
bir okyanus düşü
özlemin
aksak söylencesi baharın
kana şimdi...', '(ses...) susku putlarıyla bilinmez uzun bir soru işareti aşk yalnızlığı çoğaltan aşk ıssız bir köpek leşi parmak ucunda dokunduğum kesik der...', ARRAY['Türk Edebiyatı','Şiir','Serdar  Aydin']::text[], 8.5, '{"poet":"Serdar  Aydin","poet_slug":"serdar_aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":55}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUNDA - IV', 'yoklugunda-iv-serdar-aydin-1v5ji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(aşk...)
ney
di''li zamanlarda
çürüyen giz
ney''di
uzayan güdümlü ses
kuleleri parçalanan bozkır belki
yüreğim
ney''di aşk belki
sessizliğin...belki
sözcüklerin kangreni
aşk
ritüel düzüşme erki
yalan ve ihanet güncesi
aşk
ney''di
yokluğun gerisine sarkan
pişmanlık..belki acı
kuleleri parçalanan
bozkır...ney''di
söylenemeyen
aşk''tı
kancık bir itin
doğurgan tasarımı
içimde
ağlamak duygusu
boğulan
bir çocuk sesi
unutuş
terörize edilmiş vahşet
duyusal imi aşkın
teorize şiddet...
zaman ölüdür
kaygısı şaşkın dil
çolaktır
kırılır
ses
öfkeye dönüşürken
çağrılı soğuk deniz
mavidir
öl deyince su
saydam buyruk
buzdur
kırılır...aşk
kırgınlıktır...Serdar AYDIN
temmuz-97', '(aşk...) ney di''li zamanlarda çürüyen giz ney''di uzayan güdümlü ses kuleleri parçalanan bozkır belki yüreğim ney''di aşk belki sessizliğin......', ARRAY['Türk Edebiyatı','Şiir','Serdar  Aydin']::text[], 8.5, '{"poet":"Serdar  Aydin","poet_slug":"serdar_aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUNDA - V', 'yoklugunda-v-serdar-aydin-00rps', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(bir aşk için söylem denemesi)
deniz
ölü urganların ucunda
çırpınan
istavrit gözü
deniz ve kadın
ikicil töz...
mecazları acı olan aşk
üreyen cinnet ilmi
içindeyken senin
gördüğüm düşler
gövdenin kapılarında
onulmaz direnişi
kadınlığının
bir başına...
ve aşk sevgilim
umarsız bir tutkudur
diyen sesim
rahminin duvarlarına çarpıp
dağılırken orgazm çöllerinde
kaç günah daha çoğalırdık
kim bilir...
ayrılık
yaldızlı gece
gülümserken
duvara asılı yüzün
kanardı yokluğun
ve aşk sevgilim
umarsız bir tutkudur
diyen sesin
saplanırdı usuma...
anlamıştık
bulut üşümüştü
aşk
umarsız bir tutkuydu
gülümserken
güneş de utanırdı
gittin
içime çöktüm sonra
içime döküldü
bütün kemiklerim
pelte benlik ölü
gök
iki parça
yalnızlık
iki parça
umut
gözlerime inen
kara bir örtü
yokluğun
bir sokak betimi
yalancı bahar ihaneti
yanılmıştım
hadi şimdi
g...i...t...', '(bir aşk için söylem denemesi) deniz ölü urganların ucunda çırpınan istavrit gözü deniz ve kadın ikicil töz... mecazları acı olan aşk üreyen...', ARRAY['Türk Edebiyatı','Şiir','Serdar  Aydin']::text[], 8.5, '{"poet":"Serdar  Aydin","poet_slug":"serdar_aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":57}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKLUĞUNDAKİ SEN', 'yoklugundaki-sen-aziz-nesi-n-vk6j6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine yalnız değilim her zamanki gibi
Bu Uzakdoğu gecesinde yokluğunlayım
Aramızda yirmibeşbin kilometre
Sen kıştasın ben yazdayım
Sen bir yarısında dünyanın
Ben öte yarısındayım
Yine de bırakmıyor ellerimi yokluğun
Daha da bir gönlümcesin
Varlığından bin kat güzel
O yalımsal çıplaklığın yalaz yalaz
Ve en gizlerden konuşurken ellerin
İçimden gelmiyor mektup yazmak demeden
Sevişiyoruz yirmibeşbin kilometreden', 'Yine yalnız değilim her zamanki gibi Bu Uzakdoğu gecesinde yokluğunlayım Aramızda yirmibeşbin kilometre Sen kıştasın ben yazdayım Sen bir ya...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKSULDUK DÜNYAYI SEVDİK', 'yoksulduk-dunyayi-sevdi-k-arif-damar-uj6f5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öyle uzak
Gitgide
Öyle güzelleşti ki
O yüzü hiç görmedim
Hiç yaşamadı belki
Tülin''in yüzündeki
Duru güzellik
Nasıl da benzer
Ben kırgın
Küskünken
Evsiz barksız bir anının
Puslu
Kırık
Yerinden düşmüş camındaki
Güneşsiz bir kış akşamındaki
İnce
Solgun
Esmer
Nasıl da benzer
Ben kırgın
Küskünken
Kimselere görünmeden
Dönüp dönüp baktığım
Saksılara
Deniz kabuklarına
Kitap yapraklarına bıraktığım
Ama zor
Ama kolay
Tavanda bir yarım ay
Nasıl da benzer
İnce
Solgun
Esmer
Ben kırgın
Küskünken
Evsiz barksız bir anının
Puslu
Kırık
Yerinden düşmüş camındaki
Güneşsiz bir kış akşamındaki
Tülin''in yüzündeki
Duru güzellik
Ama zor
Ama kolay
Yoksulduk
Dünyayı sevdik
Tavanda bir yarım ay', 'Öyle uzak Gitgide Öyle güzelleşti ki O yüzü hiç görmedim Hiç yaşamadı belki Tülin''in yüzündeki Duru güzellik Nasıl da benzer Ben kırgın Küsk...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":49}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKSULLARIN ÖLÜMÜ', 'yoksullarin-olumu-charles-baudelaire-ynedi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ölüm, avutan da -ne çare ki- yaşatan da;
Hayatın sonu; yine de tek ümit, tek güven;
Bizi bir iksir gibi kavrayan, sarhoş eden;
Karda kışta, boralar, tipiler arasında.
Akşamlara kadar didinmek gücünü veren;
Parıldayan tek ışık, kapkaranlık dünyada;
Dört kitabın yazdığı o koskocaman handa
Mümkün artık doyup, dinlenip uyuyabilmen.
Sihirli parmaklarla, üstüne titreyerek,
Uykuların en güzelini getiren melek;
Yoksulun, çıplağın yatağını yapan eller.
Tılsımlı ambar; tanrıların şerefi, şanı;
Yoksulun dağarcığı ve en eski vatanı;
Bilinmedik göklere açılan tâk-ı zafer.
Charles  BAUDELAIRE', 'Ölüm, avutan da -ne çare ki- yaşatan da; Hayatın sonu; yine de tek ümit, tek güven; Bizi bir iksir gibi kavrayan, sarhoş eden; Karda kışta, ...', ARRAY['Türk Edebiyatı','Şiir','Charles  Baudelaire']::text[], 8.5, '{"poet":"Charles  Baudelaire","poet_slug":"charles_baudelaire","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKTUR GÖLGESİ TÜRKİYE''DE', 'yoktur-golgesi-turki-ye-de-sezai-karakoc-ojwc4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabahları gün doğmadan uyanır
Dilini yutacak olur içi kanlanır
Gün boyu çalışır aydınlanır
Kederini anlarsanız size ne mutlu
Acır fakir çalışan kadınlara
Titrer bir gönül kıracak diye hanım dizi
İncedir billurdandır yoktur gölgesi Türkiye''de
Bir meçhul Meryem mermerden değil ama kutlu
Gözlerine baksanız erirsiniz kar gibi
Elinizi sallasanız rüzgârından sallanır
Bir geyik olur sizi arar melûl ve bakır
Görür gibi uyur konuşur gibi susar güler ağlar gibi', 'Sabahları gün doğmadan uyanır Dilini yutacak olur içi kanlanır Gün boyu çalışır aydınlanır Kederini anlarsanız size ne mutlu Acır fakir çalı...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai_karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOKUŞ', 'yokus-volkan-i-pek-wi47j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Salmışsın kendini,
Ömrünün son yokuşundan aşağı,
Yapma diyenler en geride,
Yerlere kapaklanmışlar…
İnsanın kuş hali bu olsa gerek,
Bir yokuştan aşağı unutmak ayaklarını…
Unutmak geçmişteki nasihatleri…
Acı tebessümleri,
Haydarpaşa’dan el sallamaları,
Kutlamayı bıraktığın doğum günlerini,
Giderek büyüyen burnunu,
Her kavgada evi terk etmeyi düşündüğün ergenliğini…
Hepsini unutmak…
Hepsini Beyazıt’ta sergiye yatırmak…
Uçuyorsun var mı ötesi,
Ölüyorsun,
var mı kuşların kefeni?', 'Salmışsın kendini, Ömrünün son yokuşundan aşağı, Yapma diyenler en geride, Yerlere kapaklanmışlar… İnsanın kuş hali bu olsa gerek, Bir yokuş...', ARRAY['Türk Edebiyatı','Şiir','Volkan İpek']::text[], 8.5, '{"poet":"Volkan İpek","poet_slug":"volkan_ipek","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL AYRIMINDA', 'yol-ayriminda-ayten-mutlu-ra3l2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hüzün ikizidir aşkın
birlikte otururlar yol ortasında
ah serkeş güzelliği elmas sevişmelerin
çağırmasın beni artık çılgın krallığına
diş izi çoğaldıkça bitiyor elma
kayalık dalgalarınla dinle beni
deniz çıplak uzanır tuzun beyazlığına
sen kendi düşlerinden asıldın mı hiç
yeni bir çığlık öğret yanıtlarına
hüzün derindeki izidir aşkın
birlikte susarlar yol ayrımında', 'hüzün ikizidir aşkın birlikte otururlar yol ortasında ah serkeş güzelliği elmas sevişmelerin çağırmasın beni artık çılgın krallığına diş izi...', ARRAY['Türk Edebiyatı','Şiir','Ayten Mutlu']::text[], 8.5, '{"poet":"Ayten Mutlu","poet_slug":"ayten_mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL BOYUNCA', 'yol-boyunca-halim-yagcioglu-ylsnd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koparabilir misin bana yıldızlardan
Avuçlayabilir misin karanlığı
Sen ki milyonlar içindesin
Neden kalbinin yalnızlığı
Bulabilir misin bana dost dost dost
Ki sevsin seni karşılık beklemeden
Buz üstünde yazılır mı çocuğum
Düşündün mü deniz dikiş tutmaz neden
Düşündün mü gecelerde ne var
Böyle insanı ürperten
Sanır mısın ruhsuz bu karanlıklar
Ölüm sükûnuyla yürüyen
Tutabilir misin geçen zamanı
Dönebilir misin on beşine
Şaşmadın mı hiç çocuğum
Baharın sessizce gelişine
Kim sürdü gözlerine maviyi
Ki denizleri hatırlatır
Hiç dönen var mı öteden
Sır.', 'Koparabilir misin bana yıldızlardan Avuçlayabilir misin karanlığı Sen ki milyonlar içindesin Neden kalbinin yalnızlığı Bulabilir misin bana ...', ARRAY['Türk Edebiyatı','Şiir','Halim Yağcioğlu']::text[], 8.5, '{"poet":"Halim Yağcioğlu","poet_slug":"halim_yagcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL GİDER AH NASIL DA', 'yol-gi-der-ah-nasil-da-arif-damar-baojq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'De bana
Anlat hadi
Kaç
Kaç kez
Gönül gözüyle gördük
Can kulağıyla dinledik ki
Ah çın çın nasıl da güzel
Bir aydınlık
Beklenmedik bir zamanda
Beklenmedik bir yerde
Önümüzde
Arkamızda
Her yerde
Bir ses
Seslenen bir ses
Adımızı
Bir selam
Bir merhaba
Trende
İskelede
Durakta
Uzakta
Ah uzakta
Ah Bozcaada/Tenedos''ta
Bir şarkının ilk sözlerinde
Bir martının son sözlerinde
Ay saklanır bir buluttan bir buluta
Göz kırpar
Erken sabahların
Kurnaz yıldızı
Suda
Düşen yaprak ah nasıl da
Ah çın çın suda
Akarken
Kibrit nerede derken
Bir dergiye bakarken
Kuşluk vakti
Kapımızı kaparken
Sokaklar
Bakakalır
Kırlangıçlar çocuklar da
Ah çın çın nasıl da güzel
Yol gider ah nasıl da
Kartal bulutlardan inerken döne döne
Ah ikindi sessizliği
Nasıl da çınlar ikindi sessizliği
Yazların ovasında
Küüüt küt vurur
Açık kanadı penceremizin
Küüüt küt
Nasıl da aydınlanır su
Ah nasıl da aydınlanır
Çın çın içimizde
Takırdar durur
Tek ayak üstünde leylek
Takır takır
Takır takır', 'De bana Anlat hadi Kaç Kaç kez Gönül gözüyle gördük Can kulağıyla dinledik ki Ah çın çın nasıl da güzel Bir aydınlık Beklenmedik bir zamanda...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":59}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL HARİTASI', 'yol-hari-tasi-ozlem-tezcan-dertsi-z-jgrp6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'elmayı koparırken dalını gücendirmiş
işliyor, acımasız bağ makası bu şehrin
sağım solum sobe sırların aynasında,
eski düşlere iki beden büyüğüm
keşke fark etmeseydim korkarım,
korkarım ah büyüdüm.
ateşçiydim önceden söz nargilesine
söndüm, ustasını utandıran bir sönüş
çokluğumu bitiriyor papatyasızlık
süstüm bahçeye, ansızın sustum
hiç okşanmamış sardunyanın yanında
çıt çıkarmadı ayrılık
kirliyse yol haritası kaç kere gidilmiştir?
söylediklerimden pişmanım söylemediklerimden
kaç kişi duyar yağmurun dindiğini?
kuşatmada çöller, küller, güç yemek tarifleri
kurtuluştur, sığınmadır, bilenler bilir
gökyüzünde
şiirlerin gen haritası gizlidir.', 'elmayı koparırken dalını gücendirmiş işliyor, acımasız bağ makası bu şehrin sağım solum sobe sırların aynasında, eski düşlere iki beden büyü...', ARRAY['Türk Edebiyatı','Şiir','Özlem Tezcan Dertsi̇z']::text[], 8.5, '{"poet":"Özlem Tezcan Dertsi̇z","poet_slug":"ozlem_tezcan_dertsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL İKİYE AYRILDI', 'yol-i-ki-ye-ayrildi-robert-frost-ytmvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yol ikiye ayrıldı güze batık ormanda,
Gezemediğim için üzgünüm ikisini de
Bir gezgin gibi tek başına, uzun süre
Durdum, baktım en uzaktaki yola
Bükülüyordu çalılıkların arasında;
Ardından ötekine saptım güzellikten nasipli,
Kim olsa onu seçmez miydi zaten,
Çimenlerle kaplıydı fethedilmekti niyeti;
İşin doğrusu yolların her ikisi de
Gerçekte eşit ölçüde aşınmıştı,
Ve ikisinde de seher eşit uzanırdı
Yapraklara, ayak altında kararmamıştı renkleri
Âh, ilkini bir başka güne bıraktım!
Anlamadan bir yolun başka bir yola kavuştuğunu,
Kararsızdım gidersem dönemem asla geri.
Anlatacağım derin bir âh ile bu durumu
Yıllar yılı her yerde her zaman:
Yol ikiye ayrılmıştı ormanda ve ben--
Daha az katedilmiş olanı seçtim,
Ve bütün ayrımı yaratan da buydu.
Robert  FROST', 'Yol ikiye ayrıldı güze batık ormanda, Gezemediğim için üzgünüm ikisini de Bir gezgin gibi tek başına, uzun süre Durdum, baktım en uzaktaki y...', ARRAY['Türk Edebiyatı','Şiir','Robert  Frost']::text[], 8.5, '{"poet":"Robert  Frost","poet_slug":"robert_frost","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL TÜRKÜSÜ', 'yol-turkusu-afsar-ti-muci-n-9h8rg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çiz beyaz haritalara mor kalemle
Hiç görülmedik yepyeni kentleri
Hep oralara götür beni
Seninle olunca sıkılmam giderim
Çocuk yüreğinle sen kurarsın
Köprüleri alanları kuleleri
Panayırları ve çocuk bahçelerini
Çiz haritaların en güzel yerine
En güzel günleri ve geceleri
Seninle olunca çekinmem giderim
O kentlere yolcu diye çiz beni
Biletim pardesüm şemsiyem şapkam
Yüreğimde sevincim kafamda düşüncem
Nasıl da çok karıştık birbirimize
Bu el hangimizin eli
Bu saçlar hangimizin
Senin gittiğin her yere giderim', 'Çiz beyaz haritalara mor kalemle Hiç görülmedik yepyeni kentleri Hep oralara götür beni Seninle olunca sıkılmam giderim Çocuk yüreğinle sen ...', ARRAY['Türk Edebiyatı','Şiir','Afşar Ti̇muçi̇n']::text[], 8.5, '{"poet":"Afşar Ti̇muçi̇n","poet_slug":"afsar_timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL YORGUNU', 'yol-yorgunu-arif-damar-w5ni8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bana bir türkü öğretsen
Ayın aydınlığında söylesem
Gecenin karanlığında söylesem
Yağmur yağınca söylesem
Toprak uyanınca söylesem
Bana bir türkü öğretsen
Bana bir türkü öğretsen
Beraber olunca söylesem
Ayrı kalınca söylesem
Seni unutunca söylesem
Bana bir türkü öğretsen
Geldiğim yerlere er geç dönebilsem
Sevebilsem her şeyi yeniden sensiz
Sensiz vazgeçebilsem
Gece demesem gündüz demesem
Kimseleri dinlemesem
Hem yürüsem hem söylesem
Hem söylesem hem yürüsem', 'Bana bir türkü öğretsen Ayın aydınlığında söylesem Gecenin karanlığında söylesem Yağmur yağınca söylesem Toprak uyanınca söylesem Bana bir t...', ARRAY['Türk Edebiyatı','Şiir','Arif Damar']::text[], 8.5, '{"poet":"Arif Damar","poet_slug":"arif_damar","theme":"Türk Şiiri","is_hero":false,"total_lines":20}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOL', 'yol-a-kadi-r-f2ifr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tekmil haklar alınır.
Tekmil hürriyetler kısılır.
Tekmil köşe başları, tekmil kapılar tutulur.
Gökyüzü tıkılır dört duvar içine.
Bütün bunlara karşı,
dümdüz, apaydınlık kalır
seni bana getiren yol.', 'Tekmil haklar alınır. Tekmil hürriyetler kısılır. Tekmil köşe başları, tekmil kapılar tutulur. Gökyüzü tıkılır dört duvar içine. Bütün bunla...', ARRAY['Türk Edebiyatı','Şiir','A. Kadi̇r']::text[], 8.5, '{"poet":"A. Kadi̇r","poet_slug":"a_kadir","theme":"Türk Şiiri","is_hero":false,"total_lines":9}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLA ÇIKMAK! YİTİRMEK ÜLKELERİ', 'yola-cikmak-yi-ti-rmek-ulkeleri-fernando-pessoa-tz1py', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yola çıkmak! Yitirmek ülkeleri!
Bir başkası olmak süresiz,
Yalnız görmek için yaşamaktır
Köksüz bir ruhu olmak!
Kimseye ait olmamak, kendime bile!
Durmadan gitmek, sonu olmayan
Bir yokluğun peşinde
Ve ona ulaşma isteği içinde!
Böyle yola çıkmaktır yolculuk.
Ama ben açık bir yol düşünden öte,
Bir şeye gerek duymuyorum yolculuğumda.
Gerisi sadece gök ve toprak.
(1933)
Fernando PESSOA', 'Yola çıkmak! Yitirmek ülkeleri! Bir başkası olmak süresiz, Yalnız görmek için yaşamaktır Köksüz bir ruhu olmak! Kimseye ait olmamak, kendime...', ARRAY['Türk Edebiyatı','Şiir','Fernando Pessoa']::text[], 8.5, '{"poet":"Fernando Pessoa","poet_slug":"fernando_pessoa","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLCU', 'yolcu-uluer-aydogdu-sbdij', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'geldin
senle birlikte dağlar geldi neruda geldi dante
her şeyin tanrısı
şeytan az ötede
wagner
bir alçalıp
bir yükselip fısıldadı sular
varıp anneni emzirdin
erciyes''i, tekir yaylası''nı
ahh o baygın bakışların
muamma dedi içini çekerek borges
bir sırrı var her şeyin
usulca bir yarıktan taşa girdin tuz olarak
uğultu olarak kan
kaplana döndü suretin
kaplan çölde yürüyen mecnun''a
leyla çok uzak bir yıldızdı
gerindi
sırtını kaşıdı
teninde şeytan
bir mit
sürekli
sular seni işaret etti
yaprakların nemli
saçların dökülmekte yeryüzüne
gridir klee gridir
bir bir geçtin köyleri kasabaları cinnetleri hüzünleri
çocukları akşam üzerlerini suları efsaneleri
vardın
vardın mı ey
seni gidi şüpheci
şüpheci
şüpheci
kanma sakın
vardığını söyleyenlere
hep yolcusun
yol boyunca kazandığın şeyleri hatırla
suları
atmacaları
soğukları
mola yerlerinde göz göze geldiğin insanları
gözünü ayıramadığın
ayrılırken içinin burkulduğu sevgilileri
ayaklarını sokup
şarkılar söylediğin umudu
shakespear''i
içinde enva-i çeşit balığın dolaştığı
yüreğin gıcır bir misket
yuvarlanırken şeyh galip''te
yol işte
oluşur
bir tek yol kalır geriye
birkaç kez koklanmış sevgilinin gerdanı
hiç giyilmemiş ipek gömlek tazeliğinde
slyvia plath kalır
bulutlar kalır çardak altları
bağbozumlarının o meşhur akşamları
bak çekmecelerine eskinin
hepsi gerekli
yağmurlar yalnızca yağmurdu
gökyüzü bildik bir yüz
anlıyorsun ki şimdi
başka bir şey oldu dünya
anladın mı', 'geldin senle birlikte dağlar geldi neruda geldi dante her şeyin tanrısı şeytan az ötede wagner bir alçalıp bir yükselip fısıldadı sular varı...', ARRAY['Türk Edebiyatı','Şiir','Uluer Aydoğdu']::text[], 8.5, '{"poet":"Uluer Aydoğdu","poet_slug":"uluer_aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":66}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLCULUK', 'yolculuk-mehmet-zaman-saclioglu-geq5k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tren ya da herhangi bir geçendi
Su kıyısından.
Ne uzakta
Yakın bir aşk arası dağları.
Yaşardı akan zamanı enine sanki
Pencere önünde,
Geniş yastıklarda oturmamız.
Zaman ayrı bir dünyadır
Rüzgârları olan.
Onda nehirler dağlarla aynı hızda.
Zaman, başka bir gökyüzü
Geçerken bizi yavaşlayan
Uzun bir tren gibi
Su kıyısından.', 'Bir tren ya da herhangi bir geçendi Su kıyısından. Ne uzakta Yakın bir aşk arası dağları. Yaşardı akan zamanı enine sanki Pencere önünde, Ge...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Zaman Saçlioğlu']::text[], 8.5, '{"poet":"Mehmet Zaman Saçlioğlu","poet_slug":"mehmet_zaman_saclioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLCULUK''TAN', 'yolculuk-tan-sukru-erbas-4lwc0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve İstanbul geldi, bir halk şenliğinde
Gömmüş otuzdört ölüsünü Mayıs mavilerine..
Seslendiler bir şiir öncesinde verip elele
Bütün iyi ölülerimle ölümsüz soy şairlerim:
Unutmak kolaydır suçlamak kolaydır
Aslolan beslenip bir gül fidanı gibi
Yaşamın yapraklarıyla geçmişin toprağından
Bir gün bile yitirmeden bulutlar içinde
Güneşin yolunu
Geleceğe güller sunmaktır
Geleceğe güller sunmaktır..
I.
O zamanlar gökyüzü biçilmiş buğday kokardı
Çiğnenmiş üzüm mısır püskülü bostan yaprağı
Toprak kokardı insan emeğiyle yoğrulmuş.
Rüzgâr serin sesli konuğuydu evlerin
Bulutlardan ağaçlardan saçlardan süzülen
Bir dirim duygusuyla doldururdu odaları
Yağmur ikinci adıydı akşamların
Günün yorgunluğu üzerine dökülen
Bir düş inceliğinde akardı sular arklarda
Dilde uzaklık türküleri tutuşturarak.
İnsanlar bir soru imi gibi girip çıkarlardı
Geçimin dar kapılarından
Alın teri umut ve kaygıdan örülü
Mutluluk toprağın ve güneşin eline bakardı.
O zamanlar dünya küçüktü ve insanlar
Kardeşlik kokardı yardım duygularıyla
Paylaşmak, bir sevinci ya da güçlüğü
Bir karşı koyuş biçimiydi hayata.
Birbirine benzerdi evler, toprak dam
Beslenen hayvan, çocuk sayısı, daracık camlar..
Bir sır gibi gizlenirdi güzellik büyüdükçe kızlar
Erkekler şapkalarının siperinde geçerdi sokaklardan.
Aynı yalın dili konuşurdu yaşlılarla çocuklar
Dingin bir gölle bir akarsuyun dostluğunda.
Sevgi bir düş gülüydü bitişik avlularda
Sessizce serpilen, bunalmış ve utangaç
Evlilikle koklanırdı ancak ve solardı daha ilk yaz.
Birbirine benzerdi
Mevsimlerin bahçelere getirdiği renk
Evlere getirdiği telaş, sevinç, keder..
Yaşamak ağır bir suydu, zamanın
Ve toprağın derin ırmağında
Sürükleyerek bir nice hayatı ince kıvrımlarında
Akar, akardı..
IV.
Bana sorular öğreten dost
Bir de sen bulmadıkça doğrular yarımdır diyen..
Kimi gün bir türkü, kimi gün şiirlerle
Kitaplarla daha çok, giderek kitaplarla
Sabırlı, içten,yalın
Örnekler çıkarıp adım adım
Küçücük bir kentin kapalı hayatından
Bana dünyaları gösteren dost..
Telâşını taşıyorum yıllardır
Konuşurken birbirine vurduğun parmaklarının
Ve içine yüreğini koyup koyup
Ak güvercinler gibi ağzından uçurduğun
O büyülü, sıcak, doğru sözlerinin..
Sesini çoğaltıyorum sesler içinde
Bir tutku gibi geciktikçe büyüyen
İnancının onurunu taşıyorum yıllardır.
XIII.
İnsan ki anılardan bir buluttur
Hayatın sonsuzluğa akıp giden göğünde
Savruldukça çoğalır çözüldükçe birikir..
Düşmeden son damlası toprağın rahmine
Kimbilir kaç mevsim görür
Kaç rüzgâr geçirir..
XIX.
İnsan belleğinin ihanete vuran unutuşu
Ey yanlışı emziren kör meme
Hayatın kaçınılmaz kusuru..
Kapındayız işte koskoca bir geçmişle
Ölüler diriler düşenler dövüşenler..
Nicedir boşluğunda kimsesiz rüzgârların
Acı çığlıklar attığı cansız alanlar
Doğrular, yanlışlar..
Bir gizli dil gibi öfkenin için için
Derininde büyüdüğü dilsiz suskunluklar..
Kalanlar, kaybedilenler
Ne varsa, kapındayız işte
Tutuşturmak üzere yeniden
Zamanın küllenen yüreğini..
Sun bize inancın duru pınarlarından
Süzülen o eski tadını düşlerin;
Ömrümüzün acemi dallarında
O bir heyecanla telâş telâş açılan
Don vurmuş tomurcuğunu geleceğin..
Yaşamak ölümden üstün, acıdan büyük
Ver bize coşkusunu yeniden
Sesimizi geri ver
Sahipsiz kalmasın özgürlüğün türküleri
Kardeşliğin paylaşmanın sevginin
İnsanı çoğaltan o gönül zenginlikleri..
Zoru seçiyoruz yeniden, inançla, inatla
İyi, doğru ve güzel
Ne varsa "büyük insanlık" adına
Kapındayız işte bir daha
Tarihsin sen
İnsan emeği ve düşüyle yoğrulmuş
Göster bize geleceğin yollarını..', 'Ve İstanbul geldi, bir halk şenliğinde Gömmüş otuzdört ölüsünü Mayıs mavilerine.. Seslendiler bir şiir öncesinde verip elele Bütün iyi ölüle...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Erbaş']::text[], 8.5, '{"poet":"Şükrü Erbaş","poet_slug":"sukru_erbas","theme":"Türk Şiiri","is_hero":false,"total_lines":105}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLDA ESİRLER', 'yolda-esi-rler-a-kadi-r-6p6q1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi melûn bir gecedir.
Bir nöbetçi kürkü gibi simsiyah ortalık,
ve görünmez, garba giden yollar.
O görünmeyen yollara,
dokunaklı bir yağmur yağıyormuş gibi,
yorgun ayak sesleri dökülmektedir.
Hepsini tanıyorum onların.
Aynı topraktan buğday yediler.
Aynı topraktan taşıdılar saadeti harmanlara
kucak kucak
Ve söylediler aynı türküyü;
güneşin karşısında gerinirken,
bir zerresine bile
en harikulâde bir tebessümden fazla
kıymeti olan toprak.
Hepsini tanıyorum onların.
Yıldızlı bir gece altında otlara uzanıp,
onlardan dinlemiştim bir zamanlar
anadan doğma hikâyelerini yeryüzünün.
Hepsi memnun, hepsi genç, hepsi güzeldi.
Dudaklarında damlası yoktu hüznün.
Hiçbiri bıkmamıştı yaşamaktan.
Şimdi melûn bir gecedir.
Ne gökte bir tek yıldız,
ne yerde bir tutam ot var.
Yalnız, o mavi gözleri,
ve sarışın yüzleriyle
gençleri ve ihtiyarlarıyle insanlar,
girmişler içine sıcacık düşüncelerinin,
garba gidiyorlar,
garba giden yolda ...', 'Şimdi melûn bir gecedir. Bir nöbetçi kürkü gibi simsiyah ortalık, ve görünmez, garba giden yollar. O görünmeyen yollara, dokunaklı bir yağmu...', ARRAY['Türk Edebiyatı','Şiir','A. Kadi̇r']::text[], 8.5, '{"poet":"A. Kadi̇r","poet_slug":"a_kadir","theme":"Türk Şiiri","is_hero":false,"total_lines":33}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLDAN GEÇEN BİRİ', 'yoldan-gecen-bi-ri-i-lhan-berk-fd5jf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kırlangıç bir su birikintisi bir parça gök.
Bir şiirden düşmüş olmalı bunlar.
Böyle diyordu yoldan geçen biri.
Delta ve Çocuk', 'Bir kırlangıç bir su birikintisi bir parça gök. Bir şiirden düşmüş olmalı bunlar. Böyle diyordu yoldan geçen biri. Delta ve Çocuk...', ARRAY['Türk Edebiyatı','Şiir','İlhan Berk']::text[], 8.5, '{"poet":"İlhan Berk","poet_slug":"ilhan_berk","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YOLDAN GEÇENLER', 'yoldan-gecenler-ahmet-muhip-dranas-01svo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir rüyada yürür gibi geçerler
Evimin önünden her akşam üstü
Yüzleri bir duman gibi dağınık
Sönmüş saçlarında son damla ışık
Bir korkuları var gibi her akşam
Evimin önünden geçerler onlar
Ne sesleri ıslık çalan bir rüzgâr
Ne de omuzları yalçın bir dağdır
Ümit gözlerinde ölü bir bakış
Sayha bir bükülüş dudaklarında
Bulamadıkları nedir ki yaz, kış
Dolaşırlar şehrin sokaklarında...
Onlar - omuzları ne yalçın bir dağ
Ne sesleri ıslık çalan bir rüzgâr -
Bir rüya içinde gibi her akşam
Kopan ve uzayan şekiller ile
Sanki nehir gibi akmaktadırlar
Derinden ruhları çağıran sese.
Ahmet Muhip DRANAS
Mili Mecmua   No:140-141', 'Bir rüyada yürür gibi geçerler Evimin önünden her akşam üstü Yüzleri bir duman gibi dağınık Sönmüş saçlarında son damla ışık Bir korkuları v...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dranas","poet_slug":"ahmet_muhip_dranas","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YORGUN YÜREK', 'yorgun-yurek-sukran-kurdakul-8jx8y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir solukta yaşadım ve tükettim tümünü
Bir solukta gördüm elli üç yılda gördüğümü...
Sonunda yorgun yürek "duy..." dedi işte,
Sessiz sedasız gidilecek günü.', 'Bir solukta yaşadım ve tükettim tümünü Bir solukta gördüm elli üç yılda gördüğümü... Sonunda yorgun yürek "duy..." dedi işte, Sessiz sedasız...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YORGUN', 'yorgun-halekoray-mjykd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günleri canevimde kayıtlı
Tarihleri kalmaz aklımda
Tufandan bu yana nice savaş,
nice kıyım, nice salgın, nice kıtlık, infaz
nice
Acıyı takınmış yüzlerle
Nice gömü törenlerinde toplaştık
Mermeri aşınmış şadırvanlar gibi
yoruldu belleğim
Belleğim uçurtması çözük bir çocuk
Menzile varamayan yolcusu sonsuzluğun
Fakat yüreğim
onsekizinde henüz
Çeyizi dürülü utangaç kızı
Umudun', 'Günleri canevimde kayıtlı Tarihleri kalmaz aklımda Tufandan bu yana nice savaş, nice kıyım, nice salgın, nice kıtlık, infaz nice Acıyı takın...', ARRAY['Türk Edebiyatı','Şiir','Halekoray']::text[], 8.5, '{"poet":"Halekoray","poet_slug":"hale_koray","theme":"Türk Şiiri","is_hero":false,"total_lines":17}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YORT SAVUL', 'yort-savul-ece-ayhan-acck8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Arif Çağlar için
1.  Atlasları getirin! Tarih atlaslarını!
En geniş zamanlı bir şiir yazacağız
2.  Harbi karşılık verecek ama herkes
Göğünde kuş uçurtmayan şu üç soruya:
3.  Bir, Yeryüzünde nasıl dağılmıştır
Tarihi düzünden okumaya ayaklanan çocuklar?
4.  İki, Daha yavuz bir belge var mıdır ha
Gerçeği ararken parçalanmayı göze almış yüzlerden?
5.  Üç, Boğaziçi bir İstanbul ırmağıdır
Nice akar huruc alessultanlarda bayraksız davulsuz?
6.  Nerede kalmıştık? Tarihe ağarken üç ağır yıldız
Sürünerek geçiyor bir hükümet kuşu kanatları yoluk
7.  Çocuklar! ile bile muhbirler! ve bütün ahali!
Hep birlikte, üç kez, bağırarak, yazınız
8.  Kurşunkalemle de olabilir
Yort Savul!', 'Arif Çağlar için 1.  Atlasları getirin! Tarih atlaslarını! En geniş zamanlı bir şiir yazacağız 2.  Harbi karşılık verecek ama herkes Göğünde...', ARRAY['Türk Edebiyatı','Şiir','Ece Ayhan']::text[], 8.5, '{"poet":"Ece Ayhan","poet_slug":"ece_ayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YORULDUM YAŞAMAKTAN YURDUMDA', 'yoruldum-yasamaktan-yurdumda-sergey-yeseni-n-vxajy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yoruldum yaşamaktan yurdumda,
İçimde engin kırlara açılma özlemi,
Bırakıp gideceğim kulübemi,
Çekip gideceğim hırsız ve hayta.
Kendime bir barınak arayarak
Gideceğim günün ak pürçeklerinde.
Ve en iyi dostum beni vurmak için
Bileyecek bıçağını çizmesinde.
Çayırlık boyunca kıvrılan sarı yol
İlkbahara ve güneşe bürünmüşken,
Adını kalbimde taşıdığım
Kovacak beni eşikten.
Yeniden döneceğim baba ocağına,
Yadırgı bir sevinçle avunacağım,
Ve yeşil bir akşam, altında pencerenin
Koluyla mintanımın kendimi asacağım.
Çit kıyısındaki akça söğütler
Başlarını daha bir sevecen eğecekler.
Ve öylece, yıkamadan beni
Köpek uluması altında gömecekler.
Ve ay yüzerek durmamacasına,
Göllere küreklerini indirerek,
Ve sürdürecek yaşamasını Rusya
Avlularda ağlayarak ve hora teperek.
Sergey YESENİN', 'Yoruldum yaşamaktan yurdumda, İçimde engin kırlara açılma özlemi, Bırakıp gideceğim kulübemi, Çekip gideceğim hırsız ve hayta. Kendime bir b...', ARRAY['Türk Edebiyatı','Şiir','Sergey Yeseni̇n']::text[], 8.5, '{"poet":"Sergey Yeseni̇n","poet_slug":"sergey_yesenin","theme":"Türk Şiiri","is_hero":false,"total_lines":27}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YORULMAZ İŞÇİLERİYİZ AŞKIN', 'yorulmaz-i-sci-leri-yi-z-askin-mehmet-basaran-5r6t5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bütün gün kırlara bakmışım
Başaklarla kımıldanan
O bitek yalnızlığa
Burnumda gökyüzünün ince kokusu
Bütün gün sana bakmışım
Derin mırıltılarla ırmağa karışan
Çakıntılı gövdene senin
Uzanmışım terli toprağa
Yanına gözlerinin
Çıplak gecelere dokunuyorum
Yazın ve düşlerin sıcak kıvrımlarına
Denizi başlatıyor dudaklarının tuzu
Yüreğim konuşuyor şavkından
Ellerim böğürtlen moru
Yorulmaz işçileriyiz aşkın
Soluk soluğa ıslak taylar
Ürkek sokulmaların...
Ormanları uyandırıyor kanımın gürültüsü
Başdöndürücü yerlerindeyim dağın
Kollarımdan akan ırmak,
Sonsuza tamamlanıyorum', 'Bütün gün kırlara bakmışım Başaklarla kımıldanan O bitek yalnızlığa Burnumda gökyüzünün ince kokusu Bütün gün sana bakmışım Derin mırıltılar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Başaran']::text[], 8.5, '{"poet":"Mehmet Başaran","poet_slug":"mehmet_basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜ BRE YALAN DÜNYA', 'yuru-bre-yalan-dunya-karacaoglan-gz400', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yürü bre yalan dünya
Senden murad alınır mı
Pek dolukmuş humar gözler
Buna çare bulunur mu
Hem okudum hemi yazdım
Yalan dünya senden bezdim
Dağlar kovuğunda gezdim
Yiten yavru bulunur mu
Bahçelerde biter nergis
Ben ağlarım gece gündüz
Seher vaktı doğan yıldız
Yiten yavru bulunur mu
Karac''oğlan ağlar gülmez
Halin nedir diyen olmaz
Giden yavru geri gelmez
Yiten yavru bulunur mu', 'Yürü bre yalan dünya Senden murad alınır mı Pek dolukmuş humar gözler Buna çare bulunur mu Hem okudum hemi yazdım Yalan dünya senden bezdim ...', ARRAY['Türk Edebiyatı','Şiir','Karacaoğlan']::text[], 8.5, '{"poet":"Karacaoğlan","poet_slug":"karacaoglan","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜ YÜRÜ YALAN DÜNYA', 'yuru-yuru-yalan-dunya-yunus-emre-ufvjd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürü yürü yalan dünya
Yalan dünya değil misin
Yedi kez boşalıp yine
Dolan dünya değil misin
Bir od bıraktı özüme
Duman girdi gözüme
Bu gözle bugün yüzüme
Gülen dünya değil misin
Bir od bıraktın vay dile
Tutuştum yandın dert ile
Kıyamete bir kurt ile
Kalan dünya değil misin
Nide idim dağlar aşıp
Dağlar aşıp sular geçip
Havanın önüne düşüp
Yelen dünya değil misin
Yunus Emre''m sür sefayı
Sür sefayı çek cefayı
Ol Muhammed Mustafa''yı
Alan dünya değil misin', 'Yürü yürü yalan dünya Yalan dünya değil misin Yedi kez boşalıp yine Dolan dünya değil misin Bir od bıraktı özüme Duman girdi gözüme Bu gözle...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus_emre","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜDÜKÇE ÖĞRENMENİN ŞARKISI', 'yurudukce-ogrenmeni-n-sarkisi-kemal-ozer-bvf6r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yürüdükçe öğreniyorum ayaklarımızın da konuştuğunu
yürüdükçe sorular sorduğunu, yankılar bıraktığını ardında
öğreniyorum gök ne uçsuz bucaksız,
ne göründüğü kadar mavi
bulut değil rüzgârın taşıdığı bir tek,
vakti gösteren saat değil
yürüdükçe öğreniyorum, kendiliğinden ışımıyor sabah bile
Söylendiği yerde kalmıyor söz, durmadan ilerliyor alevi
- içinde bir yürek varsa bir sözün,
içinde bir alev varsa yüreğin -
bir alan bir başka alanın, bir kent bir başka kentin
yürüdükçe katıyor sınırlarına kendi sabırsız genişliğini
Yürüdükçe öğreniyorum, elimize neyi alırsak alalım
- bir somun parçası, aşınmış bir çift ayakkabı, bir bayrak -
yeni bir dili konuşuyor tutup kaldırdıkça havaya
öğreniyorum bir kıvılcıma yol verdiğini parmaklarımızın
neyi tutarsak tutalım ellerimizin her biri bir şalter', 'Yürüdükçe öğreniyorum ayaklarımızın da konuştuğunu yürüdükçe sorular sorduğunu, yankılar bıraktığını ardında öğreniyorum gök ne uçsuz bucaks...', ARRAY['Türk Edebiyatı','Şiir','Kemal Özer']::text[], 8.5, '{"poet":"Kemal Özer","poet_slug":"kemal_ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜDÜKÇE', 'yurudukce-uluer-aydogdu-d7y09', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bırak
uğuldasın gece
çünkü sahibi sensin gecenin
kim bilir
sabahın da
sahibi sen olacaksın
gökyüzünün de
aşk olunca
yağmurlar yağıyor olacak o kunt
yağmurlar
ıslanacağız o küfürde
tanrılar olacak, eliot
sen olacaksın hülya
yüreğini ferah tut
ve beni dinle
ben
ötelerden bahsediyorum
sular uyanmış
"ol" diye fısıldıyor rüzgâr
çoktan yola koyulmuş salik
yürüyesin
yürüdükçe
açılacak bütün çiçekler
dökülecek
ne kadar kan varsa
ne
kadar
ter
ay ışığı yorgun mu nedir bu gece
patikalardayız
suların bittiği yerde geçmek için ummana
akıtarak bütün iltihapları toplayarak bir bir
kendimizi gecelerden
yora yora yüreklerimizi
yora yora imgeleri kanayarak
ahh evet ovula ovula taşla
daha yorulmamız gerek
âşık olmamız
ahh evet ölmemiz gerek
unutma
ben seni geleceğinden öptüm.', 'bırak uğuldasın gece çünkü sahibi sensin gecenin kim bilir sabahın da sahibi sen olacaksın gökyüzünün de aşk olunca yağmurlar yağıyor olacak...', ARRAY['Türk Edebiyatı','Şiir','Uluer Aydoğdu']::text[], 8.5, '{"poet":"Uluer Aydoğdu","poet_slug":"uluer_aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":43}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREK ÇAĞRISI', 'yurek-cagrisi-adnan-yucel-3h5ay', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Acılı yağmurlarla düşmüşüm yere
Tatlı su göllerine akamıyorum
Yüzüm yüreğim deprem dalgası
Bu gül kıyımlarına bakamıyorum
Her sevi bir türküdür bağrımda
Her öfke bir ağıt
Ağıtlar kuşatmış dört yanımı
Kendi türkülerimi haykıramıyorum
Şarkılarla bezeniyor ufuklar
Yüreğim patlıyor dağbaşlarında
Yüreğim
Sancımı duyar mısın yaralarında
Kuş seslerinde yas nağmeleri
Şarkılar sabır ve çile makamında
Mendilimde öfke çıkınımda bilinç
Uykusuz kalır mısın kitaplarıma
Dudaklarımda hüzün
Avuçlarımda sevinç
Kulak verir misin çığlıklarıma
Dağları aşarak gelmişim sana
Demir kapıları kırarak
Işık olur musun karanlıklarıma
İsterim ki senden
Yaylalarda otlak olasın
Ovalarda ırmak olasın
Yayılasın göğsümün kırlarına
Sarasın beni sarasın
Dalların sevdası düşmüş toprağa
Olgun meyvelere hasret gençliğimiz
Zamanın billur çağlayanı
Gürül gürül akarken avuçlarımızda
Bir damla yağmur adına
Yakarmış dağbaşlarında yüreğimiz
Gökyüzünde sanılmış bütün yaşam
Gökyüzüne çivilenmiş ellerimiz
Ateşler yine parlıyor dağlarda
Dolular yine kırıyor çiçekleri
Gecenin karn��na inerken şafağın tekmeleri
Bulutları delen ışıklar
Ezik ve kinli
Aydınlık iri
Sanki kocaları işkencede kadın gözleri
Nasıl kapanır bu kanayan yara
Nasıl anlatılır ki sana bu hal
Terimde tuz gözyaşımda bal
Bağdaş kurar mısın soframa
Gözlerimde umut yüreğimde aşk
Ölümleri boşlayıp düşer misin sevdama
İsterim ki senden
İnancıma aşık olasın
Zindanıma ışık olasın
Yürüyesin gönlümün yollarına
Sorasın beni sorasın
İnce kabukları zorlanıyor zamanın
Gelecek damlıyor yorgun havuzlara
Damlalarla yılların gelin yüzü
Suların üstünde koskoca bir çağ
Umutlar sığmaz oluyor alanlara
Baharda gazel dökme bahçelerime
Ben yaşamayı bilmez miyim
Çocuklarım okul yollarında
Okullarım sabah kollarında
Sanki güzellikleri görmez miyim
Papatya beyazlığında ölüm sarısı
Karanfil kıvrımlarında kan
Bu çiçekler uğruna ölmez miyim
De gülüm ben seni sevmez miyim
Bahar değil acı yükleniyor dallarıma
Yapraklarımda ayrılık
Meyvelerimde gurbet
Vuslat olup gelir misin kollarıma
Ellerimde kış saçlarımda kar
Cemre olup düşer misin toprağıma
İsterim ki senden
Yılgınlıkta inanç olasın
Zulme karşı direnç olasın
Gömülesin aşkımın sularına
Göresin beni göresin
Göresin ki destan edesin
Söyleyesin dillerden dillere
Bir türkünün dizelerinde
Bir kavalın nağmelerinde
Alıp başını gidesin
Bağrı yanık yeller üstünde
Güneşin rengiyle düşesin ufuklarıma
Kırasın karanlıklarımı kırasın', 'Acılı yağmurlarla düşmüşüm yere Tatlı su göllerine akamıyorum Yüzüm yüreğim deprem dalgası Bu gül kıyımlarına bakamıyorum Her sevi bir türkü...', ARRAY['Türk Edebiyatı','Şiir','Adnan Yücel']::text[], 8.5, '{"poet":"Adnan Yücel","poet_slug":"adnan_yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":88}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREK', 'yurek-dritero-agolli-e31zs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağlar, dağlar, dağlar,
Demir yüklü, yiğitlik ve tohum yüklü!
Hiçbir yere sığmazsınız,
Yalnızca yüreğim, yüreğim içine alır sizi!
Dritero  AGOLLİ', 'Dağlar, dağlar, dağlar, Demir yüklü, yiğitlik ve tohum yüklü! Hiçbir yere sığmazsınız, Yalnızca yüreğim, yüreğim içine alır sizi! Dritero  A...', ARRAY['Türk Edebiyatı','Şiir','Dritero  Agolli̇']::text[], 8.5, '{"poet":"Dritero  Agolli̇","poet_slug":"dritero_agolli","theme":"Türk Şiiri","is_hero":false,"total_lines":7}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREĞİM KANIYOR', 'yuregi-m-kaniyor-yusuf-hayaloglu-2xxgi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakin göllerin kuğusuyduk,
Salınarak suyun yanağında.
Ve okşayarak nilüfer saçlarını gecenin.
Sonumuzun adım-adım
Yaklaştığını görürdük...
Yarılan ekmeğin buğusuyduk;
Paylaşılan zeytin tanesinin,
Yüzümüze saldıran yağmur avanesinin.
Biz hep üşüyen burnumuzu
Avucumuzda hohlayarak yürürdük.
Hiçbir hesabımız yoktu kimseyle.
Hiçbir aykırı yanımız,
Hiçbir yalanımız...
Gözüm yaşarıyor,
Yüreğim kanıyor...
Olmasaydı sonumuz böyle!..
Biri, saksımızı çiğneyip gitti.
Biri, duvarları yıktı,
Camları kırdı.
Fırtına gelip aramıza serildi.
Biri, milyon kere çoğaltıp hüzünleri
Her şeyi kötüledi,
Bizi yaraladı...
Biri şarabımızı döktü,
Soğanımızı çaldı.
Biri, hiç yoktan vurdu,
Kafeste garip kuşumuzu!
Ciğerim yanıyor,
Yüreğim kanıyor...
Solmasaydı gülümüz böyle!.
Dağlarda çoban ateşiydik,
Sarmalayarak acı bir sevda masalını
Ve hıçkırarak
Hırçın rüzgârların kavalını...
Namlunun, bağrımıza
Sinsice sokulduğunu bilirdik...
Ceylanın pınara inişiydik,
Vedalaşan birkaç damla gözyaşının;
Tenine kan bulaşan
O masum çakıl taşının...
Oysa biz dualarımızda hep
Birbirimizden daha önce
Ölmeyi dilerdik...
Bazı sorumluluklarımız vardı,
Hayata ilişkin.
Bazı basit sorularımız,
Anlaşılır bazı sorunlarımız...
Göğsüm daralıyor,
Yüreğim kanıyor...
İncinmeseydi gençliğimiz böyle...
Birer yolcuyduk,
Aynı ormanda kaybolmuş.
Aynı çıtırtıyla ürperen birer serçe.
Hep aynı kaderde buluşurduk
Sevmeye tutuklu gibi...
Birer tomurcuktuk hayatın kollarında.
Birer çiğ damlasıydık,
Bahar sabahında,
Gül yaprağında...
Dedim ya,
Hiç yoktan susturuldu şarkımız!
Yüreğim kanıyor,
Yüreğim kanıyor...
Bitmeseydi öykümüz böyle!..', 'Sakin göllerin kuğusuyduk, Salınarak suyun yanağında. Ve okşayarak nilüfer saçlarını gecenin. Sonumuzun adım-adım Yaklaştığını görürdük... Y...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":66}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREĞİMİN ACEMİ ELLERİ', 'yuregi-mi-n-acemi-elleri-yasin-erol-e7f4k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğinde yerini değiştirdiğin bir sevgiyle
Bahçelerinde evlerin dinlendiği o yerdesin
Bütün günahlarını biraraya toplayarak
Uzakların neden sinsi birer bıçak gibi
Durduğundan söz etmektesindir
Sen şimdi camların ardında buğulanan gözlerinle
Yağmura sarılacak kadar hüzünlüsündür
Rüzgara alışık kavak ağaçları gibi sessiz
Yüreğimin acemi elleri arasında
Ufalanan ekmek gibisindir
Bil ki bunlar bozkırca sezgilerden değildir
Birazdan başına üşüşür yıldızlar
Gecede ömrünü yarılayan kelebeklerin
kırılmalarını duyarsın
Eğer ağlayacaksan dilinin altına
bir ağaç parçası yerleştir
Güleceksen dudaklarını örtecek büyüklükte
bir bulut bulunsun yanında
Yerini yadırgayan bir ay dolanıyor gecede
Karanlık desen ölçülü salmış susmalarını
Aşkı utandıran bu hüzün de ne
Sen benim yüreğimin acemi elleri arasında
buğulanan ekmeğim değil miydin
Sen değil miydin
Bir çocuk yüzünden ekmeği öper gibi öptüğüm
Haydi ince ayarlanmış bir gülümseme seç dudaklarına
Çekip çevir şu karanlığı gözlerinle
Kaldır başını
Bak gökyüzüne
Gökyüzü dedikleri ilkel maviliğe
Mavilikte gizlenmiş bulut izlerine
Say ki bu bir rüyaydı
Say ki ben konuştum sen dinledin
Beni merak etme
Uzun ölümlerimi yarıladım bitmek üzere', 'Yüreğinde yerini değiştirdiğin bir sevgiyle Bahçelerinde evlerin dinlendiği o yerdesin Bütün günahlarını biraraya toplayarak Uzakların neden...', ARRAY['Türk Edebiyatı','Şiir','Yasin Erol']::text[], 8.5, '{"poet":"Yasin Erol","poet_slug":"yasin_erol","theme":"Türk Şiiri","is_hero":false,"total_lines":37}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREĞİN VAR YA YÜREĞİN', 'yuregi-n-var-ya-yuregi-n-mustak-erenus-ikzrd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceleri yıldızlar örter üstünü
Bilirsin de yine üşürsün.
Kaçışır boşluğa bu korkak sözcükler
Kan ter içinde.
Susar düşünürsün.
Boşuna mı sana bu sevda yaşamda
Bu yürek
Bu insan onuru.
Gölgelerimiz makaslanmışsa yollarda
Silkele bi kez kendini
At üstündeki kurumuş kalmışları
Yaprakları yeniden güneşe
Tut renkleri ellerinden.
Ha şöyle.', 'Geceleri yıldızlar örter üstünü Bilirsin de yine üşürsün. Kaçışır boşluğa bu korkak sözcükler Kan ter içinde. Susar düşünürsün. Boşuna mı sa...', ARRAY['Türk Edebiyatı','Şiir','Müştak Erenus']::text[], 8.5, '{"poet":"Müştak Erenus","poet_slug":"mustak_erenus","theme":"Türk Şiiri","is_hero":false,"total_lines":16}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREĞİN YERİNDE KALSIN', 'yuregi-n-yeri-nde-kalsin-metin-guven-v6m13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Simurg, ışığını gizlemek için
Geceyle yıkanmış yangınlara koşuyor
Kandan kanatları var
İzler kayboluyor yamaçlarda
Yüreğin yerinde kalsın, gerekebilir
Ölümlerin en güzelini şairler bilir.', 'Simurg, ışığını gizlemek için Geceyle yıkanmış yangınlara koşuyor Kandan kanatları var İzler kayboluyor yamaçlarda Yüreğin yerinde kalsın, g...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜREĞİNİN VURUŞUYLA', 'yuregi-ni-n-vurusuyla-akif-kurtulus-ro4bz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ikiniz''e; artık "tören bitti"
mermi susuşunu aldım, başarısız suikastler hazırladım kendime
kar içinde geçtim ovalardan, gölgemi dağ kapladı
fırtınaya karıştırdı soluğumu sevgilim, savurdu tipiye
yüreğinin vuruşuyla sayardım aramızdan geçen göçmenkuşları
unutturdu yüreğini de, fırlatıp attı boynundan uçarı kokumu
ayaz vurdu, buğulandım kara saplanmış tren camlarında
artık güneş saati kullanacak mevsimlerden çok uzaktayım
tetik sesindeyim, düşüyorum küçük ihanetlerle yaralı aşklara', 'ikiniz''e; artık "tören bitti" mermi susuşunu aldım, başarısız suikastler hazırladım kendime kar içinde geçtim ovalardan, gölgemi dağ kapladı...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif_kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":11}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİRMİ ALTILAR BALADI', 'yi-rmi-altilar-baladi-sergey-yeseni-n-yzpkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyle, şair, şarkıyı
Söyle
Gök bezi mavidir
Öyle
Denizin de şarkıdır mırıltısı
Mırıltı...
Yirmi altı onların sayısıydı, yirmi altı
Mezarlarını kumlar saklamaz
İki yüz yedinci verstada
Kurşuna dizildiklerini
Kimse unutmaz
Denizin ardında
Orda
Havada dolaşan duman
Görüyor musun kum altından
Kalkıyor Stepan Şaumyan
Kumlu çöl tenha mı tenha
Bak, orda elli el daha
Kalkıyor püfünü silerek
Diyor yirmi altılar:
"Bakû''ye gitmemiz gerek
Bir görelim durdukça duman
Nasıldır bizim Azerbaycan
Gece,
Bir kavun misali
Yuvarlatıyor ayı
Dalgalar yalıyor kıyıyı
Tam böyle bir gece
Frenkler
Onları kurşuna dizdiler.
Sosyalizm uğruna
Haydi kalk
Ayağa kalktı bütün halk
Çarlığa karşı
El ele
Hem köylü hem de amele
İliç vardı Rusya''nın orda
Beylerin başına çekiç
İndiren atamız İliç
Kafkas''taysa burda
Bunlar
Bunlar vardı, yirmi altılar
Gece karanlığı hafifçe
Hafifçedir o, bu gece
Bakû üstünde uçuyor karaltılar
Yirmi altılar
Yirmi altılardır bu karaltı
Yirmi altı.
Hışırdayan
Ne yel, ne duman
Konuşuyor dinle, Şaumyan:
"Çaparidze, sen hele bak
Köylünün elinde toprak
İşçinin elinde
Ekmek
İktidar onların demek
Bak, petrol kuyuları işler
Her yerde trenler, gemiler
Her yerde bunlar dolaşır
Ve kızıl yıldızı taşır"
Çaparidze diyor:
"Evet
Bu büyük, pek büyük nimet
Görülüyor ki emekçiler
Tamamiyle güce ermişler.
Gece, bir kavun misali
Yuvarlatıyor ayı
Dalgalar
Yalıyor kıyıyı
Tam böyle bir gece
Frenkler
Bizi kurşuna dizdiler"
Sosyalizm uğruna
Haydi kalk
Ayağa kalktı
Bütün halk
Çarlığa karşı
El ele
Hem köyle hem de amele
İliç vardı Rusya''nın orda
Beylerin başına çekiç
İndiren atamız İliç
Kafkas''taysa burda
Bunlar
Bunlar vardı, yirmi altılar.
Bakû''nün üstünde
Şafak sökmeye başlar
Sustular artık
Aziz karaltılar
Kimi alnından yaralı
Kimi göğsünden
Dönüyorlar
Mezarlarına Bakû''den
Söyle, şair,şarkıyı
Söyle
Göz bezi mavidir
Öyle
Denizin de şarkısıdır mırıltısı
Mırıltı...
Yirmialtı onların sayısıydı
Yirmialtı.
Sergey YESENİN', 'Söyle, şair, şarkıyı Söyle Gök bezi mavidir Öyle Denizin de şarkıdır mırıltısı Mırıltı... Yirmi altı onların sayısıydı, yirmi altı Mezarları...', ARRAY['Türk Edebiyatı','Şiir','Sergey Yeseni̇n']::text[], 8.5, '{"poet":"Sergey Yeseni̇n","poet_slug":"sergey_yesenin","theme":"Türk Şiiri","is_hero":false,"total_lines":104}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİRMİ İKİ YIL SONRA', 'yi-rmi-i-ki-yil-sonra-sukran-kurdakul-4938l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Unutulmaya kalkan bir trenin
Eski bir istasyona bakan penceresinde
Bir yolcuyu sorar gibi arayan
Jandarmalar, ellerimin garip nöbetçileri
Daha ilk kampana bile vurmadan
Yalnızlığın kelepçesini taktı içime.
Şehir arkada kaldı, geçtiğim son caddeden
Ne yasakların gölgesini alnında gördüğüm
Işığı kilitleyen karanlık kafeslerinde
Bu sonsuz özgürlüğe ne zaman varmışım ben
Dünyanın duygusunu gözlerinde içeren
İçimdeki adam, kabına sığmıyor gene.
Kaç akşam geçirdiğim Birinci Şubeden,
Bir tünelden kopar gibi çıkıyor trenimiz...
Jandarmalar, ellerimin garip nöbetçileri.
Hangi yalnızlığa gittiğimizi söyler mi?', 'Unutulmaya kalkan bir trenin Eski bir istasyona bakan penceresinde Bir yolcuyu sorar gibi arayan Jandarmalar, ellerimin garip nöbetçileri Da...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran_kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİRMİBİRİNCİ YÜZYILIN İNSANLARINA ŞİİRLER', 'yi-rmi-bi-ri-nci-yuzyilin-i-nsanlarina-si-i-rler-hasan-i-zzetti-n-di-namo-mkxv5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'I
Bir Eyüp sabrıyla bekledim
Sabahı olmayan gecelerde.
Gül dalları yerine demir çubuklar vardı
Münzevî-münzevî pencerelerde.
Dört uzun yıl boyunca
Dışarda koskoca bir doğa
Baştan çıkaran kokularıyla
doldurdu yolları.
Her bahar göğün kapılarında
Şarkılar okudu tarla kuşları.
Apak bulutlar geçti habersiz
Âşıklığımdan, şairliğimden,
Bahar yağmurları bensiz yağdı
Ebemkuşağı açtı bensiz.
Bir Eyüp sabrıyla bekledim
Gübreliğinde günlerimin,
İnsanlar olmadı farkında
En küçük hünerimin.
Ne de bir kimsenin haberi oldu
varlığımla yokluğumdan.
Yalnız, bir bahar sabahına benzeyen çocukluğumdan
Ebemkuşakları gelirdi
eğlendirmek için beni,
İçinde çırılçıplak çimdiğim dereler
Söylerken kulağımın dibinde ninni
Bir bahar sabahı gibi güzel çocukluğumun
Kırık beşiğine başımı koyar
Uyanmadan günlerce uyurdum.
Umudumu, dudaklarında büyük türküler
Ellerinde gelincik desteleri
karşımda bulurdum.
Öğrenme
istemem
bir Eyüp sabrı nedir
torunlarımın torunu.
Say ki dedelerin bir masal yaşadı
Say ki acılar masaldı,
Öttür ölümsüzlüğe doğru borunu!', 'I Bir Eyüp sabrıyla bekledim Sabahı olmayan gecelerde. Gül dalları yerine demir çubuklar vardı Münzevî-münzevî pencerelerde. Dört uzun yıl b...', ARRAY['Türk Edebiyatı','Şiir','Hasan İzzetti̇n Di̇namo']::text[], 8.5, '{"poet":"Hasan İzzetti̇n Di̇namo","poet_slug":"hasan_izzettin_dinamo","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜMEK', 'yurumek-ali-cengi-zkan-v15ug', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk da gelir peşimize, biz yürüyüp gideriz
Kumsalın en ince yerlerine basarak
(Çünkü hep eklemlerdedir işimiz: sevgi ve nefret,
dostluk ve düşmanlık dayanmak ve
çözülmek.
Dayanırız denizdeki konserve kutusuna,
karpuz kabuklarına, fabrika artıklarına.
Dayanırız falakaya, elektriğe, su işkencesine.
Çünkü ilerde okyanus vardır, bir büyük, bir
geniş, bir ferah.
Ondandır ki goncayı sevişimiz tazeliğine değil
açışına).
Aşk da gelir peşimize, biz yürüyüp gideriz
Kumsalın en ince yerlerine basarak
Kanatarak ayak izlerimizi
(Çünkü kanla kazanılmıştır herşey:
bir çocuğun gülüşü,
akşamları kaşıkladığımız bir tas çorba.
sevgili dudaklara kondurulan bir küçük,
bir küçücük öpücük,
başını güneşe tuttuğumuz oğullarımız,
sevgililerimiz,
Çünkü kanla kazanılmıştır herşey
ve kanla, yitirilir).
Aşk da gelir peşimize, biz yürüyüp gideriz
Kumsalın en ince yerlerine basarak
Kanatarak ayak izlerimizi
Aşk da girer içimize, biz yürüyüp gideriz', 'Aşk da gelir peşimize, biz yürüyüp gideriz Kumsalın en ince yerlerine basarak (Çünkü hep eklemlerdedir işimiz: sevgi ve nefret, dostluk ve d...', ARRAY['Türk Edebiyatı','Şiir','Ali Cengi̇zkan']::text[], 8.5, '{"poet":"Ali Cengi̇zkan","poet_slug":"ali_cengizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİRMİNCİ YÜZYILDA', 'yi-rmi-nci-yuzyilda-samih-el-kasim-dbo16', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öğrendiydim nefret etmemeyi
yüzyıllar boyunca,
beni zorla yoldan çıkardılar:
Fırlattım oku suratına koca yılanın,
çarptım ateşten kılıcı canavar tanrının suratına.
İlyas Peygamber yaptılar zorla beni
yirminci yüzyılda.
Öğrendiydim ağıza almamayı
sapık düşünceleri
yüzyıllar boyunca.
Bugün yapıştırıyorum kamçıları tanrılara,
o tanrılar ki gönlümdeydiler, kutsaldılar,
sattılar benim halkımı iki pula
o tanrılar
yirminci yüzyılda.
Öğrendiydim kapalı tutmamayı
konuklara kapımı
yüzyıllar boyunca.
Ama bir gün açtım
gözlerimi ve gördüm ki
neyim var neyim yok yağma Hasan''ın böreği.
Ve gördüm ki asmışlar karımı,
ve yavrumun sırtında
na şöyle şöyle
yara izleri.
Konuk değilmiş onlar, anladım, düşmanmışlar.
Mayınlar, bıçaklar topladım eşiğimden.
Sonra ant içtim bütün yaralarım adına:
Atmayacak eşiğimden adımını, dedim,
bir tek konuk
yirminci yüzyılda.
Bir şairden başka bir şey değildim
yüzyıllar boyunca
tanrıdan medet uman.
Oysa şimdi ben
bir volkanım,
yirminci yüzyılda.
Patlayan bir volkan!
Samih El KASIM', 'Öğrendiydim nefret etmemeyi yüzyıllar boyunca, beni zorla yoldan çıkardılar: Fırlattım oku suratına koca yılanın, çarptım ateşten kılıcı can...', ARRAY['Türk Edebiyatı','Şiir','Samih El Kasim']::text[], 8.5, '{"poet":"Samih El Kasim","poet_slug":"samih_el_kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":41}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİRMİNCİ YÜZYILIN İLK YARISI', 'yi-rmi-nci-yuzyilin-i-lk-yarisi-cahit-kulebi-j2u0r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yirminci yüzyılın ilk yarısı
Ölüm çağı oldu
Zulüm çağı oldu
Yalan çağı oldu.
Yirminci yüzyıl insanları
Asıp kestiler
Kesip biçtiler
Tepeler gibi ölü yığıp
Deryalar gibi kan içtiler.
Çocukları ağlattılar
Kadınların ırzına geçtiler.
Yirminci yüzyıl, insanların
Ağlamasın da kimler ağlasın!', 'Yirminci yüzyılın ilk yarısı Ölüm çağı oldu Zulüm çağı oldu Yalan çağı oldu. Yirminci yüzyıl insanları Asıp kestiler Kesip biçtiler Tepeler ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Külebi̇']::text[], 8.5, '{"poet":"Cahit Külebi̇","poet_slug":"cahit_kulebi","theme":"Türk Şiiri","is_hero":false,"total_lines":15}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİRMİNCİ YÜZYILIN PORTRESİ', 'yi-rmi-nci-yuzyilin-portresi-czeslaw-milosz-ryx0g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kardeşçe bir özen dolu, gülümsemenin ardında,
Nefret eder, iktidar diyalektiğinin kurbanı gazete okurundan.
"Demokrasi"ye çağırır hep göz kırparaktan.
Yalnızca nefret eder insanın bedensel zevklerinden,
Hiç unutmaz yiyip yiyip çiftleşenleri,
Tümünün boğazını kesivermektir derdi.
Genel öfkeyi durdurmak için önerisi: dans ve garden-parti.
"Kültür!" der  "Sanat!" der, ama bunlarda gördüğü
Bir sirktir, ne fazlası ne eksiği.
Tamamen tükenmiştir, bitmiştir.
Uykusunda ya da ameliyat masasında, "Tanrım, ah Tanrım!" der
Kendisini Mithra ile İsa''ya tapınmayı birleştiren Romalı gibi görür.
Eski inançlara bağlıdır hâlâ bağlıdır, bazen de kendini şeytanın elinde sanır.
Geçmişe saldırırsa da istemez tümden yıkılmasını,
Korkar kafasına başka dayanak bulamamaktan.
İskambili, satrancı, en çok da kendiyle tartışmayı sever.
Bir eli Marx''ın yazılarının üstündedir, ama gizlice İncil okur.
Tükenmiş kilise ayinlerini alaycı gözle izler.
Dekoru: At eti rengi yıkılmış bir kent.
Elinde: Ayaklanmada öldürülmüş bir "faşist" oğlanın not defteri.
Czeslaw  MILOSZ', 'Kardeşçe bir özen dolu, gülümsemenin ardında, Nefret eder, iktidar diyalektiğinin kurbanı gazete okurundan. "Demokrasi"ye çağırır hep göz kı...', ARRAY['Türk Edebiyatı','Şiir','Czeslaw  Milosz']::text[], 8.5, '{"poet":"Czeslaw  Milosz","poet_slug":"czeslaw_milosz","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜRKEN CIGARA İÇMEMELİ', 'yururken-cigara-i-cmemeli-mahzun-dogan-2zil0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '1.
Anneme göre, bırak yürürkeni, kesinlikle cigara içmemeli
babamsa, efkâr dağıtır diyor, ama bazen
Sislerden mi çıkar, sislere mi gömülür Atatürk Bulvarı?
Bunu bir Rimbaud sordu, akşamın serin koynuna girerken gençliğinden
parmaklarının arasında cigarası yanıyordu
Usul adımlarla yürüyüp gittim aldırmadan
Yüz altmış kilometre hızla giden bir otomobilin rüzgârı
biçti düşlerimi. Fırlayıp düştü önüme bir James Dean
Karınca sürüleri dolaşıyordu dudaklarında
Cigara dumanından sararmıştı
dişleri tarihin
2.
Sevdim bir kadını, çok eski bir yüzüm dedi
sahaflarda belki bulunur bir roman
Aradım durdum, bu kaçıncı cigara yandı bitti, yandı bitti
3.
Ben bir çekirgeyim belki de
yüzyıllar öncesi bir minyatürde
Belki de Fatih''in kokladığı gül
Yok yok, bir Turan Erol resmiyim
yatık bir bisiklet sahilde
Çok eski çağlarda yontulmuş
ponza taşından bir Venüs heykeli
belki de. Belki de örgüyüm Penelopeia''nın elinde
örülürüm gündüz,
çözülürüm gece
4.
Yağmurlu bir günde öldü babam
dedi Seda. Yağmurlu günlerde insan yalnızdır
Yalnız öldü babam
Okul ne ki ölümün yanında
hangi üniversiteli daha bilgece bakar
babasız bir çocuktan
5.
Seni bu kalabalığın içinden çekip çıkaracağım
Zaten acemisiyim yüzmenin, üç kulaç atsam yorulurum
Tenim alışkın değil köpüklü sulara
Her şeyi unutacağım. Unuturum tüm sözcükleri
Seninle yeni bir dil yaratmaya
Yaka paça alıp götürecekler gündüzümü
Rüzgâr bir sessizliğe karıştıracak
Sensizliğe savuracak ömrümü
6.
ki öldüğümde ben
dansını sürdürecek baletler, balerinler
narin parmakuçlarıyla çizecekler ülkemin ufkunu
öyleyse neden
korkmalı ki ölümden
7.
Annem ki şimdi bir başka ülke
güzelliği ütopya
Benim annem kuş
dalgalandırır göğü
Benim annem çiçek
badem dallarından gülümser
baharda', '1. Anneme göre, bırak yürürkeni, kesinlikle cigara içmemeli babamsa, efkâr dağıtır diyor, ama bazen Sislerden mi çıkar, sislere mi gömülür A...', ARRAY['Türk Edebiyatı','Şiir','Mahzun Doğan']::text[], 8.5, '{"poet":"Mahzun Doğan","poet_slug":"mahzun_dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":59}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜRÜYEN KENTLER', 'yuruyen-kentler-metin-guven-7p98g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anne ve oğul:
Soğuk gecelerin suç ortakları
Çıplak iletkenliği hayatın
Uykusuzkuğun nedeni mi olur
İçilir on yıllık dostlukların kahvesi
Ve telvesi ilk gördüğün denize atılır
Anne ve oğul yakınlığı
Yürüyen kentleri gibidir dünyanın.', 'Anne ve oğul: Soğuk gecelerin suç ortakları Çıplak iletkenliği hayatın Uykusuzkuğun nedeni mi olur İçilir on yıllık dostlukların kahvesi Ve ...', ARRAY['Türk Edebiyatı','Şiir','Metin Güven']::text[], 8.5, '{"poet":"Metin Güven","poet_slug":"metin_guven","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİTİK BAHAR', 'yi-ti-k-bahar-turgay-fi-sekci-69v8r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayat, kar altında kalan bahar
Çiçekleri üzerinde ölüyor en bereketli ağaçlar
Üretkenlik dört duvar arasında
Kar yağıyor bahar dallarına
Üç bin yıllık hayatın bilgesi
Sevene acı veren, bedeni bal ülke
Işıklarının ardından solup gidiyor insanlar
Kar yağıyor güneşli kirpiklerine
Yalnız sevda ve kocalma hüznünü yakıştıran ozan
Karşında bir sigara içip ölebilirdik
İlk sen mi soldun böyle uzak toprağından
Karadeniz’de yatanlar, adları yitik
Boyna dolanan kent, Magosa Kalesi
Hepsi sayılsa tüm bir tarih mi
Hayat, kar altında kalan bahar çiçekleri
Yazın tek tük meyva dallarda
Kim doyacak, kim doyuracak
Turgay FİŞEKÇİ
-----------------------------------------------------------------------', 'Hayat, kar altında kalan bahar Çiçekleri üzerinde ölüyor en bereketli ağaçlar Üretkenlik dört duvar arasında Kar yağıyor bahar dallarına Üç ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Fi̇şekçi̇']::text[], 8.5, '{"poet":"Turgay Fi̇şekçi̇","poet_slug":"turgay_fisekci","theme":"Türk Şiiri","is_hero":false,"total_lines":21}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİTİK SAVAŞLARA NAĞMELER', 'yi-ti-k-savaslara-nagmeler-onan-gunoz-q7ajd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'hani sol yumruk havada bir cenazemiz olacaktı
ve avucumuzda bir gül yaprağı
gözlerimizde gelecek, güzel günler
türküler söyleyecektik hep beraber
şimdi elimizde yalnızca
bitmemiş öyküler
sahipsiz bir ceset kaldi geriye
bütün şiirlerden
bir de bütün bu hikâyât
yani, hayatın yalancı çıkardığı son masal
yıkık duvarlarda son yazılar
&quot;aşka ve özgürlüğe dair&quot;
kanlı defterlerden arta kalan
bir kaçağın boğuk haykırışları gibi
geceleri kirli sokaklara saklanan
isimsiz mektuplar, kızgın şarkılar
ayışığında birbirine benzeyen kelimeler
ve sıcak bir odanın yalnızlığında
ve yorgun seslerde yankılanan
yitik savaşlara nağmeler...', 'hani sol yumruk havada bir cenazemiz olacaktı ve avucumuzda bir gül yaprağı gözlerimizde gelecek, güzel günler türküler söyleyecektik hep be...', ARRAY['Türk Edebiyatı','Şiir','Onan Günöz']::text[], 8.5, '{"poet":"Onan Günöz","poet_slug":"onan_gunoz","theme":"Türk Şiiri","is_hero":false,"total_lines":22}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİTİKÇİ', 'yi-ti-kci-metin-eloglu-rl6l1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hadi git azıcık İstanbul iste
Kosunlar o denizi bir çanağa
Bir çıkına elesinler o günlerimi
O yazdan Üsküdar''dan ne kaldıysa Elif''ten
Doldur ceplerine
Onlarda yoksa komşularında vardır
Tanırlar sevinirler
Beni Bay Metin gönderdi, de', 'Hadi git azıcık İstanbul iste Kosunlar o denizi bir çanağa Bir çıkına elesinler o günlerimi O yazdan Üsküdar''dan ne kaldıysa Elif''ten Doldur...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin_eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİTİKLER GECESİ', 'yi-ti-kler-gecesi-gulten-akin-fj5vc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi dünya boşlukta yavaş
Sen bütün canlılardan uzaksın yalnızsın
Rüzgâr uslandı doruklarda
Dağ çiçekleri uykuya vardı
Ay bacadan aştı uyumaz mısın
Bir ıslak serinlik yürüdü
Kara sokaklardan içeri
Çıtırdadı durdu bütün gün
Ayaklarının altında bir şeyler
Bütün gün ölüler gibi sustun
Bilsen ötesi aydınlık çizginin
Delice yakardın eski şiirlerini
Bir tutam bulut iki damla yağmur için
Yeniden sevinirdin içten içe
Bilsen ötesi aydınlık çizginin
Bu hal senin halin değil
Bütün gücünü yitirmiş
Bu hal senin halin değil
Yaşamanın kendisini yitirmiş
En insan yanıyla sana dönük
Dost dediğin ne gün içindir
Unut uzağı olduğu yere
Kaldır yatağından vakitsiz
Kaldır başucuna getir
Şimdi dünya boşlukta yavaş
Sen bütün canlılardan uzaksın yalnızsın
Rüzgâr usandı doruklarda
Dağ çiçekleri uykuya vardı
Ay bacadan aştı uyumaz mısın', 'Şimdi dünya boşlukta yavaş Sen bütün canlılardan uzaksın yalnızsın Rüzgâr uslandı doruklarda Dağ çiçekleri uykuya vardı Ay bacadan aştı uyum...', ARRAY['Türk Edebiyatı','Şiir','Gülten  Akin']::text[], 8.5, '{"poet":"Gülten  Akin","poet_slug":"gulten_akin","theme":"Türk Şiiri","is_hero":false,"total_lines":31}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİTİRDİĞİMİZ YASA', 'yi-ti-rdi-gi-mi-z-yasa-oguz-tansel-17a6z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bitkilerden dayanıksız olmuşuz
Ömrümüz ağaçlarınkinden kısa
Değiliz kuşlar kadar
El ele versek artar gücümüz
Olanca ateşiyle yüreğimizin
Kor haline gelivermek
İnsanı dünyayı ölesiye
Yeniden yaratıp sevmek
Yitirdiğimiz yasa
İşte toprak işte insan
Onu getirelim dile', 'Bitkilerden dayanıksız olmuşuz Ömrümüz ağaçlarınkinden kısa Değiliz kuşlar kadar El ele versek artar gücümüz Olanca ateşiyle yüreğimizin Kor...', ARRAY['Türk Edebiyatı','Şiir','Oğuz  Tansel']::text[], 8.5, '{"poet":"Oğuz  Tansel","poet_slug":"oguz_tansel","theme":"Türk Şiiri","is_hero":false,"total_lines":13}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUMUŞAK', 'yumusak-yusuf-altunel-mo2ht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çiğ damlalarının gülü öpüşü
kadar yumuşak olsun
kirpiklerinde oynaşan
güneşin nakışı', 'çiğ damlalarının gülü öpüşü kadar yumuşak olsun kirpiklerinde oynaşan güneşin nakışı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf  Altunel']::text[], 8.5, '{"poet":"Yusuf  Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":6}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUNUS EMRE', 'yunus-emre-necip-fazil-kisakurek-6r6pz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaç mevsim bekleyim daha kapında,
Ayağımda zincir, boynumda kement?
Beni de, piştiğin belâ kabında,
O kadar kaynat ki, buhara benzet!
Bekletme Yunus''um, bozuldu bağlar,
Düşüyor yapraklar, geçiyor çağlar;
Veriyor, ayrılık dolu semalar,
İçime bayıltan, acı bir lezzet.
Rüzgâra bir koku ver ki, hırkandan;
Geleyim, izine doğru arkandan;
Bırakmam, tutmuşum artık yakandan,
Medet ey dervişim, Yunus''um medet!', 'Kaç mevsim bekleyim daha kapında, Ayağımda zincir, boynumda kement? Beni de, piştiğin belâ kabında, O kadar kaynat ki, buhara benzet! Beklet...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kisakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kisakürek","poet_slug":"necip_fazil_kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YURDUM BENİM ŞAHDAMARIM', 'yurdum-beni-m-sahdamarim-ahmed-ari-f-hdymy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Engereğin dişlerine işledim,
Ağu dişlerine
Oluklu, çentik...
Ve vurgun,
Gözleri bir çift cehennem
Burnuna kan tütmüş
Pars bıyığına...
Dağın pulat yüreğine işledim,
Şimşeğin masmavi usturasına
Sevdanı usul-usul
Sevdanı mısra-mısra
Lo ben seni hapislerde sevmişim,
Ben seni sürgünlerde.
Yurdum benim şahdamarım...
Yücende buzul
Ve kar,
Maviş dağ tavşanları
Gün vuranda alaran
Zemheri yılanları
Ve yakut bir hışımla
Öyle çakılan
Sonsuzluğun yakışığı kartallar.
Başım gözüm üstünesin
Suskum, avazım üstüne...
Adından başka silah
Yazgından başka günah
Daha yazmamış
Hiçbir gizli dosyada
Hiçbir açık kitapta.
Peşinde azgınları
Kanlı paranın
Yani Doların itleri,
Altın, Sterlin kurtları
Ve petrol Nemrutları
Ve kurşun Yezitleri...
Kaçgunda, kaçakta
Can havlindesin...
Ve çocuk ölüleri
Parçalanmışlar
Daha süt kokuyorlar
Ve anne ölüleri
İncecikten, gencecikten
Açık hepsinin gözleri.
Halkım benim
Askıda çığ...
Ahmed ARİF', 'Engereğin dişlerine işledim, Ağu dişlerine Oluklu, çentik... Ve vurgun, Gözleri bir çift cehennem Burnuna kan tütmüş Pars bıyığına... Dağın ...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Ari̇f']::text[], 8.5, '{"poet":"Ahmed Ari̇f","poet_slug":"ahmed_arif","theme":"Türk Şiiri","is_hero":false,"total_lines":48}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YURT', 'yurt-anna-ahmatova-09ffu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‘B i z d e n
Y a l ı n ı   y o k,  d a h a
O n u r l u s u   b i z d e n, d a h a
A z   g ö z y a ş ı   d ö k e n i   y o k.’
(1922)
Yüreklerimiz tılsım gibi takınmaz yurdu,
Yurt ozanın elleri altında hıçkırmaz,
Kanatmaz bir türlü unutamadığımız yaraları
Acı uykularımızda. Vadedilmiş ülke değil.
Ruhlarımız değer biçmez yurda
Alınıp satılacak bir mal olarak;
Hastası, yoksulu, sessizi bu dünyanın, ki
Çoğu aklımıza bile getirmeyiz yurdu.
Evet, bizim için galoşlarımızdaki çamur,
Evet, dişlerimizin arasına giren, bizim için
Kumdur, ezeriz, ufalarız, öğütürüz,
O ince, temiz toprağı.
Ama yatacağız içine, otları, çiçekleri olacağız,
Utanmasız, sıkılmasız diyeceğiz ki: Bu yurt bizim.
1961 Leningrad
Anna AHMATOVA', '‘B i z d e n Y a l ı n ı   y o k,  d a h a O n u r l u s u   b i z d e n, d a h a A z   g ö z y a ş ı   d ö k e n i   y o k.’ (1922) Yürekle...', ARRAY['Türk Edebiyatı','Şiir','Anna Ahmatova']::text[], 8.5, '{"poet":"Anna Ahmatova","poet_slug":"anna_ahmatova","theme":"Türk Şiiri","is_hero":false,"total_lines":23}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUSUF ALTUNEL', 'yusuf-altunel-yusuf-altunel-276m8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünleme Düşleri, Yusuf Altunel, Virtüel Yayınları, Mayıs 2000
içmişim içmişim sırnaşmalar
dolmuşum
sevda badeleri çekmişim arlanmazlık testilerini kırıp
dolunaylı geceleri şiir şarabıyla çekmişim
coşku kayığım parçalanmış hasret kayalıklarında
ıssız aşk adacığında mahsur kalmış gemim
ayrılık zemherisi gecelerde üstüm açılmış
hayırsız sevgililerden bana mahzunluğum kalmışVirtüel
Yayınları''nca yayımlanan ikinci şiir kitabi ise şair Yusuf Altunel''e ait. Geleneksel
şiir ile reel hayat arasındaki ince çizginin ayrımında olan şair Altunel de ilk
kitabı olan &quot;Hüzünlenme Düşleri&quot;nde, kendi yaşam kozasından derlediği ve
sözün imbiğinden süzerek yeniden kurguladığı kendine ait bir dilin oluşumunun
ipuçlarını veriyor. Şiirini çelişkiler üzerine kuran şair Altunel, yaşarken çoğu kez farkına varmadığımız
ayrıntılar ile hemen hepimizin hayatını acıtan gerçekleri, birbirlerine yakın
olmayan sözcüklerle betimliyor. Şair Altunel, daha bu ilk kitabında, kendisinden', 'Hüzünleme Düşleri, Yusuf Altunel, Virtüel Yayınları, Mayıs 2000 içmişim içmişim sırnaşmalar dolmuşum sevda badeleri çekmişim arlanmazlık tes...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Altunel']::text[], 8.5, '{"poet":"Yusuf Altunel","poet_slug":"yusuf_altunel","theme":"Türk Şiiri","is_hero":false,"total_lines":18}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUSUF HAYALOĞLU', 'yusuf-hayaloglu-yusuf-hayaloglu-ok9e2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözleri İntihar Mavi, Yusuf HAYALOĞLU,
Anka Yayınları, 2002
...
Kalacak tüm izlerin hayatımda.
Gözümden bir damla yaş,
Sızlayıp resmine aktığında;
Bir yer bulabilsem keşke
Bir yer, seni hatırlatmayan;
Kan tarlası gelincik şafağında...
Öyle şiirler, öyle dizeler vardır
ki; yıllar geçse bile,
nasıl olup da aklınızın bir köşesinde kaldığına şaşarsınız.', 'Gözleri İntihar Mavi, Yusuf HAYALOĞLU, Anka Yayınları, 2002 ... Kalacak tüm izlerin hayatımda. Gözümden bir damla yaş, Sızlayıp resmine aktı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf_hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUVA', 'yuva-aziz-nesi-n-vhpth', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanyana geldikçe daha uzak
Birlikteyken daha kimsesiz
Bir ağırı sızım sızım yeri belirsiz
O da yalnız
Ben de yalnız
Acılar tütüyor bacamızdan
Görünmeyen taş duvarlar örmüşüz
Duvar olduk kendimize kendimiz
Ne yana dönsek
Kendimize çarparız', 'Yanyana geldikçe daha uzak Birlikteyken daha kimsesiz Bir ağırı sızım sızım yeri belirsiz O da yalnız Ben de yalnız Acılar tütüyor bacamızda...', ARRAY['Türk Edebiyatı','Şiir','Aziz Nesi̇n']::text[], 8.5, '{"poet":"Aziz Nesi̇n","poet_slug":"aziz_nesin","theme":"Türk Şiiri","is_hero":false,"total_lines":12}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUVARDASIN...', 'yuvardasin-umut-taydas-xp9ts', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '"Şiar''a..."
Tadı kalmadı bu kimsesizliğin,
tarifsiz uzaklıklarda ve ıssız coğrafyalarda
bir batıya göçtür yaşadığımız.
artık yaşlandım iyice ve yaslandım derme çatma duvarlara,
sessizlik can yoldaşım,
hayatımdaki tek canlı şey kum saati,
tik-taklarından biliyorum, hayatta olduğunu
safi terledim...
ağırdan alıyorsun, ağır adımlarla yaklaşıyorsun ama
tüm bu ağırlıkları ben taşıyorum,
üzerime basıyorsun, umudumu eziyorsun,
bilerek veya bilmeden; umursayacak durumda değilim,
solgun bir güne girmek üzereyim,
solgun bir hayatın içinde,
henüz vitamin bir umuda gebeyim,
biliyorum içimde ölecek,
biliyorum bir ölü boğum olacak, kurulacak düş,
durulacak hedefsiz bakışlara dönecek gözlerim,
aramayacaksın, adım gelmeyecek aklına,
hiç bir ses yokmuş gibi uyuyacaksın,
beni bu feryadın içinde şifasız bırakarak.
sabaha döndüm yüzümü, sabahlar karanlıktır,
güneşleri vardır, gövdelerinde ama paylaşmazlar,
bir güneş, bir sabahla bir olup,
üzerime gelir, gözlerimi acıtır, kızarsa canımı yakar,
bir güneş kavurur geleceğimi,
sen o sabah da gelmezsin,
uyursun, uykuya muhtaç bir çocuk gibi
bilirsin olacakları, ama bir çocuk gibi tepkisiz durur hayatın,
bense yalanım sanki, öyle ki yanacağım.
lanetlenmiş bir ülkeymişim gibi uzağımda durursun,
bütün yolları kapatırsın, sesimi kesersin, yokluğunu atarsın ortaya,
bilmem gerekeni,
dayanılmaz...
dayanamam ben de,
ve safir sebepsiz, savururum kendimi, varlığımı atarım ortaya,
oradan oraya, bilmeden ve habersiz,
duymadan ve çaresiz,
muhtaç ama mahkum;
bir odanın duvarları, tırnaklarımın arasında,
bu dünyanın kiri göğsüme bulaşmış,
bir şairin sesi, hırıltılarımda,
bu şehri deviriyorum,
iyi ki yoksun, iyi ki uzaktasın
iyi ki sırtını dönüp de hayata,
"yangınım" gamzelerini bırakmayacaksın,
bu ucube yaşayışta, bu aymaz çaresizlikte, bu viran yenilmişlikte,
iyi ki benimle olmayacaksın...
birazdan savuracağım gözlerimi, görmeye yok mecalim,
sökeceğim pencereleri, kıracağım kirişleri,
omuzlarım duvarları, azad ederim eve hapsettiğim havayı da,
bunca kırbaçlandım, şaha kalkar bir kez de ben vururum dünyaya,
tastamam küser, uzaklaşır, kaçar gider;
seninle gider,
boşlukta kalırım, bu ömür ölümü öğrenene kadar.
Umut "Dumut" Taydaş
16.05.00 - 20:37
"Bu dünyaya sergüzeşttir yaşayışım, dünya keyif almayı istedikçe..."', '"Şiar''a..." Tadı kalmadı bu kimsesizliğin, tarifsiz uzaklıklarda ve ıssız coğrafyalarda bir batıya göçtür yaşadığımız. artık yaşlandım iyice...', ARRAY['Türk Edebiyatı','Şiir','Umut Taydaş']::text[], 8.5, '{"poet":"Umut Taydaş","poet_slug":"umut_taydas","theme":"Türk Şiiri","is_hero":false,"total_lines":61}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YUVARLAĞIN KÖŞELERİ', 'yuvarlagin-koseleri-ozdemir-asaf-gm3ii', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşka gönül ile düşersen yanarsın.
Zeka ile düşersen kavrulursun.
Akıl ile düşersen çıldırırsın.
Duygu ile düşersen gülünç olursun.
Aşka düşmezsen kalabalığa karışırsın, ezilirsin.
Sersem sersem bakınıp durma bir yol seç.', 'Aşka gönül ile düşersen yanarsın. Zeka ile düşersen kavrulursun. Akıl ile düşersen çıldırırsın. Duygu ile düşersen gülünç olursun. Aşka düşm...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir_asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YÜZÜ OLAN HALK', 'yuzu-olan-halk-mehmet-taner-fsig6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '"Ah bilirim de yolları
Varamam, Kurtuba'' ya"
Su arıtan halk,
Yüze bakan: Yüzü olan halk.
Uyağın titreşimini algılayan
Binanın duruşuna göz süzen
Duru havuzlarda peygamberleri yüzen
Uzağın burgacını yargılayan halk.
Dağın tasını bulan.
Barışığız seninle
Hem o koyda, hem bu koyda;
Zaten barışığız ama
Bir türlü varamam
Çıplak Kurtuba''ya;
Kül baraka, külden çakıl
Karşılar her yerde bizi.
İççekişlerimizi durduramaz hiçbir ada.', '"Ah bilirim de yolları Varamam, Kurtuba'' ya" Su arıtan halk, Yüze bakan: Yüzü olan halk. Uyağın titreşimini algılayan Binanın duruşuna göz s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taner']::text[], 8.5, '{"poet":"Mehmet Taner","poet_slug":"mehmet_taner","theme":"Türk Şiiri","is_hero":false,"total_lines":19}'::jsonb) ON CONFLICT (slug) DO NOTHING;
