INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'akbabaların dansı', 'akbabalarin-dansi-asli-dede-6y5l7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bütün gece dinleyeceğim çığlıklarını akbabaların
dolanıp duracaklar üstünde şehrin
şehrimin
şehrimizin
şehirlerinin
paylaşıyoruz aynı sokakları, caddeleri,
yokuşları, inişleri
gelenleri, gidenleri
düşünüyorum
paylaşımı, mana ve ehemmiyetini
bir de ayıklamayı,
