INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ömür gurbet', 'bir-omur-gurbet-mahmut-kasapoglu-63j34', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan aynı, devran başka,

Toprak aynı, harman başka,

Gönül aynı, meydan başka,

Dost değişti, hâl değişti.

Yurdum kaldı uzaklarda,

Gözüm kaldı o dağlarda,

Adım kaldı sokaklarda,

Ayağımda yol değişti.

Elim işte, gönlüm yârda,

Dua ettim her bir darda,

Ekmek için bu diyarda,

Cebimdeki pul değişti.

Dost aradım gurbet elde,

Ses aradım kuru dilde,

Bir dildaş yok koca ilde,

Ağzımdaki bal değişti.

Erbil''in çay kokusunu,

Kalenin taş dokusunu,

Damlarda yaz uykusunu,

Aradım da yel değişti.

Akşam çöker pencereme,

Hasret düşer hançereme,

Türkü konar her perdeme,

Türküdeki dil değişti.

Saçlarıma karlar düştü,

Gençliğim bir tatlı düştü,

Ayna bana bugün küstü,

Takvimimde yıl değişti.

Sazım kaldı o duvarda,

Ben savruldum rüzgârlarda,

Bir yâr bekler o diyarda,

Gönlümdeki tel değişti.

Bir gün döner miyim bilmem,

Dönsem eski yeri bulmam,

Yâri sorsam, cevap almam,

Çınardaki dal değişti.

Ne unuttum doğduğumu,

Ne kaybettim olduğumu,

Gurbet tarttı duruşumu,

İnsan aynı, el değişti.', 'İnsan aynı, devran başka, Toprak aynı, harman başka, Gönül aynı, meydan başka, Dost değişti, hâl değişti. Yurdum kaldı uzaklarda, Gözüm kald...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-omur-gurbet-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmez Olsaydım', 'sevmez-olsaydim-livaneli-06jab', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ŞİİR YAZARI:@LİVANELİ_0853 KALEMİNDEN✍🏿

Sevmez Olsaydım

​Gönlümün kapısını açtığım güne
Seni ilk defa görüp seçtiğim güne
Aşkının zehrini içtiğim güne
Laf anlatamadım sevmez olsaydım
​Derdini derdime ortak eyledim
Ömrümü yoluna feda eyledim
Kendimi kendime düşman eyledim
Aklımı dinleyip sevmez olsaydım
​Gözlerin ufkumda batan bir güneş
İçimde sönmeyen korlanan ateş
Buldum sanmıştım ruhuma bir eş
Yalnız kalsaydım da sevmez olsaydım
​Gülüşün sahteymiş sözlerin yalan
Bana o günlerden hüsrandır kalan
Gençlik çağımıdır elimden alan
Zamana yenilip sevmez olsaydım
​Umutlar besledim yarınlarıma
Adını kazıdım tüm anılarıma
Ortak olamadın acılarıma
Kendi külümde yanıp sevmez olsaydım
​Bir damla vefayı çok gördün bana
Ne yaptıysam yaranamadım sana
Kırık bir kalp kaldı şimdi yanıma
Dünyam yıkılsaydı sevmez olsaydım
​Baharı beklerken kışa büründüm
Aşkının elinden yandım kavruldum
Gurbet ellerinde yelle savruldum
Toprak olsaydım da sevmez olsaydım
​Adını anarsam dilim kurusun
Gittiğin yollarda gölgen kurusun
Yüreğin sızlasın benzinin solsun
Seni tanımayıp sevmez olsaydım
​Gözümden akan o yaşlara yazık
Sana inandığım aşklara yazık
Kaderin attığı kazığa yazık
Bahtıma küsüp de sevmez olsaydım
​Her gece resmine bakıp ağladım
Karaları döşüme sarıp bağladım
Ciğerimi kor ateşle dağladım
Uykusuz kalıp da sevmez olsaydım
​Ne arayan kaldı ne soran beni
Görenler sanıyor bir deli fani
Hani o verdiğin sözlerin hani
Sözüne kanıp da sevmez olsaydım
​Bir masal yarattım kendi kendime
Sığmadım taştım ben kendi bendime
Çare bulamadım hiç derdime
Derde düşmeyip de sevmez olsaydım
​Yılları harcadım senin uğruna
Taş bastım şu garip bağrına
Dönmedin kalbimin derin çağrına
Sessiz kalsaydım da sevmez olsaydım
​Gönül sarayım yıkıldı gitti
Bu büyük sevda da burada bitti
Ettiğin zulümler canıma yetti
Sana tapıp da sevmez olsaydım
​Artık ne sevgin var ne de bir izin
Kör olsun görirse seni bu gözüm
Sana söylenecek kalmadı sözüm
Susup otursaydım sevmez olsaydım
​Son sözüm olsun bu yalan dünyaya
Benzerdi aşkımız biten rüyaya
Gerek yok artık başka hülyaya
Seni sevmez olsaydım sevmez olsaydım.

18.09.2021✍🏿
Saat:10.50', 'ŞİİR YAZARI:@LİVANELİ_0853 KALEMİNDEN✍🏿 Sevmez Olsaydım ​Gönlümün kapısını açtığım güne Seni ilk defa görüp seçtiğim güne Aşkının zehrini i...', ARRAY['Türk Edebiyatı','Şiir','Livaneli']::text[], 8.5, '{"poet":"Livaneli","poet_slug":"livaneli","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sevmez-olsaydim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Var Ya Sen', 'sen-var-ya-sen-livaneli-6ogj3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ŞİİR YAZARI:@LİVANELİ_0853 KALEMİNDEN✍🏿

Sen Var Ya Sen

​Bir gizli hecesin dilimin ucunda
Ne zaman konuşsam adın dolanır
Karanlık gecenin kör avucunda
Seninle uyanan düşler inanır
​Bakışın bir kor gibi yakar içimi
Sorarım yollara bilmez yerini
Çözemedim gitti bu kör düğümü
Rüzgârlar savurur gizemlerini
​Adını anınca durur zamanlar
Gökyüzü boyanır senin rengine
Derdimi ne kuşlar ne taşlar anlar
Ruhum rastlamadı eşi dengine
​Bir varsın bir yoksun hayat sahnesinde
Gölgeni ararım kuytu köşe dökümünde
Bir şarkı fısıldar rüzgâr sesinde
Hapsolmuş kalmışım senin hükmünde
​Gözlerin bir deniz derin ve dipsiz
Kürek çekiyorum meçhule doğru
Bu koca şehirde kalmışım sessiz
Yüreğimde saklı en büyük soru
​Sen var ya sen bir bilmece gibisin
Çözdükçe dolaşan yumağa benzer
Gönlümün sararmış son yaprağısın
Gelişin bahara yaza benzer
​Adımlarım sana doğru bükülür
Yürüdüğüm yollar sana çıkar hep
Gözlerimden sessiz yaşlar dökülür
Bu garip halime sensin tek sebep
​Bir bakışın yetti altüst etmeye
Kurduğum dünyayı yıktın tek seferde
Gerek yok artık uzağa gitmeye
Aşkının izi var bastığın yerde
​Geceleri yıldızlara sorarım seni
Anlatırlar bana parlaklığını
Unutmak mümkün mü o gülüşünü
Ruhuma bıraktığın o sıcaklığını
​Sen var ya sen hem dertsin hem derman
Yarayı açan da sensin saran da
Seninle yazıldı bu son ferman
Kayboldum seninle geçen zamanda
​Bir masal gibisin sonu gelmeyen
Her satırın ayrı bir dert bir çile
Kıymetini bilip kadrini bilmeyen
Düşer elbet dilden dile bu hale
​Yüreğim bir liman geminse sensin
Dalgalar vurdukça sığınır sana
İsterim ki bu can sende tükensin
Çok görme bu aşkı ne olur bana
​Sessizce gelirsin yine aklıma
Bir sızı yerleşir sol yanıma
Mecalim kalmaz hiç ağlamaya
Yalnızlık çöker o an dünyama
​Şimdi uzakta bir hayal misin
Yoksa içimde duran bir nefes
Gönlümün sustuğu o yer misin
Senden başkasına kapalı bu kafes
​Sen var ya sen unutulmaz sızım
Alnıma yazılmış en kara yazı
Seninle başladı benim son yazım
Bitmedi kalbimin ince sızısı
​Son kıta bitiyor tükenir sözler
Kalem de yoruldu seni yazmaktan
Yolunu gözleyen bu yorgun gözler
Vazgeçmez asla seni aramaktan.

21.11.2020✍🏿
Saat:20.39', 'ŞİİR YAZARI:@LİVANELİ_0853 KALEMİNDEN✍🏿 Sen Var Ya Sen ​Bir gizli hecesin dilimin ucunda Ne zaman konuşsam adın dolanır Karanlık gecenin kö...', ARRAY['Türk Edebiyatı','Şiir','Livaneli']::text[], 8.5, '{"poet":"Livaneli","poet_slug":"livaneli","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sen-var-ya-sen-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alparslan Ölmedi', 'alparslan-olmedi-kul-h-mid-xtzej', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Allah''ın Arslanı
Alplerin de Parslanı
Alpleri Arslan sevdi
Kendisi de Parslanı
Bana vurun hançeri
Ölmesin Alp Arslanı

Alp Arslanı ey Alp Arslanı
Bir Parsı ile dalıp
Bin Arslanın arasından
Alan Alpını

Alp Arslanı ey Alp arslanı
Bana vurun hançeri
Allansın Parslanı
Allansın Arslanı
Size yemin ederim
Ölmedi Alparslan
Yaşıyor Al Parslanları

Alparslan ey Alparslan
Bir Alpı olam bir de Parslanı
Bana vurun hançeri
Yaşasın Alp Arslanı
Bin hançer vursalar da
Ölmez Şarkın Arslanı
Size yemin ederim
Ölmedi Alparslan
Yaşıyor Al Parslanları..', 'Allah''ın Arslanı Alplerin de Parslanı Alpleri Arslan sevdi Kendisi de Parslanı Bana vurun hançeri Ölmesin Alp Arslanı Alp Arslanı ey Alp Ars...', ARRAY['Türk Edebiyatı','Şiir','Kul Hâmid']::text[], 8.5, '{"poet":"Kul Hâmid","poet_slug":"kul-h-mid","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/alparslan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı 10', 'otizmli-yavuz-un-defteri-cantasindaydi-10-mehmet-tevfik-temizturk-3-8db9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Katmamış da olurduk, bol sayıda hatayla,

Daha başka bir hâlden sıkıntı yaşatmayla,

Valla hocam diyerek yorgunluk belirtmekle,

Ceviz meselesiyle Mersin’den bahsetmekle,

Benden kaynaklı kusura bakmayın demekle,

Sorun değil dersek de üzgünlük belirtmekle…', 'Katmamış da olurduk, bol sayıda hatayla, Daha başka bir hâlden sıkıntı yaşatmayla, Valla hocam diyerek yorgunluk belirtmekle, Ceviz meselesi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  9', 'otizmli-yavuz-un-defteri-cantasindaydi-9-mehmet-tevfik-temizturk-3-3i5dk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çanta iki gözlüydü fermuarlı şekilde,

İyi bakılmış olsa idi defter içerisinde,

Anne mahcup olmuştu sürekli mesajlarla,

Ya! Diye hayret edip, kusura bakmalarla,

Bir sıkıntı da yoktur, şahsım alınmamıştır,

Bunlar rastladıklarım hiç kırılmamışımdır…', 'Çanta iki gözlüydü fermuarlı şekilde, İyi bakılmış olsa idi defter içerisinde, Anne mahcup olmuştu sürekli mesajlarla, Ya! Diye hayret edip,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  8', 'otizmli-yavuz-un-defteri-cantasindaydi-8-mehmet-tevfik-temizturk-3-clyd9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yavuz okula gelmiş çantası açılmıştı,

Defter ve kalemlikler ortaya çıkmıştı,

Çantaya bakılmamış defter çantada idi,

Kalemlik buna dâhil her biri içindeydi,

Dedik, Yavuz’a ait, defteri ince gözde,

Kalemlik ve cüzdanı çantasının içinde…', 'Yavuz okula gelmiş çantası açılmıştı, Defter ve kalemlikler ortaya çıkmıştı, Çantaya bakılmamış defter çantada idi, Kalemlik buna dâhil her ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  7', 'otizmli-yavuz-un-defteri-cantasindaydi-7-mehmet-tevfik-temizturk-3-1guub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '“Belki eve çıkarmıştır,” laflarını vermekle,

Kalemlik ve defteri evde yok lafı ile

Şahsım suçlanmaktaydı incinecek şekilde,

Çanta boş geldi, diye dikkatleri çekmede,

Evdedir desek bile teselli eklemekle,

Sonraki mesajlara da dikkat etmemekle…', '“Belki eve çıkarmıştır,” laflarını vermekle, Kalemlik ve defteri evde yok lafı ile Şahsım suçlanmaktaydı incinecek şekilde, Çanta boş geldi,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  6', 'otizmli-yavuz-un-defteri-cantasindaydi-6-mehmet-tevfik-temizturk-3-jayk7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Allah Allah neyse bir daha bakalım,” deyip,

“Dikkat mi edemedim,” lafı sözü ekleyip,

Dede geldiğinde içindeydi, denilse de,

Suçlanır hâlde idim, telaşlı bir şekilde,

Defterler gelmemiştir, lafları sıralanır,

İşlemediğim günahım alındıkça alınır…', '“Allah Allah neyse bir daha bakalım,” deyip, “Dikkat mi edemedim,” lafı sözü ekleyip, Dede geldiğinde içindeydi, denilse de, Suçlanır hâlde ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Das Problem des Übels: Das Wissen des Menschen oder die Weisheit Allahs?', 'das-problem-des-ubels-das-wissen-des-menschen-oder-die-weisheit-allahs-muhammed-ridvan-gizri-knb8c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eine der ältesten und eindringlichsten Fragen lautet: Wenn Allah gut ist, wenn seine Macht über alles reicht und er alles weiß, warum gibt es dann Übel in der Welt? Diese Frage stand jahrhundertelang im Zentrum der Theodizee-Debatten. Ungläubige benutzten sie als Waffe gegen den Glauben, Gläubige taten sich schwer, eine Antwort zu finden. Doch die Frage selbst beruht von Anfang an auf einer falschen epistemologischen Annahme: Der Mensch glaubt zu wissen, was das, was er sieht, in Wirklichkeit ist. Im Folgenden wird gezeigt, dass das Problem des Übels in Wahrheit nicht das Wissen Allahs, sondern die Grenze des menschlichen Wissens offenlegt.

Die Grenze des Wissens: Die grundlegende epistemologische Schwäche des Menschen

Jede Diskussion muss zunächst ihre Begriffe klären. Was meinen wir, wenn wir „Übel“ sagen? Im Alltag umfasst das Übel alles, was der Mensch in einem bestimmten Augenblick und aus einem bestimmten Blickwinkel als schädlich, schmerzhaft oder sinnlos empfindet. In dieser Definition steckt jedoch eine ernste epistemologische Falle: Wenn der Mensch ein Ereignis beurteilt, legt er nur die Seite zugrunde, die ihn selbst berührt, nur den Moment, den er erlebt, und nur die Folgen, die er sehen kann. Das menschliche Wissen ist strukturell mit drei großen Beschränkungen behaftet.

Die erste ist die zeitliche Beschränkung. Der Mensch kann nur wenige Jahrzehnte seines Lebens überblicken. Die Vergangenheit erinnert er nicht vollständig, die Zukunft kann er nicht wissen. Um aber darüber zu urteilen, ob ein Ereignis „schlecht“ oder „gut“ ist, müsste man seine Folgen über die gesamte Zeitdimension hinweg sehen. Der Schmerz eines Kindes während einer Operation erscheint im Augenblick als absolutes Übel. Wenn das Kind genesen ist, versteht man jedoch, dass dieser Schmerz einen Sinn hatte. Die Frage lautet: Wenn die Genesung des Kindes erst Jahre nach der Operation einträte und das Kind stürbe, ohne sie zu erleben, würde das die Operation sinnlos machen? Nein. Der Sinn hängt nicht davon ab, dass der Mensch ihn sieht.

Die zweite ist die räumliche und kausale Beschränkung. Der Mensch kann nur die Wirkungen eines Ereignisses in seiner unmittelbaren Umgebung sehen. Doch jedes Ereignis im Universum ist Teil eines Kausalgeflechts, das mit unzähligen anderen Ereignissen verwoben ist. Ein Krieg, der an einem Ort ausbricht, kann in einer fernen Region ein Friedensabkommen auslösen, daraus eine technische Erfindung und daraus, Generationen später, ein Medikament, das Millionen von Menschen rettet. Diese Kette in ihrer Gesamtheit zu überblicken, übersteigt die Fähigkeiten des Menschen bei Weitem.

Die dritte ist die Beschränkung der Perspektive. Der Mensch beurteilt ein Ereignis unvermeidlich aus dem Fenster seines eigenen Ichs. Seinen eigenen Schmerz nimmt er als universelle Katastrophe wahr, seinen eigenen Verlust als absolutes Übel. Dasselbe Ereignis kann für andere Wesen, für andere Zeiten und in anderen Zusammenhängen ganz andere Bedeutungen haben.

Kommen diese drei Beschränkungen zusammen, ergibt sich ein auffälliges Paradox: Wenn der Mensch sagt „Dieses Ereignis ist im absoluten Sinn schlecht“, erhebt er mit seinem begrenzten Wissen in Wahrheit einen unbegrenzten Anspruch. Das ist, als würde man ein Kunstwerk aus nächster Nähe betrachten und sagen: „Dieses Bild ist hässlich, hier ist ein schwarzer Fleck.“ Betrachtet man das Bild jedoch als Ganzes, zeigt sich, dass dieser schwarze Fleck ein unverzichtbarer Teil der Komposition ist.

Das Gute im scheinbar Schlechten: Die ontologische Analyse

Der zweite Einwand gegen das Problem des Übels ist nicht bloß philosophischer, sondern empirischer Natur. Geschichte und Wissenschaft haben immer wieder gezeigt, dass vieles, was der Mensch für „schlecht“ hält, unabhängig von Kontext und Zeit nicht schlechthin schlecht ist.

Beispiel aus der Natur: Schlangen galten in der gesamten Menschheitsgeschichte als Symbol des Bösen. Sie beißen, vergiften, können töten. Zugleich schützen Schlangen aber landwirtschaftliche Flächen, indem sie die Nagerpopulation kontrollieren, und bilden ein entscheidendes Glied der Nahrungskette. Darüber hinaus wird Schlangengift in der modernen Medizin in der Blutgerinnungsforschung, im Kampf gegen Herz-Kreislauf-Erkrankungen und bei der Entwicklung verschiedener Medikamente eingesetzt. Die vollständige Ausrottung der Schlangen in einer Region würde deren ökologisches Gleichgewicht ernsthaft stören. Ein Wesen, das wir für „böse“ halten, dient also in Wirklichkeit unzähligen guten Zwecken.

Beispiel Schwein: Das Schwein, dessen Verzehr im Islam verboten (haram) ist, wurde von vielen Menschen als rein schädliches Wesen betrachtet. Die Ähnlichkeit seiner Organe mit der menschlichen Physiologie hat es jedoch zu einem unverzichtbaren Werkzeug der Medizin gemacht. Herzklappentransplantationen, Diabetesforschung, chirurgische Ausbildungsmodelle, Xenotransplantation und CRISPR-Genomeditierung werden zu einem großen Teil an Schweinen betrieben. Ein Wesen, bei dem der Mensch fragt „Wozu ist das nütze?“, rettet das Leben anderer Menschen.

Beispiel Krankheit und Katastrophe: Im Laufe der Geschichte haben große Seuchen Millionen von Menschen das Leben gekostet. Diese Tode sind unbestreitbar tragisch. Dieselben Seuchen haben aber auch den Boden für die Entstehung der Immunologie, die Entdeckung der Antibiotika, höhere Hygienestandards und die Entwicklung medizinischer Institutionen bereitet. Erdbeben haben Tausende das Leben gekostet; zugleich führten sie zur Entwicklung widerstandsfähigerer Bautechnologien und zu stärkeren Maßnahmen der Stadterneuerung. Kriege haben die größten Leiden der Menschheitsgeschichte verursacht; manche Kriege haben jedoch Tyrannei beendet, neue politische Gleichgewichte geschaffen sowie die Anerkennung von Rechten und die Herausbildung völkerrechtlicher Normen beschleunigt.

Keines dieser Beispiele macht den Schlangenbiss, die Krankheit oder den Krieg im Kern gut. Darum geht es nicht. Es geht um Folgendes: Ein großer Teil dessen, was schlecht erscheint, dient in Zusammenhängen, die der Mensch nicht sieht, dem Guten. Das ist kein Zufall, sondern hat System. Im Aufbau des Universums wirken ein Gleichgewicht, eine Spannung, ein Prinzip der Ergänzung. Die Metapher der „unsichtbaren Hand“ in Adam Smiths Wirtschaftstheorie, wonach Individuen, die nur ihren eigenen Vorteil verfolgen, ungewollt das Gemeinwohl mehren, ist die Erscheinungsform dieses ontologischen Prinzips auf sozialer Ebene. Selbst diejenigen, die Böses tun, können bisweilen, ohne es zu merken, zum Mittel des Guten werden. Die in der Sure al-Kahf des Heiligen Koran erzählte Geschichte unseres Propheten Mose und des weisen Mannes veranschaulicht genau diese Wahrheit auf dramatische Weise: Ein Kind zu töten und eine Mauer auszubessern, erscheint dem Anschein nach sinnlos, ja grausam. Auch unser Prophet Mose, obwohl er ein Prophet war, erhob gegen diese Handlungen Einspruch. Als jedoch ihre Weisheit erklärt wurde, zeigte sich, dass jede Handlung einem tiefen Guten diente. Die Botschaft dieser Geschichte ist klar: Die Grenze des Wissens bestimmt die Grenze des Urteils.

Ohne Gegensatz kein Sinn: Die phänomenologische Dimension

Der dritte Einwand gegen das Problem des Übels betrifft die Struktur des menschlichen Auffassungsvermögens. Der menschliche Geist konstruiert Sinn durch Gegensätze. Das ist kein Mangel des Verstandes, sondern ein grundlegendes Strukturmerkmal des Bewusstseins. Wärme kann man ohne die Erfahrung von Kälte nicht vollständig begreifen. Den Wert des Lichts erkennt man nicht, ohne der Dunkelheit begegnet zu sein. Was Gesundheit ist, spürt man nicht, ohne je krank gewesen zu sein. Die Freude des Wiedersehens versteht man nicht, ohne den Schmerz der Trennung erlebt zu haben. Die Größe einer Gabe erfasst man nicht, ohne Hunger gelitten zu haben. Diese phänomenologische Tatsache verlangt, dass wir die Frage nach dem Dasein des Übels in einem ganz anderen Licht sehen. Was würde Gesundheit bedeuten, wenn es nie Krankheit gäbe? Was würde Geduld besagen, wenn es nie Schwierigkeiten gäbe? In welchem Boden sollte die Gerechtigkeit Wurzeln schlagen, wenn es nie Unrecht gäbe? Wie würde man den Wert der Liebe verstehen, wenn es nie Verlust gäbe?

Hier ist eine entscheidende Unterscheidung hervorzuheben: Diese Beobachtung besagt nicht, dass das Übel gut sei. Das Übel ist in seinem Wesen schlecht. Schmerz ist Schmerz, Tod ist Tod, Grausamkeit ist Grausamkeit. Man kann aber sagen, dass das Fehlen des Übels auch das Erkennen des Guten aufheben würde. Der Gegensatz ist eine sowohl semantische als auch existenzielle Notwendigkeit. Deshalb muss man das Dasein des Übels nicht nur als Problem lesen, sondern zugleich als strukturelle Bedingung der Welt des Sinns.

Die Ontologie der Prüfung: Über das Wesen der Welt

Der vierte Einwand gegen das Problem des Übels ist eine theologische Klärung dessen, was die Welt ist. Wer das Problem des Übels vorbringt, trägt weitgehend die folgende implizite Annahme in sich: „Wenn Allah gut ist, hätte er eine Welt erschaffen müssen, in der sich jeder zu jeder Zeit wohlfühlt, in der kein Schmerz erlitten wird und kein Verlust geschieht.“ Mit anderen Worten: Unabhängig vom Menschen hätte ein automatischer Mechanismus des Glücks eingerichtet werden müssen. Diese Annahme steht jedoch in direktem Widerspruch zum Weltverständnis des Islam. Im Heiligen Koran wird die Welt nicht als Paradies beschrieben. Im Gegenteil: Die Welt ist ein vorübergehender Aufenthaltsort, den der Mensch in der Prüfung verbringt. Die Menschen werden sowohl mit Wohlergehen als auch mit Not geprüft. Krankheit, Armut, Verlust und Katastrophen sind Teile dieser Prüfung. In Vers 155 der Sure al-Baqara heißt es ausdrücklich: „Wahrlich, Wir werden euch mit etwas Furcht und Hunger sowie mit Verlust an Besitz, Leben und Früchten prüfen. Und verkünde den Geduldigen frohe Botschaft.“ Vers 216 der Sure al-Baqara fasst diese Frage überaus prägnant zusammen: „Der Kampf ist euch vorgeschrieben, auch wenn er euch zuwider ist. Doch vielleicht ist euch etwas zuwider, was gut für euch ist, und vielleicht liebt ihr etwas, was schlecht für euch ist. Allah weiß, ihr aber wisst nicht.“ Die Bedeutung dieses Verses ist groß. Er erklärt ausdrücklich, dass die Urteile des Menschen über Gefallen und Missfallen nicht der Maßstab der Wirklichkeit sind. Der Mensch hält für gut, was er liebt, und für schlecht, was er nicht liebt. Gut und Böse hängen jedoch nicht vom Gefühlszustand des Menschen ab, sondern vom Wissen Allahs. Im Rahmen der Ontologie der Prüfung betrachtet, ist die Schwierigkeit nicht der Beweis eines Irrtums, sondern der Boden, auf dem Sinn entsteht. Geduld ist ohne Schwierigkeit bedeutungslos. Opferbereitschaft ist in einer Welt ohne Mühsal wertlos. Mut lässt sich ohne Gefahr nicht begreifen. Barmherzigkeit kann man ohne Leid nicht üben. Folglich könnte in einer „guten“ Welt, so wie der Mensch sie sich vorstellt, keine dieser moralischen Tugenden existieren. Eine Welt ohne Schmerz wäre zugleich eine Welt ohne Tugend.

Die Neurahmung der Gerechtigkeitsfrage: Die Dimension des Jenseits

Die vielleicht stärkste Form des Problems des Übels lautet: Warum leidet ein unschuldiges Kind? Warum erleidet ein Mensch ohne jede Schuld ein Unglück? Das Gewicht dieser Frage zu unterschätzen, ist unmöglich. Die Antwort darauf führt jedoch zwangsläufig zur Frage, ob der Tod das Ende ist. Wenn der Tod ein absolutes Ende ist und es außerhalb dieses Lebens keinerlei Mechanismus der Gerechtigkeit gibt, dann stellt unschuldiges Leiden tatsächlich ein großes Problem dar. Doch der islamische Glaube an das Jenseits (Achira) verändert diese Frage von Grund auf. Wenn dieses Leben nicht die ganze Geschichte, sondern nur ein Kapitel ist; wenn der Tod kein Abschluss, sondern ein Übergang ist; wenn es einen Tag der Abrechnung gibt, an dem jedes Unrecht seine Vergeltung findet, dann kann man nicht sagen, der Schmerz in dieser Welt sei „sinnlos“. So wie es ein epistemologischer Fehler ist, einen Film nur einige Minuten aus der Mitte anzuschauen und zu sagen „Dieser Film ist sinnlos, die Ereignisse entwickeln sich zufällig“, so ist es derselbe Fehler, ein endgültiges Urteil über eine unvollendete Geschichte zu fällen. Das Problem des Übels begeht größtenteils diesen Fehler: Es schaut nur auf die irdische Dimension des Lebens und fällt, ohne das Jenseits zu berücksichtigen, das Urteil des „absoluten Übels“. In diesem Zusammenhang gewinnt auch die Wahrheit Bedeutung, dass aller Besitz Allah gehört. Das, worüber der Mensch klagt, es sei ihm „genommen“ oder „nicht gegeben“ worden, gehörte ihm nie wirklich. Der Schöpfer hat das Verfügungsrecht über das, was er geschaffen hat. Gerechtigkeit wird nicht dadurch verletzt, dass der Eigentümer über sein eigenes Eigentum verfügt.

Das Paradox, in das der Atheismus gerät

Wer das Problem des Übels als Argument gegen Allah verwendet, gerät, ohne es zu merken, in ein tiefes philosophisches Paradox. Um sagen zu können, dass etwas „schlecht“ ist, braucht man einen universellen Maßstab des Guten. Das Übel lässt sich nur als Fehlen oder Verletzung des Guten definieren. Woher aber stammt dieser universelle Maßstab des Guten? In einem materiellen Universum, in einer Welt, in der nur Atome und blinde Kräfte herrschen, können „Gut“ und „Böse“ nicht als objektive Kategorien existieren. Dort gibt es nur das, „was ist“; das, „was sein soll“, gibt es nicht. Daher wird in einer atheistischen Weltanschauung der Satz „Das Leiden des Kindes ist schlecht“ im Grunde auf den Satz „Ich mag es nicht, dass das Kind leidet“ reduziert. Das ist aber die Bekundung einer subjektiven Präferenz, kein universelles moralisches Urteil. Andererseits muss derjenige, der das Argument „Es gibt Übel, also gibt es Allah nicht“ vorbringt, zugleich die Frage beantworten: „Es gibt auch Gutes, also gibt es Allah?“ Warum gibt es Liebe? Warum gibt es Barmherzigkeit? Warum gibt es Opferbereitschaft, Kunst, Musik, Gewissen? Wenn das Universum das Produkt blinder und sinnloser Kräfte ist, kann keiner dieser Begriffe eine objektive Bedeutung haben. Wer das Problem des Übels vorbringt, betrachtet nur die Hälfte des Bildes, das er problematisch findet.

Der Irrtum Iblis’ und die Falle des Selbst

Kommt man zur existenziellen und spirituellen Dimension dieser Frage, tritt ein weit tieferes Bild hervor. Die Rebellion Iblis’ gegen Allah nimmt genau die Gestalt eines solchen Einwands aus dem Problem des Übels an: „Ich wurde aus Feuer erschaffen, er aus Ton. Warum sollte ich mich vor ihm niederwerfen? Das ist nicht gerecht.“ Iblis behauptete, die verliehenen Gaben seien nicht gleich, die Hierarchie sei ungerecht. Das ist eine vollständig ichzentrierte Bewertung. Er stellte das „Ich“ in den Mittelpunkt und fällte sein Urteil, indem er auf das schaute, was „ihm gegeben“ und was „ihm nicht gegeben“ wurde. In dieselbe Falle tappen die meisten Menschen, wenn sie das Problem des Übels vorbringen: Sie erheben ihr eigenes Selbst, ihr eigenes Empfinden, ihren eigenen Verlust oder das Gefühl, das der Schmerz eines anderen in ihnen weckt, zum universellen Maßstab. Diese Sichtweise ist im Grunde eine Wiederholung der Sichtweise Iblis’. Wenn man in vier Gläser unterschiedliche Mengen Wasser füllt und sagt „Das ist ungerecht“, vergisst man, dass die Gläser in Wirklichkeit gar nicht existieren und es daher auch kein Subjekt gibt, dem Ungerechtigkeit widerfahren könnte. Wenn alle Selbste in Wirklichkeit Manifestationen des Geistes Allahs sind, worauf stützt sich dann der Anspruch „Mir wurde Unrecht getan“? An diesem Punkt tritt die mystische Dimension der Frage hinzu: Je mehr man sich vom Selbst löst und nachsinnt, desto deutlicher zeigt sich, dass sich der größte Teil des Problems des Übels aus der Illusion des Selbst speist. Wenn sowohl derjenige, der mit den Augen des anderen blickt, als auch derjenige, der mit den eigenen Augen blickt, Manifestationen desselben Seins sind, wessen Aufbegehren gegen wen sind dann Neid, Gefühl der Ungerechtigkeit und Rebellion?

Said Nursis Synthese: Die Gesichter der Schönheit in allen Dingen

Bediüzzaman Said Nursi hat den Kern dieser Frage in folgendem Satz ausgedrückt: „In allem, selbst in den hässlichsten erscheinenden Dingen, gibt es einen Aspekt wahrer Schönheit.“ Nursi entwickelt diese Feststellung weiter und spricht von zwei Arten der Schönheit: von Dingen, die an sich schön sind, und von Dingen, die dem Ergebnis nach schön sind. Der Schlamm und der Sturm, die der Frühlingsregen mit sich bringt, tragen hinter dem Vorhang das Lächeln unzähliger Blumen. Das raue Gesicht des Herbstes und die eisige Kälte des Winters schützen in Wirklichkeit die zarten Wesen und schaffen Raum für einen neuen Frühling. Man beobachtet, dass unter dem Schleier von Ereignissen wie Sturm, Erdbeben und Seuche viele geistige Samen Keime treiben. Der grundlegende Irrtum, auf den Nursi hinweist, ist folgender: Der Mensch ist zum einen zahirperest, das heißt, er bleibt am Äußeren haften; zum anderen ist er hodgâm, das heißt, er urteilt nur nach dem Ergebnis, das ihn selbst betrifft. Dabei kann der Zweck eines Wesens für den Menschen einer sein, während der Zweck, den der Schöpfer mit diesem Wesen verfolgt, tausendfach sein kann. Eine dornige Pflanze mag dem Menschen schädlich erscheinen; sie ist aber ein Glied, in dem die Macht ihres Schöpfers zur Schau gestellt wird und das Dutzenden anderen Wesen nützt.

Wessen Problem ist das Problem des Übels?

Fasst man die hier dargelegten Argumente zusammen, gelangt man zu folgendem grundlegenden Ergebnis:

Das Problem des Übels offenbart nicht die Unzulänglichkeit des Wissens Allahs, sondern die Begrenztheit des Wissens des Menschen. Aufgrund seiner zeitlichen, räumlichen und perspektivischen Beschränkungen kann der Mensch nicht genau wissen, was ein Ereignis in Wirklichkeit bedeutet. Was er sieht, ist nur eine Ecke des Bildes. Dass er in dieser Ecke schwarze Flecken sieht, bedeutet nicht, dass das ganze Bild hässlich ist. Der größte Teil dessen, was als Übel erscheint, ist entweder das Ergebnis einer aus dem Zusammenhang gerissenen Bewertung, oder die Folge davon, dass ohne Gegensatz kein Sinn konstruiert werden kann, oder eine notwendige Dimension der Prüfung, oder eine unverständliche Szene mitten in einer noch nicht abgeschlossenen Geschichte. Der Grundsatz „Vielleicht ist euch etwas zuwider, was gut für euch ist“ ist nicht nur ein Satz religiöser Ergebung, sondern zugleich Ausdruck einer starken epistemologischen Demut. Es ist eine Beobachtung, die in der Menschheitsgeschichte immer wieder bewiesen und von Wissenschaft und Geschichte immer wieder bestätigt wurde.

Das letzte Wort lautet: Wer das Problem des Übels als Einwand gegen die Gerechtigkeit Allahs vorbringt, macht in Wirklichkeit, ohne es zu merken, sein eigenes Wissen absolut und erhebt seine eigene Perspektive zum universellen Maßstab. Weisheit liegt aber genau darin, von dieser Verabsolutierung abzulassen und sagen zu können: „Ich kann es nicht wissen, Er weiß es.“ Der Name dieser Ergebung ist nicht Blindheit, sondern die Tugend eines Verstandes, der die Grenze des Wissens kennt.', 'Eine der ältesten und eindringlichsten Fragen lautet: Wenn Allah gut ist, wenn seine Macht über alles reicht und er alles weiß, warum gibt e...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/das-problem-des-ubels-das-wissen-des-menschen-oder-die-weisheit-allahs-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  5', 'otizmli-yavuz-un-defteri-cantasindaydi-5-mehmet-tevfik-temizturk-3-v0pka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anne telaşlanmıştı şahsımı suçlar hâlde,

Kalemlikten deftere lafa söz yüklemede,

“Ben mi dikkatsiz baktım o zaman” diye ekler,

Evet! Demek şart iken şahsım durum dengeler,

Der, “sıra Ekrem''e gelince topla demiştik,

Her ne eşyası varsa Yavuz için vermiştik,”

Hem biz buna eminiz bir şey unutulmadı,

Dede gelsin, gelmesin dikkat işi sağlandı...', 'Anne telaşlanmıştı şahsımı suçlar hâlde, Kalemlikten deftere lafa söz yüklemede, “Ben mi dikkatsiz baktım o zaman” diye ekler, Evet! Demek ş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  4', 'otizmli-yavuz-un-defteri-cantasindaydi-4-mehmet-tevfik-temizturk-3-g6r9h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mehmet hocam, kalem kutusu da yok,

Çantasının içinde hemen hiçbirisi yok,

Dedesini görünce fırlayarak mı çıkmış?

Defter ve kalemliği arkasında bırakmış,

Şahsımsa yanıt verir çantasında eminiz,

Parası vardır, diye kontrol bile etmişiz…', 'Mehmet hocam, kalem kutusu da yok, Çantasının içinde hemen hiçbirisi yok, Dedesini görünce fırlayarak mı çıkmış? Defter ve kalemliği arkasın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz Savaş', 'habersiz-savas-arda-oksakli-pxijr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklımla unutmaya,

Duygularımla yaşatmaya çalışıyorum seni.

Gözlerin hâlâ acı veriyor.

Ne tuhaf bir savaş, ne tuhaf bir zafer…

Kaybeden ben, kazanan yine sen.

Üstelik ne bir kılıç çektin,

Ne de tek bir kelam ettin.

Ben kendi içimde yenildim sana,

Sen habersizce kazanmaya devam ettin.

Ben sustukça içimde büyüdün,

Unutmak istedikçe biraz daha yer ettin.

Ne garip,

Ben senden vazgeçmeye çalışırken

Sen hiçbir şey yapmadan

Hayatımda kalmayı başardın.

Belki de en acısı şuydu:

Ben seni kaybettiğimi bile bile savaştım,

Sen ise hiç benim olmadığını bilmeden kazandın.', 'Aklımla unutmaya, Duygularımla yaşatmaya çalışıyorum seni. Gözlerin hâlâ acı veriyor. Ne tuhaf bir savaş, ne tuhaf bir zafer… Kaybeden ben, ...', ARRAY['Türk Edebiyatı','Şiir','Arda Okşakli']::text[], 8.5, '{"poet":"Arda Okşakli","poet_slug":"arda-oksakli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/habersiz-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  3', 'otizmli-yavuz-un-defteri-cantasindaydi-3-mehmet-tevfik-temizturk-3-6wxwa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Defter çantasındaydı dersek de yetinilmez,

Kendinden emin olup hatırlama kâr etmez,

Yarın gelsin demekle zaman gerekli idi,

Yeni defter iyi oldu, lafıyla desteklendi,

Yarın gelsin, bakarız düşünceleri ile

Esneklik geliştirip vakti ertelemekle…', 'Defter çantasındaydı dersek de yetinilmez, Kendinden emin olup hatırlama kâr etmez, Yarın gelsin demekle zaman gerekli idi, Yeni defter iyi ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı  2', 'otizmli-yavuz-un-defteri-cantasindaydi-2-mehmet-tevfik-temizturk-3-fcg4p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yeni defter koyduk der çantasının içinde,

Kalemlik de yok imiş sitemkâr şekillerde,

Çantasında yok hocam dedesi de aramış,

Her neresi var ise defterler bulunmamış,

Suçlanmakta gibiyiz yazı yazdıran benim,

Beslenmeden çantaya her biri benim işim,

Anne sinirli hâlde yanıt bekler durumda,

Şahsım emin şekilde teselli oluşturmada,

Defteri koyma hâlli delil sıralamada…', 'Yeni defter koyduk der çantasının içinde, Kalemlik de yok imiş sitemkâr şekillerde, Çantasında yok hocam dedesi de aramış, Her neresi var is...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Yavuz''un Defteri Çantasındaydı', 'otizmli-yavuz-un-defteri-cantasindaydi-mehmet-tevfik-temizturk-3-32yn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anne, kızgın bir hâlde mesajlarını ekler,

Matematik defteri okulda mı kaldı? Der,

Bitmek üzere iken çantada defterleri,

Mesaj çekme işiyle yükler endişeleri,

Arar ve bulamazmış ders işleyemiyormuş,

Dersi nerede diye merak da ediyormuş…', 'Anne, kızgın bir hâlde mesajlarını ekler, Matematik defteri okulda mı kaldı? Der, Bitmek üzere iken çantada defterleri, Mesaj çekme işiyle y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-yavuz-un-defteri-cantasindaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Dökmüyordu  5', 'otizmli-sarper-dokmuyordu-5-mehmet-tevfik-temizturk-3-ld3k7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hakka yemin etmiş öğretmenleriyle,

Okul vardı eğitimle kitabı defteriyle,

Doğruyu doğruluğu içi dışı sevgiyle,

Akıl dersen anlardı zekâ dersen yorumlar,

Bilinç dersen doğruyu doğru ile tamamlar,

Tamamı da gerekli sonrasına geçecek,

Sonrasını geçip de bir üst katı seçecek,

Üst kat yerleşim yeri alt kata hiç inmeden,

Bilinç fikri içinden, yanlışa hiç dönmeden…', 'Hakka yemin etmiş öğretmenleriyle, Okul vardı eğitimle kitabı defteriyle, Doğruyu doğruluğu içi dışı sevgiyle, Akıl dersen anlardı zekâ ders...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/otizmli-sarper-dokmuyordu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Dökmüyordu  4', 'otizmli-sarper-dokmuyordu-4-mehmet-tevfik-temizturk-3-w08bx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Otizmli denildi mi bilinç fikri gelmekte,

Bilip bilmeme fikri, hedefe eklenmekte,

Hedef ise ders ile davranış yüklemekle,

Hâl tavır her ne ise yukarı yükselmekle,

Değerlendirmelerle, düşüncelerimizle,

Her ne dersi var ise dikkatini çekmeyle…', 'Otizmli denildi mi bilinç fikri gelmekte, Bilip bilmeme fikri, hedefe eklenmekte, Hedef ise ders ile davranış yüklemekle, Hâl tavır her ne i...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-dokmuyordu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Dökmüyordu  3', 'otizmli-sarper-dokmuyordu-3-mehmet-tevfik-temizturk-3-itynz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dökmeme huyu ile takdir eder şekilde,

Dağıtmama huyu da tespit edildiğinde,

Şu ve bu hedefle, değerlendirildiğinde,

Davranış fikri ile dersler eklendiğinde,

Bir bir işlemekteydik incelik işlerini,

Hep iyiye varmasında düşüncelerini,

Bir diğeri, diyerek sıradaki davranış,

Anne ve babasından alması ile alkış,

Alkış denilen hâl ki iç huzur durumuydu,

Toplumdan milletime puan oluşumuydu…', 'Dökmeme huyu ile takdir eder şekilde, Dağıtmama huyu da tespit edildiğinde, Şu ve bu hedefle, değerlendirildiğinde, Davranış fikri ile dersl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/otizmli-sarper-dokmuyordu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Downlu Ve Zihinsellerle  9', 'otizmli-sarper-downlu-ve-zihinsellerle-9-mehmet-tevfik-temizturk-3-t01a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Downlular uyumlu laf söz dinleme ile

Bezli dahi olsalar, dersleri dinlemekle,

Zihinseller de uyar ziyaret etme ile

Sarper’i tesellide davranış işleriyle,

Otistikler gelmezdi güvenilmediğinden,

Hâl vaziyet gereği gönderilmediğinden,

Ya Muhammet Mustafa her teneffüs vaktinde,

Otizm fikri işinde Sarper deyip gelmede,

Yanına oturup da hâl hatır edinmekle,

Teselli gereğinde davranış eklemekle…', 'Downlular uyumlu laf söz dinleme ile Bezli dahi olsalar, dersleri dinlemekle, Zihinseller de uyar ziyaret etme ile Sarper’i tesellide davran...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/otizmli-sarper-downlu-ve-zihinsellerle-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Dondurmayla  9', 'otizmli-sarper-dondurmayla-9-mehmet-tevfik-temizturk-3-vagr3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birbirine derlerdi hakkın yok olabilir,

Yapılıp edilenler lehimize gereklidir,

Veliden izin vardı pekiştiren her neyse,

Yerine getirmekle her ne metot var ise

Çay işinden tut da şahsımdan sağlanması,

Evrak, belge yönünden tedbirler alınması…', 'Birbirine derlerdi hakkın yok olabilir, Yapılıp edilenler lehimize gereklidir, Veliden izin vardı pekiştiren her neyse, Yerine getirmekle he...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-dondurmayla-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Dondurmayla  8', 'otizmli-sarper-dondurmayla-8-mehmet-tevfik-temizturk-3-eqvvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzlaşı kâr sağlardı dondurma konusunda,

Dört çocuk dahi olsa dersten çıkıldığında,

Ellerde dondurmayla, laf söz konuşulmadan,

Verilmiş tüm sözler anlaşmalar bozulmadan,

Her ne varsa kuralla ders işleyebilirdik,

Sırrı merak edenlere laf da veremezdik…', 'Uzlaşı kâr sağlardı dondurma konusunda, Dört çocuk dahi olsa dersten çıkıldığında, Ellerde dondurmayla, laf söz konuşulmadan, Verilmiş tüm s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-dondurmayla-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Dondurmayla  7', 'otizmli-sarper-dondurmayla-7-mehmet-tevfik-temizturk-3-0c390', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Durdurulamayanları sürekli ağlamaktan,

