INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Davranış İle  7', 'otizmli-sarper-davranis-i-le-7-mehmet-tevfik-temizturk-3-p83nu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk iş davranış dedik umursanır bir hâlle,

Sonraki hâl der, isen de düzenlemelerle,

Her düzenleme işi, yanlış ve doğru diye,

Yanlışı bir bir atıp lazım gelecek seviye,

Seviye işi dersen şahsına güven verme,

Hedeften davranışa bu işi de denkleme,

Neyse ki annemiz var sürekli ilgilenen,

Bir yanında da baba sınıfı destekleyen…', 'İlk iş davranış dedik umursanır bir hâlle, Sonraki hâl der, isen de düzenlemelerle, Her düzenleme işi, yanlış ve doğru diye, Yanlışı bir bir...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-davranis-ile-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Daldan Dala Atlamakla  6', 'otizmli-sarper-daldan-dala-atlamakla-6-mehmet-tevfik-temizturk-3-t739s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sözü tutulmaz ise bu bize eziyet,

Tutulmama sonrası sınıf içi hezimet,

Bir biz, bir o, diyerek dersimiz işlenecek(!)

Her kim güç toplamışsa bizi yönlendirecek,

Ya çocuğun emrinde İbi, Rafadan Tayfa(!)

Ya da şimdi biz deyip lüzumsuzluklar rafa,

Neyse ki denge işi Sarper gelmediğinde,

Her ne varsa işlendi hedef plan içinde…', 'Sözü tutulmaz ise bu bize eziyet, Tutulmama sonrası sınıf içi hezimet, Bir biz, bir o, diyerek dersimiz işlenecek(!) Her kim güç toplamışsa ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-daldan-dala-atlamakla-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Helyum ve Barut', 'helyum-ve-barut-ali-i-hsan-kaya-2-w3hdi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '"Her panayır, akşamüstü dağılmak üzere 

kurulmuş küçük bir dünya provasıdır."

Kalabalık akıp gidiyor;

Turuncu, yeşil, sarı, siyah, mavi...

Sonra adını yeni öğrendiğim o renkler:

Cam göbeği, fuşya, nar çiçeği. 

Eğlence başlıyor saat on beşte.

Hayvanlar mühürlenmiş sahiplerinin 

sözüne,

Ayrılmıyorlar gösterilen çizgiden:

Timsah, aslan, kaplan, şempanze, yılan;

Vahşi bir sessizlikte, tek bir gövde gibi bir 

arada. 

Dönüyor dolaplar, sallanıyor salıncaklar,

Atlıkarıncanın sırtında ışık saçan çocuklar...

Çarpışıyor arabalar, patlıyor mantar 

tabancaları;

Havada geniz yakan o barut kokusu. 

Ne ararsan var bu toz bulutunun içinde:

Halka atıyor, sihirli aynada kendini 

görüyorsun.

İnce, uzun, kısa...

Dondurma ile kâğıt helva arası bir çocukluk 

tadı;

Şerbet, simit, börek...

Her şey seyyar bu dünyada, her düş satılık. 

Bir motosikletçi, ahşap uçurumun 

dairesinde,

Alnına bayrak bağlamış, kadere meydan 

okurcasına...

Seyircilerin nefesine kadar yükseliyor 

hayat,

Tekerleklerin üstünde. 

Yılancı Mustafa, sarı pitonu

Bir emanet gibi doluyor boynuna.

Ya yılan terbiye edilmiş ya da Mustafa;

Herkes hayran bu adsız, dilsiz muammaya. 

Çocuklar yerlerde gazoz kapakları,

Artist resimleri topluyor.

Biz de kendi görünmez çizgimizdeyiz;

Panayırdı hayat, içinde birer gölge. 

Deklanşöre, tam nişan aldığı an basan;

Omuzundaki tüfekle vurduğu her hedefte

Aslında zamanı deviren bir adam... 

Oysa seyircisiydim çoktan solmuş bu 

resmin;

Şimdi elimde kalan o fotoğraf:

Solgun ve derin.

Bir baloncu geçiyor, uçan düşlerin 

taşıyıcısı;

Helyumla dolan göğsünden bir ses 

yükseliyor,

İnceliyor sesi, geçmişin o ince sızısı gibi 

birdenbire. 

Eğlenceli zamanlardı, sahici ve mahzun...

Şempanzeye muz yerine şeftali atanların

Hesapsız neşesiyle;

Sonra perdeler iniyor, ışıklar sönüyor tek 

tek.', '"Her panayır, akşamüstü dağılmak üzere  kurulmuş küçük bir dünya provasıdır." Kalabalık akıp gidiyor; Turuncu, yeşil, sarı, siyah, mavi... S...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Kaya 2']::text[], 8.5, '{"poet":"Ali İhsan Kaya 2","poet_slug":"ali-i-hsan-kaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/helyum-ve-barut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Anlat Deseler', 'bana-anlat-deseler-ahmet-genc-2-hgudv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi bana hayatını anlat deseler,

En fazla sabırdan bahsederim.

Ben ne fırtınalardan geçtim, ne fırtınalar biçtim.

Hep sabrettim, hem de

Hep kendime dayanmayı öğrendim.

​Gelmeyeni bekledim,

İnanmayanı, değişmeyeni sabırla bekledim.

Hep affeden ben oldum anlamayanları.

Anladım; hayatta herkes hak ettiği kadar.

Yük olmaz insana, dayandığı kadar yük olurmuş.

​Hayat, yaşadığım sürede bana bunu öğretti.

Ne her gülüşün mutluluk, ne her susuşun kabullenmektir.

Hayat bana sadece sabretmeyi öğretti Yaşadıklarım hep yalanmış.', 'Şimdi bana hayatını anlat deseler, En fazla sabırdan bahsederim. Ben ne fırtınalardan geçtim, ne fırtınalar biçtim. Hep sabrettim, hem de He...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Genç 2']::text[], 8.5, '{"poet":"Ahmet Genç 2","poet_slug":"ahmet-genc-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hayat-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Daldan Dala Atlamakla  5', 'otizmli-sarper-daldan-dala-atlamakla-5-mehmet-tevfik-temizturk-3-3krrx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Teselli edilemez hâller gerçekleştikçe,

Her ne varsa bitti deyip de erteledikçe,

İzledik sayıver ki izlenmiş sayılmalı,

Ne İbi ne de Rafadan Tayfa açılmalı,

Kâr sağlayamayacak sürekli bağırmaktan,

Huzur bulamayacak kargaşa çıkarmaktan…', 'Teselli edilemez hâller gerçekleştikçe, Her ne varsa bitti deyip de erteledikçe, İzledik sayıver ki izlenmiş sayılmalı, Ne İbi ne de Rafadan...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-daldan-dala-atlamakla-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lal', 'lal-omer-yucekaya-2-vezry', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'boşuna bu şaşalı şölen

her detayı düşünülmüş bu buluşma

bu çaba

bu emek b o ş u n a

ben değilim beklediğiniz o ekabir misafir 

ben değilim sürâ üfleyecek israfil

susma hakkını kullanan 

kırgın bir rüzgarım ben

hadi es diye kimse üstüme gelmesin

atlarım yorgun, ben bıkkın

çırpınmıyor artık içimde ki fırtına kuşu 

kimse benden fırtına beklemesin

öyle paldır küldür 

girmeyin sınırlarımdan içeri

yeni avuttum içimdeki dikiş tutmaz yarayı

gürültüde yapmayın 

sessiz olun

yeni uyuttum göğsümde uluyan 

vampir yarasayı

dağına küskün bir rüzgar gibi 

kendi içime esiyor

tıkanmış bir baca gibi 

kendi içime tütüyorum

ateşe tövbeli bir yangın yeriyim

içim dışım is içinde

ateş saçan saçlarınızı savura savura

yakmayın içimin kuru otlarını

y a k m a y ı n

dumanlı başıma

birde siz tütün sarmayın

sağırlaşmış kulaklarıma

avaz avaz bağırmayın aşkı

gök gürültüsü gibi gürleseniz de 

sizi duyamam

sormayın aşkı bana

s o r m a y ı n

bir mezara su döker gibi sus dökülür dilime

lal olur 

konuşamam', 'boşuna bu şaşalı şölen her detayı düşünülmüş bu buluşma bu çaba bu emek b o ş u n a ben değilim beklediğiniz o ekabir misafir  ben değilim s...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/lal-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevenler Kavuşunca', 'sevenler-kavusunca-senturk-dursun-0w787', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVENLER BULUŞUNCA

Dünya başka hal alır sevenler buluşunca

Asuman neşe saçar, gönüller mestan olur

Kış bahara dönüşür âşıklar gülüşünce

Bağ bahçe yeşillenir, her yer gülistan olur

İlk adımlar atılır tebessüm edilerek

Kalpten kalbe köprüler örülür ilmek ilmek

Yürekten sevenlere bilmem ki dil ne gerek

Gözler birer alfabe, bakışlar lisan olur

Bir anda tutulunca sevda denen tufana

Ne başta akıl kalır ne mantık ne de mânâ

O anki hisler sığmaz ne şiir ne romana

Sayfalar dolar taşar, bitmeyen destan olur

Ne kadar dirensen de pes edilir sonunda

Hayaller gözü kaplar, en pespembe tonunda

Hiyerarşi işlemez sevdanın kanununda

Gönül aşk huzurunda, el pençe divan olur

Duygular şaha kalkar her daim önde gider

Hafıza formatlanır yok olur gam ve keder

Ayak yerden kesilir göklere terfi eder

Ay ışığı kılavuz, yıldızlar liman olur

ŞENTÜRK DURSUN', 'SEVENLER BULUŞUNCA Dünya başka hal alır sevenler buluşunca Asuman neşe saçar, gönüller mestan olur Kış bahara dönüşür âşıklar gülüşünce Bağ ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevenler-kavusunca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar Vardır', 'i-nsanlar-vardir-erokrates-erol-guner-loiwk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlar vardır; Gelir, geçerler hayatımızdan… Kimi ardında hiçbir iz bırakmaz, 

Kimi ruhumuza usulca dokunur,

Kimi de yüreğimizde dinmeyen bir hüzün bırakır.

İnsanlar vardır; Sessizce sokulurlar gönlümüze, 

Öyle bir yer edinirler ki içimizde, 

Bir ömür orada kalsın isteriz. 

Bazılarıysa bir serap gibidir; 

Varlıkları bir hayal, yoklukları gerçeğimiz olur.

İnsanlar vardır; Su gibi aziz, su gibi duru… 

Her kelamlarında bir huzur taşırlar, 

Konuşmaları su misali akar yüreğimize. 

Öyle insanlar vardır ki; 

Kan gibi yakın, can gibi kıymetli, 

Canan gibi vazgeçilmez olurlar.

İnsanlar vardır; Işığını yitirmiş yıldızlar misali, Karanlığın içinde sessizce kaybolurlar. 

Bir uzatsan elini, bir açsan kollarını, 

Bütün karanlıklarını bırakıp 

Gönüllerine ışık olmanı beklerler.

İnsanlar vardır; Soğuk duvarlar gibidirler. 

Bir tebessümün sıcaklığını bilmez, 

Bir gönle dokunmanın kıymetini anlamazlar. Sevginin ne olduğunu bilseler de 

Sevmeyi, sevilmeyi kendilerine yakıştıramazlar.

Ve insanlar vardır; Gelirler, hayatımıza dokunur, Bazen bir ömürlük iz bırakırlar. 

Kimi depremler kopararak gider, 

Kimi fırtınalar estirerek… 

Kimi de hiçbir şey söylemeden 

Bir ömrün en güzel yerinden eksilir.

Ama ben, kalanlardan yanayım… 

Fırtınalar koptuğunda elimi bırakmayanları, Yollar zorlaştığında yanımdan ayrılmayanları severim. 

Çünkü bilirim ki; İnsan, güzel gününde yanında olanla değil, 

En zor gününde de yanında kalabilenle insandır.

Ben, gelip geçici sevdaların değil, 

Ömrün sonuna kadar süren vefanın yanındayım. 

Çünkü bazı insanlar hayatına yalnızca uğramaz; 

Gönlüne yuva kurar, ömrüne anlam katar.

Ben gitmeyenleri severim… 

Varlığıyla huzur verenleri, 

Yokluğunda bile kıymeti eksilmeyenleri… 

Çünkü bu hayatta asıl mesele, 

Hayatımıza kaç kişinin girdiği değil; 

Kaç kişinin gönlümüzde kalmayı başarabildiğidir... İşte öyle ....

28,11,2017', 'İnsanlar vardır; Gelir, geçerler hayatımızdan… Kimi ardında hiçbir iz bırakmaz,  Kimi ruhumuza usulca dokunur, Kimi de yüreğimizde dinmeyen ...', ARRAY['Türk Edebiyatı','Şiir','Erokrates Erol Güner']::text[], 8.5, '{"poet":"Erokrates Erol Güner","poet_slug":"erokrates-erol-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/insanlar-vardir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Daldan Dala Atlamakla  4', 'otizmli-sarper-daldan-dala-atlamakla-4-mehmet-tevfik-temizturk-3-c1qgk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Üstelik emri vaki Rafadan Tayfa derken,

Rafadan Tayfa’dan da İbi’ye geçer iken,

İster çıktıkça çıkıp, ayrıldıkça ayrılıp,

İbi’den diğerine, diğerinden de çıkıp,

Maymun iştahlı muz ağacının üzerinde,

Yemesi gerekirken yenilmez dediğinde…', 'Üstelik emri vaki Rafadan Tayfa derken, Rafadan Tayfa’dan da İbi’ye geçer iken, İster çıktıkça çıkıp, ayrıldıkça ayrılıp, İbi’den diğerine, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-daldan-dala-atlamakla-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kazanan', 'kazanan-senturk-dursun-ky3cr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KAZANAN

Kıymeti yok haklılığın

Varı olan kazanıyor

Vicdanında yığın yığın

Kiri olan kazanıyor

Doğru çıkmaz yazanından

Hak aranmaz mizanından

Akıl mantık izanından

Zoru olan kazanıyor

Yere düştü edep hayâ

Süt bozuksa tutmaz maya

Ne gerek var koşturmaya

Geri olan kazanıyor

Eğri doldu bütün mahal

Doğruluklar oldu hayal

Bir aslana elli çakal

Sürü olan kazanıyor

Kaybetmek yok yasasında

Haram dolu kasasında

Paylaşımın masasında

Yeri olan kazanıyor

Ganimetler oluşurken

El hileye alışırken

Devlet malı bölüşürken

Seri olan kazanıyor

Hokkabazlık yarışında

Herkes kulvar telaşında

Menfaatler savaşında

Diri olan kazanıyor

Prim yaptı arsız sürtük

Her yer dövme üst baş yırtık

Şimdi düzen böyle artık

İri olan kazanıyor

Şentürk Dursun', 'KAZANAN Kıymeti yok haklılığın Varı olan kazanıyor Vicdanında yığın yığın Kiri olan kazanıyor Doğru çıkmaz yazanından Hak aranmaz mizanından...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kazanan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Daldan Dala Atlamakla  3', 'otizmli-sarper-daldan-dala-atlamakla-3-mehmet-tevfik-temizturk-3-gq7wt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hiçbir şey değil idi hiçbir şey işi ile

Hiçbir şeyden de hiç ile vakit geçirmekle,

Ne açar ne de okur, Türkçe denildiğinde,

Ne de rakam saymakla fikir istendiğinde,

Heveslenme işinin, az sonrası hüsranla,

Bir dakikada bıkar yoğunlaşamamakla,

Sanki çekirge gibi, daldan dala şekilde,

Her ne edilse de fikir edinmez biçimde…', 'Hiçbir şey değil idi hiçbir şey işi ile Hiçbir şeyden de hiç ile vakit geçirmekle, Ne açar ne de okur, Türkçe denildiğinde, Ne de rakam saym...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-daldan-dala-atlamakla-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılan Hayallerim', 'yikilan-hayallerim-senturk-dursun-jmni7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YIKILAN HAYALLERİM

Uzaktan sevdim seni, yüzünü görmeksizin

Her gece düşlerime, çıkıverdin sevdiğim

Yıllardır silinmedi gönlümde kalan izin

İçimde bir kor olup, yakıverdin sevdiğim

Her zaman bendim hedef, feleğin oklarında

Hasretin izi saklı saçımın aklarında

Dinmeyen yağmur oldun ruhumun göklerinde

Bulutlardan süzülüp, akıverdin sevdiğim

Aşkınla çöle düştüm Mecnuna çıktı adım

Şahitlik eder buna yürüdüğüm her adım

Ben seni kendim bildim gül sinemde sakladım

Sen bana eller gibi, bakıverdin sevdiğim

Sözle tarif edemem bende olan yerini

Hiçbir zaman bilmedin sevgimin değerini

Varlığıma susamış ayrılık hançerini

Bağrımın ortasına, çakıverdin sevdiğim

Her yerde seni sordum rastladığım kullara

Öfkem bir an dinmedi seni çalan yıllara

Özlemle bakıp durdum gelmediğin yollara

Bütün hayallerimi, yıkıverdin sevdiğim

Şentürk Dursun', 'YIKILAN HAYALLERİM Uzaktan sevdim seni, yüzünü görmeksizin Her gece düşlerime, çıkıverdin sevdiğim Yıllardır silinmedi gönlümde kalan izin İ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yikilan-hayallerim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Çizgi Film İbi''yle 14', 'otizmli-sarper-cizgi-film-i-bi-yle-14-mehmet-tevfik-temizturk-3-j8ntz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ret edelim desek de çizgi film işine,

Rafadan Tayfa’yı, İbi’yi izlemesine,

Açmayınca olmuyor yazmak istemeyince,

Anne gelsin, deyip de kaçma düşüncesine,

Anneden izinliydi alışması tercihim,

Eğitim işi bende okulu sevsin derim…', 'Ret edelim desek de çizgi film işine, Rafadan Tayfa’yı, İbi’yi izlemesine, Açmayınca olmuyor yazmak istemeyince, Anne gelsin, deyip de kaçma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-cizgi-film-ibi-yle-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir de Sen Vurma Felek', 'bir-de-sen-vurma-felek-senturk-dursun-fm81a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİR DE SEN VURMA FELEK

Cefakâr yolcusuyum sonu gelmez yolların

Ben benden habersizim nerdeyim sorma felek

Acıyla sarmaş dolaş tadı yok gönüllerin

Vuslatla aramıza perdeler germe felek

Nice ışık karardı aydınlık denen yolda

Nice umut son buldu vefadan yoksun kulda

Tufana maruz kaldım her bindiğim sandalda

Ezelden yaralıyım bir de sen vurma felek

Döküldü yapraklarım kurumuş bağ misali

Gurbet elde yalnızım özlemler dağ misali

Mazinin ağırlığı üstümde çığ misali

Hayatımın filmini geriye sarma felek

Kanadı kırık kuşum rüzgârlar yordu beni

Zemheri ayazında alevler sardı teni

İstemem acıyıp da gözyaşımı silmeni

Bari ümitlerimi kökünden kırma felek

Hüznüm evrim geçirdi sevincimle kaynaşır

Derin bir nefesimle yer yerinden oynaşır

Çilekeş ayaklarım umuda yolcu taşır

Düşe kalka yürürken yolumda durma felek

ŞENTÜRK DURSUN', 'BİR DE SEN VURMA FELEK Cefakâr yolcusuyum sonu gelmez yolların Ben benden habersizim nerdeyim sorma felek Acıyla sarmaş dolaş tadı yok gönül...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-de-sen-vurma-felek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Çilekli Bisküvi Der Durur  5', 'otizmli-sarper-cilekli-biskuvi-der-durur-5-mehmet-tevfik-temizturk-3-q9rg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şeyi takıntılı akla getirdiğinde,

Yine de tekrarlıyor mühimsenmediğinde,

Dikkatini çekmekle Sarper gel, diyerekten,

Hâl vaziyet gereği davranış yüklenmekten,

Duymama yolu, dersen iflas etmiş hâldeydi,

Gezme, gezdirme yollu hâl denenebilirdi…', 'Her şeyi takıntılı akla getirdiğinde, Yine de tekrarlıyor mühimsenmediğinde, Dikkatini çekmekle Sarper gel, diyerekten, Hâl vaziyet gereği d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-cilekli-biskuvi-der-durur-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşsiz Yangın', 'atessiz-yangin-senturk-dursun-geaok', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ATEŞSİZ YANGIN

Sanmayın ateştir içimi yakan

Bakışı buğulu göz yaktı beni

Ne harlı kıvılcım ne kızıl volkan

Gözdeki çözülmez giz yaktı beni

Birimiz Keremdik birimiz Aslı

İsterdim bitmesin muhabbet faslı

Cümleler sitemkâr dil ihtiraslı

Dudaktan dökülen söz yaktı beni

Zihnime kazıdım eşsiz ismini

Gönül tuvalime çizdim resmini

Hayal penceremde gördüm cismini

Gerdanı incili poz yaktı beni

Cemalinin şavkı vurunca cama

Kalem ilham alır durur selama

Yürek mi dayanır bu ihtişama

Yanağı gamzeli yüz yaktı beni

Bedende tek vücut ruhumda ikiz

Silinmez bendeki bıraktığı iz

Endamı tarife laf kifayetsiz

Edalı işveli naz yaktı beni

ŞENTÜRK DURSUN', 'ATEŞSİZ YANGIN Sanmayın ateştir içimi yakan Bakışı buğulu göz yaktı beni Ne harlı kıvılcım ne kızıl volkan Gözdeki çözülmez giz yaktı beni B...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/atessiz-yangin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın İle Divaneyim', 'askin-i-le-divaneyim-senturk-dursun-yphrg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'AŞKIN İLE DİVANEYİM

Aşkın ile divaneyim

Mecnun oldum çöle düştüm

Dertle dolu kemaneyim

Nağme oldum tele düştüm

Sabah olur güneş doğmaz

Gördüklerim göze sığmaz

Sitemlerim söze sığmaz

Anlatılmaz hale düştüm

Yıkılmazdım yıktın beni

Çarmıhlara çaktın beni

Ateşlerde yaktın beni

Savurduğun küle düştüm

Işık vermez çerağımla

Sükût yüklü dimağımla

Yalın ayak ayağımla

Sonu gelmez yola düştüm

Felek aldı tüm varımı

Sis bürüdü dağlarımı

Hazan vurdu bağlarımı

Çiçeksiz bir dala düştüm

Belli değil kışım yazım

Dinmek bilmek kalpte sızım

Ne karaymış alın yazım

Vefasız bir kula düştüm

Hasret kaldım nevbahara

Derdim büyük bahtım kara

Yoldaş oldum bulutlara

Boz bulanık sele düştüm

ŞENTÜRK DURSUN', 'AŞKIN İLE DİVANEYİM Aşkın ile divaneyim Mecnun oldum çöle düştüm Dertle dolu kemaneyim Nağme oldum tele düştüm Sabah olur güneş doğmaz Gördü...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/askin-ile-divaneyim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Çilekli Bisküvi Der Durur  4', 'otizmli-sarper-cilekli-biskuvi-der-durur-4-mehmet-tevfik-temizturk-3-h0d9b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne bisküvi işleri ne de şeker işleri,

Gerekmedikçe yoktu tatlı düşünceleri,

Çilekli, der durur unutturamıyoruz da

Her ne der isek de baskılayamıyoruz da

Takıntı tekrarlanınca, ertesi günlerde,

Çilekliden getirdik ikram fikri içinde, 

Bir çeşit takıntıymış ne baktı ne de yedi,

Ne laf ne de söz kaldı versen de yemedi…', 'Ne bisküvi işleri ne de şeker işleri, Gerekmedikçe yoktu tatlı düşünceleri, Çilekli, der durur unutturamıyoruz da Her ne der isek de baskıla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-cilekli-biskuvi-der-durur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Beceri İşi İle  4', 'otizmli-sarper-beceri-i-si-i-le-4-mehmet-tevfik-temizturk-3-k1w20', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yönerge bile almış dikkatli annesiyle,

Ona her ne var ise sevgi öğretmesiyle,

Bir yanında baba içten desteklemesiyle,

Davranıştan bilince anne, baba fikri ile

Her ne kural var ise tembihleyip öğretmiş,

Bu bir harf de olsa eğitim öğretim vermiş,

Kalmışsa otizm işi o da azalacaktır,

Beceri işi ile pek de kalmayacaktır…', 'Yönerge bile almış dikkatli annesiyle, Ona her ne var ise sevgi öğretmesiyle, Bir yanında baba içten desteklemesiyle, Davranıştan bilince an...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-beceri-isi-ile-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzmanlık', 'uzmanlik-senturk-dursun-zf77t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UZMANLIK

İnsanı tanımak uzmanlık ister

Yüzüne bakarak tanıyamazsın

Farklılık gösterir her bir karakter

Özüne bakarak tanıyamazsın

Kimisi meyleder şarkıya meşke

Kimi meze olur gündelik aşka

Yüreği başkadır dışı bambaşka

Pozuna bakarak tanıyamazsın

Ezelden bozuksa meşrebi soyu

Sonradan değişmez fıtratı huyu

Fesatlık tasarlar bütün gün boyu

Gözüne bakarak tanıyamazsın

Enginlere dalar kuşa benzemez

Duyguları vardır taşa benzemez

Ekmeğe benzemez aşa benzemez

Tuzuna bakarak tanıyamazsın

İnsan var kalıbı kalibresi yok

İnsan var lisanın kalitesi yok

Günlük perspektifi reçetesi yok

Dozuna bakarak tanıyamazsın

Tik toktan almışsa modeli rolü

İzzeti hastadır irfanı ölü

Zikzakla doludur gittiği yolu

İzine bakarak tanıyamazsın

Din, mezhep ırk diye böleni vardır

Gaflet uykusuna dalanı vardır

İçten pazarlıklı olanı vardır

Sözüne bakarak tanıyamazsın

ŞENTÜRK DURSUN', 'UZMANLIK İnsanı tanımak uzmanlık ister Yüzüne bakarak tanıyamazsın Farklılık gösterir her bir karakter Özüne bakarak tanıyamazsın Kimisi mey...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/uzmanlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eine mehrdimensionale Kritik des Reinkarnationsglaubens', 'eine-mehrdimensionale-kritik-des-reinkarnationsglaubens-muhammed-ridvan-gizri-7iu34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eine umfassende Analyse im Lichte von Koran, Philosophie, Neurowissenschaft und Physik

Im Verlauf der Menschheitsgeschichte hat der Tod die tiefste Frage des Daseins gebildet: Was geschieht nach dem Tod? Unter den Antworten darauf hat der Glaube an die Reinkarnation weite Verbreitung gefunden, vom Hinduismus und Buddhismus über die antike griechische Philosophie und hermetische Traditionen bis zu modernen New-Age-Strömungen. Die Behauptung, dass die Seele nach dem Tod in einen neuen Körper übergeht und dieser Kreislauf durch das Karmagesetz gesteuert wird, hat über Jahrhunderte den Lebensrahmen von Millionen Menschen geprägt. Heute bleibt der Reinkarnationsglaube jedoch nicht auf die östliche Mystik beschränkt. Einige Kreise versuchen, ihn mit dem islamischen Glauben in Einklang zu bringen, ja ihn sogar als durch Koranverse begründete Wahrheit darzustellen. Dieses Unterfangen bringt eine ernste intellektuelle Verantwortung mit sich. Um die Behauptung der Reinkarnation richtig zu beurteilen, reicht ein rein theologischer Vergleich nicht aus. Ihre philosophischen, ontologischen, neurowissenschaftlichen und physikalischen Dimensionen müssen mit derselben Sorgfalt untersucht werden.

Hier behandeln wir den Reinkarnationsglauben systematisch entlang von vier Achsen. Auf der ersten wird das Daseinsgefüge, das der Koran dem Menschen vorlegt, neu gelesen, und der Versuch, die Reinkarnation durch Koranverse zu stützen, wird einer kontextuellen Analyse unterzogen. Auf der zweiten werden die philosophischen und ontologischen Widersprüche untersucht, die der Glaube birgt, anhand der Begriffe Identität, Kausalität, Zeit und Gerechtigkeit. Auf der dritten wird im Lichte der Befunde der Neurowissenschaft und der modernen Psychologie gezeigt, wie die Reinkarnation mit den Theorien von Bewusstsein und Gedächtnis in Konflikt gerät. Auf der vierten werden schließlich die thermodynamischen und kosmologischen Aporien der Reinkarnation im Rahmen des modernen Verständnisses von Zeit, Materie und Bewusstsein aufgezeigt. Im Schnittpunkt dieser Achsen ergibt sich ein einheitliches Ergebnis: Die Reinkarnation ist weder mit dem Wortlaut des Korans noch mit den Prinzipien der Logik, noch mit den Befunden der Neurowissenschaft, noch mit dem Weltmodell der modernen Physik vereinbar. Diesen Zusammenbruch wollen wir systematisch und in seiner Gesamtheit darlegen.

Koranzentrierte Analyse

Der Rahmen des Daseins, den der Koran dem Menschen vorlegt

Der Koran stellt den Lebensweg des Menschen in einer äußerst klaren Chronologie dar. Diese Chronologie ist linear und eindeutig; sie lässt weder Raum für Vielfalt noch für Zyklik oder Unbestimmtheit. Das Dasein des Menschen besteht aus folgenden Stationen: dem Zustand des Nichtseins vor der Erschaffung, dem Leben im Diesseits mit einem Körper, dem Tod am Ende dieses Lebens und schließlich der Auferstehung vor Gott am Tag des Gerichts. Diese vier Stationen bilden ein durchgängiges Grundmotiv, das in zahlreichen Suren konsequent wiederholt wird.

Sure Al-Baqara, Vers 28, legt diese Struktur unmissverständlich dar. Dort wird berichtet, dass der Mensch zuerst tot war und dann lebendig gemacht wurde, danach wieder sterben wird, anschließend erneut auferweckt wird und schließlich zu Ihm zurückgebracht wird. Dieser Vers zieht einen eindeutigen Rahmen, der das Dasein des Menschen auf ein einziges irdisches Leben und eine einzige Auferstehung im Jenseits beschränkt. Eine Andeutung auf wiederholte Lebenszyklen oder eine Formulierung, die eine Vielfalt von Existenzen eröffnet, findet sich darin nicht.

In Sure Al-An''am, Vers 94, heißt es: „Ihr seid zu Uns gekommen, so wie Wir euch zum ersten Mal erschaffen haben." Dieser Satz zeigt, dass der Mensch bei der Auferstehung in demselben Wesen vor Gottes Angesicht treten wird, das er bei seiner ersten Erschaffung hatte. Nicht als Erbe einer in anderen Körpern gelebten Vergangenheit, sondern als jemand, der mit seinem eigenen Wesen zur Rechenschaft gezogen wird, tritt der Mensch hier auf, und das widerspricht jeder Auffassung, nach der die Seele verschiedene Körper durchwandert.

Sure Ad-Dukhan, Vers 56, beschreibt die Bewohner des Paradieses mit den Worten: „Dort werden sie nicht den Tod kosten außer dem ersten Tod." Diese Aussage macht deutlich, dass der Tod nur einmal erfahren wird. Die Vorstellung der Reinkarnation, die auf wiederholtem Sterben und Geborenwerden beruht, steht diesem Zeugnis grundlegend entgegen.

Die Analyse der Verse, die als Beleg für Reinkarnation angeführt werden

Der Vers, auf den sich die Befürworter der Reinkarnation im islamischen Kontext am häufigsten stützen, ist Sure Al-Mu''min, Vers 11. Dort wird die Rede der Bewohner der Hölle wiedergegeben: „Unser Herr! Du hast uns zweimal sterben lassen und zweimal lebendig gemacht." Dass diese zwei Tode und zwei Auferstehungen als Beweis für die Reinkarnation dienen sollen, mag auf den ersten Blick überzeugend wirken. Diese Deutung löst die Stelle jedoch vollständig aus ihrem Kontext.

Betrachtet man den Vers zusammen mit Sure Al-Baqara, Vers 28, wird unmittelbar klar, welchen Stationen die beiden Tode und Auferstehungen entsprechen: Der erste Tod ist der Zustand des Nichtseins vor der Erschaffung; die erste Auferstehung ist das Dasein im Diesseits mit einem Körper; der zweite Tod ist das Ende des irdischen Lebens; die zweite Auferstehung ist die Auferweckung am Tag des Gerichts vor Gott. Diese Chronologie ergibt sich zwangsläufig aus einer ganzheitlichen Lektüre des Korans. Sure Al-Mu''min, Vers 11, als Beleg für die Reinkarnation zu lesen, heißt, den Vers aus seinem Zusammenhang zu reißen und ihm eine Bedeutung aufzuzwingen, die dem in sich stimmigen Bericht des Korans widerspricht.

Die Verse 99 und 100 der Sure Al-Mu''minun stellen die Rückkehr in die Welt nach dem Tod zudem ausdrücklich als unmöglich dar. Dort wird die Forderung eines Menschen im Augenblick des Todes, in die Welt zurückgebracht zu werden, entschieden abgewiesen, und zwischen Tod und Auferstehung wird eine unüberwindbare Schranke errichtet. Wäre die Reinkarnation ein reales System, so hätte diese Schranke keinen Sinn, denn die Seele würde ohnehin im nächsten Körper in diese Welt zurückkehren. Gerade das Vorhandensein dieses Verses erklärt die Ungültigkeit dieses Systems.

In Sure Al-Fajr, Vers 24, schließlich werden Worte der Reue ausgesprochen: „Hätte ich doch für mein Leben etwas vorausgeschickt!" Dieser Ausdruck des Bedauerns verweist allein auf ein einziges irdisches Leben. Würde der Mensch mehrere Leben durchleben, müsste man in dieser Reue das Lernen aus früheren Leben erkennen. Im Bild des Korans jedoch muss der Mensch für ein einziges Leben Rechenschaft ablegen und empfindet tiefen Kummer darüber, dass er die vergangenen Gelegenheiten nicht genutzt hat.

Die Grenzen des Begriffs Barzach

Einer der bedeutenden Begriffe, auf die sich die Befürworter der Reinkarnation berufen, ist der Barzach (Berzah). In Sure Ar-Rahman, Vers 20, wird der Barzach als die Trennwand zwischen zwei Meeren beschrieben, die sich nicht vermischen. In Sure Al-Mu''minun, Verse 99 und 100, dient er als Schleier, der einen Verstorbenen daran hindert, in die Welt zurückzukehren.

Diese Verwendungen zeigen eindeutig, dass der Barzach lediglich die Bedeutung einer Schranke oder Grenze trägt. Von diesem Begriff ausgehend eine eigenständige Zwischenwelt mit Verhör, Strafe und Belohnung zu konstruieren oder ihn als Übergangsbereich zu deuten, der die Reinkarnation ermöglicht, ist eine Ausweitung, die der Text selbst nicht stützt. Andere Bedeutungen, die diesem Begriff zugeschrieben werden, stammen nicht aus dem Wortlaut des Korans, sondern aus nachträglich entwickelten Auslegungen.

Das zentrale Prinzip des Korans: Ein Leben, eine Prüfung, eine Auferstehung

Der Rahmen des Daseins, den der Koran dem Menschen vorlegt, ruht auf drei Prinzipien. Das erste ist das Prinzip des einen Lebens: Der Mensch lebt in dieser Welt nur einmal, verpasste Gelegenheiten lassen sich nicht nachholen, und es gibt keine Rückkehr. Das zweite ist das Prinzip der einen Prüfung: Das Diesseits ist der einzige Raum, in dem erprobt wird, was für ein Diener der Mensch ist, und das Ergebnis ist endgültig und unveränderlich. Das dritte ist das Prinzip der einen Auferstehung: Am Tag des Gerichts wird der Mensch in dem Zustand auferweckt, in dem er ursprünglich erschaffen wurde; von Vielfalt oder Zyklik kann keine Rede sein.

Der Reinkarnationsglaube verdrängt diese drei Prinzipien durch eine zyklische und unbestimmte Vorstellung des Daseins, schwächt die Verantwortung des Menschen im gegenwärtigen Leben und macht den Begriff der göttlichen Gerechtigkeit undeutlich. Eine ganzheitliche Lektüre des Korans zeigt, dass die Reinkarnation mit keinem dieser Prinzipien vereinbar ist.

Philosophische und ontologische Kritik

Das Problem von Identität und Kontinuität

Das zentrale Versprechen der Reinkarnation besteht darin, dass dieselbe Seele in verschiedenen Körpern fortbesteht. Diese Behauptung kollidiert unmittelbar mit einem der ältesten und umstrittensten Probleme der Philosophie: Was ist personale Identität, und wie bleibt sie erhalten?

In der Philosophie wird die Kontinuität der Identität auf drei Weisen bestimmt. Die materielle Identität gründet auf dem Körper; da sich der Körper bei jeder Reinkarnation jedoch vollständig ändert, scheidet dieses Kriterium von vornherein aus. Die psychologische Identität setzt die Kontinuität von Gedächtnis, Charakter und Bewusstsein voraus; bei der Reinkarnation sollen all diese Elemente vollständig gelöscht werden. Es bleibt allein die geistige Identität übrig, die Behauptung „Das Wesen ist dasselbe". Diese Behauptung ist jedoch nur die Wiederholung eines Etiketts, das mit keinem Inhalt gefüllt ist.

Ohne Gedächtnis gibt es keine Kontinuität; ohne Kontinuität keine kausale Verbindung; ohne kausale Verbindung ist die Aussage „dieselbe Person" nur eine leere Benennung. Die Reinkarnation lässt den Begriff der Identität inhaltslos und zwingt ihn als Postulat auf. Denkt man mit Wittgenstein und seinem Argument der Privatsprache, so zeigt sich, dass ein Begriff nur dann Bedeutung hat, wenn sein Gebrauch in einem öffentlichen Zusammenhang überprüfbar ist. Der Ausdruck „dieselbe Seele" aber hat weder einen beobachtbaren noch einen messbaren Inhalt und entzieht sich jeder Prüfung. Er ist semantisch leer.

Das Problem der Gerechtigkeit

Wird die Reinkarnation zusammen mit dem Karmagesetz vorgetragen, so zielt sie auf den Aufbau eines moralischen Gerechtigkeitssystems: Was in einem früheren Leben verfehlt wurde, wird im gegenwärtigen Leben mit seinem Preis bezahlt. Dieses System bricht jedoch in drei grundlegenden Hinsichten zusammen.

Erstens bleibt die Frage unbeantwortet, wer die Tat begangen hat. Zwischen der Person des früheren Lebens und der des gegenwärtigen besteht keine Erinnerungsverbindung; die Identität ist also unterbrochen. Täter und Büßer sind zwei verschiedene Personen. In diesem Fall handelt es sich nicht um Gerechtigkeit, sondern um eine unbewusste Übertragung von Verantwortung.

Zweitens führt die Frage, wem die Strafe zukommt, zu einem ernsten Problem. Wird sie der gegenwärtigen Person auferlegt, so trägt diese die Last einer Sünde, an die sie sich nicht erinnert; das ist keine Gerechtigkeit, sondern willkürliche Sanktion. Wird sie der früheren Person auferlegt, so wird eine Existenz bestraft, die nicht mehr besteht; auch das ist sinnlos.

Drittens entsteht das Paradox des Bevölkerungswachstums. Die Weltbevölkerung wächst im Lauf der Geschichte ständig. Wenn dieselben Seelen im Kreislauf verbleiben, woher stammen dann die Seelen der wachsenden Bevölkerung? Entweder werden neue Seelen erschaffen, und dann ist die Behauptung eines geschlossenen Kreislaufs gebrochen; oder die Seelen teilen sich und vermehren sich, und dann bricht die Identität vollständig zusammen. Beide Möglichkeiten zerstören das System von innen.

Die Täuschung der zeitlichen Identität

Die Behauptung der Reinkarnation enthält einen kategorialen Fehler, der zwei verschiedene zeitliche Modi vermischt. Die Sätze „A war" und „B ist" zeigen, dass Existenz zeitlich indiziert ist. Die Aussage „A = B" dagegen wird unter Beibehaltung der zeitlichen Indizes niedergeschrieben. Die Philosophie bezeichnet dies als „Trugschluss der zeitindizierten Identität".

Außerdem wird das Prinzip der Transitivität verletzt. Wenn A mit B identisch ist und B mit C, dann muss auch A mit C identisch sein. Zwischen den Personen am Anfang und am Ende der Reinkarnationskette besteht jedoch keinerlei gemeinsame Bewusstseinseigenschaft. Damit wird das grundlegende Identitätsaxiom der klassischen Logik verletzt.

Kausalität und ontologische Aufblähung

Die Reinkarnation behauptet, dass das vergangene Leben das gegenwärtige beeinflusst. Für die klassische Kausalität ist jedoch notwendig, dass A eine Spur auf B hinterlässt. Hier aber ist A (das frühere Leben) gelöscht, und B (das gegenwärtige Leben) weiß nichts von A. Eine Struktur, die die Sprache der Kausalität verwendet, aber keinen Träger der Kausalität besitzt, wird in der Philosophie als „leere kausale Funktion" bezeichnet.

Auch in ihrer Erklärungskraft ist die Reinkarnation schwach. Das Modell eines einzigen Lebens bewahrt individuelle Verantwortung, eine klare Abrechnung und ein kohärentes Gerechtigkeitsverständnis. Die Reinkarnation dagegen häuft zur Erreichung desselben Zwecks unnötige Entitäten an. Was in der Philosophie als „ontologische Aufblähung" oder „Vervielfachung der Entitäten" bezeichnet wird, erhöht die Komplexität des Systems ohne Zugewinn an Erklärungskraft.

Modale Unmöglichkeit

Eine metaphysische Theorie muss in mindestens einer möglichen Welt konsistent funktionieren können. Auch die Reinkarnation besteht diese Prüfung nicht. In einer Welt, in der das Gedächtnis erhalten bleibt, bleibt die Identität bewahrt; doch dann handelt es sich nicht um Reinkarnation, sondern um eine einfache Fortsetzung. In einer Welt, in der das Gedächtnis gelöscht wird, kann die Identität nicht bewahrt werden. In einer Welt, in der die Seele unverändert bleibt, ist Wandel sinnlos. In einer Welt, in der sich die Seele verändert, bricht die Behauptung der Identität zusammen. In keiner dieser vier Möglichkeiten können „Reinkarnation und Bewahrung der Identität" zugleich bestehen. Folglich erzeugt die Reinkarnation im modalen Raum die leere Menge; es ist unmöglich, eine konsistente Beispielwelt zu beschreiben.

Kritik aus Neurowissenschaft und Psychologie

Gehirn, Bewusstsein und Identität

Eine der grundlegendsten Erkenntnisse der modernen Neurowissenschaft besteht darin, dass Persönlichkeit, Gedächtnis und moralische Urteile weitgehend von der Gehirnstruktur abhängen. Der Fall von Phineas Gage, einer der eindrucksvollsten Fälle der Medizingeschichte, veranschaulicht dies. Gage erlitt eine schwere Schädigung des präfrontalen Kortex und entwickelte danach eine völlig andere Persönlichkeit, andere Werte und andere moralische Urteile. Derselbe Körper, dieselben Erinnerungen, aber ein anderer Mensch.

Alzheimer- und Demenzpatienten verdeutlichen dieses Bild noch stärker. Das Absterben weniger Neuronen kann Vergangenheit, Ehepartner, Kinder und sämtliche moralischen Maßstäbe auslöschen. Wenn die Seele von Hirnschäden in diesem Maße beeinflusst wird, dann widerspricht die Behauptung, sie könne im Augenblick des Todes, wenn das Gehirn vollständig zugrunde geht, ohne Schaden in einen anderen Körper überspringen, der biologischen Wirklichkeit auf das Schärfste.

Die Reinkarnation versucht, dieses Problem durch die Annahme eines „vom Gehirn unabhängigen Bewusstseinsträgers" zu lösen. Doch für diesen Träger gibt es keinerlei physische Spur, keinen messbaren Hinweis und kein prüfbares Merkmal. Eine nichtphysische, unmessbare, nicht interagierende Entität zu definieren, fällt in der Erkenntnistheorie in die Kategorie der „Entität, deren Existenz von ihrer Nichtexistenz nicht unterscheidbar ist". In der Metaphysik ist dies ein leeres Postulat.

Gedächtnis, Kryptomnesie und die Analyse der Regressionsbehauptungen

Eines der stärksten Argumente der Befürworter der Reinkarnation lautet, dass sich manche Kinder oder hypnotisierte Personen an „frühere Leben" erinnern. In der Psychologie wird dieses Phänomen jedoch mit dem Begriff der Kryptomnesie erklärt. Der Betroffene vergisst Informationen, die er als Kind gehört, gelesen oder im Fernsehen gesehen hat, oder die in seinem Unbewussten verborgen liegen; in Hypnose oder Trance gibt er diese Informationen wieder, indem er sie so darstellt, als hätte er sie selbst erlebt.

Die von Ian Stevenson von der Universität Virginia geleiteten Forschungen gehören zu den meistzitierten Arbeiten auf diesem Gebiet. Doch sie weisen erhebliche methodische Probleme auf. Dass die meisten Fälle in Kulturen gesammelt wurden, die an Reinkarnation glauben, wirft die Frage nach kultureller Beeinflussung und dem Effekt von Erwartungen auf. Dass die Untersuchungen oft erst nach dem Sprechen des Kindes einsetzen, macht das Durchsickern von Informationen unvermeidbar. Paul Edwards und andere Kritiker haben suggestive Befragung, Übersetzungsfehler und selektive Berichterstattung ausführlich dokumentiert.

Die Gedächtnisforschung von Elizabeth Loftus erschüttert zudem die Verlässlichkeit der hypnotischen Regression von Grund auf. Durch suggestive Fragen lassen sich bei Menschen Erinnerungen an Ereignisse erzeugen, die sie nie erlebt haben, und diese fühlen sich dennoch wie echte Erinnerungen an. Bis heute ist kein einziges „Datum aus einem früheren Leben" in einer kontrollierten Laborumgebung wissenschaftlich verifiziert worden.

Ebenso darf nicht übersehen werden, dass unter Milliarden von Menschen und Kindern zwangsläufig zufällige Ähnlichkeiten auftreten. Häufige Namen, verbreitete Todesarten und nachträgliche Interpretation ergeben zusammen mit selektiver Veröffentlichung einen Nährboden, auf dem statistisch „interessante" Fälle entstehen.

Libet-Experimente und das Schicksal: Bewusstsein erklärt die Handlung, es verursacht sie nicht

Die Experimente, die Benjamin Libet 1980 durchführte, haben das Verständnis von Bewusstsein und Willen grundlegend in Frage gestellt. Die im motorischen Kortex auftretende EEG-Aktivität, das sogenannte Bereitschaftspotential, beginnt 350 bis 500 Millisekunden, bevor die Versuchsperson das bewusste Gefühl meldet, sich zu einer Entscheidung entschlossen zu haben. Das Gefühl „ich habe mich entschieden" ist also nicht die Ursache der Handlung, sondern eine nachträgliche Erklärung, die das Gehirn der Handlung hinzufügt.

Dieser Befund ist auch für die Diskussion über die Reinkarnation bedeutsam. Wenn das Bewusstsein einer bereits angelegten Handlung rückwirkend das Etikett „ich habe es getan" anheftet, dann werden Begriffe wie die „Anhäufung des freien Willens" und die „Karma-Abrechnung", die das Reinkarnationssystem voraussetzt, noch grundloser. Das Karmagesetz setzt eine moralische Akkumulation von Handlungen voraus, die über mehrere Leben hinweg begangen worden sein sollen. Doch selbst der mentale Urheber dieser Handlungen ist umstritten. Zu behaupten, es existiere ein „Selbst", das diese Handlungen über mehrere Körper hinweg verfolgt und Buch führt, erscheint unmöglich.

Das Gehirn im Lichte der Shannonschen Informationstheorie: Keine Übertragung

Die Reinkarnation beinhaltet auch die Behauptung einer Informationsübertragung: Das Wissen, die Anhäufung und der Charakter, die die Seele trägt, gehen von einem Körper in den anderen über. Betrachtet man dies im Rahmen der Informationstheorie Shannons, so entspricht diese Übertragung über den Kanal null übertragenen Bits. Für eine Informationsübertragung müssen Struktur, Inhalt und Kontinuität zugleich vorhanden sein. Im Reinkarnationsmodell wird der Inhalt gelöscht, die Struktur bleibt nicht erhalten und die Kontinuität bricht ab. Was dann übertragen wird, ist keine Information, sondern bedeutungsloses Rauschen. Die Behauptung der „Wesensübertragung“ steht somit auch im Widerspruch zu den Grundprinzipien der Informationstheorie.

Kritik aus moderner Physik und Kosmologie

Thermodynamik: Die Reinkarnation als Perpetuum mobile

Der zweite Hauptsatz der Thermodynamik besagt, dass in einem abgeschlossenen System die Entropie, also die Unordnung, stets zunimmt. Stirbt ein Mensch, so löst sich das komplexe, niedrig entropische Informationssystem, das ihn ausmacht (Gehirn und Bewusstsein), in seine hoch entropische Umgebung auf und zerfällt. Die Reinkarnation behauptet dagegen, dass diese verstreute, hoch entropische Information aufgenommen, wieder zu einem niedrig entropischen, geordneten Bewusstseinskern zusammengefügt und in einen neuen Körper eingespeist wird. Thermodynamisch hieße das, den Zeitpfeil lokal umzukehren. Systeme, die die Entropie lokal senken, etwa das Leben, arbeiten mit einem enormen Energiezufluss von außen. Ein Kreislauf, in dem Milliarden Seelen ständig sterben, sich auflösen und danach ohne jeden Informationsverlust wieder organisieren, kann jedoch nicht erklären, wie das Bewusstsein nach dem Tod bewahrt wird. Mit dem Energiehaushalt des Universums ist dieses Bild nicht vereinbar.

Blockuniversum-Modell und die topologische Unmöglichkeit der Reinkarnation

Nach dem Blockuniversum-Modell, einer zwingenden Konsequenz der allgemeinen Relativitätstheorie Einsteins, sind Vergangenheit, Gegenwart und Zukunft ontologisch nicht voneinander verschieden; alle Ereignisse existieren gleichermaßen real in der vierdimensionalen Raumzeit-Mannigfaltigkeit. Das Bewusstsein und das Leben eines Menschen, der 1920 starb, verharren eingefroren an ihren Raumzeit-Koordinaten für immer. In diesem Rahmen ist nicht erklärbar, wie Reinkarnation funktionieren sollte. Bewusstsein ist eine kontinuierliche Weltlinie, die sich durch die Raumzeit-Mannigfaltigkeit erstreckt. Diese Linie zu durchtrennen und an einer anderen Koordinate neu beginnen zu lassen, ist eine topologisch ebenso absurde Forderung, wie zu verlangen, dass eine geometrische Linie im Innern eines Würfels dessen Struktur zerstört und plötzlich an einer anderen Ecke erscheint. Die Vergangenheit ist ja nicht untergegangen, sodass die dortige Seele frei werden und in einen künftigen Körper springen könnte.

Diese Auffassung steht zudem in tiefem Einklang mit den Aussagen des Korans über das Schicksal. In Sure Al-Hadid, Vers 22, wird mitgeteilt, dass alles vor seinem Eintreten in einem Buch verzeichnet ist. Die erkenntnistheoretische Parallele zum Blockuniversum zeigt sich hier: Vergangenheit, Gegenwart und Zukunft existieren im Wissen Gottes gleichzeitig.

Quantenmechanik und Bewusstsein: Der Beobachter erzeugt die Wirklichkeit

Eine der grundlegenden Erkenntnisse der Quantenmechanik ist, dass ein nicht beobachtetes System keine objektive Position besitzt. Die Beobachtung konstruiert die Wirklichkeit. Im Kontext der Reinkarnationsdebatte bedeutet dies: Auch die Vorstellung, dass sich ein Bewusstsein als unabhängiger Träger von Körper zu Körper bewegt, steht im Widerspruch zum Wirklichkeitsverständnis auf quantenmechanischer Ebene. Jedes Bewusstsein ist das Produkt einer einzigartigen Abfolge von Beobachtern; ohne das spezifische neuronale Netz, die genetische Struktur und die Erfahrungsbildung des Körpers kann ein solches Bewusstsein nicht existieren. Wie Amit Goswami es formuliert, existiert in Raum und Zeit kein Objekt, wenn keine bewusste Person es betrachtet. Die Reinkarnation nimmt dagegen das Gegenteil an, nämlich ein vom Körper unabhängig umherziehendes Bewusstsein, das auf den Körper einwirkt.

Die gegenwärtigen neurowissenschaftlichen Daten zeigen, dass Persönlichkeit, Gedächtnis und Selbsterleben aufs Engste mit dem Gehirn verbunden sind. Die Behauptung, dass dasselbe personale Bewusstsein nach dem Tod seine Integrität bewahrt und in einem anderen Körper fortbesteht, entbehrt daher jeder empirischen Stütze. Das macht die Annahme eines „unabhängigen Seelenträgers“ noch unbegründeter.

Kosmologische Ökonomie und ontologische Verschwendung

Der universelle Mechanismus arbeitet nach dem Prinzip des geringsten Aufwands: Er strebt das wirksamste Ergebnis mit dem geringsten Energieeinsatz an. Die Reinkarnation dagegen vervielfacht die Komplexität des Systems, ohne die Erklärungskraft zu steigern. Wenn das „Ganze“ am Anfang steht und am Ende wieder das „Ganze“ sein wird, sind die dazwischen liegenden Billionen Reinkarnationszyklen für den universellen Mechanismus eine buchstäbliche ontologische Verschwendung. Aus der Sicht der Kolmogorov-Komplexität widerspricht das Reinkarnationssystem dem Prinzip der algorithmischen Informationstheorie, das minimalen Code für maximalen Output verlangt. Das Hinzufügen unendlich vieler Zwischenleben, um dasselbe Individuum hervorzubringen, führt im System zu einem unlösbaren Schleifenfehler (infinite loop). Es handelt sich um ein fremdes und funktionsloses Add-on in der Kodierungsarchitektur des Universums.

Die soziale und ideologische Kritik der Reinkarnation

Das Karma-System und die Legitimierung historischer Ungerechtigkeiten

Der Reinkarnationsglaube lässt sich nicht losgelöst von seinem historischen Kontext beurteilen. Das in Indien entstandene und über Jahrhunderte bestehende Kastensystem ist eng mit der Lehre von der Reinkarnation verbunden, denn es wurde im Lauf der Geschichte mit Reinkarnations- und Karma-Lehren legitimiert. Die Botschaft dieser Lehre ist eindeutig: Wer als Paria geboren wurde, trägt die Strafe für die Sünden eines früheren Lebens; statt sich aufzulehnen, sei Fügsamkeit geboten. Diese Lehre verhindert, dass Unterdrücker zur Rechenschaft gezogen und den Unterdrückten ihre Rechte „hier und jetzt“ verschafft werden. Sie verlegt soziale Gerechtigkeit in eine imaginäre Zukunft und einen kosmischen Kreislauf und rechtfertigt so die gesellschaftliche Hierarchie. Betrachtet man es so, erfüllt der Reinkarnationsglaube nicht nur die Funktion einer metaphysischen Behauptung, sondern auch die einer wirkmächtigen politischen Ideologie.

Das Bild, das der Islam zeichnet, steht dieser Auffassung diametral entgegen. Im Koran ist jeder Mensch für seine eigenen Taten verantwortlich; niemand trägt die Sünde eines anderen. Angesichts von Ungerechtigkeit zu schweigen ist keine Tugend. Gerechtigkeit wird in dieser Welt eingefordert und nicht ins Jenseits vertagt.

Die nicht-islamischen kulturellen Wurzeln der Reinkarnation

Der Reinkarnationsglaube gehört seinen historischen Wurzeln nach zu den vorislamischen Kulturen Indiens, Griechenlands und Ägyptens. Die Koranauslegungen, mit denen man diesen Glauben in den islamischen Rahmen zu tragen versucht, bleiben Lesarten, die aus dem Textzusammenhang gelöst und so konstruiert sind, dass sie dem eigenen Glaubensgebäude dienen. Die Verse über die Verwandlung in Affen als Beleg für die Reinkarnation anzuführen, ist eine erzwungene Deutung, die den grundlegenden Unterschied zwischen Seelenwanderung und der augenblicklichen Bestrafung einer Gemeinschaft übersieht.

Der Koran bietet dem Menschen eine eigenständige Existenz, deren Wurzeln nicht in dunklen mystischen Lehren liegen, sondern im Geist, den Gott dem Menschen eingehaucht hat. Dieser Geist strömt nicht blind in einem zyklischen Karma-System dahin. Er ist ein Wesen, das in einem einzigen Leben geprüft wird, am Tag der Auferstehung vor Gottes Angesicht tritt und mit einer einzigartigen Identität Rechenschaft ablegt.

Hier wurde der Reinkarnationsglaube entlang von vier Achsen systematisch analysiert. Jede Achse gelangt mit den Mitteln ihrer eigenen Disziplin zum selben Ergebnis: Die Reinkarnation ist kein kohärentes metaphysisches Modell. Auf der Koran-Achse zeigt sich das Daseinsgefüge des Menschen als kohärentes System, das auf den Prinzipien eines Lebens, einer Prüfung und einer Auferstehung ruht. Die Verse, die die Reinkarnation zu stützen scheinen, tragen diese Deutung bei kontextueller Lektüre nicht; vielmehr bekräftigt der Gesamtbericht des Korans wiederholt und unmissverständlich, dass eine Rückkehr in die Welt nach dem Tod ausgeschlossen ist. Auf der philosophischen Achse zeigt sich, dass die Reinkarnation den Begriff der Identität inhaltsleer lässt, die Kausalität nicht zu retten vermag, das Gerechtigkeitsprinzip in unlösbare Probleme verstrickt und im modalen Raum keine konsistente Beispielwelt hervorbringt. Auf der neurowissenschaftlichen Achse untergraben die enge Bindung des Bewusstseins an die Gehirnstruktur, der konstruktive Charakter des Gedächtnisses und die Unzuverlässigkeit der Regressionsmethode die empirische Grundlage der Reinkarnationsbehauptungen. Auf der Achse der modernen Physik zeigen der Entropiesatz, die topologischen Vorgaben des Blockuniversum-Modells und das Prinzip der ökonomischen Weltordnung, dass sich die Reinkarnation mit der kosmologischen Dimension nicht vereinbaren lässt.

Über all diese Analysen hinaus lautet der grundlegendste Einwand: Die Reinkarnation ist kein Versuch, die Kontinuität der Seele zu erklären; sie ist eine metaphysische Konstruktion, die den Begriff der Kontinuität zerlegt und dabei den Anschein einer Erklärung erweckt. Diese Konstruktion entwertet das einmalige Leben des Menschen in dieser Welt, verwischt seine Verantwortung und sperrt die Gerechtigkeit in einen unbestimmten Kreislauf ein. Die Wahrheit, die der Koran dem Menschen vermittelt, sagt das Gegenteil: Dieses Leben ist einzig und einmalig. Diese Prüfung hat keine zweite Runde. Und diese Wahrheit muss nicht erkannt werden, um jeden Augenblick bedeutungslos zu machen, sondern um jeden Augenblick in tiefer Verantwortung zu leben. Wahre Rettung liegt nicht darin, sich in die Illusion wiederkehrender Leben zu flüchten, sondern darin, dieses eine, einmalige Leben im Einklang mit dem Wohlgefallen Gottes zu führen.', 'Eine umfassende Analyse im Lichte von Koran, Philosophie, Neurowissenschaft und Physik Im Verlauf der Menschheitsgeschichte hat der Tod die ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/eine-mehrdimensionale-kritik-des-reinkarnationsglaubens-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Beceri İşi İle  3', 'otizmli-sarper-beceri-i-si-i-le-3-mehmet-tevfik-temizturk-3-ol3h1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anne eğitim vermiş kalpten sevgisi ile

Baba da ilgilenmiş düşünce yüklemekle,

Hem saygı göstermişler saygı göstersin diye,

Hem de sevgi işi ile yürekten bir seviye,

Vicdanı da bilmekte merhamet şekli ile

Rab korkusu da dâhil ruhu besler bir hâlle,

Dememişler otizmli boş ver her ne olursa,

İlgilenmeyiver geç zaman harcamaktansa…', 'Anne eğitim vermiş kalpten sevgisi ile Baba da ilgilenmiş düşünce yüklemekle, Hem saygı göstermişler saygı göstersin diye, Hem de sevgi işi ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-beceri-isi-ile-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Bayrak Sayacağım Diyordu  9', 'otizmli-sarper-bayrak-sayacagim-diyordu-9-mehmet-tevfik-temizturk-3-j1qnl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani anlatabilsek diyeceğiz gel haydi,

Atlas getirme ile söylemek her çeşidi,

Okul içerisinde tekrarlamalarıyla,

Yüksek sesle bağırıp da ağlamalarıyla,

Bayrak sayacağım, der sağlasak da yararı,

Gittiği yerle mi ilgili bitmez tekrarı…', 'Hani anlatabilsek diyeceğiz gel haydi, Atlas getirme ile söylemek her çeşidi, Okul içerisinde tekrarlamalarıyla, Yüksek sesle bağırıp da ağl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-bayrak-sayacagim-diyordu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Teklifim Var', 'bir-teklifim-var-senturk-dursun-6i7py', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR TEKLİFİM VAR

Ey gönlümün maralı sana bir teklifim var

Yine eski günlere, dönelim mi ne dersin?

Yeter artık bunca kış, bize de gelsin bahar

O çocuksu yaşlara, inelim mi ne dersin?

Sevelim sevilelim şu üç günlük hayatta

Yeni rol üstlenelim sevda adlı sanatta

Olmazı başaralım buluşalım vuslatta

Felek denen illeti, yenelim mi ne dersin?

Güneşin batışıyla kararmadan sokaklar

Hazana bürünmeden dallardaki yapraklar

Kabire dönüşmeden gül kokulu topraklar

Biz de aşkın narıyla, yanalım mı ne dersin?

O gider ben giderim bahtımın peşi sıra

Saatler dakikalar sensiz döndü asıra

Albümlerde kalmasın bunca mektup hatıra

Aşk için son bir fırsat, sunalım mı ne dersin?

İçimde uçuşurken kanatsız kelebekler

Ruhuma can taşıyor yorgun argın yürekler

Sensiz hiçbir mevsimde açılmıyor çiçekler

Anka olup gülzara, konalım mı ne dersin?

ŞENTÜRK DURSUN', 'BİR TEKLİFİM VAR Ey gönlümün maralı sana bir teklifim var Yine eski günlere, dönelim mi ne dersin? Yeter artık bunca kış, bize de gelsin bah...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-teklifim-var-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Bayrak Sayacağım Diyordu  8', 'otizmli-sarper-bayrak-sayacagim-diyordu-8-mehmet-tevfik-temizturk-3-8qo5h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bayrak sayacağım, der sesini yükseltmekle,

Duygularımızı meraklandırma işiyle,

Atlasları mı vardı Türk bayrakları ile

Ya da tüm Dünya’daki bayrak çeşitleriyle,

Gün içerisinde ısrar eder hâllerdeydi,

Evi aramalıydık, bu bayrak işi neydi?', 'Bayrak sayacağım, der sesini yükseltmekle, Duygularımızı meraklandırma işiyle, Atlasları mı vardı Türk bayrakları ile Ya da tüm Dünya’daki b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-bayrak-sayacagim-diyordu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-senturk-dursun-v8xsw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENDEN SONRA

Unutmam mümkün değil adın dilimde ezber

Gönlüme bir başkası, girmedi senden sonra

Çıktığım aşk yolunda sendin bana tek rehber

Gönül gözüm kimseyi, görmedi senden sonra

Pansumanı olmazmış yürekteki yaranın

Faydası yok figanın, faydası yok naranın

Sonu hep ayrılıkmış aşk denen maceranın

Hüzün yüklü yağmurlar, durmadı senden sonra

Zamansız gazel düştü sevdamın ağacına

Mutluluğum takıldı feleğin kıskacına

Katran renkli sis çöktü umudun yamacına

Aşk saati vuslatı, vurmadı senden sonra

Ruhumdaki semadan kor yağıyor elime

Kirpiğimden kan damlar cefakâr mendilime

İflah olmaz derdim var yüreğim lime lime

Hiç kimse hatırımı, sormadı senden sonra

Kâr etmez dilimdeki bu sitem bu yakarış

Bitmek nedir bilmiyor gönlümdeki karakış

Düşlerimde dolaşır hayalin nakış nakış

Kollarım bir güzeli, sarmadı senden sonra

ŞENTÜRK DURSUN', 'SENDEN SONRA Unutmam mümkün değil adın dilimde ezber Gönlüme bir başkası, girmedi senden sonra Çıktığım aşk yolunda sendin bana tek rehber G...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senden-sonra-627-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Olmak', 'i-nsan-olmak-eminnur-acar-2-ibii3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Artık üzemez kimse beni, zira üzenler yok hükmünde

Olmayan bir şeye üzülür mu? kişi

Kimseye fazla değer vermemeli

Her kes ederi kadar kıymetli

Her olay, her kişi, birbirlerine verir, ders

Dünya öğrenme yeri

Her yaratılan farklı görevde

Her ne yaparsa kendine yapar insan

Verdiği kadar alır, ektiğini biçer

Nefsine dur diyebilendir insan

Gerisi mahlukat

Mahlukat, yer içer, uyur ve ürer

İnsan, sevgi dolu, iyilik eden

Şükür ve sabır bilendir

Nankör olmaz, kendini bilir

Kendini bilen, Rabbini de bilir

Aldığın kararlara sabır ve sebat

Yaşarken, verebilmektir

Kötü hasletlerine dur diyebilmektir, marifet

Birde böyle yaşlaşabilmektir, hüner

Yaratan bizim mutlu olmamızı ister

Mutluluk, dünya ve alemler kurallarına uymakla olur

Uymayanlar hem bu alemde hem ahiretinde mutsuzdur

Tüm insanlık için geçerlidir bu kurallar, insana yakışan budur', 'Artık üzemez kimse beni, zira üzenler yok hükmünde Olmayan bir şeye üzülür mu? kişi Kimseye fazla değer vermemeli Her kes ederi kadar kıymet...', ARRAY['Türk Edebiyatı','Şiir','Eminnur Acar 2']::text[], 8.5, '{"poet":"Eminnur Acar 2","poet_slug":"eminnur-acar-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insan-olmak-186-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Başkandı  4', 'otizmli-sarper-baskandi-4-mehmet-tevfik-temizturk-3-h5niv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevcudu tek kişiyse başkan seçimi için,

Susmayınca kendini susturabilmelisin,

Diyemezdik, başkan için kimler olmak istiyor,

Başkan olma yolunda oy kullanabiliyor,

Dedik, sen tek adaysın kendinden bahsediver,

Ardından yerine geç el kaldır oyunu ver…', 'Mevcudu tek kişiyse başkan seçimi için, Susmayınca kendini susturabilmelisin, Diyemezdik, başkan için kimler olmak istiyor, Başkan olma yolu...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-baskandi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Başını Vurdukça  9', 'otizmli-sarper-basini-vurdukca-9-mehmet-tevfik-temizturk-3-ohg2a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen anneden laf telefondan gelir gibi,

Baş vurma eylemini, dengeleme sebebi,

Artık ne baş vurulur ne de başvurulacak,

Baş vurma yolundan dertler yaşatılacak,

Davranış işlevi ile söz kâr sağlamıştı,

Baş vurulmasına başvurulamayacaktı…', 'Bazen anneden laf telefondan gelir gibi, Baş vurma eylemini, dengeleme sebebi, Artık ne baş vurulur ne de başvurulacak, Baş vurma yolundan d...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-basini-vurdukca-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reis', 'reis-senturk-dursun-p7gyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'REİS

Sen yeter ki iste Reis

Bedeninde can oluruz

Soluğunda son bir nefes

Damarında kan oluruz

Saflarında dizilirken

Gökyüzünde süzülürken

Üzüntünle üzülürken

Sevincinle şen oluruz

Ruh dünyanda hisli gönül

Bağbanında öten bülbül

Yollarında dikensiz gül

Kervanına han oluruz

Ödesen de türlü diyet

Arkandadır bütün ümmet

Ülkü ise istikamet

Pusulanda yön oluruz

Bağlamanda nağme teli

Sabahında seher yeli

Dostlarına sevgi seli

Düşmanına kin oluruz

Gönüldedir bizde tüzük

Hedefimiz arştan büyük

Çoğalırız bölük bölük

Her cephede ön oluruz

Her soruya sende cevap

Yazsam almaz defter kitap

Gecelere süslü mehtap

Şafağına tan oluruz

Yasımızdır senin yasın

Kısılmasın güçlü sesin

Kararımız net ve kesin

Senden öte sen oluruz

Yolda tuzak var olsa da

Yürümesi zor olsa da

Oklar sana doğrulsa da

Zırhla kaplı ten oluruz

ŞENTÜRK DURSUN', 'REİS Sen yeter ki iste Reis Bedeninde can oluruz Soluğunda son bir nefes Damarında kan oluruz Saflarında dizilirken Gökyüzünde süzülürken Üz...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/reis-111-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendrom', 'sendrom-senturk-dursun-y6mv8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SENDROM

Stockholm sendromu yaşarsa bir zat

Kendi katilinin âşığı olur

Gözüne perdeler dizilir kat kat

Sömürge kafanın uşağı olur

Farkında değilse iyi kötünün

Kölesi kesilir vahşi batının

Sırtını sıvamaz kendi atının

Elin katırına kaşağı olur

Goygoylar çoğalır sesler gürleşir

Düşman saflarında hepsi birleşir

Herkesin gözünde değersizleşir

Alçaktan daha da aşağı olur

Şayet silinmişse tarihi bellek

Hasmına destektir hısmına köstek

Yurduna kasteden satılık köpek

Emperyal güçlerin fişeği olur

Soylu geçmişini inkâr ederse

Soysuzun çizdiği yolda giderse

Gündelik çıkarı kâr zannederse

Her semer vuranın eşeği olur

Eğer ki hayâsız açarsa falı

İffet yırtık çıkar edep yamalı

Ya bir pezevengin satılık malı

Ya bir orospunun döşeği olur

ŞENTÜRK DURSUN', 'SENDROM Stockholm sendromu yaşarsa bir zat Kendi katilinin âşığı olur Gözüne perdeler dizilir kat kat Sömürge kafanın uşağı olur Farkında de...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sendrom-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Başını Vurdukça  8', 'otizmli-sarper-basini-vurdukca-8-mehmet-tevfik-temizturk-3-vf8po', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anneyi tanımasak diyemeyiz bu ses kim?

Bu kimin taklidi de tepki verir, bir hâlim,

Hem her tepki işinden doğruya ulaşmakla,

Hem de her doğru ile fikir ve yol almakla,

O anda da duruyor, bir kenara çekilip,

Annesi varmış gibi davranış geliştirip,

Sonrası bir nasihat rehber niteliğinde,

Sıkıntı engellenir yol gösterme işinde…', 'Anneyi tanımasak diyemeyiz bu ses kim? Bu kimin taklidi de tepki verir, bir hâlim, Hem her tepki işinden doğruya ulaşmakla, Hem de her doğru...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/otizmli-sarper-basini-vurdukca-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimliğimiz', 'kimligimiz-senturk-dursun-spbil', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KİMLİĞİMİZ

Kimliğimiz net bizim gerek yok fazla söze

Erliğin yazıldığı öyküye sorun bizi

Miğferin altındaki gururla kaplı yüze

Şehidin üstündeki örtüye sorun bizi

Hak yolun adaletin mizanı ölçüsüyüz

Kuşaklardan kuşağa devreden elçisiyiz

Mukaddes bir davanın cengâver bekçisiyiz

Adına Haçlı denen sürüye sorun bizi

Her zaman biz söyleriz son sözü son kararı

Gerekli görüyorsak keseriz şah damarı

Hak edene çakarız bir Osmanlı şamarı

Namlunun ucundaki süngüye sorun bizi

Sönmedi sönmeyecek parlayan yıldızımız

Dinmedi dinmeyecek baş döndüren hızımız

Değişmedi değişmez şiarımız özümüz

Gittiğimiz hedefe ülküye sorun bizi

Yaradan’dan ötürü kula olan sevgimiz

Mazlumun karşısında zalimledir cengimiz

Dünyanın dört yanında susmaz bizim ezgimiz

Destansı ağıtlara türküye sorun bizi

Yüzyıllardır haykırdık üstüne basa basa

Söz konusu vatansa hükümsüzdür her yasa

Soydaşa kanat gerdik Balkanlardan Kafkas''a

Aşkabat''a Taşkent''e Bakü''ye sorun bizi

ŞENTÜRK DURSUN', 'KİMLİĞİMİZ Kimliğimiz net bizim gerek yok fazla söze Erliğin yazıldığı öyküye sorun bizi Miğferin altındaki gururla kaplı yüze Şehidin üstün...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kimligimiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Başını Vurdukça  7', 'otizmli-sarper-basini-vurdukca-7-mehmet-tevfik-temizturk-3-23ef8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anne akla gelince yanındaymış gibi,

Hâli ve de sesiyle sanki hakikat gibi,

Davranış alınıyor bilinçlenme işinde,

Doğruya varılıyor içten gelir şekilde,

Biz bile görüyorduk anne taklitleriyle, 

“Başın kanarsa dikiş atarlar.” Lafı ile', 'Anne akla gelince yanındaymış gibi, Hâli ve de sesiyle sanki hakikat gibi, Davranış alınıyor bilinçlenme işinde, Doğruya varılıyor içten gel...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-basini-vurdukca-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Başını Vurdukça  6', 'otizmli-sarper-basini-vurdukca-6-mehmet-tevfik-temizturk-3-m4m0a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Davranış alınmıştı velimizin sesiyle,

Sert ve de tok bir sesle anneden tembihlerle, 

Yüzünü çevirmeden başın kanarsa deyip,

Dikiş atarlar davranışını hissettirip,

Bu bilinç işi idi davranış göstermekle,

Yanında olmasa bile korku hissettirmekle,

Başını vurma ile anneden taklitlerle,

Verdiği uyarıyla benzeyen sesler ile

Ardından vazgeçiyor anneyi hissetmekle,

Bilinç fikri gereği geriye çekilmekle…', 'Davranış alınmıştı velimizin sesiyle, Sert ve de tok bir sesle anneden tembihlerle,  Yüzünü çevirmeden başın kanarsa deyip, Dikiş atarlar da...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/otizmli-sarper-basini-vurdukca-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Ne Yapsam ki?', 'daha-ne-yapsam-ki-senturk-dursun-hndxy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DAHA NE YAPSAM Kİ?

Gönül bahçemizi çiledim her gün

Yeşeren aşkımız solmasın diye

Sitemkâr bir kelam etmedim bir gün

Vuslata bir zeval gelmesin diye

İçim ağlasa da tebessüm saçtım

Ağuyu aş bildim baldıran içtim

Maziyi yok saydım gururdan geçtim

Sevdamız yarıda kalmasın diye

İsyankâr olmadım düştüğüm hale

Dört elle sarıldım sabrı cemile

Sır gibi sakladım kendimden bile

Senden bir başkası bilmesin diye

Katlandım her sefer ettiğin naza

Açmadım ağzımı döndüm ahraza

Yalvardım notaya dil döktüm saza

Ayrılık şarkısı çalmasın diye

Her şeyden yeğ tuttum her şeyden önce

Her gün çile çektim her gün işkence

Daha da ne yapmam gerekli sence

Sevgimden bir şüphen olmasın diye

ŞENTÜRK DURSUN', 'DAHA NE YAPSAM Kİ? Gönül bahçemizi çiledim her gün Yeşeren aşkımız solmasın diye Sitemkâr bir kelam etmedim bir gün Vuslata bir zeval gelmes...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/daha-ne-yapsam-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Babasıyla 12', 'otizmli-sarper-babasiyla-12-mehmet-tevfik-temizturk-3-3f8zy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şahsım varken gezmiştik okul dışı da olsa,

Sarper gel diyerekten iş bilinç sağlamaksa,

Adel, Hasan birlikte evveli zamanlarda,

Bilinçlendirmelerle, parkın alanlarında,

Kerem de vardı ki anne gezdir dediğinde,

Elinden tutup da gezdirelim denildiğinde…', 'Şahsım varken gezmiştik okul dışı da olsa, Sarper gel diyerekten iş bilinç sağlamaksa, Adel, Hasan birlikte evveli zamanlarda, Bilinçlendirm...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Temiztürk 3']::text[], 8.5, '{"poet":"Mehmet Tevfik Temiztürk 3","poet_slug":"mehmet-tevfik-temizturk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/otizmli-sarper-babasiyla-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Babasıyla 11', 'otizmli-sarper-babasiyla-11-mehmet-tevfik-temizturk-3-789xp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çoğu kez rastlar idik babası gezdiğinde,

