INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otizmli Sarper Babasıyla 10', 'otizmli-sarper-babasiyla-10-mehmet-tevfik-temizturk-3-s4y3m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne laf geçer ne de söz yapma! Denilse bile,

Yapma! Deme deyip de hâlini sürdürmekle,

Bol akıntı içinden davranış bulamadan,

Belli etmez bir hâli sıkıntı çıkarmadan,

