INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıllanmış Şiirler', 'yillanmis-siirler-hasan-kara-3-5tubi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÇOK ZAMAN  HÜZÜN ESTİREN,

KELİMELERLE KONOŞUP AĞLAYAN.

AYRILIK ,HASRET KOKAN,

DERBEDERDİR ŞİİRLER.

BAZEN MEŞE SEVİNÇ VEREN.

BAYRAM.SEYRAN DİYEN,

MUTLU ÇOCUKLAR GİBİ ŞEN.

KEYİFLİDİR ŞİİRLER.

ANA,YR VE DE VATAN,

AKITIR GÖZLERİNDEN KAN.

ANLATIR DÜNYAYA DESTAN,

ŞANLIDIR ŞİİRLER.

SEVGİ ,AŞKLA DOLU,

GURBET,ÖZLEM YOLU.

HÜSRANDIR BİRAZ SONU.

YARALIDIR ŞİİRLER.', 'ÇOK ZAMAN  HÜZÜN ESTİREN, KELİMELERLE KONOŞUP AĞLAYAN. AYRILIK ,HASRET KOKAN, DERBEDERDİR ŞİİRLER. BAZEN MEŞE SEVİNÇ VEREN. BAYRAM.SEYRAN Dİ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kara 3']::text[], 8.5, '{"poet":"Hasan Kara 3","poet_slug":"hasan-kara-3","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yillanmis-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Karanlık', 'beyaz-karanlik-erdogan-cam-xsp7n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gece kar yağıyor şehrin saçlarına,
Sokak lambaları mahcup birer yıldız.
Ben eski paltomun içinde,
Biraz yorgun, biraz kırgın,
Biraz da dünyaya fazlalıkmışım gibi yalnız.

Kar taneleri konuyor omuzlarıma,
Beyaz kelebekler gibi, ürkek ve sessiz.
Silkelemiyorum hiçbirini,
Bırakıyorum kalsınlar.
Ne zamandır böylesine nazik
Dokunmamıştı bana hiçbir şey.

Yürüyorum...
Ayaklarımın altında ince bir kar,
Üstümde sonsuzluğa açılan gökyüzü.
Arkamda bıraktığım izlere bakıyorum,
Sanki beyaz bir kâğıda
Hüzünle yazılmış ömrümün son sözü.

Bir parkın önünde duruyorum,
Ağaçlar beyaz duvaklarını giymiş.
Dallarında uyuyan kar taneleri,
Sanki gökyüzünden koparılmış
Küçücük birer düşmüş.

Eski bir banka oturuyorum,
Yanımda kış, karşımda gece.
Bir sokak lambası eğilmiş üzerime,
Sanki sarı saçlı bir melek
Teselli arıyor yüzümde.

Paltomun yakasını kaldırıyorum,
Rüzgâr usulca geçiyor içimden.
Bir kar tanesi düşüyor avucuma,
Bakıyorum uzun uzun...
Ne kadar da benziyor insana,
Dokunur dokunmaz eriyen.

Uzakta bir pencere yanıyor,
Perdesinde titreyen sıcak bir ışık.
Kim bilir hangi odada
Bir çay demleniyor şimdi,
Hangi duvarda bir saat
Mutluluğu sayıyor yavaşçacık.

Ben burada, bu eski bankta,
Gecenin kalbine yaslanmışım.
Bir yanım çocukluğumun bahçesi,
Bir yanım sonbahar.
Meğer ben yıllardır
Kendi içime yağan bir kışmışım.

Kar yağıyor kirpiklerime,
Gözlerimde eriyor ince ince.
Kimse bilmiyor,
Hangisi gökyüzünden düşen,
Hangisi içimden süzülen
Bu sessiz gecede.

Bir ara başımı kaldırıyorum,
Ay, bulutların arasından bakıyor.
Beyaz bir mendil gibi gece,
Şehrin gözyaşlarını siliyor.
Ve ben ilk defa anlıyorum,
Bazen insanı en çok
Güzel şeyler ağlatıyor.

Sonra kalkıyorum banktan,
Üzerimde birikmiş karları silmeden.
Bırakıyorum biraz beyazlık kalsın,
Bu kadar karanlık bir ömrün üzerinde.

Yürüyorum ağır ağır,
Arkamda incecik ayak izleri.
Kar dolduruyor birer birer,
Sanki dünya benden saklıyor
Yaşadığım bütün geceleri.

Birden duruyorum...
Dönüp bakıyorum ardıma.
Ne ayak izim kalmış,
Ne oturduğum bankın üzerinde gölgem.
Yalnızca kar yağıyor,
Yalnızca gece,
Yalnızca ben...

Ah, ne garip şu hayat...
Gökyüzü binlerce kar tanesini
Birbirine değdirmeden indiriyor da,
Bir insan bazen bütün ömrünü
Tek bir sıcaklığa hasret geçiriyor.

Ve ben...
Bu beyaz gecenin ortasında,
Paltosuna kar, yüreğine hüzün yağan
Yalnız bir adamım.

Sabah olunca güneş doğacak,
Karlar eriyecek, yollar açılacak.
Ama kim bilecek,
Bu gece bir parkın ıssız bankında
Bir adamın içindeki baharın
Sessizce öldüğünü...', 'Bu gece kar yağıyor şehrin saçlarına, Sokak lambaları mahcup birer yıldız. Ben eski paltomun içinde, Biraz yorgun, biraz kırgın, Biraz da dü...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çam']::text[], 8.5, '{"poet":"Erdoğan Çam","poet_slug":"erdogan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/beyaz-karanlik-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık Nasıl Zehirlendi?', 'i-nsanlik-nasil-zehirlendi-onder-karacay-szg82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '§

