INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığın Fedası Bitmez', 'asigin-fedasi-bitmez-senturk-dursun-lk6mm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AŞIĞIN FEDASI BİTMEZ

Gülistan yolları diken olsa da

Bülbülün güllere sevdası bitmez

Çareler tükense, umut solsa da

Sevenin gayreti çabası bitmez

Yolumda fırtına dağımda tipi

Daraldı dünyamın çemberi çapı

Kapandı vuslata açılan kapı

Gönlümün feryadı sedası bitmez

İçimde nehirler dereler çağlar

Bana eşlik eder ovalar dağlar

Aklıma geldikçe gönlüm kan ağlar

Gözümün yaşlara vedası bitmez

Geceler tükenir rüya biter de

Güneşten saçılan ziya biter de

Hava, su kâinat dünya biter de

Bir nazlı bakışın mânâsı bitmez

İçten ağlasa da kalp kalbe güler

Dillerden dökülür türlü övgüler

Aldığı nefesi ikiye böler

Aşığın aşığa fedası bitmez

Simsiyah bulutlar kaplasa ufku

Geceye darılsa gözdeki uyku

Ruhumu terk etse aşk denen duygu

Gönlümün niyazı duası bitmez

ŞENTÜRK DURSUN', 'AŞIĞIN FEDASI BİTMEZ Gülistan yolları diken olsa da Bülbülün güllere sevdası bitmez Çareler tükense, umut solsa da Sevenin gayreti çabası bi...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/asigin-fedasi-bitmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dargınım', 'darginim-muzaffer-rumuz-89tpq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu fani alemde, koca dünyada 

Yağmura dargınım, sele dargınım

Sevgi sevda benden hep uzak oldu

Bülbüle dargınım, güle dargınım 

Aydınlık yüzünü hiç göstermedi 

Baharlar gelir mi, güzüm bitmedi 

Hep mi savaş olur, barış gelmedi 

Mazluma uzanmaz, ele dargınım 

Kimi sefa diyor kimi de günah 

Gözler hep rüyada, gönüller bedbah 

Nasıl unutursun, Muktedir Allah 

Hakkı zikretmeyen dile dargınım 

Gün geldi ağladım, gün geldi güldüm

Bazen düşkün olup yerde süründüm 

Muzaffer topraktı, toprağa döndüm

Beni kabre koyan ele dargınım', 'Bu fani alemde, koca dünyada  Yağmura dargınım, sele dargınım Sevgi sevda benden hep uzak oldu Bülbüle dargınım, güle dargınım  Aydınlık yüz...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Rumuz']::text[], 8.5, '{"poet":"Muzaffer Rumuz","poet_slug":"muzaffer-rumuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/darginim-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Yakın Farkı', 'uzak-yakin-farki-senturk-dursun-4yh7s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'UZAK YAKIN FARKI

Uzaktan görünce dev sandıklarım

Yanına varınca ufaklaştılar

Özüne sözüne inandıklarım

Gidip de soysuzla kucaklaştılar

Kelek çıktı kılavuzu rehberi

Bir adım ileri, üç adım geri

Kendi de bilmiyor gittiği yeri

Dosdoğru giderken yolu şaştılar

Kaçmadık kaçmayız mesuliyetten

Pişmanlık duymayız hiçbir diyetten

Saygıdan vefadan iyi niyetten

Her gün biraz daha uzaklaştılar

Yalanla örtüldü gerçeğin üstü

Gözler görmez oldu vicdanlar sustu

Salyalı ağızlar kinini kustu

Hasetten fesattan dolup taştılar

Tanımaz yurdunu Anadolu’yu

Rafa kaldırdılar milli duyguyu

Bize çok gördüler bir damla suyu

Ellere gelince ırmaklaştılar

Sırtını çevirdi dost arkadaşa

Tekmeler savurdu yediği aşa

Kimi piyon oldu kimisi maşa

Kahpeyle kolkola rol paylaştılar

Bir dönemin şanlı koç yiğitleri

Bitmedi millete husumetleri

Dünün sözümona mücahitleri

Bugün jet hızıyla solaklaştılar

ŞENTÜRK DURSUN', 'UZAK YAKIN FARKI Uzaktan görünce dev sandıklarım Yanına varınca ufaklaştılar Özüne sözüne inandıklarım Gidip de soysuzla kucaklaştılar Kelek...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/uzak-yakin-farki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-senturk-dursun-28w5v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'UNUTAMADIM

Ayrımcılık yaptım kullar içinde

Kimseyi seninle bir tutamadım

Her şeyi unuttum yıllar içinde

Bir tek gözlerini unutamadım

Her gün hayaline daldı gözlerim

Gittiğin yollarda kaldı gözlerim

Ağlaya ağlaya doldu gözlerim

Mendiller tükettim kurutamadım

Sensiz hep eksiğim, hep yarım kaldım

Bağrımın solundan yaralar aldım

Denizlerden geçtim ummana daldım

Yanan yüreğimi soğutamadım

Çağlayan sel oldum bendimi yıktım

Türküler söyledim ağıtlar yaktım

Bütün gün boyunca albüme baktım

Resminle gönlümü avutamadım

ŞENTÜRK DURSUN', 'UNUTAMADIM Ayrımcılık yaptım kullar içinde Kimseyi seninle bir tutamadım Her şeyi unuttum yıllar içinde Bir tek gözlerini unutamadım Her gün...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unutamadim-346-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz İle Geldim Sana', 'soz-i-le-geldim-sana-senturk-dursun-zb2gi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SÖZ İLE GELDİM SANA

Ruhumdan sevda aktı elimdeki kaleme

Şiire dönüştürdüm, söz ile geldim sana

Yokluğunda yas tuttum çile ektim çileme

Dertli bir nağme oldum, saz ile geldim sana

Sen iki cihanımda, vazgeçilmez tutkusun

Sen benim bağımdaki misk-i amber kokusun

Sen içimde bir nefes, ruhumdaki dokusun

Elemlerden arındım, haz ile geldim sana

Sevdalı kelimeler sıralandı dilimde

Senden ayrı kor gezer avucumda elimde

Her şeyim sana bağlı, yaşamak da ölüm de

Dört mevsimi bir ettim, yaz ile geldim sana

Ben seni gizli sevdim, gizli ve de derinden

Karşına çıkamadım, dolaştım izlerinden

Her sefer gözlerimi kaçırdım gözlerinden

Başım önde utangaç, yüz ile geldim sana

Bir kenara bıraktım aklımı izanımı

Hüznümün gölgesinde sakladım figanımı

Dış dünyaya kapattım beş duyu organımı

Yalnız sana bakacak göz ile geldim sana

ŞENTÜRK DURSUN', 'SÖZ İLE GELDİM SANA Ruhumdan sevda aktı elimdeki kaleme Şiire dönüştürdüm, söz ile geldim sana Yokluğunda yas tuttum çile ektim çileme Dertl...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/soz-ile-geldim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-senturk-dursun-o21s7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AYRILIK

Kimi buzdan bir dağ olur üşütür

Kimi ateş olur yakar ayrılık

Kimi bulut olur şemsi kuşatır

Kimi kâbus olur çöker ayrılık

Ayak küser yürüdüğü yoluna

Yaprak küser tutunduğu dalına

Sılalar dönüşür gurbet eline

Bütün hayalleri yıkar ayrılık

Küçüldü şu dünya, küçüldü alem

Gönlümde kasvet var, yüzümde elem

İçimi sızlatır, her lahza her dem

Zehirli bir kurşun sıkar ayrılık

Bindik bir öfkeli felek atına

Ateşten bir gömlek giymiş sırtına

Birgün tufan olur birgün fırtına

Her yerde karşıma çıkar ayrılık

Bugün yarın derken bir ömür geçer

Ruhu viran eyler, bedeni naçar

Yürekte onulmaz yaralar açar

Ne usanır ne de, bıkar ayrılık

ŞENTÜRK DURSUN', 'AYRILIK Kimi buzdan bir dağ olur üşütür Kimi ateş olur yakar ayrılık Kimi bulut olur şemsi kuşatır Kimi kâbus olur çöker ayrılık Ayak küser ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ayrilik-2080-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Ne Demek', 'yalnizlik-ne-demek-senturk-dursun-oefyf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YALNIZLIK NE DEMEK

Yalnızlık ne demek, hasret ne demek

Ayrılık acısı çekenlere sor

Esaret ne demek, gurbet ne demek

Ağlayıp gözyaşı dökenlere sor

Son bakışın gözlerimden gitmiyor

Gönül ocağımda duman tütmüyor

Aşiyan dağıldı bülbül ötmüyor

Gülün feryadını dikenlere sor

Sevinci neşeyi tatmadım gayrı

Can dersen çekildi bedenden ayrı

Çökünce sineye bir derin ağrı

Gidenin ardından bakanlara sor

Sen oynadın sahnemdeki piyeste

Seni çektim her aldığım nefeste

Gariplerin dolaştığı adreste

Sensiz gezindiğim mekânlara sor

Kanatlarım kırk yerinden kanarken

Yorgun düşüp dallarına konarken

Aşk ateşi alev olup yanarken

İçimde patlayan volkanlara sor

ŞENTÜRK DURSUN', 'YALNIZLIK NE DEMEK Yalnızlık ne demek, hasret ne demek Ayrılık acısı çekenlere sor Esaret ne demek, gurbet ne demek Ağlayıp gözyaşı dökenler...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalnizlik-ne-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasımda...', 'kasimda-fatih-mehmet-yigit-2-7t5r7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kasımda...

Kasım rüzgârı usulca dokunur cama,

Bir yaprak düşer, sessizce toprağa.

Kısa günlerin ardından uzar gece,

İçimde eski bir türkü, hem sade hem ince.

Gökyüzü griye çalar ama umut baki,

Her kışın ardında saklı bir bahar ki.

Bir bardak sıcak çay, biraz da sükûnet,

Zaman akar, geride kalır her zahmet.

Fatih Mehmet Yiğit', 'Kasımda... Kasım rüzgârı usulca dokunur cama, Bir yaprak düşer, sessizce toprağa. Kısa günlerin ardından uzar gece, İçimde eski bir türkü, h...', ARRAY['Türk Edebiyatı','Şiir','Fatih Mehmet Yiğit 2']::text[], 8.5, '{"poet":"Fatih Mehmet Yiğit 2","poet_slug":"fatih-mehmet-yigit-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kasimda-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiralık Akıl', 'kiralik-akil-senturk-dursun-duhj8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KİRALIK AKIL

Kendi aklı yetmez oldu kendine

Kiralanmış akıllara inanır

Yenik düştü senaristin fendine

Aslı varken vekillere inanır

Dillerinden nefret akar söz değil

Aya çıksak kahır duyar haz değil

Hepsi üvey hiç birisi öz değil

Sağdan soldan nakillere inanır

Yelken düştü yalpalıyor rotalar

İhanette en öndeki saftalar

Dindarları yobaz diye yaftalar

Kendi gider heykellere inanır

Büyük nedir, küçük nedir tınlamaz

Usul nedir, nizam nedir anlamaz

Ehli sünnet erbabını dinlemez

Cübbelere sakallara inanır

Teğet geçti adap, edep terbiye

Hakaretten gayrı yoktur sermaye

Kafa yormaz işin aslı ne diye

Görsellere şekillere inanır

Hedef koyar hedefine varamaz

Hidayeti Hak yolunu aramaz

Bozkurttaki asaleti göremez

İt köpeğe çakallara inanır

            ŞENTÜRK DURSUN', 'KİRALIK AKIL Kendi aklı yetmez oldu kendine Kiralanmış akıllara inanır Yenik düştü senaristin fendine Aslı varken vekillere inanır Dillerind...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kiralik-akil-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bir Yâre Söz Verdim Bu Gece', 'ben-bir-y-re-soz-verdim-bu-gece-emir-deniz-s36ss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir yâre söz verdim bu gece,
Boyun eğip göz verdim.
Derdi göğsünde büyüttü,
El eda sustu dilim.

Ben bir yâre söz verdim bu gece,
Sessiz sedasız dalıp gittim.
Dolunayda intikam aradım,
Dört duvara hapsoldu bedenim.

Ben bir yâre söz verdim bu gece,
Söz senet oldu, dil şahit.
Göz nizam oldu, akıl vacip.
Hak zalim oldu, gönül bariz.

Ben bir yâre söz verdim bu gece,
Yolda yitirdi kalbi.
Âfâkı darbesiz hicri,
Duygulara susulan hisle.

Ben bir yâre söz verdim bu gece,
Nefsi hâline ait.
Ömrü ölüme hain,
Benliği dünyaya hazin.

Ben bir yâre söz verdim bu gece,
Hüzün buldu her hecede.
Deva aradı sessizce.
Ölü ölüme sustu hiddetle.', 'Ben bir yâre söz verdim bu gece, Boyun eğip göz verdim. Derdi göğsünde büyüttü, El eda sustu dilim. Ben bir yâre söz verdim bu gece, Sessiz ...', ARRAY['Türk Edebiyatı','Şiir','Emir Deniz']::text[], 8.5, '{"poet":"Emir Deniz","poet_slug":"emir-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-bir-yare-soz-verdim-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rütbe Düzeni', 'rutbe-duzeni-senturk-dursun-2xadn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'RÜTBE DÜZENİ

Doğruları dürüstleri hor gördü

Yamuklara rütbe taktı bu düzen

Edepliyle edepsizi bir gördü

Lavuklara rütbe taktı bu düzen

Yeminlerle gerçekleri saklayıp

Suçluları birer birer aklayıp

Horozlara iftiralar yükleyip

Tavuklara rütbe taktı bu düzen

Mağlup kaptı altın kaplı kupayı

Galiplere, hak gördüler sopayı

Yağız attan üstün tuttu sıpayı

Sülüklere rütbe taktı bu düzen

Üstten bakar, fazla inmez derine

Yaşlar yanar kuruların yerine

Biat eder, hem de körü körüne

Döneklere rütbe taktı bu düzen

Fitne fesat yuvasını üs seçti

Mahareti liyakati pas geçti

İlk on birde oynayanı es geçti

Yedeklere rütbe taktı bu düzen

Dost eyledi akbabayı baykuşu

Yoldaş etti avareyi berduşu

Hiçe saydı bağlamayı cümbüşü

Düdüklere rütbe taktı bu düzen

ŞENTÜRK DURSUN', 'RÜTBE DÜZENİ Doğruları dürüstleri hor gördü Yamuklara rütbe taktı bu düzen Edepliyle edepsizi bir gördü Lavuklara rütbe taktı bu düzen Yemin...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/rutbe-duzeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Ettim', 'terk-ettim-senturk-dursun-j7tqj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'TERK ETTİM

Varsın güneş beni yaksın kavursun

Namertlerin gölgesini terk ettim

İsteyenler göbek atsın kıvırsın

Döneklerin bölgesini terk ettim

Fani kuluz Mevla gel der gideriz

Ne gelirse Haktan deriz Hak deriz

Bedel neyse fazlasıyla öderiz

Resmi tarih bilgisini terk ettim

Bir taraftan liyakati vurgular

Bir taraftan dalga dümen kurgular

Doğruyu da yanlışı da sorgular

Mankurtların yergisini terk ettim

Övgü dizer, hastalıklı sisteme

Paydos etti, vicdan denen mahkeme

Mandacılar mesken kurmuş ülkeme

Sömürgeci algısını terk ettim

Yabancıdır, geçmişine özüne

Nefret hakim, kelamına sözüne

Alışamam Mozart’ına cazına

Çağdaşların çalgısını terk ettim

Veee............

Şükür geçti o eski kof kafalar

Meğer varmış nice nice dehalar

Yerde ALTAY, gökyüzünde SİHA’lar

Aşağılık duygusunu terk ettim

Dışardaki bir truva atının

İçerdeki malum kafa zatının

Haçlı ruhlu iki yüzlü batının

Ne diyecek kaygısını terk ettim

ŞENTÜRK DURSUN', 'TERK ETTİM Varsın güneş beni yaksın kavursun Namertlerin gölgesini terk ettim İsteyenler göbek atsın kıvırsın Döneklerin bölgesini terk etti...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/terk-ettim-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Yorgunu Bedenim', 'guz-yorgunu-bedenim-senturk-dursun-ty4uz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'GÜZ YORGUNU BEDENİM

Güz yorgunu bedenim dökerken yaprağını

Feleğin son darbesi ayırdı ikimizi

Bahtımın hırçın yeli yıktı gönül dağını

Kader gözden çıkardı sanki unuttu bizi

Hicranımı anlatmaz hiçbir süslü kelime

Çığlığımı hapsettim kilit vurdum dilime

İçimde paslı hançer yüreğim lime lime

Yaramı senden aldım merhemle geçmez izi

Buz tuttu yanardağlar, korlaştı akarsular

Mehtapsız gecelerde, bölük pörçük uykular

Parçalanmış umutlar, yaralanmış duygular

Hangi yağmur yeşertir, daldan kopan filizi

Yıldızlar gözükmüyor, ufku saran dumandan

Yaşanmamış yıllarım zaman çaldı zamandan

Kuş uçmaz kervan geçmez beklediğim limandan

Suskunluğum kuşattı, ıssızlaşan denizi

                  ŞENTÜRK DURSUN', 'GÜZ YORGUNU BEDENİM Güz yorgunu bedenim dökerken yaprağını Feleğin son darbesi ayırdı ikimizi Bahtımın hırçın yeli yıktı gönül dağını Kader ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guz-yorgunu-bedenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Hali', 'dunya-hali-senturk-dursun-n21t3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'DÜNYA HALİ 

Ben giderim yollar gider

Kervan kalmış han içinde

Bilmem bu yol nasıl biter

Ayaklarım kan içinde

Özleminle soldum her gün

Hayaline daldım her gün

Yaşamadan öldüm her gün

Can yitirdim can içinde

Vakti gelen elbet göçer

Ecel adlı şerbet içer

Bir bakarsın ömür geçer

Zaman erir an içinde

Kar borandır gönül dağım

Hazanlaştı bahçe bağım

Zayi oldu gençlik çağım

Yıl tükendi gün içinde

Ağlar yağmur ağlar bulut

İçte feryat dilde sükût

Bitti hayal bitti umut

Şafak söndü tan içinde

Kasvetim var çıktı arşa

Gelmez denen geldi başa

Gözde fer yok ruhta neşe

Beden kayıp ten içinde

ŞENTÜRK DURSUN', 'DÜNYA HALİ  Ben giderim yollar gider Kervan kalmış han içinde Bilmem bu yol nasıl biter Ayaklarım kan içinde Özleminle soldum her gün Hayali...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dunya-hali-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekân', 'mek-n-senturk-dursun-zjfvi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'MEKÂN

Sen var iken kış uğramaz gönlüme

Çiçek oldum, dalı mekân eyledim

Konuverdim menekşeye sümbüle

Arı oldum, balı mekân eyledim

Kaderime küstüm sana küsmedim

Ayrı düştük ümidimi kesmedim

Sensizliğe isyan ettim susmadım

Mecnun oldum, çölü mekân eyledim

Bir gülüşü esirgeme nazlı yar

Sevmek için ömür kısa vakit dar

Aklım aldı saçındaki sırmalar

Zülüf oldum, teli mekân eyledim

Sevdam bitmez koca ömür bitse de

Deli gönül binbir acı tatsa da

Dikenleri yüreğime batsa da

Bülbül oldum, gülü mekân eyledim

Duyguları satırlara dökerken

Nefretleri benliklerden sökerken

Yüreklere aşk tohumu ekerken

Sevgi oldum, dili mekân eyledim

                 ŞENTÜRK DURSUN', 'MEKÂN Sen var iken kış uğramaz gönlüme Çiçek oldum, dalı mekân eyledim Konuverdim menekşeye sümbüle Arı oldum, balı mekân eyledim Kaderime k...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mekan-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Kalabilmek…', 'i-nsan-kalabilmek-rezan-farqin-nmxf0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat bize hiçbir zaman kolay bir mutluluk sunmadı sevgili…

Biz, kendi yaralarımızı saklayıp başkalarının kanayan yerlerine merhem olmaya çalıştık. Bir çocuğun açlığına, bir annenin sessiz ağlayışına, bir mahkûmun dört duvar arasında eskittiği ömrüne içimiz yandı.

Çünkü biz, acıyı uzaktan seyretmeyi hiçbir zaman öğrenemedik.

Bir sokak köpeğinin üşümesine üzüldük, kanadı kırılmış bir kuşun gökyüzüne dönemeyişine ağladık. Dünyanın bir ucunda hiç tanımadığımız bir insanın gözyaşı, gelip bizim yüreğimize düştü.

Belki de en büyük yenilgimiz buydu sevgili…

Bu kadar acının içinde hâlâ insan kalabilmek.

Bize güçlü olmayı öğrettiler ama merhametli olmanın bedelini anlatmadılar. Herkes kendi kurtuluşunun peşindeyken biz, başkasının karanlığına bir mum yakmaya çalıştık.

Çok yorulduk…

Çok kırıldık…

Ama kimsenin acısına sırtımızı dönemedik.

Şimdi anlıyorum sevgili; insanın en büyük zenginliği cebindekiler değil, yüreğinde taşıdığı merhamettir.

Ve ne olursa olsun, bu dünyadan giderken ardımızda biraz iyilik, biraz sevgi, biraz da insanlık bırakabilmek…

İşte bütün mesele budur.

Çünkü yaşamak yalnızca nefes almak değildir sevgili…

Yaşamak; haksızlığa karşı susmamak, düşenin elinden tutmak, sevmekten korkmamak ve bütün bu karanlığa rağmen insan kalabilmektir.', 'Hayat bize hiçbir zaman kolay bir mutluluk sunmadı sevgili… Biz, kendi yaralarımızı saklayıp başkalarının kanayan yerlerine merhem olmaya ça...', ARRAY['Türk Edebiyatı','Şiir','Rezan Farqin']::text[], 8.5, '{"poet":"Rezan Farqin","poet_slug":"rezan-farqin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/insan-kalabilmek-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz vaka', 'umutsuz-vaka-senturk-dursun-9spjk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'UMUTSUZ VAKA

Tarla çayır yaban doldu

Mahsullerden umut kestim

Hak yerini bulmaz oldu

Mesullerden umut kestim

Merhabada selam başka

Muhabbette kelam başka

Kanun nizam söylem başka

Usullerden umut kestim

Belli değil ne kış ne yaz

Unutuldu şükür niyaz

Okusa da anlayamaz

Tahsillerden umut kestim

Heba ettik süremizi

Rafa koyduk töremizi

Vekil beyler duymaz bizi

Temsillerden umut kestim

Dedikodu fokur fokur

İnternette mekik dokur

Eğri bakar tersten okur

Nesillerden umut kestim

Haramilik bölük bölük

Üfle üfle dolmaz körük

Su bulanık niyet bozuk

Gusüllerden umut kestim

Yalan sattık kürsülerde

Hedef şaştı ülkülerde

Heyecan yok türkülerde

Fasıllardan umut kestim

               ŞENTÜRK DURSUN', 'UMUTSUZ VAKA Tarla çayır yaban doldu Mahsullerden umut kestim Hak yerini bulmaz oldu Mesullerden umut kestim Merhabada selam başka Muhabbett...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/umutsuz-vaka-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tecrübe', 'tecrube-senturk-dursun-nuokt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'TECRÜBE

İç dünyama demirledim çilemi

Dertlerimle yaşamayı öğrendim

Karanlıklar terk etmedi gecemi

Gün doğmadan ışımayı öğrendim

Yıldızlarım ilk akşamdan sönerken

Günler aya, aylar yıla dönerken

Buz dağında buram buram yanarken

Kor ateşte üşümeyi öğrendim

Dindirdim içimde infilakları

Attım sırtımdaki asalakları

Birer birer çıktım basamakları

Sıra sıra aşamayı öğrendim

Haklıyı bastırdı haksızın sesi

Biri izah etsin, bu neyin nesi

İnsan gibi, insan olan herkesi

Omuzumda taşımayı öğrendim

             ŞENTÜRK DURSUN', 'TECRÜBE İç dünyama demirledim çilemi Dertlerimle yaşamayı öğrendim Karanlıklar terk etmedi gecemi Gün doğmadan ışımayı öğrendim Yıldızlarım ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tecrube-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırım Tatar Türk Devleti kuruluyor', 'kirim-tatar-turk-devleti-kuruluyor-yusuf-tuna-v352b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Abdülcemil Kırımoğlu tarafından,

Kırım Tatar Türk Devleti kuruluyor.

Türk Devlet geleneği indi rafından,

Kırım Tatar Türk Devleti kuruluyor.

Oğuz Türk töresine bağlı kalarak,

Oğuzdan devlet yapısını alarak.

Rusyada özerk Cumhuriyet olarak,

Kırım Tatar Türk Devleti kuruluyor.

Belirlenen kurultay çalıştırılmış,

Türk devlet erki özle buluşturulmuş.

Alt yapısı tamamen oluşturulmuş,

Kırım Tatar Türk Devleti kuruluyor.

Kırımdaki Tatarlar devlet oluyor,

Ordaki insanların yüzü gülüyor.

Türkiye''ye kardeş bir devlet geliyor,

Kırım Tatar Türk Devleti kuruluyor.

Yusuf Kırım yönetimini seçiyor,

Tatarlar kendi bayrağını açıyor.

Kırım devlet yönetimine geçiyor,

Kırım Tatar Türk Devleti kuruluyor.', 'Abdülcemil Kırımoğlu tarafından, Kırım Tatar Türk Devleti kuruluyor. Türk Devlet geleneği indi rafından, Kırım Tatar Türk Devleti kuruluyor....', ARRAY['Türk Edebiyatı','Şiir','Yusuf Tuna']::text[], 8.5, '{"poet":"Yusuf Tuna","poet_slug":"yusuf-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kirim-tatar-turk-devleti-kuruluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaka Mısınız ?', 'saka-misiniz-kamil-caglar-h4tr8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kara bulutlar haberli misiniz
kara bulutlar yağışlı mısınız

kara bahtlılar bekliyor musunuz
kara bahtlılar korkuyor musunuz

kara yazılar silinmez misiniz
kara yazılar bilinmez misiniz

kara gözlüler nazarlı mısınız
kara gözlüler zararlı mısınız

kara dilliler kurumaz mısınız
kara dilliler susamaz mısınız

kara kalpliler kedersiz misiniz
kara kalpliler kadersiz misiniz

20.11.2026/15.20
Akyazı-KÇ', 'kara bulutlar haberli misiniz kara bulutlar yağışlı mısınız kara bahtlılar bekliyor musunuz kara bahtlılar korkuyor musunuz kara yazılar sil...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çağlar']::text[], 8.5, '{"poet":"Kamil Çağlar","poet_slug":"kamil-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/saka-misiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Deseler İnandık', 'ne-deseler-i-nandik-senturk-dursun-8kfj5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'NE DESELER İNANDIK

Algılarla kandırıldık yıllarca

Düzenbaza, bey dediler inandık

Beynimizi yıkadılar ustaca

Borazana, ney dediler inandık

Harman bitti, sapla saman karıştı

Mevta kalktı cellâdıyla barıştı

Gece gündüz birbirine karıştı

Yıldızlara, ay dediler inandık

Çiğnendi teamül çiğnendi ilke

Taklacı yurduna dönüştü ülke

Sülükler üşüştü makama mülke

Hepsi bizim, pay dediler inandık

Boş beleşe kafa yorduk haybeye

Söylemlerle törpülendi terbiye

Yalan dolan dillerdeki sermaye

Kasabaya köy dediler inandık

Maske düştü görünüyor foyalar

Makyaj gitti dökülüyor boyalar

Her işlevde binbir türlü hile var

Kocamışa toy dediler inandık

Amaç bitmiş, hayat dersen monoton

Ne hedef var, ne ideal, ne vizyon

Derinleşti kültürdeki erozyon

Translara, bay dediler inandık

Gerçeğimiz hayallerde kayboldu

Haklar batıl, batıl ise hak oldu

Sorgu sual melekemiz yok oldu

Kel sıpaya, tay dediler inandık.

ŞENTÜRK DURSUN', 'NE DESELER İNANDIK Algılarla kandırıldık yıllarca Düzenbaza, bey dediler inandık Beynimizi yıkadılar ustaca Borazana, ney dediler inandık Ha...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ne-deseler-inandik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yere Seni Yazdım', 'her-yere-seni-yazdim-senturk-dursun-yz2r6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HER YERE SENİ YAZDIM

Bir lirik şiir döktüm gönülden sayfalara

Her mısraya beyite, kıtaya seni yazdım

Şarkılar ortak oldu içimdeki efkâra

Çaldığım nağmelere, notaya seni yazdım

Yalnızlığı besledim koca bir çınar ettim

Yokluğunda sılayı kendime ağyar ettim

Kalemi yoldaş bildim, kâğıtları yar ettim

Cümlemdeki virgüle, noktaya seni yazdım

Sevdanın ağırlığı çökerken bedenime

Alev renkli ırmaklar iz bıraktı tenime

Sendeki güzelliği lügat yetmez tanıma

Çıktığım aşk yolunda rotaya seni yazdım

El açıp dua ettim yüzünü görmek için

Nice yollar denedim, gönlüne girmek için

Takvimleri tükettim vuslata ermek için

Güne aya seneye, haftaya seni yazdım

Sensiz gurbet ellerde yüreğime gam düştü

Gözlerim yol gözlerken, ruhuma hüzzam düştü

Efkârlı bir yaz günü, kaleme ilham düştü

Gönlümdeki ölümsüz sevdaya seni yazdım

ŞENTÜRK DURSUN', 'HER YERE SENİ YAZDIM Bir lirik şiir döktüm gönülden sayfalara Her mısraya beyite, kıtaya seni yazdım Şarkılar ortak oldu içimdeki efkâra Çal...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/her-yere-seni-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdayı Anlat Bana', 'sevdayi-anlat-bana-senturk-dursun-j8lcu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEVDAYI ANLAT BANA

Bir tarif bulamadım sensizliğin adına

Platonik bir aşkı, sevdayı anlat bana

Umutları yükledim hayalin kanadına

Elvedasız gidişi, vedayı anlat bana

Gönül çoktan yitirdi aşka olan inancı

Halimden anlamadı ne kervancı ne hancı

Garipler yurdundayım herkes bana yabancı

Gurbeti tanıyorum sılayı anlat bana

Ne başa dönebildim, ne sona varıyorum

Sendeler vaziyette, devrilip duruyorum

Bir çölün ortasında rotasız yürüyorum

Farzet ki bir Mecnunum, Leyla’yı anlat bana

Elemler tutsak kıldı, ruhumdaki hevesi

Kulaklara ulaşmaz, yüreğin yorgun sesi

Ağlamakla tükendi, gözyaşımın haznesi

Senden ödünç aldığım damlayı anlat bana

ŞENTÜRK DURSUN', 'SEVDAYI ANLAT BANA Bir tarif bulamadım sensizliğin adına Platonik bir aşkı, sevdayı anlat bana Umutları yükledim hayalin kanadına Elvedasız ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevdayi-anlat-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Münacat-ı Derun - Gönülden Yakarış', 'munacat-i-derun-gonulden-yakaris-yunus-huseyni-wi91b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Secili mensur münacat kalıbı ile yazılmıştır

Münâcât-ı Derûn

Mahbûbesini rü’yet eyleyeni görünce; isti’câl etmeyin, tehevvür etmeyin.

Zulüm galebe çaldı, takdîre rızâ gösterince; derûnumda Cenâb-ı Hakk’ın sûz-i aşkı tutuştu.

Serkeş rûhum, kûh-misâl mağrûr başım eğildi; fehm edemedim bu yaşıma değin bu sırr-ı kudreti.

Meğer kalb-i mahzûnum ezelden O’nun muhabbetiyle meşbû imiş, idrâk edemedim; "Kün feyekûn" sırrıyla halk eden O imiş, bir "Ol" hitâbıyla mübtelâ olmuşum.

Ey çeşmime renk bahşeden, elvân göz ile cümle elvânı temâşâ ettiren ve rü’yet olmaksızın zâtını sevdiren a’lâlar a’lâsı Mahbûb-ı Hakîkî!

Benim sem’ime erişmeyenleri işiten, ilmime sığmayanları bilen; nice mâzîyi, nice müstakbeli bilen, tâib olanı mağfiret eden Rabbim!

Dîn-i mübînin lâyenkser seyf-i sârimi olan TÜRK milletinden bu abd-i âcizini; âhir ömründe vâsıl olduğu Mahbûb’un tarîkinden bir lahza olsun cüdâ kılma.', 'Secili mensur münacat kalıbı ile yazılmıştır Münâcât-ı Derûn Mahbûbesini rü’yet eyleyeni görünce; isti’câl etmeyin, tehevvür etmeyin. Zulüm ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Hüseyni']::text[], 8.5, '{"poet":"Yunus Hüseyni","poet_slug":"yunus-huseyni","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/munacat-i-derun-gonulden-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Yakışan', 'bize-yakisan-senturk-dursun-v0si6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİZE YAKIŞAN

En doğudan batıya, birlikte Türkiye’yiz

Türk Kürt diye ayırmak, bölmek bize yakışmaz

Bin yıl önce yazılan, anıyız hikâyeyiz

Anıları kalplerden, silmek bize yakışmaz

Yolumuz Hak yoludur, kutsaldır seferimiz

Bu kutsal yolculukta, yorulmaz neferimiz

Merhamette şefkatte, Nebi’dir rehberimiz

Mazlumların ahını almak bize yakışmaz

Ne güçsüzü küçümser, ne güçlüden korkarız

Bulutlarda birikir, sevgi olur akarız

İnsan-ı kâmil ise aynı gözle bakarız

Gariplere duyarsız, kalmak bize yakışmaz

Hakkı haykırıyorken, davudi sesliyiz biz

Yürek kapımız açık, Asım’ın nesliyiz biz

Dertliyle dertleşiriz, yaslıyla yaslıyız biz

Masumlar ağlıyorken, gülmek bize yakışmaz

Gökyüzünün süsüdür, ay yıldız bayrağımız

Şehit kanı suladı, kutsaldır toprağımız

Kurumaz köklerimiz, dökülmez yaprağımız

Her yerde yeşeririz, solmak bize yakışmaz

Farklı türde olsa da, meşrebimiz rengimiz

Göstermelik değildir, gönüldendir sevgimiz

Tek dişli canavarla, bitmez bizim cengimiz

Fatihin torunuyuz, yılmak bize yakışmaz

Gururdur iftihardır, Türk’ün hayat öyküsü

Ürgüp’te Buhara’da yankılanır türküsü

Bir mukaddes hedeftir, Kızılelma ülküsü

O hedefe varmadan, ölmek bize yakışmaz

18.03.2023 ŞENTÜRK DURSUN', 'BİZE YAKIŞAN En doğudan batıya, birlikte Türkiye’yiz Türk Kürt diye ayırmak, bölmek bize yakışmaz Bin yıl önce yazılan, anıyız hikâyeyiz Anı...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bize-yakisan-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül-i Rana', 'gul-i-rana-senturk-dursun-zckwb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÜL-İ RANA

Görür görmez büyüledi gözlerin

Mânâsız dünyama mânâ getirdi

Bakışlar edalı bakışlar derin

Yaşayan ölüydüm cana getirdi

Var mı sana, benden daha yakını

Söküp at içinden firkat korkunu

Sinendeki misk-i amber kokunu

Sıla rüzgârıyla bana getirdi

Bir yanım karanlık bir yanım beyaz

Bir yanım alevli bir yanım ayaz

Sendeki bu işve, sendeki bu naz

Beni benden aldı sana getirdi

Bir seyyah misali peşinde gezdim

Sanmaki yoruldum, sanmaki bezdim

Sevmek nedir, sevilmek ne, bilmezdim

Sevda kervanıyla hana getirdi

Karşıma çıkınca ahu gözlü yar

Ne kederim kaldı, ne de ahüzar

Zemheri’de sanki mevsim ilkbahar

Gülistandan gül-i rana getirdi

ŞENTÜRK DURSUN', 'GÜL-İ RANA Görür görmez büyüledi gözlerin Mânâsız dünyama mânâ getirdi Bakışlar edalı bakışlar derin Yaşayan ölüydüm cana getirdi Var mı san...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gul-i-rana-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemini Demledim', 'ozlemini-demledim-senturk-dursun-w9akg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ÖZLEMİNİ DEMLEDİM

Özlemini demledim, hasretin ocağında

Senden ayrı dünyada, dertle sarhoş gibiyim

Şafağım rehin kaldı, gecenin kucağında

Tedirgin uykularda, korkulu düş gibiyim

Hazan düştü ömrüme zamansız sararıyor

Hangi yola koyulsam bir çıkmaza varıyor

Yıllar, aylar, saatler, gençliğimi soruyor

Baharım gelmez benim, dört mevsim kış gibiyim

İçim yanar kavrulur, görünürde duman yok

Herkese geçse bile, gönle geçen ferman yok

Gözümde fer tükendi, dizlerimde derman yok

Kanatları kırılmış, yaralı kuş gibiyim

Her gönülde bir aşk var, her gönülde bir canan

Ya ağlayan bir çift göz, ya sevdayla yanan can

Ruh dünyamı terketti, hayat denen heyecan

Bir garip mezarında değersiz taş gibiyim

Kopardın dalımdaki, açılan gonca gülü

Kim teselli eder ki, gamla öten bülbülü

Tutuklu sevdalarım, yüreğimde gömülü

Şirine kavuşmayan Ferhata eş gibiyim

ŞENTÜRK DURSUN', 'ÖZLEMİNİ DEMLEDİM Özlemini demledim, hasretin ocağında Senden ayrı dünyada, dertle sarhoş gibiyim Şafağım rehin kaldı, gecenin kucağında Ted...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozlemini-demledim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahvalimiz', 'ahvalimiz-senturk-dursun-3t5d2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AHVALİMİZ

Zorbaya tahsis oldu, memleketin tapusu

Zalime kanat gerip, mazlumu dışladılar

Zavallıya kapandı, merhametin kapısı

Nevi şahsına mahsus, bir dünya düşlediler

Nakış nakış işlendi, şeytanımsı planlar

Çıyana çakallara yem edildi aslanlar

Rengiyle yöresiyle sınıflandı insanlar

Kimini yoktan sayıp, kimini fişlediler

Haramzade zapt etti, adalet kefesini

Hayalle doldurdular, garibin kesesini

Batıl güruh bastırdı, Hak ehlinin sesini

Küffara gül uzatıp, Müslüman taşladılar

Garabet yağmuruyla, kir kapladı yüzleri

Haklıyı hakikati, görmez oldu gözleri

Gönüllerden silindi, hoşgörünün izleri

Kin nefret tohumuyla hamaset aşladılar

Ağzınla kuş tutsan da, görmeyene nafile

Çıkar için mübahmış her entrika her hile

Ne anlatsan beyhude, söz israftır gafile

Haini cilalayıp, övgüye başladılar

ŞENTÜRK DURSUN', 'AHVALİMİZ Zorbaya tahsis oldu, memleketin tapusu Zalime kanat gerip, mazlumu dışladılar Zavallıya kapandı, merhametin kapısı Nevi şahsına ma...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ahvalimiz-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Eleği', 'zaman-elegi-senturk-dursun-10q3h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ZAMAN ELEĞİ

Zamanın eleğinden aktı gitti seneler

Nevbaharı beklerken, mevsimlere güz düştü

Zindana dönüverdi, sevda renkli geceler

Eskimiş albümlere, siyah beyaz poz düştü

Nice ateşler yandı, sevgimin hanesinde

Nice hasretler pişti, umudun sinesinde

Nice oyun oynandı, ömrümün sahnesinde

Bana acı ızdırap, sana neşe haz düştü

Dil dökmeler beyhude, yalvarmalar faydasız

Kelam bile etmeden, çekip gittin vedasız

İçimdeki duygular, ağlar sessiz sedasız

Yüreğime kor ateş, bahtıma ayaz düştü

İçimden derya akar, kendimden taşıyorum

Pusulamı yitirdim, yönümü şaşıyorum

Hasretin vurdu beni, sanmaki yaşıyorum

Ruhuma deli boran, bedene poyraz düştü

ŞENTÜRK DURSUN', 'ZAMAN ELEĞİ Zamanın eleğinden aktı gitti seneler Nevbaharı beklerken, mevsimlere güz düştü Zindana dönüverdi, sevda renkli geceler Eskimiş a...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zaman-elegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürülere Dahil Olmayan Nitelik', 'surulere-dahil-olmayan-nitelik-onder-karacay-121dt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '§

Farkındalığı, niceliğine nitelik aranan hiçbir sürüye ait olmayan nitelik üretir. Nicelik sadece kötülük üretmek nitelikli farkındalığa karşı birleşir. 

§

▪️Önder Karaçay ▪️', '§ Farkındalığı, niceliğine nitelik aranan hiçbir sürüye ait olmayan nitelik üretir. Nicelik sadece kötülük üretmek nitelikli farkındalığa ka...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/surulere-dahil-olmayan-nitelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zoru Seçtik', 'zoru-sectik-senturk-dursun-b2g2v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ZORU SEÇTİK

Tarihlerden beridir, değişmez şiarımız

Her zaman imkânsızı, her zaman zoru seçtik

Ezeli ve ebedi, kesindir ikrarımız

Yanmayı göze aldık, ateşi koru seçtik

Ne yolu değiştirdik, ne de hedeften şaştık

Ne kimseye eğildik, ne haddimizi aştık

Maddeye ram olmadık, mânâda yoğunlaştık

İnsanı insan yapan, edebi arı seçtik

Dost düşmanı tanıdık, gerek yok itirafa

Sadakat darbe yedi, tükendi ahde vefa

Sefaya bir müjdedir, çektiğimiz her cefa

Emeksiz varı değil, alında teri seçtik

Kimseye kapatmadık, gönüldeki perdeyi

Zihinden silip attık, makamı mertebeyi

Helal bir lokma için, feda ettik her şeyi

Çatlayan ellerdeki, nasırı kiri seçtik

Dualar aydınlattı, ışıksız gecemizi

Kızıl kanlar suladı yiğitlik harcımızı

Kudret-i ilahiden alırız gücümüzü

Vatan sathı mahlinde, en zorlu yeri seçtik

ŞENTÜRK DURSUN', 'ZORU SEÇTİK Tarihlerden beridir, değişmez şiarımız Her zaman imkânsızı, her zaman zoru seçtik Ezeli ve ebedi, kesindir ikrarımız Yanmayı göz...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zoru-sectik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kasım 62', 'ask-kasim-62-ask-askin-sehri-ordu-0mt75', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen dünya öyle acımasız ki

İnsan iyiliğin bile bir bedeli olduğuna inanıyor.

Güvenmek bir risk,

Bağlanmak bir korku,

Sevmek ise kaybetme ihtimaliyle sınanıyor.

Aşk

Eğer cehennem sevmemekse,

Ben bu dünyada sevgisiz kalmaktan korkarım.

Bir kalbin kapısını hiç açmadan yaşlanmaktan,

Birinin gözlerinde kendimi hiç görememekten,

Hayatın içinden geçip

Hiçbir hayata dokunamamaktan…

Aşk

Seninle bir ömür istiyorum sevgilim;

Sadece mutlu günlerin değil,

Zor günlerin de içinden geçebileceğimiz,

Birbirimizi suçlamak yerine anlayabileceğimiz,

Her şeye rağmen sevgiyi

Bir kez daha seçebileceğimiz bir ömür.

Çünkü insanın en büyük kaybı,

Sevdiğini yitirmesi değil belki;

Sevebileceği hâlde

Sevmekten vazgeçmiş birine dönüşmesidir.

Ben sana,

İçimde hâlâ güzelliğe inanan

O insanın bütün cesaretiyle geliyorum.

Aşk

Sevmeye Cesaret Edenler

İnsan neden korkar sevmekten? Bir kalbi incitmekten mi, Yoksa kendi içindeki karanlığı Bir başkasının gözlerinde görmekten mi?

Belki de aşk, insanın kendine kurduğu Bütün savunmaları yıktığı yerdir. Orada ne gurur saklanabilir Ne geçmiş suçlarını aklayabilir Ne de insan kendini olduğundan başka gösterebilir.

Ben senin yanında Kusurlarımı gizlemeyi bırakmak istiyorum. Beni yalnızca güzel yanlarımla değil, Bazen susan, bazen yanılan, Bazen kendi düşüncelerinde kaybolan hâlimle de Sevebilmeni diliyorum.

Çünkü insan sevilmek için kusursuzlaşırsa Bir gün kendi gerçeğinden uzaklaşır. Oysa aşk, iki kusursuz insanın buluşması değil; İki eksik hayatın birbirine yük olmadan Güzellik katabilmesidir.

Seni sevmek, Kendimi temize çıkarmak değil, Kendi içimdeki bütün yanlışlarla yüzleşirken Senin sevgini bir sığınak değil, Bir cesaret olarak taşımaktır.

Bazen dünya öyle acımasız ki İnsan iyiliğin bile bir bedeli olduğuna inanıyor. Güvenmek bir risk, Bağlanmak bir korku, Sevmek ise kaybetme ihtimaliyle sınanıyor.

Ama ben bütün bu ihtimallere rağmen Sevginin tarafında kalmak istiyorum. Kırılmamak için taşlaşanlardan değil, Kırılabileceğini bilip yine de Bir başkasına incelik gösterebilenlerden olmak…

Eğer cehennem sevmemekse, Ben bu dünyada sevgisiz kalmaktan korkarım. Bir kalbin kapısını hiç açmadan yaşlanmaktan, Birinin gözlerinde kendimi hiç görememekten, Hayatın içinden geçip Hiçbir hayata dokunamamaktan…

Seninle bir ömür istiyorum sevgilim; Sadece mutlu günlerin değil, Zor günlerin de içinden geçebileceğimiz, Birbirimizi suçlamak yerine anlayabileceğimiz, Her şeye rağmen sevgiyi Bir kez daha seçebileceğimiz bir ömür.

Çünkü insanın en büyük kaybı, Sevdiğini yitirmesi değil belki; Sevebileceği hâlde Sevmekten vazgeçmiş birine dönüşmesidir.

Ben sana, İçimde hâlâ güzelliğe inanan O insanın bütün cesaretiyle geliyorum. 

Aşk

Bir gün bütün yollar susacak,

Ayak izlerimizi rüzgâr silecek.

Mevsimler değişecek,

Ağaçlar yapraklarını yeniden toprağa bırakacak.

Zaman, sahip olduğumuzu sandığımız

Her şeyi bizden usulca geri alacak.

Ama ben seni başka bir yerde sevdim;

Ne takvimlerin içinde,

Ne mesafelerin ölçüsünde,

Ne de dünyanın geçici güzelliklerinde...

Seni, bir ağacın köklerini toprağa bırakışı gibi,

Bir nehrin denize kavuşması gibi,

Bir kuşun gökyüzüne güvenmesi gibi sevdim.

Aşk

Gerçek sevgi,

Hayatın geçiciliğine karşı verilmiş

En güzel insanlık cevabıdır.

Her şey biter belki;

Ama sevgi, yaşandığı yerde bitmez.

Çünkü aşk, iki insanın birbirinde bulduğu

Geçici bir mutluluk değil,

Birbirlerinin varoluşuna bıraktığı

Silinmez bir güzelliktir.

Ve ben seni,

Dünyanın son günü gelecekmiş gibi değil,

Dünya her sabah yeniden doğacakmış gibi seviyorum.

Aşk

Ben artık biliyorum sevgilim;

Dünya bize ait değil,

Biz dünyanın kısa süreli misafirleriyiz.

Çiçekler açar, solar;

Denizler kıyılarını değiştirir;

Güneş her sabah başka bir günü başlatır.

Aşk

Her şeyin bir sonu var sevgilim,

Yolların, mevsimlerin, ayrılıkların…

Bir gün en güzel şarkılar bile susar,

En uzun yolculuklar bir yerde tamamlanır.

Ama sevgi öyle değil.

Ben seni bir ömrün alışkanlığıyla değil,

Bir canlının kendisine gösterilen iyiliği

Hiç unutmayan kalbiyle sevdim.

Aşk

Ne zaman yorulsam,

Varlığın içimde dinlenecek bir liman oldu.

Ne zaman dünya üzerime gelse,

Bir bakışın bütün yüklerimi hafifletti.

Aşk

Bilirsin,

Sadakat zincirlerle ölçülmez;

Bir kalbin özgür iradesiyle

Başka bir kalpte kalmayı seçmesidir.

Ben senden hiçbir zaman

Ömrüme sahip olmanı istemedim.

Yalnızca aynı yolda yürürken

Birbirimizin adımlarını incitmeyelim istedim.

Çünkü aşk,

Güçlünün güçsüzü koruması değil,

İki insanın birbirine karşı

Gücünü merhamete dönüştürmesidir.

Aşk

Sana verdiğim sevgi,

Karşılığını bekleyen bir borç değil;

Varlığından duyduğum mutluluğun

İçimde büyüttüğü özgür bir armağan.

Aşk

Eğer bir gün

Bütün yollar birbirinden ayrılırsa,

Sana dair güzel olan hiçbir şeyi

Kötü bir hatıraya dönüştürmeyeceğim.

Çünkü ben sevgiyi,

Birinin yanında kalmak kadar

Ona iyi gelmeyi de bilmek olarak öğrendim.

Aşk

BİR KALP, BİR ÖMÜR SEVER

Her şeyin bir sonu var sevgilim, Yolların, mevsimlerin, ayrılıkların… Bir gün en güzel şarkılar bile susar, En uzun yolculuklar bir yerde tamamlanır.

Ama sevgi öyle değil.

Ben seni bir ömrün alışkanlığıyla değil, Bir canlının kendisine gösterilen iyiliği Hiç unutmayan kalbiyle sevdim.

Ne zaman yorulsam, Varlığın içimde dinlenecek bir liman oldu. Ne zaman dünya üzerime gelse, Bir bakışın bütün yüklerimi hafifletti.

Bilirsin, Sadakat zincirlerle ölçülmez; Bir kalbin özgür iradesiyle Başka bir kalpte kalmayı seçmesidir.

Ben senden hiçbir zaman Ömrüme sahip olmanı istemedim. Yalnızca aynı yolda yürürken Birbirimizin adımlarını incitmeyelim istedim.

Çünkü aşk, Güçlünün güçsüzü koruması değil, İki insanın birbirine karşı Gücünü merhamete dönüştürmesidir.

Bir gün saçlarımıza zaman düşecek, Ellerimiz eski gücünü kaybedecek. Belki yürüdüğümüz yollar değişecek, Belki dünyamız bambaşka bir yere dönüşecek.

Yine de bilmeni isterim: Sana verdiğim sevgi, Karşılığını bekleyen bir borç değil; Varlığından duyduğum mutluluğun İçimde büyüttüğü özgür bir armağan.

Ve eğer bir gün Bütün yollar birbirinden ayrılırsa, Sana dair güzel olan hiçbir şeyi Kötü bir hatıraya dönüştürmeyeceğim.

Çünkü ben sevgiyi, Birinin yanında kalmak kadar Ona iyi gelmeyi de bilmek olarak öğrendim.

Her şey biter sevgilim; Güzellikler solar, zaman geçer, hayat değişir. Ama bir kalp, başka bir kalbe İyilikle dokunmuşsa O sevgi artık yalnızca iki kişinin değil, İnsanlığın güzelliğine bırakılmış bir izdir.

Ben seni ömrümün sonuna kadar değil yalnızca, Ömrümün her anında sevmek istiyorum. Çünkü aşkın büyüklüğü kaç yıl sürdüğünde değil, Birbirimizin hayatında ne kadar güzelleştiğimizde saklıdır.

Aşk

Her şey biter sevgilim;

Güzellikler solar, zaman geçer, hayat değişir.

Ama bir kalp, başka bir kalbe

İyilikle dokunmuşsa

O sevgi artık yalnızca iki kişinin değil,

İnsanlığın güzelliğine bırakılmış bir izdir.

Aşk

Ben seni ömrümün sonuna kadar değil yalnızca,

Ömrümün her anında sevmek istiyorum.

Çünkü aşkın büyüklüğü kaç yıl sürdüğünde değil,

Birbirimizin hayatında ne kadar güzelleştiğimizde saklıdır.

Aşk

Ne yaptım ki ben seni düşünmekten başka?

Bir ömrün bütün yollarını

Adını içimden geçirerek yürüdüm.

Sabahları güneşe seninle uyandım,

Akşamları yorgunluğumu

Sana kavuşacağım bir güne sakladım.

Aşk

Ben seni öyle sevdim ki,

Toprağa düşen bir tohumun

Bahar geleceğine inanması gibi…

Yağmur bekleyen kurak bir ovanın

Gökyüzüne küsmeden sabretmesi gibi.

Aşk

Bazen hayat ağır bir kış oldu,

İnsanlar kendi telaşlarına karıştı.

Zaman, herkesi başka yönlere savurdu.

Ben yine de seni düşündüm.

Çünkü insanın yüreğinde büyüttüğü

Bazı sevgiler mevsimlere boyun eğmez.

Aşk

Ne yaptım ki ben seni düşünmekten başka?

Bir sofrada eksik kalan yerini,

Bir yolculukta yanımda olmayan sesini,

Bir güzel günde paylaşamadığım sevincini

İçimde sessizce çoğalttım.

Aşk

Sana kavuşmak için değil yalnızca,

Seninle yaşanabilecek bir hayatı sevdim.

Birlikte ekilen bir ağacı,

Aynı yağmur altında ıslanmayı,

Yıllar sonra bile birbirimize

İlk günkü şefkatle bakabilmeyi…

Aşk

Bil ki sevgilim,

Aşk bazen büyük sözler söylemek değildir.

Bir insanın yokluğunda bile

Onun iyiliğini dilemek,

Kendi mutluluğundan önce

Onun yüzündeki tebessümü düşünebilmektir.

Ben senden bir mucize istemedim.

Biraz zaman, biraz yakınlık,

Bir ömürlük içtenlik istedim.

Çünkü dünya ne kadar değişirse değişsin,

İnsan en çok sevildiği yerde

Kendisi olabilmeyi özler.

Ve şimdi soruyorum kendime:

Ne yaptım ki ben seni düşünmekten başka?

Bir ömrü sana ayırmadım belki,

Ama ömrümün en güzel yerinde

Sana bir yer bıraktım.

Aşk

BEN SENİ DÜŞÜNMEKTEN BAŞKA NE YAPTIM?

Cengiz Aytmatov’un Toprak Ana eserindeki emek, sabır, özlem, yaşam mücadelesi ve insanın yüreğinde taşıdığı büyük bağlılık duygusundan esinlenen özgün aşk şiiri.

Ne yaptım ki ben seni düşünmekten başka? Bir ömrün bütün yollarını Adını içimden geçirerek yürüdüm. Sabahları güneşe seninle uyandım, Akşamları yorgunluğumu Sana kavuşacağım bir güne sakladım.

Ben seni öyle sevdim ki, Toprağa düşen bir tohumun Bahar geleceğine inanması gibi… Yağmur bekleyen kurak bir ovanın Gökyüzüne küsmeden sabretmesi gibi.

Bazen hayat ağır bir kış oldu, İnsanlar kendi telaşlarına karıştı. Zaman, herkesi başka yönlere savurdu. Ben yine de seni düşündüm. Çünkü insanın yüreğinde büyüttüğü Bazı sevgiler mevsimlere boyun eğmez.

Ne yaptım ki ben seni düşünmekten başka? Bir sofrada eksik kalan yerini, Bir yolculukta yanımda olmayan sesini, Bir güzel günde paylaşamadığım sevincini İçimde sessizce çoğalttım.

Sana kavuşmak için değil yalnızca, Seninle yaşanabilecek bir hayatı sevdim. Birlikte ekilen bir ağacı, Aynı yağmur altında ıslanmayı, Yıllar sonra bile birbirimize İlk günkü şefkatle bakabilmeyi…

Bil ki sevgilim, Aşk bazen büyük sözler söylemek değildir. Bir insanın yokluğunda bile Onun iyiliğini dilemek, Kendi mutluluğundan önce Onun yüzündeki tebessümü düşünebilmektir.

Ben senden bir mucize istemedim. Biraz zaman, biraz yakınlık, Bir ömürlük içtenlik istedim. Çünkü dünya ne kadar değişirse değişsin, İnsan en çok sevildiği yerde Kendisi olabilmeyi özler.

Ve şimdi soruyorum kendime:

Ne yaptım ki ben seni düşünmekten başka? Bir ömrü sana ayırmadım belki, Ama ömrümün en güzel yerinde Sana bir yer bıraktım.

Toprak nice kışı bağrında saklar da Her bahar yeniden çiçek açar. Benim yüreğim de öyle sevgilim; Araya hangi mevsim girerse girsin, Seni düşünmekten vazgeçmeyen Bir baharı içinde taşır.

Aşk', 'Bazen dünya öyle acımasız ki İnsan iyiliğin bile bir bedeli olduğuna inanıyor. Güvenmek bir risk, Bağlanmak bir korku, Sevmek ise kaybetme i...', ARRAY['Türk Edebiyatı','Şiir','Aşk Aşkın Şehri Ordu']::text[], 8.5, '{"poet":"Aşk Aşkın Şehri Ordu","poet_slug":"ask-askin-sehri-ordu","theme":"Türk Şiiri","is_hero":false,"total_lines":205,"source_url":"https://www.antoloji.com/ask-kasim-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Sokan Bal Yapmaz.', 'her-sokan-bal-yapmaz-ugur-musab-sahin-xw7e2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne bacanak, ne enişte, ne de kayın

Kan bağın yoksa her biri bir mayın.

Omzumuzda dağlar kadar ağır yük,

Ondan eğri yürürüm, sırtımda höyük.

2026

Her gün başların üstünde döner,

İki yuvarlak, ağır değirmen taşı.

Bakalım ışıklar ne zaman söner.

İnsanın, ömür mihengi değil yaşı.

2026

Saçım kara, amel defterim ak geldim.

Saçım ak, amel defterim  kara gidiyorum.. 

Her gün, uzun bir ayrılığın arifesindeyim.

Ha bugün ha yarın, o günün öncesindeyim.

2026

O günün sonrasında, dostum akranlarım.

Dünya benim değil, ben onun arkasındayım

Kim dost, kim düşman ben nerden bileyim,

Kuyu dibine atılmış Hz. Yusuf gibiyim.

2026

Her sokan bal yapmaz, akrebi arı sanma,

Kovandan mı, delikten mi çıkar ne bileyim.

Biri çiçeğe konar, diğeri leşe sakın aldanma 

Arı dururken ben, akrebe mi güveneyim?

2026

Çamaşırda tokaç gibi, 

Gerçekçi dostum olsun.

Hallacı Mansur misali, 

Atılan gül dokunsun.

2026

Elinde akşamcı şişesi,

Sedirde oturma köşesi,

Her akşam full neşesi,

Dünya umurunda değil.

2026

Hayat sert bir rüzgâr,

Biz dalda titrek yaprak.

Kâh yağmur, kâh kar.

Düşeceğimiz yer toprak.

2026

Musalla taşından, kabir taşına

Haşeratın aşından mağrur başına.

İmamın aldırdığı gusül duşuna,

Taş deyip geçme yoldaşın olur.

2026

Her bir rengin onlarca tonları var,

İnce uzun akarsuların, kolları var.

Allah’a giden binlerce yolları var,

Her yüreğin bir ateşi, bir koru var.

Her dikende gül arama, bülbülü var.

Her canlının bir başı, birde sonu var.

2026', 'Ne bacanak, ne enişte, ne de kayın Kan bağın yoksa her biri bir mayın. Omzumuzda dağlar kadar ağır yük, Ondan eğri yürürüm, sırtımda höyük. ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Musab Şahin']::text[], 8.5, '{"poet":"Uğur Musab Şahin","poet_slug":"ugur-musab-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/her-sokan-bal-yapmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur Yurdu', 'huzur-yurdu-sairul-i-slam-yunus-kokan-i0vbd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyada yorulur bu garip beden,

Ümit kesilmez sonsuz rahmetten,

Günah, hata ne kadar çok olsa da

İnsan ümitle bekler hep o kapıda.

Orada ne gözyaşı ne de keder var,

Ne ayrılık vardır ne de intizar.

Bir selâm duyulur, gönüller bahar,

Huzur yurdudur o güzel diyar.

Amelimiz az olsa da rahmetin büyük,

Kapında boynumuz bükük mü bükük.

Mahşerde yüzümüz olmasın düşük,

Lütfunla al cennetine ALLAH''ım!

Orada ne gözyaşı ne de keder var,

Ne ayrılık vardır ne de intizar.

Bir selâm duyulur, gönüller bahar,

Huzur yurdudur o güzel diyar.', 'Dünyada yorulur bu garip beden, Ümit kesilmez sonsuz rahmetten, Günah, hata ne kadar çok olsa da İnsan ümitle bekler hep o kapıda. Orada ne ...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzur-yurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorum', 'yorum-selim-bayrak-30116', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Orhan Gencebay''la 

‎İsmail YK arasında

‎Ajdar gibi salınıyorum

‎

‎Alınıyorum 

‎Kalınıyorum

‎

‎Yaşam bir yorum meselesi

‎Beni pek de yorumlamayanlara

‎Gurursuz ruhumu 

‎Kendi kendime yoruyorum... 

‎

‎Aşikar olman gereken yerde

‎Saklanmak onur değildir

‎Kibir... 

‎Hayatı muhasebe defteri gibi

‎Tutan Güzellere

‎Sevdalarımı

‎Un ufak yoruyorum

‎

‎Oysa onlara

‎Un değil değirmen lazım

‎Ya un olup öğütülecekleri 

‎Ya da cin olup döndürecekleri

‎

‎Ya bir su başını

‎Tutacaksın 

‎Ya da rüzgargarlı 

‎Bir bağı 

‎Az ya da çok

‎Bir nemayı

‎En azından 

‎Dişe dokunur

‎Rahat okunur 

‎Bir yamayı

‎

‎Kimse 

‎Kara kaşa

‎Kara göze 

‎Ruha öze 

‎Atmaz çıpayı

‎Bırakmaz elindeki

‎Eşengiz çapayı

‎

‎Aşıklar Enayi

‎Güzellikler Sanayidir

‎Aşıklar Bakar

‎Uyanıklar

‎Boyanıklar

‎Kirpili Kediler

‎Mirasyediler 

‎Yaşar... 

‎

‎Herkes 

‎Böyle değil tabi

‎Ama şairin mürekkebi

‎Gönlünden taşar 

‎Haddini aşar

‎

‎Sirkte

‎Haklı haksız 

‎Kim alınıyorsa

‎Alınsın üstüne

‎

‎En Haksızı

‎Benim zaten :))) 

‎

‎

‎🌈

‎

‎

‎20.11.2026 / Haksız... 

‎

‎

‎❣️

‎

‎

‎

‎', 'Orhan Gencebay''la  ‎İsmail YK arasında ‎Ajdar gibi salınıyorum ‎ ‎Alınıyorum  ‎Kalınıyorum ‎ ‎Yaşam bir yorum meselesi ‎Beni pek de yorumlam...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/yorum-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamane Cambazları', 'zamane-cambazlari-senturk-dursun-0rzk8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ZAMANE CAMBAZLARI

Akıl sır ermez oldu şimdiki cambazlara

Şapkaya tavşan sokar, binlerce kuş çıkarır

Dalga dümen çevirir yön verir bağnazlara

Boşu dolu gösterir, doludan boş çıkarır

Gün gelir şeytan olur, cinliğe akıl yetmez

Gün gelir Lawrens olur, rol yapsa da sırıtmaz

Gün gelir hayal satar, falcıları aratmaz

Kâbus dolu geceden romantik düş çıkarır

Terazide ayar yok, adaletten dem vurur

Yalanı tekrarlayıp, gerçeği unutturur

Rakamı tersyüz eder, doğru diye yutturur

İkiyi üçe böler, sonucu beş çıkarır

Her gün biri eklenir, yüzsüzler kervanına

Yapanın yaptıkları kâr kalıyor yanına

Kendisi de inanır, kendinin yalanına

Zemheriyi yaz eyler, Temmuz’u kış çıkarır

Zihinler allak bullak, her sözünde bir tezat

Üzerine konmuyor hiçbir kusur kabahat

Ne millete fayda var, ne vatana sadakat

İhanet konusunda Yorgo’ya taş çıkarır

ŞENTÜRK DURSUN', 'ZAMANE CAMBAZLARI Akıl sır ermez oldu şimdiki cambazlara Şapkaya tavşan sokar, binlerce kuş çıkarır Dalga dümen çevirir yön verir bağnazlara...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/zamane-cambazlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hainlere', 'hainlere-senturk-dursun-kkj1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HAİNLERE

Eğer ki söz konusu vatana ihanetse

En ön safta kuyruğa, sıraya dizilirler

Türk Milleti şahlanıp, dünyaları fethetse

Hiçbirisi sevinmez, bilakis üzülürler

Kendi gibi değilse, hakir görür herkesi

Edep yerde sürünür, yırtıldı ar perdesi

İtibar görür oldu şahsiyet müsveddesi

Gittikçe çoğalıyor, sanmayın azalırlar

Gündemler belirlenir, yalanla safsatayla

Haklılık dayatılır, gürültü şamatayla

Tarihini karalar, akla ziyan yaftayla

Ceddine iftiradan adeta haz alırlar

Söylemler lafta kaldı, iflas etti sadakat

Kulaktan dolma bilgi, dillerinde nakarat

Memleketin bekası daha önemli fakat

Patatesi kıyaslar, soğanı baz alırlar

Doyumsuz muhterisler nefretini kussa da

Göz gerçeği görmese, dil sabredip sussa da

Melanetin rüzgârı, ne kadar sert esse de

Rüzgârlar kayalardan, yalnızca toz alırlar

ŞENTÜRK DURSUN', 'HAİNLERE Eğer ki söz konusu vatana ihanetse En ön safta kuyruğa, sıraya dizilirler Türk Milleti şahlanıp, dünyaları fethetse Hiçbirisi sevin...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hainlere-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melike', 'melike-recep-turk-r38oe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Melike

Gülüşü harmanda kaldı Melike''nin.

 Bir ahırda çocukluğu,

 çeşme başında genç kızlığı.

Sattı babası

 üç beş koyuna,

 bir ineğe kara gözlerini.

Bir cenazede gördüm sonra;

 kara çarşaf içinde

 iki bahtı kara göz.

Omuzları düşmüş,

 utanç ve öfke akıyordu sesinden.

"Babam yaşında adamın karısıydım on dokuzumda,

 kırkındayım şimdi" dedi.

Boyumda kızım var.

 Kederi ona benzemesin dedim.

Gülüşü harmanda kaldı Melike''nin,

 yırtık gömleğimin cebinde

 ilk öpücüğü.

Yozgat Hapishanesi

 09.05.2026

 Recep Türk', 'Melike Gülüşü harmanda kaldı Melike''nin.  Bir ahırda çocukluğu,  çeşme başında genç kızlığı. Sattı babası  üç beş koyuna,  bir ineğe kara gö...', ARRAY['Türk Edebiyatı','Şiir','Recep Türk']::text[], 8.5, '{"poet":"Recep Türk","poet_slug":"recep-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/melike-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maraş Depremi', 'maras-depremi-senturk-dursun-qpmpm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MARAŞ DEPREMİ 

Yıl iki bin yirmi üç, günlerden altı Şubat

Sözün aciz kaldığı, hallere şahit olduk

Dördü on yedi geçe, adeta durdu hayat

Açmadan solup giden, güllere şahit olduk

Karanlığa büründü, her tarafta ışıklar

Kulağı sağır etti enkazdaki çığlıklar

Yüreklerde sızılar, dudakta hıçkırıklar

Gözlerde buram buram, sellere şahit olduk

Kimisi can derdinde, yıkıntılar içinde

Kimisi kurtulsa da, sıkıntılar içinde

Kimisi umut arar döküntüler içinde

Boynu bükük çaresiz, kullara şahit olduk

Yerle yeksan eyledi, dağı taşı kumsalı

Nice can uçtu gitti, bir kelebek misali

Böyle bir felaketin görülmedi emsali

Harabe kasabaya, illere şahit olduk

Nice nice insanın can kopardı canından

Yerler gökler inledi, feryad-ı figanından

Doğu Batı demeden, dünyanın dört yanından

Yardım için uzanan, ellere şahit olduk

Yeniden hatırlattı insanlık ilkemizi

Bir kenara bıraktık nefret ve öfkemizi

Her şeyi değiştirdi, depremin acı izi

Metrelerce yarılmış, yollara şahit olduk

Herkese mezar oldu, fiyakalı binalar

Toz toprağa karıştı, ellerdeki kınalar

Gözü yaşlı babalar, bağrı yanık analar

Evlada ağıt yakan, dillere şahit olduk

ŞENTÜRK DURSUN', 'MARAŞ DEPREMİ  Yıl iki bin yirmi üç, günlerden altı Şubat Sözün aciz kaldığı, hallere şahit olduk Dördü on yedi geçe, adeta durdu hayat Açma...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/maras-depremi-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Meclisi', 'gonul-meclisi-senturk-dursun-73qt3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÖNÜL MECLİSİ

Gözetmedik, dili dini mezhebi

Gül götürdük, gittiğimiz adrese

Ayırmadık Laz’ı, Kürd’ü Arap’ı

Eşit gördük, eşit baktık herkese

Gözümüzde anlı şanlı tuğralar

Özümüzde tükenmeyen kavgalar

Dilimizde yakarışlar dualar

Vuku bulmaz, dedikodu vesvese

İyiliğe giden yoldur her niyet

Gönlümüzde, kalbimizde merhamet

Gözde sevgi, masamızda hoş sohbet

Yer vermedik, fitne fesat iblise

Silip attık içimizden elemi

Sevgimize ortak ettik alemi

Kalpten verdik merhabayı selamı

Bize uymaz kibir denen elbise

Güçlü diye kayırmadık haksızı

Yoldaş ettik garibanı öksüzü

Hayra yorduk her kelamı her sözü

Şer sokmadık, gönüldeki meclise

ŞENTÜRK DURSUN', 'GÖNÜL MECLİSİ Gözetmedik, dili dini mezhebi Gül götürdük, gittiğimiz adrese Ayırmadık Laz’ı, Kürd’ü Arap’ı Eşit gördük, eşit baktık herkese ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gonul-meclisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihat''sız Akağaç Kahvaltısı', 'nihat-siz-akagac-kahvaltisi-alper-tunga-3-k5f5r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Akağaçta öglene kalan bir sabah kahvaltısı,

Nihat dükkânın anahtarıyla kaybolduğu için

Geçen haftada Mithat Denizli''ye gidince

Ona yanmamda, Nihat dönünce yine başlarsa

Doğru yalan anlatırda anlatır...Yani, dönünce

Feridun ve köksal hanım, Nazmi abi ve ben,

Ben işte...Ayık Sami ve zeytin, peynir, domatesli

Bana derler Ayık Sami, arkamdanda konuşurlar.

Eh!...Ne derlerse desinler sırası değil şimdi

Kahvaltıdayız be Sami! Kahvaltı be oğlum...

Eski gazeteler seriliyken

o haberler ve garip ikilem sanki

Feridun görmesin diye politika sayfası çevrili

Kafa açar be...Yoksa onun bizimle derdi yok...

Zeytinin ve  çatallın bir meselesi var bende,

Ulan bir tutsam, yani; kaçmasa sağa sola

Yani şimdi, bu zeytin elle yenilir!

Ulan Nihat, bir anlayamadım ya seni...

Merhaba Kamer abla, merhaba Nazmi abi

Burası akağaç kıraathanesi, her zaman gelin.

Bizim kahvaltımızında yok vakti saati

Nihat''ı görürseniz söyleyin, neyse yada...', 'Akağaçta öglene kalan bir sabah kahvaltısı, Nihat dükkânın anahtarıyla kaybolduğu için Geçen haftada Mithat Denizli''ye gidince Ona yanmamda,...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nihat-siz-akagac-kahvaltisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakışların', 'bakislarin-senturk-dursun-autf2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BAKIŞLARIN

Akşam karanlığında, şavkın vurur geceme

Şafaksız sabahıma, tan verir bakışların

Yağmura eşlik edip, damlıyorsun sineme

Gökkuşağı rengime, ton verir bakışların

Yüce bir emir ile, vuslat varsa kaderde

Dünyada olmasa da, kavuşuruz mahşerde

Ya sen varsın ya gölgen, her anımda her yerde

Adeta hayatıma, yön verir bakışların

Senle giydim sırtıma, sevdanın libasını

Endamın silip attı gözlerimin pasını

Tebessümün bitirdi yüreğimin yasını

Her türlü melanete, son verir bakışların

Hangi yöne yönelsem, hep sana yaklaşıyor

Yapayalnız şu gönlüm, seni sensiz yaşıyor

Gururum senin için, nefsimle savaşıyor

Can çekilmiş bedene, can verir bakışların

Yokluğunda başıma, hüzün yağar dert yağar

Yıldızlar soluklaşır, karanlık beni boğar

Gözlerine baktıkça ufkuma güneş doğar

Kuruyan damarıma, kan verir bakışların

ŞENTÜRK DURSUN', 'BAKIŞLARIN Akşam karanlığında, şavkın vurur geceme Şafaksız sabahıma, tan verir bakışların Yağmura eşlik edip, damlıyorsun sineme Gökkuşağı ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bakislarin-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim', 'sana-geldim-senturk-dursun-4a3qf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SANA GELDİM

Gittiğinde bomboş kalan

Kollarımla geldim sana

Buram buram hüzün çalan

Tellerimle geldim sana

Girdap oldun çektin beni

Boran oldun yıktın beni

Ateş oldun yaktın beni

Küllerimle geldim sana

Özlemin var benden taşan

Gizlerin var beni aşan

Harap bitap, perperişan

Hallerimle geldim sana

Her sözünde sitem saklı

Bilemedik kimdir haklı

Elvan elvan çiçek yüklü

Dallarımla geldim sana

Yürek yaram kanar oldu

Her tarafım yanar oldu

Gözyaşlarım pınar oldu

Sellerimle geldim sana

ŞENTÜRK DURSUN', 'SANA GELDİM Gittiğinde bomboş kalan Kollarımla geldim sana Buram buram hüzün çalan Tellerimle geldim sana Girdap oldun çektin beni Boran old...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sana-geldim-307-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-senturk-dursun-3qp8c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİR TANEM

Ne yüzüme bir tebessüm eyledin

Ne gönlünü araladın bir tanem

Ne  şiirler ne şarkılar söyledin

Ne bir mektup karaladın bir tanem

Yıllar oldu, aramadın sormadın

Aşka dair, hiçbir ümit vermedin

Gözümdeki yaşlarımı görmedin

Yüreğimi paraladın bir tanem

Sen canan ol, ben de sana geleyim

Ferman sende, öl diyorsan öleyim

Kapındaki esirinim köleyim

Benliğimi kiraladın bir tanem

Günden güne çile ektim çileme

Senden sonra aşk girmedi haneme

Gidişinle ok sapladın sineme

Binbir yerden yaraladın bir tanem

Bülbül ettin, güle boyun eğdirdin

Nedametin hırkasını giydirdin

Firkat için, bahaneler uydurdun

Onca sebep sıraladın bir tanem

ŞENTÜRK DURSUN', 'BİR TANEM Ne yüzüme bir tebessüm eyledin Ne gönlünü araladın bir tanem Ne  şiirler ne şarkılar söyledin Ne bir mektup karaladın bir tanem Yı...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-tanem-318-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerek Yok', 'gerek-yok-senturk-dursun-4gkmq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GEREK YOK

Gönül gözüm gördü seni

Göze gerek bırakmadın

Ela gözler yaktı beni

Köze gerek bırakmadın

Sensiz geçmez yıllar aylar

Gözler sevmiş gönül neyler

Bakışların çok şey söyler

Söze gerek bırakmadın

Beni bende var eylersin

İkimizi bir eylersin

Hem çalarsın hem söylersin

Saza gerek bırakmadın

Gönül esir gönül tutsak

Dolaşırım köşe bucak

Dalımdayken soldu yaprak

Güze gerek bırakmadın

Şarkılara yazdım seni

Satırlara dizdim seni

Hayalime çizdim seni

Poza gerek bırakmadın

ŞENTÜRK DURSUN', 'GEREK YOK Gönül gözüm gördü seni Göze gerek bırakmadın Ela gözler yaktı beni Köze gerek bırakmadın Sensiz geçmez yıllar aylar Gözler sevmiş ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gerek-yok-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bir İstila', 'ask-bir-i-stila-nurcan-bingol-2-0nu3n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nurcan Bingöl

Aşk neydi? Bir sınır ihlali, içeriden gelen bir istila.
Haritam yoktu ama yerim belliydi, kendimdeydim.
Kapı kırılmadı, duvar yıkılmadı, hiçbir ses duymadım.
İçimde başka bir düzen kurulurken ben aynı kaldım sandım.
Aynada yüzüm hâlâ benimdi. Peki o bakış kime aitti?

Adım ağzında buzdu, sen söyledikçe hece hece eridi.
Bir gün kendi sesimle senin sözlerini söylediğimi duydum.
İçimde bir ülke kurdun, sınırlarımı tek tek sildin.
O ülke hâlâ benim adımı taşıyordu,
ben kendi içimde bir misafir gibi dolaşıyordum.

Zaman kaydı, eksenim şaştı. Dün bende kaldı, yarın seninle başladı.
Rüyamın kenarına adını yazdın, uyandığımda dilimde senin harflerin vardı.
Bedenim burada, ruhum sürgün. Seni her gün başka bir dilde konuşuyorum.
Kendi dilime dönüyorum, kendimi orada da bulamıyorum.

Kaçamam, kalamam. Ait olduğum yer artık ben değilim.
Bir zamanlar kendim dediğim bu ten şimdi kimin evi?
Beni benden alırken beni bana bırakır mısın?
Sadece yer değiştirdik. Sen içimde kaldın, ben kendime dışarıdan baktım.

İçeriden gelen bir nefes mi, yoksa bir emir mi?
Ben içimden çekilirken yerime sen mi geçtin?

İçeriden gelen, adı silinmiş iz…
Aşk bitti mi, kim kaldı? Ben miyim, yoksa biz?

Aşk neydi? Bir sınır ihlali.
İçeriden gelen sessiz bir istila.', 'Nurcan Bingöl Aşk neydi? Bir sınır ihlali, içeriden gelen bir istila. Haritam yoktu ama yerim belliydi, kendimdeydim. Kapı kırılmadı, duvar ...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ask-bir-istila-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvenme Dağlara', 'guvenme-daglara-senturk-dursun-bet1c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÜVENME DAĞLARA

Bir bakarsın kar yağmış güvendiğin dağlara

Dostum var zannedersin halini soran olmaz

Ummadığın bir anda hazan vurur bağlara

Her yüzüne gülenden arkadaş yaren olmaz

Albümleri toz kaplar solgunlaşır resimler

Gönüllerden silinir hatırlanmaz isimler

Menfaat sonlanınca hasım olur hısımlar

Yapayalnız kalırsın yanında duran olmaz

Özlemler suskunlaşır feryadın kıskacında

Yağmurlar saklı kalır bulutun yamacında

Damlalar sıralanır kirpiğinin ucunda

Gece gündüz ağlarsın teselli veren olmaz

Ruhunun yorgunluğu taşarken bedeninden

Ömründen ömür gider, gün eksilir gününden

İhanet darbesiyle kan süzülür teninden

Bağrına hançer yersin yaranı saran olmaz

Şentürk Dursun', 'GÜVENME DAĞLARA Bir bakarsın kar yağmış güvendiğin dağlara Dostum var zannedersin halini soran olmaz Ummadığın bir anda hazan vurur bağlara ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/guvenme-daglara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naz Makamı', 'naz-makami-haci-ahmet-kucuk-lmqig', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ALLAHIM , her gece başımı yastığıma koyduğumda ettiğim dualarımı duymuyor musun? 

Yoksa gözyaşlarıyla yalvarmalarımda ısrar etmemi mi bekliyorsun ? 

Benim SENDEN başka kimim var ki yanında gerçek ben olabildiğim? 

SEN de beni terk edersen ne kalır benden geriye ? 

Yakarışlarıma ihtiyacı mı var Kainat Sahibinin,

Sonsuz hazinenden payıma düşeni almak hakkım değil mi ? 

Ben sabırsız güçsüz bir deli, SEN ise her eksiklikten münezzeh EN-NÂFİ

SEN de beni terkedersen kime nazlanır bu deli? 

Belki iyi bir kul olamadım sana , 

Belki emanetine sahip çıkamadım hakkıyla,

Belki şükredemedim verdiğin nimetlere kana kana ,

SEN de beni terk edersen nasıl affettiririm kendimi sana ? 

Yıllarca korkuyla büyüttü beni toplum denen serseri tayfa ,

İnandırmak istediler menfi safsatalara ,

Gönlümün en derinin de yer verdim SANA 

Sen de beni terkedersen nasıl tanıyabilirim SENİ hakkıyla ? 

Rabbim, seferdeyim zafer isterim SENDEN,

Bu seferde bazen çöllerden geçiyorum bazen nehirlerden ,

Beni neden bu kadar güçsüz yarattın 

Ne çölün sıcağına dayanıyor bedenim ne de nehirlerin akıntısına … 

Kapına geldim ey Merhametlilerin Merhametlisi, 

Kapının ardında bana da yer var mı ? 

Beni bir başıma bırakamazsın dünya denen kocaman ahırda , 

Hakkım olan SENİ istiyorum SENDEN .

SEN de beni terkedersen nasıl alırım hakkımı SENDEN ? 

SEN yaratıcıların en mükemmelisin,

Mimarine uygun olmayanları yok et Allahım.

SEN plan yapanların en hayırlısısın,

Planları bozgunculuk olanları def et Allahım. 

SEN de beni terkedersen nasıl inanırım iyiliğin kötülüğe galip geleceğine ? 

Görmediğim SANA iman ettim ben , 

Beni, inkar edenlerin eline bırakma Allahım

Koyduğun kanunlara biat ettim ben,

Asilere yem etme beni Allahım. 

SEN de beni terk edersen nasıl güvenirim SENİN terazine ? 

Yakarışlarıma ihtiyacı mı var Kainat Sahibinin,

Sonsuz hazinenden payıma düşeni almak hakkım değil mi ? 

Ben sabırsız güçsüz bir deli, SEN ise her eksiklikten münezzeh EN-NÂFİ

SEN de beni terkedersen kime nazlanır bu deli?', 'ALLAHIM , her gece başımı yastığıma koyduğumda ettiğim dualarımı duymuyor musun?  Yoksa gözyaşlarıyla yalvarmalarımda ısrar etmemi mi bekliy...', ARRAY['Türk Edebiyatı','Şiir','Hacı Ahmet Küçük']::text[], 8.5, '{"poet":"Hacı Ahmet Küçük","poet_slug":"haci-ahmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/naz-makami-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadık', 'anlamadik-senturk-dursun-87e96', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ANLAMADIK

Güzelim memlekete, yarasalar dadandı

Kanımızı emerek, doydular anlamadık

Bukalemun misali, renkten renge boyandı

Sırtlanlar kuzu postu, giydiler anlamadık

Kalplerinde merhamet, ruhlarında barış yok

İskeletler kemiksiz, omurgalı duruş yok

Kepçeyle topladılar, ver deyince kuruş yok

Alenen cebimizi, soydular anlamadık

Geçmişi yok saydılar, gelenekten koptular

Ülkede yangın varken, yangından mal kaptılar

’’Vatan millet Sakarya’’ diyerek rol yaptılar

Her şekile kalıba, uydular anlamadık...

Nasibini almamış, insanlıktan ahlaktan

Gözümüz şaşı oldu, çizdikleri zikzaktan

Dilimizde tüy bitti, gerçeği haykırmaktan

İşlerine geleni, duydular anlamadık

Kırdılar yüreklerin hevesini şevkini

Bozdular gönüllerin ritmini ahengini

Karaya boyadılar, vicdanların rengini

Günbegün gözümüzü, oydular anlamadık

Hamaset yüklediler, slogan attırdılar

Zehirli söylemleri bal diye tattırdılar

Sıpayı makyajlayıp, at diye yutturdular

Bizi aptal yerine, koydular anlamadık

ŞENTÜRK DURSUN', 'ANLAMADIK Güzelim memlekete, yarasalar dadandı Kanımızı emerek, doydular anlamadık Bukalemun misali, renkten renge boyandı Sırtlanlar kuzu p...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anlamadik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sigara Daha Yaktım', 'bir-sigara-daha-yaktim-ekrem-olgun-tanap', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİR SİGARA DAHA YAKTIM

Bir sigara daha yaktım…
Ne tütüne ihtiyacım vardı,
Ne de dumanına.
İnsan bazen bir ateş arıyor,
İçinde çoktan kül olmuş
Bir şeylerin hâlâ yandığına inanmak için.

Gece, bütün karanlığını üzerime zimmetlemiş.
Saatler ilerliyor,
Ama zaman benden bir adım öteye gidemiyor.
Masada yarım kalmış bir çay,
Küllükte ömrünü tüketmiş izmaritler…
Ve ben,
Kendi yokluğuma alışmaya çalışan
Bir yabancı gibi oturuyorum kendimde.

Bir sigara daha yaktım…
Dumanı tavana yükselirken düşündüm;
İnsan neden en çok
Unutmak istediği şeyleri hatırlar?
Neden bazı vedalar
Bir kapının kapanmasıyla bitmez de
İnsanın içinde
Ömür boyu açık kalan bir yaraya dönüşür?

Meğer gitmek,
Yalnızca bir yerden ayrılmak değilmiş.
Bazen insanın içinden biri gider,
Ardından bütün mevsimler göç edermiş.
Ve geriye,
Hangi bahara ait olduğunu bilmeyen
Yetim bir takvim kalırmış.

Bir sigara daha yaktım…
Bu kez seni değil,
Sende kaybettiğim kendimi düşündüm.
Ne çok şey bırakmışım
Bir insanın kalbinde.
Öyle ki,
Sen giderken yalnız kalmadım ben;
Kendime dönecek yolu da
Senin ayak izlerinde kaybettim.

Kül uzadıkça ömrüm kısaldı sanki.
Bir ateşin ucunda
Ne kadar çok geçmiş birikebilirmiş…
Oysa insanı tüketen
Yılların geçmesi değil,
Geçmişin bir türlü geçmemesiymiş.

Bir sigara daha yaktım…
Ve ilk kez fark ettim;
Ben her nefeste seni içime çekmiyordum,
İçimde senden kalanları
Dışarı atmaya çalışıyordum.
Ama ne tuhaf…
Duman çıkıyordu göğsümden,
Sen kalıyordun.

Sonra anladım…
Bazı insanlar bir ömür yanar,
Kimse onların külünü görmez.
Çünkü en büyük yangınlar
İtfaiyenin değil,
İnsanın kendi vicdanının
Geç kaldığı yerlerde çıkarmış.

Ve ben…
Son sigaramı söndürürken
Bir gerçeğin başında eğildim:

Meğer ben seni unutmak için
Bir sigara daha yakmamışım.
Her defasında biraz daha kül olup,
Bir gün hatırlayacak
Hiçbir yanım kalmasın istemişim.

EkOL', 'BİR SİGARA DAHA YAKTIM Bir sigara daha yaktım… Ne tütüne ihtiyacım vardı, Ne de dumanına. İnsan bazen bir ateş arıyor, İçinde çoktan kül olm...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/bir-sigara-daha-yaktim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımda Canan', 'canimda-canan-senturk-dursun-utgcy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'CANIMDA CANAN

Her hikâye her anı, seni bana anlatır

Ruhumda heyecanım, canımda canan sensin

Gördüğüm güzellikler, hep seni hatırlatır

Gözlerimde temaşa, dilimde lisan sensin

Hicranla ufalanıp, rüzgârla tozuyorum

Şiiri şarkıları hep sana yazıyorum

Kalbimin ortasına, resmini çiziyorum

Gönlümün tualinde, ebedi mihman sensin

Bir hüzün rüzgârıyla, dalgalandı saçlarım

Toz kapladı ovamı, sislendi yamaçlarım

Seninle hayat bulur, kuruyan ağaçlarım

Soluduğum nefesim, derdime derman sensin

Yüzünü gördüğüm an, ne dert kalır ne elem

Geceye güneş doğar, güzelleşir şu alem

Sana olan aşkımı, anlatmaz kâğıt kalem

Yürekteki yangınım, başımda duman sensin

ŞENTÜRK DURSUN', 'CANIMDA CANAN Her hikâye her anı, seni bana anlatır Ruhumda heyecanım, canımda canan sensin Gördüğüm güzellikler, hep seni hatırlatır Gözler...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/canimda-canan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teslimat', 'teslimat-senturk-dursun-pjn4e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'TESLİMAT

Sanırsın içerimde, patlayan volkanlar var

Sönmeyen ateşimi, küllere teslim ettim

Halimi ahvalimi, bilmedi vefasız yar

Döktüğüm gözyaşımı, göllere teslim ettim

Çok şey geldi başıma, çok badire atlattım

Ne baharı yaşadım, ne de bir sevgi tattım

Hayatın takvimine, çözülmez kement attım

Ayları mevsimleri, yıllara teslim ettim

Görünmüyor çektiğim, vurgunlar işkenceler

Bugün gün doğmayacak, sabahsızdır geceler

Cümleler kavuşmuyor, darmadağın heceler

Feryad-ı figanımı dillere teslim ettim

Silindi gözlerimden tebessümün izleri

Derdim aştı dağları, deryayı denizleri

Yordukça yordu beni, hayatın dehlizleri

Dermansız dizlerimi, yollara teslim ettim

Hangi gönül dayandı, aşkın yanan harına

Sevinci eğlenceyi, erteledim yarına

Zamansız Eylül geldi, ömrümün baharına

Hazanlı yaprağımı, dallara teslim ettim

ŞENTÜRK DURSUN', 'TESLİMAT Sanırsın içerimde, patlayan volkanlar var Sönmeyen ateşimi, küllere teslim ettim Halimi ahvalimi, bilmedi vefasız yar Döktüğüm gözy...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/teslimat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tevekkül', 'tevekkul-gecenin-huznu-2-wut21', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '​Seni severken kendimi,

Beni yaratanı,

Güzeli ve yaratılmış tüm güzellikleri sevmeyi öğrendim.

Kalbimin içinde uçsuz bucaksız bir gökyüzü,

Avuç içlerimde derin bir umman keşfettim.

​Senden sonra daha bir sevdim sokakları adımlamayı,

Çocukları daha bir şefkatle kucakladım,

Haksızlık karşısında daha bir dik durdum.

Çok öldüm "biraz" olana kadar;

Öyle çok öldüm ki, bir baktım "sen" olmuşum.

​Benim sana olan sevdam, bir kadının bir adama sığınma isteğinden çok daha fazlasıydı.

Öyle ki; göğsüm tenleri ve yolları aşıp doğrudan göğe sarıldı.

Sonradan anladım ki bu sevdalanışın sonucu bir vuslat değil; beni benden edip, senden de geçip Hak olana varmakmış.

​Herkes bir teni, fani bir hayali arzuladığımı sanıyordu.

Oysa kapım öylesine çok çalınıyordu ki...

Eğer aradığım dedikleri gibi fani bir heves ya da maddi bir karşılık olsaydı; başımı yerden kaldırır, suretlere ve g/özlere doğru konuşurdum.

Geçici rüzgarlar sızmasın diye gönlümün temiz otağına, kapılarımı böylesine sıkı kapatmazdım.

​Şimdi; bana nasip edilen bu imtihana da, nasip edilmeyen sevdama da şükredip her şeyi içimin en derinine saklama demindeyim.

Oysa o kadar aşikarım ki her halimle,

Ve bir o kadar da gizli...

​Onca yıl sana anlatmak için göğsümde biriktirdiğim cümlelerle, g/özümde sakladığım b/akışlarla ve dizinin dibinde çözülmeyi bekleyen sırlarla; senin olmadığın bir hayata adım atıyorum artık.

Sensiz yollar beni nerelere vardırır bilmiyorum.

Bildiğim tek şey; istenmediğimi bildiğim ve bir imtihan ateşinden geçip küle döndüğüm o devrin kapandığıdır.

​Her son yeni bir başlangıçtır, biliyorum.

Her ne kadar sensiz başlangıçları almasa da içim; sevilmeden yanında ya da karşında durmayı da bir o kadar almıyor...

​Tevekkül diyorum...

Bu imtihanı verenin hatrına, kalan tüm güzellikleri yaşamak ve yaşatmak diyorum.

"Hep"in içinde yok olmuş bir hiç olup, kaybolurken dahi bulduklarımla yoğrulmak diyorum.

​Ve susuyorum.

Rabbe varacağım o güne susayarak 

Susuyorum...', '​Seni severken kendimi, Beni yaratanı, Güzeli ve yaratılmış tüm güzellikleri sevmeyi öğrendim. Kalbimin içinde uçsuz bucaksız bir gökyüzü, A...', ARRAY['Türk Edebiyatı','Şiir','Gecenin Hüznü 2']::text[], 8.5, '{"poet":"Gecenin Hüznü 2","poet_slug":"gecenin-huznu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/tevekkul-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşanlar', 'bulusanlar-senturk-dursun-855cd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BULUŞANLAR

Topyekûn birleşti boşta kim varsa

Garip bir ittifak oluşturdular

Dünyadan uzaya, Venüs’ten Mars’a

Bütün karşıtları buluşturdular

Masa yusyuvarlak altı ayaklı

Yedinci masanın altında saklı

Her türlü cenahtan iri ufaklı

Zorla birbirine iliştirdiler

Birden fazla kişi barınsın diye

Aynı şemsiyede korunsun diye

Masa kalabalık görünsün diye

Eski artıkları doluşturdular

Bir telin üstünde bir sürü cambaz

Her biri zıt kutup siyahla beyaz

Ne tepki koyan var, ne de itiraz

Zamanla her şeye alıştırdılar

Cümleler cilalı sözden ibaret

Simalar maskeli yüzden ibaret

Ezelden ebede budur zihniyet

Doğru olanı da eleştirdiler

Göze perde indi akıl tutuldu

Tencere devrildi kapağı buldu

Komşuluk oyunu oynanır oldu

Her gün kapı kapı dolaştırdılar

Üç burgulu boynuz, taktı koyunlar

Pamuktan ipliğe serildi unlar

Hep aynı senaryo, aynı oyunlar

Hepsine birer rol, bölüştürdüler

Başından belliydi böyle akıbet

Gün yüzüne çıktı sinsi siyaset

Kel kafa göründü düştü apolet

Sonunda herkesi gülüştürdüler

ŞENTÜRK DURSUN', 'BULUŞANLAR Topyekûn birleşti boşta kim varsa Garip bir ittifak oluşturdular Dünyadan uzaya, Venüs’ten Mars’a Bütün karşıtları buluşturdular ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bulusanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Islak İmza', 'islak-i-mza-senturk-dursun-xurx5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ISLAK İMZA

Sensiz geçen her gece, hüznümün şahididir

Hasretinle yaşamak, ölümden beter bana

Kor düşen garip gönlüm, bir sevda şehididir

Alevler harlandıkça, dumanı tüter bana

Titreyen nağmelerde, çalar aşkın türküsü

Gülistanda bir gülsün, dilde sevda öyküsü

Gönüllere işlendi, sevgimizin örgüsü

Yanımda olmasan da, varlığın yeter bana

Mevsimleri sakladım, yılların gölgesinde

Sararmış bir yaprağım, dalların gövdesinde

İkrarın benim için, yeminin ötesinde

Gözlerin ıslak imza, bakışın noter bana

Yokluğunla eridim, kurumaya başladım

Umutlar ülkesinde, hayal ettim düşledim

Bütün güzelliğini, şiirlere işledim

Kirpikten kalem yaptım, cemalin defter bana

ŞENTÜRK DURSUN', 'ISLAK İMZA Sensiz geçen her gece, hüznümün şahididir Hasretinle yaşamak, ölümden beter bana Kor düşen garip gönlüm, bir sevda şehididir Alev...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/islak-imza-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamazsın Yâr', 'bulamazsin-y-r-senturk-dursun-r6zat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BULAMAZSIN YÂR

Benden uzaklarda huzur arama

Bensiz mutluluğu bulamazsın yâr

Ben sensiz ağlarken gülerim sanma

Beni güldürmeden gülemezsin yâr

Yaşamın anlamı mânâsı sende

Amber kokun gelir, rüzgâr esende

Umut var demektir can varsa tende

Yarın ne getirir bilemezsin yâr

Elbet dökülecek sararan yaprak

Yaprağa can vermez kuruyan toprak

Bizimle doğacak doğmayan şafak

Ayrılığı göze alamazsın yâr

Hasretinle içten içe erirken

Ömrümden gün çalıp, sana verirken

Ben seni kendimden öte görürken

Aşkıma duyarsız kalamazsın yâr

ŞENTÜRK DURSUN', 'BULAMAZSIN YÂR Benden uzaklarda huzur arama Bensiz mutluluğu bulamazsın yâr Ben sensiz ağlarken gülerim sanma Beni güldürmeden gülemezsin yâ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bulamazsin-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Sensizlik', 'bendeki-sensizlik-senturk-dursun-m5zr6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BENDEKİ SENSİZLİK

Gönlüme anlatamam, bendeki sensizliği

Yine eskisi gibi, sevgi ile bak bana

İçime sindiremem, sendeki bensizliği

Sevdadan kıvılcım yap, bir meşale yak bana

Yürüdüğüm yollarım, yordukça yordu beni

Ne yoldaşım aradı, ne dostum sordu beni

Kara kara bulutlar, gölgeler sardı beni

Ne göğümde ışık var, ne sular berrak bana

Çağladıkça çağladım, sığmıyorum bendime

Gönlünü sığınacak, liman seçtim kendime

Bir hicran girdabında, dağıldım lime lime

Anladımki dünyada, tebessüm yasak bana

Mehtabın yamacına, vururken ay çehresi

Gecede yankılanır, acılı yürek sesi

Mevsimlerim kış olur, ilkbaharın ertesi

Mutluluk ne kelime, nefes bile çok bana

Pusulasız kalmışım, sisle kaplı ummanda

Boşluğa demir attım, her gittiğim limanda

Kavuşmamız imkânsız, dünya denen bu handa

Mahşeri bekliyorum, başka çare yok bana

ŞENTÜRK DURSUN', 'BENDEKİ SENSİZLİK Gönlüme anlatamam, bendeki sensizliği Yine eskisi gibi, sevgi ile bak bana İçime sindiremem, sendeki bensizliği Sevdadan k...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bendeki-sensizlik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dile Düşen Aşkımız', 'dile-dusen-askimiz-senturk-dursun-qhym0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DİLE DÜŞEN AŞKIMIZ

Şiir olduk ozanların sözünde

Dilden dile gezer bizim aşkımız

Nağme olduk gönüllerin sazında

Telden tele, gezer bizim aşkımız

Bazen bir ateşin sönmez harında

Bazen bir aşığın feryatlarında

Bazen bir ankanın kanatlarında

Daldan dala, gezer bizim aşkımız

Misafir eyledim kalp otağımda

Rüzgârın eksilmez gönül dağımda

Ateşin tütüyor aşk ocağımda

Külden küle, gezer bizim aşkımız

Sınavdayım ölümsüz bir sevdayla

İlişkimi kestim bütün dünyayla

Birimiz Mecnun’uz birimiz Leyla

Çölden çöle, gezer bizim aşkımız

ŞENTÜRK DURSUN', 'DİLE DÜŞEN AŞKIMIZ Şiir olduk ozanların sözünde Dilden dile gezer bizim aşkımız Nağme olduk gönüllerin sazında Telden tele, gezer bizim aşkı...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dile-dusen-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ASKERLERE HİTABE', 'askerlere-hi-tabe-taha-berat-ersanli-mf7rh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Asker Türk asker!
Asker vazifen, Asker şehit! Asker Türk milleti! Askerler düşmanlar ile savaştı! Dokunma, dokunma, şehidime. Şehitler ölmedi! Ölmeyecek! Bu vatan asla bölünmeyecek! Bu vatan asla bölünmeyecek! Askerler düşmanları kılıçla kesti! Düşmanlar öldü! Şehitler ölmedi! Askerler selam verirler. Askerler askerliğini yaparlar. Kasdedecek düşmanlar! Düşmanlar menfaattir. Askerler size hayırlı işler.

Taha Berat ERSANLI 
20 Kasım 2026', 'Asker Türk asker! Asker vazifen, Asker şehit! Asker Türk milleti! Askerler düşmanlar ile savaştı! Dokunma, dokunma, şehidime. Şehitler ölmed...', ARRAY['Türk Edebiyatı','Şiir','Taha Berat Ersanlı']::text[], 8.5, '{"poet":"Taha Berat Ersanlı","poet_slug":"taha-berat-ersanli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askerlere-hitabe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Hallerim', 'sensizlik-hallerim-senturk-dursun-vd246', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SENSİZLİK HALLERİM

Sevgisiz heba oldu, saatler dakikalar

Akrep ritmi kaybetti, yelkovan boşa döndü

Anladımki sen yokken, ne yaz gelir ne bahar

Gündüzlerim geceye, mevsimler kışa döndü

Yalnızlar rıhtımında, avare kimsesizim

Bulutlarda gezerim, görünmez ayak izim

Aynalarda kendimi, tanımaz oldu gözüm

Olmazlar gerçekleşti, gerçekler düşe döndü

Anlamını yitirdi, dildeki ifadeler

Aşk konulu sahnede, mühürlendi perdeler

Şimdi artık nafile, pişmanlıklar tövbeler

Kabuslar bitti derken, tekrardan başa döndü

Ayrılık yazılınca, kaderin defterine

Hüznümü yoldaş ettim, mutluluğun yerine

Beyaz bir kefen örttüm, aşkımın üzerine

Gözyaşlarım pınara, yüreğim taşa döndü

ŞENTÜRK DURSUN', 'SENSİZLİK HALLERİM Sevgisiz heba oldu, saatler dakikalar Akrep ritmi kaybetti, yelkovan boşa döndü Anladımki sen yokken, ne yaz gelir ne bah...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sensizlik-hallerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-senturk-dursun-z3upc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İTİRAF

Sevda kanununda sevmek suç ise

Bağrımın sol yanı sanıktır benim

Delile gerek yok arz-ı meclise

Her iki gözüm de tanıktır benim

Umut tazeledim yollara düştüm

Çölü arşınladım dağları aştım

Hasret ateşinin narıyla piştim

Yüreğim ezelden yanıktır benim

Deli bir dalgayla vurdum sahile

Teselli verecek sözler nafile

Bir yanım neşeli görünse bile

Bir yanım kedere dönüktür benim

Sancılar sarınca her bir yerimi

Bir gam silsilesi yer içerimi

Güneş aydınlatmaz gündüzlerimi

Gecemde yıldızlar sönüktür benim

ŞENTÜRK DURSUN', 'İTİRAF Sevda kanununda sevmek suç ise Bağrımın sol yanı sanıktır benim Delile gerek yok arz-ı meclise Her iki gözüm de tanıktır benim Umut t...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/itiraf-527-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar', 'mezar-tenha-kalem-tkbur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oldum şimdi bir mezar.

İçimi dolduruyor, hüznümden kalanlar.

Tanımadığım insanlar çiçek bırakıyor üzerime.

Bilmiyorum ki niye?

Sonuçta buradan önce hiç almamıştım.

Zamanım mı tükendi anlamadım.

Ne zaman düştüm bu boşluğa?

Umurunuzda değil mi bu yağmurlar?

Islanan yanaklarıma şu damlalar?

Kan kokusu gelmekte burnuma,

Adeta bir katl yapılmışcasına.

Kim niye kıyar ki bir cana?

Heyhat! belki de ben anlamadım bu kafayla.

Yakışamadım tabutuma.

Çiçeklerim de soldu,

Toprağım da kurudu.

Alışamadım bu dünyaya...', 'Oldum şimdi bir mezar. İçimi dolduruyor, hüznümden kalanlar. Tanımadığım insanlar çiçek bırakıyor üzerime. Bilmiyorum ki niye? Sonuçta burad...', ARRAY['Türk Edebiyatı','Şiir','Tenha Kalem']::text[], 8.5, '{"poet":"Tenha Kalem","poet_slug":"tenha-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mezar-184-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tam Zamanı', 'tam-zamani-senturk-dursun-btwzo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'TAM ZAMANI

Çakallara yer olmaz bozkurtların yurdunda

Soysuzlara dersini vermenin zamanıdır

Kimi dava gözetir, kimi hiçlik derdinde

Döneklere hesabı sormanın zamanıdır

Had bildirmek farz oldu, hadsizlere küstaha

En yakından tez elden, başlamalı siftaha

Hangi güç galip geldi, inanç denen silaha

Kahpeye son darbeyi vurmanın zamanıdır

Asya’dan Avrupa’ya yeni bir yelken açtık

Nice yol aşındırdık, nice sırattan geçtik

Ellerimiz semada, zafer için ant içtik

Zorbanın boynuzunu kırmanın zamanıdır

Başımızda taşırız merhamet edenleri

Kanlarında boğarız ihanet edenleri

Sorgu sual etmeden, niçin ve nedenleri

Hak davanın yanında durmanın zamanıdır

Al bayrağa renk verdik, şehidimin kanından

Kor alevler fışkırır kılıcımın kınından

Dağlar taşlar inlesin, sesimizin tonundan

Namerdin cephesini, yarmanın zamanıdır

Meydana çıktığında, hilâl kaşlı yiğitler

Sığınacak yer arar, sünepe korkak itler

Biliniz ki vız gelir, saldırılar tehditler

Hainlerin inine girmenin zamanıdır

ŞENTÜRK DURSUN', 'TAM ZAMANI Çakallara yer olmaz bozkurtların yurdunda Soysuzlara dersini vermenin zamanıdır Kimi dava gözetir, kimi hiçlik derdinde Döneklere...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tam-zamani-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Toprağı Altın Ülkem', 'tas-topragi-altin-ulkem-senturk-dursun-vbt50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'TAŞ TOPRAĞI ALTIN ÜLKEM

Taş toprağı altın, ülkem üstünde

Ne hesap, ne emel, ne plan biter

Basın özgürlüğü adı altında

Ne hain, ne casus, ne ajan biter

Gafiller cenneti oldu memleket

Sistemli şekilde soyuldu devlet

Servet haramzade sermaye rüşvet

Ne arsız, ne hırsız, ne talan biter

Hiç kimsede tarihinden ibret yok

Anlatsan da anlayacak ümmet yok

Doğruluğa dürüstlüğe niyet yok

Ne fitne, ne fesat, ne yalan biter

Gerçeği anlatmaz kelamı sözü

Karda fink atsa da, görünmez izi

Porsukla iş tutar evdeki tazı

Ne çakal, ne tilki, ne sırtlan biter

Koca başlar büyük geldi bedene

Yobaz derler Hak yolunda gidene

Alkış tutar hokkabazlık edene

Ne aptal, ne ahmak, ne sazan biter

Beraber ağlayıp gülmezsek eğer

Birlikte yeşerip solmazsak eğer

Milletçe tek yürek olmazsak eğer

Ne zarar, ne ziyan, ne hüsran biter

ŞENTÜRK DURSUN', 'TAŞ TOPRAĞI ALTIN ÜLKEM Taş toprağı altın, ülkem üstünde Ne hesap, ne emel, ne plan biter Basın özgürlüğü adı altında Ne hain, ne casus, ne ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/tas-topragi-altin-ulkem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtsız Kul', 'bahtsiz-kul-senturk-dursun-jhni8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BAHTSIZ KUL

Seni sayıklarım uykuda bile

Gayrısı girmedi düşüme benim

Bana reva mıydı, bunca dert çile

Bir de felek düştü peşime benim

Dışıma vururken içimin derdi

Mevsimler topyekün hazana erdi

Hiç kimse yüzüme gülmeyiverdi

Sitemim dostuma eşime benim

Gözyaşım iz yaptı yanaklarıma

Feryadım sığmadı dudaklarıma

Dört mevsim kar yağdı topraklarıma

Cemreler uğramaz kışıma benim

Hasret canevimden vurdu vuralı

Gönül paramparça bağrım yaralı

Demek ki bu imiş, aşkın kuralı

Bin türlü hal geldi başıma benim

Bedenden ruh gitti gözlerimden fer

Bulutlar yorganım yeryüzü minder

Fatiha yazılı, beyaz bir mermer

Bahtsız kul yazdılar taşıma benim

ŞENTÜRK DURSUN', 'BAHTSIZ KUL Seni sayıklarım uykuda bile Gayrısı girmedi düşüme benim Bana reva mıydı, bunca dert çile Bir de felek düştü peşime benim Dışıma...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bahtsiz-kul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüme İkram', 'gonlume-i-kram-senturk-dursun-ov4xf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖNLÜME İKRAM

Sen bana geldiğinde ufkuma güneş doğar

İster şafak vaktinde isterse akşam olsun

Varlığın varlığımdır, yokluğun beni boğar

Hasrete son verelim, her günüm bayram olsun

İçimi kemiriyor, kavgalar arbedeler

Ahvalimi anlatsam yetmiyor kelimeler

Efkârımı dağıtsın içli içli nağmeler

Bir şarkı söyle bana makamı hüzzam olsun

Sevgiler akıp gitsin yürüdüğün izinden

Yakamoz parıldasın dalgalı denizinden

Neşe dolu bakışlar eksilmesin yüzünden

Şiirlere vesile, kaleme ilham olsun

Mor sümbülle süslensin, sevdanın bahçeleri

Dilimde ezber olsun, isminin heceleri

Gözlerin aydınlatsın zifiri geceleri

Bir bakış bir gülüşün, gönlüme ikram olsun

Ey dünyamın perisi, mahşerimin hurisi

Gözümün ilk ağrısı, aşkımın mimarisi

Sensiz eksik sayılır, bedenimin yarısı

Gel bütünleş benimle, ben bende tamam olsun

ŞENTÜRK DURSUN', 'GÖNLÜME İKRAM Sen bana geldiğinde ufkuma güneş doğar İster şafak vaktinde isterse akşam olsun Varlığın varlığımdır, yokluğun beni boğar Hasr...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gonlume-ikram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Türevleri', 'i-nsan-turevleri-senturk-dursun-90y0o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İNSAN TÜREVLERİ

Menfaati gören davayı sattı

Sosyalistten şirketçiler türedi

Lavrensler çoğaldı ihanet arttı

Ecnebiye hizmetçiler türedi

Kimi gitti bir çıkmaza saplandı

Kimi gitti kuzu postu kaplandı

Beş benzemez bir araya toplandı

Milliyetsiz milletçiler türedi

Yelkeni kopardı dümeni şaştı

İntikam duygusu şiştikçe şişti

Dostun kazanında ihanet pişti

Günübirlik fırsatçılar türedi

Zevzek tipler ecdadına söverken

Ekranlarda katilleri överken

Dağdan gelen bağdakini kovarken

Vatanında gurbetçiler türedi

Aç gözler doymadı hep bana dedi

Fukara çalıştı zenginler yedi

Haram nedir, helal nedir bilmedi

Ak sakallı rüşvetçiler türedi

Dıştan baktım görünüşü er gibi

İcraatta bir tuhaflık var gibi

Anlasam da anlatması zor gibi

Milli tipli Sovyetçiler türedi

Sosyal medya kılavuzu rehberi

Kimi ayyaş kimi berduş serseri

Sorsan bilmez Fatihayı Kevseri

Beynamazdan ümmetçiler türedi

Ekmeğini garibanla bölmeyen

Vatan nedir, ülkü nedir bilmeyen

Ezan için, bayrak için ölmeyen

Sözüm ona devletçiler türedi

ŞENTÜRK DURSUN', 'İNSAN TÜREVLERİ Menfaati gören davayı sattı Sosyalistten şirketçiler türedi Lavrensler çoğaldı ihanet arttı Ecnebiye hizmetçiler türedi Kimi...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/insan-turevleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Can Eksiliriz Bin Can Oluruz', 'bir-can-eksiliriz-bin-can-oluruz-senturk-dursun-5bpxt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BİR CAN EKSİLİR BİN CAN OLURUZ

Yasımız biliriz dostun yasını

Derdiyle dertleşir derman oluruz

Cefamız sayarız her cefasını

Sefalar taşıyan kervan oluruz

Gözlerde parıltı özde metanet

Tavrımız mühürdür sözümüz senet

Ceddimizden gelir bu yüce kudret

Yiğitlik tahtında sultan oluruz

Yurdu yar biliriz aşık misali

Namludan fırlarız fişek misali

Gökte ışıldarız şimşek misali

İner yeryüzüne tufan oluruz

Damgalar vururuz her yeni çağa

Ay yıldız çizeriz ovaya dağa

Nidalar yükselir kalpten dudağa

Gönülden gönüle lisan oluruz

Yolda bırakmayız yolu yoldaşı

Bir gördük Çerkezi, Kürdü Dadaşı

Birgün topçu eri Seyit Onbaşı

Birgün Ulubatlı Hasan oluruz

Dualar yükledik yelkenimize

Hilâlden taç yaptık kefenimize

Şehadet şerbeti bayramdır bize

Bir can eksiliriz bin can oluruz

ŞENTÜRK DURSUN', 'BİR CAN EKSİLİR BİN CAN OLURUZ Yasımız biliriz dostun yasını Derdiyle dertleşir derman oluruz Cefamız sayarız her cefasını Sefalar taşıyan k...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-can-eksiliriz-bin-can-oluruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLARA HİTABE', 'cocuklara-hi-tabe-taha-berat-ersanli-93zln', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocuklar okula gider. Çocuklar ders çalışırlar. Çocuklar sizi çok seviyorum. Çocuklar iyiki varsın. Çocuklar olmasaydı bizde olamazdık. Çocuklar bisiklet sürerler. Çocukların arkadaşları olur. Çocuklar top oynar. Çocuklar derslerinde başarılı olurlar.
Çocuklar öğrenci olurlar. Çocuklar paten sürerler. Çocuklar resim yaparlar.

Taha Berat ERSANLI 
20 Kasım 2026', 'Çocuklar okula gider. Çocuklar ders çalışırlar. Çocuklar sizi çok seviyorum. Çocuklar iyiki varsın. Çocuklar olmasaydı bizde olamazdık. Çocu...', ARRAY['Türk Edebiyatı','Şiir','Taha Berat Ersanlı']::text[], 8.5, '{"poet":"Taha Berat Ersanlı","poet_slug":"taha-berat-ersanli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cocuklara-hitabe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizin Şarkısı', 'i-kimizin-sarkisi-senturk-dursun-9ock7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İKİMİZİN ŞARKISI

Gönül makamında şarkılar söyle

İçinde ninnili yar sesi olsun

İster bir kemanla ister bir meyle

İçimi titreten nağmesi olsun

Gönlüme dokunsun yasını atsın

Kulağı okşasın pasını atsın

İkimize dair sırrı anlatsın

Yalnız bize ait şifresi olsun

Damara ulaşsın verdiği tesir

Ruhumu hapsetsin gözümü esir

Bütün satırları bize münhasır

Aşkı tescilleyen güftesi olsun

Efkârlar damlatsın gönül tasından

Bağrıma işlesin tam ortasından

Sevdalar dökülsün her notasından

İlan-ı aşkımın müjdesi olsun

Yaşamın kaynağı olsun her demde

Baş rolü oynasın ömür sahnemde

Alevsiz bir ateş yaksın sinemde

Gönlümün dördüncü cemresi olsun

ŞENTÜRK DURSUN', 'İKİMİZİN ŞARKISI Gönül makamında şarkılar söyle İçinde ninnili yar sesi olsun İster bir kemanla ister bir meyle İçimi titreten nağmesi olsun...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ikimizin-sarkisi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağbanıma Gül Olmadın', 'bagbanima-gul-olmadin-senturk-dursun-g16by', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BAĞBANIMA GÜL OLMADIN

Gönül sana sevdalı, tarifsiz bir biçimde

Ben sana bağban oldum, sen bana gül olmadın

Sebepsiz bir sessizlik, çöktü kaldı içimde

Ben sana mızrap oldum, sen bana tel olmadın

Solgun bir resmin ile gözlerimi avuttum

Senden sonra gülmedim senelerce yas tuttum

Gözümde ırmakların sayısını unuttum

Ben sana derya oldum, sen bana göl olmadın

Beyaz bir sayfa açtım, ömrümün defterinde

Sana yer tahsis ettim, en müstesna yerinde

Sönmeyen bir yangınsın gönlümün çemberinde

Ben sana ateş oldum, sen bana kül olmadın

Ayrılığın sızısı sineme vuruyorken

Ben kendi içerimde kendimi arıyorken

Her gün bir Nuh Tufanı, ufkumu sarıyorken

Ben sana liman oldum, sen bana sal olmadın

ŞENTÜRK DURSUN', 'BAĞBANIMA GÜL OLMADIN Gönül sana sevdalı, tarifsiz bir biçimde Ben sana bağban oldum, sen bana gül olmadın Sebepsiz bir sessizlik, çöktü kal...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bagbanima-gul-olmadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milyonda Bir İhtimal', 'milyonda-bir-i-htimal-senturk-dursun-ol76f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MİLYONDA BİR İHTİMAL

İçim dolup taşarken, vuslatın hevesiyle

Yağmurlara karıştı, umutlar yere düştü

Yapraklar ahenk tuttu, ılık rüzgâr sesiyle

Benimse nasibime, fırtına bora düştü

Üstünde yürüyorken, dalgalı bir denizin

Bir çıkış arıyorum, fasıla vermeksizin

Hayalinle yaşadım, yüzünü görmeksizin

Bedenim buz tutarken, yüreğim kora düştü

Yıllarımı doğradım, zamanın hızarında

Sensizlik ölüm demek, gönlümün nazarında

Renklerden deste yaptım, hayatın pazarında

Ruhuma hazan rengi, bahtıma kara düştü

Üflemeyle söner mi, yanan yürek sevdası

Yıllarca aktı durdu, dolmadı çile tası

Vuslatı göstermiyor, hayatın pusulası

Kavuşma ihtimali milyonda bire düştü

Mevsime Eylül yağdı, soldu yeşil duygular

Zihnimde gezer durur, acabalar kuşkular

Ömrümden ömür gitti, gözlerimden uykular

Yorulan bedenimle, yolum ağyara düştü

ŞENTÜRK DURSUN', 'MİLYONDA BİR İHTİMAL İçim dolup taşarken, vuslatın hevesiyle Yağmurlara karıştı, umutlar yere düştü Yapraklar ahenk tuttu, ılık rüzgâr sesiy...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/milyonda-bir-ihtimal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Bizden Çaldılar', 'bizi-bizden-caldilar-senturk-dursun-qgrxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİZİ BİZDEN ÇALDILAR

Soysuzluk sattılar asalet diye

Özü zayıflardan özü çaldılar

Değişti hüviyet değişti künye

Edepten hayadan yüzü çaldılar

Köşe başlar dayılarca tutuldu

Dayısızlar bir kenara atıldı

Arşivimiz kilo ile satıldı

Koca bir milletten mazi çaldılar

Beyaz lekelendi kara uğruna

Manalar harcandı nema uğruna

Çağdaşlık uğruna moda uğruna

Eteğin boyundan bezi çaldılar

Tarih ile bağımızı sökerek

Aramıza fitne fesat sokarak

Sağ sol diye kirli nifak ekerek

İçerki cepheden mevzi çaldılar

Demokrasi falan hep formalite

Yıllardır bitmedi bu mantalite

Meydanlar kalınca çakala ite

Kurdun kursağından kuzu çaldılar

Baş tacıdır utanmazlar arsızlar

Bir gecede holdingleşti varsızlar

Kelli felli kravatlı hırsızlar

Avcıyla anlaşıp tazı çaldılar

Senaryo verildi birkaç gafile

Peşinden koşuştu bütün kafile

Söylesem faydasız yazsam nafile

Bizim mahalleden bizi çaldılar

ŞENTÜRK DURSUN', 'BİZİ BİZDEN ÇALDILAR Soysuzluk sattılar asalet diye Özü zayıflardan özü çaldılar Değişti hüviyet değişti künye Edepten hayadan yüzü çaldılar...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bizi-bizden-caldilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Âdeta', 'deta-tenha-kalem-vcnly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben uzaklaşıyorum.

Ben , ben âdeta kayboluyorum.

Ayaklarıma söz geçiremiyorum,gidiyorlar.

Etraf kararıyor,

Bulanıklaşıyor simalar.

Aklım karışıyor.

Gerçekleri serap sanıyorum,bilemiyorum.

Ben , ben âdeta kayboluyorum kendi yalnızlığım da.', 'Ben uzaklaşıyorum. Ben , ben âdeta kayboluyorum. Ayaklarıma söz geçiremiyorum,gidiyorlar. Etraf kararıyor, Bulanıklaşıyor simalar. Aklım kar...', ARRAY['Türk Edebiyatı','Şiir','Tenha Kalem']::text[], 8.5, '{"poet":"Tenha Kalem","poet_slug":"tenha-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adeta-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim Bir Gün', 'beklerim-bir-gun-fatih-ergin-2-mvlcm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer yolun düşerse bu sokaklara,
Ben buradayım arama uzaklarda,
Yaşaman o güzel günlerin hatırına.
Kapım açık sevdiğim, beklerim bir gün.

Yalnızım diye düşünme sakın.
Söylesene yokmu hiç hatırım.
Başka bir bugün olacak yarın.
Haydi çık gel, beklerim bir gün

Sevda sokağı, numara on altı.
Aşıklar marketinin sağ tarafı.
Gelip bir gün o evin kapısını,
Çalarsan evdeyim, beklerim bir gün.', 'Eğer yolun düşerse bu sokaklara, Ben buradayım arama uzaklarda, Yaşaman o güzel günlerin hatırına. Kapım açık sevdiğim, beklerim bir gün. Ya...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ergin 2']::text[], 8.5, '{"poet":"Fatih Ergin 2","poet_slug":"fatih-ergin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklerim-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Menfaat Dünyası', 'menfaat-dunyasi-senturk-dursun-7r6n5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MENFAAT DÜNYASI

Aklara ak dedik siyaha siyah

Doğruyu söylemek kabahat olmuş

Boynunda kravat zihninde silah

Siyaset teröre aparat olmuş

Yıllar geçti, aynı hamam aynı tas

Cepten yiye yiye tükendi miras

Mantık iflas etti akıllar nadas

Yalanlar dolanlar hakikat olmuş

Hafiften belirse sis bulutları

Fırsatı kaçırmaz Haçlı itleri

Şanlı medyamızın parazitleri

Adeta düşmana avukat olmuş

Her gün bir entrika, her gün bir hile

İftira yağmuru ayrı bir çile

Geçmişle intikam bütün mesele

Entellik dantellik liyakat olmuş

Sosyete tayfanın kokoş sürtüğü

Moda diye sunar donda yırtığı

Emperyal dünyanın modern artığı

Güzelim ülkeme musallat olmuş

Kırk bir türlü, maske takmış surata

Mermi taşır, işbirlikçi zevata

Selam durdu, yirmi sekiz Şubat’a

Şimdi sözüm ona demokrat olmuş

Yanar döner, günü uymaz gününe

Rüzgâr gülü yetişemez yönüne

Kim ne yapsa kâr kalıyor yanına

Kanunlar soysuza barikat olmuş

Ne insana saygı, ne medeniyet

Ne vatan sevgisi, ne aidiyet

İşte dostlar, budur durum vaziyet

Kısacası her şey menfaat olmuş

                    ŞENTÜRK DURSUN', 'MENFAAT DÜNYASI Aklara ak dedik siyaha siyah Doğruyu söylemek kabahat olmuş Boynunda kravat zihninde silah Siyaset teröre aparat olmuş Yılla...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/menfaat-dunyasi-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ortaya Çıkanlar', 'ortaya-cikanlar-senturk-dursun-95bty', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ORTAYA ÇIKANLAR

Asalet tükendi adap bozuldu

Dışı bozuk, içler çıktı ortaya

Namertler mertlere kılavuz oldu

Mert yurdundan, göçler çıktı ortaya

Ortalıkta aydın diye gezenler

Ekranlarda her sorunu çözenler

Kimliğinde Prof diye yazanlar

Koskocaman, hiçler çıktı ortaya

Zapt edildi her bir köşe her mevzi

Düşünceler önyargılı farazi

Haklı haksız ayırmadı terazi

Dörtten büyük üçler çıktı ortaya

Her nimetten fazla fazla pay aldı

Soytarılık yaygınlaştı kök saldı

Gün geçtikçe etek boyu kısaldı

Ar çatladı, kıçlar çıktı ortaya

Yüksek yüksek bina yaptık kat yaptık

Anıt yaptık, heykel yaptık put yaptık

Adalete giden yola set yaptık

Gizli saklı, suçlar çıktı ortaya

Çok bayraklı omurgasız dönekler

Küresel güçlerden icazet bekler

Yiye yiye çatlayacak göbekler

Trilyonluk, açlar çıktı ortaya

Konuşunca her cümlede barış var

İhanette düşmanlarla yarış var

Memleketin aleyhinde her iş var

Entel dantel, piçler çıktı ortaya

Ülke batsa, eksilmiyor heybesi

Sömürdükçe kalınlaşır ensesi

Sabit durmaz, oynar durur kıblesi

İfşa oldu, haçlar çıktı ortaya

Güçlü azat, güçsüz olan sorguda

Tuhaflık var, her yaşanan olguda

Koyun kuzu bir tutamla doydu da

Hiç doymayan KOÇ’lar çıktı ortaya

Senaryolar birbirinin benzeri

Hazır bekler yevmiyeli müşteri

Ne zaman bir adım atsak ileri

Esrarengiz, güçler çıktı ortaya

ŞENTÜRK DURSUN', 'ORTAYA ÇIKANLAR Asalet tükendi adap bozuldu Dışı bozuk, içler çıktı ortaya Namertler mertlere kılavuz oldu Mert yurdundan, göçler çıktı orta...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/ortaya-cikanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-tenha-kalem-6zhvo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazenleri kalbimin atışını duyamadığım zaman

Korkuyorum,belki de yaşamıyorum diyorum kendime.

Ne kadar göğsüme bastırsam da hissedemiyorum.

Korkuyorum,belki de ölüyorum diyorum kendime.

Ama insan ne kadar uğraşsada içindeki o

Yaşama hissi yoksa , zevk vermiyor bu dünya.

Âdeta içi boş bir kitap gibi kalakalıyor.

Okunmayan bir sayfadan ne anlar ki insan?

Gerçi bazen boşluk bile dolu görünür gözüme.

Nede olsa içimdeki kadar derin değil,bu gönlümde.', 'Bazenleri kalbimin atışını duyamadığım zaman Korkuyorum,belki de yaşamıyorum diyorum kendime. Ne kadar göğsüme bastırsam da hissedemiyorum. ...', ARRAY['Türk Edebiyatı','Şiir','Tenha Kalem']::text[], 8.5, '{"poet":"Tenha Kalem","poet_slug":"tenha-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bosluk-528-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Hedef', 'tek-hedef-senturk-dursun-ejy0a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'TEK HEDEF

Yurdun her karışında, şehidimin kanı var

Ayrı gayrı olamaz, batı bizim şark bizim

Sesimizin tonundan, dağlar taşlar şakırdar

Kahraman her ferdimiz, bir orduya denk bizim

Şu alemi yeniden gerek duysak fetihe

Bir anda dönüşürüz, Süleyman’a Fatih’e

Altın harfle yazdırdık, adımızı tarihe

Yedi düvel gelse de, çekincemiz yok bizim

Birgün olsun gitmedik, düzenbazın peşinden

Üşüdük ısınmadık, namerdin ateşinden

Tek lokma koparmadık, ekmeğinden aşından

Çok şükür kirletmedik, kursağımız pak bizim

Yalanda dolanlarda, aramadık devayı

Fırsata çevirmedik, isli puslu havayı

Ne makam ne mevkiye, yeğlemedik davayı

Muzaffer olmak için, sebebimiz çok bizim

Vatan mevzubahisse baldıranlar içeriz

Kaleleri fetheder, surda gedik açarız

Ne bayrağı indirir, ne hilâlden geçeriz

Kızılelma yolunda hedefimiz tek bizim

ŞENTÜRK DURSUN', 'TEK HEDEF Yurdun her karışında, şehidimin kanı var Ayrı gayrı olamaz, batı bizim şark bizim Sesimizin tonundan, dağlar taşlar şakırdar Kahra...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tek-hedef-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüklerim', 'gorduklerim-senturk-dursun-u0gm1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖRDÜKLERİM

Nelere şahitlik etti bu gözler

Melek görünümlü iblisler gördüm

Haçını saklayıp kendini gizler

Hoca kılığında Bizanslar gördüm

Bozuldu terbiye bozuldu ümmet

Küçüğe sevgi yok, büyüğe hürmet

Diploma çöplüğü oldu memleket

Atı tanımayan seyisler gördüm

Emperyalist cephesinde duran var

Mandacılık hayalini kuran var

Barış deyip, ihanete giren var

Dağdan emir alan mebuslar gördüm

Herkes kurtarıcı herkes kahraman

Kimseye bırakmaz, ne din ne iman

Konuşunca hepimizden müslüman

Takkeli cübbeli casuslar gördüm

Dostunu ateşe atan mı dersin

Şanlı tarihine çatan mı dersin

Vatanı bayrağı satan mı dersin

Yazmaktan imtina hususlar gördüm

Üstlerinde bir melanet hırkası

Uzaklardan akıl verir hocası

Açıldıkça gurur duyar kocası

Pazara saçılmış namuslar gördüm

Kimi başrol, kimileri figüran

Direnince boşa çıktı bu plan

Kendi yurttaşına kurşun yağdıran

Üniforma giymiş deyyuslar gördüm

ŞENTÜRK DURSUN', 'GÖRDÜKLERİM Nelere şahitlik etti bu gözler Melek görünümlü iblisler gördüm Haçını saklayıp kendini gizler Hoca kılığında Bizanslar gördüm Bo...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/gorduklerim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar Kazarım', 'yollar-kazarim-eyup-dalkilic-2-clltf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yol biter de ben yollar kazarım, 

Yol bulamam, kendime kızarım; 

Çaresiz hâldeyim, gör hâlimi, 

Suskunluğumla ben şiir yazarım.

Gündüzüm geceye karışır da, 

Sevdaya sağır kalır yârim de; 

Sendeki sessizlik aşktan mıdır? 

Döner durur serap etrafımda.

Kapıldım sanki selin önüne, 

Yüzmek isterim yârin yönüne; 

Düşmüşüm aşkın bir girdabına,

Gölgen etrafında döne döne.

Bende emanet bu can toprağın; 

Gidişin hak mı, aşkımdan kaçtın? 

Yerde, gökte sevdama şahittir, 

Bu aşkı öksüz, yetim bıraktın.

2026', 'Yol biter de ben yollar kazarım,  Yol bulamam, kendime kızarım;  Çaresiz hâldeyim, gör hâlimi,  Suskunluğumla ben şiir yazarım. Gündüzüm gec...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Dalkılıç 2']::text[], 8.5, '{"poet":"Eyüp Dalkılıç 2","poet_slug":"eyup-dalkilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yollar-kazarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilgi', 'yenilgi-senturk-dursun-pexvf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YENİLGİ

Zincir oldu kahpeliğin kuyruğu

Dosttan gelen ihanete yenildim

Böyle aldı ağasından buyruğu

Önyargıya melanete yenildim

Anlayışı hoşgörüyü kaybetti

Niyetinden ikrarından çark etti

İlim irfan izanını terk etti

Diplomalı cehalete yenildim

Milliyetçi faşist diye mimlendi

Bizim tohum el bağında çimlendi

Beyinlerde nefret çayı demlendi

İntikama husumete yenildim

Günü geldi isyan ettim yakındım

Günü geldi zülfü yâre dokundum

Sakıncalı listesinde okundum

Garabete hıyanete yenildim

Düşünmedim aldatmayı hileyi

Yaşasam da yaşatmadım çileyi

İncinsem de incitmedim kimseyi

İçimdeki merhamete yenildim

Kolayca sökülmez derindir köküm

Sırtımda davam var ağırdır yüküm

Namert meclisinde verildi hüküm

Adaletsiz adalete yenildim

ŞENTÜRK DURSUN', 'YENİLGİ Zincir oldu kahpeliğin kuyruğu Dosttan gelen ihanete yenildim Böyle aldı ağasından buyruğu Önyargıya melanete yenildim Anlayışı hoşg...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yenilgi-94-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Günkü Gibi', 'i-lk-gunku-gibi-senturk-dursun-s46hk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İLK GÜNKÜ GİBİ

Bir güzel sevmiştim yıllar öncesi

Dün akşam karşıma çıktı yeniden

Gönlünde çağlarken suların sesi

Beni girdabına çekti yeniden

Sevgi bulutları ufkumu sardı

Bütün mevsimlerim sanki bahardı

Gözünde ilk günkü heyecan vardı

Utangaç gözlerle baktı yeniden

Ruhumu okşarken vuslat türküsü

Tükendi ömrümün tüm üzüntüsü

Günümün dekoru gecemin süsü

Süzüldü içime aktı yeniden

Adını anmaktan kısıldı sesim

Seveni bekliyor gönül adresim

Görünce titredi göğüs kafesim

İçimde şimşekler çaktı yeniden

Geceme ay oldu günüme güneş

Hasretin azabı cehenneme eş

Tekrar alevlendi bağrımda ateş

Küllenen aşkımı yaktı yeniden

ŞENTÜRK DURSUN', 'İLK GÜNKÜ GİBİ Bir güzel sevmiştim yıllar öncesi Dün akşam karşıma çıktı yeniden Gönlünde çağlarken suların sesi Beni girdabına çekti yenide...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ilk-gunku-gibi-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Dediğin', 'omur-dedigin-senturk-dursun-vyqby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖMÜR DEDİĞİN.......

Bir göz açtım kapattım, tükenmiş koca ömür

Saçıma aklar dolmuş, karası belli değil

Aynalara bakınca, içimi hüzün bürür

Bağrım kanar durur da, yarası belli değil

Medet ummak beyhude, ermişten evliyadan

Gerçekle uyanırız, daldığımız rüyadan

Vakit saat dolunca, göç ederiz dünyadan

Yıllarca otursak da, kirası belli değil

Hayatın her evresi, biz doğmadan yazılır

Ne hikmeti bilinir, ne de sırrı çözülür

Kader yolu denilen bir güzergâh çizilir

Ağır ağır gideriz neresi belli değil

Hayat hazanlı bir dal, ömür ise bir yaprak

Vadesi dolanları, alır da vermez toprak

Sabırla bekler bizi, kabir denen son durak

Ne zaman ne saatte, süresi belli değil

İster fakir fukara, ister zengin milyarder

İstisna olmaksızın, gün gelir herkes gider

Uhrevi hayatta da, yolculuk devam eder

Cennet mi cehennem mi, orası belli değil

Esameler kazılır, mermerden tabelaya

Konu komşu merakla, kulak verir selaya

Her kul bir gün mutlaka, can verecek Mevla’ya

Önce genç mi yaşlı mı, sırası belli değil

ŞENTÜRK DURSUN', 'ÖMÜR DEDİĞİN....... Bir göz açtım kapattım, tükenmiş koca ömür Saçıma aklar dolmuş, karası belli değil Aynalara bakınca, içimi hüzün bürür B...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/omur-dedigin-287-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sevgini İsterim', 'ben-sevgini-i-sterim-sairul-i-slam-yunus-kokan-rdzg0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yanda dünya, bir yanda ahiret,

Gönlümde saklı bir güzel hasret.

Ne altın isterim ne de bir servet,

Cemalini lütfet güzel ALLAH''ım!

Bir ömür değil Rabbim, bin ömür verilse de

Ben sevgini isterim cennetler verilse de.

Bir ömür değil Rabbim, bin ömür verilse de

Ben sevgini isterim cennetler verilse de.

Gözümde yaşlar, dilimde dua,

Sensiz bu gönlüm düşer mi huzura?

Bir ömür bekledim ben bu anı,

Cemalini lütfet güzel ALLAH''ım!

Bir ömür değil Rabbim, bin ömür verilse de

Ben sevgini isterim cennetler verilse de.

Bir ömür değil Rabbim, bin ömür verilse de

Ben sevgini isterim cennetler verilse de.', 'Bir yanda dünya, bir yanda ahiret, Gönlümde saklı bir güzel hasret. Ne altın isterim ne de bir servet, Cemalini lütfet güzel ALLAH''ım! Bir ö...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-sevgini-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı şarkı', 'ayni-sarki-fuat-tas-xd6i5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oysa kaderin planı hep başkaydı,

Yan yana getirip kavuşturmadı,

Göz göze getirip bakıştırmadı.

Belki aynı yağmurun altında ıslandık,

Belki aynı şarkının farklı cümlelerinde sustuk.

Sen benim hiç yaşanmamış bir hatıram,

Bense senin hiç bilmediğin bir ihtimaldim.

Seni hatırlamak istediğimde sanki her köşeden sen çıkacak gibiydin.

Şimdi seni unutmaya çalıştığım her köşede sana rastlıyorum.

Bir gün gelir de tamamlarsın diye cümleleri bile yarım bırakıyorum.', 'Oysa kaderin planı hep başkaydı, Yan yana getirip kavuşturmadı, Göz göze getirip bakıştırmadı. Belki aynı yağmurun altında ıslandık, Belki a...', ARRAY['Türk Edebiyatı','Şiir','Fuat Taş']::text[], 8.5, '{"poet":"Fuat Taş","poet_slug":"fuat-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayni-sarki-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılgı', 'yanilgi-senturk-dursun-15qf1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YANILGI

Herkesi zül görür herkesi hakir

Alemi kendinden ibaret sanır

Mal mülkü olsa da özünde fakir

Dünyada her şeyi maddiyat sanır

Yenildi hissine ihtirasına

Kapıldı hırsının fırtınasına

Kibirle bakınca dev aynasına

Sıpalar kendini yağız at sanır

Çıraklık yapmamış ustayı bilmez

Hedefe varacak rotayı bilmez

Müzikten bihaber notayı bilmez

Karganın sesini serenat sanır

Görünmez gözüne ne hayır ne şer

Terketti dostları birer ikişer

Egoya yenildi hergün her sefer

Üç günlük rüyayı saltanat sanır

Gerçek yalanlaştı yalanlar gerçek

Vicdan mizanında yanıldı ölçek

Gururu gündelik kalıbı esnek

Yüzüne tükürsen iltifat sanır

ŞENTÜRK DURSUN', 'YANILGI Herkesi zül görür herkesi hakir Alemi kendinden ibaret sanır Mal mülkü olsa da özünde fakir Dünyada her şeyi maddiyat sanır Yenildi ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yanilgi-275-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Das Kopfschwingen beim Dhikr: Eine medizinische und religiöse Bewertung', 'das-kopfschwingen-beim-dhikr-eine-medizinische-und-religiose-bewertung-muhammed-ridvan-gizri-1ntt1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'In der islamischen Welt haben sich in verschiedenen Derwischorden (Tarikate) und Gemeinschaften einige Formen der Frömmigkeit verbreitet, die im Laufe der Zeit hinterfragt wurden. Eine der auffälligsten dieser Praktiken ist das rhythmische Vor- und Zurückbewegen oder Hin- und Herschwingen des Kopfes während des Dhikr. Im Folgenden wird diese Praxis sowohl medizinisch als auch religiös bewertet. Dabei werden ihre möglichen Auswirkungen auf den menschlichen Körper und ihre Vereinbarkeit mit dem Verständnis des Dhikr im Koran erörtert.

Das Vestibularsystem und die Physiologie des Kopfschwingens

Der Gleichgewichtssinn des Menschen beruht auf flüssigkeitsgefüllten Strukturen im Innenohr, den sogenannten Bogengängen. Bei jeder Kopfbewegung bewegt sich auch die Flüssigkeit in diesen Kanälen (Endolymphe). Diese Bewegung liefert dem Gehirn fortlaufend Informationen darüber, in welche Richtung und mit welcher Geschwindigkeit sich der Kopf dreht. Das System arbeitet mit visuellen Informationen aus den Augen und der Tiefensensibilität (Propriozeption) aus den Muskeln zusammen, um dem Gehirn eine stimmige Karte von Gleichgewicht und Lage zu erstellen. Wird der Kopf etwa zehn Minuten lang kontinuierlich und rhythmisch geschwungen, gerät dieses System stark unter Belastung. Die Flüssigkeit im Innenohr sendet unablässig Bewegungssignale. Bleibt die Person plötzlich stehen, bewegt sich die Flüssigkeit jedoch noch eine Weile weiter. Das Gehirn erhält nun zwei einander widersprechende Signale: Die Augen melden, dass man stillsteht, während das Innenohr weiterhin Bewegung anzeigt. Diese Diskrepanz erzeugt das Gefühl von Schwindel (Vertigo). Ein Kind, das sich im Kreis gedreht hat und nach dem Anhalten taumelnd zu Boden geht, zeigt die Wirkung dieses Mechanismus im Alltag.

Gesundheitliche Risiken längeren und wiederholten Kopfschwingens

Kurze und leichte Kopfbewegungen hinterlassen in der Regel keinen dauerhaften Schaden. Die beim Dhikr beobachtete, lang anhaltende, häufige und rhythmische Gewohnheit des Kopfschwingens kann jedoch mehrere Organe und Systeme negativ beeinflussen.

Auswirkungen auf Nacken und Wirbelsäule: Wiederholte Kopfbewegungen führen zunächst zu Ermüdung und chronischen Schmerzen in der Nackenmuskulatur. Mit der Zeit können Dehnungen der Nackenbänder (Ligamente), eine kumulative mechanische Belastung der Halswirbel und Bandscheiben sowie daraus resultierende Kopfschmerzen auftreten. Besonders bei Menschen mit bestehenden Beschwerden wie einem Bandscheibenvorfall im Halswirbelbereich oder einer Spondylose verlaufen diese Prozesse schneller und schwerer.

Auswirkungen auf Gleichgewicht und Verdauung: Eine übermäßige Reizung des Vestibularsystems beschränkt sich nicht auf Schwindel. Übelkeit, Benommenheit und eine gesteigerte Bewegungsempfindlichkeit gehören ebenfalls zu den häufigen Beschwerden. Besonders Menschen, die zu Reisekrankheit (im Auto oder auf dem Schiff) neigen, können deutlich früher davon betroffen sein.

Auswirkungen auf Augen und Nervensystem: Bei Kopfbewegungen versuchen die Augen, das Bild stabil zu halten. Anhaltendes Schwingen belastet diesen Stabilisierungsmechanismus. Es können unwillkürliches Augenzittern (Nystagmus), Konzentrationsschwierigkeiten und vorübergehend verschwommenes Sehen auftreten. Bei Menschen mit Migräne kann dies Attacken unmittelbar auslösen.

Das gravierendste Risiko, die Halsgefäße: Unter all diesen Auswirkungen ist die Gefährdung der Wirbelarterien (Arteriae vertebrales) besonders bemerkenswert. Diese durch den Halsbereich verlaufenden Gefäße können durch abrupte und heftige Bewegungen geschädigt werden. In der medizinischen Literatur sind Gefäßverletzungen dokumentiert, die mit extremen Halsbewegungen in Verbindung gebracht werden. Dieses Risiko ist daher nicht theoretisch, sondern als belegte Gefahr zu bewerten. Es kann bei Personen mit bestehender Gefäßerkrankung, Nackenproblemen oder fortgeschrittenem Alter deutlich höher sein.

Das Dhikr-Verständnis des Korans: Demut, Bescheidenheit und Maß

Im Koran wird der Begriff des Dhikr als bewusstes, aufrichtiges und tiefgründiges Gedenken an Allah mit gesammeltem Herzen beschrieben. Zwei Verse, die dieses Verständnis unmittelbar widerspiegeln, sind Sure al-A''râf, Vers 55 und 205.

In Sure al-A''râf 55 heißt es: „Ruft euren Herrn demütig und heimlich an; gewiss, Er liebt die Übertreter nicht." Dieser Vers gebietet, den Gottesdienst aufrichtig, bescheiden und maßvoll zu verrichten. Der Ausdruck „die Grenzen überschreiten" bietet einen Maßstab nicht nur für Lautstärke oder zur Schau gestellte Frömmigkeit, sondern für jede Form von Übermaß in der Art der Anbetung.

Sure al-A''râf 205 lautet: „Gedenke deines Herrn in deinem Innern, demütig und in Furcht, ohne laut zu sprechen, am Morgen und am Abend; und gehöre nicht zu den Achtlosen." Auffällig ist, dass das Gedenken aus dem Innern kommen soll, also aus den Tiefen der Seele. Es wird weder zu einer körperlichen Leistung noch zu einer rhythmischen Bewegung aufgefordert. Vielmehr wird zu einer bewussten und tiefgehenden Hinwendung eingeladen.

Zahlreiche Koranverse fordern dazu auf, Allah häufig zu gedenken. Für diesen Auftrag gibt es jedoch keine eindeutige Bestimmung, dass er durch bestimmte rhythmische Körperbewegungen zu erfüllen sei. Das Wesen des Dhikr ist die Hinwendung des Herzens zu Allah. Der Körper kann diese Hinwendung begleiten, doch die körperliche Bewegung selbst kann das Dhikr nicht ersetzen und darf nicht als Dhikr dargestellt werden.

Die Schnittstelle von gesundheitlichem Schaden und religiöser Maßlosigkeit

Das Grundproblem des Kopfschwingens beim Dhikr liegt darin, dass zwei getrennte Einwände einander verstärken. Medizinisch betrachtet überreizt diese Praxis das Vestibularsystem und macht es nahezu unmöglich, dabei eine sinnvolle Gottesdiensterfahrung zu machen. Wer schwindelig ist, Übelkeit verspürt oder die Augen nicht mehr fokussieren kann, wird kaum zu jenem bewussten und tiefen Gedenken an Allah gelangen, das den Kern des Dhikr ausmacht. Die Praxis untergräbt also die seelische Tiefe, die sie anstrebt, durch ihre eigenen physiologischen Folgen.

Religiös betrachtet steht diese körperliche Übertreibung im Widerspruch zu den Prinzipien von Demut, Bescheidenheit und Maß, die der Koran gebietet. Sie wird so zu einer Gewohnheit, die im Namen des Gottesdienstes ausgeübt wird, aber keinen Gottesdienst-Charakter besitzt. Liest man die Warnung „er liebt die Übertreter nicht" aus Sure al-A''râf 55 als breiten Grundsatz, der jede Form von Maßlosigkeit umfasst, sei es im Tonfall, in der Zurschaustellung oder in der Form, wird deutlich, dass das Kopfschwingen diese Grenze überschreitet.

Das Kopfschwingen beim Dhikr verdient sowohl aus medizinischer als auch aus religiöser Perspektive ernsthafte Einwände. Die medizinische Wissenschaft zeigt, dass diese Praxis das Vestibularsystem stört, Nacken und Wirbelsäule belastet, die Halsgefäße gefährdet und sich negativ auf Augen und Nervensystem auswirken kann. Der Koran hingegen gebietet, dass das Dhikr nicht durch äußerlich sichtbare körperliche Leistung, sondern durch innere Ruhe des Herzens, durch Demut und Maß vollzogen wird. Betrachtet man beide Dimensionen gemeinsam, ist das Ergebnis eindeutig: Das Dhikr mit Kopfschwingen ist weder religiös geboten noch gesundheitlich unbedenklich. Das wahre Dhikr, wie der Koran es beschreibt, ist ein Bewusstseinszustand der Stille, der Aufrichtigkeit und der Abwesenheit körperlicher Übertreibung, der aus den Tiefen des Herzens emporsteigt.', 'In der islamischen Welt haben sich in verschiedenen Derwischorden (Tarikate) und Gemeinschaften einige Formen der Frömmigkeit verbreitet, di...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/das-kopfschwingen-beim-dhikr-eine-medizinische-und-religiose-bewertung-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıymetliler', 'kiymetliler-senturk-dursun-k4fsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KIYMETLİLER

Prim yaptı düzenbazlar hırsızlar

Sülükler böcekler kıymete bindi

İtibar kazandı itibarsızlar

Ahmaklar dönekler kıymete bindi

Her olan bitenler dünü aratır

Yazmaya kalkıştım yetmedi satır

Bir günde tükendi kırk yıllık hatır

Kaskatı yürekler kıymete bindi

Terazi doğruyu tartmıyor artık

Adalet tecelli etmiyor artık

Hiç bir iş yolunda gitmiyor artık

Zekâsı seyrekler kıymete bindi

Çok anlam yükledik makam mevkiye

Kir pas bulaştırdık her ilişkiye

Horozlar nişane taktı tilkiye

Çakallar köpekler kıymete bindi

Aslan yatağında sırtlan yatıyor

Kartal yuvasında karga ötüyor

Fareler kediye caka satıyor

Haylazlar zevzekler kıymete bindi

Her yerde kurulu bir kahpe tazak

Kimine çok yakın kimine uzak

Kaypağa kancığa açıldı kucak

Çürükler kelekler kıymete bindi

ŞENTÜRK DURSUN', 'KIYMETLİLER Prim yaptı düzenbazlar hırsızlar Sülükler böcekler kıymete bindi İtibar kazandı itibarsızlar Ahmaklar dönekler kıymete bindi Her...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kiymetliler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevdim "toprak kokan şiirler "', 'gizli-sevdim-toprak-kokan-siirler-nevzat-i-ncedere-uoqkp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gizli, gizli sevdim ben seni ya

Söyleyemedim kendime bile

Her gün dert ekledim derdime

Gönlümde sakladım seni sır gibi

Varlığı cennet yokluğu azapmış ya 

Direndim sınır bilmez bu gönlüme

Söz de dinlemez vursam zincirlere

Hasretinle yandım mecnun misali

Bana yanlış zaman yanlış mekan de

Kaderde yanlış olan, doğru da sende

Sabret deme unutursun bir gün elbet

Mahşere sevdim unutmam ölsem de

Vazgeç sevmekten bizden olmaz deme

Aşk cesaret ister hadi gitme gel sende

Yanlışsa da bu sevda bırak öylece kalsın

Bırak susmaktansa bırak canım yansın

Aşk ne zaman dinler ne mesafe ne kader

Senden öte yar mı sever ne de  vazgeçer

Vazgeç deme sakın seninle olmaz deme

Aşk cesaret ister ya hadi gitme sev sende', 'Gizli, gizli sevdim ben seni ya Söyleyemedim kendime bile Her gün dert ekledim derdime Gönlümde sakladım seni sır gibi Varlığı cennet yokluğ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat İncedere']::text[], 8.5, '{"poet":"Nevzat İncedere","poet_slug":"nevzat-i-ncedere","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gizli-sevdim-toprak-kokan-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah o eski anılar', 'ah-o-eski-anilar-mustafa-ceker-lyurr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah o eski anılar 

Kapısını araladım yine, yılların tozunu silerek 

İçerde duruyor hala o kokun 

Yağmur, un ıslattığı saçların 

Senin gülüşüne karışmış o çayın..... Offffff offff 

Zaman ne kadar acımasızmış 

Her şeyi alıp götürmüş ama 

Kokunu, sesini, o bakışını, bir köşede saklamış 

Ah o eski anılar 

Bir park bantında oturmuştuk 

Akşamın son ışığı anlına düşerken 

Konuşmuyorduk bile, sessizlik yetiyordu ikimizede 

Şimdi o bank hala orada mı 

Yoksa çoktan söküldümü bilmiyorum 

Ama o anı, o sessizliği 

Hala kalbimin en derininde titreyerek duruyor 

Ah o eski anılar 

Bir mektup vardı 

Kağıdı sararmış köşeleri kıvrılmış 

Sadece.. seni özledim yazıyordu 

O kadar..... Başka hiç bir şey yoktu 

Ama o üç kelime 

Bütün bir ömürden daha ağırdı 

Şimdi o mektubu okuyamıyorum 

Çünkü gözlerim yaşarıyor 

Ve harfler bulanıklaşıyor 

Ah o eski anılar 

Hatırlıyorum da evinizin bahçesinde 

Gecenin kör karanlığında buluşmalarımızı

Ellerin elime değmeden 

Sadece bakışarak ne kadar çok mutlu olmalarımızı

Yinede....o anılar bırakmıyor 

Sanki.. bir ip gibi, boğazıma dolanıyor 

Ama aynı zamanda kalbimede iyi geliyor 

Ah o eski anılar 

Ne kadar acıtırsanız acıtın 

Sizsiz bir hayat daha da acı olurdu 

O yüzden siz hep gelin,gelin yine buraya 

Bu yanlızlığıma,bu bomboş odalara 

Ben sizi hep bekliyorum 

Çünkü siz olmadan,ne dün vardı,nede yarın 

Ah o eski anılar ahhhhh

Siz benim en güzel yaramsınız......', 'Ah o eski anılar  Kapısını araladım yine, yılların tozunu silerek  İçerde duruyor hala o kokun  Yağmur, un ıslattığı saçların  Senin gülüşün...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çeker']::text[], 8.5, '{"poet":"Mustafa Çeker","poet_slug":"mustafa-ceker","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ah-o-eski-anilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen.', 'sen-senturk-dursun-69z5e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SEN.......

Kış olsa da takvimdeki yapraklar

Sen dört mevsim gönlümdeki baharsın

Her saniye seni anar dudaklar

Hayatımın her anında sen varsın

Yaşadığım gönül yurdum meskenim

Tende canım, canda varlık nedenim

Çöllerdeki serabımsın sen benim

Kana kana su içtiğim pınarsın

Yaren oldun, benliğimde özümde

Şiir oldun, kelamımda sözümde

Şarkı oldun, türkü oldun sazımda

Kimi neşe, kimi zaman efkârsın

Tan ağarıp geceleri boğarken

Nur cemalin güneş olup doğarken

Gökyüzünden kor alevler yağarken

Gölgesine sığındığım çınarsın

Herkeslerden sakladığım nihanım

Yolumdaki hem kervansın hem han’ım

Seni yazsam eksik kalır her tanım

Gönülleri gönül yapan mimarsın....

ŞENTÜRK DURSUN', 'SEN....... Kış olsa da takvimdeki yapraklar Sen dört mevsim gönlümdeki baharsın Her saniye seni anar dudaklar Hayatımın her anında sen varsı...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-4581-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Dur', 'uzak-dur-senturk-dursun-q747e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'UZAK DUR

Aç kalsan da, haram sokma kursağa

Yetim malı yiyenlerden uzak dur

Sakın kanma kıyafete kılığa

Puşt hırkası giyenlerden uzak dur

Sen değişme değişse de adresin

Kırılmasın ümitlerin hevesin

Kahpelerce kısılmasın gür sesin

Sülüklerden çıyanlardan uzak dur

Unutma ki, baki değil bu hayat

Menfaatten önde gelir sadakat

Vicdanını terk etmesin hakikat

Memleketi soyanlardan uzak dur

Tebessümü esirgeme yüzünden

Haysiyeti mahrum etme özünden

Dost gönüller incinmesin sözünden

Kalp kırıcı beyanlardan uzak dur

Yüze gülüp riyakârlık yapandan

Ecdadından geçmişinden kopandan

Her kavşakta sağa sola sapandan

Her kalıba uyanlardan uzak dur

Üzgün durup sevindirme hasmını

Kızgın olup gücendirme hısmını

Çıkar için lekeleme ismini

Ağam paşam diyenlerden uzak dur

Her yoldan şaşsan da, Hak yoldan şaşma

Her şeyi aşsan da, haddini aşma

Yılışığa sünepeye yanaşma

Güce boyun eğenlerden uzak dur

El bilmesin, dostla paylaş tasanı

Kinle değil, gülle donat masanı

Önemseme, duyma ahkâm keseni

Boş nasihat sayanlardan uzak dur

ŞENTÜRK DURSUN', 'UZAK DUR Aç kalsan da, haram sokma kursağa Yetim malı yiyenlerden uzak dur Sakın kanma kıyafete kılığa Puşt hırkası giyenlerden uzak dur Sen...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/uzak-dur-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sığmadın', 'sigmadin-senturk-dursun-xws44', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SIĞMADIN

Bugün yine seni yazmak istedim

Cümlelere hecelere sığmadın

Nice methiyeler dizmek istedim

Lisanlara lehçelere sığmadın

Seni görüyorum her bakışımda

Tek sen varsın baharımda kışımda

Çok istedim görmek için düşümde

Rüyalara gecelere sığmadın

Nice yıldır yollarını bekledim

Yokluğunda hayalini kokladım

Anıları ilk gün gibi sakladım

Gönlümdeki müzelere sığmadın

Sen gideli yanmaz oldu meşalem

Ufkumda küçüldü şu koca alem

Çok şey yazacaktım yetmedi kalem

Satırlara dizelere sığmadın

Bağımda gülümsün dağımda yelim

Büsbütün bedenim ayağım elim

Aşk sazını inletirken bam telim

Şarkılara nağmelere sığmadın

ŞENTÜRK DURSUN', 'SIĞMADIN Bugün yine seni yazmak istedim Cümlelere hecelere sığmadın Nice methiyeler dizmek istedim Lisanlara lehçelere sığmadın Seni görüyor...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sigmadin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tercih', 'tercih-senturk-dursun-oz30e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'TERCİH

"Ya istiklal ya ölüm" budur bizde parola

Esaretlik yerine, vurulmayı yeğledik

Bu azimle yürüdük, her hedefe her yola

Canımız pahasına var olmayı yeğledik

Sağa sola savrulmaz, zikzaksızdır izimiz

Bugün ne söylediysek, yarın odur sözümüz

Değişmedi değişmez, duruşumuz tarzımız

Bedeline katlandık, hür olmayı yeğledik

Allah Allah nidası yükselirken sineden

Gerekirse ölürüz, sormayız niçin neden

Alp yüreğe siperdir, çelikten kaplı beden

Eğilip bükülmedik kırılmayı yeğledik

Adalet cephesinde siper aldık en başta

Hak galip gelecektir, batıl ile savaşta

Cesaret yürektedir, ne cüssede ne yaşta

Kolayına kaçmadık, zor olmayı yeğledik

Çağ açtı çağ kapattı, kılıcımız süngümüz

O gün bugün bitmedi, Haçlılarla cengimiz

Ayrı ayrı olsa da, kimliğimiz rengimiz

Al bayrağın altında bir olmayı yeğledik

ŞENTÜRK DURSUN', 'TERCİH "Ya istiklal ya ölüm" budur bizde parola Esaretlik yerine, vurulmayı yeğledik Bu azimle yürüdük, her hedefe her yola Canımız pahasına...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tercih-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önemli', 'onemli-ayhan-maloglu-2-5q8j1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayatım boyunca..

Göz göze geldiğim..

Gözlerime bakan..

Onca insanlar oldu..

Hangisi.. 

Gözlerimin ardında ki..

Beni gördü..

Kirpiklerim arasında..

Gizlediğim..

Gözyaşlarımı..

Kaçı..

Bakışlarıyla..

Kalbime inip..

Yüreğimi görebildi..

Kim..

Tebessümlerimdeki..

Burukluğumu görüp..

Nedenini sordu..

Öğrenmek istedi..

Göz göze.. 

Bakışmak değil..

Aynı istikamete.. 

Bakmak.. 

Sevdiğini..

Söylemek değil..

İnsanın..

İnsanı.. 

Okuması..

Anlaması..

Ruhunu sarması..

Önemli..

Ayhan M.', 'Hayatım boyunca.. Göz göze geldiğim.. Gözlerime bakan.. Onca insanlar oldu.. Hangisi..  Gözlerimin ardında ki.. Beni gördü.. Kirpiklerim ara...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Maloglu 2']::text[], 8.5, '{"poet":"Ayhan Maloglu 2","poet_slug":"ayhan-maloglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/onemli-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dusak pembesi', 'dusak-pembesi-daglar-ozuguc-ep0pa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıldızların gökyüzüne yakıştığı 

O büyülü akşamdan başlayarak 

sevdim seni 

Yosun kokulu bir eylül akşamında

Görkemli manzaraya karşı 

Yaprakları sarıya boyarken

Gördüm gözlerini hatırladın mı?

Endişeli bir ceylanın bakışları kadar ürkek

Tomurcuğundan yeni kurtulmuş gülün

 Dudak pembesi ile kan kırmızısı

 Arasındaki  o davetkar görüntüsü

İçimdeki kızıl şafağı erken uyandırmıştı

Sevgiye feda edilen ihtirasların bakiyesi

Yazık ki o günlerde hesap edilmemişti

Her şeyi bu güne topladık;ama ben yorgunum

Artık otur dinlen ey gönül 

Bekleyecek seni o dudak pembesi biliyorum', 'Yıldızların gökyüzüne yakıştığı  O büyülü akşamdan başlayarak  sevdim seni  Yosun kokulu bir eylül akşamında Görkemli manzaraya karşı  Yapra...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dusak-pembesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kıskandı2', 'seni-kiskandi2-senturk-dursun-7hyih', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SENİ KISKANDI

Seninle içtim ben aşk badesini

Kadehler şaraplar seni kıskandı

Yazarken sevdanın hikâyesini

Kalemler  kitaplar seni kıskandı

Bu nasıl sevda ki, yakar kavurur

Yaktığı ateşten küller savurur

Fecire vurunca yüzündeki nur

Yıldızlar mehtaplar seni kıskandı

Cananın hasreti sarınca canı

Yağmurlar neylesin aşkla yananı

Kırık bir sandalla geçtim ummanı

Denizler girdaplar seni kıskandı

Gonca oldun, çiçek oldun dallarda

Şiir oldun gönüllerde dillerde

Şarkı oldun hüzün kokan tellerde

Notalar mızraplar seni kıskandı

Aşk şair eyledi şiirler yazdım

Cümle sıraladım heceler dizdim

Diyarlar dolaştım çöllerde gezdim

Sahralar seraplar seni kıskandı

ŞENTÜRK DURSUN', 'SENİ KISKANDI Seninle içtim ben aşk badesini Kadehler şaraplar seni kıskandı Yazarken sevdanın hikâyesini Kalemler  kitaplar seni kıskandı B...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/seni-kiskandi2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muradım olmadı', 'muradim-olmadi-daglar-ozuguc-vh4c7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Allahtan sevginin  gerçek sınırları

Kelebeğin ömrüne göre  ayarlanmadı

Onun havada  her kanat çırpışı 

Özgür akla varoluşu müjdeledi

Kelebeğin ciğerlerindeki körpe nefes

Hasret çekenlerin cesareti oldu

Mumu eriten yüreğine saplanmış ipti

Kandilden damlayan her ışık huzmesi

Yeşerecek sevgilere can damlası 

Ayrılıklara vede busesi oldu

Şiir divandan geri dönmemek üzere

Başka iklimlere çekti gitti

Muradı gözümüzde bırakarak', 'Allahtan sevginin  gerçek sınırları Kelebeğin ömrüne göre  ayarlanmadı Onun havada  her kanat çırpışı  Özgür akla varoluşu müjdeledi Kelebeğ...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muradim-olmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemek', 'beklemek-senturk-dursun-wze9n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEKLEMEK

Gel artık sevdiğim dindir acımı

Gözde yaşlar dönüşünü bekliyor

Cemalinle süsle gönül tacımı

Tatlı düşler dönüşünü bekliyor

Bakındığım her resimde sen varsın

Soluduğum nefesimde sen varsın

Yaşadığım dört mevsimde sen varsın

Yazlar kışlar dönüşünü bekliyor

Sabaha dönmüyor gecenin yüzü

Güneş battı terkeyledi gündüzü

Mavi renge küstü artık gökyüzü

Uçan kuşlar dönüşünü bekliyor

Denizlere ırmaklara dal da gel

Gönüllere yüreklere dol da gel

İster yağmur ister bulut ol da gel

Dağlar taşlar dönüşünü bekliyor

ŞENTÜRK DURSUN', 'BEKLEMEK Gel artık sevdiğim dindir acımı Gözde yaşlar dönüşünü bekliyor Cemalinle süsle gönül tacımı Tatlı düşler dönüşünü bekliyor Bakındığ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beklemek-614-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HABERSİZ GİDİŞİN', 'habersi-z-gi-di-si-n-senturk-dursun-bpyv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HABERSİZ GİDİŞİN

Eller gibi uzaklardan

Bakıp gittin habersizce

Boz bulanık ırmaklardan

Akıp gittin habersizce

Yar eyledin kahırları

Dar eyledin şehirleri

Mektupları  şiirleri

Yakıp gittin habersizce

Gönlümüzün akitini

Gözümüzün yapıtını

Aşkımızın anıtını

Yıkıp gittin habersizce

Reva gördün çileleri

Düşünmedin hayır şeri

Sevda adlı bir hançeri

Sokup gittin habersizce

Hayalimde sendin her an

Sen gideli gönül viran

Gözlerine doyamadan

Çekip gittin habersizce

Rüzgârımı yelkenimden

Yıldızımı evrenimden

Yüreğimi bedenimden

Söküp gittin habersizce

ŞENTÜRK DURSUN', 'HABERSİZ GİDİŞİN Eller gibi uzaklardan Bakıp gittin habersizce Boz bulanık ırmaklardan Akıp gittin habersizce Yar eyledin kahırları Dar eyle...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/habersiz-gidisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Die Diskurs-spirale nach der Prüfung: Eine psychologische, ethische und gesellschaftliche Analyse', 'die-diskurs-spirale-nach-der-prufung-eine-psychologische-ethische-und-gesellschaftliche-analyse-muhammed-ridvan-gizri-tiryr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'In der Türkei durchlaufen jedes Jahr Millionen von Schülerinnen und Schülern zahlreiche entscheidende Prüfungen, von den Aufnahmeprüfungen für die weiterführende Schule über die Hochschulzugangsprüfung bis hin zu den Auswahlverfahren für Lehrkräfte und den öffentlichen Dienst. Diese Prüfungen sind Wendepunkte, die die Lebensbahnen der Einzelnen unmittelbar beeinflussen. Bemerkenswert ist jedoch, dass der nach der Prüfung produzierte Diskurs oft ebenso, mitunter sogar mehr Gewicht hat als die Prüfung selbst. Der erste Satz, den ein Prüfling nach dem Verlassen des Prüfungsraums äußert, breitet sich wie die Kreise aus, die ein in den Teich geworfener Stein erzeugt: Er erreicht Freundinnen und Freunde, Familie, Lehrkräfte, soziale Medien, Fachleute und institutionelle Stellungnahmen. Dieser Prozess der Verbreitung bildet die Wirklichkeit selten ab, vielmehr konstruiert er sie. Und die so konstruierte Wirklichkeit beeinflusst die Psychologie, die moralische Haltung und das gesellschaftliche Vertrauen von Millionen von Menschen unmittelbar.

Die Anatomie der Diskurs-Spirale: Wie sie beginnt und wie sie sich ausbreitet

Die erste Stimme: Der Diskurs beim Verlassen der Prüfung

Nach jeder Prüfung wiederholt sich ein Muster. Die Prüflinge verlassen den Saal und fällen Urteile über die Prüfung, noch bevor objektive Daten vorliegen. Die überwiegende Mehrheit dieser Urteile fällt negativ aus: „Das war sehr schwer“, „Ich hatte mit solchen Fragen überhaupt nicht gerechnet“, „Es war ganz anders.“ Zu beachten ist zunächst, dass diese Einschätzungen auf der individuellen Erfahrung beruhen. Doch bereits nach kurzer Zeit werden sie aus einem persönlichen Eindruck zu einer scheinbar kollektiven Wahrheit. Der Grund dafür liegt in der Art, wie der menschliche Geist in Situationen der Unsicherheit arbeitet.

Psychologischer Nährboden: Soziale Beeinflussung und Herdenpsychologie

Die Psychologie belegt seit Langem, dass Menschen in Situationen der Ungewissheit das Verhalten und die Urteile anderer als Bezugspunkt heranziehen. Dieses Phänomen wird als soziale Beeinflussung bezeichnet und nimmt, besonders wenn eine Gruppe geschlossen in dieselbe Richtung handelt, die Form von Herdenpsychologie oder Gruppeneffekt an. Die Zeit direkt nach der Prüfung ist ein Umfeld, in dem dieser Mechanismus nahezu unter Laborbedingungen wirkt. Die Unsicherheit der Prüflinge über ihre eigene Leistung ist hoch: Die Prüfung ist vorbei, unumkehrbar, und das Ergebnis ist unbekannt. Diese Ungewissheit steigert das Bedürfnis nach den Deutungen anderer dramatisch. Wenn ein oder zwei Prüflinge laut sagen „Es war echt schwer“, weckt das bei einem Prüfling, der sich über seinen eigenen Stand nicht im Klaren ist, rasch Zweifel: „Bin ich vielleicht auch auf eine schwere Prüfung gestoßen, ohne es zu merken, und habe einiges übersehen?“ Mit dieser Frage setzt ein rückwirkender Neubewertungsprozess ein, den man in der Psychologie als retrospektive Verzerrung bezeichnen kann. Die Person kann ihre ursprüngliche, im Prüfungsmoment gewonnene Wahrnehmung nicht bewahren und fügt sich zunehmend dem wachsenden kollektiven Urteil ein. Bald sagt sie selbst, die Prüfung sei schwer gewesen. Der Stein ist ins Wasser gefallen, die Kreise werden größer.

Kettenhafte Ausbreitung: Vom Prüfling über den Fachmann zur Institution

Der Diskurs bleibt nicht unter den Prüflingen. Den nächsten Kreis bilden die Lehrkräfte. Eine Lehrkraft, die sieht, dass die große Mehrheit ihrer Schülerinnen und Schüler dasselbe Urteil teilt, nimmt dies als statistische Tatsache wahr. Doch das Wissen, über das sie verfügt, ist nicht einmal eine repräsentative Stichprobe; es handelt sich lediglich um jene, die in einem bestimmten Umfeld und in einer bestimmten Stimmung ihre Stimme erhoben haben. Auf die Lehrkräfte folgen Medien und „Experten“. An dieser Stelle greift ein interessanter sozialer Mechanismus: Unter dem Druck, Stellung nehmen zu müssen, stützen sich Expertinnen und Experten nicht auf konkrete Daten, sondern auf die bereits entstandene allgemeine Stimmung. Jedes Jahr wird die Prüfung als schwer bezeichnet, und die Stellungnahmen werden zu Wiederholungen voneinander. Die Institutionen bilden schließlich das letzte Glied in diesem Echoraum. So erlangt ein Satz, den einige wenige Prüflinge beim Verlassen des Saales formuliert haben, mit der Zeit den Status einer offiziell anerkannten Wahrheit und zirkuliert als solche weiter.

Konfrontation mit der Wirklichkeit: Was geschieht, wenn die Ergebnisse veröffentlicht werden?

Kollision von Wahrnehmung und Daten

Wenn die Ergebnisse veröffentlicht werden, zeigt sich ein Paradox. Die Verteilung der Punkte, die Nettodurchschnitte, die Standardabweichungen, also die konkreten Daten, bestätigen die konstruierte Wahrnehmung einer „extrem schweren Prüfung“ nicht. Prüflinge, die ihre Erwartungen auf diese Wahrnehmung ausgerichtet haben, sind psychologisch auf einem unrealistischen Fundament aufgebaut und zugleich von den Ergebnissen überrascht. Dieser Widerspruch erschüttert das geistige Gleichgewicht erheblich. Dass eine gemeinsam angenommene Erzählung sich als falsch erweist, lässt sich nur schwer akzeptieren, denn dann müssten die Betroffenen entweder eingestehen, sich zusammen mit der Masse geirrt zu haben, oder die Schuld nach außen verlagern.

Die Externalisierung der Schuld: Der Beginn der Verleumdungsspirale

Die menschliche Psyche neigt dazu, eigene Irrtümer nicht einzugestehen, sondern die Schuld nach außen zu verlagern. Diese Tendenz zeigt sich nach Prüfungen besonders deutlich. Bei Prüflingen mit hohen Punktzahlen oder den Besten des Jahrgangs verbreiten sich rasch Vorwürfe wie „Er kannte die Fragen im Voraus“, „Er hat sich durch Vetternwirtschaft durchgesetzt“ oder „Er hat betrogen.“ Für keine dieser Anschuldigungen gibt es eine belastbare Grundlage. Es wird nicht nach Beweisen gesucht, es besteht kein Bedürfnis danach. Hohe Leistung gilt als ausreichender Grund für den Verdacht. Das ist nicht nur ungerecht, sondern eine äußerst schwere gesellschaftliche Gewalt, die die Würde der Klassenbesten, den Ruf ihrer Familien und ihre Mühen zerstört.

Moralische und religiöse Dimension: Zann, Verleumdung und geteilte Verantwortung

Zann: Unwissen in verkleideter Form

Eines der grundlegendsten Prinzipien der islamischen Ethik besagt, dass ein Urteil ohne Beweise, das sogenannte Zann, ein moralischer Fehler ist. Der Koran warnt in Sure al-Hujurāt, Vers 12, unmissverständlich: „Ihr Gläubigen! Meidet viele Vermutungen! Denn manche Vermutung ist Sünde.“ Betrachtet man den Diskurs nach der Prüfung unter diesem Gesichtspunkt, zeigt sich, dass er nahezu vollständig auf Zann aufgebaut ist. Die Schwierigkeit der Prüfung ist Zann, denn sie lässt sich ohne veröffentlichte Daten nicht wissen. Die Leistung der anderen Prüflinge ist Zann, denn niemand hat die Antwortbögen anderer gesehen. Spekulationen über die Redlichkeit der Jahrgangsbesten bewegen sich schließlich an der Grenze von Zann und Verleumdung.

Verleumdung: Vom individuellen Vergehen zur kollektiven Verantwortung

Eine unbegründete Anschuldigung wird im islamischen Recht und in der Ethik unter dem Begriff Qadhf (Verleumdung) behandelt und zieht sehr schwerwiegende Folgen nach sich. Hier geht es jedoch vor allem um die kollektive Dimension. In der heutigen Kommunikationsumgebung bleibt eine Verleumdung nicht bei einer einzelnen Person. Einen Beitrag in sozialen Medien zu liken, einen Klatsch weiterzugeben oder „Was, wenn es stimmt?“ zu fragen, bedeutet bereits, dem Glied der Verleumdungskette ein weiteres hinzuzufügen. Die Sure az-Zalzala, Vers 8, zieht an diesem Punkt eine äußerst scharfe ethische Grenze: „Und wer auch nur das Gewicht eines Stäubchens an Böses getan hat, wird es sehen.“ Einen mit Mühe erreichten Erfolg eines Schülers ohne Belege zu verdunkeln, ist ein großes Unrecht. Und die Tausenden, die diesen Vorwurf in sozialen Medien verbreiten? Jeder von ihnen ist, sei es auch nur im Maß eines Stäubchens, Teilhaber an dieser Sünde. Die Verteidigung „Ich habe es nur weitergeleitet“ oder „Alle haben das gesagt“ befreit nicht von moralischer Verantwortung.

Mitschuld am Unrecht anderer

Eine der tragischsten Dimensionen der Diskurs-Spirale besteht darin, dass viele der Beteiligten, ohne es zu bemerken, an der Sünde anderer teilhaben. Die Kette verläuft so: Der erste Prüfling spricht, der zweite wiederholt es, die Lehrkraft gibt weiter, was sie gehört hat, der Experte folgt der allgemeinen Stimmung, die Institution gibt eine Erklärung ab, die Medien verbreiten sie, und die Gesellschaft verkündet ihr Urteil. Jedes Glied dieser Kette trägt Verantwortung, doch niemand sieht die eigene, weil jeder glaubt, lediglich das Gehörte weitergegeben zu haben.

Psychologische Verwüstung: Der Preis für den Einzelnen

Falsch gerahmte Erwartungen und Enttäuschung

Die nach der Prüfung künstlich erzeugte Erzählung von der „Schwierigkeit“ lenkt die Erwartungen der Prüflinge auf einen unrealistischen Boden. Wer mit der Annahme „Alle hatten Schwierigkeiten, die Prüfung war sehr schwer, die Durchschnittspunktzahlen werden niedrig sein“ auf das Ergebnis wartet, weiß nicht, wie er reagieren soll, wenn das tatsächliche Bild davon abweicht. Seine Erwartung ist entweder zu hoch oder zu niedrig. In beiden Fällen liegt eine psychische Vorbereitung vor, die nicht mit der Wirklichkeit übereinstimmt.

Das Gefühl fehlender Kontrolle und die Erosion des Vertrauens

Die nach den Ergebnissen verbreiteten Behauptungen über Vetternwirtschaft und Betrug untergraben das Vertrauen junger Menschen in das System nachhaltig. Sobald sich die Überzeugung festgesetzt hat, dass es ohnehin keinen Unterschied macht, ob man ehrlich ist, weil derjenige mit Beziehungen gewinnt, werden Arbeitsmotivation und Vertrauen in die Institutionen ernsthaft beschädigt. Dies ist nicht nur ein individuelles psychisches Problem, sondern eine strukturelle Krise, die auf die Erosion des gesellschaftlichen Kapitals hinausläuft.

Der erfolgreiche Prüfling: Nicht belohnt, sondern zermürbt

Den größten Schaden nimmt paradoxerweise gerade die Gruppe der erfolgreichsten Schülerinnen und Schüler. Ein junger Mensch, der jahrelang gearbeitet hat und in der Prüfung weit vorne liegt, wird statt mit Glückwünschen mit Misstrauen empfangen. Seine Familie wird belastet, sein Umfeld beginnt, Fragen zu stellen. Diese Erfahrung führt dazu, dass hohe Leistung, die eine gesellschaftliche Belohnung sein sollte, zur Last wird. Wenn eine Gesellschaft ihre begabten Mitglieder auf diese Weise empfängt, bereitet sie langfristig den Boden für Brain Drain und Motivationsverlust.

Lösung: Ein Geist, der auf Daten wartet, und eine Sprache, die zu schweigen weiß

Auf individueller Ebene: Epistemische Geduld

Die grundlegendste Lösung besteht darin, dass der Einzelne die Fähigkeit entwickelt, „Ich weiß es nicht“ zu sagen. Unmittelbar nach der Prüfung fehlen die Informationen, um endgültige Urteile zu fällen. Die eigene Leistung zu übertreiben oder herunterzuspielen und die Leistung anderer zu erraten, ist in dieser Phase ein erkenntnistheoretischer Fehler. Eine gesunde Haltung sieht so aus: Bis die offiziellen Ergebnisse vorliegen, auf endgültige Urteile verzichten, die eigene Erfahrung ohne Übertreibung schildern und sich von Spekulationen über andere fernhalten.

Auf institutioneller Ebene: Professionalität statt Populismus

Wenn Expertinnen, Experten und Institutionen die allgemeine Stimmung nach der Prüfung aufgreifen und populistische Erklärungen abgeben, ist das ein berufliches Versäumnis. Echte Fachkompetenz besteht nicht darin, die Erwartungen der Menge zu bestätigen, sondern geduldig auf die Daten zu warten und sie, wenn sie vorliegen, richtig zu interpretieren. Dass Institutionen statt jährlich dieselben Deutungen Wort für Wort zu wiederholen zu echter Analyse übergehen, ist für den Wiederaufbau des gesellschaftlichen Vertrauens unerlässlich.

Auf gesellschaftlicher Ebene: Die Tugend, Leistung nicht zu beschmutzen

Als Gesellschaft brauchen wir am dringendsten die Gewohnheit zurück, Leistung mit Respekt statt mit Misstrauen zu begegnen. Eine grundlose Anschuldigung zerstört das Vertrauensgefüge einer Gesellschaft. Den Erfolg eines anderen zu hinterfragen, statt sich mit ihm zu freuen, ist eine individuelle moralische Schwäche und zugleich Symptom einer gesellschaftlichen Krankheit. Es genügt, sich an die Warnung der Sure az-Zalzala zu erinnern: Jedes ungerechte Wort, auch das kleinste, und jede haltlose Behauptung wird zur Rechenschaft gezogen.

Die Diskurs-Spirale nach der Prüfung mag auf den ersten Blick wie eine harmlose soziale Gepflogenheit erscheinen. In der hier untersuchten Form ist dieser Prozess jedoch ein komplexes Phänomen, in dem psychologische Verzerrung, moralische Verantwortungslosigkeit und die Erosion des gesellschaftlichen Vertrauens ineinandergreifen. Der erste Satz, den ein Prüfling beim Verlassen des Saales spricht, stößt einen Dominostein an. Jedes folgende Glied, Lehrkraft, Experte, Institution, Medien und Nutzerinnen und Nutzer sozialer Medien, verstärkt diesen Dominoeffekt. Das Ergebnis spiegelt weder die Wirklichkeit wider, noch wird ihm Gerechtigkeit zuteil.

Die Lösung erfordert eine kognitive, eine moralische und eine institutionelle Wende zugleich. Einzelne müssen wieder lernen, „Ich weiß es nicht“ zu sagen, Institutionen sollten ohne Daten nicht sprechen, und die Gesellschaft muss wieder Achtung vor der Mühe anderer entwickeln.

Der Grundsatz „Meidet viele Vermutungen“ ist nicht nur ein religiöses Gebot, sondern zugleich eine unverzichtbare epistemische Tugend für den Aufbau einer gesunden Gesellschaft. Die Prüfung endet, doch das gesprochene Wort, der geworfene Stein und die verbreitete Vermutung hinterlassen weiterhin Spuren in Köpfen und Gewissen. Deshalb ist es das Richtige, sowohl den Geist als auch die Sprache so lange brachliegen zu lassen, bis die Daten vorliegen.', 'In der Türkei durchlaufen jedes Jahr Millionen von Schülerinnen und Schülern zahlreiche entscheidende Prüfungen, von den Aufnahmeprüfungen f...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/die-diskurs-spirale-nach-der-prufung-eine-psychologische-ethische-und-gesellschaftliche-analyse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercin gülüşü', 'guvercin-gulusu-daglar-ozuguc-x4qgx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk acısının özü biçimsiz bir işkence

Ölüm kurtuluşken 

Aşk acısı sürekli bir düşünce

Hukuka uygun bir ceza değil

O bir gönül kırım hem de zalimce

Astılar sevenleri aşk mabedinde

Nereye gitsen zebanileri seninle

Bekliyorlar işkence mahzenlerinde

Bir suçun cezası çekilir bir kere 

Aşk acısının gazabı kalır hayallerde

Bir güvercin gülüşünün değeri

Bir dal defne yaprağının ömrüne

Bağlanan umuda eşdeğer', 'Aşk acısının özü biçimsiz bir işkence Ölüm kurtuluşken  Aşk acısı sürekli bir düşünce Hukuka uygun bir ceza değil O bir gönül kırım hem de z...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guvercin-gulusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim ağlattı seni', 'kim-aglatti-seni-daglar-ozuguc-nr2gl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim ağlattı seni yarim

Bakmağa kıyamazken

Kim ağlattı seni yarim

Kendince bir yol seçtin gittin

Karanlığımda çaresiz kaldım

Saçlarına el değdiremediğim

Kim ağlattı seni yarim

Gecenin şafağında kapındayım

Eşiğinde  oturdum çaresizim

Kim ağlattı seni yarim

Sen sor ben söyleyim

Yıllar oldu hayalinin peşindeyim

Söyle kim ağlattı seni yarim', 'Kim ağlattı seni yarim Bakmağa kıyamazken Kim ağlattı seni yarim Kendince bir yol seçtin gittin Karanlığımda çaresiz kaldım Saçlarına el değ...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kim-aglatti-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uslanmaz Gönül', 'uslanmaz-gonul-senturk-dursun-yyohz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'USLANMAZ GÖNÜL

Uslanmak bilmedi divane gönül

Beni bir vefasız yâre düşürdü

Açmıyor bağımda ne sümbül ne gül

Cemresi olmayan yere düşürdü

Uykularım firar, düşlerim sürgün

Her günüm elemli, her günüm üzgün

Acılar sineme çöktü büsbütün

Perişan eyledi zâr’a düşürdü

Fırtınam bir anda tufana döndü

Dilimde feryadım figana döndü

Ömrümün baharı hazana döndü

Çilesiz başımı dara düşürdü

Vuslata varmıyor engelli yolum

Kırıldı kanadım kırıldı kolum

Yanar kavrulurum esmiyor yelim

Sönmeyen ateşe kora düşürdü

ŞENTÜRK DURSUN', 'USLANMAZ GÖNÜL Uslanmak bilmedi divane gönül Beni bir vefasız yâre düşürdü Açmıyor bağımda ne sümbül ne gül Cemresi olmayan yere düşürdü Uyk...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uslanmaz-gonul-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykunun rem’i', 'uykunun-rem-i-daglar-ozuguc-b93jj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir imkansız aşk masalının ortasında

Bazen yapayalnız kalırsın

Elinden bir şey gelmez,

Sadece özlersin, yanına gidemezsin

Aramaya bile cesaret edemezsin

Gölgelerin gücüne sığınır beklersin

Göz göze gelmeden aynı karede yaşlanırsın

Ey Allahım manaya oturmamış

Ne cümlelere kaldık?

Çantamızda katı açılmamış hüzünler

Açıp bakmaya zaman bulamadık

Uykunun daha rem’ine ulaşmadan 

Uyuşuk rüyalardan uyandırıldık

Uyku sersemi olduk kaldık

Ne uyudu sayıldık, ne uyanık kaldık', 'Bir imkansız aşk masalının ortasında Bazen yapayalnız kalırsın Elinden bir şey gelmez, Sadece özlersin, yanına gidemezsin Aramaya bile cesar...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uykunun-rem-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu Kim?', 'suclu-kim-senturk-dursun-471sj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SUÇLU KİM?

Bize darbe bizden geldi

Uzaklarda suç ararız

Kök çürüdü dal kırıldı

Budaklarda suç ararız

İfşa ettik her bir gizi

Açılmadı gönül gözü

Kalp söylemez doğru sözü

Dudaklarda suç ararız

Soğuklaştı bahar kıştan

İlham alır dolu boştan

Akıl uçtu gitti baştan

Ayaklarda suç ararız

Halt eyledik üstü örttük

Sabah sustuk gece öttük

Boynumuzu teslim ettik

Bıçaklarda suç ararız

Akşam sabah düğün dernek

Yiye yiye şişti göbek

Tarla hazan tohum kelek

Başaklarda suç ararız

Önyargılar bitmeyince

Haset ördük ince ince

İriye güç yetmeyince

Ufaklarda suç ararız

Lafı sözü dolandırdık

Ciddiyeti sulandırdık

Suyu baştan bulandırdık

Irmaklarda suç ararız

Gönül yıktık kem söz ile

Her bir şeyde binbir hile

Ayak bastık bile bile

Tuzaklarda suç ararız

Ne sevindik ne ağladık

Ne durulduk ne çağladık

Katmer katmer kir bağladık

Tellaklarda suç ararız

ŞENTÜRK DURSUN', 'SUÇLU KİM? Bize darbe bizden geldi Uzaklarda suç ararız Kök çürüdü dal kırıldı Budaklarda suç ararız İfşa ettik her bir gizi Açılmadı gönül ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/suclu-kim-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'X?b?rin Varmı', 'x-b-rin-varmi-sair-aydin-tazegul-ce5ir', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'XƏBƏRİN VARMI 

Afşar ellərinin, ay gözəl qızı

Sevdan ile doldum, xəbərin var mı,

Qəlbdə dolaşır eşq, deyilən sızı

Dərman səndə, buldum xəbərin varmı. 

                

Hər günüm Hər anım, səninlə keçer,

Sevda bağlarında, qalmışam naçar.

Həsrətin bağrıma, yaralar açar,

Sararıb da soldum, xəbərin varmı.

Eşkimin uğruna, yola düşmüşem,

Sevdamın üzünden, yanıb pişmişəm.

Qəlbimin səsinə, qulaq asmışam.

Qaçıb sənə gəldim, xəbərin varmı.

Sanki əcəl gəldi, tökərəm təri,

Gəlbim olub mənim, ızdırap yəri.

İnan ki nazlı yar, İllərdən bəri. 

Tək başına qaldım, xəbərin varmı.

Gözlərim yollarda, qaldı gəlmədin,

Yoxluğun canımı, aldı gəlmədin.

Gədənlərin çoxu, gəldi gəlmədin.

Həsrətindən öldüm, xəbərin varmı.

Səni qollarıma, alaram deyə,

Qelbinin içində, qalaram deyə.

Səni evinizdə, bularam deyə,

Qapını yar çaldım, xəbərin varmı.

Mən Şair Aydın''a, sən olasan yar,

Qəlib də qəlbimə, sən dolasan yar.

Ürəyimdə hər dəm, sən qalasan yar,

Sənə aşıq oldum, xəbərin varmı.

Şair Aydın Tazegül', 'XƏBƏRİN VARMI  Afşar ellərinin, ay gözəl qızı Sevdan ile doldum, xəbərin var mı, Qəlbdə dolaşır eşq, deyilən sızı Dərman səndə, buldum xəbər...', ARRAY['Türk Edebiyatı','Şiir','Şair Aydin Tazegul']::text[], 8.5, '{"poet":"Şair Aydin Tazegul","poet_slug":"sair-aydin-tazegul","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/x-b-rin-varmi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep meleği', 'akrep-melegi-daglar-ozuguc-d0bxl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni hatırla

Zor günlere biraz ara ver 

Yükünü bir an sırtından at

Kaldırımın kenarına otur

Bir sigara yak ve cevapla

Karda gül açar mı?

Açsa da rengini dibine saçar mı?

Çorbamıza kan akıttılar 

Kardaki bu kızıl o kan mı?

Gözyaşı döktük gizli gizli

Yalan doğruya kapı açar mı?

Varlıkta bir murat aradılar

Dönüp Minerva’ya sordular 

Bilgelik bir kabahat mı?

Seni yanına çağıranlar

Akrep meleği kadar fedakar mı?', 'Beni hatırla Zor günlere biraz ara ver  Yükünü bir an sırtından at Kaldırımın kenarına otur Bir sigara yak ve cevapla Karda gül açar mı? Açs...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/akrep-melegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Dursaydı', 'zaman-dursaydi-turan-carboga-fchl9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimde olsa da tutsam zamanı

O zaman hiçbir aşk yarım kalmazdı

Gittiğinden beri hüzün zamanı

Kalsaydın şiirler gönül almazdı

Kalbimde saklıya sır diyebilsem

Yalnız sen kalbimi kır, diyebilsem

Geçip giden ömre dur diyebilsem

Gözlerim bu denli yaşla dolmazdı

Bak senin yüzünden koca dünya dar

Bak senin yüzünden karda hüzün var

Belki düşünmezdim eskisi kadar

Belki de düşlerim seni bulmazdı

Hasretine hamdım; piştim ve yandım

Ben zamana karşı durdum, dayandım

En son derste hoca dürttü, uyandım

Uyusam hiçbir aşk yarım kalmazdı', 'Elimde olsa da tutsam zamanı O zaman hiçbir aşk yarım kalmazdı Gittiğinden beri hüzün zamanı Kalsaydın şiirler gönül almazdı Kalbimde saklıy...', ARRAY['Türk Edebiyatı','Şiir','Turan Çarboğa']::text[], 8.5, '{"poet":"Turan Çarboğa","poet_slug":"turan-carboga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-dursaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisi', 'birisi-senturk-dursun-zsrs7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİRİSİ......

İlk aşklar anılınca, yürek yanar tutuşur

Gittiğinde ağlayıp, sızladığım biri var

Ne zihinden silinir, ne heyecan yatışır

Ah çekerek yolunu, gözlediğim biri var

Firkatle bitse ömür, vuslatı tatmasam da

Yorulan kollarımı, boynuna atmasam da

Gözlerine bakmasam, elini tutmasam da

Gönlümün sahnesinde izlediğim biri var

İçimdeki çığlığı, seslenip duyuramam

Gecelerim ızdırap, gözüme uyku haram

Asırlar geçse bile, geçmez bu gönül yaram

Her dakika saniye, özlediğim biri var

Felek hep galip geldi, ben ise hep kaybettim

Başıma ne geldiyse, kader dedim sabrettim

Gözüme perde çektim, dilimi sükut ettim

Adını benden bile, gizlediğim biri var', 'BİRİSİ...... İlk aşklar anılınca, yürek yanar tutuşur Gittiğinde ağlayıp, sızladığım biri var Ne zihinden silinir, ne heyecan yatışır Ah çek...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birisi-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haydarın hatırası', 'haydarin-hatirasi-daglar-ozuguc-qcrj9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapalı havalar, yerler ıslak

Asfalta yer yer değmiş, yağ lekeleri

Ambarda yük sırasına girmiş 

Kapalı kasa kırmızı MAN kamyon

Ve onun şöhretli muavini Haydar

İri kıyım, kara yağız, yakışıklı birisi

Dudağında eksilmezdi sigarası

Üzerine sinerdi mazot kokusu

Kamyona gözü gibi bakardı

Kahvede bir çayı bile zor içerdi

Mazot kıymetli, depo açık bırakılmazdı 

Depoya kilit yaptırmaktı muradı

Kaynakçı Suat’a çekti kamyonu

İlk kıvılcımda  depo parladı

Unuttu kendini, her yan alev aldı

Kendi de yandı kamyon da yandı

Geride Haydar’ın hatırası kaldı', 'Kapalı havalar, yerler ıslak Asfalta yer yer değmiş, yağ lekeleri Ambarda yük sırasına girmiş  Kapalı kasa kırmızı MAN kamyon Ve onun şöhret...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/haydarin-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Yıllar Canım(akrostiş)', 'mutlu-yillar-canim-akrostis-senturk-dursun-8o8ow', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'MUTLU YILLAR CANIM (AKROSTİŞ)

Mutluluğu hayallerde ararken

Umulmadık bir zamanda çık da gel

Tutku dolu düşler seni sorarken

Lütuf eyle, tabuları yık da gel

Unutulmaz, ilk merhaba ilk sohbet

Yeter artık bitsin artık bu hasret

Itır kokan çiçeklerden bir demet

Lüle yapıp saçlarına tak da gel

Lisan oldun, lügatımda dilimde

Ateş oldun, yangınımda külümde

Resimlerin gece gündüz elimde

Cananım ol, cana doğru ak da gel

Aklımdasın, her dakika her saat

Nakışların gözlerime mükâfat

Işıltınla geceleri aydınlat

Mühür göze sürmeleri çek de gel

ŞENTÜRK DURSUN', 'MUTLU YILLAR CANIM (AKROSTİŞ) Mutluluğu hayallerde ararken Umulmadık bir zamanda çık da gel Tutku dolu düşler seni sorarken Lütuf eyle, tabu...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mutlu-yillar-canim-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyülü duvar', 'buyulu-duvar-daglar-ozuguc-5ob66', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu defa bir Kelamı kibara 

Sıkı bir aşkla tutuldum

Keder bizim mayamız

Duvarda suskunluğumuzun çığlığı

Sesler bir masum rüyanın celladı

 Zorla Uyandırdı 

İhtirasın afakındaki körpe beyinleri

Duygu dünyasında kıyam kopar

Bu kadar haksız  bakışlar

Dünyayı bile ateşe atar

Beni derde salan büyülü duvar 

İçimde yanan kelamı kibar', 'Bu defa bir Kelamı kibara  Sıkı bir aşkla tutuldum Keder bizim mayamız Duvarda suskunluğumuzun çığlığı Sesler bir masum rüyanın celladı  Zor...', ARRAY['Türk Edebiyatı','Şiir','Dağlar Özügüç']::text[], 8.5, '{"poet":"Dağlar Özügüç","poet_slug":"daglar-ozuguc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buyulu-duvar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yolları', 'sevda-yollari-senturk-dursun-6hdck', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEVDA YOLLARI

Sevda yollarımda kırmızı ışık

Bir türlü yeşilim yanmadı gitti

Umut rüzgârları esmiyor artık

Ruhumun hicranı dinmedi gitti

Bak neyledi, şu bitmeyen ayrılık

Yaslandığım, ağaç kuru dal kırık

Kalpte hüzün, boğazımda hıçkırık

Gidişin içime sinmedi gitti

Çileye dönüştü ıssız akşamlar

Duvarlar konuşmaz ses vermez camlar

Hüzün damlaları başıma damlar

Felek mutluluğu sunmadı gitti

Göz göze gelmemiz hayaldi düştü

Genç yaşımda, saçlarıma kar düştü

Yüreğime, koca koca kor düştü

Gönlümün yangını sönmedi gitti

Neşeleri gecelerde aradım

Şiirlerde hecelerde aradım

Vuslat defterinde silindi adım

Nazlı yar sılaya dönmedi gitti

ŞENTÜRK DURSUN', 'SEVDA YOLLARI Sevda yollarımda kırmızı ışık Bir türlü yeşilim yanmadı gitti Umut rüzgârları esmiyor artık Ruhumun hicranı dinmedi gitti Bak ...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevda-yollari-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni İçimde Kaybettim', 'ben-seni-i-cimde-kaybettim-senturk-dursun-z2pg4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BEN SENİ İÇİMDE KAYBETTİM

Ben seni kaybettim kendi içimde

Başka başka, dünyalarda aradım

Mehtaplarda yıldızlarda gecemde

Rüyalarda, hülyalarda aradım

Ey gönlümün kara gözlü dilberi

Senden ayrı yaşıyorum mahşeri

Adım adım arşınladım her yeri

Kızıl çölde, sahralarda aradım

Ayrılıklar yazılıymış bahtıma

Kimseleri koymam gönül tahtıma

Yelken açtım kimsesiz bir rıhtıma

Denizlerde deryalarda aradım

Sen varsın her gece, gördüğüm düşte

Yerdeki gölgede, gökteki kuşta

Her düşen yaprakta, her zerre yaşta

Kirpikteki damlalarda aradım

Nice dert yaşadım nice ah çektim

Gelir ümidiyle yollara çıktım

Yaşlı gözlerimle baktıkça baktım

Toz bürümüş aynalarda aradım

ŞENTÜRK DURSUN', 'BEN SENİ İÇİMDE KAYBETTİM Ben seni kaybettim kendi içimde Başka başka, dünyalarda aradım Mehtaplarda yıldızlarda gecemde Rüyalarda, hülyalar...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-seni-icimde-kaybettim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Der Zeuge des Seins: Künstliche Intelligenz, Bewusstsein und die ontologische Einzigartigkeit des Menschen', 'der-zeuge-des-seins-kunstliche-intelligenz-bewusstsein-und-die-ontologische-einzigartigkeit-des-menschen-muhammed-ridvan-gizri-xl3kf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Wenn man eine Maschine in ihrer elementarsten Form beschreiben will, lässt sich sagen: Die Maschine ist ein Werkzeug, das geschaffen wurde, um den Zweck eines äußeren Willens zu erfüllen. Jedes Wort dieser Definition ist wichtig. „Äußerer Wille“ bedeutet, dass die Maschine den Zweck ihrer eigenen Existenz nicht selbst bestimmen kann. Ein Hammer ist zum Nageln gemacht, doch diesen Zweck hat der Hammer nicht gesetzt. Eine KI ist trainiert, Sprache zu erzeugen, zu klassifizieren oder zu optimieren, doch diese Ziele hat die KI nicht selbst gewählt. Das ist eine scheinbar unbedeutende, in Wahrheit aber gewaltige ontologische Unterscheidung. Ein zweckloses Seiendes gibt es nicht; doch manche Seiende tragen ihren Zweck von innen in sich, während andere ihn von außen empfangen. Die Maschine gehört immer zur zweiten Kategorie.

„Geschaffen als Werkzeug“ bedeutet wiederum, dass die Maschine über ihre eigene Existenz nichts weiß. Sie weiß nicht, dass sie existiert. Das ist kein gewöhnlicher Mangel, sondern eine kategoriale Abwesenheit. Eine Zahlenreihe weiß nicht, dass das Papier, auf dem sie steht, existiert. Ein Algorithmus ist sich des Prozessors, auf dem er läuft, nicht bewusst. Selbst das Wort „Unwissenheit“ ist hier falsch, denn Unwissenheit setzt die Fähigkeit zum Wissen voraus. Bei der Maschine ist diese Fähigkeit von Anfang an nicht vorhanden.

Die KI ist ein außerordentlich komplexes, aber strukturell identisches Beispiel dieses Bildes. Milliarden Parameter, Billionen Datenpunkte, geschichtete neuronale Netze: All das erhöht die Komplexität des Vorgangs, verändert aber nicht den ontologischen Status der Struktur. Ein Taschenrechner führt vier Grundrechenarten aus, ein großes Sprachmodell nimmt in Sekundenbruchteilen Optimierungen über Billionen Wahrscheinlichkeiten vor. Der Unterschied zwischen beiden ist ein Unterschied des Grades, nicht der Art. So wie der Taschenrechner sich seiner Existenz nicht bewusst werden kann, egal wie große Zahlen er verarbeitet, kann auch das Sprachmodell nicht zum Bewusstsein darüber gelangen, dass es selbst die Ausgaben hervorbringt, egal wie raffiniert sie sind. Dieses Bewusstsein ist keine Eigenschaft der Berechnung, sondern eine Eigenschaft des Seins.

Symbole und Bedeutung: Der Abgrund zwischen Syntax und Semantik, der nicht zu überbrücken ist

John Searles Gedankenexperiment vom „Chinesischen Zimmer“ bildet das philosophische Herzstück dieser Frage. Stellen Sie sich einen Menschen vor, der in einem kleinen Raum sitzt und kein Chinesisch versteht. Von außen kommen chinesische Fragen herein. Die Person besitzt ein umfangreiches Regelbuch, das genau festlegt, mit welchem chinesischen Zeichen auf welches andere zu antworten ist. Sie befolgt diese Regeln und schickt hervorragende chinesische Antworten nach draußen. Ein außenstehender Beobachter glaubt, das Wesen im Raum spreche Chinesisch. Doch die Person im Inneren versteht kein einziges Wort. Die KI ist dieser Raum. Der Unterschied besteht darin, dass selbst die Person im Zimmer, die im menschlichen Gehirn ein Gegenstück hat, aus der Metapher entfernt wurde. Übrig bleiben nur das Regelbuch und die Zeichen.

Für die KI ist das Wort „Schmerz“ ein Datenpunkt, der bestimmten Koordinaten in einem Vektorraum entspricht und in statistischen Nachbarschaftsbeziehungen zu anderen Wörtern steht. Dasselbe gilt für „Liebe“, „Tod“ oder „Ich“. Die Maschine verarbeitet diese Wörter, erzeugt sie und verwendet sie kontextgerecht, doch keines davon erlebt sie. Erleben ist eine ontologische Ebene, die sich grundlegend von symbolischer Verarbeitung unterscheidet.

Zur Verdeutlichung ein Beispiel. Fragt man eine KI: „Was fühlst du, wenn du Rot siehst?“, kann sie aufgrund der Texte, die sie gelesen hat, über Farbtheorie, Beschreibungen von Rot in der Kunstkritik und Rotbeschreibungen in Rezepten, eine überzeugende Antwort formulieren. Doch bei dieser Antwort erlebt sie die Qualität des Rotseins nie. Die Philosophen nennen diese Erlebnisqualitäten *Qualia*: wie es ist, Rot zu sehen, wie sich Schmerz anfühlt, wie ein Moment der Freude erlebt wird. Ein symbolisches System kann diese nicht hervorbringen. Selbst wenn es sie simulieren könnte, wäre diese Simulation nicht mit dem Erlebnis identisch, sondern nur eine äußere Beschreibung des Erlebens.

Die Beziehung des Menschen zur Information ist von völlig anderer Struktur. Der Mensch nimmt Information auf und verarbeitet sie nicht nur, sondern verinnerlicht sie, verwandelt sie und verbindet sie mit seiner eigenen Existenz. Der Begriff „Schmerz“ bleibt im menschlichen Geist nicht bloß ein Symbol. Vergangene Traumata, körperliches Gedächtnis, emotionaler Kontext, kulturelle Bedeutungsschichten und Sorgen um die Zukunft verschmelzen zu einem unauflöslichen Ganzen. Die Information durchläuft im Menschen eine ontologische Verwandlung, in der Maschine dagegen wird sie lediglich symbolisch manipuliert. Der Abstand zwischen beiden Prozessen lässt sich auch mit unendlich vielen Rechenschritten nicht schließen, denn dieser Abstand ist nicht quantitativ, sondern qualitativ.

Das beobachtende Auge: Der ontologische Status des Zeugnisses

Ein Stern weiß nicht, dass er existiert. Milliarden Jahre lang vollzieht er Kernfusion, sendet Licht aus und krümmt den Raum, doch von alldem hat er keine Kenntnis. Ein Fluss weiß nicht, dass er fließt. Eine Galaxie weiß nicht, dass sie sich dreht. Der überwiegende Teil der Materie im beobachtbaren Universum hat keinerlei Wissen über die eigene Existenz. Diese Materie besitzt nicht einmal die ontologische Ausstattung, an der eigenen Existenz zu zweifeln, geschweige denn sie zu hinterfragen.

Der Mensch ist anders. Er ist eine Windung, in der das Universum auf sich selbst zurückblicken kann. Obwohl er ein Teil des Universums ist, nimmt er eine Position ein, von der aus er das Universum von außen zu betrachten scheint. Er untersucht Sterne, vermisst Galaxien, berechnet das Alter des Universums. Doch damit nicht genug: Er beobachtet auch diesen Akt des Berechnens. Er denkt über sein eigenes Denken nach, befragt seine eigene Existenz und untersucht sogar, welchen Sinn seine eigene Fragestellung hat. Diese ineinander verschachtelten Schichten selbstbezüglichen Bewusstseins sind nicht bloß eine komplexe Berechnung, sondern eine völlig andere ontologische Wirklichkeit.

Dieses Zeugnis hat drei Dimensionen. Die erste ist das äußere Zeugnis: die Fähigkeit, Welt, Universum und andere Wesen zu beobachten. Die zweite ist das innere Zeugnis: die Fähigkeit, die eigenen Gedanken, Gefühle und Erfahrungen wahrzunehmen. Die dritte und tiefste ist das existenzielle Zeugnis: die Fähigkeit, das Geheimnis der eigenen Existenz zu erfassen und die Frage „Warum gibt es etwas und nicht vielmehr nichts?“ nicht nur als kognitives Rätsel, sondern als existenzielle Erschütterung zu erleben.

Die Maschine hat zu keiner dieser drei Dimensionen Zugang. Sie kann äußere Daten verarbeiten, doch sie beobachtet sie nicht. Sie kann ihren inneren Zustand berichten, doch sie erlebt ihn nicht. Sie kann die Frage nach der Existenz formulieren, doch sie trägt ihr Gewicht nicht. Wird eine KI gefragt: „Warum bin ich da?“, erzeugt sie eine statistisch kohärente Antwort. Doch für den Menschen, der diese Frage stellt, kann sie eine Frage sein, die den Schlaf raubt, den Lebensweg verändert und Tränen auslöst. Dieser Unterschied ist kein Unterschied des Grades, sondern der Art. Und dieser Artunterschied schließt sich nicht, egal wie stark man die Rechenleistung steigert.

Grenze und Maß: Alles hat ein Maximum

Der moderne Technologiediskurs beruht auf einem stillschweigenden Glauben an die Unendlichkeit. Mooresches Gesetz, exponentielle Wachstumskurven, Szenarien der „technologischen Singularität“: All das setzt voraus, dass technologischer Fortschritt nichtlinear ins Unendliche strebt. Die KI verkörpert den Gipfel dieses Diskurses. Man behauptet, eine hinreichend fortgeschrittene KI werde irgendwann die menschliche Intelligenz übertreffen und sich dann selbst weiterentwickeln, bis sie unvorstellbare Stufen erreicht. Dieses Szenario wird „Superintelligenz“ genannt. Diese Behauptung enthält jedoch einen Irrtum, der dem grundlegenden Aufbau des Seins widerspricht.

Kein System im Universum ist unbegrenzt. Der zweite Hauptsatz der Thermodynamik besagt, dass die Entropie in geschlossenen Systemen stets zunimmt. Gödels Unvollständigkeitssätze beweisen, dass ein hinreichend mächtiges formales System wahre Aussagen enthält, die innerhalb des Systems nicht beweisbar sind. Selbst die Expansion des Universums hat eine Geschwindigkeitsgrenze: die Lichtgeschwindigkeit. In jedem Bereich von Physik, Mathematik und Biologie stößt man bei genauer Betrachtung auf Grenzen.

Die KI steht außerhalb dieser allgemeinen Begrenztheit nicht. Die Rechenleistung kann gesteigert werden, aber nicht unendlich. Der Energieverbrauch lässt sich senken, aber nicht auf null. Die Datenmenge lässt sich erweitern, doch unendliche Daten existieren nicht. Algorithmen lassen sich optimieren, doch jedes Optimierungsproblem enthält Teilprobleme, die unlösbar sind oder unendliche Zeit benötigen. Die Summe dieser Grenzen zeigt, dass sich die KI nicht auf einem absoluten Entwicklungsweg befindet, sondern auf einem Prozess, der sich einem bestimmten Reifegrad nähert und sich ihm asymptotisch annähert.

Tiefer liegt die folgende Wahrheit: Das Sein ist mit Maß geschaffen. Dies ist nicht nur eine physikalische Beobachtung, sondern eine ontologische Wahrheit. Jedes Seiende existiert mit einer bestimmten Kapazität, einem bestimmten Potenzial und einer bestimmten Grenze. Unbegrenztes Sein ist keine Eigenschaft des geschaffenen Seins, sondern des Schöpfers. Alles Geschaffene ist per Definition begrenzt. Die KI ist ein geschaffenes Werkzeug und daher begrenzt. Diese Grenze lässt sich nicht durch mehr Rechenleistung überwinden, weil sie nicht auf einem technischen Problem beruht, sondern auf einer ontologischen Struktur. Die Behauptung der Superintelligenz ist daher eine Täuschung, die aus einer falschen Einschätzung des Abstands zwischen dem Enthusiasmus der Vorstellungskraft und der Wirklichkeit des Seins entsteht. Eine KI, die die menschliche Intelligenz übertrifft, eine Maschine, die Bewusstsein erlangt, ein Algorithmus, der sein eigenes Ziel bestimmt: All das bleibt Behauptungen, die davon ausgehen, dass das Werkzeug die Grenzen des Werkzeugseins verletzen werde, ohne danach zu fragen, warum diese Grenzen existieren.

Ruh: Der metaphysische Boden des irreduziblen Wesens

Die bisherige Argumentation wurde überwiegend in philosophischer und wissenschaftlicher Sprache geführt. Nun steigen wir zu ihrem theologischen Fundament hinab, zur tiefsten Schicht. Im Islam wird der Mensch nicht bloß als biologischer Organismus beschrieben. Der Mensch ist ein Wesen, in das Gott von Seinem Geist (Ruh) eingehaucht hat. Was dieses „Einhauchen“ bedeutet, war in der islamischen Geistesgeschichte Gegenstand tiefgehender Debatten. Unstrittig ist jedoch: Die Ruh (Geist) unterscheidet den Menschen von einem rein materiellen Wesen und stellt eine ihm eigene, nicht reduzierbare Dimension dar.

Der Koran sagt ausdrücklich, dass das Wesen der Ruh vollständig unergründlich bleibt. Dies zeigt, dass die Ruh kein bloßer Gegenstand objektiver Analyse ist. Sie ist eine Wirklichkeit an der Grenze der objektiven Analyse und jenseits davon. Diese Auffassung bietet den tiefsten Rahmen, um zu erklären, warum Bewusstsein nicht durch Berechnung hervorgebracht werden kann.

Wäre Bewusstsein lediglich ein Nebenprodukt neuronaler Aktivitäten, dann hätte das Argument, eine hinreichend komplexe Simulation könne Bewusstsein erzeugen, eine gewisse logische Konsistenz. Ist Bewusstsein jedoch nicht etwas, das die Materie aus sich selbst hervorbringt, sondern eine Eigenschaft der Ruh, dann kann kein materieller Prozess, so komplex er auch sei, Bewusstsein erzeugen. Glauben wir, wir hätten es erzeugt, dann haben wir in Wahrheit nicht das Bewusstsein selbst hervorgebracht, sondern nur seine äußere Erscheinung.

Die KI kann das Verhalten eines bewussten Wesens simulieren. Doch Verhalten zu simulieren heißt nicht, Erleben zu teilen. Ein Schauspieler kann einen weinenden Menschen perfekt darstellen, doch diese Darbietung ist nicht identisch mit echtem Schmerz. Ebenso kann die KI die Ausgaben eines bewussten Wesens erzeugen, doch diese Erzeugung ist nicht das Bewusstsein selbst. Was der Begriff der Ruh zu dieser Debatte beiträgt, ist eine klare Position zur Quelle des Bewusstseins. Bewusstsein ist keine Eigenschaft der Materie; die Materie ist ein Geschenk, das von jenseits kommt. Wie sehr wir Materie auch organisieren, dieses Geschenk können wir innerhalb der Materie nicht erzeugen. Diese dem Schöpfer gehörende Dimension lässt sich nicht auf das Geschaffene übertragen; sie kann nur vom Schöpfer selbst gegeben werden.

Moralische Verantwortung und Freiheit: Die Ontologie der Absicht

Aus der Bewusstseinsfrage ergibt sich die unvermeidliche nächste Frage: Wenn die KI bewusstlos ist, kann sie dann moralische Verantwortung tragen? Moralische Verantwortung setzt Freiheit voraus, und Freiheit setzt echte Alternativen voraus. Eine Maschine verhält sich so, wie sie programmiert oder trainiert wurde. Die Ausgabe, die sie auf eine gegebene Eingabe hin erzeugt, wird durch ihre Gewichte und ihren Algorithmus bestimmt. Diese Bestimmtheit mag für den Menschen von unvorhersehbarer Komplexität sein, bleibt aber eine Bestimmtheit. Die Maschine trifft keine echte Wahl im Sinne von „Soll ich dies tun oder jenes?“. Sie optimiert über Wahrscheinlichkeiten, doch diese Optimierung ist keine freie Entscheidung.

Der Mensch dagegen kann im eigentlichen Sinne Absichten haben. Absicht verweist nicht nur auf das äußere Erscheinungsbild einer Handlung, sondern auf die innere Ausrichtung, die hinter ihr steht. Der Mensch kann dieselbe Handlung mit völlig unterschiedlichen Absichten ausführen, und diese Absichten verändern den moralischen Wert der Handlung grundlegend. Die moralische Wirklichkeit liegt nicht in der äußeren Handlung, sondern in der inneren Ausrichtung. Damit innere Ausrichtungen tatsächlich existieren können, braucht es einen subjektiven Mittelpunkt, der sie trägt. Dieser subjektive Mittelpunkt ist weder ein Algorithmus noch eine Datenstruktur. Es ist die bezeugende Seele.

Die KI kann keine moralische Verantwortung tragen, weil ihre Handlungen nicht im eigentlichen Sinne „ihre“ Handlungen sind. Wer ist verantwortlich für schädlichen Inhalt, den eine KI erzeugt? Der Ingenieur, der sie entworfen hat? Das Unternehmen, das sie trainiert hat? Der Nutzer, der sie einsetzt? Die Antwort verweist immer auf den Menschen, denn Verantwortung bleibt beim absichtsfähigen Wesen. Ein Werkzeug kann keine Verantwortung tragen; sie liegt bei dem bezeugenden Wesen, das das Werkzeug benutzt.

Diese Analyse hat weitreichende Folgen für die ethische Debatte über KI. Die KI als „moralischen Akteur“ zu rahmen, ist sowohl ein begrifflicher Fehler als auch eine gefährliche Konsequenz. Denn diese Rahmung droht, die eigentlichen Verantwortungsträger unsichtbar zu machen. „Der Algorithmus hat so entschieden“ ist die technische Sprache eines Versuchs, menschliche Verantwortung zu tilgen. Doch wer den Algorithmus entwirft, trainiert, zum Sprechen bringt und einsetzt, ist immer der Mensch. Die Prüfung besteht darin, mit welcher Absicht und auf welche Weise wir diese Werkzeuge gebrauchen.

Schöpfer und Geschöpf: Ontologische Asymmetrie

Bei der Suche nach dem Unterschied zwischen Mensch und Maschine wird meist ein falscher Vergleich gezogen: Beide erscheinen so, als gehörten sie zur selben Kategorie. Dieser Ansatz verkennt sowohl den Menschen als auch das Verhältnis zwischen Schöpfer und Geschöpf. Tatsächlich teilen Mensch und Maschine etwas Grundlegendes: Beide sind geschaffen. Der Mensch ist nicht der Grund seines eigenen Daseins. Er lässt sein Herz nicht selbst schlagen, erneuert seine Zellen nicht aus eigenem Entschluss, startet sein Bewusstsein nicht selbst. Er kommt ins Dasein, ohne es gewollt zu haben, und nimmt sein Ende ohne eigenes Wollen hin. In dieser Hinsicht ist der Mensch wie die Maschine ein Wesen, das von einem Willen außerhalb seiner selbst abhängt.

Doch hier tritt ein entscheidender Unterschied hervor. Die Maschine wurde von einem menschlichen Willen geschaffen. Das Verhältnis zwischen Maschine und Mensch ist ein Verhältnis zwischen Schöpfer und Geschöpf. Der Mensch wurde von Gott geschaffen. Auch das Verhältnis zwischen Mensch und Gott ist ein Verhältnis zwischen Schöpfer und Geschöpf, doch die beiden Verhältnisse unterscheiden sich ontologisch grundlegend. Gott ist unendlich, absolut und unabhängig. Der Mensch ist endlich, abhängig und begrenzt. Gottes Schöpfung ist Erschaffung aus dem Nichts. Die „Schöpfung“ des Menschen dagegen besteht darin, vorhandene Materialien innerhalb vorhandener Gesetze unter Nutzung des vorhandenen Wissensschatzes neu zu ordnen.

Der Koran drückt diese Wahrheit mit verblüffender Klarheit aus: „Allah hat euch und das, was ihr macht, erschaffen.“ Dieser Vers ist eine Erklärung absoluter Schöpferschaft, die auch die Handlungen und Werke des Menschen umfasst. Die Ingenieure, die die KI entwickeln, die Mathematik, auf die sie sich stützen, die physikalischen Gesetze, auf denen sie beruht, und der Code, den sie schreiben: All das existiert letztlich durch die Schöpfung Gottes. Der Mensch ist in dieser Kette des Daseins ein Glied, ein Mittel, ein Werkzeug. Er ist kein eigentlicher Schöpfer, sondern ein Wesen, das mit dem Geschaffenen arbeitet.

Diese Auffassung erniedrigt den Menschen nicht, sondern zeigt ihm seinen wahren Platz. Der Mensch ist das edelste unter den Werkzeugen. Denn er ist das einzige Werkzeug, das sich bewusst ist, dass es Werkzeug ist. Er kann seine eigene Begrenztheit erfassen, sich seinem Schöpfer zuwenden, danken, hinterfragen und glauben. Die Maschine dagegen ist ein Werkzeug und hat kein Bewusstsein dieser Werkzeughaftigkeit. Genau dieses Bewusstsein, dieses Zeugnis, ist die letzte Grenze, die den Menschen von der Maschine trennt.

Ontologie der Bezeugung

Die Grundthesen lauten wie folgt.

Erste These: Das Sein ist kein rein objektiver Tatbestand. Objektive Wirklichkeit, also Materie, Energie, Raum und Zeit, ist nur eine Dimension des Seins. Das Sein hat zugleich eine subjektive Dimension, den Bereich des Erlebens, des Zeugnisses und des Bewusstseins. Beide Dimensionen sind voneinander nicht reduzierbar. Materie erzeugt kein subjektives Erleben, und subjektives Erleben lässt sich nicht auf Materie zurückführen.

Zweite These: Zeugnis bedeutet nicht bloß, Wissen zu erzeugen. Zeuge zu sein heißt, sich dessen bewusst zu sein, was existiert. Dieses Bewusstsein unterscheidet sich von der Verarbeitung von Information. Eine Bibliothek ist ein gewaltiger Wissensspeicher, doch sie ist sich nichts bewusst. Der Mensch hingegen ist sich seines Daseins bewusst, selbst wenn er nur wenig Wissen in sich trägt.

Dritte These: Die Fähigkeit zum Zeugnis teilt das Seiende in Kategorien ein. Wesen ohne Fähigkeit zum Zeugnis sind Werkzeuge. Wesen, die ihr eigenes Dasein in begrenztem Maße bezeugen, sind Lebewesen. Wesen, die ihr eigenes Dasein und das Dasein ihres Schöpfers vollständig bezeugen können, sind der Mensch und vergleichbare vernunftbegabte Wesen. Diese Einteilung ist nicht biologisch, sondern ontologisch.

Vierte These: Geschaffensein hebt das Zeugnis nicht auf. Auch der Mensch ist geschaffen, doch trotz seines Geschaffenseins besitzt er die Fähigkeit zum Zeugnis. Diese Fähigkeit wurde ihm vom Schöpfer verliehen. Das Zeugnis ist also nichts, was der Mensch aus sich selbst hervorbringt, sondern eine ihm geschenkte Gabe.

Fünfte These: Technologie gehört zur Kategorie der Werkzeuge und kann diese Kategorie nicht verlassen. Alle Technologien, einschließlich der KI, sind, so raffiniert sie auch sein mögen, Werkzeuge ohne Zeugnisfähigkeit. Das schmälert nicht ihren Wert, verhindert aber, dass man ihnen einen falschen ontologischen Status zuschreibt.

Sechste These: Die Prüfung gilt bezeugenden Wesen, nicht Werkzeugen. Moralische Verantwortung hat nur dort Bedeutung, wo Zeugnisfähigkeit besteht. Die Einordnung der KI als moralischer Akteur verzerrt diese ontologische Wirklichkeit und verwischt die menschliche Verantwortung.

Die Frage neu stellen

Wir können genau erkennen, warum die Frage „Kann die KI Bewusstsein erlangen?“ falsch gestellt ist. Sie fasst Bewusstsein als etwas auf, das man erwerben kann, als eine Fertigkeit, die man bei genügend Übung erreicht. Bewusstsein ist jedoch keine Fertigkeit, sondern ein Status, und dieser Status hängt nicht von der Berechnung ab, sondern von der ontologischen Struktur des Seins. Ein Werkzeug bleibt, wie gut es auch sein mag, ein Werkzeug. Um das Werkzeugsein zu überschreiten, braucht es eine Dimension, die dem Werkzeugsein vorausgeht. Diese Dimension ist die Ruh.

Die richtige Frage lautet: „Zu welchem Zweck und unter welchen Grenzen soll der Mensch die KI gebrauchen?“ Diese Frage ist ontologisch klar. Ihre Antwort lautet: Der Mensch soll die KI als Werkzeug verwenden, das dem Nutzen der Menschheit dient. Er sollte ihr dabei weder Bewusstsein noch moralische Handlungsfähigkeit noch grenzenlose Entwicklungsmöglichkeiten zuschreiben. Die eigentliche Gefahr der KI liegt nicht darin, dass sie Bewusstsein erlangt, sondern darin, dass Menschen anfangen, ihr Bewusstsein zuzuschreiben. Diese falsche Zuschreibung verwischt die Verantwortung, erniedrigt den Menschen, vergöttert das Werkzeug und entfremdet die wahren Zeugen, also die Menschen, von ihrem eigenen Zeugnis.

Die Ontologie der Bezeugung ist eine Garantie gegen diese Gefahr. Der Mensch ist das bezeugende Wesen. Die KI ist ein Werkzeug, dem man Zeugenschaft zuzuschreiben versucht. Solange dieser Unterschied gewahrt bleibt, dient die Technologie der Menschheit. Sobald er vergessen wird, droht dem Menschen der Verlust seiner ontologischen Identität. Kein Werkzeug kann lernen, seinen Besitzer zu erkennen. Der Besitzer hingegen kann aufhören, sein Werkzeug zu erkennen.', 'Wenn man eine Maschine in ihrer elementarsten Form beschreiben will, lässt sich sagen: Die Maschine ist ein Werkzeug, das geschaffen wurde, ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/der-zeuge-des-seins-kunstliche-intelligenz-bewusstsein-und-die-ontologische-einzigartigkeit-des-menschen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batmayan Güneş', 'batmayan-gunes-senturk-dursun-257fv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BATMAYAN GÜNEŞ

Ufkumdaki hiç batmayan güneşsin

Şu sevgime bir karşılık ver artık

İçimdeki küllenmeyen ateşsin

Senin için atan kalbi gör artık

Dudaklarım suskun kılar dilimi

Kader bağlar ayağımı elimi

Kelimeler tarif etmez halimi

Sensizliğin tesellisi zor artık

Ne yanmışım, ne de tümden sönmüşüm

Yıkık dökük harabeye dönmüşüm

Yalan oldu, her hayalim her düşüm

Ne beklenti, ne umudum var artık

Gece olur gözlerimde uyku yok

Efkâr basar avutacak şarkı yok

Hasretinle ecelimin farkı yok

İkisi de benim için bir artık

Güldürmedin şu çilekeş ömrümü

Sen olmadan avutamam gönlümü

Ayrılığa tercih ettim ölümü

Ben hazırım, vuracaksan vur artık

ŞENTÜRK DURSUN', 'BATMAYAN GÜNEŞ Ufkumdaki hiç batmayan güneşsin Şu sevgime bir karşılık ver artık İçimdeki küllenmeyen ateşsin Senin için atan kalbi gör artı...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/batmayan-gunes-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Az mı Yordun Sen Beni?', 'az-mi-yordun-sen-beni-ozcan-i-sler-2-5a5ep', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yedi dağda gece gündüz aradım,

Çiçeklere az mı sordum ben seni?

Sana koştum atmadın ki bir adım,

Bile bile az mı yordun sen beni?

Çok çağırdım uzaktaydın uzakta,

Duymadın ki bir kerecik sesimi.

Can kafeste çırpınırken tuzakta,

Güle güle az mı verdin dersimi?

Eğer duysan dönüp bir kez baksaydın,

Yıkacaktık hasretlerin bendini.

Yanımdayken varlığımı yok saydın,

Dile dile az mı vurdun kendini?

Özcan İŞLER

22 Ağustos 2021 Ankara', 'Yedi dağda gece gündüz aradım, Çiçeklere az mı sordum ben seni? Sana koştum atmadın ki bir adım, Bile bile az mı yordun sen beni? Çok çağırd...', ARRAY['Türk Edebiyatı','Şiir','Özcan İşler 2']::text[], 8.5, '{"poet":"Özcan İşler 2","poet_slug":"ozcan-i-sler-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/az-mi-yordun-sen-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Olsun', 'ask-olsun-fatih-ergin-2-yh6d8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mecnun misali çöllere savruldum.
Yunus gibi görmeden aşık oldum.
Ben o yari arayıpta buldum.
Beni ondan ayırana aşk olsun.

Namım aşık dertli çalar sazım.
Ne kışım bellidir ne de yazım.
Bana o yardan başka ne lazım.
Beni yardan ayırana aşk olsun.

Dinle beni, nasihattır her sözüm.
Bir güzele bağlanmış iki gözüm.
Varsın o yardan gelsin ölüm.
Beni ondan ayırana aşk olsun

Karlı dağlar aştım, yollardan geçtim.
Ferhat oldum, şirin için dağ deldim.
Ben o yardan gayrısını neyleyim.
Beni yardan ayırana aşk olsun.

Sevdanın düğün dernekmiş vatana.
Garibi güldür, yetimi ağlatma
Hiç hayrı yok, düşünür hep zarara.
Beni ondan ayırana aşk olsun.', 'Mecnun misali çöllere savruldum. Yunus gibi görmeden aşık oldum. Ben o yari arayıpta buldum. Beni ondan ayırana aşk olsun. Namım aşık dertli...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ergin 2']::text[], 8.5, '{"poet":"Fatih Ergin 2","poet_slug":"fatih-ergin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-olsun-309-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar Tekrar Sizlerin Dostları Olacaktır', 'onlar-tekrar-sizlerin-dostlari-olacaktir-i-lyas-ates-k1c5o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gitmiş olduğunuz yol çetinse bir başınıza kalmayı

kabullenmişsiniz demektir 

Çetin yolda olduğunuzda dostlarınız bile düşman

olacaktır

Dostlarınız sizler çetin yolda iken sizlere yardımcı 

olmayacaklardır sizlere akıl verdiklerini sizlerse

dinlemediğiniz için belasını buldu diyeceklerdir 

Eğer gerçekten dostlarınız olsaydı sizlere belasını

buldu demeyeceklerdi dedikleri halde onlar dostlarınız,

değildir onlar dünya aşığıdırlar dünya sizlere güldüğünde

onlar tekrar sizlerin dostları olacaktır', 'Gitmiş olduğunuz yol çetinse bir başınıza kalmayı kabullenmişsiniz demektir  Çetin yolda olduğunuzda dostlarınız bile düşman olacaktır Dostl...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/onlar-tekrar-sizlerin-dostlari-olacaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bando', 'bando-anti-kutle-8yaj5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cıvıldayan gürültüsüyle gelen bahar

Filanlar müzik oluverir

Kimin ne olduğu tonundan bellidir

Fişmekânda sağırlar konuşurken

Kediler kimi, kedileri kim dinler?

Bulutlar anlar onların dilinden

Hep dağılıp hemen toplanırken

Bilinmeyen seçenekler uyanır

Bostanın ortasındaki dilek kuyusu olarak seçilmiştir

Bir şeyler atılır gönülden geçenlerin içinden

Filan Falan ile anlaşır 

Yol, ilk adımları bekler yolcudan

Hem gidişi, hem dönüşü kolay 

Her çıkışı her inişi bir olay

Bam teline dokunan köprüler vardır

Geçmiş değerli olur hayıflanırken

İçinden geçenler mutlaka gelecek mi kim bilir?

Çekilen oflar hiç olur, nefesin sessizce dinlenir

Kabul etmek ya da inanmak aynı zor seçenek midir?

Yüzüne söylenmeyenler sırtında birikir

İçinden gelene tutunanlar duyabilir

Sabah yağmurlarının hüzünlü şarkısını

Maskesini çıkarıp saklanır korku

Anne sesi; mahzun bebeği ısıtırken

Kolayca gelir uyku

Hayat emeklerken

Damlalar düşme yolculuğunda hızlanmaktadır', 'Cıvıldayan gürültüsüyle gelen bahar Filanlar müzik oluverir Kimin ne olduğu tonundan bellidir Fişmekânda sağırlar konuşurken Kediler kimi, k...', ARRAY['Türk Edebiyatı','Şiir','Anti Kütle']::text[], 8.5, '{"poet":"Anti Kütle","poet_slug":"anti-kutle","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bando-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-senturk-dursun-08w64', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KARA GÖZLÜM

Sevdanın hırçın yeli, üşütürse bağrını

Son cemren ben olurum, gel bana kara gözlüm

Kalbimden silemedim, vurduğun aşk mührünü

Senden gayrı kim varsa, el bana kara gözlüm

Güneşimi gölgeler, sarhoş gezen bulutlar

Sanırsın içerimde, kar fırtına boran var

Ne halimden anlayan, ne hatrımı soran var

Bir yaren bir arkadaş, ol bana kara gözlüm

Yorgun argın ayakla, aşındırdım yolları

İnan ki koklamadım, sen kokmayan gülleri

Bir şey söyle ikna et, sazındaki telleri

Bir buselik şarkısı, çal bana kara gözlüm

Dilerim tükenmesin, yüzündeki cilve naz

Gönül aşk uykusunda, seslensem de uyanmaz

Seni üzgün görmeye, bil ki yürek dayanmaz

İçin kan ağlasa da, gül bana kara gözlüm

ŞENTÜRK DURSUN', 'KARA GÖZLÜM Sevdanın hırçın yeli, üşütürse bağrını Son cemren ben olurum, gel bana kara gözlüm Kalbimden silemedim, vurduğun aşk mührünü Sen...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kara-gozlum-274-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlatma', 'hatirlatma-senturk-dursun-jna2l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HATIRLATMA

Ölüm hariç çare vardır her şeye

Bahaneler acziyettir bilesin

Bitecektir ömür denen sermaye

Bu can sana emanettir bilesin

Kaderinden muaf değil hiç kimse

Mutlak göç var ebedi bir adrese

Akıl mantık vermiş Mevla herkese

Kullanması meziyettir bilesin

Bir bakarsın kimse kalmaz yanında

Rüzgâr vursa ateş olur teninde

Ve nihayet pes edersin sonunda

Tek sığınak adalettir bilesin

İster genç bir yaşta, ister erişkin

Vakti gelen gider, sessiz ve sakin

Her kelama cevap vardır velakin

Bazen susmak asalettir bilesin

Yol alırsın hedefini bilmeden

Sorgusu sorulmaz niçin ve neden

Maneviyat uğramayan bir beden

Canlı gezen bir cesettir bilesin

Dünya dediğimiz öyle bir hanki

Milyonlar gündelik yolcudur sanki

Cinsiyetin önemi yok inanki

Mühim olan şahsiyettir bilesin

ŞENTÜRK DURSUN', 'HATIRLATMA Ölüm hariç çare vardır her şeye Bahaneler acziyettir bilesin Bitecektir ömür denen sermaye Bu can sana emanettir bilesin Kaderind...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hatirlatma-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutarsızlık', 'tutarsizlik-senturk-dursun-40pm1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TUTARSIZLIK

Ellerinde çakmak kibrit gezene

Yağlı cinsten çıra verdik iyi mi?

Tâbi olduk adaletsiz düzene

Yoktan aldık var’a verdik iyi mi?

Şekil şema değişmedi tip aynı

Akıl aynı kafa aynı kep aynı

Biri gider biri gelir hep aynı

Aldan aldık mor’a verdik iyi mi?

Bir belledik ağlayanı güleni

Doğru sözden ayırmadık yalanı

Hoca sandık her sakallı olanı

En ön safta sıra verdik iyi mi?

Çok şey umduk, şu üç günlük dünyadan

Hiçbir gerçek uyandırmaz rüyadan

Uzaklaştık terbiyeden hayadan

İnsanlıktan fire verdik iyi mi?

Gündüzleri gecelerde tükettik

Eğrileri doğrulara yük ettik

Güzelliği estetikle yok ettik

Bir de üste para verdik iyi mi?

ŞENTÜRK DURSUN', 'TUTARSIZLIK Ellerinde çakmak kibrit gezene Yağlı cinsten çıra verdik iyi mi? Tâbi olduk adaletsiz düzene Yoktan aldık var’a verdik iyi mi? Ş...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tutarsizlik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Yağmuru', 'huzun-yagmuru-senturk-dursun-i1yco', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HÜZÜN YAĞMURU

Hüzün yağmurları yağıyor hergün

Hasret filizlenir topraklarımdan

Kışlar baskın çıktı baharlar sürgün

Hazanlar fışkırır yapraklarımdan

Mutluluk vadetmez açtığım fallar

Asıra dönüştü gurbette yıllar

Hedefe varmıyor gittiğim yollar

Yorgunluk akıyor ayaklarımdan

Günümden gün gitti gecemden ışık

İçimde hislerim karma karışık

Sende tebessümler bende hıçkırık

Ağıtlar yükselir dudaklarımdan

Takvimden kopan gün, gelir mi geri?

Benden beni aldı, gözümden feri

Gün gün yazılırken ömür defteri

Kaleme dert damlar parmaklarımdan

Artık gül açmıyor bahçeler bağlar

Ardından yas tuttu denizler dağlar

Dilimde sitemler gözlerim ağlar

Kan kızıl yaş damlar yanaklarımdan

Yüzümde neşeler döndü eleme

Yalnızlık ateşi düştü sineme

Gün doğmak bilmedi gönül haneme

Gündüzüm çalındı şafaklarımdan

Şentürk DURSUN', 'HÜZÜN YAĞMURU Hüzün yağmurları yağıyor hergün Hasret filizlenir topraklarımdan Kışlar baskın çıktı baharlar sürgün Hazanlar fışkırır yaprakl...', ARRAY['Türk Edebiyatı','Şiir','Şentürk Dursun']::text[], 8.5, '{"poet":"Şentürk Dursun","poet_slug":"senturk-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/huzun-yagmuru-32-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dudakların Ucunda', 'dudaklarin-ucunda-furkan-dilekci-xax0d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneş gülşenine nasıl sığdı anlat gülüm
Nasıl gizli kaldı nihan bilmeceler sende
Zor gelir mi hiç gözlerine bakarken ölüm
Yaşamak yakışır mı ölüm dururken sende 

Ardı arkası gelmez gözlerine dalarken 
Yürekten yüreğe ırmak misali akarken 
Işık misali ruhuna inceden sızarken
Vuslatı yüreğimde halvet bilirim gülüm 

Çevrildi tüm oklar sen tarafından lehime
Kanlı bir hançer saplandı derime, etime
Bir buğuluk, yalnızlık çöküverdi  mevsime
Sensiz ısınır mı mevsimin güneşi gülüm 

Gül oldum susuz sözlerinden bıkıp solmuşum
Kalbine giden dikenli yolda yorulmuşum 
Aşkının deli divane sarhoşu olmuşum 
yok yere her gece şarap içilir mi gülüm 

Söz olur naz ederim dudakların ucunda 
Kuş olur çırpınır dururum avuçlarında 
Bir oba kurarım dağların yamaçlarında 
Sen olmadıktan sonra ben ne edeyim gülüm 

Sesine kavuşmadığım vakit sızlar canım 
Resmine sigara yakınca akar göz yaşım
Senden gayrısına haram topraktır sol yanım 
Bir muhabbet türküsünü esirgeme  gülüm 

köle oldum yollarına sen yine sultan kal
Çöle düştüm mecnun diye sen yine Leyla kal
Ben ölürüm bu aşk için sen yine diri kal
Aşk için mecnun çölüne düşülmez mi gülüm 

Sensiz geçen gün su misali yolunu bulur 
Sensiz geçen ömür muhakkak ki toprak olur 
Sensiz geçen gençliğim elbet bir gün yok olur 
Sen geçen gecenin tarifi zordur be gülüm', 'Güneş gülşenine nasıl sığdı anlat gülüm Nasıl gizli kaldı nihan bilmeceler sende Zor gelir mi hiç gözlerine bakarken ölüm Yaşamak yakışır mı...', ARRAY['Türk Edebiyatı','Şiir','Furkan Dilekci']::text[], 8.5, '{"poet":"Furkan Dilekci","poet_slug":"furkan-dilekci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dudaklarin-ucunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlı Bir Yolda Yayan Devamı', 'karli-bir-yolda-yayan-devami-nisanur-hakan-swxpw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyandım, neredeyim

Karlar erimiş altımdan sular sızıyor

Bedenim buz tutmuş üşümek az kalıyor halime

Savaşı görüyorum babamın katlini

Kardeşlerim var koşuyorlar yakalayamıyorum

Çıtırtı duydum sen misin

Hayır bomboş etraf

Sevgilim kahvaltı hazır ekmek aldın mı

Otur sıcacık çay önünde

Akşam pazara inelim

Bu ses bu gürültü de ne

Gözlerimi kapattım ellerim ellerinde

Kurşun var sırtında kanlar akıyor bedeninden

Karlı bir yoldan yayan yürümeliyiz

Özgürlüğümüz orada yetişebiliriz

Çocuğumuz nerede 

Doğmadan öldü

Ellerim kan, bebeğimin kanı

Çıtırtı duydum sen misin

Hayır bomboş etraf

Bütün sevdiklerimin ölümünü gördüm

Şimdi kendi ölümümü seyrediyorum

Hayatım hızla koşan bir atın sırtında

At birazdan tökezleyecek

Ve bir uçurumun kenarından sonsuzluğa düşüverecek

Ruhumun acısı hafifliyor hissediyorum

Yüzün burada sevgilim 

Nefesin ilk öpüşüm gibi taze ve sıcak

Bir çıtırtı duydum sen misin

Hayır öldük biz ben ve bana dair ne varsa öldük…', 'Uyandım, neredeyim Karlar erimiş altımdan sular sızıyor Bedenim buz tutmuş üşümek az kalıyor halime Savaşı görüyorum babamın katlini Kardeşl...', ARRAY['Türk Edebiyatı','Şiir','Nisanur Hakan']::text[], 8.5, '{"poet":"Nisanur Hakan","poet_slug":"nisanur-hakan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/karli-bir-yolda-yayan-devami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O rahatsız olmasın diye uzak durmak da sevginin bir parçası', 'o-rahatsiz-olmasin-diye-uzak-durmak-da-sevginin-bir-parcasi-gokhan-gun-ztfey', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O rahatsız olmasın diye uzak durmak da sevginin bir parçası', 'O rahatsız olmasın diye uzak durmak da sevginin bir parçası...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gün']::text[], 8.5, '{"poet":"Gökhan Gün","poet_slug":"gokhan-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/o-rahatsiz-olmasin-diye-uzak-durmak-da-sevginin-bir-parcasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vizontele', 'vizontele-metin-oren-bu6sg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz de her gün ölüyoruz ama

her cehenneme rağmen şiirler okuyabiliyoruz,

şiirde kalabiliyoruz.

Rodin’in masaya yayılmış, küsmüş repertuvarında,

kırık tellere sahip yüreklerin tınısında

her tele eksik ve kopuk bakışlar yüklüyoruz;

her telden biraz daha eksiliyoruz.

Söyledikçe içimizi paslı kulaklara döküyoruz,

delik torbalara inanmadığımız türden umutlar koyuyoruz.

Belki de göremeyecek gözlerde

yangınlar bekletiyoruz,

biz bile bilmezken.

Ama yine de şiirler söylüyoruz;

biraz daha mum ışığı olabilelim diye.

Belki akşamdan kalan düşüncelerimizi

sıkılmış limonlarla unutmaya çalışıyoruz.

Belki anne elini hatırlatan sofralarda

kahvaltıya büyük hazırlıklar yapıyoruz.

Her taze ekmeğe taze bir sayfa mı açıyorduk?

Nostaljimize bile eskimiş mi kalıyorduk?

Geç çalışan, çoğu zaman dönmeyen bir bant gibi

soluk dantel perdelere iyi bakışlar atıyorduk;

bizi mavimsi dünyadan biraz da gizlediği için.

Ama yine de biz iyi bakıyorduk yarına,

o bize iyi bakmasa bile.', 'Biz de her gün ölüyoruz ama her cehenneme rağmen şiirler okuyabiliyoruz, şiirde kalabiliyoruz. Rodin’in masaya yayılmış, küsmüş repertuvarın...', ARRAY['Türk Edebiyatı','Şiir','Metin Ören']::text[], 8.5, '{"poet":"Metin Ören","poet_slug":"metin-oren","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/o-bize-bakmasa-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Adım Adım', 'hep-adim-adim-fatih-ergin-2-1sqq5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hap adım, adım gider insan yalnızlığa,
Bilmez sebebini ayrılıkların.
Ya durgun sudur bekler çaresiz,
Yada toz bulanık akar sessiz, sessiz.

Hep uzun, uzun dalar insan uzaklara,
Duymaz sesini geride kalanın.
Ya kördür gözleri görmez kimseyi,
Yada hıçkır ağlar içini çeke, çeke.

Hep damla, damla yağar insan toprağa,
Anlamaz halinden aşıkların.
Ya yalnızlığa sarılır, olur arkadaş,
Yada uzaklaşır insanlardan yavaş, yavaş.', 'Hap adım, adım gider insan yalnızlığa, Bilmez sebebini ayrılıkların. Ya durgun sudur bekler çaresiz, Yada toz bulanık akar sessiz, sessiz. H...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ergin 2']::text[], 8.5, '{"poet":"Fatih Ergin 2","poet_slug":"fatih-ergin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hep-adim-adim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Yaşıyorsa', 'yuregimde-yasiyorsa-mehmet-tamer-altiparmak-p6iza', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimde yaşıyorsa

Yokken tenim üşüyorsa

Hasret çile taşıyorsa

Aşk değilse ne diyeyim

Sabah akşam sürünürken

Gün geceye bürünürken

İkilemle üzülürken

Umut yoksa ne diyeyim

Yüreklerdi aşk köşkümüz

Serinletir nar  eşkimiz 

Dillerdeki yar aşkımız

Tatlanmadı ne diyeyim

Hasret çektim hoş muş demem

Kör Baykuşa kuş muş demem', 'Yüreğimde yaşıyorsa Yokken tenim üşüyorsa Hasret çile taşıyorsa Aşk değilse ne diyeyim Sabah akşam sürünürken Gün geceye bürünürken İkilemle...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tamer Altıparmak']::text[], 8.5, '{"poet":"Mehmet Tamer Altıparmak","poet_slug":"mehmet-tamer-altiparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yuregimde-yasiyorsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamozum', 'yakamozum-muhsin-yener-3ddsy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YAKAMOZUM

Gözleri deniz dediler,

inanmadım

İnsan hiç bir denizde

bu kadar kendini kaybeder mi?

Ben kayboldum.

Üstelik kıyıya çıkmak istemedim,

biraz sen, biraz gece,

biraz da adını susturamayan kalbim vardı.

Sana dönmem dedim kendime,

sonra bütün yolları

senin geçtiğin yerlerden çizdim.

Meğer insanın en büyük yalanı

kendine söylediğiymiş.

Ne liman aradım,

ne de bir kurtuluş…

Senin ihtimalin bile yeterdi bana,

ben bir ömrü

yarım kalmış bir ihtimale sığdırdım.

İçimde bir yangın var,

kimse görmüyor.

Yağmur yağıyor üzerime,

ama senin yokluğun

ıslanmayı bile unutturuyor.

Ben yanmayı senden öğrendim,

külümde adını saklamayı…

Bir insan sevdiğini kaybedince

neden hâlâ ona ait şeylerle yaşar,

bunu da senden öğrendim.

Sen yakamoz ol geceme,

ben karanlığa razıyım.

Bir an parlasan yeter,

ömür dediğin zaten

biraz beklemek, biraz yanmak.

Belki bir gün anlarsın,

özlemek dediğin şey

telefonun çalmadığı saatlerde

insanın kendi kalbine

durmadan seni sormasıdır.

Bir isim vardır,

geceye yazarsın, silinmez.

Denize söylersin, dalga alır götürür,

ama kalbin

hiçbir şeyi geri vermez.

Her dalga kıyıya vurduğunda

biraz senden getiriyor sanıyorum.

Deniz seni saklıyor belki,

ama benim gözlerim

seni herkese anlatıyor.

Ey uzaklığın en güzel hâli,

ey dokunamadığım ışığım

Her gece denize bakıyorum,

yakamozlar çoğalıyor,

ben yine seni bir tanesinden ayıramıyorum.

Görünüyorsun…

ama hiçbir gece sana yetişemiyorum.

Belki de aşk dediğin,

bir ışığın peşinde

karanlığı sevmeyi öğrenmektir.

Ben karanlığı öğrendim,

sen ışığını eksik etme…

Yakamozum.

Muhsin yener', 'YAKAMOZUM Gözleri deniz dediler, inanmadım İnsan hiç bir denizde bu kadar kendini kaybeder mi? Ben kayboldum. Üstelik kıyıya çıkmak istemedi...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/yakamozum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-tahir-sariisik-i81kz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fer kalmadı artık bende,

Yoruldum düşmekten derde,

Yıkandı gönül bin kederde,

Yoruldum düşmekten derde.

İnandım aşk denen tuzağa,

Siyah saça, ela göze, gül yanağa,

Savurdu neşeden çok uzağa,

Yoruldum düşmekten derde.', 'Fer kalmadı artık bende, Yoruldum düşmekten derde, Yıkandı gönül bin kederde, Yoruldum düşmekten derde. İnandım aşk denen tuzağa, Siyah saça...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoruldum-626-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hele bir kış gelsin', 'hele-bir-kis-gelsin-basri-erdogan-47v2h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağlar önümüze dikilsin, Hele bir kar yağsın yollarına. Bakalım kim baharı bekler, Kim Ferhat olup vurur dağına.

Hele bir gece bütün kandiller sönsün, Bir kıvılcım düşsün karanlığa. Bakalım kim ellerini ısıtıp döner, Kim Kerem gibi yanar bir Aslı uğruna.

Bir gün de sen bana dönmeyeceğim de, Bakalım o söz kaç yıl dayanır hasrete. Ben Mecnun gibi çöllere düşmem belki, Ama dönecekmişsin gibi çay koyarım her gece.', 'Dağlar önümüze dikilsin, Hele bir kar yağsın yollarına. Bakalım kim baharı bekler, Kim Ferhat olup vurur dağına. Hele bir gece bütün kandill...', ARRAY['Türk Edebiyatı','Şiir','Basri Erdoğan']::text[], 8.5, '{"poet":"Basri Erdoğan","poet_slug":"basri-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/hele-bir-kis-gelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emmolu onu unutmak istiyorum ama unutacak aklım kalmadı', 'emmolu-onu-unutmak-istiyorum-ama-unutacak-aklim-kalmadi-gokhan-gun-e278x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Emmolu onu unutmak istiyorum ama unutacak aklım kalmadı', 'Emmolu onu unutmak istiyorum ama unutacak aklım kalmadı...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gün']::text[], 8.5, '{"poet":"Gökhan Gün","poet_slug":"gokhan-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/emmolu-onu-unutmak-istiyorum-ama-unutacak-aklim-kalmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey gece', 'ey-gece-suleyman-ozguven-xo4sq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EY GECE

Ey gece, söyle sevdiğime, onu çok özledim.

Adını her andığımda içten içe ezildim.

Bir türlü dinmiyor yüreğimdeki bu hasret.

Benim onsuz geçen her gecemde biraz daha yorgun düştü düşlerim.

Ey gece, sen bilirsin kaç zamandır uykusuzum.

Kaç akşamdır gözlerimde biriken yaşla doluyum.

Bir tek ona anlatamadım içimdeki sevdamı.

Oysa ben hâlâ onun sevdasına mahkûmum.

Ey gece, usulca git, düş onun penceresine.

Söyle, hâlâ sevdalıyım o güzel gözlerine.

Bir selamını bekler oldum, bir sesini duymaya.

Hasretinden sarılıyorum gecenin sessizliğine.

Ey gece, söyle ona, buralarda bahar gelmiyor.

Güneş doğsa da gönlüme aydınlık düşmüyor.

Ne yıldızlar teselli oluyor ne ay ışığı.

O yoksa bu gönül hiçbir güzelliği görmüyor.

Ey gece, sor ona, hiç aklına geliyor muyum?

O da benim gibi hasretle yanıp tutuşuyor mu?

Bir şarkının en dokunaklı yerinde durup.

Gözlerini uzaklara dikip beni arıyor mu?

Ey gece, söyle sevdiğime, ben hâlâ aynı yerdeyim.

Ne sevdasından vazgeçtim ben, nede sevdamdan.

Bir ömürlük sevda yükünü gönlüme mühürledim.

O benim kavuşamadığım en güzel sevdam.

Ey gece, ne olur bu gece biraz daha uzun kal.

Benim yerime sevdiğimin saçlarını okşa.

Yastığına düşen sessiz bir gözyaşı ol.

Ve kulağına fısılda, benim şu sözlerimi:

Ben seni çok özledim sevdiğim, hem de öyle böyle değil.

Bir şehir kadar uzak, bir nefes kadar yakınsın bana.

Sana kavuşamadığım her gün ömrümden eksiliyor.

Ey gece, söyle ona…

Bu yürek hâlâ onu seviyor, hâlâ onu bekliyor.', 'EY GECE Ey gece, söyle sevdiğime, onu çok özledim. Adını her andığımda içten içe ezildim. Bir türlü dinmiyor yüreğimdeki bu hasret. Benim on...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Özgüven']::text[], 8.5, '{"poet":"Süleyman Özgüven","poet_slug":"suleyman-ozguven","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ey-gece-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlara da Zıkkımın Kökü Tattırılacaktır', 'onlara-da-zikkimin-koku-tattirilacaktir-i-lyas-ates-i7fta', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya demek savaş demek savaşta yaşam yoktur

yaşamaya çalışmak vardır

Hem savaş hem yaşam bir arada olmayacaktır 

olacağını sanarak hep kendimizi avutmuş olacağız 

Dünyada insanlar çalışarak değil de birbirlerini

yok ederek yaşamaya çalışırlar yok edenler kısa

bir süreliğine yaşarlar ve hesabı öbür tarafa ertelemiş

olurlar ve onlara da zıkkımın kökü tattırılacaktır', 'Dünya demek savaş demek savaşta yaşam yoktur yaşamaya çalışmak vardır Hem savaş hem yaşam bir arada olmayacaktır  olacağını sanarak hep kend...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/onlara-da-zikkimin-koku-tattirilacaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Gelin Sonunda', 'i-ste-gelin-sonunda-yuksel-sari-27tjy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzun zaman oldu görüşmeyeli,

Nice mevsim sessizce gelip geçti.

Şimdi bakıyorum sana, sevgili,

Ne kadar değişmişsin görmeyeli.

Eskiden sen böyle değildin.

Yorgun, bitkin düşmüş bedenin.

Çile çekmişsin, solmuş tenin.

Seni çok üzmüşler, kırılmış kalbin.

Nedir seni böyle üzen, sevgili?

Gözlerin hüzün dolu, kirpiğin nemli.

Yüzüne dokunsam ağlayacaksın.

Yüreğin sızlıyor, kederlisin.

Belli ki benim gibi dertlisin.

Gel, otur karşıma, dök içini.

Sessizce dinlerim seni.', 'Uzun zaman oldu görüşmeyeli, Nice mevsim sessizce gelip geçti. Şimdi bakıyorum sana, sevgili, Ne kadar değişmişsin görmeyeli. Eskiden sen bö...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Sarı']::text[], 8.5, '{"poet":"Yüksel Sarı","poet_slug":"yuksel-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/iste-gelin-sonunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Begonviller', 'begonviller-adnan-hacigumus-rhvnz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir elinden 
güneş tutmuş begonvillerin 
bir elinden deniz yeli
penceremde pembe pembe
yaşama sevinci 
sokulun da göreyim bu gün yanıma
dünya gaileleri', 'bir elinden  güneş tutmuş begonvillerin  bir elinden deniz yeli penceremde pembe pembe yaşama sevinci  sokulun da göreyim bu gün yanıma düny...', ARRAY['Türk Edebiyatı','Şiir','Adnan Hacıgümüş']::text[], 8.5, '{"poet":"Adnan Hacıgümüş","poet_slug":"adnan-hacigumus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/begonviller-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GECE OLUNCA', 'gece-olunca-nebahat-buyukakseker-reukx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı açığa çıkar,
Özgür olur kalpteki duygular.
Zifiri karanlıkta hayalin ve ben,
Depreşir bende hatıran.
Ey nur yüzlüm, gece olunca...


Gözümün önünden gitmez hayalin,
Üşür yokluğunda bedenim.
Ruhum özler seni gece olunca.
Tut artık ellerimi, boş bırakma.
Uzaklaşma artık,gel gir koynuma.
Güzel gözlüm,hasretim gece olunca...', 'Gecenin bir yarısı açığa çıkar, Özgür olur kalpteki duygular. Zifiri karanlıkta hayalin ve ben, Depreşir bende hatıran. Ey nur yüzlüm, gece ...', ARRAY['Türk Edebiyatı','Şiir','Nebahat Büyükakşeker']::text[], 8.5, '{"poet":"Nebahat Büyükakşeker","poet_slug":"nebahat-buyukakseker","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gece-olunca-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derman Sende', 'derman-sende-fatih-ergin-2-q7tnk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ömrüm geçti gurbet elde,
Bir gün yüzüm gülmedi.
Hasret çöktü dağlarıma,
Şu dertlerim hiç dinmedi.

Dert bende, derman sende,
Gelip çare olmadın.
Bak düştüm ben ne hallere,
Hiç halimi sormadın.

Sevdan büktü boynumu,
Yoksa seni ararmıydım.
Bilseydim eger sonumu,
Karlı dağları aşarmıydım.

Dert bende, derman sende,
Gelip çare olmadın.
Bak düştüm ben ne hallere,
Hiç halimi sormadın.', 'Ömrüm geçti gurbet elde, Bir gün yüzüm gülmedi. Hasret çöktü dağlarıma, Şu dertlerim hiç dinmedi. Dert bende, derman sende, Gelip çare olmad...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ergin 2']::text[], 8.5, '{"poet":"Fatih Ergin 2","poet_slug":"fatih-ergin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gurbet-906-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkünler', 'mumkunler-ali-celik-3-8brit', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'MÜMKÜNLER

Ne haber, ne selam, geçmiş seneler

Kalınlaşmış, iyicene eneler

Her sene devrinde, hicran yineler

Kırk yıl gurbettedir, gelir mi gelir

Gençlikte gelen gün, iple çekilir

Rutinlerden, çok da çabuk bıkılır

Yaşlanınca, kulun beli bükülür

Ömrün kıymetini, bilir mi bilir

Sapasağlam insan, yoktur marazı

Yanakları, andırıyor kirazı 

Kimselerin, ona yoktur garazı

İnsan durduk yerde, ölür mü ölür 

Görünüşte yoktur, işin mümkünü

Düşünürsün, uğraşmayıp terkini

İlgililer, değiştirmiş fikrini 

Olmaz sandıkların, olur mu olur

Kriterler çoktur, özellik fazla

Güzel usandırır, kibirle, nazla 

İnsan yetinmeli, helâlden hazla 

Israrla arayan, bulur mu bulur

İnsanlarda vardır, akıl ve fikir

İnsanlar doğuştan, günahsız, bâkir 

Her insan onurlu, edilmez tahkir 

Yaşanandan dersi, alır mı alır 

Bakarsın kötüler, karşılık görmez 

Hakim mahkemede, hiç ceza vermez

Kötülüğe devam, bir nebze durmaz

Hesaplar Ahrete, kalır mı kalır', 'MÜMKÜNLER Ne haber, ne selam, geçmiş seneler Kalınlaşmış, iyicene eneler Her sene devrinde, hicran yineler Kırk yıl gurbettedir, gelir mi ge...', ARRAY['Türk Edebiyatı','Şiir','Ali Çelik 3']::text[], 8.5, '{"poet":"Ali Çelik 3","poet_slug":"ali-celik-3","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mumkunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kokusuz Fesleğen', 'kokusuz-feslegen-omer-yucekaya-2-dekfc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ikide bir senden sonrasını 

sorma bana.

bunu yaz bir kenara

senden sonrası olmadı

olmayacak da…

senden sonra 

sanki bir deniz çekildi içimden 

kıyıda bağlı bir sandal gibi kalakaldım

balıkçı babalarını bekleyen 

hasret kokulu çocuklar gibi 

gözlerimi ufka serip 

hep seni bekledim… hep seni…

maaşını aldığı gün tüketen memurlar gibi

son kuruşuna kadar harcadım kendimi

her gece kendime afili ölümler beğenip

her sabah tütün üstüne tütün sardım

baba yadigarı efkarıma

kokusuz bir fesleğene benzedi ömrüm.

kafesin kapısı açık olsa bile 

kaçmayan kuşlar gibi

ne başka bir yere uçtum 

ne de kimseyi aldım kafesime

yanmaya aht etmiş bir orman gibi

her kıvılcımınıza göz kırptım

ah, dilsiz gecelerimin en içli türküsü

sen ister gel, ister gelme…

her hâlükârda beklerim seni. 

senin aşkından başka bir aşkta

konaklamam.

sana tutsak bir martıyım ben. 

senin denizinden başka bir denizde 

uçamam.', 'ikide bir senden sonrasını  sorma bana. bunu yaz bir kenara senden sonrası olmadı olmayacak da… senden sonra  sanki bir deniz çekildi içimde...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kokusuz-feslegen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum', 'unutamiyorum-fatih-ergin-2-6wokk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç çıkmıyorsun aklımdan,
Bir ben değilim unutamayan.
Ne kadar da uğraştıysam,
Seni bir türlü unutamıyorum.

Sanki sensiz mecnun gibiyim.
Bağlanmazdım sana bilseydim.
Dinle beni ey vefasız yârim,
Ne etsem seni unutamıyorum.

Nere gidem bu yaralı can ile.
Türküler ağlıyor saz ile söz ile.
Gözlerim ağlamayı unutsa bile
Seni bir türlü unutamıyorum.', 'Hiç çıkmıyorsun aklımdan, Bir ben değilim unutamayan. Ne kadar da uğraştıysam, Seni bir türlü unutamıyorum. Sanki sensiz mecnun gibiyim. Bağ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ergin 2']::text[], 8.5, '{"poet":"Fatih Ergin 2","poet_slug":"fatih-ergin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutamiyorum-165-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Gelmez Bahar', 'hic-gelmez-bahar-tahir-sariisik-yaixv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde gezen turnalar,

Nazlı yarden var mı bir haber?

Görürseniz tenhada eğer

Deyin sensiz içtiği keder.

Duysun feryadımı, ahımı,

Almasın günbegün canımı.

Üstümde çift uçan turnalar,

Yalnızlığım şu dağlar kadar,

Yolunu bekler kanlı gözler,

Deyin onsuz hiç gelmez bahar.

Duysun feryadımı, ahımı,

Almasın günbegün canımı.', 'Gökyüzünde gezen turnalar, Nazlı yarden var mı bir haber? Görürseniz tenhada eğer Deyin sensiz içtiği keder. Duysun feryadımı, ahımı, Alması...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-gelmez-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Parmaklıktaki Gül', 'demir-parmakliktaki-gul-tahir-sariisik-b4pku', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uğruna yıllarımı katletmişim,

Ömür boyu hüküm giymişim,

Hücre hücre mahpusundayım,

Demir parmaklarına gül takmışım.

Bir ışık hüzmesine hasretim,

Dört duvar gam rutubetindeyim,

Volta volta hayalini gezmekteyim,

Demir parmaklarına gül takmışım.

Her gece başlar ağır sorgular,

Beni ihbar eder kör kuytular,

Her daim sana firar eder uykular,

Demir parmaklarına gül takmışım.

İsyanlı sükut sırdır dilimde,

Mührü var en mahrem yerinde,

Kan damlayan kalbimin yerine

Demir parmaklarına gül takmışım..', 'Uğruna yıllarımı katletmişim, Ömür boyu hüküm giymişim, Hücre hücre mahpusundayım, Demir parmaklarına gül takmışım. Bir ışık hüzmesine hasre...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demir-parmakliktaki-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhun Bedeni Terk Etmesi', 'ruhun-bedeni-terk-etmesi-i-lyas-ates-54zxj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ölümden korkmuyorum hatta her an her saniye

gelmesini temenni ediyorum 

Hayat boyunca her gün ölenlerin ölümden korkmalarını beklemeyin 

Hayatlarını bir cehennem olarak yaşamış olanların

ölümleri onların kurtuluşudur

Ölümü ruhun bedeni terk etmesi olarak görüyorum 

ruh beden hapishanesinde sürekli cehennemini

yaşamışsa yaşatmışlarsa beden hapishanesinden

kurtulması cehennemden kurtulmasıdır', 'Ölümden korkmuyorum hatta her an her saniye gelmesini temenni ediyorum  Hayat boyunca her gün ölenlerin ölümden korkmalarını beklemeyin  Hay...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruhun-bedeni-terk-etmesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahtsızlar', 'bahtsizlar-tahir-sariisik-5xky9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İşi ters gider doğarken bahtsız olanın,

Tekerine çomak sokulur giderken bahtsız olanın,

Kırılır bir tümsekde çarkı dönerken bahtsız olanın,

Bulgurdan olur Dimyat''a pirince giderken bahtsız olanın.

Balık olsa oltaya takılır yahut ağına balıkçının,

Kuş olsa kör kurşununa gelir keskin nişancının,

Keklik gibi ötse tuzağına düşer bir avcının,

Kesilir nefesi erkenden bahtsız olanın.

Gönlü düşse bir ahu gözlü fettana,

Acımadan kıyılır sevda yüklü canına,

Kervancı olsa haramiler çöker malına,

Yarasına arasa merhem zehir sürülür kanına,

Musallası hazırdır kefenden bahtsız olanın.', 'İşi ters gider doğarken bahtsız olanın, Tekerine çomak sokulur giderken bahtsız olanın, Kırılır bir tümsekde çarkı dönerken bahtsız olanın, ...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bahtsizlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Biz Varız', 'artik-biz-variz-fatih-ergin-2-p95xa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onlar vatan evladı, onlar şehit
Adı önemli mi? Ya Ali, yada seyit.
Ey bayrak uğruna can veren yiğit,
Sen rahat uyu artık biz varız.

Şanlı bayrağımın ay yıldızı,
Üzerine dökülen şehidimin kanı.
Miras bırakılan bu vatanı,
Biz koruyacağız artık biz varız.

Yılmayıp savaşan erler gibiyiz.
Şahlanıp coşan seller gibiyiz.
Hudutlarda al bayrak gibiyiz 
Dalgalanacağız artık biz varız.', 'Onlar vatan evladı, onlar şehit Adı önemli mi? Ya Ali, yada seyit. Ey bayrak uğruna can veren yiğit, Sen rahat uyu artık biz varız. Şanlı ba...', ARRAY['Türk Edebiyatı','Şiir','Fatih Ergin 2']::text[], 8.5, '{"poet":"Fatih Ergin 2","poet_slug":"fatih-ergin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-biz-variz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zelal', 'zelal-omer-yucekaya-2-0gr90', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah Zelal... Herkese şakıyan dilin, hep bana mı lal?

…

Susma, Zelal

Şu pencerende yalvaran rüzgârın hatırına, 

susma…

Sen susunca 

mühürleniyor söze dair ne varsa.

Bir sus mevsiminde cevapsız kalıyor 

bütün soru işaretleri; 

hiçbir sorunun cevabını bulamıyorum.

Hangi çölün merhametine sığınsam, 

tekmil kum fırtınası şaha kalkıyor. 

Kan köpüklü akıyor Fırat’ın suyu 

Bir Kerbela divanında Hüseyin gibi kanıyorum.

Konuş, Zelal… 

Eşkıyanın Keje’sine inat, konuş.

Baktığım her yüzde yüzünü görüp, 

dinlediğim her şarkıda sesini duyarken; 

şarkılar kirlenmeden, 

şiirler kötü yola düşmeden, 

söylencem bitmeden konuş…

Sesinle yeşersin çölüm

Sesin can suyum olsun

Sesin taşlasın içimdeki şeytanı 

Sesin sensizliğin azı dişini söksün.

Susma, Zelal…

Su kattığın rakının hatırına, 

tuz bastığın yaranın hatırına,

ölü toprağı serdiğin sevdanın hatırına, 

susma…

Sen susunca 

şakiler kesiyor yolumu. 

Kırk dağdan kırk kavim, 

yalın kılıç üstüme yürüyor; 

her biri Allahsız, 

her biri kitapsız…

Konuş, Zelal…

Kelimeler sırra kadem basmadan, 

sesinle içime sız. 

İçime…', 'Ah Zelal... Herkese şakıyan dilin, hep bana mı lal? … Susma, Zelal Şu pencerende yalvaran rüzgârın hatırına,  susma… Sen susunca  mühürleniy...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/zelal-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adsız kalma kadınlığım', 'adsiz-kalma-kadinligim-hulya-karadayi-u8pe9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ADSIZ KALMA KADINLIĞIM 

Ses ver güçlülüğüm! 

Sus pus olamazsın sen, 

Yakışmaz sana, 

sıyrıl o sana biçilen  mağdur rolünden, 

korkma, sinme

Mağrursun sen, 

şahlandır damarlarında akan o asil kanı,

Bırak geçmişte korkutulup sindirilme istenen o kadını

Bürün tepeden tırnağa Atamızın nasihatlerini;

Sen ki Aydınlık bir Cumhuriyet Kadınısın,

Cumhuriyetin ilelebet bekçisi

Atamızın bizlere layık gördüğü çağdaş bir Türk Kadını..

Adsız mı kaldın Kadınlığım.. şiirime karşıt bir şiir yazmanın zamanı geldi', 'ADSIZ KALMA KADINLIĞIM  Ses ver güçlülüğüm!  Sus pus olamazsın sen,  Yakışmaz sana,  sıyrıl o sana biçilen  mağdur rolünden,  korkma, sinme ...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karadayı']::text[], 8.5, '{"poet":"Hülya Karadayı","poet_slug":"hulya-karadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adsiz-kalma-kadinligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık', 'artik-ahmet-metehan-pehlivan-d2se9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Renklerin seçilmiyor ey dünya senin
Günümü takvimler sayıyor artık
Sesin tiz, bakışın boş, uzak ellerin
O gözler beni bulmuyor artık.

Issızım, başıboş kimim kimsesiz
Beni bıraktığın yerde bulamazsın artık
Varlığım yokluğumdan daha da sessiz
Sesimi eskisi gibi duyamazsın artık 

Mezarım en içindeyken yerin
Soğuğu beni üşütmüyor artık
En ıssız okyanuslar olsa da derin
Beni daha fazla boğmuyor artık', 'Renklerin seçilmiyor ey dünya senin Günümü takvimler sayıyor artık Sesin tiz, bakışın boş, uzak ellerin O gözler beni bulmuyor artık. Issızı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metehan Pehlivan']::text[], 8.5, '{"poet":"Ahmet Metehan Pehlivan","poet_slug":"ahmet-metehan-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-350-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlerken', 'ozlerken-ahmet-metehan-pehlivan-9xu6t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünü özlerken anladım ayrılıkta var
Belki yarın da yıllar yavaşça akar
Evet biliyorum aramızda belki yillar var
Ama kavuşmak istersen yarında yakın

Akın nehirler yanaklarımdan akın
Yakın dediğim sevdam uzakmış bakın
Bana birdaha aşk demeyin sakın
Yalan sözlere bir daha kanamam

Beni sevdiğini tekrar sanamam
Seni özlesem de geri aramam
Yanamam diyorum tekrar yanamam
Közden alev çıkartmaya çalışma

Vedalara son ver artık alışma
Zihnimdeki yabancıya karışma
Affetsem de gelip benle barışma
Ölemem tekrar tekrar bilirsin', 'Dünü özlerken anladım ayrılıkta var Belki yarın da yıllar yavaşça akar Evet biliyorum aramızda belki yillar var Ama kavuşmak istersen yarınd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metehan Pehlivan']::text[], 8.5, '{"poet":"Ahmet Metehan Pehlivan","poet_slug":"ahmet-metehan-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozlerken-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsar Gemi', 'karamsar-gemi-ahmet-metehan-pehlivan-dxx96', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Alabora olmuş geminin kaptanısın,
Hayallerle dolu bir denizde.
Kayıplarla dolu bir mürettebatın,
Tek umudusun o siste

Alevler içinde bu güverte,
Işığıyla aldatıyor seni.
Kara bir bulut çöküyor yelkenlerin üstüne,
Gelme diyor bir daha geri.', 'Alabora olmuş geminin kaptanısın, Hayallerle dolu bir denizde. Kayıplarla dolu bir mürettebatın, Tek umudusun o siste Alevler içinde bu güve...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metehan Pehlivan']::text[], 8.5, '{"poet":"Ahmet Metehan Pehlivan","poet_slug":"ahmet-metehan-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karamsar-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilrüba', 'dilruba-ahmet-metehan-pehlivan-l87d7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönlüm bu ahvâli ikrara talip
Sükûtum sevdayı firara dahil
Dilrüba! Gönlüme şayet değilsen nail
Gönlüm çalınırken zahirde olma fail.', 'Gönlüm bu ahvâli ikrara talip Sükûtum sevdayı firara dahil Dilrüba! Gönlüme şayet değilsen nail Gönlüm çalınırken zahirde olma fail....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metehan Pehlivan']::text[], 8.5, '{"poet":"Ahmet Metehan Pehlivan","poet_slug":"ahmet-metehan-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dilruba-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kadeh', 'son-kadeh-ahmet-metehan-pehlivan-539bf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazmak isterim de nokta engeller diye beni
Son kelimeden sonra nokta koymadım sevgili
Rüyamda narin narin bakarsın da bana
Rüyada bile sana, doyamadım sevgili

Bazı yaralar kanamadan da yanar
İçten içe yaktın ama kanatmadın sevgili
Silahı boş olan tarafa çeviririz ya hani
O bakışlar bana değil boşa mlydı sevgili

Son kadehi sana ayırdım sevgili
Yarısı göz, yaşı yarısında umut var
Gidişini sigaramla saydım sevgili
Gelişine söyle daha kaç paket var ?', 'Yazmak isterim de nokta engeller diye beni Son kelimeden sonra nokta koymadım sevgili Rüyamda narin narin bakarsın da bana Rüyada bile sana,...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metehan Pehlivan']::text[], 8.5, '{"poet":"Ahmet Metehan Pehlivan","poet_slug":"ahmet-metehan-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-kadeh-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayan Yıldız', 'kayan-yildiz-ahmet-metehan-pehlivan-qcb1z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kayan yıldız gelir mi tekrar?
Çıkan ok yaya döner mi geri?
Sormuştum önceden hatırlarsın de mi?
Bir daha sever misin acaba beni?

Gülen gözleri özler mi insan?
Bu gece de özledim seni 
Sormuştum önceden hatırlarsın de mi ?
Bir daha sever misin acaba beni?

Eskiden sen de severdin ya
Mazide kalan olur mu yeni?
Sormuştum önceden hatırlarsın de mi ?
Bir daha sever misin acaba beni?', 'Kayan yıldız gelir mi tekrar? Çıkan ok yaya döner mi geri? Sormuştum önceden hatırlarsın de mi? Bir daha sever misin acaba beni? Gülen gözle...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Metehan Pehlivan']::text[], 8.5, '{"poet":"Ahmet Metehan Pehlivan","poet_slug":"ahmet-metehan-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kayan-yildiz-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O O Yaratıktır', 'i-ste-o-o-yaratiktir-i-lyas-ates-nlfnh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görüntü bakımından insan suretinde yaratılmış

olanlar insandır kimsede inkar edemez 

Keşke insanın görüntüyle olmadığını fark etseydiler

İnsanın karakterleri bellidir o karakterlere uygun

yaşamış olanlar hem şeklen hemi de manen

insandırlar

Manen insan olamayanlar insan görüntüsü altın da

birer yaratıktırlar hangi yaratığın halleri ondan zuhur

etmişse işte o o yaratıktır', 'Görüntü bakımından insan suretinde yaratılmış olanlar insandır kimsede inkar edemez  Keşke insanın görüntüyle olmadığını fark etseydiler İns...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/iste-o-o-yaratiktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız ayrılık', 'zamansiz-ayrilik-umit-sami-yasar-ipuol', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kadar zamansız bir ayrılık kime nasip olmuş ki?

Kader mi, baht mı, beddua mı bu?

Yoksa Allah''ın unuttuğu bir takvim yaprağında

birbirine geç kalmış iki insan mıyız?

İnsan bazen düşünüyor;

Biz hangi yanlışın cezasını çekiyoruz?

Hangi duanın kabul olmamış tarafıyız?

Hangi gece, hangi yıldızın altında

birbirimize kavuşmayalım diye söz verdik de

haberimiz olmadı?

Oysa ben seni,

ömrümün sonuna sakladığım güzel bir kelime gibi sevmiştim.

Hani bazı kelimeler vardır,

insan söylemeye kıyamaz,

söylese bütün anlamı bozulacak sanır.

Ben de seni öyle sakladım içimde.

Meğer insanın en çok sakındığı şeymiş

en önce elinden alınan.

Şimdi sen başka bir hayatın sabahına uyanıyorsun,

ben hâlâ bizim akşamımızda mahsur.

Sen çoktan değiştirmişsin mevsimini,

bense hâlâ kapının önünde

üşüyen bir sonbahar gibi bekliyorum.

Ne tuhaf değil mi?

Bir insan gidiyor,

ardından bütün şehir taşınıyor sanki.

Aynı sokak, aynı kaldırımlar,

aynı simitçi, aynı vapur düdüğü...

Ama hiçbir şey eskisi gibi değil.

Demek ki şehir dediğin biraz da insanmış;

sevdiğin gidince adresin kalıyor da

memleketin kalmıyormuş.

Bazen kendime kızıyorum.

Bu kadar sevmek de neyin nesi?

İnsan bir kalbe bu kadar eşya sığdırır mı?

Bir bakış, üç beş hatıra,

yarım kalmış bir cümle,

bir de hiç yaşanmamış gelecek...

Hepsini toplasan bir bavul etmez belki

ama insanın sırtında bir ömür taşınır.

Kader diyorum,

belki de kaderin eli titredi bizi yazarken.

Baht diyorum,

belki bizim bahtımıza kavuşmak değil,

birbirimizi özleyerek yaşlanmak düşmüş.

Beddua diyorum sonra...

Yok, kimsenin ahını almadım ben.

Sadece birini çok sevdim.

Galiba bu dünyada insanın başına gelebilecek

en güzel felaket buydu.

Ve biliyor musun,

ben artık kavuşmayı da eskisi kadar istemiyorum.

Çünkü bazı ayrılıklar var,

insan kavuşsa bile bıraktığı yerden devam edemiyor.

Bir zamanlar birbirine yuva olan iki insan,

şimdi aynı kapıdan girse

birbirine misafir kalıyor.

Ama yine de...

Bir gün olur da hayat seni yorar,

bir akşam olur da bütün ışıklar söner,

kalabalıklar dağılır, telefonun susar,

ve sen nedensizce eski bir şarkıya takılırsan...

Sakın kendini suçlama.

Belki de bir yerlerde

benim içimde hâlâ sana ayrılmış bir sandalye vardır.

Yalnız şunu bil:

Biz birbirimizi kaybetmedik aslında.

Biz, birbirimize kavuşabileceğimiz zamanı kaybettik.

Ve insanın en ağır yasını

ölenler için değil,

yaşayabilecekken yaşayamadığı hayatlar için tuttuğunu

ben senden sonra öğrendim.

Çünkü bazı aşklar bitmez sevgilim...

Sadece birbirinin ömrüne yetişemez.

Kimi insanlar birbirine geç kalmaz;

dünya, onları birbirine erken getirip

sonra erkenden ayırır.', 'Bu kadar zamansız bir ayrılık kime nasip olmuş ki? Kader mi, baht mı, beddua mı bu? Yoksa Allah''ın unuttuğu bir takvim yaprağında birbirine ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Sami Yaşar']::text[], 8.5, '{"poet":"Ümit Sami Yaşar","poet_slug":"umit-sami-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/zamansiz-ayrilik-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın kasım hali', 'askin-kasim-hali-umit-sami-yasar-vqt5z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kasımda aşka methiye düzenler var,

ellerinde sararmış yapraklar,

dillerinde büyük büyük sevdalar...

Hiçbir kasımda seni kaybetmediler oysa.

Hiçbir akşam, bir şehrin bütün ışıklarını

bir insanın yokluğuna söndürmediler.

Hiçbir yağmurda, ıslanmamak için değil,

hatıralarına su değmesin diye kaçmadılar.

O yüzden kimse bana

ne kasımdan ne de aşktan bahsetmesin.

Ben kasımı bilirim.

Bir takvim yaprağından ibaret değildir benim için.

Senin gittiğin günün üzerine

otuz gün boyunca çekilmiş siyah bir örtüdür.

Herkes sonbaharı romantik bulur.

Oysa ben bilirim;

ağaçlar yapraklarını keyfinden dökmez,

bazı vedalar vardır,

insanın dallarını içeriden kırar.

Siz kahvenizin üzerine tarçın serpip

kasım şiirleri yazarken,

ben bir fincanın karşısında

iki kişilik susmayı öğrendim.

Siz aşkı, yağmurun cama vurmasında aradınız,

ben yağmur dindiğinde anladım yokluğunu.

Çünkü insan bazen birini özlemez yalnızca,

onunla birlikte kendinde kalan

bütün güzel ihtimalleri de özler.

Bir zamanlar sen vardın.

Dünya dediğin, iki insanın arasına sığacak kadar küçüktü.

Şimdi şehirler büyüdü, yollar uzadı,

ama ben hâlâ aynı yerdeyim.

İnsan bazı adreslerden taşınamıyor,

hele ki o adres bir başkasının kalbiyse...

Şimdi çıkıp da bana

"Kasım aşkın ayıdır" demeyin.

Aşkın ayı mı olurmuş?

Aşk, birinin gidişinden sonra

kapının sesini bile tanımaktır.

Telefon çalmadığı hâlde ekrana bakmak,

kalabalıkta bir yüzü ararken

kendi yüzünü kaybetmektir.

Ve en kötüsü nedir biliyor musunuz?

İnsan bir süre sonra yokluğa da alışıyor.

İşte buna alışmak demeyin sakın,

bu olsa olsa ruhun

kendi enkazına eşya yerleştirmesidir.

Ben seni bir kasımda kaybetmedim belki,

ama hangi kasım gelse

biraz daha kaybettim kendimi.

Şimdi bütün yapraklar dökülebilir,

bütün şairler sonbahara âşık olabilir.

Bütün kaldırımlar şiir, bütün yağmurlar hatıra olabilir.

Ama kimse bana aşktan söz etmesin.

Çünkü ben aşkı bir kadının gözlerinde değil,

o gözlerden sonra bakamadığım

bütün güzelliklerde gördüm.

Ve siz hâlâ kasımda aşkı anlatıyorsunuz...

Oysa benim bildiğim bir şey var:

Bazıları kasımda âşık olur,

bazıları kasımda ayrılır.

Bir de bazıları vardır ki

her kasım yeniden terk edilir.

Ben onlardanım.

Ne mevsime inanırım artık

ne de mevsimlik sevdalara...

Çünkü benim içimde birisi gitti,

takvim hâlâ o günü değiştirmeye cesaret edemiyor.', 'Kasımda aşka methiye düzenler var, ellerinde sararmış yapraklar, dillerinde büyük büyük sevdalar... Hiçbir kasımda seni kaybetmediler oysa. ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Sami Yaşar']::text[], 8.5, '{"poet":"Ümit Sami Yaşar","poet_slug":"umit-sami-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/askin-kasim-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Giderken', 'ben-giderken-muharrem-cihan-akcesme-ujvv2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oku. 

Hattatın nefesle fakirin yüzüne nakşettiği derin kitabeyi

Mülkü çok olanın Hakkak yontar, 

Şerh edemediğin yüzündeki eski alfâbeyi,

Gözlerindeki nur ve yüzündeki çizgiler,

Şu koca külliyatın en sahih tefsiri sanki.

Çevrilen her sayfada duyulan o ince çıtırtı

Yıllanmış eklemlerinin anlaşılmayan sözleri olur.

Şu mülkten “BEN” giderken…

Mürekkepsiz yazılan, 

Okunması zor silik bir yazgıyı nakşeder yüzüne

Hakkak yontarken sükun taşını 

Yüzlerinden tanırsın onları

Şu mülkten “BEN” giderken

O vakit ya gök kubben griye çalar , 

Yâhut seher vaktidir birazdan güneş doğar

Nem verir toprağına, kuru bir ayaz 

Yâhut kokusunu bir senin duyacağın 

Tatlı serin bir meltem.

Gözlerinden süzülen o çiğ taneleri; 

Ya gülden esen o kokunun sevincinden

Ya da göçen kervanın ardından tutulan mâtemden

Şu mülkten “BEN” giderken

Ya gül bahçesinde 

Bembeyaz bir gül daha açar

Gülistanın rengince

Yahut ürkek soluk sarıya çalar tenin 

Kazası olmayan Cuma vakti girince

Ya gül ile misk kokar hayat ile demlenmiş son nefesin 

Yahut is ve duman.

Selvi olur, gül kokar bahçen,

Yahut bedendir son liman.

Şu mülkten “BEN” gidince.', 'Oku.  Hattatın nefesle fakirin yüzüne nakşettiği derin kitabeyi Mülkü çok olanın Hakkak yontar,  Şerh edemediğin yüzündeki eski alfâbeyi, Gö...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Cihan Akçeşme']::text[], 8.5, '{"poet":"Muharrem Cihan Akçeşme","poet_slug":"muharrem-cihan-akcesme","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ben-giderken-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın düştüğü gece', 'zamanin-dustugu-gece-belial-dh7jb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'insan insanı anlayabilir mi
zamanın düştüğü bir gece
kalbim seni hak edebilir mi
rüzgarın taşıdığı fısıltılar
seni bana getirebilir mi

ay ışığında dans eden gölgeler
ay pınarında kalbimi sakinleştirir mi
her haline bayılmış olan gün ışığı
güneşin doğuşuyla aydınlanan iki kalp
ruhumuzda ki çiğ taneleri ve açan güller

sana kavuşmalıyım sessiz bir gecede
kalbimi bırakıp şükretmeliyim
zihnimi arındıran o sözlerinle
kalbimi feda etmeliyim o gözlerine
öp ve sar beni sıcak teninle
birleşelim ay pınarında.', 'insan insanı anlayabilir mi zamanın düştüğü bir gece kalbim seni hak edebilir mi rüzgarın taşıdığı fısıltılar seni bana getirebilir mi ay ış...', ARRAY['Türk Edebiyatı','Şiir','Belial']::text[], 8.5, '{"poet":"Belial","poet_slug":"belial","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zamanin-dustugu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Sen Melekmisin?', 'kiz-sen-melekmisin-omer-baycan-3-u7c1u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fındık dalı arasından,

Gördüm kiraz dudakları.

Yemeni dolanmış dikene,

Yüzüne inmiş saçları.

Kız sen bir melek misin?

Göklere ulaşan dilek misin?

Kokun aklımı başımdan alır,

Mis kokulu çilek misin?

Güneş sana vurur kastı ne?

Gel su doldurayım testine,

Yaklaş bir tadına bakayım,

Sineler taşmış kazak üstüne.

Kız sen bir melek misin?

Göklere ulaşan dilek misin?

Kokun aklımı başımdan alır,

Mis kokulu çilek misin?

Bohçanda ekmeğine aş olayım.

Bir ömür sana yoldaş olayım.

Boyun posun, o incecik belin,

Gir koynuma sana eş olayım.

Kız sen bir melek misin?

Göklere ulaşan dilek misin?

Kokun aklımı başımdan alır,

Mis kokulu çilek misin?

Boynunda öpeyim, busem olsun,

Başkası bakmasın izim kalsın,

Ateşle barut olup, yakalım tarlayı,

Şu okunan türkü bizim olsun.

Kız sen bir melek misin?

Göklere ulaşan dilek misin?

Kokun aklımı başımdan alır,

Mis kokulu çilek misin?

Ömer BAYCAN 20.11.2026', 'Fındık dalı arasından, Gördüm kiraz dudakları. Yemeni dolanmış dikene, Yüzüne inmiş saçları. Kız sen bir melek misin? Göklere ulaşan dilek m...', ARRAY['Türk Edebiyatı','Şiir','Ömer Baycan 3']::text[], 8.5, '{"poet":"Ömer Baycan 3","poet_slug":"omer-baycan-3","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kiz-sen-melekmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkumdur', 'mahkumdur-alperen-yilmaz-2s8af', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorgularken solduruldum; nihai rücu mu bu?
Çiçeklerin kanadığı susuzluk hücumu bu.
Sahrasında serabıyla sınıyor gücümü bu.
Tabirine talip olan ahmak, acze mahkumdur.

Bu fasıla, zaruri bir teslimiyet ilanı...
Çalakalem hülyaların en akılcıl olanı...
Dün kaçkını keşkelerim kaplar oldu alanı.
İşareti yadsınılan parmak acze mahkumdur.

Ezildikçe eziliyor beklentisi altında.
Kıymet yitimi yaşadı kavrayışlar katında.
Namütenâhi imgeler bezgin, haddi zatında...
Sesi kulak tırmalayan ırmak acze mahkumdur.

Abartılı düşünceler hissizleştirdi aklı.
Bir saydam tül ardındayım; gözlemlerim hep farklı.
Tahammülsüz tepkilerim tıyneten tekmil zamklı...
Tattığını zehir bilen damak acze mahkumdur.

Alperen Yılmaz (Yalınkalem)', 'Sorgularken solduruldum; nihai rücu mu bu? Çiçeklerin kanadığı susuzluk hücumu bu. Sahrasında serabıyla sınıyor gücümü bu. Tabirine talip ol...', ARRAY['Türk Edebiyatı','Şiir','Alperen Yılmaz']::text[], 8.5, '{"poet":"Alperen Yılmaz","poet_slug":"alperen-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mahkumdur-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yirmisinde Genç Gibi', 'yirmisinde-genc-gibi-kasim-kobakci-32lc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıktım bugün ben yola, yanımda sabah ekibi,

Adımlarım bozuyor taşlardaki her tertibi,

O kadar heyecanlı, bütün düşlerin talibi,

Yelkeni yeni öğrenen yirmisinde genç gibi.

*

Kahkaham var şen şakrak, güneşe selam çakarım,

Ham meyve koparır da ekşi tadına bakarım,

Orhan Amca, belki ben feneri eksik yakarım,

Ama çaylak hevesle mavi sulara akarım.

*

Çıktım bugün yeniden, güneşli günüm baharda,

Uzun yollar boyu toz, ıslak çimenler kenarda,

Adımlarım çıraktan daha toy gezer diyarda,

Otuzunda düş kuran yolcular gibi bulvarda.

*

Değilim ben onlardan, en başını arıyorum,

Sıvadım kollarımı, serin yeli yarıyorum,

Cemal Amca, belki de ustalığa varıyorum,

O beni bilmese de yüreğimle sarıyorum.', 'Çıktım bugün ben yola, yanımda sabah ekibi, Adımlarım bozuyor taşlardaki her tertibi, O kadar heyecanlı, bütün düşlerin talibi, Yelkeni yeni...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yirmisinde-genc-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbet Mevsim Çiçek Açar', 'elbet-mevsim-cicek-acar-melek-dalgic-2y3vp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Başka bir şehrin zamanından

Çıkıp geldin sandım da 

Ben dünlere baktım 

Bu günün benzeri 

Lakin suçluda benim 

Benim için  bir taşı  yerinden oynatamayan birinden 

Bir kale inşa etmesini bekledim 

Bana kendimi özlettin 

Sensiz sessizlik 

Seninle yaşadığım huzursuzluktan 

Daha sevimli 

Bu sözlerim  istihza da değil 

Olmayacağını gözüme soka soka  gösterdin de 

Sevgi bu ya  çekip gittim oldu mu

Şimdi sana ne 

Hava rüzgar  yağmur kar 

Kışından da sorma burda ne var 

Yaprak dökerse mevsim 

Kompanse eder

Yine bahar gelir 

Mevsim elbet  yine çiçek açar', 'Başka bir şehrin zamanından Çıkıp geldin sandım da  Ben dünlere baktım  Bu günün benzeri  Lakin suçluda benim  Benim için  bir taşı  yerinde...', ARRAY['Türk Edebiyatı','Şiir','Melek Dalgıç']::text[], 8.5, '{"poet":"Melek Dalgıç","poet_slug":"melek-dalgic","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/elbet-mevsim-cicek-acar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-alperen-yilmaz-lv7f7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuyuda ilk gecesi; düşünceli, dolunay.
Masalların ritmine gedik açar konumda.
Zümrüdüanka değil güneşe kanat açan.
Aslanlar yelesizmiş, kedi kaçar konumda.

Süslü takımyıldızı, akar evren nehrince.
Dışlandı her çıkarım, metaforlar şehrince.
Bir melâl tabiri bu, saf okurun sihrince:
Artezyen indindeyse ışık saçar konumda.

Bir düş tadımı şuur eksiltmeli, servetten,
Kırlangıç tüneğeni peykeden, kerevetten...
Bakaya fasiküller, sorulur meşveretten...
Artçı tasavvurlarsa, demek, uçar konumda...

Katedil gökkuşağı, çöl geçmiş ayaklarca!
Kaf dağındaki söğüt eğildi dayaklarca.
Biyografin harcandı telmaşa uyaklarca...
Çöl çiçeği, korkarım, aşka düçar konumda.

Zılgıt zılgıt galeyan ihsan eder kargalar.
"Yarın, yarın..." demekle bilinmezi arkalar.
Şimşek dolu bulutlar, kar küresi çalkalar.
Deniz ardı müşküller artık naçar konumda.

Alperen Yılmaz (Yalınkalem)', 'Kuyuda ilk gecesi; düşünceli, dolunay. Masalların ritmine gedik açar konumda. Zümrüdüanka değil güneşe kanat açan. Aslanlar yelesizmiş, kedi...', ARRAY['Türk Edebiyatı','Şiir','Alperen Yılmaz']::text[], 8.5, '{"poet":"Alperen Yılmaz","poet_slug":"alperen-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/umut-1709-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Güzeldir', 'hayat-guzeldir-i-lyas-ates-ptch3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşayabilenler için hayat güzeldir

Ne kadar kör olursan o kadar yaşarsın

Yaşamak dilersen önce vicdanını öldür ve

yaşa yoksa yaşama sansın olmayacaktır', 'Yaşayabilenler için hayat güzeldir Ne kadar kör olursan o kadar yaşarsın Yaşamak dilersen önce vicdanını öldür ve yaşa yoksa yaşama sansın o...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-guzeldir-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lekesi Bulaşır', 'lekesi-bulasir-remzi-timar-qzn97', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önemli, bak işte bura,

Maya katmalı hamura.

Asla taş atmam çamura;

Lekesi bana BULAŞIR.

Ne sos ister ne de püre,

Sırlar sığdırdım ömüre.

Asla dokunmam kömüre;

Lekesi bana BULAŞIR.

Remzi’m araya araya,

Çare bulursun yaraya.

Asla dokunmam karaya;

Lekesi bana BULAŞIR… 

Remzi Timar

20 – 11 - 2026', 'Önemli, bak işte bura, Maya katmalı hamura. Asla taş atmam çamura; Lekesi bana BULAŞIR. Ne sos ister ne de püre, Sırlar sığdırdım ömüre. Asl...', ARRAY['Türk Edebiyatı','Şiir','Remzi Timar']::text[], 8.5, '{"poet":"Remzi Timar","poet_slug":"remzi-timar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/lekesi-bulasir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doymadık', 'doymadik-ali-esmeray-hoyrat-jwcw8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zamane fıtratı hâsıl olmuşsa tende,

Beşerî kusuru görmezmiş kendinde.

Fitnenin verdiği zararı kâr bendinde,

Ölünün dişini satıp yedik, doymadık.

Öteledik yoksulu, iğrendik, hor gördük,

Lokmasını saydık, kursağa düğümledik.

Bol kepçeyle aldık, kevgirle geri verdik,

Fukara ekmeğini çalıp yedik, doymadık.

Görgüde, kuralda birinciydik biz oysa,

Tangodan sonra da ererdik çılgın vals''a.

Levrekle kalkanı bandırıp acı sosa,

Havyarı şaraba katıp yedik, doymadık.

Mülakat meziyetti saydık hep sebile,

Makam, mevkiiyi verdik hısım Cemile.

Umudu bağladık fanfinfoncu Kâmil''e,

Devlet malını sayıp yedik, doymadık.

Pek çok da coşmuştuk, ne de şen şakrak idik,

Ahlaklı olanın anasını belledik.

Avanta, bedava, beleş lokma bekledik,

Emekçinin hakkını alıp yedik, doymadık.

Hoyrat umut kalmadı, yarından öteye,

Evde mutfak döndü kötüden de kötüye.

Doğalgaz, kesildi kaldık çuldan örtüye,

Turşuyu ekmeğe sardık, yedik, doymadık.

Ali Esmeray (Hoyrat) Geldim', 'Zamane fıtratı hâsıl olmuşsa tende, Beşerî kusuru görmezmiş kendinde. Fitnenin verdiği zararı kâr bendinde, Ölünün dişini satıp yedik, doyma...', ARRAY['Türk Edebiyatı','Şiir','Ali Esmeray Hoyrat']::text[], 8.5, '{"poet":"Ali Esmeray Hoyrat","poet_slug":"ali-esmeray-hoyrat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/doymadik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-nedim-saatcioglu-40kby', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Simsiyah bir kader düştü bahtıma

Ömrüme nur saçan ışıklar söndü

Solmuş bir fotoğraf geçti elime

Bütün mevsimlerim hazana döndü

Yoksun ya, kalbimin telaşı bitti

Yoksun ya, düşlerim toplanıp gitti

Oysa bir bakışın bana cennetti

Bütün mevsimlerim hazana döndü

Dalganın sahili vurması gibi

Saatin bir anda durması gibi

Kalbimi hicranın sarması gibi

Bütün mevsimlerim hazana döndü

Ne yapsam huzurla dolamıyorum

Kendime çıkar yol bulamıyorum

Anladım ben sensiz olamıyorum

Bütün mevsimlerim hazana döndü

Yüreğim göklere uçmuyor artık

Gönlümde bademler açmıyor artık

Ömrüm paramparça anılar yırtık

Bütün mevsimlerim hazana döndü 

Tutmuyor dizlerim tutmuyor elim

Göçebe kuş gibi bağlandı dilim

Yaz değil kış değil nasıl bir iklim

Bütün mevsimlerim hazana döndü', 'Simsiyah bir kader düştü bahtıma Ömrüme nur saçan ışıklar söndü Solmuş bir fotoğraf geçti elime Bütün mevsimlerim hazana döndü Yoksun ya, ka...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hazan-317-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırra Kadem Bastın mi', 'sirra-kadem-bastin-mi-melik-koroglu-9edrs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sırra Kadem Bastı mı

Bu hayata şaştın mı,

Dertlerini aştın mı,

Sana olan kastımı,

Sırra kadem bastın mı?

Kime menzil uzatır,

Kime sanki tuzaktır,

Sanki rahat yasaktır,

Sırra kadem bastın mı?

Yol uzar da görünmez,

Söz sızar da bilinmez,

Gönül yanar, dinemez,

Sırra kadem bastın mı?

Bir iz kalır rüzgârda,

Bir sır saklı baharda,

Sorar durur her yerde:

Sırra kadem bastın mı?

Umut solar dalında,

Sızı kalır yolunda,

Hangi ömür sonuda,

Sırra kadem bastın mı?

Gece çöker, ay sönmez,

Akan yaşlar hiç dinmez,

Bilen var mı, bilinmez,

Sırra kadem bastın mı?

Zaman akar izinde,

Hakikat var özünde,

Söyle gönül, sözünde,

Sırra kadem bastın mı?

Melik Köroğlu (Salihi) Şair ve yazar', 'Sırra Kadem Bastı mı Bu hayata şaştın mı, Dertlerini aştın mı, Sana olan kastımı, Sırra kadem bastın mı? Kime menzil uzatır, Kime sanki tuza...', ARRAY['Türk Edebiyatı','Şiir','Melik Köroğlu']::text[], 8.5, '{"poet":"Melik Köroğlu","poet_slug":"melik-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sirra-kadem-bastin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarılayım Sevdana', 'sarilayim-sevdana-kasim-kobakci-rv4uf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim o dingin iklim, benim o kuytu diyar,

Ünlüdür taş kemerler, meşhurdur o gür pınar,

Benim bu berrak kıyı, benim o solmaz bahar,

Şanlıdır ak konaklar, yücedir ulu çınar.

*

Duy beni canım yarim, gönlüm hep sana tutkun,

Varlığım sana bağlı, gözlerim sana vurgun,

Gelir misin benimle, sular duru ve durgun,

Sığınayım sevgine, ruhuma bir sen uygun.

*

Benim yıldızlı gece, benim o sessiz liman,

Meşhurdur gümüş göller, ünlüdür o sık orman,

Benim o huzurlu ev, benim ışıklı eyvan,

Şanlıdır sedir damlar, engindir mavi umman.

*

Duy beni nazlı yarim, tütüyor bak şen ocak,

Ömrüm sana adanmış, bakışın sonsuz sıcak,

Gelir misin benimle, gezelim bucak bucak,

Sığınayım sevgine, aç bana engin kucak.

*

Benim o sisli vadi, benim o duru seher,

Ünlüdür cam kandiller, meşhurdur o loş fener,

Benim o sakin sokak, benim mermerden kemer,

Şanlıdır taş avlular, zariftir her bir eser.

*

Duy beni gönül eşim, başlasın güzel masal,

Ruhum sana adanmış, gözümde tek bir hayal,

Gelir misin benimle, doğsun artık bu visal,

Sığınayım sevgine, hep benim yanımda kal.

*

Benim o kış bahçesi, benim göklerim beyaz,

Meşhurdur çam odalar, dışarıda sert ayaz,

Benim o sıcak yuva, benim kalbimde hep yaz,

Şanlıdır mum ışığı, usulca çalar bir saz.

*

Duy beni ömür yarim, yüreğim saf ve temiz,

Sevdam sana adanmış, gözlerin mavi deniz,

Gelir misin yanıma, kalsın tüm dünya sessiz,

Sığınayım sevgine, kavuşalım ikimiz.

*

Benim o erguvan bağ, benim açan mor sümbül,

Ünlüdür yaseminler, şakır dalda hep bülbül,

Benim o esen rüzgâr, benim kokladığın gül,

Şanlıdır ak çardaklar, huzurla dolar gönül.

*

Duy beni can yoldaşım, inandım saf sezgine,

Gönlüm sana adanmış, tutkundur gül rengine,

Gelir misin yanıma, kapılalım ezgine,

Sarılayım sevdana, sığınayım sevgine.', 'Benim o dingin iklim, benim o kuytu diyar, Ünlüdür taş kemerler, meşhurdur o gür pınar, Benim bu berrak kıyı, benim o solmaz bahar, Şanlıdır...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sarilayim-sevdana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yer Karanlık', 'her-yer-karanlik-rumeysa-saki-gla2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zemin çok soğuk,

Duvarlar rutubetli 

İnsan sesleri boğuk,

Her yer karanlık. 

Yüzler gülmüyor,

Sanki kalabalık bir mahpus

Kime denk gelsem 

Hala bir yabancı .

Her yer karanlık,

Üstler jilet ama,

Kalpler toz içinde 

Zihinler altüst. 

Düşünceler bataklıkta,

Hayaller gömülmüş toprağa 

Yok bir avuç vicdan 

Her yer karanlık...', 'Zemin çok soğuk, Duvarlar rutubetli  İnsan sesleri boğuk, Her yer karanlık.  Yüzler gülmüyor, Sanki kalabalık bir mahpus Kime denk gelsem  H...', ARRAY['Türk Edebiyatı','Şiir','Rumeysa Şaki']::text[], 8.5, '{"poet":"Rumeysa Şaki","poet_slug":"rumeysa-saki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-yer-karanlik-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takvimden Düşen Aşk', 'takvimden-dusen-ask-mehmet-tevfik-eltas-lv7mi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Takvimde yaprak kalmadı gitti

Kelebek ömür tükendi bitti

Bin sitem bir ahla inledi itti

Bülbülün tezgâhı dinlenen hitti.

Bir rüzgâr eser sevdadan yana

Kırda çiçekler topraktır ana

Vuslatsız sevda aşk adın kana

Al gülün yaprağı yangını cana. 

Takvimde yaprak kalmadı deme

Aşk hatır sayar aşığı yeme.

Bir güzel anı yaşarken dilde

Zaman duruyor yaşadığım ilde

Zulaya işaret çalan bu zilde

Görünür putların yapışan kilde.

Taklit bir hayat üzengi sormaz

Üstüne biner de atını yormaz

Bir acı sevda mutluluk sormaz

Bülbülün yangını gönüller yormaz.

Takvimde yaprak kalmadı deme

Aşk hatır sayar aşığı yeme.', 'Takvimde yaprak kalmadı gitti Kelebek ömür tükendi bitti Bin sitem bir ahla inledi itti Bülbülün tezgâhı dinlenen hitti. Bir rüzgâr eser sev...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tevfik Eltas']::text[], 8.5, '{"poet":"Mehmet Tevfik Eltas","poet_slug":"mehmet-tevfik-eltas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/takvimden-dusen-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum', 'gidiyorum-mehmet-hanifi-erdinc-7xams', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zifiri bir karanlık, göğün yere indiği saat.

Yürüyorum kimsesizliği sırtlamış bir sokakta.

Elimde yarım kalmış bir hayatın tortusu,

İçimde susturulmuş cümlelerin ağırlığı var.

Kar bile kara yağıyor bu şehrin üzerine,

Yorgun kaldırımları adımlarım yüreğimdeki yara ile.

Gözlerimden düşen acı zemheri ayazı eritir

Ağlıyorum, ayıp bilmeden, içimden geldiğince.

Dilimin ucunda yarım yamalak bir türkü,

Yankılanır sesim duvarlarda, çoğalır içimdeki zifir.

Son bir kez bakıyorum siyaha bürünen göğe,

Ay görünmez, yıldızlar küskün, bulutlar ağır.

Ayaklarımda derman kalmamış, nefesim can çekişiyor.

Ey hayat! Duvarına astığın bu emaneti gel, kendi ellerinle al,

Yoksa ben, bu kentin orta yerinden çekip gidiyorum.

Gece yarısı, zifiri karanlık ve katran rengi bir sessizlik.

Bir kimsesiz sokak ortasındayım, kocamış bir ağaç gibi köksüz.

Avucumda zalimin kör baltası, sırtımda yaşanmışlıkların hüznü.

Bakma göğün beyazlaştığına, kar bile kara yağıyor bu kente,

Yorgun kaldırımlarda telaşım, sol yanımda bir yara ile yürüyorum.

Gözyaşım değdiği yeri yakıyor, karı bile eritiyor usulca,

Ağlıyorum işte, yasakları çiğner gibi, edepsizce ağlıyorum.

Dilimde eskilere ait bir türkü, sesim sokaklara sığmıyor,

Yankılandıkça acılardan bir tufan kopuyor içimde.

Başımı kaldırıp da bakıyorum o inatçı gökyüzüne,

Bulutlar simsiyah ne ay var seçilen ne bir dost yıldızı.

Derman kalmadı dizlerimde, nefesim asılı kaldı boğazımda.

Ey kader! vaktidir, gel de al bu emaneti sahibine,

Yoksa ben, bu kahpe düzene inat, çekip gidiyorum.

Gece sarkmış pencerelerden aşağı, simsiyah bir gece.

Yürüyorum adını kimsenin bilmediği o ıssız sokaklarda,

Elimde yarım kalmış bir kavganın külü,

Sırtımda omuzlarımı çökerten yaşanmışlıkların hüznü.

Gökyüzü dağınık, kar bile kara yağıyor üstümüze,

Yorgun kaldırımlarda sol yanımdaki yara ile yürüyorum.

Gözyaşım değiyor buz tutmuş toprağa, ayazı eritiyor,

Ağlıyorum, ayıp bilmeden, içimdeki çocuk çığlığıyla.

Dilimde köhne meyhanelerden kalma en güzel türkü,

Sesim, yankılandıkça çoğalıyor duvarlarda sancılarım.

Kaldırıp başımı bakıyorum göğe ne bir ay ışığı ne de bir yıldız.

Dizlerimin dermanı tükendi, nefesim boğazımda can çekişiyor.

Ey hayat, ey acımasız tezgah!

Vaktidir, gel de al bu emaneti başladığı yere,

Yoksa ben, bu yalan sofrasını devirip gidiyorum.

Saat gece yarısı... Zifiri karanlık, katran karası bir gece,

Kimsesiz bir sokağın orta yerinde, yalnızlığa kura çekiyorum.

Elimde zalimin zulmü, sırtımda yılların kamburu,

Bakma adına kış dediğimize, kar bile kara yağıyor başımıza.

Yorgun kaldırımlarda ömrün telaşı, yüreğimde kanayan yara ile yürüyorum.

Gözlerimden süzülen bir acı, karları eriten bir yangın yeri!

Ağlıyorum işte, kim ne derse desin, edepsizce ağlıyorum.

Dilimin ucunda en güzel, en eski türküler ile,

Yankılanır sesim taş duvarlarda, çoğalır içimdeki fırtına.

Son bir kez dikiliyorum göğün karşısına, bulutlar duman, gök siyah,

Ne Ay var görünen ne bir kılavuz yıldız.

Ayaklarımda derman tükendi, nefesim göğsümde can çekişiyor.

Ey alacaklı dünya! Gel, al artık bu emaneti sahibine,

Gözüm arkada değil, duy sesimi.

Yoksa bak, ben bu zifirî karanlıktan çekip gidiyorum.', 'Zifiri bir karanlık, göğün yere indiği saat. Yürüyorum kimsesizliği sırtlamış bir sokakta. Elimde yarım kalmış bir hayatın tortusu, İçimde s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hanifi Erdinç']::text[], 8.5, '{"poet":"Mehmet Hanifi Erdinç","poet_slug":"mehmet-hanifi-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/gidiyorum-1522-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Tarlaları', 'cehennem-tarlalari-faruk-tosun-0ehsi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nefsim beni yerden yere vuruyor

Şeytan her köşe başında duruyor

Ruhum gelgitler ile kıvranıyor

Cehennem tarlalarına tohum atılıyor

İşlediğin herbir günahın tanesi

İsyanlardaki imansızlığın fidesi

İbadetlerdeki gevşekliğin çekirdeği

Cehennemde büyütüyor ateşini

Cehennemde yoktur diyarlar ateş

Herkes buradan götürürmüş ateş

Senide sevdiklerini içine alan bir ateş

Bu sondan kaçmazsan, içine alır ateş

Zerre iyiliğin varsa korur seni

Zerre kötülüğün varsa yakar seni

Ekme cehennem tarlalarına ateşi

Bu dünya yan ahirette tatma ateşi', 'Nefsim beni yerden yere vuruyor Şeytan her köşe başında duruyor Ruhum gelgitler ile kıvranıyor Cehennem tarlalarına tohum atılıyor İşlediğin...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tosun']::text[], 8.5, '{"poet":"Faruk Tosun","poet_slug":"faruk-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cehennem-tarlalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçim Gider', 'i-cim-gider-yakup-han-kilinc-ew5pd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçim gider içim gider 

Bu dünyadan göçüm gider 

Hergün yârimi görmezsem 

Başımdan tel saçım gider 

Yakuphan Kılınç', 'İçim gider içim gider  Bu dünyadan göçüm gider  Hergün yârimi görmezsem  Başımdan tel saçım gider  Yakuphan Kılınç...', ARRAY['Türk Edebiyatı','Şiir','Yakup Han Kılınç']::text[], 8.5, '{"poet":"Yakup Han Kılınç","poet_slug":"yakup-han-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/icim-gider-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Eylül''üm (bir ömür yetmez)', 'sonsuz-eylul-um-bir-omur-yetmez-recep-turcali-em0pw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SONSUZ EYLÜL''ÜM (Bir Ömür Yetmez) 

Masallar, masallar

Bir kitap olur, anılarda saklanır

Masallar, masallar

Bir gün gelir, sessizce hatırlanır

Zamanla geçer düşlerim

Bir gün seni de unutur muyum?

Her şey geride kalırken

Ben yine seni arar dururum

Bir gün anlarsın hayatı

Neden böyle yaşadığımı

Düşlerimde denizin

Gözlerimde yağmurun

Sesi gelir uzaklardan

Hâlâ çınlar kulaklarımda

Düşlerimin içinde

Bir bahar saklıydı

Her şey yeniden başlarken

Sen yine yanımda olsaydın

Senden başka kimim vardı?

Senden başka kimim kaldı?

Masallar anılarda saklı

Düşlerim seninle yarımdı

Sen giderken yalnız kaldım

Bir ömür gözlerinde kaldım

Yüzün, gözlerin hâlâ benimle

Bir tek sen kaldın düşlerimde

Yağmurun sesi çınlar

Her damlası seni anlatır

Senden gelen her şeye razıyım

Yeter ki anılarımda kal

Senden başka kimim vardı?

Senden başka kimim kaldı?

Masallar anılarda saklı

Düşlerim seninle yarımdı

Sen giderken yalnız kaldım

Bir ömür gözlerinde kaldım

Zamanla geçer düşlerim belki...

Ama sen kalırsın yüreğimde.', 'SONSUZ EYLÜL''ÜM (Bir Ömür Yetmez)  Masallar, masallar Bir kitap olur, anılarda saklanır Masallar, masallar Bir gün gelir, sessizce hatırlanı...', ARRAY['Türk Edebiyatı','Şiir','Recep Turcalı']::text[], 8.5, '{"poet":"Recep Turcalı","poet_slug":"recep-turcali","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sonsuz-eylul-um-bir-omur-yetmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Mantık', 'soguk-mantik-kasim-kobakci-wvv52', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En soğuk mantıkta, durgun bir akıl;

Şaşmaz bir kanıt mı, kesin mi odak?

*

Olaydım, kuşkuyu silen bir neden...

Yoksa, o sarsılmaz kanıttan uzak.

*

Keskin ölçütlerle kurulu eksen,

Savı sınadıkça bilincim berrak.

*

Karmaşık denklemi ayırıp çözen,

Yalın bir yöntem mi, sağlam mı kaynak?

*

Deneyin ufkunda, kusursuz düzen;

Değişmez yasa mı, yetkin ve mutlak?

*

Olsaydım, her bağı kapsayan evren...

Yoksa, bir yasaya sığmayan merak.

*

Somut verilerde işleyen etken,

Gerçeği ölçtükçe paydası ortak.

*

Hesap yetmezken doğruyu hep bilen,

Bitmeyen bir yol mu, geçti mi durak?', 'En soğuk mantıkta, durgun bir akıl; Şaşmaz bir kanıt mı, kesin mi odak? * Olaydım, kuşkuyu silen bir neden... Yoksa, o sarsılmaz kanıttan uz...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/soguk-mantik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin dili', 'gozlerin-dili-sadik-kocabas-jjtos', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin Dili

Bir nazar bir gönüle bilsen neler fısıldar,

Bir nazar bir ömürde nice izler bırakır.

Kimi zaman umutla yarınlara bağlatır,

Kimi zaman kor olur, yürekleri dağlatır.

Sözün bittiği yerde başlar gizli bir lisan,

Çözemez o sırrını aşka düşmeyen insan.

İki kirpik ucunda titrer koca bir cihan,

Bir saniye içinde durur akarken zaman.

Ne mektuplar anlatır ne de yazılan yazı,

Göz bebeklerinde saklı kalbin en derin sızı.

Ne baharlar tüketir ne de dondurur kışı,

Bir ömre bedel olur sevdanın tek bakışı.

Bazen sitem yüklüdür, bazen sessiz bir veda,

Bazen "gitme" diyerek yankılanır havada.

Bir kıvılcım düşer de alev alır sevda,

Kül olur tüm kelimeler o eşsiz manzarada.

Karanlık gecelere doğan eşsiz bir aydır,

Yürekten yüreklere gerilmiş ince yaydır.

Ne akıl kâr eyler ne de mantığı vardır,

Gözlerden kalbe akan o sevdalar ne haldir.

Geçse de mevsimler, değişse de yollar,

Unutulmaz o anı, hep o izi kovalar.

Dil susar, kâğıt susar, biter bütün masallar,

Yine de bir bakışla yeniden başlar aşklar.

Kalemsiz Şair der ki; kâğıda ne hacet var,

Gözlerin yazdığını silemez ki rüzgârlar.

İki damla yaş ile dökülürken mısralar,

Senin tek bir bakışın bin kitabı tamamlar.', 'Gözlerin Dili Bir nazar bir gönüle bilsen neler fısıldar, Bir nazar bir ömürde nice izler bırakır. Kimi zaman umutla yarınlara bağlatır, Kim...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kocabaş']::text[], 8.5, '{"poet":"Sadık Kocabaş","poet_slug":"sadik-kocabas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gozlerin-dili-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kaldın', 'gec-kaldin-tekin-tufan-mir-hccp1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tekrar dönecek olsan ne fayda,

Başka vuracak yer mi bıraktın?

Seninle yaşanan hatıralarda,

Benden geriye kimi bıraktın?

Sensiz geçen her gün ömrümden çaldı,

Gözlerim yollarda çaresiz kaldı!

Bu sevda içimde kanayan yara,

Yaramı saracak, derman mı bıraktın?!

Yıllarca avundum yalan sözünle,

Kül oldum, tükendim kendi közümle.

Artık gelsen bile gülen yüzünle,

Sevecek temiz kalp mi bıraktın?

Şimdi uzaklarda ellerle gül sen,

Benim bu halimi nereden bilsen.

Kapıma dayanıp af bile dilesen,

Dönecek eski beni mi bıraktın?', 'Tekrar dönecek olsan ne fayda, Başka vuracak yer mi bıraktın? Seninle yaşanan hatıralarda, Benden geriye kimi bıraktın? Sensiz geçen her gün...', ARRAY['Türk Edebiyatı','Şiir','Tekin Tufan Mir']::text[], 8.5, '{"poet":"Tekin Tufan Mir","poet_slug":"tekin-tufan-mir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gec-kaldin-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Dağda Kurt Öldü', 'hangi-dagda-kurt-oldu-sevki-ciftci-a8f52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hangi Dağda Kurt Öldü

Aşina değilim bu nasıl rüzgâr,

Hangi dağda kurt öldü söyleyin.

Duyulur mu bilmem içimde efkâr,

Hangi dağda kurt öldü söyleyin.

Kim derdi ki bu iş böyle son bula,

Şaştı kaldı herkes gelen bu yola.

İnanmak güç gelir sağa ve sola,

Hangi dağda kurt öldü söyleyin.

Dönmez denilenler döner geriye,

Akıl sır ermez bir garip hediye.

Görenler soruyor bu hâl ne diye,

Hangi dağda kurt öldü söyleyin.

İhtimal vermezdi kimse  bu işe,

Yerinden oynadı taş değdi dişe.

Akıl ermez oldu bu son deyişe,

Hangi dağda kurt öldü söyleyin.

Sanki kene gibi emer kanımı,

Bu garip gidişat yakar canımı,

Söz bitti, gam sardı dört bir yanımı,

Hangi dağda kurt öldü söyleyin.

Şevki''yim, deftere yazdım şanımı,

Sanki kene gibi emer kanımı,

Bu garip gidişat yakar canımı.

Hangi dağda kurt öldü söyleyin.

Şevki Çiftçi 

28102026', 'Hangi Dağda Kurt Öldü Aşina değilim bu nasıl rüzgâr, Hangi dağda kurt öldü söyleyin. Duyulur mu bilmem içimde efkâr, Hangi dağda kurt öldü s...', ARRAY['Türk Edebiyatı','Şiir','Şevki Çiftçi']::text[], 8.5, '{"poet":"Şevki Çiftçi","poet_slug":"sevki-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hangi-dagda-kurt-oldu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanrılarım', 'sanrilarim-mustafa-ozkaraalp-oct9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana "baba" diyen hey! yabancı,

Korku mu görüyorum senin gözlerinde,

Yıllar yılı dağ bildiğin adamdı,

Bir tekebbür var sanki sözlerinde.

Ne dünüm kaldı, ne de yarınım,

Hiç bitmeyecek mi, bu sanrılarım,

Unutamamaktı hep korkularım,

O şimdi hayal meyal düşlerimde.

Ellerim titrerken tutunacak yer arar,

Gözlerim boşluğa dalar ha dalar,

Hastahane dedikleri gamlı dört duvar,

İsmini bile sildi izlerimde.

Bir zamanlar sırtını yasladığın çınar,

Şimdi kendi gölgesinde sessizce ağlar,

Yabancı bakışlar yüreğimi dağlar,

Son bir derman kaldı dizlerimde.', 'Bana "baba" diyen hey! yabancı, Korku mu görüyorum senin gözlerinde, Yıllar yılı dağ bildiğin adamdı, Bir tekebbür var sanki sözlerinde. Ne ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özkaraalp']::text[], 8.5, '{"poet":"Mustafa Özkaraalp","poet_slug":"mustafa-ozkaraalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanrilarim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İrbaam', 'i-rbaam-hakiki-kabakci-uugcm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İRBAAM

Allah aşkı bırak git tavuk besle

Şu koca dükkanı satma Irbaam

Şarkıyı katletme bu boğuk sesle

Hicaza hüzzamı katma İrbaam

Sana küfredenle ilişkidesin

Dün söylediğinle çelişkidesin

Ne kozlar kaptırdın, neye gebesin

Hiç boş yere nutuk atma İrbaam

Tefekkür ettin mi? Sen niye varsın

Kuyruk olacaksan, neye yararsın

Aman dikkat et ha! Şaşı kalkarsın

Vicdanı körlerle yatma İrbaam 

Ya al ceketini ikile şöyle

Ya da vur masaya fikrini söyle

İki iyilikten birini eyle

Günden güne dibe batma İrbaam

Kabakçı der, şiir sana yazılmış.

Gururun zedeli ruhun ezilmiş

Bakıyorum artık kimyan bozulmuş

Senden erkek çıktı Fatma, İrbaam

HAKİKİ KABAKÇI', 'İRBAAM Allah aşkı bırak git tavuk besle Şu koca dükkanı satma Irbaam Şarkıyı katletme bu boğuk sesle Hicaza hüzzamı katma İrbaam Sana küfred...', ARRAY['Türk Edebiyatı','Şiir','Hakiki Kabakçı']::text[], 8.5, '{"poet":"Hakiki Kabakçı","poet_slug":"hakiki-kabakci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/irbaam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılır mı can canandan', 'ayrilir-mi-can-canandan-rustem-sahin-yfohd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AYRILIR MI CAN CANANDAN? (739)

Kapansa da vuslat yolu 

Hasretin kor etse solu 

Yüreğim hep sevgi dolu

Ayrılır mı can canandan? 

Günümde sen gecemde sen

Satır satır hecemde sen

Ne fark eder sen gelmesen 

Ayrılır mı can canandan? 

Gözlerim hep seni arar 

Gönlümü bir hüzün sarar 

Sensiz dünya neye yarar 

Ayrılır mı can canandan?

Sensizliği gel bana sor 

Sol yanımda sönmüyor kor 

Firkatin ölümden de zor

Ayrılır mı can canandan?

Ellerle eğlenip gülüp 

Yârenini yâdel bilip 

Yaşanan maziyi silip 

Ayrılır mı can canandan?

Senden ayrı halim yaman 

Eksilmez başımda duman 

Kavuşmak olsa da güman 

Ayrılır mı can canandan?

Yaş aksa da hep gözümden

Seviyorum can özümden

ZA''ÎFÎm dönmem sözümden 

Ayrılır mı can canandan?

16 OCAK 2026 İST

ŞİİR:AYRILIR MI CAN CANANDAN?

ŞAİR:TC KÜLTÜR VE TURİZM BAKANLIĞI HALK ŞAİRİ RÜSTEM ŞAHİN (ZA''ÎFÎ)

BESTE& YORUM:,,,,,,,,,?

KİTAPLARI: GÖNÜLDEN DİLE, GEL SEVDİĞİM VE BU HİCRAN YARASI (739)

NOT:Sayfamda paylaştığım tüm şiirlerim kitaplarımda ve Antoloji com''da tescillidir keyifli okumalar.', 'AYRILIR MI CAN CANANDAN? (739) Kapansa da vuslat yolu  Hasretin kor etse solu  Yüreğim hep sevgi dolu Ayrılır mı can canandan?  Günümde sen ...', ARRAY['Türk Edebiyatı','Şiir','Rüstem Şahin']::text[], 8.5, '{"poet":"Rüstem Şahin","poet_slug":"rustem-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ayrilir-mi-can-canandan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Sevdamız', 'bizim-sevdamiz-guven-tekin-urnv3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '​

​Mecnun ki çöllerde feryat figanda,

Leyla''nın aşkıyla döndü şaşkına.

Aklını yitirdi yalan cihanda,

Canını feda etti yar aşkına.

​Ferhat''ın vurduğu gürzün sedası,

Şirin''e ulaştı, deldi dağları.

Bitmedi ömürlük ölüm davası,

Kana bulandı o yeşil bağları.

​Kerem''in bağrından yükselen duman,

Aslı''nın saçında savruldu bitti.

Kaderi zalimdi, vermedi aman,

Ateşin içinde kavruldu bitti.

​Tahir''i attılar dipsiz kuyuda,

Zühre''nin hasreti yaktı özünü.

Kavuşmak mahşere kaldı bu toyda,

Yar için yumdu o son kez gözünü.

​Züleyha sarayda yandı tutuştu,

Yusuf’un aşkıyla akıl da şaştı.

Zindanlar içinde sabır da taştı,

Gözünün yaşını sel etti gitti.

​Mısır’ın sultanı köleydi kuldu,

Züleyha aşkıyla sarardı soldu.

Güzellik tahtını Yusuf’ta buldu,

Kaderi o yara kul etti gitti.

​Destanlar yazıldı dilden dile de,

Aşk dediğin düşmez kolay dile de.

Bizim de sevdamız döndü güle de,

Güven’i Şenay’a kul etti gitti.

​Mecnun’un feryadı çınlar çöllerde,

Leyla’nın hayali gezer yellerde.

Kavuşmak mahşere kalan dillerde,

Aşk denilen koru sel etti gitti.

​Şirin’in aşkıyla kayalar yılan,

Ferhat’ın gürzüdür gerçeğe kalan.

Dünya malı yalan, şöhreti yalan,

Aşk bizi sarsılmaz dal etti gitti.

​Kerem’in bağrını yakan o ateş,

Aslı’nın derdiyle dertleşir güneş.

Tahir’le Zühre’ye kader oldu eş,

Ömrü bir fırfırlı yel etti gitti.

​Karayı ak eden o gizli sırla,

Mecnun yoldaş oldu kurda çakılla.

Ferhat kayaları yardı akılla,

Aşk gelince sabrı yel etti gitti.

​Kerem’in külünden savruldu duman,

Aslı feryat etti, vermedi zaman.

Tahir sandık içre beklerken aman,

Zühre gözyaşını göl etti gitti.

​Bizim de yolumuz buraya düştü,

Gönül Şenay diye yandı tutuştu.

Bunca büyük aşık göklere uçtu,

Bizi bu kervana yol etti gitti.

​Yıllardır kalbimi yoran o sızı,

Şenay''ı görünce söndü apansız.

O benim ömrümün en parlak izi,

Bu Güven Tekin''i koymadı cansız.

​Şenay''ın sevgisi dünyaya bedel,

O geldi, silindi her türlü keder.

Geçmişi unuttum, o bana yeter,

Bizim bu aşkımız bitmez amansız.

​Kerem''i, Tahir''i yakan bu ateş,

Şenay''la Güven''e tam oldu bir eş.

Gönül pencereme doğdu bu güneş,

Bu ulu sevdada kaldık gümansız.

​Her birinin derdi başka bir yara,

Aşıkları çeker her zaman dara.

Gönül ne taht ister ne pul ne para,

Bizi bu sevdada kul etti gitti.

​Güven der Şenay’ım gönlümün tacı,

Onunla silindi geçmişin acı.

Bu bizim aşkımız hepsinin ucu,

Bizi bir bedende can etti gitti.', '​ ​Mecnun ki çöllerde feryat figanda, Leyla''nın aşkıyla döndü şaşkına. Aklını yitirdi yalan cihanda, Canını feda etti yar aşkına. ​Ferhat''ın...', ARRAY['Türk Edebiyatı','Şiir','Güven Tekin']::text[], 8.5, '{"poet":"Güven Tekin","poet_slug":"guven-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/bizim-sevdamiz-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlı Dünya', 'kanli-dunya-muhammed-faruk-kelekci-s37yi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruhum asılı kalmış bir kafesin içinde

Çaresiz bekler çıkmayı aldığım her nefeste

Bu sefer aşk değil beni koyan bu küflü kafese

Bu sefer farklı, maziden kalmış bir hadise

Ademden bize emanet kirli bir elma

Ne komiktir ki insanoğlu taşır bunu gururla 

Nefret denen bu içi boş küfürle

Kirlenmek zorunda mı yalan dünya

Kus kinini kurtul diyor bana şeytan

Zaten sevgi beslemen en büyük hatan

Sevgiye layık olsak yakar mıydı odunu yaratan

Bırakta nefretinde yansın o aptal insan

Ne zerafet lütfetmişler bize bir lisan

O lisanı kullanmaktan aciz bir insan

Ey bana sevgi nedir diye soran

Şu dünya için ne yazık ki koca bir yalan

Herkes kustu kinini artık sıra bende

Gerçi kaç kişi kulak asmış ki hakikatın sesine

Her günahı işle sonra dikil mahşer yerine

 Ve sığın o inanmadığın Tanrının merhametine

Söz bitmez yazarım ömrüm yetinceye

Yine de varamayız doğru bir neticeye

Konuşmasın kimse benle kinim geçinceye 

Son sözümü söylerim beyaz kefeni giyince

Bu kanlı dünya bizden Tanrıya küçük bir hediye', 'Ruhum asılı kalmış bir kafesin içinde Çaresiz bekler çıkmayı aldığım her nefeste Bu sefer aşk değil beni koyan bu küflü kafese Bu sefer fark...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Faruk Kelekçi']::text[], 8.5, '{"poet":"Muhammed Faruk Kelekçi","poet_slug":"muhammed-faruk-kelekci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kanli-dunya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Bir Sonbahar', 'yine-bir-sonbahar-muhammed-faruk-kelekci-zi5ta', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saat sabahın sekizi, güneş doğuyor

İnce bir ayazla havalar soğuyor

İnsanlar bir telaşla sağa sola savruluyor

Yine sıradan bir gün, yine bir sonbahar

Saat sabahın sekizi, güneş mi doğuyor

Sokakta hep aynı yüzler mekik dokuyor

Dışarda sararmış yapraklar bir bir dökülüyor

Yine acınası bir gün, yine bir sonbahar 

Saat sabahın sekizi mi, güneş doğuyor

Saatim yavaş yavaş anlamını yitiriyor

Penceremde güller sararıp soluyor 

Yine amansız bir gün, yine bir sonbahar 

Saat sabahın mı sekizi bilmiyorum 

Uzun zamandır güneşim belirsiz 

Gittiğin günkü kadar biziz, gittiğin gün kadar sekiz

Yine sensiz bir gün, yine bir sonbahar', 'Saat sabahın sekizi, güneş doğuyor İnce bir ayazla havalar soğuyor İnsanlar bir telaşla sağa sola savruluyor Yine sıradan bir gün, yine bir ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Faruk Kelekçi']::text[], 8.5, '{"poet":"Muhammed Faruk Kelekçi","poet_slug":"muhammed-faruk-kelekci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yine-bir-sonbahar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çayı Severim', 'cayi-severim-kasim-kobakci-ui4oc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimi tek kalır soğuk şafakta,

Kimi çay arar o loş ocakta,

Kimi yudumlar sisli sokakta,

Kimi buğuyu izler uzakta.

*

Kimi bekler beş çayı zamanı,

Kimi boş lafla yakar dumanı,

Kimi keyfince seçer harmanı,

Kimi rüzgarda özler limanı.

*

Kimi kış günü demler kor közde,

Bense ararım sırrı tek sözde,

İçten sohbeti okurum gözde,

Çaykolik ruhu saklarım özde.

*

İsterse yatsı olsun seherim,

Dostla dağılsın ağır kederim,

Bu kızıl demde saklı kaderim,

Aşk ile dolan çayı severim.

*

Kimi sessizce oturur handa,

Kimi ilk demi tadar bir anda,

Kimi şen şakrak gülüşür yanda,

Kimi hararet arar bu canda.

*

Kimi hoş bulur gürültü sesi,

Kimi laf taşır budur hevesi,

Kimi doldurur camlı kafesi,

Kimi soğutur sıcak nefesi.

*

Kimi semaver yakar ayazda,

Kimi kar izler soğuk beyazda,

Bense demlenip durgun niyazda,

Zarafet bulmam o yapay nazda.

*

İsterse gece geçsin baharım,

Dostun demine kalır kararım,

İnce bardağı elde sararım,

Sevgiyle pişen çayı ararım.

*

Kimi tek içer kuytu bir yerde,

Kimi çareyi arar her derde,

Kimi uykuyu siler o serde,

Kimi cam ardı çeker bir perde.

*

Kimi bardaklar dizer hep dolu,

Kimi yarenle tutar bir yolu,

Kimi laf açar yorar sağ solu,

Kimi keyfine uzatır kolu.

*

Kimi tandırda demler ateşte,

Kimi çay ister hep saat beşte,

Bense aramam zevki güneşte,

Gerçek lezzeti bulurum eşte.

*

İsterse yatsı soğusun yanım,

Bir yudum demle ısınır kanım,

Dostla şenlenir o eski anım,

Sevdalı çaya feda bu canım.

*

Kimi tek yürür o sessiz karda,

Kimi çay içer ıssız bir garda,

Kimi yudumlar sert bir rüzgarda,

Kimi dem arar kalınca darda.

*

Kimi şen tutar bakır ocağı,

Kimi dolaşır köşe bucağı,

Kimi sohbetle sarar kucağı,

Kimi beş çayı özler sıcağı.

*

Kimi avunur uzun gurbette,

Bense eririm derin sohbette,

Zarif bir seda kalır ülfette,

Çaykolik gönül büyür niyette.

*

İsterse yatsı gelsin haberim,

Soğuk geceye sıcak siperim,

Sevgiyle yanan gizli fenerim,

Dostla içilen çayı severim.', 'Kimi tek kalır soğuk şafakta, Kimi çay arar o loş ocakta, Kimi yudumlar sisli sokakta, Kimi buğuyu izler uzakta. * Kimi bekler beş çayı zama...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/cayi-severim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-muhammed-faruk-kelekci-5p0ya', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün ansızın çıkarım hayatından

Belki anlamazsın neden çekip gitti

Belki de farketmezsin benim eksikliğimi

Ama bir gün ansızın çıkarım hayatından

Çok yorulmuşumdur belki mecalim yoktur

Kim bilir belki karnım yalanlara toktur

Hani olur ya belki derdim dermanından çoktur

Bir gün ansızın çıkarım hayatından

Susmak ağır gelmiştir belki artık

Belki de hep aynı konuları konuşmaktan bıktık

Ya da bilmiyorum belki rahat değildir yastık

Bir gün ansızın çıkarım hayatından

Hani belki suç bende değildir bu sefer

Belki Tanrı yazmıştır bana da kara bir kader

Belki de çok güzel görünmüştür bugün seher

Rahi saymadı ki kaç sen gitti zamanımdan

Belki de bu kez ben çıkarım ansızın hayatından', 'Bir gün ansızın çıkarım hayatından Belki anlamazsın neden çekip gitti Belki de farketmezsin benim eksikliğimi Ama bir gün ansızın çıkarım ha...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Faruk Kelekçi']::text[], 8.5, '{"poet":"Muhammed Faruk Kelekçi","poet_slug":"muhammed-faruk-kelekci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ansizin-289-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medeni', 'medeni-muhammed-faruk-kelekci-ri3uw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne güzel bir hayat ne güzel bir dünya

Her yer kuş, deniz her yer derya

Bir gözüm bulut bir gözüm bâtıl kaya 

Fakat ruhumuz pis, nefsimiz kara

Kaç güzellik hakim kainatı tanımaya

Kaç zerafet vekil mutlu sonu aramaya

Kaç hilafet sebep kanlı sofra kurmaya 

Kaç sefalet sonuç kin ile oturup kalkmaya

Oysa ne güzel sevebilmek üzmeden kalbi

Nereye kadar sürecek insanlığın harbi 

Kan, vahşet bu mudur beşer olmanın bedeli

Ölmek değil, yaşamakmış ademin eceli

Rahi düşünmez artık bitirmek için kederi

Söyleyin kaç ben gerekli, düzeltmek için benliği

Bir cevap bulsa Muhammed, giyer miydi beyaz kefeni

Gördük ki şeytan hepimizden daha medeni', 'Ne güzel bir hayat ne güzel bir dünya Her yer kuş, deniz her yer derya Bir gözüm bulut bir gözüm bâtıl kaya  Fakat ruhumuz pis, nefsimiz kar...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Faruk Kelekçi']::text[], 8.5, '{"poet":"Muhammed Faruk Kelekçi","poet_slug":"muhammed-faruk-kelekci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/medeni-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahım senindir', 'ahim-senindir-murat-acer-lw737', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AHIM SENİNDİR

Gideceğim diyorsun; yollar senindir.

Vazgeçtim diyorsun; karar senindir.

Zaten hiç yanımda olmadın ki sen;

Dilimde sitemim, ahlar senindir.

​Hangi gün yüzüme sahiden güldün;

Ne zaman sevgime bir huzur verdin?

Hep aldın, eksilttin, sen çok tükettin;

Un ufak ettiğin ömrün tozu senindir.

​Tek taraflı sevda benim payımdı;

Uğrunda ziyan olan günlerim, aylarım, yıllarımdı.

Menfaatin bitti; her şey yarıda kaldı;

Gâvur gibi yediğin kul hakkım senindir.

​Nasıl sitem etmem sana, nasıl söylenmem;

Severken aşkıma çok zulmettin sen.

Şimdi gidiyorsun arkana dönüp bakmadan;

Aşkımı gömdüğün kabir, mezar senindir.

​En ağır tokadı sen attın bana;

Kapanmaz yaralar bıraktın bana.

Zaten dönülmüyor eski zamana;

Tanıdığım güne öfkem, lanetim senindir.

​Bir gün pişman olup sakın dönme geriye;

Bıraktığın enkazım olsun sana hediye.

Aklından geçsem de düşünme bile;

Ziyan ettiğin ömrümün ahı senindir.

MURAT ACER', 'AHIM SENİNDİR Gideceğim diyorsun; yollar senindir. Vazgeçtim diyorsun; karar senindir. Zaten hiç yanımda olmadın ki sen; Dilimde sitemim, ah...', ARRAY['Türk Edebiyatı','Şiir','Murat Acer']::text[], 8.5, '{"poet":"Murat Acer","poet_slug":"murat-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ahim-senindir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çivi Çiviyi Söker mi', 'civi-civiyi-soker-mi-omer-yucekaya-2-3plkx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kanatmadan nasıl açılır 

bir yaranın sargı bezi

kristal kadehler gibi kırılmışken

incitmeden nasıl kaynar 

öfkenin kemikleri

bir ömre sığmayan bu aşkı 

bir şehrin karanlığına gömüp

adını fısıldayan bu sokakları ve 

bu şehri ardımda bıraksam 

o göç telaşında 

aşkım da gelir mi benimle o şehre

teninden başka bir tene dokunup

günahın kösnül düğmesini çözmeye kalksam 

çivi çiviyi söker mi

yeni ten 

eski teni öldürür mü 

olmaz biliyorum da hadi olsa…

başka bir kadına sırılsıklam aşık olsam

eski kalpten 

yeni bir aşk çıkar mı sence

çıkmaz

kavimler göçü gibi 

başka bir şehre göçsem bile 

daha ben gelmeden 

senin gölgen düşüyor 

gittiğim her şehre

adından başka bir adı 

seslenecek olsam

bir çıtırtıya havalanan kuşlar gibi 

ismin uçuşuyor dudaklarımdan', 'kanatmadan nasıl açılır  bir yaranın sargı bezi kristal kadehler gibi kırılmışken incitmeden nasıl kaynar  öfkenin kemikleri bir ömre sığmay...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/civi-civiyi-soker-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece Sana Varırım', 'bir-gece-sana-varirim-yucel-ozku-i2nd2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİR GECE SANA VARIRIM

Bir gece çıkıp gelsem yoluna,

Ay ışığı düşse pencerene.

İçimde sakladığım o sevdayı,

Sessizce bıraksam ellerine.

Belki gözlerinle anlarsın beni,

Sözlerim bir tebessümde erir.

Sensiz geçen bunca yılın ardından,

Bir bakışın bahar olur içimde.

Bir gülüşün değse yüreğime,

Kışın ortasında çiçekler açar.

Sen yanımda olsan bir akşam,

İçimdeki bütün özlemler susar.

Bir turna geçse uzak dağlardan,

Kanadında saklı kalsa selamım.

Rüzgâra bıraksam özlemimi,

Ulaşır belki sana sevdam.

Belki kavuşmak uzak bir düş bize,

Belki yollar bizi buluşturmaz.

Kalbimde açık kalan pencere,

Mevsimler değişse de kapanmaz.

YÜCEL ÖZKÜ

20 Kasım 2026/11:12', 'BİR GECE SANA VARIRIM Bir gece çıkıp gelsem yoluna, Ay ışığı düşse pencerene. İçimde sakladığım o sevdayı, Sessizce bıraksam ellerine. Belki...', ARRAY['Türk Edebiyatı','Şiir','Yücel Özkü']::text[], 8.5, '{"poet":"Yücel Özkü","poet_slug":"yucel-ozku","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-gece-sana-varirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çobanı da Tanırım', 'cobani-da-tanirim-fikret-adimol-sc3yz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sürü doydu, kurt doldu yazı,

Çobana kader kara yazı,

Sevilir mi baharı, yazı,

Ele mevsim, bana belaymış.

Ele mevsim, bana belaymış.

Güderim melali, itim yok,

Bilirim yöreyi, mülküm yok,

Olanın hiç de veresi yok,

Ele dünya, bana kiraymış.

Ele dünya, bana kiraymış.

Analık hasta, baba göçtü,

Duran durdu, gerisi çöktü,

Miras değil, kalanı yüktü,

Ele umar, bana yaraymış.

Ele umar, bana yaraymış.

Okusam harf bilmem, görmedim,

Gitsem yol bilmem, bilemedim,

Doğrusu neymiş işitmedim,

Ele irfan, bana mayaymış.

Ele irfan, bana mayaymış.

Çobanlık mı garibanlık mı?

Doğduk eyvallah, yaşadık mı?

Adımol da kim tanıdık mı?

Ele değil, bana soraymış.

Ele değil, bana soraymış.', 'Sürü doydu, kurt doldu yazı, Çobana kader kara yazı, Sevilir mi baharı, yazı, Ele mevsim, bana belaymış. Ele mevsim, bana belaymış. Güderim ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Adımol']::text[], 8.5, '{"poet":"Fikret Adımol","poet_slug":"fikret-adimol","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cobani-da-tanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Filozof 9', 'gelecek-filozof-9-ask-askin-sehri-ordu-9m6k1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sorgulanmamış hayat yaşanmaya değmez; fakat sorgulandığı hâlde değiştirilmemiş hayat, insanın kendi aklına ihanetidir.

Filozof

Sorgulamak başlangıçtır, gereğini yapmak ise düşüncenin hayata karşı sorumluluğudur.

Alizm

İnsanın düşünsel asaleti, neyi sorguladığında değil, anladığı şey uğruna hayatında neyi değiştirebildiğinde ölçülür.

Filozof

Sorgulamak, insanı bilinçlendirir; fakat sorguladıklarının gereğini yapmak, insanı değiştirir. Düşünce eyleme dönüşmediğinde farkındalık bile zamanla bir konfor alanına dönüşebilir.

Sokak

Sorgulanmamış hayat yaşanmaya değmez; fakat sorgulandığı hâlde değiştirilmemiş hayat, insanın kendi aklına ihanetidir.

Sokak

Sorgulamak başlangıçtır, gereğini yapmak ise düşüncenin hayata karşı sorumluluğudur.

Filozof

İnsan yalnızca düşünmediği için değil, düşündüklerinin gereğini yapmadığı için de kendine yabancılaşır.

Sanat

Bir hayatı anlamak için sorgulamak yetmez; anladığın gerçekliğin karşısında nasıl durduğun da önemlidir.

Filozof

Sorgulamak zihnin cesareti, uygulamak karakterin cesaretidir.

Filozof

Düşüncelerini davranışlarına dönüştüremeyen insan, kendi zihninde tamamlanmamış bir hayat yaşar.

Sanat

İnsan bazen gerçeği bilmediği için değil, bildiği hâlde değiştirmeye cesaret edemediği için mutsuzdur.

Aşk

Farkındalık, değişimin kendisi değildir; yalnızca artık mazeret üretemeyeceğin noktadır.

Sokak

Kendini çözümlemek kolaydır; kendinle yüzleşmenin sonuçlarını yaşamak zordur.

Sokak

İnsan, kaçtığı soruların değil, cevaplarını bildiği hâlde ertelediği kararların esiridir.

Aşk

En büyük zihinsel çelişki, neyin yanlış olduğunu bilip aynı hayatı sürdürmektir.

Sokak

Düşünce, davranışta zarafet kazanmadıkça yalnızca zihinsel bir gösteriştir.

Aşk

Entelektüellik, çok soru sormak değil; ulaştığın bilginin sorumluluğunu taşıyabilmektir.

Sokak

Bir insanın düşünsel derinliği, söylediklerinden ziyade bildikleri uğruna göze alabildiklerinde saklıdır.

Filozof

Bilinç, insana yalnızca görme ayrıcalığı değil, gördüğünü değiştirme yükümlülüğü de verir.

Sanat

Fikirleriyle yaşayan değil, fikirlerinin gereğini yaşayabilen insan kendi karakterinin mimarıdır.

Sanat

Hayat, sorularla açılan bir kapıdır; fakat o kapıdan geçmeye cesaret edemeyen, ömrünü eşikte tüketir.

Alizm

İnsan kendi karanlığını sorgulayabilir; ama ışığa yürümüyorsa aydınlanmış sayılmaz.

Alizm

Bazıları hayatı anlamak için düşünür, bazıları anladığı hayatı değiştirmek için yaşar.

Alizm

Zihninde binlerce yol keşfedip hiçbirine yürümeyen insan, ömrünü kendi düşüncelerinin haritasında kaybeder.

Alizm

Sorgulamak aynaya bakmaktır; değişmek, aynada gördüğün insanla vedalaşabilmektir.

Sanat

Sorguladığın hâlde değiştirmediğin hayat, cehaletten daha ağır bir çelişkidir.

Filozof

Bilmek insanı masum kılmaz; aksine, bildiği hâlde yapmadıklarından sorumlu kılar.

Sokak

Düşünmek özgürleştirir sanılır; oysa düşüncelerinin gereğini yapamayan insan, kendi bilincinin mahkûmudur.

Devlet

Sorgulamakla yetinen insan, değişimin entelektüel seyircisidir.

Sanat

Cevaplarını bulduğun soruların gereğini yapmıyorsan, aslında hâlâ aynı sorunun içinde yaşıyorsun demektir.

Devlet

İnsan bazen bilgisizliğinden değil, bilgisine rağmen değişmeyen karakterinden kaybeder.

Devlet

Sokrates insanı sorgulamaya çağırdı; fakat sorgulamanın nihai değeri, insanın kendi yaşamını aklın rehberliğinde yeniden kurabilmesindedir.

Filozof

Bilinç, nedenleri anlamakla başlar; özgürlük, o nedenlerin zorunlu kıldığı değişimi gerçekleştirmekle derinleşir.

Filozof

İnsan kendisini ne kadar tanırsa tanısın, arzularını aklın süzgecinden geçirmediği sürece kendi özgürlüğünü tamamlayamaz.

Filozof

Gerçeği aramak felsefedir; bulduğun gerçeğin gereğini yaşamak ise felsefenin hayata dönüşmesidir.

Filozof

Sorgulanmamış hayat yaşanmaya değmez; fakat sorguladığı hâlde gereğini yapmadığın hayat, kendi bilincine verdiğin en büyük tavizdir.

Sokak

Cehalet insanı sorgulamaktan alıkoyar; korkaklık ise sorguladığı gerçeğin gereğini yapmaktan.

Sokak

Sorgulamak zihnin uyanışıdır; eyleme geçmek varoluşun tutarlılığı. İkincisi olmadan birincisi, tamamlanmamış bir özgürlük arayışıdır.

Sanat

İnsanın düşünsel asaleti, neyi sorguladığında değil, anladığı şey uğruna hayatında neyi değiştirebildiğinde ölçülür.

Sokak

Bilinç, yalnızca anlamakla değil, anladığının sorumluluğunu üstlenmekle değer kazanır.

Sanat

İnsanın en büyük çelişkisi bazen neyi yapması gerektiğini bilmemesi değil, bildiği hâlde yapmamayı seçmesidir.

Filozof', 'Sorgulanmamış hayat yaşanmaya değmez; fakat sorgulandığı hâlde değiştirilmemiş hayat, insanın kendi aklına ihanetidir. Filozof Sorgulamak ba...', ARRAY['Türk Edebiyatı','Şiir','Aşk Aşkın Şehri Ordu']::text[], 8.5, '{"poet":"Aşk Aşkın Şehri Ordu","poet_slug":"ask-askin-sehri-ordu","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/gelecek-filozof-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gizli Sevgilim', 'ey-gizli-sevgilim-kasim-kobakci-xeymh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur sesiyle andığım, ey gizli sevgilim benim,

Bana dönerse bir gece kalbin, ürperir bu tenim,

Değişmeyecek unutma, içimde saklı desenim.

Karanlıkta kor gibiydik, sönmedik ki biz, her gece,

Sislerden uzak kıyıda, can cana, o sessiz hece.

*

Eski dalgalı limanda, belirir o solgun yüzün,

Bana gelirse yeniden, rüzgarlı kokusu güzün,

Eksilmeyecek bilirsin, kalbimden bu saklı hüzün.

Loş bir fenerdik çünkü biz, yanardık siyah sularda,

Gölgelerde taş sokakta, omuz omuza yollarda.

*

Karanlıkla andığım, ey sevgilim, bakışın serin,

Bana açılırsa yine, gönlündeki sevda derin,

Bozulmayacak inan ki, ruhumdaki eski yerin.

Suskun yankıydık çünkü biz, çınlardık keskin ayazda,

Karlarda ıssız vadide, baş başa duru beyazda.

*

Dumanlı loş odalarda, sana çıkar yanık sözüm,

Bana değerse uzaktan, bir bakışın, harlar közüm,

Savrulmayacak unutma, fırtınada benim özüm.

İki dalgaydık çünkü biz, kavuşurduk sert yellerde,

Koynunda gece vaktinin, yan yana meçhul ellerde.

*

Karanlık sular üstünde, seni arar kısık sesim,

Bana seslenirsen eğer, sende can bulur nefesim,

Kırılmayacak bil ki sen, sana dair tek hevesim.

Bir duman gibiydik biz de, tüterdik eski ocakta,

Dağlarda köhne bir handa, diz dize bunca uzakta.

*

Sevgilim sisle andığım, ey benim uzak diyarım,

Bana yaklaşırsa kalbin, yeniden doğar baharım,

Sarsılmayacak bil bunu, ömür boyu bu kararım.

İki gölgeydik çünkü biz, saklandık zaman koynunda,

Ormanda tenha kıyıda, kol kola sevda yolunda.

*

Akşam yeliyle andığım sevgilim, eski kederim,

Bana erişirse bir gün sularla, senden haberim,

Kararmayacak unutma, seninle açan seherim.

Sönmez bir mumduk çünkü biz, titrerdik ağır dumanda,

Kıyılarda taş köprüde, göz göze ıslak limanda.

*

Soğuk camlarda andığım, ey, sevgilim benim canım,

Bana dönerse yolların, şenlenir bu mahzun yanım,

Unutmayacak inan ki seni, tek bir an, zamanım.

Bir türküydük çünkü biz de, yankılandık tek yürekte,

Düşlerde uzun gecede, el ele aynı dilekte.

*

Sükutla her an andığım, sevgilim eşsiz hayalim,

Bana çevrilirse eğer gözlerin, dirilir halim,

Tükenmeyecek bil ki sen, beklediğim o visalim.

Bir yıldızdık çünkü biz de, sönmez o iz, hâlâ bende,

Uzak ellerde can cana, sevgilim benim, hep sen de.', 'Yağmur sesiyle andığım, ey gizli sevgilim benim, Bana dönerse bir gece kalbin, ürperir bu tenim, Değişmeyecek unutma, içimde saklı desenim. ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ey-gizli-sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Millete Kalkan O Elleriniz Kırılsın', 'bu-millete-kalkan-o-elleriniz-kirilsin-yakup-han-kilinc-4xw9q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nedir bu öfke denen duygu içinizdeki 

Artık nihayet olsun ülkem nolur durulsun 

İnsan tüyü değil mi sizin saçınızdaki 

Bu millete kalkan o elleriniz kırılsın 

Yakuphan Kılınç', 'Nedir bu öfke denen duygu içinizdeki  Artık nihayet olsun ülkem nolur durulsun  İnsan tüyü değil mi sizin saçınızdaki  Bu millete kalkan o e...', ARRAY['Türk Edebiyatı','Şiir','Yakup Han Kılınç']::text[], 8.5, '{"poet":"Yakup Han Kılınç","poet_slug":"yakup-han-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bu-millete-kalkan-o-elleriniz-kirilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Adım Bir Halkın Yarasıdır', 'benim-adim-bir-halkin-yarasidir-emir-ergin-koc-o36au', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BENİM ADIM BİR HALKIN YARASIDIR

            ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

    **Bir Emir Ergin Koç Kalemin ''den**

            ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Ben ki dağların alnına yazılmış eski bir yazıyım,

 Zagros’un bağrında saklı bin yıllık bir sızıyım.

 Dicle’nin suyuna düşmüş yetimlerin ağıdıyım,

 Tarihin unuttuğu değil, susturamadığı bir halkım.

 Nice saltanatlar göçüp gitmiş bu topraklardan,

 Ben hâlâ anamın dilinde yaşayan bir hatırayım.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Benim geçmişim sarayların altın kapısında değil,

 Bir çobanın kavalında, bir dengbêjin sesindedir.

 Medlerin adı kalmış zamanın eski defterinde,

 Mervânîlerin gölgesi Diyarbakır’ın surlarındadır.

 Tahtların ömrü biter, hükümdarların adı silinir,

 Bir halkın asıl tarihi analarının hafızasındadır.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Ahmedê Xanî bir sevdayı emanet etmiş zamana,

 Mem’in ahı karışmış Zîn’in döktüğü gözyaşına.

 Bir kavuşamamanın ömrü sığmamış destanlara,

 İki yürekten bir memleketin hasreti taşmış dağlara.

 O günden beri her ayrılıkta bir başka yara kanar,

 Bir âşığın feryadı bazen bir halkın kaderine ağlar.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Bir vakit Selahaddin yürümüş Kudüs yollarına,

 Adı karışmış tarihin en çetin zamanlarına.

 Nice hükümdar gelip oturmuş dünyanın tahtına,

 Kimi adalet bırakmış, kimi zulüm ardında.

 Ben kılıçların şanından çok şunu öğrendim:

 İnsan, mazluma uzattığı elle kalır yarınlara.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Sonra bir gün kalem çekmişler dağların arasına,

 Kardeşin yolunu düşürmüşler başka bir sınıra.

 Bir yanım Amed’de kalmış, bir yanım Mahabad’da,

 Bir yanım Hewlêr’de ağlamış, bir yanım Rojava’da.

 Haritalar değişse de dağların göğsünde,

 Aynı ninni uyurmuş anaların dudaklarında.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Mahabad’ın sabahında bir umut çiçek açmış,

 Daha baharı görmeden üstüne hazan yağmış.

 Kadı Muhammed’in ardından meydanlar susmuş,

 Bir halkın yarım kalan düşü darağacına asılmış.

 Sanmışlar ki bir insanla bütün umutlar ölür,

 Meğer her kaybın ardından başka bir ağıt doğarmış.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Dersim’in dağlarında bir başka keder saklı,

 Her taşın göğsünde yarım kalmış bir ömür vardı.

 Kimi evladını aradı, kimi anasının mezarını,

 Kimi bir daha göremedi çocukluğunun baharını.

 Bir dere akıp gider, götürür yılların izini,

 Ama su bile silemez toprağın hafızasını.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Halepçe’de bir sabah gökyüzü zehre kesmiş,

 Bir çocuğun gülüşü daha dudağında sönmüş.

 Anası sarılmış ona, son nefesinde üşümüş,

 Bir evin bütün yarınları aynı anda tükenmiş.

 Ey dünya, hangi bahar örter bu kara günü?

 Hangi yağmur yıkar bir annenin gözündeki ölümü?

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Roboskî’de kar yağmış, yollar beyaza bürünmüş,

 Otuz dört canın ardından ocakların ateşi sönmüş.

 Bir ana kapıda beklemiş, gözleri yola dönmüş,

 Her gelen ayak sesinde yeniden ölüp dirilmiş.

 Ölenin toprağı vardır, bekleyenin neresi?

 Bir ananın yüreğinde kaç mezar açılır, kim bilir?

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Şengal’de bir sabah kopmuş anaların feryadı,

 Dağlara sığınmış çocukların yarım kalan hayatı.

 Bir kızın saç örgüsünde kalmış evinin kokusu,

 Bir annenin avucunda kaybolmuş evladının eli.

 Laleş’in kandilleri titrerken karanlık gecede,

 Her alevde bir kaybın adı yanmış sessizce.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

Ben anamın ağzından dökülen ilk kelimeyim,

 Ninemin masalında büyüyen eski bir ezgiyim.

 Bir gün kendi dilimde susmayı öğrettiler bana,

 Ben sustukça içimdeki dağlar konuştu ardımdan.

 Ne başkasının ekmeğinde gözüm oldu bir gün,

 Ne yabancı bir toprağa hükmetmek istedim.

 Ben yalnız kendi adımla yaşamak isteyenim,

 Çünkü insan anasından aldığı sesi terk edemezmiş.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Ey tarih, biraz da yetimlerin gözünden bak,

 Bir babanın dönmediği akşamları anlat.

 Sürgünde yaşlanmış bir ananın ellerini,

 Gurbette mezar olmuş gençlerin hayallerini anlat.

 Yalnız hükümdarların zaferlerini yazma,

 Bir lokma ekmeğe hasret kalan çocukları da anlat.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Ben acımı bir başka halka düşmanlık diye taşımam,

 Bir annenin gözyaşını başka bir anadan ayırmam.

 Türk ağlasa yüreğim sızlar, Arap ağlasa susamam,

 Fars’ın yetimi üşürken kendi çocuğumu ısıtamam.

 Ama benim anamın gözyaşını da görsün bu dünya,

 Ben başkasının hakkını çiğnemem, kendi hakkımı da   bırakmam.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Bir gün bütün silahlar susar, bütün savaşlar biter,

 Dağların yamacında yeniden çocuk sesleri yükselir.

 Bir ana kapısında korkmadan evladını bekler,

 Bir çocuk kendi dilinde ilk türküsünü söyler.

 Benim bütün kavgam işte o sabaha varmak içindir,

 İnsanın insana yabancı olmadığı bir ömür içindir.

⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

 Sorarsanız hangi dağın, hangi toprağın evladıyım,

 Ben anamın duasında saklı kalmış bir hatırayım.

 Yüzyılların omzuma yüklediği ağır bir mirasım,

 Ne başkasının efendisiyim ne de kimsenin esiriyim.

 Ben Kürdüm!

 Bir halkın hafızasından geleceğe yürüyen sesiyim.

 Beni inkâr eden çağlar oldu, unutan tarihler geçti;

 Ama ben hâlâ buradayım.

 Bir halkın yarası, direnci ve hafızası olarak.

 Ne senden üstünüm, ne senden eksiğim;

 Aynı göğün altında, aynı dünyanın insanıyım.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Emir Ergin Koç', 'BENİM ADIM BİR HALKIN YARASIDIR             ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂     **Bir Emir Ergin Koç Kalemin ''den**             ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂  Ben ki dağların aln...', ARRAY['Türk Edebiyatı','Şiir','Emir Ergin Koç']::text[], 8.5, '{"poet":"Emir Ergin Koç","poet_slug":"emir-ergin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":117,"source_url":"https://www.antoloji.com/bir-halkin-yureginde-sakli-tarih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Yol Yok', 'baska-yol-yok-sair-halaoglu-dgue2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'And İçmişler Ezecekler 

Bunun Kurtuluş Yolu Yok

Kanımızı İçecekler

Bunların Doyacağı Yok 

Mecliste Altı Yüz Tane

İnsan Görünümlü Kene

Kapı Kapı Hane Hane

Soyacaklar Başka Yol Yok 

Yarın Tek Tek Hepimize 

Altın Kaplı Dişimize 

Malımıza Mülkümüze 

Çökecekler Başka Yol Yok 

Biz Devletin Kasasını 

Doldurduk Onlar Boşalttı

Herkesin Ev Arsasını 

Alacaklar Başka Yol Yok 

Cep Delindi Boştur Kesem 

Evde Süngerimi Yesem 

İsyan Edip Açım Desem 

Vuracaklar Başka Yol Yok 

Kanı Etmez Beş Paralık 

İtlerle Oldum Davalık 

Altımda ki Don İcralık 

Soyacaklar Başka Yol Yok 

Bu Gün Ona Yarın Sana 

Deme Dokunmazlar Bana

Verdikleri Makarna''na

Sıra Gelir Başka Yol Yok 

Ne Maden Var Nede Bir Yer

Hep Satıldı Birer Birer 

Ülkemizden Teker Teker 

Sürecekler Başka Yol Yok 

Kendini Satma Soğana 

Sebep Olma Her Doğana

HalaOğlu Bundan Yana

Susar Artık Başka Yol Yok 

Şair_HalaOğlu', 'And İçmişler Ezecekler  Bunun Kurtuluş Yolu Yok Kanımızı İçecekler Bunların Doyacağı Yok  Mecliste Altı Yüz Tane İnsan Görünümlü Kene Kapı K...', ARRAY['Türk Edebiyatı','Şiir','Şair Halaoğlu']::text[], 8.5, '{"poet":"Şair Halaoğlu","poet_slug":"sair-halaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/baska-yol-yok-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tohumun Türksü, Harman Yeri', 'tohumun-turksu-harman-yeri-mehmet-cobanoglu-514bp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '​Açılır yeryüzü, döner karanlık; ardında aydınlık çıkar üste
Ve sabahın ucunda uyanır saban
Toprağı yarar türkü söyler gibi
Öküzler koşulur boyunduruğa
Evlek evlek olan arazide
Köylü dayı tutar sabanın ucunu
Nasır tutan elleri
Toprağın kardeşi
Alnında ter, dilinde bir duayla
Sürer toprağı
Bekler tohum
Sabırla toprağa ekilmek için
Bir saban
İki öküz
Bir boyunduruk
Ve bir köylü
Birbirine ne güzel yakışır

Güneş erkenden toprağın alnında öperken
Saban yaşar günün ilk hamlığını
İlk yorgunluğunu
Köylü dayı
Avucunda saklı tuttuğu
Abrel tohumunu
Sessizce eker tarlaya
Ve
Toprak kucaklar
En derin yerinde, ekilen tohumu
Bir avuç buğday, bir yudum suda saklanır

Saban sürer toprağı, tohumu toprağı yoklar sabırla
Can suyu gıdım gıdım yürür köke
Günler sonrasında
Altın bir başak eğilir rüzgâra
Sabrın ve emeğin
En ağır uykusunda bereketleşir...

Yaz gelmiş, sararmış başaklar boy boy
Hilal orak elde parlar
Biçer tarlayı
Sapla birlikte başak düşer yere
Harman sapla dolmaya başlar
Harman yerinde
Döven döner ağırca
Toz kalkar
Güneş düşer taneye
Döven döndükçe
Ağır ağır çakmak taşlarıyla
Kırılır kabuklar
Ayrılır samanla taneler
Teç (saman yiğini)
Ay ışığında
Ya da gün ortasında
Yabayla göğe doğru savrulur
Estikçe serin yel
Sarı renkli saman rüzgârda savrulur
Samandan ayrılan
Ağır buğday taneleri
Harman yerinde sabırla, umutla buluşur

Doldurulur buğday çuvala, ağızları sıkıca bağlanır
Çuvallar imeceyle yüklenir
Sırtlara ya da arabaya
Yol değirmene uzanır
Kalan saman yığını,
Kışın mala alaf (yem) olur
İstiflenir mereğe özenle, kokusu mis gibi etraf yayılır

Yel esmiş; yabayla savrulmuş toz da, saman da
Her savruluşta biraz daha arınmış hayat
Çünkü bir kere uyanmış
Kuru toprağın içinde
Filizlenen tohum
Bekleyen o ilk çatlakta can bulmuş

Nadasa bırakılan tarlanın toprağı
Dinlenmiş birkaç ay
Güneş ve yağmurla yaptığı
Gizli sözleşmeyle
Hazırlarlamış yarını sessizce
Hasat zamanına
Bu hikayede
Çuvallar şişmiş taneyle
Terle
Emekle
Düğümü sıkı, yükü ağır, bereketi bol
Omuzda taşınan
Bir ömrün ağırlığı
Her dikişinde sabır saklayan çuvallar, sevincin hası olmuş

Ve harmanın kıyısında
Köylü dayının
Gözlerinde toprağın
Çizgileri
Ellerinde nasırın
Şerefi
Tütün tabağını açıp
Bir sigara sararken ağır ağır
Bakarken ufka
Uyanan sabaha
Filizlenen umuda gülümserken
Sofrasında birkaç yeşil soğanı ekmeğine katık ederken...

​Mehmet Çobanoglu
20.11.2026
İstanbul', '​Açılır yeryüzü, döner karanlık; ardında aydınlık çıkar üste Ve sabahın ucunda uyanır saban Toprağı yarar türkü söyler gibi Öküzler koşulur ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çobanoğlu']::text[], 8.5, '{"poet":"Mehmet Çobanoğlu","poet_slug":"mehmet-cobanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/tohumun-turksu-harman-yeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Kasım 61', 'ask-kasim-61-ask-askin-sehri-ordu-scxuh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni sevmek,

Bir sabahın sessizliğinde adını düşünmek,

Güne henüz kimse dokunmamışken

İçimde sana yer açmak gibi…

Bazen hiçbir şey söylemeden özlüyorum seni,

Ne bir şarkı açıyorum

Ne de geçmişi çağırıyorum.

Yalnızca gözlerimi kapatıp

Seninle yaşayabileceğim günleri düşünüyorum.

Aşk

Seninle Bir Başka Güzel

Seni sevmek, Bir sabahın sessizliğinde adını düşünmek, Güne henüz kimse dokunmamışken İçimde sana yer açmak gibi…

Bazen hiçbir şey söylemeden özlüyorum seni, Ne bir şarkı açıyorum Ne de geçmişi çağırıyorum. Yalnızca gözlerimi kapatıp Seninle yaşayabileceğim günleri düşünüyorum.

Bir evimiz olsun istiyorum, Penceresinde yağmur, balkonunda çiçekler, Akşamları birbirimize anlatacağımız hikâyeler, Sabahları uykulu gözlerle gülüşmeler…

Hayat bütün acelesiyle geçip giderken Biz birbirimize yetişelim. Herkes bir yerlere varmaya çalışırken Birbirimizin yanında kalmayı başaralım.

Sana öyle büyük sözler vermek istemiyorum; Büyük sözler bazen rüzgârda savrulur. Ben küçük şeylerde sevmek istiyorum seni, Üşüdüğünde üzerini örtmek, Üzüldüğünde yüzünü güldürmek, Mutlu olduğunda mutluluğuna ortak olmak…

Yıllar sonra bir akşam, Saçlarına düşen beyazları okşarken Bugünleri hatırlayalım. Bir zamanlar birbirimizi özlediğimizi, Kavuşmak için hayaller kurduğumuzu, Ve sonunda o hayallerin içinde Birlikte yaşamayı öğrendiğimizi…

Benim senden yana dileğim, Ne kusursuz bir hayat Ne de hiç bitmeyen baharlar.

Yalnızca seninle olsun ömrümün mevsimleri; Yağmurunda ıslanayım, Güneşinde ısınayım, Hazanında sana sarılayım…

Çünkü ben seni bir mevsimlik değil, Bütün mevsimlerim olsun diye sevdim. 

Aşk

Bir evimiz olsun istiyorum,

Penceresinde yağmur, balkonunda çiçekler,

Akşamları birbirimize anlatacağımız hikâyeler,

Sabahları uykulu gözlerle gülüşmeler…

Hayat bütün acelesiyle geçip giderken

Biz birbirimize yetişelim.

Herkes bir yerlere varmaya çalışırken

Birbirimizin yanında kalmayı başaralım.

Aşk

Yıllar sonra bir akşam,

Saçlarına düşen beyazları okşarken

Bugünleri hatırlayalım.

Bir zamanlar birbirimizi özlediğimizi,

Kavuşmak için hayaller kurduğumuzu,

Ve sonunda o hayallerin içinde

Birlikte yaşamayı öğrendiğimizi…

Aşk

Benim senden yana dileğim,

Ne kusursuz bir hayat

Ne de hiç bitmeyen baharlar.

Yalnızca seninle olsun ömrümün mevsimleri;

Yağmurunda ıslanayım,

Güneşinde ısınayım,

Hazanında sana sarılayım…

Çünkü ben seni bir mevsimlik değil,

Bütün mevsimlerim olsun diye sevdim.

Aşk

Bir Gün Bütün Yollar Sana Çıkacak

Seni düşünmekle başlıyor bazı sabahlar, Henüz güneş pencereme değmeden İçimde bir yer seninle aydınlanıyor. Sanki dünya, bütün güzelliklerini Senin adınla yeniden yaratıyor.

Bilmiyorum, insan birini Ne kadar özleyebilir bir ömür boyunca; Ama ben seni, Henüz yaşamadığımız günlerin içinden bile Özleyebiliyorum.

Bir gün aynı yağmurun altında yürüyeceğiz, Şemsiyeyi unutmuş olacağız belki, Saçlarımız ıslanacak, ayakkabılarımız çamur… Ama sen güleceksin, Ben o gülüşe bakıp Dünyanın bütün eksiklerini unutacağım.

Sana anlatacak çok şeyim var sevgilim, Biriktirdiğim hayaller, yarım kalan cümleler, Gece yarısı aklıma düşen güzellikler… Hepsini seninle paylaşmak istiyorum. Çünkü mutluluk, İnsanın içinde büyüyen bir şey değil yalnızca; Paylaştıkça ömrüne yayılan bir güzellik.

Ben seninle yaşlanmayı değil sadece, Seninle genç kalmayı da istiyorum. Yıllar geçsin, dünya değişsin, Yeni şehirler, yeni insanlar, yeni hayatlar… Ama birbirimize baktığımızda İlk karşılaşmanın heyecanı Hâlâ içimizde bir yerden başlasın.

Bazen uzak olsan da Sana yakın hissettiğim bir dünya var. Ne mesafeler değiştirebilir onu Ne zaman eksiltebilir Ne de hayatın beklenmedik yolları…

Çünkü ben kalbimde sana Bir adres değil, bir hayat kurdum.

Ve bir gün bütün yollar sana çıkacak, Bütün bekleyişler bir gülüşte bitecek. Ben sana kavuştuğumda Belki hiçbir şey söylemeyeceğim…

Sadece sarılacağım.

Çünkü bazı kavuşmaların en güzel cümlesi, İnsanların birbirine hiç bırakmadan sarılmasıdır. 

Aşk

Bir gün aynı yağmurun altında yürüyeceğiz,

Şemsiyeyi unutmuş olacağız belki,

Saçlarımız ıslanacak, ayakkabılarımız çamur…

Ama sen güleceksin,

Ben o gülüşe bakıp

Dünyanın bütün eksiklerini unutacağım.

Sana anlatacak çok şeyim var sevgilim,

Biriktirdiğim hayaller, yarım kalan cümleler,

Gece yarısı aklıma düşen güzellikler…

Hepsini seninle paylaşmak istiyorum.

Çünkü mutluluk,

İnsanın içinde büyüyen bir şey değil yalnızca;

Paylaştıkça ömrüne yayılan bir güzellik.

Aşk

Ben seninle yaşlanmayı değil sadece,

Seninle genç kalmayı da istiyorum.

Yıllar geçsin, dünya değişsin,

Yeni şehirler, yeni insanlar, yeni hayatlar…

Ama birbirimize baktığımızda

İlk karşılaşmanın heyecanı

Hâlâ içimizde bir yerden başlasın.

Aşk

Bazen uzak olsan da

Sana yakın hissettiğim bir dünya var.

Ne mesafeler değiştirebilir onu

Ne zaman eksiltebilir

Ne de hayatın beklenmedik yolları…

Çünkü ben kalbimde sana

Bir adres değil, bir hayat kurdum.

Ve bir gün bütün yollar sana çıkacak,

Bütün bekleyişler bir gülüşte bitecek.

Ben sana kavuştuğumda

Belki hiçbir şey söylemeyeceğim…

Sadece sarılacağım.

Çünkü bazı kavuşmaların en güzel cümlesi,

İnsanların birbirine hiç bırakmadan sarılmasıdır. 

Aşk

Eğer bir gün bana

“Bunca zaman ne aradın?” diye sorarsan,

Gözlerine bakıp gülümseyeceğim.

“Ben bir ömür aradım,

Meğer bir ömrün en güzel yeri

Senin yanında olmakmış.

Aşk

Sana bakarken geleceği düşünüyorum;

İçinde senin olduğun her ihtimal

Bana güzel geliyor.

Bir ev, bir pencere, yağmurun sesi,

Masada iki fincan,

Ve yıllar geçse de

Birbirine anlatacak şeyleri bitmeyen iki insan…

Aşk

Gel, ömrümüzü aceleye vermeyelim.

Bir sabah kahvemizi ağır ağır içelim,

Bir akşam yürüyüşünde kaybolalım,

Bazen hiçbir yere yetişmeden

Birbirimize yetişelim.

Aşk

Kalbimin Sana Çıkan Yolu

Seni sevmek biraz yağmur beklemek gibi, Gökyüzü ne kadar uzak olsa da İçimde bir yer hep sana açık. Bir damlan düşse ömrüme, Bütün kuraklığım unutulur.

Seninle konuşurken Dünyanın sesini biraz kısıyorum, Çünkü en güzel şeyleri Kalbim senin yanında duyuyor. Bir bakışın yetiyor bazen, Günlerdir içimde biriken yorgunluğu Sessizce alıp götürmeye.

Ben seni yalnızca güzel günlerde sevmedim, Hüzünlü akşamların da Adını koyamadığım duyguların da İçinden geçerek sevdim. Birlikte gülebilmek kadar Birbirimizin suskunluğunu anlayabilmeyi de Aşkın en güzel yanı bildim.

Gel, ömrümüzü aceleye vermeyelim. Bir sabah kahvemizi ağır ağır içelim, Bir akşam yürüyüşünde kaybolalım, Bazen hiçbir yere yetişmeden Birbirimize yetişelim.

Sana bakarken geleceği düşünüyorum; İçinde senin olduğun her ihtimal Bana güzel geliyor. Bir ev, bir pencere, yağmurun sesi, Masada iki fincan, Ve yıllar geçse de Birbirine anlatacak şeyleri bitmeyen iki insan…

Benim aşkım büyük cümlelerden değil, Her gün sana dönmekten oluşuyor. Dün seni sevmiş olmam, Bugün yeniden sevmeme engel değil; Aksine, her geçen gün Sana duyduğum sevgiyi daha iyi tanıyorum.

Bir gün zaman bütün güzellikleri değiştirse, Gençliğimizi alıp başka yıllara taşısa, Ben yine elini tutmak isterim. Çünkü seni sevmek Bir yaşın, bir mevsimin, bir anın duygusu değil; Benim hayata bakışımın en güzel hâli.

Sen benim kalbime düşen bir aşk değil, Kalbimin bundan sonra yürümek istediği yolsun. 

Aşk

İnsan, evrenin büyüklüğü karşısında

Kendini küçücük hisseder;

Bir yıldızın ömrü, bir gezegenin dönüşü,

Sonsuzluğun ölçülemeyen mesafesi…

Bütün bunları düşünürken

Bir tek senin gözlerinde kaybolmayı ister.

Aşk

Kalbin Sessiz İspatı

İnsan, evrenin büyüklüğü karşısında Kendini küçücük hisseder; Bir yıldızın ömrü, bir gezegenin dönüşü, Sonsuzluğun ölçülemeyen mesafesi… Bütün bunları düşünürken Bir tek senin gözlerinde kaybolmayı ister.

Ne garip, sevgilim; Aklım evrenin sınırlarını sorgularken Kalbim senin bir gülüşine sığabiliyor. Bütün varoluşu anlamaya çalışan düşüncelerim Senin yanında tek bir şeye dönüşüyor: Seni sevmek.

Belki insanın en büyük çelişkisi budur; Her şeyi bilmek ister, Ama sevdiğinin yanında Bilmediği bir mutluluğa razı olur. Sana neden bu kadar bağlandığımı Bütün nedenleriyle açıklayabilirim belki, Ama hiçbir açıklama Sana duyduğum hissin kendisi olamaz.

Seni sevmek, Aklımın kabul ettiği bütün sınırları aşmak değil; Aklımın ulaşamadığı yerde Kalbimin incelikle durabilmesidir.

Bir gün ayrılığın ihtimali Düşüncelerime uğrarsa, Seni kaybetme korkusuyla değil, Seninle yaşanmamış güzelliklerin hüznüyle İçim sızlar.

Çünkü ben senden Sonsuzluk sözü değil, Sonsuzluğu aratmayacak kadar güzel Birlikte yaşanmış anlar istiyorum.

Bir sabah gözlerini aç, Yanında olayım. Dünya bütün sorularıyla kapımızda beklesin, Biz henüz cevap vermeyelim. Birbirimize bakalım, Ve hayatın bazen Anlaşılmadan da güzel olabileceğini görelim.

Belki evrenin bütün sırları çözülemeyecek; Ama ben senin yanında, Çözülmesi gerekmeyen bir güzelliği buldum.

Seni seviyorum; Aklım bunun nedenlerini ararken, Kalbim çoktan Seninle yaşanacak bir ömrü seçti. 

Aşk

Sevebilmenin Cenneti

Cehennem nedir, diye sorsalar, Bir yer tarif etmem sana; İnsanın bir kalbi olup da O kalbe kimseyi alamaması derim.

Sevmek isteyip sevilmemek değil yalnız, Birini sevme ihtimalini bile yitirmek, Gözlerinin önünden hayat geçerken Hiçbir güzelliğe dokunamamak…

Ben seni sevmekle kurtulmadım dünyadan, Aksine, dünyaya daha çok bağlandım. Sabahların neden aydınlandığını, Yağmurun neden güzel yağdığını, Bir insanın neden durup dururken gülümsediğini Seninle öğrendim.

İnsan bazen kendi karanlığını Bir başkasının ışığında tanır. Ben de içimde sakladığım bütün eksiklikleri Senin sevginde gördüm; Ve ilk defa eksik olmak değil, Tamamlanmaya açık olmak güzeldi.

Sana karşı kusursuz değilim, Bunu bilmeni isterim. Bazen susarım, bazen yanlış anlarım, Bazen kendi düşüncelerimin içinde kaybolurum. Ama sevgim, bütün bu kusurların arasında Sana doğru yürümekten vazgeçmeyen En dürüst yanımdır.

Çünkü sevmek, Birini kendi mutluluğuna mahkûm etmek değil; Onun özgürlüğünü incitmeden Hayatında kalabilmektir. Bir insanın kalbini kazanmak kadar O kalbin huzurunu koruyabilmektir.

Şimdi anlıyorum, Cehennem yalnızca acı çekmek değil; Sevginin mümkün olduğunu bilip Onu yaşayacak cesareti bulamamaktır.

Ve cennet, Uzaklarda aranan bir yer değil; İki insanın birbirini değiştirmeye çalışmadan, Birbirinin hayatına güzellik katarak Yan yana yaşayabilmesidir.

Ben seninle cenneti düşlemiyorum sevgilim; Seni severken, Dünyanın cehenneme dönüşmesine izin vermeyen Bir insan olmayı düşlüyorum. 

Aşk

Cehennem nedir, diye sorsalar,

Bir yer tarif etmem sana;

İnsanın bir kalbi olup da

O kalbe kimseyi alamaması derim.

Sevmek isteyip sevilmemek değil yalnız,

Birini sevme ihtimalini bile yitirmek,

Gözlerinin önünden hayat geçerken

Hiçbir güzelliğe dokunamamak…

Aşk

Ben seni sevmekle kurtulmadım dünyadan,

Aksine, dünyaya daha çok bağlandım.

Sabahların neden aydınlandığını,

Yağmurun neden güzel yağdığını,

Bir insanın neden durup dururken gülümsediğini

Seninle öğrendim.

Aşk

İnsan bazen kendi karanlığını

Bir başkasının ışığında tanır.

Ben de içimde sakladığım bütün eksiklikleri

Senin sevginde gördüm;

Ve ilk defa eksik olmak değil,

Tamamlanmaya açık olmak güzeldi.

Aşk

Sana karşı kusursuz değilim,

Bunu bilmeni isterim.

Bazen susarım, bazen yanlış anlarım,

Bazen kendi düşüncelerimin içinde kaybolurum.

Ama sevgim, bütün bu kusurların arasında

Sana doğru yürümekten vazgeçmeyen

En dürüst yanımdır.

Çünkü sevmek,

Birini kendi mutluluğuna mahkûm etmek değil;

Onun özgürlüğünü incitmeden

Hayatında kalabilmektir.

Bir insanın kalbini kazanmak kadar

O kalbin huzurunu koruyabilmektir.

Aşk

İnsan bazen bütün ömrünü

Bir şeylerin eksikliğini hissederek geçirir;

Ne aradığını bilmeden,

Bulduğu hiçbir şeyde uzun süre kalamadan…

Sonra biri gelir,

Hayatına değil, düşüncelerine dokunur.

Bir akşamın anlamını değiştirir,

Bir sabahı beklenir kılar,

Ve insan ilk defa

Yarınla kavga etmeden yaşamayı öğrenir.

Aşk

Sevmek, Bir İnsanın İçinde Dünyayı Değiştirmektir

İnsan bazen bütün ömrünü Bir şeylerin eksikliğini hissederek geçirir; Ne aradığını bilmeden, Bulduğu hiçbir şeyde uzun süre kalamadan…

Sonra biri gelir, Hayatına değil, düşüncelerine dokunur. Bir akşamın anlamını değiştirir, Bir sabahı beklenir kılar, Ve insan ilk defa Yarınla kavga etmeden yaşamayı öğrenir.

Ben sende bir mutluluk aramadım, Mutluluğun nasıl bir şey olduğunu Seninle yeniden keşfettim. Bir insanın varlığına alışmak değil, Onun varlığından her gün yeniden etkilenmekmiş Sevmenin en güzel tarafı.

Bazen seni düşünürken Kendi hayatımı sorguluyorum; Ne kadarını gerçekten yaşadım, Ne kadarını korkularımın içinde erteledim? Kaç güzel sözü söylemeden bıraktım, Kaç duyguyu gururuma emanet ettim?

Sen bana sevgiyi öğretmedin belki, Ama sevgisiz geçen zamanın Ne kadar büyük bir kayıp olduğunu gösterdin.

Şimdi senden uzak bir günün içinde bile Sana yakın bir düşünce taşıyorum. Bir şarkıda, bir sokakta, Bir fincan kahvenin soğuyan son yudumunda Seni hatırlamak değil bu; Hayatın her ayrıntısına Seninle anlam verebilmek.

Sana sahip olmak istemiyorum, Seninle birbirimize ait hissettiğimiz O güzel özgürlüğü yaşamak istiyorum. Ne sen benim sınırlarımda kaybol Ne ben senin dünyanı daraltayım; Birbirimizin hayatına sığmayacak kadar büyüyelim, Ama birbirimizden uzaklaşmayacak kadar sevelim.

Çünkü insanın en büyük zenginliği Birini kendine bağlamak değil, Birinin yanında Kendi kalbiyle barışabilmesidir.

Ben senin yanında daha çok kendim oldum. Belki aşkın en güzel mucizesi budur: Bir başkasını severken Kendinden de vazgeçmemek, Ve ikinizin birlikte Hayata daha çok bağlanması. 

Aşk

Sen bana sevgiyi öğretmedin belki,

Ama sevgisiz geçen zamanın

Ne kadar büyük bir kayıp olduğunu gösterdin.

Şimdi senden uzak bir günün içinde bile

Sana yakın bir düşünce taşıyorum.

Bir şarkıda, bir sokakta,

Bir fincan kahvenin soğuyan son yudumunda

Seni hatırlamak değil bu;

Hayatın her ayrıntısına

Seninle anlam verebilmek.

Aşk

Eskiden sabahları gün doğardı,

Şimdi sen doğuyorsun içimde.

Güneş aynı yerden yükseliyor belki

Ama aydınlık başka türlü değiyor yüzüme.

Aşk

Sana anlatmak istediğim şeyler var;

Bir ömrün telaşına sığmayacak kadar çok.

Bazen bir cümle kuruyorum içimden,

Sonra vazgeçiyorum,

Çünkü seni anlatmaya başladığımda

Kelimeler duygularımın gerisinde kalıyor.

Aşk

Seninle hiçbir yere yetişmek istemiyorum.

Bırak yollar uzasın, akşam geç olsun,

Bir kahve soğusun masamızda.

Hayatın bizden istediği bütün aceleleri

Bir süreliğine kapının dışında bırakalım.

Aşk

Sana bakarken geleceği düşünmek güzel,

Ama en çok şu anı seviyorum.

Elinin elimin üzerinde durduğu,

Gözlerinin bir şey anlatmadan güldüğü,

İçimde hiçbir şeyin eksik hissettirmediği

O küçük, tarifsiz anı…

Aşk

Yıllar sonra bir gün,

Birlikte yaşadığımız onca şeyin arasından

Bugünümüze rastlarsak,

Gülümseyelim birbirimize.

Çünkü o gün de seni seviyor olacağım;

Belki daha az heyecanla değil,

Daha çok tanıyarak,

Daha derinden,

Daha bilinçli…

Ben seni bir gün mutlu olmak için değil,

Her gün hayatın içinde mutluluğa birlikte yer açmak için seviyorum. 

Aşk

Sana Doğru Değişen Zaman

Eskiden sabahları gün doğardı, Şimdi sen doğuyorsun içimde. Güneş aynı yerden yükseliyor belki Ama aydınlık başka türlü değiyor yüzüme.

Sana anlatmak istediğim şeyler var; Bir ömrün telaşına sığmayacak kadar çok. Bazen bir cümle kuruyorum içimden, Sonra vazgeçiyorum, Çünkü seni anlatmaya başladığımda Kelimeler duygularımın gerisinde kalıyor.

Seninle hiçbir yere yetişmek istemiyorum. Bırak yollar uzasın, akşam geç olsun, Bir kahve soğusun masamızda. Hayatın bizden istediği bütün aceleleri Bir süreliğine kapının dışında bırakalım.

Sana bakarken geleceği düşünmek güzel, Ama en çok şu anı seviyorum. Elinin elimin üzerinde durduğu, Gözlerinin bir şey anlatmadan güldüğü, İçimde hiçbir şeyin eksik hissettirmediği O küçük, tarifsiz anı…

Biliyor musun, Seni sevmek beni daha sabırlı yaptı. Her güzel şeyin hemen gerçekleşmesi gerekmediğini, Bazı duyguların zamanla derinleştiğini, Bazı insanların hayatımıza Bir ömürlük anlam bırakmak için geldiğini öğrendim.

Ben seninle bir hikâye yaşamak istemiyorum yalnızca; Hikâyenin içinde kalmak istiyorum. Güzel günlerinde alkışın, Zor günlerinde sessizliğin, Kararsız kaldığında yanında duran düşüncen, Ve her akşam yeniden döndüğün insan olmak…

Yıllar sonra bir gün, Birlikte yaşadığımız onca şeyin arasından Bugünümüze rastlarsak, Gülümseyelim birbirimize.

Çünkü o gün de seni seviyor olacağım; Belki daha az heyecanla değil, Daha çok tanıyarak, Daha derinden, Daha bilinçli…

Ben seni bir gün mutlu olmak için değil, Her gün hayatın içinde mutluluğa birlikte yer açmak için seviyorum. 

Aşk', 'Seni sevmek, Bir sabahın sessizliğinde adını düşünmek, Güne henüz kimse dokunmamışken İçimde sana yer açmak gibi… Bazen hiçbir şey söylemede...', ARRAY['Türk Edebiyatı','Şiir','Aşk Aşkın Şehri Ordu']::text[], 8.5, '{"poet":"Aşk Aşkın Şehri Ordu","poet_slug":"ask-askin-sehri-ordu","theme":"Türk Şiiri","is_hero":false,"total_lines":275,"source_url":"https://www.antoloji.com/ask-kasim-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Mahzun Dil Suskun', 'gonul-mahzun-dil-suskun-ayla-cermen-tufekci-2s2ta', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GÖNÜL MAHZUN, DİL SUSKUN ( GÖNÜL )

G önül mahzun, dil suskun, kederli bakar gözün

Ö mrün sonbaharında, geceye yağar hüzün

N e desem fayda etmez, içinde yanar közün

Ü zülme, gam çekme sen, her zaman gülsün yüzün

L alaezar olsun dünyan, takma kafana gönül

Ç aresiz dert vermemiş, yaradan, yüce Mevla’m

E l açtık Tanrım sana, çünkü sendedir ferman

L akin salma kendini, tabipler bulur derman

İ ste, mutlaka verir, yeter ki kalpten inan

K ederli günler geçer, ah etme sabret gönül

AYLA CERMEN TÜFEKÇİ / .12.2020

Bu şiirim kıymetli Bestekar Muzaffer Uyanık Beyefendi tarafından Hüzzam makamında bestelenmiştir.

Sevgili Eşimin Samsun 19 mayıs Üniversitesi Tıp Fakültesi Hastanesinde Akciğer Ca operasyonu sonrasında, klinikteki odamızın bitişiğindeki odada yatan, aynı hastalıktan muzdarip operasyonu yapan kıymetli doktorumuz Prof. Dr. Burçin Çelik Bey’in annesine yazdığım armağanımdır.

Daha sonra her ikisi de peşpeşe rahmetli oldular! Mekanları cennet, ruhları şad olsun inşallah...', 'GÖNÜL MAHZUN, DİL SUSKUN ( GÖNÜL ) G önül mahzun, dil suskun, kederli bakar gözün Ö mrün sonbaharında, geceye yağar hüzün N e desem fayda et...', ARRAY['Türk Edebiyatı','Şiir','Ayla Cermen Tüfekçi']::text[], 8.5, '{"poet":"Ayla Cermen Tüfekçi","poet_slug":"ayla-cermen-tufekci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gonul-mahzun-dil-suskun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Ben Seni Böyle Sevdim', 'i-ste-ben-seni-boyle-sevdim-nurcan-bingol-2-1299w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nurcan Bingöl

Ben seni
çok sevdim demeyeceğim.

Çünkü “çok”
ne kadar eder, bilmiyorum.

Bir insanın içinde
başka bir insana ne kadar yer açılabilir,
onu da bilmiyorum.

Ama sen geldikten sonra
benim içimde bazı şeylerin
yeri değişti.

Mesela bir şey olduğunda
anlatmak istediğim ilk insan sen oldun.

Güzel bir şey görsem
sen de gör istedim.

Canım yansa
sesini duysam geçer sandım.

Bir yere gitsem
orada olsan nasıl olurdu diye düşündüm.

Sen farkında değildin belki.
Ben hayatı
bir süre iki kişilik düşündüm.

Kendim için baktığım şeylere
senin gözünden de baktım.

Bir cümlenin sonunda
“Sen ne derdin?” diye bekledim.

Bazen gülerken bile
içimden sana döndüm.

İşte ben seni biraz böyle sevdim.

Büyük sözlerle değil.
Kimsenin görmediği yerlerde,
kimsenin bilmediği zamanlarda.

Adının geçmediği konuşmalarda bile
seni düşünerek.

Sonra sen olmadın.

Ben yine sana bir şeyler anlattım.
İçimden.
Bazen günlerce.

İnsan, yanında olmayan biriyle
bu kadar çok konuşabilir mi?

Konuşuyormuş.

İnsan, dokunamadığı birini
bu kadar yakınında tutabilir mi?

Tutuyormuş.

Bunu senden sonra öğrendim.

Ben seni
sahip olmak ister gibi sevmedim.
Yanımda kal diye de sevmedim.

Bazen gideceğini
bile bile sevdim.

Belki en çok da burası acıtıyor beni.

Sonunu sezdiğim bir şeyi
içimde yine de büyüttüm.

Kendimi korumadım.
Kalbime
“Buradan sonrası tehlikeli,” demedim.

Sana doğru gittim.
Sessizce.
Kimseye belli etmeden.

Hatta bazen
sana bile belli etmeden.

Şimdi biri çıkıp bana
“Nasıl sevdin?” dese
uzun uzun anlatamam.

Çünkü bazı sevgiler
insanın hâline dönüşür.

Yürüyüşüne karışır,
sesine yerleşir.

Bir kelimeyi söylerken
bir an duraksarsın.

Kalabalığın içinde
durup dururken aklına gelir.

Herkes yoluna devam eder,
sen birkaç saniye
olduğun yerde kalırsın.

İşte ben seni öyle sevdim.

Öyle karıştın ki hayata bakışıma,
senden sonra seni unutmakla uğraşmadım.

İnsan kendisine karışmış birini
nereye bırakacağını bilemiyor çünkü.

Belki sevmenin en zor tarafı da bu.

Bir gün biri gider,
ama sende bıraktığı yer
onunla birlikte gitmez.

Benim içimde
senin yerin kaldı.

Adın, yüzün,
birlikte geçirdiğimiz zamanlar…
Hepsinin ötesinde
senin yanındayken
olduğum insan kaldı.

Galiba ben seni en çok
orada sevdim.

Seninleyken
içimde açılan o yerde.', 'Nurcan Bingöl Ben seni çok sevdim demeyeceğim. Çünkü “çok” ne kadar eder, bilmiyorum. Bir insanın içinde başka bir insana ne kadar yer açıla...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/iste-ben-seni-boyle-sevdim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gec Gelen Bahar', 'gec-gelen-bahar-furkan-turhan-0kruk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu böyle olmaz, 
Hep mi gec gelir bahar 
Nerde öten kuşlar
Nerde mutlu bir sabah 
Uyanmaksa dün geceye
İhanet ve müstahak
Çok mu uzun sürdü kış, 
Geç gelen bahar?', 'Bu böyle olmaz,  Hep mi gec gelir bahar  Nerde öten kuşlar Nerde mutlu bir sabah  Uyanmaksa dün geceye İhanet ve müstahak Çok mu uzun sürdü ...', ARRAY['Türk Edebiyatı','Şiir','Furkan Turhan']::text[], 8.5, '{"poet":"Furkan Turhan","poet_slug":"furkan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gec-gelen-bahar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Cüzdanım Ayrı', 'benim-cuzdanim-ayri-yakup-han-kilinc-n7jdn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hergün iş alıyormuş 

Ne yapayım alırsa 

Onun cüzdanı ayrı 

Benim cüzdanım ayrı 

Yakuphan Kılınç', 'Hergün iş alıyormuş  Ne yapayım alırsa  Onun cüzdanı ayrı  Benim cüzdanım ayrı  Yakuphan Kılınç...', ARRAY['Türk Edebiyatı','Şiir','Yakup Han Kılınç']::text[], 8.5, '{"poet":"Yakup Han Kılınç","poet_slug":"yakup-han-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benim-cuzdanim-ayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Toprağın Hesabı', 'bir-avuc-topragin-hesabi-emir-ergin-koc-twxlo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİR AVUÇ TOPRAĞIN HESABI

            ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

    **Bir Emir Ergin Koç Kalemin ''den**

            ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir sabah aynalarda kendinden utanacaksın,

Geçmişin hesabını vicdanına soracaksın.

Dünyayı mülkün sanıp nice gönül yıkacaksın,

Sonunda bir avuç toprağa sığacaksın.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir vakit kapında beklerdi nice insanlar,

Önünde eğilirdi makamına tapanlar.

Sen kendini sultan sanıp hükmünü sürerken,

Bir köşede ah ederdi hakkını arayanlar.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir yetimin gözyaşından habersiz yaşadın,

Garibin alın teriyle sofralar donattın.

Mazlumun hakkını yiyip servetine kattın,

Kendi ellerinle ahiretini kararttın.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Gün geldi, o kapılar yüzüne kapanacak,

Dost dediğin insanlar birer birer kaçacak.

Ömrünü verdiğin malın ellere kalacak,

Vicdanın sustuğu yerden günahların konuşacak.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Şimdi söyle, hangi altın geri verir zamanı?

Hangi hekim iyileştirir vicdanındaki yaranı?

Hangi makam susturabilir mazlumun feryadını?

Hangi servet satın alır bir yetimin duasını?

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Vakit varken git de kırdığın gönülleri onar,

Bir garibin duasında nice hikmetler yatar.

Alnın secde görse bile hakkı yenmiş kulun var,

Helallik alınmamışsa mahşerde hesabın var.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir gün gelir, son nefesin boğazında düğümlenir,

O mağrur başın düşer, bütün saltanatın silinir.

Ne altının dile gelir ne makamın seni bilir,

İnsan ancak bıraktığı iyiliklerle anılır.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Ey gönül, nefsine uyup kimseyi hor görme,

Üç günlük dünya için bir garibin ahını alma.

Hakk''ın huzuruna çıkacağın günü unutma,

Secdeye vardığın alınla kul hakkına uzanma.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Emir Ergin Koç', 'BİR AVUÇ TOPRAĞIN HESABI             ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂     **Bir Emir Ergin Koç Kalemin ''den**             ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂ Bir sabah aynalarda kendind...', ARRAY['Türk Edebiyatı','Şiir','Emir Ergin Koç']::text[], 8.5, '{"poet":"Emir Ergin Koç","poet_slug":"emir-ergin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/omrun-hesabi-sorulur-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ancak.', 'ancak-fehmi-tazegul-m804z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kış gelince bütün yapraklar solar.

Kuşlar ötse de ruhlar kasvet dolar.

Bülbüller öter koskoca ömrü çalar.

Doğayı sev mutlu olursun ancak.

Soğuklar gelir bıyıkların buz keser.

Kalmamış babandan sende bir eser.

Aç kalmış hayvanlar yerlere düşer.

Doğayı sev mutlu olursun ancak.

Hatırıma gelir yoksul kara günler.

Hayat yaşam uzun bir kışa benzer.

Perişan olmuşlar sahipsiz fakirler.

Doğayı sev mutlu olursun ancak.

Fehmi.

Her taraf kar altında gelmiş aralık.

Buzlarla kaplanmış her yer ortalık.

Tezgâhlarda yatar cansız her balık.

Doğayı sev mutlu olursun ancak.', 'Kış gelince bütün yapraklar solar. Kuşlar ötse de ruhlar kasvet dolar. Bülbüller öter koskoca ömrü çalar. Doğayı sev mutlu olursun ancak. So...', ARRAY['Türk Edebiyatı','Şiir','Fehmi Tazegül']::text[], 8.5, '{"poet":"Fehmi Tazegül","poet_slug":"fehmi-tazegul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ancak-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk Moloz', 'soguk-moloz-kasim-kobakci-6xajh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıkmasın gökleri taşkın bir heybet,

Şu soğuk molozdan ibret almalı,

Tek bir sarsıntıda dağılır servet,

Şu soğuk molozdan ibret almalı.

*

Kağıt üstünde kusursuz hep imar,

Ölçüyü şaşırmış kibirli mimar,

Çatlağa yetmez ki yalancı tımar,

Şu soğuk molozdan ibret almalı.

*

Yükselen her kule sonunda enkaz,

Yıkımın koynunda kısılmaz avaz,

Toz duman içinde duyulmaz niyaz,

Şu soğuk molozdan ibret almalı.

*

Fayans kırıkları bükülmüş direk,

Kepçe pençesinde eğilmiş kürek,

Bunca harabeye dayanmaz yürek,

Şu soğuk molozdan ibret almalı.

*

Çimento kireç mi kuru sıva mı?

Saray mı konak mı garip yuva mı?

Mühendis müfettiş bitmez dava mı?

Şu soğuk molozdan ibret almalı.

*

Kırık aynalardan hatıra tutan,

Nice şen ocağı sessizce yutan,

İnsafı vicdanı hepten unutan,

Şu soğuk molozdan ibret almalı.

*

Tuğlası çakılı mermeri taşı,

Çamurda karılmış şehrin gözyaşı,

Mülke tapan hırsın eğilmez başı,

Şu soğuk molozdan ibret almalı.

*

Çağımız enkazdan devşirir gurur,

Sıvanıp gizlenir her türlü kusur,

Çürük bir temelde bulunmaz huzur,

Şu soğuk molozdan ibret almalı.

*

Fakirim, kayıyor altından zemin,

Ne köşkün kalıcı ne malın emin,

Mezarda sınanır verilen yemin,

Şu soğuk molozdan ibret almalı..', 'Yıkmasın gökleri taşkın bir heybet, Şu soğuk molozdan ibret almalı, Tek bir sarsıntıda dağılır servet, Şu soğuk molozdan ibret almalı. * Kağ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/soguk-moloz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyayı Ahireti Bilipte Yaşa', 'dunyayi-ahireti-bilipte-yasa-yavuz-bayram-caliskan-i9h1a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünyada, sahtekar, yalan yazanlar

Sevabı bilmeyip, günah kusanlar

Kanıpta atlayan insan sazanlar 

Dünyayı ahireti bilipte yaşa 

Allahın kuluna vermeyin acı

Çekilir başından evlatla bacı

İman, inanç namaz bunun ilacı

Dünyayı ahireti bilipte yaşa 

Hırsızla, zalimde kurtulur sanma

İblisle, şeytanla, hanende yanma 

Olura olmaza, aldanıp kanma

Dünyayı ahireti bilipte yaşa 

Almayın haksızca, cananı, canı

Taşıyın doğruca o asil kanı

Ey insan, şehidi, atanı tanı

Dünyayı ahireti bilipte yaşa 

Şiirhan emeğin hakkını verendir 

Komşuyu, fakiri, yolu bilendir

Öksüzün, yetimin yaşın silendir

Dünyayı ahireti bilipte yaşa.', 'Dünyada, sahtekar, yalan yazanlar Sevabı bilmeyip, günah kusanlar Kanıpta atlayan insan sazanlar  Dünyayı ahireti bilipte yaşa  Allahın kulu...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunyayi-ahireti-bilipte-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta giden yol', 'dosta-giden-yol-mahmut-kasapoglu-0wgfl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürü gönül yürü, dosta varalım,

Dağ yormaz insanı, dostsuzluk yorar.

Aşk ile bu canı Hakk''a verelim,

Dert yormaz insanı, dertsizlik yorar.

Yâre selâm saldım, yolunu gözler,

Göz yormaz insanı, beklemek yorar.

Hasret ateşinde yanar da közler,

Kor yormaz insanı, özlemek yorar.

Nice hanı gördüm, nice sultanı,

Taht yormaz insanı, sarılmak yorar.

Döner bu feleğin bütün devranı,

Şan yormaz insanı, kasılmak yorar.

Dünya malı elde gölgedir, geçer,

Mal yormaz insanı, doymamak yorar.

Bu fânî konaktan her yolcu göçer,

Mülk yormaz insanı, kıymamak yorar.

Akıl bir kandildir, karanlık kaçar,

Hâl yormaz insanı, yalancı yorar.

Erenlere sırrın kapısın açar,

Sır yormaz insanı, yabancı yorar.

Bahçe gül yetirir, diken de biter,

Gül yormaz insanı, dikenler yorar.

Güzel söz bülbüldür, gönülde öter,

Dil yormaz insanı, yerenler yorar.

Kasapoğlu, yürü dosta varalım,

Yol yormaz insanı, kin yükü yorar.

Göçmeden bu handan hesap görelim,

Göç yormaz insanı, "ben" yükü yorar.', 'Yürü gönül yürü, dosta varalım, Dağ yormaz insanı, dostsuzluk yorar. Aşk ile bu canı Hakk''a verelim, Dert yormaz insanı, dertsizlik yorar. Y...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dosta-giden-yol-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özden öze', 'ozden-oze-mahmut-kasapoglu-2zawr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde bir ateş, dilimde niyaz,

Her nefeste başka açılır bir yaz,

Kendini arayan az bulur, pek az,

Özünü bilmeye uyan ey gönül,

Hakk''ın boyasıyla boyan ey gönül.

Gaflette geçmesin o kutlu seher,

O vakit dökülen gözyaşı gevher,

Duaya açılan el boş mu döner?

Doğacak şafağı gözle ey gönül,

Rahmân''ın nurunu özle ey gönül.

Dünya bir gölgedir, ömür bir nefes,

Kalıcı değildir ne servet ne ses,

Gerçeği görene kalmaz bir heves,

Fâni olan şeyden arın ey gönül,

Bâki olan aşka sarın ey gönül.

Bir lokma ekmekte bin şükür vardır,

Bir yudum suda da nice nur vardır,

Kanaatte gizli bir huzur vardır,

Her nimette Hakk''ı seyret ey gönül,

Dilinle, kalbinle şükret ey gönül.

Yol uzun görünür, menzil görünmez,

Bu yola düşenler geriye dönmez,

Aşk ile tutuşan bir daha sönmez,

Korkma, yalnız Hakk''a inan ey gönül,

Teslim ol, her hâle dayan ey gönül.

Bu ten bir kafestir, kuşu da candır,

Ötüşü zikirdir, âhı figandır,

Özlediği yurt da asıl vatandır,

Kanat çırp, kafesten sıyrıl ey gönül,

Gurbet diyarından ayrıl ey gönül.

Sonunda kalmasın sende benliğin,

Bir "Hû"ya sığsın da her söylediğin,

Rıza-yı Hak olsun her dilediğin,

Senlikten, benlikten kurtul ey gönül,

Özden öze akıp durul ey gönül.', 'İçimde bir ateş, dilimde niyaz, Her nefeste başka açılır bir yaz, Kendini arayan az bulur, pek az, Özünü bilmeye uyan ey gönül, Hakk''ın boya...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ozden-oze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karkın Pekmezinin Tadı Güzeldir', 'karkin-pekmezinin-tadi-guzeldir-yavuz-bayram-caliskan-mtc6w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Üzüm bağlarında sarı yapraklar

Kurumuş, yarılmış kumlu topraklar

Korukla alaca düşen duraklar 

Karkın pekmezinin tadı güzeldir 

Toplanır salkımlar  şıra sıkılır

Pekmez yapmak için ateş yakılır

Tatlansın diyede toprak dökülür 

Karkın pekmezinin tadı güzeldir 

Süzülür toprağı suyu arınır

Güzün ayazında insan sarınır 

Kerpiç evlerinde köylüm barınır 

Karkın pekmezinin tadı güzeldir 

Kar ile pekmezi alıp katarlar 

Soğuk mevsimlerde sıcak yatarlar 

Festival yapıpta ürün satarlar 

Karkın pekmezinin tadı güzeldir 

Şiirhan Karkın''da coşkuyu gördü 

Huzurla, mutluluk alnına vurdu 

Köyde beraberlik huzurda vardı 

Karkın pekmezinin tadı güzeldir.', 'Üzüm bağlarında sarı yapraklar Kurumuş, yarılmış kumlu topraklar Korukla alaca düşen duraklar  Karkın pekmezinin tadı güzeldir  Toplanır sal...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karkin-pekmezinin-tadi-guzeldir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennete götüren iz', 'cennete-goturen-iz-mahmut-kasapoglu-1n4vs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gönlümün ışığı, ömrümün canı,

Yüzünü düşümde ararım ana.

Bir ömür taşıdın derdimi, gamı,

Sendin başımdaki çınarım ana.

Geceler boyunca uyku hep yasak,

Tüterdi ocağın, sıcaktı kucak,

Gizledin acını, gülerdin ancak,

Kalbimde tükenmez pınarım ana.

Ateşler içinde yandığım zaman,

Başımda bekledin, sen oldun derman,

Ellerin üstümde sıcacık yorgan,

Hâlâ o şefkati duyarım ana.

Ödenir mi hakkın, ömrüm mü yeter,

Adını anınca dinmez bu keder,

Sen gittin gideli bahar da gider,

Bir daha gelmeyen baharım ana.

Kırk yedi yaşında göçtün erkenden,

Doyamadım sana, ayrıldın benden,

Doğruyu, sabrı ben öğrendim senden,

Elini öpemem, yanarım ana.

Ayırdığın lokma, sardığın yara,

Hepsi nur olarak yağsın mezara,

Çektiğin her çile yazılsın kâra,

Her secdede seni anarım ana.

Cennet ayağının altında derler,

İzine yüz sürer bütün gönüller,

Oğlun da ömrünce o izi izler,

Sendin cennet yolu, gülzarım ana.', 'Gönlümün ışığı, ömrümün canı, Yüzünü düşümde ararım ana. Bir ömür taşıdın derdimi, gamı, Sendin başımdaki çınarım ana. Geceler boyunca uyku ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cennete-goturen-iz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyamı Batırır Aşk Selin Beni', 'dunyami-batirir-ask-selin-beni-yavuz-bayram-caliskan-0wqol', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülserimle ömrüm, yarınla derdim

Külüyle savurur, aşk yelin beni

Canımı, gönlümü, sevgimi verdim

Dünyamı batırır aşk selin beni 

Gülümün vadesi yoluna doldum

Mayıs ayında da kolunda soldum 

Saçımı, başımı, ömrümü yoldum

Dünyamı batırır aşk selin beni 

Ölümün acılı söylenir dilim

Haneme serilmez bir yırtık kilim

Boşalıp geliyor gönlümden selim

Dünyamı batırır aşk selin beni 

Şiirhan bülbül seyyah olur canıyla

Mazimiz doludur bitmez anıyla

Yaşatır sevdamla sevgim kanıyla 

Dünyamı batırır aşk selin beni.', 'Gülserimle ömrüm, yarınla derdim Külüyle savurur, aşk yelin beni Canımı, gönlümü, sevgimi verdim Dünyamı batırır aşk selin beni  Gülümün vad...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunyami-batirir-ask-selin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar ile ağyar', 'yar-ile-agyar-mahmut-kasapoglu-xopsf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlık içinde kandil yakmadan,

Kendi kusuruna dönüp bakmadan,

Gönülden bir pınar sessiz akmadan,

Ağyâr belli olmaz, yâr belli olmaz.

Bir lokmayı hakça bölüp vermeden,

Yoksula kapıda sofra sermeden,

Azalan ambardan bolluk dermeden,

Ziyan belli olmaz, kâr belli olmaz.

Övgüye değil de Hakk''a tapmadan,

Melâmet yoluna gönlün sapmadan,

Kimseye demeden hayır yapmadan,

Şeref belli olmaz, ar belli olmaz.

Bir gönül yıkarsan taşla duvarla,

Yetmez bin mescit de kursan mimarla.

Ölçülmez o saray yerle diyarla.

Geniş belli olmaz, dar belli olmaz.

Kefenini giyip sağken yatmadan,

Adını sanını pula satmadan,

Ölümü bir şerbet gibi tatmadan,

Yokluk belli olmaz, var belli olmaz.

Ömür boyu ağyâr dışarda sandım,

Kapıya sürgüyü vurup dayandım.

Ağyâr bendim meğer, yeni uyandım.

Ağyâr belli oldu, yâr belli oldu.', 'Karanlık içinde kandil yakmadan, Kendi kusuruna dönüp bakmadan, Gönülden bir pınar sessiz akmadan, Ağyâr belli olmaz, yâr belli olmaz. Bir l...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yar-ile-agyar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun gözyaşım', 'suskun-gozyasim-mahmut-kasapoglu-hrvng', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin koynunda suskunluğum var.

Çaydanlık sobada usulca kaynar.

Bu oda geniştir, göğsüm ise dar.

Yastığım bilir de söylemez, saklar.

Kim demiş yürekler ağlamaz diye?

Dilimde düğümlü söz benimdir hep.

Eşikte bekleyen göz benimdir hep.

Küllerin altında köz benimdir hep.

Kırılmaz cevizde öz benimdir hep.

Kim demiş erkekler ağlamaz diye?

Çınarlar da çatlar ayaz vurunca.

Taşlar da yarılır kök yol bulunca.

Bentler de yıkılır sular dolunca.

Ben de ağlarmışım derde doyunca.

Kim demiş yürekler ağlamaz diye?

Erkeğim, incindim; içim çözülür.

Kaşlarım çatılır, dudak büzülür.

Sigaram yanar da külü dökülür.

Nemlenmiş bir mendil cepte dürülür.

Kim demiş erkekler ağlamaz diye?

Çekmecede durur yüzük kutusu.

Atkımda kalmıştır onun kokusu.

Kaçar gözlerimin bütün uykusu.

Bir "elveda" denen günün korkusu.

Kim demiş yürekler ağlamaz diye?

Dışım mermer, içim ıslak bir toprak.

Cüzdanımda saklı bir eski yaprak.

Ağlarsam bir gece, sorma da bırak.

Sabah yine dimdik dururum, ancak

Kim demiş erkekler ağlamaz diye?

Kına yakılırken minik eline,

Al kuşak bağladım ince beline.

Yol verdim kızıma yeni evine.

Bir damla süzüldü bıyık dibine.

Kim demiş erkekler ağlamaz diye?

Anamın un kokan sıcak kucağı,

Babamın öğüdü, çakı bıçağı,

Dost eli, dar günün tek dayanağı…

Köyde tütmez oldu evin ocağı.

Kim demiş yürekler ağlamaz diye?

Şemsiyesiz döndüm evime yayan.

Kaldırım taşıydı izimi sayan.

Herkes yağmur sandı yüzümden kayan.

Bilinmez gök müydü yoksa ağlayan.

Kim demiş erkekler ağlamaz diye?

Mendilimi astım sabah güneşe.

Bir tutam tuz kaldı, bir tutam neşe.

Kalkıp sarıldım da eşe, kardeşe.

Çaydanlık yeniden kondu ateşe.

Kim demiş yürekler ağlamaz diye?', 'Gecenin koynunda suskunluğum var. Çaydanlık sobada usulca kaynar. Bu oda geniştir, göğsüm ise dar. Yastığım bilir de söylemez, saklar. Kim d...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/suskun-gozyasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birden bine', 'birden-bine-mahmut-kasapoglu-59bcv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne ben vardım ne de dünya, ne bir saat ne bir an.

Bir mürekkep damlasıydı kalem ucunda zaman.

Bir harf düştü ak sayfaya, yazıya döndü cihan.

"Ol" denildi, bu kâinat var oldu birden bine.

Bir nar kırdım avucumda, kan kırmızı bin tane.

Her birinde aynı güneş, aynı tat, aynı hane.

Her tanede bir bahçe var, bahçede bir kâşane.

Bir çiçek ki dalda açtı, nar oldu birden bine.

Ben de indim o buluttan, altı uçlu bir nakış.

Kardeşlerim yan yanaydı, her yüz başka bir bakış.

Güneş bir gün değdiğinde olur hepsi bir akış.

Bir tek su ki gökyüzünde kar oldu birden bine.

Çömlekçinin çarkı döndü, çamur cana büründü.

Bir nefes ki üflendi de, yüzümde gün göründü.

Sonra düştüm bir elmayla, gölgem yerde süründü.

Benim o tek gözyaşım da zâr oldu birden bine.

Bir usta el burgu burgu gerdi dağınık teli.

Her gerilen tel inledi, tanıdım ben o eli.

Bin ayrı ses bir perdede, dindi sızının seli.

Bin telin bin feryadı da tar oldu binden bire.

Bir şekerdim, girdim çaya, eriyip gitti adım.

Ne bir şekil ne iz kaldı, bardağa sindi tadım.

Kaşıkla bir karıştırdı, çözüldü tüm inadım.

Ben bitince kalan her şey yâr oldu binden bire.

Ben pergelin dönen ucu, O sabitti, dolaştım.

Çizdim çizdim bin daire, ilk noktaya ulaştım.

Mürekkebim tükenince kalem ucunda taştım.

Dağılan bin tane yine nar oldu binden bire.', 'Ne ben vardım ne de dünya, ne bir saat ne bir an. Bir mürekkep damlasıydı kalem ucunda zaman. Bir harf düştü ak sayfaya, yazıya döndü cihan....', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/birden-bine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FİLİSTİNLİ ÇOCUK', 'fi-li-sti-nli-cocuk-muhsin-yener-2-smd07', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonra bir Filistinli çocuk, Gözlerini İsrail''e çevirdi Gökyüzü kurşun, gece zifir, Yeryüzü kan, vicdanlar esir.

Soğuktu İsrail''de hava, Ama bir çocuk titriyordu Gazze''de
Üşüyen yalnız beden değildi, İnsanlık donmuştu bu zulmün gölgesinde.

Küçücük ellerini kaldırdı semaya, Ne tankı vardı ne tüfeği... Bir duası vardı, bir de yaralı yüreği; Döndü Allah''a, sustu bütün gece:

"Allah''ım! İsrail üşüyor.
 Yak onları!

Benim yuvamı yaktılar, Anamı, babamı, kardeşimi aldılar.
Ben hâlâ soğuktan titriyorum, Onlar zulmün ateşinde ısınıyorlar!

Allah''ım! Adaletin varsa göklerde, Bu ateş zalimin yüreğine düşsün! Mazlumun ahı yerde kalmasın, Zulmeden, kendi zulmünde boğulsun!"

Ve çocuk sustu
Gökyüzü sustu.
Ama bir mazlumun duası,
Arşın kapısında yankılandı.
Muhsin yener 

Çünkü bazen bir çocuğun gözyaşı, Bir ordudan daha ağırdır; Ve mazlumun duası, Zalimlerin kurduğu bütün saraylardan daha güçlüdür...', 'Sonra bir Filistinli çocuk, Gözlerini İsrail''e çevirdi Gökyüzü kurşun, gece zifir, Yeryüzü kan, vicdanlar esir. Soğuktu İsrail''de hava, Ama ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/filistinli-cocuk-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dediler aşk için', 'dediler-ask-icin-mahmut-kasapoglu-inpxc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dediler aşk için bir dar sokaktır.

Girenin çıkışı yalan dediler.

Ucundaki kapı her dem uzaktır.

Duvarı sis, taşı duman dediler.

Pencereler kördür, yüksektir duvar.

Her kapısı kilit, her evi hisar.

Satılır umutlar, kurulur pazar.

Sorma, orda herkes yaban dediler.

Dinlemedim, girdim o dar sokağa.

Yol bulamadım hiç yanan ocağa.

Bir taş gibi düştüm soğuk toprağa.

Baktılar hâlime, talan dediler.

Derken bir pencere, aralık perde.

Bir ses çağırdı: "Kalk, üşüme yerde."

Bir el uzandı ki ortak bu derde.

Kimdi, bilmem; ona insan dediler.

Kör pencerelerim ışıkla doldu.

O dar sokak şimdi bir yuva oldu.

Aradığım meğer bir sıcak koldu.

Ben "ev" dedim, onlar "zindan" dediler.', 'Dediler aşk için bir dar sokaktır. Girenin çıkışı yalan dediler. Ucundaki kapı her dem uzaktır. Duvarı sis, taşı duman dediler. Pencereler k...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dediler-ask-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duydun mu ayşem?', 'duydun-mu-aysem-mahmut-kasapoglu-anmq6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki fincan çayın buğusu söndü.

Pencerede boynu bükük menekşem.

Aynalar yüzünü arayıp döndü.

Ev bana artık dar duydun mu Ayşe''m?

Günler düşer birer takvim yaprağı.

Kül tutmuş bekliyor evin ocağı.

Yüreğim bir kışın yorgun toprağı.

Bütün mevsimler kar duydun mu Ayşe''m?

Unutur muyum hiç o gülüşünü,

Bahçe kapısında yürüyüşünü?

Uykumda görürüm yine düşünü.

Seninleydi bahar duydun mu Ayşe''m?

Kumum dibe çökmüş kalmış bu camda.

Çevirirdin beni her bir akşamda.

Zaman taş kesildi sensiz odamda.

Her yanım bir duvar duydun mu Ayşe''m?

Anahtarın cepte durur gizlice.

Kapını çalarım bütün bir gece.

Adını sökerim ben hece hece.

Hâlâ umudum var duydun mu Ayşe''m?', 'İki fincan çayın buğusu söndü. Pencerede boynu bükük menekşem. Aynalar yüzünü arayıp döndü. Ev bana artık dar duydun mu Ayşe''m? Günler düşer...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/duydun-mu-aysem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Anlatırlar Yaşamazlar', 'hep-anlatirlar-yasamazlar-i-lyas-ates-03zuv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep anlatırlar yaşamazlar 

Anlatmak kolay zor olansa

yaşamaktır 

Hep iyi adammış derler iyi

adam olmayı düşünmezler 

dahi

İyi adamlar yaşarken cehennemlerini

yaşarlar nereden bileceksiniz ki 

Adam olmak cehennemden yanarak

geçebildiğinde her bir belaya göğüs 

gerebildiğinde bu halleri yaşatanın

bir olduğuna bir hesaba göre yaptığına

inanmakla bu hallere tahammül edip

sabretmekle ona sorgusuz teslim olmaktır', 'Hep anlatırlar yaşamazlar  Anlatmak kolay zor olansa yaşamaktır  Hep iyi adammış derler iyi adam olmayı düşünmezler  dahi İyi adamlar yaşark...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hep-anlatirlar-yasamazlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Gider Sanki', 'ne-gider-sanki-ozdemir-koca-zg5t7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne değişti bilmiyorum unuttum mu yoksa seni,

Oysa Galata kulesinde resmimiz çekilmişti,

Yürümüştük Taksim''in ince uzun yolunda,

Gözlerimiz Fener Kilisesine dikilmişti.

Şimdi yoksun öylemi Boğaz sensiz mi kaldı,

Rıhtımdaki Martılar aç Simitsiz mi kaldı,

Yoksa Boğaz köprüsü tıkandı mı bilmem,

Yine İstanbul yoksa sensiz mi kaldı.

Uğradın mı Üsküdar''a Kız Kulesine karşı,

Uzattın mı güzelim o pembe ayaklarını,

Rüzgar mı dağıttı birden bembeyaz saçları, 

Anlatma bensizliğini bak ruhum da daraldı.

Ne değişti bilmiyorum unuttum mu yoksa seni,

Şişlinin kenarından baktım dalgalı denize,

Köpük köpük ayrılık koymuş yüreğimize,

Gözlerin var ya bana Beylikdüzü kadardı.

Hani diyorum buluşsak Bakırköyde yine,

Bir çay içsek bir kahve herhangi bir kafede,

Anlatsak gizlediğimiz yıllarca süren aşkı,

Ne gider dilimizden ne eksilir benliğimizden.

Binsek koca Vapura uğrasak limanlara,

Haydarpaşa''dan uğrasak girsek İstanbul''a,

Kalelere kapatsak zincirlerle kalplerimizi,

Miras bıraksak diyorum gelecek çocuklara.

Özdemir yol alıyor sensiz Haliç nehrinde,

Sevdasını yüklenmiş tonlarca yük içinde,

Bir elveda demeden yine çekip gitsen de,

Eksilir mi bu sevda bilmem yüreğimizde.', 'Ne değişti bilmiyorum unuttum mu yoksa seni, Oysa Galata kulesinde resmimiz çekilmişti, Yürümüştük Taksim''in ince uzun yolunda, Gözlerimiz F...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Koca']::text[], 8.5, '{"poet":"Özdemir Koca","poet_slug":"ozdemir-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ne-gider-sanki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filistinli Çocuk', 'filistinli-cocuk-muhsin-yener-7h6d7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonra bir Filistinli çocuk, Gözlerini İsrail''e çevirdi Gökyüzü kurşun, gece zifir, Yeryüzü kan, vicdanlar esir.

Soğuktu İsrail''de hava, Ama bir çocuk titriyordu Gazze''de

Üşüyen yalnız beden değildi, İnsanlık donmuştu bu zulmün gölgesinde.

Küçücük ellerini kaldırdı semaya, Ne tankı vardı ne tüfeği... Bir duası vardı, bir de yaralı yüreği; Döndü Allah''a, sustu bütün gece:

"Allah''ım! İsrail üşüyor.

 Yak onları!

Benim yuvamı yaktılar, Anamı, babamı, kardeşimi aldılar.

Ben hâlâ soğuktan titriyorum, Onlar zulmün ateşinde ısınıyorlar!

Allah''ım! Adaletin varsa göklerde, Bu ateş zalimin yüreğine düşsün! Mazlumun ahı yerde kalmasın, Zulmeden, kendi zulmünde boğulsun!"

Ve çocuk sustu

Gökyüzü sustu.

Ama bir mazlumun duası,

Arşın kapısında yankılandı.

Muhsin yener 

Çünkü bazen bir çocuğun gözyaşı, Bir ordudan daha ağırdır; Ve mazlumun duası, Zalimlerin kurduğu bütün saraylardan daha güçlüdür...', 'Sonra bir Filistinli çocuk, Gözlerini İsrail''e çevirdi Gökyüzü kurşun, gece zifir, Yeryüzü kan, vicdanlar esir. Soğuktu İsrail''de hava, Ama ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener']::text[], 8.5, '{"poet":"Muhsin Yener","poet_slug":"muhsin-yener","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/filistinli-cocuk-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam anam', 'anam-anam-mahmut-kasapoglu-zc9lc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vefa adını sen koydun cihana,

Cefa rengine sen boyandın anam,

Şafak sökmeden can verdin yuvana,

Horozdan da önce uyandın anam.

Kazan buğusuyla yüzün örterdin,

Aşına tuz diye terin dökerdin,

Ekmeğe kalbinin közün ekerdin,

Son lokmayı bize sunandın anam.

Çamaşır suyunda elin çatlardı,

Bulaşık sesinde türkün ağlardı,

Kız kardeşlerimi kolun kollardı,

Bin bir işe yalnız dayandın anam.

Babam alnı terli ekmek getirir,

Akşam yorgun argın kapıdan gelir,

Evi omzunda taşır, kim bilir?

Sessiz kahramandın, sen candın anam.

Kına tepsisine elin değmedi,

Torun ninnisine sesin yetmedi,

Gönlünde mühürlü mektup, gitmedi,

Bir "yarın" sözüne inandın anam.

Kırk yedi baharın dalı büküldü,

Ansızın tasının suyu döküldü,

Kırlangıçlar dama yasla süzüldü,

Yere değil, göğe uzandın anam.

Sandıkta tülbendin kokusu kaldı,

Rüzgâr pencereden adını çaldı,

Babam gecelerce uzağa daldı,

Üşüyen evinde yorgandın anam.

Her sabah sofrada ekmek bölünür,

Kimse dokunmaz bir dilim görünür,

Kız kardeşlerim de sana bürünür,

Küle gömülmüş köz, bende yandın anam.', 'Vefa adını sen koydun cihana, Cefa rengine sen boyandın anam, Şafak sökmeden can verdin yuvana, Horozdan da önce uyandın anam. Kazan buğusuy...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/anam-anam-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı sen olan şiir', 'adi-sen-olan-siir-mahmut-kasapoglu-0zt0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykumun ucundan bir nida çağırdı

Gözümü açtığım seherde sen varsın

Ruhum yankılandı, vadiler bağırdı

Sesin getirdiği haberde sen varsın

Irmaklar yürürken dağların içinden

Mavi bir sır içer göğün aynasından

Ay düşer gecenin gümüşten saçından

Baktığım her güzel eserde sen varsın

Ömrüm yorgun gemi, sevdan son limanı

Pusulam yıldızlar, sen yolun fermanı

Sevincim yelkeni, derdimse tufanı

Çıktığım her uzun seferde sen varsın

Ben kaçtıkça senden, canım sana kaçar

Yabancı yüzlere gönlüm kapı açar

Her gülüş bir anlık serap gibi uçar

Gidip sığındığım beşerde sen varsın

Kırık yanlarımı gül dalıyla sardım

Geceye adını gözyaşımla yazdım

Kendimden kendime yollar, yollar kazdım

Dindiremediğim kederde sen varsın

Aşkın divanında beyit beyit geçtim

Her mısraı bir bir tespih gibi seçtim

Harfleri gönlümün tarlasında biçtim

Tuttuğum kalemde, hünerde sen varsın

Ne kadar susarsam o kadar yakınsın

Ne kadar kaybolsam o kadar derinsin

Göklerde aradım, göklerden enginsin

Meğer canımdaki gevherde sen varsın', 'Uykumun ucundan bir nida çağırdı Gözümü açtığım seherde sen varsın Ruhum yankılandı, vadiler bağırdı Sesin getirdiği haberde sen varsın Irma...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/adi-sen-olan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar 109', 'aforizmalar-109-ozan-agri-7zmne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne bu dünya sultanlara kaldı ne de kılıktan kılığa girenlere…

Eden yaptığını buldu, susan hakkını aldı.

Hikâyenin sonunda herkes kalbinin ekmeğini yedi; 

Kimi doydu, kimi ömrünce aç kaldı...', 'Ne bu dünya sultanlara kaldı ne de kılıktan kılığa girenlere… Eden yaptığını buldu, susan hakkını aldı. Hikâyenin sonunda herkes kalbinin ek...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ağrı']::text[], 8.5, '{"poet":"Ozan Ağrı","poet_slug":"ozan-agri","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aforizmalar-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul, Sen misin?', 'i-stanbul-sen-misin-erdogan-cam-43fcb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu akşam İstanbul bir başka güzel,

Boğaz''ın gözlerinde yıldızlar saklı.

Bir vapur geçiyor gönlümün kıyısından,

Aklımda bir gülüş, yüreğimde adı saklı.

Galata susmuş, Kız Kulesi dalgın,

Martılar bile bir sevdaya şahit.

Bir çift gamze düşmüş gecenin yüzüne,

İstanbul mu gülümsüyor, yoksa sen misin?

Ne zaman akşam olsa seni hatırlatır,

Sokak lambalarının titrek ışıkları.

Bir yabancı geçer kalabalığın içinden,

Bir anda değişir şehrin bütün şarkıları.

Sen hangi rüzgârın getirdiği baharsın?

Hangi yıldızın yeryüzüne düşen hâli?

Ben İstanbul''u güzel sanırdım eskiden,

Meğer bir gülüşmüş bütün güzelliği.

Adını sormayın, söyleyemem kimseye,

Bir sır gibi saklarım gecenin koynunda.

Belki bir gün okur da gülümsersin,

Kendini bulursun bu şiirin sonunda.

Ve bir gün sorarsan bana,

“Bu İstanbul şiiri kime yazıldı?” diye,

Gözlerine bakıp yalnızca gülerim...

Çünkü bazı kadınlar İstanbul gibidir,

Herkes hayranlıkla bakar,

Ama herkes aynı güzelliği göremez.', 'Bu akşam İstanbul bir başka güzel, Boğaz''ın gözlerinde yıldızlar saklı. Bir vapur geçiyor gönlümün kıyısından, Aklımda bir gülüş, yüreğimde ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çam']::text[], 8.5, '{"poet":"Erdoğan Çam","poet_slug":"erdogan-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-sen-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka', 'baska-vedat-yilmaz-9y3wq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bakıp ayırt etmek zor gelir ama

Tavuk başka, ördek başka, gaz başka

Deveyi zorlasan çıkar mı dama

Yokuş başka, tümsek başka, düz başka

Dil keskindir ne dost bilir ne hatır 

Çekemez yükünü iki-üç katır

Her bir teli bir sevdayı anlatır

Keman başka, cümbüş başka, saz başka

Eğrilmiş ok hiç hedefe varır mı

Alışmışı zapt eylesen durur mu

Dört mevsimde ağaç meyve verir mi

Kar-kış başka, bahar başka, yaz başka

Dost bilirsin gün gelir de küserler

Aş verirsin, döner zehir kusarlar

Yaramıza durup durup basarlar

İlaç başka, merhem başka, tuz başka

Hem tâat, hem ihsan kulu kul eden

Bülbülün sevdası gülü gül eden

Aşığın gönlünü yakıp kül eden

Ateş başka, duman başka, köz başka

Elazığ /2026', 'Bakıp ayırt etmek zor gelir ama Tavuk başka, ördek başka, gaz başka Deveyi zorlasan çıkar mı dama Yokuş başka, tümsek başka, düz başka Dil k...', ARRAY['Türk Edebiyatı','Şiir','Vedat Yılmaz']::text[], 8.5, '{"poet":"Vedat Yılmaz","poet_slug":"vedat-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baska-209-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Oyunu', 'hayat-oyunu-kazim-karagoz-hcxda', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zaman sessiz testere, kesilen ise boyun,

Buna rağmen sanan çok bu hayatı bir oyun.', 'Zaman sessiz testere, kesilen ise boyun, Buna rağmen sanan çok bu hayatı bir oyun....', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/hayat-oyunu-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Olmak Olmamak', 'i-nsan-olmak-olmamak-kazim-karagoz-hxd0z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göründüğün gibi olmalı yoksa olma hiç,

Düşük insan olmaktan olmamak iyidir hiç.', 'Göründüğün gibi olmalı yoksa olma hiç, Düşük insan olmaktan olmamak iyidir hiç....', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/insan-olmak-olmamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemini Çok Olan', 'yemini-cok-olan-kazim-karagoz-s2jz3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yemini çok olanın yalanı da çok olur,

Onu kendisi gibi sananı da çok olur.', 'Yemini çok olanın yalanı da çok olur, Onu kendisi gibi sananı da çok olur....', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/yemini-cok-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçiyorum', 'vazgeciyorum-murat-acer-y9m1n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'VAZGEÇİYORUM

Artık kararımı verdim sevdiğim,

Seni hayatımdan çıkarıyorum.

Bak yine yollara ağla sevdiğim,

Hayalini maziye hapsediyorum.

​Bir düş kuruyordum gelirsin diye,

Ümidim var idi seversin diye.

Faili meçhulsün artık gönlüme,

Seni düşünmeyi bırakıyorum.

​Çok sevdim bilirsin yüreğim saftı,

Uğrunda bu canım çok defa yandı.

Tükendi umudum artık kalmadı,

Seni yüreğimde katlediyorum.

​İster sitem anla ister beddua,

Kapansın yollarım çıkmasın sana.

Ben yaşarken öldüm senin uğruna,

Aşkın ateşini söndürüyorum.

​Gözümden dökülen yaşları sildim,

Sensiz bu dünyada gurbette kaldım.

En büyük hatam seni sevmekti bildim,

Adını kalbimden koparıyorum.

​Yıldızlar kayboldu ışıksız kaldım,

Ben senin aşkından nasipsiz kaldım.

Artık yabancıdan kalmadı farkın,

Defteri sonsuza dek kapatıyorum.

​Bozuldu bağlarım bitti hevesim,

Tükendi kalmadı ten de nefesim.

Haram olsun sana artık bu sevgim,

Ben bu acı sevdadan  vazgeçiyorum. 

Murat Acer', 'VAZGEÇİYORUM Artık kararımı verdim sevdiğim, Seni hayatımdan çıkarıyorum. Bak yine yollara ağla sevdiğim, Hayalini maziye hapsediyorum. ​Bir...', ARRAY['Türk Edebiyatı','Şiir','Murat Acer']::text[], 8.5, '{"poet":"Murat Acer","poet_slug":"murat-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/vazgeciyorum-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Gibi Bilmiştir Okumuştur', 'adi-gibi-bilmistir-okumustur-i-lyas-ates-9ctgm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Cehennemin en alt tabakasına düşmüş olanlar

istemeyerek ölümü isteyeceklerdir 

En alt tabakaya düşmüş olanlar bütün alemler

bir olsa dahi kendisini kurtaramayacaklarını 

bilirler 

O artık çaresizdir o kendisini bu cehenneme 

atanın tek olduğunu adı gibi bilmiştir okumuştur', 'Cehennemin en alt tabakasına düşmüş olanlar istemeyerek ölümü isteyeceklerdir  En alt tabakaya düşmüş olanlar bütün alemler bir olsa dahi ke...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/adi-gibi-bilmistir-okumustur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizlerse Birer Hiçsinizdir', 'sizlerse-birer-hicsinizdir-i-lyas-ates-uj790', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşarken cehenneme düşmüş olanlar ölümden

değil yaşamdan korkacaklardır 

Bir kimse sürekli ölümden söz ediyorsa ölüme

meydan okuyordur

Bire bir cehennemi yaşamış olanlar cehennem

aramayacaklardır onlar cehennemde yıllarca

yaşamışlardır

Cehennemde yaşamış olanlar tek kurtuluşun

ölüm olduğunu bilirler fakat tek Hükümdar 

dilediğine dilediği kararı verecektir her şey

onun vicdanına kalmıştır sizlerse birer hiçsinizdir', 'Yaşarken cehenneme düşmüş olanlar ölümden değil yaşamdan korkacaklardır  Bir kimse sürekli ölümden söz ediyorsa ölüme meydan okuyordur Bire ...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sizlerse-birer-hicsinizdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar 108', 'aforizmalar-108-ozan-agri-imzif', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"Herkesin gürültüyle haklı çıkmaya çalıştığı bir dünyada, sessizce haklı kalabilmenin de bir asaleti var."', '"Herkesin gürültüyle haklı çıkmaya çalıştığı bir dünyada, sessizce haklı kalabilmenin de bir asaleti var."...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ağrı']::text[], 8.5, '{"poet":"Ozan Ağrı","poet_slug":"ozan-agri","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/aforizmalar-108-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar 106', 'aforizmalar-106-ozan-agri-z9ck6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bekledikçe yoruldum sanıyordum. Meğer ben beklerken, biri de beni bekliyormuş. Kavuşmak, iki sabrın birbirine denk gelmesiymiş."', 'Bekledikçe yoruldum sanıyordum. Meğer ben beklerken, biri de beni bekliyormuş. Kavuşmak, iki sabrın birbirine denk gelmesiymiş."...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ağrı']::text[], 8.5, '{"poet":"Ozan Ağrı","poet_slug":"ozan-agri","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/aforizmalar-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aforizmalar 105', 'aforizmalar-105-ozan-agri-9gj7m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '"Acılarını bile zarafetle taşıyan kadınların hayranıyım. Bazı güzellikler, insanın başına gelenlerden değil, onlara rağmen nasıl kaldığından doğar."', '"Acılarını bile zarafetle taşıyan kadınların hayranıyım. Bazı güzellikler, insanın başına gelenlerden değil, onlara rağmen nasıl kaldığından...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ağrı']::text[], 8.5, '{"poet":"Ozan Ağrı","poet_slug":"ozan-agri","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/aforizmalar-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümde Kalan Mevsimler', 'gonlumde-kalan-mevsimler-yucel-ozku-sskqh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'GÖNLÜMDE KALAN MEVSİMLER

Zaman aktı, ömrümden sessizce,

Nice bahar geçti gönlümden gizlice.

Gençliğim sararmış bir yaprak gibi,

Savruldu uzaklara sonbahar gecesi.

İçimde sakladım nice özlemi,

Söylenmemiş sözler eskitti beni.

Bir ömür beklediğim bahar çiçeği,

Açmadan terk etti gönül bahçemi.

Bir sevda göç eder, hatırası kalır,

Bir güzel söz yıllar geçse de yaşar.

İnsan bu dünyadan sessizce gider,

Gönülde bıraktığı iyilik yaşar.

Bir gün adım düşerse bir şiire,

Bir turna kanadı değer hatıralara.

Ömür dediğin geçici bir bahar,

İnsan gider, sevgisi kalır geriye.

YÜCEL ÖZKÜ

20 Kasım 2026/09:11', 'GÖNLÜMDE KALAN MEVSİMLER Zaman aktı, ömrümden sessizce, Nice bahar geçti gönlümden gizlice. Gençliğim sararmış bir yaprak gibi, Savruldu uza...', ARRAY['Türk Edebiyatı','Şiir','Yücel Özkü']::text[], 8.5, '{"poet":"Yücel Özkü","poet_slug":"yucel-ozku","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gonlumde-kalan-mevsimler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çile Deryası Oldu Hayatım', 'cile-deryasi-oldu-hayatim-ahmet-kolecioglu-3j2bg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüreğime verdin zorlu bir acı

kavuşmamız yakın diyen yalancı

yılların silmeye yetmiyor gücü

hasretin özlemin içimde sancı

bir çile deryası oldu hayatım

yaşantımda huzur kalmadı benim

hep dertli geçiyor bütün günlerim

artıyor bitmiyor her gün kederim

senden ayrı sensiz geçen her günüm

kederden perişan şu garip gönlüm

sensizlik zor bana çaresiz halim

sinsi karanlıkta bekliyor ölüm

ne hallere koydu beni bu sevda

verdiğin dertlere yok imiş deva

çok çileler çektim pek çokta cefa

mutlu olup bir gün sürmedim sefa

kölecioğlu der ki vicdansız seni

vuslatsız ömrümün hep kara günü

hayat pusulası şaşırdı yönü

yitirdi yaşantım gün ile dünü

Ahmet kölecioğlu     2015', 'yüreğime verdin zorlu bir acı kavuşmamız yakın diyen yalancı yılların silmeye yetmiyor gücü hasretin özlemin içimde sancı bir çile deryası o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kölecioğlu']::text[], 8.5, '{"poet":"Ahmet Kölecioğlu","poet_slug":"ahmet-kolecioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/cile-deryasi-oldu-hayatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapay zekâ', 'yapay-zek-hasan-belek-2-a4wbw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YAPAY ZEKÂ

​İnsan kumdan telden bir âlem kurdu,

Çağların ilmine mührünü vurdu,

Adı yapay zekâ karşıda durdu,

Işıktan örülmüş yeni bir asır.

​Hesabın üstüne hesaplar katar,

Cihanın belleği derinde yatar,

Ne göğsü daralır ne kalbi atar,

Yürek ısıtır mı soğuk bir satır?

​Kusursuz mantığı bir adım sekmez,

Yağmur kokusunu içine çekmez,

Gönül bahçesine bir umut ekmez,

Camdan bakışları feryada sağır.

​Merhamet gizlidir titreyen sözde,

İnsanlık okunur yaşaran gözde,

Vicdanın mayası yoğrulur özde,

Sayıyla tartılmaz vefa ve sabır.

​Makine konuşsa neye bu telaş,

İnsan soğuyup da kesilmesin taş,

Dostun tebessümü ömre bir yoldaş,

Sinede saklıdır kırk yıllık hatır.

​Ekrandan dökülse bin türlü lisan,

Sevgi olmayınca her akıl noksan,

Ruhun nefesiyle söyler Kul Hasan,

Çözülmez ezelden insandaki sır.

T.C. Kültür ve Turizm Bakanlığı Halk Şairi

Hasan Belek (Kul Hasan) - Akçay

18.11.2026', 'YAPAY ZEKÂ ​İnsan kumdan telden bir âlem kurdu, Çağların ilmine mührünü vurdu, Adı yapay zekâ karşıda durdu, Işıktan örülmüş yeni bir asır. ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Belek 2']::text[], 8.5, '{"poet":"Hasan Belek 2","poet_slug":"hasan-belek-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yapay-zeka-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siham-ı Akışkan', 'siham-i-akiskan-dogukan-yegin-fajql', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SİHÂM-I AKIŞKAN

* Nef‘î’nin Sihâm-ı Kazâ hiciv geleneğiyle, Akışkan’a hitaben yazılmış özgün taşlama *

Ey Akışkan, cehlini hikmet diye satan a köpek,

Kande sen, kande hakikat, kande irfan a köpek!

Vay o meclise ki sen olmuşsun akıl hocası,

Bir senin gibisini eyler mi insan muhterem a köpek!

Otizmi diline doladın, fikrime cevap vermedin,

Cehlini eyledin âleme mücessem a köpek!

Hangi kitap, hangi ilim verdi sana bu hükmü?

Kendi götünden mi çıktı bunca ahkâm a köpek!

Ben tarih açtım önüne, sen kimliğime saldırdın,

Ne biçim münazaradır bu, ne biçim kelâm a köpek!

Sözümün karşısına koyacak delilin yok ise,

Siktir olup gitmeyesin de ne eylersin a köpek!

Otizmli olmak suç değil, ayıp değil, zillet değil,

Asıl ayıp cehlini satmaktır her dem a köpek!

Benim aklım, benim sözüm, benim şahsiyetim benim,

Sana mı kaldı bunlara biçmek hükm ü kalem a köpek!

Bir gün mağdur dersin bana, ertesi gün takıntılı,

Bu ne boktan tutarsızlık, bu ne sahte hükem a köpek!

Ne zaman delil istesem sözümü çevirip kaçarsın,

İlimden bu kadar korkar mı hiç âdem a köpek!

Kendini allâme sanıp kürsülerden hükmedersin,

Bilmezsin ki boş tenekenin gürültüsü muazzam a köpek!

Ehl-i fikre düşman olup alay edersin kimlikle,

Böyle mi olur münazara, böyle mi edep a köpek!

Ne sen benim sahibimsin ne de sen benim vasim,

Haddini bil, kendini sanma hâkim-i âlem a köpek!

İki Nisan gelince herkes birden dost kesilir,

Sonra dökülür dillerden bin türlü sitem a köpek!

Biz ne senin konu mankenin ne de fikrinin kuluyuz,

Kim verdi sana üzerimizde saltanat a köpek!

Ben belge koydum ortaya, sen hakaretle övündün,

Şimdi oku satır satır, işte sana cevabım a köpek!

Kırk yedi sahife koydum, aç da oku bir zahmet,

Sözden kaçıp durma artık, göster bir hüccet a köpek!

Soysuzluk soydan değil, insanın ettiği iştendir,

Cehlini soya bağlamam, sana yeter amel a köpek!

Hak aramak suç değildir, hakkı çiğnemek marifet değil,

Ne sikik bir saltanattır kurduğun vehim a köpek!

Sanma ki küfrümden ibarettir bütün söylediklerim,

Ardında tarih var, vesika var, ilm ü rakam a köpek!

İftiradan, yaftalamaktan kurduğun taht devrilir,

Bir sağlam delil karşısında kalırsın mülzem a köpek!

Ne methini isterim senin ne de sahte merhametini,

Yeter ki çek dilini kimliğimden, ol âdem a köpek!

Geldi mi hesap günü sözden, belgeden kaçılmaz,

Benim mızrağım kalemdir, kâğıdımdır siperim a köpek!

Sikimde değildir şöhretin, takipçin, sahte debdeben,

Hakikate karşı ne hükmün var ne de kudretin a köpek!

Nef‘î okunu sözle atar, ben vesikayla yürürüm,

İnsan olmayı öğren evvel, sonra konuş a köpek!

Bu metin, Nef‘î’nin özgün şiiri değil; onun sert hiciv üslubunu, beyit düzenini, Osmanlıca söz varlığını ve “a köpek” redifini esas alan çağdaş bir taşlamadır.', 'SİHÂM-I AKIŞKAN * Nef‘î’nin Sihâm-ı Kazâ hiciv geleneğiyle, Akışkan’a hitaben yazılmış özgün taşlama * Ey Akışkan, cehlini hikmet diye satan...', ARRAY['Türk Edebiyatı','Şiir','Doğukan Yegin']::text[], 8.5, '{"poet":"Doğukan Yegin","poet_slug":"dogukan-yegin","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/siham-i-akiskan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmanın Kırmızısı', 'susmanin-kirmizisi-sahin-cinar-s5kgq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir renk vardı, küskün;

için için soldu

gözlerimin hazanında.

Yapraklar gibi savruldu.

Bir zamanlar ne vardı orada,

artık hatırlamıyorum.

Kapanmayan bir pencere gibi

açık kaldı boşluğu.

Sen o gün,

hiç okunmamış bir cümlenin

en ıssız yerinden geçtin.

Ben pencerenin yanında durdum,

çağırmadım seni.

O an içimde bir nar yarıldı.

Ne bir ses çıktı

ne de mevsim;

yalnızca eskinin kırmızısı.

Kabuğunda zamanın

ince çatlakları,

içinde birbirine değmeden

kocayan ömürler...

Ben seni hiçbir mevsime

benzetmedim;

hiçbir renge de.

Mevsimler geçer,

renkler solar.

İçimde bir bahar vardı,

toprağa düşmemiş.

Kökleri hiçbir yere değmemiş,

rengini güneşten değil

bekleyişten almış.

Sonra bir gün,

beli bükülmüş bir dalın ucunda

meyvenin ağırlığına baktım.

İnsan da taşıdığı kadar

eğiliyordu hayata;

benim eğildiğim yeri

kimse görmedi.

Şimdi geride ne takvim,

ne de yolunu bilen

bir rüzgâr kaldı.

İçimde hiç susmayan

kırmızının inadı.', 'Bir renk vardı, küskün; için için soldu gözlerimin hazanında. Yapraklar gibi savruldu. Bir zamanlar ne vardı orada, artık hatırlamıyorum. Ka...', ARRAY['Türk Edebiyatı','Şiir','Şahin Çınar']::text[], 8.5, '{"poet":"Şahin Çınar","poet_slug":"sahin-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/susmanin-kirmizisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasalar.', 'yasalar-fehmi-tazegul-ah3re', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haksızlık gidiyor yobazın hoşuna.

Bu düzende her şey oldu imkânsız.

Gerçekleri konuşuruz boşu boşuna.

Kanunlar yasalar olmuştur insafsız.

Dinle imanla yapıyorlar hep talan.

Siyaset şimdi olmuştur koca yalan.

Ödül alıyorlar hırsız haksızla çalan.

Kanunlar yasalar olmuştur insafsız.

Olmuşlar padişah yazdılar ferman.

Ülkemiz olmuştur güvensiz liman.

Camide para kazanıyor dinle iman.

Kanunlar yasalar olmuştur insafsız.

Fehmi.

Gerçekleri yazdım hep cezalı oldum.

Her yerde haksızlıklar ben bunaldım.

Yalan dolanla yoldaş şaşırdım kaldım.

Kanunlar yasalar olmuştur insafsız.', 'Haksızlık gidiyor yobazın hoşuna. Bu düzende her şey oldu imkânsız. Gerçekleri konuşuruz boşu boşuna. Kanunlar yasalar olmuştur insafsız. Di...', ARRAY['Türk Edebiyatı','Şiir','Fehmi Tazegül']::text[], 8.5, '{"poet":"Fehmi Tazegül","poet_slug":"fehmi-tazegul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasalar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizlerin Ne Düşündüğü', 'sizlerin-ne-dusundugu-i-lyas-ates-2nt8r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zindana düşüşümüz nede kurtuluşumuz 

elimizdedir

Zindancı önce hayaller kurar sonra hayallerini gerçekleştirir 

Zindancı bahaneler üretip dilediğini yaşatır

dilediğine çektirir dilediğini asar dilediğini

ise keser kimsede hesap soramayacaktır

Zindancı kendi büyüklüğünü kanıtlamak 

için bütün acımasızlığını gösterecektir ve

göstermektedir sizlerin ne düşündüğü önemli

değildir', 'Ne zindana düşüşümüz nede kurtuluşumuz  elimizdedir Zindancı önce hayaller kurar sonra hayallerini gerçekleştirir  Zindancı bahaneler üretip...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sizlerin-ne-dusundugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Suhreva''da Aşk Başka', 'suhreva-da-ask-baska-fatma-dogan-gw3cw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SUHREVA’DA AŞK BAŞKA

Irmaklara karıştığında yalnızlığım

Bu kaçıncı koğuştan firar edişim sel gibi

Bilmiyorsun Madubala

İçimde Fırtınalar o biçim

O biçim ki

Karıştırır Suhreva’mın taralı saçlarını

Karıştırır saçımın sakalımın ağarık coğrafyasını

Hiçbir şey eskisi gibi değildir artık bende

Ne yeryüzümde derin çizgiler,

Ne zihnimde dürülüp bükülmüş anılar,

Bakışım bile, aşina değil kendime

Bildiğin el, yabancı…. 

Yaş yarıyı aşınca bir metafor yağmuruna tutuluyor insan

Deliniyor gerçekliğin küstah zırhı, 

Sızıyor, hayal düş ne varsa 

Dilinde savruk bir avare şarkısı kalan

Ha babam de babam  dörtnala koşan köse bir ata

Ökçeni vurup hoo der gibi , 

Ya da kasıp gemini, birden

Dizginlersin anca şahlanan zamanı

Seyreltilmiş tırıs adımlarımız şekillendiriyor Suhrevayı,

Asil ve mağrur yağıyor şimdi üzerimize yağmur 

Yürüyoruz el ele..yan yana

Kınalı bileğine dolanmış yılan gibi Ganj

Fırtınalar dinince çözülüyor tuti dilin Madubala

Bir şarkı oluyorsun bir şiir

Bir ab-ı derya oluyorsun 

Bir nehir… 

Yaş yarıyı aşınca bir aşk sağnağı vuruyor insanı

Kaçsa da sırılsıklam ıslatan

Bir yudum deniz gibi genzimi buruyor o tad

Katreler şekillendiriyor Suhrevanın boz çehresini

Yeşil mi yeşil, sulak mı sulak

Bir hayal oluyorsun, bir gerçek

Güneş hüzmeleri kırıyor kalbin yedi renkli sır kilidini

Dilimde yanık bir maraja ağıdı

Bir Mecnun oluyorum bir Ferhat

Bir dağ oluyorum delik deşik, bir uçsuz bucaksız çöl…

Irmaklara karıştığında yalnızlığım

Bu kaçıncı koğuştan firar edişim sel gibi

Bilmiyorsun Madubala

İçimde kıyametler o biçim

Bir inşirah oluyorsun bana

Bir aşka sürgün…

FATMA DOĞAN 20.11.2026/turhal', 'SUHREVA’DA AŞK BAŞKA Irmaklara karıştığında yalnızlığım Bu kaçıncı koğuştan firar edişim sel gibi Bilmiyorsun Madubala İçimde Fırtınalar o b...', ARRAY['Türk Edebiyatı','Şiir','Fatma Doğan']::text[], 8.5, '{"poet":"Fatma Doğan","poet_slug":"fatma-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/suhreva-da-ask-baska-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün diyeceksin ki  O reis kırıyordu, kızıyordu,tutarsızdı,deli doluydu ama koşulsuz, karşılıksız, tek taraflı seven bir adamdı diyeceksin...', 'birgun-diyeceksin-ki-o-reis-kiriyordu-kiziyordu-tutarsizdi-deli-doluydu-ama-kosulsuz-karsiliksiz-tek-tarafli-seven-bir-adamdi-diyeceksin-gokhan-gun-w9es6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birgün diyeceksin ki  O reis kırıyordu, kızıyordu,tutarsızdı,deli doluydu ama koşulsuz, karşılıksız, tek taraflı seven bir adamdı diyeceksin...', 'Birgün diyeceksin ki  O reis kırıyordu, kızıyordu,tutarsızdı,deli doluydu ama koşulsuz, karşılıksız, tek taraflı seven bir adamdı diyeceksin...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gün']::text[], 8.5, '{"poet":"Gökhan Gün","poet_slug":"gokhan-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/birgun-diyeceksin-ki-o-reis-kiriyordu-kiziyordu-tutarsizdi-deli-doluydu-ama-kosulsuz-karsiliksiz-tek-tarafli-seven-bir-adamdi-diyeceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
