INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle bir tesadüf', 'seninle-bir-tesaduf-i-hsan-yilmaz-u3x63', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SENİNLE BİR TESADÜF

— İhsan YILMAZ

Seninle bir tesadüf eseri karşılaştık, Ama gözlerine baktığım ilk anda, Anladım ki bazı karşılaşmalar tesadüf değil, Kaderin kalbe yazdığı en güzel hikâyeymiş.

Bir bakışın içime işledi, Bir gülüşün ruhuma dokundu. Ne seni arıyordum ne de aşkı, Ama sen çıktın karşıma, Ve bütün yollarım sana döndü.

Şimdi düşünüyorum da, İyi ki o gün, o yerdeydim. İyi ki gözlerin gözlerime değdi. Çünkü bazı insanlar bir ömre, Bir tek tesadüfle sığar.

Kasım/2026', 'SENİNLE BİR TESADÜF — İhsan YILMAZ Seninle bir tesadüf eseri karşılaştık, Ama gözlerine baktığım ilk anda, Anladım ki bazı karşılaşmalar tes...', ARRAY['Türk Edebiyatı','Şiir','İhsan Yılmaz']::text[], 8.5, '{"poet":"İhsan Yılmaz","poet_slug":"i-hsan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seninle-bir-tesaduf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular Durulmaz', 'sular-durulmaz-hasan-arpaci-lphai', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlemek gecenin ruhunda varken,

Kim demiş bu mevsim çiçekler açmaz.

Yağmur damla damla gülüp oynarken,

Kim demiş bu mevsim böcekler uçmaz.

Biz kinin dibine kibrit suyunu,

Dökeli çok oldu bozduk oyunu,

Bu yaz da yaylaya saldık koyunu,

Kim demiş ırmaklar sular durulmaz.

Az veren candanmış çok veren maldan,

Sevgi de böyledir asalet kandan,

Gelsede… ah kalbim! dayan ha dayan,

Ömür geçip gider hayali kalmaz.

Hasan bu alemin vefası yoktur,

Nereye bakarsan cefası çoktur,

Cefanın acısı kalbe konuktur,

Böylesi haller hiç hayra yorulmaz.

Hasan Arpacı, 2025, Üsküdar', 'Özlemek gecenin ruhunda varken, Kim demiş bu mevsim çiçekler açmaz. Yağmur damla damla gülüp oynarken, Kim demiş bu mevsim böcekler uçmaz. B...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arpaci']::text[], 8.5, '{"poet":"Hasan Arpaci","poet_slug":"hasan-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sular-durulmaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader Beni Unutmuş', 'kader-beni-unutmus-mustafa-kaynak-2-z7psl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yoruldum dünyanın çilesi ile,

Bir derman bulamadım derdime.

Geceler oldu dert ortağım,

Bir gülen bulamadım yüzüme.

Gönlümde açılan yaralar derin,

Ne gelenim oldu ne soranım benim.

Herkes kendi derdine düşmüş,

Bu garip hâlimi gören var mı benim?

Kader beni unutmuş, yazım kara,

Düştüm gurbet elde uzak yollara.

Her gece dertliyim, bitmiyor çilem,

Yansam da su veren olmuyor bana.

Bir dost selamını esirgeyen çok,

Gülmeye hasretim, ağlayanım yok.

Dost bildiklerim hep vefası yalan,

Derdimi anlatsam var mı ki soran?

Ele bahar gelmiş, bana güz var,

Ömrümün baharı olmuş sonbahar.

Bir ömür bekledim, gelmedi yâr,

Yazım değişmez, gelse de bahar.

Kader beni unutmuş, yazım kara,

Düştüm gurbet elde uzak yollara.

Her gece dertliyim, bitmiyor çilem,

Yansam da su veren olmuyor bana.

Mustafa Kaynak', 'Yoruldum dünyanın çilesi ile, Bir derman bulamadım derdime. Geceler oldu dert ortağım, Bir gülen bulamadım yüzüme. Gönlümde açılan yaralar d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kader-beni-unutmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir sözleri 3', 'siir-sozleri-3-mehmet-hanifi-ocal-2-026rh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan çoğu kez mutluluğunu erteliyor mutlu olmak için cabaladiginda mutsuz olabiliyor insan bu bazen bir evlat,bir kardeş,bir Arkadaş bir sevgili çoğu zamanda havadan sudan yerli yersiz, gereksiz. İşte ozaman tükenir insan, farkına vardığında İş işten geçmiştir.Mutluluk  gereksizdir artik yanar kendi haline, mutlu olmak için çabaladiklarina, oysa bütün mutluluklar böyledir   birtek vefasızlara dağıtınca çoğalmıyor,

Mutsuz Olmanin tek nedeni Mutlulukların hoyratca tüketilmesidir.', 'İnsan çoğu kez mutluluğunu erteliyor mutlu olmak için cabaladiginda mutsuz olabiliyor insan bu bazen bir evlat,bir kardeş,bir Arkadaş bir se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hanifi Öcal 2']::text[], 8.5, '{"poet":"Mehmet Hanifi Öcal 2","poet_slug":"mehmet-hanifi-ocal-2","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/siir-sozu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-ayhan-maloglu-2-kclpy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni..

Göklerde aradım..

Gündüz bakamadığım..

Güneşte..

Gece..

Parlayan yıldızlarda..

Rahmet yüklü..

Bulutlarda..

Yüzümü okşayan..

Rüzgarlarda buldum..

Seni..

Yerde aradım..

İnsan kokan..

Bir bebeğin gülüşlerinde..

Bir kelebeğin kanatlarında..

Bir karıncanın, arının..

Yaptıklarında..

Senden başka..

Hiç kimsesi kalmamış..

Kimsesizlerin..

Gözyaşlarında buldum..

Seni..

Bende aradım..

Sadece bana ait..

Parmak izlerimde..

Küçücük bir noktadan..

Kainatı seyreden..

Gözlerimde..

Nefeslerimde..

Hayatta kalmam için..

Gece gündüz atan..

Kalbimde buldum..

Oysa..

Sen hep bende..

Ban en yakın..

Şah..

Damarımdaymışsın..

Körlük bende..

Seni..

Kendi dışımdaki..

Arayışım için..

Senden..

Özür dilerim..

Ayhan M.', 'Seni.. Göklerde aradım.. Gündüz bakamadığım.. Güneşte.. Gece.. Parlayan yıldızlarda.. Rahmet yüklü.. Bulutlarda.. Yüzümü okşayan.. Rüzgarlar...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Maloglu 2']::text[], 8.5, '{"poet":"Ayhan Maloglu 2","poet_slug":"ayhan-maloglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/arayis-608-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan... 1', 'i-nsan-1-sedat-hunker-ew9m9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir insan kalpli insan hatırlıyorsa

İnsani kalbi yaşamaya yaşamaya unuttuğundandır

Bir insan niyetli insan hatırlıyorsa

İnsani niyeti i yaşamaya yaşamaya unuttuğundandır

Bir insan huylu insan hatırlıyorsa

İnsani huylu yaşamaya yaşamaya unuttuğundandır

Bir insan arsız insan hatırlıyorsa

İnsani arlı yaşamaya yaşamaya unuttuğundandır

Bir dilli insan hatırlıyorsa

İnsani dilli yaşamaya yaşamaya unuttuğundandır

Bir insan sağsız insan hatırlıyorsa

İnsani sağcı yaşamaya yaşamaya unuttuğundandır

Bir insan sevsiz insan hatırlıyorsa

İnsani sevli yaşamaya yaşamaya unuttuğundandır

Bir insan şerefsiz insan hatırlıyorsa

İnsani şerefli yaşamaya yaşamaya 

Bir insan iyisiz insan hatırlıyorsa

İnsani iyi yaşamaya yaşamaya unuttuğundandır

Bir insan hayırsız insan hatırlıyorsa

İnsani hayırlı yaşamaya yaşamaya unuttuğundandır

Bir insan temizsiz insan hatırlıyorsa

İnsani temiz yaşamaya yaşamaya unuttuğundandır

Bir insan doğrusuz insan hatırlıyorsa

İnsani doğru yaşamaya yaşamaya unuttuğundandır

Bir insan helalsiz insan hatırlıyorsa

İnsani helalli yaşamaya yaşamaya unuttuğundandır

Bir insan insanisiz insan hatırlıyorsa

İnsani insanlık yaşamaya yaşamaya unuttuğundandır

Kara mecnun

İnsanur(nurlu) 

İnsanur/suz(nurlu ve nursuz) 

İnsanursuz(nursuz)', 'Bir insan kalpli insan hatırlıyorsa İnsani kalbi yaşamaya yaşamaya unuttuğundandır Bir insan niyetli insan hatırlıyorsa İnsani niyeti i yaşa...', ARRAY['Türk Edebiyatı','Şiir','Sedat Hünker']::text[], 8.5, '{"poet":"Sedat Hünker","poet_slug":"sedat-hunker","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/insan-1-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin Seni Geri Koyan', 'sensin-seni-geri-koyan-huseyin-sigirtmac-ot4zk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sebep arama derdine.

Sensin seni geri koyan.

Bakmadın vatan yurduna.

Sensin seni geri koyan.

Öne çıkardın zalimi.

Geride koydun alimi.

Tasviye ettin bilimi.

Sensin seni geri koyan.

Öne aldın hıyarları

Bozdun bütün ayarları.

Düşünmedin değerleri.

Sensin seni geri koyan.

Tamah ettin kaşık bala.

Barikat çektin her yola.

Kim kaldı senle kolkola.

Sensin seni geri koyan.

Hürafeyi aldın öne.

Bilimi kaldırdın sona.

Yaz günü kalırsın dona.

Sensin seni geri koyan.

Düşünmedin Sığırtmaç''ı.

Yüreğine kattın acı.

Perişanız kardeş, bacı.

Sensin bizi geri koyan.

Hüseyin SIĞIRTMAÇ

Antalya 21 Kasım 2026', 'Sebep arama derdine. Sensin seni geri koyan. Bakmadın vatan yurduna. Sensin seni geri koyan. Öne çıkardın zalimi. Geride koydun alimi. Tasvi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sensin-seni-geri-koyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Ezanımı Dinler Gibi', 'son-ezanimi-dinler-gibi-dr-yusuf-polat-lkpu0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyduğum her ezanı, son ezanım bilirim,

Bir daha dinlemeyecekmiş gibi dinlerim.

Her tekbirde biraz daha 

Susar içimde dünya,

Her secdede Rabbime yaklaşırım az daha

Gökyüzüne baksam son yıldızım kaybolur

Dolunayı seyrederim 

Son gecem gibi bakarım göklere

Bir şiirin son mısraında bırakırım kendimi,

Yüzünü son kez görüyormuş gibi özlerim.

Çünkü ömür dediğin, avuçta duran bir su,

Ne kadar sımsıkı tutsan da akıp gider.

Bir nefeslik huzur düşer 

Bazen yüreğime,

İnsan huzuru kaybetmemek için dua eder.

Dolunay kadar büyük umut taşırım içimde,

Kâinat kadar geniş olsun isterim gönlüm.

Ne saltanata aldanırım 

Ne de dünyanın o anlık süsüne,

Zalimin gölgesinde solmayan ömür isterim

Ey Rabbim!

Ben bazen kendime bile geç kaldım,

Bazen nefsimin ardında yolumu kaybettim.

Dünya denilen bu uzun yolculukta

Nice nimeti gördüm de şükür de geciktim

Şimdi bir seher vaktidir, kapındayım,

Ne mazeretim kaldı 

Ne de saklayacak günahım.

Beni bana bırakma, 

Ey merhametlilerin en merhametlisi,

Benim 

Senden başka sığınacak kimim var ki; Rabbim', 'Duyduğum her ezanı, son ezanım bilirim, Bir daha dinlemeyecekmiş gibi dinlerim. Her tekbirde biraz daha  Susar içimde dünya, Her secdede Rab...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/son-ezanimi-dinler-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Mekanda', 'ayni-mekanda-i-lyas-ates-fde4k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Cennetle cehennem aynı mekanda ayrı dünyaların 

yaşadığı birbirlerini fark etmedikleri yerin adıdır 

Cennetle cehennem gözler önünde sürekli yaşanmaktadır

kimse nerede yaşadığını bilmemektedir 

Nerede yaşadığınızı fark etmeniz için acılar içinde

kıvranıp kıvranmadığınıza veya huzur içinde olup

olmadığınıza bakın göreceksiniz', 'Cennetle cehennem aynı mekanda ayrı dünyaların  yaşadığı birbirlerini fark etmedikleri yerin adıdır  Cennetle cehennem gözler önünde sürekli...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayni-mekanda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Razısın', 'razisin-kenan-gezici-bidwg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herkes zannediyor, bu bakan gözler nasılda kör.

Çoğu da azı da etti sizi, en büyük günahkâr kul.

Sarmış ruhlarını toz bulutu bakanda, bakmayanda kör.

Yaslanmayın insan seslerine beklesinler bir köşede.

Şu aynada duran yüz ben miyim diye sorsa beni ah Mira.

Alışma derim olma sakın benim gurbetimde bekleyen.

Bin parça olmuşum ben hey, hasret bütüne şeyda.

Daha nasıl olacak niçin sevsin kül olmuş, bin parça.

Değsin ayaklarımıza serin ıslak nemli kırlar.

Alacağım bir elindir razı dünden gelmeye Mira.

Ne bir söz sana düşer, sus sakın etme bir kelime.

Nasıl duracaksın, senin ruhun bana şeyda.

Kenan GEZİCİ   20/11/2026', 'Herkes zannediyor, bu bakan gözler nasılda kör. Çoğu da azı da etti sizi, en büyük günahkâr kul. Sarmış ruhlarını toz bulutu bakanda, bakmay...', ARRAY['Türk Edebiyatı','Şiir','Kenan Gezici']::text[], 8.5, '{"poet":"Kenan Gezici","poet_slug":"kenan-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/razisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendrom', 'sendrom-zaman-melankoli-shx1l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bacağım daha huzursuz diğerinden

Zarar da vermedim bihaberim derdinden

Dinlenmeden ne yokuş iner ne de çıkar

Bütün yükü diğer bacağıma yıkar

Sızlanır gece uykuya çekilince

Derdi kasılmaktır gönlünce

Unutmuş görünür koşturduğumuz günleri

Sevgiliye vardığımız telaşlı halleri

Sadece bahçeye varınca durulur, göllenir

Ağaçlar çiçekler arasında eğlenir

Dönelim eve dersem dellenir

Huysuz çocuk oldu bacağım', 'Bir bacağım daha huzursuz diğerinden Zarar da vermedim bihaberim derdinden Dinlenmeden ne yokuş iner ne de çıkar Bütün yükü diğer bacağıma y...', ARRAY['Türk Edebiyatı','Şiir','Zaman Melankoli']::text[], 8.5, '{"poet":"Zaman Melankoli","poet_slug":"zaman-melankoli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sendrom-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haksız yere hayattan koparılan insanlara', 'haksiz-yere-hayattan-koparilan-insanlara-arsipel-ren-swx50', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '22 Eylül 2026 – Salı

Yalnızım gün doğarken,
yalnızım gün batarken.
Yalnızım hayatta,
tek başıma doğarken.

Yalnızsın katledilirken,
yalnızsın katille yan yanayken,
yalnızsın katil sokaktayken,
tek başına adaleti beklerken.

Sen yoksun kalpsizler sokakta.

Yalnızdın gafil avlanırken,
yalnızdın ruhun çaresiz kalırken,
yalnızdın bedenine kirli eller değerken,
sen yoksun adalet sağlanmazken.

Sen yoksun katiller sokaktayken,
sen yoksun kalpsizler insanlığın içindeyken,
sen yoksun hâkimler rüşvet alırken,
sen yoksun, şimdi hukuk da yok.

Sen olduğunda hukuk var mıydı ki?
Senin yokluğunda hukuk olsun.
Senin yokluğunda hak olsun.

Ne kaldı ki sen gittiğinde,
yurdun içi temiz olsun?', '22 Eylül 2026 – Salı Yalnızım gün doğarken, yalnızım gün batarken. Yalnızım hayatta, tek başıma doğarken. Yalnızsın katledilirken, yalnızsın...', ARRAY['Türk Edebiyatı','Şiir','Arsipel Ren']::text[], 8.5, '{"poet":"Arsipel Ren","poet_slug":"arsipel-ren","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/haksiz-yere-hayattan-koparilan-insanlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kedim', 'kedim-faruk-tosun-rf6v5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biri benimle oynasın diye 

Döner etrafımda pervane

Daima benimle vakit geçirmek ister

Yemeğine bile beraber gitmek ister 

Sabah namazına kaldırmak için çabalar

Namazında etrafımda döner mırıldar

Hasta olana mutlaka ziyarette bulunur

Teselli etmek için göbeğinde uyuklar

Pazardan gelince alınanları kontrol eder

Yiyeceği rokasını, balığını mümkünse ister

Dondurmaya hiç dayanamaz 

Yalayıp yutar hemen doymaz

Evde uzun süre kalınca yalnız

Küser nazlanır karşımıza çıkmaz

Eşyalara kimse zarar veremez

Zarar vermediği eşya var mı bilinmez

Tırmalar, çizer, yırtar perdeleri

Biz yanlış açsak hanımın gözleri

O evin patronu efendisi

Bizler onun köleleri

Ya Rahim diyerek mırlamaları 

Evin bereketi zikirli mırıldanmaları

Evi daima gezen, kontrol bekçisi

Haşeratı görünce, haber eder herkesi

Sevgi merhameti en güzel gösteren

Sohbetlerde konu herkesin kedisinden

Kainatın efendiside severdi sizleri

Kedicik babası Ebu Hureyre sahabesi', 'Biri benimle oynasın diye  Döner etrafımda pervane Daima benimle vakit geçirmek ister Yemeğine bile beraber gitmek ister  Sabah namazına kal...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tosun']::text[], 8.5, '{"poet":"Faruk Tosun","poet_slug":"faruk-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kedim-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanla Sevdim Seni', 'zamanla-sevdim-seni-dr-yusuf-polat-pk4ci', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni öyle bir anda sevdim sanma

Bir yıldırım düşmedi geceme,

Bir sabah ansızın uyanıp

Adını bulmadım sessiz yüreğimde.

Sen içime zamanla ağır ağır işledin,

Kar örtüsünün toprağa değmesi gibi,

Bir çiçeğin güneşe dönmesi,

Bir çocuğun annesine koşması gibi.

Önce senin sesini sevdim,

Sonra sustuğun yerleri...

Bir bakışında saklı kalan

O kimseye söylemediğin asi kederi.

Sonra anladım;

İnsan bazen birini sevmez yalnızca,

Onunla yeniden sever dünyayı.

Bir ağacın gölgesini,

Bir akşamın sessizliğini,

Bir fincan çayın buğusunda

Hayatın bir ucuna tutunmayı...

Senden önce de geçerdi mevsimler,

Ama bahar başka türlü geliyor artık.

Elmalar daha kırmızı, 

Otlar biraz daha gür ve de yeşil

Geceler daha yıldızlı, 

Dolunay daha parlak

Yalnızlık bile daha iyi oldu seninle

Seni sevdim;

Ömrün sonunda unutulmayacak

Bir ömrün içine sığmayacak kadar,

Ne servet istedim senden

Ne de dünyaya hükmeden bir taht.

Biraz gözlerinde kalabilseydim,

Biraz yüreğinde yaşasam yeter bana...

Çünkü dünya dediğin,

Bir gün hepimizi bırakıp gidecek.

Ne saraylar kalacak ne de nefes,

Ne insanın övündüğü dünyalık heves

Geriye belki bir isim, bir dua,

Bir de bir başkasının kalbinde

İz bırakmış olmanın huzuru kalacak.

Seni sevdim, öyle bir sevdim ki;

Artık senden önceki ben, bana yabancı.', 'Seni öyle bir anda sevdim sanma Bir yıldırım düşmedi geceme, Bir sabah ansızın uyanıp Adını bulmadım sessiz yüreğimde. Sen içime zamanla ağı...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/zamanla-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Ağır Yükü', 'sevdanin-agir-yuku-yucel-ozku-refgm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEVDANIN AĞIR YÜKÜ

Sana kırılmıyorum artık,

Ne bir sözüm var ne sitemim.

Ben bir ömrü sana adarken,

Kendimi unutmuşum sevgilim.

Bir bakışına bahar yükledim,

Bir gülüşünle çoğaldı düşlerim.

Sen bir gün gelip geçtin,

Ben yıllarımı sende beklettim.

Kimseyi suçlamıyorum artık,

Ne gidişini ne de susuşunu.

Bir kalp ne kadar sevebilirse,

Ben ömrümce sevdim seni.

Artık adını ansam bile

İçimde eski bir yara sızlamaz.

Yalnız bir şey öğrendim senden:

Her sevda bir ömür taşınmaz.

YÜCEL ÖZKÜ

20 Kasım 2026/06:09', 'SEVDANIN AĞIR YÜKÜ Sana kırılmıyorum artık, Ne bir sözüm var ne sitemim. Ben bir ömrü sana adarken, Kendimi unutmuşum sevgilim. Bir bakışına...', ARRAY['Türk Edebiyatı','Şiir','Yücel Özkü']::text[], 8.5, '{"poet":"Yücel Özkü","poet_slug":"yucel-ozku","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevdanin-agir-yuku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Şeye Benzemez', 'hicbir-seye-benzemez-yucel-ozku-qhkrt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HİÇBİR ŞEYE BENZEMEZ

Adını ansam akşam içinde,

Bir yıldız uyanır gecenin yüzünde.

Hangi mevsim sığar güzelliğine,

Bahar saklı kahve gözlerinde.

Sen geçince değişir akşamın rengi,

Ay ışığı konar kirpiklerine.

Bir turna alır seni kanadına,

Bırakır gönlümün en güzel yerine.

İçimde bir deniz, kıyısında sen,

Her dalga adını fısıldar taşlara.

Nice mevsim geçse sensizliğimden,

Bahar yine senden doğar dallara.

Seni bir ömre sığdıramadım,

Adın çoğalır her nefesimde.

Gece bütün yıldızları söndürse,

Bir ışık kalır gözlerinin içinde.

YÜCEL ÖZKÜ

20 Kasım 2026/05:55', 'HİÇBİR ŞEYE BENZEMEZ Adını ansam akşam içinde, Bir yıldız uyanır gecenin yüzünde. Hangi mevsim sığar güzelliğine, Bahar saklı kahve gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Yücel Özkü']::text[], 8.5, '{"poet":"Yücel Özkü","poet_slug":"yucel-ozku","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hicbir-seye-benzemez-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğümde Sen', 'gogumde-sen-yucel-ozku-kp6rg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÖĞÜMDE SEN

Bir sen varsın göğümün mavisinde,

Adın dolaşır sabahın serinliğinde.

Turnalar geçer düşlerimin üstünden,

Kanatlarında sen varsın yine.

Gülüşün değince akşamlarıma,

Bir ışık düşer pencereme.

Bahar saklı kahve gözlerinde,

İçim ısınır seni düşününce.

Elini tutsam bir akşamüstü,

Yolumuz uzasa sevdamızla.

Gökyüzü seyretse sevincimizi,

Bir ömür geçse yan yana.

Yıldızlar sönse gecelerimde,

Deniz çekilse kıyılarımdan,

Yine de eksilmez içimdeki sen;

Ben göğü gözlerinde öğrendim.

YÜCEL ÖZKÜ

20 Kasım 2026/05:35', 'GÖĞÜMDE SEN Bir sen varsın göğümün mavisinde, Adın dolaşır sabahın serinliğinde. Turnalar geçer düşlerimin üstünden, Kanatlarında sen varsın...', ARRAY['Türk Edebiyatı','Şiir','Yücel Özkü']::text[], 8.5, '{"poet":"Yücel Özkü","poet_slug":"yucel-ozku","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gogumde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikate Açılan Kapım', 'hakikate-acilan-kapim-dr-yusuf-polat-ergcp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben seni birden sevmedim gönül,

Sevgi dediğin bir hüküm de değil,

İnsanın içinde ağır ağır

Hakikate dönüşen bir yolculuk.

Önce bir ses düştü içime,

Sonra o ses bir duaya dönüştü.

Bir bakışta merhameti,

Bir susuşta hikmeti öğrendim.

Anladım ki insan,

Bazen bir başkasını severken

Kendi özüne yürürmüş aslında

Seni sevdim; bir yaşlı ağacın

Kökünden dalına yürüyen su gibi

Bir tohumun karanlığı yarıp

Aydınlığa doğru uzanması misali

Ne acelem vardı kavuşmaya

Ne de korkum vardı ayrılıktan.

Çünkü öğrendim;

Sevgi sahip olmak değil,

Bir gönülde güzelliğe yer açmaktı.

Seni sevdim,

Dünya bu kadar gürültülü değilken,

İnsan insanın yükünü taşırken,

Bir lokma bölüşülünce bereket,

Gözyaşı silinince ibadet sayılırken...

Sonra ne çok şey değişti bir bilsen

Vicdan susturuldu,

Menfaat hakikatin yerine geçirildi.

İnsan göğe bakmayı unuttu,

Yere sahip olmayı marifet sandı.

Kendi nefsine yenildi,

Sonra yenilgisini kader diye anlattı.

Oysa bilmez miydi ki

Hiçbir insan dünyanın sahibi değil,

Herkes yalnızca bir yolcu.

Ne malı götürebilir son durağa

Ne makamı, ne şanı ne de şöhreti.

Geriye ne kalır insan dediğinden

Bir yetimin başını okşamak,

Bir mazlumun yanında durmak,

Bir gönülde incitmeden yaşamak,

Bir nimetin sahibini unutmamak...

İşte ben seni böyle sevdim.

Sende yalnızca kendimi değil,

İnsanı, hayatı ve de hakikati sevdim.

Bir gün bütün yollar tükense,

Bütün sesler sussa,

Bütün mevsimler ömrünü tamamlasa 

Sevginin öğrettiği merhamet kalacak.

Çünkü artık biliyorum:

Sevmek, 

Birine kavuşmak değil yalnızca;

Onunla birlikte 

Hakikat kapısında

Daha iyi bir insan olabilmekmiş meğer', 'Ben seni birden sevmedim gönül, Sevgi dediğin bir hüküm de değil, İnsanın içinde ağır ağır Hakikate dönüşen bir yolculuk. Önce bir ses düştü...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/hakikate-acilan-kapim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâr Haramdır', 'y-r-haramdir-asik-sahi-kebir-0glvo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ay batar dağlarda seher vaktidir.

Anma gayrı meni, adım haramdır.

Bu söz aşıkın maşuka ahtidir.

Dertli başıma dermanım haramdır.

Zülfikarım ol, al boynumu menim.

De yorma yalnız koy koynumu menim.

Görmeni istemem sonumu menim.

Eriyip giden başa yâr haramdır.

Zemana bırakıp zamane yettik.

Aşk gül idi, aldık dikeni biçtik.

Bunca zaman biz bize neler ettik.

Gayrı cennetten köşk bize haramdır.

Halık bilir hal hallardan nicedir.

Rahmana saldık, her şeyden yücedir.

Hayatın anlamı tek bir gecedir.

O gece yanıma bir eş haramdır.

Âşık Şah-ı Kebir''em nihanımdır.

Dağın başında bir taş fermanımdır.

Kul değil ölüm menim cânanımdır.

Kula verdiğim cân kula haramdır.

                                  Âşık Şah-ı Kebir', 'Ay batar dağlarda seher vaktidir. Anma gayrı meni, adım haramdır. Bu söz aşıkın maşuka ahtidir. Dertli başıma dermanım haramdır. Zülfikarım ...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahı Kebir']::text[], 8.5, '{"poet":"Aşık Şahı Kebir","poet_slug":"asik-sahi-kebir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yar-haramdir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesinin Tenime Değdiği Gece', 'sesinin-tenime-degdigi-gece-huseyin-erdinc-640ig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O gece sesini dinlemek yetmiyordu bana.

Biraz daha konuşmanı,

kelimelerini uzatmanı,

adımı söylerken sesinin aldığı o ince tonu

bir kez daha duymayı istiyordum.

Yatağına uzanmıştın.

Saçların yastığa dağılmış,

telefon kulağında,

gecenin bütün karanlığı çevrende toplanmıştı.

Ben de kendi yatağımda gözlerimi kapatmış,

seni karşımda düşünüyordum.

Yüzüne düşen saçlarını geriye alıyordum hayalimde.

Parmaklarım yanağından boynuna iniyor,

dudaklarım ensende biraz oyalanıyordu.

Sen başını hafifçe yana çeviriyor,

saçlarının arasından bana yer açıyordun.

Sesin değişiyordu.

Konuşurken nefesin uzuyor,

kelimelerin arasına sıcak bir heyecan yerleşiyordu.

Ben o heyecanı duydukça

sana biraz daha yaklaşmak istiyordum.

Seni yalnızca öpmek değildi istediğim.

Kollarımın arasında tutmak,

omuzlarından beline kadar seni okşamak,

başını göğsüme yasladığında

saçlarının kokusunu içime çekmekti.

Sen de beni istiyordun.

Bunu sesindeki her değişimden,

bana söylediğin her özel sözden duyuyordum.

Gecenin içinde kendi arzuna doğru ilerlerken

benim hayalim de seninle birlikte büyüyordu.

Birbirimizin tenini düşlerken

mesafeler küçülüyor,

iki ayrı oda aynı mahremiyete dönüşüyordu.

Senin heyecanın benim sabırsızlığıma karışıyor,

benim sana duyduğum istek

gecenin her dakikasında biraz daha derinleşiyordu.

Sonra o uzun bekleyiş,

o birikmiş sıcaklık,

o birbirine ulaşma isteği

bir dalga gibi yükseldi.

İki ayrı bedende

aynı anda çözülen bir fırtına…

Nefeslerimiz hızlandı,

bütün bedenimiz o yoğun hazzın ardından

yavaş yavaş gevşedi.

Sen sırtını bana döndün.

Hayalimde kollarımın arasına yerleştin.

Belinden sardım seni,

seni kendime doğru çektim.

Başını omzuma bıraktın.

Ensenin açıkta kalan yerine

uzun bir öpücük kondurdum.

Saçlarını parmaklarımla taradım.

Dudaklarımı boynunda gezdirirken

sen biraz daha geriye sokuldun.

Bir kolum belinde,

bir elim saçlarında…

Sen göğsüme yaslanmış,

ben yüzümü boynuna gömmüşüm.

İki ayrı şehirde,

iki ayrı yatakta,

birbirimizin sıcaklığını hayal ederek

öylece kaldık.

Gece uzadı.

Sen benim kollarımda uykuya dalacak kadar yakın,

ben seni bırakmayacak kadar sana dönüktüm.

Hüseyin Erdinç', 'O gece sesini dinlemek yetmiyordu bana. Biraz daha konuşmanı, kelimelerini uzatmanı, adımı söylerken sesinin aldığı o ince tonu bir kez daha...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdinc']::text[], 8.5, '{"poet":"Hüseyin Erdinc","poet_slug":"huseyin-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sesinin-tenime-degdigi-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun Yüreğim', 'suskun-yuregim-ekrem-olgun-r2b9k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SUSKUN YÜREĞİM

Ben sustum…
Çünkü bazı duygular,
Dile geldiğinde eksilir anlamından.
Ve insan bazen
En büyük feryadını
Hiç ses çıkarmadan taşır içinde.

Kimse bilmedi,
Göğsümde kaç mevsimin yarım kaldığını.
Kaç kez kendime dönüp
Kendi kapımda yabancı olduğumu.
Ben herkese bir yüz gösterdim,
Bir de kimsenin görmediği
İçimdeki o sessiz enkazı.

Suskun yüreğim…
Sen ne çok şey biriktirdin,
Bir tek kelimeye sığdıramadığın.
Kaç kırgınlığı affetmek sandın,
Kaç vazgeçişi sabır diye adlandırdın.
Ve kaç defa,
Seni anlamayan insanlara
Kendini anlatmaktan utandın.

Bilirsin…
Her sessizlik huzur değildir.
Bazen insanın içinde
Bir ömür boyu süren mahşerdir.
Dışarıdan bakıldığında sükûnet,
İçeriden bakıldığında
Kendi küllerini sayan bir yangındır.

Ben de sevdim,
Bir insanın varlığını
Kendi varlığımdan büyük tutacak kadar.
Bir gülüşe bütün baharlarımı verdim,
Bir bakışta yıllarca yaşadım.
Ama öğrendim ki
Kalbin en derin yerinde açan çiçekler
Her zaman bir başkasının gözünde görünmezmiş.

Şimdi susuyorum…
Ne söyleyecek sözüm bittiğinden,
Ne de anlatacak hikâyem kalmadığından.
Yalnızca anladım,
Bazı hakikatler
Duyulmak için değil,
İnsanın içinde olgunlaşmak için varmış.

Ey suskun yüreğim…
Sana en çok ben haksızlık ettim.
Herkesin yarasına merhem ararken
Senin kanayan yerlerini görmezden geldim.
Başkalarının mutluluğuna ömür biçerken
Kendi günlerimi eksilttim.

Ve şimdi,
Bir gün yeniden konuşursam
Sesimi duyanlar şaşırmasın.
Çünkü ben susarken
İçimde binlerce cümle büyüttüm.

İnsan bazen söyleyemediklerinden değil,
Söylese de anlaşılmayacağını bildiklerinden susar.
Ve en ağır yalnızlık,
Kalabalıkların içinde sessiz kalmak değil,
Kendi yüreğinin sesine
Bir ömür geç cevap vermektir.

EkOL', 'SUSKUN YÜREĞİM Ben sustum… Çünkü bazı duygular, Dile geldiğinde eksilir anlamından. Ve insan bazen En büyük feryadını Hiç ses çıkarmadan taş...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/suskun-yuregim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Güzel Dünya', 'seninle-guzel-dunya-ekrem-olgun-qmw9b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SENİNLE GÜZEL DÜNYA

Seni sevmek…
Bir çiçeğin baharı beklemesi değil,
Kışın ortasında bile
İçinde bir bahçe büyütebilmektir.
Ve ben,
Seninle öğrendim
İnsanın bir başka insanda
Nasıl mevsim değiştirebildiğini.

Sen gülünce…
Dünya biraz daha yaşanılır oluyor,
Gökyüzü maviliğini hatırlıyor.
Sanki bütün güzel şeyler
Varlığını senden ödünç alıyor.
Ve ben her defasında
Bir insanın yüzünde
Bu kadar çok hayat olmasına şaşırıyorum.

Bilirsin sevgilim,
Her kalbin kendine ait bir dili vardır.
Kimi susarak sever,
Kimi dokunarak anlatır kendini.
Ben seni,
Henüz söylenmemiş bir kelimenin
Dünyaya ilk kez anlam vermesi gibi seviyorum.

Ellerini tuttuğumda
Zaman durmuyor aslında,
Aksine, ilk kez yaşamaya değer
Bir hızla akıyor.
Çünkü aşk,
Birlikte geçirilen yılların uzunluğu değil,
Bir anın içine
Kaç ömürlük mutluluk sığdırabildiğindir.

Bazen yüzüne bakıyorum,
Bir ressamın henüz keşfetmediği
Bir rengin karşısındaymışım gibi.
Ne gözlerinin rengini anlatabiliyorum
Ne de gülüşünün bende bıraktığı izi.
Çünkü bazı güzellikler
Görülmek için değil,
İnsanın içinde çoğalmak için vardır.

Sen benim,
Hayata karşı kazandığım bir zafer değilsin.
Hayatın kendisini sevmem için
Bana sunduğu en güzel sebeplerden birisin.
Seninle yürüdüğüm yolları değil,
Yürürken kim olduğumu seviyorum.
Çünkü yanında
Kendimin en güzel hâline dönüşüyorum.

Ve bir gün saçlarımıza
Aynı mevsimin beyazı düşerse,
Ben yine ilk günkü gibi
Gözlerine bakmak istiyorum.
Yüzündeki her çizgide
Birlikte güldüğümüz günleri,
Ellerindeki her izde
Birbirimize dokunduğumuz yılları görmek…

Sevgilim,
Ben sana sonsuzluk vadetmiyorum.
Çünkü sonsuzluk,
İnsanın henüz yaşamadığı zamana
Verdiği bir isimdir.

Ben sana daha güzel bir şey söylüyorum:

Ömrümün bütün yarınları bilinmez olabilir,
Ama seninle yaşadığım her bugün,
Hayatın bana verdiği en güzel cevaptır.

Ve şimdi anlıyorum…
Aşk, iki insanın birbirine bakması değil yalnızca;
Birbirinin gözlerinden
Aynı dünyaya yeniden hayran kalmasıdır.

EkOL', 'SENİNLE GÜZEL DÜNYA Seni sevmek… Bir çiçeğin baharı beklemesi değil, Kışın ortasında bile İçinde bir bahçe büyütebilmektir. Ve ben, Seninle ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/seninle-guzel-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşünde Mahsur Kaldım', 'gulusunde-mahsur-kaldim-ekrem-olgun-mhlve', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GÜLÜŞÜNDE MAHSUR KALDIM

Sen gülerdin…
Ben dünyanın bütün kederlerini
İki gamzenin arasına sığdırırdım.
Ne zaman yüzüne baksam,
Bir ömür yaşamış gibi yorulur,
Bir çocuk kadar yeniden başlardım.

Bilmezsin…
İnsan bazen bir çift göze değil,
O gözlerin kendisine bakarken
Dünyayı nasıl değiştirdiğine âşık olur.
Ben seni güzel olduğun için sevmedim,
Güzelliğin senden sonra
Hiçbir şeye yakışmadığı için sevdim.

Bir gülüşün vardı senin,
Sanki bahar, kışın alnından öperdi.
Gamzelerine düşen her tebessümde
Kalbim kendi yerini unuturdu.
Ve ben,
Yüzünde açılan o iki küçük çukurda
Koca bir ömrü kaybetmeyi göze alırdım.

Şimdi hangi aynaya baksam
Yüzümde senden kalma bir hüzün.
Hangi şarkıya sığınsam
Nakaratında yarım kalmış bir dün.
Meğer aşk,
Bir insanın gidişinden sonra
Onun gülüşünü içinde yaşatmakmış bütün ömrün.

Sana kızamıyorum…
Çünkü insan,
En çok incindiği yerden de sevebiliyormuş.
Bir zamanlar cennet sandığı gözlerin
Kendi cehennemine açıldığını bilse de
O kapıyı kapatamıyormuş.

Ve bir gün,
Başka birinin yanında gülerken
Gamzelerin yine çıkarsa ortaya,
Bil ki uzaklarda bir adam
Hiç kimsenin bilmediği bir yerinden kırılacak.

Çünkü sen,
Benim hayatımdan giden bir kadın değilsin yalnızca.
Sen, içimde hâlâ yaşayan
Ama artık bana gülümsemeyen
En güzel ihtimalimsin.

Ben seni unutamadım sevgilim…
Unutmak, hatırlamaktan vazgeçmekse eğer,
Ben daha seni sevmekten
Bir tek gün bile izin almadım.

EkOL', 'GÜLÜŞÜNDE MAHSUR KALDIM Sen gülerdin… Ben dünyanın bütün kederlerini İki gamzenin arasına sığdırırdım. Ne zaman yüzüne baksam, Bir ömür yaşa...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gulusunde-mahsur-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Dediğin İşte', 'i-nsan-dedigin-i-ste-dr-yusuf-polat-zp90g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi ateş yakar dumanına isyan eder;

Kimi başkasının yangınında ısınır,

Kimi engin denizlerde yaşar

Ama bir damla su olmaya yanaşmaz.

Kimi yüzüne sahte maskeler takar,

Âleme güzel görünmek için;

Kimi herkese uğrar da

Kendi kapısını çalmayı hep unutur.

Kimi dünyayı düşünmeden affeder,

Öyle ki düşmanına bile dua eder;

Lakin kendi hatasının karşısında

Bir türlü kendine merhamet beslemez.

İnsan işte…

Bir secdeyle göklere yükseleni var

Bir kibirle uçurumlara düşen

Bir lokmayı bölüşerek büyüyen,

Bir hırs uğruna kendinden eksileni var

Kimi merhametiyle bütün dağları aşar,

Kimi öfkesiyle bir gönlü viran eder.

Kimi bir ömür Hakk''ı arar,

Kimi kendini buldum sanırken

Kendisinden habersiz yaşar.

İnsan dediğin çözülmeyen bir sır;

Hem en güzel ayetin tecellisi,

Hem kendi elleriyle yazdığı imtihan.

Bir yanında göklere uzanan ruh,

Bir yanında toprağa mahkûm nefis…

Ey insan! Sen

Kâh göklere başkaldıran bir yıldız,

Kâh

Toprağın altında kaybolan bir tohum…

Bir yanında meleklerin imrendiği ruh,

Ötesinde nefsinin esiri mahkûm duygular

İnsan dediğin işte

Göklere çıkacak kadar aziz; 

Kendi nefsinde kaybolacak kadar aciz

Üstünlerin üstünü aşağılıkların en aşağısı', 'Kimi ateş yakar dumanına isyan eder; Kimi başkasının yangınında ısınır, Kimi engin denizlerde yaşar Ama bir damla su olmaya yanaşmaz. Kimi y...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/insan-dedigin-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamadın Beni', 'anlamadin-beni-nobetci-sair-r19sd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Savrulduk ikimiz dört Bir yana 
Ayrılığın acısını gel birde sor bana 
Zehir kattın durmadan sen kanıma 
Anlamadın bir türlü sana olan sevgimi

Gözümü seninle açar seninle kapatırdım 
Yüreğimde her zaman aşkını yaşatırdım
İmkansız olsa da hep sana katlanırdım 
Anlamadın bir türlü sana olan sevgimi

Çok konuşur susmak bilmezdim 
İnan ki seni kimseye değişmezdim 
Bilseydim seni böyle sevmezdim 
Anlamadın bir türlü sana olan sevgimi 

Şimdi gel gör beni ne haldeyim 
Sevgine Hasret Deli divaneyim 
 alıp da başımı söyle nereye gideyim 
Anlamadın bir türlü sana olan sevgimi', 'Savrulduk ikimiz dört Bir yana  Ayrılığın acısını gel birde sor bana  Zehir kattın durmadan sen kanıma  Anlamadın bir türlü sana olan sevgim...', ARRAY['Türk Edebiyatı','Şiir','Nöbetçi Şair']::text[], 8.5, '{"poet":"Nöbetçi Şair","poet_slug":"nobetci-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anlamadin-beni-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-veli-akca-pf8nc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İNSAN

Ne bir kervanı kaldı ne bir hanı

Kayboldu dostları boş kaldı yanı

Canını cansız bıraktı cananı

Koca dünyada yapayanlız insan

Eski itibarı düşmüş yerlere

Özyurdu benziyor gurbetellere

Sonbaharda karışmış gazellere

Gittikçe sararıp soluyor insan 

Dünya ona o dünyaya duyarsız

Zaman su gibi eriyor ayarsız

Güzel çirkinleşmiş iyiler arsız...

Aynada gerçeği arıyor insan

Saraylar yaptırmak için fezaya

Ne kıtaya sığıyor ne deryaya

Yakayı kaptırmış sanal dünyaya

Hayalleri gerçek görüyor insan

Hoyrati der teşbihte olmaz hata

Somut görünenler dönmüş soyuta

Gidişat sanki başka bir boyuta

Bilinmez aleme yürüyor insan

20.11.2026. Veli Akca şiiri

2026 yılının kelimesi  "human" 

Yani İNSAN...', 'İNSAN Ne bir kervanı kaldı ne bir hanı Kayboldu dostları boş kaldı yanı Canını cansız bıraktı cananı Koca dünyada yapayanlız insan Eski itib...', ARRAY['Türk Edebiyatı','Şiir','Veli Akca']::text[], 8.5, '{"poet":"Veli Akca","poet_slug":"veli-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/insan-1290-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Şahit Olmak', 'kendine-sahit-olmak-ekrem-olgun-eq4ii', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KENDİNE ŞAHİT OLMAK

İnsan, en çok sustuğu yerde eksilir;
Çünkü bazı hakikatler söylenmeyince ölmez,
Sahibini içten içe tüketir.

Herkes geçmişinden kurtulmak ister,
Oysa geçmiş, geride bıraktığımız zaman değildir;
Bugün verdiğimiz kararların
Dün tarafından yönetilmesidir.

Bir insanı tanımak için yüzüne bakma,
Neyi kaybetmekten korktuğuna bak;
Çünkü insanın gerçek efendisi,
Vazgeçemediği şeydir.

Bazen affetmek bir erdem değildir,
İnsanın kendi acısına
Artık hesap soracak gücü kalmamasıdır.

Ne gariptir...
İnsan en çok kendine yabancıyken
Başkalarının onu anlamamasından yakınır.
Oysa insan, kendi içinde kaybolduğunda
Bütün yolları başkalarında arar.

Herkes bir iz bırakmak ister dünyada,
Kimse düşünmez,
Bazı izlerin bir başkasının yarası olduğunu.

Bir ömür doğru insanı ararız,
Fakat kimse kendine şu soruyu sormaz:
Ben, bir başkasının hayatında
Hangi yanlışın karşılığıyım?

Kimi insanlar yalnızlıktan korkar,
Kimileri kalabalıktan;
Çünkü yalnızlık insanı kendisiyle,
Kalabalık ise kendinden kaçışıyla yüzleştirir.

Ve bir gün anlarsın,
Her kayıp senden bir şey götürmemiştir;
Bazıları, sana ait sandığın
Yabancı parçaları söküp almıştır.

İnsan yaşlandıkça bilgeleşmez her zaman,
Bazen yalnızca yanılgılarına
Daha inandırıcı gerekçeler bulur.

Sonunda herkes kendi ömrünün tanığıdır,
Ama herkes gördüğü gerçeği söyleyemez;
Çünkü bazı itiraflar
Bir suçun değil,
Bir ömürlük masumiyet vehminin sonudur.

Ve insanın en büyük trajedisi şudur:
Kendini bulmak için bir ömür harcar,
Bulduğunda ise
O insanla yaşayacak kadar ömrü kalmamıştır.

EkOL', 'KENDİNE ŞAHİT OLMAK İnsan, en çok sustuğu yerde eksilir; Çünkü bazı hakikatler söylenmeyince ölmez, Sahibini içten içe tüketir. Herkes geçmi...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kendine-sahit-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akılsoyunması', 'akilsoyunmasi-ertan-hurmanli-di2pg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle konuşmak başlı başına akılsoyunması

Çırılçıplak kalıyor beynimin tüm kıvrımları

Kimsenin bilmediği kelimeyi suskuya bulayıp

Saçlarını suyağrısı denizlere daldırıyorsun

Sen ki superisi gibi yüzersin suda

Göller birikir içkanama yanaklarında

Ben ki yürekçil bir kuşum avuçlarında

Çırpındıkça büyüyor gözkıyametin

Düştükçe kanat ekleniyor düşkuşlarıma

Adını yazabilmek için hiçliktaşlarına

Sözcükleri heceyıkımına uğratıyorum 

Senin yakanı ilikleyen gülce sabahlar

Benim yakamı yırtıyor gecekıvrımında

Üstümüze yıkılıyor zamanenkazı

Senin güldüşüren gamzen olmasa

Nasıl atlatırız bilmem ömürayazını?

Aramızdan sinsice geçiyor zamanhırsızları

Çalamadıkları tek şey, eş/siz aşksızısı

Gel, saçlarına yıldıztozumu serpeyim

Avuçlarıma dökülsün çeyrek geceyarıları

Sen uykukaçağı, ben azılı rüyafirarisi

Birlikte vuralım sabahyalanlarını', 'Seninle konuşmak başlı başına akılsoyunması Çırılçıplak kalıyor beynimin tüm kıvrımları Kimsenin bilmediği kelimeyi suskuya bulayıp Saçların...', ARRAY['Türk Edebiyatı','Şiir','Ertan Hurmanlı']::text[], 8.5, '{"poet":"Ertan Hurmanlı","poet_slug":"ertan-hurmanli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/akilsoyunmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey müminler, size cenneti anlatayım', 'ey-muminler-size-cenneti-anlatayim-suleyman-ozguven-8v4a3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EY MÜMİNLER, SİZE CENNETİ ANLATAYIM

Ey müminler, size cenneti anlatayım, Ömrünüz boyunca beklediğiniz vuslatı anlatayım. Ne ölüm var orada ne de ayrılık, Ne gözyaşı dökülür ne de gönülde kırgınlık. Bir ömürlük imtihan sona erecek, Rabbimizin rahmeti kullarını sarıp sarmalayacak.

"İman edip salih ameller işleyenlere, altlarından ırmaklar akan cennetler olduğunu müjdele." (Bakara, 2/25)

Ey müminler, size cennetin bahçelerini anlatayım, Yeşillikler içindeki eşsiz güzelliklerini anlatayım. Ağaçlarının gölgesi uzanacak önünüze, Meyveleri sunulacak her birinize. Ne solacak bir çiçek ne kuruyacak bir dal, Her köşesinde ayrı bir nimet, ayrı bir cemal.

"Orada ne yakıcı güneş ne de dondurucu soğuk görürler." (İnsan, 76/13)

Ey müminler, size cennetin ırmaklarını anlatayım, Sütünden, balından akan pınarlarını anlatayım. Bir yanında tertemiz sular çağlayacak, Bir yanında bal ırmakları akacak. Susuzluk nedir bilmeyecek oradaki canlar, Rabbimizin ikramıyla dolacak bütün sofralar.

"İçinde bozulmayan sudan ırmaklar, tadı değişmeyen sütten ırmaklar ve süzme baldan ırmaklar vardır." (Muhammed, 47/15)

Ey müminler, size cennetin köşklerini anlatayım, İnci misali parlayan saraylarını anlatayım. Altın bilezikler takılacak kulların ellerine, İpekten elbiseler giyilecek bedenlerine. Tahtlar üzerine kurulacak iman ehli insanlar, Ne gam kalacak yüreklerinde ne de eski zamanlardan kalan efkâr.

"Onlar orada altın bileziklerle süslenirler, ince ve kalın ipekten yeşil elbiseler giyerler." (Kehf, 18/31)

Ey müminler, size cennetteki kavuşmayı anlatayım, Yıllarca hasret kaldığınız buluşmayı anlatayım. Anne babalar, evlatlar bir araya gelecek, İmanla yaşayan aileler yeniden birleşecek. Dünyada yarım kalan nice muhabbet tamamlanacak, Rabbimizin lütfuyla sevenler birbirine kavuşacak.

"İman edenlerin, soylarından gelen ve imanla kendilerine uyan nesillerini de kendilerine kattık." (Tûr, 52/21)

Ey müminler, size cennetteki kardeşliği anlatayım, Kalplerden silinecek bütün kırgınlıkları anlatayım. Ne kin kalacak orada ne de düşmanlık, Ne haset bulunacak ne de gönülde karanlık. Dünyada birbirini incitenler arınacak, Rabbimizin izniyle gönüller huzur bulacak.

"Biz onların göğüslerindeki kini söküp atarız. Onlar kardeşler olarak tahtlar üzerinde karşı karşıya otururlar." (Hicr, 15/47)

Ey müminler, size cennetin ebediyetini anlatayım, Bir daha ölmeyeceğiniz o hayatı anlatayım. Ne yaşlılık çökecek ne hastalık bulacak, Ne de bir gün gelip mutluluğunuz son bulacak. Dünyada her güzel şeyin bir sonu vardır, Cennette ise ebedî hayat müminleri beklemektedir.

"Orada ebedî kalacaklardır. Oradan ayrılmayı da istemezler." (Kehf, 18/108)

Ey müminler, size meleklerin selamını anlatayım, Cennet kapılarında karşılanmanızı anlatayım. Kapılar açılacak, melekler sizi karşılayacak, Sabreden kullara selamlarını sunacak. Dünyada nice imtihanlardan geçen insanlar, O gün huzura kavuşacak, bitecek bütün acılar.

"Melekler her kapıdan yanlarına girerler. Sabretmenize karşılık selam sizlere! Dünya yurdunun sonucu ne güzeldir!" (Ra''d, 13/23-24)

Ey müminler, size cennetin en büyük müjdesini anlatayım, Bütün nimetlerden üstün olan saadeti anlatayım. Ne köşklerin güzelliği ne ırmakların akışı, Ne de altınların, incilerin göz kamaştırışı. En büyük nimet Rabbimizin rızasına ermektir, O''nun cemalini görme şerefine erişmektir.

"Allah''ın rızası ise hepsinden büyüktür. İşte büyük kurtuluş budur." (Tevbe, 9/72)

Ey müminler, size cennetin nimetlerini anlatayım, İnsan aklının erişemediği güzellikleri anlatayım. Ne gözler görmüştür ne kulaklar işitmiştir, Ne de insanın hayaline bütünüyle düşmüştür. Rabbimiz saklamış kullarına nice güzellikler, Salih amellerin ardında bekleyen sonsuz müjdeler.

"Yaptıklarına karşılık olarak onlar için göz aydınlığı olacak nimetlerden nelerin saklandığını hiç kimse bilemez." (Secde, 32/17)

Ey müminler, cennete giden yoldan ayrılmayın, Namazı terk edip de gaflete dalmayın. Yetimin başını okşayın, yoksulun elinden tutun, Mazlumun duasını alın, kimsenin hakkına dokunmayın. Dünyada ektiğiniz iyilikler karşılıksız kalmayacak, Rabbimizin katında hiçbir güzel amel zayi olmayacak.

"Kim zerre miktarı hayır yapmışsa onu görür." (Zilzâl, 99/7)

Ey müminler, henüz vakit varken tövbe edin, Rabbimizin rahmetine gönülden yönelin. Günahınız çok diye ümidinizi kesmeyin, O''nun merhametinden asla uzaklaşmayın. Bir damla gözyaşıyla af dileyin, Rabbimizin bağışlamasına sığının.

"Allah''ın rahmetinden ümit kesmeyin. Şüphesiz Allah bütün günahları bağışlar." (Zümer, 39/53)

Ey Rabbim, bizlere cennetini nasip eyle, Son nefesimizi imanla vermeyi nasip eyle. Anne babalarımızı, evlatlarımızı ayırma, Sevdiklerimizi rahmetinden mahrum bırakma. Bizi cennetine kabul edilen kullarından eyle, Mahşer günü bizleri Habibinin sancağı altında buluştur.

"Rabbimiz! Bize dünyada da iyilik ver, ahirette de iyilik ver ve bizi ateş azabından koru." (Bakara, 2/201)

ÂMİN, ÂMİN, ÂMİN...', 'EY MÜMİNLER, SİZE CENNETİ ANLATAYIM Ey müminler, size cenneti anlatayım, Ömrünüz boyunca beklediğiniz vuslatı anlatayım. Ne ölüm var orada n...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Özgüven']::text[], 8.5, '{"poet":"Süleyman Özgüven","poet_slug":"suleyman-ozguven","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ey-muminler-size-cenneti-anlatayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cavidan', 'cavidan-suleyman-ozguven-ztgkk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'CAVİDAN

Gönül mülkümün sultanı

Ey Cavidan, cemâlinle gönlüme düştü bir ziyâ, Hüsnüne meftun oldu bu gönül, bulamadı devâ. Zülfünün her teli sanki geceden kopmuş bir nişan, Gözlerinse sevdâ ehline açılmış iki cihan.

Ruhumun ikliminde sen açan gonca-i gülsün, Bülbülün dilinde saklı, gönlümde öten bülbül sesisin. Bir nazarın değse yeter, bahâr olur hazânım, Senin aşkınla şenlenir virâne gönül hanım.

Ey yâr, firâkın düşse gecelerime hicran olur, Sensiz geçen her dem ömrüme ağır bir ziyan olur. Vuslatın bir bayramdır, hasretin bin keder, Sana kavuşmak için bu gönül nelerden vazgeçer bir bilsen.

Ne mülk isterim senden ne de taht u tâc, Bir tebessümün yeter, gönlüme olur ilâç. Sana yazdığım her gazel aşkımın nişanesi, Her mısrada saklıdır kalbimin bir parçası.

Cavidan, ey ömrümün bitmeyen bahârı, Sen oldun gönül mülkümün en kıymetli yâdigârı. Eğer aşk bir kitapsa, sensin ilk satırım, Eğer ömür bir şiirse, sensin son mısram.

Ne kalem anlatabilir ne mürekkep seni yazar, Güzelliğin karşısında bütün kelâm susar. Ben seni bir heves değil, bir ömürlük sevda bildim, Dünyaya bin kez gelsem yine seni severdim.', 'CAVİDAN Gönül mülkümün sultanı Ey Cavidan, cemâlinle gönlüme düştü bir ziyâ, Hüsnüne meftun oldu bu gönül, bulamadı devâ. Zülfünün her teli ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Özgüven']::text[], 8.5, '{"poet":"Süleyman Özgüven","poet_slug":"suleyman-ozguven","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cavidan-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboldum.', 'kayboldum-yucel-ozku-4ftml', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KAYBOLDUM

Bir baktın, mevsimler değişti içimde,

Bahar, adını yazdı gönül defterime.

Kahve gözlerinde bir ömür saklı,

Ben ömrümü bıraktım gözlerine.

Saçlarının telinde bir bahar,

Geceye karışan bir sevda saklı.

Gülüşün değince yorgun kalbime,

Yeniden sevmek düştü payıma.

Dudaklarında yarım kalmış bir şiir,

Bakışlarında anlatılmamış bir ömür.

Her bakışında yeniden anladım,

Güzelliğin sığmaz hiçbir söze.

Bir sarılışın yeter ömrüme,

Göğsünde diner hasretim.

Ne uzaklık kalır ne de zaman,

Bir ömür seninle aynı düşte uyusam.

Sen benim en güzel rastlantım,

Kalbime yazılmış silinmez şiirsin.

Kaç bahar geçerse geçsin dünyadan,

Benim en güzel mevsimim sensin.

YÜCEL ÖZKÜ

20 Kasım 2026/01:40', 'KAYBOLDUM Bir baktın, mevsimler değişti içimde, Bahar, adını yazdı gönül defterime. Kahve gözlerinde bir ömür saklı, Ben ömrümü bıraktım göz...', ARRAY['Türk Edebiyatı','Şiir','Yücel Özkü']::text[], 8.5, '{"poet":"Yücel Özkü","poet_slug":"yucel-ozku","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kayboldum-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başarı, Kendini Dinleyebilmektir', 'basari-kendini-dinleyebilmektir-selin-ozalan-sutzb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İç sesini dinlemeyi öğrenen her birey, aslında hayattaki en büyük başarılarından birine ulaşmıştır. Çünkü etrafımızdaki insanlar her zaman konuşacak, eleştirecek ve söyleyecek bir şeyler bulurlar. Önemli olan, bütün bu seslerin arasında kendi kalbinizin sesini duyabilmektir. Hayatta en az bir kez olsun kendinize gerçekten şu soruyu sormayı öğrenmelisiniz: Ben ne istiyorum? Çünkü asıl başarı belki de tam olarak budur. Hayatın stresine, telaşına ve bitmek bilmeyen sorumluluklarına o kadar çok kapılmışız ki zamanla gerçekten neye ihtiyacımız olduğunu unutmuşuz. Belirli bir düzenin, belirli saatlerin ve toplum tarafından oluşturulmuş beklentilerin içerisinde yaşamaya alışmışız. Adeta birbirinin aynısı olan hayatlar sürmeye başlamışız. Alışılagelmişin dışında davrandığımızda ise çevremiz tarafından sürekli eleştirilmekten kurtulamıyoruz. Peki, biz ne zaman başkalarının sesine biraz olsun sağır olup kendimizi dinlemeyi öğreneceğiz? Topluma baktığımda, dışarıdan kusursuz gösterilmeye çalışılan hayatların aslında kendi içerisinde ne kadar kırılgan, hatta paramparça olabildiğini görüyorum. Özellikle gençlere baktığımda, bazılarının kendine güvenmeyi unuttuğunu, bazılarının özgüven eksikliğiyle mücadele ettiğini, bazılarının ise geleceğe dair kaygılarının altında ezildiğini görüyorum. Oysa unuttuğumuz çok önemli bir gerçek var: Her insanın başarısı, yeteneği ve hayata bakış açısı birbirinden farklıdır. Herkesi aynı kefeye koymak, herkesten aynı başarıyı beklemek sizce de büyük bir haksızlık değil midir? Bir sınav düşünün. Düşük bir not aldığınızda sizinle dalga geçilir, tembel olduğunuz söylenir ya da gelecekte başarılı olamayacağınız ima edilir. Peki, başarı gerçekten birkaç sınav sonucuyla ölçülebilir mi? Bir insanın zekâsı, yeteneği, azmi ve hayattaki potansiyeli yalnızca aldığı notlardan mı ibarettir? Elbette hayır. Bir insan akademik hayatta istediği başarıyı elde edememiş olabilir ancak bu, onun başka alanlarda yetenekli, üretken veya başarılı olamayacağı anlamına gelmez. İşte tam da bu yüzden gençler zamanla kendilerine olan inançlarını kaybediyor, gelecekleri hakkında kararsızlık yaşamaya başlıyorlar. Çünkü sürekli başkalarının beklentilerine göre yaşamaya çalışırken kendi isteklerini ve potansiyellerini keşfetmeye fırsat bulamıyorlar. Benim söylemek istediğim çok basit: Bir kez olsun kendinize dönün. Hayatın gürültüsünü biraz olsun susturun ve gerçekten ne istediğinizi sorun kendinize. Bu hayat sizin. Başkalarının beklentilerine göre şekillendirmek, başkalarının çizdiği yollarda yürümek zorunda değilsiniz. İnsan, başkalarının kendisi için belirlediği hayatı yaşamak yerine kendi hayatının öznesi olmalı. Çünkü herkesin hikâyesi, zamanı, yeteneği ve varacağı yer birbirinden farklıdır. Unutmayın; hayatı anlamlı ve başarılı kılan, herkesin izinden gitmek değil, insanın kendi yolunu bulabilmesi ve kendi izini bırakabilmesidir.', 'İç sesini dinlemeyi öğrenen her birey, aslında hayattaki en büyük başarılarından birine ulaşmıştır. Çünkü etrafımızdaki insanlar her zaman k...', ARRAY['Türk Edebiyatı','Şiir','Selin Özalan']::text[], 8.5, '{"poet":"Selin Özalan","poet_slug":"selin-ozalan","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/basari-kendini-dinleyebilmektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayet', 'sikayet-orhan-karatasguler-4-y7dy6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayrılık acısından dem vurmuş 

Kendince şikayet etmişsin 

Seninkisi bir kaç damla gözyaşı

Üç vakte gebe, uzayan üç gece 

Bir cümlelik aşkta unutulan üç hece 

Ben bir gülüşün bir ömrü heder ettiğine şahit olmuşum

Koca çağlayanın bir damlada kayboluşunu 

Bir kıvılcımın koca bir ormanı kül edişini 

Suyun söndüremediği ateşlerde 

Ruhun nasıl yandığını 

Bir umuda koşan kelebeklerin 

Mum ışığına üşüşünü

Yanan kanatların mum dibine düşüşünü Ateşin yananan yürekte  üşüdüğünü 

Ayaza çeken soğuğun 

Bir bedende uyuşunu 

Girdapların denize , denizin okyanusa dönüşünü görmüşüm.', 'Ayrılık acısından dem vurmuş  Kendince şikayet etmişsin  Seninkisi bir kaç damla gözyaşı Üç vakte gebe, uzayan üç gece  Bir cümlelik aşkta u...', ARRAY['Türk Edebiyatı','Şiir','Orhan Karataşgüler 4']::text[], 8.5, '{"poet":"Orhan Karataşgüler 4","poet_slug":"orhan-karatasguler-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sikayet-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Misali', 'kum-misali-ozge-bilgec-7zra1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kavramak istersin, sızar avucundan,

Ömür bir bir dökülür günün ucundan.

Tutulmaz ne dünün ne yarının eli,

Akar gider hayat, şelaleden akan kum misali.

Her zerre bir anı, her damla bir iz,

Bu sonsuz nehirde birer gölgeyiz.

Bir yangın artığı, bir hicran yükü

Akar gider hayat, şelaleden akan kum misali.

Ne barajlar dayanır bu sessiz sese,

Ne de bir saniye sığar o son nefese.

Dünya bir handır, çalar içeri gireni 

Akar gider hayat, şelaleden akan kum misali', 'Kavramak istersin, sızar avucundan, Ömür bir bir dökülür günün ucundan. Tutulmaz ne dünün ne yarının eli, Akar gider hayat, şelaleden akan k...', ARRAY['Türk Edebiyatı','Şiir','Özge Bilgeç']::text[], 8.5, '{"poet":"Özge Bilgeç","poet_slug":"ozge-bilgec","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kum-misali-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşktan Yana', 'asktan-yana-asik-sahi-kebir-nzst4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmezler Pir''im bilemezler,

Gördüğümüzü göremezler.

Derdi vereni söylemezler,

Acı çeken yine cân oldu.

Hak deyi gezdiğim yollardan,

Güvendiğim emin kollardan,

Kırmaz dediğim bu kullardan,

 Zarar gören yine cân oldu.

Kimse bilmez görmez halini,

Kim öder hicran vebalini,

Al yaşlar dökmüş cemalini,

Yalnız gören yine cân oldu.

Derdim var desem herkeste var.

Meni yakar desem herkes yanar.

Var mı yüz güldüren bir tane yar,

Harab olan yine cân oldu.

Men deyi bir şey anlatamam.

Şikayet sayar dayanamam.

Sözle kimseyi aldatamam.

Sefil olan yine cân oldu.

Aşk ilinde kullar yalancı,

Hak dilinde herkes yabancı.

Bilseler ki kimler talancı,

Zehirlenen yine cân oldu.

Şah-ı Kebir''em, aşktan yana.

Yüzüm gülmedi aşktan yana.

Af olur mu câna kıyana,

Gülü solan yine cân oldu.

                         Âşık Şah-ı Kebir', 'Bilmezler Pir''im bilemezler, Gördüğümüzü göremezler. Derdi vereni söylemezler, Acı çeken yine cân oldu. Hak deyi gezdiğim yollardan, Güvendi...', ARRAY['Türk Edebiyatı','Şiir','Aşık Şahı Kebir']::text[], 8.5, '{"poet":"Aşık Şahı Kebir","poet_slug":"asik-sahi-kebir","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/asktan-yana-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ve Sevda Üzerine', 'ask-ve-sevda-uzerine-erkan-eren-kxfki', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sükun dağlarının yamacına vururken ışık

bakışına toplanır, çıkar meydana gizil hayatlar

uzaklardan, sınırı yüzlerin

yıkar ağırdan gövdesini hesapsız anılara

ve düşlerle gelir, düşüncelerle

kötürüm kalan zamanın ayak sesleri

uğurlanırken hep birileri

uçsuz toprağında yankısı ince yağmurların

yaklaştıran kendine biraz,

yeli vurur göğsüne bu seher vaktinin

uzaklığından anlarsın, düşünüp

yakılan yüreğini

hasretin şiiridir hep yârin sözleri

yaşarırken gözlerin

ateşten yanan şarkıları kısacık ömrün

gölgeli gözlerin sırrı

uyanışların derin uykusu,

göğe bakınıp ağlayan dilin

ilerde, ta ilerde sınırda bekler hayatı

ve sıfırlanırken başlangıçlar

sonuna gelirsin tüm tekinsiz hazırlıkların

açıverir gülleri aşkın

soldurulan ışığı yıldızların ve ayın

böylesi mahzun gecelerde

uzak şehirleri soluyan yakındaki şiirler

yüreklendirir esmer sevinçleri

neye dokunsan hayat

nereye baksan karşında hep o hayal

her yer gurbet sana

ve sana her yer memleket

açıverir gülleri sevdanın ve aşkın…

durgun göllerin yanında

serin ovaların bağrında

dağa taşa bakıp, uyuyan ormana

nice günlerden sert ve soğuk

mutlu, huzur içindeyken nice günler

hayatın yaşı anlaşılmaz, asla

tarih ötesi yorgunlukla hesaplanır yıllar ve yollar

adın ve sanın kadarsın

yaşadıkça anlar, anladıkça yaşarsın

yüreğin ırmağı akar bir diğerine

gözlerde yakamoz, bakışlarda mehtap parıldar

aşkın ve sevdan kadarsın

yaşadıkça anlar, anladıkça yaşarsın…', 'sükun dağlarının yamacına vururken ışık bakışına toplanır, çıkar meydana gizil hayatlar uzaklardan, sınırı yüzlerin yıkar ağırdan gövdesini ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Eren']::text[], 8.5, '{"poet":"Erkan Eren","poet_slug":"erkan-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/ask-ve-sevda-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih Tekerrürden İbaret', 'tarih-tekerrurden-i-baret-erkan-eren-wqaw4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dilinde hayli bezgin umursamazlıkla

tasa etmeden kopuyor büsbütün hayattan

yaşlı kentin ıssız sokaklarında

unutuluyor kadim bir halkın geleceği

düşünmekten ırak

bilmeden nasıl sınandığını

çaresizliğini büyüten fütursuz yanılgıların içinde

ve savrulurken dipsiz bir yalnızlığın çölünde

her nisyan bir öfkedir aslında

zamana, ölüme ve acıya

kışkırtsa da anıların esrik duygusu

bir suskudur yüreğinde isyanla karışık

dünya tanığıdır aşkın

uçsuz hayallerin ve kavganın

öyle kahramanlar vardır ki

yeniden küllerinin içinden doğarlar aniden

nidası kopar tufan gibi inançlarının

arzı ve göğü titreten

bir kentin yazgısı yeniden yazılır

ve o halkın kutlu geleceği

tarih tekerrür eder hayatın içinde böylece…', 'dilinde hayli bezgin umursamazlıkla tasa etmeden kopuyor büsbütün hayattan yaşlı kentin ıssız sokaklarında unutuluyor kadim bir halkın gelec...', ARRAY['Türk Edebiyatı','Şiir','Erkan Eren']::text[], 8.5, '{"poet":"Erkan Eren","poet_slug":"erkan-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tarih-tekerrurden-ibaret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kal Benimle', 'sen-kal-benimle-hamza-mamas-nfi9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bilmem nasıl derler 

Soğurur ruhumdan elemi seni seyretmek

Ne gam kalır, ne rüyadan belirtiler

Tualde rengarenk cümbüş

Kayın ağaçlarının titrek sarılığında 

Altın sarısı güzelliğinde gözlerim

Yormuşken yolu, son seferdeyim.

Aheste geçiyor zaman 

Örgülü yeleleri savruluyor rahvan atların.

Nevruz şenliğinde takılıp kalmışım.

Ölümsüz gibi her saniye

Yol gitsin seninle kalayım gerıye 

Ey ruhumun emiri

Yüreğime dokunan sevdanın türküsü

Yol gitsin

Gün gitsin

Dün gitsin sen kal benimle', 'bilmem nasıl derler  Soğurur ruhumdan elemi seni seyretmek Ne gam kalır, ne rüyadan belirtiler Tualde rengarenk cümbüş Kayın ağaçlarının tit...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-kal-benimle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heves', 'heves-harun-celik-3-jtr34', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin aşkın bir hevesti, bunu çok iyi anladım.

Ben ki senden gelecek en ufak bir sevgiye muhtaçtım.

Beni sev diye değil bu sözler, bunu bil, inan ki

Yaptığın hatanın farkına varsan, bu bile yeterdi.

Dışarıdan gözlemliyorum insanları; yaşamak bu değil.

Aşkın devri bitmiş, gözler şöhrete, paraya dikilmiş.

Sevgi, saygı yok; sırtından bıçaklamak isteyen çok.

Bunca derdin arasında sevdaya kalan bir yer yok.

Zaman aldırmadan geçiyor, ağlasan da gülsen de.

Öyle bir yara açılmış ki dikiş tutmuyor kalpte.

Ben yine severim de yürek dayanır mı bunca ihanete?

Ayrılık bile kahpece kefen giydirir yaşarken bedene.', 'Senin aşkın bir hevesti, bunu çok iyi anladım. Ben ki senden gelecek en ufak bir sevgiye muhtaçtım. Beni sev diye değil bu sözler, bunu bil,...', ARRAY['Türk Edebiyatı','Şiir','Harun Çelik 3']::text[], 8.5, '{"poet":"Harun Çelik 3","poet_slug":"harun-celik-3","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/heves-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Kadar Gerçek', 'dus-kadar-gercek-erkan-eren-6zpfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'suskunluğuna akarsın, yoksun

yüreğinin gizeminden geçer tüm ırmaklar

bulutlarıyla ağar içine mahzun gözlerinin

hasret kaldığın, unutulmayan güzel yıllar

seni pencerenin karanlığına hapseden

yitik sokakların hınzır uğultusu

gözlerken kendini aynasında puslu mazinin

en güzel hatıranın görkeminde kaybolursun

kuşlar nicedir üstümden uçar delicesine

nihayetinde feryadıdır ondan habersiz kalışın

vardır bilirim sevdiği her insanın

gününü beklersin, ölümden yok kaçanımız

mısralara böldürmekten kendini

hakkını vermek isterim bu lirik şiirin

zaman büyütürken hiç geçmeyen kederimi

yüreğine kat beni, ey sevgili

tek başınayım bu hazımsız yeryüzünde

ve özlersin kendini

yâre yakılan bir gamlı yürek taşırsın

tılsımlı bir bilmece gibi düşsel bu hayat

bilemez insan ömrün ne getireceğini

uzadıkça yıllar

anlaşılmaz gelir yaşananlar…', 'suskunluğuna akarsın, yoksun yüreğinin gizeminden geçer tüm ırmaklar bulutlarıyla ağar içine mahzun gözlerinin hasret kaldığın, unutulmayan ...', ARRAY['Türk Edebiyatı','Şiir','Erkan Eren']::text[], 8.5, '{"poet":"Erkan Eren","poet_slug":"erkan-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dus-kadar-gercek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz doğmamış sabah', 'henuz-dogmamis-sabah-basak-kaya-mit80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen dünya, kendi ağırlığına yenilir, Duvarlar içimize doğru büyür,

İnsan, kendi kalbinin içinde

Çıkışını bulamadığı bir mevsime sıkışır.

Oysa içimizde tuhaf bir şey yaşar, Takvimlerin yaşlandıramadığı bir çocuk, Saçlarına ak düşse de düş kurmaktan vazgeçmeyen,

Her kırılışında başka renkte çiçeklenen bir dal.

Belki de bütün mesele budur,

Karanlık dediğimiz, ışığın henüz çözemediği bir düğüm,

Acı dediğimiz, ruhun derininde

Henüz adını koyamadığımız bir değişim.

Gel, bu gece zamana dokunmayalım, Saatlerin telaşını kapının dışında bırakalım, İçimizde tomurcuklanan o eski baharı Kimsenin bilmediği bir yerde saklayalım.

Nasıl olsa sabahın bir huyu var,

En suskun pencerelere bile renk bırakır,

Ve hayat, bütün itirazlarımıza rağmen

Bir gün yeniden gülümsemeyi hatırlar.

Belki de yarın dediğimiz şey,

Henüz yaşanmamış bir mucizenin ilk nefesidir.', 'Bazen dünya, kendi ağırlığına yenilir, Duvarlar içimize doğru büyür, İnsan, kendi kalbinin içinde Çıkışını bulamadığı bir mevsime sıkışır. O...', ARRAY['Türk Edebiyatı','Şiir','Başak Kaya']::text[], 8.5, '{"poet":"Başak Kaya","poet_slug":"basak-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/henuz-dogmamis-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soğuk ile diz dize', 'soguk-ile-diz-dize-osman-atas-coyjp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sessiz bir sonbahar gecesinde,

Oturduk şehrin bir köşesine,

Soğuk ile diz dize,

Kaldık yine biz bize,

Kelimeler kördüğüm oldu bile.

Sevdiklerimden uzak,

Sayısız günlerin birinde...

Mesafeler vurdu ters kelepçe,

Zamandan müebbet yemişçesine.

Sabır taneleri bir bir eksilmekte,

Usul usul bitiyor bu gece.', 'Sessiz bir sonbahar gecesinde, Oturduk şehrin bir köşesine, Soğuk ile diz dize, Kaldık yine biz bize, Kelimeler kördüğüm oldu bile. Sevdikle...', ARRAY['Türk Edebiyatı','Şiir','Osman Ataş']::text[], 8.5, '{"poet":"Osman Ataş","poet_slug":"osman-atas","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/soguk-ile-diz-dize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Yazmalim', 'al-yazmalim-ekrem-olgun-a00h6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AL YAZMALIM

Al yazmalım…
Sen hangi baharın yarım kalmış duasısın,
Hangi gurbetin dönüşü olmayan yolu?
Ben seni bir ömür sevmeye niyet ettim,
Kader, daha ilk satırda kırdı kalemimi.
Meğer bazı sevdalar yaşanmak için değil,
İnsanın içinde ömür boyu kanamak içinmiş.

Sen saçlarına akşamı bağlayan kadın,
Ben gözlerinde sabahı bekleyen adam.
Bir mendilin ucuna sığdırdım hasretimi,
Bir ömrü, gelmeyeceğin yollara adadım.
Sen bilmezsin al yazmalım,
Ben her giden trende biraz daha kaldım.

Bir vakit ellerin değmişti ellerime,
Dünya o gün kendi dönüşünü unutmuştu.
Ne gökyüzü bu kadar yakındı toprağa,
Ne de bir kalp böylesine yurdundan olmuştu.
Sen gittin…
Ben o günden beri
Kendi göğsünde sürgün yaşayan bir adamım.

Al yazmalım…
Bir sevdanın da yetim kaldığı olurmuş,
Ne mezarı belli olur ne de öldüğü zaman.
İnsan bazen birini kaybetmezmiş aslında,
Onunla yaşayacağı bütün yarınları kaybedermiş.
Ve en ağır matem,
Ölmemiş birinin ardından
Ömür boyu yas tutmakmış.

Şimdi hangi türküye dokunsam sen ağlarsın,
Hangi rüzgâr esse saçların gelir aklıma.
Bir eski fotoğrafın sararmış kenarında
Hâlâ gençliğimle beklerim seni.
Zaman herkesi yaşlandırdı al yazmalım,
Bir tek sana kavuşamadığım yaşımda kaldım.

Bilirim, her sevda kavuşmakla tamamlanmaz,
Bazı aşklar ayrılığın alnına yazılır.
Bir kadın gider, ardında bir adam kalır;
Kadın başka bir hayata karışır,
Adam kendi hayatından çıkarılır.

Ve bir gün sorarlarsa sana,
"O adam seni ne kadar sevmişti?" diye,
Sakın ömrünü anlatarak cevap verme.
De ki:

"Ben onun hayatından gittim,
O benim yokluğumdan hiç dönemedi."

EkOL', 'AL YAZMALIM Al yazmalım… Sen hangi baharın yarım kalmış duasısın, Hangi gurbetin dönüşü olmayan yolu? Ben seni bir ömür sevmeye niyet ettim,...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/al-yazmalim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışamadım', 'alisamadim-erokrates-erol-guner-tpxwb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni bir daha göremeyecek olmak… 

Ne büyük bir acı, bir bilsen…

Şimdi her gece başımı yastığa koyduğumda,

 Sensizliğin acısı düşüyor rüyalarıma..

 Uykularımda bile senden mahrum kalıyorum;

 Her sabah gözyaşlarımla uyanıyorum yokluğuna…

Belki günler geçiyor, zaman akıp gidiyor;

 Ama ne dinmeye yüz tutuyor içimdeki sızı

 Ne de hafifliyor yüreğimde yanan bu yangın…

 Aksine, her geçen gün biraz daha büyüyor sensizliğin ateşi;

 Ben ise o ateşin içinde her gün biraz daha eriyor, 

 Kor gibi yanıp, küle dönüyorum…

Ben senin hasretinle, yana, yana eriyip tükeniyorum sevdiğim…

Ey bakışına, gülüşüne kurban olduğum, yâr!...

 Söyle şimdi, söyle, senin olmadığın bir hayata nasıl alışırım?

 Senin olmadığın bir günü nasıl yaşarım ben?

Şimdi adını anınca, boğazım düğüm düğüm oluyor,

 Nefesim kesiliyor, dizlerim titriyor..

Ben bir gün değil, bir an bile sensizliğe alışamadım, alışamıyorum sevdiğim..

 Yokluğunun ağırlığı altında her defasında

 Biraz daha yıkılıyor, biraz daha eriyorum…

Artık, artık yokluğunu düşünmek bile istemiyorum.

 Oysa ben,  sensizliğin karanlığında kaç kez yıldızları saydım, 

 Kaç gece gözyaşı döktüm,

 Kaç defa kendi içimde yıkıldım, inan sayısını bile bilmiyorum…  İnan bilmiyorum 

Ama şunu bil sevdiğim, şunu hiç unutma:

 Ben seni gökyüzündeki yıldızlar kadar değil,

 Her bir yıldızın ışığında seni arayacak kadar sevdim.

 Sen benim için yalnızca bir sevda değil,

 Yokluğunda bile bana hayat oldun ,nefes oldun.. 

Şimdi söyle, söyle bana sevdiğim…

Sana aldığım nefesimi versem,

 Yeniden dünyaya döner misin?

 O kara toprağın altından kalkıp

 Bir kez daha ellerimi tutar mısın?

 Yeniden gözlerimin içine bakıp,

 Beni yine sever misin?

Yada…. Beni de yanına alır mısın?

Ne olur beni sensiz bırakıp gitme.. 

Ne olur, bu kadar acımasız olma…

 Biliyorum, sen beni bu dünyada sensiz bırakıp,

 O kara toprağın altında tek başına yatacak kadar

 Bencil değilsin…

Ama ne olur, gittiğin yerde de beni de unutma.

 Çünkü ben hâlâ burada, Senin yokluğuna alışamadan,

 Sensizliğin acısıyla yaşamaya çalışıyorum da onuda beceremiyorum …

Şimdi gidiyorum, gidiyorum sevdiğim..

 Ama şunu sakın, sakın aklından çıkarma sevdiğim...

Ben... Ben seni yalnızca yaşarken değil,

Ömrünün son nefesine kadar sevdim..

Çünkü ben seni ölünceye kadar değil, 

Öldükten sonra da sevdim.. 

Bu can bu bedenden çıkıncaya kadar da seveceğim 

Ben seni, öldükten sonra da seveceğim...

18,04,2021', 'Seni bir daha göremeyecek olmak…  Ne büyük bir acı, bir bilsen… Şimdi her gece başımı yastığa koyduğumda,  Sensizliğin acısı düşüyor rüyalar...', ARRAY['Türk Edebiyatı','Şiir','Erokrates Erol Güner']::text[], 8.5, '{"poet":"Erokrates Erol Güner","poet_slug":"erokrates-erol-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/sensizligin-acisi-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüz Çevirmiş Dünya', 'yuz-cevirmis-dunya-umit-arat-2-tcxoe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşmüş bir ateşte öyle yanarım

Girdaba kapılmış gider ağlarım

Yokmuş bu dünyada yara saranım

Yüz çevirmiş hayat kime ne deyim

Varmı yaşamanın hiçbir amacı

Sensiz dünya bana zehirden acı

Arasan bulunmaz bunun ilacı

Yüz çevirmiş kader kime ne deyim.

Karalar giyinmiş bağlı elleri

Açmıyor bağımın solmuş papatyaları

Küsmüş ötmez artık hiç bülbülleri

Yüz çevirmiş dünya kime ne deyim.

Dolanır dururum gücüm yetmiyor

Tükenmiş çareler fayda etmiyor

Genç Kalem böyle ömür geçmiyor

Yüz çevirmiş her şey kime ne deyim.', 'Düşmüş bir ateşte öyle yanarım Girdaba kapılmış gider ağlarım Yokmuş bu dünyada yara saranım Yüz çevirmiş hayat kime ne deyim Varmı yaşamanı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Arat 2']::text[], 8.5, '{"poet":"Ümit Arat 2","poet_slug":"umit-arat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yuz-cevirmis-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MÜ''MİN KAFİR HERKES AĞLAR', 'mu-mi-n-kafi-r-herkes-aglar-cafer-sadik-yazgan-cv653', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yerler ağlar, gökler ağlar,
Peygamber özüne ağlar.
Zehra ile Haydar ağlar,
Mümin, kafir herkes ağlar.

Sadık yazdı, kalem ağlar,
Kerbela''da taşlar ağlar.
Duyan yürek derin ağlar,
Her bir nefes, canlar ağlar.

Şimrin gözü kanla dolmuş,
Kılıç susmuş, hançer ağlar.
Kendi eli titrer durur,
Şimrin eli, canlar ağlar.

Zehra elde gömlek tutar,
Kanlı gömlek dile gelir.
Mahşer günü nida kopar,
Kıyamette yasla ağlar.

Harmale okunu saldı,
Ali Asgar can evladı.
Ok değdiğinde sustu dünya,
Yer ağladı, gök ağlar.

Ümmü Leyla bağrı yanar,
"Ekber" diye ağlar, ağlar.
"Yavrum" diye ağıt yakar,
Ana yüreği kan ağlar.

Rabab''ın sütü ağlar,
Asgar gelir, gönül ağlar.
Dertli yürek taş kesilir,
Gözden yaşlar selce çağlar.

Ekber''in zülfü savrulur,
Amber kokar, sümbül ağlar.
Gül yüzüne hasret kalan,
Bağda ağlar, taşta ağlar.

Ehlibeytin yasın yazdım,
Zalim ile zulmü yazdım.
Mürekkebim kana döndü,
Kalem ile yasım yazdım.

Ali''nin başı yarıldı,
Mihrap kana boyandı.
Cami sustu, minber yandı,
Muhammed''in canı yandı.

Malik Eşter mezar sarar,
Ali''den yadını anar.
Dost dedi Haydar için,
Kabrin başı yasla ağlar.

Sadık der ki yandı bağrım,
Kerbela''dır derdim, ağrım.
Ehlibeyte kurban canım,
Bu sevdayla gönlüm ağlar.

Sadık der ki kanlı çölüm,
Her taşında vardır ölüm.
Hüseyin''le ağlar gönlüm,
Gözlerimden yaşlar akar.', 'Yerler ağlar, gökler ağlar, Peygamber özüne ağlar. Zehra ile Haydar ağlar, Mümin, kafir herkes ağlar. Sadık yazdı, kalem ağlar, Kerbela''da t...', ARRAY['Türk Edebiyatı','Şiir','Cafer Sadık Yazgan']::text[], 8.5, '{"poet":"Cafer Sadık Yazgan","poet_slug":"cafer-sadik-yazgan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/mu-min-kafir-herkes-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Edepsiz !', 'edepsiz-kamil-caglar-0obk9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kuzeyden indi tokat
adım silkelendi yarım yamalak
bir çamaşır mandalıyla asıldım
kurudu etim, budum..
yüzüme yapıştı yoksulluk
griye döndü tonum
tenimde bir arsızlık
canıma tak etti, haksızlık!
isteksizim sonunda, dargınlıktan
sıkıldım artık serenattan..
tonsürton bir edepsizim!
zannın hikmetini bilmeden,
usûlsüz üstüme giymişim..

19.11.2026/16.20
Akyazı-KÇ', 'kuzeyden indi tokat adım silkelendi yarım yamalak bir çamaşır mandalıyla asıldım kurudu etim, budum.. yüzüme yapıştı yoksulluk griye döndü t...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çağlar']::text[], 8.5, '{"poet":"Kamil Çağlar","poet_slug":"kamil-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/edepsiz-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkem Ağaçsız Kalmasın', 'ulkem-agacsiz-kalmasin-umit-arat-2-1ancu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kıymayın ormana onlar bir candır

Doğaya çevreye birer hayattır

Sahip çık ağaçlar bize hep candır

Şu yüce dağlarım öksüz kalmasın.

Türlü türlü çiçek açar ovası

Dalında ne güzel durur meyvesi

Bozma hiçbir kuşun güzel yuvası

Yaylalar, ovalar çıplak kalmasın.

Oksijen deryası bize bir nimet

Aldığın nefese her gün şükür et

Ormanlar bizlere kutsal emanet

Ağaçsız topraklar yerler kalmasın.

Ağaçsız yerlerde hiç hayat yoktur

Dağları ormansa ne güzel hoştur

Genç Kalem der ki ağaçlar dosttur

Cennet bu ülkem ağaçsız kalmasın.', 'Kıymayın ormana onlar bir candır Doğaya çevreye birer hayattır Sahip çık ağaçlar bize hep candır Şu yüce dağlarım öksüz kalmasın. Türlü türl...', ARRAY['Türk Edebiyatı','Şiir','Ümit Arat 2']::text[], 8.5, '{"poet":"Ümit Arat 2","poet_slug":"umit-arat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ulkem-agacsiz-kalmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Corona', 'corona-umit-arat-2-v1sxw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görünmez bir düşman gibi dolaştın

Nice ocak söndü nice can yaktın

Saldırdın bizlere her gün ağlattın

Acıman hiç yokmuş senin korona.

Kiminin canını aldın zamansız

Kimini bıraktın halsiz mecalsiz

Çöktün üstümüze kâbus amansız

Bitirdin hayatı zalim korona.

Seninle yaşamak öyle bir zor ki

Yıktıkça eline ne geçti sanki

Yakayı bırakıp bilmem gider ki

Yeter çektiğimiz senden korona.

Aldın elimizden ekmeği aşı

Bıraktın ardından acı göz yaşı

Genç Kalemin birde bacı kardeşi

Yaktı hepimizi zalim korona.', 'Görünmez bir düşman gibi dolaştın Nice ocak söndü nice can yaktın Saldırdın bizlere her gün ağlattın Acıman hiç yokmuş senin korona. Kiminin...', ARRAY['Türk Edebiyatı','Şiir','Ümit Arat 2']::text[], 8.5, '{"poet":"Ümit Arat 2","poet_slug":"umit-arat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/corona-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Yalanımış', 'dunya-yalanimis-umit-arat-2-h7ipw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorulma boşuna çaban nafile

Çekersin dünyada her türlü çile

Bir sevenin bir gün çıksa da bile

Dikerler üstüne bir mezar taşı.

Sanmaki dünya da muradın olur

Bu acı dertlerin bir gün son bulur

İyi günün dostu nede çok olur

Dara düşsen hepsi çekilir gider.

Ne gelenin olur ne seni soran

Ne adın anılır ne sana yanan

Çıksa da sana bir bakıp acıyan

Döker toprağına bir yudum suyu.

Dünya yalan ımış fazla güvenme

Kimseye sırrını sakın söyleme

Genç Kalem derki bir şey bekleme

Mezarına gelmez Allah’ın kulu.', 'Yorulma boşuna çaban nafile Çekersin dünyada her türlü çile Bir sevenin bir gün çıksa da bile Dikerler üstüne bir mezar taşı. Sanmaki dünya ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Arat 2']::text[], 8.5, '{"poet":"Ümit Arat 2","poet_slug":"umit-arat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-yalanimis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dijital proleterya', 'dijital-proleterya-umut-kaplan-8ooak', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Digital Proletarya

Bak şu ekranın arkasındaki dijital yoldaşlara,

Hepsi birer "özgür" birey, hepsi kendi adasında.

Sermayenin fiber optik ağlarında sörf yaparlar,

Devrimi tek tıkla başlatırlar, kahvelerini soğutmadan.

Algoritma burjuvazisi emretmiş: "Kaydır, beğen, geç!"

Dijital yabancılaşma dediğin, üç kuruşluk bir skeç.

Artı-değer üreten klavyeler, nasırlı başparmaklar,

Sanal barikatların ardında hep sahte kahramanlar.

"Bana dokunmayan virüs bin yaşasın" diyen lümpen burjuva,

Profiline eklemiş en havalı pozları süslü davaya

Dayanışma dedikleri yirmi dört saatin bir hikayesi,

Sınıf bilinci mi? O da en son güncellemenin bir hediyesi.

Kendi kendinin patronu olmuş, prekarya ve yalnız,

Veri madeninde ırgat, ama filtrelerle hepsi kral kraliçe

Kaldırın sanal yumrukları, ekranlar parlasın biraz,

Sistemin kölesi olmuş, sen yine utanmadan "özgürlük" diye yaz!', 'Digital Proletarya Bak şu ekranın arkasındaki dijital yoldaşlara, Hepsi birer "özgür" birey, hepsi kendi adasında. Sermayenin fiber optik ağ...', ARRAY['Türk Edebiyatı','Şiir','Umut Kaplan']::text[], 8.5, '{"poet":"Umut Kaplan","poet_slug":"umut-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dijital-proleterya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldım Çaresiz', 'kaldim-caresiz-umit-arat-2-hcf56', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün yine içim efkârla doldu

Senin yokluğunda çaresiz kaldım

Hasretin yürekte yara dert oldu

Senin gidişinde çaresiz kaldım.

Arayı arayı gezdim dolandım

Yollar aştım sana yar varamadım

Oturdum ardından öyle ağladım

Tükendi ümidim çaresiz kaldım.

Bir başıma kaldım döndüm virane

Dokunsan ağlarım halim sorana

Kimbilir nerede yârim dolana

Sen gidince öyle kaldım çaresiz.

Ararsın boşuna yaban ellerde

Sefil olur kalır gittiğin yerde

Genç Kalem gibi düşersin derde

Yar yoluna baka kaldım çaresiz.', 'Bugün yine içim efkârla doldu Senin yokluğunda çaresiz kaldım Hasretin yürekte yara dert oldu Senin gidişinde çaresiz kaldım. Arayı arayı ge...', ARRAY['Türk Edebiyatı','Şiir','Ümit Arat 2']::text[], 8.5, '{"poet":"Ümit Arat 2","poet_slug":"umit-arat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kaldim-caresiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Gülüşü', 'annemin-gulusu-guven-tekin-urkea', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '​Gündüzün yükünü sırtımdan atıp,

Her gece gizlice sana yürürüm.

Dünyanın derdini derine katıp,

Rüyamda uyanır, seni görürüm.

​Benim her yokuşum, her düzüm sana,

Yürüdüğüm her yol anneme çıkar.

Hasretle sarılan o özüm sana,

Yokluğun içimde bir nehir, akar.

​Karanlık odama bir ışık sızar,

Rüyalar aleminde hasbihal ederiz.

Zaman durur orda, kaderi yazar,

Biz bizde kaybolur, bize gideriz.

​Beni bir tek senin o gözün anlar,

Yüzüme bakarsın içten ve derin.

Sanki hiçe sayılır geçen o yıllar,

Hâlâ başımdadır o şefkatli elin.

​Dudağında beliren o tatlı gülüş,

İçimin kışını bahara döner.

Sanki bir mucize, kutsal bir geliş,

Gönlümün yanan o ateşi söner.

​Annem sen gülünce ben de gülerim,

Dünyanın neşesi yüzünde açar.

Seninle her derdi baştan silerim,

Karanlık gölgeler önümden kaçar.

​Ama her gecenin bir sabahı var,

Gözümü açarım, her şey bir rüya.

Oturmuş içimde bir yetim ağlar,

Yalanmış meğerse bu koca dünya.

​Anladım, gidenler gelmezmiş geri,

Toprak alanını vermezmiş usta.

Sadece kalırmış kalpteki yeri,

İnsan uyanınca kalırmış yasta.

​Gidip de dönmeyen yollar utansın,

Ümitler rüyada çiçek açarken.

Vefasız bu dünya varsın uykuda yansın,

Ellerim boş kalır ömür uçarken.

Nasibim bu hasret, bu dertli yara.

Tatlı bir tebessüm kalır rüyadan.

Eşsiz bir özlemle düşerim dara,

Kurtarır hatıran beni dünyadan,

İsmin kalbe mühür, canım anneciğim,

Nur içinde uyu, benim her şeyim.', '​Gündüzün yükünü sırtımdan atıp, Her gece gizlice sana yürürüm. Dünyanın derdini derine katıp, Rüyamda uyanır, seni görürüm. ​Benim her yoku...', ARRAY['Türk Edebiyatı','Şiir','Güven Tekin']::text[], 8.5, '{"poet":"Güven Tekin","poet_slug":"guven-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/annemin-gulusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurun Şahit Olduğu Gece', 'yagmurun-sahit-oldugu-gece-i-hsan-yilmaz-xjmqa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'YAĞMURUN ŞAHİT OLDUĞU GECE

İhsan YILMAZ

İlk göz göze geldiğimiz o an, Sanki zaman durdu Gözlerinden yüreğime bir kıvılcım düştü, Adını koyamadığım bir sıcaklık, Sessizce içime işledi.

Sonra bir gün elini tuttum, Parmakların parmaklarıma dokunduğunda, Kalbimin sesini duydum. Boynuma sarıldığın o an, Dünya sustu, yalnızca ikimiz kaldık.

Hatırlıyor musun ? Dışarıda yağmur yağıyordu, Gökyüzü sanki bizim için ağlıyordu. Ama biz mutluyduk… Nefeslerimiz sıcacık, Yüreklerimiz birbirine yakındı.

O romantik gecenin sessizliğinde, İlk mutluluğumuzu birlikte yaşadık. Yağmur cama usulca vururken, Sen başını omzuma yasladın, Ben gözlerinde kaybolmayı seçtim.

Ne yağmurun sesi sustu, Ne de içimdeki o güzel heyecan… Bir tek sen vardın, Bir de kalbimin sana söyleyemediği Binlerce sevgi sözcüğü.

Bilmeni isterim… Bazı insanlar hayatımıza tesadüfen girer, Ama ruhumuzda unutulmaz izler bırakır. Sen benim için öyle birisin. Bir bakışınla başlayan, Bir dokunuşunla güzelleşen, Yağmurlu bir gecede kalbime yazılan En güzel hatıralarımdan birisin.

Bir gün yine yağmur yağarsa, Bil ki ben o ilk geceyi hatırlayacağım. Çünkü bazı geceler sabah olur, Ama insanın yüreğinde hiç bitmez…

Kasım/2026', 'YAĞMURUN ŞAHİT OLDUĞU GECE İhsan YILMAZ İlk göz göze geldiğimiz o an, Sanki zaman durdu Gözlerinden yüreğime bir kıvılcım düştü, Adını koyam...', ARRAY['Türk Edebiyatı','Şiir','İhsan Yılmaz']::text[], 8.5, '{"poet":"İhsan Yılmaz","poet_slug":"i-hsan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yagmurun-sahit-oldugu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyüp Yazgan', 'eyup-yazgan-cafer-sadik-yazgan-na1aa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EYÜP YAZGAN

Stêrka Esmanê Min 

Eyübê can bire min

Stêrka esmanê min

Birîna giyanê min

hesretu jiyana min

Cennet bibe cihê te

Nur biherike ser te

Ehl''i beyt rêhbere te

Kur ''an nur''e jı bo te

Berxê dayîke wa çû,

Sebra dilê min wa çû.

Ronahiya çava çu,

Eyûbê canemın çû

Xortek nazik wek kevok,

Dilê paqij, rû xeşık.

Hejdeh salî, he zarok,

Te jı bir nake dirok

Bigrî dayê ke, ew çu

Bihara dilê min çû,

Hêviya rojên min çû,

Eyûbê min barkır, çû!

Ezîzê dil lı ku ye?

Sebrâ dilê mel ku ye?

Dermanê çav lı ku ye

Eyübe me lı ku ye 

Wek biharê xeşık bu,

Pır nazıku delal bu

Azize dile mın bu

Ew bêhna diya xwe bû

Xortê nazik, canê min,

Gula sor baxçeyê min.

Êşê xiste dilê min,

Kûla giran, derdê min.

Ev bû mêvanê kalê,

Ronahiya her halê.

Çû, hişt agir lı male,

Ax û nalîn ket malê.

Eyûb  li te digerîm,

 Çıma ez te nabinim.

Nûra çava nabinim

 Hêstira  dıbarinim

Eyûb, li te digerîm,

Li ser rê û ber derî.

Ez dengê te dibihîzim,

Lê tu nayê cane  min.

Eyûbe canê min çû,

Sebra dilê min wa, çû.

Piştî te dil şewitî,

Ruhê min bı tere çû

 Eyûb can ji bir na be,

Agirê dil namire.

Navê wî dil dimîne,

Eyüp tı car namıre!

Azîzê dila çuye

Sebra dilê mel ku ye?

Dermanê her du çavan,

Ronahiya me çûye

  

Eyûb,çûyî ji ba mîn,

Jiyan bu zindana min. 

Hêsir çavan dibarin, 

Dünya bu zindana mi. 

Cennet mekanê te ke

Cîhê te fîrdews bi ke

Ehli beyt şefaet ke

Xwedê rehmê lı te ke

Dayık dıbej canê min,

Tu ronîya çavên min

Ew Berxemın lawe min

Hesreta wi canemın 

Sadık Cafer 

10.10.2026', 'EYÜP YAZGAN Stêrka Esmanê Min  Eyübê can bire min Stêrka esmanê min Birîna giyanê min hesretu jiyana min Cennet bibe cihê te Nur biherike se...', ARRAY['Türk Edebiyatı','Şiir','Cafer Sadık Yazgan']::text[], 8.5, '{"poet":"Cafer Sadık Yazgan","poet_slug":"cafer-sadik-yazgan","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/eyup-yazgan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sana Küsmedim', 'ben-sana-kusmedim-umit-arat-2-hebgj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gel yüzünü benden çevirme gülüm

Ben sana küsmedim cananım benim

Senden başkasına yoktur hiç sözüm

Ben sana küsmedim sevdiğim benim

Bağrımda hasretin bir ateş gibi

Yakıyor alevi sanki kor gibi

Bağlanmışım sana deliler gibi

Ben sana küsmedim ela gözlüm benim

Uzaklaşma benden gel del eyleme

Seni sevdiğimi ele söyleme

Zaten yaralıyım gülüp eğlenme

Ben sana küsmedim sevdiğim benim

Taşımaz bu yüklü düşer kollarım

Şaşır çıkmaza girer yollarım

Senden ayrılırsam nasıl yaşarım

Ben sana küsmedim ela gözlüm benim

Kış bitmeden mevsim bahar olur mu

Garip bülbül bağda gülsüz durur mu

Genç Kalem söyle sensiz olur mu 

Ben sana küsmedim sevdiğim benim.', 'Gel yüzünü benden çevirme gülüm Ben sana küsmedim cananım benim Senden başkasına yoktur hiç sözüm Ben sana küsmedim sevdiğim benim Bağrımda ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Arat 2']::text[], 8.5, '{"poet":"Ümit Arat 2","poet_slug":"umit-arat-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-1518-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Dediklerim', 'dost-dediklerim-ramazan-yildiz-3-aeukn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koşup tutar beni zordayken derdim

Seyrimize baktı dost dediklerim

Yağmur olup yağar kordayken derdim

Bağrımızı yaktı dost dediklerim

Dost için yokuşu dümdüz ederdim

Karanlık geceyi gündüz ederdim

Seni beni yoktu biz için derdim

Şimdi bizi ekti dost dediklerim

Dosta gönül konmaz hiç naz olmazdı

Dost olan dostuna aç göz olmazdı

Onlarsız kış bahar hiç yaz olmazdı

Boynumuzu büktü dost dediklerim

Bahçelerinde gül bağ olsunlar da 

Varsın yerlerinde sağ olsunlar da 

Benden ötelerde dağ olsunlar da

Tepemize çöktü dost dediklerim 

Kul Ramazan der ki ne bilsin eller

Ömür geldi geçti harcandı yıllar

Dostların yerinde esiyor yeller

Dalımızı döktü dost dediklerim

RAMAZAN YILDIZ', 'Koşup tutar beni zordayken derdim Seyrimize baktı dost dediklerim Yağmur olup yağar kordayken derdim Bağrımızı yaktı dost dediklerim Dost iç...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Yıldız 3']::text[], 8.5, '{"poet":"Ramazan Yıldız 3","poet_slug":"ramazan-yildiz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dost-dediklerim-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yahya Maslak', 'yahya-maslak-cafer-sadik-yazgan-p6muy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ji Bo Bîranîna Keke mın

Ey Yahya ye Keke  min, stêrka esmanê min,

hesretu jiyana min,Êşê xiste dilê min

Şiret''e te tev ders bun, ji mer nûru hikmet bun,

Gotinên te xurt û kûr , rêyên te saf û nûr bûn.

İnsanek hişmend zana, bo feqîran dest-zana,

Kel ha dostu ciran a, stêrken asuman a.

Kekê çûna te pir zor,Anî ser me xem û mor.

Tu hişmend û zana bûy,Çira tarî kir serbor.

Kekê bi aqil û jîr, bûyî rêber û xebîr,

Ji bîra me tu naçî, di dil de mabî azîr.

Îro ketî bîra min, kekê min tu sebra min,

têr nebûn keko ji te ,sohbet û şîrete te.

Kanê sebra dilê me , kekê me  wek bavê me,

Ka dermanê vî dilî, hesir''u bê kes ma me

Piştî te dil şewitî, ruhê me bi te ra ma

Tu çûy ev dilê me ma, canê me li ba te ma 

Kekê min bar kir ji vir, sebra dila çû ji vir,

Mala me  bê şevçira, çav man li dû te bira,

Çûy ji ba me axa can, jiyan bo me bû zîndan,

Bete sebra mın naye, jiyan lı me bu zindan 

Cihê te ew firdewsê, tewaf ke alî hewsê,

Ehlê beyt şefaat ke, Xwedê dilê te şa ke.

Sâdık dıbêj bîra te, ji dil naçe navê te,

Rihma xade lı te be ,nebi hevale te be.

Ey Yahya  kanîya nûr,Hesreta te dil de kûr,

Xuda rehme li te ke,bi Hüseyn ra heşir ke', 'Ji Bo Bîranîna Keke mın Ey Yahya ye Keke  min, stêrka esmanê min, hesretu jiyana min,Êşê xiste dilê min Şiret''e te tev ders bun, ji mer nûru...', ARRAY['Türk Edebiyatı','Şiir','Cafer Sadık Yazgan']::text[], 8.5, '{"poet":"Cafer Sadık Yazgan","poet_slug":"cafer-sadik-yazgan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yahya-maslak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Naciye', 'naciye-salim-erben-qkhrl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar geçse de solmaz yüzün,

Bahara döner her bir güzün,

Gönlümde taht kurdu bu özün,

Can yoldaşımsın sen Naciye.

Aynı sofrada ekmek böldük,

Aynı dertlere çare bulduk,

Zorlu yollarda omuz olduk,

Ömür ortağım sen Naciye.

Saça ak düşse gönül gençtir,

Seninle her gün ayrı sevinçtir,

Yuvamız sarsılmaz bir dinçtir,

Gözümün nurusun Naciye.

Salim''im der ki vefa sende,

Sıcaklık tüter bu bedende,

Sen varsan huzur var hanede,

İki cihanda yar Naciye.', 'Yıllar geçse de solmaz yüzün, Bahara döner her bir güzün, Gönlümde taht kurdu bu özün, Can yoldaşımsın sen Naciye. Aynı sofrada ekmek böldük...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/naciye-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MALDA YALAN MÜLKTE YALAN', 'malda-yalan-mulkte-yalan-sahin-i-nalcik-6cdon', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '​Ne insanlar geldi geçti bu dünyadan,
​Biri sultan oldu, biri şah biri hanedan
Hepsi tahtını bıraktı gitti,
Bir pencere misali; her gelen baktı geçti,

Malda yalan, mülkte yalan, birazcık da sen oyalan,
Malda yalan, mülkte yalan, birazcık da sen oyalan.

Nice "ben benim" diyen, mal mülk,
Servetini bırakıp gitti.
Kime kaldı ki bu fani dünya,
Bir nefeslik can için bu kadar telaş niye?

​Malda yalan, mülkte yalan, birazcık da sen oyalan,
Malda yalan, mülkte yalan, birazcık da sen oyalan.

​Senin bu kibrin kime, senin bu havan kime?
Bakma öyle yüksekten...
İyi bir insan olup sen özüne dönsene
Git bak firavuna; kendini tanrı sanıyordu,
Şimdi müzede süs eşyası oldu

Malda yalan, mülkte yalan, birazcık da sen oyalan,
Malda yalan, mülkte yalan, birazcık da sen oyalan.


​Malda yalan, mülkte yalan, birazcık da sen oyalan,
Malda yalan, mülkte yalan, birazcık da sen oyalan', '​Ne insanlar geldi geçti bu dünyadan, ​Biri sultan oldu, biri şah biri hanedan Hepsi tahtını bıraktı gitti, Bir pencere misali; her gelen ba...', ARRAY['Türk Edebiyatı','Şiir','Şahin İnalcık']::text[], 8.5, '{"poet":"Şahin İnalcık","poet_slug":"sahin-i-nalcik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/malda-yalan-mulkte-yalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdasızlık', 'sevdasizlik-yilmaz-efe-alabas-cs22f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ne zormuş bu sevdasızlık

sevda hayatın tadı tuzuymuş

eşi benzeri yok eksikliğinin

sevdasızlık insana koyuyormuş

masamda kitabım ve yarım çay

elimde sigaram aklımda kadınlar

ama öyle herhangi bir kadın değil

dudak üstünde beni olan kadınlar

içimde bi sıkıntı var hissediyorum

sanıyorumki sevdasızlıktır sebebi

eğer bulursam şiir seven bir kadın

sanıyorumki geçer sıkıntım pek tabi', 'ne zormuş bu sevdasızlık sevda hayatın tadı tuzuymuş eşi benzeri yok eksikliğinin sevdasızlık insana koyuyormuş masamda kitabım ve yarım çay...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Efe Alabaş']::text[], 8.5, '{"poet":"Yılmaz Efe Alabaş","poet_slug":"yilmaz-efe-alabas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevdasizlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes aç', 'herkes-ac-yilmaz-efe-alabas-wz57l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bazen unutuyorum hayatın zalimliğini

hesap ödettiğimde taş oynarken

üstünde hoş benli bir dudağı öperken

doğan güneşe sigaramı üflerken

sonra farkına varıyorum

bu daha buz dağının görünen yüzü

şairim en başta hüzünlüyüm

güzel anlarda güzel şiir yazılmıyor

gerçi ne kadar güzel an var tartışılır

gelecek ne kadar güzel tartışılır

ha kısıtlı imkanlar o tartışılmaz işte

şairlerin dertleri o da tartışılmaz

orhan veli mesela kalemini severim

mütevazıymışta aslında lakin

ceketsiz göçtü cebinde 28 kuruşla

velhasıl biz hatayı başta yaptık

nerde kalem kağıt bulsak yazdık

öyle bir yere geldik ki herkes aç

çare arayıp şiir yazan daha da aç', 'bazen unutuyorum hayatın zalimliğini hesap ödettiğimde taş oynarken üstünde hoş benli bir dudağı öperken doğan güneşe sigaramı üflerken sonr...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Efe Alabaş']::text[], 8.5, '{"poet":"Yılmaz Efe Alabaş","poet_slug":"yilmaz-efe-alabas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/herkes-ac-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Yaratan Odur', 'beni-yaratan-odur-cafer-sadik-yazgan-8ivvh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni yaratan odur, yolumu o gösterir.

Aç kalsam doyuran o, susasam su verendir.

Bir illet vursa tene, şifam yine ondandır,

Öldüren odur ancak, diriltecek olandır.

Hesap günü gelince ümidim odur ancak.

Hatalarım silinip affa mazhar olacak.

Rabbim bana hikmet ver, ilminle beni donat.

Salihlerin yanına beni de ulaştır kat.

Gelecek nesillerde,hayırla anılayım,

Cennetin mirasçısı, kutlu bir kul olayım.

Yolunda yürüyelim, bağışla babamı da.

Rezil rüsva eyleme, o büyük gün kapıda.

O gün ki ne evlat var, ne mal verir bir fayda.

Ancak temiz bir kalptir,kurtuluş o sarayda.

Müttaki kullar için,cennet yakınlaşacak.

Azgınların önüne,ateş çıkarılacak.

Seslenilir onlara: "Hani nerede taptığınız?"

"Hani Allah dışında,medetler umduğunuz?"

"Size yardım eder mi,sahte ilahlarınız?"

"Kendine hayrı yok ki,ne bekler canlarınız?"

Rabbim bizi kınama,Unutup yanılırsak, 

hesaba çekme ya Rab, hata ile dolarsak.

Bir öncekiler gibi,ağır yük yükleme hiç.

Hesaba çekme ya Rab, hata ile dolarsak.

Sadık der ki ya Rabbi,Affına sığınırım

Rahmetinin nuruyla,Ben Yolunda yürürüm 

Babamı da bağışla,Huzuruna varayım

Salih kullar içinde,Cennetê kavuşayım', 'Beni yaratan odur, yolumu o gösterir. Aç kalsam doyuran o, susasam su verendir. Bir illet vursa tene, şifam yine ondandır, Öldüren odur anca...', ARRAY['Türk Edebiyatı','Şiir','Cafer Sadık Yazgan']::text[], 8.5, '{"poet":"Cafer Sadık Yazgan","poet_slug":"cafer-sadik-yazgan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/beni-yaratan-odur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburen....', 'mecburen-emsal-toprak-c21o5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mecburen… 

Zakkum ekilen yerde hiç gül biter mi

Kim, ne ektiyse onu biçer mecburen 

Mümkün mü? karga bülbül gibi öter mi

Miadı dolan,serden geçer mecburen 

Altına,akçeye kul olup tapan 

Aldanıp,aldatıp,batıla sapan 

Masuma,mazluma haksızlık yapan 

Mizanda adaleti seçer mecburen 

Su arar bulur yatağını,akar alışır

Eğilen her baş ayağa bakar alışır

Çengi,kemeri,zili beline takar alışır 

Kötü nam sahibiyle göçer mecburen 

Tilki çok kurnazdır, hem de çok kıvrak

Kibirliye hem mübah,her şey O’na hak! 

Muhtaçtır Kırk teyide yazıp,çizdiği evrak 

Kirli çamaşırını döküp,saçar mecburen 

Can bedendeyken sakın umudu kesme

Rızık kefillidir, geç, güç olursa küsme

Kalabalıkta yapa yalnız yel olup esme

Arkasızdan dost,arkadaş kaçar mecburen 

E.TOPRAK', 'Mecburen…  Zakkum ekilen yerde hiç gül biter mi Kim, ne ektiyse onu biçer mecburen  Mümkün mü? karga bülbül gibi öter mi Miadı dolan,serden ...', ARRAY['Türk Edebiyatı','Şiir','Emsal Toprak']::text[], 8.5, '{"poet":"Emsal Toprak","poet_slug":"emsal-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mecburen-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rengarenk Hasret', 'rengarenk-hasret-kenan-gezici-n8y7y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmiyorum artık içim neden yangın yeri.

Emin olamıyorum hangi hasreti yaşamalı.

Evet ben bunca yılı yaşadım.

Tanıdık silüetler geçmese önümden.

Gözlerim görmese, aklım hep suçlu.

Bana ait değilmiş gibi gelir dün.

Ulaşmak tamam mümkün değil her istediğine.

Aynalarda köşe kapmaca oynuyorlar benimle.

Bana inat biriken bunca hasret.

Biraz yaşayacaktık sadece 

Neden bu yük niye.

Bir belirip bir kayboluyor.

Beyaz renge bürünen de var.

Kap kara dolaşıyor korkutucu bazıları.

Kenan GEZİCİ   20/11/2026', 'Bilmiyorum artık içim neden yangın yeri. Emin olamıyorum hangi hasreti yaşamalı. Evet ben bunca yılı yaşadım. Tanıdık silüetler geçmese önüm...', ARRAY['Türk Edebiyatı','Şiir','Kenan Gezici']::text[], 8.5, '{"poet":"Kenan Gezici","poet_slug":"kenan-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/rengarenk-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-erokrates-erol-guner-dzhnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben; Güneşin altında kavrulmuş bir çöl,

Sen; Gönül bahçemi dolduran bir göl...

Ben; Susuzluktan çatlamış kıraç bir toprak,

Sen; Ömrüme can veren çağlayan bir ırmak...

Ben; Kimsesiz garip avre bir bülbül,

Sen; Cennet bağımada solmayan bir gül...

Ben; Diyar diyar gezen garip  bir yolcu,

Sen; Gönlüme huzur veren güzel bir duygu...

Ben; Sevgiye hasret kalmış bir dilenci,

Sen; Gönül deryam da saklı bir, inci tanesi...

Ben; Karanlıklarda kaybolan bir gece,

Sen; Karanlığımı aydınlatan bir güneş...

Ben; Sensizliğin içinde yarım bir hayat,

Sen; Hayatıma bahar getiren bir kanat...

Ben; Vuslatın yolunu gözleyen bir yürek,

Sen; Kavuşmak için dilediğim bir dilek...

Ben; Sensizliğin yarım bir cümlesi, 

Sen; Ömrümün en güzel şiir bestesi...

Şimdi ben, sensiz kurumuş bir dal gibi

Seninle yeniden yeşermeyi umut ederek,

Her mevsim baharı bekliyorum....

Ve biliyormusun... 

Ben sensiz yaşamayı değil,

Seninle yeniden hayat sarılmayı diliyorum... Sen bunu bil yeter....

10,12, 2023', 'Ben; Güneşin altında kavrulmuş bir çöl, Sen; Gönül bahçemi dolduran bir göl... Ben; Susuzluktan çatlamış kıraç bir toprak, Sen; Ömrüme can v...', ARRAY['Türk Edebiyatı','Şiir','Erokrates Erol Güner']::text[], 8.5, '{"poet":"Erokrates Erol Güner","poet_slug":"erokrates-erol-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sen-ve-ben-1078-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlgiye aşık kadin', 'i-lgiye-asik-kadin-emin-korkmaz-kiyom', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Offfff kiii neeeee offffff

Bak yine senli oldu bu gece de

Rutubet tutmuş karşı duvara astım son bakışını 

Yaktım sigaramı da o son gulsune ve tokusturdum kadehimi yanlizligina ve özlemle kokladigim saçının teline,

Offff kiii neee offffff

Sabahları uyanırken artık zorlanıyorum yaşlanıyorum galiba eskisi de görmüyor zaten gözlerim galiba ben seni özlerken kos koca bir ömür yitirmisim ardından ve kimse duymadan kimse görmeden sen bilmeden 

Offff kiii neeee offfff', 'Offfff kiii neeeee offffff Bak yine senli oldu bu gece de Rutubet tutmuş karşı duvara astım son bakışını  Yaktım sigaramı da o son gulsune v...', ARRAY['Türk Edebiyatı','Şiir','Emin Korkmaz']::text[], 8.5, '{"poet":"Emin Korkmaz","poet_slug":"emin-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ilgiye-asik-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür Olmak Ne Güzel Şey', 'ozgur-olmak-ne-guzel-sey-dursun-alabiyik-2-2ah1x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖZGÜR OLMAK EN GÜZEL ŞEY

Fakir olmak ayıp değil

Özgür olmak en güzel şey

Yüzün kara gezmek ayıp

Ak yüzlü olmak en güzel şey

Ayıp olan çalmak soymak

Yetimlerin hakkın yemek

Haram lokmaya el sürmek

Dürüst olmak en güzel şey

Kul hakkı çıkar unutman

Sahipsiz mal alıp satman

Helal yiyin haram tatman

İnsan olmak en güzel şey

Aç mezarı gördünüz mü

Neyin nesi sordunuz mu

ÂŞIK SEFİLİ sevdiniz mi 

Özgür olmak en güzel şey

2.11.2026

ÂŞIK SEFİL DURSUN ALABIYIK', 'ÖZGÜR OLMAK EN GÜZEL ŞEY Fakir olmak ayıp değil Özgür olmak en güzel şey Yüzün kara gezmek ayıp Ak yüzlü olmak en güzel şey Ayıp olan çalmak...', ARRAY['Türk Edebiyatı','Şiir','Dursun Alabıyık 2']::text[], 8.5, '{"poet":"Dursun Alabıyık 2","poet_slug":"dursun-alabiyik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozgur-olmak-ne-guzel-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift Sıfır Gemisi ve Tüplü Televizyon', 'cift-sifir-gemisi-ve-tuplu-televizyon-alper-tunga-3-1awev', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gün tüm duvarlarına lambalar asılı,

Sadri Alışık izlenen açık hava sineması gibi

Ve yine tam vaktinde geçiyorum.

Yine seviyorum... Gözlerinden.

Güvertesinden turist Ömer selamı vesselam.

eski tüplü televizyonlar nostaljisinde

Birazda doksanlı yıllara nispeten

El atarileri ve tetris oynama hasretimleyim.

Saçılacak yine bir aralıkta sevimli hediyelerle ve...

Biraz saçlarını anlatalım prenses...

Bir masal perisinin saçları nasıl anlatılırdı

Dalgalı denizler gibiydi bir denk gelişim bu

Aslında bütün detayların sihirli ve nadide

Ben biraz o sevimliliğin aynası olmak istedim.

siyah beyaz bir zamana döneceğim.

Topuklarına basılmış bir ayakkabıyla

Saçlara limon kolonyası ve gömlek tek çizgi...

Tanıdık bir simaya dönüşürken bir saniyeliğine 

Bu defa bütün belediye işçileri minettar,

Yarın gün boyunca tetris oynarlarken

Ve şehirlerde yine gündem değişicekse

Süpürülmemiş sarı yapraklar gündem olacak

Bir romantizm, bir nostaljiye karışacak

Artık evden cıkmayan çocuklarda sokaklarda,

Tablet, bilgisayar faslından el atarisine dönüş bu

Okullarda öğretmenlerin gözleri dolacak ve...

En sıkıcı dersler dahi eminim kaynayacak.

Sevgisiz yetişkinlere bu gün sözüm yok,

Onları Ahmet Batman''la avutmalı

Yine ruh hastası bir köşe yazarı anlatacak,

Kimileri inanıp komplo teorisi derse aldırış etme.

Senin gözlerin en büyük gerçeklik

Güneşten ve aydan ışık toplayan bu gemi 

Son hızda giderken sendeler bir aralıkta 

Kendi etrafında dönerek tekrar doğrulur 

Çift sıfır gemisi hep zamana muhalif

Ve çift sıfır gemisi zamanı durdurur 

En büyük aşıklar bu gemiyle buluşur', 'Bu gün tüm duvarlarına lambalar asılı, Sadri Alışık izlenen açık hava sineması gibi Ve yine tam vaktinde geçiyorum. Yine seviyorum... Gözler...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/cift-sifir-gemisi-ve-tuplu-televizyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmış aşk bile yeter', 'yasanmis-ask-bile-yeter-hakan-ozucelenk-tc6wm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nerden bileyim,seni seveceğimi?

Tutku, arzu, özlem olacağını.

Şu küçük,   sıska kızın  gör yaptığını.

İstanbul bana dar, sensiz dert sığanığı.

O göz göze geldiğim an, yaşam cennet.

Bu güzelliğin bana artık  eziyet.

Kader kurdu aramızda bir set.

Gülümsemen bana bir ziyafet.

Yapamadım, aşk sınavı notum sıfır.

Oysa sen aktif ben pasif  ağır.

Geride kalan ömür  boyu kahır. 

Ahirette kızıp , yüzüme bağır

Bana bu yaşattığın sevdaya değer.

Dönmek istersen bir gün eğer.

Bil , bu aşık seni hep bekler. 

Yaşanmış  aşk bile bana yeter.', 'Nerden bileyim,seni seveceğimi? Tutku, arzu, özlem olacağını. Şu küçük,   sıska kızın  gör yaptığını. İstanbul bana dar, sensiz dert sığanığ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Özüçelenk']::text[], 8.5, '{"poet":"Hakan Özüçelenk","poet_slug":"hakan-ozucelenk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasanmis-ask-bile-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Hasretin', 'senin-hasretin-dortdivanli-ali-balaban-sa2cq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen öyle özlüyorum ki seni

Sızlıyor kalbimin en derinleri

Dalıyor gözlerim yine boşluğa

Gündüzler neyse de zor geceleri

Suskunluğum birikir içten içe

Hasretinle yorulur her hece

Bir gölge gibi düşer düşlerime

Senden kalan her anı sessizce

Dilimde hep aynı sessiz çağrı

Yüreğimde hasretin ince ağrı

Ne zaman dinse bu derin sızı

Yeniden sarar beni akşamları

Yüreğimdeki eksiklik büyürken

Sessizce içime hasret düşerken

Adına her gün şiirler yazarken

İçim yanar zaman sensiz geçerken

Dertli yüreğim düştü bir sevdaya

Özlemin sığmaz hiç bir yanıma

Hep aynı sızı benim sol yanımda

Senin hasretin tuz basar yarama

19 Kasım 2026 ALİ BALABAN', 'Bazen öyle özlüyorum ki seni Sızlıyor kalbimin en derinleri Dalıyor gözlerim yine boşluğa Gündüzler neyse de zor geceleri Suskunluğum biriki...', ARRAY['Türk Edebiyatı','Şiir','Dörtdivanlı Ali Balaban']::text[], 8.5, '{"poet":"Dörtdivanlı Ali Balaban","poet_slug":"dortdivanli-ali-balaban","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/senin-hasretin-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktım Bak', 'yaktim-bak-suskun-sair-fazli-acar-3ozes', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YAKTIM BAK

O sokak başını da, o sözü de…

Geldiğin yolu, beklediğim geceleri…

Hatta seni bile yaktım içimde!

Ama nedense,

Sönmüyor bu lanet kor!

Ben sana değil,

Kendime kırgınım.

O gözlerine inanan benliğime…

O “dönecek” diyen saflığıma…

Uğruna delirdiğim gölgene!

Sen neredeydin be?

Ben sokaklarda can verirken,

Adını duvara kazırken,

Kendimle kavga ederken,

Sen kiminle güldün ha?!

Kimin şiirine sustun?!

Bak, ellerim hâlâ titriyor,

Ne bir dua tutuyor beni,

Ne bir küfür rahatlatıyor artık…

Dilimde yarım bir yemin var:

Bir daha kimseye,

“Beklerim” demeyeceğim!

Zaten…

Beklemek nedir bilir misin sen?

Saatin tik takını dinleyip,

İç çekmekle geçen bir ömür…

Ve o ömrün,

Senin yüzünden

Ziyan oluşu!

İşte o yüzden…

Bu gece son!

Ne sokak başı kaldı,

Ne de seni sevecek bir yürek!

Kalbim mi?

Onu da gömdüm.

Mezarı, o terk ettiğin şehirde!

Suskun Şair Fazlı Acar', 'YAKTIM BAK O sokak başını da, o sözü de… Geldiğin yolu, beklediğim geceleri… Hatta seni bile yaktım içimde! Ama nedense, Sönmüyor bu lanet k...', ARRAY['Türk Edebiyatı','Şiir','Suskun Şair Fazlı Acar']::text[], 8.5, '{"poet":"Suskun Şair Fazlı Acar","poet_slug":"suskun-sair-fazli-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yaktim-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Bile Yetişemedim', 'kendime-bile-yetisemedim-ecrin-yavuz-0c0tc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben biraz yarım kalmış bir cümleyim,
sonunu kimsenin merak etmediği.
Biraz çocukluğunda büyümek zorunda kalmış,
biraz da büyüdükçe çocukluğunu özlemiş biriyim.

İçimde iki ayrı mevsim var;
biri her şeye rağmen gülüyor,
diğeri en güzel günün ortasında
kimseye belli etmeden kışa dönüyor.

Bazen bir kelimeyle gökyüzüne çıkıyorum,
bazen hiçbir şey olmamışken
kendi içime düşüyorum.
Beni anlamayanlar değişken sanıyor,
oysa ben her hâlimde kendimle savaşıyorum.

Bir babanın yokluğunu taşıyorum içimde,
öyle sıradan bir özlem değil bu;
kalabalıkların ortasında gözümün
bir çift tanıdık göz araması.
Bazen bir başarı kazanıyorum,
ilk ona anlatmak geliyor içimden.
Sonra hatırlıyorum…
Bazı sevinçlerin de yetimi olur insan.

Sevdim.
Hem de kendimden eksilte eksilte.
Gidenin ardından kapıyı kapatamadım bazen,
kalanın yanında da kendimi bulamadım.
Birinin beni seçmesini beklerken
kaç kez kendimi seçmeyi unuttum, bilmiyorum.

Dost dediklerime içimi açtım,
bazıları içimdeki en kırılgan yeri öğrendi,
sonra tam oradan incitti.
Yine de kimseye kötülük düşünemedim.
Çünkü benim kalbim,
kırıldığı yerden bile başkasına
yer açmaya çalıştı.

Bana güçlü diyorlar.
Oysa bilmiyorlar;
bazen yalnızca ağlamamak için
dişlerimi sıktığımı.
Bazen bir mesaj beklediğimi,
bazen bir ses duymak için telefonu elime aldığımı,
bazen de kimse gelmeyecek diye
ekrana bakmayı bıraktığımı…

Benim içimde anlatılmamış çok şey var.
Bir mezuniyet fotoğrafında eksik kalan sarılış,
bir bayramda boğazıma düğümlenen özlem,
kimseye söylemediğim geceler,
kendime bile itiraf edemediğim kırgınlıklar…

Ve bütün bunların arasında
hayata tutunmaya çalışan bir ben.

Beni tek bir hastalığın adıyla anlatmayın.
Ben yalnızca inişlerimden ibaret değilim.
Bazen kendime yetişemeyen,
bazen kendi içimde kaybolan,
ama hâlâ bir şeylerin güzel olabileceğine
inanmak isteyen bir kadınım.

Şimdi biri çıkıp da sorsa:
“Sen en çok nerede kayboldun?”

Cevap veremem.

Çünkü ben bir gün kaybolmadım.
Biraz babamı özlerken,
biraz sevilmeyi beklerken,
biraz da kimseye belli etmeden ayakta dururken
kendimden uzaklaştım.

Ve en acısı ne biliyor musun?

Herkesi kaybetmekten korktuğum bu hayatta,
bir gün dönüp kendimi aradım.

Baktım…

Ben, herkese yetişmeye çalışırken
kendime hiç gelememişim.', 'Ben biraz yarım kalmış bir cümleyim, sonunu kimsenin merak etmediği. Biraz çocukluğunda büyümek zorunda kalmış, biraz da büyüdükçe çocukluğu...', ARRAY['Türk Edebiyatı','Şiir','Ecrin Yavuz']::text[], 8.5, '{"poet":"Ecrin Yavuz","poet_slug":"ecrin-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/kendime-bile-yetisemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teğet Geçen Kader', 'teget-gecen-kader-dortdivanli-ali-balaban-7dc8h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aynı şehrin sokaklarında yürürken

Aynı rüzgârı soluyup içimize çekerken

İki yabancı gibi hasretinden erirken

Birbirine teğet geçmekmiş meğer kader

Aynı göğün altında, aynı düşlerde

İzlerin kalır rüzgârın estiği yerlerde

Ne sesin duyulur ne gölgen görünür

Sadece teğet geçer bizi bu ömür

Aynı sokak taşlarına basıp geçerken

Aynı akşam serinliğinde sessizce beklerken

İçimizde yarım kalan ukte dillenirken

Birbirine teğet geçmekmiş meğer kader

19 Kasım 2026 ALİ BALABAN', 'Aynı şehrin sokaklarında yürürken Aynı rüzgârı soluyup içimize çekerken İki yabancı gibi hasretinden erirken Birbirine teğet geçmekmiş meğer...', ARRAY['Türk Edebiyatı','Şiir','Dörtdivanlı Ali Balaban']::text[], 8.5, '{"poet":"Dörtdivanlı Ali Balaban","poet_slug":"dortdivanli-ali-balaban","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/teget-gecen-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkla Yanan', 'askla-yanan-eyup-dalkilic-2-tbqpz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsterim dertler bende, 

Hayat hep sende olsun,

Kaybolmuş bende yıllar.

Senin aşkından yoksun.

Mahkûm kaldım bir aşka. 

Yalnızlığın da suskun,

Döndü hazan hicrana, 

Kırıldı kalbim durgun.

Aşkla yanan gönlüme. 

Dermansız dik bir yolsun,

Etme zulüm dur yeter 

Benim gibi bir kulsun.

Yakar aşk ince ince, 

Kalbimse sana kırgın,

Gözüm yolunu bekler, 

Ben de hep sana vurgun.

2026', 'İsterim dertler bende,  Hayat hep sende olsun, Kaybolmuş bende yıllar. Senin aşkından yoksun. Mahkûm kaldım bir aşka.  Yalnızlığın da suskun...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Dalkılıç 2']::text[], 8.5, '{"poet":"Eyüp Dalkılıç 2","poet_slug":"eyup-dalkilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askla-yanan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevincini Sen İkiye Bölerdin', 'sevincini-sen-i-kiye-bolerdin-mehmet-tamer-altiparmak-uf9z8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben aşıktım sende beni severdin

Sevincini sen ikiye bölerdin

Mutluluktan gözlerinle gülerdin

Sarsan beni deryalardan derince

Duygu desem, değer desem ciğerdin

Elmas desem inan bana değerdin

Yaşamanın sevincini sen verdin

Yüreğime aşkı yazdın derince

Kahreden sevdanın gonca gülüsün

İltifata mazhar aşkın dilisin

Selam kelam sevgi saygı bilirsin

Gözleri gülmez mi bir gül verince

Dert belayla şer acıyla inletir

Telli sazın namesini dinletir

Yaşamayı hayat sana belletir

Ak gerdanda kara beni görünce

Bir umut la ömür boyu aradım

Yar aşkına ben ömrümü adadım

Mazideki hatıralar dilimde yadım

 Pişman oldum hidayete erince 

Naz yaparken gururumu eziyor

Keskin gözleriyle beni üzüyor

Acı sözleriyle beni yakıyor

Yaylalarda yeller eser serince', 'Ben aşıktım sende beni severdin Sevincini sen ikiye bölerdin Mutluluktan gözlerinle gülerdin Sarsan beni deryalardan derince Duygu desem, de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tamer Altıparmak']::text[], 8.5, '{"poet":"Mehmet Tamer Altıparmak","poet_slug":"mehmet-tamer-altiparmak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevincini-sen-ikiye-bolerdin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmicem', 'affetmicem-emin-korkmaz-60cu2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok özledim seni ama gidemem 

Oda gelmicek zaten

Belki en uzun en çetin gece olacak

Ama ona uzaktan sevmeme sebep olan kimseyi affetmeyecegim...', 'Çok özledim seni ama gidemem  Oda gelmicek zaten Belki en uzun en çetin gece olacak Ama ona uzaktan sevmeme sebep olan kimseyi affetmeyecegi...', ARRAY['Türk Edebiyatı','Şiir','Emin Korkmaz']::text[], 8.5, '{"poet":"Emin Korkmaz","poet_slug":"emin-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/affetmicem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir İçinde Şiir', 'siir-i-cinde-siir-nurittin-gunay-2-rwyqm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Terk edilirken bir kez daha 

      İlk aşkını hatırladı

Kim bilir bu kaçıncıydı 

      Böylesi gelgitler yaşarken

Yine bir sonbahar akşamında

     Yüreği kaçıncı kez kanamıştı 

Dalından düşen yapraklar misali 

    Savrulmaktaydı hayatı

Hüzünlü şarkılara yoldaşlık eden 

    Bir garip yolcu misali

Ayrılık rüzgarları estiğinde 

   Başında deli deli

İçini bir hoş ederdi yârin işveleri 

    Eserken kavak yelleri

Yüzünde derin bir hüzün

    Dudaklarında ilk öpüşün ıslaklığı', 'Terk edilirken bir kez daha        İlk aşkını hatırladı Kim bilir bu kaçıncıydı        Böylesi gelgitler yaşarken Yine bir sonbahar akşamınd...', ARRAY['Türk Edebiyatı','Şiir','Nurittin Günay 2']::text[], 8.5, '{"poet":"Nurittin Günay 2","poet_slug":"nurittin-gunay-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/siir-icinde-siir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tevbe (43) Peygamberimize Tatlı Uyarı', 'tevbe-43-peygamberimize-tatli-uyari-selim-i-c-hvpq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Peygamberler yüce Allah’a en yakın,

Onlar tertemiz; çamur atmaktan sakın!

Her hâlükârda, hep edebini takın!..

Günahtan uzaktır onlar iyi belle! 

Zaman zaman işleyebilirler zelle. 

Tebük’e katılmamak asıl niyeti, 

Peygambere sıralamış mazereti, 

İzini de kapmış işin nihayeti… 

Münafığın huyu, işi gücü hülle,

Yalanlar söyler, konuşurken Resulle.

Kabul edilmeseydi her sözlü beyan, 

Sualler sorulsaydı onu zorlayan, 

Münafığın fikri olur idi ayan… 

Uyarıldı peygamber hafif bir dille: 

“Hemencecik, niçin izin verdin ille!”', 'Peygamberler yüce Allah’a en yakın, Onlar tertemiz; çamur atmaktan sakın! Her hâlükârda, hep edebini takın!.. Günahtan uzaktır onlar iyi bel...', ARRAY['Türk Edebiyatı','Şiir','Selim İç']::text[], 8.5, '{"poet":"Selim İç","poet_slug":"selim-i-c","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tevbe-43-peygamberimize-tatli-uyari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hârâbât', 'h-r-b-t-furkan-kar-u7g58', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gün olur uğrarsın hârâbâtıma

zevkten bir gâm deviririz câmlarda

huşu ile yatarız zindanlarda

dilber gönlüm kesbettin bakışınla 

 Ah, figan rüzgarı vurdu başıma

dudağınla ağu kattın aşıma

gönlüme saplandı deli firkatın 

habs-i nefesteyim ciğerimde sen

sevdamı raks ettirdin sigaranla

sâki yaşımı damlattı câmlara

bir rüzgar gibi yaktın sen cismimi

ağlarım ben şimdi hârâbâtımda', 'gün olur uğrarsın hârâbâtıma zevkten bir gâm deviririz câmlarda huşu ile yatarız zindanlarda dilber gönlüm kesbettin bakışınla   Ah, figan r...', ARRAY['Türk Edebiyatı','Şiir','Furkan Kar']::text[], 8.5, '{"poet":"Furkan Kar","poet_slug":"furkan-kar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/harabat-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Kalbindeki İyiliği Başkasında Arama', 'kendi-kalbindeki-i-yiligi-baskasinda-arama-livaneli-r3kzp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ŞİİR YAZARİ:@LİVANELİ_0853 KALEMİNDEN✒

Kendi Kalbindeki İyiliği Başkasında Arama

​İnsan bazen bir başkasında arıyor
kendi içinde duran şeyi
Sanki sende hiç yokmuş gibi
sanki bir tek onda varmış gibi
​Halbuki senin içinde de var
Öyle çok uzakta değil
öyle çok zor da değil
Kendi halinde duruyor orada
​Birine selam verince
birinin halini hatırını sorunca
içinden geçen o düz şeyi yapınca
görüyorsun zaten
​Başkasının elindekine bakıp
keşke bende de olsa diyorsun ya
çoğu zaman sende de var o
Sadece üstü biraz örtülmüş
​Kendi kalbindeki iyiliği başkasında arama
o zaten hep seninle
​Bazen yoruluyorsun
bazen kırılıyorsun
için daralıyor
sanki hiç kalmamış gibi geliyor
​Ama bir durup bakınca
o temiz yer hâlâ orada
Kimsenin bozamadığı
sana ait bir köşe
​Büyük laflara gerek yok
büyük işlere de
Bir tas su vermek gibi
kötü söz söylememek gibi
​Kimse görmese de olur
kimse alkışlamasa da olur
Sen kendi içini bil yeter
için rahat olsun yeter
​Kendi kalbindeki iyiliği başkasında arama
senin kalbinde duruyor o
​Birinin gözünde aradığın ışık
belki de kendi gözünde var
Birinin sözünde aradığın sıcaklık
belki de kendi sesinde
​Başkasından bekleyince
çoğu zaman gelmiyor
Gelince de tam istediğin gibi olmuyor
İnsan en çok kendini anlıyor
​Kendi kendine yetmek
kötü bir şey değil
Kendi ışığını yakmak
kimseye zarar vermez
​Birini değiştirmeye uğraşma
sen kendi yerinde dur
İçindeki o sakin hali
korumaya çalış yeter
​Kendi kalbindeki iyiliği başkasında arama
başkasında değil sende
​Gün gelir akşam olur
gün gelir sabah olur
İnsan her gün yeniden başlıyor
her gün biraz daha öğreniyor
​Dışarıda arayıp bulamadığın
o sade şey var ya
evinin içinde gibi
kendi içinde
​Ne çok büyüt ne çok küçült
olduğu gibi kabul et
İçindeki o iyi niyeti
elinden bırakma
​Her şey geçiyor
herkes bir yerlere gidiyor
İçinde kalan o temiz şey
seninle kalıyor
​Kendi kalbindeki iyiliği başkasında arama
o zaten hep senin içinde duruyor.

04.07.2023✒️
Saat:17.19

İzinsiz almayın paylaşmayın şiirlerimin telif hakları bulunmaktadır⛔', 'ŞİİR YAZARİ:@LİVANELİ_0853 KALEMİNDEN✒ Kendi Kalbindeki İyiliği Başkasında Arama ​İnsan bazen bir başkasında arıyor kendi içinde duran şeyi ...', ARRAY['Türk Edebiyatı','Şiir','Livaneli']::text[], 8.5, '{"poet":"Livaneli","poet_slug":"livaneli","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/kendi-kalbindeki-iyiligi-baskasinda-arama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şifâ', 'sif-kara-cocuk-3-rnnpy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İplik iplik yağar yağmur,

Bir damla da düşer mi semada?

Gönül gözüyle baksan hümaya,

Sebep mi aranır başka şifaya?

​O hâlde sebep nedir telaşaya,

Bu niyaz ulaşmaz mı arş-ı âlâya,

Göz yaşın döksen de toprağa,

Sebep bulunmaz mı çorak toprağa..

​Gönül susmuş, boyun bükmüş rızâya,

Düşen her yaş nefes olmuş duâya.

Yürek sessiz yüzün dönmüş semâya,

Çorak toprak döner elbet şifâya.', 'İplik iplik yağar yağmur, Bir damla da düşer mi semada? Gönül gözüyle baksan hümaya, Sebep mi aranır başka şifaya? ​O hâlde sebep nedir tela...', ARRAY['Türk Edebiyatı','Şiir','Kara Çocuk 3']::text[], 8.5, '{"poet":"Kara Çocuk 3","poet_slug":"kara-cocuk-3","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sifa-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fîl Ağlar Bana', 'f-l-aglar-bana-mehmet-i-slami-az1wi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya RABBİM görürsün bedbaht halimi 

Âşkın da musaddık kul ağlar bana

Derimi yüzerek kesti elimi

Duyunca köy belde il ağlar bana

Secde et emriyle secde de kalan

İLMÜ LEDÜNNİDE ummana dalan

Biçare hâlime muttali olan

Mazlumlar yetimler dul ağlar bana

İttiba etmeyen mucidi yalan 

Kütükken hicrandan sararıp solan

Kudret kaleminin çizdiği plân

Kaza edilirken yol ağlar bana

Kâbus oldu hayâllerim düşlerim

Sıfırlandı ağzımdaki dişlerim

Didelerden akan kanlı yaşlarım

Coşup çağlar iken sel ağlar bana 

Ayı çün ormanı dolaşamayan

İslâm düşmanına bulaşamayan

Gidip de hedefe ulaşamayan

Ayaklarla kollar yol ağlar bana

Kâfirlerin attığı taş değmeyen

Ehl-i batıl madde perest sevmeyen

Hakk’tan gayrısına boyun eğmeyen

Mekke ye girmeyen fil ağlar bana

Âşık isem ahvâlimi hâlimi

Arz ederim, Hakk’ı diyen dilimi

Kesseler de RABB’ e arzuhâlimi

Arzettiğim zaman çöl ağlar bana

Demiştik ki Hakkın safına girek

Ehl-i hakikati bire bir görek

Uzattım gardaşım tutsun diyerek

Tutulmayan temiz el ağlar bana

İSLÂMİ Rahmana doğru giderken

Kurtuluş, afiyet İSLÂM’ da derken 

Dikene sitemle feryât ederken

Bülbülü inleten gül ağlar bana', 'Ya RABBİM görürsün bedbaht halimi  Âşkın da musaddık kul ağlar bana Derimi yüzerek kesti elimi Duyunca köy belde il ağlar bana Secde et emri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İslami']::text[], 8.5, '{"poet":"Mehmet İslami","poet_slug":"mehmet-i-slami","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/fil-aglar-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim kalbime mühürlemediysen çıkar aklımdan...', 'rabbim-kalbime-muhurlemediysen-cikar-aklimdan-gokhan-gun-x18ym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rabbim kalbime mühürlemediysen çıkar aklımdan...', 'Rabbim kalbime mühürlemediysen çıkar aklımdan......', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gün']::text[], 8.5, '{"poet":"Gökhan Gün","poet_slug":"gokhan-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/rabbim-kalbime-muhurlemediysen-cikar-aklimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Mevsimi', 'sevda-mevsimi-ekrem-olgun-whumn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEVDA MEVSİMİ

Ben seni bir mevsime benzetmedim hiç,
Çünkü mevsimler geçerdi,
Sen geçmedin.
Bir sonbaharın hüznüyle girdin ömrüme,
Ve ben,
İlk defa dökülen yaprakların değil,
Dalında kalamayan bir kalbin
Acısını öğrendim.

Oysa ne güzel başlamıştı her şey…
Gözlerin, henüz keşfedilmemiş bir bahardı,
Gülüşün, kışın ortasında açan
İmkânsız bir çiçek.
Ben senin bir bakışında
Ömrümün bütün iklimlerini unuttum.
Meğer insan,
Bir çift gözde de mevsimsiz kalabilirmiş.

Sonra sen gittin…
Ne takvimler değişti içimde,
Ne de güneş eskisi gibi doğdu.
Bir haziran sabahında üşümeyi,
Bir temmuz gecesinde titremeyi
Senin yokluğunda öğrendim.
Anladım ki,
İnsanın üşümesi için kış gerekmezmiş;
Bazen birinin gitmesi,
Bütün güneşleri söndürmeye yetermiş.

Şimdi hangi bahar kapımı çalsa
İçeri almıyorum.
Çünkü bazı çiçekler
Toprağa değil, hatıralara kök salarmış.
Ve bazı sevdalar,
Ne yaşanırken tamamlanır
Ne de bittikten sonra ölürmüş.
İnsan bazen birini kaybetmezmiş,
Onunla birlikte
Bir daha yaşayamayacağı bütün ihtimalleri
Toprağa verirmiş.

Bilirsin…
Her mevsimin bir dönüşü vardır.
Kışın ardından bahar,
Gecenin ardından sabah gelir.
Ama senin ardından
Hiçbir şey gelmedi.
Sanki zaman,
Gittiğin günün eşiğinde diz çöktü;
Ve bütün saatler
Senin dönmeyeceğin bir vakti gösterdi.

Şimdi soruyorlar bana:
"Hangi mevsimi seversin?" diye.
Ne baharı söyleyebiliyorum,
Ne yazı, ne de sonbaharı…
Çünkü ben mevsimleri
Takvimlerden değil,
Bir zamanlar ellerimi ısıtan
O ellerin yokluğundan tanıyorum.

Ve artık biliyorum sevgilim,
Sevda mevsimi diye bir şey yokmuş.
Sevda, insanın içinde başlayan
Ve bazen bir ömür bitmeyen
En uzun mevsimmiş.

Sen benim baharım değildin…
Ben seninle bütün mevsimleri sevdim.
Sen gidince anladım;
Meğer ben bir mevsimi değil,
Ömrümün bir daha gelmeyecek
İklimini kaybetmişim.

EkOL', 'SEVDA MEVSİMİ Ben seni bir mevsime benzetmedim hiç, Çünkü mevsimler geçerdi, Sen geçmedin. Bir sonbaharın hüznüyle girdin ömrüme, Ve ben, İl...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sevda-mevsimi-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi geldin sandım kötü iz bıraktın , kötü gittin sandım iyi iz bıraktın be Börte', 'i-yi-geldin-sandim-kotu-iz-biraktin-kotu-gittin-sandim-iyi-iz-biraktin-be-borte-gokhan-gun-7fvo7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İyi geldin sandım kötü iz bıraktın , kötü gittin sandım iyi iz bıraktın be Börte', 'İyi geldin sandım kötü iz bıraktın , kötü gittin sandım iyi iz bıraktın be Börte...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gün']::text[], 8.5, '{"poet":"Gökhan Gün","poet_slug":"gokhan-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/iyi-geldin-sandim-kotu-iz-biraktin-kotu-gittin-sandim-iyi-iz-biraktin-be-borte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçliğe Geliş', 'hiclige-gelis-haydar-guven-gciul', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte ben geldim!

Omzumda paralanmış nakışlı heybemde küflenmiş keçi peyniri

Ve birkaç sana yazılamamış nahoş dizelerle...

Yıldızlardan başka oyuncağı olmayan çocuk

Büyüdü yaşanası olamayan anilarla

Korkmaz oldu bağırtısından kadınların ve

Yeyyare gürültülerinin.

Ayağında tozlara bulanmış nasırlı bir iskarpin,

Gömleğinde ufalanmış hilal düğmelerin parıltısıyla...

Kimse görmesin diye

Korkak yüzünü rüzgârın çamuruyla kapatan

Korkudan

O ben,

Ben geldim işte.

Doğduğum evin avlusu hıçkırıyor yüzüme,

Kulaklarımda bu hâllerimle geldiğim sen...

Kaybolan sesinin su gibi icime aktigini

Bir görsen!

Gözlerime batıyor olmayışın.

 Bu hiçliği bile bile,

Heybemde ufalanmış keçi peyniriyle

 Ben geldim işte.', 'İşte ben geldim! Omzumda paralanmış nakışlı heybemde küflenmiş keçi peyniri Ve birkaç sana yazılamamış nahoş dizelerle... Yıldızlardan başka...', ARRAY['Türk Edebiyatı','Şiir','Haydar Güven']::text[], 8.5, '{"poet":"Haydar Güven","poet_slug":"haydar-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hiclige-gelis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak Aldı', 'toprak-aldi-hakan-dagli-2-hs0fr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprak aldı seni benden,

Gözüm ayrılmıyor yerden.

Bir ömür eksildi ömrümden,

Adın düşmüyor dilimden.

Her gece göğe bakıyorum,

Yıldızlarda seni arıyorum.

Bir dua gibi adını anıp,

Yokluğuna sarılıp uyuyorum.

Bırak adımız göklerde yankılansın,

Melekler bile sevdamızı kıskansın.

Cennetin bütün gülleri sana açılsın,

Yıldızlar aşkımızı masal diye anlatsın.

Bir gün kavuşursak göğün katında,

Melekler şahit olsun aşkımıza.

Cennet beklemesin beni boşuna,

Benim cennetim sensin, senin yanında.

Gel gör ki şimdi yoksun yanımda,

Sesin kaldı gecenin en tenhasında.

Ben hâlâ ilk günkü gibi severken,

hatıra sın artık kalbimin derinlerinde.

Varsın gökyüzü mavisini kaybetsin,

Bütün mevsimler bir kışa dönsün.

Senin olmadığın bir cennette,

Ne güller açsın ne bülbüller ötsün.', 'Toprak aldı seni benden, Gözüm ayrılmıyor yerden. Bir ömür eksildi ömrümden, Adın düşmüyor dilimden. Her gece göğe bakıyorum, Yıldızlarda se...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dağlı 2']::text[], 8.5, '{"poet":"Hakan Dağlı 2","poet_slug":"hakan-dagli-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/toprak-aldi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyse', 'neyse-ahmet-coskun-z5q8q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neyse

Okunmaz alnımız yazısı sende

Nasılda olmuşuz beyhude bende

Ömrü çürüttük ya senle erkende

Sana söyleyecek sözüm var neyse

Uzaktan bakınca görünmez astar

Her sözün ucuna bağlama mastar

Ne çokmuş bak kefenime makastar

Söylenecek sözüm herkese neyse

Gönlümüzde kavurduk her tasayı

Çiğnendik biz çiğnemedik yasayı

Musa değildim ya vursam asayı

Boğulduk biz derin sularda neyse

Gönül hoşluğumuz kalple vicdana

Çok gelip geçti insanlar şu cihana

Gündüz boş versen de gece rüyana

Şer musallat masum bedene neyse

İncitmek yazmaz hiç kitabımızda

Sustuk dil bozmak yok adabımızda

Sandılar korkuluk var karşımızda

İstesek sözle gömerdik ya neyse

Coşkûnî', 'Neyse Okunmaz alnımız yazısı sende Nasılda olmuşuz beyhude bende Ömrü çürüttük ya senle erkende Sana söyleyecek sözüm var neyse Uzaktan bakı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Coşkun']::text[], 8.5, '{"poet":"Ahmet Coşkun","poet_slug":"ahmet-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neyse-110-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünün isyanı', 'gokyuzunun-isyani-umut-kaplan-rd7b5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün ağarmadan düşeriz şehrin bu sağır asfaltına

Yorgun adımlarımızla aşınır soğuk kaldırımlar

Tek bir yöne akan bu kalabalıkta

Herkes birbirinin kopyasıdır biraz

Ama sen, o boğucu uğultunun ortasında bile

Başka bir rüzgâra tutunursun inatla

Aynı duraklarda üşür,

Aynı tıklım tıklım vagonlara sıkışırız belki

Herkes cebinde aynı telaşı,

Yüzünde aynı yenilgiyi taşırken

Senin gözlerinde bambaşka bir gökyüzünün isyanı vardır

Bilirsin;

Aynı yoldan yürümek, aynı yazgıya boyun eğmek değildir

Bu kentin gri sabahlarında

Herkes ezberlenmiş bir hayatı tekrarlarken

Sen kendi türkünü mırıldanırsın içinden

Kimselere duyurmadan, usulca

Ve anlarsın ki asıl mesele yolu değiştirmek değilmiş

Aynı yolda yürürken bile

Her şeye inat kendi izini bırakabilmekmiş

O izden boy verir işte yarının hiç solmayacak güneşi

En zifiri sokakların ucunda bile

Bir şafak gizlidir mutlaka

Sen yürüdükçe dağılır bu şehrin üstündeki ölü toprağı

Çünkü umut,

En çok da diz çökmeden yürüyenlerin avucundadır.', 'Gün ağarmadan düşeriz şehrin bu sağır asfaltına Yorgun adımlarımızla aşınır soğuk kaldırımlar Tek bir yöne akan bu kalabalıkta Herkes birbir...', ARRAY['Türk Edebiyatı','Şiir','Umut Kaplan']::text[], 8.5, '{"poet":"Umut Kaplan","poet_slug":"umut-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gokyuzunun-isyani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyanın Hengamesinde', 'dunyanin-hengamesinde-mehmet-balikci-yd6sz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben Yunus değilim, yutar beni bu tufan,

Ben İbrahim değilim, yakar beni bu zaman.

Ne sığınacak bir liman ne tutunacak bir dal,

İçimde kopar fırtına, yüzümde derin bir hâl.

Benim de bir yüreğim var, yorulur acılardan,

Bir yanım umut bekler, bir yanım kanar yaradan.

Her ateşe yürünmez, her derde dayanılmaz,

İnsan bazen susar da içindeki ses dinmez.

Ne Yunus''un sabrıdır bende ne İbrahim''in imanı,

Taşıyamam omzumda dünyanın bütün kahrını.

Ten buruşmuş, ak düşmüş saça sakala,

Bir ömür tükenmiş, dönmüş acı bir masala.', 'Ben Yunus değilim, yutar beni bu tufan, Ben İbrahim değilim, yakar beni bu zaman. Ne sığınacak bir liman ne tutunacak bir dal, İçimde kopar ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Balıkçı']::text[], 8.5, '{"poet":"Mehmet Balıkçı","poet_slug":"mehmet-balikci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dunyanin-hengamesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ZAMANDAN KALAN FOTOĞRAF', 'zamandan-kalan-fotograf-huseyin-demirr-sessiz-ciglik-pps04', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‎
‎Bir gün, odanın o en sessiz köşesinde,
‎Akşamın rengi duvarlara sinerken usulca,
‎Eski bir albümün, bir çekmecenin kıyısında
‎Bir kâğıt parçasına takılacak gözlerin.
‎O an duracak zaman, duracak dünya,
‎İçinde bir şeyler kopacak derinden.
‎Bakacaksın o gözlere, o gülüşe, o yüzdeki sabra,
‎Hafızanın tozlu yollarından geçip gelecek geçmiş.
‎Seni seven, seni her halinle kabullenen,
‎Kırılsa da gidemeyen o mahzun siluet
‎Sessiz bir çığlık gibi dikilecek karşına.
‎Elindeki kâğıt ağırlaşacak, taş gibi çökecek avucuna.
‎Bir zamanlar ne kadar kolaydı kırmak,
‎"Nasıl olsa kalır" sanırken hoyratça savurmak...
‎Bir sözün zehrini, bir bakışın soğukluğunu,
‎Sanki hiç bitmeyecekmiş gibi harcanan o günleri,
‎Şimdi o donmuş karenin içinde izleyeceksiniz baş başa.
‎O fotoğraf konuşmayacak, ama her şeyi haykıracak.
‎Düğümlenecek boğazında söylenmemiş tüm özürler,
‎Zamanın en ağır, en acımasız adaleti başlayacak o an.
‎İçin sızlayacak, gözlerin dolacak ama ağlayamayacaksın;
‎Kendi kendine fısıldayacaksın o odanın karanlığında:
‎"Ben buna nasıl böyle davranmışım?
‎Nasıl kıymışım bu inceliğe, bu sessiz bekleyişe?"
‎Geri dönmek isteyeceksin, yollar kapalı;
‎Yalvarmak isteyeceksin, o ses çoktan uzaklarda...
‎Kâğıt üzerindeki bir gülüşün karşısında
‎Kendi vicdanının mahkemesinde sanık kalacaksın.
‎Ne sazın teli dindirecek bu sızıyı,
‎Ne de gecenin koyuluğu örtecek pişmanlığını.
‎Zaman seni tam da oradan vuracak işte:
‎Bir fotoğrafa bakıp,
‎Geçmişteki kendi gölgenle yüzleştiğin,
‎"Keşke"lerin altında sessizce ezildiğin o yerde.
‎Sadece bir kare kâğıt,
‎Ve senin içinde hiç dinmeyecek o derin, o dilsiz keder...
‎', '‎ ‎Bir gün, odanın o en sessiz köşesinde, ‎Akşamın rengi duvarlara sinerken usulca, ‎Eski bir albümün, bir çekmecenin kıyısında ‎Bir kâğıt p...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demirr Sessiz Çığlık']::text[], 8.5, '{"poet":"Hüseyin Demirr Sessiz Çığlık","poet_slug":"huseyin-demirr-sessiz-ciglik","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/zamandan-kalan-fotograf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasip Diye Beklerken', 'nasip-diye-beklerken-huseyin-demirr-sessiz-ciglik-907hi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '‎
‎​Sazın her teli bir sızı, bir kırgınlık çalıyor,
‎Geceler uzadıkça hasretin yüreğimi dağlıyor.
‎Şimdi senden çok uzakta, loş bir odanın içinde,
‎Adın yankılanıyor en sessiz, en ıssız nefeste.  
‎​Duvarlarda gölgeler uzar, saatler ağır aksar,
‎İçimdeki fırtınalar sessizce ruhumu sarar.
‎Bir bardak soğuk çay, yarım kalmış bir cümle,
‎Sensiz geçen her gün, bir başka hüzünlü düğümle.
‎​Seni heves değil, nasip bildim ben bu yolda,
‎Bir ömürlük yara gibi sakladım en derin solda.
‎Herkes giderken, zaman her şeyi silip süpürürken,
‎Ben seninle yanmayı seçtim, sessizce tükenirken.  
‎​Bir heves olsaydın, rüzgârla savrulup giderdin,
‎İlk kış ayazında, ilk fırtınada biterdin.
‎Ama sen içimde kök salan en derin sızısın,
‎Karanlık gecelerimde hiç batmayan yıldızsın.
‎​O yüzden ne acelem var ne vazgeçmeye niyetim,
‎Acıyla büyüdü sana olan en saf hürmetim.
‎Kavuşmak zor, yollar dikenli, gökyüzü kapalı,
‎Ama bu kalp senden başkasına ömür boyu dargın, kapalı.  
‎​Bir gün gelir mi bilmem o beklenen bahar sesi,
‎Belki de hep böyle kalır bu hasretin nefes nefesi.
‎Pencereme vuran yağmur senin adını fısıldar,
‎Uzaklaştıkça yollar, içimdeki özlem katlanır, büyür, daralır.  
‎​Ne acelem var artık, ne de bir umut dilenecek halim,
‎Seni nasip bildim ya, kırık dökük de olsa seninleyim.
‎Bir ömür beklemek düşerse payıma, boynum kıldan ince,
‎Adını anarak susarım, gece sessizliğe bürününce.  
‎​
‎', '‎ ‎​Sazın her teli bir sızı, bir kırgınlık çalıyor, ‎Geceler uzadıkça hasretin yüreğimi dağlıyor. ‎Şimdi senden çok uzakta, loş bir odanın i...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demirr Sessiz Çığlık']::text[], 8.5, '{"poet":"Hüseyin Demirr Sessiz Çığlık","poet_slug":"huseyin-demirr-sessiz-ciglik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/nasip-diye-beklerken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın Verdiği Umut', 'topragin-verdigi-umut-huseyin-demirr-sessiz-ciglik-7kztz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '‎Toprağın Verdiği Umut
‎​Bulutlar dağılır bir gün, güneş açar yeniden,
‎Hasretin gölgesi silinir, çıkar içimizden.
‎Yağmur olsan, gökten düşsen şu bekleyen toprağa,
‎Binlerce damla arasında yine bulur tutardım seni, asla bırakmam boşa.  
‎​Korkmam artık toprağın aldığından, bilirim,
‎O ki her bahar yeniden diriltir, yeşertir her şeyi.
‎Toprak aldığını geri vermiyor sanırdım eskiden,
‎Oysa saklıyormuş en güzel yarınları derininden.  
‎​Her damlanda bir umut, bir nefes, bir selam,
‎Kuruyan dallara can verir, açar en taze fidan.
‎Sen yağmur ol, ben toprak olayım, kucaklayayım seni,
‎Kayıp gitmesin ellerimden ömrümün en güzel teni.
‎​Gidenlerin ardında kalan o sessiz bekleyiş,
‎Bir sabah güneşle birlikte döner tatlı bir gülüşe.
‎Toprak saklar ama küsmek yok, her şey vaktini bekler,
‎En karanlık geceden sonra mutlaka doğar seher.
‎​Avuçlarımda tuttuğum o ilk yağmur tanesi,
‎Siler gözümdeki tüm yorgunluğu, tüm sisi.
‎Toprak aldığını geri vermiyor değil, aksine büyütür,
‎Sevgiyle ekilen her tohumu, bir gün mutlaka çiçeklendirir.  
‎​
‎', '‎Toprağın Verdiği Umut ‎​Bulutlar dağılır bir gün, güneş açar yeniden, ‎Hasretin gölgesi silinir, çıkar içimizden. ‎Yağmur olsan, gökten düş...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Demirr Sessiz Çığlık']::text[], 8.5, '{"poet":"Hüseyin Demirr Sessiz Çığlık","poet_slug":"huseyin-demirr-sessiz-ciglik","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/topragin-verdigi-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Surette Farklı Maskeler', 'ayni-surette-farkli-maskeler-mehmet-balikci-pb08e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Niye artık konuşmuyorsun?” diye sorarlar,

Birbirinin arkasından nice sözler savuranlar.

Yüz yüze gelince sevgi gösterip gülerler,

Sonra hiçbir şey olmamış gibi aynı sofraya oturanlar.

Kardeş kardeşi çekiştirir, elti görümceyi taşlar,

Aile denen çınarın dibinde nice hesaplar başlar.

Dilde birlik, özde çıkar; ne tuhaf bir hikâye,

Herkes birbirine dosttur, yoksa ortada menfaatler.

Ben sustum, çünkü sözünüz artık etmiyor tesir,

Sizin sevginiz çıkar kadar, dostluğunuz da esir.

Aynı sofrada oturun, sürdürün sahte düzeni,

Kan bağı akraba yapar, insanlık verir değeri.', '“Niye artık konuşmuyorsun?” diye sorarlar, Birbirinin arkasından nice sözler savuranlar. Yüz yüze gelince sevgi gösterip gülerler, Sonra hiç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Balıkçı']::text[], 8.5, '{"poet":"Mehmet Balıkçı","poet_slug":"mehmet-balikci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayni-surette-farkli-maskeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakışın Yeter', 'bir-bakisin-yeter-sairul-i-slam-yunus-kokan-a7nlz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçların dans eder rüzgârda, 

Gözlerin deniz.

Seninle hayat cennet, 

Cehennem olur sensiz.

Bir bakışın yeter, aklım gider,

Seninle kalır mı hiç keder?

Bir sen, bir ben, bir de güzel yarınlar,

Aşkımızla şenlensin tüm yıllar!

Bir ömür bitse sana doyamam,

Bin şarkı yazsam seni anlatamam,

Seninle dünyanın en bahtiyarı benim,

Alın yazımsın sevgilim sen benim.

Bir bakışın yeter, aklım gider,

Seninle kalır mı hiç keder?

Bir sen, bir ben, bir de güzel yarınlar,

Aşkımızla şenlensin tüm yıllar!', 'Saçların dans eder rüzgârda,  Gözlerin deniz. Seninle hayat cennet,  Cehennem olur sensiz. Bir bakışın yeter, aklım gider, Seninle kalır mı ...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-bakisin-yeter-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Dediğin Böyle Olacak', 'sevda-dedigin-boyle-olacak-sairul-i-slam-yunus-kokan-zwnti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçların rüzgârda savrulur,

Bu adam sana gönülden vurulur.

Oldum ben bu aşkın esiri,

Seninle güzel dünyanın her yeri!

Sevda dediğin böyle olacak!

Gönül dediğin böyle yanacak!

Deli gibi seviyorum seni,

Kalbime yazdım ismini.

Bakışına kandım, gülüşüne yandım,

Değişmem seninle bir anı dünyaya,

Gönlüm düştü bu sevdaya,

Daldım aşk denen deryaya.

Sevda dediğin böyle olacak!

Gönül dediğin böyle yanacak!

Deli gibi seviyorum seni,

Kalbime yazdım ismini.', 'Saçların rüzgârda savrulur, Bu adam sana gönülden vurulur. Oldum ben bu aşkın esiri, Seninle güzel dünyanın her yeri! Sevda dediğin böyle ol...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbime-yazdim-ismini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evde Kalmışlar Kulübü', 'evde-kalmislar-kulubu-mah-las-t53ye', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evlenmek isteyen de üzgün, istemeyen de.

Toplum otuzuna kadar ensende,

Sonrası zaten ikinci perde.

Sakın bir şeye sinirleneyim deme,

Evde kalman herkese bahane.

İmzayı atan nasihatta fevkalade,

Aracı ol desen biçare.

Anaların boynu bükük kaldı,

Allah sabır eyleye.', 'Evlenmek isteyen de üzgün, istemeyen de. Toplum otuzuna kadar ensende, Sonrası zaten ikinci perde. Sakın bir şeye sinirleneyim deme, Evde ka...', ARRAY['Türk Edebiyatı','Şiir','Mah Las']::text[], 8.5, '{"poet":"Mah Las","poet_slug":"mah-las","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/evde-kalmis-kizlar-kulubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben de Yandım', 'ben-de-yandim-remzi-ozmen-swot7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüzgarlara süvari deli bir taydım

Sesim yankılanırdı dağlarda.

Elim göklerde yıldızlar avucumda

Başım özgürlüğün doruğunda.

Bu yaylalar, bu vadiler şahidim 

Esaret nedir bilmeden yaşadım. 

Kartallarla yarışırdım, bulutlarla yoldaştım, 

Bir yelpaze misali açılıp kapanan yelelerim,

Nice kavgalarım vardı zaferlerle dönüşüm.

Bir yılkı atıydım özgürlüğün doruğunda 

İnletirdim yeri göğü,

Sesim yankılanırdı dağlarda.

Aygır gibi kavgacı, küheylan gibi serkeştim

Tozu dumana katardım kalkınca şaha

Sen çıkınca karşıma duruldum ehilleştim.

İşte yenildim, artık sen oldun dünyam 

Gönül dağı kadar yokuştur yolum

Bir çölü susuz geçmek gibidir sınavım

Fırtınalarında göz açabilmek,

Dalgalı bir denizi yüzüp geçmektir muradım

Madem ki sana yenildim 

Başımı alıp bir daha gitmiyorum uzaklara

Seviyor sevmiyor diye bakma papatya falına

İnanma, sevmiyor diyen yapraklara!..

Heyhat bir kördüğüme dolanmış gönlüm

Biliyorum çözmeye yetmeyecek ömrüm

Görünmüyor ufukta bana başka bir yol

Bu bir tercih midir yoksa kader mi

Gözlerin karanlık bir zindanmış

Düşünce anladım,

Ocağına kor olup giren kül olup çıkarmış!..

Bu yüzden ben de yandım!..', 'Rüzgarlara süvari deli bir taydım Sesim yankılanırdı dağlarda. Elim göklerde yıldızlar avucumda Başım özgürlüğün doruğunda. Bu yaylalar, bu ...', ARRAY['Türk Edebiyatı','Şiir','Remzi Özmen']::text[], 8.5, '{"poet":"Remzi Özmen","poet_slug":"remzi-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-de-yandim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
