INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkacağız Bu Çağı', 'yikacagiz-bu-cagi-mehmet-i-slami-06403', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yahudi ABD’nin cinsiyeti domuzdur 

Gangaster ataları insanlığın katili

Küfr milleti içinde asıl değil de yozdur

Gasp ettiniz kıtayı ateşledim fitili

Bak şu kancık domuzcuğa erkeğinin potağı

Bilmiyor ki cehennemin zümerası otağı

Akreplerle bir leş sen de yıkacağım bu çağı

Yıkacağım başınıza sökeceğim sitili

İSLÂMİ’ yim iki ayaklı itlere kemiği

Vermem, versem dört ayaklı tutar sıkar ümiği

Solucanlar bile ister bunlara çakmak iği

Süngüsü ibiğidir çilli Horozun batılı', 'Yahudi ABD’nin cinsiyeti domuzdur  Gangaster ataları insanlığın katili Küfr milleti içinde asıl değil de yozdur Gasp ettiniz kıtayı ateşledi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İslami']::text[], 8.5, '{"poet":"Mehmet İslami","poet_slug":"mehmet-i-slami","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yikacagiz-bu-cagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbime Yazdım İsmini', 'kalbime-yazdim-i-smini-yunus-yanki-4bh69', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçların rüzgârda savrulur,

Bu adam sana gönülden vurulur.

Oldum ben bu aşkın esiri,

