INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunma ilk şiir', 'dokunma-ilk-siir-gece-gozlu-jkc8o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dokunma!

Sadece iyi misin diye merak etmiştim seni

İyi gördüm seni

Bende olamadigin kadar iyi

Aslında gelmeyecektim

Her zaman yazdığım gibi yazacaktım sana

Cevap vermeyeceğini bile bile

Bekleyecektim geceler boyu delice

Ama yolum düşmüşken

Uğramak istedim gözlerine 

Beni unutmuşmusun diye merak etmiştim 

Unutmuşsun hemde hiç olmadığı kadar

Destanlar yazdığım gözlerinden bile silmissin adımı 

Varlığım o kadar acitiyormuydu canını 

Bilseydim bu kadar çok sevmezdim seni

Acıtacak kadar sarmazdim yokluğunu 

Affet farkında olmadan yaralamişim bendeki seni

Aldatmişim kendimi biz diyerek

Ama sende hak ver bana

İlk defa taşıyorum yokluğunu

Bu kadar çabuk alismami bekleme benden 

Hasret her saniye Bursa''da

Zamanla alışacağım yokluğuna

Neyse...

Yoksun kaç zamandır 

 Korkma niyetim kalmak değil 

Geçerken uğradım öğlesine 

Hem iyi oldu bu

Uzun zaman olmuştu gözlerinde ölmeyeli...

Gece gözlü', 'Dokunma! Sadece iyi misin diye merak etmiştim seni İyi gördüm seni Bende olamadigin kadar iyi Aslında gelmeyecektim Her zaman yazdığım gibi ...', ARRAY['Türk Edebiyatı','Şiir','Gece Gözlü']::text[], 8.5, '{"poet":"Gece Gözlü","poet_slug":"gece-gozlu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/dokunma-ilk-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahşere kalan', 'mahsere-kalan-orhan-dlr-xpsx1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gizli mühür gibi göğsümde duran sızısın

Dünya gözüyle görmek dokunmak haram yüzüne

Kadere boyun eğen iki garip yıldızı

Gökler bile kıyamaz indirmez yeryüzüne

Bizim bu fani ömre sığmayan sevdamızı

Melekler bir sır gibi defterine yazmıştır

Toprak saklar içimde kanayan yaramızı

Zaman bizi bu dertle hasretle sınamıştır

Kavuşmak mahşere dek sükûta gömülse de

Bilirim o kutsal gün her şey tamamlanacak

Bu yorgun gövdemizden ruhlar süzülse de

Aşkımız ahiretin nuruyla yıkanacak

O kapı açılınca o sır çözüldüğünde

Gözlerin gözlerimi ilk defa tanıyacak

Yarım kalan dünyada bu mahzun öykümüz de

Cennetin bahçesinde ebedi can bulacak

Orhan Diler', 'Bir gizli mühür gibi göğsümde duran sızısın Dünya gözüyle görmek dokunmak haram yüzüne Kadere boyun eğen iki garip yıldızı Gökler bile kıyam...', ARRAY['Türk Edebiyatı','Şiir','Orhan Dlr']::text[], 8.5, '{"poet":"Orhan Dlr","poet_slug":"orhan-dlr","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mahsere-kalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymuş Melekler Çağrımı Semadan', 'duymus-melekler-cagrimi-semadan-kasim-kobakci-0xmft', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duymuş melekler çağrımı semadan,

Dünden haber taşır şu serin sular.

*

Kâh mehtap olmuş umutla parlayan,

Selamlarla dolmuş ak pak odalar.

*

Kâh bir ahşap tekne olmuş, salınan,

Sitemsiz rızkını sırtından sunar.

*

Açıp mavi camı koklarız her an,

Oh deriz, yaşamak ne hoş bir bahar.

*

Kovmuş dünkü sisli havayı liman,

Gülümseyen begonvil hayat arar.

*

Her şeylerin bize güldüğü zaman,

Ahh benim belalı başım hep yanar.

*

Ahh gül yüzlü yoldaş, ah ey nazlı can,

Yeni bir aşkla, değiş tokuş başlar.

*

Ve yaşam aşkıyla coşup çağlayan,

O kıpır kıpır yürek durmaz atar.

*

Her gördüğü güzellikten alır kan,

Biraz daha can toplar ömre katar.

*

Biraz daha yaşamak için inan,

Ah baş tacım bu koyda umut parlar.

*

Mandalina dalında uyur cihan,

Bu yarımada bizi aşkta tutar.', 'Duymuş melekler çağrımı semadan, Dünden haber taşır şu serin sular. * Kâh mehtap olmuş umutla parlayan, Selamlarla dolmuş ak pak odalar. * K...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/duymus-melekler-cagrimi-semadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Bozkurt lazım', 'bize-bozkurt-lazim-yusuf-tuna-xpvyk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çakal her yerde var,

Bize Bozkurt lazım.

Yoksa ar olur ar,

Bize Bozkurt lazım.

Çakal sizin olsun,

İsteyenler alsın.

Bozkurt olan gelsin,

Bize Bozkurt lazım.

Bizlere olur kut,

Ak dağlar olur yurt.

Asena dişi kurt,

Bize Bozkurt lazım.

Gelirsen gel direk,

Gel vuslata erek.

Bozkurda kurt gerek,

Bize Bozkurt lazım.

Yusuf onunla baş,

Taş gibi olur taş.

Kurduma arkadaş,

Bize Bozkurt lazım.', 'Çakal her yerde var, Bize Bozkurt lazım. Yoksa ar olur ar, Bize Bozkurt lazım. Çakal sizin olsun, İsteyenler alsın. Bozkurt olan gelsin, Biz...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Tuna']::text[], 8.5, '{"poet":"Yusuf Tuna","poet_slug":"yusuf-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bize-bozkurt-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasımda çık gel', 'kasimda-cik-gel-yuksel-demir-gj86s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Takvimler Aralıkta bağlanır, Hikayeler Eylülde.

Bence bir sürpriz yap bu yıl,

Kasımda çık gel örneğin, güzel olur,

Kırgın bir gelincik gibi gel.

İkimiz de yorgunuz biliyorsun,

Eylül kadar yükümüz yok yine de.

Sırtüstü uzanalım yan yana,

Gözlerimiz kapalı dinleyelim ama yağmuru,

Çılgın sağanaklar vursun yüzümüze.

Yeni hikayeleri ilk ondan öğreniriz,

Belki bizi de katar birine hani, kim bilir...

Ah keşke...ah yine...aşk mı olsa...', 'Takvimler Aralıkta bağlanır, Hikayeler Eylülde. Bence bir sürpriz yap bu yıl, Kasımda çık gel örneğin, güzel olur, Kırgın bir gelincik gibi ...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Demir']::text[], 8.5, '{"poet":"Yüksel Demir","poet_slug":"yuksel-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kasimda-cik-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Unuttuğu Yerde', 'zamanin-unuttugu-yerde-ali-taskale-wreg1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senden sonra

bir fotoğrafın içinde yaşlandı zaman.

Çiçekler dalında kurudu,

pencereler gökyüzünü unuttu,

ve gözlerim

geçmişin kapısında nöbet tutan

iki eski saat oldu.

bir askerin yırtık postallarında...

Sen gittin.

Ama gitmek

her zaman eksilmek değilmiş;

bazen bir insan

yokluğuyla yerleşirmiş

başka bir insanın bütün odalarına.

Şimdi içimde

kimsenin dinlemediği bir ezgi var.

Nakaratı sen,

sessizliği ben.

Ne zaman gece

kendi karanlığını üzerime giydirse

bir yerinden sızıyor hatıran.

Ben seni

artık bir kavuşmanın ihtimaliyle değil,

geçmişin bile silemediği

o tuhaf varoluşunla seviyorum.

Çünkü bazı insanlar

hayattan çıkınca bitmez.

Bir ömrün içinde

ömür olmaya devam ederler...

Ali TAŞKALE | İstanbul

Mayıs 2017', 'Senden sonra bir fotoğrafın içinde yaşlandı zaman. Çiçekler dalında kurudu, pencereler gökyüzünü unuttu, ve gözlerim geçmişin kapısında nöbe...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkale']::text[], 8.5, '{"poet":"Ali Taşkale","poet_slug":"ali-taskale","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zamanin-unuttugu-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya İçinde Rüya', 'ruya-i-cinde-ruya-sevki-ciftci-x3tg7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüya İçinde Rüya

​Bu nasıl iştir bende şaşıyorum,

Rüya içinde rüya yaşıyorum.

Kalbimde hatıraları taşıyorum,

Rüya içinde rüya yaşıyorum.

​Tabuta koydular sağken canımı,

Görenler az sandı san ki şanımı.

Kalabalık sardı dört bir yanımı,

Rüya içinde rüya yaşıyorum.

​Aşağı yoldan akıp geldi ahali,

Şaştım kaldım gördüm bu acip hali.

Uyanıp soramam gayrı o sâli,

Rüya içinde rüya yaşıyorum.

​İnsanlar geçiyor akan sel gibi,

Dağılmış saçlarım esen yel gibi,

Ömürler tez biter solan gül gibi,

Rüya içinde rüya yaşıyorum.

​Şevki’yim fevç fevç sardı hep bu hayat,

Bir sır kalır mı ki geriye kat kat,

Bölündü uykum da kalmadı tat,

Rüya içinde rüya yaşıyorum.

Şevki Çiftçi', 'Rüya İçinde Rüya ​Bu nasıl iştir bende şaşıyorum, Rüya içinde rüya yaşıyorum. Kalbimde hatıraları taşıyorum, Rüya içinde rüya yaşıyorum. ​Ta...', ARRAY['Türk Edebiyatı','Şiir','Şevki Çiftçi']::text[], 8.5, '{"poet":"Şevki Çiftçi","poet_slug":"sevki-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ruya-icinde-ruya-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Börteçine romanından bir kesit', 'bortecine-romanindan-bir-kesit-gokhan-gun-5zqo6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Börteçine, henüz kendi evliliğinin nasıl bir yola gireceğini bilmiyordu. Fakat artık yalnızca kaderin kendisine sunduklarını beklemek istemiyordu. Kendi hayatının içinde bir insan olarak var olmak, düşüncelerini paylaşmak ve hayallerine yeniden yer açmak istiyordu.

Belki üniversite hayali geçmişte kalmıştı. Belki gençliğinde kurduğu planların hepsi gerçekleşmeyecekti. Ama öğrenmekten, kendisini geliştirmekten, hayata karışmaktan vazgeçmek zorunda değildi.

Bir gün çocukları olursa onlara yalnızca iyi bir insan olmayı değil, kendi seslerini duymayı da öğretmek istiyordu.

Çünkü insanın hayatında başkalarının sözleri önemli olabilirdi; fakat insan kendi iç sesini tamamen kaybettiğinde, bir gün aynaya baktığında kendisine yabancılaşabilirdi.

Başını pencereden çevirdi.

Yüzünde bu kez başka bir ifade vardı.Bu, geçmişe özlem duyan bir genç kızın hüznünden farklıydı. İçinde hâlâ sorular vardı ama o sorulardan kaçmamaya karar vermişti.

Belki gerçek mutluluk, insanın her şeyi baştan doğru yapmasında değildi.

Belki mutluluk, yanlışlarını ve eksiklerini fark ettikten sonra kendisine yeni bir yol açabilmesindeydi.

Henüz yolun başındaydı.

Önünde yaşayacağı yıllar, karşılaşacağı sınavlar ve vereceği yeni kararlar vardı.

Ve günün birinde geriye dönüp baktığında, hayatının en önemli sorusunun şu olduğunu anlayacaktı:

“Ben başkalarının istediği insan olmak için mi yaşadım, yoksa kendi içimdeki Börteçine’yi de yaşatabildim mi?”

Bu sorunun cevabını zaman verecekti.Ama zamanın Börteçine’den alacağı çok şey, ona öğreteceği daha da fazla şey vardı.Evlilik günleri geçiyor hayat ilerliyordu:

Hayat, Börteçine’ye hiç beklemediği kapılar açmaya devam ediyordu.

Gençliğinde kurduğu hayaller, ailesinin beklentileri, yarım kalan sevdası ve yeni hayatına alışma çabası derken zaman kendi yolunu çizmişti. Artık yalnızca bir evin gelini, bir adamın eşi değildi. İçinde büyüyen yeni bir canla birlikte bambaşka bir yolculuğa hazırlanıyordu.

Anne olacaktı.

Bu düşünce, kalbinin derinliklerinde daha önce hiç tanımadığı bir heyecan uyandırıyordu. Bazen karnına dokunuyor, henüz yüzünü görmediği bebeğiyle sessizce konuşuyordu.

“Sen gelince her şey değişecek mi acaba?” diye fısıldıyordu.

Belki değişecekti. Belki de değişmesi gereken şey, hayatın kendisinden çok Börteçine’nin hayata bakışıydı. Aylar geçtikçe bebeğini kucağına alacağı gün yaklaşıyordu. Evde hazırlıklar başladı. Aile büyükleri tavsiyelerde bulunuyor, herkes doğacak çocuğun heyecanını yaşıyordu. Börteçine de bu heyecanın içindeydi. Fakat onun heyecanına biraz da bilinmezliğin korkusu karışıyordu.

İyi bir anne olabilecek miydi?

Çocuğuna sevgisini nasıl gösterecekti? Onu nasıl büyütecek, nasıl koruyacak, nasıl bir gelecek hazırlayacaktı?

Kendisinin çocukluk yıllarında kurduğu hayalleri düşündü. Bir zamanlar dünyayı tanımak, okumak, öğrenmek ve kendi yolunu çizmek istemişti. Şimdi ise kucağına alacağı çocuğun geleceğini düşünüyordu.

İnsan anne olmaya hazırlanırken, kendi çocukluğuna da yeniden dönüyordu belki.

Kendi annesinden öğrendiklerini, ailesinden gördüklerini, hayatın kendisine öğrettiklerini hatırlıyordu. Bir annenin sevgisinin yalnızca güzel sözlerden ibaret olmadığını biliyordu. Sevgi bazen uykusuz bir gece, bazen sabırla beklenen bir hastalık, bazen de çocuğunun mutluluğu için yapılan sessiz bir fedakârlıktı.

Börteçine, henüz doğmamış çocuğu için bütün bunları yapmaya hazır olduğunu hissediyordu.

Dünyaya gelen küçük adam

Beklenen gün geldiğinde, Börteçine’nin hayatı bir anda değişti.

Doğumun ardından duyduğu ilk haber, bir erkek çocuğu dünyaya getirdiğiydi.

Bir oğlu olmuştu.

O an, zaman sanki bir süreliğine durmuştu. Bütün korkuları, endişeleri ve cevabını aradığı sorular uzaklaştı. Gözleri bebeğini arıyordu. Onu ilk kez kucağına aldığında küçücük yüzüne baktı; parmaklarını, gözlerini, başını okşadı.İçinden tarifsiz bir duygu yükseldi.

Bu küçücük insan, artık onun dünyasının en kıymetli parçasıydı.

Börteçine’nin gözlerinden yaşlar süzüldü.

Bunlar ne geçmişin hüznüydü ne de geleceğin korkusu. Bunlar, ilk kez anne olmanın insana yaşattığı o derin duygunun gözyaşlarıydı.

“Hoş geldin oğlum,” diye fısıldadı.

“Seninle birlikte ben de yeniden doğdum sanki.”

Bebeğinin küçücük elini tuttu. O minicik parmakların kendi parmağına sarılışını hissettiğinde, hayatın bütün karmaşasına rağmen yaşamaya değer ne kadar çok şey olduğunu düşündü.

Oğlunun yüzüne baktı.Henüz hiçbir şey bilmiyordu. Dünyanın güzelliklerinden, insanların acılarından, hayatın zorluklarından habersizdi. Onun için dünya, annesinin sıcaklığı ve kucağının güveninden ibaretti.

Börteçine ise o küçücük bedende kocaman bir gelecek görüyordu. Belki bir gün okula gidecek, arkadaşlar edinecek, hayaller kuracaktı. Belki büyüdüğünde kendi kararlarını verecek, kendi yolunu seçecekti.

Börteçine''nin kalbinden bir dilek geçti:

“Allah''ım, oğlumu iyi bir insan olarak büyütmeyi nasip et. Onun kalbini merhametle, aklını bilgiyle, yolunu güzelliklerle doldur. Benim yaşayamadığım hayalleri yaşasın ama en önemlisi, kendi hayallerini kurmaktan korkmasın.”

İşte o an, anneliğin yalnızca bir çocuğu dünyaya getirmek olmadığını hissetti. Annelik, bir insanın geleceğine emek vermek, ona güvenli bir dünya hazırlamak ve zamanı geldiğinde kendi kanatlarıyla uçmasına izin verebilmekti. Oğlunun doğumuyla birlikte evin içindeki her şey başka bir anlam kazandı. Geceler bölündü. Uykular kısaldı. Günler, bebeğin ihtiyaçlarına göre şekillenmeye başladı. Börteçine bazen saatlerce oğlunun başında bekliyor, uyurken yüzünü seyrediyordu. Onun küçücük bir hareketi bile kendisini heyecanlandırmaya yetiyordu.

İlk ağlaması, ilk gülümsemesi, gözlerini annesine çevirdiği o anlar…

Her biri hafızasında ayrı bir yere yerleşiyordu.

Yorgun düştüğü zamanlar da oluyordu elbette. Bazen gecenin bir yarısında oğlunu kucağında sallarken gözleri kapanıyor, ama bebeğinin en ufak sesinde yeniden uyanıyordu.

Yine de şikâyet etmiyordu.

Çünkü kucağındaki çocuk, hayatına yepyeni bir anlam katmıştı. Fakat annelik, insanın kendi içindeki bütün soruları ortadan kaldırmıyordu. Aksine, bazı soruları daha da derinleştiriyordu.

Börteçine artık yalnızca kendisini düşünmüyordu. Eşini, evini, oğlunu ve gelecekte onları bekleyen hayatı düşünüyordu.

Bir annenin kalbi, çocuğunun geleceği söz konusu olduğunda daha geniş bir dünya kuruyordu. Börteçine de oğlunun güzel bir eğitim almasını, kendine güvenmesini, sevildiğini bilerek büyümesini istiyordu.

Onun, hayatında karşısına çıkacak seçimleri korkmadan yapabilmesini arzuluyordu.

Bir gün oğlu büyüyüp kendisine, “Anne, ben ne olmak istiyorsam onu seçebilir miyim?” diye sorsa, ona ne cevap vereceğini düşündü.

Hiç tereddüt etmeden, “Elbette oğlum,” demek istiyordu. Sonra kendi gençliğini hatırladı.', 'Börteçine, henüz kendi evliliğinin nasıl bir yola gireceğini bilmiyordu. Fakat artık yalnızca kaderin kendisine sunduklarını beklemek istemi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gün']::text[], 8.5, '{"poet":"Gökhan Gün","poet_slug":"gokhan-gun","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/bortecine-romanindan-bir-kesit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mazinin Ezgisinde', 'mazinin-ezgisinde-ali-taskale-3ttx8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden geriye içimde,

yarım bırakılmış bir düş kadar mahzun,

solgun bir fotoğrafın suskunluğunda

zamanı bekleyen bir çiçek kaldı.

Bir pencerenin buğusunda

gökyüzüne adını yazan gözlerim var;

her bakışta biraz daha eskiyen,

her özleyişte yeniden açan...

Olsun.

Ben yine seni,

kalbimin kimselere uğramayan kıyısında,

eski bir ezginin unutulmuş notasından,

mazinin küllenmiş sızısından seveceğim.

Çünkü bazı aşklar

zamanın hükmüne girmez;

bir ömrün içinden çekip gitseler de

ruhun en eski odasında

ışıklarını söndürmeden yaşarlar.

Ve ben,

her dem biraz daha geçmişe karışarak,

hasretini içimde çoğaltıp

seni sevmeye devam edeceğim...

Ali TAŞKALE | İstanbul

Temmuz 2018', 'Senden geriye içimde, yarım bırakılmış bir düş kadar mahzun, solgun bir fotoğrafın suskunluğunda zamanı bekleyen bir çiçek kaldı. Bir pencer...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkale']::text[], 8.5, '{"poet":"Ali Taşkale","poet_slug":"ali-taskale","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mazinin-ezgisinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '# BİR ADAMIN YÜREĞİNDE DİNLENMEK İSTİYORUM', 'bi-r-adamin-yuregi-nde-di-nlenmek-i-sti-yorum-yurekli-bir-kadin-ply5y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bir adamın yüreğinde dinlenmek istiyorum,
Ömrün bütün yorgunluğunu kapısında bırakıp,
Bir çift gözün içine sığınıp,
Dünyanın sesini susturmak istiyorum.

Öyle bir sevda olsun ki gelişin,
Ne vedası olsun ne de yarım kalmış cümlesi.
Ben artık ayrılıkların ezberini bozmak,
Bir adamın son durağı olmak istiyorum.

Bilmezsin kaç geceyi sabaha bağladım,
Kaç yıldızı gözyaşımla ıslattım.
Kimsenin omzuna başımı koyamadım,
Ben hep kendi yüreğimde ağladım.

Çoğu zaman sabah ezanı duyulurken
Bir dua bıraktım gecenin koynuna;
Allah''ım, dedim, bir gün olsun
Beni de birinin vazgeçilmezi yap.

Ben öyle bir kadın değilim ki
Bir sevdaya ömrümü koyup da eksileyim.
Seversem bahar olurum bir adamın ömründe,
Gidersem ardımda koca bir kış bırakırım.

Ama yoruldum be adam,
Hep kendi yarasına merhem olmaktan.
Bir yanım hâlâ sevmeye aç,
Bir yanım korkuyor yeniden kanamaktan.

Gel artık,
Ama öyle bir gel ki ardına bakma.
Kalbime bir kere dokunacaksan
Bırakma beni dokunduğun yerde.

Ben senden bir saray istemiyorum,
Bir ömürlük huzur sığsın yeter avuçlarına.
Fırtınalar kopsun dışarıda,
Ben başımı koyayım omzuna,
İlk defa korkmadan uyuyayım yanında.

Çünkü ben de bir kadınım,
Geceleri güçlü, sabahları mahzun…
Herkese karşı dimdik duran,
Bir tek sevdiğinin yanında susup
Gözleriyle anlatmak isteyen.

Ve bil ki,
Benim beklediğim yalnızca bir adam değil;
Yıllardır içimde üşüyen o kadına
Bir ömürlük bahar getirecek bir yürek.

**Ben bir adamın yüreğinde ev olmak istiyorum…
Bir ömürlük misafir değil.**

**YÜREKLİ BİR KADIN**', 'Ben bir adamın yüreğinde dinlenmek istiyorum, Ömrün bütün yorgunluğunu kapısında bırakıp, Bir çift gözün içine sığınıp, Dünyanın sesini sust...', ARRAY['Türk Edebiyatı','Şiir','Yürekli Bir Kadın']::text[], 8.5, '{"poet":"Yürekli Bir Kadın","poet_slug":"yurekli-bir-kadin","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-adamin-yureginde-dinlenmek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş Yetmişi Geçmiş.!', 'yas-yetmisi-gecmis-hikmet-guner-lkc2m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir baktım aynaya
Yaş yetmişi geçmiş
Yıllar sanki
Koşarcasına gelip de geçmiş
Doldu gözlerim
Geldi aklıma tek tek
Çocukluk, gençlik, yaşananlar
Olmuş yaş yetmiş
Bu dünyada
Nede çok şey ertelemişim
Her gün bugün değil yarın demişim
Yarın olmazsa öbür gün demişim
Dönüp de arkama baktığımda
Neler, neler yaşamadan geçmişim
Sanki varmış gibi daha çok yıllar
Akıp da giden kaybolan yıllar
Hepsini bir bir terk etmişim
Ne olur biraz yavaş geçin yıllar
Daha görecek güzel günlerimiz var
İçimde heveslerim
Söyleyecek sözlerim
Hayallerim, yaşayacaklarım var
Geçmiş gitmiş yıllar
Benden neler neler almış
Bana bugün neler kalmış
Aldı gençliğimi benden
Aldı Hayallerimi benden
Daha doyamadan hayata
Yaşayacaklarım vardı
Hayallerim vardı
Neydi acelen neydi böyle
Bıraksaydın da yaşasaydım ya
Çekip çekip de gittin öyle
Yaş yetmişi geçmiş
Yıllar sanki koşarcasına
Gelip de geçip gitmiş öyle…', 'Bir baktım aynaya Yaş yetmişi geçmiş Yıllar sanki Koşarcasına gelip de geçmiş Doldu gözlerim Geldi aklıma tek tek Çocukluk, gençlik, yaşanan...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Güner']::text[], 8.5, '{"poet":"Hikmet Güner","poet_slug":"hikmet-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yas-yetmisi-gecmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noel', 'noel-gamze-gul-bilici-djsm3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '​Noel arifesi hazırlık başlar erkenden,

Sokak boyu en renkli çam ağaçları doluyken.

Ailece huzurla akşam yemeğinde toplanırız,

Kar dışarıda lapa lapa yağarken.

​Yılın son günü heyecan ile geçerken,

Geri sayım başladı hemen.

Geçen yılı   düşündüm  aniden.', '​Noel arifesi hazırlık başlar erkenden, Sokak boyu en renkli çam ağaçları doluyken. Ailece huzurla akşam yemeğinde toplanırız, Kar dışarıda ...', ARRAY['Türk Edebiyatı','Şiir','Gamze Gül Bilici']::text[], 8.5, '{"poet":"Gamze Gül Bilici","poet_slug":"gamze-gul-bilici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/noel-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meri İle Zemheri', 'meri-i-le-zemheri-emrah-kilbas-0pa1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bakınca Uzaktan sana..,
Görünen bir kemik birde deri..
Nerdesin nasılsın Merak Etmem,
Hakkın varmı acep bende Meri..

Boluyuda gördük İstanbuluda..,
Üsküdarıda gördüm EyüpSultanıda,
Sıcağı, Yağmuru koy kenara Emi,,,,
Meri sen hep bana oldun Zemheri', 'Bakınca Uzaktan sana.., Görünen bir kemik birde deri.. Nerdesin nasılsın Merak Etmem, Hakkın varmı acep bende Meri.. Boluyuda gördük İstanbu...', ARRAY['Türk Edebiyatı','Şiir','Emrah Kılbaş']::text[], 8.5, '{"poet":"Emrah Kılbaş","poet_slug":"emrah-kilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/meri-ile-zemheri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Karalaması 2', 'bir-ask-karalamasi-2-saban-durmaz-2-00wte', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okudum yüzünde acılardan bir şiir

Vururdu dizeleri yüreğime yüreğime

Titrek bir kalp sanki avuçlarımda varlığın

Bolca taşikardi

Bolca travma

Senin gözlerin bir okyanus -belki Pasifik

Demir atardım bakire adalarına

Seni severdim maviliğinde suların

Gözyaşlarından parmaklarıma sızan ıslaklığın

Ne gerek var bunlara

Ne gerek var mektuplara

Gel acını alayım demek varken

Bir yaz akşamı serin odalarda?', 'Okudum yüzünde acılardan bir şiir Vururdu dizeleri yüreğime yüreğime Titrek bir kalp sanki avuçlarımda varlığın Bolca taşikardi Bolca travma...', ARRAY['Türk Edebiyatı','Şiir','Şaban Durmaz 2']::text[], 8.5, '{"poet":"Şaban Durmaz 2","poet_slug":"saban-durmaz-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-ask-karalamasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Diyemedik.', 'elveda-diyemedik-ozdemir-koca-ab9fq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bunca yolu araya koymakta neyin nesi,

Bir kez oturup köşeye iki laf diyemedik,

Kini kıskançlığı herkese duyurmak iyimi,

Ayrıldık bak yine de elveda diyemedik.

Kaşlarını çatmanın ne anlamı var bilmem,

İnsanlığı satmanın ne anlamı var bilmem,

Yaktın yıktın düşleri ne anlamı var bilmem,

Ayrıldık bak yine de elveda diyemedik.

Oysa ne hayaller kurduk mavi göklerde,

Bir bulut olacaktık yağacaktık ovalara,

Bir çiçeğin damarından konacaktık tacına,

Ayrıldık bak yine de elveda diyemedik.

Sen küskün bir Ay çiçeği olarak kaldın,

Ben bir kenger sakızı oldum ağızlara,

Bizim aşkımız öyle konuşuldu dillerde,

Ayrıldık bak yine de elveda diyemedik.

Oysa çöl kumlarından çoktu sevdamız,

Savrulduk oradan oraya mekan edinemedik,

Kuruduk çiçek açmadın dallarımızda,

Ayrıldık bak yine de elveda diyemedik.

Özdemir gönülde sürgün verdi durmadan,

Ne bahçe oldu ömrüm ne Gülşen ne bağban,

Söndü ışığım işte senle ayrıldığım zaman,

Ayrıldık bak yine de elveda diyemedik.', 'Bunca yolu araya koymakta neyin nesi, Bir kez oturup köşeye iki laf diyemedik, Kini kıskançlığı herkese duyurmak iyimi, Ayrıldık bak yine de...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Koca']::text[], 8.5, '{"poet":"Özdemir Koca","poet_slug":"ozdemir-koca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elveda-diyemedik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Örtüsü', 'kalbimin-ortusu-berdan-dogu-pejee', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Lisanımda bulunmaz heybetinin tabiri,

Gözlerim kıpkırmızı dalganla yüzleşir.

Geçer gözümden bir tarihin en acılı güzleri,

Gördüğüm sarp hülyalar endamınla düzleşir.

Lisanımda bulunmaz heybetinin tabiri.

Gölgende serinleyene denir mi hiç sayedar?

Senden olan değil, seninle olan payidar.

Hakikatin ırmağında allara boyandın,

Mehmedimin göğsünde kanlara boyandın.

Seninle gördük istikbalin müstesna aydınlığını,

Bize tebessüm ettin dalga dalga.

Hakikatin ırmağında allara boyandın.

Sabilerin elleriyle koştun kırlarda,

Can evimden arsız hicranı kovdun.

Osman''ın son nefesiyle dikildin toprağa,

Mustafam''dan kalan namusum oldun.

Sabilerin elleriyle koştun kırlarda.

Uğruna canana yükselene denir mi hiç sayedar?

Senden olan değil, seninle olan payidar

Sen dalgalanırsan, matemler devrilir yere

Sen dalgalanırsan, umudu tazelenir gariplerin

Sen dalgalanırsan, saadet yenilmez kedere

Sen dalgalanırsan, kalpleri ferahlar yetimlerin

Sen dalgalanırsan, matemler devrilir yere

Hilalinle parıldayana denir mi hiç sayedar

Senden olan değil, seninle olan payidar', 'Lisanımda bulunmaz heybetinin tabiri, Gözlerim kıpkırmızı dalganla yüzleşir. Geçer gözümden bir tarihin en acılı güzleri, Gördüğüm sarp hüly...', ARRAY['Türk Edebiyatı','Şiir','Berdan Doğu']::text[], 8.5, '{"poet":"Berdan Doğu","poet_slug":"berdan-dogu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kalbimin-ortusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Stalingrad Traktör Fabrikası', 'stalingrad-traktor-fabrikasi-alper-tunga-3-7ed4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yarın eski traktör fabrikasını geri alacağız,

Bir hafta önce, Ruslara teslim etmiştik

Tanrım...Bir hafta önce sakladığım viski!

Biliyordum, bu hurda yığınına döneceğimizi

Şimdi onların ele geçirdiği mühimmatlarla 

Heryer yıkılıp yok olana kadar,

Acımasız bir çocuk oyunu bizim savaşımız,

Stalingrad...Burası, görmeniz gereken son yeryüzü,

korkulu rüyalarımı unuttuğum bir toprak parçası

Yarın aynı fabrikaya üçüncü saldırışımız...

Az önce ayakları titreyen, bir asker siperden ayrıldı

Ay ışığı hiç bu kadar huzur veremezdi, belkide

Şimdi kar fırtınası var ve hâlâ sızlanan Bavyeralı

Burası bizim için son cehennem, son vicdan azabı

Up uzun coğrafyalar boyunca...bire on!

Bir Alman Birliğine, on Sovyet kalabalığı,

Bir panzere onlarca t-34, binlerce tanksavar...

Son imha ettiğim tank, bize aitti... İnanamazsın.

Kendi gemimizi yakarcasına, bunu kabul eder gibi

Donmuş nehirlerde kurşuna dizilen köylüler geliyor,

Bir kar fırtınasında Stalingrad...

hiçbir Alman general için yaşamak istemiyorum.

Yarın, traktör fabrikasına tekrar saldırıacağız,

Yarın, son haftadan kalan viskimle bulaşacağım', 'Yarın eski traktör fabrikasını geri alacağız, Bir hafta önce, Ruslara teslim etmiştik Tanrım...Bir hafta önce sakladığım viski! Biliyordum, ...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/stalingrad-traktor-fabrikasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfkem Bile Seni Özlüyor', 'ofkem-bile-seni-ozluyor-mustafa-alp-591a8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dün akşam adın geçti.

çaydanlığı ocaktan aldım.

bir şey söylememi beklediler.

bardakları doldurdum,

birini fazla doldurmuşum.

eskiden olsa anlatırdım.

nerede incindim,

hangi sözün ağır geldi.

sen cümlenin yarısında yorulurdun,

ben anlaşılmak için

aynı yerimden bir daha kırılırdım.

bir gece “başlama yine” dedin.

başlamadım.

sen uykunu aldın o gece.

ben söyleyeceklerimi

sabah ekmek almaya götürdüm.

fırıncı “başka?” diye sordu.

ne tuhaf,

insanın içi doluyken

bu kadar küçük bir soruya “yok” demesi.

sonra “uslandın” dediler.

ağzımdan şikayet çıkmıyordu.

bir adamın sesi kesilince

ahlakı düzelmiş sayılıyor.

ne terbiyeli bir cenaze.

sen de rahatladın.

“artık kavga etmiyoruz,” dedin.

masanın çatlağı örtünün altında kalmıştı.

örtüyü sen seçmiştin,

deseni güzeldi doğrusu.

benim de payım var.

kırıldığım her yerde seni suçlu buldum önce.

bir gün bir dostuma “uzatma” dedim.

adam sustu.

o akşam kendimi senin yerinde buldum.

onu arayacaktım.

“yarın,” dedim.

meğer insan başkasına borçluyken

ne kolay uyuyormuş.

kendi alacağına gelince

sabaha kadar hesap tutuyor.

sana bunu da anlatamadım.

hep haklı durduğum yerden

biraz çekilmem gerekecekti.

bunca yıl derdimi savundum.

kusurum üşümesin diye

üstünü de onunla örttüm.

ama o son akşam

ne haklıydım ne haksız.

karşında oturuyordum.

“bir şey söyle,” dedin.

söylesem yine sesime kızacaktın,

susunca yüzüme kızdın.

içimden bir öfke kalktı,

sana kadar gelemedi.

yıllarca kapına dayanmıştı,

bu defa ayakkabısını bile giymedi.

o gece mutfakta

bir kaşığı yerine koyamadım.

çekmeceyi açtım,

kapattım.

sen içeriden bir şey sordun.

duymamış gibi yaptım.

cevap verecek halim

sorundan çok önce gitmişti.

ahali hemen hükmünü verdi.

“affet de kurtul.”

sanki anahtar cebimde,

ben kapıyı keyfimden kilitli tutuyorum.

bir de “unut” dediler.

insan başkasının sırtındaki yükü

ne güzel yere bırakıyor.

ben seni cezalandırmak için susmadım.

ilk günler bir sözünü bekledim,

sonra kendi sözümü.

ikisi de gelmeyince

akşamları radyoyu açtım.

haberleri bile sonuna kadar dinledim.

biri cümlesini bitirsin istedim.

geçen gün aradın.

telefon uzun uzun çaldı.

açmadım.

buna zafer diyecek değilim.

o sesin karşısında yeniden küçülmekten

korktum.

sonra dostumu aradım,

hani sözünü kestiğim.

“o gün ne anlatacaktın?” dedim.

önce hatırlamadı.

ben bekledim.

bu defa acelem yoktu.

konuştu.

bir yerde sesi titredi.

çözüm bulmaya kalkmadım.

elimde soğuyan çayı sonuna kadar tuttum.

telefonu kapatınca ağladım.

sana söyleyemediğim ne varsa

birden dile gelmedi.

yalnız, “çok yoruldum,” dedim.

odada kimse itiraz etmedi.

✍️', 'dün akşam adın geçti. çaydanlığı ocaktan aldım. bir şey söylememi beklediler. bardakları doldurdum, birini fazla doldurmuşum. eskiden olsa a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alp']::text[], 8.5, '{"poet":"Mustafa Alp","poet_slug":"mustafa-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/ofkem-bile-seni-ozluyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalı Kuzu', 'kinali-kuzu-osman-yuksel-surdem-bwal4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pazardan alırlar kınalı kuzu 

Ben miyim  kurbanlık kuzu 

Verin elime bir kalıp buzu 

Yanan bağırım sönsün benim 

İçime attım tüm dertlerimi 

Açtılar bugün günah defterimi 

Mizana koymuşlar tüm sözlerimi 

Bir günaha ateşe attılar beni', 'Pazardan alırlar kınalı kuzu  Ben miyim  kurbanlık kuzu  Verin elime bir kalıp buzu  Yanan bağırım sönsün benim  İçime attım tüm dertlerimi ...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Sürdem']::text[], 8.5, '{"poet":"Osman Yüksel Sürdem","poet_slug":"osman-yuksel-surdem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kinali-kuzu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkinci Çay', 'i-kinci-cay-mustafa-alp-lse7t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seninle ilk oturduğumuz gün

çayımı bitirip kalkacaktım.

öyle alışmışım.

birinin vaktini almadan

kendi ömrümden çıkmaya.

“bir tane daha içer misin?” dedin.

garsona bakmadım hemen.

yüzüne baktım.

nezaketen mi söyledin,

gerçekten kalabilir miydim?

eskiden sevildiğini anlamak için

sesin değişsin diye beklerdim.

biraz kıskançlık, biraz kavga.

göğsüm sıkıştı mı “tamam,” derdim,

“bu büyük sevda.”

ne acayip hesapmış.

evde her akşam yangın,

ahali kapıda,

“ne tutkulu çift.”

ben de az övünmedim

uyumadığım gecelerle.

bir sofrada kaç lokma yediğimi

kimse sormadı.

sabaha kadar ağlamışım,

sevdamın ciddiyeti oradan belliymiş.

sen ikinci çayı söyledin.

sonra gününü anlatmaya koyuldun.

otobüsü kaçırmışsın,

bir çocuğun atkısını yerden almışsın.

ben büyük bir söz beklerken

sen şekeri bana uzattın.

bir yerde güldüm.

öyle hazırlıksız,

öyle ağzımı kapatamadan.

yan masadakiler dönüp baktı.

sen de güldün.

ben sustum,

neden sustuğumu sordun.

“sesim fazla çıktı,” dedim.

“e, güldün,” dedin yalnız.

çocukken koşarken düşmüşüm de

dizim kanamadan kalkmışım gibi

şaşırdım kendi halime.

sonra seni beklemeye başladım.

bilirim ben kendimi.

iki güzel akşama

bir ömürlük anahtar yaptırırım.

sen daha sokağını söylemeden

ben içimde perde seçerim.

bu defa acele etmedim desem yalan olur.

telefon geç çalınca

bir saatlik sessizliğe

kaç yıllık terk ediliş doldurdum.

aradığında sesim sertti.

“niye böylesin?” dedin.

önce “bir şey yok” diyecektim.

sonra pencereye gittim.

“gelmeyeceksin sandım,” dedim.

söyleyince ne küçük kaldı

içimde büyüttüğüm mahkeme.

“bugün gelemedim,” dedin,

“yarın da işim var.”

içim burkuldu.

sen sözünü değiştirmedin.

o akşam ilk kez

senin yarınında kendime bir saat aramadan

uyudum.

ertesi gün pazara çıktım.

uzun zamandır ilk kez

canım ne çektiyse onu aldım.

bir demet maydanoz,

iki domates,

bir de acısından biber.

eve dönünce yemek yaptım.

sana fotoğrafını göndermedim.

sofraya oturdum,

yemeğim sıcaktı.

senin haberin olmadan da

güzel bir şey olabiliyormuş bana.

bir akşam tartıştık.

ben sözünü kestim.

sen yüzüme baktın.

“bitireyim,” dedin.

bitirdin.

ben de o eski maharetime başvurmadım,

sesimi yükseltip haklı çıkmaya.

özür diledim.

hemen sarılmadın.

çayı tazeledik.

biraz sonra elime dokundun.

o arada ne seni düşman ettim

ne kendimi kapıya koydum.

şimdi ahali soruyor.

“uğruna ölür müsün?”

bir kere de

“yanında nasıl yaşıyorsun?” deseler.

ölmeye şahit çok,

insanın sevincine iki sandalye çekilmiyor bazen.

o günlerde annemi aradım,

yarım bıraktığım kitabı açtım.

bir sabah erkenden yürüdüm,

dönüşte ekmek aldım.

karnım acıkmıştı.

eve varmayı bekleyemedim,

ucundan kopardım.

sana anlatacaklarım vardı.

hepsini biriktirip hayatımı akşama saklamadım.

gün içinde yaşadım,

akşam sana geldim.

yine aynı masaya oturduk.

bu defa saati ben sordum.

“gidecek misin?” dedin.

“birazdan,” dedim.

“yarın erken kalkacağım.”

garson boşları topladı.

“bir çay daha?” diye sordu.

sana baktım, gülümsedim.

“bugünlük yeter,” dedim.

ceketimi giyerken

yarın içeceğim çayı da düşündüm.

✍️', 'seninle ilk oturduğumuz gün çayımı bitirip kalkacaktım. öyle alışmışım. birinin vaktini almadan kendi ömrümden çıkmaya. “bir tane daha içer ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Alp']::text[], 8.5, '{"poet":"Mustafa Alp","poet_slug":"mustafa-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":121,"source_url":"https://www.antoloji.com/ikinci-cay-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahaitum: Eine theologische Auseinandersetzung mit dem Endgültigkeitsanspruch des Korans', 'bahaitum-eine-theologische-auseinandersetzung-mit-dem-endgultigkeitsanspruch-des-korans-muhammed-ridvan-gizri-1esee', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'In der Geschichte haben viele religiöse Bewegungen sich als Fortsetzung der vorangegangenen Tradition positioniert, sich aber mit der Zeit zu eigenständigen Glaubenssystemen entwickelt. Das Bahaitum ist dafür eines der eindrücklichsten Beispiele. Diese Bewegung entstand im Iran des 19. Jahrhunderts aus dem Schoß der schiitischen Tradition und erhebt heute mit Millionen von Anhängern den Anspruch einer globalen Religion. Das Bahaitum präsentiert sich als Vereinigung aller Religionen, als Wegbereiter des Weltfriedens und als letztes Glied der göttlichen Offenbarung. Genau an diesem Punkt tritt jedoch eine grundlegende Spannung zutage. Denn damit das Bahaitum bestehen kann, muss zwingend die folgende Aussage wahr sein: Der Islam ist unvollendet, der Koran ist unzureichend, und Gott hatte es nach 1200 Jahren nötig, eine neue Botschaft zu senden. Im Folgenden wird dieser Kernanspruch des Bahaitums anhand der inneren Logik des Korans, der Grundsätze theologischer Konsistenz und des historischen Kontexts kritisch untersucht.

Historischer Ursprung und theologischer Anspruch des Bahaitums

Vom Babismus zum Bahaitum

Das Bahaitum ist nicht im luftleeren Raum entstanden. Seine Wurzeln liegen in der Schaykhi-Bewegung, die im Iran des 19. Jahrhunderts innerhalb der schiitischen Tradition aufkam. Auf diesem Boden trat Sayyid Ali Muhammad 1844 mit seinem ersten Anspruch hervor: Er sei das Tor (arab. „Bab") zum erwarteten Mahdi. Bald wuchs dieser Anspruch; der Bab war nun nicht mehr nur ein Tor, sondern der Mahdi selbst. Er brachte ein neues Gesetz und erklärte, die Geltung der früheren Religionen sei aufgehoben. Nach der Hinrichtung des Bab im Jahr 1850 ging die Führung der Bewegung faktisch an Mirza Husayn Ali über. Dieser verkündete 1863 in Bagdad seinen eigenen Manifestationsanspruch: Er war nun Baha''u''llah, also die größte Manifestation Gottes. Dieser Übergang stellt einen äußerst kritischen Bruch dar. Denn der Bab hatte seinen Halbbruder Mirza Yahya als Nachfolger eingesetzt. Dass Baha''u''llah diese Einsetzung nicht anerkannte und stattdessen seine eigene Prophetenschaft verkündete, spaltete die Bewegung von Anfang an und schrieb die Legitimitätskrise in ihre DNA ein.

Politische Dimension und äußere Unterstützung

Baha''u''llah blieb nicht bloß ein religiöser Führer. In den Jahren des Exils schrieb er Briefe an den persischen Schah, den osmanischen Sultan, den russischen Zaren, Königin Victoria und den Papst und forderte sie auf, sich ihm zu unterwerfen. Das geht weit über eine rein religiöse Verkündigung hinaus und ist ein politischer Überlegenheitsanspruch. Die Bewegung bewegte sich im Lauf der Geschichte auf einer Linie, die sich mit britischen und russischen Interessen überschnitt. Diese Überschneidung führte dazu, dass das Bahaitum im Nahen Osten als ein mit westlichen Mächten verbundenes Projekt wahrgenommen wurde und starkem Druck ausgesetzt war. Die erlittene Verfolgung ist real und zu verurteilen, kann aber kein Beweis für die theologische Wahrheit der Bewegung sein; in der Geschichte wurden viele Irrlehren verfolgt.

Kitab-i Aqdas und das neue Gesetz

Das 1873 in Akka verfasste Kitab-i Aqdas ist das grundlegende Gesetzesdokument des Bahaitums. Dieses Buch ordnet zentrale Fragen des islamischen Rechts wie Gebet, Fasten, Ehe, Erbe und Strafen neu. Es führt ein Gebet ein, das dem täglichen Gebet ähnelt, aber nur drei Mal am Tag verrichtet wird, eine der Zakat ähnliche Abgabe namens Huququ''llah von neunzehn Prozent sowie ein anderes Kalendersystem. Hier wird die theologische Spannung greifbar. Das Bahaitum ist keine Fortsetzung oder Auslegung des Islam; mit seinem eigenen Buch, seinem eigenen Gottesdienstsystem, seinem eigenen Kalender, seiner eigenen Gebetsrichtung und seiner eigenen Rechtsstruktur ist es eine vollkommen eigenständige Religion. Dies mit dem Schlagwort der „Einheit der Religionen" darzustellen, erzeugt eine erhebliche begriffliche Unschärfe.

Der theologische Grundkonflikt

Sure 5:3 und der Anspruch der Vollendung

Die für das Bahaitum kritischste Stelle des Korans ist der dritte Vers der Sure al-Ma''ida:

„Heute habe Ich euch eure Religion vervollkommnet und Meine Gunst an euch vollendet und euch den Islam als Religion gebilligt."

Dieser Vers ist nicht bloß eine historische Aussage, sondern eine ontologische Abschlusserklärung. Die Vollendung der Religion bedeutet die Verkündung, dass ihr künftig nichts mehr hinzugefügt wird. Das Bahaitum muss, um zu bestehen, behaupten, dieser Vers sei falsch verstanden worden oder müsse symbolisch gelesen werden. Es gibt hier zwei Optionen, und beide sind für das Bahaitum problematisch:

Option A: Der Vers ist im wörtlichen Sinne wahr. Dann ist die Religion tatsächlich vollendet, und Baha''u''llahs neue Bestimmungen stehen in direktem Widerspruch zu dieser Aussage.

Option B: Der Vers ist symbolisch oder kontextbezogen begrenzt. Dann wird selbst die klarste Selbstaussage des Korans unzuverlässig, was das Vertrauen in den gesamten Koran zusammenbrechen lässt.

Eine dritte Option gibt es nicht.

Hatamu''n-Nabiyyin: Siegel oder Letzter?

Einer der systematischsten Einwände der Bahai gegen den Koran bezieht sich auf den Ausdruck „Khatam an-Nabiyyin" in Sure 33, Vers 40. Nach bahaiischer Deutung bedeutet das Wort „Khatm" „Siegel" und müsse nicht mit „der Letzte", sondern mit „der Bestätigende" übersetzt werden. Durch diese Deutung wird unser Prophet Muhammad nicht als der Letzte, sondern als ein Siegel positioniert, das die früheren Propheten bestätigt, und die Tür bleibt für spätere Propheten offen. Diese Deutung hat jedoch sprachlich und kontextuell ernsthafte Probleme. Im Arabischen umfasst die Wurzel „khatm" sowohl die Bedeutung des Versiegelns als auch die des Schließens und Beendens. Einen Umschlag zu versiegeln heißt, ihn zu schließen; diese beiden Bedeutungen schließen einander nicht aus, sondern ergänzen sich. Zudem stützt die allgemeine Erzählung des Korans eine Lesart im Sinne von „abschließen". Wenn Muhammad lediglich ein Bestätiger wäre, warum findet sich dann im Koran nicht einmal ein einziger klarer Hinweis darauf, dass man später kommende Propheten erwarten solle?

Das Problem des Zirkelbeweises

Die tiefste epistemische Schwäche des Bahaitums liegt darin, dass sein Legitimitätsanspruch eine zirkuläre Struktur hat:

- Baha''u''llah ist die Manifestation Gottes, weil er dies in seinen eigenen Schriften gesagt hat.

- Woher wissen wir, dass seine Schriften wahr sind? Weil die Manifestation Gottes es gesagt hat.

Diese Struktur ist in der Logik als „Zirkelbeweis" oder „petitio principii" bekannt. Die zu beweisende Aussage wird als Beweis verwendet. Der Koran dagegen verlangt von Anspruchstellern äußere und objektive Belege: „Bringt euren Beweis her, wenn ihr wahrhaftig seid." (Sure 2:111) Im Lauf der Geschichte haben Hunderte von Menschen behauptet: „Gott hat mich gesandt." Die logischen Mittel, die das Bahaitum zur Zurückweisung dieser Ansprüche verwendet, führen, auf es selbst angewandt, zum selben Ergebnis.

Die Grenzen der symbolischen Auslegungsmethode

Wenn alles Symbol ist, hat nichts mehr Bedeutung

Das Rückgrat der bahaiischen Auslegungslehre ist die symbolische Lesart der physischen und eschatologischen Erzählungen des Korans. Demnach bedeutet das Jüngste Gericht keine physische, sondern eine spirituelle Umwandlung, und die Schilderungen des Jenseits stehen für geistige Wirklichkeiten. Dieser Deutungsrahmen ist äußerst flexibel und umfassend. Doch diese Flexibilität hat ihren Preis: Wenn jede Aussage eines Textes symbolisch gemacht werden kann, kann dieser Text von sich aus nichts mehr mit Sicherheit sagen. Die Bedeutung entsteht dann nicht aus dem Text selbst, sondern aus dem vom Ausleger vorab übernommenen Rahmen. Die Inkonsistenz dieser Methode zeigt sich im folgenden Gedankenexperiment: Wenn die Aussage „Ich habe die Religion vollendet" symbolisch ist, warum ist dann die Aussage „Baha''u''llah sagte, in tausend Jahren werde keine neue Manifestation kommen" nicht symbolisch? Wird dieselbe Methode auf bahaiische Texte angewandt, löst sie auch die Fundamente des Bahaitums auf.

Das Problem der vorweggenommenen Schlussfolgerung

Das zweite grundlegende Problem der bahaiischen Auslegung betrifft die epistemische Reihenfolge. Die übliche Auslegungsmethode lautet: Der Text wird gelesen, die Bedeutung wird abgeleitet, die Schlussfolgerung wird gezogen. In der bahaiischen Auslegungsmethode verläuft die Reihenfolge umgekehrt: Zuerst wird entschieden, dass Baha''u''llah recht hat, anschließend werden die Koranverse so gedeutet, dass sie dieses Ergebnis stützen. Im Koran werden weder der Bab noch Baha''u''llah noch das Kitab-i Aqdas namentlich erwähnt. Sie werden erst nachträglich in den Koran hineingelesen. Diese Methode kann von jeder Ideologie auf jeden heiligen Text angewandt werden; sie hat daher keine Beweiskraft.

Warum sprach Gott nicht deutlich?

Der Koran beschreibt Gott als allwissend, vollkommen und klar sprechend. Diese Beschreibung macht eine Frage unausweichlich: Wenn Gott nach 1200 Jahren Baha''u''llah senden wollte, warum hat Er das nicht im Koran ausdrücklich angekündigt? Im Koran finden sich Verweise auf Moses, Jesus und Muhammad. Auf Baha''u''llah gibt es dagegen keinen klaren Verweis. Die Bahai füllen diese Lücke mit symbolischen Deutungen. Diese Antwort wirft jedoch eine neue Frage auf: Warum sollte der Verkünder einer für die gesamte Menschheit bestimmten Botschaft im Voraus durch rätselhafte Andeutungen angekündigt werden, statt in klaren Worten?

Kritik am Anspruch der „Einheit der Religionen"

Einheit oder Absorption?

Das Bahaitum präsentiert sich häufig als eine Bewegung, die alle Religionen vereint. Dieses Narrativ wirkt auf den ersten Blick inklusiv und friedfertig. In Wirklichkeit geschieht jedoch keine Vereinigung, sondern eine Umformung. Im Zentrum des Moses steht die Tora. Im Zentrum Jesu steht das Evangelium. Im Zentrum Muhammads steht der Koran. Das Bahaitum dagegen stellt Baha''u''llah ins Zentrum all dieser Religionen. Das bedeutet nicht die Vereinigung der Religionen, sondern deren Neudefinition durch Einbeziehung in den bahaiischen Rahmen. Der Diskurs lautet also „Einheit", die Praxis dagegen „Bahaisierung".

Wenn die Religionen im Kern gleich sind, warum ändern sich dann die Bestimmungen?

Nach bahaiischer Lehre speisen sich alle Religionen aus derselben göttlichen Quelle und sind im Kern eins. Diese These enthält einen ernsten inneren Widerspruch: Wenn die Religionen im Kern gleich sind, warum mussten dann Gebet, Fasten und Rechtsstruktur des Islam geändert werden? Wenn es Veränderung gibt, sind die Religionen nicht im Kern gleich. Wenn keine Veränderung nötig war, ist das Bahaitum überflüssig. Beide Aussagen können nicht gleichzeitig wahr sein.

Frauen und Autorität: Die Distanz zwischen Anspruch und Praxis

Das Bahaitum stellt die Prinzipien der Gleichheit und der universalen Gerechtigkeit in den Mittelpunkt seiner Lehre. Das höchste Verwaltungsorgan der Bewegung, das Universale Haus der Gerechtigkeit, besteht jedoch ausschließlich aus Männern, und Frauen können in diesem Gremium kein Amt bekleiden. Darüber hinaus hat die Bewegung im Lauf ihrer Geschichte um den Begriff der „Bundesbrecher" einen ernsten Ausgrenzungsmechanismus entwickelt. Dass eine Bewegung, die Klerikertum und institutionelle Autorität in den traditionellen Religionen kritisiert, in ihrem Inneren selbst verbindliche Auslegungsinstanzen und Disziplinarmechanismen schafft, ist ein tiefer Widerspruch.

Der Zusammenbruch der Theorie der fortlaufenden Offenbarung

Der Begriff des „Letzten" wird bedeutungslos

Das Grundnarrativ des Bahaitums lautet: Moses kam, Jesus kam, Muhammad kam, der Bab kam, Baha''u''llah kam, und diese Kette wird fortgesetzt. Die Bewegung geht davon aus, dass die nächste Manifestation frühestens in tausend Jahren kommen kann. Dieses Narrativ enthält ein in sich unlösbares Problem: Wenn die Kette der Offenbarung fortgesetzt wird, ist keine Religion endgültig. Kein Buch ist abgeschlossen. Keine Bestimmung ist dauerhaft. Dann wird der Begriff der „Wahrheit" zu einem sich ständig aktualisierenden Betriebssystem. Was heute wahr ist, kann morgen ungültig sein. Wie aber kann das Bahaitum die Dauerhaftigkeit seiner eigenen Lehren garantieren? Nach seiner eigenen Logik kann es das nicht. Die Bewegung untergräbt sich damit selbst.

Widerlegung durch das eigene Argument

Das Bahaitum richtet an Muslime häufig folgendes Argument: „Auch die Anhänger früherer Religionen haben die neuen Propheten abgelehnt. Warum begeht ihr denselben Fehler noch einmal?" Dieses Argument ist logisch zweischneidig. Wenn es in der Vergangenheit ein Fehler war, neue Propheten abzulehnen, dann wäre es auch ein Fehler, künftig auftretende neue Anspruchsteller abzulehnen. Wenn im Jahr 2200 jemand auftritt und sagt: „Mir wurde nach Baha''u''llah offenbart", hat das Bahaitum keine logische Begründung, diesen Anspruch zurückzuweisen. Das von ihm selbst hervorgebrachte Argument bindet auch es selbst.

Die Unmöglichkeit absoluter Rechtleitung

Der Koran beschreibt Gott als Den, der der Menschheit eine klare Rechtleitung sendet. Wenn diese Rechtleitung alle paar Jahrhunderte erneuert werden muss, wie viel der früheren Rechtleitung kann dann wirklich als Rechtleitung gelten? Damit eine Rechtleitung diese Eigenschaft tragen kann, muss sie zumindest für einen gewissen Zeitraum gültig bleiben. Ein ständig revidiertes System erinnert nicht an Rechtleitung, sondern an vorläufige Direktiven. Dies impliziert Unwissenheit oder mangelnde Voraussicht Gottes, was mit dem Verständnis der Einheit Gottes (Tawhid) unvereinbar ist.

Die Stellung Baha''u''llahs und die Gefahr der Überhöhung

„Die größte Manifestation Gottes"

Die Ausdrücke, die in bahaiischen Texten für Baha''u''llah verwendet werden, sind bemerkenswert: „göttliche Manifestation", „Erscheinung Gottes", „größte Offenbarung Gottes". In welche Richtung können sich diese Begriffe mit der Zeit entwickeln? Der Koran wahrt beharrlich die ontologische Unterscheidung zwischen Gott und den Geschöpfen. Wird ein Mensch als „größte Manifestation Gottes" dargestellt, birgt das mit der Zeit die Gefahr, diesen Menschen übermäßig zu erhöhen. Es genügt, sich daran zu erinnern, wie die Stellung Jesu im Christentum allmählich vergöttlicht wurde. Die Theologiegeschichte hat immer wieder gezeigt, dass solche begrifflichen Verschiebungen langsam, aber tiefe Spuren hinterlassen.

Die Debatte um den Schriftstil

Von arabischen Sprachkritikern wird beurteilt, dass der arabische Stil der Werke Baha''u''llahs, insbesondere des Kitab-i Aqdas, den Koran nachahme, diese Nachahmung aber äußerst grob ausfalle. Darüber hinaus gibt es ernsthafte Behauptungen, dass einige Werke Baha''u''llahs erst nach seinem Tod zusammengestellt wurden und dabei möglicherweise Veränderungen erfuhren. Dieser Umstand wirft wichtige Fragen zur Authentizität des Textes auf.

Die Begegnung zweier Offenbarungstheorien

Das Modell des Korans

Der Koran gründet sein Offenbarungsverständnis auf folgende Grundachsen: Gott weiß vollkommen, spricht makellos und sendet den Menschen einen klaren Beweis. Dieser Beweis ist nicht in rätselhaften Symbolen, sondern als verständlicher, lebbarer und bewahrter Text herabgesandt worden. Vollendung, Bewahrung und Universalität sind die drei Grundpfeiler dieses Modells.

Das bahaiische Modell

Das bahaiische Modell dagegen beschreibt die Offenbarung als progressiven und historischen Prozess. Je nach den Bedürfnissen der Epoche erscheint eine neue Manifestation und passt ihre Botschaft dem Verständnis dieser Zeit an. Dieses Modell wirkt auf den ersten Blick evolutionär und humanistisch. Seine Annahme hat jedoch folgende zwingende Konsequenzen: Die Vollendungserklärung des Korans ist ungültig. Der Anspruch des Korans auf Bewahrung muss symbolisch verstanden werden. Der Universalitätsanspruch des Korans ist begrenzt. Mit anderen Worten: Der Koran spricht über sich selbst falsch oder irreführend.

Zwei Systeme können nicht gleichzeitig wahr sein

Diese beiden Modelle schließen einander aus. Wenn die Theorie des Korans wahr ist, bricht das Fundament des Bahaitums zusammen. Wenn die Theorie des Bahaitums wahr ist, müssen die Endgültigkeits- und Vollendungsansprüche des Korans neu interpretiert werden. In diesem Fall wird die Glaubwürdigkeit des Korans faktisch beschädigt. Die Debatte findet nicht auf der Ebene der Auslegung einzelner Verse statt, sondern auf der Ebene der Begegnung zweier konkurrierender Offenbarungsepistemologien. Und auf dieser Ebene gibt es keinen Mittelweg.

Wer trägt die Beweislast?

Wird der Koran als letzte Offenbarung anerkannt, so unterliegt jeder spätere Anspruch „Gott hat mich gesandt" einer Beweislast. Diese Last liegt beim Anspruchsteller, nicht beim Zuhörer. Das Bahaitum kann diese Last nicht tragen. Denn die von ihm vorgelegten Beweise sind zirkulär; es leitet seine Legitimität aus seinem eigenen Anspruch ab. Seine Auslegungen des Korans dagegen untergraben den Text, statt ihn zu stützen. Die tiefste Gefahr, die das Bahaitum aus Sicht des Korans darstellt, ist diese: Der Koran wird dem Anschein nach als heilig gehalten, seine Bedeutung aber wird nach der bahaiischen Doktrin neu geschrieben. Das heißt, den Wortlaut eines Textes zu bewahren und seinen Geist zu entleeren. Etwas Vollendetes unterliegt keiner ständigen Revision. Etwas Bewahrtes braucht nicht neu geschrieben zu werden. Das Universale erneut zu universalisieren ist sinnlos. Der Koran sagt über sich selbst: Ich bin vollendet, ich bin bewahrt, ich ziele auf das Universale. Das Bahaitum hingegen muss, um bestehen zu können, sagen: Nein, du bist noch nicht vollendet. Diese beiden Stimmen können nicht gleichzeitig recht haben. Und die Frage, welche Stimme sich auf den stärkeren Beweis stützt, ist jeweils gesondert beantwortet worden.', 'In der Geschichte haben viele religiöse Bewegungen sich als Fortsetzung der vorangegangenen Tradition positioniert, sich aber mit der Zeit z...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bahaitum-eine-theologische-auseinandersetzung-mit-dem-endgultigkeitsanspruch-des-korans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Kapısı', 'umut-kapisi-osman-yuksel-surdem-baq1v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapılar bir bir kapandı yüzüme

Dünya dar geliyor artık gözüme

Güven kalmadı artık el sözüne

Alacağım var kıyamet gününe

Dünya olmuş bir menfaat kapısı

Bilmezler ki her şey kulun yapısı

Elde ne mal kaldı ne mülk yarısı

Dost dediklerim hep çıkar kapısı

Dünya nimetlerini elimle itip attım 

Nefsimi bir dilenciye ucuza sattım 

Kimseye derdimi demeden yattım 

Bu dünyadan kendimi çekip attım 

Ne kendime bir faydam var ne ele 

Artık suskunum söz gelmiyor dile 

Ne gerek var söylenecek son söze 

Gönlüm taştı yaş gelmiyor bu göze', 'Kapılar bir bir kapandı yüzüme Dünya dar geliyor artık gözüme Güven kalmadı artık el sözüne Alacağım var kıyamet gününe Dünya olmuş bir menf...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Sürdem']::text[], 8.5, '{"poet":"Osman Yüksel Sürdem","poet_slug":"osman-yuksel-surdem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umut-kapisi-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biçilir mi?', 'bicilir-mi-ramazan-yildiz-3-1uk5r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİÇİLİR Mİ?

Yollar vardır sıla için

Yola kıymet biçilir mi?

Çöller vardır Leyla için

Çöle kıymet biçilir mi?

Dosta doğru varmak için

Hali hatrı sormak için 

Candan cana sarmak için

Yola kıymet biçilir mi

Gönül denen o sarayı

Sarmak varsa bir yarayı

Gözün görmez hiç parayı

Pula kıymet biçilir mi?

Doğru yanlış eler ise

Helal işler eyler ise

Tatlı tatlı söyler ise

Dile kıymet biçilir mi?

Gelecekse zulüm ile 

Kafir hemde bile bile

Görev verir Ebabile

File kıymet biçilir mi?

Köz olup da uçacaksa

Küle kıymet biçilir mi?

Nur Dağında açacaksa 

Gül’e kıymet biçilir mi?

RAMAZAN YILDIZ', 'BİÇİLİR Mİ? Yollar vardır sıla için Yola kıymet biçilir mi? Çöller vardır Leyla için Çöle kıymet biçilir mi? Dosta doğru varmak için Hali ha...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Yıldız 3']::text[], 8.5, '{"poet":"Ramazan Yıldız 3","poet_slug":"ramazan-yildiz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bicilir-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayd''a Gör Beni!', 'kayd-a-gor-beni-mehmet-i-slami-bl1rf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olur ya hatırlar ararsan eğer

Baktığında dolunayda gör beni

Senin bir gülüş dünyalar değer

Mevta da değilim hay da gör beni

Eğer arzularsan yârim var deyû

Güzel ahlâk edep hayâ ar deyû

Yetmez mi ettiğin ahu zar deyû

Sevinçte kederde vay da gör beni

Biz bu kutsal aşkla düştük yollara

Sabretmiştik anlatılmaz hâllere

Senin kaprisinle düştük dillere

Taşı gediğine koy da gör beni

Derdimi döktüğüm ağrı dağında

Sırrımı açtığım Ömer çağında (r.a) 

Nâr iken Nûr olan Nemrut bağından

Urfa da balıklı çay da gör beni

Eldeki orakla ekini biçtik

Yığını çekerek harmana geçtik

Onlar yiyorlarken biz zehir içtik

Nevri bulandıran kayd’ a gör beni

Kara Murat ile Ayşegül mayâ

Koca Memil baba Hatçe anaya

Ertuğrul bedene Osman kayaya

Fatih Sultan, Selim bey de gör beni

Zikr-i İlâhi haykıran ağızda

Siyah da esmer de kara yağızda

Su iken çeliği dağıtan buzda

Mevlâna da saz da ney de gör beni

Şayet aldandınsa sen senden utan

İki Melek vardır amelin tutan

Lânetullâh hüsnü amelin yutan

Kürrei sallayan fay da gör beni

Her an omuzuna takvayı takın

İblisten uzak dur Meleğe yakın

Akın var efendim CAHİM’ e akın

Belde de oba da köy de gör beni

İSLÂMİ son vakte ramak kaldığın 

Seksen sene arayıp da bulduğun

Sermayen beş metre çaput aldığın

Yirmi Batman susuz şey de gör beni', 'Olur ya hatırlar ararsan eğer Baktığında dolunayda gör beni Senin bir gülüş dünyalar değer Mevta da değilim hay da gör beni Eğer arzularsan ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İslami']::text[], 8.5, '{"poet":"Mehmet İslami","poet_slug":"mehmet-i-slami","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kayd-a-gor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Minnet Etmem', 'minnet-etmem-osman-yuksel-surdem-pkemd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben  günahkar olsamda bir kulum 

Yaradan isterse yönümü bulurum 

Affına sığınır kapısında dururum 

Minnet etmem, kula boyun eğmem

Çaresiz kalsam da ümidimi kesmem

Haram lokmaya el uzatıp ta yemem 

Kulun kapısına gidip te dilenmem

Minnet etmem, kula boyun eğmem', 'Ben  günahkar olsamda bir kulum  Yaradan isterse yönümü bulurum  Affına sığınır kapısında dururum  Minnet etmem, kula boyun eğmem Çaresiz ka...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Sürdem']::text[], 8.5, '{"poet":"Osman Yüksel Sürdem","poet_slug":"osman-yuksel-surdem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/minnet-etmem-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizi Yakacaksın', 'bizi-yakacaksin-naki-aydogan-ec5ay', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bizi Yakacaksın
Gitme her şey biter,
İter.
Ne iter?
Biter.
Ebedi molekül mü kalacağız
Atom bilindi
Parcıklar hesap ediliyor
Bilinç altı atom altı 
Moleküler yaşam cemaatçılık
Bir hareket
Ayrı düşünce zor
Anti madde kalmakta var
Anarşist
Anarşist kurcalar
Terörist parçalar kütle içinde
Moleküler yapı bünyede kütle tümör.

Bizi yakacaksın
Çünkü moleküler yapı tutuşur
Kütle yanıp kül olur.
Din iman ve de ideoloji iyi ama bir tutuşmakta var.
Mazallah.

Ya aile hane
Hanede aile gelenek görenek töre bağlar
Hısım sağlar hasım göder
Su bağlar hava salınır bir kütle uyuruz
Uyduk mu?', 'Bizi Yakacaksın Gitme her şey biter, İter. Ne iter? Biter. Ebedi molekül mü kalacağız Atom bilindi Parcıklar hesap ediliyor Bilinç altı atom...', ARRAY['Türk Edebiyatı','Şiir','Naki Aydoğan']::text[], 8.5, '{"poet":"Naki Aydoğan","poet_slug":"naki-aydogan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bizi-yakacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Son Baharı', 'omrumun-son-bahari-osman-yuksel-surdem-77f96', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bak geldi de geçti ömrümün baharı

Çiçek bile açmadan geldi sonbaharı

Kaç gecenin kaldı bilmem ki sabahı

Üzerime yük kaldı bu ömrün günahı

Yıllar geçti kalmadı yaşanacak gün

Belki bugün ömrümde kalan son gün

Kim bilir belkide ölüm bize düğün

Davul zurna çalınır mı bilmem bugün

Ne yaşadım ki ne umayım hayattan

Böyle yazmış yazımı beni yaratan

Sanki düşer gibiyim bir uçurumdan

Bir rüya olsada uyansam bu uykudan', 'Bak geldi de geçti ömrümün baharı Çiçek bile açmadan geldi sonbaharı Kaç gecenin kaldı bilmem ki sabahı Üzerime yük kaldı bu ömrün günahı Yı...', ARRAY['Türk Edebiyatı','Şiir','Osman Yüksel Sürdem']::text[], 8.5, '{"poet":"Osman Yüksel Sürdem","poet_slug":"osman-yuksel-surdem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/omrumun-son-bahari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kuyu', 'kor-kuyu-selcuk-karakis-t4pv2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Asi gönlüm koptu bağlarından

Kandırıp yedirdi yasak elmadan

Bir yol ki, ne vuslatı var, ne sonu

Çıkamaz oldum bu kör kuyudan

Bir gülse, akmaz durur zaman

Kader, boynumda yağlı urgan

Teslim olduğum buğulu gözler

Dilerse, çıkmam bu kör kuyudan', 'Asi gönlüm koptu bağlarından Kandırıp yedirdi yasak elmadan Bir yol ki, ne vuslatı var, ne sonu Çıkamaz oldum bu kör kuyudan Bir gülse, akma...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Karakış']::text[], 8.5, '{"poet":"Selçuk Karakış","poet_slug":"selcuk-karakis","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kor-kuyu-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılış', 'yikilis-hidayet-gedik-tx18y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir güzel tanıdım seneler önce

Ansızın karşıma çıktı yeniden.

Dizlerim titredi onu görünce

Küllenen ateşi yaktı yeniden.

Bir yağmur sonrası hava serindi

Gök mavi gözleri gökten derindi

Yakına gelince gamze göründü

Aklımı olmaza çekti yeniden.

Tarifsiz duygular geldi dilime

Dilime dolandı üç beş kelime

Geçmişe takılıp kalan halime

Maziye dalarak baktı yeniden.

Usûlen hal hatır, sonrası kaldı

Sonrası kalınca müsaade aldı

Hoşçakal deyince gözlerim doldu

Ruhuma şimşekler çaktı yeniden.

Merakı mucibim kimdi hayali?

Maksuda erdi mi var mı helali?

Avuçta durmayan sular misali

Bilinmez ummana aktı yeniden.

Yollara yârenlik benim kaderim

Kulların elinden her dem hederim

Yıllara yenildim bitmez kederim

Haraptar bendimi yıktı yeniden.', 'Bir güzel tanıdım seneler önce Ansızın karşıma çıktı yeniden. Dizlerim titredi onu görünce Küllenen ateşi yaktı yeniden. Bir yağmur sonrası ...', ARRAY['Türk Edebiyatı','Şiir','Hidayet Gedik']::text[], 8.5, '{"poet":"Hidayet Gedik","poet_slug":"hidayet-gedik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yikilis-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık', 'varlik-eyup-dalkilic-2-0p9vk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ümit varsa insan yaşadıkça hayâl kurar, 

Nefsine uyan insan tüm gönülleri kırar. 

Sevgi sabrı çağırır da nefret derman arar.

Kibir çirkin illet kendini de zira yakar. 

Kimi sükûtla büyür de kiminden kin akar, 

Bir gönül yakarsan, bil ki tüm âlemde yanar. 

Merhamet duygusu insanda büyük bir vakar, 

Zalime merhamet mazlumun canını yakar.

1979', 'Ümit varsa insan yaşadıkça hayâl kurar,  Nefsine uyan insan tüm gönülleri kırar.  Sevgi sabrı çağırır da nefret derman arar. Kibir çirkin il...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Dalkılıç 2']::text[], 8.5, '{"poet":"Eyüp Dalkılıç 2","poet_slug":"eyup-dalkilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/varlik-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri gelir', 'geri-gelir-ayhan-maloglu-2-1wl1f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatta..

Evrene..

Neyi gönderirsen..

O sana..

Geri gelir..

Kötülük..

Kötüye..

İyilik..

İyiye..

Yalan..

Yalancıya..

Sevgi..

Sevene..

Geri gelir..

Mutluluksa..

Herkesin..

Mutlu olmasını..

Dileyene..

Kendi için.. 

İstediklerini.. 

Başkaları içinde..

İsteyene.. 

Katlanarak..

Geri gelir..

Gönderdiğin..

Seni bulur..

Bulmazsa..

Yanlış kişiye..

Yalnız yere..

Göndemişindir..

Ayhan M.', 'Hayatta.. Evrene.. Neyi gönderirsen.. O sana.. Geri gelir.. Kötülük.. Kötüye.. İyilik.. İyiye.. Yalan.. Yalancıya.. Sevgi.. Sevene.. Geri ge...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Maloglu 2']::text[], 8.5, '{"poet":"Ayhan Maloglu 2","poet_slug":"ayhan-maloglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/geri-gelir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Hâlime Hamdolsun', 'her-h-lime-hamdolsun-sairul-i-slam-yunus-kokan-djgp0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözümde yaş var, dilimde hamdım,

Yolumda taş var, Sana dayandım.

Dünyada garip bir kulunum ben,

Kapına geldim, Sana sığındım.

Bazen ağlattın, hikmetin vardı,

Bazen lütfettin rahmetin sardı,

Bazen beklettin, sabrımı tarttın.

Her hâlime hamdolsun ALLAH''ım!

Ne mal isterim ben, ne de bir taht,

Senin rızan olsun bana en büyük baht.

Son nefesimde de dilimde kalsın,

Ruhumu melek tevhidde alsın.

Bazen ağlattın, hikmetin vardı,

Bazen lütfettin rahmetin sardı,

Bazen beklettin, sabrımı tarttın.

Her hâlime hamdolsun ALLAH''ım!', 'Gözümde yaş var, dilimde hamdım, Yolumda taş var, Sana dayandım. Dünyada garip bir kulunum ben, Kapına geldim, Sana sığındım. Bazen ağlattın...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/her-halime-hamdolsun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönüllü Yalnızlık', 'gonullu-yalnizlik-nurcan-bingol-2-qcru0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönüllü yalnızlık bana huzur,
gönülsüz yalnızlık bana keder.

Öldüm sanki…
Ağlayanım yok.

Konuştum…
Dinleyenim yok.

Şimdi sustum.
İçimde yankılanıyor sessizliğim.

Gece,
Azrail gibi
omzuma çökmüş.

Kalbim,
kimsesiz bir evin
kırık penceresi.
Rüzgâr giriyor içeri,
bir tek insan sesi uğramıyor.

Ne gelen var,
ne soran,
ne de “Nasılsın?” diyen biri…

Bir sustum.
Kimsenin duymadığı
kıyametler koptu içimde.

Mevsimlerden ocaktı.
Ateşe eğilmedim.
Baharı beklerken
kendi ayazımda demlendim.

Eksildim belki,
ama tükenmedim.

Sonra yalnızlığımı
gidenlerin ardından toplamayı bıraktım.
Başkalarının yokluğundan alıp
kendi ellerime bıraktım.

Şimdi yalnızlığa talibim,
varlığını nimet gibi gösterip
yokluğunu borç bırakanlara inat.

Ah be, koca yaşlı dünya…
Senin ayına,
güneşine,
yıldızlarına vurgunum.

Onlar da
göğün kalabalığında yalnız.
Birbirlerine varmadan
bize yetişiyor ışıkları.

Ben de öğrendim.

Yalnızlık,
insanı kimsesiz bırakmaz her zaman.
Bazen kalabalıktan alır,
kendine verir.

Bazen de büyük bir senfoni gibi
kulağımda usul usul çalar.
Dinledikçe içim durulur.

Şimdi yalnızlık bana keder değil.

Çünkü ben artık
gidenlere değil,
kendime gönüllüyüm.

Nurcan Bingöl', 'Gönüllü yalnızlık bana huzur, gönülsüz yalnızlık bana keder. Öldüm sanki… Ağlayanım yok. Konuştum… Dinleyenim yok. Şimdi sustum. İçimde yank...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/gonullu-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şükür Sana', 'sukur-sana-sairul-i-slam-yunus-kokan-5l9r0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşi doğdurdun her bir sabaha.

Bir nefes verdin, bin şükür Sana,

Gizli, aşikâr nimetlerin sayısız,

Şükürler olsun ey Rabbim Sana!

Beni kul eyledin, aldın huzuruna.

Şükür Sana ALLAH''ım, şükür Sana,

Düşsem de kalkarım Sen''in adınla,

Şükür Sana ALLAH''ım, şükür Sana!

Bir lokma ekmeğe, bir yudum suya,

Şükürler olsun ey Rabbim Sana!

Dertlerim içinde Sen''sin umudum,

Senin lütfun ile yaşıyor ruhum.

Beni kul eyledin, aldın huzuruna.

Şükür Sana ALLAH''ım, şükür Sana,

Düşsem de kalkarım Sen''in adınla,

Şükür Sana ALLAH''ım, şükür Sana!', 'Güneşi doğdurdun her bir sabaha. Bir nefes verdin, bin şükür Sana, Gizli, aşikâr nimetlerin sayısız, Şükürler olsun ey Rabbim Sana! Beni kul...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sukur-sana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Yandığın Belli Olacak', 'kime-yandigin-belli-olacak-ali-taskale-a0j1k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sokak lambası gibi olmayacaksın,

kime yandığın belli olacak...

Bir şehrin bütün karanlığına

aynı ışığı düşürmek değildir mesele;

bazen bir çocuğun üşüyen ellerine,

bazen ekmeğini yarıya bölen

bir babanın suskunluğuna

ışık olabilmektir.

Çünkü meydanlar kalabalık,

kürsüler yüksek,

sözler gökyüzüne kadar uzanıyor.

Ama aşağıda,

kimsenin eğilip almadığı

bir hayat kırıntısı var.

Birileri koltukların ömrünü uzatıyor,

birileri umutların...

Birileri kendi adını

memleketin kaderine yazıyor,

birileri yarınını

seçim meydanlarında arıyor.

Oysa halk,

kimsenin gölgesinde büyümek için

doğmadı.

Ne bir makamın basamağıdır insan,

ne de bir iktidarın

tüketilebilir hatırası.

Ben tarafımı

bayrakların rengine göre seçmedim;

bir sofrada eksik kalan lokmaya,

bir mahkeme kapısında eskimiş bekleyişe,

bir annenin içine gömdüğü çığlığa

bakarak seçtim.

Ve öğrendim:

Işık,

her yere değdiğinde değil,

karanlığın nerede ağırlaştığını

bildiğinde anlam kazanır.

Sokak lambası gibi olmayacaksın...

Ne herkese yaranmak için yanacaksın

ne de kendi gölgeni aydınlatmak için.

Kime yandığın belli olacak.

Çünkü bazı ışıklar

yol göstermez;

yalnızca

kimin karanlıkta bırakıldığını

gösterir.

Ali TAŞKALE | İzmir

Haziran 2025', 'Sokak lambası gibi olmayacaksın, kime yandığın belli olacak... Bir şehrin bütün karanlığına aynı ışığı düşürmek değildir mesele; bazen bir ç...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkale']::text[], 8.5, '{"poet":"Ali Taşkale","poet_slug":"ali-taskale","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/kime-yandigin-belli-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karar Günü', 'karar-gunu-yasar-baykal-ms1lu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zalim felek, bu mu dermanı

Ayrılık çıktı, karar fermanı

Söz dinlemez, kara gönlüme

Teselli bulamam, yara gönlüme

Düştüm, dağıldım, şifasız ayrılığa                          

Dağıldım, kalmadım, yalansız aynalar

Mapusum parmaklık, zindanı bahtıma

Dost geceler, dostum kara geceler

Ayrılık çıktı, karar günüme 		     

Hançer saplandı, yaralı kalbime

Bu aşkın oyunu, bahtımın çilesi

Alnıma yazılmış, aşkın teline

Dağıldım rabbim, burası aşkın zindanı

Mapusluğun bulunmaz, derde dermanı

Ağlarım, ben ağlarım, dünya gülsün

Sevmişim kara felek, yoktur dermanı

Karar günüm bugün, kara parmaklıklar

Aşkın zindanındayım, dağıldım rabbim

Sanığım aşka, tanık olun parmaklıklar

Gülsün dünya, ağlarım, ben ağlarım

Bugün karar günüm, kara geceler

Dost geceler, dostum kara geceler

Zalim felek, bu mu dermanın

Ayrılık çıktı, karar fermanın 

Söz dinletemem, kara gönlüme

Teselli bulamam, yara gönlüme

Ayrılık çıktı, karar günüme 		     

Hançer saplandı, yara kalbime

Bu bahtımın oyunu, aşkın çilesi

Alnıma yazılmış, derman teline

Damarımda nabzım can taşır

Parmaklıklar benden iz taşır

Dağıldım kalmadım, yalansız aynalar

Dost geceler, dostum kara geceler', 'Zalim felek, bu mu dermanı Ayrılık çıktı, karar fermanı Söz dinlemez, kara gönlüme Teselli bulamam, yara gönlüme Düştüm, dağıldım, şifasız a...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/karar-gunu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işığın Tutanağı', 'isigin-tutanagi-ali-taskale-t3grx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sokak lambası düşünün;

yanıyor.

Ama kimin için?

Altından geçen yoksulun

yüzünü aydınlatıyor,

gölgesini uzatıyor.

Kürsüde bir gölge büyüyor,

meydanda binlerce ayak

aynı vaadin tozunu yutuyor.

Koltuklar konuşuyor artık,

insanlar susuyor.

Bir makamın çekmecesinde

katlanmış bir halk var.

Üzerinde

seçim tarihleri,

yarım kalmış vaatler,

imzalanmamış hayatlar...

Ve birileri

memleketi kendi adının

uzun bir dipnotu sanıyor.

Hayır!

Bu ülke

kimsenin kişisel aynası değil.

Hiçbir yüz

bu kadar büyüyemez

bir halkın yüzünden.

Benim tarafım

bir siyasi haritada işaretli değil.

Bir çocuğun beslenme çantasında

eksik kalan yarında,

bir emeklinin cüzdanında

sessizce küçülen dünyada,

hakkını ararken

sesini kaybeden insanın

boğazında düğümlü.

Ben oradayım.

Işığımı oraya tutuyorum.

Çünkü karanlık

bazen lambanın sönmesi değildir;

yanan bütün ışıkların

yanlış yere çevrilmesidir.

Ve sen...

Sokak lambası gibi olmayacaksın.

Yanacaksan

bir makamın gölgesine değil,

insanın yüzüne yanacaksın.

Kime yandığın belli olacak.

Çünkü ışığın da

bir vicdanı olmalı.

Ali TAŞKALE | İzmir

Kasım 2026', 'Bir sokak lambası düşünün; yanıyor. Ama kimin için? Altından geçen yoksulun yüzünü aydınlatıyor, gölgesini uzatıyor. Kürsüde bir gölge büyüy...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkale']::text[], 8.5, '{"poet":"Ali Taşkale","poet_slug":"ali-taskale","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/isigin-tutanagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Hakkı Yiye Yiye', 'kul-hakki-yiye-yiye-yakup-kiraz-lr84g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kul hakkı yiye yiye 

Dönmüş tombalak kediye

Rüşvet de diyemiyor

Adını koymuşlar hediye"', 'Kul hakkı yiye yiye  Dönmüş tombalak kediye Rüşvet de diyemiyor Adını koymuşlar hediye"...', ARRAY['Türk Edebiyatı','Şiir','Yakup Kiraz']::text[], 8.5, '{"poet":"Yakup Kiraz","poet_slug":"yakup-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kul-hakki-yiye-yiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Benim Ruh Eşim', 'o-benim-ruh-esim-yasar-baykal-p7jer', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruh eşim merhaba

Kalbim sana da  merhaba 

Ruh eşim, ben gibi değil

Ben gökyüzü seviyorum mesela

O sabah rüzgarının ürperten esişini

Ben ateşin başında akşam güneşini

O cam tavandan yıldız izlemeyi

Ruh eşim kendi gibi

Başucuna bırakılmış

Özenle sıkılmış

Günlük mevsim meyvesi

O benim ruh eşim

Anlarız birbirimizi

Sevgimiz dağlar değil

O benim ruh eşim

Onu sevdiğimi biliyor

Ben onun bana sevgisini

Biliyoruz sevgi kaynaktır

Hep verir

O benim ruh eşim

Tüketmeyi aklından geçirmez

Tamamlanmak gibi yudumlar gibi

Birbirimizi

O benim ruh eşim

Anlarız birbirimizi

Sevgimiz kocaman değil', 'Ruh eşim merhaba Kalbim sana da  merhaba  Ruh eşim, ben gibi değil Ben gökyüzü seviyorum mesela O sabah rüzgarının ürperten esişini Ben ateş...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/o-benim-ruh-esim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-nurcan-bingol-2-4v0mf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu aşkın biletini sen kes,
bedelini benden isteme.
Kalbimi al;
ama benden “kal” dememi bekleme.

Şehirlere hazin sonlar çökmüş;
her sokak senden kalan
bir vedaya çıkıyor.
İçimde tarifsiz bir yangın var.
Kitaplar susuyor,
şiirler yarım kalıyor,
şarkılar sesini bulamıyor.
Hiçbir söz anlatamıyor
içimde büyüyen bu acıyı.

Sen hiç bilir misin
dünyanın insanın başına çökmesini?
Bir zamanlar altında huzur bulduğun göğün
bir gün üstüne kapanmasını…
Kararmış bulutların
omuzlarına çöküşünü,
nefes aldığın her yeri
karanlığa boğuşunu?

O günden beri gözlerim
uzaklara bakar kaldı.
İçim bir yol arıyor,
ayaklarım olduğum yerde.
Ne sana varabiliyorum
ne kendime dönebiliyorum.

İki elim iki yakanda kaldı;
tutmak için değil,
soramadığım hesabın ağırlığıyla.
Ahım sırtına kambur oldu, bilesin.
Ben sustukça büyüdü içimde,
sen duymadıkça
biraz daha ağırlaştı.

Ben sana
bütün yorgunluklarımın hesabını sormadım.
Hangi gece uykumu yitirdim,
hangi susuşunda içimden eksildim,
bir bir önüne dökmedim.

Ben yalnızca
“Gitme,” diyememenin
ızdırabını yaşıyorum.

Dilimde düğümlenen o söz
geç kaldı belki.
Sen kapıya vardığında
ben hâlâ içimde
sana açılacak bir yol arıyordum.

İnsan bazen sevdiğine
“Kal,” demeyi bile beceremiyor.
Gururundan değil;
sözünün karşılıksız kalmasından korkuyor.
Ben de sustum.
Sen o suskunluğu
gitmene izin sandın.

Oysa ben seni
sen gidesin diye sevmedim.
Ardına bakmadan çekip gidesin diye
ömrümden eksiltmedim kendimi.

Şimdi bu aşkın biletini sen kes.
Yol senin, son durak senin…
Kalbimi al;
içinde senden kalan ne varsa
senin olsun.

Ama benden
seni unutmayı bekleme.
Bir zamanlar evim bildiğim birini
hiç yaşamamışım gibi
nasıl silerim?

Sen gittin ya…
Gecemden ayımı,
gündüzümden güneşimi aldın.
Beni karanlıkların ortasında
kendimle baş başa bıraktın.

Eski ben nasıldım, bilmiyorum.
Bu hâlimi de hiç sevmedim be.
Şehirler sustu,
şarkılar yarım kaldı.
Ben hâlâ
“Gitme,” diyememenin
sızısıyla yaşıyorum.', 'Bu aşkın biletini sen kes, bedelini benden isteme. Kalbimi al; ama benden “kal” dememi bekleme. Şehirlere hazin sonlar çökmüş; her sokak sen...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/gitme-1474-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-nurcan-bingol-2-25qjc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nurcan Bingöl

Gittin ya,
gecemden ayımı aldın,
gündüzümden güneşimi.
Ben karanlıklara düştüm be gülüm.

Ölüm bütün kasvetiyle üstüme sinmiş,
kokusu içime dağılmış.
Ruhum bedenimle Araf’ta kalmış şimdi.
Meğer zalimin zulmüymüş
yârim diye bağrıma bastığım.
Ruhunu satmış sevdiğim.
Bunu bildiğim gün bile
adını içimden yâr diye geçirdim.

Sevdamız iki ülke arasında kaybolmuş.
İkimiz de bakıyoruz
birbirimizi yitirdiğimiz yere.
Mektuplarım çoktan yola çıkmış,
varacakları adres bile belli değil.

Nefesimi tutuyorum da
saatli bir bomba gibi duruyor göğsümde.
Bir bıraksam,
ikimizden geriye ne kaldıysa
alıp götürecek sanki.

Seninle yaşadığımız şehrin üstüne
ölümün yası yağıyor.
Belki yağmurlar fırtınaya dönecek.
Burada her şey başka be gülüm.

Şimdi, en savunmasız hâlimde
üstüme gelenlere selam olsun,
kadere de, Azrail’e de.
Bir de arkama bakmadan
yürüyememenin acısı var.

Ah be gülüm,
ölüm en çok yaşayanlara gelir.
Kıyamet de en çok
vurgun yemişlerin içinde kopar.
Sessiz çığlıklar
evlerin duvarları arasında kalır.
O kıyametin zulmünü
bir tek sevdiğinin ihanetini yaşayan bilir.

Öldüm de
soğuk, puslu bir sabah
ezan sesine uyandım.
Göğsüm yine inip kalktı.
İçimde bir yer
öylece kaldı.

Sen hiç kefensiz ölüm bilir misin?
Selâsı okunmaz.
Yasını da gidenler tutar.

İlmek boynuna geçer de
insan hâlâ nefes alır.
İlmeği geçiren elin
sevdiğine ait olduğunu anladığımda
İşte o zaman can verdim

Korktuğumda
elimi ilk sana uzatırdım.
Şimdi avuçlarımda
sensizliğin nemi, soğuk hüznü.
Katilim de sen, sevdiğim de sen.
Kurşunum ihanet.
Mezarım bu dünyada yaşamak oldu. Be gülüm

Eskiden aklıma önce
ruhun bedenden ayrılışı gelirdi.
Sonra bir kefen,
bir de üstüne kapanan toprak.

Meğer ruh hâlâ bedendeyken de
yaşanırmış o gidiş.
İnsan her nefeste duyarmış
kanayan yerin acısını.

En acısı buymuş ya
Ben seni yaşarken sevdim.
Sen beni yaşarken öldürdün be gülüm.', 'Nurcan Bingöl Gittin ya, gecemden ayımı aldın, gündüzümden güneşimi. Ben karanlıklara düştüm be gülüm. Ölüm bütün kasvetiyle üstüme sinmiş, ...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/gulum-1093-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EY İÇİMDEKİ İNSAN', 'ey-i-ci-mdeki-i-nsan-nurcan-bingol-2-8ijxp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'EY İÇİMDEKİ İNSAN

Söz: Nurcan Bingöl

Dalmış türlü türlü hayallere,
Kadere gülme, ey içimdeki insan.
Bendeki hülyalara aldanıp,
Hayatla meşk eder durursun.

Saklı içinde binbir sevda,
Kimi düş olur, kimi yara.
Hepsini kendinden bilirsin,
Sana mı kalır sandın sevdalar?

İnsanın ışığını görüp,
Onu tanıdığını sanırsın.
Bir kulda kusursuzluk ararken,
Hakk’a değil, kula mı eğiliyorsun?

Yürüdüğün bu yolda,
Ayağının altındaki taş,
Suyla can bulan toprak,
Gölgesine sığındığın ağaç…

Ne bir yaprak senin hükmünde,
Ne gökte uçan kuşun kanadı.

Ey içimdeki insan,
Bir yanın sabır, bir yanın ateş.
En çetin savaş kendi içinde,
Sessizce sürer, kimse bilmez.

Ne elinde tuttuğun kalır,
Ne de üstüne bastığın toprak.
Bir nefeslik ömrün içinde,
Neyi kendine mülk sanıyorsun?

Ey içimdeki insan,
Bir gün bu yol da bitecek.
Ne sevdaların seninle gelecek,
Ne de dünya seninle gidecek.

Bir tek kendine sor o vakit:
Emanete sahip çıkabildin mi?

Bunca ömrün, bunca nefesin içinde,
İnsan-ı kâmil olabildin mi,
Ey içimdeki ham ervah?', 'EY İÇİMDEKİ İNSAN Söz: Nurcan Bingöl Dalmış türlü türlü hayallere, Kadere gülme, ey içimdeki insan. Bendeki hülyalara aldanıp, Hayatla meşk ...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ey-icimdeki-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Akıl Fikir Versin', 'allah-akil-fikir-versin-aydin-ahmet-9fy1s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zıvanada iyice çıktık

Allah akıl fikir versin

Contayı devreyi yaktık

Allah akıl fikir versin

Karar milletin diyorsun

Haini affediyorsun

De bana ne içiyorsun

Allah akıl fikir versin

Bu mudur açılım, barış

Bu düpe düz bir yalvarış

Öyle miydi dim dik duruş

Allah akıl fikir versin

Başımız düştü ya dara

Dün ak derdik bugün kara

Bu nasıl çılgın macera

Allah akıl fikir versin

Emekliler sekarette

Kuru soğana minnette

Bari biraz dua et de

Allah akıl fikir versin

Uçtu gitti akaryakıt

Düşmez gayrı hiç bir vakit

Atatürk’e takmış akit

Allah akıl fikir versin

Gidiyoruz geri geri

Yetmez oldu alın teri

Gaza getir ver mehteri

Allah akıl fikir versin

Amerika bize düşman

İsveç doğduğuna pişman

İyi ki var Mazhar Osman

Allah akıl fikir versin

Esnaf emekli yanıyor

Troller uçtuk sanıyor

Herkes bizi kıskanıyor

Allah akıl fikir versin

Çökün pazara sergiye

Dayan zamlara vergiye

Kulak verin bu vurguya

Allah akıl fikir versin

Üç güne bir zam geliyor

Cebi cüzdanı deliyor

Garibana züht kalıyor

Allah akıl fikir versin

İyice azdı sosyal medya 

Kimi Vilma kimi Nadya

Düzelir mi bozuk podye

Allah akıl fikir versin

Ozan Ahmet takma boşa

Çok yoruldun koşa koşa

Yaramaz ki hiçbir işe

Allah akıl fikir versin', 'Zıvanada iyice çıktık Allah akıl fikir versin Contayı devreyi yaktık Allah akıl fikir versin Karar milletin diyorsun Haini affediyorsun De b...', ARRAY['Türk Edebiyatı','Şiir','Aydın Ahmet']::text[], 8.5, '{"poet":"Aydın Ahmet","poet_slug":"aydin-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/allah-akil-fikir-versin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlat', 'evlat-nurcan-bingol-2-9vosr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'EVLAT

Söz: Nurcan Bingöl

Evlat…

Canım yangını arşa değmiş,
Kalbimi en çok acıtanım…

Ben seni canıma karşılık sevdim,
Ben seni kimsesizliklerimde tuttum.
Hiç keşkem olmadın,
Hep iyikim oldun.

Hiç duraklarda beklemedim,
Nefes almaya bile durmadım.
Hep koştum…
Sen koşma, sen bekleme diye.

Ardına bakmadan yürü istedim,
Keşkelere kalmasın yarınların.

Kendi yorgunluğumu unuttum,
Senin yoluna düşmesin diye.
Kendimi hayatın önüne attım,
Sana değmesin diye dünyanın ağırlığı.

Fırtınalı denizlerden çıktım,
Senin kıyılarına varmasın diye tufanlar.

Ben ne tufanlar gördüm…
Beni yıkmaya çalışan her şeye dayandım da
Senin gözlerindeki şimşeklerle
Bana bakışına dayanamadım.

Sözlerin yıktı beni,
Kırıldığım yer öldürdü beni.

Bin kere kırıldım,
Bir kere öldüm.

Yarınlar bitti,
Nefesim bitti.

Sen içimde gidenleri görmedin,
Bendekiler çoktan yol aldı.

Ne bir ses duydun,
Ne bir veda…

Artık içimde cenazeler
Öyle büyük törenlerle kalkmıyor.

Evlat…

Ben sana ömrümden ömür verdim.
Sen benim içimde
Nelerin öldüğünü bilmedin.

Yine de…

Sana bedduam yok,
Sana çok büyük acım var.

Hayatın içindeki bütün yok oluşlara rağmen,
Sana rağmen…

Seni Allah’ın emaneti bilip
Önünde eğiliyorum.', 'EVLAT Söz: Nurcan Bingöl Evlat… Canım yangını arşa değmiş, Kalbimi en çok acıtanım… Ben seni canıma karşılık sevdim, Ben seni kimsesizlikler...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/evlat-237-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırgın ayrılacağım', 'kirgin-ayrilacagim-ahmet-bal-4-lw1ru', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onca bahar günüm kışlara döndü 

bu dünyadan kırgın ayrılacağım 

Ne ocağım yandı ne duman tüttü 

bu dünyadan kırgın ayrılacağım 

 Eşime dostuma sevdiklerime 

Canımdan kıymetli dediklerime.

En büyük darbeyi yediklerime 

Bu dünyadan kırgın ayrılacağım 

Hiç bir şey istemem her şeyim  kalsın 

Kimse  aramasın kimse sormasın 

Son bir dilek hakkım bile olmasın 

Bu dünyadan yorgun ayrılacağım', 'Onca bahar günüm kışlara döndü  bu dünyadan kırgın ayrılacağım  Ne ocağım yandı ne duman tüttü  bu dünyadan kırgın ayrılacağım   Eşime dostu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kirgin-ayrilacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan En Çok Sevdiklerini Öldürür', 'i-nsan-en-cok-sevdiklerini-oldurur-nurcan-bingol-2-gllh2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsan en çok sevildiğini sandığı yerde küçülür,
en çok sevdikleri öldürür insanı.
En büyük yıkımlar
en yakın bildiklerinden gelir.

Çünkü insan
yabancının açtığı yaraya değil,
can bildiğinin sessizliğine kanar.
Bir söz değil yalnızca,
o sözü söyleyenin yeri yıkar içinde.

Bazen içinde bir orman yanar,
bir dağ yıkılır.
Acısı içinde yılları devirirsin.
Gözyaşların içine içine akar da
en yakınlarının merhametsizliği
köklerini kurutur.

Dışarıdan bakan
yalnızca sustuğunu sanır.
Oysa içinde
bir ömürlük gürültü kopar.
Kimse duymaz
yıkılan taşların sesini.

Unutma,
aynı toprakta kök saldığın,
güneşi, suyu bölüştüğün herkes
seninle aynı göğe uzanmaz.
Kimi zehirli bir sarmaşık gibi
sarar seni,
nefesini keser.

Önce gölgesinde dinlenirsin,
sonra güneşine hasret kalırsın.
Sarıldığın dalın
seni ayakta tuttuğunu sanırsın;
bir gün anlarsın,
tutunduğun şey
düşüşünü geciktirmiş yalnızca.

Kalakalır­sın.
Beklediğin, umduğun bu değildir.
Ardına bakamazsın,
önüne bakamazsın.
Yıkılırsın.

Ne gidecek gücün vardır
ne de kalacak hâlin.
Bir yanın “bitti” der,
öteki yanın
hâlâ bir açıklama bekler.

Zordur…
Bildiklerini bilmediğini fark etmek
çok zordur.

İnsan en çok da
kendisine anlattığı hikâyeye inanır.
Görmediğini değil,
görüp de yakıştıramadığını
kabullenmek zordur.

Öyle herkese yaslama sırtını.
İnsan, arkasında kimsenin kalmadığını
düşene kadar göremez.

Vah ki düşene…

İşte o vakit
lal olur dilin,
âmâ olur gözlerin.
Gördüğünü görmezden gelir,
bildiğini içine gömersin.

Çünkü bazen susmak,
acıyı büyütmemek için
bulabildiğin tek çaredir.

Söylersen kırılır bir şeyler,
susarsın içinde.
İnsanı bazen
hangisi daha çok yakar bilemez;
yalnızca sesini
kendi içine kapatır.

Ama bil ki
insan her sevdiğinden kolay vazgeçmez.
Bir ömür içinde yaşattıklarını
bir günde çıkaramaz gönlünden.

Bir adı silmekle bitmez her şey,
bir kapıyı kapatmakla susmaz hatıralar.
Bazen bir koku, bir şarkı,
eski bir söz
bütün yaraları yeniden konuşturur.

Bir gecede her şey değişir.
Doğrular, yanlışlar yer değiştirir.
Bir zamanlar can bildiklerin
şimdi gönlünün en uzak yerindedir.

İşte orada
derin bir suskunluk başlar.

İç çekişler…
Gururun önüne geçen gözyaşları…

İnsan bazen bir kere ağlar,
çok ağlar, çok…
Bir ömrün yasını
bir defa da tutar gibi.

Sonra susar.

Çünkü gözyaşının da
bir yere kadar dili vardır.
Sonrası, insanın
kendine bile anlatamadığı
bir sessizliğe döner.

Unutmaz…
Ama unutur.

Ne yaşadığını değil,
yaşadıklarının içinde bıraktığı acıyı.

Bir gün uyanır,
göğsündeki ağırlık eskisi kadar değildir.
Yara duruyordur belki,
ama her dokunuşta kanamaz.
İnsan bazen
acıyı taşımayı öğrenir.

Hayat bu ya…

Gün gelir,
ne söyleyecek bir söz kalır
ne de aralık bir kapı.

Beklemek de yorar,
umut etmek de.
Bir zamanlar döner diye
gözünü yoldan ayırmadığın
o yol, sonunda
sana yabancı olur.

Bazen kendi içinde öldürdüğün
insanların yasını tutarsın.

Öldüklerini bile bile,
gelmeyeceklerini bile bile…

Çünkü bazı vedalar
kapı önünde edilmez.
İnsan, birini içinde
yavaş yavaş uğurlar.
Her hatırada biraz daha
yer açar olmayışına.

Ve anlarsın:

İnsan en çok sevdiklerini öldürür.', 'İnsan en çok sevildiğini sandığı yerde küçülür, en çok sevdikleri öldürür insanı. En büyük yıkımlar en yakın bildiklerinden gelir. Çünkü ins...', ARRAY['Türk Edebiyatı','Şiir','Nurcan Bingöl 2']::text[], 8.5, '{"poet":"Nurcan Bingöl 2","poet_slug":"nurcan-bingol-2","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/insan-en-cok-sevdiklerini-oldurur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskün', 'kuskun-ahmet-bal-4-pxqxy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Harcana harcana geçti bir ömür 

Kendime küskünüm yıllara küskün 

Bir parça mutluluk layık görmeyen 

talihe küskünüm kadere küskün 

Kendime küskünüm ben sana küskün 

Gönül buz kentinde baharı bekler 

Hebaya gittiler onca emekler 

Beni öldürmeye yetti hasretler 

Ben ona küskünüm ben bana küskün 

Ben bana küskünüm ben sana küskün

Son demi yaşandı geçti gençliğim

Haktan revamıydı neydi çektiğim 

Kuruş etmezlere paha biçtiğim

Dünyaya küskünüm insana  küskün 

Ben bana küskünüm ben sana küskün 

Gönlüm buz kentinde bahar bekledi 

Hasretin üstüne hasret ekledi 

Oysa ben ölüydüm  o can bekledi

Yazıma küskünüm sızıma küskün 

Ben bana küskünüm ben sana küskün', 'Harcana harcana geçti bir ömür  Kendime küskünüm yıllara küskün  Bir parça mutluluk layık görmeyen  talihe küskünüm kadere küskün  Kendime k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kuskun-78-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç mi yüzüm gülmeyecek', 'hic-mi-yuzum-gulmeyecek-ahmet-bal-4-2gs3j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu kadere talihe bak 

Hiç mi yüzüm gülmeyecek 

Artık yoruyor yaşamak 

Hiç mi yüzüm gülmeyecek 

Dönüp duran devran oldum

Pusulasız kervan oldum

Yedi paylık kurban oldum 

Hiç mi yüzüm gülmeyecek 

yazılmış hep bahtım kara

içerimde derin yara

söyleyin yalan dünyada

hiç mi yüzüm gülmeyecek', 'Şu kadere talihe bak  Hiç mi yüzüm gülmeyecek  Artık yoruyor yaşamak  Hiç mi yüzüm gülmeyecek  Dönüp duran devran oldum Pusulasız kervan old...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hic-mi-yuzum-gulmeyecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Gözüyle', 'gonul-gozuyle-mehmet-kaya-6-elcsh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşünce sineye aşkın ateşi,

Sönermiş dünyanın sahte güneşi,

Bulunmaz o yolda sevdanın eşi,

Bakmayı bilirsen gönül gözüyle.

Zikrinle nurlanır kara geceler,

Duayla çözülür gizli heceler,

Huzur iklimine erer niceler,

Hakikat görünür gönül gözüyle.

Sabrın ocağında pişer yürekler,

Vuslat kapısında uçar dilekler,

Tevekkül bağında açar çiçekler,

Ömür dokunurmuş gönül gözüyle.

Adil olup edep giyen kul olur,

Hikmet pınarında diller durulur,

Benliği bırakıp cemali bulur,

Menzile varırmış gönül gözüyle.

Nefis sarayını virane eyle,

Marifet sırrını nişane eyle,

Biçare Kaya''yı divane eyle,

Rabbe vasıl olsun gönül gözüyle.

19.11.26 - M. Kaya', 'Düşünce sineye aşkın ateşi, Sönermiş dünyanın sahte güneşi, Bulunmaz o yolda sevdanın eşi, Bakmayı bilirsen gönül gözüyle. Zikrinle nurlanır...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kaya 6']::text[], 8.5, '{"poet":"Mehmet Kaya 6","poet_slug":"mehmet-kaya-6","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gonul-gozuyle-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben eski ben olsaydım', 'ben-eski-ben-olsaydim-ahmet-bal-4-19yco', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya niye üstüme 

Gelir gibi oluyor 

Ne oldu anlamadım 

Çok zoruma gidiyor 

Ben engeller aştıkça 

Dert üst üste biniyor 

Girdiğin bu hallerin 

Sabrımı çok   Zorluyor 

Ben eski ben olsaydım 

Karalarmı bağlardım 

Ben eski ben olsaydım 

Ortalığı yakardım 

Ben eski ben olsaydım 

İcabına bakardım 

Ben eski ben olsaydım 

Ben eski ben yar 

Yar dediğim sarmıyor 

Dost kuyumu kazıyor 

Sonu ne olur dersin 

Sabrım beni zorluyor 

Ben engeller aştıkça 

Dert üst üste biniyor 

Girdiğin bu hallerin 

Sabrımı çok   Zorluyor 

Ben eski ben olsaydım 

Karalarmı bağlardım 

Ben eski ben olsaydım 

Ortalığı yakardım 

Ben eski ben olsaydım 

İcabına bakardım 

Ben eski ben olsaydım 

Ben eski ben yar', 'Dünya niye üstüme  Gelir gibi oluyor  Ne oldu anlamadım  Çok zoruma gidiyor  Ben engeller aştıkça  Dert üst üste biniyor  Girdiğin bu haller...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-eski-ben-olsaydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl İsterse / Ben vazgeçtim Artık', 'nasil-i-sterse-ben-vazgectim-artik-ahmet-bal-4-0ju9h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben vazgeçtim  artık onun aşkından 

Yolu bahtı açık olsun giderse 

Attım belasını gitti başımdan 

Bundan sonra gitsin kime isterse

Gidiyorsa gitsin nasıl isterse 

Gönlümden azadı mübarek olsun

Şimdi varıp gitsin ellerin olsun

Benim için öldü  başım sağolsun 

Bundan sonra gitsin kime isterse

Gidiyorsa gitsin nasıl isterse 

İkinci yüzünü saklamış benden 

Oda hep  kırılsın kırdığı yerden 

Mutluluk görmesin gittiği yerden 

Bundan sonra gitsin kime isterse', 'Ben vazgeçtim  artık onun aşkından  Yolu bahtı açık olsun giderse  Attım belasını gitti başımdan  Bundan sonra gitsin kime isterse Gidiyorsa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nasil-isterse-ben-vazgectim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zordu Mapushane', 'zordu-mapushane-ahmet-bal-4-zn7f3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir senede yalnız üç beş  ay geçtim

Zaman durdu ben zamana gücendim

Yer değişti yön değişti çok değiştim

Çıktım artık bitti anne ben geldim 

Zordu anam zordu zor mapushane

Dumansız alevsiz kor mapushane

Menzili çok uzun   yol mapushane

Bitti artık bitti hasret ben geldim

Saç ağardı baş göğerdi yaşım yok 

Ağlayacak kuru duvar taşım yok

Kolsuz kanatsızım anne başım yok 

Sar ne olur sar boynumu ben geldim', 'Bir senede yalnız üç beş  ay geçtim Zaman durdu ben zamana gücendim Yer değişti yön değişti çok değiştim Çıktım artık bitti anne ben geldim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/zordu-mapushane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kime Ne', 'kime-ne-mehmet-kaya-6-32rww', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağı, taşı, yurdu talan ettiler,

Bam teline vurdu, artık yettiler,

Sofrandan ekmeği çalıp gittiler,

İsyan benim, öfke benim, kime ne!

Türklüğün düşmanı o hain eller,

Terörist başını metheden diller,

Ulusal kimliği bölen sefiller,

Vatan benim, bayrak benim, kime ne!

Zalime baş eğmez, Hak’tır şahidim,

Ölüme gülerek giden şehidim,

Toprağa can veren asil yiğidim,

Ulus benim, millet benim, kime ne!

On bin yıl tarihte şanlı izim var,

İskit’ten Sümer’e kadim sözüm var,

Ali gibi Zülfikar’da özüm var,

Töre benim, iman benim, kime ne!

Ey Kaya! Hak için kaynar bu kanım,

Kırılmaz kalemim, susmaz lisanım,

Bir hilal uğruna fedadır canım,

Yürek benim, destan benim, kime ne!

                          17.11.2026 – M. Kaya', 'Dağı, taşı, yurdu talan ettiler, Bam teline vurdu, artık yettiler, Sofrandan ekmeği çalıp gittiler, İsyan benim, öfke benim, kime ne! Türklü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kaya 6']::text[], 8.5, '{"poet":"Mehmet Kaya 6","poet_slug":"mehmet-kaya-6","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kime-ne-315-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormuyor', 'sormuyor-ahmet-bal-4-ibrbo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşka meşke bakmıyorum unuttum

Zaten yarim arayıpta sormuyor 

Gözlerimin yaşlarını kuruttum

Vicdansız yar merak Edip sormuyor

Kaç baharı kış eyledim zay ettim 

Bir günümü bir dakkayı  ay ettim 

Bu gecede sabahı çok zor ettim 

İnat etmiş arayıpta sormuyor sormuyor 

Hiç aklımdan çıkacağı yok gibi 

Bekle bekle harab ettim kendimi 

Aramazsa yakacağım kendimi 

Merak edip arayıpta sormuyor', 'Aşka meşke bakmıyorum unuttum Zaten yarim arayıpta sormuyor  Gözlerimin yaşlarını kuruttum Vicdansız yar merak Edip sormuyor Kaç baharı kış ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sormuyor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Bırakma', 'sensiz-birakma-ahmet-bal-4-7qvfy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gitmek çözüm değil dur dinle yarim

Ne olursun beni sensiz bırakma

Daha sen gitmeden yandı yüreğim

Ne olursun beni sensiz bırakma

Göze geldik bize değdi nazarlar

Belki de aklını karıştıran var

Bilmez misin sana kara sevdam var

Ne olursun beni sensiz bırakma

Dinle nolur beni bir bak gözüme

Bir hatam var ise söyle yüzüme

Seni deli gibi seveni üzme

Ne olursun beni sensiz bırakma

yaralanırım ben sende kalırım 

Çaresi bulunmaz derde kalırım 

Uzanmaz ellerim yerde kalırım 

Ne olursun beni sensiz bırakma', 'Gitmek çözüm değil dur dinle yarim Ne olursun beni sensiz bırakma Daha sen gitmeden yandı yüreğim Ne olursun beni sensiz bırakma Göze geldik...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-birakma-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnşallah', 'i-nsallah-ahmet-bal-4-hymcq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dilerim düşersin sende çıkmaza 

Geriye dönüşün olmaz inşallah 

Kapansın gittiğin bütün yolların 

 Arayıp  soranın  olmaz inşallah 

Her iki cihanda yakanda elim 

Nasıl başkasına bakar  gözlerin 

Sayende tükendim yoktan beterim 

Seninde yüreğin yanar inşallah 

Yaptığın yanına kalmaz inşallah 

Ben senin uğruna ömrümü verdim

Sendin yar düşlerim  sendin emeğim 

İnsan değilmişsin nerden bileydim

Yaptığın. yanına kalmaz inşallah', 'Dilerim düşersin sende çıkmaza  Geriye dönüşün olmaz inşallah  Kapansın gittiğin bütün yolların   Arayıp  soranın  olmaz inşallah  Her iki c...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/insallah-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O zaman', 'o-zaman-ahmet-bal-4-3fkdv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hele şu dağların dumanı kalksın

Belki yar imana gelir o zaman

Ayrılık ateşi bacayı sarsın 

Belki yar çıkıpta gelir o zaman 

Daha derdi kalmaz çeker gidersem 

Bir gelseydi bari ölmeden görsem 

Ölüyormuş deyip haber göndersem 

Belki yar çıkıpta gelir o zaman 

Kapansın iyileşir  derin yaralar 

Ölüm ara  sıra kapı aralar 

Yakamdan düşseler  bunca belalar 

Belki haber alır  gelir o zaman', 'Hele şu dağların dumanı kalksın Belki yar imana gelir o zaman Ayrılık ateşi bacayı sarsın  Belki yar çıkıpta gelir o zaman  Daha derdi kalma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-zaman-136-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Demedi Derim Çok Çok', 'yar-demedi-derim-cok-cok-ahmet-bal-4-w48fl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben üzülmem  yasın tutmam 

Yar demedi derim çok çok 

Boyun eğme sende gönlüm 

Var  demedi derim çok çok 

Dili Yâryâr dolaşıyor

Kalbi olmadan yaşıyor

Benle gönül eyleşiyor 

Yar demedi derim çok çok

Gideceksen git gidersin 

Olmuyordu bitti dersin 

Hiç tanımam etmem dersin 

Yar demedi derim en çok', 'Ben üzülmem  yasın tutmam  Yar demedi derim çok çok  Boyun eğme sende gönlüm  Var  demedi derim çok çok  Dili Yâryâr dolaşıyor Kalbi olmadan...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-demedi-derim-cok-cok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gelir', 'olum-gelir-hakverdi-ersan-2-jetek', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm gelir yavaş yavaş

İçimi dökecek yok gardaş

Bağrıma bastım her gün taş

Ölüm gelir yavaş yavaş

Ölüm gelir yavaş yavaş

Dört duvar banadır sırdaş

Beden toprak olur yoldaş

Ölüm gelir yavaş yavaş

Dünya hali sorma bana

Bu gün bana yarın sana

Azrail uğrar her cana

Ölüm gelir yavaş yavaş

Ölüm gelir yavaş yanaş

Hayat biter umut bomboş

Dönüşü yok yolum yoldaş

Ölüm gelir yavaş yavaş', 'Ölüm gelir yavaş yavaş İçimi dökecek yok gardaş Bağrıma bastım her gün taş Ölüm gelir yavaş yavaş Ölüm gelir yavaş yavaş Dört duvar banadır ...', ARRAY['Türk Edebiyatı','Şiir','Hakverdi Erşan 2']::text[], 8.5, '{"poet":"Hakverdi Erşan 2","poet_slug":"hakverdi-ersan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olum-gelir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Yeter', 'o-yeter-ahmet-bal-4-jg3nc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatacak bir meselem yok benim 

Bir arınsam şu dertlerden o yeter 

Dünya yansa hiç gözümde yok benim

Bi kurtulsam şu dertlerden  o yeter 

Kin ektirdi kin biçtirdi bağımda 

Kar yağdırdı bana Temmuz ayında 

En deli yıllarım gençlik çağımda 

bir kurtulsam şu hasretten o yeter 

Huzurumu haram etti   o zalim 

 Gelde demem o derece yok halim

 Çok tükendim sana yemin ederim

Ben kurtulsam şu dertlerden o yeter', 'Anlatacak bir meselem yok benim  Bir arınsam şu dertlerden o yeter  Dünya yansa hiç gözümde yok benim Bi kurtulsam şu dertlerden  o yeter  K...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-yeter-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Gibisin', 'herkes-gibisin-ahmet-bal-4-59yd3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sende  bittin sende düştün gözümden 

Benim için artık Herkes gibisin 

Yedi yabancılar  vefalı  senden 

Sende benim için herkes gibisin 

Acınacak hale nasıl acırsam 

Sana yabancıyım ele nasılsam 

Deliliğe vursam artık unutsam

Nasıl olsa sende  herkes gibisin 

Beni senin kadar yakan olmadı

Böyle düşman gibi bakan olmadı 

Sana olan sabrım bitti kalmadı 

(Olmadı sevdiğim bizden olmadı )

Sen gönlümde artık herkes gibisn 

Herkesleştin artık benim gözümde 

Duygusuz bir adam oldum sayende

Öldürdün bu aşkı kanı elinde 

Artık benim için herkes gibisin', 'sende  bittin sende düştün gözümden  Benim için artık Herkes gibisin  Yedi yabancılar  vefalı  senden  Sende benim için herkes gibisin  Acın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/herkes-gibisin-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hedef Tahtasına Döndü Yüreğim', 'hedef-tahtasina-dondu-yuregim-ahmet-bal-4-p4yet', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne hale düşmüşüm   görmeye gelme

Bu kaçıncı  darbe bilmem yediğim

Hançeri vurdular  zaten kalbime 

Hedef tahtasına döndü yüreğim 

Bende zaten her şey  bildiğin gibi 

Değişmedi gitti  kötü kaderim 

Kaç kere kırdılar kırdığın  gibi 

Hedef tahtasına döndü yüreğim 

Kaç kurşun yedim ben kaçıncı yara 

Ayakta durmaya çalışıyorum 

Gönlüme aldığım koydu zarara 

Ben hep sevdiğimle  savaşıyorum

 (Özgür Ata ile Ortak )', 'Ne hale düşmüşüm   görmeye gelme Bu kaçıncı  darbe bilmem yediğim Hançeri vurdular  zaten kalbime  Hedef tahtasına döndü yüreğim  Bende zate...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hedef-tahtasina-dondu-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Schamanismus und der Maßstab der Wahrheit: Eine epistemologische, ontologische und koranzentrierte Kritik', 'schamanismus-und-der-ma-stab-der-wahrheit-eine-epistemologische-ontologische-und-koranzentrierte-kritik-muhammed-ridvan-gizri-kteom', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Der Schamanismus, eine der ältesten Glaubenspraktiken der Menschheitsgeschichte, ist heute nicht mehr nur Gegenstand akademischen Interesses; durch New-Age-Strömungen, Identitätspolitik und eine Welle kultureller Nostalgie hat er neue Popularität erlangt. Insbesondere in türkischen und mongolischen Gesellschaften werden diese Praktiken als „Religion der uralten Ahnen" präsentiert und verdienen eine Kritik, die sowohl religiös als auch philosophisch ernst genommen wird. Wir behandeln den Schamanismus hier nicht als Gegenstand emotionaler oder kultureller Angriffe, sondern als Gegenstand einer grundsätzlichen Untersuchung darüber, wie Wissen, Sein und Autorität legitimiert werden. Die Kritik hat drei Hauptachsen: epistemologische Ungültigkeit, ontologische Inkohärenz und koranzentrierte theologische Unvereinbarkeit.

EPISTEMOLOGISCHE KRITIK: DAS PROBLEM DER WISSENSQUELLE

Erfahrung kann nicht das Maß der Wahrheit sein

Das gesamte Wissenssystem des Schamanismus ruht auf einer einzigen Behauptung: „Ich habe es erlebt, also ist es wirklich." Dieser Satz erscheint auf den ersten Blick plausibel, ist philosophisch jedoch äußerst brüchig. Im Laufe der Geschichte haben Menschen mit unterschiedlichen, oft einander widersprechenden Erfahrungen diese als universelle Wahrheit ausgegeben. Ein christlicher Heiliger sagt, er habe Maria gesehen. Ein hinduistischer Yogi behauptet, Krishna gesehen zu haben. Ein Spiritist gibt vor, mit den Toten zu sprechen. Der sibirische Schamane berichtet, mit den Geistern der Tundra zu verkehren, der Amazonas-Schamane, mit den Wesen des Waldes zu kommunizieren. Alle stehen auf demselben epistemischen Boden: der persönlichen Erfahrung. Erkennen wir diesen Boden als gültig an, bleibt kein übergeordnetes Kriterium mehr, das bestimmen könnte, welche dieser einander widersprechenden Erfahrungen wahr ist. Dann bricht der Wahrheitsbegriff selbst zusammen, und epistemologische Anarchie wird unvermeidlich. Mehr noch: Erfahrung ist nicht ein Beweis für das Sein, sondern lediglich für das Bewusstsein. Im Traum einen Drachen zu sehen, beweist nicht, dass es den Drachen gibt; es beweist nur, dass im Bewusstsein eine Vorstellung entstanden ist. Auch das Sehen von Geistern durch den Schamanen beweist höchstens, dass der Schamane glaubte, Geister zu sehen. Nicht aber die Existenz der Geister.

Eine unfalsifizierbare Aussage ist kein Wissen

Eines der grundlegenden Kriterien der wissenschaftlichen Epistemologie ist die Falsifizierbarkeit. Damit eine Aussage den Status von Wissen erlangen kann, muss sie überprüfbar, beobachtbar und gegebenenfalls widerlegbar sein. Die Aussage „Wasser kocht bei 100 Grad" ist überprüfbar. Die Aussage „Die Erde kreist um die Sonne" ist messbar. Die Aussage „Die Geister haben mir das gesagt" ist jedoch weder überprüfbar noch beobachtbar noch widerlegbar. Darüber hinaus hat das schamanische System einen Fluchtweg hervorgebracht, der den Verifikationsmechanismus selbst aufhebt. Der Schamane macht eine Prophezeiung; tritt sie ein, sagt er: „Die Geister haben die Wahrheit gesprochen." Tritt sie nicht ein, sagt er: „Die Geister waren zornig" oder „Der Glaube der Person hat nicht ausgereicht." Dieser geschlossene Kreislauf immunisiert die Aussage gegen wissenschaftliche Kritik. Doch diese Immunität ist ein Beweis nicht ihrer Stärke, sondern ihrer Schwäche. Jedes System, das einen Wissensanspruch erhebt, muss für Kritik offen sein.

Kulturelle Relativität und universelle Inkonsistenz

Würden Schamanen tatsächlich Zugang zu derselben metaphysischen Sphäre haben, müssten sich die Ergebnisse dieses Zugangs zumindest in den Grundzügen decken. Die Geister, die der sibirische Schamane beschreibt, unterscheiden sich jedoch völlig von denen des Amazonas-Schamanen. Die Wesen der türkischen Kam-Tradition stehen im Widerspruch zu denen des mongolischen Schamanismus. Jeder Stamm sieht die Bilder seiner eigenen Kultur, die Kategorien seiner eigenen Sprache und die Gestalten seiner eigenen Geschichte. Das weist auf etwas höchst Bedeutsames hin: Schamanische Erfahrungen spiegeln keine universelle metaphysische Wirklichkeit wider. Sie sind ein Produkt des kulturellen Unterbewusstseins, des gesellschaftlichen Gedächtnisses und der individuellen Psychologie. Der türkische Schamane sieht die Geister der türkischen Kultur. Der hinduistische Mystiker sieht hinduistische Bilder. Diese Übereinstimmung ist kein Zufall; sie ist der Beweis dafür, dass die Erfahrung die kulturelle Matrix nicht überschreiten kann.

Die Falle des Zirkelschlusses

Die grundlegende Beweisstruktur des Schamanismus ist logisch zirkulär:

- „Es gibt Geister." Was ist der Beweis? „Ich habe sie gesehen." Woher wissen wir, dass du sie gesehen hast? „Weil die Geister mir erschienen sind."

Die Behauptung wird wiederum durch die Behauptung gestützt. Dies ist in der Geschichte der Logik als *petitio principii* bekannt, ein Fehlschluss, bei dem die Schlussfolgerung bereits in der Prämisse verborgen ist. Der Schamanismus kann keinen unabhängigen Beweis anbieten, der aus diesem Zirkel herausführt.

ONTOLOGISCHE KRITIK: DAS PROBLEM DER GRUNDLAGE DES SEINS

Das Problem des unendlichen Regresses

Der Schamane sagt: „Der Geist hat mir dieses Wissen gegeben." Doch wer hat es dem Geist gegeben? Ein anderer Geist. Wer hat es diesem gegeben? Wieder ein anderer Geist. Diese Kette setzt sich ins Unendliche fort. In der Philosophie nennt man dieses Problem den unendlichen Regress, und es ist für jedes Erklärungssystem fatal. Eine Wissens- oder Seinskette muss auf eine letzte Quelle zurückgehen, die sich selbst erklärt. Andernfalls hängt das System in der Luft. Der Schamanismus kann diese letzte Quelle nicht benennen. Geister beruhen auf anderen Geistern, diese auf weiteren Geistern, doch nirgends lässt sich die unerklärte erste Quelle aufzeigen. Der Koran dagegen gibt auf dieses Problem eine klare Antwort: Die Quelle allen Seins ist Allah, der selbst ohne Ursache ist. „Die Entscheidung liegt allein bei Allah." (Yusuf, 40) Dies ist eine philosophisch konsistente ontologische Grundlage; die offene Geisterkette des Schamanismus ist es nicht.

Die Falle des Anthropomorphismus

In schamanischen Erzählungen sprechen Geister, zürnen, lieben, wollen und weisen den Weg. Sie handeln also mit allen Kategorien der menschlichen Psychologie. Das ist äußerst auffällig. Warum ähneln Wesen, die angeblich in den Tiefen des Universums existieren, dem Charakter eines Menschen und nicht dem eines Elektrons? Warum spiegeln sie nicht die Struktur einer Galaxie, sondern die Autorität eines Stammesältesten wider? Die Antwort lautet: Diese Wesen wurden nicht von außen beobachtet, sondern von innen hervorgebracht. Der menschliche Geist entwirft ein Universum, indem er sich selbst zum Bezugspunkt nimmt. Der Schamanismus erklärt nicht das Universum; er spiegelt das Verlangen des Menschen wider, sich selbst in den Mittelpunkt des Universums zu stellen. Dies zeigt, dass der Schamanismus in seinem Kern einen tiefen humanistischen Narzissmus enthält. Bei einem 13,8 Milliarden Jahre alten Universum, hunderten Milliarden Galaxien und Billionen von Sternen ist es mit epistemischer Bescheidenheit unvereinbar, dass die gesamte Metaphysik um einen kleinen zentralasiatischen Stamm kreist.

Das Subjekt-Objekt-Paradoxon

Der Schamane befindet sich in einem geschlossenen System, in dem Beobachter und Beobachtetes zugleich dasselbe sind. Er ist es, der die Erfahrung macht, er ist es, der sie deutet, und er ist es, der sie als wahr bestätigt. Einen unabhängigen externen Kontrollmechanismus gibt es nicht. Dies ist zugleich der deutlichste Hinweis auf wissenschaftliche Ungültigkeit und epistemologische Unsicherheit. Damit Wissen verlässlich sein kann, bedarf es einer vom Subjekt unabhängigen Bestätigungsgrundlage. Im Schamanismus fehlt diese Grundlage. Das System ist ein in sich geschlossenes Spiegelkabinett; jede Spiegelung bestätigt die vorherige, doch hinter keiner steht eine wirkliche Quelle.

Ockhams Rasiermesser

Die Geisterfahrung des Schamanen lässt sich auch auf einfachere, ökonomischere Weise erklären. Unterbewusste Prozesse, symbolisches Denken, kulturelle Konditionierung, Gedächtniskonsolidierung und neurologische Mechanismen genügen, um die Erfahrungen zu erklären, die der Schamane nach eigener Aussage macht. Nach dem in der Philosophie als Ockhams Rasiermesser bekannten Prinzip ist es überflüssig, zur Erklärung eines Phänomens zusätzliche Annahmen hinzuzufügen. Der Begriff der „Geister" verleiht dem Schamanismus keine Erklärungskraft; er macht die Erklärung lediglich komplizierter.

NEUROLOGISCHE UND PSYCHOLOGISCHE KRITIK: DAS GEHIRN SPIELT SICH SELBST

Die neuronale Grundlage des Trancezustands

Die moderne Neurowissenschaft hat den Trancezustand der Schamanen umfassend untersucht. Lang anhaltender Trommelrhythmus, insbesondere Theta-Wellen im Bereich von 4–7 Hz, stimuliert das limbische System des Gehirns und löst die Freisetzung von Endorphinen und Dopamin aus. Hinzu kommen Hypoxie (Sauerstoffmangel), intensive körperliche Rituale, Hunger und Erschöpfung, die die Hirnaktivität tiefgreifend verändern. In diesem veränderten Bewusstseinszustand kann das Gehirn seine eigenen inneren Signale als äußere Wesen wahrnehmen. Die Aktivierung des Temporallappens erzeugt Erfahrungen von „Anwesenheit" und des „Übergangs in eine andere Dimension". Die Unterdrückung des Default-Mode-Netzwerks (DMN) hebt die Grenzen des Selbst auf und vermittelt das Gefühl der „Vereinigung mit dem Universum". All diese Prozesse sind neurologisch dokumentiert, wiederholbar und ohne übernatürliches Eingreifen erklärbar. Der Schamane lauscht seinem eigenen neuronalen Rauschen und hält es für Offenbarung. Das unterscheidet sich epistemologisch nicht vom Fall eines Patienten, der sein Ohrensausen für eine Engelsstimme hält.

Placebo-Effekt und Heilungsanspruch

Dass die Rituale der Schamanen in einigen Fällen eine heilende Wirkung zeigen, wird häufig als Beleg für eine übernatürliche Kraft angeführt. Dieser Effekt lässt sich jedoch durch einen in der Medizin äußerst gut dokumentierten Mechanismus erklären, den Placebo-Effekt. Der starke Glaube des Patienten an die Genesung kann das Immunsystem und die Selbstheilungsmechanismen des Körpers aktivieren. Psychische Entlastung kann tatsächlich nützlich sein; das bestätigt jedoch die metaphysischen Behauptungen des Schamanen nicht. Dass eine Praxis einem Menschen guttut, beweist nicht ihre Seinsbehauptungen. Hinzu kommt: Bei echten organischen Erkrankungen hat die Unzulänglichkeit schamanischer Eingriffe tragische Folgen gehabt. Dass ein Patient mit Lungenentzündung oder Krebs, während der Schamane die Trommel schlägt, von echter Behandlung ferngehalten wurde, gehört zu den stillen, aber schwerwiegenden menschlichen Kosten der Geschichte.

Die Täuschbarkeit des menschlichen Geistes

Der menschliche Geist ist außerordentlich leicht zu täuschen. Die moderne Kognitionswissenschaft hat uns gezeigt: Der Mensch kann nichtmenschliche Gesichter sehen, nicht vorhandene Stimmen hören, falsche Erinnerungen bilden, Traum und Wirklichkeit verwechseln und unter Hypnose falsche Erinnerungen erzeugen. Dass eine Erfahrung äußerst stark und wirklich erscheint, zeigt nicht, dass ihr ein objektives Gegenstück entspricht. Der Schamanismus verwandelt genau diese Fragilität in eine strukturelle Autoritätsquelle. Die Aussage „Ich habe es gesehen" erhält eine unantastbare Stellung. Doch eine der größten philosophischen Entdeckungen der Menschheit lautet: Das Erscheinende und das Wirkliche decken sich nicht immer. Die Sonne scheint sich zu bewegen, in Wahrheit dreht sich die Erde. Materie erscheint fest, ist aber größtenteils leerer Raum. Die Aussage „Ich habe es gesehen, also ist es wirklich" ist im Laufe der Geschichte immer wieder widerlegt worden.

KORANZENTRIERTE THEOLOGISCHE KRITIK

Die Ausschließlichkeit des Wissens vom Verborgenen (Ghaib)

Nach dem Koran gehört das Wissen über die unsichtbare Welt allein Allah: „Sprich: Keiner in den Himmeln und auf der Erde kennt das Verborgene außer Allah." (Naml, 65) Dies ist nicht bloß eine theologische Vorliebe, sondern eine epistemologische Grenzlinie. Der Mensch kann auf der Grundlage seiner individuellen Erfahrung kein sicheres Urteil über die unsichtbare Welt fällen. Dass der Schamane Behauptungen über das Verborgene aufstellt, verletzt nach dem Koran dieses Prinzip unmittelbar. In diesem Rahmen ist die Annahme, die Wesen, mit denen der Schamane nach eigener Aussage kommuniziert, seien eine verlässliche Wissensquelle, aus koranischer Sicht unbegründet.

Tauhid und das Problem der Vermittlung

Im Schamanismus umfassen Konzepte wie Bergegeister, Flussgeister, Ahnengeister und Schutzwesen auch das Darbringen von Opfergaben an diese Wesen, ihre Verehrung und die Bitte um Hilfe. Funktional bedeutet dies, zwischen den Menschen und Allah unsichtbare Vermittler zu stellen. Genau dies ist auch die grundlegendste Kritik, die der Koran an den Götzendienern von Mekka übt: Auch sie benutzten Geschöpfe als Vermittler. Dieser Aspekt des Schamanismus kann daher als andere Form des historischen Götzendienstes bewertet werden. Statt einer Steinfigur ein unsichtbarer Geist; die Praxis hat sich geändert, die Struktur blieb dieselbe.

Der Erkenntniswert mystischer Erfahrung

Der Koran warnt die Menschen vor Träumen, Einbildungen und bloßen Mutmaßungen. Dass eine Erfahrung gemacht wurde, bedeutet nicht, dass sie wirklich ist. Im Koran sind die Maßstäbe der Wahrheit die Offenbarung, die Vernunft und die Zeichen (Ayat) Allahs; nicht die individuelle mystische Erfahrung. Daher kann die Trance-Erfahrung des Schamanen aus Sicht der koranischen Epistemologie keinen Status als verlässliche Wissensquelle erlangen. Der Koran macht außerdem deutlich, dass Verstorbene nicht in das diesseitige Leben zurückkehren können und dass es für die Erwartung von Hilfe von Ahnengeistern keine koranische Grundlage gibt. Die Quelle der Rechtleitung ist Allah und Seine Offenbarung; nicht Ahnenkulte.

KULTURELLE UND HISTORISCHE KRITIK

Der Mythos der „uralten türkischen Religion"

Der Schamanismus wird mitunter als ursprüngliche und reine religiöse Identität der Türken dargestellt. Dieser Ansatz ist historisch problematisch. Die Türken haben in ihrer Geschichte nie ein einziges, reines Glaubenssystem besessen. Im Verlauf von den Göktürken über die Seldschuken bis zu den Osmanen haben sich Buddhismus, Manichäismus, Zoroastrismus, Islam und verschiedene lokale Praktiken miteinander vermischt. Zudem ist der Schamanismus weniger eine „Religion" als ein Bündel von Praktiken, die auf Geisterkommunikation, Heilung, Weissagung und Naturkulten beruhen. Er hat keinen kohärenten Text, keine systematische Theologie und keine universelle Morallehre. In den historischen Quellen ist auch festgehalten, dass Kams in politischen Machtkämpfen instrumentalisiert wurden und zuweilen Scharlatanerie-Vorwürfen ausgesetzt waren. Moderne Neo-Schamanen wiederum bieten eine Version an, die mit New-Age-Strömungen, Yoga und kommerziellen Workshops vermengt ist; ihre Verbindung zur traditionellen sibirischen Kam-Tradition ist begrenzt.

Der Schamanismus und die Zerstörung des Islam

Dass schamanistische Elemente in den Islam eingefügt wurden, hat in türkischen Gemeinschaften ein ernstes religiöses Problem geschaffen. Herdkulte (Ocak-Traditionen), Grabbesuche, der Glaube an die Verfügungsgewalt der Toten, einige sufische Rituale und magische Praktiken in der Volksmedizin sind Elemente, deren Wurzeln in der schamanistischen Tradition liegen. Dieser Synkretismus hat dazu geführt, dass mit dem Tauhid-Prinzip unvereinbare Glaubensvorstellungen und Praktiken unter der Identität des Islam legitimiert wurden. Eine ähnliche Tendenz lässt sich auch in einigen Zweigen des Sufismus beobachten. Die strukturelle Ähnlichkeit der Sema-Rituale mit der Trancepraxis, Grabbesuche, die Vorstellung der Vermittlung durch Heilige in einigen alevitisch-bektaschitischen Traditionen und der Glaube an die „Verfügungsgewalt der Toten" sind Punkte der Abweichung vom ursprünglichen Tauhid-Prinzip des Islam.

Die Frage der zivilisatorischen Produktivität

In der Geschichte hat keine schamanistische Gesellschaft ein bahnbrechendes Wissenssystem in Mathematik, Astronomie, Medizin oder Ingenieurwesen hervorgebracht. Der Schamanismus löst Probleme nicht, sondern verweist sie an die Magie; für Regen wird getanzt, bei Krankheit werden Geister beschworen, bei Hungersnot wird geopfert. Doch die Gesellschaft, die ein Abwassersystem baute, hat die Gesellschaft, die Regentänze aufführte, im historischen Wettbewerb überholt. Wenn Schamanen tatsächlich Wissen aus anderen Dimensionen empfingen, müsste dieses Wissen in der Menschheitsgeschichte mindestens ein messbares, überprüfbares und nützliches Ergebnis hervorgebracht haben. Kein Schamane hat das Datum eines Meteoriteneinschlags berechnet, kein Schamane die Quelle einer Epidemie ermittelt, kein Schamane ein ungelöstes mathematisches Problem beantwortet. Diese Leere deutet darauf hin, dass nicht der Inhalt des Anspruchs, sondern seine Quelle problematisch ist.

AUTORITÄT UND DAS PROBLEM DER KONTROLLE

Unhinterfragbare Autorität

Die Autorität des Schamanen beruht auf einer Quelle ohne Verifikationsmechanismus: seiner eigenen Erfahrung. Wer kann feststellen, dass das, was der Schamane sagt, falsch ist? In der Regel niemand. Denn die einzige Quelle des Wissens ist die eigene Erfahrung des Schamanen. Diese Struktur verleiht dem Schamanen eine unhinterfragbare Autorität und ist in der Geschichte systematisch missbraucht worden. Der Schamane hat sich mit seiner auf übernatürliche Kräfte gestützten Autorität die besten Ressourcen des Stammes angeeignet; diese Aneignung wurde als „heilig" legitimiert.

Innerer Widerspruch und Wahrheitskrise

Zwei Schamanen können mit derselben Methode zu gegensätzlichen Ergebnissen gelangen. Dem Schamanen, der sagt: „Die Geister haben mir dies gesagt", kann ein anderer Schamane entgegnen: „Die Geister haben genau das Gegenteil gesagt." Dem Schamanismus fehlt ein gemeinsamer und objektiver Maßstab, der diesen Widerspruch auflösen könnte. Das System ist einer in sich unlösbaren Verifikationskrise ausgeliefert. Wahrheit wird nicht durch einen universellen Maßstab, sondern durch die individuelle Erfahrung des Schamanen bestimmt. Das aber tötet die Wahrheit.

DER MASSSTAB DER WAHRHEIT

Das grundlegende Problem des Schamanismus liegt nicht im Inhalt seiner einzelnen Rituale, sondern in der Methode, mit der er zu Wissen gelangt. Der Schamanismus setzt voraus, dass das menschliche Bewusstsein die Befugnis besitzt, die Wahrheit auszulegen. Doch eine der wichtigsten Lehren der Menschheitsgeschichte lautet: Das Bewusstsein ist nicht der verlässlichste Schiedsrichter. Der Mensch kennt seinen Zustand vor der Geburt nicht. Er kennt das Danach des Todes nicht. Er kennt das Wesen des Bewusstseins nicht. Er kennt die Natur der Zeit nicht. Dass ein so begrenztes Wesen aufgrund einer wenige Stunden dauernden Trance-Erfahrung endgültige Urteile über die unsichtbaren Schichten des Universums fällt, gleicht einem Menschen, der nie eine Landkarte gesehen hat und dennoch die Koordinaten aller Kontinente einzeichnen will. Und dieser Irrtum ist die gemeinsame Krankheit aller mystischen Systeme, aller Zeitalter und aller Regionen. Wahrheit wird nicht an ihrem Alter und nicht an der Intensität der Erfahrung gemessen, sondern daran, dass sie sich auf Beweise stützt.', 'Der Schamanismus, eine der ältesten Glaubenspraktiken der Menschheitsgeschichte, ist heute nicht mehr nur Gegenstand akademischen Interesses...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/schamanismus-und-der-ma-stab-der-wahrheit-eine-epistemologische-ontologische-und-koranzentrierte-kritik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni nasıl Vurdun Öyle', 'beni-nasil-vurdun-oyle-ahmet-bal-4-uquux', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kirpiğini oynatmadan 

beni nasıl vurdun öyle 

Hiçbir silah kullanmadan 

Beni nasıl vurdun söyle 

Yara aldım ve  yerdeydim 

Kurtulurdum gitmeseydin 

Birazcık can çekişseydim 

Beni nasıl vurdun öyle 

Tesellimdin inanmıştım 

Yalnız sana bağlanmıştım 

Senden sonra dağılmıştım 

Beni nasıl vurdun öyle …

Bir çaresi varsa söyle 

Yaralandım kaldım yerde 

Bir sözünle tek heceyle 

Beni nasıl vurdun öyle', 'Kirpiğini oynatmadan  beni nasıl vurdun öyle  Hiçbir silah kullanmadan  Beni nasıl vurdun söyle  Yara aldım ve  yerdeydim  Kurtulurdum gitme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/beni-nasil-vurdun-oyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aradım', 'seni-aradim-ahmet-bal-4-ythm0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben aşkı gönlüme esir etmedim 

Her  tutuk yürekte  seni aradım 

Çok acı çekerken çekip gitmedim 

Verdiğim emekte seni aradım 

Aradım aranmaz yerde aradım 

Ahde vefa denen yerde aradım 

Ben seni sayılı günde aradım 

Ağlayıp gülmekte seni aradım 

Yaşayıp ölmekte seni aradım 

Bütün dar sokakta kayıp adreste 

İçtiğim sularda taze çiçekte 

Kara gecelere doğan güneşte 

Ben kalıp gitmekte seni aradım', 'Ben aşkı gönlüme esir etmedim  Her  tutuk yürekte  seni aradım  Çok acı çekerken çekip gitmedim  Verdiğim emekte seni aradım  Aradım aranmaz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-aradim-173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmazlara vurulmuşum', 'olmazlara-vurulmusum-ahmet-bal-4-w1ri1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olmazlara vurulmuşum 

Sorma nasıl yıkılmışım 

Ne varmışım ne yokmuşum 

Senden sonra ben 

Senden sonra ben 

Ahtımı yıktı kader 

Dilim dilim ayırdı ya 

Düşene kim neder 

Can bedenden ayrıldı ya 

Olmazlara vurulmuşum 

Görme beni dağılmışım 

Bir yalana inanmışım 

Senden sonra ben 

Senden sonra ben', 'Olmazlara vurulmuşum  Sorma nasıl yıkılmışım  Ne varmışım ne yokmuşum  Senden sonra ben  Senden sonra ben  Ahtımı yıktı kader  Dilim dilim a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/olmazlara-vurulmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yardan razıyım', 'yardan-raziyim-ahmet-bal-4-rb7nr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her ne kadar beni üzmüş olsada 

Helalleştim ben o yardan razıyım 

Dertleri üst üste  dizmiş olsada 

Helalleştim ben o yardan razıyım 

Razıyım ben ondan zalimde  olsa

Ben razıyım ondan dertlere  koysa

Çıkartıp kalbimi  yerlere  vursa 

Helalleştim ben o yardan razıyım

Sarılıp ağlaştım  gitmeden önce 

Bu büyük aşkımız bitmeden önce 

Hayatımı zehir etmeden önce

Helalleştim ben o yardan razıyım

Her ne kadar beni üzmüş olsada 

Helalleştim ben o yardan razıyım 

Dertleri üst üste  dizmiş olsada 

Helalleştim ben o yardan razıyım 

Beni kurşunlara dizmiş olsada 

Helalleştim ben o yardan razıyım 

Razıyım ben ondan zalimde  olsa

Ben razıyım ondan dertlere  koysa

Çıkartıp kalbimi  yerlere  vursa 

Helalleştim ben o yardan razıyım

Beklemem ardıma düşmesin elbet 

Dayan ey  yüreğim birazcık sabret

Nasibim değilmiş  gerisi  kısmet 

Helalleştim ben o yardan razıyım 

Razıyım ben ondan canı sağolsun 

Zaten dağılmışım  o mutlu olsun 

 aklına gelmesin varsın unutsun 

Helalleştim ben de ondan razıyım 

Sarılıp ağlaştım  gitmeden önce 

Bu büyük aşkımız bitmeden önce 

Hayatımı zehir etmeden önce

Helalleştim ben o yardan razıyım', 'Her ne kadar beni üzmüş olsada  Helalleştim ben o yardan razıyım  Dertleri üst üste  dizmiş olsada  Helalleştim ben o yardan razıyım  Razıyı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yardan-raziyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorsun', 'bilmiyorsun-ahmet-bal-4-0rps5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben o zalim yar yüzünden 

Neler çektim bilmiyorsun 

Hayır görmedim ömrümden

Neler çektim bilmiyorsun 

Çok vicdansız  vurdu kaçtı 

Sabır  desen  doldu taştı

Felek gibi  kırdı geçti 

Neler çektim bilmiyorsun 

Bir canım var o götürdü 

Yedi ömrümü bitirdi 

Bir gülseydi o yeterdi

Neler çektim bilmiyorsun', 'Ben o zalim yar yüzünden  Neler çektim bilmiyorsun  Hayır görmedim ömrümden Neler çektim bilmiyorsun  Çok vicdansız  vurdu kaçtı  Sabır  des...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmiyorsun-148-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ablamın Yokluğu', 'ablamin-yoklugu-serpil-ersoy-zumruduanka-oc0qz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonra sen uyudun…

‎Ben bir daha uyanamadım yokluğuna.

‎Aldım başımı gidiyorum,

‎Yalnız başıma,

‎Yalın ayak raylarda…

‎

‎Bir tren düdüğü çaldı uzaklardan,

‎İrkilip durdum bir an.

‎Sanki sesin geldi sandım,

‎Sanki dönecekmişsin gibi ardından…

‎

‎Sana gelmeliydim ablam,

‎Yokluğun öyle ağır, öyle acı ki…

‎Her adımda biraz daha eksiliyorum,

‎Ama ısrarla yürümeye devam ediyorum,

‎Yalın ayak, kırık dökük hayallerle…

‎

‎Sen bana yokluğunu bıraktın ablam,

‎Ben hangi yüreğe sığdırayım bu acıyı?

‎Hangi geceye anlatayım özlemimi,

‎Hangi sabaha uyandırayım sensizliğimi?

‎

‎Biliyor musun ablam,

‎İnsan bazen bir ömür konuşmak ister de

‎Bir tek kelime edemez.

‎Adını anarken boğazına düğümlenir dünya,

‎Gözlerinden sessizce bir ömür dökülür.

‎

‎Ben senin ardından

‎Ne vedalaşmayı becerebildim

‎Ne de yokluğuna alışmayı…

‎Her gece ellerimi açıp Yaradan''a sığındım,

‎Seni özlemekten başka ne gelirdi elimden?

‎

‎Şimdi hangi yöne dönsem sen yoksun,

‎Hangi anıya dokunsam izin var.

‎Bir yanım hâlâ sana gelmek ister,

‎Bir yanım sensiz yaşamayı öğrenmeye çalışır.

‎

‎Ablam…

‎Sen gittin, zaman yürümeye devam etti,

‎Ama benim içimde bir gün hep yarım kaldı.

‎Sensizliğe konuşmaktan yoruldum

‎Ve ben hâlâ o rayların üzerinde,

‎Yalın ayak, gözlerimde yaş,

‎Sana kavuşamamanın özlemiyle

‎Yürüyorum…

‎Yürüdükçe sana değil,

‎Sensizliğine varıyorum.

‎

‎

‎Not...Ablama duyulan özlemim... Çok özledim seni mekanın cennet olsun Abla

‎', 'Sonra sen uyudun… ‎Ben bir daha uyanamadım yokluğuna. ‎Aldım başımı gidiyorum, ‎Yalnız başıma, ‎Yalın ayak raylarda… ‎ ‎Bir tren düdüğü çald...', ARRAY['Türk Edebiyatı','Şiir','Serpil Ersoy Zümrüdüanka']::text[], 8.5, '{"poet":"Serpil Ersoy Zümrüdüanka","poet_slug":"serpil-ersoy-zumruduanka","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ablamin-yoklugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyhude', 'beyhude-aydin-ahmet-megvv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aldanma dünya malına 

Hepsi beyhude değil mi?

Sanma sararlar salına

Hepsi beyhude değil mi?

Karun olsan kime kalır

Sultanlar da bir gün ölür

Bin sene yaşasan n’olur?

Hepsi beyhude değil mi?

Çare değil ilaç merhem

Ömür biter dirhem dirhem

Zerrece yok buna şüphem

Hepsi beyhude değil mi?

Salacağa bineceksen 

Bir çukura ineceksen

Eyvah deyip yanacaksan

Hepsi beyhude değil mi?

Fayda değil evlat torun

Ölüm gelir bugün yarın

Ecirden öte yok kârın

Hepsi beyhude değil mi?

Servetinle övünsen de

Mala mülke sevinsen de

Seksen sene avunsan da

Hepsi beyhude değil mi?

Şu dünyada ölüm varken

Sanma daha vakit erken

Kazandım kaybettim derken

Hepsi beyhude değil mi?

Ozan Ahmet dünya yalan

Gün tükendi ömür talan

Var mı burda baki kalan

Hepsi beyhude değil mi?', 'Aldanma dünya malına  Hepsi beyhude değil mi? Sanma sararlar salına Hepsi beyhude değil mi? Karun olsan kime kalır Sultanlar da bir gün ölür...', ARRAY['Türk Edebiyatı','Şiir','Aydın Ahmet']::text[], 8.5, '{"poet":"Aydın Ahmet","poet_slug":"aydin-ahmet","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/beyhude-182-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken', 'sen-yokken-ahmet-bal-4-5x914', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana zemheriyi tattırdı hayat 

Eriyip tükendim bittim sen yokken 

Her Neyim varsa batırdım işte 

Çektim   kapıları gittim sen yokken 

Derdini başımın tacı eyledim 

Yıllarca kendime yalan  söyledim

Yemin verdim başka yari sevmedim 

Aşka inancımı yıktım sen yokken 

Yine kadehlerden kalkmadı başım 

Yastığıma düştü aktı gözyaşım

Ziyan oldu benim onca uğraşım 

Gün be gün eriyip bittim sen yokken 

Ben her gün eriyip bittim sen yokken', 'Bana zemheriyi tattırdı hayat  Eriyip tükendim bittim sen yokken  Her Neyim varsa batırdım işte  Çektim   kapıları gittim sen yokken  Derdin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-yokken-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyi Gelecek', 'i-yi-gelecek-ahmet-bal-4-qtozs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Söylemeye dilim varmıyor ama 

Galiba sensizlik iyi gelecek 

Oturdum kendimi çektim hesaba 

Galiba  sensizlik iyi gelecek 

Belkide sensizlik iyi gelecek 

Bir süre ayrılık iyi gelecek 

Gözlerin sevdayla bakmıyor gibi

Bir şeyler kemirir durur içimi 

Bilirsin  sen beni ve hislerimi 

Bir süre ayrılık iyi gelecek 

Yanımda gibisin  aslında  yoksun 

Neyse aradığın belki bulursun 

Hayırlısı neyse isterim olsun 

Bir süre ayrılık iyi gelecek', 'Söylemeye dilim varmıyor ama  Galiba sensizlik iyi gelecek  Oturdum kendimi çektim hesaba  Galiba  sensizlik iyi gelecek  Belkide sensizlik ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iyi-gelecek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahmur Gözlüm Günaydın', 'mahmur-gozlum-gunaydin-ahmet-bal-4-uyzxa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kaç uyurum diye günler mi saydın

Uyandın mı mahmur gözlüm günaydın 

Ben bir hafta isem sen buçuk aydın 

Uyandın mı mahmur gözlüm günaydın

Sen kara  dünyamın çiçekli bağı

Seni güzellerin  şahı sultanı 

Ayın yeryüzüne vuran şafağı

Uyandın mı kızıl goncam günaydın

Uyanıp uyumak öyle yakışır

Gündüzler yarime biraz zor yetişir

Uykuna birazcık nazın karışır

Seni güzellikler Şah-ı günaydın

Seni güzellerin  şahı günaydın', 'Kaç uyurum diye günler mi saydın Uyandın mı mahmur gözlüm günaydın  Ben bir hafta isem sen buçuk aydın  Uyandın mı mahmur gözlüm günaydın Se...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mahmur-gozlum-gunaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Düşer', 'yasamak-duser-ahmet-bal-4-zw4dn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasretim sığmıyor bak dört duvara

Gözlerim kan  ağlar İçimde yara 

Bir bela yüzünden düştüm zindana 

Yazan yazmış bana yaşamak düşer 

Tükeniyor sabrım taştı taşacak 

Belkide hasretin sonum olacak 

Ben Yapsam  ne olur kader  yıkacak

Yazan yazmış bana yaşmak düşer 

Yaşanan yaşandı bakmam ardına 

İnsanların  çok geç vardım farkına 

Zaten umutlarım kaldı yarına 

Yazan yazmış bana yaşamak düşer', 'Hasretim sığmıyor bak dört duvara Gözlerim kan  ağlar İçimde yara  Bir bela yüzünden düştüm zindana  Yazan yazmış bana yaşamak düşer  Tükeni...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasamak-duser-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep İçime Dert atmaktan', 'hep-i-cime-dert-atmaktan-ahmet-bal-4-ro6zc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan içine çıkmıyom 

Ben içime dert atmaktan

Hiç kimseyle  konuşmuyom

Hep içime dert atmaktan 

Kendim ile  çok ağlaştım 

Bi küs kaldım  bir barıştım 

Sensizliğe zor alıştım 

Hep içime dert atmaktan

Benim  derdim hep benmişim 

Ele bahane bulmuşum 

Yüzüm asılı kalmışım 

Hep içime dert atmaktan 

Ağlatıldım bizar oldum 

Yarlardan sızar oldum 

İki metre mezar oldum 

Hep içime dert atmaktan .', 'İnsan içine çıkmıyom  Ben içime dert atmaktan Hiç kimseyle  konuşmuyom Hep içime dert atmaktan  Kendim ile  çok ağlaştım  Bi küs kaldım  bir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hep-icime-dert-atmaktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkar mı sandın', 'yikar-mi-sandin-ahmet-bal-4-mve83', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben Aşkı felekten yara almışım 

Senin bu gidişin yıkar mı sandın 

Gözümün yaşını kendim silmişim 

Uğruna  bir damla akar mı sandın ? 

Ne Bağışla beni nede af dile 

Gönlümün sultanı olsan nafile 

Acı çeke çeke unutsam bile 

Beni ayrılıklar yıkar mı sandın 

Ne umardım neler buldu bahtımı 

Her şey üst üsteydi zorlar aklımı 

  Seninle yitirdim bütün şansımı 

Bundan sonra seni takar mı sandın 

Gönlüm  ardın sıra bakar mı sandın

Ne bağışla nede benden şans dile 

Sen başımın tacı olsan nafile 

Hıçkıra hıçkıra ağlasam bile 

Beni ayrılıklar yıkar mı sandın', 'Ben Aşkı felekten yara almışım  Senin bu gidişin yıkar mı sandın  Gözümün yaşını kendim silmişim  Uğruna  bir damla akar mı sandın ?  Ne Bağ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yikar-mi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Diye Dünyayı Dert Edeyim', 'ne-diye-dunyayi-dert-edeyim-ahmet-bal-4-8i4hx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün yaşıyorum yarın meçhulüm

Ne diye dünyayı dert edeyim ki 

Haktan ne geldiyse hepsi kabulüm 

Ne diye dünyayı dert edeyim ki 

Yanlış bir adreste yanlış yerdeyim 

Dönüş niyetim yok umut vermeyin 

Beni kınamayın horda  görmeyin

Ben niye dünyayı dert edeyim ki 

Kimler gelip kimler geçti bu handan

Bende bir haberim kayıp zamandan 

Ömürde su gibi aktı bir yandan 

Ne diye dünyayı dert edeyim ki 

Benim Söylenecek sözüm bitmişken

Kalır dediklerim çekip gitmişken 

Artık buralarda işim bitmişken 

Ne diye dünyayı dert edeyimki .. 

Her bir derdim  bana derdi andırdı 

Yarim dediklerim zaten kandırdı 

Hergün Ecelime  günler saydırdı 

Ben niye dünyayı dert edeyimki', 'Bugün yaşıyorum yarın meçhulüm Ne diye dünyayı dert edeyim ki  Haktan ne geldiyse hepsi kabulüm  Ne diye dünyayı dert edeyim ki  Yanlış bir ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-diye-dunyayi-dert-edeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitsin Hasret', 'bitsin-hasret-ahmet-bal-4-5sr93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Madem ayrı yaşanmıyor

Çık gel bari bitsin hasret

Benim gönlüm uslanmıyor

Sen  gel bari bitsin hasret 

Zaten dertler aştı boydan

Vazgeçmedin sen bu Huydan

Zincirlendim iki koldan 

Gel çöz bari hasret bitsin 

 Bitsin hasret bitsin hasret 

Hadi dön gel bitsin hasret 

Öyle özledimki  seni 

Bitir artık bitsin hasret 

Yetmedimi  yaşattığın 

Tak etti bak  ayrılığın 

Sensiz herşey  darmadağın 

Çık gel hadi bitsin hasret', 'Madem ayrı yaşanmıyor Çık gel bari bitsin hasret Benim gönlüm uslanmıyor Sen  gel bari bitsin hasret  Zaten dertler aştı boydan Vazgeçmedin ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bitsin-hasret-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter Ol', 'beter-ol-ahmet-bal-4-rv8c7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen bu sevdalara layık değilsin 

Alına satıla puldan beter ol 

Düş kara sevdaya gez diyar diyar 

Mecnun denen kuldan daha beter ol 

Ol benden beter daha beter ol 

Kalp ile taşınmaz yükü çeker ol 

Haram  olsun sana ne hakkım varsa 

Bana bir yabancı elden beter ol 

Gönlümde bir koca cihandın bittin 

Kimlerin  sözüne inandın gittin 

Çok bile dayandım   çok sabır çektim 

Sende bu halinden daha beter ol', 'Sen bu sevdalara layık değilsin  Alına satıla puldan beter ol  Düş kara sevdaya gez diyar diyar  Mecnun denen kuldan daha beter ol  Ol bende...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beter-ol-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm', 'gonlum-ahmet-bal-4-ipb2h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani söz vermiştin ağlamak yoktu 

Sellere meydan mı  okudun gönlüm

Gidene umutlar bağlamak yoktu 

Feleğin canına okudun  gönlüm 

Ben yarin  yüzünü  Düşlerim ansız 

Yaktı yüreğimi yaktı vicdansız 

Daha kavuşmamız yasak imkansız 

Benimde canıma okudun gönlüm 

Kimseler görmeden ayrılacaktık 

Bu Sevda derdinden kurtulacaktık

Elveda etmeden ayrılacaktık 

Feleğin canına okudun gönlüm', 'Hani söz vermiştin ağlamak yoktu  Sellere meydan mı  okudun gönlüm Gidene umutlar bağlamak yoktu  Feleğin canına okudun  gönlüm  Ben yarin  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gonlum-343-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteyen namert', 'i-steyen-namert-ahmet-bal-4-93mxp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim her bir anım seninle dolu 

Kaybolup gitmesin zamanı beklet 

Galiba ayrılık ölümden zoru 

Senden ayrı bir yar isteyen namert 

Adın  düğüm düğüm hecelerimde 

Sensizlik bir ölüm gecelerimde 

Sana yalan  yere yemin etsemde 

Senden ayrı bir yar isteyen namert 

Yalanım yok sana yemin ederim 

Eğer sevmiyorsan çekip giderim 

Ben seni sevmişim seni bilirim

Senden ayrı bir yar isteyen namert', 'Benim her bir anım seninle dolu  Kaybolup gitmesin zamanı beklet  Galiba ayrılık ölümden zoru  Senden ayrı bir yar isteyen namert  Adın  düğ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isteyen-namert-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Geldin Bana', 'niye-geldin-bana-ahmet-bal-4-dcgs1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ne hayırsız yarmışsın 

Demeyemi geldin bana 

Unutmadım aklımdasın

Demeye mi geldin bana 

Hangi rüzgâr attı seni 

Toz dumana kattı seni 

Yeni yar bulmuştun hani 

Demeye mi geldin bana 

Niye geldin niye bana 

Söyle niye geldin bana 

Deneyelim gel bir daha 

Demeyemi geldin bana 

Böyle olsun istemezdim 

Bugün olsaydı gitmezdim 

Seni kırıp incitmezdim

Demeyemi geldin  bana', 'Sen ne hayırsız yarmışsın  Demeyemi geldin bana  Unutmadım aklımdasın Demeye mi geldin bana  Hangi rüzgâr attı seni  Toz dumana kattı seni  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/niye-geldin-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk İşine', 'ask-i-sine-ahmet-bal-4-cy9b7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dili yanmış bir tövbekarım 

Sözüm yetmez aşk işine 

Her yürekte biraz varım 

Yüzüm tutmaz aşk işine 

 Seni sorsam diyar diyar 

Belki yolum bana çıkar 

İki gözüm  kuru pınar 

Yaşım yetmez aşk işine 

Ben bulunmaz bir bilinmezim 

Ağlaşılmaz gülünmezim 

Gelinmezim  gidilmezim 

Gücüm yetmez aşk işine 

Her sürgünde biraz bittim 

Benden uzak yere gittim 

Dayanılmaz acı çektim 

Aklım ermez aşk işine ..', 'Dili yanmış bir tövbekarım  Sözüm yetmez aşk işine  Her yürekte biraz varım  Yüzüm tutmaz aşk işine   Seni sorsam diyar diyar  Belki yolum b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-isine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim yarim yar Olsaydı', 'benim-yarim-yar-olsaydi-ahmet-bal-4-bkizc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben boynumu büker miydim

Benim yarim yar olsaydı 

Per perişan gezer miydim 

Benim yarim yar olsaydı 

Ne sarsılır ne düşerdim 

Ne canımdan vazgeçerdim 

Nede  başka yar severdim

Benim yarim yar olsaydı

Bilmem benden ne  bekledi 

Ömrümü verdim yetmedi 

Bir kuru ekmek yeterdi 

Keşke yarim yar olsaydı 

Ne sarsılır ne düşerdim 

Ne canımdan vazgeçerdim 

Nede  başka yar severdim

Benim yarim yar olsaydı', 'Ben boynumu büker miydim Benim yarim yar olsaydı  Per perişan gezer miydim  Benim yarim yar olsaydı  Ne sarsılır ne düşerdim  Ne canımdan va...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Bal 4']::text[], 8.5, '{"poet":"Ahmet Bal 4","poet_slug":"ahmet-bal-4","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-yarim-yar-olsaydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Yolu', 'hayat-yolu-i-smail-eymen-akay-nev2k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Keşke bilseydim değerini zamanın

Ama herkes bilir keşkenin ağacı yeşermez

Geçip gitti o güzel günlerim

Nereden bileyim bir daha gelmez

Hayat böyleymiş dostlar

Geçip gider üç günde

Yolcuyuz bu hayat denen yolda

Bilmem sonu neredir

Bildiğim şu dur ki

Yolda ne yaparsan sonda onu bulursun

Üç günlük yol diye

Sakın birikim yapmayayım deme

Çünkü ey dost

Sen yolda yaptıklarınla sonda bilinirsin

Üç günlük yol olsa bile

Sen yine de iyilik yap

Ey yolcu zamanın kıymetini bil

Çünkü 1 dakika sonrasının garantisi bile yok

Ama sen yine de

Doğruluktan sapma

Para mal mülk 

Bunlar geçicidir dost

Senin gözün parada değil

Amellerinde olsun', 'Keşke bilseydim değerini zamanın Ama herkes bilir keşkenin ağacı yeşermez Geçip gitti o güzel günlerim Nereden bileyim bir daha gelmez Hayat...', ARRAY['Türk Edebiyatı','Şiir','İsmail Eymen Akay']::text[], 8.5, '{"poet":"İsmail Eymen Akay","poet_slug":"i-smail-eymen-akay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayat-yolu-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağrı Dağı Beyaz', 'agri-dagi-beyaz-yasar-baykal-3cqyh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağrı Dağı beyaz

Gayri buralarda duramam

Anan anan godek anan

Aman aman... halim yaman

Ağrı Dağı beyaz

Gayri buralarda duramam

On dokuzuma geldin gelin

Hiç mi beni sevmedin?

Hiç mi yuvam demedin?

Godek anan ayırdı bizi

Anan anan godek anan

Murat Suyu bataklık

Bohcani beraber kapattık

Yirmisini göstermedi

Anan anan godek anan

Cilav komuşsun da ataşa

Anan da durmuşsun farzına

Hiç mi yanmadın halıma yar?

Neyleyim bir başıma?

Kurban olurdum perçemine

Kurban oldum alem içine

Ağrı Dağı beyaz

Gayri buralarda duramam

Ağrı Dağı beyaz

Aman aman halim yaman', 'Ağrı Dağı beyaz Gayri buralarda duramam Anan anan godek anan Aman aman... halim yaman Ağrı Dağı beyaz Gayri buralarda duramam On dokuzuma ge...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/agri-dagi-beyaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Die metaphysischen und moralischen Aporien des Satanismus', 'die-metaphysischen-und-moralischen-aporien-des-satanismus-muhammed-ridvan-gizri-q4hn5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Der Satanismus wird, insbesondere in der Moderne, als Symbol der Freiheit, der Individualität und der Rebellion gegen traditionelle Autoritäten dargestellt. In seinen theistischen oder symbolischen Formen betrachtet, positioniert diese Ideologie den Satan als befreiende Figur und – Gott bewahre – Gott als unterdrückende Autorität. Dieses Bild birgt jedoch ernsthafte Probleme in logischer, metaphysischer und theologischer Hinsicht.

Die Behauptung „Satan ist das Symbol der Freiheit, Gott – Gott bewahre – das der Unterdrückung"

Dieser Behauptung liegt eine fehlerhafte Definition des Freiheitsbegriffs zugrunde. Wer Freiheit lediglich als grenzenloses Verfolgen der eigenen Begierden definiert, gelangt zu der absurden Konsequenz, auch Abhängigkeiten als Freiheit zu betrachten. Auch der Drogensüchtige folgt seinen Begierden, ebenso der Spielsüchtige und derjenige, der seinen Zorn nicht zu beherrschen vermag. Sklave der Begierden zu sein ist nicht dasselbe, wie wirklich frei zu sein. Wahre Freiheit bedeutet, die Begierden lenken zu können, nicht von ihnen gelenkt zu werden.

In den theistischen Religionen ist das wesentliche Merkmal des Satans nicht Freiheit, sondern Hochmut und Rebellion. Aus koranischer Perspektive versucht der Satan nicht, den Menschen zu befreien, sondern ihn zu täuschen; er wird als ein Wesen beschrieben, das die Menschen von der Wahrheit entfernt. Zudem zeigt sich bei Betrachtung der gesamten Geschichte des Satans keinerlei Befreiung. Der Satan konnte nicht Gott werden, er konnte sein Schicksal nicht ändern, sein Ende nicht ändern, das Urteil nicht ändern. Die Rebellion hat ihm keinerlei ontologische Macht verliehen. Die Geschichte des Satans ist daher nicht die Geschichte der Freiheit, sondern die der Ohnmacht.

Die Behauptung „Satan ist barmherziger"

Diese Behauptung enthält mehrere logische Probleme. Vor allem beruht die Annahme, der Satan sei barmherzig, auf keiner kohärenten Lehre; in der satanistischen Literatur findet sich dazu keine starke und systematische Lehre. Die Behauptung ist daher nichts weiter als eine emotionale Annahme. Zudem beweist die Existenz von Leid nicht zwingend die Unbarmherzigkeit Gottes. Dass ein Ereignis kurzfristig Schmerz verursacht, bedeutet nicht, dass es langfristig schlecht ist. Eine Operation ist schmerzhaft, doch ihr Ziel ist die Heilung. Die Existenz von Leid allein ist kein Beweis für das Böse.

Die Behauptung „Satan repräsentiert Wissenschaft und Wissen"

Die moderne Wissenschaft beruht auf Beobachtung, Experiment, Mathematik und kritischem Denken. Zwischen der Entstehung der wissenschaftlichen Methode und der Anbetung des Satans besteht keinerlei historischer Zusammenhang. Wissenschaft stützt sich auf überprüfbare Belege; die Behauptung, der Satan sei eine Quelle des Wissens, ist hingegen nicht überprüfbar. In der koranischen Terminologie wird Wissen in zwei Kategorien unterteilt: die Offenbarung, also das absolute Wissen, sowie Einflüsterung und Mutmaßung, also begrenztes und irreführendes Wissen. Die Funktion des Satans besteht nicht darin, Wissen hervorzubringen, sondern die Wahrnehmung zu verzerren. Der Koran erklärt dies mit den Begriffen „Waswasa" (Einflüsterung), „Tazyīn" (Ausschmückung) und „Wa''d" (leeres Versprechen). Der Satan ist keine epistemische Quelle; er bringt keine Wahrheit hervor, sondern nur Illusionen.

Hinzu kommt: Wenn man bedenkt, dass ein bedeutender Teil der satanistischen und okkulten Traditionen auf geheimem Wissen, Geheimnissen, Initiationen und Symbolen beruht, drängt sich unweigerlich die Frage auf: Wenn die Wahrheit universell ist, warum muss sie dann verborgen werden? Dass eine Lehre sich fortwährend auf das Geheimnis stützt, beweist ihre Richtigkeit nicht; vielmehr gebietet es, ihr mit Skepsis zu begegnen.

Die Behauptung „Gut und Böse sind relativ"

Wenn Gut und Böse völlig relativ wären, könnten auch Mord, Folter und Vergewaltigung nicht objektiv als schlecht gelten, da jeder sein eigenes Recht bestimmen könnte. Die große Mehrheit der Menschen erkennt jedoch an, dass bestimmte Handlungen unabhängig von der Kultur falsch sind. Dies erschwert die Auffassung, Moral sei völlig relativ. Noch interessanter ist Folgendes: Selbst die Verfechter des Relativismus fordern universelle Gerechtigkeit, wenn ihnen selbst Unrecht widerfährt. Dieses Verhalten zeigt, dass Rede und Handeln der betreffenden Person im Widerspruch stehen und dass im praktischen Leben die Idee einer objektiven Moral unvermeidlich akzeptiert wird.

Nach dem Islam ist die Moral weder völlig relativ noch eine rein menschliche Erfindung. Die natürliche Moral (fiṭrī) enthält einen universellen Kern, während die religionsgesetzliche Moral (sharʿī) diesen Kern durch die Offenbarung ausdifferenziert. Dass Handlungen wie Unterdrückung, ungerechtes Töten und Verrat von Kultur zu Kultur unterschiedlich bewertet werden, bedeutet nicht, dass sich die Wahrheit ändert, sondern dass der Mensch abirrt.

Die Behauptung „Der Mensch ist sein eigener Gott"

Der Mensch kann seine Geburt nicht wählen, seinen Tod nicht kontrollieren, Krankheiten nicht verhindern und die Gesetze des Universums nicht verändern. Angesichts dieser Tatsachen ist die Behauptung, der Mensch besitze unbegrenzte Souveränität, mit der rationalen Wirklichkeit unvereinbar. Das Individuum ist biologisch, psychologisch und soziologisch von der Außenwelt abhängig. Darüber hinaus würde ein völlig grenzenloses, individuumszentriertes Freiheitsverständnis das gesellschaftliche Leben unmöglich machen. Die unbegrenzte Freiheit eines Individuums greift unweigerlich in den Freiheitsbereich eines anderen ein. Dies führt im Hobbes''schen Sinne zu einem „Krieg aller gegen alle". Wenn jeder sein eigenes Moralgesetz aufstellt, ließe sich philosophisch auch rechtfertigen, dass der Starke den Schwachen unterdrückt; dieses Ergebnis widerspricht jedoch dem universellen Streben der Menschheit nach Gerechtigkeit und Barmherzigkeit.

Die ontologische Stellung des Satans

Der Satan als geschaffenes Wesen

Das grundlegendste Argument, das das metaphysische Fundament des Satanismus zum Einsturz bringt, lautet: Wer hat den Satan erschaffen? Gott. Wer hat dem Satan seine Macht verliehen? Gott. Wer erhält die Existenz des Satans aufrecht? Gott. Wer wird das Ende des Satans bestimmen? Gott. Folglich ist der Satan keine unabhängige Autorität. Dass ein Geschaffenes mit seinem Schöpfer rivalisiert, ist logisch unmöglich. Im Koran wird dem Satan keine Zwangsgewalt über den Menschen zugeschrieben. Der Satan kann keinen Lebensunterhalt gewähren, kein Leben geben, keinen Tod geben, kein Schicksal schreiben, kein Universum erschaffen. All dies gehört allein Gott. Somit ist der Einfluss des Satans nicht ontologisch, sondern psychologisch: Der Satan ist keine schöpferische Kraft, er wirkt lediglich über die Wahrnehmungen. Seine größte Waffe ist nicht Macht, sondern die Illusion, Macht zu besitzen.

Der Zusammenbruch des Dualismus

Die theistischen Versionen des Satanismus erzeugen oft unbewusst die Vorstellung eines dualistischen Universums: auf der einen Seite Gott, auf der anderen der Satan. Wenn es jedoch einen allmächtigen Gott gibt, ist eine zweite absolute Macht logisch unmöglich. Es kann nicht zwei unendliche Mächte geben; denn wenn die eine die andere an etwas hindern kann, das diese nicht tun soll, ist die gehinderte nicht unendlich; kann sie sie nicht hindern, ist sie ebenfalls nicht unendlich. Absolute Macht ist eine. Der Koran verweist ausdrücklich auf diese Logik: „Wären in beiden (Himmel und Erde) andere Götter als Gott, so wäre die Ordnung zerstört." Der Satan ist daher nicht der Rivale Gottes, sondern ein geschaffener Diener.

Die ontologische Abhängigkeit des Satans von Gott

Der Begriff des Satans hat für sich allein keine Bedeutung; er ist nur in Bezug auf Gott Satan. Nimmt man den Gottesbegriff weg, bricht auch der Begriff des Satans zusammen. Wenn es einen Rebellierenden gibt, muss es auch einen geben, gegen den rebelliert wird. Daher ist der Satan ontologisch von Gott abhängig; Gott hingegen ist nicht vom Satan abhängig. Schon diese asymmetrische Beziehung zeigt deutlich, was ursprünglich und was abgeleitet ist. Wenn ein theistischer Satanist sagt: „Ich wähle den Satan", macht er unbewusst ein weiteres Zugeständnis: Da der Begriff des Satans ohnehin von Gott abhängt, bedeutet diese Wahl im Grunde, den ontologischen Vorrang Gottes stillschweigend anzuerkennen.

Der wahre Charakter des Satans: Hochmut

Betrachtet man die koranische Erzählung vom Satan, so war der erste Fehler des Satans weder mangelndes Wissen noch mangelnde Anbetung; es war sein Materialismus, sein Hochmut, dass er sich selbst für überlegen hielt. Der Satz „Ich bin besser als er" fasst das Wesen des Satans in einer einzigen Zeile zusammen. Bemerkenswert ist Folgendes: Der Satan des Korans zweifelt nicht an der Existenz Gottes, leugnet Gott nicht, spricht mit Gott, kennt die Macht Gottes, kennt das Jenseits, kennt Paradies und Hölle. Dennoch unterwirft er sich der Wahrheit nicht. Das Problem des Satans ist nicht Unwissenheit, sondern das Ich. Deshalb ist der Satan des Korans nicht das Symbol der Unwissenheit, sondern des Hochmuts. In vielen Auslegungen des Satanismus wird das Individuum in den Mittelpunkt gestellt: ich, meine Begierden, meine Wünsche, meine Macht, meine Herrschaft. In dieser Hinsicht birgt der Satanismus die Gefahr, den ersten Fehler des Satans zur Ideologie zu erheben. Die Koranstelle „Hast du den gesehen, der sich seine Neigung zum Gott genommen hat?" weist genau auf diese Logik hin: Auch dass der Mensch sein eigenes Ego verabsolutiert, ist eine Form der Vergöttlichung.

Das Paradox der Rebellion

Der Satanismus definiert sich als Rebellionsbewegung. Dem Satan zu folgen ist jedoch in Wirklichkeit keine Rebellion, sondern Gehorsam gegenüber dem Satan. Wahre Rebellion bedeutet, sich gegen den Satan zu stellen; denn wer den Ruf des Satans zurückweist, weist auch dessen Autorität zurück. Unter diesem Gesichtspunkt erzeugt der Satanismus, während er behauptet, Rebellion zu sein, unbewusst eine neue Bindung. Zudem zeigt sich bei Betrachtung der Angebote des Satans, dass sie stets denselben Inhalt haben: Ich-Bezogenheit, Überlegenheit, Lust, Macht, Grenzenlosigkeit. Auch das Angebot an Adam war von dieser Art: Unsterblichkeit. Auch heute strebt die Menschheit nach denselben Dingen. Der Ruf des Satans ist daher keine neue Wahrheit, sondern die ausgeschmückte Form dessen, wonach das menschliche Ego ohnehin verlangt.

Die Grenzen eines lustzentrierten Lebens

Der Satanismus wendet sich häufig gegen die Unterdrückung der Begierden. In der Philosophiegeschichte, insbesondere bei Epikur, ist jedoch eine Tatsache feststehend: Die unkontrollierte Fixierung auf Lust führt nach einer Weile zur Erschöpfung der Lust, zu Überdruss und zu größerem seelischem Leid. Ein Leben, das nur augenblicklichen Genüssen nachjagt, stürzt den Menschen in eine Sinnkrise. Sich den Instinkten völlig hinzugeben ist keine Machtdemonstration, sondern bedeutet, unter die Kontrolle tierischer Triebe zu geraten. Wahrer Wille und wahre Stärke bestehen darin, dass der Mensch diese starken Triebe unter Kontrolle halten und durch das Sieb von Vernunft und Gewissen leiten kann. Opferbereitschaft und Vergebung entspringen nicht Schwäche, sondern großer psychologischer Reife und innerer Stärke. Ohne Werte wie Barmherzigkeit und gegenseitige Hilfe hätte die Menschheit keine Zivilisation aufbauen können.

Der Satanismus aus der Perspektive der Informationsmechanik

Aus der Perspektive der Systemtheorie gewinnt die Philosophie des Satanismus ihren existenziellen Code, indem sie die aus der Hauptquelle stammenden Daten umkehrt. Mathematisch ausgedrückt funktioniert sie nach der Formel S₁ = −1 × S₀. Dies zeigt, dass S₁ für sich genommen keinerlei informationellen Wert besitzt. Unterbricht S₀ den Datenfluss, bleibt für S₁ kein Wert mehr zum Multiplizieren, und das Ergebnis ist null, also der absolute informationelle Tod. Wenn ein System das, was es zerstören will, so sehr braucht, ist die Behauptung, es sei frei und originell, eine mathematische Unmöglichkeit. Der Satanismus stellt jedes Individuum im Universum in den Mittelpunkt seines eigenen Fraktals und verlangt, dass jedes Individuum sein eigenes absolutes Gesetz hervorbringt. Dieser Ansatz zerstört jedoch die fraktale Geometrie des Systems selbst. Wenn jedes Individuum ein absoluter und unbegrenzter Gott ist, entsteht, sobald sich diese Bereiche überschneiden, keine Harmonie, sondern zerstörerische Interferenz. Man stelle sich vor, jeder Knoten in einem Computernetzwerk erklärte sich zum einzigen Server des Netzwerks: Das Netzwerk würde sofort blockieren. Das letzte Versprechen des Satanismus, „die Vergöttlichung aller", endet in einem fraktalen Kollaps, bei dem alle Knoten des Informationsnetzes einander auslöschen.

Dienerschaft und wahre Freiheit

Nach der islamischen Theologie wird der Mensch nicht frei, wenn er sich seinem Ego absolut unterwirft; im Gegenteil, er wird zum Sklaven tausender vergänglicher Begierden, Ängste und Lüste. „Ubūdiyya", also Dienerschaft, bedeutet im Islam, sich allein dem einen und absoluten Schöpfer zu unterwerfen. Wenn das Individuum Diener Gottes wird, befreit es sich von den Fesseln des Geldes, des Ansehens, der Lust, der Zustimmung anderer und des eigenen Egos. Das, was die satanische Philosophie Freiheit nennt, ist daher in Wirklichkeit die elendste Sklaverei; die vom Islam verheißene Dienerschaft hingegen ist absolute Freiheit gegenüber allem Geschaffenen.

Jede der Kernbehauptungen des Satanismus bricht bei sorgfältiger Prüfung zusammen. Der Satan ist nicht das Symbol der Freiheit, sondern der Ohnmacht. Er ist nicht der Repräsentant der Wissenschaft, sondern der Erzeuger der Illusion. Er ist nicht barmherzig, sondern ein Rufer, der die Schwächen des Menschen ausnutzt. Das tiefste metaphysische Problem ist dieses: Der Satanismus kann seinen Anspruch auf Unabhängigkeit ontologisch nicht begründen. Die angebetete oder erhöhte Figur ist ein geschaffenes Wesen, das nicht aus sich selbst existieren, sein eigenes Schicksal nicht schreiben und sein eigenes Ende nicht bestimmen kann. Im tauhīd-Verständnis des Korans gleicht die Verherrlichung des Satans dem Zurücklassen der Sonne und dem Leugnen des Lichts; denn selbst die Existenz des Schattens hängt von der Sonne ab. Es ist wie bei einem Fisch, der gegen den Ozean rebelliert: Er glaubt zu rebellieren, ändert die Richtung, beschleunigt, taucht in die Tiefe, steigt an die Oberfläche, doch er hat das Wasser nie verlassen. Genau darin liegt die größte metaphysische Aporie des Satanismus: Die Bühne, auf der er zu rebellieren glaubt, ist von Anfang an die von Gott errichtete Bühne.', 'Der Satanismus wird, insbesondere in der Moderne, als Symbol der Freiheit, der Individualität und der Rebellion gegen traditionelle Autoritä...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/die-metaphysischen-und-moralischen-aporien-des-satanismus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkikindi yağmurları', 'kirkikindi-yagmurlari-adnan-hacigumus-yc9fy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'döllenip dillerinden

kollarımda tomurcuklandı bu sevgi

yıkanarak büyüdü

kırkikindi yağmurlarında gözlerimin

mevsimler geldi renk renk

baharlar gitti sarı sarı

ne rüzgarlara dayandı bilirsin

karlar yağdı üstüne

eller uzandı

koparamadı

senden başka hiçbiri', 'döllenip dillerinden kollarımda tomurcuklandı bu sevgi yıkanarak büyüdü kırkikindi yağmurlarında gözlerimin mevsimler geldi renk renk baharl...', ARRAY['Türk Edebiyatı','Şiir','Adnan Hacıgümüş']::text[], 8.5, '{"poet":"Adnan Hacıgümüş","poet_slug":"adnan-hacigumus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kirkikindi-yagmurlari-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düello', 'duello-omer-yucekaya-2-2vs76', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bilsen kaç kez izledim 

başrolü bize verilmiş o veda sahnesini ve 

her izleyişimde 

dudaklarıma kaç kez batırdım dişlerimi

dün gibi hatırlıyorum 

kadrajda eskitme bir masa 

masada içilmeyi bekleyen iki çay 

yarılanmış iki paket sigara ve 

yaşanması gereken bir ayrılık vardı

kadrajın dışında kalsa da 

kopacak fırtınanın farkındaydı garson kızlar

her zaman cıvıl cıvıl olan o Kafe 

terk edilmiş bir kasabaya dönmüş 

en müdavim müşteriler bile 

erkenden evine gitmişti

iki sevgili değil 

düelloda birbirinin açığını kollayan 

kanlı katiller gibiydik

ölüm kusmaya yeminli 

iki Smith & Wesson’du bakışlarımız. 

tebessüme bile kurşun atıyorduk

sen siyah sürme çekmiştin 

b’elâ gözlerine 

tırnaklarına kan kırmızı bir oje sürmüş 

okşamayayım diye 

tel çit çekmiştin saçının her bir teline

birlikte aldığımız yüzüğü 

bir çıkarıp bir takarken o zarif parmaklarına 

nasıl mağrur 

nasıl ölümcül ve nasıl şıktın bir katile göre

bense aptal âşık…

kadrajdaki o kanlı veda sahnesine 

hafifletici sebepler arıyor

kendimce yeniden başlamayı umuyordum ki ben… içinde sen olan en kötü rüyayı bile 

hayra yoruyordum.

müzik kutusunda

“Cinayet Saati’ni” söylemeye başlamıştı ki Ahmet Kaya…

telaşla kalktın masadan

doğum dününde aldığım fuları o kuğu boynuna bağlarken

kül tablasında hırsla ezdin sigaranı ve…

dudaklarının namlusundan 

kalibresiz bir “hoşça kal” sapladın göğsüme

kırıldı zamanın gümüş kanatları 

sanki birileri odun attı cehenneme

ya da sen 

cehennemi bıraktın içime 

gittin işte… 

işini bitirmiş Azrail gibi sessizce

konuşmak istedim 

kelimeler boşa tetik düşürdü dudaklarımda konuşamadım 

kadavranın üstünde unutulmuş bir tabut gibi kalakaldım.

ah benim huysuz leydim 

ah benim çingene klarnetim

bir şarjörü boşaltır gibi 

boşaltırken ömrüme hasreti 

öyle ayrılık bürümüştü ki gözlerini 

görmedin avucumda tuttuğum mermileri 

ve hiçbir zaman bilmeyeceksin 

o düelloya 

benim boş bir silahla gittiğimi…', 'bilsen kaç kez izledim  başrolü bize verilmiş o veda sahnesini ve  her izleyişimde  dudaklarıma kaç kez batırdım dişlerimi dün gibi hatırlıy...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/duello-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Hüküm', 'beklenen-hukum-eyup-dalkilic-2-eqdzz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giydirdiler bizlere bâtılın gömleğini,

Bilemedik mazlumun ahını, çektiğini.

Göremedik zalimin çektirdiği zilleti;

Kırdılar, yıktılar bizde yorgun yürekleri.

Yoksa esir mi kalmıştır zalime kâinat?

Beklenen hüküm gelir bir gün zalime inat;

Getirir geceler umutla bu aydınlığı.

Yıkılır bu düzen, olur tüm zalimler şah mat,

Doğar şafak yeniden karanlığı yırtarak.

Felek döner, hüküm değişir, kalmaz bu devran;

Zulümle kurulan tahtı yerle bir eder bir âh-ı nâlân.

Mazlumun gözyaşı arşa varır, durmaz artık zaman,

Zilletle beslenen o güç, bir gün olur perişan!', 'Giydirdiler bizlere bâtılın gömleğini, Bilemedik mazlumun ahını, çektiğini. Göremedik zalimin çektirdiği zilleti; Kırdılar, yıktılar bizde y...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Dalkılıç 2']::text[], 8.5, '{"poet":"Eyüp Dalkılıç 2","poet_slug":"eyup-dalkilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-pisman-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutunamayanlar', 'tutunamayanlar-omer-yucekaya-2-9giiz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '“-Abe yakışıklı…

kolundaki pirensese bir çiçek almaz mısın”

bir demet kokina’yı satabilmek için 

kırk takla atmış 

fal bakayım diye peşimize düşmüştü.

ya o çingene kızın duası kabul olmuş 

ya da aşk kısa bir süreliğine bizi seçmişti

vurgun yemekten korkmayan 

bıçkın süngerciler gibi 

nasıl dalmıştık aşkın derinliklerine 

pür telaş

nasıl okşamıştık aşkın lepiska saçlarını

gel gör ki 

bir öfkenin yamacında

yırtıldı mutluluğun haritası 

su dondu 

ateş söndü

biz tozpembe olsun diye çabaladıkça 

kızıla öykündü aşkın tuvali

geriye saksı da çürümüş bir Kokina 

ayrı parmaklardan çıkarılıp

aynı çekmeceye konan iki alyans kaldı

düştüğümüz o yankısız uçurumda

bize uzatılan bir merdivendi aşk

t u t u n a m a d ı k

yalan oldu çingene kızın falı

k a v u ş a m a d ı k', '“-Abe yakışıklı… kolundaki pirensese bir çiçek almaz mısın” bir demet kokina’yı satabilmek için  kırk takla atmış  fal bakayım diye peşimize...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tutunamayanlar-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mağlubiyet', 'maglubiyet-omer-yucekaya-2-cjdz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşkın seyir defterinde

herkes kalp değil 

yürek taşır göğsünde 

herkes özler 

herkes sever kendince…

bakmayın kapıyı çarpıp gidenlere

ayrılıklarda

herkes kanar ince ince…

aşk bir galibiyet 

ayrılık yenilgiyse

giden de, kalan da savaşı kaybetmiştir 

ikisi de öyle uzaktır ki zafere

o an başka bir aşk çalsa kapıyı

ikisinin dudaklarından da 

aynı cümleler dökülür

-almayım inşallah başka sefere…', 'aşkın seyir defterinde herkes kalp değil  yürek taşır göğsünde  herkes özler  herkes sever kendince… bakmayın kapıyı çarpıp gidenlere ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Yücekaya 2']::text[], 8.5, '{"poet":"Ömer Yücekaya 2","poet_slug":"omer-yucekaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/maglubiyet-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemedim aşkımı sana', 'soyleyemedim-askimi-sana-ali-kaya-7-3f1og', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kırar üzerim diye. 

söyleyemem sevgimi de. 

kaç kere niyetlendim de. 

söyleyemedim aşkımı sana.

söyleyemedim aşkımı sana. 

kırar üzerim diye. 

söyleyemem sevgimi de. 

kaç kere niyetlendim de. 

söyleyemedim aşkımı sana.

söyleyemedim aşkımı sana. 

kızar darılırsın diye.

yüzüme bakmazsın diye. 

benden kaçarsın diye. 

söyleyemedim aşkımı sana. 

söyleyemedim aşkımı sana. 

kızar darılırsın diye.

yüzüme bakmazsın diye. 

benden kaçarsın diye. 

söyleyemedim aşkımı sana. 

söyleyemedim aşkımı sana. 

bakışın derin olur.

sözlerin ağır olur. 

yok den sonum olur.

söyleyemedim aşkımı sana. 

söyleyemedim aşkımı sana. 

bakışın derin olur.

sözlerin ağır olur. 

yok den sonum olur.

söyleyemedim aşkımı sana. 

söyleyemedim aşkımı sana. 

kızar darılırsın diye.

yüzüme bakmazsın diye. 

