INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çık Gel', 'cik-gel-zeyno-garagiz-319hc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaderin sayfası çevrilip durur,

Mevsimler ömrümü çalmadan çık gel,

Gönül bir ümide devrilip durur,

Vakit kemendini salmadan çık gel.

Düşlerim kapında nöbet tutuyor,

Rüyâmda uykumu bölmeden çık gel,

Bir ince sızı var sabrım bitiyor,

Hasret yüreğimi delmeden çık gel.

Bir hüzün demlenir her an ocakta,

Gecenin yükünü almadan çık gel,

Müebbet sancısı kaldı kucakta,

Damarım zehirle dolmadan çık gel.

Kor kandil misali yanarım gece,

Saçımı başımı yolmadan çık gel,

Sözlerim düğümlü dilimde hece,

Bu hasret başıma kalmadan çık gel.

Azrail biçerken güller şahidim,

Gülün goncaları solmadan çık gel,

Yolunu gözlerken kullar şahidim,

Gönlüm başkasını bulmadan çık gel.

Garagız lâl olur sesini duysa,

Ecel kapımıza dalmadan çık gel,

Sevdanın ateşi köz olmuş oysa,

Son umut içimde ölmeden çık gel.

Zeyno Garagız kalemi 🖊

Zeynep Senem

Çapraz kafiye', 'Kaderin sayfası çevrilip durur, Mevsimler ömrümü çalmadan çık gel, Gönül bir ümide devrilip durur, Vakit kemendini salmadan çık gel. Düşleri...', ARRAY['Türk Edebiyatı','Şiir','Zeyno Garagız']::text[], 8.5, '{"poet":"Zeyno Garagız","poet_slug":"zeyno-garagiz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cik-gel-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dergahlar kapatıldı Mason Locası açıldı', 'dergahlar-kapatildi-mason-locasi-acildi-yusuf-tuna-l10n7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lions ve Rotary Kulüpleri yerini aldı,

Dergahlar kapatıldı Mason Locası açıldı.

Kiliseler Havralar geldi camiler boş kaldı,

Dergahlar kapatıldı Mason Locası açıldı.

Fatih''in yerine kahramanımız Sezar oldu,

Altı yüz otuz senelik Osmanlı nazar oldu.

Hilafet kaldırıldı tatil günü pazar oldu,

Dergahlar kapatıldı Mason Locası açıldı.

İslami düşünce tamamiyle bizde kurudu,

Türk İslam kültürü Müslüman ülkede eridi.

Siyonist düşünceler her yeri alıp yürüdü,

Dergahlar kapatıldı Mason Locası açıldı.

İdareciler ülkeyi laik ülke kıldılar,

Savaş yapan Türk insanları geride kaldılar.

Soyadı kanunuyla Siyonistler Türk oldular,

Dergahlar kapatıldı Mason Locası açıldı.

Yusuf antlaşmada gerekli maddeler eklendi,

İlk zaman Türkiye''nin laik olduğu saklandı.

Tekkelerle zaviyelere gitmek yasaklandı, 

Dergahlar kapatıldı Mason Locası açıldı.

Not-Kaynak:

Ne idik ne olduk?Semiha Ayverdi.S.106.

M. Remzi Sanver, "Masonluk Kültürü", 2010, s. 101-102.', 'Lions ve Rotary Kulüpleri yerini aldı, Dergahlar kapatıldı Mason Locası açıldı. Kiliseler Havralar geldi camiler boş kaldı, Dergahlar kapatı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Tuna']::text[], 8.5, '{"poet":"Yusuf Tuna","poet_slug":"yusuf-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dergahlar-kapatildi-mason-locasi-acildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fon Vurgunu', 'fon-vurgunu-zeyno-garagiz-p7f5f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sanal bir saraya kurdun tahtını,

Rakam yükseldikçe övdün bahtını,

Meğer serap imiş bozdun ahdını,

Bir fon vurgunuyla bozdular seni.

Cennet bahçesiydi rakamın yüzü,

Aldandın faize unuttun güzü,

Şimdi ayaz vurdu kırdılar dizi,

Bir fon vurgunuyla büzdüler seni.

Yetimin hakkını yedin doymadın,

Yaptığın hatayı günah saymadın,

Zindana düşünce yine aymadın,

Bir fon vurgunuyla üzdüler seni.

Cüzdanın doldukça vicdanın sustu,

Menfaat uğruna dostluklar küstü,

Şerefi pul eden nefsinde pustu,

Bir fon vurgunuyla çözdüler seni.

Eş dost meclisinde adın satıldı,

Bu zehir lokmalar kolay yutuldu,

Kızgın bakışlarla nefes tutuldu,

Bir fon vurgunuyla dizdiler seni.

Sırça köşkünü de hızla kırdılar,

Seni bir çamura atıp vurdular,

Umut ipini de gerip sardılar,

Bir fon vurgunuyla düzdüler seni.

Menfaat bürüdü görmedi gözün,

Söküldü vicdanın kalmadı özün,

Ne itibar kaldı nede bir yüzün,

Bir fon vurgunuyla yüzdüler seni.

Garagız der hüsran yüreği deldi,

Kurduğun hayâller bir kuru yeldi,

Dikişin tutmadı sonun tez geldi,

Bir fon vurgunuyla çizdiler seni.

Zeyno Garagız kãlemi 🖊

Zeynep Senem', 'Sanal bir saraya kurdun tahtını, Rakam yükseldikçe övdün bahtını, Meğer serap imiş bozdun ahdını, Bir fon vurgunuyla bozdular seni. Cennet b...', ARRAY['Türk Edebiyatı','Şiir','Zeyno Garagız']::text[], 8.5, '{"poet":"Zeyno Garagız","poet_slug":"zeyno-garagiz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/fon-vurgunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdini Küçük Görme', 'derdini-kucuk-gorme-kazim-karagoz-7as34', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Buna da mı üzüldün demeyesin kimseye,

Başına gelir dersin beni mi buldu diye.

Her dert sahibine büyüktür küçümseme hiç,

Bırak derdini döksün sorma ne oldu diye.', 'Buna da mı üzüldün demeyesin kimseye, Başına gelir dersin beni mi buldu diye. Her dert sahibine büyüktür küçümseme hiç, Bırak derdini döksün...', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/derdini-kucuk-gorme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamozlar küskün', 'yakamozlar-kuskun-mahmut-kasapoglu-iap4f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay sustu, ürperir ak Samanyolu;

Rüzgârın koynunda savrulur yazı.

Sessizlik bir kadeh, zehirle dolu,

Sunar dudağıma kaderin nazı.

Çatlamış aynada çoğalır yüzüm,

Bir ömür kendime varmadı sözüm.

Kırılmış dallarda asılı güzüm,

Saçımda zamanın düşmüş beyazı.

Yorgun martıların kanadı düşkün,

Denizin alnında yakamoz küskün.

İçimde dalgalar, kıyılar sürgün;

Köpükten kefene sardım avazı.

Boğazım düğümlü, suskun bir türkü;

Göğsümde devrilmiş bin yıllık ülkü.

Zincirdir boynumda geçmişin yükü;

Yarıda kesilmiş bir kul niyazı.

Sabır taşı çatlar, yol uzak, ırak;

Gidenin ardından döküldü yaprak.

Umut da kül oldu, toprağım kurak;

Kalbimde kışların bitmez ayazı.

Bir gün karanlıklar çekilse eğer,

Küllerim içinden doğsa bir seher;

Yalnız sevda değil, inat ve kader

Ayakta tutarmış kırık bir sazı.', 'Ay sustu, ürperir ak Samanyolu; Rüzgârın koynunda savrulur yazı. Sessizlik bir kadeh, zehirle dolu, Sunar dudağıma kaderin nazı. Çatlamış ay...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yakamozlar-kuskun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Yalnızım Diye!', 'neden-yalnizim-diye-kazim-karagoz-5pnmb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neden yalnızım diye kalmayasın ha naçar,

Bil ki kargalar sürü kartallar yalnız uçar.', 'Neden yalnızım diye kalmayasın ha naçar, Bil ki kargalar sürü kartallar yalnız uçar....', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/neden-yalnizim-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
